INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'022404B293C54E4292A3B9F7372A1490', 'Bagpuss', 13387, 79430, 1974, 'Bagpuss is a UK children''s television series, made by Peter Firmin and Oliver Postgate from 12 February 1974 to 7 May 1974 through their company Smallfilms. The title character was, "An old, saggy, cloth cat, baggy, and a bit loose at the seams." Although only 13 episodes of the show were made, it remains fondly remembered, and was regularly repeated in the UK for thirteen years. In 1999 Bagpuss topped a BBC poll for the UK''s favourite children''s TV programme.', 'Emily, a young girl in the early twentieth century, runs a shop that doesn''t sell anything. Instead, she finds lost and broken objects, bringing them back to her store to display in the front window so their rightful owners might eventually reclaim them. Before leaving the shop, Emily places each newly discovered item in front of Bagpuss, a saggy, baggy, and much-loved old pink-and-white striped cloth cat. With a magical verse, she wakes Bagpuss from his slumber, transforming the shop''s quiet sepia-toned world into vibrant color. As Bagpuss awakens, the other toys and ornaments in the shop come to life as well. Madeleine, a folk-singing rag doll, and Gabriel, a banjo-playing toad, join the pompous wooden woodpecker bookend Professor Yaffle in examining the new object. They are soon joined by the mice carved into the side of the Marvellous Mechanical Mouse Organ, who scurry out to help. The toys discuss the item''s possible origins, often leading Bagpuss, Madeleine, or Gabriel to share a story or sing a traditional folk song about its past. Once the stories are told, the mice set to work mending the broken object, squeaking out work songs as they repair the damage. Though Professor Yaffle frequently bickers with the playful mice, peace is always restored by the other toys. After the item is fully repaired, it is carefully placed in the shop window, ready for its owner to find. Their work completed, Bagpuss begins to yawn. As he falls back asleep, the rest of the toys return to their inanimate forms, and the vibrant colors of the shop fade back into a quiet stillness, waiting for Emily to bring them a new treasure.', '["children''s programming that actively lowers your resting heart rate","gentle reminders that broken things are worth fixing","british stop-motion characters living at a perfectly reasonable pace","resolving the problem and immediately taking a nap"]', 'Ended', 'BBC One', '', 6.8, 4, '1974-02-12', '1974-05-07', 1.6759, 'en', 'Bagpuss', '', 13, 1, 0, 'Scripted', 'GB', '/5dzsYX1bFKfyyOAiRbMiVaTBjx7.jpg', '/g9BbinRaTkLbV01DUNtseDd9AsY.jpg', '2026-04-03T17:23:58Z', '2026-04-03T19:35:20Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'04E6F8E4B4C14E78B4529E0420D9B098', 'The Real Housewives of Atlanta', 17380, 84159, 2008, 'Bravo''s cameras turn to the Southern states as the network presents this inside look at the Real Housewives of Atlanta. These women handle the personal dramas that affect their affluent lifestyles with a signature Southern brand of “style” and “grace.”', 'The Real Housewives of Atlanta follows the personal and professional lives of a group of affluent women residing in and around Atlanta, Georgia. The series chronicles their daily interactions, business ventures, family dynamics, and active social calendars within the city''s elite circles. Initially centering on women like NeNe Leakes, Shereé Whitfield, and Kim Zolciak, the cast continually evolves over its extensive run, introducing long-term figures such as Kandi Burruss, Cynthia Bailey, Phaedra Parks, Kenya Moore, and Porsha Williams.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'0D6BD89908C24F1683302ECE61DCB0D3', 'Playdays', 15569, 320850, 1988, 'PlayBus, later called Play Days was a children''s pre-school television programme from the United Kingdom. The series ran from 17 October 1988 to 28 March 1997 on Children''s BBC. Each daily episode would have the bus stop at one of the puppet characters bus stops.', 'Playdays is a British educational television series for preschool children, structured around the daily journeys of a magical animated bus. The series follows the Playbus as it travels to a different designated stop each day of the week, introducing distinct locations, activities, and a recurring cast of human presenters and puppet characters. Initially titled Playbus, the program utilizes a magazine-style format that blends live-action storytelling, interactive games, crafts, and music to promote early literacy, numeracy, and social skills among young viewers.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'0E7701BB0A1E48A2B25D695F11F74857', 'Funnybones', 5982, 151181, 1992, 'Funnybones was a Welsh children''s television series that was first aired in Welsh on S4C and in English on the BBC in 1992. It was based on the eponymous series of books by Janet and Allan Ahlberg which were illustrated by Andre Amstutz and focused on the adventures of a family of skeletons, sometimes known as the Funnybones. There was Big Funnybone, Little Funnybone, and Dog Funnybone. Each episode was 5 minutes in length. The voices were provided by popular comedian Griff Rhys Jones who also plays Moon Man, who serves as the narrator in the TV series.', 'In a dark, dark town, down in a dark, dark cellar, lives a family of cheerful skeletons: Big Funnybone, Little Funnybone, and their loyal pet, Dog Funnybone. Waking up when the sun goes down, the nocturnal trio emerges from their subterranean home to explore the nighttime world and attempt to frighten anyone they might come across. Narrated from above by the musical Moon Man, the series follows the accident-prone skeletons as they embark on a variety of gentle, whimsical adventures around their neighborhood and beyond. Big, known for his small red bowler hat and signature catchphrase "Good idea!", and Little, the pragmatic brains of the group, guide their energetic, barking companion through an array of nocturnal escapades. Their nightly activities range from mundane neighborhood walks to fantastical journeys, including riding spooky ghost trains to the seaside, exploring dark dinosaur museums, sailing rafts across the ocean, and embarking on elaborate mystery tours. The skeletons frequently encounter the logistical challenges of everyday life, such as attempting to trade their noisy dog for a quieter pet at Mr. Bonehead''s pet shop, only to discover that parrots, hippos, and rabbits cause far more trouble. Despite their best efforts to be scary, the Funnybones almost always fail to find anyone to frighten, usually ending up amusing themselves instead. Their clumsy nature means they frequently bump into each other in the shadows, tumbling to pieces and scattering their bones across the pavement. Whenever this happens, they must gather their scattered parts and visit Dr. Bones at the local skeleton surgery to be properly pieced back together before the sun rises and they return to their dark, dark cellar.', '["spooky aesthetic but absolutely zero actual scares","adventures that happen while the rest of the world is asleep","pets that cause significantly more problems than they solve","trying to be intimidating but mostly just injuring yourself"]', 'Ended', 'BBC One', '', 6.3, 3, '1992-09-29', '1992-12-15', 0.2695, 'en', 'Funnybones', '', 12, 1, 0, 'Scripted', 'GB', '/1JCUCfRt5cCk1nLMEL2mpbXxFpU.jpg', '/qaYSEFitbgfyM1fbep1B2E0auAd.jpg', '2026-04-03T17:24:52Z', '2026-04-03T19:35:54Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'115860D03DF8477BAD7CD9CD43A59ACE', 'Faerie Tale Theatre', 4603, 75391, 1982, 'A live-action children''s television anthology series retelling popular fairy tales.', 'Faerie Tale Theatre is a live-action fantasy anthology television series created, hosted, and executive-produced by actress Shelley Duvall. The series adapts twenty-six classic folk stories, poems, and fairy tales from authors such as the Brothers Grimm, Charles Perrault, and Hans Christian Andersen into hour-long television plays, concluding with a cast and crew reunion special. Each episode begins with a warm introduction by Duvall, who guides the audience into a whimsical world characterized by theatrical, practical sets and elaborate costumes inspired by classic children''s book illustrations.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'1376F5E8E2D84D049D7E2497F76DC8AE', 'The Adventures of Dudley the Dragon', 14460, 369680, 1993, 'The story follows Dudley, a dragon who recently woke up from centuries of hibernation and his new ten-year-old friends Matt and Sally. The two kids would guide Dudley around the modern world and the trio would learn about environmentalism, friendship and pro-social values.', 'The series follows Dudley, a lovable and childlike green dragon who suddenly awakens from a centuries-long hibernation to discover that the modern world has drastically changed around him. Upon emerging from his colorful cave, Dudley quickly befriends two ten-year-old children, Matt and Sally. Serving as his guides to the contemporary era, the children help the gentle dragon navigate unfamiliar technology, social customs, and the changing natural environment. Throughout the series, the trio embarks on various localized adventures, exploring themes of environmental conservation, interpersonal conflict resolution, and community building.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'15CF36CCCBB548F0AB47D936BCBB4691', 'The Enchanted World of Brambly Hedge', 58876, 254401, 1996, 'The Enchanted World of Brambly Hedge is a stop-motion animated series based on the Brambly Hedge books by Jill Barklem. The show was produced by Reader''s Digest Video and Hit Entertainment; in the United States, episodes began airing on the Starz premium channel in 1997.', 'Set in the tranquil English countryside, The Enchanted World of Brambly Hedge follows a community of self-sufficient, anthropomorphic mice who live in a complex network of treehouses and tunnels within a dense hedgerow. The tight-knit society operates without the threat of predators or malice, focusing instead on the challenges of nature, traditional rural craftsmanship, and communal celebrations. The mice work together to gather harvests, prepare for the changing seasons, and care for one another under the gentle guidance of leaders like Lord Woodmouse and the wise Mr. Apple.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'17FDBE5F70B04C44BFEAA7543BB6EABB', 'Stranger Things', 66732, 305288, 2016, 'When a young boy vanishes, a small town uncovers a mystery involving secret experiments, terrifying supernatural forces, and one strange little girl.', 'In the fall of 1983, the quiet town of Hawkins, Indiana, is thrown into turmoil when young Will Byers vanishes without a trace. As his frantic mother Joyce and the weary police chief Jim Hopper search for answers, Will''s loyal friends—Mike, Dustin, and Lucas—conduct their own investigation. They soon cross paths with Eleven, a mysterious girl with telekinetic powers who has escaped from the nearby Hawkins National Laboratory. The laboratory, covertly run by the United States government, has been experimenting on children and inadvertently opened a portal to a dark, parallel dimension known as the Upside Down. Over the ensuing years, Hawkins becomes the epicenter of escalating supernatural incursions. The group, which gradually expands to include older siblings Nancy and Jonathan, reformed popular high schooler Steve, newcomer Max, and a host of eccentric allies, repeatedly faces monstrous threats unleashed from the alternate dimension. They battle vicious Demogorgons, a hive-mind entity known as the Mind Flayer that possesses local residents, and deadly government agents attempting to cover up the laboratory''s catastrophic mistakes. The conflict ultimately traces back to Henry Creel, the laboratory''s original psychic test subject. Banished to the Upside Down by Eleven years prior, Creel has transformed into the malevolent entity Vecna, orchestrating the dimensional breaches to merge his nightmarish realm with the real world. As Vecna''s power grows, bringing the town to the brink of an apocalyptic military quarantine, the separated friends must reunite. Harnessing Eleven''s powers, the ingenuity of the teenagers, and the fierce protection of their adult guardians, the heroes launch a desperate final campaign to close the rifts, defeat Vecna, and save Hawkins from being completely consumed by the Upside Down.', '["grumpy men whose entire personality becomes protecting a weird child","mothers who would rather fight a demon barehanded than give up on their child","older siblings reluctantly driving the getaway car","small towns where the property values must be in absolute shambles"]', 'Ended', 'Netflix', 'It only gets stranger...', 8.572, 20936, '2016-07-15', '2025-12-31', 157.0245, 'en', 'Stranger Things', 'https://www.netflix.com/title/80057281', 42, 5, 0, 'Scripted', 'US', '/uOOtwVbSr4QDjAGIifLDwpb2Pdl.jpg', '/8zbAoryWbtH0DKdev8abFAjdufy.jpg', '2026-04-03T15:40:38Z', '2026-04-03T19:36:49Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'18D83BE758714D85A1CB465290910DEE', 'Arthur', 2153, 74678, 1996, 'The show revolves around the lives of 8-year-old Arthur Read, an anthropomorphic aardvark, his friends and family, and their daily interactions with each other.', 'Set in the fictional American town of Elwood City, the series follows the daily life of eight-year-old Arthur Read, an anthropomorphic aardvark, alongside his family and a diverse group of friends. Arthur navigates the typical trials of third grade at Lakewood Elementary under the firm but fair instruction of Mr. Ratburn. At home, Arthur contends with his strong-willed four-year-old sister, D.W., his infant sister, Kate, and his loving parents, David and Jane. His inner circle of friends includes his food-loving best friend Buster Baxter, the athletic and outspoken Francine Frensky, the wealthy and status-conscious Muffy Crosswire, the highly intelligent Brain, and the tough but secretly gentle Binky Barnes.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'1CA717D3FC894BA79E6340F80F341B50', 'Pawn Stars', 21755, 111051, 2009, 'Go inside the colorful world of the pawn business. At the Gold & Silver Pawn Shop on the outskirts of Las Vegas, generations of the Harrison family run the family business, and there’s clashing and camaraderie every step of the way.', 'Pawn Stars chronicles the daily operations and colorful encounters at the World Famous Gold & Silver Pawn Shop in Las Vegas, Nevada. Opened in 1989, the 24-hour family business is originally run by three generations of the Harrison family: patriarch Richard "Old Man" Harrison, his son Rick Harrison, and Rick''s son Corey "Big Hoss" Harrison, alongside Corey''s childhood friend, Austin "Chumlee" Russell. The series documents the continuous stream of customers who bring in a wide array of vintage, rare, and historically significant items to sell or pawn.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'1DF66CF33A18440F8ACD9A7EF9C6E204', 'The Chronicles of Narnia', 13793, 78930, 1988, 'The Chronicles of Narnia is a British television miniseries adapting four of C.S. Lewis''s books, blending live-action with animation for fantasy elements like Aslan and the creatures. The first series—The Lion, the Witch and the Wardrobe—aired from 13 November to 18 December 1988; the second—Prince Caspian and The Voyage of the Dawn Treader—aired from 19 November to 24 December 1989; and the third—The Silver Chair—from 18 November to 23 December 1990. Each series consists of six episodes each.', 'During the Second World War, the four Pevensie siblings—Peter, Susan, Edmund, and Lucy—are evacuated from London to a large country house. While exploring, Lucy steps into a magical wardrobe and discovers the snowy land of Narnia. She learns that Narnia is trapped in an endless winter by the tyrannical White Witch, Jadis, who prevents Christmas from arriving. Eventually, all four siblings enter Narnia. Edmund, seduced by the White Witch''s promises of Turkish delight, betrays his family. The remaining children take refuge with Mr. and Mrs. Beaver and learn of a prophecy that four humans will end the Witch''s reign with the help of the great lion, Aslan. Aslan sacrifices his own life on the Stone Table to save Edmund from the Witch''s claim on traitors, but deeper magic resurrects the lion. Together, they lead an army to defeat the White Witch. The Pevensies are crowned Kings and Queens of Narnia, ruling for many years until they stumble back through the wardrobe, returning to their childhood as if no time has passed. In the second season, the Pevensie children are drawn back into Narnia while waiting at a railway station. They discover that centuries have passed in Narnian time and the land has been conquered by the Telmarines, who have driven the magical creatures into hiding. The children ally with the rightful heir to the throne, Prince Caspian, who is fleeing his murderous uncle, King Miraz. With the help of Aslan and the awakened creatures of Narnia, the Pevensies defeat Miraz''s army and restore Caspian to the throne. Later, Edmund, Lucy, and their obnoxious cousin Eustace Scrubb are pulled through a painting of a ship into the Narnian sea. They join King Caspian aboard his ship, the Dawn Treader, on a voyage to locate seven exiled Narnian lords. Along the journey, Eustace is temporarily turned into a dragon, a painful ordeal that deeply humbles him. The crew faces various islands filled with magical perils, slave traders, and invisible creatures before reaching the end of the world, where Aslan appears and sends the children home. In the final season, a reformed Eustace and his schoolmate Jill Pole flee from bullies at their boarding school through a magical door, emerging in Aslan''s Country. Aslan tasks them with finding King Caspian''s kidnapped son, Prince Rilian. Guided by a pessimistic but steadfast Marsh-wiggle named Puddleglum, Eustace and Jill journey north across the treacherous giant lands of Ettinsmoor. They are tricked into seeking shelter at the castle of Harfang but escape upon realizing the giants intend to eat them. Fleeing into the subterranean Underland, they discover Prince Rilian under the mind-control of the Lady of the Green Kirtle. Rilian is tied to a silver chair that keeps him enchanted. The children and Puddleglum break the chair, freeing the prince, and then defeat the Lady, who transforms into a giant serpent. They escape the collapsing Underland and return Rilian to Narnia just in time for him to say goodbye to his dying father. Aslan resurrects Caspian in his own country, allowing the children to see him restored before returning to their own world.', '["unsupervised minors resolving complex geopolitical conflicts","talking animals with vastly superior moral compasses","loyalty demonstrated by complaining the entire time but doing the right thing anyway","siblings remembering they actually love each other when faced with mortal peril"]', 'Ended', 'BBC One', '', 7.5, 20, '1988-11-13', '1990-12-23', 6.9117, 'en', 'The Chronicles of Narnia', '', 18, 3, 0, 'Scripted', 'GB', '/pfAFIkQd9MD4KDxlElCVSNKwnaR.jpg', '/kXTZR11xLYaShf3ZMeTmBP9Lsq7.jpg', '2026-04-03T17:17:40Z', '2026-04-03T19:37:27Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'1F54A881CF7D4CCE9BC738768C2CF36E', 'Game of Thrones', 1399, 121361, 2011, 'Seven noble families fight for control of the mythical land of Westeros. Friction between the houses leads to full-scale war. All while a very ancient evil awakens in the farthest north. Amidst the war, a neglected military order of misfits, the Night''s Watch, is all that stands between the realms of men and icy horrors beyond.', 'Set on the fictional continents of Westeros and Essos, the series chronicles the violent dynastic struggles among the realm''s noble families for the Iron Throne. King Robert Baratheon asks his old friend Eddard "Ned" Stark, Lord of Winterfell, to serve as Hand of the King following the sudden death of the previous Hand. Ned discovers that Robert''s heirs are actually the product of incest between Queen Cersei Lannister and her twin brother Jaime. When Robert dies in a suspicious hunting accident, Ned is betrayed and executed by Cersei''s son, King Joffrey.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'212E97F93BFB49D08A5BF3586F06C585', 'Tom''s Midnight Garden', 30428, 251553, 1989, 'Forced to stay with his aunt and uncle for the summer holidays, Tom Long is lonely and bored, until one night he hears the clock strike 13. He suddenly finds himself transported to a magical Victorian garden of the 1880s and meets a girl.', 'Tom Long is sent to quarantine with his stuffy Uncle Alan and Aunt Gwen in their cramped flat after his younger brother Peter contracts the measles. Bored, lonely, and frustrated by the lack of a garden or playmates, Tom lies awake at night. His mundane summer changes when he hears the grandfather clock in the hallway—owned by the reclusive, elderly landlady Mrs. Bartholomew—mysteriously strike thirteen. Venturing downstairs to investigate, Tom opens the back door and discovers that the dreary yard of dustbins has magically transformed into a sprawling, sunlit Victorian garden.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'27BADAD17C004147BC51C8E96063F79B', 'Dogtanian and the Three Muskehounds', 5341, 74972, 1981, 'France, 17th century, under the reign of Louis XIII. Dogtanian is an impetuous and innocent peasant from Gascony, as well as a skilled swordsman, who travels to Paris with the purpose of making his dream come true: to join the Corps of Muskehounds of the Royal Guard.', 'In seventeenth-century France, Dogtanian, an impetuous and idealistic young dog from the country, travels to Paris with grand dreams of joining King Louis XIII''s elite Muskehounds. Eager to prove his worth, his hot-headed nature and unshakeable sense of honor immediately land him in trouble. Shortly after arriving in the city, he accidentally insults three formidable swordsmen—the legendary Muskehounds Athos, Porthos, and Aramis—and challenges them each to a duel. Before blades can clash, the four are interrupted by the Cardinal''s guards. Standing united against a common enemy, they quickly form a lifelong brotherhood bound by the famous motto "one for all, and all for one."
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'27F7EFB171144E2E9427635393A6DDB1', 'Kratts'' Creatures', 933, 71102, 1996, 'Kratts'' Creatures is a children''s television program on PBS. The show was hosted by the Kratt Brothers, Chris and Martin. It also featured Shannon Duff as Allison Baldwin and Ron Rubin as the voice of an animated anthropomorphic dinosaur. The show introduced its viewers to the world of animals. 50 episodes were produced in total. The show ran for only one season on PBS from June 3, 1996 until August 9, 1996. Then after cancellation, aired reruns until June 9, 2000. It also aired reruns on PBS Kids Go! from October 2006 to May 2008. Due to its popularity the show inspired an unofficial spinoff, Zoboomafoo, another show created by the Kratts, which premiered on January 25, 1999.', 'Brothers Chris and Martin Kratt embark on globetrotting expeditions to explore the animal kingdom and introduce young viewers to wildlife in its natural habitat. Acting as enthusiastic guides, the zoologist brothers travel to diverse locations—ranging from the African savanna and the Australian Outback to the Florida Everglades and the forests of Canada—to observe creatures like chimpanzees, kangaroos, cheetahs, and sharks. The live-action documentary footage is woven together with physical comedy as the brothers demonstrate animal behaviors and test their own physical limits against the abilities of the creatures they study. While Chris and Martin are out in the field, they are supported from their high-tech headquarters, Creature Central, by their teenage friend Allison Baldwin. Allison operates the base''s computers, supplying the brothers with vital research and scientific context for their adventures. The team is additionally joined by Ttark, a quirky, animated anthropomorphic creature who appears on monitors to share educational facts and add a touch of fantasy to the series. Blending live-action exploration with animated segments and fast-paced humor, the program highlights the diversity of the natural world and emphasizes the importance of understanding and respecting all species.', '["men being absolutely thrilled by bugs and dirt","the reason millennials thought they would grow up to be marine biologists","treating animals with the respect normally reserved for visiting dignitaries","core memories of watching pbs on a sick day"]', 'Ended', 'PBS', '', 8.3, 3, '1996-06-03', '1996-08-09', 0.7682, 'en', 'Kratts'' Creatures', '', 50, 1, 0, 'Scripted', 'US,CA', '/6FSDfMgrCH1zYSoFppJ0OZVGpBU.jpg', '/j6sBB0eEiszkPB6V78J1GvjBRgQ.jpg', '2026-04-03T17:11:47Z', '2026-04-03T19:38:13Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'2CB2FE67CC744641AC37515651FA5EB8', 'The Animals of Farthing Wood', 188, 74638, 1993, 'The Animals of Farthing Wood is an animated series created by the European Broadcasting Union between 1992 and 1995 and based on the series of books written by Colin Dann. It was produced by Telemagination, based in London, and La Fabrique, based in Montpellier in France, but also aired in other European countries. The first countries to air the series were Germany and the United Kingdom, in January 1993.', 'When human developers bring bulldozers to destroy Farthing Wood to build houses, the resident animals are forced to flee their ancestral home. Realizing they cannot survive the journey individually, the diverse group of predators and prey form a desperate alliance. Under the leadership of Fox and the guidance of Toad, who knows the way to a nature reserve called White Deer Park, they swear the Oath of Mutual Protection, vowing not to eat or harm one another until they reach their destination. Their perilous journey forms the first major arc, fraught with natural disasters, human hunters, poisoned water, busy highways, and agricultural machinery. Along the way, several animals tragically lose their lives, but the survivors eventually reach the safety of White Deer Park, welcomed by the Great White Stag.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'3259EBA1E2EF46DBA2BBF293688C2024', 'Zoboomafoo', 4217, 78794, 1999, 'Zoboomafoo is an American children''s television series that aired from January 25, 1999, to April 28, 2001, and is still shown today in syndication depending on the area, and it is regularly shown on PBS Kids Sprout. A total of 65 episodes were aired. A creation of the Kratt Brothers, it features a talking Coquerel''s Sifaka, a type of lemur, named Zoboomafoo, or Zoboo for short, and a collection of repeat animal guests. Every episode begins with the Kratt brothers in "Animal Junction", a peculiar place in which the rules of nature change and wild animals come to visit and play. After January 16, 2004, the show was pulled from its weekday airing on most PBS stations, though some continue to air the show.', 'Zoboomafoo is an educational live-action and animated children''s television series hosted by zoologist brothers Chris and Martin Kratt. The series is set in Animal Junction, a whimsical clubhouse and wildlife center where the hosts observe, care for, and play with a diverse array of visiting animals. At the beginning of each episode, the brothers arrive at Animal Junction and summon the titular character, Zoboomafoo (affectionately known as Zoboo), a Coquerel''s sifaka lemur who leaps across a field to reach them. The Kratt brothers offer Zoboo a snack, such as garbanzo beans or sweet potato slices. Upon eating, the live-action lemur spins around on a turntable and transforms into a talking, anthropomorphic puppet who serves as the brothers'' enthusiastic companion.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'3610E7F095B04BB5BF72CACD6914D36E', 'Ivor the Engine', 2618, 435497, 1976, 'Ivor the Engine is a British children''s animation by Oliver Postgate and Peter Firmin''s Smallfilms company. It is a children''s television series relating the adventures of a small green locomotive who lived in the "top left-hand corner of Wales" and worked for The Merioneth and Llantisilly Railway Traction Company Limited. His friends included Jones the Steam, Evans the Song and Dai Station, among many other characters.', 'Set in the idyllic, fictional top left-hand corner of Wales, the series follows the daily operations and gentle adventures of the Merioneth and Llantisilly Rail Traction Company Limited. The railway''s pride is Ivor, a small green steam locomotive who is entirely sentient. Unlike other anthropomorphic trains, Ivor lacks a human face and communicates not through speech, but through a series of rhythmic puffs and the three musical notes of his whistle, which his devoted driver, Jones the Steam, perfectly understands.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'38224AAB22FE4B2DB0152E17038FDE3B', 'Madeline', 17194, 101611, 1988, 'A young girl embarks on a series of misadventures, causing her friends and teachers to be worrisome. Based on the children''s books by Ludwig Bemelmans.', 'In an old house in Paris covered in vines, twelve little girls live in two straight lines under the watchful eye of their devoted headmistress, Miss Clavel. The smallest and bravest of the students is Madeline, a fiercely independent, red-haired orphan with a knack for finding both trouble and adventure. The animated series adapts and expands upon Ludwig Bemelmans'' classic children''s books, following the girls'' daily routines and extraordinary escapades in and around France. Unfazed by mice, tigers, or even a ruptured appendix, Madeline leads her classmates with an indomitable spirit and a strong moral compass.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'3F51CDD308DF42F8806F78D3958C3166', 'The Witcher', 71912, 362696, 2019, 'Geralt of Rivia, a mutated monster-hunter for hire, journeys toward his destiny in a turbulent world where people often prove more wicked than beasts.', 'In the sprawling, medieval-inspired landmass known as the Continent, monstrous beasts roam freely, and humanity is often just as ruthless. Geralt of Rivia is a witcher—a mutant warrior rigorously trained and chemically altered from childhood to hunt and kill monsters for coin. Traveling with his loyal horse Roach, the stoic and solitary Geralt attempts to navigate a chaotic world while strictly adhering to his own moral code, often finding that the humans he encounters are far more treacherous than the supernatural creatures he slays.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'4363C674AD554E7999DC101BEE2108C9', 'The Real Housewives of D.C.', 31493, 170151, 2010, 'The Real Housewives of D.C. is an American reality television series that debuted August 5, 2010, on Bravo. It is the network''s fifth installment in The Real Housewives series. On April 7, 2011, Bravo announced that The Real Housewives of D.C. had been cancelled. This was a first in the history of the franchise that one of its series had not been renewed.', 'The series documents the personal and professional lives of five affluent women residing in and around Washington, D.C.: Mary Amons, Lynda Erkiletian, Cat Ommanney, Michaele Salahi, and Stacie Scott Turner. The overarching narrative explores the intersection of politics, high society, and personal drama within the exclusive circles of the nation''s capital. Mary, a Washington native and mother of five, manages her family life and philanthropic endeavors while navigating the rigid social etiquette of the Beltway. Lynda balances her responsibilities running a successful modeling agency with raising her children and managing her relationship with her younger boyfriend. Stacie, a prominent real estate broker, embarks on a deeply personal journey to locate her biological father, uncovering long-hidden details of her family''s past. Cat, an outspoken British interior designer and author, frequently causes friction within the group due to her blunt opinions regarding American politics and the social customs of the other women, all while dealing with increasing tension in her marriage. However, the defining storyline of the series revolves around Michaele and her husband, Tareq. Throughout the season, Michaele presents an image of high society access and vast wealth, often clashing with Lynda and Cat over her erratic behavior, her alleged health issues, and her claims of being a former Washington Redskins cheerleader. The series culminates in a highly publicized incident where Michaele and Tareq attend a White House state dinner honoring Indian Prime Minister Manmohan Singh without an official invitation. The fallout from this unprecedented gatecrashing event dominates the latter part of the season, drawing intense scrutiny from the Secret Service and the national media. The ensuing legal and social ramifications bring the series to a dramatic close, straining the Salahis'' relationships with the rest of the cast and ultimately leading to the show becoming the first in the franchise to be canceled after a single season.', '["women who would benefit from a silent retreat","proof that money cannot buy self-awareness","adults who desperately need a hobby","unintentional cautionary tales about vanity"]', 'Ended', 'Bravo', 'I don''t make money, I spend money.', 4.0, 5, '2010-08-05', '2010-10-21', 0.6373, 'en', 'The Real Housewives of D.C.', 'http://www.bravotv.com/the-real-housewives-of-dc', 11, 1, 0, 'Reality', 'US', '/uXkmzijKgBYAkeXas453ZrQxnNg.jpg', '/1FugcefO6h1jE6i85iTx61cPa8l.jpg', '2026-04-03T16:35:01Z', '2026-04-03T19:39:19Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'43EC58570A064270ABE79084053C1A19', 'The Borrowers', 40306, 81205, 1992, 'The Borrowers are small, 15cm high humans who live in the English hinterland. They live out their lives in mouse-hole sized nooks in human homes, and survive by ''borrowing'' all they need from the house and its inhabitants. This series follows young girl Arriety, and her parents Pod and Homily, as they are displaced from their home and try to find a new home, with the help of a human boy, George.', 'The Clock family—Pod, Homily, and their spirited teenage daughter Arrietty—are "Borrowers," miniature people who secretly live beneath the floorboards of a 19th-century English manor. They survive by ingeniously repurposing small, discarded items from the "human beans" who inhabit the house above, making sure to avoid detection. Despite her father''s strict warnings about the dangers of the human world, the adventurous Arrietty is discovered by George, a young boy sent to the country to recover from an illness. Against all borrower rules, Arrietty forms a bond with George, who promises to keep their existence a secret and begins bringing the family gifts. However, the nosy and cruel housekeeper, Mrs. Driver, uncovers the tiny family''s presence. Determined to exterminate them, she locks George away and calls in a rat-catcher. The Clocks are forced to abandon their comfortable home, fleeing into the vast and terrifying English countryside. Seeking refuge in an old boot, they face constant threats from oversized wildlife and the elements. They soon encounter Spiller, a rugged and resourceful "wild" borrower, who helps them navigate the wilderness and eventually reunites them with their long-lost relatives in a caretaker''s cabin.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'4A6F36EF8E464297B58FDEF3C13E83A2', 'Bear in the Big Blue House', 207, 70622, 1997, 'The series provides children with valuable tools for growth in key areas of music, social skill development, and cognitive learning through integrated programs combining music, movement, and exploration. With Bear and all his friends, learn about cooperation, teamwork and more.', 'In the gentle and vibrant environment of Woodland Valley, a seven-foot-tall, friendly bear named Bear serves as the central caregiver and host inside the Big Blue House. Every day, Bear opens his doors to warmly welcome viewers, greeting them with a song and a playful sniff to see how they smell. Inside, he tends to a lively, diverse group of young animal friends, each exhibiting distinct preschool-aged personalities and quirks. His household includes Ojo, a curious and imaginative red bear cub; Tutter, a meticulous, cheese-loving blue mouse who frequently fusses over chores and order; Treelo, a highly energetic lemur who loves dancing and music; and Pip and Pop, a pair of mischievous, fun-loving purple otter twins who reside in the nearby pond. Throughout the series, the household explores different daily themes such as sharing, nighttime routines, hygiene, emotions, or the changing seasons. Bear gently guides his friends through their conflicts, fears, and discoveries, using patience, humor, and educational songs to teach them essential cognitive and social-emotional skills. Alongside his interactions with the physical inhabitants of the house, Bear frequently searches for and converses with Shadow, a playful and elusive silhouette girl who sings whimsical stories using shadow puppetry. Other recurring elements include Bear''s morning conversations with Ray the Sun, who helps start the day, and his quiet evening reflections with Luna the Moon. At the end of every episode, Bear steps out onto the balcony to recount the day''s events to Luna. They sing the Goodbye Song together, reinforcing the show''s comforting structure and closing out the day''s lessons before Bear bids the audience farewell.', '["adults treating children''s minor inconveniences with immense respect","media that actively lowers your resting heart rate","gentle giants patiently managing absolute chaos","ending the day with a quiet conversation about what happened"]', 'Ended', 'Playhouse Disney', '', 7.5, 106, '1997-10-20', '2010-01-01', 12.9352, 'en', 'Bear in the Big Blue House', 'http://www2.disney.co.uk/DisneyChannel/playhouse/friends/bear/index.htm', 117, 4, 0, 'Scripted', 'US', '/hww73tErgeSOQ6YlcKjey0smc8s.jpg', '/sJzekWt8wobtQZel7n8gM3NjiVt.jpg', '2026-04-03T17:35:31Z', '2026-04-03T19:39:43Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'4C7F47AFE049449D91CD73923F2F9AC4', 'Ghostwriter', 3925, 72889, 1992, 'Ghostwriter is an American television program created by Liz Nealon and produced by the Children''s Television Workshop and BBC One. It began airing on PBS on October 4, 1992, and the final episode aired on February 13, 1995. The series revolves around a close knit circle of friends from Brooklyn who solve neighborhood crimes and mysteries as a team of young detectives with the help of an invisible ghost named Ghostwriter. Ghostwriter can communicate with the kids only by manipulating whatever text and letters he can find and using them to form words and sentences. The series was filmed on location in Fort Greene, Brooklyn.', 'In the Fort Greene neighborhood of Brooklyn, a diverse group of middle-school friends discovers a benevolent, invisible spirit trapped inside an old book. They name the amnesiac entity Ghostwriter and quickly learn that he can only perceive and communicate through written text. Unable to hear or speak, Ghostwriter interacts with the physical world by pulling letters and words from signs, clothing, books, and computer screens, rearranging them to send messages to the children. Together, the kids form a secret detective agency, wearing composition notebooks on lanyards to communicate with their spectral ally and document clues. 
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'50BD27464B5C47328F78AB2E87B4D161', 'Liberty''s Kids', 11110, 77619, 2002, 'Liberty''s Kids is an animated educational historical fiction television series produced by DIC Entertainment, originally broadcast on PBS Kids from September 2, 2002 to April 4, 2003, although PBS continued to air reruns until August 2004. The show has since been syndicated by DiC to affiliates of smaller television networks such as The CW and MyNetworkTV and some independent stations so that those stations can fulfill FCC educational and informational requirements. Since September 16, 2006, the series aired on CBS''s new block called KOL Secret Slumber Party on CBS, then it was aired on KEWLopolis, which taking September 12, 2009. In 2008 it ran on The History Channel. The series is currently on the Cookie Jar Toons block on This TV and CBS''s Cookie Jar TV. In 2012, Qubo announced the channel will air Liberty''s Kids in fall 2012. The series was based on an idea by Kevin O''Donnell and developed for television by Kevin O''Donnell, Robby London, Mike Maliani, and Andy Heyward.', 'In 1773, as the American colonies stand on the brink of revolution, three young apprentices and their caretaker find themselves at the center of history while working for Benjamin Franklin''s Pennsylvania Gazette. James Hiller, an orphaned colonial youth with fiercely patriotic ideals, and Sarah Phillips, a dignified English girl visiting the colonies with staunchly Loyalist views, serve as investigative reporters for Franklin. They are joined by Henri, an orphaned French boy seeking refuge, and Moses, a freed African-American man who manages the printing shop. Sent by Franklin to cover the growing unrest, the young journalists witness the unfolding American Revolution firsthand, traveling from the Boston Tea Party to the battlefields of Lexington and Concord, the winter at Valley Forge, and ultimately the Constitutional Convention. Over the course of the war, the apprentices confront the complexities and human costs of the conflict. James must reconcile his uncritical revolutionary zeal with the grim realities of espionage and warfare. Sarah grapples with her divided loyalties, slowly shifting her perspective as she observes the colonists'' struggle for self-governance. Meanwhile, Moses navigates the paradox of fighting for liberty in a land that still practices slavery, particularly as he searches for his enslaved brother, Cato. By interviewing historical figures like George Washington, Thomas Jefferson, and Abigail Adams, the youth document the birth of a nation while discovering the profound sacrifices required to secure freedom and forge a stable republic.', '["educational programming that forgot to be boring","reminding kids that their ancestors were tougher than them","historical events witnessed by inexplicably present children","cartoons that refuse to talk down to their audience"]', 'Ended', 'PBS', '', 7.6, 19, '2002-09-02', '2003-04-04', 5.8919, 'en', 'Liberty''s Kids', '', 40, 1, 0, 'Scripted', 'US', '/uAJYUum6922FcIlLiOLbJGRqQTP.jpg', '/6OrFwNfXb8pSdnW14Wm16zWUXGW.jpg', '2026-04-03T17:38:28Z', '2026-04-03T19:40:15Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'542C438283D44D54AB69EDA231823F2B', 'The Real Housewives of Potomac', 65300, 303252, 2016, 'Just up the river from our nation’s capital lies a hidden gem—Potomac, Maryland. Its rolling hills, gated mansions, sophisticated prep schools, and exclusive country clubs all serve to keep the area invitation-only. Sprinkled throughout this community are a handful of old-line, wealthy African-American families who have historically broken racial barriers to provide a life of privilege for their children. In a town where entry is granted only through class, pedigree, and lineage, how far will the ladies go to secure their spot at the top of this prestigious circle?', 'The Real Housewives of Potomac follows the personal, professional, and social lives of an exclusive group of affluent women residing in and around Potomac, Maryland. Originally focusing on the strict etiquette rules and old-line pedigree of wealthy African-American families in the Washington D.C. area, the series explores how these women navigate high-society expectations while managing their marriages, motherhood, and growing business empires. At the center of the community''s social structure is Karen Huger, who frequently styles herself as the Grande Dame of Potomac, demanding respect and adherence to traditional social protocols. Her ongoing rivalry and complex friendship with Gizelle Bryant, who frequently questions the others'' decisions and relationships, serves as a central dynamic across the seasons. Gizelle, along with her close confidante Robyn Dixon, forms a tight-knit alliance that frequently challenges the newer additions to their circle. Robyn''s storyline heavily features her on-again, off-again relationship and eventual remarriage to her former husband, Juan Dixon, amidst recurring rumors of infidelity. Meanwhile, Ashley Darby, a former pageant winner, brings a younger perspective to the group, continuously balancing her turbulent marriage to an older, wealthy real estate developer with her journey into motherhood and eventual separation. As the seasons progress, the social circle expands to include women who disrupt the established hierarchy. Monique Samuels introduces tensions over parenting and lifestyle, culminating in an explosive physical altercation that splinters the group''s allegiances. Candiace Dillard Bassett, a former pageant queen trying to step out of her mother''s financial shadow, repeatedly finds herself at the center of intense vocal disputes, struggling to moderate her reactions while pursuing a music career and building a family. Later additions, including political commentator Dr. Wendy Osefo and entrepreneur Mia Thornton, bring new wealth and accomplishments into the fold, challenging the original cast members over social standing, professional legitimacy, and unspoken family secrets. Throughout the series, the women travel extensively, host lavish charity events and parties, and constantly renegotiate their friendships. The narrative balances the glamorous facade of Potomac''s gated communities with the harsh realities of public divorces, legal battles, health scares, and shifting financial fortunes, observing how far each woman will go to secure her spot at the top of their prestigious circle.', '["lavish dinner parties ruined by unnecessary screaming","women treating minor etiquette breaches like federal crimes","husbands looking off camera for help","apologies that are actually just new insults"]', 'Returning Series', 'Bravo', 'The word on the street is that I’m the word on the street.', 5.8, 46, '2016-01-17', '2026-03-01', 7.2955, 'en', 'The Real Housewives of Potomac', 'http://www.bravotv.com/the-real-housewives-of-potomac', 193, 10, 1, 'Reality', 'US', '/lgSkHpr6LXxsh2YXiBrDZHn5wUR.jpg', '/dlVTyTBEkZ9z60dREnN7KngX1gt.jpg', '2026-04-03T16:35:37Z', '2026-04-03T19:40:18Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'55596F061A134DA591DF218B92FCA64A', 'The Real Housewives of Beverly Hills', 32390, 196741, 2010, 'A reality series that follows some of the most affluent women in the country as they enjoy the lavish lifestyle that only Beverly Hills can provide.', 'The Real Housewives of Beverly Hills chronicles the personal and professional lives of an ever-evolving group of affluent women residing in or around the glamorous, high-stakes enclave of Beverly Hills, California. Operating within a hyper-wealthy social circle, the women balance their family obligations, philanthropic endeavors, and lucrative business ventures with the relentless demands of their intricately connected social calendar. While the cast frequently rotates across fifteen seasons, the overarching narrative is driven by deep-seated personal histories, shifting allegiances, and spectacular confrontations set against a backdrop of private jets, sprawling mansions, and extravagant international vacations.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'5648CD2A194D4AB9A2AEB2F9743F463C', 'Avatar: The Last Airbender', 246, 74852, 2005, 'In a war-torn world of elemental magic, a young boy reawakens to undertake a dangerous mystic quest to fulfill his destiny as the Avatar, and bring peace to the world.', 'In a world divided into four nations—the Water Tribes, the Earth Kingdom, the Fire Nation, and the Air Nomads—certain individuals known as benders can telekinetically manipulate one of the four classical elements using martial arts. The Avatar, the only person capable of mastering all four elements, is tasked with maintaining balance and peace among the nations. The series begins a century after the Fire Nation, led by Fire Lord Sozin, declares war on the other nations following the sudden disappearance of the Avatar. To ensure their victory, the Fire Nation commits genocide against the Air Nomads to eliminate the Avatar''s next reincarnation.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'567AA148B059435984F6A3C38CF2B0AE', 'Bernard''s Watch', 15697, 71925, 1997, 'British children''s drama series about a young boy who could stop time with a magical pocket watch.', 'Bernard Beasley is a young boy living in Nottinghamshire who struggles with chronic tardiness and the chaotic pace of everyday life. His fortunes change when a mysterious Postman, acting as an emissary for an unseen magical order, gifts him a golden pocket watch. When Bernard clicks the button on top of the watch, time immediately stops for everyone and everything around him. By clicking it again, time resumes, allowing Bernard to seamlessly navigate his surroundings without anyone noticing his temporal interventions.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'570BF5C232B3408A83364C07E7B9A3DA', 'The Real Housewives of Miami', 34268, 228691, 2011, 'Six of the most influential and connected women live life to the fullest in the sunny city where both the party and the drama never stop.', NULL, NULL, 'Returning Series', 'Bravo', 'Same heat. New shade.', 5.5, 21, '2011-02-22', '2025-10-16', 3.9908, 'en', 'The Real Housewives of Miami', 'https://www.bravotv.com/the-real-housewives-of-miami', 114, 7, 1, 'Reality', 'US', '/mlhCJsrZ2QsZmMuvI66RUhPAy3h.jpg', '/z1Wj0JhRF2AN6zSYsk5moptCfVA.jpg', '2026-04-03T16:35:09Z', '2026-04-03T16:54:47Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
