INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'57BDE44B499E447785DB15CE05EE894E', 'Come Outside', 14343, 71583, 1993, 'A BBC educational children''s television series that aimed to encourage young children to learn about the world around them. The starting point for each programme is something with which children are already familiar, such as water, wood, paper, boots, spiders, buses, soap, street lamps. The two main characters are Auntie Mabel, and her dog Pippin. They go on adventures in Auntie Mabel''s aeroplane, travelling far and wide across the UK to find out more. Music, rhymes and stories enrich the programme topics.', NULL, NULL, 'Ended', 'BBC Two', '', 5.8, 5, '1993-09-23', '1997-03-18', 0.3246, 'en', 'Come Outside', 'http://www.bbc.co.uk/cbeebies/comeoutside/', 40, 3, 0, 'Scripted', 'GB', '/6ce4IRSFIg7yoK0OkW3faQF1xlk.jpg', '/mVQa19LBrhqfxmf1Hb3XRAZaYPE.jpg', '2026-04-03T17:19:30Z', '2026-04-03T17:19:35Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'57F0E548F9D1412A8B9BDC3960A09B22', 'Shaun the Sheep', 3902, 79890, 2007, 'Shaun the Sheep thinks and acts like a person in a barnyard, which usually gets him into trouble. The farmer''s sheepdog, Bitzer, tries to keep Shaun and his friends out of trouble. The farmer is oblivious to the humanlike features of his flock, who are like one big, happy family.', NULL, NULL, 'Returning Series', 'BBC One', '', 7.6, 280, '2007-03-05', '2025-12-01', 13.5559, 'en', 'Shaun the Sheep', 'http://www.shaunthesheep.com', 170, 6, 1, 'Scripted', 'GB', '/z2gPfTQd3I0JLWOAEdKYMQRLoun.jpg', '/onwny8s0VTTN7te9TJnItgvyWHy.jpg', '2026-04-03T17:39:30Z', '2026-04-03T17:39:37Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'5CC5CB2F38CF4A648A109007E89133ED', 'The Phoenix and the Carpet', 26972, 267518, 1997, 'The Phoenix and the Carpet is a six-part British miniseries based on E. Nesbit''s 1904 fantasy novel of the same name. Produced by HIT Entertainment for BBC One, it aired from 16 November to 21 December 1997.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'60191EA0FCBE4CEFA9231CD785F429B3', 'The Puzzle Place', 12954, 78315, 1995, 'The Puzzle Place is an American children''s television series produced by KCET in Los Angeles, California and Lancit Media in New York City, New York. It premiered on the Public Broadcasting Service on January 16, 1995, and ran for about four years, airing its final episode on December 4, 1998. Reruns were continued until March 31, 2000. The show followed a multi-ethnic group of kids from different parts of the United States who hung out at "the Puzzle Place", which is a teen hangout themed around jigsaw puzzle pieces. In each episode the characters were confronted with an everyday conflict usually encountered in childhood and even early teenagerdom, such as making moral decisions, sharing, racism, sexism, etc.', NULL, NULL, 'Ended', 'PBS Kids', '', 10.0, 1, '1995-01-16', '1998-12-04', 2.3272, 'en', 'The Puzzle Place', '', 75, 3, 0, 'Scripted', 'US', '/7i58GcVBdMHHOqquMzzLSsMjPFg.jpg', '/yKGbtg5Hpps3BWeIZqPN61hS4Eh.jpg', '2026-04-03T17:12:20Z', '2026-04-03T17:12:26Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
