INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'67529854994741C0B8D3417037B58EEF', 'Oakie Doke', 3586, 252134, 1995, 'Oakie Doke was a children''s television programme that was broadcast from September 1995 until December 1996 on the BBC. It was produced by Cosgrove Hall Productions and was shown in stop motion animation. The show ran for two series, each containing 14 episodes.', NULL, NULL, 'Ended', 'Telemundo', '', 5.0, 2, '1995-09-11', '1998-06-15', 1.6847, 'en', 'Oakie Doke', '', 26, 2, 0, 'Scripted', 'GB,MX,CA,IT', '/6Belgd2PCloaQLhRwpFel9ZJMrx.jpg', NULL, '2026-04-03T17:19:24Z', '2026-04-03T17:19:29Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'67DD09049ABA49BCB1B1D047B59106CE', 'Kipper', 25985, 71479, 1997, 'Kipper is a charming collection of tales that follows the adventures of a curious and friendly dog as he explores the world, makes new friends, and learns valuable life lessons through imaginative fun and play.', NULL, NULL, 'Ended', 'Nickelodeon', '', 7.6, 12, '1997-09-05', '2000-12-21', 3.6598, 'en', 'Kipper', '', 78, 6, 0, 'Scripted', 'GB', '/evbqA7XtVJnwJuxdzMqG17nBFqx.jpg', '/28ydoTvksl00rZUP7LheUVS8OHK.jpg', '2026-04-03T17:10:47Z', '2026-04-03T17:10:54Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'69D0907AF6DA472E97DA11F5413BE48A', 'Fireman Sam', 5200, 73517, 1987, 'Follow the adventures of fireman Sam and his colleagues as they protect the citizens of the Welsh town of Pontypandy. Whenever the alarm sounds, brave Sam and his co-workers can be counted on to jump into a fire engine, hop onto a helicopter, or even launch an inflatable lifeboat to battle blazes, mount rescue missions, or provide medical attention to those in need.', NULL, NULL, 'Returning Series', 'S4C', '', 6.1, 39, '1987-11-17', '2024-11-12', 21.2322, 'cy', 'Sam Tân', 'http://www.firemansamonline.com', 359, 16, 1, 'Scripted', 'GB', '/sXsqaIOjemMuHxGu3XukIyVM7jN.jpg', '/dEPV4QKCdo8pqLN4g4h8pn6Jga7.jpg', '2026-04-03T17:14:36Z', '2026-04-03T17:15:10Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created