INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'6CCEE4AA0CE543108203868E44BD835E', 'Katie and Orbie', 10074, 188531, 1993, 'Katie and Orbie is a Canadian animated television series aimed at preschoolers, originally broadcast in Canada from June 2, 1997 by Family Channel and later aired in the United States on PBS from June 2, 1997 and on Disney Channel from June 2, 1997–December 31, 1999. In Canada, the series aired uninterruptedly on Family Channel and (beginning on 2007) Disney Junior (formerly called Playhouse Disney) until December 31, 2012. The series has also aired in several countries around the world.', NULL, NULL, 'Ended', 'PBS', '', 0.0, 0, '1993-05-03', '2003-06-09', 1.3407, 'en', 'Katie and Orbie', '', 78, 6, 0, 'Scripted', 'CA', '/52BNwVLgoqi8bGdOdlV98S93ZIJ.jpg', '/7Kn12mPS7f9tOfvnwX27nzuzjnr.jpg', '2026-04-03T17:11:20Z', '2026-04-03T17:11:47Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.ori