INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'7DE73ABB3D424DA38FD15FE548762C95', 'Paddington Bear', 7447, 82747, 1976, 'Paddington Bear is a series of British animated shorts based on the Paddington Bear book series by Michael Bond produced by FilmFair. This was the first television series based on the popular children''s book Paddington Bear. In the United States it was usually shown on pay television as filler in between programs. Its narrator was actor Michael Hordern. It was one of the few television programmes to combine a puppet show with cartoon - Paddington himself was a puppet, but other characters in the series were depicted as cartoon characters.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'7F6201F9072D41308BE5BD20B8D34B0D', 'The Real Housewives of Orange County', 10222, 80117, 2006, 'A view into the lives of several women and their families who live in one of the wealthiest communities in the country with the viewer taken "inside the gates" to show their lives aren''t always perfect.', NULL, NULL, 'Returning Series', 'Bravo', 'I make my own money, and I make my own rules.', 5.4, 68, '2006-03-21', '2025-11-20', 12.9505, 'en', 'The Real Housewives of Orange County', 'http://www.bravotv.com/the-real-housewives-of-orange-county', 347, 19, 1, 'Reality', 'US', '/mEg3ohdBkLOs0L1GmYGtiwyJXlE.jpg', '/3ZzSaTwUC7wNd9CNTDQ76eP6guG.jpg', '2026-04-03T16:35:28Z', '2026-04-03T16:56:27Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_a