INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'822343ABB68840B9B089D0B3DDCDB256', 'Breaking Bad', 1396, 81189, 2008, 'Walter White, a New Mexico chemistry teacher, is diagnosed with Stage III cancer and given a prognosis of only two years left to live. He becomes filled with a sense of fearlessness and an unrelenting desire to secure his family''s financial future at any cost as he enters the dangerous world of drugs and crime.', NULL, NULL, 'Ended', 'AMC', 'Change the equation.', 8.94, 17422, '2008-01-20', '2013-09-29', 154.9488, 'en', 'Breaking Bad', 'https://www.sonypictures.com/tv/breakingbad', 62, 5, 0, 'Scripted', 'US', '/ztkUQFLlC19CCMYHW9o1zWhJRNq.jpg', '/tsRy63Mu5cu8etL1X7ZLyf7UP1M.jpg', '2026-04-03T15:40:32Z', '2026-04-03T16:03:29Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at