INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'8639998CD0BA4C81848AD2088456B21B', 'The Real Housewives of Dubai', 196592, 413388, 2022, 'As the 11th city in the franchise, the series highlights a group of women navigating their relationships, careers, and supremely lavish and ultra-wealthy lifestyles in the United Arab Emirates. With the desert paradise of Dubai as the backdrop, this billionaire''s playground is known for its over-the-top opulence, jaw-dropping modern architecture and wild nightlife scene. Whether they''re coasting on a private plane, running their own empires or hosting on a private island, these glamourous, successful women are ready to serve up scorching hot drama and unexpected twists.', NULL, NULL, 'Canceled', 'Bravo', 'If you think money can’t buy you happiness, you clearly haven’t been to Dubai.', 6.2, 11, '2022-06-01', '2024-09-17', 1.9185, 'en', 'The Real Housewives of Dubai', 'https://www.bravotv.com/the-real-housewives-of-dubai', 29, 2, 0, 'Reality', 'US', '/nC8PyRTFwrs6xKDrGSJWoqcYBUR.jpg', '/8kGaLkIdPWly8GJTZtzZBNsSwQ7.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:54:16Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_na