INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'8E92650AC8BE4461AD477C8E4E7028AE', 'Old Bear Stories', 4737, 75500, 1993, 'In a playroom which is home to a variety of sentient toys, their leader, the wise and caring "Old Bear" had disappeared some time ago, having been put into the loft and forgotten. After the toys rescue him and bring him back down to the playroom, Old Bear again becomes their most respected toy. Each episode focuses on the adventures of Old Bear and his loveable friends in and about the playroom.', NULL, NULL, 'Ended', 'ITV1', '', 8.5, 3, '1993-10-03', '1997-12-24', 1.2608, 'en', 'Old Bear Stories', '', 41, 3, 0, 'Scripted', 'GB', '/r4VBugitcQFSfgnzJSWICFzkY1k.jpg', '/6CTJdIH7jTdQ8iRvK4iaZOiY1WX.jpg', '2026-04-03T17:18:55Z', '2026-04-03T17:19:00Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_