INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'8FA41B21585A4283B31DBE7C4F46ED32', 'Jackanory', 8861, 72645, 1965, 'Jackanory is a long-running BBC children''s television series that was designed to stimulate an interest in reading. The show was first transmitted on 13 December 1965, the first story being the fairy-tale Cap-o''-Rushes read by Lee Montague. Jackanory continued to be broadcast until 1996, clocking up around 3,500 episodes in its 30-year run. The final story, The House at Pooh Corner by A. A. Milne, was read by Alan Bennett and broadcast on 24 March 1996. The show returned on 27 November 2006 for two one-off stories.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'90D490FAC5EC40A5AAC3C70E29B32B31', 'Sister Wives', 34045, 193711, 2010, 'Husband Kody Brown, along with his four wives (only one of which is legally married to Kody) and their combined 18 children, attempts to navigate life as a "normal" family in a society that shuns their lifestyle.', NULL, NULL, 'Returning Series', 'TLC', '', 6.0, 51, '2010-09-26', '2026-02-01', 14.5429, 'en', 'Sister Wives', 'https://tlc.com/tv-shows/sister-wives/', 274, 17, 1, 'Reality', 'US', '/lnSXPiP9nYx23AbaekTCdTBq722.jpg', '/bpD0l55NTyHzIGX0QdTdogTk1ro.jpg', '2026-04-03T16:34:26Z', '2026-04-03T16:52:57Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
