INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'9D3D37FB870742FAA874DF8D61E4F530', 'Mister Rogers'' Neighborhood', 15, 77750, 1968, 'Mister Rogers'' Neighborhood is an American children''s television series that was created and hosted by namesake Fred Rogers. The series originated in 1963 as Misterogers on CBC Television, and was later debuted in 1966 as Misterogers'' Neighborhood on the regional Eastern Educational Network, followed by its US network debut on February 19, 1968, and it aired on NET and its successor, PBS, until August 31, 2001. The series is aimed primarily at preschool ages 2 to 5, but has been stated by PBS as "appropriate for all ages". Mister Rogers'' Neighborhood was produced by Pittsburgh, Pennsylvania, USA public broadcaster WQED and Rogers'' non-profit production company Family Communications, Inc.; previously known as Small World Enterprises prior to 1971, the company was renamed The Fred Rogers Company after Rogers'' death.', NULL, NULL, 'Ended', 'PBS', 'Won''t you be my neighbor?', 5.987, 119, '1968-02-19', '2001-09-07', 6.1762, 'en', 'Mister Rogers'' Neighborhood', 'https://www.misterrogers.org/', 871, 31, 0, 'Scripted', 'US', '/qhbeRYVg120cBmc9XvGxvk6EmJF.jpg', '/bvbOrvK0hQveMB6SmQoAwIuRToh.jpg', '2026-04-03T17:35:37Z', '2026-04-03T17:36:20Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'9EC4DB232CBC4508BDA8CA2796BC7346', 'The Really Wild Show', 5344, NULL, 1986, 'The Really Wild Show was a long-running British television show about wildlife, broadcast by the BBC as part of their CBBC service to children. It also runs on Animal Planet in the US.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'A4832EBCC15049F9966BC33E86A06DFA', 'Fraggle Rock', 2957, 76085, 1983, 'The Fraggles are a fun-loving community of creatures who live in a subterranean fantasy land where they love to play, sing and dance their cares away, sharing their world with the tiny Doozers and the giant Gorgs. The series teaches empathy and tolerance and encourages children to understand people different from themselves.', NULL, NULL, 'Ended', 'HBO', '', 7.3, 185, '1983-01-10', '1987-03-30', 14.764, 'en', 'Fraggle Rock', 'https://www.henson.com/fraggle-rock/', 96, 5, 0, 'Scripted', 'US', '/nyvNej9aHC2wydFflPMrASS6MF7.jpg', '/fyUt0I4tSnclpg7WZJVRKHMSjcz.jpg', '2026-04-03T17:34:59Z', '2026-04-03T17:35:53Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'A62FB7905C8F4D7D8C40D76543B40070', 'Between the Lions', 4302, 74776, 2000, 'Between the Lions is a PBS Kids puppet television series designed to promote reading. The show is a co-production between WGBH in Boston and Sirius Thinking, Ltd., in New York City, in association with Mississippi Public Broadcasting, in Mississippi. The show has won seven Daytime Emmy awards between 2001 and 2007. The target audience is children 4 to 7 years old. It has the same puppet style as Sesame Street and several season 2 episodes, notably in Dance in Smarty Pants, had a few characters from Sesame Street guest appearing. Between The Lions started its 10th and final season on September 20, 2010. The Show Ended in November, 22 2010 Along with Reading Rainbow', NULL, NULL, 'Ended', 'PBS', '', 7.5, 6, '2000-04-03', '2010-11-22', 6.8398, 'en', 'Between the Lions', 'http://www.pbskids.org/lions/', 140, 10, 0, 'Scripted', 'US', '/3MIfUYQvR58F99QFnSiwCo7fTnF.jpg', '/oAqPZZ4I2NPwZDRnwd2zZSAWmcr.jpg', '2026-04-03T17:12:27Z', '2026-04-03T17:12:35Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
