INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'AC75C382124642CD95B87E8AE011FFB6', 'The Magic School Bus', 7248, 71416, 1994, 'An eccentric schoolteacher takes her class on wondrous educational field trips with the help of a magical school bus.', NULL, NULL, 'Ended', 'PBS Kids', 'Seat belts, everyone!', 7.7, 126, '1994-09-10', '1997-12-06', 14.3285, 'en', 'The Magic School Bus', '', 52, 4, 0, 'Scripted', 'CA,US', '/3A70wxUpplD4V3IcL8WmNFBgAbV.jpg', '/pWZjTb2ixwVEzvnsvv3KYz5pvIs.jpg', '2026-04-03T17:37:47Z', '2026-04-03T17:37:54Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'AFC5387354E44581A0453B0871B9E185', 'Eyewitness', 88869, 256481, 1995, 'Dive into the field of natural science, Discover the Solar System or the various functions of the human body. The information is presented in the "Eyewitness Museum", a computer-generated science museum. Various exhibits are shown, and stock video footage is usually seen through large windows or other depressions in the wall.', NULL, NULL, 'Ended', 'BBC Two', 'See the world as never before', 6.0, 1, '1995-06-05', '1997-11-24', 2.7736, 'en', 'Eyewitness', '', 40, 3, 0, 'Documentary', 'GB', '/514KMLuumHPQyPDD3IOSerubtLh.jpg', '/ibPvNTOPWSuzeFpzAhpuvZ7YYPT.jpg', '2026-04-03T17:39:03Z', '2026-04-03T17:39:09Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = exclude