INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'B6B9D3AE627346ED9E99538F94677C34', 'McGee and Me!', 4642, 72267, 1989, 'After moving to a new home in Indiana, eleven year old aspiring cartoonist Nick Martin and his animated friend, McGee, learn lessons relating to growing up and morality.', NULL, NULL, 'Ended', 'Trinity Broadcasting Network', '', 7.3, 3, '1989-06-04', '1992-06-21', 2.4467, 'en', 'McGee and Me!', 'http://www.mcgeeandme.com/', 12, 2, 0, 'Scripted', 'US', '/pX4LUyTkAEZgRzGBMYvcn5dMgAG.jpg', '/fbydQkLcwe2ACzmHB0co0zcCIvv.jpg', '2026-04-03T17:40:08Z', '2026-04-03T17:40:13Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'BCDE3737B03B4A75B676BA4495CEB9D8', 'The Real Housewives of New York City', 14808, 84669, 2008, 'A fast-paced reality show that follows several incredibly busy and ambitious Manhattan women. Watch as they balance envious social calendars, challenging careers, and motherhood, with the hustle and bustle of the big city all around.', NULL, NULL, 'Returning Series', 'Bravo', 'New York City is my playground.', 5.7, 65, '2008-03-04', '2025-02-04', 13.2938, 'en', 'The Real Housewives of New York City', 'http://www.bravotv.com/the-real-housewives-of-new-york-city', 292, 16, 1, 'Reality', 'US', '/dzy5nUc4MfTdQFBdbUFAT1FRPLQ.jpg', '/cowrSDpkCkNcmg5fO7gstaZLR1B.jpg', '2026-04-03T16:35:21Z', '2026-04-03T16:55:54Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.creat