INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'C2E225504DCA4DA9B833E28E45132E0B', 'The Real Housewives of New Jersey', 18204, 89831, 2009, 'We head to the Garden State for this installment of the “Housewives” franchise, focusing on affluent Jersey girls who are more than just friends. The cast has changed through the seasons but the featured housewives through the years have included Caroline Manzo, a devoted wife and mother of three adult children; former Las Vegas cosmetologist Jacqueline Laurita, who is now a full-time housewife; and Teresa Giudice, a mother of four who runs her household without help from a nanny or personal assistant.', NULL, NULL, 'Returning Series', 'Bravo', 'You’ll never see how toxic someone is until you breathe fresher air.', 6.0, 63, '2009-05-12', '2024-08-11', 7.0479, 'en', 'The Real Housewives of New Jersey', 'http://www.bravotv.com/the-real-housewives-of-new-jersey', 252, 14, 1, 'Reality', 'US', '/n3ZNgp7IpQOUXoGoV8svZccZeoP.jpg', '/12Xbio78KHTn5qO94XlE6s8gtQb.jpg', '2026-04-03T16:35:14Z', '2026-04-03T16:55:16Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, 