INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'C93CCFA02B504B25A25CC6F531496E68', 'The Demon Headmaster', 19094, 72455, 1996, 'The Demon Headmaster is a British television series based on the children''s books by Gillian Cross of the same name. Made for CBBC, the drama was first broadcast between 1996 and 1998. The first series contained six episodes, and aired twice weekly from 2 to 18 January 1996, the second series contained seven episodes, and aired once a week from 25 September to 6 November 1996, and the third series contained six episodes, and aired twice weekly from 6 to 22 January 1998.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'CAAA394A75034A13B3B9A2F97AA40065', 'The Berenstain Bears', 4665, 72502, 2003, 'We follow a family of bears, known as the Berenstain Bears, as they figure out life together. With friendly neighbors and close friends, the journey is never boring. Inspired by the book series written by Stan and Jan Berenstain.', NULL, NULL, 'Ended', 'Treehouse TV', '', 6.6, 18, '2003-01-06', '2004-09-28', 4.5069, 'en', 'The Berenstain Bears', 'http://www.berenstainbears.com', 80, 3, 0, 'Scripted', 'CA', '/cRA1KVomv7d9avL7UpdPBJmASrv.jpg', '/8Ehogxv09PYKQkqVibwS4mcpg5C.jpg', '2026-04-03T17:40:21Z', '2026-04-03T17:40:27Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
