INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'D0C42B0DAF0445358B6EC153528A949B', 'Bill Nye the Science Guy', 3483, 78494, 1993, 'It''s "Mr. Wizard" for a different decade. Bill Nye is the Science Guy, a host who''s hooked on experimenting and explaining. Picking one topic per show (like the human heart or electricity), Nye gets creative with teaching kids and adults alike the nuances of science.', NULL, NULL, 'Ended', 'PBS', '', 7.276, 87, '1993-09-10', '1998-06-20', 8.178, 'en', 'Bill Nye the Science Guy', 'https://billnye.com/', 100, 5, 0, 'Scripted', 'US', '/xdGGiQ8gBEwjyafLxW34IK8sblZ.jpg', '/7BG0EAfPn037Sj9h1cAB2srqQSX.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:47Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'D23BF5F854C2468A94F00AA0E8D7D130', 'Wishbone', 2152, 76132, 1995, 'Wishbone is a children''s television show. The show''s title character is a Jack Russell Terrier of the same name. Wishbone lives with his owner Joe Talbot in the fictional modern town of Oakdale, Texas. He daydreams about being the lead character of stories from classic literature He was known as "the little dog with a big imagination". Only the viewers and the characters in his daydreams can hear Wishbone speak. The characters from his daydreams see Wishbone as whatever famous character he is currently portraying and not as a dog.', NULL, NULL, 'Ended', 'PBS Kids', '', 8.0, 35, '1995-09-10', '1997-03-12', 5.1747, 'en', 'Wishbone', '', 50, 2, 0, 'Scripted', 'US', '/1cheNK4CBKopFScmgKP7bYjV3xs.jpg', '/pvnqWAu0b7wZtSq0hFqT3cWOkhg.jpg', '2026-04-03T17:10:41Z', '2026-04-03T17:10:47Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded