INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'F9B2AD8612094164A1134082814F1352', 'The Crocodile Hunter', 1904, 90601, 1997, 'Australian host Steve Irwin and his wife Terri run a wildlife refuge. Their shared passion is educating the world about wildlife, including the much feared crocodile and numerous venomous snakes. Steve''s specialty is the capture and relocation of crocodiles. No animal appears too threatening to Steve, his true respect for animals is the foundation for everything he does.', NULL, NULL, 'Ended', 'Animal Planet', '', 7.6, 33, '1997-04-05', '2004-06-18', 5.9687, 'en', 'The Crocodile Hunter', '', 69, 5, 0, 'Documentary', 'AU', '/youExJaJ4EW8jjDllu0emOJAIKi.jpg', '/v48dSrKSKD3C5aLJofx4bnhYwQ.jpg', '2026-04-03T17:39:09Z', '2026-04-03T17:39:30Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'FD00C1EF7EC74F90BBECF9EBCC6D410D', 'Theodore Tugboat', 3160, 71612, 1993, 'Theodore Tugboat is a Canadian children''s television series about a tugboat named Theodore who lives in the Big Harbour with all of his friends. The show originated in Halifax, Nova Scotia, Canada as a co-production between the CBC, and the now defunct Cochran Entertainment, and was filmed on a model set using radio controlled tugboats, ships, and machinery. Production of the show ended in 2001, and its distribution rights were later sold to Classic Media. The show premiered in Canada on CBC Television, then went to PBS, was on Qubo in the US, and at one time, had appeared in eighty different countries.
INSERT INTO tv_shows (id, title, tmdb_id, tvdb_id, year, overview, plot, shelf_suggestions, status, network, tagline, vote_average, vote_count, first_air_date, last_air_date, popularity, original_language, original_name, homepage, number_of_episodes, number_of_seasons, in_production, type, origin_country, poster_key, backdrop_key, created_at, updated_at) VALUES (X'FF372C479C4A4C3281FDE489570667DF', 'Pingu', 9262, 75669, 1986, 'Playful penguin Pingu lives with his family in Antarctica, where he often finds himself caught up in mischievous high jinks with his pal Robby.', NULL, NULL, 'Ended', 'CBeebies', '', 6.9, 157, '1986-05-28', '2006-03-03', 8.2629, 'en', 'Pingu', '', 156, 6, 0, 'Scripted', 'CH,GB', '/nLE7NR3EsEbv2NfG0bLIaOEhGfY.jpg', '/10UOUxOjmLCwGOvNXNaiIdWXav.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:51Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, tmdb_id = excluded.tmdb_id, tvdb_id = excluded.tvdb_id, year = excluded.year, overview = excluded.overview, plot = excluded.plot, shelf_suggestions = excluded.shelf_suggestions, status = excluded.status, network = excluded.network, tagline = excluded.tagline, vote_average = excluded.vote_average, vote_count = excluded.vote_count, first_air_date = excluded.first_air_date, last_air_date = excluded.last_air_date, popularity = excluded.popularity, original_language = excluded.original_language, original_name = excluded.original_name, homepage = excluded.homepage, number_of_episodes = excluded.number_of_episodes, number_of_seasons = excluded.number_of_seasons, in_production = excluded.in_production, type = excluded.type, origin_country = excluded.origin_country, poster_key = excluded.poster_key, backdrop_key = excluded.backdrop_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
