INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'02CDC01216D24444B010B45AD42283B9', X'5CC5CB2F38CF4A648A109007E89133ED', 1, 'Miniseries', 'Four Edwardian children find a strange egg in their newly-arrived Persian carpet. It hatches into a Phoenix bird that grants wishes and also transforms the rug into a magic carpet, which takes them on a series of adventures all over the world and at home.', NULL, '1997-11-16', '2026-04-03T17:18:35Z', '2026-04-03T17:18:35Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
