INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'0987F081B3B74E3CABB7795E56C279D5', X'87AF6181D36D459187C233400A5F013C', 4, 'Season 4', 'While an unexpected turn of events might force Frankie to reevaluate her career at the car dealership, Mike''s made it his mission to ensure that Axl somehow earns a sports scholarship to college next year. Meanwhile, Sue''s not only navigating high school, but wants to navigate Indiana roads by getting her driver''s license. It''s no wonder that youngest son Brick keeps his nose in a book!', '/7WaBgPSBtS53IS44BvhY4wvCQyo.jpg', '2012-09-26', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'09DB9EAE334C4283929AF00ECB3FD845', X'5763807E668F42F49F90716799017463', 51, '2008', '', NULL, NULL, '2026-04-03T17:22:07Z', '2026-04-03T17:22:07Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'0A9ABA05559F4DB4A6CA8AC35CC378D1', X'1F54A881CF7D4CCE9BC738768C2CF36E', 6, 'Season 6', 'Following the shocking developments at the conclusion of season five, survivors from all parts of Westeros and Essos regroup to press forward, inexorably, towards their uncertain individual fates. Familiar faces will forge new alliances to bolster their strategic chances at survival, while new characters will emerge to challenge the balance of power in the east, west, north and south.', '/p1udLh0gfqyZFmXBGa393gk8go5.jpg', '2016-04-24', '2026-04-03T15:40:37Z', '2026-04-03T15:40:37Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'0AB4DFB258C94E52B5BF49BBA0BFC597', X'822343ABB68840B9B089D0B3DDCDB256', 1, 'Season 1', 'High school chemistry teacher Walter White''s life is suddenly transformed by a dire medical diagnosis. Street-savvy former student Jesse Pinkman "teaches" Walter a new trade.', '/1BP4xYv9ZG4ZVHkL7ocOziBbSYH.jpg', '2008-01-20', '2026-04-03T15:40:32Z', '2026-04-03T15:40:32Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
