INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'0D2293DDDFCA45918F9A0FBE023F8D1C', X'3F51CDD308DF42F8806F78D3958C3166', 1, 'Season 1', 'The witcher Geralt, a mutated monster hunter, struggles to find his place in a world in which people often prove more wicked than beasts.', '/5BvFJfi3qBxTFaLKsft202YeqGl.jpg', '2019-12-20', '2026-04-03T15:40:45Z', '2026-04-03T15:40:45Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'0D24C74283F24F378A5D0B09C7DF6A7F', X'3F51CDD308DF42F8806F78D3958C3166', 4, 'Season 4', 'After the Continent-altering events of Season Three, Geralt, Yennefer, and Ciri find themselves separated by a raging war and countless enemies. As their paths diverge, and their goals sharpen, they stumble on unexpected allies eager to join their journeys. And if they can accept these found families, they just might have a chance at reuniting for good...', '/d74mHAWr5Q73O7lINSME4YBDhhh.jpg', '2025-10-30', '2026-04-03T15:40:46Z', '2026-04-03T15:40:46Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
