INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'1CFDFF3AD5314A9EAFC98010A979DD27', X'1DF66CF33A18440F8ACD9A7EF9C6E204', 2, 'Prince Caspian / The Voyage of the Dawn Treader', 'Prince Caspian of Narnia wonders and dreams about the old days when animals talked, and there were mythical creatures and four rulers in Caer Paravel. But his uncle and aunt don''t like to hear him thinking of such things, and plan to murder him and take his throne. Caspian''s tutor Dr Cornelius manages to save him, and not only teach him about the old ways, but bring him into and introduce him to the real Narnia. But Caspian''s plight is desperate, and he must use the legendary horn to call help from another world: Peter, Susan, Edmund, and Lucy.
INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'1D39506B06B84F9391360208069BD7E4', X'BCDE3737B03B4A75B676BA4495CEB9D8', 3, 'Season 3', 'Two fresh faces, Sonja and Jennifer, join the housewives as they navigate family commitments, high-powered careers and upper-crust society.', '/n5SLtEJqeOlLl9JgrU49HPsNksy.jpg', '2010-03-04', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
