INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'21384B9C43FA410CB89D102E7CF9129B', X'90D490FAC5EC40A5AAC3C70E29B32B31', 4, 'Season 4', 'After living in separate rental homes for the past two years, the Browns are one step closer to fulfilling their dream of being together under one roof, moving into four adjacent houses in the same neighborhood. But now they have four large mortgages and a struggling start-up jewelry business. Meanwhile, Meri finally decides on whether or not to accept Robyn''s offer to be her surrogate, but will Kody agree with her decision? And as more kids prepare to leave the nest, Kody and the wives have a surprise in store that will rebuild the closeness the family once shared back in Utah.', '/spQ3LzMIVbZnRmNFJlgOLpjnOO6.jpg', '2013-07-21', '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
