INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'228172B6FED04226ACDF820049D2C72E', X'90D490FAC5EC40A5AAC3C70E29B32B31', 12, 'Season 12', 'Last season, Kody Brown, his four wives, and their families relocated to Flagstaff, Arizona where they hoped to start an exciting new chapter of their lives. Little did they know that settling down in temporary homes before breaking ground on the land they purchased would be harder than they thought. This season, we see the Browns continuing to work through their new lifestyle of living apart from one another and the stressful decisions they must make about their future home. Like the rest of the world, COVID-19 puts an extra strain on the family and the Browns'' big gatherings and large parties that brought the family together are now a thing of the past.', '/3irSP04YtsI4ouMhpl5QSj3UC5A.jpg', '2021-02-14', '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
