INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'54C290142DBD49FFA23FCF4C546E0B3A', X'BCDE3737B03B4A75B676BA4495CEB9D8', 6, 'Season 6', 'Season six sees the return of Aviva Drescher, Sonja Morgan, Carole Radziwill, Ramona Singer, and Heather Thompson, who are joined by model and businesswoman Kristen Taekman as they navigate their hectic lifestyles of jam-packed social calendars, careers, relationships, children and the hustle and bustle of city living. Also returning in a recurring role this season is Countess LuAnn de Lesseps.', '/egMC4TND81m6MUQEbdplmoeWLD8.jpg', '2014-03-11', '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
