INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'650BAC937B5941FCB277DC6F8BDCD7BB', X'87AF6181D36D459187C233400A5F013C', 8, 'Season 8', 'In Season 8, the Heck kids break out of their comfort zones and navigate new situations. Axl discovers the love of his life. Sue changes her major to drama. And Brick has made it his mission to fit in with his high school peers. With an emptier nest, Frankie and Mike cut back on the parental duties – easier said than done as parenting continues no matter where your kids are!', '/aK7rPyRLv8NSCUk12qlqxjNNlOk.jpg', '2016-10-11', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
