INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'6C71887AD6E341F1AA7CF482ABC104D2', X'1DF66CF33A18440F8ACD9A7EF9C6E204', 3, 'The Silver Chair', 'Shipped off to a miserable school, Eustace finds companionship in Jill Pole. Running from bullies, the two hide in a garden shed that magically transports them into the magical world of Narnia, where they''re entrusted with a task by Aslan: to rescue the king''s stolen son, Prince Rilian. Together, with Puddleglum the Marshwiggle, Eustace and Jill must travel north across the mountains, dodge giants, and journey down into the earth itself to rescue Rilian from the mysterious evil that holds him bound there.', '/Ai2kAEB8VYDm1PZCaV4h3v626Og.jpg', '1990-11-18', '2026-04-03T17:17:41Z', '2026-04-03T17:17:41Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
