INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'7F5AE98B491340C2A54254BC3F1EC0A4', X'74E16096AF9F436EA57F923E0F6239E1', 6, 'Season 6', 'It’s season six and Rick and Morty are back! Pick up where we left them, worse for wear and down on their luck. Will they manage to bounce back for more adventures? Or will they get swept up in an ocean of piss! Who knows?! Piss! Family! Intrigue! A bunch of dinosaurs! More piss! Another can’t miss season of your favorite show.', '/cvhNj9eoRBe5SxjCbQTkh05UP5K.jpg', '2022-09-04', '2026-04-03T15:40:43Z', '2026-04-03T15:40:43Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
