INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'879892836FEA40D78D9122C4947DB105', X'90D490FAC5EC40A5AAC3C70E29B32B31', 11, 'Season 11', 'The Sister Wives have just moved to Flagstaff, Arizona, where they find that the ups and downs of their family''s polygamist lifestyle are as dramatic as they''ve ever been. Angry neighbors drive one wife out of her rental house and the cost of the many properties the family needs for Kody''s four wives and many kids are threatening a financial disaster. In hopes of reducing this burden, Kody makes plans for the whole family to build one giant house, but the wives are not so sure. And an argument erupts when the Browns try to divide up their new property. Tensions with first wife, Meri, are still unresolved and she goes back into therapy with Kody to try to fix their relationship. Of course, there''s much to celebrate as well. Meri''s daughter Mariah and her girlfriend Audrey get engaged and Janelle''s daughter Madison has a second baby!', '/kbQTJ27kIJ4smUIKtCEBtclgybq.jpg', '2020-01-05', '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
