INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'ABEB8D075C864F6AA110B11CBA2A4138', X'5648CD2A194D4AB9A2AEB2F9743F463C', 3, 'Book Three: Fire', 'Aang wakes up from his battle with Azula to discover that Ba Sing Se has fallen and the world thinks he''s dead. So he and his friends set off undercover across the Fire Nation to find Fire Lord Ozai before the Day of Black Sun. Prince Zuko returns home as the triumphant son, but soon finds the honor he so greatly craved from his father is worthless. New alliances are formed and Team Avatar forges a new plan to stop the Fire Lord. But will they find him in time?', '/roPE4jaHawj1Dm6uIXJHuLDpkNy.jpg', '2007-09-21', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
