INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'B8C1B631985045F39361CDAD5571A492', X'90D490FAC5EC40A5AAC3C70E29B32B31', 14, 'Season 14', 'Last year, Christine kicked Kody out of her home, which was one of the hardest things she has ever done. But now, formally putting an end to their marriage turns out to be even harder. And when she has to tell her sister wives and her children, nobody takes it well. She is determined to move to Utah to be with her older children. The stresses multiply as people begin to take sides.
INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'B91685B5C0D44040B72E620169541BFC', X'7F6201F9072D41308BE5BD20B8D34B0D', 2, 'Season 2', 'The second season comprises ten episodes, each delving into the personal and professional lives of the cast members. The series provides an intimate look at their daily routines, family dynamics, and social interactions within the exclusive community. Notably, Kimberly Bryant made a single-season appearance, while the other women continued to feature in subsequent seasons.', '/tXrQJXr4CeLMgpmwGlEGtAynevE.jpg', '2007-01-16', '2026-04-03T16:35:29Z', '2026-04-03T16:35:29Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
