INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'BB360D4475EF4AC39D24461C5C182502', X'822343ABB68840B9B089D0B3DDCDB256', 0, 'Specials', '', '/4RaIvSQgHHHPfaI1jFqaMR8UJWM.jpg', '2009-02-17', '2026-04-03T15:40:32Z', '2026-04-03T15:40:32Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'BB5A884361814A6DBFDF33EF2C6BE7B8', X'04E6F8E4B4C14E78B4529E0420D9B098', 10, 'Season 10', 'In Season 10 , Cynthia is free, fabulous, and embracing all life has to offer. Eager to move forward, Shereé is focusing on healing old relationship wounds and preparing for an empty nest with her daughter heading off to college. Kenya, who focuses on growing her beauty empire, is over the moon after a whirlwind romance. Fully vindicated after last season''s shocking allegations, it''s business as usual for Kandi, who is juggling managing the popular Old Lady Gang restaurant and planning the highly-anticipated Xscape reunion. Excited for a new start, Porsha is looking for love and embracing a new vegan lifestyle. Fresh off performing in her one-woman comedy show and back in the housewives universe, NeNe returns more determined than ever to build her empire and support her family. And in her first time rejoining the group since Season 5, Kim is back on the scene and ready to shake things up.', '/jgA336eJVvgXWBgOnpQXMQ2amAB.jpg', '2017-11-05', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
