INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'BC6D3E376E5E472D90AA4C6DF1F7DEF8', X'90D490FAC5EC40A5AAC3C70E29B32B31', 5, 'Season 5', 'Season 5 begins with two daughters graduating high school, Mykelti and Madison. The grown ups plan to lip sync a song to celebrate, but it brings out some negative feelings for Janelle, who is not comfortable being so outgoing and admits to being embarrassed in public by the others'' behavior. And a deeper issue of feeling like she''s not heard bubbles to the surface and she sees a therapist to discuss that along with her challenging relationship with first wife Meri. On a business level, the family discusses whether to turn down investors'' money and keep full ownership of Sisterwives'' Closet and whether to keep the products all their own creations or branch out and resale other artists'' designs and products. Christine''s mother moves in with her in Las Vegas, and in episode four, the Browns allow two anthropologists to live with them for two days to see the inner workings of polygamy, an arrangement that could either put their lifestyle in a positive or negative light.
INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'BCAB920A51A54CBBAA5941578A0EB005', X'55596F061A134DA591DF218B92FCA64A', 7, 'Season 7', 'In season seven, returning housewives Erika Girardi, Lisa Vanderpump, Kyle Richards, Lisa Rinna, and Eileen Davidson welcome new housewife Dorit Kemsley and friend Eden Sassoon.', '/jhZDQtwo2O8ITkbVKSZoZiEIVfb.jpg', '2016-12-06', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
