INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'D7FF9136A8334C43A37CA985A34F45A9', X'90D490FAC5EC40A5AAC3C70E29B32B31', 15, 'Season 15', 'In this season, Kody is still grappling with the fallout from his divorce with Christine, and he is struggling in many of his other relationships. Christine, however, is learning to love who she is on her own by planning trips and celebrations along the way. Robyn is the only wife secure in her marriage yet devastated that her original dream of a big, happy polygamist family is falling apart. Meri is steadily coming to realize that Kody isn''t going to have the change of heart she has been waiting for and makes a life-changing decision. Lastly, Kody has been spending less and less time at Janelle''s house, and, after an explosive fight, she kicks him out. Through their transparency and vulnerability, the Browns shed light on the hardships their family is struggling to overcome.', '/nBtzYRr6mSg4MMhzkQqXNDlp5pm.jpg', '2023-08-20', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
