INSERT INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES (X'DD4554C26E74499A808A7DAD5F2BE50F', X'822343ABB68840B9B089D0B3DDCDB256', 5, 'Season 5', 'Walt is faced with the prospect of moving on in a world without his enemy. As the pressure of a criminal life starts to build, Skyler struggles to keep Walt’s terrible secrets. Facing resistance from sometime adversary and former Fring lieutenant Mike, Walt tries to keep his world from falling apart even as his DEA Agent brother in law, Hank, finds numerous leads that could blaze a path straight to Walt. ', '/r3z70vunihrAkjILQKWHX0G2xzO.jpg', '2012-07-15', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z') ON CONFLICT(id) DO UPDATE SET tv_show_id = excluded.tv_show_id, season_number = excluded.season_number, name = excluded.name, overview = excluded.overview, poster_key = excluded.poster_key, air_date = excluded.air_date, created_at = excluded.created_at, updated_at = excluded.updated_at;
