INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0011D9C5B7584175882F7021319FE820', X'FB06E6584B5446828783EAA88A99E61E', 7, 'Best Wishes', 'After wishes for snow and cupcakes come true, Buster, Francine, and Binky are convinced that George has Wish Mojo, and put him under incredible pressure to use his new Wish Mojo to wish for even more snow.', '2014-10-02', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
