INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'014E77DFDEE14A39B0F10306DF2F208A', X'208E80DE61E34A2F857FC667FFC29134', 15, 'Anne Murray', 'Scooter bugs everyone by leaving his skateboard lying around. Kermit trips on it and smashes a set. Later, Anne performs while the Muppets all dance on skateboards.', '1980-02-01', 26, '/xgBPDCQBcIMZb1rmsMJehSZ3kBX.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
