INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'01B8CDE87CF7499295769AC275DDC2FC', X'02C86AE38C3B4CC08E1F0B27D01DCD91', 6, 'Dream a Little Nightmare', 'Shereé and Kim make the best out of a boating trip on the "Redneck Riviera," Atlanta''s Lake Lanier. Shereé assembles an army of publicists, designers, event planners to get her fashion line, She by Shereé, off the ground. She moves quickly to turn her vision into a reality and attempts to plan a high-end fashion viewing of her samples in a matter of weeks. With the support of her husband, Gregg, NeNe pursues DNA testing to answer the question about the paternity of her father. Lisa''s husband Ed is gearing up to get back in the game after a year of rehabilitating an injury, though Lisa wishes he would not go back to the NFL. DeShawn invites all of the ladies to her home for a sunset barbeque to mend broken fences. NeNe agrees to be civil, but is upset when some of the women don''t show. Sheree refuses to let her investors and the press see her sweat when the She by Sheree show starts to unravel at the seams.', '2008-11-11', 43, NULL, '2026-04-03T16:34:44Z', '2026-04-03T16:34:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
