INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'028A6902905E46CABDE2EB0E25732CBA', X'F2D25A2BCDD546BA91F4E490E0B002E5', 13, 'Alphabet Dragon', '', NULL, 29, NULL, '2026-04-03T17:12:15Z', '2026-04-03T17:12:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0294683BF4F84FDDBC958D61AAD3581C', X'4B2A19E02FAE492EBC31F78E63D88EBC', 9, 'Cowboys and Cannons', 'Light a fuse with Pawn Stars when a 19th century sun dial cannon explodes into the shop. Will Rick blast out the big bucks or will the deal fizzle out? Next, a signed helmet from one of Hollywood''s biggest flops, Heaven''s Gate, gallops in. Will Rick cowboy up an offer or ride off into the sunset? Then, sterling silver baby figurines gleam their way into the shop. Will Rick take a shine to them or will the deal get tarnished? And later, a 1964 Beatles board game plays its way in. Will Corey score a fab win, or lose his turn?', '2016-09-07', 21, '/ix7ZbB8w9Eb8ZQNOgMISDZpbKQT.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
