INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'029E76E908854D0D800AE80427F0D27D', X'6E0BE2A3A234453BABB70BA535A93601', 20, 'Franklin the Detective', 'Franklin tries to find out where the ball went during a game of baseball played by Beaver, Fox and Raccoon. All the clues point to it falling in the river, but Bear points out that it knocked down a branch as it got stuck in a tree.', '2000-07-09', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'02AF1261CCEE44678A4DEA53D78C61BA', X'B1D55597D9D24EEEAB9546DBB163291A', 20, 'Pingu in the Ice Cave', 'Pingu and his parents are doing odd jobs when Pingo comes over and asks Pingu on a playdate. The two go off hysterically. They play with their ball and have fun at first, but get a bit carried away, and the ball goes off into an overhang in the ice. When they try to retrieve it, they fall through a sort of trapdoor in the ice and into an ice cave. The entrance collapses above them, and they must find another way out. After looking around in the dripping, echoing caverns, they see a slope to the surface - which happens to be on the other side of a deadly chasm. Pingu manages to cross by swinging on a rope, which comes off as he gets to the other side. He then lassoes the ropes onto a small stalagmite next to Pingo, and tells Pingo to hang onto it and shuffle across the chasm, with Pingu holding onto the rope on the other side. But Pingu begins to slip due to Pingo''s weight on the rope and he nearly falls. Pingu quickly tugs on the rope, pulling Pingo back up unharmed and catches him just in time, and the two crawl out cheerfully to the surface.', '1990-05-05', 5, '/6R9Opfbm5BdeYp46gRcOXpqCDPn.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
