INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'02D837184A304CBF849057C99D534EBD', X'5C4E51C6E20746AD875C72988EB1E13E', 8, 'Patton Pending', 'The Pawn Stars snap to attention as they check out a photo album signed by one of history''s greatest military leaders - General George S. Patton. Containing pictures labeled as "classified," can the gang make a strategic advance for these images from World War II or will they be out-maneuvered and forced to retreat? Then, it''s off the races when Rick and Chumlee come across a pair of jockey boots autographed by horse-racing legend Willie Shoemaker. Will Rick chomp at the bit for this rare piece of sports history or will he back the wrong horse? And later, a man comes in hoping to sell his Kevlar bulletproof vest. Will Corey take aim at buying this heavy-duty body armor or is this deal too tough to penetrate?', '2011-04-25', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
