INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'034A9B8AC9164A9C9033A054B3046B02', X'70C8CB4624944DD498F66BFB9B3FAF73', 15, 'Bumpy Ride', 'The Pawn Stars are presented with the opportunity to add one of the world''s most recognizable trophies to their collection - a Grammy. Will the gang put up the cash to get the gold or will the deal hit a sour note and be taken off the charts? Then Corey and Chumlee hope to buy an incredibly rare mini Coca Cola cooler from the 1930s. Can they shake up a good deal and restore this classic piece of Americana, or will the negotiation fizzle out? And later a married couple wheel up to the shop with an outrageous rickshaw used to carry tigers in the Siegfried and Roy stage show. Will the shop make an offer and get into the pedicab business or will the deal steer itself out of control?', '2010-03-29', 21, '/kGb1aU5EJt3Tsa4Whhsxf4IQQSI.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
