INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'03576469267B40A08B15B24DEBEF58DD', X'0BBD380C5CB846A68838B5D60223C073', 24, 'Vincent Price', 'In honor of guest star Vincent Price, the show is filled with monsters, ghosts, bats, vampires and spooky situations. A three-headed monster auditions for the show: "We sing!" "No, we dance!" "No, we tell jokes!"', '1977-04-23', 26, '/wavAIJzV2hidngoeGdrLMH3SCqk.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0358852222D2496EB55B4A3EDF99A1CF', X'E4023DA233D74A2BA04ACA449BD23935', 13, 'Valentine’s Day VI', 'Valentine''s Day aims its sights on the Heck kids when a nervous Brick finds out that his quirky girlfriend Cindy wants him to kiss her on the special day, Darrin asks Frankie and Mike to help out with an exciting scavenger hunt he''s putting together for Sue, and Axl begins to question his girlfriend Devin''s request that he not give her anything for what she considers to be a lame tradition.', '2015-02-11', 22, '/jmrvSetoohqJZAGavJDpXvhunyN.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'035D0E28D56146BDB3DF25DBB49AEBA0', X'D3E13496E3C8490383B45A31FEDEE232', 15, 'Bato of the Water Tribe', 'Aang feels neglected as Katara and Sokka reunite with Bato, an old friend of their father’s from the South Pole. They begin to reminisce on their times in the past while they wait for a message to arrive from their father. Aang believes Katara and Sokka will abandon him and go out to find their father should the message arrive. However, when the messenger gives Aang the message to give to Bato, Aang betrays his friends in a way Katara or Sokka could never imagine. However, when Zuko recruits a bounty hunter named June to track Aang down, his friendship is put to the test as he must deal with the fact that he betrayed his friends while defending himself from yet another fight.', '2005-10-07', 25, '/sBSdSLVgW6JxpYKhEQiWGbVl1Q3.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0363C6B51B4B4C7DB129EE83D646C4B3', X'4892E2AF46C14B4EAC81EAC161B5A347', 2, 'Episode 2', 'STOP PRESS -BLUE PETER INDOOR RIDING SCHOOL OPENED BY PRINCESS ANNE  That was the welcome news that greeted handicapped riders in Tyne and Wear this summer. The Indoor School was provided by some of the old wool and cotton donated by viewers to the Clothes Horse Race Appeal.  Today PETER reports on the Official Opening and talks to some of the disabled children who are now able to ride whatever the weather.', '1977-09-15', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
