INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'03957D6E762F4CE9A4E0A131249B89F8', X'70C8CB4624944DD498F66BFB9B3FAF73', 6, 'Tattoos and Tantrums', 'The Pawn Stars have a chance to buy a saddle that may have been used by Kevin Costner in Dances with Wolves. Will the gang pony-up and make the deal or will they let it ride off into the sunset? Then Rick looks to buy a late 1800s Winchester rifle that was one of first lever-action repeating rifles ever made. Can he load-up and make a big bang of a deal, or will this negotiation have too much of a kickback for him to handle? Then Corey meets a man hoping to sell his tattoo kit. Will Corey make the deal and get inked-up or will he pass on the deal and get ink-ed up anyway?', '2010-02-01', 21, '/wHAbaGtw1Ktmob2fu781VDYIlTk.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
