INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'03FB0703F7FA4E17B82D1095CC992B58', X'70D9E39768134785887D27D034928BAE', 13, 'Pingu and the Paper Aeroplane', 'Pingu and Pingi are on their way to school on Pingu’s sledge, when they hit a bump and fall off. Pingo comes past on his scooter, has a good laugh at their predicament and continues on his way. Later at school someone in the class throws a screwed up piece of paper into the air. It hits Pingu on the head and bounces off as Pingi notices. Pingu realizes who threw the paper when Pingo chortles, and throws a screwed up piece of paper from his own exercise book back at Pingo. Pingo picks up the piece of paper thrown by Pingu, straightens it out, makes a paper plane and throws it into the air. It hits the teacher on the back of the head. The teacher asks the class who it was, and Pingo says that it was Pingu. Pingu can’t explain away why the paper the plane is made from is from his exercise book, and gets sent to stand in the corner. Pingu then spots Pingo’s scooter and plans revenge. He sneaks over and unscrews the nut that secures the front wheel on the scooter. He throws the wheel-nut away and sneaks back into the corner. When school finishes, Pingu is just leaving when he sees Pingo offering Pingi a go on his scooter. She only gets a short distance before the front wheel comes off the scooter and she falls off. Pingu goes over to Pingi, while Pingo wonders what has happened to his scooter and how he’s going to get home. Pingu is just about to leave with Pingi and although he feels amused at first, he feels some remorse, so the front of the scooter is propped on to the back of the sledge and, with Pingu and Pingi on the sledge and Pingo on the scooter, they ride off together.', '1995-09-07', 5, '/lkmkstRKE9c8HEp3vXTnYPjTKA0.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'03FF49579B744689B6A15C0EFF5BE5CC', X'A6EFE88301134477BF0657B42A3770EE', 12, 'The Reverse Peephole', 'Elaine gets into a hassle regarding fur; Jerry stops carrying a wallet, while George suffers from his overstuffed one; Kramer keeps Newman from being evicted.', '1998-01-15', 22, '/qGjKrw6md0t1G0ccHHaUaOvxQJ.jpg', '2026-04-03T16:34:12Z', '2026-04-03T16:34:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
