INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0406AB1526D547F49ED27F51C161F0FD', X'0AB4DFB258C94E52B5BF49BBA0BFC597', 2, 'Cat''s in the Bag...', 'Walt and Jesse attempt to tie up loose ends. The desperate situation gets more complicated with the flip of a coin. Walt''s wife, Skyler, becomes suspicious of Walt''s strange behavior.', '2008-01-27', 49, '/AbMoecO0ZZio0LcgeLxlzdyGs6X.jpg', '2026-04-03T15:40:32Z', '2026-04-03T15:40:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0409C93FD6094168B251E5126F3C8E39', X'1D713CA64E174F84949C8CFD98514127', 19, 'Birthday Blues', 'Salute the troops with the Pawn Stars when a military ID signed by Marilyn Monroe entertains the shop. Will Rick be hypnotized by the rare beauty, or will this scene-stealer''s signature be a fake? Then, a customer scales in with a First Edition of Beethoven''s 6th Symphony. Can Rick conduct a great sale or will he be out of tune? And later, when Corey and Antwaun are caught sneaking around when planning Chumlee''s Birthday celebration. Will they throw the party of the year or will Chumlee spoil his birthday surprise?', '2014-10-02', 21, '/j1jyf3lj904IHV1YJyFxzTbgfaN.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'040A26FE645546BBAB22B37D8E7FFCBE', X'C4D795AE6AFA47D698194DD057030A3C', 15, 'Let''s Make It Official', 'As Porsha and Dennis prepare for their baby''s arrival, the ladies speculate about when they will take their relationship to the next level; Eva deals with the stresses of wedding planning; Kandi and Todd struggle with the decision to use a surrogate.', '2019-02-17', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'040EB6E2F55A4A45B6BEADFAB63AA0B9', X'081F12E29239494690A147763B935DB2', 5, 'Episode 5', '', '1986-02-18', 25, NULL, '2026-04-03T17:21:14Z', '2026-04-03T17:21:14Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'04119DFC84FD497C8B4B11B197AE9252', X'AE8F64D94B834147A44CBFE720381F8E', 9, 'Elmo Finds a Baby Bird', 'Elmo and Rosita are thinking of rhymes when they hear, “Peep, peep.” Suddenly, a little baby bird appears. Elmo and Rosita want to help the bird but do not know why he is peeping. Chris hears the chirping and places the bird in a tree, but the bird hops out next to Chris! Elmo, Rosita, and Chris think the bird is hungry and Big Bird comes along and suggests feeding the baby bird some birdseed. After all, that’s what Big Bird likes to eat!
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'04147012D3A94FB7AB72482209C3F0D7', X'2DCBD12286D846E8BBE59143875ABD34', 5, 'Buster''s Breathless', 'D.W. obtains poison ivy while playing a game. Buster recaps his problem with asthma and how everyone was afraid of him being injured or getting themselves injured.', '1999-10-07', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0419156E5AD74E6D81F2669854DD5479', X'F4C403079B5E4263A4E0DFA138131E7F', 67, 'Elmo''s World: Singing, Drawing and More', 'Join Sesame Street''s curious red monster as he explores singing, drawing and telephones! Elmo''s World offers kids and adults a fresh and light-hearted take on the world around them. Each episode comes to life in Elmo''s bright, exciting and very original room - the drawer, door, shade and TV all join in the fun. And he''s even visited by a Muppet opera diva and a talking Muppet Phone! Also featuring Elmo''s pet goldfish, Dorothy, the zany Mr. Noodle and classic songs that will delight viewers of all ages.', '2002-01-01', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
