INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'041F2D7C6B104C7DADC5EFA039EA306F', X'0442FB97146049238558B994078DC6B8', 18, 'Shifty Wigs', 'Gizelle plans a family photo shoot, but hearts are broken when there is an issue with Jamal. Wendy struggles with telling her mother she wants to quit teaching, meanwhile Ashley arranges for Michael to have a face to face with her uncle and mom. Karen celebrates her wig line launch with a ''Wig Shift Party,'' but a close run-in between Candiace and Monique leaves everyone in an uproar.', '2020-11-29', 42, '/rFXhevxCXPRs6NDTtn4Ad7kld8e.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0426E5FEB4B745D6B5DF9AFEC221CFFE', X'991E78F103A54D268F7575E11DB4243C', 12, 'When Things Get Broken: A Library is Full of Things to Do!', 'Rogers reads the library book When the TV Broke before visiting the neighborhood library. Once there, he finds a title the librarian recommends. Before he reads, Rogers sits in on a kids'' crafts group. In the Neighborhood of Make-Believe, King Friday insists that the royal HulaMouse must return to the Castle. Chuck Aber sees him first, and when he takes HulaMouse to the Castle, they learn King Friday is flying around the world in search of him.', '1999-05-03', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0427196BFCDD499397F9670E2A34DD4F', X'4FE93658C46343298E649D523869C2CB', 14, 'Honest Abe', 'Join the Pawn Stars as they are presented with an Abraham Lincoln campaign ribbon from the 1860 presidential race. Will this historic piece of presidential memorabilia win their vote or will a tough debate leave the shop divided? Then, Chumlee and the Old Man have a chance to buy a fully functional 19th century dynamite detonator. Will they wire up a deal and blast through a negotiation or will it blow up in their faces? And later, a man comes in with a pair of classic 1990 Air Jordan basketball sneakers. Will the guys make an easy slam dunk or will a late whistle on the play call foul?', '2010-11-01', 21, '/7vgWU3mTDkVwQRlr4kYWYNCfNqH.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
