INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'04523914AEF349CEB906F306E358628C', X'BD8A516B9872472DA8387AFF1070FEA3', 17, 'Rudolf Nureyev', 'Sketches/Songs: The Electric Mayhem, A Wagner opera performed, "Swine Lake", "Something''s Missing", "Veterinarian''s Hospital", "It''s Cold Outside", "Clair De Lune", "Top Hat"', '1978-01-22', 26, '/n0h7Zh26Et9erPfsH8NiXGYuLsJ.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'04533C8D13934A7D980272002037E625', X'45E64A158FC04E4BA1CA9E3F42F3634D', 11, 'The Moon', 'Let the moon master Bill Nye teach you the ancient and not-so-ancient secrets of the Moon.   Wax on, wax off. The Moon grows bigger (waxes) and smaller (wanes) every 30 days or so. The word   ""month"" comes from the word ""moon"". The Moon is the closest thing in space to Earth, and it''s one of   the most well-studied orbs in our solar system. We know that Moon rocks are rich in calcium and aluminum,   that the Moon has no atmosphere, and that there are over a million craters on the Moon''s surface. The   Moon doesn''t glow on its own, it reflects sunlight.   Watch the Moon every night for a month as it grows, shrinks, and at one point disappears. The Moon   doesn''t actually change it''s shape. It''s the way the sun shines on the part of the Moon we see that makes   the phases change. The Earth moves around the Sun, the Moon moves around the Earth. As the Moon   moves through its orbit, the Sun shines on bigger or smaller portions of it. If you were looking at the Moon   from the Sun, it woul', '1993-11-19', 26, '/p9CcEc6lw8LYpSSGIMrqPZdWY7F.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0457F4E38F0940E6BEFD8790D7F06E82', X'8012F05A66A34254885F0A679393F3DD', 10, 'Attack of the Slime Monster (2)', 'Jamal, Lenni, and Alex are graduating from middle school and Tina is hosting the party, while Jamal and Tina work on the prom committee.  However, the band that was supposed to play at the prom backed out.  Jamal and Tina convince Lenni to play with Tina''s brother Tuan.  However, Lenni and Tuan get off to a bad start.  Eventually, they learn to play their music together.  In the meantime, Alex has been writing the story.  He writes about the Slime Monster running away and kidnapping Gaby and about his attempts to save her.', '1995-01-29', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'045A10871BD64F8490110351D3481375', X'2DADBC6B684F4884A0B257BDA7546DC2', 2, 'Time Loop', 'Bernard''s cousin Lucy comes to stay and discovers Bernard''s watch and gets stuck in a time loop.', '2000-09-22', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
