INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0467E4DF50994E4F960275F2C8A366AF', X'3FC7C152E4F6426AA89936EC454C4403', 73, 'Out with the Garbage', 'Zak thinks he is doing a good thing by cleaning Wheezie''s side of the room. But he soon discovers that the "junk" he threw away was actually all of Wheezie''s treasures, making Wheezie get very upset. Now, the gang has to help Wheezie get them back.', '2000-04-25', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'046EFD745C4A447FBE20C05F1BA3B4B4', X'136B81D3964D4B8FA21492F00D96D6B9', 12, 'Oscar''s eclipse party', 'Oscar throws an eclipse party with his Grouch telescope while Telly panics about the moon disappearing and prepares with a protective outfit. Maria scolds Oscar for tricking Telly, allowing him to yell at the Grouch before they reconcile.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'046EFF8AD29E4734821BFEE9914DEEBA', X'3AF7EA64FA134097B8E440AF07083054', 49, 'Episode 49', 'Rogers discusses facial expressions vibrations with musical instruments. In the Neighborhood of Make-Believe, King Friday decides he likes X the Owl''s teacher.', '1974-04-25', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0472CCFB59674B7984B8CDF87C4A8296', X'5DB3FF78E43948E18F67988ECBF85D17', 18, 'The Chase', 'The Duke of Buckingham and Dogtanian arrive too late, Milady''s ship has already left for France. Buckingham suggests they use his faster, but smaller, ship. As they catch up to the ship Milady drops some barrels at them, for no apparent reason. When this fails Milady throws a knife at the ship, cutting the sail and thwarting their chase. Dogtanian lassoes a couple of sharks, and uses Pip as bait to make them tow the ship...', '1982-01-29', 24, '/jHuJFcC6zVcVayNNiXySWcdEO9.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0474E9FB95F9401D8B8CA76F694EC5A3', X'9310A2885AF04746A8D7D7635FFB6BEB', 14, 'Mister Rogers Talks About GRANDPARENTS', 'Mister Rogers arrives with a handheld cassette recorder which he demonstrates by recording himself and playing it back. He plays another tape recording of various grandparents who tell what their grandchildren call them and also shares a few photographs of his own grandparents.', '1984-05-10', NULL, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'047CAD82C2DF4FFC9B980FADCBB4B61E', X'20D7138EEEA846A88ADA2B0F0EE1F674', 78, 'Episode 78', 'Whip Crack Away!
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'048128C5530541C887522D3540DCBC05', X'A4843A51AEEF427C902C7FB3BD670CD4', 8, 'Falling for Fall', 'It''s fall / autumn in the Big Blue House. Treelo asks Bear to come into the living room, where Ojo is standing completely still. She''s pretending to be a tree and so Treelo and Bear join and pretend to be an entire forest. When the leaves start falling off for all, Treelo begs for them not to go and Bear realizes that Treelo doesn''t understand about why the leaves are falling off. As Bear begins hunting for Treelo, he comes upon Tutter, who''s pushing a pumpkin into his mousehole. Bear helps him to push the pumpkin and learns that fall is Tutter''s favorite season because it''s a time when everything changes. He''s making pumpkin pie this year and he promises Bear a special something. In the Shadow segment, Shadow tells the story of "Peter, Peter Pumpkin Eater" and also gives Bear a tip to help find Treelo. He eventually finds Treelo with Pip and Pop, trying to glue leaves back onto trees. He explains to Treelo that the leaves fall off to make way for new leaves in the spring and Treelo realizes that nothing is wrong with the leaves after all.  Songs  Falling for Fall  Notes  This episode includes a brief segment in which real kids discuss what they love best about the fall. Much it involves leaves --- leaves falling, changing color, throwing leaves, jumping in them and making collages with them. Other favorites include wearing sweaters and jackets, it not being so hot and eating apples.', '1997-10-29', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0485C78531CB44F594936BB19CB59D8A', X'DBD3583FE9B246D1A37E309EB666E233', 10, 'We Come in Peace (and Packing Heat)', 'Cynthia and Peter join Phaedra and Apollo on a surprising double date, where they officially bury the hatchet from Kim''s baby shower. Phaedra is planning a trip to South Africa and convinces Cynthia it might be the perfect setting for all the women to get in touch with their heritage and to bring some perspective to all the recent drama.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'04948117836A464499E419C40A8A4237', X'A9657E86413549CEB1F9C295113077E1', 27, 'Episode 27', '', NULL, 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'049D8F10502242EDA952ADCFF86F8FE5', X'787DFA0BC8274DADA82D0548A6534D88', 4, 'Charity Case', 'A trip to Napa concludes with tensions at a high. Back in the OC, Vicki and Brooks consider some unconventional cancer treatments, Meghan puts the final touches on her first OC charity event while Heather faces the harsh reality of going over budget on her dream home. Meanwhile, Shannon receives some shocking news and unresolved issues between her and Meghan become the topic of the ladies'' scrutiny at Meghan''s JDRF charity event.', '2015-06-29', 44, '/5wJqcAbKTSPC6HJ6KStXX6u6hSI.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
