INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'04AD2E0AD3A548BCAF5A7BBA39E5D01F', X'015CCEB30A474F26A68381A4696951F0', 5, 'Postman Pat and the Tuba', 'Pat goes to search Granny Dryden''s attic and finds an old tuba, which gives him a bright idea for Greendale''s annual fete. When Pat learns to play the tuba, it makes an awful noise!', '1995-05-29', 25, NULL, '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'04B03414281A4E588FCD4104967C258F', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 7, 'The Whoosh & Vanish Mystery', 'Telly and Elmo are going to play basketball, but Telly feels they need a snack first. They lay their ball on the table and head to Hooper''s. Chris serves them some healthy apple slice and the duo head off, just as a large gust of wind starts blowing. The two find their ball is now missing!', '2010-10-06', NULL, '/xkjWLIwi9IpSQiIZOW8oXCDtFtq.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'04B100C2988E484BB04840B1E4C146CC', X'3EE646E823AE4DECBBC6C7E6A210D55B', 82, 'Snuffy wants to recycle', 'Snuffy wants to recycle his soda can, but points out to Bob that Gordon and Susan''s bin doesn''t have enough room. Although the bin has plenty of room and there are already some cans inside it, it''s too small to accommodate the Snuffleupagus-sized empty can of Snuffle Up. Gabi and the other kids do some recycling of their own with the Hooper''s Store bins as Snuffy announces the sponsors.
