INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'04F0A4B42C5A40028434E5B8EC98A148', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 80, 'Episode 2175', 'Luis, Susan, and the kids are meeting Mrs. Honker''s new baby, who doesn''t have a name yet. Big Bird asks Micki to hold his hand while he practices crossing the street (actually going from the stoop of 123 Sesame Street to Hooper''s Store).
