INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'05A652FFD7D1442B9F72D794C6C6C574', X'F30BBF8187704E74B68B280E7C85B52F', 3, 'The Jacket', 'Jerry buys a real expensive new suede jacket with a colorful inner lining. George has a song from Les Miserables that he just can''t get out of his mind. Kramer is supposed pickup a magician friend''s doves, and needs someone to help him for two minutes; Elaine takes on the job. Kramer promises she''ll get "a lift" to the hotel where Jerry and George are meeting her and her father, Alton Benes, an author cut from Hemingway cloth. Jerry and George suffer while waiting with Elaine''s father. When it begins to snow, Jerry turns his new jacket inside out, to protect it, but Alton Benes doesn''t want to be seen on the street with him.', '1991-02-06', 23, '/sjEg8xWgVH1IgNXla1pnHNLM2hN.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
