INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'05FE07B3B03A4C3399E481C279211191', X'34674C90410E427CBE4D2A6F6F865A80', 12, 'Like a Rock', 'Take a load off with the Pawn Stars when a 1955 Chevy Pickup rolls by the shop. A rare "first edition" model, will the guys offer a truck full of cash for this sweet ride, or will they haul a* out of there? Then, a guy pops in with a Smith and Wesson "top break" revolver. Favored by Police Departments in the late 1800''s, can Rick lay down the law and make a deal, or is he simply outgunned? And later, Rick and the Old Man are presented with a 1950''s admiral''s telephone from a U.S. Navy ship. Complete with a line for ordering nuclear strikes, will they navigate through this deal unscathed, or will the Old Man go down with the ship?', '2012-06-11', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
