INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'061D1B1CC0BB45FF88043AC00D6BFA9E', X'5D57283D079C4F6693C833A2FEEADA89', 10, 'Sleepless in Orson', 'Frankie and Mike start to worry when Brick begins developing irrational fears. Sue is conflicted about Derrick Glossner''s behavior. Axl and Sean shut down Darrin''s attempt to start a Boss Co spinoff.', '2014-01-08', 22, '/JvzTXufhYKPnAuYmxZCvpx1Iyo.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'061D26BE7824461287FED73E6C4BCD8A', X'E40E6B639F84449F8E8853209B0906C8', 10, 'Triangle Lover of the Day', 'Telly stares in awe at the Triangle Triple Crown, which will be worn for three weeks by the "Triangle Lover of the Day" at today''s Triangle Lovers'' Club meeting. He loves triangles more than anyone else, so he is sure that he will get crowned, and he invites Baby Bear to the special occasion. Baby Bear is not sure he will fit in with the other Triangle Lovers, since he doesn''t call himself one, but Telly reassures him that he''ll do fine.', '2007-08-31', NULL, '/d0BugA2RK1fL9ZIxKsqX4FYue8H.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'061E4F714E454D369EBDB9BD03ECB1A0', X'1D713CA64E174F84949C8CFD98514127', 12, 'Break Room Battle', 'Get the show on the road with the Pawn Stars when an antique circus calliope whistles into the shop. Will Rick become the Ringmaster of this musical relic, or is the seller just clowning around? Then, Rick rallies for a letter signed by JFK about the 1963 March on Washington. Will his dream of taking it home come true or will it find freedom somewhere else? And later, when Rick hangs a unique painting in the break room, it offends the guys. Will they force Rick to redecorate or will he win this artistic showdown?', '2014-08-14', 21, '/ohAs0F7EBdl9Xza35f8wt3PaCzh.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
