INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0668DEC89A25407393CF229226A15B43', X'4DA606E79D2346828BD5F535E1DA706F', 5, 'Franklin the Spy', 'Franklin and Bear play secret agents and uses a hidden tape recorder on their friends.  But the recorder stopped taping just when the secret was about to be revealed and Franklin & Bear takes it one step to far.', '1998-09-21', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'066CC9F640264F07BEDBBD4F4EC28B00', X'40700E8A1DCE4895BEDE522A13A8BCAD', 23, 'Ants and Eaters', 'When an anteater shows up, Zoboo worries that it will eat a colony of ants living in Animal Junction. He tries to broker a peace agreement between the creatures. Zoboo learns that even though anteaters need ants to survive, ants have many ways of protecting themselves from anteaters. Predation is part of life in the creature world and every creature has what she needs to survive.', '2001-05-25', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0675B5CE45144566B7377F943DB8A948', X'D920EBAEF00A4E25ABFE40492C74DED6', 7, 'May the Pawn Be With You', 'Rick flies across the pond to look at an epic Star Wars collection, including an iconic prop from the movie. Will the force be on his side, or will he leave solo? Meanwhile, a seller phones home with everyone’s favorite Ewok. Will Chum pick up the call or let it ring through? Finally, the Gold & Silver Pawn Shop gets a new employee. Can he work with Corey to make a deal on a Planters jar, or will they go nuts?', '2019-12-23', 42, '/cQY6F9GoVTnp5TSYrRiUrHmSVif.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0675DAF2B1FC4185AFE2B93CD3795A3B', X'E48599F866FF4C0F927465B9AE1CDA9E', 65, 'Episode 65', 'John visits Zeebrugge and reports on one of the most dangerous and daring exploits of the Great War.', '1977-05-02', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'067A92DFB9E54E56B37F0EFF8D33EBD3', X'C21DBD225E2E4414BB67750399AAF6F0', 14, 'Smells Like Pawn Spirit', 'The Pawn Stars see their spirits soar when a guy brings in a Charles Lindbergh doll from the 1920s. Will the appeal of this rare toy fly over Rick''s head, or will he take the pilot''s seat and make a deal? Then, the shop becomes a real freak show when a guy brings in an antique poster advertising a sword swallowing act. Will Rick cough up the cash for this piece of show biz history, or will the asking price be too hard to swallow? And later, a guy comes in with a harmonica that once belonged to Aerosmith front man Steven Tyler. Played by Tyler, can they make a deal with some "Sweet Emotion," or will they tell the customer to "Walk This Way" right out of the shop?', '2012-01-09', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
