INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'069B038971E54A21B9589F66E5532943', X'4892E2AF46C14B4EAC81EAC161B5A347', 23, 'Episode 23', 'Today JOHN, PETER and LESLEY will be announcing details of the 1977 Appeal. In the past Blue Peter viewers have collected old rags, scrap metal, postcards, books and stamps. Find out how you can help this year. Have paper and pencil handy for the depot''s address.', '1977-11-28', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'069CF195CBF5411F9B7038E92119677A', X'941B8C6544544336BE7C1D0591C12F90', 9, 'Pinga Sleepwalks', 'Pingu is trying to get to sleep, but Pinga is snoring. He tries to stop the noise by throwing things at her, but this has no effect. He gets out of bed and tries comforting her, but this also has no effect. He takes out her dummy, which makes her sit up and yell, so he quickly puts it in again. Pinga spits out the dummy and then sleepwalks out of the room. Pingu is about to get back into bed when he realises she’s gone, and follows her. Pinga goes past Mother and Father, who are asleep on the couch, and out of the front door. Pingu follows, and tries to stop her, but he can’t. Pinga, followed by Pingu, then goes into a neighbour’s igloo and there are all sorts of noises and crashes. She comes out and wanders on, while Pingu backs away as the door is slammed shut. Pingu then acts as a bridge over a ravine so she doesn’t fall in, and generally tries to protect and shepherd her on her walk, including going through an icicle cave and up on to a precipice. Though he’s basically too late each time, she comes to no harm, but Pingu has a few scrapes. Eventually he takes her back home on a sledge. She gets into bed and snuggles down, still asleep. Pingu gets into his bed and also falls asleep. All too soon Father is waking them up for breakfast. Pinga is quite perky but it’s a real effort for Pingu to wake, and then get up. At the breakfast table, Pingu then falls asleep with his head in his breakfast bowl!', '2003-09-26', 5, '/aNVX3HhZ7a4A2YFU5gIrvfuSBiE.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
