INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'06ADF25E5C6543E6907D280FD85D2028', X'3AF7EA64FA134097B8E440AF07083054', 3, 'Making a Pizza [1328]', 'Rogers sees how pizza is made by observing two guests at Brockett''s Bakery. In the Neighborhood of Make-Believe, Miss Paulifficate''s pizza dough, thrown in the air, lands with an OCS lesson attached.', '1974-02-20', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'06B087379C49447389D0AFA399F1D1F3', X'5BA20443D99F482081F66832D3F2BC4F', 13, 'Amphibians', 'Frogs, toads, salamanders, newts, and caecilians (worm-like animals that have backbones) are all amphibians, animals that spend part of their lives in water and part on land. Amphibians are slimy. Amphibians are cold-blooded that means their body temperature changes with the temperature outside. And as amphibians grow up, they go through metamorphosis.', '1996-01-30', 26, '/sX5LrSgbtWhiYoxPd8BOYpXAP2T.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
