INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0727831CAF4A4493BA195318B7B85B15', X'E1063F8766C24E2DA91353362941AA19', 68, 'Episode 343', 'Kids are busy drawing with crayons outdoors. When a stiff breeze begins to blow the papers about, Tom suggests that the kids come into his store to play. Once inside, the kids decide to play catch. Tom suggests that the store isn''t the best place to play catch. The kids agree and go outside. Tom observes that there are some things that it''s better to do inside and some things it''s better to do outside.', '1972-02-09', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
