INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0735465FC7BF4A7898F0701F47BD8EC3', X'B86D15EA425341A59F144A254EC601E0', 3, 'It''s My Party and I''ll Fight If I Want To', 'Teresa''s father goes to the ICU just as the family gears up for a birthday party. Elsewhere, tension grows between Kathy and Teresa; Caroline returns to an unkempt mansion; and a white lie infuriates Teresa.', '2013-06-16', 43, '/6HF8bLyLFMuLyLZNnvIGV4LxUDV.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
