INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0742AF517E4243F5AC4E392FAC3D206E', X'EA73E13C696248048305C303DF65F89F', 20, 'Welcome the Platypus Family (5) - Digging in the Neighborhood of Make-Believe', 'Rogers brings in various shovels, one of which he uses to put down fertilizer. In the Neighborhood of Make-Believe, Henrietta has sewn curtains with a duckbill pattern. These go to the site for the new Platypus mound. Rogers also shares his homemade recipe for making Ice pops.', '1969-03-07', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
