INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'074B51FF50BA41E3B99B5826CFADCB07', X'34674C90410E427CBE4D2A6F6F865A80', 2, 'Corey''s Big Burn', 'The Pawn Stars prepare to play rough when an original program from the very first NFL championship rushes into the shop. A 1932 game between the Chicago Bears and the Portsmouth Spartans, will the guys push this deal into overtime, or will damage cause them to pass? Then, Rick sees dollar signs when he''s presented with an exploding dye pack of $10 bills. Used by banks to catch thieves, can Rick steal the deal, or will it blow up in his face? And during the night shift, a 1960''s Schwinn tandem bike rolls into the shop. Will Chumlee and Olivia take this classic bike for a pawn-paired spin, or will the negotiation go flat?', '2012-04-09', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'074C8DFE9FF8409A8594FC14AE39E7F1', X'C66C23B01456451ABB8045C28B0309EC', 7, 'The Bear and the Maiden Fair', 'Dany exchanges gifts in Yunkai; Brienne faces a formidable foe in Harrenhal.', '2013-05-12', 58, '/nNuLiw1TnQMNJ8B3ijN2D6jyAfc.jpg', '2026-04-03T15:40:36Z', '2026-04-03T15:40:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'074D48CA81B345F98D754F8466930BFF', X'F13CB62284E34654A8F10CEAB09A9CA6', 5, 'Franklin''s Pumpkin', 'Franklin and Bear have been growing a huge pumpkin in the hopes of entering it in the county fair and winning first prize. As they run an errand to help Mrs. Muskrat, they tell her of their pumpkin and learn about the amazing things she does with seemingly useless broken glass. When their pumpkin suffers an unfortunate accident, Mrs. Muskrat shows them how they too can make something great out of something seemingly useless.', '2002-05-13', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
