INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'076A03E8B8FB49B89BA842236222B4AD', X'9193E795DA7C40ECB68FF63AA7D5174F', 214, 'The Fallen: A Roundtable', 'Writer Bryan Cogman sits down with a few main casts who face their deaths in season 4. The 30-minute feature shows what it''s like to live - or die - in the world of Game of Thrones, from the first announcement of the impending end to the execution of the final scene.', '2015-02-17', 30, '/1rb8gGU9SEQcv8gyVmXj8Jbbz5.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'076A50F2D18D4D9A8FF27E590B23756C', X'70D9E39768134785887D27D034928BAE', 10, 'Pingu And The Message In A Bottle', 'Pingo is fishing, and Pingu meets up with him by the water. Pingu spots a bottle bobbing up and down in the water, and throws snowballs into the water to float the bottle to the shore. He smashes the bottle, and finds a mysterious map inside. This shows a route from the water into the hills, with a big “X” at the end point. Pingu and Pingo follow the route, which is quite hazardous in parts, to a boarded up cave. Pingu goes into the cave and discovers a padlocked chest. He brings it out and breaks into it, but he and Pingo are both disappointed to find that the chest is empty except for a shell. They then have a difference of opinion over who gets what, as they both want the chest; Pingo eventually takes the chest and Pingu the shell. When Pingu gets home with the shell Pinga is quite keen to have it, but Pingu won’t give it to her. Mother comes over and he gives it to her, but Pinga tries to grab it and it falls to the floor, breaking open. They’re all surprised to see a pearl drop out and roll across the floor. Pinga rushes to get it and gives it to Pingu, and they’re all pleased at their good fortune.', '1995-08-17', 5, '/8duuFjaHc3jmojJf8MB3PMbAqRb.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'077726D9CC214BCEB179AABE23DA5A46', X'9193E795DA7C40ECB68FF63AA7D5174F', 123, 'Histories & Lore: The Wall', 'Samwell Tarly explains the impressive construction and function of the Wall, including its natural defenses against wildling attempts to scale, breach, and circumnavigate it.', '2015-02-17', 4, '/3NlmULP5ZpYZCK0xYRmTHUn7VaI.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'07832EE7F43340C4A11F4452359CBD77', X'0B9D7AE7218E45A08C3AE69912F5A6ED', 6, 'Franklin and the Computer', 'Franklin spends too much time on Beaver''s computer game, Dam Builders. Beaver thinks that Franklin is more interested in the game than spending time with her, who comes to his senses and puts his friend before the game.', '1999-10-25', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0785CC2C0601479395E82C8846EEBA97', X'18DA994319634E04A7A0AE63802BB1FA', 17, 'Friends and Enemas', 'Vicki is confronted by her son Michael for not letting him know about her most recent procedure; Tamra and Gina''s conflict continues at Emily''s Turkish coffee cup reader gathering; Kelly questions if Shannon may be manipulating the Tamra-Gina rift.', '2018-11-12', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'07886336EEB040FCBAF7A82401400D32', X'34674C90410E427CBE4D2A6F6F865A80', 22, 'Bullitt Proof', 'Burn some rubber with the Pawn Stars when they check out a 1968 Ford Mustang GT fastback. Just like the car driven by Steve McQueen in "Bullitt," will Rick get into a high-speed chase for this classic muscle? Then, a guy moseys in with an 1858 Smith & Wesson Model 1. The same model used to kill Wild Bill Hickok, will this Old West pistol still pack a punch, or is the seller drawing dead? And later, a man dashes in with a WWII telegraph set. A wireless version often associated with spies, will the guys tap out a good price, or will the seller s bottom line force them to stop?', '2012-08-13', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
