INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'07D2DAD580414C2AA2030D51C7FFEAC7', X'7477E2D4FF694DF0A6AE55FC4F0A96BF', 7, 'Leavin'' on a Prayer', 'On the last full day of the trip, Jill relives her camp experience by taking the group canoeing at a local lake; a final dinner at Shaker Village brings the ladies together as Phaedra reveals a late-night surprise to lift everyone''s spirits.', '2022-07-21', 50, '/sZvikHQFPqrpL9l4t9SlHhu9FoQ.jpg', '2026-04-03T16:34:40Z', '2026-04-03T16:34:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'07D5749355BC410385FFF5CB1F93C614', X'70C8CB4624944DD498F66BFB9B3FAF73', 21, 'License to Pawn', 'The Pawn Stars look to buy an 1862 Civil War postage stamp mysteriously encased in a coin shaped holder. Will they give this stamp the priority treatment, or will they see that it''s "returned to sender?" Then Corey and Rick have a chance to rev up a deal for a 1980 10th Anniversary edition Datsun ZX. Will they burn rubber for this T-top sports car, or will the deal stall out? Finally, a man walks in with an original cast member script of the 1964 James Bond classic Goldfinger. Will the gang turn and shoot a bull''s-eye for this 007 memorabilia, or will the Old Man impersonate the villain Dr. No?', '2010-05-02', 21, '/sBZJxrzUIQxNp5dcG0eKkAQ3Kzd.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
