INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'07EE7004B6B34DCDBA54D53070354087', X'F30BBF8187704E74B68B280E7C85B52F', 1, 'The Ex-Girlfriend', 'George has doubts about his current relationship that he broke off. Elaine is curious about a relationship that she has with a guy in her building that has degenerated over the past two years. Jerry is reluctantly drawn into George''s ex-relationship when he picks up some books left at her apartment. Although he wants to break it off with her, she has this "psycho-sexual" hold over him and he becomes worried about what George might think if he lets this relationship develop. Elaine confronts the guy in her building and Jerry''s relationship maybe in jeopardy when his girlfriend sees his act.', '1991-01-23', 23, '/9oK4EcRiiMk8sPymtrQKG4ZMi16.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
