INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'07F209E9988242A2ABE9205E9167D627', X'83D0476945B34D29AF02590315104997', 2, 'The Elephants in the Room', 'The second day in Thailand starts with a visit to an elephant sanctuary that leaves the women feeling bonded and relaxed; Candiace''s shady dinner and an off-the-cuff remark threaten to throw the whole trip into chaos.', '2023-03-23', 52, '/44bF8NQLL7RLdgKo5fWEsijgAWi.jpg', '2026-04-03T16:34:41Z', '2026-04-03T16:34:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
