INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'080C9B65702B49AEAA2FEB4EA4F37B0C', X'1E967562CB824C1AB523A8212971DA9E', 2, 'Celebrating the Arts: Sand Art', 'Rogers takes his final visit to his sand table, leading to a video insert of Jessica Ricciardelli playing with sand at a beach. Afterward, Rogers makes his second and final trip to Tony Chiroldes'' toy-and-book store. King Friday pronounces the Neighborhood of Make-Believe will hold an art festival. That doesn''t impress Lady Elaine, who appoints herself the art judge.', '2001-09-07', NULL, NULL, '2026-04-03T17:35:49Z', '2026-04-03T17:35:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0817135205594B53AEFD3333E43CE2F8', X'136B81D3964D4B8FA21492F00D96D6B9', 66, 'Paper airplanes with Big Bird', 'Big Bird discovers how to make paper airplanes from a library book and announces plans to create one with Snuffleupagus, much to the amusement of David and Gordon. A massive paper airplane suddenly soars through the air and crashes into Hooper''s Store, sent by Snuffy with his \"medium-sized paper.\" David and Gordon debate whether the mysterious airplane proves Snuffleupagus exists while Big Bird grins at their confusion.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'081777F78D7649FCA5C73E685CAF9411', X'151E88A195764BD1B84AC4D64C1C9FE8', 23, 'Reunion (2)', 'As the reunion continues, Garcelle and Diana hit a point of no return in their already-frayed friendship; Sutton reflects on her ongoing tension with Lisa; Garcelle discovers the trashy truth behind Erika''s book review.', '2022-10-19', NULL, '/lftBwI8SvS06Dnggisf8himYyA0.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
