INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0827488F5E584372968673464F969A4E', X'8B6BBAC8E5EF49C7A5C1197CFB19F772', 13, 'Mister Rogers Talks About Play', 'In Make-Believe, Lady Elaine and her Museum have gone. Even though there is "no play allowed" Ana, Prince and Daniel just have to play, and the Prince speaks up against his father''s rule. A musician who is blind visits the Music Shop.', '1981-07-22', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
