INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'08553F25C53C45E18B6E9E03E56054D6', X'4F18AC4C8757456CA49A224F00E6A9F7', 1, 'The Golden Triangle of Destiny', 'Chris welcomes the viewer to Sesame Street, as he serves Telly his lunch: a grilled-cheese sandwich, which is cut into Telly''s favorite shape: a triangle. Suddenly, heroic music plays as Minnesota Mel, a swashbuckling hero, makes a swinging entrance. He''s on one of his "patented high-stakes adventures," this time in search of the Golden Triangle of Destiny.', '2008-08-11', NULL, '/uVrEGnA60ATXwMEEwwlNehWXZLC.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0860296D1DD449A59B87CB5E7EDC8E7A', X'BFDF87FF01DD4B5494BD19B384F41BDB', 7, 'Something''s Fishy', 'While Vicki revels in the return of her family to Orange County, Heather strives to find a work/life balance on the eve of her book launch. Kelly struggles to figure out Shannon''s motive for setting her up and bonds with Vicki over their shared anger. Tamra plans a last hurrah for Meghan before she gets pregnant, but the sushi party goes off the rails when Kelly loses her cool and crosses a line.', '2016-08-15', 44, '/8Plu1hF5NOMqeUs9phrekDNt5Hw.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0869964ABF3A41D7B9A7D4C6E8722B50', X'05C0E384194C44179F62803EB615E409', 27, 'A baby doll bed', 'Title number 0027. Opens with Mister Rogers arriving with toy baby crib. Mr. Rogers makes a toy bed and pretends to make a doll sleep in it. Lady Elaine also wants Edgar Cooke''s pillow.', '1968-03-26', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'086AD774CC9446918079C03635ED538F', X'331FC1DF6D704D79B585BF28024A4124', 19, 'Cry Wolf', 'Norman accidentally sets off Dilys'' new fire alarm, so she confiscates his football. To get it back, he sets the alarm off again, and again when a fox enters the shop.', '2008-12-05', 10, NULL, '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0870F2E092B3465EADEE0C039DCF0D49', X'9DFF2271F91B47C1A20D58973840B764', 7, 'Mali Boo', 'Pete and Tony find an old Malibu surfboard and Pete meets the board''s owner, the ghost Moondoggy who never did manage to surf Big Blue, the once every 30 year tidal wave. But with  Pete, he just may have a chance.', '2000-03-07', 24, NULL, '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'08731EC599D84E29BAA846210C324075', X'0BBD380C5CB846A68838B5D60223C073', 12, 'Ben Vereen', 'Fozzie gets stuck in a magician''s trick cabinet. The cabinet is dragged onstage so that he can perform his act -- and at the end of the act, two pig stagehands tip the box over so he can take a bow. Crazy Harry, who makes frequent appearances (and frequent explosions) during the show, blows up the cage before the end of the show so that Fozzie can escape.', '1976-11-21', 26, '/AhqmhMmkUyO76fEbkEie4Df0JBh.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'087E9441D86343E2907DBE45E8CB17B2', X'4B2A19E02FAE492EBC31F78E63D88EBC', 12, 'Pawn in Space', 'Explore the cosmos with the Pawn Stars when a cast signed helmet from the 1960''s TV show "Lost in Space" orbits the shop. Will Rick think it''s out of this world or will he yell, "Danger"? Then, a strange antique object surfaces in the shop and has Rick and Corey scratching their heads. Will they unravel the mystery and make a deal or will they remain clueless? And later, a pair of sneakers signed by NBA legend Robert Parish shoots in. Will Chum lace up a sale or will he get benched?', '2016-10-31', 21, '/vmJdr4ZnnCcUCaRra121ysOV2XJ.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
