INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0882EF94346842A7B8316AD278761C9F', X'79C64E0A348841BC9B5C2243FF15B373', 15, 'Stranded Under the Tuscan Sun', 'As the Italian getaway heats up, Sutton alerts Amanda to comments being made behind her back. Amanda fires back when Boz questions her authenticity. Rachel makes it clear she doesn’t need anyone speaking for her. A surprise intervention leaves Dorit feeling ambushed. She storms off, leaving Kyle and Erika stranded.', '2026-03-26', NULL, '/xQ8x5Yq4nfuQ7IlgrRQd48SH1iW.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'088825B078EB4C049BC4F13DD272D0F4', X'5144DE59E67F4FCF919B7106989AB797', 21, 'Picture Perfect', 'Ben is unwilling to wear his glasses for a group picture because of some teasing, but unwittingly wreaks havoc when he spends a day without them. Nuzzle goes for a “hip cat” approach, which fails to impress Sizzle.', '1995-02-13', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
