INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'088F3C1DFE094481BBE41290A00B5993', X'6FEDBA8252F34184BE776B26E556CD0E', 29, 'Fortune Telling', 'Paddington is at the funfair and has his fortune told by Madame Zaza.', '1976-05-19', NULL, NULL, '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'089224ED1F3A483CA040AE678242D7B8', X'5DB3FF78E43948E18F67988ECBF85D17', 25, 'Milady''s Revenge', 'Dogtanian and The Three Musketeers have crossed the Pyrenees into Spain, looking forward to their time in the Spanish court. They''re enjoying the journey too much to realise there''s a stranger behind them with a carrier pigeon. They enter the city on the day of a bullfight, Pip dreams of being a matador. After Pip falls off Sandy and wakes from his daydream they hear a bull has escaped. The bull runs straight at them and they ride out of the way leaving a baby in its path. Athos leaps from his horse, takes the bull by the horns and wrestles it to the ground...', '1982-03-19', 24, '/7VOT0G1z09PsaBoGYS8cmhGdnkg.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
