INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'08A81769EA60437D919FB94C6D9A4966', X'1D713CA64E174F84949C8CFD98514127', 38, 'Mini Rick', 'Take charge with the Pawn Stars when a Civil War-era broadside is brought into the shop. Issued by President Lincoln and proclaiming a National Day of Humiliation, will Rick post the bills for it or will he tear it down? Then, Rick gets his groove on when he checks out a 1947 fully restored Wurlitzer jukebox. Can Rick get the jukebox for a song or will it be a broken record? And later, Rick gets frustrated when Chumlee brings a kid into the pawnshop. Will Rick change his mind after meeting the child or will he not be kidding around?', '2014-12-11', 21, '/ecUkgKqkWsQngB3Duscx1yZqA1T.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'08B7B9E61E0847B1B8A0886A39C81E31', X'05C0E384194C44179F62803EB615E409', 59, 'Plumbing', 'Title number 0059. Opens with Mister Rogers arriving with a hammer. Mr. Rogers demonstrates the use of three tools, a hacksaw, a hammer, and a screwdriver. Handyman Negri comes to fix Rogers'' sink. Tadpole Frogg expresses his sadness for thinking he had broken a fountain.', '1968-05-09', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
