INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'08C0521395BB4053BDE2BEC2DC8BA6E3', X'48A6D3B8384241DAAAECB49A9B65F17F', 4, 'The Igloo', 'Kipper and Tiger build an igloo one cool Winter''s day, but when Pig and his cousin, Arnold arrive, Pig discovers that he is too big to fit in it. Then, it rains with hailstones and the gang have to have fun with umbrellas. Shortly after the rain, however, the igloo collapses in the sunshine, forcing Pig''s cousin, Arnold to have his own igloo home.', '1998-10-15', 30, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'08C319ED9FB547709EB2C01F28A38214', X'0D2293DDDFCA45918F9A0FBE023F8D1C', 2, 'Four Marks', 'Bullied and neglected, Yennefer accidentally finds a means of escape. Geralt''s hunt for a so-called devil goes to hell. Ciri seeks safety in numbers.', '2019-12-20', 62, '/7KWyZgiSXSAuagbtzjTZLrkOtNk.jpg', '2026-04-03T15:40:45Z', '2026-04-03T15:40:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'08C6744E3E8244488E2BB078CE3B8454', X'E48599F866FF4C0F927465B9AE1CDA9E', 20, 'Episode 20', 'The lights go down in London as John helps with a spectacular piece of demolition that will change the face of world-famous Piccadilly Circus, and Lesley starts a series of ''cheap-and-easy'' Christmas presents with some ideas for cards to make at home.', '1976-11-18', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'08C822F554D84831973366425754092D', X'4C79C0B621A442778967BE1E791EFDBE', 2, 'Pingu and the Hose', 'Pingu comes out of the igloo to play, sees a hose lying on the ground and then hears voices coming out of the end of it. He follows the hose to its other end and finds Father and Grandfather in the shed doing some bottling. They are talking, and it’s their voices that Pingu heard coming through the hose. He shows them what is happening, and they’re surprised. He then takes the hose, and plays a trick on Pinga by making her believe that the snowman is speaking to her, and a similar trick on Robby by making him believe that a fish is speaking to him. Then he puts the end of the hose into the shed and attempts to fool Father and Grandfather as well. Their initial surprise soon turns to suspicion, and they find the hose and track it back to the source. Pingu is oblivious to this, and continues making noises into the hose. Father and Grandfather have an idea and place the end of another hose just behind Pingu and they, together with Pinga and Robby, shout into it, startling Pingu. After Pingu has calmed down they all have a good laugh.', '2005-01-04', 5, '/OKV9NFNW2TjyDBAXiZnYtfD04F.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'08C8E17CA5794E9A8A6DB38420E9B8D6', X'7CCD5605FE0B4E00AE7F3E3DAA252F8B', 4, 'It''s All About Choices', 'As Vicki Gunvalson''s daughter, Briana, recovers from her breakup with her high school sweetheart, Vicki tries to set her up with the son of one of her insurance colleagues. Simon and Tamra Barney attend a BBQ party at the Gunvalsons. Meanwhile, Gretchen Rossi flies to Michigan to visit with her deceased fiancé kids. Back in Orange County, Lynne Curtin and her family settles into their new home in Laguna Beach. New housewife, Alexis Bellino, and her husband, Jim, have their weekly date night to reconnect with each other where he surprises her with a special gift.', '2009-12-03', 44, '/uxOvn5TE6BdXNdvk634WEetkurp.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
