INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'09105DB6EFC243A297B27D1298574769', X'136B81D3964D4B8FA21492F00D96D6B9', 15, 'Max Monster''s broken wagon', 'Bob and Oscar quarrel over the letter Q while Big Bird teaches about cooperation. Max brings his broken wagon to be fixed, refusing to replace it despite being missing every part except the handle.
