INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0930D3D08E134C40B9FEC2E99CE0A2C8', X'5C16DB9D5E7140EBB44EF559B2DDB8F3', 3, 'Pinocchio', 'James Coburn, Carl Reiner, Paul Reubens and Lainie Kazan star in this amazing version of the Carlo Collodi''s classic tale. A magical blue fairy brings a marionette named Pinocchio to life in order to grant a woodcutter''s wish. Now Pinocchio must prove himself kind and loving in order to become a real, live boy. But, if he is bad, which sometimes he is, his nose will grow and only until he realizes his mistake will it shrink back to a valid size. This is one of the best Faerie Tale Theatre episodes, and one of the best versions of this classic Faerie Tale!', '1984-05-14', 51, '/4f0IRTC7qxRubcj7mvEwYbgyJv0.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
