INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0992E4E743D44337A47F087ED0510FA2', X'1E967562CB824C1AB523A8212971DA9E', 5, 'Celebrating the Arts: The Last Program', 'Everyone in the Neighborhood of Make-Believe now knows that Lady Elaine is still dwelling on that day long ago when somebody hurt her feelings, but when the time comes to "judge" all the artwork she arrives not with a judgment, but with a collage of all the neighbors. It is Lady Elaine''s rightful act of compassion toward those around her. Mr. McFeely and Rogers share a video collage of artists in their various fields.', '2001-08-31', NULL, NULL, '2026-04-03T17:35:49Z', '2026-04-03T17:35:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
