INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'099EF77962294C3AA537E9F89C553F97', X'5144DE59E67F4FCF919B7106989AB797', 37, 'Here''s to the Winners', 'Ben becomes discouraged when everyone but him has won a trophy for something, even though he does have an impressive skill that’s worthy of a prize in and of itself. Sizzle and Nuzzle do not appear in this episode, and Skye and Julie only make cameo appearances.', '1995-03-07', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
