INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'09B647CBD1F94EBE82CFF3B3B59E05C2', X'34674C90410E427CBE4D2A6F6F865A80', 17, 'Stalled Deals', 'The Pawn Stars call "shotgun!" when a 1918 Buick Touring Car journeys to the shop. Top of the line for its day, will the Old Man''s soft spot for old cars make him loosen up his wallet? Then, Rick and Chumlee encounter a tennis racket signed by tennis legend Arthur Ashe. Can Rick serve up a monster offer for this rare piece of sports memorabilia, or is the price too far out of bounds? And later, a guy sneaks in with a set of fake books used to smuggle guns out of Germany after WWII. Will the guys try to conceal their interest, or is the seller trying to sneak one by?', '2012-06-25', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
