INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'09F29D1CB5C7484BA3778357E48E8795', X'54C290142DBD49FFA23FCF4C546E0B3A', 7, 'Fireworks', 'The Fourth of July in the Hamptons leads to interpersonal fireworks. Here, Kristen and Ramona clash; Ramona and Sonja butt heads; and tensions boil over at a clambake when Aviva approaches Carole to settle differences.', '2014-04-22', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'09FE2FDF0A5A4A3BAEB6BC84B7F317CB', X'A8DB07E5FBA349A9BD12947C111B39BE', 15, 'All Bets Are Off', 'Jules lashes out after listening to the ladies trash LuAnn. Meanwhile, Ramona tries to make amends with LuAnn; Sonja is set up on a blind date when she hosts an elegant dinner party; and the ladies hit the road for the Mohegan Sun casino.', '2016-07-13', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A0043A3BD96477B8AF6E1B4D5EBEC43', X'9193E795DA7C40ECB68FF63AA7D5174F', 170, 'Histories & Lore: The Hand of the King', 'Petyr Baelish details the successes and failures of past Hands of the King.', '2017-12-12', 4, '/qcbo8z60abYixVN13oHrSyb5XVa.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A05277D013042A9851081B38119F249', X'0E4196154C964DDE8ED2715770BA77BB', 22, 'A Trip to the General Store', 'On a nice day, Bear decides to make a trip to the General Store to pick up some things he needs. Hearing that he''s going to the store, everyone in the Big Blue House asks if they can come too, and Bear agrees. They ask him just how the whole process of buying things and getting money works, so he tells them all about how to earn money and how clams are used as currency in Woodland Valley. Bear wants to get going to the store, but instead they all split up to find ways to earn money. Finally, they all get going to the store. But something happens at the store that teaches them another lesson entirely. Also, Bear spends some time with Shadow at the store, and she tells him a story about a turtle who saved money. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A05F01C00D142B79E5A5C7638648044', X'E291DF42D44F49E5BF812DF32EE4A30F', 6, 'You Never Know', 'It''s Ojo''s birthday. She already knows that everyone''s put together a big party for her, but she doesn''t know about some special surprises. These include the biggest of all --- a visit from her good friend Ursa. Pip and Pop learn just how important it is to keep such a surprise. Treelo also learns something about surprises --- that sometimes they are fun, but the wrong kind of surprise can be scary. In the Shadow segment, Shadow sings a verse of "Pop Goes the Weasel." 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A0CC4F2764B44FF8975E44D39CFF95A', X'6C47406BB3D640D8B4831AE1B3D30009', 7, 'Helicopter Heroes', '1. Stuck in the Muck 2. Sausages versus Shrimps 3. Twiching the Night Away 4. Model Plane 5. Open Day', NULL, 10, NULL, '2026-04-03T17:14:36Z', '2026-04-03T17:14:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
