INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A1E57C8E35D41409CCCEBC7D592B8F6', X'913F846D85DF46948DD40D5909F78887', 8, 'Self-Discipline', 'Zach’s obsession with a new video game, rather than his scouting manual, leaves him embarrassingly unprepared during a troop camping trip, prompting a story from Plato about the need for self-discipline.', '2000-11-12', 30, NULL, '2026-04-03T17:38:35Z', '2026-04-03T17:38:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A1E813598584F728CD2F4D39243110F', X'EA1650C2E4F146C793BA74B5D45D08E5', 18, 'Reunion (2)', 'Hosted by Bravo''s Andy Cohen, part II of the reunion has the ladies of Hotlanta, Cynthia Bailey, Kandi Burruss, NeNe Leakes, Phaedra Parks, Sheree Whitfield, Kim Zolciak get together to set the record straight on some of the most talked-about antics of the season and answer some of America''s most burning questions.', '2011-02-20', 43, '/yzHOCfUN60xIeQDSGSEnnZCpEBR.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A2366ECA8314B3D92B946AE29BC3406', X'68138DE20900460AB58E480688F1E081', 38, 'What''s The Story?', '', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A23975547E948BA8720DEE6671293F3', X'3087A3EDE94E42769D02A78183DEA1D3', 13, 'Make an A* Out of a Donkey', 'Kenya and Phaedra focus on their competing workout videos as their feud builds, with Porsha ultimately getting caught in the crossfire. Elsewhere, Cynthia tries to expand her agency, and NeNe learns hard lessons about success.', '2013-01-27', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A24E5AC9C50426CBC1E6343C8B9B640', X'941B8C6544544336BE7C1D0591C12F90', 24, 'Pingu Plays Tag', 'Pingu is having a game of tag with Pinga, and he is determined to avoid being "it" at all costs, rushing round the igloo, hiding in bed and hiding behind the ironing board, where Father is ironing. When Pingu bangs the ironing board, causing the ironing to fly into the air, Father tells them to go outside to play. Pingu gives Pinga the slip by climbing up on an ice arch. When she can’t find him she gives up looking and goes home. Pingu meanwhile has discovered that there is no easy way down from the top of the ice arch! Pinga tells Father that she can’t find Pingu and, as it’s getting late, Mother, Father and Pinga set off in the motorised sledge to look for him. As night falls, Pingu is still on the ice arch, getting colder and colder, and Mother, Father and Pinga are still searching. Eventually they find Pingu, and Father persuades Pingu to jump down into his arms, which he safely does. Later, Pingu is helping Father by folding the ironing when Pinga tags him, to his annoyance. Father consoles Pingu, then surprises him by tagging him himself and running off …', '2004-02-04', 5, '/nuTAEYS7dfhS7GcjknZrLV9cSIt.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A26093028C249AAA94602DF292143F7', X'487FDBCDEC5A454E8268B50566EB8546', 3, 'Don''t Cross the Caro-line', 'Caroline Stanbury undergoes hypnotherapy to confront her past. Lesa tries to convince her mother to move to Dubai. Sara reluctantly goes on a double date with a new man. Michael says good riddance to Caroline Stanbury and Sergio with a farewell party, but someone is left off the guest list.', '2024-06-18', 43, '/l55zxyRQE4asUSJqHUIAJqC3Uqm.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A29F93F0C6742FA8E96D45818ADAAA3', X'3FC7C152E4F6426AA89936EC454C4403', 42, 'Treasure Hunt', 'The kids visit the secret Treasure Trove with their dragon friends, but forget Quetzal''s final instruction and end up lost. It is only by following directions and working together that they break free.', '2000-01-17', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
