INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A2F48AA16B0412FACFE36419004B54C', X'8E5ED8A408E540069F36C68C91DDFEE4', 4, 'Episode 753', '', NULL, NULL, NULL, '2026-04-03T17:36:40Z', '2026-04-03T17:36:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A325A29834C4DD09AE34DF0CEB323FE', X'EA1650C2E4F146C793BA74B5D45D08E5', 6, 'Trashed Collection', 'With Bryson''s 90-day deadline to get a job or get out approaching, NeNe hopes introducing her late bloomer to Cynthia''s boyfriend and club owner Peter will inspire her son to find a career path. While visiting his daughter, Noelle, Cynthia''s ex-fiancé, actor Leon Robinson, discuss Cynthia reservations about marriage. Even while planning a high-end yard sale, Kim begins work on her new track with help from Kandi, but things get heated between the two when creative differences arise. Already puzzled with Phaedra''s ever-changing due date, the ladies are shocked to hear she’ll be inducing her baby "early." NeNe''s marriage troubles come to a boiling point when she reveals a dark relationship secret to Cynthia.', '2010-11-07', 43, '/8PhYwBtrwVCtaLchaRJI5rKOzmW.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A344F42C2524A8AB9B0811024014CA7', X'24003C6DD9194616A7DD0D38BB7A0656', 16, 'Race', 'Pat comes across her real-life husband Laurence Hutchins who invites her to a café by the river. He offers to give her a lift in his car, but she declines. Rosie and Jim dislike his remark of the Ragdoll being slow and decide to race him in the boat.', '1996-08-02', 10, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A36487ED3204B28820A105945777F5E', X'05C0E384194C44179F62803EB615E409', 66, 'All about cars', 'Title number 0066. Opens with Mister Rogers arriving with a bag of toy cars. Mr. Rogers explains how all toys do what you want them to do. His son, John, also makes his first appearance on the show to play with model antique cars. Meanwhile, at the Neighborhood of Make-Believe, Corny''s newly rebuilt factory offers to help Mime Jewel Walker in his go-cart play-act.', '1968-05-20', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0A42553CBAA841D5B2D54F5F26072A6F', X'1D713CA64E174F84949C8CFD98514127', 4, 'Put Up Your Nukes', 'Go to DEFCON 1 with the Pawn Stars when a seller claims he has a cover for a thermonuclear warhead. Can Rick successfully defuse the negotiation or will it blow up in his face? Then, Corey swings into action when a mandolin from Bob Wills'' Texas Playboys comes into the shop. Will he pull some strings for the country classic or will it be out of tune? And later, Chumlee tries to find something he''s better at than Rick. Will he be able to beat the boss or will Rick prove once and for all don''t mess with the best?', '2014-07-17', 21, '/whJXD0CycdCsYhoGzaVFO2VBqka.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
