INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0AE164E469D748EF9D70471C0E95AD2C', X'61E0C9D9337E4FE4A0FDE567B29AF115', 4, 'The Epiphany', 'On day two of the Milwaukee girl''s trip, the women rally around Britani. Lisa makes her own plans for the day. Heather tells Whitney about the Prism rumors, causing her to clash with Meredith. Relationships are tested at a motorcycle-themed dinner where Lisa and Angie attempt to hash out their issues until Lisa crosses the line. Britani makes an announcement about her relationship and questions Bronwyn''s true motives behind marrying an older man.', '2024-10-09', 43, '/qwJwUDjP8eauiqDzdLtWcoD7GmS.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
