INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0AE353AE81624521BA1D7AF3B6E2779B', X'6BE7468483E64D00BD693E4FCA97CABB', 9, 'Killing Time in Austin', 'The ladies head to Brandi and Stephanie’s lake house in Austin for a fun getaway weekend. On the trip down, LeeAnne is shocked to learn that everyone is “in” on the details of an embarrassing secret from her past. Later, the drinks flow freely at dinner as a drunken Brandi puts her acrobatic skills on display. The next morning, Cary and Stephanie engage in a heated confrontation with LeeAnne, in the aftermath of a horrific late night fight they overheard.', '2016-06-06', NULL, '/tJelgvddPBaEnp9PC850bN9ifkZ.jpg', '2026-04-03T16:35:03Z', '2026-04-03T16:35:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
