INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0BA087EAE14E43D7A59A7F809E19EC8C', X'1C9EA7D3E2544E7B8A9F33EEA9C6C341', 10, 'Living on the Edge', 'After an icy welcome in Toronto, Nene lays out her standing with each of the girls. Nene and Eva sit face to face and revisit old wounds, while a group trust exercise forces the ladies to live on the edge in an unexpected way. Kenya, Porsha, and Kandi team up to find the snake that recorded Cynthia, but before they can get to it, there is a surprise that will shock everyone.', '2020-01-05', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0BA331B9E2BF42F88B0A1D2260DBCF86', X'34674C90410E427CBE4D2A6F6F865A80', 21, 'Kick the Can', 'Take the field with the Pawn Stars when a World Series ring from the 1995 Atlanta Braves slides into the shop. Known as "the team of the 90s," will the guys try to push the negotiation into extra innings, or is this item out of their league? Then, Corey and the Old Man hear the sweet sound of cash when a Sho-Bud steel guitar comes in. A classic instrument in country music, can the Old Man get it for a song, or is the seller singing a different tune? And later, a guy brings in an oilcan used for fueling a 19th century lighthouse lamp. Will the Old Man guide this deal through treacherous waters?', '2012-07-09', 21, '/pp71O0HWed02OEyCnWuuOJnxtzT.jpg', '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
