INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0BB4C628F05F461385424C0207C9125A', X'5144DE59E67F4FCF919B7106989AB797', 2, 'Train Driving Kids', 'The boys have a model train but refuse to share with the girls, insisting it’s a boys’ activity. Gradually everyone takes to other suggested activities, leaving only Leon and Kiki still wanting to play with the model train. Nuzzle struggles to play a toy xylophone.', '1995-01-17', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
