INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0C08910FEDDB4E4EBA8F56F023744D4A', X'596E6E8FF65147F283B8D4CDEE8E5927', 13, 'Episode 13', '', '2005-06-26', 25, NULL, '2026-04-03T17:21:20Z', '2026-04-03T17:21:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0C11B449F7154731A818ACAA1EE36F41', X'A4843A51AEEF427C902C7FB3BD670CD4', 19, 'Magic in the Kitchen', 'Bear has just gone inside the Big Blue House for some relaxing swinging in the living room in the kitchen. Ojo, however, is soon there to remind Bear of a promise he made. She''s very hungry and Bear had promised to make her his "incredible banana berry whole-wheat pancakes with maplely syrup." So Bear heads to the kitchen to get cooking, and Ojo offers to help out. She goes to get Snow Bear and soon after, Pip and Pop join in the cooking. Tutter and Treelo appear soon after and Tutter''s a bit annoyed with Treelo for taking him flying through the trees. Still, they join in the preparation as well --- Bear has them set the table. Tutter disagrees with Treelo as to how to fold the napkins, but Bear gets them working together on a new way to do it. In the Shadow segment, Shadow sings the song "Muffin Man." In her version, however, the Muffin Man is a super treat that''s able to fly into your mouth (with a little help.) 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0C1623ED8D6041E38DAA95F0D9C4D78B', X'D5351B608A0C482AA6DD4FB860CFE143', 23, 'Episode 1413', 'Mister Rogers arrives with a catalog of tents to share with viewers -- Tempered Tents For All Seasons.  In the Neighborhood of Make-Believe, Lady Aberlin is making a tent for Prince Tuesday when Mr. Allmine arrives in the Neighborhood.', '1975-03-19', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0C16D66FC15242A5A22E7CB7CD99E165', X'A860511CB630415E99A1A9E0922FBFD7', 8, 'To Eat or Not to Eat', 'A new candy bar that Buster wants to try is making anyone who eats the candy bar act strange.', '2011-10-14', 13, NULL, '2026-04-03T17:38:00Z', '2026-04-03T17:38:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0C181BEDC35C4D27A878F18F2C61ECBE', X'A79A245FACAB4EBEAEE929867F9E52F6', 21, 'Game Night!', 'It''s game night at the Browns, and it''s about to get a little crazy. The family gets competitive as Mykelti and Gwendlyn host Sister Wives trivia. There''s lots of noise and chaos, and there''s punishments for the losers, so the stakes are high!', '2018-03-25', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0C2633D0AE81407FAD5661B841B25644', X'913796E9C0CE44DD98BCF6F520CB2444', 3, 'How to Make an Apple Pie and See the World', 'LeVar and a friend say following recipes and cooking foods are very much like science experiments. They work on recipes which include lasagna made with rice, a marinara sauce, and apple raisin muffins. Helen Mirren reads How to Make an Apple Pie and See the World, a tale of a lady who goes to elaborate lengths to get all the ingredients to make a pie after she finds her local grocery store closed.', '1995-10-10', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
