INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0C2CF90373984A8DA15E8BDDBD45FF2E', X'994C75E506FA4BE1A142EA7B2C892DD0', 5, 'Curiosity: A Visit with Violinist Hilary Hahn', 'Rogers reads his own book titled "Daniel Striped Tiger Gets Ready for Bed". He finds violinist Hilary Hahn at Negri''s Music Shop. Nighttime grips the Neighborhood of Make-Believe with worry over Little Panda and Prince Tuesday.', '2000-09-07', NULL, NULL, '2026-04-03T17:35:49Z', '2026-04-03T17:35:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0C2EC11D9A3B45FEADB123AF2217468B', X'0E4196154C964DDE8ED2715770BA77BB', 4, 'First Day At Mouse School', 'It''s finally Tutter''s very first day at Mouse School. He''s really excited and happily shows off his bookbag and other school supplies to the other kids in the Big Blue House. Meanwhile, Bear and Doc Hogg share a cry over how much he''s growing up. But when it comes time to go to school, Tutter is scared that he won''t fit in. Bear agrees to accompany him and to wait outside the school, until he''s comfortable with being there without him. 
