INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0C55263521EE46E38DB7D9023A60B282', X'4D2CAC0F38FD438B8AFAACF43952E535', 22, 'Episode 22', 'A weekly programme for younger viewers.  Including ''The Story of San Marco'', a scale model serial and ''Ginger and Pickles'', a story by Beatrix Potter with the original pictures.  Introduced by Christopher Trace and Leila Williams.', '1959-03-12', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0C579B5ACA32421EA034ECA68706CD42', X'6B5CAA66F66F4ED1817FA00BAD08790E', 6, 'Finale', 'Teresa''s plans for a civilised dinner with the housewives and their families are scuppered when the ladies discuss Danielle''s past. Danielle blames Dina for spreading rumours about her even when Caroline admits responsibility for gossiping about her, and an argument breaks out between the housewives and Teresa gets angry with her guests. Later, Teresa''s husband tried to placate the guests with champagne.', '2009-06-16', 43, '/9mXLgQ59inVrPf0IpBerkZ5PCpP.jpg', '2026-04-03T16:35:14Z', '2026-04-03T16:35:14Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0C579D15810B4B23AC21846859ED7DA8', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 36, 'Inside Looks (on The Fix-Up)', 'Inside look from the season 3 episode "The Fix-Up."', NULL, 4, NULL, '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0C58811378E24BF4A4109147F40F9CE9', X'54FACB0BDB5941FE9D64C7C7221A3C81', 1, 'Divided, They Summer', 'It''s been one crazy summer for the New York City housewives. Bethenny struggles with the sudden passing of her boyfriend Dennis, while Luann is coming to terms with the fact that she relapsed and had to go back to rehab. Ramona is tackling her fear of the water by taking swim lessons, and Sonja is adjusting to her new apartment. Dorinda has made positive changes in her life, but she has yet to face the tension between her and Luann. They haven''t spoken since the incident at Luann''s cabaret five months ago.', '2019-03-06', 60, '/n3MMlfa82nFKf8Nq6NhizJyaLoE.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0C7055BC9DF644BEAFE94E19D8281783', X'2E6EE129B32E4417950056F1CC9BC434', 3, 'Mrs. Katz and Tush', 'LeVar pays a visit to a family friend, who is Jewish, to learn how to prepare special foods served during a Seder dinner, like Challah bread and potato latkes. Reizyl Bozyk and Rick English read the featured story of an elderly Jewish lady and how she befriends her neighbor''s young son after she is widowed and he gives her a pet cat to keep her company.', '1993-10-13', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
