INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0CB52E0B2DAE4237AE2F5BBA7B3D44EB', X'F593D90C533942F59C885BFD48D04075', 16, 'Everything Must Go', 'Everything must go when the farmer sets up a stall by the side of the road and leaves Bitzer in charge. The lazy sheepdog soon tires of his role and gives Shaun the job. He proves to be a much better salesman than Bitzer and the flock are only too happy to get stuck in, selling pretty much all the farmer''s worldly possessions.', '2009-11-22', NULL, '/tu94Up52tzFwm0radaLcCEBTE15.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
