INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0CBEDE8B04794D19804F7D7728FABD71', X'33825A1537DC4FF982BDCC720498149A', 11, 'My Life on the Dee List', 'Kameron tries to impress her daughter with a bow and arrow, while Kary has her first photoshoot for her jewelry line. Stephanie throws husband Travis a mid-life crisis themed 50th birthday party. Things get crazy when Mama Dee appears to crash the party and one of the ladies refuses to attend. The ladies leave for Thailand, with LeeAnne hoping this trip will finally be a positive one for her.', '2019-11-13', NULL, '/uItA2zZrv7WwdKm9EGrLrTNuW4j.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
