INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0CE0175B01D6431094FE7997003F287B', X'1A534647384B4C00BB6CA3371AD962EB', 13, 'Rocky Road', 'Come out fighting with the Pawn Stars when handprints signed by Sylvester Stallone pummels into the shop. Will Rick score a knockout deal, or go down a Rocky road? Then, Rick scouts out two signed Norman Rockwell lithographs. Titled "Puppy Love" and "Dressing Up", will they be picture perfect, or show their true colors? And later, Chumlee tries to prove he is more active than everyone thinks he is by entering an arm-wrestling competition. Will Chum muscle his way to a win or will he be strong armed out of the competition?', '2015-02-26', 21, '/aF0rF5L0WJTjiX1felD5ljSERVr.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0CE07F6B455B4DF79B71990A631E539A', X'3D4E0E451C67475EB37D9E7E6B8B942A', 8, 'Barking at Buddha', 'Wishbone wants to be a hero and tries to rescue two misguided youngsters when they set out to impress the older kids. As ""Monkey,"" he yearns to be immortal and seeks a position of importance in Wu Ch''eng-en''s Chinese folktale.', '1997-03-10', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0CE4BB79C9984405B2933492F9231704', X'98D80972E53A43DDA03A7703465E6F87', 2, 'Sturgis and Acquisitions', 'Start your hog and ride with the Pawn Stars as they head to the annual Sturgis Motorcycle Rally. Can Rick relax and enjoy the trip, or will he stop and hunt for deals along the way? And back in Las Vegas, the Old Man and Olivia are holding down the shop. Will school be in session as he teaches her the pawn biz, or will he just take a nap and make her do all the work? And later, the guys arrive in Sturgis, but Rick spots a sweet deal, a 1966 Honda CB160 motorcycle. Is he just window-shopping, or will he insist on mixing business with pleasure?', '2012-11-05', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
