INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0D032048FFF74C88A29EAA218B1BCFE9', X'136B81D3964D4B8FA21492F00D96D6B9', 2, 'Big Bird can''t get back to sleep', 'Big Bird wakes from a nightmare and struggles to fall back asleep despite help from Maria, Susan, and the Honkers. Maria falls asleep mid-relaxation advice while Susan''s bedtime stories don''t help, but the Honkers'' rendition of "Brahms'' Lullaby" finally gets Big Bird to sleep.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0D04E64631744F079F1BC6E150E8638D', X'0BA7CC9B13144E1EB74F76463A622991', 10, 'Fun & Games: Mister Rogers Goes Bowling', 'Rogers, along with McFeely, go to a bowling alley to show how to play, and how the pin machine work. The hodgepodge team tries to decide what game to play. After a few sports are rejected, everyone decides to play hide and seek. Lady Elaine decides to find them all with her boomerang, but everyone feels they won by doing their best. Before leaving, Randy Caribou turns his jersey to Lady Elaine so she can be on the team.', '1989-02-24', NULL, NULL, '2026-04-03T17:35:45Z', '2026-04-03T17:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
