INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0D478155B0A7477FB381207AEBDAE565', X'98D80972E53A43DDA03A7703465E6F87', 12, 'Wouldn''t It Be Ice?', 'Hold steady and fire with Pawn Stars as Rick checks out a Japanese Knee Mortar. Used in WWII for fighting in the dense jungles of the Pacific, will Rick see the chance to make a deal, or does the seller not even have a leg to stand on? Then, Corey and Chumlee read the fine print when an original signed copy of Wayne Gretzky''s NHL contract skates into the shop. Will the guys pass, or take off the gloves and fight for it? And later, Corey continues to push for a partner’s stake in the pawn shop by betting Rick he can make bigger deals. Will the gamble pay off?', '2012-12-03', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
