INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0D539EE85C5245579BA4AEE71CA9E56F', X'27D0351A92F54D01995C6B5928957075', 9, 'Not a Yacht of Fun', 'Meredith convinces Jen to include Danna on the girl''s trip, but when Angie K. claims the primary bedroom, she becomes a target; Heather, Lisa and Whitney take sides, but when Angie K. retaliates with an accusation against Jen, it becomes a war.', '2022-11-30', 44, '/qR3jS46EEX3YBjiMEwYFyK4ooch.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0D5785A29EE249D5B197A52512E58C52', X'4FE93658C46343298E649D523869C2CB', 19, 'Pedal to the Metal', 'The Pawn Stars meet a man with a handwritten lost poem from rock legend Jimi Hendrix. Will the rare Hendrix verse provide new insight into the ''60s icon or will the cryptic words remain locked in a purple haze of mystery? Then, the guys are presented with a chessboard made with wood from one of the most famous ships in history, the Titanic. Will the shop navigate the icy waters to make a deal or will they be forced to stop engines and jump ship? And later, Rick and Chumlee check out a classic child''s pedal car from the 1950s. In need of major repair, will the gang take a chance on restoring this miniature beauty or will missing pieces keep them from trying?', '2011-01-24', 21, '/lownWP2BFdTbwEtqpaDdngWnflY.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
