INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0D59C10A08B14BFA97F03C64654121B8', X'49A0092491694B3FB8F0D7BD68794DB9', 6, 'Margs & Marriage', 'Teresa invites Jackie over for a visit; an innocent conversation between Dolores and Paul takes a sour turn when his divorce becomes the focus; Margaret recruits her friends for a charity golf outing; Jen Fessler meets with Jennifer Aydin for lunch.', '2024-06-09', 42, NULL, '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
