INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0D5C262A65234115B9FF4829FC91C4F3', X'432A6ABDDCCA44CC82CEFB39E33B8949', 9, 'Castle Waterfall Pt 4', 'Rogers needs a washer for a fountain he wants to assemble. Instead of taking one from Bob Trow''s workshop, he merely leaves him a note. In the Neighborhood of Make-Believe, the Castle fountain works only to a small extent. Lady Elaine has taken the windmill at Someplace Else apart for unknown reasons.', '1971-02-25', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
