INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0D7917315F6544228EBCFE2A27170DAF', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 39, 'Inside Looks (on The Letter)', 'Inside look from the season 3 episode "The Letter."', NULL, 2, NULL, '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0D7D3B848A254988B16D5713BA8E089E', X'CA19F89515144988A70995E84EAB7CEE', 6, 'Raiders Of The Lost Pawn', 'There’s a British invasion when a pair of vintage rock t-shirts roll into the Gold & Silver. Do Rick and Chum have the moves like Jagger to seal the deal? Next, Corey and Chum take a drive down memory lane when “Gumby” and “Pokey” toys cruise into the shop. Will the duo stretch for a deal, or say “neigh.” Then, a seller brings in a poster by Israeli artist, Gad Ullman. Will Rick hand over the money, or will he exhibit no interest? And later, Corey and Chum look at unopened Atari games. Can they unlock a deal before it’s game over?', '2020-12-14', 42, '/1nGnANw6tvwBTF7GXfHWyjD86X2.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0D7E358789A9423BB159B1D2573319B2', X'48A6D3B8384241DAAAECB49A9B65F17F', 5, 'Hiccups', 'Poor Kipper gets the hiccups one warm Summer''s day while having some quiet time in his inflatable paddling pool and his friends, first Pig, then Jake, and finally Tiger give him various suggestions on how to cure them, like standing upside-down and making music and drinking a glass of water from the wrong side, that is until an unexpected and musical surprise cures the hiccups forever.', '1998-10-22', 30, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0D7EE2737BE149FD906252178625E46A', X'E291DF42D44F49E5BF812DF32EE4A30F', 11, 'Bear''s Secret Cave', 'Pip and Pop, along with Treelo, have decided to go fossil-hunting. They''ve gathered up all their gear in a backpack and are ready to go. This gets Bear thinking about discoveries and how much he enjoys discovering things himself. He then hears Ojo and Tutter calling him. They''ve been searching around the attic and came across an old, dusty box. It turns out to be a treasure chest filled with some of Bear''s old things. He remembers that the played with them all in a secret cave, but he can''t recall just where exactly the cave is. Ojo and Tutter decide to get the help of the rest of the kids to rediscover the secret cave. Once there, they find out some things they never knew about Bear and realize that he''s a lot like them. 
