INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0DAC18B11EAD4CC7B3C3F4BC85E03149', X'22BEBA7F9B8E456393DA46E76ECBA427', 2, 'Show and Tell Elmo', 'Abby goes to the Storybook Community School for the first time, and Mrs. Goose and her class make her feel welcome. But when it''s time for Show and Tell, she doesn''t have anything to share, so she decides to use her magic wand to leave school and ask Elmo for help.', '2006-08-15', NULL, '/tEg9FW95AH2gJTgvXsgC1K1jgEw.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0DAF8C6A1478434994D54092AC0D0C1F', X'5BA20443D99F482081F66832D3F2BC4F', 2, 'Nutrition', 'All food, whether it’s protein, fat, carbohydrates, vitamins, or minerals, is made of chemicals. When your body gets a hold of these chemicals, it recombines them and makes energy. Different types of food make different amounts of energy, which are measured in calories. How do scientists figure out the amount of calories in food? In this episode, Bill will reveal the secrets of the bomb calorimeter – an instrument of food science.', '1995-11-10', 26, '/p3q64EKJSsUHQ9uX1glupScHzMX.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
