INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0DBC1159B5504AEBB1742BB75FAB74D6', X'7CCD5605FE0B4E00AE7F3E3DAA252F8B', 17, 'Reunion Special (2)', 'In the conclusion of a two-part reunion show, the women look back over the last season with the drama continuing between them.', '2010-03-11', 44, '/piRwrcOzHtMMocjsxeKzsnKC9iS.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0DBFF9201C8942FB80D9D058255A9382', X'61E0C9D9337E4FE4A0FDE567B29AF115', 18, 'Reunion (2)', 'In part two of the reunion, the husbands talk about their role in their wives'' arguments. Tensions reach an all-time high as Meredith attempts to clear her name to Angie''s husband, Shawn, over the rumors that have circled the group for the past two years. Heather challenges Bronwyn''s shifting narrative on her infidelity story with Todd. Mary gives an emotional update on Robert Jr., and the ladies have an impactful and honest conversation.', '2025-01-29', 43, '/sNNrSJiCmBwmOhlamHbGChiuchK.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
