INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0DE0AD4D10A146B5A885E1C6B148DFC9', X'98D80972E53A43DDA03A7703465E6F87', 28, 'Grand Theft Corey', 'Put the pedal to the metal with the Pawn Stars as the guys check out a completely customized 1932 Ford Roaster. With less than 500 miles on it, will a high asking price put a red light on negotiations? Then, Corey and Chum lee face off against a guy trying to sell a Marilyn Manson Clayton doll. Used in the making of "Celebrity Death match," will they make an offer or is this deal DOA? And later, Rick eyes a diploma from the 1912 Olympics. Awarded for a 2nd place finish in swimming, can Rick turn it into pawn shop gold?', '2013-02-18', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
