INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0DFC166CADA94AF4B284944923D87561', X'208E80DE61E34A2F857FC667FFC29134', 7, 'Linda Lavin', 'Miss Piggy announces that this show is Kermit''s birthday, and before he can react, she launches into the tribute she''s organized. They''ve planned a This Is Your Life-style show with birthday greetings, including one from Mr. Dawson, Kermit''s old acting coach from Leland, Mississippi. Wayne and Wanda, the singing duo from the first season, show up and give Kermit such a guilt trip that he rehires them. When they sing, Kermit remembers why he fired them in the first place.', '1979-12-07', 26, '/9lsJhWQvy8V1j0puWHf8HIG8rvh.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
