INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E09AA59842243A7AD1C0C2C85366B3B', X'EC8D33228CA24E8D9D22268AEE320274', 3, 'Pawn Barons', 'When a customer walks into the shop with a camera that shot the first footage of Elvis, will Rick and Corey shake up a good deal, or will they return to sender? Then Chum tries to dig up some info on a mysterious fossil. Is it a dinosaur egg or will Chum end up with egg on his face? Then Rick tries to strike black gold with a Standard Oil stock certificate. Will he buy low and sell high or will the market crash? And finally, Corey chomps his teeth into some Holyfield/Tyson tickets.', '2025-02-05', 42, '/svck1Xjk7Z21jEa4GayRE4pX6Gv.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
