INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E13042924A3497DA2483FB5CD7B1C3F', X'F8B697543E4145E5832A64D9C2809AD7', 9, 'Learn To Earn', 'Bernard wants a new skateboard and Pentup Primary decides to pay the students to clean the school. But with Nicolette stealing half the kids'' money, Bernard must do something to get some new wheels.', '2005-03-03', 15, NULL, '2026-04-03T17:20:06Z', '2026-04-03T17:20:06Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E18610E113A4EB78837A0EA5AF3C2C7', X'ECB64EF34F8045A7B4A9C04434B02E35', 10, 'Sunday Funday', 'Get ready for the biggest game of the year with the Pawn Stars when a ball signed by NFL hall of famer Walter Payton spirals into the shop. Will Corey be able to keep his head in the game, or will a tough negotiation cause him to fumble? Then, when a program from the first Super Bowl rushes in, Corey is forced to make a game-time decision. Will he score before the clock runs out? And later, all bets are off when the Old Man gets to decide who has to work the day of the big game. Will the guys play by the rules or make an illegal substitution?', '2014-01-30', 21, '/s7xTqbRgol0AlkmhR5Cy9DjbiUt.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
