INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E26327511FE477C9ADEE5BF302C1018', X'E03D79BDE01F4414B0B3F3B5F26E97F4', 23, 'The Bridge', 'Frankie and Mike attempt to cure Brick of his irrational fear of crossing over bridges. Meanwhile, Axl is pitted against nemesis Sean Donahue when a lifeguard position opens up at the local public pool, and Frankie is ready to pull her hair out when she tries to help an indecisive and emotional Sue pick out a two-piece bathing suit to wear on the pool''s opening day.', '2011-08-05', 22, '/k3ztA0OTDJHMv882vQhnwsKUrnB.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
