INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E368753C026437C8C0CCFDF3B3931F2', X'7CCD5605FE0B4E00AE7F3E3DAA252F8B', 13, 'Let''s Bow Our Heads and Pray', 'The ladies are finishing their lunch in San Francisco. What started out as a fight between Alexis Bellino and Vicki Gunvalson ends up with everyone taking the opportunity to tell Vicki just what they think of her. Back in Orange County, Lynne’s daughter, Raquel, tells her friends about the family’s eviction. Tamra Barney and Vicki try to figure out where their friendship stands. Alexis and her husband, Jim, invite their pastor and his wife to breakfast. They talk about the role of modern day Christians and how Alexis feels judged for her beauty and looks. Gretchen and her boyfriend, Slade Smiley, are off to Palm Springs for a weekend getaway with her parents. It’s Tamra’s 42nd birthday and her husband, Simon, takes her out for a romantic dinner.', '2010-02-18', 44, '/jqZfHWK2E7ZX3oPkBMxiO9MD6D5.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E39912C5127444FBEBC94F89D652F37', X'21745B85D26942FAB4DD701B2DA5C085', 14, 'Episode 14', 'with John Noakes, Peter Purves, Lesley Judd', '1973-10-25', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E46253A7D274B2D8C3DC273B7C03CE2', X'7C75633629DB4634B976E993E8F51DA2', 3, 'Hold Your Horses', 'The ladies of Potomac get decked out in their best hats and are off to the races for one of Baltimore''s elite events, The Preakness Stakes. Charrisse continues to reinvent her life by gifting herself a new champagne room. Karen welcomes her daughter with open arms, when she returns home for the summer. Robyn struggles to answer questions about her relationship status with Juan. Meanwhile, Monique heads to the "Dirty South" to celebrate her husband''s induction into the Alabama Hall of Fame, where she also reunites with her "Monster-In-Law" for the first time in months.', '2017-04-16', 42, '/3Wn9PdBpLpHWccrKE4Qw5ylhuR9.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E474BAC5E944876A9BA685BA87619F0', X'151E88A195764BD1B84AC4D64C1C9FE8', 3, 'There''s Sutton About Crystal', 'Kyle invites her friends to the desert for the launch of her new store. Sutton apologizes to Dorit for seeming unsympathetic following her traumatic home invasion. Garcelle urges the women to be up front with each other. While Erika and Diana point out that all their problems share a common denominator, Crystal winds up triggered by a past offense and Lisa feels they''re all missing the point.', '2022-05-25', NULL, '/eENOdnVnvgqn7awGnoKzdBK5DkD.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E47F7F8FFDF42DBB4B2E1EECF7CBC95', X'DB555B9887D64CD2B7B4973F9206CB1E', 20, 'Whooping It Up for Wedding Bells', 'Shannon goes on a date with a man who she plans to invite to Vicki’s engagement party. Emily helps Gina pack up her Coto house. Braunwyn and her mom Dr. Deb meet for yoga while continuing to avoid their unresolved issues. Emily is surprised at a medical diagnosis. The ladies celebrate Vicki’s engagement with a “farmhouse chic” party, but Tamra melts down after seeing Kelly.', '2019-12-17', 44, '/us8O6RqzBjvYN5g4RxPKJ294Pcx.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E4DF98D410C4515B58F828027D916A5', X'3EE646E823AE4DECBBC6C7E6A210D55B', 99, 'Peck at Birdland', 'Big Bird reads a large sign posted in the yard for Elmo and the Birdketeers, advertising a "Peck" this afternoon at Birdland. He demonstrates to Elmo how birds peck, and Susan can even do it too and plans to go. At Birdland, Hoots the Owl shows off the pieces of his new dance floor for the peck tonight.
