INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E55E7E71D4448BDBF85B07B7EFC3C62', X'190C6E498849440487D4EAEF943A6024', 2, 'Oakie Doke And The Nut Mystery', 'Doke helps Rufus to find his missing nut stash and Rose to find Root using Manny''s water detector. They find Root fast asleep in a hollow tree along with the nut stash Dave and Denzil stole.', '1995-09-18', 10, NULL, '2026-04-03T17:19:24Z', '2026-04-03T17:19:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E5756CD8634430EB01BB3E9BFA96C9F', X'9D74600D722247C1BD1B635F5B41B7D1', 9, 'Germs Make Me Sick!', 'LeVar goes on a search for microorganisms, distinguishing the good ones from the bad. An animated satire of Hill Street Blues (which ran 1981-1987) shows white blood cells ready to fight germs. Molly Mandlin reads Germs Make Me Sick!, explaining how people can catch colds and diseases from exposure to germs.', '1986-07-03', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E580AB1B75C493F804E415255FA91F7', X'F21CA545466C448CADA5B8ACC8B856DC', 3, 'Time and Again', 'Bernard and his Dad go fishing which causes the magic watch to break, Bernard is very upset however the postman steps in and saves the day.', '1999-09-24', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E5E005221B44E53976BBAB4ABA1879F', X'3982796B54514100904246BEDF6A20A5', 26, 'Pingu Builds a Snowman', 'Pingu and Pinga get up to find a nice fresh fall of snow outside. They go off in the sledge to have some fun, but hit a bump sliding down a hill and get thrown off. They decide to build a snowman and have made a start when Robby turns up and suggests it should be a big one. They all agree, and Robby helps to gather the snow to form the bottom half. They make a ball to put on top for the body, but have difficulty getting it up and making it stay on. Pingu then spots a nearby signpost, used by hikers to find their way, and has the idea of using this to support the snowman. Pingu and Robby roll the balls of snow across and build up the snowman around the signpost, covering up the signs with snow to form the arms of the snowman. They then have problems trying to get the head on, as it’s so tall. Pingu has another idea and goes off on the sledge, and Pinga and Robby work on finishing off the body of the snowman. While all this has been going on, a hiker has been wandering around nearby, clearly lost. He spots Pinga and Robby, and comes over to them. Pinga and Robby ask him for help with the snowman, and he kindly puts on the head and makes it appear that the snowman is on a hike by adding a rucksack and a pole on his shoulder with a bag. The hiker asks Pinga and Robby if they know the way, but they say that they don’t, so the hiker wanders off again. Pingu then arrives back on the sledge with a ladder, and a carrot in a bucket, and is surprised to see the finished snowman. He wonders how Pinga and Robby did it. The hiker then returns, having found a sheer cliff in his way, and asks them again if they know the way. As they’re about to reply the snow falls off one of the snowman’s arms revealing the sign, to the hikers surprise. The hiker brushes off the snow on the other arm, which to his relief tells him the way he needs to go.', '1994-12-20', 5, '/uZKBSloU28eyrGGBFy61HptAyMe.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0E6066B63EAA4AB1887DD82DD4CCA60A', X'D5F0284F0EE345BF8539D02A825D15B2', 6, 'Farmer of the Opera', 'Julia surprises Martina with an opera performance she will never forget; Guerdy puts Larsa on blast for broadcasting her cancer diagnosis; Lisa hosts the ladies in Palm Beach, where Julia begins to question her growing friendship with Alexia.', '2023-12-06', 44, '/cXBC3m3jZ3TAcKZWG2xaxmPfEnF.jpg', '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
