INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0EDCBB2671E84B04AFAECC67C8FCD450', X'BD8A516B9872472DA8387AFF1070FEA3', 15, 'Elton John', 'Sketches/Songs: "Crocodile Rock", "Swedish Chef", "Benny and the Jets", "Veterinarian''s Hospital", "Any Old Iron", "Goodbye Yellow Brick Road", "Pigs In Space", "Don''t Go Breaking My Heart"', '1978-01-08', 26, '/3IbvEIUfRiWZGtisyqmHXcLIeSa.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0EE302DA0AD74B968229EAA120F1348A', X'BD8A516B9872472DA8387AFF1070FEA3', 9, 'Dom DeLuise', 'Miss Piggy hires Scooter to pay off the audience to go wild for her. She also has him send her dozens of bouquets and write her piles of fan mail, all part of an attempt to get Kermit to notice her more. Piggy and Scooter stage a conversation for Kermit to overhear, in which she pretends to have an offer from another show, but Kermit isn''t fooled. After finding out from Scooter what''s really going on, he tells Piggy he''s heard about her offer and has decided to let her go. When she breaks down in tears, sobbing that she can''t leave him, Kermit agrees to take her back, but at a lower salary. After all, if she can afford to have Scooter pay off the audience for her... Miss Piggy gets hysterical and depressed, but is refreshed by Dom DeLuise.', '1977-11-25', 26, '/tzUqIAG9GyX5knIGetjEqFGITIL.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0EE502B6965940E29AF7EC373CFA75B4', X'5C1B881FAC584D72B63F209952D4F902', 59, 'Episode 59', 'Dr Who''s Spring Clean  The BBC''s travelling Dr Who exhibitions are constantly changing to keep pace with the latest monsters the Doctor tackles. Tina goes behind the scenes, to lend a hand with this very unusual spring clean.', '1980-04-03', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0EE7E058AFAB4C3581210656F0A26944', X'151E88A195764BD1B84AC4D64C1C9FE8', 12, 'Beverly Hills Blackout', 'Diana apologizes to Garcelle for acting out at her birthday party. Lisa has a frank conversation with Erika about her recent behavior. Kathy’s prank annoys but doesn’t surprise Kyle. Dorit isn’t happy about PK’s brush with the law and makes her feelings clear. Sutton dips her toes into the dating pool and makes a memorable impression on her Bumble match.', '2022-07-27', NULL, '/9yW8L0jkkGaCaYG7F3HIwD6s5ZA.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
