INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0F0BF809323A46AD9918DCBA75680A57', X'BFDF87FF01DD4B5494BD19B384F41BDB', 21, 'Reunion (3)', 'The reunion concludes with the ladies recounting their traumatic experience in Glamis. Old wounds are opened as Meghan finds herself on the defensive for her lack of sympathy towards Vicki after the accident. When the ugly drama of Ireland is discussed, emotions run high and Shannon is driven to her breaking point.', '2016-11-21', 44, '/iJyvGUTY0xcuqeoetUzFBl78BvI.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
