INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0F1E44C0305E47EE8ADE4DF0B65CA305', X'4C79C0B621A442778967BE1E791EFDBE', 16, 'Pingu Wraps Up', 'Mother is ironing, and Pingu is chasing Pinga around the kitchen. Pinga then crashes into a chair, hurting her foot, and Mother rushes to console her. Mother decides that the foot needs a bandage. Pingu gets the first aid box out and Mother wraps up the foot. She goes to get the scissors to cut the bandage, but while she’s gone, Pingu finishes off himself by wrapping Pinga’s other foot and her arm. He then goes outside with the first aid box wondering what to wrap next. He starts with the snowman’s head, and then wraps Fathers motorised sledge. He calls in on Grandfather, and Grandfather lets Pingu wrap him up. Pingu leaves without unwrapping him, to Grandfather’s dismay. Grandfather tries to eat his sandwich, without success, then struggles across to the phone to call for help from Father. Meanwhile Pingu has wrapped the sign outside the bakery, some skis he found outside another igloo, a stranger on a bench next to a sign, and the bench and sign. Father arrives on his skis to untie Grandfather, and then goes off to find Pingu by following the trail of wrapped items that Pingu has left behind him. Pingu and Father then return, unwrapping the items, including the stranger, on the way. Pingu is riding on the front of the skis when they crash into a block of ice and tumble off, breaking a ski. They wonder what to do, then Pingu uses his skill in wrapping to bind up the broken ski so that they can finish their journey.', '2005-12-01', 5, '/4DxQMR05bD64CLVpsrfZse3D4EE.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
