INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0F7FE4BB4ECF47188739FA1E9D32EB07', X'54FACB0BDB5941FE9D64C7C7221A3C81', 17, 'Jesus, the Countess and Joseph', 'The show must go on for LuAnn who has been snubbed by the ladies; Dorinda is shocked by the surprise party; Tinsley is accused of lying about her relationship with Scott; Bethenny throws her S''mores and Whores Party.', '2019-07-03', 60, '/cj7pdLkK3yYUa3rWFY7Zgp5xjSQ.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0F818895695B4926B2BD814A57D80B5E', X'941B8C6544544336BE7C1D0591C12F90', 5, 'Pingu Wants to Fly', 'Pingu is having a snowball fight with Robby. Most of Robby’s snowballs are hitting Pingu, but Pingu has not managed to hit Robby at all, much to Pingu’s annoyance. During the fight, a seagull comes to watch and nearly gets hit by a snowball. The seagull takes Pingu’s side in the fight and makes a snowball, which it drops on Robby. Seeing the seagull flying makes Pingu want to fly himself, so he tries to do it. First he tries jumping off a small block of ice, but he can’t stay in the air. Then he tries jumping off the top of a rather taller block of ice, and still can’t stay in the air. Pingu spots an old barrel nearby and, using an old plank, makes a seesaw-like launcher. He stands on one end and Robby jumps from the high block of ice on to the other end, launching Pingu into the air. Pingu gets rather higher than before, but still can’t fly and plummets head first into a pile of snow, from which Robby pulls him out. Just then a balloon seller passes by, and gives Pingu his helium balloons in exchange for a couple of fish caught by Robby. Robby ties the balloons round Pingu’s waist, and at last Pingu’s into the air and flying. The wind catches him and he drifts away, chased by Robby on the ground. Pingu initially enjoys it, but soon decides that he’d rather be on the ground. The seagull comes by and pops one of the balloons, but this has little effect other than spinning Pingu around. The seagull then pops all the other balloons and Pingu crash-lands on the top of a high block of ice, from which he gets down using a rope made from the balloon strings. Robby then fires a large snowball at Pingu from a catapult. The snowball goes well above Pingu, and Pingu decides he’ll take cover. Robby prepares another shot, but is startled by the seagull just as he’s about to release the snowball; the snowball shoots into the air and lands on Robby’s head. He and the seagull both find this funny.', '2003-08-29', 5, '/dRsEtYezYRv4tfhVku9x6JybqST.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
