INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0F8AB96C2E0848168F2064236BE312B5', X'BFF09904103D4AE29C13C1FEBC903A46', 5, 'Work Song', 'This week''s episode is about performance. In "When Aunt Lena Did The Rumba" a little girl puts on her own musical to cheer up her sick Aunt Lena. The Boy''s Choir of Harlem shows us the beauty of music through voice. Comedian Peter Patovsky shows how he makes people laugh. Then travel to Broadway for a glimpse of the hit musical "CATS". Books featured this week are "My Mama Had a Dancing Heart", "The Dancing Man", and "The Old Man Who Loved To Sing".', '1998-10-09', 30, NULL, '2026-04-03T17:36:20Z', '2026-04-03T17:36:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
