INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'0F96E5A7B6C044BB8827DB56056D0664', X'1D713CA64E174F84949C8CFD98514127', 29, 'Wake Up Call', 'Dive in with the Pawn Stars when a 1964 770 Amphicar floats into the shop. Will Rick be able to navigate his way to a deal, or will he sink it before it swims? Then, Corey and Chum are on a roll when they check out a 1939 National Bowling Association Championship Ring. Will they bowl a strike or wind up in the gutter? And later, Rick bets Corey and Chum can''t go without their cellphones for the day. Can they answer the call or will they be disconnected?', '2014-11-06', 21, '/dsUsEQaTq2bRqWS1r30Wm5YuH9l.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
