INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1075269F47BB40B8B20B0081E6FAA196', X'7C75633629DB4634B976E993E8F51DA2', 1, 'Don''t Let the Zip Code Fool Ya', 'Gizelle and Charrisse’s friendship hangs in the balance following Gizelle''s shocking accusation that Charrisse is cheating on her husband. When the two ladies finally get together to talk, all bets are off! Meanwhile, Ashley’s involvement in a new charity threatens her responsibilities to her and Michael’s restaurant, causing tension in their marriage. Also, Robyn and Juan adjust to their new lives outside of Potomac, while Karen and Ray butt heads as they hunt for a new home.', '2017-04-02', 42, '/uKCi4h7paImEiWGlSsKVctUpzxZ.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'107650C445F44287B47261501F0EAB19', X'5144DE59E67F4FCF919B7106989AB797', 28, 'Owning It', 'Leon obtains a new watch but drives everyone else crazy with it, causing them to snap back at him. Kiki is preparing chili in the kitchen, and Sizzle and Nuzzle want to taste it so badly.', '1995-02-22', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
