INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'10855C945E0742E4867F71D122EDC05C', X'8B6BBAC8E5EF49C7A5C1197CFB19F772', 17, 'Mister Rogers Talks to Parents About Competition', 'Rogers discusses with parents combative attitudes.', '1981-05-30', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'108EEED30B734ACAB576AEA95284594E', X'3982796B54514100904246BEDF6A20A5', 3, 'Pingu and the Seagull', 'It is a nice day and Pingu is out riding his brand new blue scooter. Circling overhead is a Seagull. It squawks, and Pingu hoots back and waves to it. The Seagull then poos on the scooter, rather annoying Pingu. Pingu goes indoors, cleans up the scooter and puts a cover over it. He then goes outside again. The Seagull is now sitting on top of the igloo, and squawks when it sees Pingu. Pingu makes a snowball and throws it at the Seagull. The snowball narrowly misses as the Seagull takes off. The Seagull retaliates by pooing on Pingu''s right foot. Pingu cleans himself off, and then spots that the Seagull has landed on the ice nearby. He tries to grab it, but it takes off and flies out of reach. The Seagull lands again, and Pingu has another attempt at grabbing it, but this try also fails. The Seagull lands for a third time, but this time Pingu sneaks up on it from behind and succeeds in getting hold of its legs. The Seagull tries to fly away, and eventually Pingu has to let go. The Seagull circles around, and poos on Pingu again, this time on his right shoulder. The Seagull then lands to have a drink from a nearby ice hole and is grabbed on the beak by a lobster, which won’t let go. After initially being amused, Pingu takes pity on the Seagull and tugs the lobster off. The lobster turns on Pingu and follows him into the igloo. Pingu eventually chases the lobster away and back into the pool by banging some pan lids. He pets the Seagull, and just when he thinks he’s made friends with it, it flies away and poos on him yet again, right on the top of his head. He goes inside and tells Mother all about it, and she washes his head clean.', '1992-01-05', 5, '/isIXUg1LVoPnnHxG5RUiPAlFbVv.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
