INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'10B4FB1B398049E8884B3C4A8708FA8B', X'97A3D1F5A8F147CD81222E74A092836D', 26, 'What''s Up With Alex? (2)', 'Lenni finds out Spencer has something to do with how Delilah knew where to get her tape recorder.  Tina and Hector go on a stakeout by taping Big Ralph.  They find out that a kid is involved, but they don''t know who it is.  Big Ralph gets arrested in the meantime.  Also, another student, Jason, had a gold bracelet stolen from his locker.  A boy named Arnie is also acting suspicious about the fact he has Maria''s camera.   In the meantime, Alex is playing at a Dragons game.  After their victory, Kevin wants to celebrate by smoking pot, which Alex doesn''t want to do.  Alex turns him down.  Kevin doesn''t show up for school the next day, so Alex is now behind on a project he''s supposed to do with Kevin.  Kevin offers Alex pot again, but accidently leaves a joint behind, which Gaby finds.  Gaby writes Alex a heartfelt letter about why he shouldn''t smoke marijuana, which he takes with him on his way to Kevin''s house.', '1994-04-17', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
