INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'10C32910813648F997452DBC571561A2', X'BD8A516B9872472DA8387AFF1070FEA3', 6, 'Rich Little', 'Gonzo auditions real chickens for his dancing chicken act. Due to a last-minute cancellation, he finally gets on stage, but his chicken Lolita hardly moves.', '1977-11-04', 26, '/3vzzbzkXPAgc82OP2MxdfTvr8zV.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'10C50873FA7A4EF4BF6195F005D37184', X'22BEBA7F9B8E456393DA46E76ECBA427', 6, 'Snow White & The 6 Dwarves', 'Snow White (Amy Sedaris) visits Sesame Street with her dwarves.  One by one, each dwarf leaves the group, and soon Snow White ends up with ZERO dwarves.  Can Elmo save the day for Snow White?  Also in this episode: Bert and Ernie sing about circles and Grover learns how to ride a bike.  This episode is brought to you by the letter O and the number 7', '2006-08-22', NULL, '/sjuvKOH8Snmb6QesGMzQmZhyEjZ.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'10C891EC89A94DDD8F161E0A896E96F6', X'3EE646E823AE4DECBBC6C7E6A210D55B', 86, 'Preston''s caps', 'The Count asks Susan if he can accompany her on her errands today. She soon realizes he''ll be counting every step she takes and tells him she''ll be driven crazy. The Count is thrilled and adds her to the total of people he''s driven crazy so far (six) before he starts to follow Lillian.
