INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'10DD3652BB244A82AA9353EABAA5DB54', X'2F5A4FFE2548418185AC6145CB3E3BF7', 1, 'Meri, On Her Own...', 'Meri''s offer on the B&B is accepted! But she doesn''t have enough cash for the down payment and asks the family for help. Kody steps up, but later, he realizes he doesn''t have the money and reneges, leaving Meri to come up with the money on her own.', '2019-01-20', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'10E59B2B9B284F7980D6A85A6ACE076C', X'DA06465B91544FEBA455374DF7DAB02F', 4, 'Birdseed Cookies For Granny (4086)', 'ig Bird’s granny is coming to Sesame Street, and with Alan’s help, Big Bird bakes“The World’s Greatest Birdseed Cookies” for her. Big Bird and Alan have gatheredall the ingredients they need- birdseed, applesauce, bananas, porridge and cinnamon. Then, Baby Bear comes in wanting his porridge, but tries a healthy fruit saladinstead of his usual since Big Bird and Alan need the last bit of porridge to makethe cookies. As Alan and Big Bird continue to mix the ingredients, The Count comesin to help them count and figure out how many cookies they will be able to makewith the dough.', '2005-04-07', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
