INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'11114B866B58494A8F8F2920DA7BF667', X'AD180412A5D64E4A8B49590334F2FC69', 12, 'Homeward Bound', 'When the weasels return home, all the animals are overrun with joy. Fox explains their problem with the rats to the weasels and asks for their help. They agree, but first they must train Fido and Cleo on how to deal with rats ... using Spike as a volunteer. Mossy tells Hurkel that he found Shadow in a hutch by the Warden''s cottage. While Hurkel and the weasels try to get her out, the Warden''s cat summons Rollo to get rid of them. Of course, he recognizes his weasel friends and is very happy to see them. Meanwhile, after a few fights for leadership of the herd, the white deer and Farthing animals name Laird as the new leader of White Deer Park. Elsewhere, the rats, at their largest number yet, prepare to launch a massed attack on the animals of the park.', '1995-12-14', 25, '/h3FsLpvVxV6Ew0LDGnJ5luKD8Qc.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
