INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1154A3DD20BD4B10922DB99F4AB56916', X'63F9BF6D39B344F4B885A56807277A80', 29, 'The Christmas Toy', 'When no people are around, the toys still play in the playroom. But since a toy will be frozen forever if a person catches it out of position, they have to be very careful. It''s Christmas Eve, and Rugby the Tiger remembers how he was the Christmas Toy last year, and thinks he''s going to be unwrapped again. And it''s up to Apple the Doll, who Rugby supplanted as the favorite toy, to tell him what''s in store. But Rugby won''t believe her, and tries to get into the Christmas package and lets Meteora, Queen of the Asteroids, loose. Unfortunately, she doesn''t know she''s a toy and thinks she''s landed among aliens. And it''s up to Apple, Mew (the Cat''s toy mouse), and the other toys to get Rugby out of the box and Meteora back in it before they''re found and frozen.', '1986-12-06', 50, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'11574006166040728EE03B572B5CC122', X'AC068B8E80F646BFAFB2DCEBCF76DC36', 8, 'Spooky', 'Skye and Ben exclude Kiki and Julie from their Count Spookula club because they don''t think girls like spooky stuff, but they learn that some girls do like scary stuff, and some boys don''t. Leon and Jody do not appear in this episode. Sizzle and Nuzzle only make cameo appearances.', '1998-10-29', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
