INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'115C3FFECD7D41B8BA71423022389A9F', X'6C47406BB3D640D8B4831AE1B3D30009', 4, 'Fire Of Pontypandy', 'When Fireman Sam performs a super-heroic rescue, he is awarded a special bravery medal and offered a new job in Newtown by visiting Chief Fire Officer Boyce. Meanwhile, a Pontypandy Pioneer Scouts camping trip, results in a forest fire that threatens to engulf Pontypandy, forcing everyone to prepare to evacuate ! Will Fireman Sam leave his beloved town, and will this be the end of Pontypandy ?', '2018-06-13', 10, NULL, '2026-04-03T17:14:36Z', '2026-04-03T17:14:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1164AF130FC84CF3AC47B21CF9A944FD', X'5B5E8B2F0A854488B3DC3D8B794E6582', 2, 'It''s Either My Way or the Feng Shui', 'Vicki prepares for her big office move while Shannon enlists the help of her feng shui expert to try and bring balance into her otherwise chaotic life. Lydia is busy launching her brand new magazine which features Peggy, an Armenian firecracker, whose life may look perfect but not everything that glitters is gold. Kelly struggles to make her marriage work while Meghan settles into life as a new mom. Tamra plans an over-the-top birthday party for her granddaughter, Ava, where tempers fly as Lydia and Shannon meet for the first time and don''t see eye to eye when it comes to Vicki.', '2017-07-17', 44, '/6vTKz7Z2cYfUFGbCQMEC9wE5wp.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
