INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'11936112401B49D5AAD487AC9F76C292', X'5BA20443D99F482081F66832D3F2BC4F', 14, 'Volcanoes', 'Volcanoes are mountains made from molten rock. The Earth’s crust is divided into big slabs, called plates, which are slowly moving all the time. The plates are floating on the Earth’s mantle, a layer of gooey hot rock that flows like maple syrup. Some places in the mantle, the rock gets very hot and nearly liquid. It’s called magma. Sometimes the magma reaches the Earth’s surface and forms a volcano.', '1996-01-31', 26, '/uYEckRJRRtdxDthkhxMzNc00fgq.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
