INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'11E81AA3C3954E33837A6D3E7555299A', X'89BA90EC2C794A12A11D7465D1757683', 18, 'Rick and Morty The Non-Canonical Halloween Adventures', 'This follow up to the original run of the Non-Canonical Adventures brings new movie parodies featuring Rick and Morty. The movies featured are: Beetlejuice; The Blair Witch Project; Evil Dead 2; Hellraiser; Home Alone; Jaws; Predator; Reservoir Dogs; Terminator 2; and Videodrome.', '2019-10-31', 3, '/qxXtl0IktQPHWIUy3AGoFgtvd9j.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'11E882C4714D4E90ADD0D070D0A726C8', X'9193E795DA7C40ECB68FF63AA7D5174F', 213, 'Unused / extended scenes from season 3', 'Five unused and extended scenes.', '2014-02-18', 14, '/c4xCuru2cxaUd8xzGPsa3R90828.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'11EB653DB1A649C9B47D943E142A9CF9', X'E291DF42D44F49E5BF812DF32EE4A30F', 1, 'Friends At Play', 'Ojo is excited about a visit from her friend, Christine. The two quickly get involved in one of Ojo''s imaginative games --- a pillow castle. Tutter arrives and asks if they''d like to play checkers, but Ojo tells him she''s in the middle of her game with her "best friend," Christine. Tutter is hurt by the use of the term "best friend." He creates his own friend to play with, "Mr. Cheese," but Bear helps to mend his friendship with Ojo. He also finds Pip and Pop at odds with Treelo out at the Otter Pond. He keeps pretending to be a monster during their Deep-Sea Divers game and they don''t like it at all. Bear, however, introduces them to a game called The Treasure of Kalamazoo Bay. In the Shadow segment, Shadow retells the story of "Mary Had a Little Lamb." The lamb in this version drives a car, skies and scuba dives in its efforts to follow Mary everywhere she goes.', '1999-07-19', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'11F0F33286F443E996B248D3FA55478D', X'36E5C604FEA94BCF834371BFAF60ECD2', 4, 'Foduck The Vigilant', 'Foduck is soon to earn his ''v-word''. This means he will be allowed to travel in the open ocean.   However, he is having a spot of bother picking a name so he turns to his other tug friends for help.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'11F263288146494BBDCEF338144D7343', X'EA73E13C696248048305C303DF65F89F', 54, 'Toy Boat', 'Lady Aberlin gives the Trolley a waves costume for the opera, which also fools Corny making him want to have a part in the opera. The entire Neighborhood of Make-Believe will be the backdrop, simulating the sea.', '1969-04-24', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'11FB4EAF4C2A425286012C681460BB97', X'8BDF0AD3A7984D5AB304C7501EAE6867', 4, 'You Just Don''t Get It', 'While her fiancé is in the hospital, Gretchen Rossi lifts her spirits by hosting a burlesque party at her home. Vicki Gunvalson and her family tour a million dollar yacht that she hopes to buy despite her daughter Briana''s protest. Life without their father around pushes Jeana Keough''s kids, Colton and Kara, to grow up quickly and seek out other paternal figures. Meanwhile, Tamra Barney''s son, Ryan, has an abrupt change of career aspirations much to Tamra and Simon''s surprise. New housewife Lynne Curtin is introduced and we meet her husband and two precocious teenage daughters, Raquel and Alexa. The eldest, Raquel, pushes her parents into having a huge 18th birthday blowout bash at their house. Vicki, Jeana and Tamra try to have a girls night out but a discussion about marriage and ex-husbands turns into a contentious situation between Vicki and Jeana.', '2008-12-16', 44, '/5xdde6IJ6PsqXLeCZWhJY4RqGMu.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
