INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'123A0B714E254C8BBCEBA2B13824A2DE', X'698A60DF8ED44CA9BCB1EBAB343DACDD', 15, 'The Visa', 'A lawyer George dates could help Jerry''s pal, who''s facing deportation, thanks, in part, to Kramer''s trip to Florida.', '1993-01-27', 23, '/60QyGW6rYUEjbBewNB0mDHcG1t7.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'123CE03C9C09452CB9627FAE67F6A093', X'42E591E22A884434AE9F3D4B1D685613', 20, 'London Pawning', 'Pawn Stars goes international when Rick takes a trip to England and visits his buddy''s pawn shop. Will Rick feel outclassed when he discovers that Regal Pawn owns a piece of the Titanic? Then, back in Las Vegas someone wants to buy Rick''s favorite mini-bike, a Rupp Roadster. Will the guys have the guts to sell it while Rick is out of the country? And later, Rick finds some rare maps of Nevada and North America. But with non-negotiable prices, will he take his business elsewhere?', '2013-08-15', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'12470991BF5B48D3B344544527B51811', X'E40E6B639F84449F8E8853209B0906C8', 17, 'The Worm Cup Games', 'Alan invites Big Bird into Hooper''s Store to watch the Worm Cup games on his TV set. The audience consists of a few kids, and even some worms with their own miniature tables and vans. The worm audience is split into two groups: one from France, and one from the USA. Alan explains to Big Bird that the objective of the Worm Cup games is to kick a ball into a cup the most times. Worms from all over the world are competing for the cup, including Slimey.', '2007-09-20', NULL, '/mvHPcvwT2ID0QuDN2N48fXhpeSX.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'124727E6A1814745B7209266BFB15C02', X'421C33664D984BAFB4AD6EC5047DF9F8', 4, 'Ladonna Compson: Party Animal', 'Apple picking, bake sales, craft classes... there''s so much to do in Elwood City in the fall! And Ladonna''s determined to do it all. But when you''re juggling so much at once, you''re bound to drop a ball... or five.', '2013-11-12', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
