INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'124D89928DAC4B1494C294C8BB08015A', X'20D7138EEEA846A88ADA2B0F0EE1F674', 31, 'Episode 31', 'Remember when Simon shared his cornflakes with a tiger, Sarah played bowls with Chelsea Pensioners and Peter flew like a bird at the world''s first Aerodium? Other highlights include guide dog Prince''s first meeting with his blind owner, Sarah''s dive on the Mary Rose and Simon''s climb up a 100ft spar tree. Special guests include HRH Prince Charles, David Bellamy, Sefton, Terry Wogan and Evil Edna.', '1982-12-30', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'124D99E7AF5F40958936A8BEB61C2BAA', X'6D2B78D726124AFB81CADEE774AF9C2B', 8, 'Dance', 'Rogers first sees Sam Weber demonstrating his tap-dancing skills. Mr. McFeely shows a videotape on how shoes are made. Sam Weber also visits the Neighborhood of Make-Believe to disprove Lady Elaine''s belief that men don''t dance.', '1987-05-11', NULL, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'12543EDAF67449C6BACCA055B9F2C35E', X'5A771F52FE964EA2B567A8DDE899059E', 5, 'E Equals MC Pawn', 'The Pawn Stars make calculated moves when some handwritten math by Albert Einstein could multiply their profits. Chumlee tries to prove he isn''t dim when he pays big bucks to have an antique headlamp tester shining brightly once again. Corey and Chumlee take a stab at buying a prop from the classic horror movie "Child''s Play." Later, a pill case pops into the shop that may have once belonged to Hollywood legend Carole Lombard, but Rick does a second take to make sure it''s not a stand-in.', '2017-10-30', 21, '/6aVMR1qcgklwo13TMwOBpq8j556.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
