INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1278F1901DFC46C1AB268E3C2ED9EAEE', X'5DB3FF78E43948E18F67988ECBF85D17', 5, 'Monsieur Treville, Captain of the Musketeers', 'Dogtanian has gone to see Monsieur Treville to join the Musketeers. When he arrives Widimer and some guards are about to arrest Aramis and Athos for drawing their swords against some of the guards. Treville comes down and sorts the problem pointing out both sides drew their swords, making it a duel, so both parties should be arrested. Before leaving Widimer spots Dogtanian and orders the guards to arrest him, a farcical chase follows, ending with Dogtanian jumping on a coach that takes him back to the Musketeers headquarters...', '1981-11-06', 24, '/cQK8I1laiFAk98GNXRosH4Jitdr.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
