INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1286CE3651264746A30A818021267009', X'65D1CAD80120425EAE9B5020CE773B32', 12, 'Defense Is the Best Offense', 'The women return from two tense trips with most feeling the planned bonding failed to take hold. Tamra joins Sophia on a music-school tour. Jenn realizes her upcoming wedding is having a greater emotional impact on her kids than she anticipated. Everyone reunites when Gretchen hosts a tactical training event. The ladies learn self-defense, but a shocking rumor about Tamra leads to an explosive confrontation.', '2025-09-25', NULL, NULL, '2026-04-03T16:35:36Z', '2026-04-03T16:35:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1288B7BFE8984B9BA10B5C0E6D7D95EB', X'095258D0D8DB40968AC76A42CD4CBDCF', 16, 'The Battle Of Leaking Roof', 'It''s about to rain, and Ma wants Pa to fix the hole in the roof before it starts to pour. At the same time, Boober and Mokey are out getting radishes, and when Ma accidentally picks Boober up, he loses his hat. Boober''s too afraid to go back out there, so Mokey goes out by herself to get the hat. Meanwhile, Ma''s having a terrible time getting Pa to fix the roof, because he''s too scared of heights. Will Pa get over his fear and fix the hole in the roof before the rainfall?', '1985-04-15', 24, '/2Bd3PI5E5G1gUZwrFyyUZVrFZqS.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
