INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'12E34B87818B4E169B93F53274CD6CF0', X'02849455D14B476B9603EEF5FB5D2AB3', 16, 'Au Revoir Drama', 'While the ladies celebrate Monique’s birthday with a fabulous night of burlesque, Candiace finally uses her vocals to win the women over. Gizelle confronts Charrisse about her involvement in bringing Sherman’s ex-wife around, leaving Charrisse and Monique at odds. Ashley and Karen exchange heated words and accusations regarding Karen’s marriage, cause a deeper rift in their already rocky friendship.', '2018-07-22', 42, '/yZqfdpuhMlkQuInEOadaV6QGmfT.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'12E5C6E55ECF4857B7FA94D4AE751AA5', X'0EBBA123871D4D2BA054EB85D2AD9450', 39, 'Princess and the Popstar', 'Princess Poppyseed''s life on her familys farm is far from the glamorous world of her favorite pop singer Vanna Banana.  While Princess milks the cows and dreams of a life on stage, Vanna has her own dreams of a life far from the hectic pace of stardom.  On a chance meeting Vanna & Princess cross paths and realize they look almost exactly alike which leads to the crazy notion that maybe they could switch lives!  In a flash the girls secret plan is launched but as Princess tries to live up to the demands of being a diva and Vanna learns how to milk the cows each girl realizes that the life they longed for doesn t fulfill all their dreams after all and the life God gave them is the one for which they were uniquely and lovingly designed.', '2011-08-16', 30, '/i2s97n4spM7Il4WOBe3u12LuiWw.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
