INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'135F2195CDD447A5895EA98F7470C288', X'A8DB07E5FBA349A9BD12947C111B39BE', 16, 'The Countess Bride', 'Gambling, dancing and dining lift spirits for the ladies at the Mohegan Sun casino. Also: Carole and Adam discuss their future; conflicting discussions surround plans for LuAnn''s engagement dinner; Bethenny packs for an ill-advised trip; and a new getaway is announced.', '2016-07-20', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'135F717C850C47EAB739B5080A0D0C81', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 22, 'Rock, Rock Band', 'Vergil Von Vivaldi, played by Michael McKean, has come to Sesame Street to start a rock band made completely out of rocks! Vergil sings a song to show that there are rocks all over Sesame Street. He points out that the sidewalk, a statue in the garden, and the building are all made of rocks. Elmo and Abby join Vergil to search for rocks and try to identify their names based on their characteristics. First, they find a tiny rock, called a pebble. It is too light to be the singer of the rock band, but can be the tambourine player. Elmo then sees a heavy rock. It will play the gong in the rock band. Zoe comes by and suggests Rocco could be the lead singer. The group observes that Rocco is a rock called basalt, which means it came from a volcano. Unfortunately it has too many holes, so he can’t be the lead singer but can play the bass. Elmo finds limestone with fossils of leaves and shells on it from a long, long, long time ago. Vergil says the limestone can play the flute. Zoe finds a shiny rock called obsidian. It will play the oboe. Then, Abby finds marble that is sparkly and colorful. Marble will play the mandolin. Since they haven’t found a lead singer, Abby finally changes Vergil into a smooth, crystal like, sparkly rock called a gem. He can be the lead singer. The only thing left to do is… rock!', '2010-12-27', NULL, '/l5MRHn5K1LmS3Vu30NbuqKU3d3I.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'136300E9468A4185A3A3AA7DD722C20F', X'7C542833ED0A42729C53E822408AB434', 18, 'Sailing Lesson', 'When Charlie and Bronwyn take the kids on a sailing lesson, Charlie feels upstaged by Peter and a seagull. As Charlie tries to win back the kids'' attention, he ends up sinking the boat.', '2024-11-04', 10, '/uapcCTcwhFTOdFJTIBqaqnfCyEZ.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
