INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'136D52465E1E4D5AA919FE07E85790FE', X'D9973960273B4A92A7DA62EFE8860D09', 12, 'Sinners in the City', 'The Vegas trip implodes during dinner when Jen feels betrayed by Meredith and Lisa, yet again. Later that night, the ladies, sans Jen, gather together and discover there is more deception brewing amongst the group. Mary reminds Lisa of Jen’s destructive behavior, and Whitney arranges a spiritually healing activity for the ladies only to be derailed when Meredith’s marriage rumors are brought up, Jen is confronted and the women are left questioning who to trust.', '2021-01-27', 42, '/hiMzE1whpf8MAStwkBXHUUBBWCC.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
