INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'139A1D5568414E53866458F0EF171E16', X'3EE646E823AE4DECBBC6C7E6A210D55B', 110, 'Tim Robbins stars in Prairie Dawn''s pageant', 'Tim Robbins arrives on Sesame Street, and Big Bird and Snuffy try to guess who he''s looking for. It''s Prairie Dawn. When she shows up he becomes star-struck, mentioning some of his favorite Prairie Dawn pageants, and she invites him to watch the rehearsal of her newest production.
