INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'13A2F9E7695B496CB24544D7ED4A3546', X'63F9BF6D39B344F4B885A56807277A80', 26, 'The Muppets on Puppets', 'The Muppets on Puppets aired on NET in 1968, as part of the Adventure in the Arts anthology series. In this one-hour special, Jim Henson -- with the help of Muppet character Rowlf the Dog -- explains the art of puppetry, from building to performance. Henson describes the various kinds of puppets; demonstrates how to operate a hand puppet; and provides a brief history of puppet development and performance throughout the world, beginning with the influence of the character Punch from the Punch and Judy shows of the 1800s. Jerry Juhl and Frank Oz demonstrate how other kinds of puppets work, such as the string puppet or marionette, the Javan rod puppet, the finger puppet, and the Sicilian puppet.', '1968-01-01', 26, '/dwkHumJPMSjXNJjZXu8aBOM8Nz1.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
