INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'13B165F8175649ECAAA570AE875DB3B5', X'1A534647384B4C00BB6CA3371AD962EB', 3, 'RC/DC', 'Rock on with the Pawn Stars when a signed AC/DC album electrifies the shop. Will Chum get it "done dirt cheap" or will he wind up on the "Highway to Hell"? Then, Rick gets fired up over a Beals Model Remington revolver. Can he hit his target or will the deal end in a draw? And later, when Rick wants to find new ways to advertise the pawn shop, he thinks small to get big results. Will Rick be able to pick a winner or will his new plan run out of juice?', '2015-01-15', 21, '/sZMZip6tvgPN3CSzgIlL9NzLJbT.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
