INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'13BDF0A0C1BF4AF9A25A81D793A29A86', X'E291DF42D44F49E5BF812DF32EE4A30F', 5, 'Halloween Bear', 'It''s Halloween at the Big Blue House. The house is all decorated and everyone is getting ready. Bear helps his friends to find costumes and helps Tutter with carving a pumpkin. He always helps out Treelo when he''s scared by Ojo''s bat costume. Later, everyone gets together for some fun trick-or-treating. The kids have all picked out their Halloween costumes, but Bear hasn''t been able to find anything to dress up as. The kids go through Bear''s box of costumes and come up with an amusing idea. In the Shadow segment, Shadow performs the song "What Do Shadows Do for Halloween?"', '1999-10-21', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
