INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'13C7C53EAE5745FA8B9F8C5203D70191', X'937EE587E2EB46AA9A693D6BAB04398F', 6, 'A Three Hat Day', 'A totally unreal hat store called "Hats... to Where?" sells hats that transport customers to all parts of the world. LeVar whisks himself to the horse racetrack at Turf Paradise, to a model train display in Three Bridges, New Jersey, and to the Nassau Coliseum, where he gets a goal tending lesson from Kelly Hurdey of the New York Islanders. Zelda Rubenstein reads A Three Hat Day, a story about a man who loves hats very much, and how he meets his soul mate when he goes shopping in a new hat store.', '1987-06-29', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
