INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'14034D262F924D84A0B152DE2C1CC31B', X'B1D55597D9D24EEEAB9546DBB163291A', 24, 'Pingu and his Friends Play too Loudly', 'Pingu and Pingg are playing hopscotch, not knowing they are doing it in a parking space. When a parking neighbor comes here to park in and they get into a fight. Then suddenly, Pingu and Pingg are forced to play somewhere else. They go over to another igloo, and start running and playing about very noisily. The grouchy neighbor starts yapping at them. Pingu, Pingg and Pingo who comes along tease her. She was about to hit them with a carpet beater but she missed. She leaves and accidentally closes the window on her hand! She cries like a wolf (in the early version of course she did this,) making Pingo, Pingg and Pingu laugh. They then start playing ball, and the ball accidentally goes onto the grouchy neighbor''s roof. She catches it and takes it inside. Pingo and Pingg protest to tell Pingu to go get it back so he begs for it back. With no avail, but then suddenly, the grouchy neighbor gets locked outside, and though hearing them, laughing at her. At first, Pingu decides to help her, by climbing through the window and unlocking the door. Then suddenly, she gives them their ball back, and they all play together. But the grouchy neighbor accidentally hits the window on her igloo making them all laugh again!', '1990-10-13', 5, '/eU30zzZPcP1Y030q3xDFnREZMbI.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1406595599694B01996F42B58C36F712', X'DEC4A06D731B41E48B15374F47D1F5C7', 7, 'Spa-Cation', 'After being on home confinement for over a month, Teresa says goodbye to her ankle bracelet and the ladies plan a trip to celebrate; Siggy returns to her religious roots; Melissa confronts Jacqueline about involving Joe Gorga in her fight.', '2016-08-28', 43, '/bZba7BlQhPn3ehOCZIyo89RwaVT.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'140A0EBAE37C40DDA531928334EFF94A', X'4D2CAC0F38FD438B8AFAACF43952E535', 181, 'Episode 181', 'A magazine programme for younger viewers. Introduced by Christopher Trace.', '1962-04-30', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'140B156707684B1B8B36071F4671D8B7', X'363A94F9E0E5441CAA862BE2E9832DA1', 5, 'Wreck it Rick', 'Rick and Chum kick it with a rare pair of Pumas from 1968. But will a shocking sticker price leave them in the dust, or can they race their way to a deal? Next, Chum is blown away by a fan from the 1940s. Later, Rick reads into a collection of letters from historical figures, but it''s some lab notes by Marie Curie that really leave him glowing. And finally, a Post Malone guitar inspires a smashing adventure for the guys. Will it bring them closer together, or wreck their day out?', '2021-10-30', 42, '/eZ4WJRAK3SPhvINhvtvh65D1AGw.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'140B3E9F00C44BBAA62BB3D19B7F216E', X'73AE1459BA914185A9DABF6F2844AF49', 13, 'Not Feeling Jovani', 'Dorinda hosts the women at Blue Stone Manor for a relaxing weekend in the Berkshires. Sonja confronts Luann about paying her less than she deserves to perform in her cabaret show, and Dorinda steps in to defend Sonja. Meanwhile, Elyse approaches Ramona about the current state of their friendship.', '2020-07-09', 60, '/kQChlr3Vy6VlEIPq59XkTCpqRvQ.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'140B69D6FFBD48A49D6C61BFEC61888D', X'1A534647384B4C00BB6CA3371AD962EB', 31, 'Ticket to Pawn', 'Twist and shout with the Pawn Stars when a 1963 Beatles signed guitar strums into the shop. Will Rick "let it be" or yell for "help"? Take a ride with Corey as he gets revved up when he checks out a 1981 Suzuki motorcycle. Will he kick start a sale or will the negotiation skid out of control? Then, Rick tries to teach the guys some office etiquette.', '2015-05-25', 21, '/seD17DjWP5b7KSVJsPFTofhnWXB.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
