INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1418AE192A5A4B77AB3B34987EE67BB4', X'C01DDD2ABDB14C978D0458F791EF1C24', 39, 'Stinky', 'In the creature world, different smells mean different things. When a skunk visits the gang at Animal Junction, Zoboo, Martin and Chris discover the difference between a ''come-here'' smell and a ''go away'' smell. They also visit with a mink, a creature that scent-marks to let other creatures know that it has passed by. Chris decides to make a Chris scent so he can scent-mark Animal Junction. Jackie gives her friend''s dog a bath in tomato juice to get rid of a gift from a skunk that didn''t want to play with her.', '2000-04-26', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
