INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'143962803C1248A0AA235E063044A642', X'5B2C93657BD94CA1A3FB15F1A024A56E', 6, 'Girls'' Night Out', 'LuAnn''s son objects to her busy social schedule when she and Bethenny go to dinner after having drinks at the house. Elsewhere, an aloof Jason is late to a dinner with Bethenny, Jill and Bobby; and Alex brings Simon to a girls-only night, a move that irks Ramona.', '2008-04-08', 60, '/69Uf6uOwXn2ZWLgyN0e5r5ydIu3.jpg', '2026-04-03T16:35:21Z', '2026-04-03T16:35:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
