INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1448DE1700674A7F9A44629B3DC1CC55', X'DF77DBA2BBDA4F3897138D5C856F852E', 3, 'There Were Five In a Bed', 'The bed where all the toys sleep is getting rather crowded. When Old Bear falls out and bumps his head the toys decide it would be a good idea to try and find somewhere else to sleep. They try all sorts of strange sleeping places; drawers, baskets, bowls and hammocks but there always seems to be a problem. In the end Old Bear comes up with the perfect solution and, at last, there is plenty of room for them all to sleep.', '1993-10-17', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
