INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'146C9BD4164E496BB96CE4B678F121C3', X'4A8E3DB080684FF3942F91F45F665F20', 18, 'Hug, Hug, Hug!', 'A sculpter named Pygmalion carves a statue of a woman, falls in love with her, and gives her a hug - only she can''t hug him back. The Lions then try to help find ways for the statue to hug Pygmalion.', '2000-04-26', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'146CEEF0E6C34FF3A202537991C7D547', X'941B8C6544544336BE7C1D0591C12F90', 26, 'Pingu''s Bedtime Shadows', 'It is night, and Father keeps dozing off. Pingu and Pinga are playing outside, and Mother tells Father to get them in so they can get ready for bed. They come in and Mother takes them into the bathroom while Father dozes off in the chair again. After some typically naughty behaviour in the bathroom by Pingu, including squirting the toothpaste on the mirror and making a fiendish shape from the pattern, they eventually get to bed. Mother snuggles them down in bed. Pinga dozes off, but then wakes and is scared when she sees a shadow of a monster on the wall. Pingu is also initially scared by the shadow, but then realises that a mask and some other things have caused the shadow. They both sit on Pingu’s bed and Pingu makes some shadows on the wall that Pinga enjoys. She then wants Pingu to do Robby, but is not very impressed by Pingu’s attempt and does a better one herself. Pingu then does a sailing boat; Pinga does a schooner. After some thought Pingu does a shadow of Father and mimics him, which Pinga applauds. Pingu then thinks that Pinga is doing a lifelike shadow of Father, with appropriate sounds, and claps wildly, but doesn’t realise as Pinga has that it’s the real thing! Father tells them to go to bed, but when Mother comes in she finds all three of them asleep, snuggled together in Pingu’s bed which makes her laugh, and then puts a blanket over them.', '2004-02-06', 5, '/5gIyaCskulMYapKkRGhlR5CDSke.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'146D6A46C19144179060C0C275A2605A', X'671BD4DA347040F99A0340FBA34D2B8E', 1, 'Vive La Hecks', 'Axl returns home from his summer trip to Europe, sporting a man-bun and embracing a new, chill European outlook on life. Mike just wants him to clean up and look for a job, but Frankie thinks Axl will do this on his own and asks Mike to give him a little breathing room. Meanwhile, because Sue worked the entire summer at Spudsy’s and missed out on having any fun, she decides to cram in a whole summer of fun in two days before going back to college; Brick makes the decision to break up with Cindy because he doesn’t want to be tied down in a relationship when he’s about to embark on the revelry of his “big sophomore year”; and Frankie desperately tries to come up with an item for a time capsule that’s being buried under the Orson cow that will make the town remember the Hecks when it’s opened in 100 years.', '2017-10-03', 22, '/9YzlgkgtN1TzZqTMVfx9Bl0nMgb.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
