INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'14C684BEC08942DBA3B9C241F73AFE33', X'227B84290DFD47E4B874C37DA20C403F', 3, 'Sink or Sell', 'Corey gets into deep water with his dad and "The Old Man" when he buys a 1984 Chris Craft boat without first testing it out. Will he bounce back and make a profit or see his investment sink? Then, an old timer brings Rick an 1849 colt revolver that he forgot to unload! Will Rick add this antique weapon to his pawn shop arsenal, or will the sale backfire?  Finally, the Pawn Stars get a chance to buy an incredibly rare 1954 Gretch Guitar previously owned by Robert Duvall.', '2009-07-26', 21, '/ng0AfPMXHEzBaNq3VgGmzI7oLqc.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
