INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'14D34C1603EA47818489B1E86E7FD13C', X'A0FA50759CE148C199950C0FD866E549', 14, 'Hemlines and Headlines', 'As Mauricio’s dating life starts to make headlines, Kyle struggles to picture what her own life will be like moving forward. Erika’s fabulous home remodel is finished, but will it meet her mother’s high standards? Garcelle and Dorit have a long-awaited one-on-one, where someone’s rose-tinted glasses may prevent them from seeing eye-to-eye. The press is out for Sutton’s first fashion show, but a runway faux pas could make all the wrong headlines.', '2025-03-04', 43, '/pLt1WCOhZKaavQEUnuntpu2d0Yp.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
