INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'14DA76F9D9CB4EAD878ABDC5A84CB94A', X'3269A890BBA94E6C9278F7EB38EB1720', 14, 'Spinning Things', 'A lot of things spin – bike wheels, footballs, hard disks in your computer, and even the Earth – they’re all twirling around. Spinning things have inertia, which means they keep spinning unless something slows them down. Bike tires keep spinning until you put on the brakes. A football spirals through the air until you catch it. The Earth keeps on spinning 24 hours a day, seven days a week. It’s been spinning for over four billion years.', '1995-09-15', 26, '/9vSWoxLYNCQrULCcYffgRR32VqZ.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'14DB8F04B9C3495AB65351427206A9AC', X'5A6D9A42165B4B5692730A06874DFE10', 13, 'Madeline at Cooking School', 'Madeline, the girls, and Pepito prepare a disastrous meal for Lord Cucuface, who immediately enrolls them for cooking lessons at the famed Cordon Bleu. After various mishaps, the children finally get the hang of French cuisine, but Madeline fails to receive her diploma because she has given her creation to the hungry. In the end, Miss Clavel helps Madeline realize that the satisfaction of helping someone is more rewarding than any blue ribbon could ever be.', '1993-10-24', 21, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
