INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'14F1D808F8A54DF2B7261808D7929BE1', X'98D80972E53A43DDA03A7703465E6F87', 15, 'It''s a Wonderful Pawn', 'Do time with the Pawn Stars when a Christmas dinner menu from Alcatraz Prison from 1912 comes into the shop. Will Rick sentence this piece to life in the pawn shop, or let it escape? Then, Rick and the Old Man check out a bomber jacket worn by a member of the famous WWII fighter squadron, The Hell Hawks. Can the guys make an offer, or is the asking price sky high? And later, Chumlee is put in charge of the annual Christmas party. Can Christmas be saved?', '2012-12-17', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
