INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'150454B883C74A82A5C934414FB9E172', X'5B5E8B2F0A854488B3DC3D8B794E6582', 3, 'The Not So Quiet Woman', 'Trust issues plague Vicki as she organizes her new office. Also, Peggy deals with her looming surgery; Tamra is thrust back into a past role; and Shannon confronts her weight gain as well as her nemesis, Kelly Dodd, who crashes dinner.', '2017-07-24', 44, '/1NOuxekzFTJNYXbZ5ERvX3ocuY6.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1506C8F46F1C41C38F5835AC96815C24', X'BC6D3E376E5E472D90AA4C6DF1F7DEF8', 2, 'Polygamists in a Shark Tank', 'Robyn and Meri hit a critical point in their relationship as the Browns pitched their latest business idea to investors.', '2014-06-15', 60, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'150B8BCA86AF44E796FF22B2EA23DE61', X'45E64A158FC04E4BA1CA9E3F42F3634D', 7, 'Digestion', 'Take time to digest this show.   They say that your food is no more inside you than a pencil is inside a donut, when it''s poked through   the hole. Instead of the food going in you, food goes through you. But, all the energy you get to live and   grow comes from your food. All the chemicals that become your body and brain as you get bigger, come   from your food. You get these vital chemicals through a process called ""digestion."" Your body breaks   food down and grabs all the nutrients you need from it. Then, your body gets rid of what''s left over.   Digestion starts in your mouth. You begin breaking food down by breaking it into pieces with your teeth   and jaw muscles. Your saliva (your spit) is full of chemicals that react with the chemicals in food and   make them break apart. Then you swallow. Your food goes down a tube (your esophagus) to your stomach,   where powerful hydrochloric acid breaks it down further into a mushy mash we call chime (kime). From   there, the chime goes in', '1993-10-22', 26, '/bSBfTnmfAcweSND7cLFDnfOZ8qy.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
