INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1538E28514F8448A9FCF5C333121EF9E', X'1996DDD820C94A3096BE2B87FAB8D17C', 24, 'Who''s Who (2)', 'Tina gets worried when Lana doesn''t show up at the tailor shop. She finds her locked in her garage. Lana believes that it''s just an obsessed fan. Tina and the team go to Lana''s house to find out who might be after her. They find out that she had four husbands. One of her husbands was the one who made her a star, but she divorced him. Another member of her family is her long lost daughter who''s holding a grudge against her.', '1993-03-14', NULL, '/ypCoXiFnPS2cagUXMmZ4frkLidC.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
