INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'15453AE701EE4842BB4FDF8B0C7CFE65', X'913796E9C0CE44DD98BCF6F520CB2444', 4, 'Owen', 'It''s easy to get flashbacks while watching Reading Rainbow. Now it''s LeVar''s turn, as he gets in touch with visions of "his boyhood." Matthew Broderick reads "Owen," about a little mouse who''s very attached to his security blanket and doesn''t want to give it up, even if it means he will be teased when he starts school.', '1995-10-11', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
