INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'158632A2A38E4FB6B4BAF8289A757D64', X'F0F8B366CB3340B3A50FA1CA7780916F', 12, 'The Honk of Honks', 'Cantus and the Minstrels are back and ready to perform the Song of Songs, but first Gobo must find the Honk of Honks. Along the way, he meets Doc face to face for the first time.', '1987-03-23', 24, '/9sckd0sta2T5otvfZ8m5NZsXG6J.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'158D98D0413E4879B2D8FE19BEF7C9E8', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 3, 'Chicken About Thunderstorms', 'It’s a windy, overcast day on Sesame Street. Elmo, Abby, Leela, and some chickens have just won the first game of the T-Ball season. They are celebrating with Chris when they hear a loud rumble of thunder and raindrops start falling. The chickens start to panic, and everyone gathers into Hooper’s Store where it’s safe. Elmo suggests that the chickens cover their eyes so they don’t get scared by the lightning, but that doesn’t stop them from hearing the thunder. Abby waves her wand and puts earmuffs on the chickens. This time, they don’t hear the thunder but they can still see the lightning! As they continue to panic, Leela suggests that they comfort the chickens by telling them that they are safe and explain what thunderstorms are. One chicken calms down, but the other three are still scared. To help the others feel better they try watching the storm like a fireworks show, counting in between the lightning and thunder to hear the storm moving away. They also make their own lighting and thunder musical performance inside Mr. Hooper’s store. It works! The remaining three chickens calm down just as the storm fades away. The sun comes out and everyone heads back outside to play T-Ball!', '2010-09-29', NULL, '/rCg3KbbbcNzV2bQSNcJ26GexGte.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'158DBE3EFC7B49BF96C4CB76DA4D9190', X'9193E795DA7C40ECB68FF63AA7D5174F', 162, 'Histories & Lore: Riverrun', 'Brynden Tully details the history of Riverrun, the ancestral castle of the House Tully , and the strengths that have allowed it to resist millennia of wars.', '2016-11-15', 4, '/8OYahNvrmYpNBcWJcAXF3p19g6Q.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'158EB893F31A449CA4CEC1C3B1F97501', X'F07B879456254682AAE1E56966B4C7A8', 21, 'It''s Mine', 'Julie and Kiki want to play with the same thing at the same time. With the help of Skye’s Uncle Victorio, a member of the Tribunal Council, they learn that the best way to solve a conflict is to make a rule that everyone agrees to follow. The kids brainstorm lots of ideas before they finally find a rule that everyone thinks will work. Sizzle and Nuzzle fight over napping spots. Ben and Jody do not appear in this episode.', '1996-02-12', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
