INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'15A8B4EA2B7B43929C2CD2F23ACB69D5', X'E38E9D8714324A1AA7D064A559BF7570', 9, 'Whistler''s Quarry', 'After escaping the Hunt for now the animals come across a large quarry. It is here that they meet Whistler, a great blue heron. A name he received because of the wind whistling through a bullet hole in his wing when he flies. Whistler saves Toad''s life when a carp fish catches Toad in it''s mouth, when Toad tries to compete against Whistler''s fishing. Whistler fetches the carp from the water and returns Toad to the other animals. Whistler then joins the animals on their journey.', '1993-02-28', 24, '/KoUuPvUca6nryjHY8TH9SQl4EI.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
