INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'15E459D757874523B340026E5C47F3B1', X'A0FA50759CE148C199950C0FD866E549', 17, 'A Caribbean Send Off', 'A catamaran ride ends in rough waters as Sutton finds herself searching for a buoy of support. Garcelle questions Kyle’s loyalty and Jennifer calls out a conspiracy, leaving Erika and Dorit seeing red. While Boz tries to get to the bottom of the group’s divide, the final dinner in Saint Lucia leads to some very ruffled feathers.', '2025-03-25', 55, '/b0DSs3Xs10TkQKc1QvpsSKoU03y.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'15E51093D0234D7EA1E261AD08E1965E', X'AD180412A5D64E4A8B49590334F2FC69', 6, 'Adventure For The Birds', 'The weasel family are still looking for another home away from White Deer Park. While the rest of the Farthing animals are still trying to find out where the missing animals are. It is up to Whistler to solve it. He follows the truck to a walled-in nature reserve. When Plucky finds him, he tells him that the place is a new sanctuary. Although it''s a nice place, many of the animals were separated from their families. Meanwhile Owl is still trying to escape the moth-eaten Rook, who says he loves her, but gets into trouble when she hides in a house.', '1995-11-02', 25, '/sE0ivMq2h3IvmttFeZia0FH5nbw.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
