INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'15EAC7B75AA2469D8227091D4BEF430B', X'6F731E6BD3C54DE684E17A19CB650E86', 43, 'Rocking Restorations', 'Get overhauled with the Pawn Stars and revisit some of the coolest restorations in the shop''s history: an extremely rare 17th-century samurai sword, a rugged and rickety 1973 Jeep, a vintage penny arcade Grip Tester, a rusty toy tricycle from the 1930s and a $100,000 helicopter rebuild that sends the Old Man soaring.', '2016-07-06', 21, '/Anpot4fixvRJiMb7rgvz7WxuQmR.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
