INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'160504655B4643929F10A9A542F7D535', X'4DA606E79D2346828BD5F535E1DA706F', 8, 'Franklin and the Babysitter', 'Granny was not able to babysit Franklin when his parents have to go out for the night. So Mrs. Muskrat was called in. Franklin was not pleased for he was looking forward to spending time with his Granny.', '1998-09-28', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'160C036CBEB241B9B4377F1D67B7E26F', X'3269A890BBA94E6C9278F7EB38EB1720', 18, 'Birds', 'Scientists believe that birds evolved from reptiles. Birds have backbones, and they lay eggs, but they’ve developed a unique feature that sets them apart from all other animals – feathers. Feathers are made of the same stuff human fingernails and hair are made from – a protein called keratin. Feathers, combined with lightweight bones, powerful wings and strong hearts let birds fly.', '1995-10-13', 26, '/lPITKhM9DcRlJRPvM5yxuVq1aqs.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
