INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'16149866D10347C8835EE8228CA8C65A', X'F29F456F8E3849AF88087943977100EC', 7, 'Bud''s Knotty Problem', 'Bud learns to tie his shoes after seeing a pair of boots that he wants.', '2016-10-13', 13, NULL, '2026-04-03T17:38:02Z', '2026-04-03T17:38:02Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
