INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1650FB0AE2324F8AA5228433BC7CDF5F', X'F593D90C533942F59C885BFD48D04075', 17, 'Party Animals', 'The farmer throws a fancy-dress house party for his birthday. When Bitzer loses all the invitations, however, Shaun saves the day again. Disguised in their own ingenious costumes, the sheep stand in as the guests and have a good old knees-up. But can they fool the farmer into believing he is surrounded by his friends?', '2010-02-14', NULL, '/kx6T5Rp51fTjan1GaHB031MTx4C.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1651C650AF9B44E4815EA54A6BF09699', X'18DA994319634E04A7A0AE63802BB1FA', 13, 'Heat Waves and Hot Flashes', 'In Jamaica, the heat gets to everyone; Shannon laughs it up in a salt scrub with Vicki and Kelly; Gina shares an emotional moment with the ladies; after some fun and games on bamboo rafts and rope swings, tension erupts between Shannon and Tamra.', '2018-10-15', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1653DB84E3894FA1BE541FB1123CD320', X'BFDF87FF01DD4B5494BD19B384F41BDB', 10, 'Shock and Roll', 'Tamra, Vicki, Heather and Kelly travel to Glamis to celebrate Eddie''s birthday. While the trip is supposed to be down and dirty fun, Tamra and Heather are still wary of Kelly''s filthy mouth. After a long RV ride down, the ladies finally get some fresh air and see what the motor sports mecca has to offer. The next day, the ladies set out to explore the dunes, leading to a ride they will never forget. Meanwhile back in Orange County, lives are forever changed as Meghan receives the results from her pregnancy test and Shannon''s holistic home has finally sold, leaving the Beador''s two weeks to move out.', '2016-09-05', 44, '/79d5GzIyt3fwLw9slSbhUvhf9fR.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
