INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1692518471E443F9A3EC808AA3DBCC29', X'05C0E384194C44179F62803EB615E409', 64, 'Learning about firefighters', 'Title number 0064. Opens with Mister Rogers arriving and then discusses firemen. Picture Picture shows what firemen do before they go to help people. Mr. McFeely helps Mr. Rogers put on a fireman''s outfit and pretend rescues a doll. He also sings "Sometimes I Don''t Understand". In Make-Believe, Handyman Negri and Daniel help Corny to process his sad and mad feelings, giving him hope from his distressed state. Handyman Negri gets right to work, rebuilding Corny''s factory. Lady Elaine is worried that everyone thinks she started the fire, but we learn that even she can be an imp, she never wants to hurt anyone. She and Mr. Negri find the most important pieces of the factory. They sing the "Sometimes People are Good" song.', '1968-05-16', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
