INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'16A98E53D856456DABAE72D89C93F6C4', X'2794739239BA45A6B67BFC609EB26E51', 4, 'Snap and Spot', 'Tom Thomas gets into a new birdwatching app which soon leads him into trouble when he gets stuck on a cliff. It is up to Pontypandy''s new pilot Krystyna to save the day!', '2022-11-04', 9, '/1MkcIQUV3MCJd4n1qdFP6Rnyb99.jpg', '2026-04-03T17:14:41Z', '2026-04-03T17:14:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'16B24001B2504DACB05CB017A3139902', X'2AFE02C5499E4D46AD930504A321941F', 1, 'Captured', 'Martin, son of Luke the Warrior, is captured by the evil Badrang. Seasons later, when Martin gets in a fight with Hisk, one of Badrang''s horde, he is tied on top of Marshank in a storm. Bandrang hopes the seagulls eat Martin in the morning. But in the middle of the night, Rose the mouse and her friend Grumm the mole hear Martin crying out in the storm; the reason she and Grumm go to Marshank is to rescue her brother, Brome, who was captured by Badrang. She calls out to Martin whether he has seen him. She tells Grumm that they should help the poor mouse. So in the morning they use slings to ward off the seagulls to hope to free Martin, somehow.....', '2001-12-03', NULL, '/xP9SPSZxrF2sUtqVeYLZEmHhu29.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
