INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'171B94CDE52E43E1A154739A9C7071B6', X'C4717644555D4DF1AEC0C095B101E7C0', 6, 'The Lotus Seed', 'Young people who emigrated to the United States from Asian countries are interviewed and discuss having to learn a new language and fitting in with other children their age while dealing with language and cultural barriers. Rona Figueroa reads the story of The Lotus Seed, about a woman who flees her native country during wartime and manages to save only one memento, a lotus seed given to her by her mother from the garden she tended for the emperor.', '1994-10-10', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1720BAD8073241B3B597A376606B94AD', X'51F03551BA41409D85F4E51BDDFDF82E', 7, 'Kelly vs. Bethenny', 'In one corner: Kelly. In the other: Bethenny. The two housewives square off in a diva duel during a downtown bar meeting. In other unfolding dramas, all six wives assemble at a magazine party, where Kelly reflects on her fight with Bethenny. And there''s back-and-forth tension over an upcoming tennis match.', '2009-03-31', 60, '/aYQmZU7EcWPKONrnuhEjoCv1C2A.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
