INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'174F95929E79466B8C52E7ABA50AFEB8', X'4900FC8D5E7E408E972ECE9269D203B3', 4, 'Judge & Jury', 'The ladies gather to celebrate Shane finally passing the California bar. Despite making amends with Gina, Shannon runs into another roadblock with Emily. Noella’s situation worsens as she struggles to find answers about her husband. Heather learns about Dr. Jen’s issues with Noella and soon finds herself in Noella’s crosshairs.', '2021-12-22', 44, '/ig8kn980co6m8o4Ks52h3XY3NkC.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1751DC6BA2704524BD01BD85DB88299E', X'EDC63A592FD4442A9343F2872D776BDC', 1, 'Arthur''s Perfect Christmas', 'Plans are under way in Elwood City for the best holidays ever! Arthur, D.W., their friends and family make preparations for perfect gifts, perfect parties, and perfect family traditions for Christmas, Hanukkah and Kwanzaa. But, just as in real life, perfection cannot last and things begin to fall apart. Arthur learns that the joy in Christmas isn''t found in an artificial vision of the perfect holiday season, but in the wonderfully messy, imperfect world he lives in.', '2000-11-23', 55, '/76AQgJrxXtqUAGtgPhpgXJ4qIm1.jpg', '2026-04-03T17:37:54Z', '2026-04-03T17:37:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
