INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'176147F8F99043ECB22B8AE69F21323B', X'DB555B9887D64CD2B7B4973F9206CB1E', 7, 'Dance Like No One Is Watching', 'Kelly invests in a new business and goes to a Wellness Expo to practice her pitch. While Gina meets with a new lawyer about her DUI, Braunwyn and Kelly head to Las Vegas to support Emily at her dance performance. Then, the ladies travel to a wellness resort in Miraval, Arizona. At a sound bath, Kelly bonks Shannon over the head which leads to an unexpected trip to Urgent Care.', '2019-09-17', 44, '/ufcfb5arNJBOjX6OY4rmivK6fUC.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
