INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1772FA87906E4438A4FF47D4DB142246', X'04207E76D8554F29A0661732FEEA34B5', 6, 'It''s Not Me, It''s You', 'After the outburst at The Brownstone, a battle breaks out on Facebook when Danielle accuses Jacqueline''s teenage daughter of threatening her life. Wanting to put an end to the drama, Jacqueline and Teresa confront Ashley about the alleged attacks. Dina decides to follow her energist''s advice and sets up a face-to-face meeting with Danielle to officially cut her out of her life.', '2010-06-07', 43, '/wZD5MiWJaBOSIB81TxADTWbKp6g.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
