INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1783758401A84EB5890233F679F2C647', X'53F9624FFCF84F7782F6D2EB3F5376EE', 5, 'The Year of Release', 'Meri asks the church for a release from her marriage to Kody. Gabe opens up to Janelle about his relationship with his father. Christine is excited for her second date with David. Mykelti reveals she ate her placenta. Robyn is left in tears on Christmas.', '2024-10-13', NULL, '/yYDN2Zh1gRxRwBMq6C0AExs3SVf.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
