INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'179C1B45F7FF4D48BB5EE4B08D6EBE4F', X'4F18AC4C8757456CA49A224F00E6A9F7', 7, 'Annual Triangle Toss', 'Baby Bear welcomes the viewer to Sesame Street, when Telly runs into him, and excitedly tells him (and the viewer) that today is the Triangle Lovers Club''s annual Triangle Toss (similar to ring toss). He displays his lucky triangle vest, which is what he claims helps him win every year. When he tries it on, however, he notices it''s smaller than it was last year. Baby Bear and Leela help him put it on Telly, and they notice it''s such a tight squeeze that he can''t move his arms, but that doesn''t worry him.', '2008-08-20', NULL, '/AlbpJCSi19nrGxlesW6ssK9qJOC.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
