INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'17D6007B5ECE440898F217C39FE9EE53', X'150D1480F3F143F99A22D2527756FBA2', 11, 'No Business Like Shade Business', 'Gizelle hits some speed bumps trying to teach her daughter Grace to drive; Ashley''s family isn''t happy with Michael''s proposed venture into the movie business; Karen and Wendy work on putting together their candle lines.', '2021-09-19', 42, '/rRZes20f0fBCQ81intj82Xd6OMt.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'17D9F76C108E42C3B8F6299D371F0752', X'1A534647384B4C00BB6CA3371AD962EB', 41, 'On the Road', 'Hit the road with the Pawn Stars to revisit the best items ever seen outside of the shop: Rick''s international trip to London where he finds some rare American maps, a vintage piano used by the Rat Pack found within the home of eccentric collector Lonnie Hammergen, an exclusive tour of an L-39 Soviet Albatros Fighter Jet, and an ancient Samurai helmet that causes Rick to detour while traveling to the Sturgis Motorcycle Rally.', '2015-08-10', 21, '/btwPCzZJeq9a66ZbF2AaL8stJ30.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'17DBDBD3E2634EE8871744FAFDD486DB', X'262E8E7CFA784578A216ADD6F184C4D2', 21, 'Sister Wives on the Strip', 'The Sister Wives get makeovers and head to the strip for a night on the town while Kody stays home to babysit all the kids. How will they react when they come face to face with all the "adult" entertainment Vegas has to offer?', '2011-11-20', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'17E1A1603B5545A580FE56C101F2B241', X'F4D370CA3C3940A8911DE2B5E7C6B0D7', 3, 'The Castle', 'While Little Bear and Duck are sorting through their farm set they find an old piece of castle wall. This gives them an idea and with the help of the other toys they create a new castle complete with a moat and drawbridge. Old Bear explains what sort of games you can play with a castle and they find a clever way to divide themselves into teams to play. With Little Bear firing paper cannon balls from the battlements, it looks as though it will be hard for Bramwell’s team to invade the castle but he has a very clever plan.', '1996-09-18', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'17E2F70C20BB4D07990FB29819E67FD4', X'BBFEE3B49C9548A6BEAA791FA08B1F43', 15, 'Episode 15', 'They said it could not be done! For 72 miles through 12 tunnels and over 17 viaducts, the railway line from Settle to Carlisle climbs over some of the most spectacular countryside in Britain. This famous track was one of the last important lines to be laid - it was opened to traffic in 1876. Simon and Goldie follow the tracks of the pioneers who created one of the engineering master-pieces of the Victorian age.', '1983-10-31', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
