INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'17F50718CD3442ECA1714E766C709AD3', X'136B81D3964D4B8FA21492F00D96D6B9', 94, 'Uncle Wally visits', 'Uncle Wally, Big Bird''s visiting uncle, spends the day exploring Sesame Street alongside his excited nephew. Big Bird proudly shows Uncle Wally all his favorite places and warmly introduces him to his many friends. Uncle Wally entertains everyone with funny stories and they enjoy a wonderful day together.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'17FA91C6211F4800A9EFB1C621E9D957', X'D5351B608A0C482AA6DD4FB860CFE143', 1, 'Episode 1391', 'Mister Rogers plays a few rounds of hide and seek with viewers before Audrey Roth invites him to see her new mobile home which will serve as both her home and office. With Frisbees scattered around her desk at the office, Barbara Russell is working on a new promotion for Audrey Cleans Everything: "It''s as easy to find our new location as it is to throw a Frisbee." Audrey shows Mister Rogers around her new home.
