INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'180971A7EBF142BB8D383390B57BA49D', X'852A07B0F228419791477AEED79390BF', 8, 'A Harlem Night', 'Eboni hosts the ladies for an educational night in Harlem where Ramona introduces the group to her friend Bershan. Luann bonds with her daughter over their sobriety while Leah stresses over her daughter’s upcoming high school experience. And, over cocktails at Ramona''s apartment, Eboni and Ramona''s friendship gets put to the test.', '2021-06-29', 60, '/3y1Ah3rXGqNdrL3khD7ZJ9147xn.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
