INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1813ACC99834456DB05083BC426AA514', X'48A6D3B8384241DAAAECB49A9B65F17F', 13, 'Kipper''s Circus', 'Kipper and Tiger play circus and can do pretty much everything perceiving to it except doing a handstand. And Pig and Arnold are the exact opposite!', '1998-12-17', 30, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'181524DA9EC2416BB235E963A996E4DE', X'B054AFF3548C4F56B372B1EA26613ABB', 3, 'Mister Rogers Talks About FRIENDS', 'Mister Rogers opens with a visit to the Neighborhood resturaunt where Audrey Roth happily shows him to his seat. After talking about table settings and other common things found at a resturaunt, Mister Rogers orders a sandwich with cheese, lettuce, and tomato on whole wheat. He gladly accepts an offer to visit the resturaunt''s kitchen and watch as the chef prepares his sandwich.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'181AA43611F94246A220533A705747D4', X'65F5ABC80C59497B86E58C6165EE480C', 4, 'God Save the Queen, Bitch', 'The Beaver Creek trip continues, as Kameron and Stephanie feud over a miscommunication regarding Brandi''s adopted baby. Cary tries to calm Kameron down but it''s no use. Brandi pits D''Andra against LeeAnne in a pageant for the title of "Queen."', '2018-09-05', NULL, '/pStMyTRGrPqcXM3UMybb6poFGbO.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
