INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1823BC1DB05346EDABB88F5AEDE76BC6', X'151E88A195764BD1B84AC4D64C1C9FE8', 15, 'Disco Inferno', 'As Dorit’s charity dinner continues, Crystal addresses troubling rumors she’s been hearing. Sutton objects to a hurtful label and drops a bombshell in return. The ladies boogie down at Lisa’s disco event where Kathy keeps putting her foot in her mouth. Kyle tries to get Erika and Sutton to face the music. Garcelle is called out for pushing a narrative but stands her ground and then some.', '2022-08-17', NULL, '/wVlLG66Yf9WyTQ6vHtWVtszQIaX.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1824226BD5B249DCB21A6F01FEBA39AF', X'4060AD7F4B8F43938EB166A150B928B6', 1, 'Ramp Racers', 'Elmo and Rosita want to race their ping-pong balls, but the only ramp on Sesame Street is being used. This is a problem! They wonder if they can make another ramp. What if they use cardboard? Let’s try! It works. With Julia’s help, Elmo and Rosita didn’t give up, and they built two long ramps. They all get a chance to race their ping-pong balls – Julia, too!', '2020-11-12', 26, '/sMhmxkJZwQHxdTHqdPQg7u6AQ06.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1825BD09FF0844CE8FF7D7CCD07D9556', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 90, 'Episode 2055', 'Telly wasn''t ready for the viewer''s arrival and wanted to surprise them with a poem, so he frantically asks Bob for a word that rhymes with "street." Luis tries finishing a birthday card to his cousin while hiding from Elmo, who always wants to play. Forgetful Jones greets Telly as "Silly Monster," prompting Telly to correct him, and Forgetful apologizes for forgetting his real name.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'18298CB84F2C4D02B194E25511C8C1B2', X'C9ADC698BE924DD794ADD8F6759361CA', 41, 'Episode 41', 'Rogers hears that Mrs. McFeely is ill. In the Neighborhood of Make-Believe, Queen Sara begins to fall ill.', '1973-04-16', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'182A4584946C4C15AA2DA0931F156767', X'AB509C47EC644FB3856003873DD0C37E', 23, 'The Face Painter', 'Elaine''s boyfriend is too zealous a hockey fan; George ventures saying "I love you"; Kramer has an altercation with a chimp.', '1995-05-11', 22, '/xYpbmxYjGh16DRYkYuzNHqt1Qks.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'182B3D87FD524061B7E516761CEBFDBB', X'E3A2866991B545F7BB735006ACC084E8', 23, 'Washday', 'The sheep use the farmer''s clotheshorse as a merry-go-round - the garments get dirty and have to be washed before the farmer returns.', '2007-09-04', 7, '/nycp3c730k7gmaTZ7NnBKkuy0i.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'182E3CE0F4124C92916B78AD0D97B41F', X'136B81D3964D4B8FA21492F00D96D6B9', 59, 'Bob reads to the Two-Headed Monster', 'Bob reads stories to the Two-Headed Monster, whose two heads constantly disagree about plot direction, demonstrating different perspectives and compromise.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'18305EF585F44C7488E191B2DC2BC309', X'BB5A884361814A6DBFDF33EF2C6BE7B8', 8, 'A Mad Tea Party', 'Kandi and Todd face criticism from the Old Lady Gang as they search for a new general manager who can help turn business around at the restaurant. Meanwhile, Cynthia and Marlo come together to serve tea - literally - to NeNe and Porsha with the hopes of bringing the two former friends back together. Kenya and Shereé make an unlikely duo as they join forces to produce a PSA against domestic violence, but an unexpected setback arises the day of the shoot and nearly shuts production down.', '2018-01-07', 43, '/7pPxFV30yrRBkTmUA2z2h0S5BM0.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1830DD08E49B4444977916F191C4A7C4', X'050D8AE16CC14018933DB3C3D13DE856', 65, 'Episode 65', 'There''s more to driving a limousine than meets the eye, as Janet discovers when she trains as a chauffeuse.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'18366BDE52CB42FA82DB1BC3C5771CD6', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 61, 'Playing with Barkley', 'Nobel Price yells out on the street to everyone about his new invention. Maria and Luis come out of the Fix-It Shop to see his new alphabet, which he calls the "Price-phabet." He explains the only difference it has from the regular alphabet, is that the letter Z is replaced with a little smiley Elmo brings Barkley over to the yard to play some Hide and Seek, and closes his eyes and counts to ten.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'183F81FB870143C19234A143BD3F23EA', X'02849455D14B476B9603EEF5FB5D2AB3', 15, 'Turm-Oil in France', 'While the ladies enjoy a fabulous day on the French Riviera, Candiace begins feeling detached from the group. After noticing Karen without her wedding ring, suspicion mounts about the state of her marriage. And Monique and Charisse’s friendship is officially put to the test, leading to a revelation that leaves everyone stunned.', '2018-07-15', 42, '/qQ8KX15XxrO8glg6aZshQOP4xqK.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
