INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'184D1790F05D43C38A8A236C279CDB6D', X'D123FD65EFB74EBBA23E190C447791CF', 13, 'Reunion Part 1', 'The ladies reunite to discuss what happened during and after the season; Larsa gets grilled about her looks and OnlyFans; Julia reveals shocking details surrounding the death of her son; Nicole, Marysol and Alexia rehash their Hamptons drama.', '2022-03-03', 44, '/52GzLkH8TBtpCpB0T5tHwkIJHD.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1854E976D0DC481F8931CDB4A93A52F4', X'ECB64EF34F8045A7B4A9C04434B02E35', 7, 'Anytime, Any Mace', 'Prepare for battle with the Pawn Stars as Rick checks out a medieval mace. Will it be a fair fight for this primitive weapon or is he in for a low blow? Then, Rick and the Old Man check out a set of cap guns from the 1950s. Will nostalgia force them to pull the trigger? And later, the Old Man sends Corey and Chum on a simple errand that turns into a daylong adventure. Will they make it back in one piece?', '2014-01-23', 21, '/Ltdxn8pUaXA2x1gzqkMSLIVcmI.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
