INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'186669A5CC3747FCAD7FFC6AA8137A5E', X'7C542833ED0A42729C53E822408AB434', 24, 'The Taste of Pontypandy', 'James has the idea of using the horse and cart to deliver his team''s forgotten cherry pop to a tasting competition. But when the pop gets shaken up and starts to pop open, scaring the horse, they are soon on a runaway horse.', '2024-11-08', 10, '/sOtKDcEmRvjZoKEEIQLYknkQmDv.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
