INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1873C1233A6146F59665B79B331EF58E', X'196E5A10AC254D588416575D3A71FCEF', 3, 'Where the Pawn Stars Roam', 'When Rick reels in an antique glass fishing buoy made in Japan, he hopes the seller''s price floats his boat. Meanwhile, Chum checks out a rare dinosaur fossil. Can he dig up a good price, or will the seller have a bone to pick with him? Then, a customer brings in an original poster for the film "Where the Buffalo Roam." Will Rick draw up a deal, or will he want it gonzo? And later, Rick and Corey head to the range to test out a 1580 German "puffer" pistol. Is it a wheely good deal, or a misfire?', '2024-07-24', 42, '/r58n4mWHraADiujQWPxZs8Do6qr.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
