INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'18CF87F8B87A4297853E8A0E5EC7BE75', X'DE052E8E7DBD454AA6D8B9AFBA6E9BFA', 5, 'A Safe Place', 'A safe place must be found for a valuable Womble history book.', '1973-02-12', NULL, '/gLDiWI2mTgl6iFyiDnueXnmBCcx.jpg', '2026-04-03T17:23:19Z', '2026-04-03T17:23:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'18CFED0A8A7C41B2A523BB60B412002B', X'65F5ABC80C59497B86E58C6165EE480C', 3, 'The Badger of Beaver Creek', 'Kameron invites everyone to fly to Colorado on the Wescott''s private jet to stay at their luxury home. D''Andra and Brandi put their squabble on ice for the weekend. Kameron shames Stephanie for the white lies she told at Brandi''s baby reveal.', '2018-08-29', NULL, '/uSwvf6IQ6qDs8nuERxo1F1T8zOd.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
