INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'18DC8B6687B64F5487A256E7729E7A4B', X'5213521551604D429D0FDB242B1ABCAA', 5, 'Archibald Frisby', 'LeVar gets in his share of scientific method while at an amusement park. He answers questions by observing and using trial and error. Along the way, we learn how different kinds of scientists find answers to their own questions. Arnold Stang reads the featured tale about a young boy, obsessed with science and mathematics, whose mother sends him to summer camp to help him improve his social skills, but his scientific knowledge helps him learn even more, and makes him into a camp hero when he figures out how to win the softball game by calculating trajectories.', '1995-10-06', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'18E60EF5F08E44248DBE8A5A09B8CD11', X'18DA994319634E04A7A0AE63802BB1FA', 15, 'The Day After', 'Shannon continues to isolate herself; the women climb a gorgeous waterfall; Vicki coaxes Shannon to rejoin the group for a beachside dinner, where Shannon makes amends with only a few of the women; an unexpected phone call makes Emily emotional.', '2018-10-29', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'18E7060D9E324126BA2A462EFBDE3E2E', X'D920EBAEF00A4E25ABFE40492C74DED6', 16, 'Across the Pawn''d', 'Rick shoots over to England for an explosive chance to test out antique weapons. Meanwhile, back at the shop, a seller brings in something that offers the Gold & Silver some “Home Improvement.” Can Chum hammer out a deal, or will he need more power? Then, it’s all eyes on Corey when an item that inspired a classic movie rifles into the shop. Can Big Hoss trigger a deal’ Finally, Rick gets a Prime look at a classic car that belonged to Winston Churchill. Will he win the war of negotiation’', '2020-04-03', 42, '/lCDjiqQ7jOepSIiqkdbQuhpKWki.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
