INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'18FC99DEB0DF4DF7A91C46A821463F60', X'DE8EC76916BB436BBE43AEDC7E18A7D7', 35, 'Let''s Go Camping', 'Chris and Elmo are excited to be camping in the woods! All kinds of animals join Chris and Elmo for the camp out. After Chris finds the right kind of food for each animal, they all eat dinner together. Elmo and Chris both agree they should have a sleepover like this every night! Season finale.', '2020-07-11', NULL, '/3DduhyrWus8EdkNCkB4rsNhSCbZ.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
