INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'191F93B7B2CE43A8AE861AF51F3D3DFF', X'EFD2082E32F54EDD9A7BA4326D6992C9', 28, 'How to Build a Dinosaur', 'Grover, Elmo, and Rosita are imagining that they are paleontologists, a scientist who digs through dirt and stones to find fossils.', '2019-05-25', NULL, '/a31ZrAhwEkFdIcLcCublhkAS90D.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1923244394B940B88D6300C24E0B6921', X'4D2CAC0F38FD438B8AFAACF43952E535', 245, 'Episode 245', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. Including Giant Modelling, an outsize dolls'' house kit. Little Watha: Part 4: The Rain by Oliver Postgate. The wicked Medicine Man banishes Little Watha from the Popangwawa Tribe, but the Eagle and the Beaver help their Brother. Told by Peter Hawkins and Patricia Hayes.', '1963-09-02', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'19240B637D554CCFA4930E1BDFE431F8', X'8C0F12E153794A27ACA2B69401A33B0F', 13, 'Arthur''s TV-Free Week', 'Everyone has all pledged not to watch TV for one whole week.', '1997-10-28', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'192939D9837F4A77BD0D45D054AF4ABC', X'4D2CAC0F38FD438B8AFAACF43952E535', 333, 'Episode 333', 'Valerie Singleton thrives on variety, which she finds in abundance on Blue Peter. Her assignments have taken her on whirlwind trips, from a day in Africa to a near-trip to Bangkok, and a quick jaunt to Boulogne, where she was described as "une jeune et jolie personne de 27 ans." "I can''t bear things to be the same every day," she explains, preferring the unexpectedness of the job to her previous role as an announcer. Since joining the show in September 1962, Valerie has become a favorite among children. She has found that her wide interests—including riding, yachting, and skiing—often feature in her reports. She also enjoys crafts and has a great fondness for animals, especially Jason and Petra. A former actress, Valerie attended RADA before moving into TV plays and commercials. The opportunity to become an announcer presented a difficult choice, and she admits she "hankered after" acting for a long time. However, she clearly loves Blue Peter, and its audience loves her in return.', '1965-02-04', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'193A08EBEDFA47F5A12613FD5D0A098A', X'8A5892F6CCB74F029A5A85B134B5F0CF', 3, 'Bluebell', 'A good donkey will always do what she is told, even though she has to run rather a long way to do it; luckily there are wheels for the return journey.', '1976-02-19', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'193E9E0F662D4769AAFBBEA8D252335D', X'E48599F866FF4C0F927465B9AE1CDA9E', 77, 'Episode 77', 'Narrow Escapes  JOHN, PETER and LESLEY relive some of their most heart-stopping moments during the past ten years. Hold your breath with them as John falls five miles, Lesley escapes death by inches and Peter crashes at 60 mph straight through a furniture van!', '1977-06-16', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'19487868B3D742CF81FD966504FB953A', X'7DA1B69304D14168A0A09715407C04C6', 2, 'Sam''s Birthday', 'A broken birthday present for Sam goes haywire after James attempts to fix it.', '2016-05-07', 10, '/qg2I6tODRHFbvDg6T3f6eNUQUDz.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1949DCC0736D428391E352B5D8FD22CB', X'DBD3583FE9B246D1A37E309EB666E233', 4, 'Jewels Be Dangled', 'Phaedra does the proper Southern thing and apologizes to Kim for her husband''s behavior at Kim''s baby shower. Shereé takes Phaedra along to see her Chateau Shereé construction site, only to find no progress has been made. Kandi plans her 35th birthday bash despite a case of the biological clock blues. The party heats up when Phaedra presents a “Ridickulous” surprise that neither Kandi – nor her mom – will ever forget. Meanwhile, Cynthia’s attempt at making peace between her husband and sister backfires, leaving her torn between her new family and her old one. Kim tries to figure out how she will handle the birth of her new son.', '2011-11-27', 43, '/gxnua3fWBy3JtGKw4Z95QWLDrH6.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
