INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'195E1A0DFAFF4C4ABDEC610D19E722E2', X'98D80972E53A43DDA03A7703465E6F87', 31, 'Book ''Em Rick', 'Read up on the Pawn Stars when one of the first books ever printed comes in the shop. An incunable from the 15th century, will the guys judge this worm-eaten work by its cover? Then, Corey and the Old Man hear the sweet sound of music when a sitar strums by the shop. An Indian instrument popularized by the Beatles, can it score a big hit? And later, the guys jump through flaming hoops for an ID card belonging to the late stuntman Evel Kneivel.', '2013-03-04', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
