INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1981CE9F69F54F9FAF86FD415C70C9C8', X'54C290142DBD49FFA23FCF4C546E0B3A', 8, 'Unforgivable Debt', 'Ramona reveals Sonja''s financial secrets. Elsewhere, Kristen visits a new modeling agent; Sonja is stood up by her 23-year-old flame; and the heat is on at a spa when Kristen and Ramona have a dispute.', '2014-04-29', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
