INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1A19FDEB95894146AEF505192A2942AA', X'1BB5392776F64ED39C415414AD0865CE', 11, 'Battle', 'Underground in the kingdom of Malkariss, Mattimeo and friends see the slaves building a huge city. Brave Tess refuses to be a slave and Mattimeo is brutally attacked when he tries to save her from punishment. The slaves are thrown into a dark cell. Matthias unravels the last secret of the Loamhedge parchment and and finds a way into Malkariss - the old rabbit''s amulet is the key to enter!
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1A1B72B486B84029B9E30F512391DE2F', X'42E591E22A884434AE9F3D4B1D685613', 18, 'Corey''s Big Splurge', 'Who you gonna call? The Pawn Stars! The guys remember the 80''s as they check out a replica of the proton pack from "Ghostbusters." Will they give this item a ghost of a chance? Then, a seller brings in an original work by the street artist Banksy. Can Chumlee convince the Old Man that street art is valuable? And later, Rick and Corey take their 1951 "Steve McQueen" Chevy to an auction. But when Corey sees a classic Plymouth Roadrunner, will he spend a king''s ransom to buy his dream car?', '2013-08-08', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
