INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1A5C8B77019B47868E0B1B3B90BCE75E', X'A8DB07E5FBA349A9BD12947C111B39BE', 7, 'Airing Your Dirty Laundry', 'Sonja is caught off guard by Bethenny''s response to her new business. Also, LuAnn moves in with Sonja; Jules scouts for a new nanny; and Dorinda hosts a party, leading to tension, an argument and a sprawling sidewalk screaming match.', '2016-05-18', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
