INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1A64639E32734F5F892482AF75330298', X'6F731E6BD3C54DE684E17A19CB650E86', 42, 'Napoleon Complex', 'Build an empire with the Pawn Stars when a letter signed by Napoleon marches into the shop. Will Rick make it a short sale or will his offer be defeated? Next, a surreal Pedro Friedeberg figure creeps its way in. Will Rick sculpt a deal or will the design disappoint? Then, the guys rock out when a 1960s Monkees talking puppet takes the stage. Will Corey become a daydream believer or will the deal get cancelled? And later, Rick gets schooled when some original "Dick & Jane" illustrations roll in. Will he author a deal or will it just be child''s play?', '2016-07-06', 21, '/eqRWkQUqAlbCZdVzaZK31VIZtLZ.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1A6488CE74A44336BA8789FCE8785584', X'27A5A980EC0D4637B5BADF8324A6405A', 11, 'A Christmas Gift', 'On a tipsy whim - and against Mike''s wishes - Frankie decides to throw a Christmas Eve party at the house; Mike buys Frankie a much needed new dishwasher for Christmas, but has a hard time keeping it a secret when she begs him to replace the old one before the party; Sue calls on Reverend TimTom to explain the meaning of Christmas to Brick when he reads the Bible and begins to question it; and Axl gets annoyed with Bob when he tries too hard to be cool in order to befriend him while working together on a Christmas tree lot.', '2011-12-07', 22, '/cQhilactHaPXYwRlR8S1bZ7JLBh.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1A69AC755B584A6F873B7634B0BFD376', X'0BBD380C5CB846A68838B5D60223C073', 20, 'Kaye Ballard', 'Tired of the "embarrassingly square" theme song, bass player Floyd Pepper informs Kermit that he and the rest of the orchestra pit (except Rowlf) are quitting. Kermit says their conductor Nigel will write a new theme, but Floyd refuses: "He wrote the first one, man." Floyd performs his idea for a new theme, a dreadful Zappa-esque piece called "Fugue for Frog." Kermit won''t use it and refuses that Floyd submits to Kaye Ballard a petition about the theme song, so the band leaves. The closing theme is performed solo by Rowlf on the piano.', '1977-01-23', 26, '/ooRxGlbMobmnduhdTmWwAlLtG0m.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
