INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1A98D7C324AE4414A1CAD9847FA3559F', X'FC120008C5C447D7A3A991A401394C41', 22, 'Visit the Dentist', 'Sister Bear has a loose tooth. Brother scares Sister by telling her that the dentist will pull out her tooth with a pair of "yankers". Not only that, Brother has a toothache from eating too much candy. They both hide their dental problems until Mama finds out and takes them to the dentist. Brother gets a cavity filled and Sister''s tooth falls out at the dentist''s office.', '2003-02-04', NULL, '/5Cg7MN8STW5DfT0gxsLPtV1hibK.jpg', '2026-04-03T17:40:21Z', '2026-04-03T17:40:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1AA0F3926969449C9A92D3439CE50FD5', X'F07B879456254682AAE1E56966B4C7A8', 19, 'I Scream, You Scream', 'Jody and the kids learn that dealing with a difficult situation is easier when you’re able to talk about your feelings, especially with issues like divorce and remarriage. Sizzle and Nuzzle think of ways to organize the basement. Julie and Ben do not appear in this episode.', '1996-02-08', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1AA7B452384C4A85999A16A8CF98888A', X'BA99B779CADA43A7902A2ADB472C2E30', 5, 'Episode 5', 'The family have taken up refuge in an old boot that they have found in the forest. This is the base camp for Pod''s excursions out to try and find another family of borrowers, one that is supposed to live in a badger''s nest somewhere nearby. This episode introduces a new borrower, a young boy about Arrietty''s age that lives in the forest.', '1992-12-06', 30, NULL, '2026-04-03T17:17:47Z', '2026-04-03T17:17:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
