INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1AAE80D671C4498281DDF6F648CF851B', X'6F731E6BD3C54DE684E17A19CB650E86', 25, 'Legends of Rock', 'Go wild with the Pawn Stars when a hand-painted, signed guitar from Def Leppard''s Phil Collen rocks into the shop. Will Rick "Pour Some Sugar" on his offer or will he have to call in a special guest? Then, a pair of sneakers signed by NBA legend LeBron James hit the floor. Will it be an air-ball or a three-pointer for Chum? Next, Rick finds the time to check out a 19th century carriage clock. Will he get wound up over this French classic or will it turn into a ticking time bomb? And later, an original Mogen David wine ad displays itself. Will Rick like what he sees or end up with a bad taste in his mouth?', '2016-02-03', 21, '/lIV6Wr73JxnkkQL8Ld6otbe9ddA.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
