INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1ADB3FDA949746278211C16F646B3209', X'CEFD1496B6494C62AEF935A22558AC08', 2, 'Haute Dogs of Dallas', 'Stephanie makes a play to put a crack in Brandi’s newfound friendship with LeeAnne, but it backfires turning Cary and LeeAnne against her. Meanwhile, Travis drops millions on a house in the city, but Stephanie is the last to know. D’Andra makes moves towards taking over her mother’s cosmetics business, but it won’t be easy. And fur flies when Brandi and Stephanie meet again at the Howl-O-Ween dog costume contest.', '2017-08-21', 60, '/joyaVtX1vSEiL6YeG94ZkondnZz.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
