INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1B014BCA785D477AB8BA7A71233F39F6', X'5A771F52FE964EA2B567A8DDE899059E', 16, 'Some Serious Coinage', 'The first American coin ever made has Rick thinking this is a sale that was mint to be - but it''ll cost him a serious chunk of change. Corey and Chum see a future for an antique "Jetsons" cartoon lunchbox that zooms across their counter. Can they draw on their negotiating skills and make a deal? A hood ornament from an Austrian automaker pulls into the shop, but will it drive Rick to make an offer? Later, Rick gets some self-help, medieval style, from an ancient Latin book.', '2018-01-29', 21, '/cZiifErO0Go7bvUNtgRt3RadhHs.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
