INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1B043F81CE9B422486B4D18EC899DF5E', X'68138DE20900460AB58E480688F1E081', 21, 'Dance Fever!', 'Bear is really excited about building the new birdhouse kit that he got in the mail, but Pip & PopTM and TutterTM are more excited about making something out of the box it came in. After gladly surrendering the box to his friends, Bear sets out it build the birdhouse on his back stoop, only to find that Jacques, an industrious local beaver, has bigger plans for Bear''s seemingly simple subject.', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
