INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1B103BB033734602933C5EA5130652E2', X'7BC54DF3F32A454EAEF6A9436C35D53B', 20, 'Episode 20', 'Rogers has a recent chest x-ray, and explains what having an x-ray taken is about. In the Neighborhood of Make-Believe, Lady Elaine warns her neighbors that King Friday might be starting a wild animal zoo. That, she feels, is his big secret, although it isn''t.', '1970-02-27', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1B10C186EB4849D5A1B0F23A638E7463', X'18DA994319634E04A7A0AE63802BB1FA', 2, 'One Apology, Another Betrayal', 'In the wake of Vicki repairing her friendship with Tamra, Vicki must face one last hurdle and apologize to Eddie. Tamra teaches an exercise class and introduces her new friend Gina, a recent transplant from Long Island, to the ladies. Emily and husband Shane celebrate their ninth anniversary. Shannon travels for the first time as a single mom to Mexico with her daughters. Kelly is stunned to learn that Vicki and Steve set up her ex-husband Michael and confronts Vicki over the betrayal.', '2018-07-23', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
