INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1B2480BC91B445239877638A5AF02C9F', X'879892836FEA40D78D9122C4947DB105', 15, 'Two Moms, a Daughter, a Baby', 'Kody and Robyn are struggling with the bank as the mortgage process is not designed for plural marriage. Then in North Carolina, Maddie’s water breaks – at the mall. Evie K is born, but when she has problems breathing, an ambulance is called.', '2020-04-12', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1B2CC2ED27A245668EBD997CD292A4FD', X'1CAFB2C3BBCB4172B02D441A5AAA155F', 9, 'You and I Together: A Visit with a Teen and his Service Dog', 'Rogers talks about how a variety of sticks is similar to a group of words: the more you have, the better you can work with them. Mr. McFeely shows a video of a service dog, named C.D., aiding a handicapped child. In the Neighborhood of Make-Believe, Dr. Bill Platypus tries to ensure Lady Elaine that the gorilla, called Kevin Wendell, is tame. Maggie Stewart Comes And Brings A Videotape On Mr Rogers Gets A Haircut', '1998-08-21', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1B311C0FAA6E4A43A547A3FE7B91FD21', X'E2AA315868E5494F951A498CA0518DBB', 15, 'The Piano', 'The Farmer plays the piano and tortures everyone with his musical inability.', '2012-11-30', 7, '/1MsopwfzPc85ZEHamVjNb7sAKYI.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1B328DF5C5BC499D991067E7D57D1D8A', X'F4938E7D11A84756B40598BEDD7C9B28', 6, 'Pat''s Tractor Express', 'Pat has to deliver some eggs and a registered letter to some campers. The letter is too valuble to leave and the campers are at the waterfall. Pat''s van can''t travel the bumpy road so Miss Hubbard borrows a tractor and takes him on a rather bumpy ride to the waterfall. When Pat returns to his van, he sees that a hen has got in and laid an egg!', '1981-10-21', 14, '/8JVWL1UMkoD2QkMqI0DdNjYqrOO.jpg', '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1B32E32768B2478D8188F72D155F2D93', X'DA06465B91544FEBA455374DF7DAB02F', 24, 'Bob''s Deaf Niece (4106)', 'Rosita and Telly want to play a game of tag but they can’t find anyone to play with them. They meet Bob’s niece Samara and wonder if she would like to play.  She can’t hear them because she is deaf.  Rosita and Telly are concerned because they don’t know how they will be able to all speak and play together. Samara explains that even though she can’t hear them, she can talk to them by using sign language.  They have a lot of fun learning, playing, and also signing and saying the alphabet together.  Everyone on Sesame Street gets so excited about sign language that they all can’t wait to learn more.', '2005-10-04', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
