INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1B3F40143E094B1C90FE07E292E11416', X'DB555B9887D64CD2B7B4973F9206CB1E', 5, 'Liar, Liar, Friendships on Fire', 'The day trip to Beverly Hills continues and Shannon surprises the group with tourist clothes and a double decker bus ride through Hollywood. Meanwhile, Tamra confronts Braunwyn, Emily leaves the trip early, and Braunwyn has dinner with her mom.', '2019-09-03', 44, '/kMJM1n9wkm3Wy5WibtzwjGpMMyN.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
