INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1BE8091CA46F44ECB366B59E2DE44512', X'02849455D14B476B9603EEF5FB5D2AB3', 12, 'Can''t Hide From These Green Eyes', 'After seeking counsel from her uncle, Ashley must face the truth about why Michael is hesitant to have more children. Robyn confronts Karen about her lies in a public forum, while Charrisse is left questioning her friendship with Monique. The stress of wedding planning becomes too much for Candiace, testing her relationship with Chris.', '2018-06-17', 42, '/b04fKAzI9LJ6miIMbNnYMzIPjYW.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1BEA79D4556E4AE79B8952EBBE51E74F', X'9920276098D04DDAAB2048D2B5C65987', 7, 'Big Trouble in Little Sanchez', 'Rick joins in on hijinks while Beth and Jerry sort out relationship issues.', '2015-09-13', 23, '/mmGdga7NBsz7CCZNVJrZ7bvzuOe.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1BEB941D3BA24FC297EDB078890D381C', X'5C1B881FAC584D72B63F209952D4F902', 30, 'Episode 30', 'Hurry, Hurry, Hurry! This week''s your last chance to join in with the Great Blue Peter Bring and Buy Sale before the Oxfam shops take down their posters this Saturday. Thanks to you, the lives of starving Cambodian babies, children and adults are being saved - watch out for the latest news on today''s programme.', '1979-12-20', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1BF22B57F95F46C4BD569C9B7B2BF54A', X'1BB5392776F64ED39C415414AD0865CE', 1, 'Slagar the Slaver', 'In the kitchens of Redwall Abbey, Mattimeo, son of Matthias and Cornflower, fights Vitch, a mean little rat. Mattimeo is punished by his father for discourtesy to a guest. But Mattimeo''s instincts about Vitch are validated when it transpires that Vitch is a spy for Slagar the fox - a slaver for the terrible underground Kingdom of Malkariss. Slagar gains entry to Redwall disguised as the leader of a troupe of magicians. At the great feast he is able to drug the drinks and capture Mattimeo and his friends: Tess, Tim, Sam Squirrel, and Cynthia Bankvole.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1BFDB60406E1476B8D6D44E7AA8C5DE7', X'16CBF3F2FFFD4A78BCA396D05F5A2C6B', 15, 'Dueling Detectives', 'When George''s giraffe puppet Wally goes missing, Fern and Binky war over who can find him.', '2016-05-26', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
