INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1C071EE546184DCD8372420D526B1D19', X'136B81D3964D4B8FA21492F00D96D6B9', 18, 'Gladys needs a new cowbell', 'Gladys the Grouch cow needs a new cowbell, and the Sesame Street community helps her find or create a replacement for her beloved noisemaker.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1C07726BE698497BB54CBF5FEAAAD431', X'45E64A158FC04E4BA1CA9E3F42F3634D', 19, 'Outer Space', 'The show is way out there, way far away. After all, it''s in Outer Space.   When you look at the night sky on a clear dark night, you can see thousands of stars. There are far more   than you could count. And, they are way out there. They are very, very far away. It''s about the hardest   thing to imagine about space. Let''s talk about the nearest star to us, the Sun. If somehow outer space   were not an icy cold vacuum with nothing to eat, drink, or breathe, and we could drive there in a car, to   get to the Sun at freeway speed of 100 kilometers/hour (61 miles/hour), it would take171 years of driving   without stopping to sleep or get gas out in the near nothingness of space. That''s just to the Sun. To get   to even the closest star, Proxima Centauri, would take 40,000 years. On top of that, most things, billions   and billions of stars, are much, much farther away than that! It is just astonishing.   How do we know that everything is so far away? We have watched the sky for centuries.', '1994-02-04', 26, '/o5VNyP5JvKz0pfAdSUE1Wv68xvO.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
