INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1C120D3B288A43BDA3D9B0B6C6E2C15D', X'879892836FEA40D78D9122C4947DB105', 6, 'An Awkward Valentine''s Day', 'Kody pushes the idea of building one big house, but the Sister Wives are divided. Then it''s Valentine''s Day a very awkward holiday for a polygamist. Lastly, at Kody''s birthday party, Mariah and her girlfriend show up with a major announcement!', '2020-02-02', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1C150BE8E3FC4AC89CE8139634C42B96', X'5144DE59E67F4FCF919B7106989AB797', 18, 'Mad Music Magic', 'Kiki leads the kids in a makeshift band, but her authority seems to do more harm than good when she won’t allow them to play their preferred instruments. Sizzle attends her cousin’s birthday party, so Nuzzle tries to be the dog and the cat at the same time.', '1995-02-08', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
