INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1C1F76855853423190F55EF04D9FDF38', X'C9ADC698BE924DD794ADD8F6759361CA', 19, 'Episode 19', 'Rogers shows crayon rubbings. Later he sees preparations for a variety show at Betty''s Little Theater. In the Neighborhood of Make-Believe, King Friday wants to rush Prince Tuesday''s learning skills.', '1973-03-15', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1C200DA97F2F4D17BF99D65EAF0895F6', X'63F9BF6D39B344F4B885A56807277A80', 20, 'A Muppet Family Christmas', 'When Fozzie and the Muppet Show gang drop in unexpectedly on Fozzie''s mother, she is forced to cancel her winter vacation plans and entertain them all. Soon the Sesame Street gang comes by as carolers, and then Kermit and his nephew Robin discover a Fraggle Rock hole in the basement. A snow storm blows in, stranding everyone at the house, except for Miss Piggy, who arrives just in time for all the Muppets to celebrate Christmas together.', '1987-12-16', 26, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1C20A8DA75654C5592558C3805AECECF', X'D3E13496E3C8490383B45A31FEDEE232', 17, 'The Northern Air Temple', 'When Aang and his friends hear rumors about surviving airbenders, they decide to stop by the Northern Air Temple on their way to the North Pole to see for themselves. What they find is a bunch of people who are not airbenders, but have mastered the art of gliding; though this upsets Aang because they have been defacing the temple. However, there was one part of the temple where nobody has been able to enter, and what Aang and his friends discover inside spells oncoming conflict.', '2005-11-04', 25, '/uQBMjMJchIR1yuW06ZZeCCxxEot.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
