INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1C3AAD04270C445EAE7C202296664B70', X'A61EDA16B5724C5BBA5557DF932417EC', 11, 'Wonder Mountain', 'Mokey is planning a trip to Wonder Mountain — alone. Red thinks Mokey is too dreamy and ethereal to be able to take care of herself, so she secretly follows Mokey in order to protect her from trouble. But it''s Red who needs protection.', '1986-03-17', 24, '/kbJr7DxZ2BpbyYg7QR0MDhIxtwc.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
