INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1C442E556FD44026AAAD3020FE439E8D', X'70D9E39768134785887D27D034928BAE', 5, 'Pingu Pretends to be Ill', 'Pingu wakes, gets up sleepily, goes to the toilet, and is about to go back to bed when he notices that Pinga is already up, and realises he should be too. He decides that he’ll go back to bed anyway, and snuggles down again. Mother calls to him to get up, but all he does is go completely under the blanket. Pinga leaves for the nursery with Father, and Mother calls again to Pingu to get up, as it’s getting late. When nothing seems to be happening she goes to see what Pingu is doing. When Mother asks Pingu why he hasn’t got up he says he’s not feeling very well. Mother feels his forehead, and goes to get the thermometer. Pingu chortles to himself. Mother brings back the thermometer and a hot drink, puts the thermometer into Pingu’s mouth, and goes away again. Pingu takes the thermometer out, puts it into the hot drink to get the temperature up and then puts it back into his mouth. Mother comes back, sees that Pingu apparently has a temperature and calls the doctor. The doctor rushes over, Mother shows him the thermometer and he examines Pingu. The doctor ponders for a moment, and then calls Mother out of the room to consult. Mother is worried, but the Doctor reassures her that there’s nothing much wrong! Pingu goes over to the door and looks through the keyhole to find out what is going on, and sees the doctor pull a large syringe out of his bag. Pingu is rather worried by what this might mean, and when Mother and the Doctor return to the bedroom Pingu is nowhere to be seen as he has hidden under the bed. Mother and the Doctor go to the bathroom to see if Pingu is there, and Pingu takes the opportunity to sneak out of the bedroom. Mother spots him, and the doctor explains that the syringe was just a way of getting him to admit that he''s fine, so they both let Pingu go. He grabs his satchel and rushes off to school, getting there just as the bell rings for the first lesson.', '1995-07-13', 5, '/rvdezjZD5I4b874m8iOnNh6EQ2p.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1C449C2DA481416D8D8AA6616E0C1E50', X'F63C3F6109704E3781CC2B9045A9952C', 23, 'Maria Watches Pets At The Fix-It Shop (Repeat) (3938)', '', '2001-01-31', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
