INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1CB255446196440A92D2157C654275BF', X'98D80972E53A43DDA03A7703465E6F87', 33, 'Close, But No Cigar', 'Ask not what your Pawn Stars can do for you, when the guys get a chance to own JFK''s personal cigar box. A piece that sat in the Oval Office, will the guys light up at the opportunity or will negotiations go up in flames? Then, a guy pops in with one of the most powerful handguns ever made, a Colt Walker. A model used by the Texas Rangers, can Rick get the seller to surrender this rare gun? And later, an Olympic gold medal makes it''s way into the shop. From the 1988 games in Seoul, will Corey stretch out for the win?', '2013-03-11', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
