INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1D4CC793339341DDA48DE01E68C94222', X'33825A1537DC4FF982BDCC720498149A', 4, 'Trash Talk', 'Day two of the girls trip in Mexico kicks off with a polo match, a talking horse, cartwheels, and a lot of tequila, but Stephanie finds herself having a hard time finding the fun. Kameron and Brandi find themselves at odds over LeeAnne’s behavior. An explosive argument erupts when names are called and napkins are thrown.', '2019-09-25', NULL, '/21HAUrokYGAS0gIt5c7Wm8z7Ill.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1D52CA2D540D42E8A848C82AC2CB58C3', X'1415EF1C411A4C26814A7C79C3628BC2', 22, 'Reunion (3)', 'The reunion concludes when the housewives look back on their fun-filled trip to Mexico, from Lu’s tipsy topple to the tequila-drinking marathon. Tinsley and Sonja attempt to clear the air and salvage their friendship. However, the reunion takes a turn when Bethenny questions the sincerity of Ramona’s tearful apology. In the hot seat, Ramona is forced to address the accusations she made against Bethenny this season.', '2017-08-30', 60, '/cFrlw6zShLRbbqIgCog1DNNI8bv.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1D566E051063455AB78FDDC169098805', X'B3D2E6DE205C47BD94CE282860AAD053', 5, 'Chapter Five: The Flayed', 'Strange surprises lurk inside an old farmhouse and deep beneath the Starcourt Mall. Meanwhile, the Mind Flayer is gathering strength.', '2019-07-04', 52, '/40CezQOYMQ1t726K3hqdz7Y1Z6G.jpg', '2026-04-03T15:40:39Z', '2026-04-03T15:40:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1D611A09828D4D42ACCEC15CAA91EC6D', X'1D713CA64E174F84949C8CFD98514127', 21, 'Van Gogh a Go Go', 'Paint a picture with the Pawn Stars when lithographs believed to be from Vincent van Gogh are brought into the shop. Will this famous artist''s work draw Rick in or will he brush it off? Then, Corey and Chumlee relive their childhood when a vintage skateboard collection rolls in. Will they skate away with the collection or totally wipe out? And later, while Rick is out of the store, Chumlee makes a mess of things. Will Chum cry over spilt milk or can he clean up before Rick returns?', '2014-10-09', 21, '/uahLm03GEZJFWnECNCU0tvbtwAo.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1D6718614DD34679958AF10575599ED1', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 7, 'Gladys needs a new cowbell', 'Snuffleupagus wrote his name today in Snufflegarden, but because he writes so big, he had to use four cards. He shows them off to Big Bird and the kids, who make several attempts to put them in the right order.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1D69AE6B45E84B378461284A32AAFDFB', X'13ECB08FA00049F98D9654C16C3AD653', 13, 'ABQ', 'Skyler confronts Walt about his secrecy; Jesse falls apart; and Jane''s grief-stricken father takes action that results in further tragedy.', '2009-05-31', 48, '/xdSWJjptnLAvFnh5Is6iJPlH1ds.jpg', '2026-04-03T15:40:33Z', '2026-04-03T15:40:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1D6B2812E5D84BA7A2E1254C28F9AD2C', X'B753871204CE43A6916362280BBB084B', 55, 'Elmo and Big Bird learn about being plants (3905)', '', '2000-04-28', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1D728A5A23FA46F7B00CA946C8CD2F10', X'AE8F64D94B834147A44CBFE720381F8E', 19, 'Inspected By 4', 'Leela, Telly and Elmo are folding clothes in the laundromat when Inspector 4, Judah Friedlander, comes along to inspect for things that are in groups of four. Inspector 4 can’t find four of anything and threatens to shut down the Laundromat! Luckily, Elmo suggests counting the bottles of fabric softener. Time to count! 1,2,3,4! There are four bottles of fabric softener. They pass the number 4 inspection!
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1D749BD14B7F4354B569335B887ACA38', X'5C4E51C6E20746AD875C72988EB1E13E', 29, 'The King''s Bling', 'The Pawn Stars are presented with a necklace once owned by the King of Rock and Roll himself, Elvis Presley. Made of an entire pound of gold, will Rick get all shook up with excitement, or is the King''s chain just an impersonator? Then, a guy brings in a collection of over 200 vintage Matchbox cars from the 50''s, 60''s and 70''s. With the seller hoping to pawn them for a big loan, will the guys bank on the value of these toys, or will they worry about collateral damage? And later, a man comes in with a pair of German Pickelhauben helmets from World War I. Sporting traditional Prussian spikes on top, can these rare helmets draw Rick onto the negotiation battlefield? Or will he be too hard-headed to make an offer?', '2011-09-05', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
