INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1D7EE3942F9E4046A147FECE08E7DD6F', X'4091B13B4DB64857AD2220B5658C6B89', 12, 'Teresa''s Mystery Man', 'Teresa’s mystery man is revealed and Jackie’s apple picking birthday adventure turns into a chance to bash Dolores’ relationship. On the contrary, Joe Gorga gets some shocking health news.', '2021-05-05', 43, '/jqYKEacohjKmGQ7T2OCGI2bUvyK.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
