INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1D8E867322844DB7A1F3C7AF2DC9A290', X'FFC2A75E0FFA4B26B1219B91B277594A', 6, 'Make-Ups and Breakdowns', 'Cynthia and NeNe continue to clash as they try to resolve their issues. Meanwhile, Phaedra plunges into work to keep her mind off Apollo''s dramas; Cynthia makes her runway comeback at New York Fashion Week; and Kandi treks to the Big Apple to visit Todd''s mother.', '2014-12-14', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1D999784D6764BCD8DF827ED6A41B492', X'E4023DA233D74A2BA04ACA449BD23935', 5, 'Halloween V', 'Brick invites a girl over to the house for Halloween, Sue tries to raise money for college with a pumpkin patch screening of "It''s the Great Pumpkin, Charlie Brown," and Axl accidentally gets locked in the library.', '2014-10-29', 22, '/pNvumMREeenZlr10eOSQXWOWqj6.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1D9D1213140D444D9B7F56BBD9A607B0', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 64, 'Miss Blechman visits Oscar, her favorite student', 'Miss Blechman is visiting Sesame Street and pesters Luis to try and guess what she does for a living. Given her clues of working in a classroom, receiving apple cores from young Grouches, and dirtying up her blackboard, Luis knows that she is a Grouch teacher and is there to see Oscar, who was her b Miss Blechman gives Oscar a Grouch listening test, identifying the various nasty noises around them.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1D9EC6A963C4465D8BF170FC04CACF25', X'5BA20443D99F482081F66832D3F2BC4F', 18, 'Computers', 'With special guest, Mick H. Computers are used throughout the world all the time. Computers are in cars, calculators, televisions – you’re even using one right now. Humans use computers to take information – things like pictures, words, numbers, and sound, and turn it into electricity. The information is changed into a pattern of electrical pulses, a bunch of electricity “ons” and “offs.” The computers are designed so that they can tell the difference between pieces of information by the different patterns of “ons” and “offs.” Computers change the information you give them, turn it into electrical pulses, make changes to it, and give it back to you in a form you can understand in a matter of thousandths of seconds. It’s not the computers, it’s the electricity that makes computers so fast.', '1996-04-25', 26, '/xj3FkroiwBEf0ZLaCEiYMA46zFk.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1DA1C57F5F7C4366940CC3C091A5587C', X'E606692A47B7411EB54B7C6BF61A67B7', 2, 'The Carrot Seed/The Empty Pot', 'From their roof garden, Lionel and Theo marvel at a flower that gets at Theo''s sinuses. Includes re-readings of stories first heard in the episodes', '2005-04-25', 30, '/i6j8ZMsuJrgTolTOHtz9Na9E4DZ.jpg', '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1DA6D3101B484212B90AD3B71E3178AC', X'C21DBD225E2E4414BB67750399AAF6F0', 9, 'High Tops', 'The Pawn Stars feel a jolt of history when a guy brings in the original AC motor built by Nikola Tesla. Considered one of the most important inventions of the 19th century, will they power up a high voltage deal for this national treasure, or will the negotiation run out of juice? Then, Rick and Corey check out a 1968 VW Bug convertible. Nearly restored, but with a broken motor, will Rick try to convert this busted bug into cash, or will this deal crash on arrival? And later, Chumlee nearly loses his grip when a pair of Marty McFly high tops levitates into the shop. A limited edition Nike shoe, will Chumlee tie up the deal, or will he send these kicks back to the future?', '2011-12-26', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
