INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1DBB22BEF8F14DFCB1ADCDDBBAE2CFBC', X'05C0E384194C44179F62803EB615E409', 114, 'Staying well', 'Lady Elaine wants to turn King Friday upside-down with her Boomerang, but it backfires and the whole Neighborhood turns upside-down.', '1968-07-25', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1DBF9EBA00D14AA4AC5BFD772C3D8F7A', X'E291DF42D44F49E5BF812DF32EE4A30F', 23, 'Read My Book', 'Bear is holding his weekly book club. He''s excited that the mail has come because he ordered a new book and sure enough, there''s a package waiting for him. However, when he opens the package, he finds that the book is called 1001 Ways to Cook Slop. This definitely isn''t the book he ordered. A quick phone call to Jeremiah Tortoise reveals the mixup --- Bear must have received Doc Hogg''s cookbook by mistake, while Doc Hogg got the book intended for Bear. He says that he''ll get the problem taken care of as fast as he can. This leaves Bear with a bit of a dilemma, as he still needs a book to read for his club, but it could take a while for Jeremiah to bring the right book. Bear decides to search the Big Blue House for another book to read. As he goes about his search, he finds that everybody in the Big Blue House has ideas on books that he could read. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1DC357A14B8A4BD38603929D0227DFBD', X'EA73E13C696248048305C303DF65F89F', 5, 'Ducklings', 'Rogers brings ducklings into the Television house. For their benefit, he fills a wading pool and both he and François Clemmons feed the ducklings. Lady Aberlin and Lady Elaine discuss the difference between being alive and being a model. Robert Troll tells King Friday that Sara Saturday will soon be arriving from Westwood.', '1969-02-14', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1DC55C4A60244D0593E4594715A0ED64', X'5C16DB9D5E7140EBB44EF559B2DDB8F3', 1, 'Goldilocks And The Three Bears', 'It''s probably the most famous story of trespassing in fiction. In this version, its unquestionably the most entertaining. Tatum O''Neal stars as the mischievous but lovable heroine in this story of a child who invades the lives of 3 bears. The amusing threesome is headed by Alex Karras. Carole king and John Lithgow and Hoyt Axton are included in the talented supporting cast.', '1984-01-09', 51, '/pLDzOPmahwHA9OQkw09CFJmeFrB.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
