INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1DE5FDFE442746C2ACB0B5E804D851A3', X'EA1650C2E4F146C793BA74B5D45D08E5', 16, 'The Bride and the Doom', 'Back from the Miami trip, Cynthia''s rocky road to the altar is nearing the end, but as she struggles with last minute wedding jitters, her mom and her sister urge her to reconsider getting married altogether. Phaedra has a surprisingly emotion reaction to heading back to work after her maternity leave. Sheree''s acting chops are challenged at her very first movie audition, and Kandi finally confronts Kim about their financial arrangement regarding their new song, "The Ring Didn''t Mean a Thing."', '2011-01-30', 64, '/74qYX4ZotuZDjsxGrZqLlxr8S7l.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
