INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1E19167D011046938A8F74CF79C81EE0', X'ECB64EF34F8045A7B4A9C04434B02E35', 42, 'Breaking the Bank', 'The Pawn Stars take it to the hoop when one of NBA legend Dr. J''s supposed game-worn sneakers steps into the shop. Will the guys score a slam dunk on this item or will it be an air ball? Then, a rare Half Eagle coin from the Civil War flies in. Can the guys land this Eagle or will it fly away? And later, when everyone borrows from Rick''s coin jar, will he see it''s time to change or will the guys break his bank?', '2014-05-22', 21, '/pZr9SU7rg6WsCMeHNwKCmCNSTQJ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
