INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1E3CAD4DFDA24F5A9619895E732A2442', X'2E6EE129B32E4417950056F1CC9BC434', 8, 'Is This a House for Hermit Crab?', 'LeVar sets out to build a bird house, prompting an examination of animal habitats. Eartha Kitt reads the story of a growing hermit crab, who is now too large for his current shell, and all the difficulties he has trying to find a new place to live, all the while trying to avoid predators who want to eat him.', '1993-10-20', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
