INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1E61F6996B8B4BEFB485F42C35060B74', X'BBFEE3B49C9548A6BEAA791FA08B1F43', 13, 'Episode 13', 'The remarkable story of Judy, the only dog ever to become an official prisoner of war. Captured by the Japanese after the fall of Singapore, Judy survived the gruelling conditions of a forced labour camp and on her return to Britain she was awarded the Dicken Medal. The citation read '' for magnificent courage and endurance in Japanese prison camps, thus helping to maintain morale among her fellow prisoners, and for saving many lives by her intelligence and watchfulness''.', '1983-10-24', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
