INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1E744888AA1745349B8D465BABC5D919', X'05C0E384194C44179F62803EB615E409', 17, 'Donkey Hodie comes to the Neighborhood of Make-Believe', 'Title number 0017. Opens with Mister Rogers arriving with papers in his hand. A young donkey named Jenny is visiting Mister Rogers on the porch. Back in the house, he, Lady Aberlin, and Mr. McFeely play a game of Pin the Tail on the Donkey. In the Neighborhood of Make Believe, Donkey Hodie has just arrived and is looking for a place to live. He assures Lady Aberlin and Henrietta Pussycat that he no longer bites.', '1968-03-12', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
