INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1E77AB76C5784049B00F84E28EA69F71', X'F4C403079B5E4263A4E0DFA138131E7F', 63, 'Elmo''s World: Food, Water & Exercise', 'Join Elmo as he explores why food, water, and exercise are essential parts of your life! An apple talks about his family tree, Elmo scuba dives to depths unknown, and you can even join in the exercise by groovin’ to the Bunny Hop! Learn with Elmo about foods from around the world, dip into the deep water and stay healthy and strong with exercise!', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1E7B2D7AF2E041CC963B17762C9EE50C', X'5144DE59E67F4FCF919B7106989AB797', 12, 'I Love Kiki', 'Kiki is at a loss as to what to do when she unwittingly “breaks” Julie’s toy horse, and can''t bring herself to tell her. Sizzle looks after the sneaker that Nuzzle likes to chew on, but when the Piece Police throw it out as she naps, she panics. Ben does not appear in this episode.', '1995-01-31', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1E7F56B15AE3479C8E024623EA64F0AB', X'9193E795DA7C40ECB68FF63AA7D5174F', 153, 'Histories & Lore: The Dothraki', 'Jorah Mormont details the history of the first major migration of the Dothraki after the Doom of Valyria towards Central Essos, and how the newly invaded invaders destroyed the civilizations of what would later become the Dothraki Sea.', '2016-11-15', 5, '/8WiJ6QMpFFnoZvCNDCM2czO89Li.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1E881AE9778C4A84AFB4E6D7E6FED761', X'2AEBFAD431454BC19DEF5F1D5BDFCFC8', 3, 'The Pen', 'Elaine regrets accompanying Jerry on a visit to his parents, where local gossip includes how Jerry acquired a pen that writes upside down.', '1991-10-02', 23, '/eLZeYFfxDblM6ynFP9byqUGhVO0.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1E917BFED3474521AEE3C4A381BC3648', X'BFDF87FF01DD4B5494BD19B384F41BDB', 3, 'Lies in the Air, Sand in My Hair', 'Vicki and Briana take a road trip from Oklahoma to Orange County when Vicki finally gets her wish, her daughter is moving back.  But Briana''s homecoming is not all that Vicki hoped. Meghan faces her fear of needles head-on when she begins her IVF shots without Jimmy, as Heather struggles with her children''s expectations about how much they see their father. Kelly throws a beach party to get to know all the women better and Vicki and Tamra pull their heads out of the sand to try and resolve the issues that have plagued them for the past year.', '2016-07-11', 44, '/5ZxIAw5lErd7UZJyJTXel7Rsz9s.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
