INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1E97A7A077C44D96AA999640E202FD85', X'A61EDA16B5724C5BBA5557DF932417EC', 8, 'A Brush with Jealousy', 'When a new artist shows up in Fraggle Rock, Mokey is determined to prove that she is better. She even goes as far as to acquire a magic paintbrush — one that brings danger to anyone who uses it.', '1986-02-24', 24, '/r3mFA3sk0QItDSPwtkfFP37NjzJ.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
