INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1EA965CBED6C467CACCD7C715B55D07E', X'136B81D3964D4B8FA21492F00D96D6B9', 33, 'Linda''s first day at the library', 'Linda starts her first day as a librarian and learns how to help patrons, organize books, and share her love of reading with visitors.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1EA97323D5864593BBB634A409734769', X'68138DE20900460AB58E480688F1E081', 24, 'Buggin''', 'When Bear talks to Ray in the morning, he learns that there''s a thunderstorm coming. He gets things ready for the upcoming storm, and then hears Ojo and Treelo racing inside. They got scared by the storm and are worried that they''re still in danger. Bear assures them that he''s prepared at that they''re safe inside the Big Blue House. Tutter gets scared too, and everyone''s really scared when the power goes out. Bear allays their fears with his Bearcraft flashlight, but then Tutter gets scared by his shadow. Eventually, the power comes back on, and the kids start a game of hide-and-seek. Tutter then comes across Pip and Pop pretending to be a purple flower monster and is scared into hiding himself. Although they were just trying to have fun, they eventually realize their mistake and apologize. Together, everyone summons Shadow, who tells the tale of Little Miss Muffet. In Shadow''s version, Little Miss Muffet isn''t the least bit scared of the spider who sits down beside her and invites it to share her curds and whey. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1EB507186E6F424CB64150CB54D06584', X'E2909BECD5804388ACDC22ADE5168644', 5, 'Food', 'Rogers visits the home of music director and close friend John Costa, who is preparing a pasta dinner. As the all-out effort for Northwood comes to a close, Bob tells Daniel the truth about the "vegetable soup tree".', '1984-11-23', 27, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
