INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1ED5FA0D946E4DB4B8C28766548D7375', X'6C47406BB3D640D8B4831AE1B3D30009', 8, 'Fireman Sam: The Great Fire of Pontypandy', 'Fireman Sam: The Great Fire of Pontypandy, known in Scotland as Fireman Sam: The Great Fire of London, is a 2010 animated film, based on the Welsh stop-motion television series, Fireman Sam. Norman, Derek, Sarah & James and Dilys go pioneering with Trevor Evans in the forest. Norman Price and his cousin Derek want a campfire to cook sausages and try to light a fire by rubbing sticks together. The trouble is, Dilys calls them away and the fire gets going without them realising it and the great fire of Pontypandy starts!', NULL, 10, '/rcC4chijhaTr2l50tqjsYsx8eNL.jpg', '2026-04-03T17:14:36Z', '2026-04-03T17:14:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
