INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1F2CDE4D857A40918B3B5310E4C6560B', X'42E591E22A884434AE9F3D4B1D685613', 19, 'Secret Agent Man', 'Step up to the plate with the Pawn Stars when a 2004 World Series players ring swings by the shop. The year the Red Sox broke the curse of the Bambino, will the guys hit this deal over the Green Monster? Then, Chumlee spies a toy James Bond Aston Martin from the 1960''s. Complete with working gadgets and weapons from the film series, will the piece stir Chumlee into action, or does he get shaken by a high asking price? And later, the guys get tired of Rick''s grumpy behavior and try to push him into taking a vacation.', '2013-08-15', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
