INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1F87AAA0E3A045728ECC84FECD2A66A9', X'363A94F9E0E5441CAA862BE2E9832DA1', 8, 'Rocket Man', 'Corey drills down on the chance to buy a vintage dentist''s chair; an Andy Warhol Superman poster flies into the shop; Corey takes a shot at some miniature toy pistols; Rick and Chum take a 1964 Cadillac Coupe DeVille for a spin.', '2021-11-20', 42, '/sL17Njl5Gi26LYTMtS36o4GzP2z.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1F8B84E6DDA74F1A8CE34D1531F88E5F', X'B1D55597D9D24EEEAB9546DBB163291A', 22, 'Pingu''s Grandfather Is Sick', 'Pingu is painting a painting while his mom is ironing clothes, but then the telephone rings and Pinga answers the phone, Pingu''s mom rushes Pinga off the phone - it is Grandpa who''s suffering measles. Pingu tells Pinga not to mess up his painting but Pinga throws red on it. Pingu gets really angry at Pinga and she runs away from Pingu. They go to Grandpa''s house, but Pinga blocks the door so Pingu can''t get out. Pingu backs up and rushes the door, but Pinga has moved away and he falls flat on the ground. They all go to Grandpa’s house and while Mother tries treatments, Pingu and Pinga run around babbling and dancing, possibly to entertain Grandpa, but end up annoying him. Mother lectures them and tells them to be quiet, but they pretend to cook something in a pot and the lid falls off. Mom tells them to stop messing about and again tells them to be quiet, but they play dress-up while Pingu is on a sled and they crash into the drawer. Pingu''s mom, exasperated, makes them go outside, where Pingu finds a board and puts it above a giant wad of snow to play seesaw. Mother, exasperated again, tells them to stop. Pingu then kicks snowballs into the door and kicks one into Mother. She finally has had enough of their behavior and tells them to go home. They then use markers to make fake spots and then call Mother. She comes home, lifts the bed sheets and finds them all spotty, like the measles. When Mother rubs their heads she finds out they have used crayon and they try it on Mother. When she jumps on the bed in the ending, she breaks it (much to Pingu''s surprise). They then laugh.', '1990-05-26', 5, '/hAQqK9aQzh02DIc1u3SMI5pAtNG.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
