INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1FB2F303B3664A4B9DEBA28533ECE0AE', X'F13CB62284E34654A8F10CEAB09A9CA6', 9, 'Franklin Stays Up', 'Franklin is having a campout in his backyard and he and Rabbit hatch a plan to stay up all night. Originally, all members of the sleepover are on board, but then they fall asleep one-by-one until finally Franklin and Rabbit are the only ones who make it until morning to see the sunrise, but not without a few setbacks.', '2002-05-27', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
