INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1FB4E96DF4124A3193F753F771002822', X'E56BE195538942BC8AA92D9E9B0D974F', 1, 'Vote For Froglet', 'An election special. The narrator explains the democratic process, and demonstrates it by asking the Clangers to vote between the Soup Dragon and a Froglet. The Soup Dragon wins the election on a policy of "No Soup for Froglets", but the Clangers are dissatisfied with the result.
