INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1FB70856D2CB4F54A14B386C428C8CCD', X'235468B020FC4714BC3FD7E7AEB25F4B', 1, 'MIA Back in Action', 'Alexia is blindsided when Todd files for divorce. Julia revels in the joy of adopting two baby boys, but not all seem supportive. Lisa throws an Old Hollywood birthday party for her boyfriend, Jody, but Larsa has a bone to pick about her ex.', '2025-06-11', 54, '/pHsq7GQ093h0FwbneOCqjsgqSEo.jpg', '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
