INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1FBFA8487255454493A7D83DF335909E', X'97A3D1F5A8F147CD81222E74A092836D', 18, 'Who is Max Mouse? (2)', 'Max Mouse continues to wreak havoc in Hurston. Jamal Lenni, and a lot of other kids grades get changed, false alarms go off and a child is nearly killed in a fire because the fire department is responding to a false alarm. Ms. Kelly has had enough. The kids have never seen her so upset. Then there''s a new message on the computer but this one looks serious.  The team''s three suspects are Calvin, Erica and Janice.', '1993-01-03', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
