INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1FCFD556484544A69FEAF8EB2379BDDD', X'21384B9C43FA410CB89D102E7CF9129B', 8, 'A Wife Decides', 'To move forward with their new life, the Brown’s burn the bag Kody used daily to go between each house. Janelle hits a plateau with her weight loss. Kody and Meri make a decision on Robyn''s surrogacy offer.', '2013-09-08', NULL, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
