INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1FDA7C22464A446DBEAF17E33B4D3D3A', X'4861CE46904543C7963F27B4EA539804', 134, 'Episode 264', '', '1971-05-13', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1FDD99AB7C464408ABE989D8411F0BD0', X'45E64A158FC04E4BA1CA9E3F42F3634D', 18, 'Electricity', 'It''s time for Bill Nye to shed a little light on electricity.   Electricity might seem mysterious, but once you understand the science the light goes on (so to speak).   You flip a switch, and the lights turn on. You push the play button, and your personal stereo starts playing   music. When you flip the switch or push play, you start a flow of electrons. Electricity is the flow of   electrons, and electrons are very tiny charged particles. Electrons are found in atoms, the tiny pieces that   all stuff is made from. We can make electrons flow in two ways. Batteries make electricity by mixing up   chemicals -- making a chemical reaction that forces electrons to move in a path from the battery to the   personal stereo and back to the battery. Electricity that turns on lights in your home is made by power   plants. Most power plants use big machines called generators to make electrons by twirling wire in a   magnet. The magnet makes electrons in the wire move around, creating electricity.', '1994-01-28', 26, '/vqlmjIOrFgXGa3165j5D659kD6h.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1FE8DB09BB0F4D5990F1601BFD8E1942', X'89BA90EC2C794A12A11D7465D1757683', 7, 'Rick and Morty The Non-Canonical Adventures: Blade Runner', 'A claymation recreation of a classic scene from ‘Blade Runner’.', '2017-07-11', 1, '/c6WEy6P5qDTIKLtkaQfoM4qL18U.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1FE9F0D5079F4A1E8BCDCD913C378EF7', X'3AF7EA64FA134097B8E440AF07083054', 61, 'Episode 61', 'Rogers first shows his driver''s license. As a favor for Mr. McFeely, he gives a delivery to Trow''s workshop. Robert Trow is giving a lesson on silkscreening to a professional artist. The Neighborhood of Make-Believe has waited a weekend for the license for MGR-TV. A few hurdles still have to be cleared. X and Mr. McFeely have delivered to an empty studio. But Lady Elaine and King Friday arrive in haste, eager to get MGR-TV back on the air.', '1974-05-13', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
