INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'1FF1AAC228604F5BBFA4C1E8B1301AB6', X'97616D6E5C17449FA37655F1DA83D6C3', 4, 'Mister Rogers Talks About DISCIPLINE', 'Mister Rogers arrives with a towel and a pair of swim trunks and makes good on his promise from the previous day to show viewers where he swims. He talks about how he made a promise to himself to swim a certain length every day and has done so almost every day for ten years. Mister Rogers then shows film footage of his daily swimming. Following the film, Mister Rogers talks about how he doesn''t always feel like swimming but he does it anyway because he made a promise to himself to do so.', '1982-03-03', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
