INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'201A2B3D7A6141CEB45E2D0955B5D3EE', X'04FB713D9C5945F78DE0ACD7582DAA53', 7, 'Brunch Gone Bad', 'Margaret hosts a brunch leading to a big blowup; Teresa, Melissa, Joe Gorga, and Margaret head to Danielle''s wedding, but tensions run high between Teresa and her brother. Melissa worries their family drama could ruin Danielle''s special day.', '2018-12-19', 43, '/n5bWzHJSnEKmjRoAFHvyFQK9K9w.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'202B31D6E733463F87334D54F5A78C5B', X'70C8CB4624944DD498F66BFB9B3FAF73', 33, 'Moon Walking', 'The Pawn Stars are blasted into orbit when someone brings in a flag from one of NASA''s final missions to the Moon. Autographed by the crew of Apollo 16, will the gang take one giant leap and buy this rare piece of history or will they take steps to abort the mission? Then, Rick is presented with an 1861 Civil War Colt musket that was won in a poker game. Mysteriously perfect in every detail, will Rick risk going all-in on an offer or will he second guess his hand and fold? And later, Corey and Chumlee meet a guy selling his collection of NFL pins from the first 20 Super Bowls. Will they draw up the perfect play and celebrate the win or will they fumble the deal and lose yardage?', '2010-07-12', 21, '/oddqYDsj3SY4HBFaDeWIQraxa6C.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'202C454F303348A0A8149B8F6147BB40', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 85, 'Telly becomes a firefighter', 'Oscar gathers all his "friends" for a club photo, cramming them closer and closer together for the shot. Luis explains the parts of a toy fire engine to Telly, who immediately dreams of becoming a firefighter. After putting on a helmet and getting a small extinguisher, Telly discovers he must wait for people to call for help rather than solicit for work, and learns that real firefighters require training and education.
