INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'20ABED11392B463C85AD850767C32853', X'33319C06A2B043BF8694B3E8E37E49E9', 7, 'Disappearing Duck', 'Rosie and Jim notice some ducks in the canal and their Duck wants to meet them, so they take him as they follow Neil to visit a place with more ducks.', '1997-02-21', 10, NULL, '2026-04-03T17:19:38Z', '2026-04-03T17:19:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'20AD4F1C85314AC8BC7093DBB005025D', X'3FC7C152E4F6426AA89936EC454C4403', 1, 'To Fly with Dragons', 'After moving to a new house, a 6-year-old girl named Emmy and her little 4-year-old brother named Max find a magical dragon scale that takes them to Dragon Land, a place where they meet magical dragon friends, Cassie, Ord, Zak and Wheezie the 2-headed dragon, and Quetzal the teacher at their School in the Sky.', '1999-09-06', 30, '/anETWah643iUQqXto0kQazQcX3P.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'20ADA2B806514601AD666C6C0950A1A4', X'46D7A706C7A84EBEB96F387C66E8BB8B', 49, 'Episode 1494', '', '1981-01-29', NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'20B38D4A79924D06A02750067FA2D9D9', X'D5383B3D56364D71B99CB84774B4B3C6', 19, 'Pingu Builds a Tower', 'Pingu, Pinga and Robby are looking at a picture of the Tower of Babel in a book. He spots some ice bricks nearby, and decides he wants to build a tower. Robby and Pinga agree to help. While Pingu puts the first few bricks into place, Pinga gets a brick to add. Pingu points to a big pile of bricks and sends Pinga over to get more. Robby flips a brick neatly into place with his nose. Pingu applauds. Robby shoves another brick across. Pingu can’t reach it from where he is standing on the tower and gets Pinga to lift it to him. Pinga gets several bricks together, stacked like a train. Robby then finds a plank and has an idea; they can use it to get the bricks up to Pingu who is on the top of the tower. He places the plank on a brick, like a seesaw. Pinga sees this and wants to try out the seesaw. Pinga then puts a brick on the end of the plank and Robby hits the other end of the plank with his tail. The brick flies into the air and lands in just the right spot on the tower. Pingu pats it into place. Robby and Pinga then set up a production line. Pinga pushes blocks on at one end and Robby flips them into the air. This process gets stopped when Pinga loads several blocks together and the plank snaps. While they’re wondering what to do, Pingg turns up. He’s amazed by what he sees. They explain what they’re building. Pingg thinks the idea is hilarious and has a good laugh at them, which annoys Pingu. Pingu makes a snowball and tosses it at Pingg, just missing. Pingg runs off. Robby then flips a brick up to Pingu, who catches it and puts it in place. While he’s doing this the seagull lands on the top of the tower next to Pingu. Pingu tries to shoo the seagull away; the seagull tries to peck Pingu. Pingu calls down to Robby, who tosses a fish up to the seagull. The seagull catches the fish and flies away. Pinga and Robby wave it goodbye. Pingu wants more bricks to lay, but Pinga and Robby can’t find any more. Then Pinga comes with several more. Robby is delighted until he sees where Pinga got them from – the bottom of their tower! The tower starts to wobble, and despite Robby’s attempts to stop it falling it crashes to the ground in a heap, with Pingu underneath. Robby thinks Pingu has been flattened in the fall but suddenly sees a flipper being waved for help. A relieved Robby pulls away some bricks so that Pingu can get out. Pinga brings the book and suggests they start again, but Pingu doesn’t think this is a very good idea and tosses the book away.', '2000-01-01', 5, '/bboYehA0XhULv8xMi27gtQpqnuK.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'20BD11B7553E481D8A20C87AA396B12C', X'BC1B58B0F2D64214914B231F27FB4D61', 7, 'Teresa''s Got a Gun', 'Teresa and Melissa attempt to make peace, after which some of the gang journey to the Catskills. Back in the Garden State, Kathy savors the flavor of scouting for restaurants and Melissa prepares for a holiday dance recital. This spins into motion a family reunion---and it won''t include Teresa.', '2011-06-26', 43, '/bPZrO4Gsjgu8Vzz9M6mDxRPoe3t.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
