INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'20C5F63FD80A4920B543D3C5DBB18219', X'73AE1459BA914185A9DABF6F2844AF49', 12, 'Eat, Drink, and Be Scary', 'Looking for love again, Ramona meets with a matchmaker. Meanwhile, Dorinda and her daughter Hannah discuss Dorinda’s recent life struggles. And to mark the end of Halloween week, Luann hosts a voo-doo themed dinner party where Ramona becomes the subject of everyone’s witchy ire.', '2020-07-02', 60, '/mEzEmnyk2bgpBMnSbtohPfZqOTJ.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
