INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'20D4BDD727274BC785E2BEC7ED247C88', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 103, 'Episode 2198', 'Maria has just finished making a small table to give to Linda for her birthday. Telly comes by with a potted plant and asks Maria to build him a table to put it on. Buster the Horse greets Oscar and remarks that he looks rather slovenly, a word Oscar has never heard before. Buster explains it and gives various synonyms which are new to Oscar as well.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'20D572E921D14C7C9D2FF744AE5F75EE', X'3FC7C152E4F6426AA89936EC454C4403', 50, 'Frog Prints', 'Everyone goes on a boat ride through Dragoon Lagoon where Max makes friends with a Unifrog named Hoppy, who can say his name, despite Quetzal''s objections that he can’t take him home because he would feel homesick and miss his family.', '2000-01-21', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'20DA57DB7A3F4FDC947E2AEFD99E2B95', X'4F18AC4C8757456CA49A224F00E6A9F7', 5, 'Firefly Show', 'At dusk, Chris welcomes the viewer to Sesame Street as he closes Hooper''s Store, and listens to all the nighttime sounds. Telly and Baby Bear pass by him with a net and a jar, and tell him that they''re trying to catch fireflies. Chris goes home, and Telly and Baby Bear tell the viewer to help them out by pointing out any fireflies they see. One flies above their head, and they scramble to catch it as they follow it near and far.', '2008-08-15', NULL, '/4OnXjgBbdzKkaqIxemgTaTRLKx9.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
