INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'20E60612AF8D4C00B0245601E2A1E8CD', X'F29F456F8E3849AF88087943977100EC', 2, 'Arthur and the Whole Truth', 'While Arthur is practicing for a piano recital, he learns that Buster has been telling him white lies just to not hurt his feelings. Arthur and Buster agree to not tell any more white lies.', '2016-10-10', 13, NULL, '2026-04-03T17:38:02Z', '2026-04-03T17:38:02Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
