INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'20F875F6A7854640B252917D82F60F32', X'941B8C6544544336BE7C1D0591C12F90', 8, 'Pingu''s Moon Adventure', 'Pingu’s and Grandfather are outside looking at the moon, and Grandfather explains to Pingu how to get there in a rocket. Pingu decides he wants to visit the moon, so when he gets home he goes into the shed and gets out the toolbox. Pinga comes and asks what he’s doing. Pingu tells her that he’s going to build a rocket to go to the moon, and she wants to help. They go into the shed and come out with a miscellaneous collection of objects that, together with an old barrel, they use to build the rocket. Grandfather arrives just as they finish with a present for Pingu - an old diving helmet for him to use as a space helmet. Grandfather shows Pingu how to do a moonwalk like in the war while Pinga is getting her potty to use as a helmet, and both Pingu and Pinga go into the rocket. Grandfather tells them not to land on the grass if they land on another planet. Inside, they make their space uniforms using tinfoil. Pingu sits in the pilots seat and pulls the lever to take off, but they’re then both scared when the rocket starts rocking and shaking. They then see a strange alien face, that''s peering in at the window and making weird noises. Pingu looks out of the window to find out what’s going on, and realises that Grandfather is responsible. Pingu and Pinga get out of the rocket, hide, and then watch Grandfather performing! They creep up behind him and yell, giving him quite a shock. They all laugh about it, and together moonwalk off to plant a commemorative flag.', '2003-09-19', 5, '/jFTez5k7dYrwvxZ1LqNWBVZ1J6K.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2105F74BF16F490E98D7FDCC9906B344', X'6053B5C1CE86425C8166E0FCC3466061', 50, 'Episode 50', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-03-09', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'210A8DF9DB434CE38A989516051F9A61', X'54FACB0BDB5941FE9D64C7C7221A3C81', 19, 'Reunion (2)', 'The women confront Ramona over her lies and insults; Dorinda, Bethenny, and Sonja challenge Tinsley to tell the truth about her relationship; Luann is in the hot seat as Andy and the ladies discuss her sobriety slip and probation violation.', '2019-07-18', 60, '/g40LxkHp90pJsyTrZTUl9EGFouY.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'211E0B9D328D4C7793EE275A0C1548D2', X'05FA5E1878D241FEAE300C242C7FFB6A', 24, 'Fields of Fire', 'Sam receives new equipment for fighting fires. It proves to be useful when careless campers fail to put out their fires in the fields.', '2003-05-01', 10, '/xPoeoII4VZbOfWDiF5j5rSJy1Ny.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
