INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'212860441B9849A88F4EED9736BD30C2', X'FB4ECC73CB924C5C821F92179058B37B', 9, 'Poconoko! (3664)', '', '1997-11-27', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2129F2F7C57B4A7EB116B0D51593CC21', X'E291DF42D44F49E5BF812DF32EE4A30F', 13, 'I For-Got Rhythm!?', 'One morning, Bear finds that he can no longer do The Bear Cha-Cha-Cha. It seems that he has simply lost his rhythm. It''s so bad that he can''t even say "cha-cha-cha." He loaned his records to Doc Hogg, but when he can''t get them back, he has to find some other way to regain his rhythm. Pip and Pop attempt to help by providing their services as the "rhythm-masters." Later, Bear finds Treelo dancing to a calypso beat and joins in. In the Shadow segment, Shadow sings a song called "Tingalayo." About a donkey, it featueres a Latin beat. She also gives Bear a tip to help find his rhythm. 
