INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2139E018E6CB40269CF2C6AFC1DDE9C6', X'79916E0E881C43A7B4EE00E5052A94BE', 2, 'The Cold Snap', 'The Dispatcher can''t hear properly due to a bad cold, this situation unfortunately leads to some confusion because he is not entirely sure what everyone else is saying exactly.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'213DAF1746E44CAD931C0AF72C79DD6D', X'DA06465B91544FEBA455374DF7DAB02F', 22, 'Grouch Apprentice (4104)', 'Donald Grump, the grouch with the most trash in the world, is looking for a new apprentice. Oscar, Grundgetta, and the other grouches can''t wait to meet him because if they get chosen, they will get to keep some of Grump''s trash. Elmo decides that he wants to be Grump''s helper too, but just because he likes to help others. Grump puts them through counting and sorting tasks that Elmo does great at. Oscar and Grundgetta are too busy arguing and the other grouches have already been fired. Grump decides that even though Elmo succeeded at all the tasks, he is too good at being a helper to help a grouch. Elmo doesn''tmind. He gets to leave with the one thing he wanted anyway- Grump''s hairpiece. Grundgetta and Oscar are both hired, but they decide that Grump''s trash isn''t worth it if they have to help him to get it. He leaves Oscar and Grundgetta no choice but to tell him, "You''re fired!"', '2005-09-28', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
