INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'217A4B14A2744771A2AFAA5CC07E5763', X'58222745ACE2461A8831178516550BA0', 6, 'I Got Six', 'A boy''s day in the city and out, overlapping with others'' exploits, run through the 6 times table.', '1973-02-10', 3, '/8G37SZDTTVamqaZvOhZqqUEK6cE.jpg', '2026-04-03T17:13:55Z', '2026-04-03T17:13:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'217C788B6B274FFDBBE539883B946535', X'E40E6B639F84449F8E8853209B0906C8', 25, 'Rosita Gets Upset at Zoe & Abby', 'Rosita and Zoe are both excited about their play date together. As they start to play hide-and-seek, Abby Cadabby poofs up out of nowhere. Rosita is about to show Abby how they play hide-and-seek, but Abby mentions another game, "jumping rhymes," which piques Zoe''s interests. Zoe and Abby are good at the game, but Rosita has trouble thinking of words that rhyme with "chair," and can only think of made-up words (which are acceptable).', '2007-10-12', NULL, '/7ERLOEgQuTHjHLGFZMCkeMTPXfW.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
