INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'21E0E1A441634082BA5C2EEDCF783167', X'C9D2B3FB78454F3C9847CE1F7717257A', 6, 'Pawn of the Seas', 'An 18th-century sea map from the legendary Captain Cook has Rick exploring a big deal; Chumlee haggles for a hilarious "Saturday Night Live" prop; an autographed piece of memorabilia from WWE star Roddy Piper; an antique bicycle.', '2019-03-04', 42, NULL, '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'21E3F2760A42443AAB57ED72C580EE1D', X'20D7138EEEA846A88ADA2B0F0EE1F674', 23, 'Episode 23', 'Twelve-year-old Juliette Smith from Barrow-in-Furness wants to be a train-driver when she leaves school. Today she has a taste of the old days of steam as she rides with Simon on the footplate of the 532 Blue Peter.', '1982-11-29', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'21E4B601638F47D5879BC4FDA55113AA', X'4B2A19E02FAE492EBC31F78E63D88EBC', 25, 'Wound Up Rick', 'Make some noise with the Pawn Stars when an autographed Led Zeppelin album looks to break records in the shop. Will Rick give a whole lotta love and make a deal, or will it ramble on out the door? Then, an antique whistle collection announces itself. Will Rick be whistling a happy tune or will a deal blow away? Next, Corey gets political when a Doonesbury cartoon pencils itself in. Will he draw up a deal or will his offer get erased? And later, the minutes are ticking down when Rick explores a self-winding clock. Will he make the time for a deal or wind up with nothing?', '2017-01-23', 21, '/26aDoZ5Y6c8bU24FEoPNRmWkLBS.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'21F00DE36176452AB1C8AE2C4F66562C', X'8BDF0AD3A7984D5AB304C7501EAE6867', 3, 'Love Tanks', 'Tamra and Simon Barney celebrate their ten-year wedding anniversary with a weekend getaway in Napa, and they invite Vicki and Donn Gunvalson to join them. While Tamra and Simon enjoy a romantic weekend of wine tasting, grape-stomping and gourmet dining, Vicki struggles just to be civil to Donn. Envious of Tamra and Simon''s relationship, Vicki concludes that her "love tank" is empty and she''s uncertain if Donn can fill it. Although her husband, Matt, is still in her house, Jeana Keough is making an effort to re-build her life post-separation with the encouragement of her family and her trainer, John Ellis. Gretchen Rossi and Jeff attend the Indianapolis 500. With his history in the automotive and racing car industry, Jeff''s status provides access and privilege that very few people have at the races. Gretchen rubs elbows, exchanges a few kisses, and rides along with the Indy 500 royalty. Meanwhile, a horrible turn of events threatens Lauri Peterson''s fairytale life with her husband, George.', '2008-12-09', 44, '/cZHsP2SCO7684NZvlEIMHlTumaP.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'21F2F01111C742A78131BF935E133878', X'5062CE298DBB48AB879B0771221678D5', 3, 'One Warm Fox', 'It is winter, and very, very cold. So cold, in fact, that Fox borrowed some of Percy''s clothes with the help of a scarecrow in the cold winter night. Percy doesn''t notice though, because Fox puts them back in the morning.', '1999-10-03', 15, NULL, '2026-04-03T17:19:02Z', '2026-04-03T17:19:02Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'21F7ECA316A845CEA367CFB4049B0524', X'0D24C74283F24F378A5D0B09C7DF6A7F', 4, 'A Sermon of Survival', 'Yennefer''s conviction starts to waver. Ciri opens up to Mistle about her true identity. Geralt finds himself at the mercy of Dijkstra.', '2025-10-30', 55, '/yTKE8PmQy4lm1gHgobnoxIGq3WK.jpg', '2026-04-03T15:40:46Z', '2026-04-03T15:40:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'21FCA2C9B0CE406CB8CEBE312E429120', X'27A5A980EC0D4637B5BADF8324A6405A', 6, 'Bad Choices', 'As the Heck home begins to literally fall apart, Frankie and Mike consider leaving homeownership behind and moving the family to an apartment. Meanwhile, Axl tries to fake Frankie out by pretending that he''s sick in order to get out of taking a school test - and must later convince her that he''s well enough to attend a party that evening; Sue and her ex-sort-of-boyfriend, Brad, volunteer to prepare a school skit about showing the dangers of texting and drinking while driving; and Brick tries to offer a little bit of levity by spouting off Shakespearian quotes.', '2011-10-19', 22, '/yNbIgrHMeIwIM0qBfTzum6Vmksj.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
