INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2206F9D62E03413EA52BFC80689F84AA', X'573FA62F55A94F1797CCD1A005A83CC8', 27, 'Ruff Ruff Doggie Robot', 'Elmo, Tamir, and Alan are building a robot dog, but the tail isn''t "waggedy." What if they wrap a wooden paintbrush with shiny foil? Let''s try!', '2025-07-17', 26, '/uuAAMm3mfHPFQjeJSSZalHWQlUU.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2211A85E2CA44D75854473577FD08251', X'F4D370CA3C3940A8911DE2B5E7C6B0D7', 5, 'Little Bear''s Snowmen', 'It’s winter and snow has covered everything in the garden. The toys have fun playing on a sledge and building a wonderful snowman. Little Bear is worried that the birds must be very hungry as their food is hidden under the snow. At lunchtime the toys all go inside to make bread snowmen to go with Old Bear’s delicious soup. While they are waiting for them to cook, they tell each other food stories and become more and more hungry. At last the bread is ready but Little Bear has not forgotten that the birds need feeding too and he has a really good idea.', '1996-10-02', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
