INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'221B325ED8FE47F3B2CBD706FF668361', X'10E64538C78A4CB082F917D14256DBAC', 23, 'Find My Hecks', 'Frankie figures out a way to secretly track Sue and Axl after they refuse to abide by their curfew while they''re home for the summer. Meanwhile, Brick''s determined to discover who else could be class valedictorian as middle-school graduation approaches.', '2016-05-11', 22, '/upnx2eaEFGHJpO6Vo5Ya6iqrbYe.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
