INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'22AD1EFA88324A17BEB8B6A6FD2958C8', X'B1D55597D9D24EEEAB9546DBB163291A', 17, 'Pingu Has Music Lessons', 'Pingu is playing with his blocks, and teaching Pinga what they are, while Mother and Father bake a cake (possibly something else). While Pingu plays with his blocks, Pinga plays her trumpet. Pingu likes this and shows Pinga his instrument, an accordion. Pingu then starts playing awful music hysterically with it, and Mother tells him to stop. Pingu sticks his tongue at her, and resumes playing music with it again (this time holding it from one side and bouncing it up and down like a yo-yo). Finally, Mother has had enough and sends Pingu outside, Pinga, who liked Pingu''s playing, is annoyed and starts crying. Meanwhile, all around the town, people flee and lock themselves in their houses to get away from Pingu''s playing, but when he finally gets to his grandfather, he finds him playing his own accordion nicely. Asking him how he does it, Grandpa gives Pingu music lessons, and he swiftly ends up playing excellently. Pingu then goes home and plays some nice, proper music for his family.', '1990-04-14', 5, '/xlegbSjDMzXwhUZZBK9k1ueWyGa.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
