INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'22E1BE11168E4C4CAB1732B245364D42', X'363A94F9E0E5441CAA862BE2E9832DA1', 1, 'Pawn Jam', 'When a very special cowboy hat owned by President Ronald Reagan moseys into the shop, can Rick wrangle an offer? Next, Chum lights up when a glowing Pearl Jam painting rocks across the counter. Will a deal make him come alive, or will the seller look for a better man to buy it? Next, Rick and Corey rehash the past when a seller brings a Sammy Sosa signed baseball into the shop. Who will win the race to bring home a deal? And finally, inspired by a signed copy of photographer, Peter Lik''s book, Chum sets out to capture an unforgettable muse.', '2021-10-02', 42, '/9tLHRHkrLDfDL5GHNHrgqMo3YGh.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'22E40F7AC1C5428C9CC98C895CA7339F', X'22BEBA7F9B8E456393DA46E76ECBA427', 19, 'Oscar Loves Cranky', 'Oscar gets a new dog: a Rottendoodle named Cranky. Because he has heard that Rottendoodles are grouches that never do what you tell them to, never help anyone, and never kiss, he is astonished when Cranky starts doing all those things.', '2006-09-21', NULL, '/tRNONnlbtNyVfLMw4S1fnunAruG.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
