INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'22F54D563CA6480FB149B96540412444', X'6F731E6BD3C54DE684E17A19CB650E86', 34, 'Rick the Emperor', 'All hail the Pawn Stars when a 44 BC Roman coin with Julius Caesar''s portrait presides over the shop. Will Rick command a high price or will the deal be assassinated? Next, a rare 1960s leather jacket zips in. Will Corey have a cow over the rockin'' style or will he think it''s a bad fit? Then, Corey and Chum hit a streak when plaster casts of Joe DiMaggio''s feet steal a base in the shop. Will the guys mold together a deal or will the sale crumble? And later, Rick is quarantined when a scarlet fever sign infects the shop. Will a deal be his cure or will it just make him sick?', '2016-05-11', 21, '/r7fhIPswpodgu9zj9Q1rbPyT5a2.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
