INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'23339EC13FBB47E3AE7201D25F6437CA', X'991E78F103A54D268F7575E11DB4243C', 13, 'When Things Get Broken: Rolling Ball Sculptures of George Rhoads', 'Rogers visits the studio of George Rhoads. He watches as Rhoads demonstrates one of his mechanical ball inventions. A co-worker shows Rogers around to see various men at work on these machines. In the Neighborhood of Make-Believe, King Friday returns, not at all pleased by HulaMouse''s absence. At the height of his anger, he breaks a toy that Lady Aberlin has brought.', '1999-05-10', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
