INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'23423B828D36434FB29F4E2B0A325466', X'4F18AC4C8757456CA49A224F00E6A9F7', 14, 'Big Bird''s Nest Sale', 'Big Bird hangs up a sign for his nest sale and welcomes the viewer. He’s selling toys that he doesn’t play with anymore, and says that all the toys in the nest are for sale, while everything out of the nest isn’t, including Radar. Snuffy arrives at his nest, and Big Bird makes him his “Assistant Nest Sale Snuffleupagus”. Snuffy''s only task is to remember what toys are for sale and which are not, especially Radar. Big Bird briefly leaves to get more of his toys from Maria and Luis’s apartment and puts Snuffy in charge, but unbeknownst to him and Snuffy, Big Bird’s tail knocks Radar into the nest when he leaves.', '2008-10-02', NULL, '/8Csx7SOXtWflDJHj4tlBZg2LBwB.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
