INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2357DEF8B0B3492FB434ECF58A45E573', X'33440D76E69F47ADAC25862CCBC9DFA1', 2, 'Home Sweet Drama', 'As Robyn discusses her intervention with Juan, Karen meets with Mia to discuss their fractured relationship. Ashley throws a housewarming party and invites her new friend Nneka. It soon turns out Nneka and Wendy may be more familiar with each other than anyone knew.', '2023-11-12', 55, '/44vt9dunjTektaECaa2AScS9K8J.jpg', '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
