INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2366F439EE9B42A0A69EE6EF0E9323DF', X'F13CB62284E34654A8F10CEAB09A9CA6', 4, 'Franklin and Betty', 'Beaver''s cousin Betty is in town and Franklin is the first of the Woodland kids other than Beaver to meet her. The two quickly become friends with each other, Betty identifying with Franklin''s interest in sand-castle building and also wanting to get away from Beaver, who is obliviously centered on her own interests.', '2002-05-06', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2367B6107BF4405E8BB1078F08942D5B', X'DE052E8E7DBD454AA6D8B9AFBA6E9BFA', 19, 'Wombles And Ladders', 'A ladder is adapted to Womble size', '1973-06-20', NULL, '/r5qNhLOpB8TDoLJ71FjuSFQouun.jpg', '2026-04-03T17:23:19Z', '2026-04-03T17:23:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'236F21F57FF441ECB50BA0EEE79425D6', X'8BAE6AA34B554FA6BC158F4317BD1F13', 49, 'Snow People Pt 4', 'Rogers uses the heater for the fish tank and shows the room''s radiator. He also sees that the Brown Marionette Theater is heated with a furnace. In the Neighborhood of Make-Believe, Henrietta begs for a role in the upcoming opera.', '1972-04-27', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'236F8E40C8FF41DFAB054FBF53DAFFCC', X'AE8F64D94B834147A44CBFE720381F8E', 2, 'Cowmonster Pair', 'Elmo and Telly are at Hooper''s Store when Little Bo Peep comes looking for her cow. Elmo and Telly offer to help her and decide to call themselves the Cowmonster Pair! Luis comes along and sings about animal tracks and now Elmo and Telly have their first clue! They find animal tracks on the ground, but when Telly tosses his lasso around an animal, it’s a chicken, not a cow! Luis gives them another clue and sings about tracks that are kind of round. Telly and Elmo come across round animal tracks and are certain they found the cow! Telly tosses the lasso around an animal but this time it’s a raccoon. Luis comes along again and gives them another musical cow clue- animal tracks that are in the shape of two half moons. They find tracks that are kind of round and look like two half moons, but the tracks are from a moose, not a cow! Telly becomes discouraged and Elmo reminds Telly they can’t give up. Instead, they should use the clues they already have and put them all together. Elmo realizes that they have to find animal tracks that look like the moose tracks, only smaller! This time, they follow animal tracks that lead to a door. They open the door and there is the cow! Yee-haw! Little Bo Peep thanks the Cowmonster Pair for finding her cow. They are true cow finding experts!', '2009-11-11', NULL, '/ypYNGxNzWZFfLLcoQjU8AEmUyqa.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
