INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2370D4CD30C24827816D0B58F105575A', X'D405F9734C7E4CB6B7C0D09A884C9B35', 4, 'Ramona''d', 'Ramona gripes when a certain wine isn''t made available at Cindy''s birthday party. Meanwhile, a betrayal results when Sonja confides in Cindy that she plans to negotiate a meeting between Ramona and Kelly; LuAnn throws a cocktail party for the wives in the Hamptons.', '2011-04-28', 42, '/eKwVAdcK3OlF69SDP3TzivI3ESf.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
