INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'239F8020885E438BBFCAB6323F293F38', X'D9973960273B4A92A7DA62EFE8860D09', 9, 'Hip Hop and Heartbreak', 'Meredith and Seth are happy to be back together, while Heather has an awkward Valentine’s Day with her ex-husband and Lisa spends time with her family at the aquarium. And after Jen plans a surprise birthday party for her husband and doesn’t invite Mary, Whitney hears that the other women are talking about Jen behind her back and things get heated when she decides to tell Jen the rumor during Sharreiff’s birthday party.', '2021-01-06', 42, '/bbj1RYSjaEQeusB8pcNaxs9T2o7.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
