INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'23A3C0868739401E8DA7EA5E71B077ED', X'87F8406382B345A4936C3759E5D91CE3', 24, 'Reunion (3)', 'The reunion concludes with the husbands taking the stage; Sharrieff explains where he was on the day of Jen''s arrest, while Justin confirms whether Whitney''s beauty venture depleted their savings.', '2022-03-13', 55, '/a2jnw04xTf1CCRL8aZWsuiBJg14.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'23A6274CBAB049819535469C631AFBAE', X'4F3632B8A91046B6B2EDF2882CC14B2D', 2, 'Best Pet in the World (4058)', 'Zoe, Telly, Elmo, and Baby Bear get into a debate about who has the best pet. Each of them expresses all of the reasons that a certain pet is the best and they get very heated. The friends start to get really frustrated and angry at each other, and eventually Maria comes by to see what is going on.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'23AA0E52BC0B473C81341E58421A58AA', X'79916E0E881C43A7B4EE00E5052A94BE', 13, 'Theodore''s Day Off', 'Theodore requests to the Dispatcher for some time off which is agreed upon but soon gets very, very bored.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'23B35380034F4720A6DCE5A9ED08CD36', X'68138DE20900460AB58E480688F1E081', 37, 'We Did It Our Way', 'It''s a special night in Woodland Valley --- tonight is the night of Harvest Moon. There''s a special party out at the Otter Pond and Luna even has a special surprise for Bear. Bear and his friends enjoy the delights of the night, such as fireflies and constellations. Tutter does his best to stay up, but Bear allows him to catch a little sleep before the big celebration. Bear searches for party lanterns for the celebration, but it''s ultimately Pip and Pop who find them. Everything is finally ready for the big party and it''s drawn quite a crowd --- besides Bear and the kids, Doc Hogg, Lois, Otto and Etta, Grandma Flutter, Christine, Jacques the Beaver, Doc Owl, and even Big Old Bullfrog are there. In fact, everyone''s there except Luna --- they''re worried she may have disappeared behind a cloud. But it turns out she was just getting her special surprise ready --- an old friend Bear hasn''t seen in a long time! In the Shadow segment, Shadow tells a wild story about a man who takes a trip to the moon in a balloon. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'23B78F908C974CA29895F73AFDE24CD0', X'E8981E01407B4EF7B8093B5F30B5248D', 10, 'Rickmurai Jack', 'Tryin'' something new, broh. Doin'' it big.', '2021-09-05', 22, '/6yPSy0ipNQfFUAX3tHSEf75rCdu.jpg', '2026-04-03T15:40:42Z', '2026-04-03T15:40:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
