INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'24908F3907154A8D9E009A463F42E115', X'95CA8B6FCCBC431A9D959B23367BBFED', 13, 'Season’s Grillings', 'Shockwaves from an unexpected news article continue to spread as the ladies try to piece together the truth. Meanwhile, Garcelle serves up a very Haitian holiday meal for her family. When Kyle gathers the ladies for Christmas dinner, holiday cheer turns to jeer as the women press for answers, and Erika realizes that not everyone has her best interests at heart.', '2021-08-18', 43, '/tsESNfxVltBeXDNroy2cFJoJ3BQ.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2492720EF9F048B2B11B1805A93B528B', X'99B7102639194813A330EB09E0E43D74', 5, 'Show Way', 'As LeVar helps his wife and daughter construct his family tree, Diahann Carroll narrates Show Way, in which the author chronicles her family back to her Great, Great, Great, Great Grandmother, who was a slave in the South. Through traditions passed down to each generation, her family learned to sew "Show Way" quilts that were secretly maps designed to help slaves escape to the north to freedom, and how her relatives taught her to keep up with the love of quilting to retain family history.', '2006-11-10', 30, NULL, '2026-04-03T17:36:22Z', '2026-04-03T17:36:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
