INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'24DB341C7FA945278B57527A1710A32E', X'D5351B608A0C482AA6DD4FB860CFE143', 22, 'Episode 1412', 'Mister Rogers takes viewers outside where he has a tent set up in the grass. After showing the real tent, he goes back inside and shows how a tent can be made inside using two chairs and a blanket.  In the Neighborhood of Make-Believe, everyone is confused by a tent which appeared overnight.', '1975-03-18', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'24DD008338D54024A0F3D7E520C9AD49', X'87F8406382B345A4936C3759E5D91CE3', 7, 'Slippery Slope', 'A fun day of snow tubing leaves Mary and Lisa at odds, Jennie and Mary at war and Meredith and Jen nowhere to be found when it comes to having Lisa’s back. Meanwhile, Heather throws a party for Beauty Lab, Meredith and Seth plan for the future and Jennie still reeling from her conversation with Duy looks towards other solutions for their marital their problems.', '2021-10-24', 44, '/hKPNkaKGxyCSQt7oOvHO3xMPhEo.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
