INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'24F050C203F94703BE4253D1FC4422EB', X'05C0E384194C44179F62803EB615E409', 3, 'Chef Brockett bakes a cake fit for a king', 'Title number 0003. Opens with Mister Rogers arriving with a package from Chef Brockett. Because of the new rules and restrictions in Make-Believe, Cornflake S. Pecially refuses to visit the castle. Chef Brockett delivers a cake to King Friday, who is suspicious of more changes, cuts the cake into many pieces to inspect it.', '1968-02-21', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
