INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'24F4B8D58CEE45B09A12785760562C5D', X'AE8F64D94B834147A44CBFE720381F8E', 16, 'Camping Show', 'Chris and Elmo are excited to be camping in the woods! They unpack their camping supplies and take out two sleeping bags and two canteens. One sleeping bag and canteen for each of them. Next, they take out four hotdogs and marshmallows. Elmo gives two hotdogs and marshmallows to himself and two to Chris. Suddenly, a beaver emerges from the woods. Elmo asks Chris if the beaver can stay for dinner. The beaver explains that he doesn’t eat hot dogs and marshmallows but likes to eat bark.  
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'24FADA29204140DB8BF3C9916D711565', X'5A771F52FE964EA2B567A8DDE899059E', 20, 'Fully Vested', 'The Pawn Stars start off with a bang when a beautiful pair of 18th century breech-loading pistols breach the shop. Will these guns hit the bullseye or will they misfire? Things get heavy when a seller brings in a paperweight made by renowned glass artist Paul Stankard. A vest made to hold the 14 harmonicas of Blues Traveler frontman John Popper is music to Chum''s ears; Popper himself even pops into the shop to give Chum a harmonica lesson.', '2018-02-19', 21, '/fBVlfMNrkA1itH7sBXfCDSHJMpL.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
