INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2518C0C2A97B40C082F93AC78088941C', X'A5F2554F07B64471ACE046B97C492097', 4, 'The Demon Headmaster Strikes Again (Part Four)', 'Rose continues to drive a wedge between Dinah and her family, as Simon helps Dinah.', '1996-10-16', 25, NULL, '2026-04-03T17:40:35Z', '2026-04-03T17:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2519F9B354D742BFB23F79F7C6A403EA', X'095258D0D8DB40968AC76A42CD4CBDCF', 21, 'A Dark And Stormy Night', 'Gobo feels as if he''s done it all and wishes there was someplace he could explore. But when he hears that the Gorgs are going on a vacation, he thinks his problem is solved, and decides to map the inside of the Gorg''s castle. So she gets Boober and Mokey to help scare Gobo, who''s got Wembley by his side for the overnight stay. But when the Crown Jewel becomes missing, Junior gets scared and thinks somebody''s in the castle. When Gobo and the gang reveal themselves to Junior, Junior later thinks that there''s a real thief outside. Junior must work with the Fraggles to catch the jewel thief in order to prove to his parents he''s mature enough to watch over the castle.', '1985-05-20', 24, '/8ul1ahUE9QysS4DLkcAZL0PCm1K.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'251BDFBF90E34CDDB60BABA15472C20B', X'4B4D327B6C8B459C9E73B1D4D84AED77', 21, 'Draw It', 'Brother joins an art class to be a better drawer.', '2003-10-14', NULL, NULL, '2026-04-03T17:40:22Z', '2026-04-03T17:40:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'251BF2E6ADBB48FD91FB4E6AD719D568', X'A8DB07E5FBA349A9BD12947C111B39BE', 21, 'Reunion (1)', 'The New York ladies reunite. Here, Dorinda recalls her toughest, most embarrassing moments with John; the women dish on Luann''s ex and sharpen focus on Ramona''s love life; and a look back at a Berkshires trip causes accusations to soar between Luann and Bethenny.', '2016-08-28', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'251C3ACE38EE487AA0B182AF0E0E3024', X'095258D0D8DB40968AC76A42CD4CBDCF', 12, 'Gobo''s School For Explorers', 'Gobo finds out about Uncle Matt''s Secret Rules for Exploring through a postcard, and decides to open up a school for explorers. On his first expedition, he- along with Red, Wembley and Mokey- must travel to the Hole To Who-Knows-Where. Gobo becomes so fixated on the rules that he starts to disregard common sense, and of course, he and Red go at it again. Wembley and Mokey start to agree with Gobo''s rules, but before long, they both side with Red. Gobo decides to go find the Hole To Who-Knows-Where by himself, not knowing that he is still tied on to Red. When Gobo and Red fall through the Hole, Gobo needs to use logic to get back home.', '1985-03-18', 24, '/g6ZQuB6oF0FgmKklWVJ94AT36Rx.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
