INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'253451B2E94E4A7A98C6F43C52671656', X'F4C403079B5E4263A4E0DFA138131E7F', 101, 'Put Down the Duckie', 'There''s a special going on at Sesame Street. First, Gladys Knight and the Pips sing the theme song, then Phil Donahue interviews the residents; Alastaire Cookie tells us the tale of "The 39 Stairs" with Grover. Bob sings the "Who Are the People in Your Neighborhood" song with Ralph Nader, Barbara Walters and Martina Navratilova; Hoots teaches Ernie about how if he wants to play a saxophone, he must put down his duckie; Kermit tries to get Oscar interested in public television; a classic Grover waiter sketch; James Taylor sings an interesting song and finally, some culture: an opera', '1998-01-15', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'254052632810429480B15292D92038D4', X'EBC99729CCB74D6482C142708CD7BA85', 54, 'Episode 54', 'In two weeks'' time, 7,500 athletes will be running in the London Marathon. At 26 miles, 385 yards, it''s the longest race in the world. Sarah tells the story of how this greatest test of man''s endurance began.', '1981-03-16', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'25406462F17B4F1EBDD6B4A94238DEFD', X'DA06465B91544FEBA455374DF7DAB02F', 25, 'Adventures of Little Big Bird (Part 1) (4107)', 'Mumford is doing his new big/little trick for everyone.  While he meant to turn a big letter “M” into a little letter “M,” he accidentally turns Big Bird into little Big Bird!  Big Bird realizes that he is in a brand new world being little.  Everything is so big and he meets small creatures he never would have been able to before.  All of a sudden, he hears Snuffy calling him for their playdate.  Big Bird tries to call back, but Snuffy can’t hear him because he is too small.  This becomes very frustrating and Big Bird wants to be big again.  He figures out a plan and embarks on his trip to Alan and Gordon, who can help him find Mumford.', '2005-12-29', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
