INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'256AC475AE364D0AB2BA0370E73FE6CB', X'CA09391ADE6A4B2BAEFCC2EFBC80A106', 8, 'The Lady with the Ship on her Head', 'Turning even crazier, the show plays with our heads in more ways than one. LeVar is the "Head reporter" of a mock-news program called "HEADline News Report" and "reports" on a truly head-spinning array of all things ridiculous about the head. Included is a "Head-to-Head" interview with The Grateful Head, a fictitious musical group of singing heads...no necks, just heads. They sing a song called, "I Ain''t Got No Body." Marilyn Pasekoff reads the featured story of a vain French woman, trying to win a fancy hat contest, unwittingly has a miniature sailing ship land on her head, and wins the contest when the judges mistake the boat for her head ornament.', '1991-09-25', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
