INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'25779275017C4210BC4D3806BBC64855', X'991E78F103A54D268F7575E11DB4243C', 5, 'Noisy and Quiet: Ways to Play about Being Noisy and Quiet', 'Chuck Aber, dressed as a marching-band leader, visits the television house to borrow one of Rogers'' noisemakers. Contrasting the noise is Rogers'' contention that a smile is quiet and lovable. The Neighborhood of Make-Believe is ready for its costume-laden parade, but must convince X and Henrietta of the parade''s nature.', '1999-03-15', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'25789F639DD748C59BBC1AD7963556AD', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 30, 'Money to Pawn', 'Don''t get fooled at the pawn shop when a seller hands Chumlee a thirty dollar bill. Will this curious cash have Chum reaching for his wallet to buy it or will it turn out to be a costly currency that''s not worth making a deal? Next, sparks will fly when Rick considers restoring a worse for wear spark plug cleaner made by Albert Champion. Later, Rick hires a small team of experts to draw up a value for a Walt Disney signed copy of The Art of Animation. Will a spoonful of sugar make the deal go down or will a no deal leave Rick singing hakuna matata?', '2017-08-28', 21, '/A1tMIouo2CoP20pDDQXEQz6muws.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
