INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'25BD38B3E7784FEDBFABC8046A8966BE', X'ABFE14EEDB424DDEA96A601FF3C53ECC', 6, 'High Standards', 'Cluny attempts to starve the abbey into submission as within Redwall pressure mounts as tempers flare. When Basil and Jess Squirrel seem to desert, Matthias wonders if surrender is close. He decided to try and rescue the stolen tapestry from Cluny in order to give courage to the citizens of Redwall - and discovers that Basil and Jess are attempting the same thing! They outwit Cluny, retrieve the precious tapestry of Martin, and renew the spirit of Redwall.', '1999-09-19', NULL, '/xyZEEqKvFvCTWkRcN69eLRETtkD.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'25BD9EE1744D40ADBE833E24B39768D2', X'A8C6182E05E14B6891A55126CF6C94F0', 30, 'In Praise of Ben', 'The title kinda gives it away, the episode begins with Sarah coming ''home'' to Philidelphia, she''s greeted by Moses, and eventually, a slightly bitter James. The rest is ''in praise of Ben'' Benjamin Franklin. It''s about is education, his inventions, and many other things.', '2002-11-08', 30, '/7KT08ePmVRTBsfVi0F2xRYbs9G0.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
