INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'25D4E99E3AB44C7A9C4F5E61D6A30005', X'6F731E6BD3C54DE684E17A19CB650E86', 30, 'Gangsters, Guns, & Guitars', 'Get mobbed with the Pawn Stars and revisit some of the best guns, guitars and gangster memorabilia ever to enter the shop: a limited edition guitar hand-painted and played by Def Leppard''s Phil Collen, a signet ring possibly once owned by Lucky Luciano, a rare 1800''s octagon barrel .22 caliber Winchester, a 1969 Les Paul Professional guitar, an ornately engraved 1894 Marlin rifle, and a check signed by Carlo Gambino that prompts Rick to give its owner an offer he can''t refuse.', '2016-04-06', 21, '/l4HizKDDxKPwj2gAcCd1Exy0iyf.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
