INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'25F0E9E8060646CEB20D364A602B4541', X'A4843A51AEEF427C902C7FB3BD670CD4', 17, 'A Winter''s Nap', 'On a cold winter day, Bear puts on his nightcap and decides to take a nice winter''s nap. However, it would seem that others in the Big Blue House have other plans for Bear. Ojo comes to Bear in alarm --- concerned about the sudden disappearance of her duck friends from the Otter Pond. Bear makes her a cup of cocoa and tells her about migration. Treelo takes Bear outside, telling him there''s feathers falling from the sky. Bear introduces him to the delights of snow. Bear finally settles down for the nap, but is woken up by Pip and Pop. They take him outside, where all the kids have a special surprise for him. Tutter''s been trying to take a nap too, but with all the noise, he finds himself just as awake as Bear. In the Shadow segment, Shadow tries to help Bear get to sleep. She sings "Rockabye Baby."', '1997-11-12', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
