INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'26097495DCBC4191AFE72C2896542EA6', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 49, 'Uncle Wally''s Snortleoutagus gag', 'Uncle Wally visits and tricks Big Bird by impersonating Snuffleupagus. The prank teaches about trust and the importance of being truthful with friends.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'260AF4005E42456894B92EC21724F5F8', X'573A556EED204222A12DB1B7779E1B18', 7, 'Faces in the Forest', 'Falling in love with the orangutans of Sumatra, Steve assists them in their rehabilitation process.', '1999-09-10', 44, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'261A11A46F564CA192A72F9838FDE9F9', X'871570B4BF2F4BA1994065FB932CB009', 3, 'Party in a Sweatbox', 'Kenya tries to make amends with Sheree following fiery conflict at Cynthia''s launch party. Meanwhile, Phaedra and Kandi have differing views on their friendship; Kim Fields meets the remaining ladies; and Kenya hosts a bash to launch her hair-care line.', '2015-11-22', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'261A43E951554B378E63B2831826D3F1', X'5DB3FF78E43948E18F67988ECBF85D17', 21, 'The Shipwreck', 'The Blue Falcon, after escaping, is continuing his reign of terror on the high seas. Dogtanian, still tired from his last attempt to catch the Falcon, and the 3 Musketeers are told to catch him on the Mediterranean and bring him back to France. Cardinal Richelieu is discussing the Musketeers plan with Count Rochefort, Rochefort suggests that he also takes a sea voyage to find the Falcon first.At the waterfront Juliette gives Dogtanian a gift, unseen by anyone Milady is watching, promising I will have my revenge Dogtanian, neither you nor your friends will ever see France again...', '1982-02-19', 24, '/uEnVTtVtbZFaZpew1d7UHZ9Z2id.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'261C6663F6F24078BE4F5D513010D26D', X'DF77DBA2BBDA4F3897138D5C856F852E', 5, 'Little Bear''s Trousers', 'Little Bear wakes up to find he has lost his trousers. After visiting his friends, one by one, he discovers they have all been using the trousers in very untrousery ways; as a sail for a boat, as a skiing hat, to carry bricks and as a flag. Little Bear is quite upset when he finally finds Bramwell Brown using the red trousers as an icing bag! But the cake Bramwell has made saves the day when it becomes a ‘Trousers Day’ cake and Little Bear finally gets his beloved trousers back.', '1993-10-31', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
