INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'266325F0951A48B39C39D6B00AB77632', X'ECB64EF34F8045A7B4A9C04434B02E35', 8, 'Silent Stars and Rebel Cars', 'Get revved up with the Pawn Stars as Corey checks out a 1940 Buick said to have been owned by Fidel Castro. Will he jump at the chance to own a piece of the communist''s sedan? Then, Rick is silenced when Charlie Chaplin''s driver''s license cruises into the shop. Will the rare piece of movie history lead to a huge pay day? And later, Chum puts his money where his mouth is when he takes a sudden interest in investing. Question is: will he end up with more money or more problems?', '2014-01-23', 21, '/uTPNzqcM0RKPgBn7j59cIny0HwZ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2673A77B869A4BF8818004029D8AF988', X'CEFD1496B6494C62AEF935A22558AC08', 11, 'Ladies Who Launch', 'It’s almost time for Kameron’s Sparkle Dog Launch Party and Dallas’ who’s who and best in show are dressed to the canines to step and repeat, get their first taste of the bright pink kibble, and even stop at the Pet Psychic for a quick read. But before we get there, D’Andra has a meeting at the cosmetics lab only to find out the main ingredient for her new snow algae skin care product won’t make the launch deadline, which will jeopardize Dee’s final decision to hand over the company. Meanwhile, LeeAnne has a meeting with Brandi, urging her to make Stephanie choose Brandi and loose Cary. And at the party, while Mark confronts LeeAnne about saying he frequents the gay bars, Cary confronts Brandi about telling everyone she was Mark’s nanny. Why is Brandi behaving more and more like LeeAnne?', '2017-10-23', NULL, '/eOHKuGK5whGloP1XtRZ1Iief7x3.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
