INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'26CB7BD6A3AC4796ACF896BB7AD96FED', X'18DA994319634E04A7A0AE63802BB1FA', 3, 'Tres Amigas', 'Kelly’s argument with Vicki continues; Tamra and Vicki fly to Mexico for a girls weekend to help break Shannon out of her shell; a night of dancing on the bars ends with a real injury and the trio opening up about their real vulnerabilities.', '2018-07-30', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'26CBB444D03648CD943528995635A2B2', X'3087A3EDE94E42769D02A78183DEA1D3', 18, 'He''s Stalking, I''m Walking', 'After being teased by the women in Vegas about whether or not she''s pregnant, Porsha waits to take the test until she''s home in Atlanta with Kordell. NeNe travels to NYC for a whirlwind press tour to promote her sitcom, while Kandi''s stretched to the breaking point with renovations of both her business and her home. Kenya thought she had extracted Walter from her life, but the men keep inviting him around; the talk soon turns ugly and rumors begin to fly.', '2013-03-17', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
