INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'26E06015EE2C4F6D80E4D48A437FF649', X'7DA1B69304D14168A0A09715407C04C6', 21, 'Big Top Norman', 'Norman creates his own big top circus, but a trick involving some sheep goes awry when they escape into town.', '2016-07-16', 10, '/3qd0Xm76WFC6MflzcGThAyQNUFg.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'26E20845DDF643B29281FA649E655215', X'BBFEE3B49C9548A6BEAA791FA08B1F43', 10, 'Episode 10', 'More than half the population of Sri Lanka follow the teachings of the Lord Buddha, which began nearly 600 years before Christ was born. The monks start their training when they are very young, as Peter discovered when he met The Rev Wimela - aged 10. Like most children Wimela has lessons and homework - but not many 10-year-olds have their heads shaved every three months -Buddha teaches that long hair leads to vanity!', '1983-10-13', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
