INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'26EBC3CC047E4CADAD7BA2652F0F30A1', X'68138DE20900460AB58E480688F1E081', 7, 'Back To Nature', 'Bear gets a new Spanish-language tape in the mail, but just as he''s about to try it, he''s waylaid by Tutter, who, it seems, has a touch of laryngitis. He cant talk at all. A concerned Bear gives him a small bell to call him when he needs some-thing, and Tutter keeps bear running back and forth his Spanish lessons with Pip&Pop to a misunderstanding between Ojo and Treelo. During the course of Bear''s busy day, we discover how to communicate with words and without them.', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
