INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'26FE7641668244649B23AF0089F3FA04', X'98D80972E53A43DDA03A7703465E6F87', 5, 'Lord of the Ring', 'The Pawn Stars say their prayers when a guy brings in a ring believed to have been owned by a Catholic Cardinal. A symbol of status and power in the Church, does Rick see a chance for cathedral-sized profits, or lose faith in the item''s worth? Then, a woman pops in with a collection of four antique pistols from the 1800''s. Will the guys load up a giant offer, or is this deal shooting blanks? And later, Corey and Chumlee remember their own high school days when they check out John Wayne''s yearbook. Can this deal be voted most likely to succeed, or will the seller look like the class clown?', '2012-11-13', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
