INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'273C5691793C48F795CF0E51B955FE3F', X'C01DDD2ABDB14C978D0458F791EF1C24', 26, 'Playtime', 'You know what they say about all work and no play.  Thus the Kratts take a break at Animal Junction, playing with lion cubs, serval kittens, ducklings and, yes, children.', '1999-06-25', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'273D66DB185446C4B8BE93BD320DFE9C', X'DBD3583FE9B246D1A37E309EB666E233', 14, 'No Bones About It', 'Fresh off of their emotional trip to the orphanage, the ladies find themselves in a place of peace and harmony with one another. They get a taste of authentic African culture, visiting a local museum and a not-so-traditional herbalist. Later, they bond over sex talk at NeNe and Marlo''s cozy pajama party. But the good vibes are short-lived. Cynthia and Kandi make comments about Kim that bother Sheree so much that she decides to report back to Kim about this "betrayal."', '2012-02-19', 43, '/iiDbghI1HRX5fxapaza7kbs8idU.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'274071E7329148E79FAC02783A797A22', X'83D1C2FB7CD949779A5D98D36CFB59D3', 11, 'Episode 580', 'Grammy Award winner Bobby McFerrin sings ABCs with Hoots the Owl.  The Two-Headed Monster learns to blow bubbles.  Maria and Luis try to reminisce about their wedding.  Betty Lou sings the "Amigo" song.  "Sesame Street News" correspondent Kermit the Frog reports on London Fog.  Ernie and Bert leaky faucet skit.  Cookie Monster sings about subtraction.  Placido Flamingo performs a "Lost Toy Opera" with Big Bird.', '1988-12-05', NULL, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2740D33EDE41440FA7A65364EBC98368', X'B054AFF3548C4F56B372B1EA26613ABB', 4, 'Mister Rogers Talks About FRIENDS', 'Mister Rogers arrives with a fife which he has borrowed from Joe Negri. Expressing how difficult it is to play the fife, Mister Rogers takes viewers to the kitchen where he has a row of bottles set up. Using these bottles, filled with various amounts of water, Mister Rogers is able to play Tree Tree Tree.
