INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'276C1407A81F4A9B852BE402123D5A00', X'C13CAC4525544775BB86C6AA65C1CA2E', 4, 'Suburban Killers', 'Not all dangerous creatures live out in the wilderness of the forests, the jungles and the Outback. Some of them live in the homes of suburbanites in Australia. Steve examines some of the venomous snakes and spiders that can make unwelcome appearances in suburbia.', '1997-04-26', 44, NULL, '2026-04-03T17:39:10Z', '2026-04-03T17:39:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
