INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'282D9B21B2AB4EE2B3019285C0772C85', X'698A60DF8ED44CA9BCB1EBAB343DACDD', 12, 'The Airport', 'On a flight to NYC, Jerry has a first-class time, but Elaine suffers in coach. Meanwhile, Kramer and George try to hit the right airport.', '1992-11-25', 24, '/eKQ6GEq6I9tffPjkhw2dARszVs.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2834056433144BB78C768495A55A9FA8', X'79C64E0A348841BC9B5C2243FF15B373', 3, 'A Match Made in Beverly Hills', 'Boz takes the group’s single status into her own hands and hosts a speed-dating party. While Dorit shows off her charm, Erika gets stage fright in front of the bachelors. Kyle opens up about finding love after her separation. Rachel encourages Sutton to embrace her old self post-annulment. Dorit gets financial advice from “Money Queen” Amanda.', '2025-12-18', NULL, '/v2mgE6aZ3NWp58tWzW4q5bZHwGj.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'283799ECCEF44E21BE7A8A44688ACE17', X'17E6CC8EDCF34CE697DB5A9FC8E31EB5', 17, 'Game Over', 'Angela and Charles throw a gala draped in elegance, but with secrets swirling, tensions brewing and an unexpected guest invited, the night is anything but buttoned up; Porsha leans on loved ones as she mourns her cousin''s sudden passing.', '2025-06-29', 42, NULL, '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'283C73BAA578468FBA2C04D72B58F2B3', X'B6BAA6EC09084A4790017E7158985002', 6, 'Wet All Over', 'Arnold and Wanda are due to give a report on the town waterworks. But Ms. Frizzle thinks it''s field DRIP time! She turns the bus and class into water drops and the kids evaporate, condense, become rain and rush by river into the ocean. After several trips through the water cycle, they''re ready to turn back into regular kids. But the magic key that will get them out of the cycle is locked in the school bathroom! Trying to work their watery way into the bathroom, the kids go through the town waterworks and see how water is purified. Can they get to school through bathroom pipes? Or are they stuck in the water cycle forever?', '1995-10-14', 25, '/zW5qKlnyk0ifaXcdAkBXCBFweZm.jpg', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
