INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2859E46733CA42E8978D2585A447EDC9', X'C7FFC8DF467147E3A11B606828BCB508', 10, 'Salud', 'Walt''s family worries when he doesn''t turn up for Walter, Jr.''s 16th birthday. Jesse is forced to put his lab skills to the test without Mr. White''s help.', '2011-09-18', 48, '/dBrs0Npmn76g81yel2mjK7mTaOj.jpg', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'285E835C7B154984901A6DB2611EF142', X'DA06465B91544FEBA455374DF7DAB02F', 12, 'Telly Learns The Grouchketeer Cheer (4094)', 'The Big Bad Wolf feels so exhausted from having to chase pigs and dress up like a Grandma all the time that he decides to take a vacation.  In the meantime, Zoe, Elmo, and Telly audition to be the temporary wolf.  The three of them first have to blow down a straw house, then chase pigs, and lastly, pretend to be Grandma.  All three of them creatively think of different strategies to pass the test.  They all then begin arguing over who could best play the role of the Big Bad Wolf.  Gordon talks to them and helps them to realize that it’s more important to stay friends than to be the wolf.  When it’s time for the Big Bad Wolf to decide, he gives the role to Gordon since he did such a great job showing Telly, Zoe, and Elmo how to do everything that a Big Bad Wolf should do!', '2005-04-19', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2861F08EF8F8407FA7C7A57FDB095282', X'BCAB920A51A54CBBAA5941578A0EB005', 12, 'Feeding a Need', 'After a tear-filled Mexico trip, Lisa Rinna confronts Eden over the “near death” accusations. Lisa Vanderpump buys her son Max a condo, and the scripted show inspired by Kyle''s childhood becomes even more of a reality. Lisa Rinna is honored with an award from her favorite charity, but Dorit has increasing suspicions about what she sees as erratic behavior from Rinna.', '2017-02-21', 43, '/8eGwyHk4RgcUqCSCqWvw9nChjbz.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'28655221F87F4EACA31B142A60F0906E', X'D1863F2F02EC40CEAF64DB03FBE518A7', 13, 'The Princess Story', 'Rosita helps Abby and Zoe think outside the ''fairy tale'' box as they imagine and make up a story together. Also featuring Cookie Monster''s Star Smores parody, and Elmo the Musical-prince. Brought to you by the letter P and the number 4.', '2016-04-02', NULL, '/qrFJ9lUOnZzMiEWnaTTdXpHpdzU.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
