INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'28A2C41F3B7741BB91E03301F7D6B6C7', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 12, 'Caves', 'Caves come in all different shapes and sizes depending on how they were formed. Spelunkers (people who explore caves) have plenty of descriptive names for caves and the natural rocky features that form within them – soda straws, fried eggs, popcorn and draperies are just a few. Caves can be as simple as one straight passage with a few stalactites overhead, or as complex as a labyrinth, with many stalagmite-carpeted rooms.', '1998-04-25', 26, '/wbKGPtG5ADg50dkR2FbTXQHInBv.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
