INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'28C789537C14446E8E6561BA30C57DBA', X'4B2A19E02FAE492EBC31F78E63D88EBC', 27, 'Pawn Patent', 'Space out with Pawn Stars when an autograph of astronomer Edwin Hubble takes a starring role. Will Rick hitch his wagon to this star or keep his feet on the ground? Next, an 1850s patent model self-lighting and extinguishing lantern flashes into the shop. Will Rick light up an offer or will the deal go dark? Then, a Starrett Food Chopper slices in. Will Corey dice up an offer or will he get cut? And later, an 1871 British Martini-Henry Short Lever Rifle bores into the shop. Will Rick shoot off a deal or will he misfire?', '2017-01-30', 21, '/pZO0OtQ9u5P4JiYJXBR136LCq7E.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
