INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'28D5D8E875624685AABD878FAD53853F', X'42E591E22A884434AE9F3D4B1D685613', 17, 'The Chum-Sake', 'Print money with the Pawn Stars as the guys check out an entire sheet of test notes. Made when the U.S. Mint was testing a new printing press, will they see dollar signs, or is this funny money too hot to touch? Then, Corey and Chumlee have to duck and cover when some poleaxes swing into the shop. Used in Medieval times to dismount horse-riding soldiers, can they land a deal? And later, the guys try to give Chumlee a new nickname, but can they make it stick?', '2013-08-08', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'28D82BDE2F2C4841B77B57BDBA39C4F4', X'95CA8B6FCCBC431A9D959B23367BBFED', 17, 'A Tale of Two Accidents', 'At Kathy''s spa day, Erika reveals a shocking story about her family, leaving the group with questions. Meanwhile, Crystal works on her big-ticket basement renovation and Garcelle moves one step closer to finding Mr. Right. Dorit’s wedding dress launch is anything but happily ever after, as Sutton and Erika come face-to-face and Garcelle has to answer for a provocative comment.', '2021-09-15', 43, '/ukZSY4VumoGKNq5DCkt6qk04n75.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
