INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'28F1DEECEE954BE1A5E1395C89D4D2AD', X'332249FA796B4F92B7F8421D523B0BDC', 13, 'A Rum Punch to the Gut', 'Sanya attempts to redeem herself from Sheree’s birthday party backlash with a fun couples trip to Jamaica. Just as she and Kenya forge a new bond, however, Marlo and Kandi’s friendship appears to pass the point of no return.', '2022-08-07', NULL, '/vJfuPjacpIjUIWr7Y4D31PTv8eu.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'28F2C22234884198A59D7D99C557E2BD', X'5B2C93657BD94CA1A3FB15F1A024A56E', 5, 'Careful, She Bites', 'Bethenny serves up healthy culinary pointers to Alex, but events turn sour when romantic problems are disclosed. Elsewhere, Alex basks in a birthday bash on a yacht; and Ramona''s daughter preps for a school dance.', '2008-04-01', 60, '/1T3VJKAE2MQjkEXZ6UyhacA30Kc.jpg', '2026-04-03T16:35:21Z', '2026-04-03T16:35:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'28F5EB7A7A0948CC9BBA1E09436E5FCB', X'ECB64EF34F8045A7B4A9C04434B02E35', 28, 'Tee''d Off', 'Tee off with the Pawn Stars when a USGA Rules of Golf book from 1934 putts into the shop. Will Chumlee be able to drive home a piece of golf history or will it turn out to be a bogey? Then, Rick deals with some "sweet emotion" when he checks out an organ owned by Steven Tyler. Will he be able to cash in on this high note or will he "dream on?" And later, Chumlee takes a big swing at golf after he and Corey make a little wager. Will the odds be in his favor when he gets help from legendary trainer, Butch Harmon, or will he be too deep in the rough?', '2014-04-03', 21, '/jAAzpISoVqp51xIc3fDFX43PWHF.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
