INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'290491F6B13B4AB5AA093D42D5C2C0F6', X'E48599F866FF4C0F927465B9AE1CDA9E', 14, 'Episode 14', 'Including a report from France, in which LESLEY tells the story of the Burghers of Calais and how 600 years ago, six brave citizens walked out of their besieged town to face certain death. Their dramatic exploits made them national heroes.', '1976-10-28', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
