INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'293DDCEC0985495D9A05AD207AF93229', X'6F731E6BD3C54DE684E17A19CB650E86', 21, 'Titanic Pawn', 'Be the lookout with the Pawn Stars when a 1906 Silver Half Dollar that belonged to a passenger on the Titanic sails into the shop. Will Rick make a first class offer or will he be sending out an SOS? Then, Rick''s leading a double life when a first edition of "The Strange Case of Dr. Jekyll and Mr. Hyde" transforms in the shop. Will he unravel the mystery and make a deal or will it be a split decision? Then, Rick gives direction when a 1936 Zeiss 16mm camera rolls in. Will he focus in on a sale or will he cut it loose? And later, a Howard Hughes plane altimeter takes off in the shop. Will Rick land the deal or will he just wing it?', '2016-01-06', 21, '/39V9xUCKDRizUnVsWkKujw20nZk.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
