INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'29C5253899C7407985A9F007CBBFE564', X'23C93536610C41C5AC6BA6B243423258', 1, 'A Crash Course in Deflection', 'As news spreads of Karen''s car accident and DUI charge, the ladies rally around her, but not without asking a few probing questions. Wendy closes an important chapter in her life. Ashley meets with a lawyer to finally take the next steps toward divorce. Mia navigates co-parenting with Gordon, but her unique family dynamic leads to a big conflict.', '2024-10-06', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'29C5A0EAF5AF434199C4A74AC3601453', X'1D713CA64E174F84949C8CFD98514127', 36, 'Flying High', 'Get ready to rock with the Pawn Stars when a guitar signed by bass player Garry Tallent strums into the shop. Was Corey "Born to Run" with Bruce Springsteen''s bandmate''s guitar or will the deal leave him "Dancing in the Dark"? Then, Rick examines a replica of a 1964 Peace Dollar. Will he be able to cash in on this infamous coin or will he strike out? And later, inspired by a fragment of a Fokker T-2 plane that comes into the shop, Rick challenges Chum to a paper airplane contest. Will the guys be able to get their planes off the ground or will it be back to the drawing board?', '2014-12-04', 21, '/AoUpFl3GOfcqIASJtPIWUwWAWyw.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
