INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2A2E7B17328545098E0661A9367AC097', X'3EE646E823AE4DECBBC6C7E6A210D55B', 108, 'Telly and Oscar write', 'Oscar is weary of hearing the "Sesame Street Theme" every day and wishes they''d come up with something better. Telly happens to have a composition ready and sings a song all about saying "Hi." Oscar reads Telly a book he''s written to combat all the nice stories they always hear.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2A2F95DF4CC94897BA55667A1395683D', X'5C1B881FAC584D72B63F209952D4F902', 2, 'Episode 2', 'Fit for a Queen  A teddy made of chrysanthemums, a koala bear with a plum for a nose and an owl sitting under a banana moon were just three of the hundreds of stunning floral displays admired by Her Majesty The Queen when she made her first-ever visit to Westminster Cathedral for the International Year of the Child Flower Festival. Blue Peter film cameras were there to record this historic event and so were nine Blue Peter viewers aged from five to 16 -winners of the Flower Picture competition.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2A301AC8F0694B71A74E437DB226B4D9', X'4D2CAC0F38FD438B8AFAACF43952E535', 158, 'Episode 158', 'A magazine programme for younger viewers. Introduced by Christopher Trace. Including Blue Peter Alphabet: E for Engineering. The Fly Who Wanted a Tail, a traditional Russian folk-story told by Elena Snow. How to Build Your Own Model Theatre.', '1961-11-06', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2A3D6C0C37CE486DA33F8EA6C3375135', X'136B81D3964D4B8FA21492F00D96D6B9', 68, 'Episode 1903', 'Telly frantically tries to retrieve a kite stuck in a tree, eventually learning from Luis how to solve the problem with a ladder. Oscar reveals he spent the morning deliberately getting the kite stuck, causing mischief as usual. The group learns about teamwork while preparing soup, and Big Bird helps Telly count place settings for his monster birthday party using a clever trick.
