INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2AFBD0D4B84B4BF5B19A1137A29C0C30', X'9D74600D722247C1BD1B635F5B41B7D1', 1, 'Animal Cafe', 'LeVar goes to a 24-hour diner to look into night jobs, and profiles people who have occupations in the evening and early morning hours, like radio DJ''s, bakers, cab drivers, and police officers. In a separate story, a man ventures into a cave to see bats and other nocturnal animals. Martin Short narrates the story of "Animal Cafe," about a cat and dog who operate a third shift restaurant for all the animals in their neighborhood while keeping it a secret from their human owner.', '1986-06-23', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2AFBD6F370A6409686384DE0B8F1AB55', X'F07B879456254682AAE1E56966B4C7A8', 11, 'Hello, Maggie', 'Kiki’s cousin Maggie visits from Mexico. Even though she only speaks Spanish, the other kids learn that friendship and communication can develop through gestures and a few simple words. Nuzzle gets trapped in a dollhouse. Leon and Jody do not appear in this episode.', '1996-01-29', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
