INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2B4F57A20FFE495C9BF6C0A3C77FA342', X'05FA5E1878D241FEAE300C242C7FFB6A', 2, 'Twist of Fate', 'Station Officer Steele takes Norman and Mandy Flood pot-holing, but he soon ends up in a tight spot.', '2003-04-01', 10, '/aG0LnQyEg3wBU1Om5M6vfSg7v6w.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2B5199A9AE5F4E5DAB09A886C171B038', X'02849655BD954D8DAF3B03321918EEEE', 23, 'Madeline and the Tea Party', 'The girls are planning a spring tea in honor of Lord Cucuface and the trustees when Sugar Dimples, the child movie star, drops in to visit and takes over, turning their simple party into a major "Hollywood" production, with over-the-top results. It is up to Madeline to bring the party down to earth and remind Sugar Dimples that it is the company that counts, not the lavishness.', '2001-02-07', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
