INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2B59C217E15947948A8BB8B41920B085', X'F30BBF8187704E74B68B280E7C85B52F', 6, 'The Statue', 'Jerry has a box of stuff his grandfather left him. Inside is an interesting looking statue that could replace one George''s parents had years ago, but he broke. George plans to pick the statue up later but in the meantime he tells his parents about the replacement statue. Meanwhile the boyfriend of a bitter Finnish author (whose latest work Elaine is going to edit) is going to clean Jerry''s apartment. When Jerry returns to his apartment it is cleaned beyond reason. Later when Jerry and Elaine are at the author''s apartment, they see the statue on her mantelpiece. Getting it back may jeopardize Elaine''s chance at being an editor, but save George from his parent''s wrath.', '1991-04-11', 23, '/y9bT1IQX4DUfizADWxGVvl39z4h.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
