INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2C74668B1CF44CB690CC4107E54153B3', X'C01DDD2ABDB14C978D0458F791EF1C24', 4, 'Who''s in the Hole?', 'A flying squirrel glides in looking for a hole to live in, and a search around Animal Junction reveals lots of other animals, from foxes and rabbits to snakes and porcupines, already living in various holes. When a man starts to cut down a dead tree with a hole in it, Jackie stops him by explaining that it may be the home of an owl.', '1999-01-28', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2C78930A747A4144A57D4BCAA33FA88F', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 68, 'Ask Oscar about discussions', 'Telly asks Gordon if he spends too much time worrying. Gordon assures him that he just happens to feel one feeling very strongly and everyone does it, especially the Heartstrongs... David happens upon the day''s Grouchketeer meeting, where Oscar has prepared a lecture on the four basic Grouch food groups - sticky, gloppy, oozy, and noisy foods.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2C7B0E80E61D43288A06D588E1669E0C', X'5A6D9A42165B4B5692730A06874DFE10', 20, 'Madeline at the Louvre', 'Madeline paints a magnificent picture and accidentally leaves it at the Louvre, where it is mistaken for a masterpiece and hung next to the Mona Lisa, upstaging DaVinci''s creation. Madeline tries to get the painting back, but one believes that she is the anonymous artist. In the end she finds she must use her feisty individuality to prove herself to the authorities.', '1993-12-12', 30, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
