INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2C83D6A9FB9D4826A93EA9B1D9C20AC4', X'63F9BF6D39B344F4B885A56807277A80', 18, 'The Muppets Go Hollywood', 'When Kermit the Frog throws a glamorous party at the Cocoanut Grove nightclub to celebrate the premiere of the Muppets'' first feature film, The Muppet Movie, hosts Dick van Dyke and Rita Moreno interview the wide array of celebrities and Muppets who attend the event.', '1979-05-16', 49, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2C842A7AE851460AA5EA1FAB0AE8CC79', X'262E8E7CFA784578A216ADD6F184C4D2', 5, 'Wife #3 Hits Sin City', 'It''s Wife #3''s turn with Kody! Christine and her kids head to Vegas so they can spend time some alone time with their dad in her favorite vacation spot. Meanwhile back at home, Meri decides to take the rest of the family out for a bowling night.', '2011-04-10', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2C895ACC512742D0B2D1DD39086AD4FA', X'650BAC937B5941FCB277DC6F8BDCD7BB', 12, 'Pitch Imperfect', 'Axl begins to panic when he realizes that he only has four months of college left before he graduates, and he hasn''t sent out any job resumes - something he should have started when he was a junior. Meanwhile, Brad agrees to lead Sue''s no-cut a cappella group as they enter a music competition, and Brick desperately asks for Frankie and Mike''s advice when girlfriend Cindy tells him that he reads too much, and if he doesn''t stop, she''ll break up with him.', '2017-01-17', 22, '/KJhQINEMwgO37htYcf03P49mJB.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2C8ABF9AA6964F31B87CACD908BEF755', X'D0E5568D939D4D89AB4EC291A90691CF', 9, 'The Robot', 'Kipper is waiting for Pig and Arnold at the duck pond when a small friendly robot clanks out of the water. At Kipper''s house it tries a piece of bread, a milk shake and some chocolate cookies but when Kipper introduces Hippo, to his horror, the robot eats him too! Happily Kipper and Hippo are reunited at the duck pond.', '2000-11-23', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
