INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2C97C255913A4A6EA64B179E2E8BF5F6', X'119C16D5104745EC8242C72A8EED423B', 17, 'Arthur Babysits', 'Arthur has plenty of gripes about his past babysitters, but soon finds himself trying his hand at some babysitting of his own. He ends up having the Tibble Twins'' Grandma ask him to babysit the infamous Tibble Twins and he agrees to the job. Despite the warnings from both his friends and D.W., he takes on the task and quickly finds himself overwhelmed. After some quick thinking, and a willingness to keep at things, he comes up with a plan.', '1996-10-17', 13, '/jbsz1PEQP1w4jt5HXoq7uYik7ty.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
