INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2D00FD1BA36F4096A4A0294193CEA85C', X'4EB9B495796241D9BA8A3BED48D9BCC6', 10, 'Treats!', 'An advertising Dream Team - creators of the Lions'' favorite ""Wheaty Meat Treats"" spot - is hired to create a commercial for the library. But it seems the team needs a little help. Guest Starring Vanessa Williams, Oliver Platt, and Jon Stewart.', '2002-11-18', 30, '/iJ1nSj9dQNY8KVtBKBcNjuqCdpB.jpg', '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2D0122D6B0454EE5943C4473B903BD99', X'F9A8D8B3D72E437EA9D57477F6D64DF8', 3, 'Kind Rudy', 'Elmo and Rudy are helping Abby out in the garden because she hurt her wrist, and Rudy wonders how else he can help, too. What if he holds the door for Chris, who is holding the bag of soil, waters the flowers, cleans up paint left out at the community center, and makes a get-well card for Abby''s wrist? Just because some things are done doesn''t mean you can''t help. There are so many ways to be kind!', '2022-11-17', 26, '/itOtHUYFLvO2Fmo6jORxM72amp5.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
