INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2D142CDB279546C19A0A97F1B72EC530', X'B753871204CE43A6916362280BBB084B', 5, 'Barkely Does Not Want To Take a Bath (3855)', '', '2000-01-07', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2D19DB2FD8554B73964436C864F26F16', X'AE8F64D94B834147A44CBFE720381F8E', 3, 'Baby Bear is Afraid of Bees', 'Baby Bear and Abby are near a garden when a bee flies by. Baby Bear is filled with panic because he is afraid of bees! Chris reminds him that they are usually harmless when left alone, but Baby Bear doesn’t care; he wants nothing to do with them. Abby suggests granting Baby Bear a wish so that he isn’t afraid of bees. Abby points her wand at Baby Bear, but Chris, who is standing close by, also gets hits with her magic. Baby Bear and Chris both turn into bees! Oops! Abby doesn’t know how to fix the spell. As Abby calls her mommy to find a solution, the bees put Chris and Baby Bear to work! But they don’t understand what they need to do—how do bees help flowers? 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2D1BE4C9A76C4C318CB930605B1104DF', X'BBFEE3B49C9548A6BEAA791FA08B1F43', 16, 'Episode 16', 'Blue Peter''s silver tabby, Jack, will be in good company today, meeting champions who''ll be competing in the chinchilla, silver tabby and Smoke Cat Society''s 75th Anniversary Show. They include Premier Marisha Simpatico, or Tico for short, Grand Champion Andarphils, otherwise known as Cleo, and Saleila Prima Donna known to her owners as Prima. Discover what makes the champions purr - and what goes on behind the scenes to produce a real live Top Cat!', '1983-11-03', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2D1F96F3DF2143E5ADCC9EFA1ADA13E7', X'4861CE46904543C7963F27B4EA539804', 48, 'Episode 178', '', '1971-01-13', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2D243866043F49EB8E5BC880019B3950', X'02C86AE38C3B4CC08E1F0B27D01DCD91', 7, 'Best of Enemies', 'After DeShawn''s failed attempt at reconciliation, Lisa''s on a mission to get the ladies into the same room. She meets Kim and Shereé for lunch. Humbled by her less than stellar fashion viewing, which went on despite not having any actual samples to put on the models, Sheree turns to successful Atlanta designer Michael Knight of Project Runway fame, to advise her on where she went wrong and what to do to get it back on track. Lisa is trying to put on a brave face for Ed, now that he''s signed with the Oakland Raiders, but is worried that her "best friend" will be a continent away and back in the brutal world of NFL football. Meanwhile, DeShawn''s husband Eric is at home with an injury, and after 13 years in the NBA, he''s considering retirement, which could mean an end to DeShawn''s extravagant lifestyle. The five ladies and their families get together for dinner, but can they put aside the injuries and start to heal old friendships?', '2008-11-18', 43, NULL, '2026-04-03T16:34:44Z', '2026-04-03T16:34:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2D28571D0B1A4A5E84D005A853DF9C8B', X'63F9BF6D39B344F4B885A56807277A80', 23, 'Lady Gaga and the Muppets Holiday Spectacular', 'A holiday extravaganza features Lady Gaga singing tunes from her 2013 album, "ARTPOP," and performing with Kermit the Frog and other Muppet favorites. Also included are duets with Elton John, Joseph Gordon-Levitt, and RuPaul; an appearance by Kristen Bell; and renditions of seasonal classics by the Swedish Chef, Beaker, and Animal.', '2013-11-29', 90, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2D342B74FA8E42B7A4C56FE14C0E4D3F', X'AC068B8E80F646BFAFB2DCEBCF76DC36', 3, 'You Don''t Match', 'Ben’s lack of exposure to diversity causes him to assume that Tim can’t be Leon’s cousin because Tim is too fair-skinned. When he learns he is wrong, Ben’s openness in accepting his mistake helps his view of the world grow as he discovers that even people who are the same race have different colors of skin.', '1998-10-21', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2D3740E146A34531B2EDA82312BFCC8C', X'78A02D50E3DC4549844A3CF357A32EF4', 22, 'Reunion Part Two', 'Kenya reflects on her complicated relationship with Matt and confirms the status of where things stand today. Phaedra gives updates on the status of her divorce with Apollo and brings proof to make her case. Shereé calls out Kenya for constantly adding fuel to the fire and in an emotional confession, Shereé reveals more heartbreaking details surrounding her tumultuous marriage with Bob.', '2017-04-23', 43, '/fbBqWQ1guO1sdslNaDwoQj8Jq9z.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
