INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2DB36299F4A24E6A909AFF9BE6EDC91E', X'7BC54DF3F32A454EAEF6A9436C35D53B', 52, 'Birth of Prince Tuesday', 'Rogers talks of being able to do certain skills at certain ages. Meanwhile, the Neighborhood of Make-Believe is abuzz with excitement, as Queen Sara gives birth to a prince named Tuesday.', '1970-04-14', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2DB52F38AACB4334BD1D6A03C974A07E', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 12, 'There’s An App For That', 'Baby Bear is ordering a bowl of porridge at Hooper’s Store when Telly comes in bouncing on his pogo stick. As he’s practicing the boingarooni, the hardest pogo trick, Mack, the pogo salesman, bounces in and tries to sell Telly and Baby Bear an iPogo stick. With an iPogo, not only can you boing without ever falling off, you can do almost anything- make a phone call, take a picture, and cool off hot porridge! Telly agrees to exchange his old, beloved pogo stick for a brand new iPogo. When he tries it, the iPogo seems to do everything but boing. Baby Bear uses the manual to figure out that they need to press a hexagon icon to get the iPogo to boing, but when he tries that, it ejects Telly right off! Then, they try a triangle icon, but that shakes Telly like a milkshake. Telly finally does the perfect boingarooni, but is disappointed because the iPogo did it for him. Telly asks the salesman for his old pogo stick back and everyone celebrates as Telly does the boingarooni all by himself!', '2010-11-03', NULL, '/dRXqLgpGa3TUTZHxAMM5i9Judug.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
