INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2DEDA9B9B3AA46F2A68CB879C2577ACA', X'5144DE59E67F4FCF919B7106989AB797', 30, 'Practice Makes Perfect', 'While nearly all the kids are sick with chickenpox, Skye finds a guitar and wants to play it, but he is slow to understand that he has to put time and effort into becoming good at it. Sizzle tries playing billiards. Ben and Julie only make cameo appearances.', '1995-02-24', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2DF16FA4B3D84B8384EB767E03456EE1', X'E6EA14319E67463783AEA11073E8C7E0', 9, 'Busted BBQ', 'Lisa Vanderpump takes a tour of the space Ken wants for a new restaurant. Meanwhile, Eileen flies to Italy to spread her sister''s ashes; and Kyle hosts a barbecue, where dramas sizzle over Yolanda''s claims, plus a 20-year grudge rears its ugly head.', '2016-01-26', 43, '/ogH6tdN2nVT1vDCN95Jmyn6mSIx.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
