INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2E1F86E6EA584453AB45BFCE74DAA82D', X'936491E2AB834E1FB5C72C03F6461D86', 3, 'Summer Story', 'During the harvest season, Lord Woodmouse and Primrose go picking blackberries, while Wilfred looks for adventure by trying to find a creature called The Weasel. Primrose and Wilfred get lost as they explore the wilderness, so all the other mice send out a search party. The search party finds Primrose and Wilfred, so they all return home.', '1997-08-25', 25, NULL, '2026-04-03T16:14:06Z', '2026-04-03T16:14:06Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
