INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2E2A8424D51E4F498ADB2805A4542B2A', X'B6A0F2287DDC409CB808681B777A6704', 14, 'Mister Rogers Makes an Opera', 'Rogers finds a bubble-making machine and a knitting machine at Bob Trow''s workshop. Mr. McFeely shows a video of how people make sweaters in a factory. Reardon also visits the Neighborhood of Make-Believe. Lady Aberlin decides she will be a sweater-maker for an upcoming opera.', '1980-05-29', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
