INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2E3033AE08A74548A2B1F182AB82B816', X'05C0E384194C44179F62803EB615E409', 120, 'Rain on the day of the fair', 'It''s raining in the neighborhood, so Rogers brings in his umbrella. The Neighborhood of Make-Believe appears sad because the rain there is threatening to spoil the street fair.', '1968-08-02', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2E3711C6AA994EF687D88AAFC20F9B14', X'4C79C0B621A442778967BE1E791EFDBE', 20, 'Pingu and the Rubberband Plane', 'Pingu is on his way to school with his toy truck when Pongi catches him up. Pongi is carrying a box that contains a model plane powered by a rubber band. Pingu goes to touch the plane but Pongi quickly shuts the box and walks on. Then Pingg goes past, carrying a long thin box, and Pingo also goes past, bouncing on his pogo stick. After seeing these toys Pingu is quite envious. At school, they’re all playing. Pingu is playing a game of “catch the fish” with Pingi, Pingo is bouncing about on his pogo stick, Pingg is playing swing-ball and Pongi is flying his plane. The schoolmaster has a try at “catch the fish” and gets one. Just then the plane flies low over his head and lands. Pingu goes over to where it has landed and picks it up, but Pongi rushes over and grabs it back. He then relents and lets Pingu hold it. The schoolmaster comes across to look at the plane and breaks the rubber band, so he goes to his box and gets a new one. He then gets distracted, so Pingu tries out the plane with the new rubber band. It doesn’t go very far, so Pingu gets a bigger one from the rubber band box and tries the plane again. It still doesn’t fly very well. Pingu then finds a very big band in the box and wants to try it, but Pongi doesn’t want to. The schoolmaster then tells them all to sit down, and starts the lesson that is on how to draw a circle. Pingu isn’t doing very well, but then he has an idea and pretends he wants to go to the loo. When the schoolmaster says yes, he sneakily collects the plane on the way, fits the very big rubber band and tries it out. The plane zooms round the classroom, disrupting the lesson, then zooms off, with Pongi and Pingu in pursuit. It then buzzes around Father, who is out on his motorised sledge to make a delivery, and twice he nearly crashes into the fish stall trying to avoid it. When the plane finally lands Pongi grabs it. Pingu catches up, and Father sees them. Pingu explains what he’s done, and Father takes them both back to school. At school the schoolmaster is still trying to teach how to draw a circle, but he’s not having much success. When Pingu and Pongi arrive, the schoolmaster tells them off and confiscates the plane. Then Pingu has another idea. He attaches the plane to Pingg’s swing-ball and sets it going, and it flies round in a perfect circle. The class then use the method to draw their own circles.', '2006-02-23', 5, '/xClBG592XaQn9WvzZhROtr2lBi.jpg', '2026-04-03T17:22:21Z', '2026-04-03T17:22:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2E3BE49CFBF2451F976AE3DB5792F02F', X'151E88A195764BD1B84AC4D64C1C9FE8', 17, 'The Girl With the Diamond Earrings', 'The ladies hit the slopes in Aspen, where Dorit proves to be shaky on her skis. Sutton goes snowmobiling but is really revved up about Diana. Garcelle broaches a very touchy subject with Erika at dinner. Back at the house, Rinna wants everyone to chill out, but things get heated when Kyle and Crystal confront Erika about her perceived lack of empathy.', '2022-09-07', NULL, '/zqALNzRtYz9ebQgAEU5qs3vGEo4.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
