INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2E54989348264784973CCF46A335E462', X'CA19F89515144988A70995E84EAB7CEE', 21, 'Wanted: Pawned or Alive', 'Rick is ready for some football when a Super Bowl bucket hat rushes into the shop. Can he score big, or will he fumble the deal? Later on, Corey and Chum turn green with envy when Spencer brings in an Incredible Hulk comic book. They give their strongest offer, but will it get smashed? Next, a set of Snow White and the Seven Dwarfs pencil holders awaken Corey''s interest. Will the negotiations be the fairest of them all, or leave him feeling grumpy? And finally, Rick and Chum take a trip to Los Angeles to see a coveted pair of sneakers that Michael Jordan wore in the movie "Space Jam." But will an out of this world asking price, drive Rick looney?', '2021-08-21', 42, '/o2bnoboCkI7gPupl1Y1o0pupM20.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
