INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2E873AD3E1514041BADAEEA003228E06', X'F12380A993E547BB9E2FCF1EED11EEE4', 19, 'One on One: Part 4', 'In this final episode of the One-on-One interviews, Meri and Kody talk about their dark times in Vegas. Kody defends Robyn and accuses the other wives of using her as a scapegoat. Meri is asked about the new man in her life.', '2026-02-01', NULL, NULL, '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2E8B6DCF247349ADAB34FA7F8194CA3A', X'BFDF87FF01DD4B5494BD19B384F41BDB', 8, 'Shannon Gets Her Groove Back', 'After an explosive night at the sushi dinner, Heather and Tamra discuss Kelly''s volatile behavior as Kelly regretfully turns to her friend Meghan and receives some tough love. Meanwhile, Meghan takes the next crucial step in her IVF process. Later, Shannon celebrates a night full of surprises with all her friends and family. Back in the OC, Vicki and Kelly have a party of their own and bond over being the odd women out.', '2016-08-22', 44, '/ng0qJFsiF6PWYtG4KtP7XAPwC41.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
