INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2E8CF2B2AB854C6CB97488B8C4EFA0BB', X'5C4E51C6E20746AD875C72988EB1E13E', 20, 'Kings and McQueens', 'The Pawn Stars are blown away when a seller limps in with a 19th century shotgun disguised as a cane. Will Rick take a shot at buying this legendary concealed firearm or will his offer miss the mark? Then, Rick and Chumlee race to check out a 1940 Indian Motorcycle once owned by the King of Cool, Steve McQueen. Will this negotiation take off like a Bullitt or will Rick let this one make a Great Escape? And later, the guys are presented with a book printed by founding father Benjamin Franklin. Will Rick shell out some of his own Benjamins for this rare piece or will he find it''s not worth the paper it''s printed on?', '2011-07-18', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
