INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2E9EBD6B44FB485198951FE2010296CC', X'4B2A19E02FAE492EBC31F78E63D88EBC', 20, 'A Pawn of Lies', 'Bend your mind with the Pawn Stars when two original lithographs by graphic artist M.C. Escher are brought in. Will Rick make a surreal sale or will he find the deal impossible to construct? Next, things get transparent when a censored recording made on a Soviet X-ray is exposed in the shop. Will Rick throw the seller a bone or will the deal cause a stress fracture? Then, Corey calls shotgun when a Wells Fargo model stagecoach rides in. Will he jump on the bandwagon and make an offer or will he be walking home? And later, a 1950s toy lie detector puts Chum in the hot seat. Will he make an honest offer or will he fail the test?', '2017-01-01', 21, '/40X8Bp9EOUcrx0q5Gm0K4yGrrN4.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2EA52EA1305F4C7C81AB54DA14FF1737', X'6C1EC19F74DF4F359A6117B98175D826', 6, 'Read Between the Signs', 'Erika is left seeing stars at her astrology party when old resentments flare up between Kyle, Teddi and Dorit; Denise''s simmering frustration boils over in front of a speechless Lisa Rinna; Garcelle questions a new friend''s priorities.', '2020-05-20', 43, '/xMZ0x7aeiDF2lXVul47PrxscxRh.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2EB04EF4D4E043C18597E599E092758D', X'3FC7C152E4F6426AA89936EC454C4403', 56, 'True Blue Friend', 'The gang inadvertently uses permanent paint and turn themselves into different colors. They must follow Quetzal''s instructions in order to remove the paint from their bodies.', '2000-01-26', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2EB3D25F2E0B48B3987076D8B69D554A', X'8BAE6AA34B554FA6BC158F4317BD1F13', 40, 'Lady Elaine Flies into Space Pt 5', 'Lady Elaine radios back to the Neighborhood of Make-Believe, saying she will stay in space because she has made the most extraordinary discovery.', '1972-04-14', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2EBB191190674859B1D849277C3B1AFF', X'DBD3583FE9B246D1A37E309EB666E233', 12, 'South Africa: Just Like Home', 'The ladies arrive in Cape Town, South Africa for a 10-day adventure where it’s officially the “Smalls” (Phaedra, Shereé and Kandi) versus the “Talls” (NeNe, Cynthia and Marlo). However, Africa works its magic on them - even NeNe and Shereé put aside their differences for the first time in months. On a yacht ride in the harbor, they open up to each other about their differences and attempt to start anew. But the love-fest is only a few hours old when NeNe''s new bestie, Marlo, confronts Shereé about not inviting her to a dinner party. A huge fight erupts, with NeNe playing the unlikely role of peacemaker. Back in Atlanta, with Kroy away at football camp, Kim’s feeling the pressure of being a single mother of three.', '2012-01-29', 43, '/vfaPqWhuby2J76WPJF901XdAZwl.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
