INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2ED81531D94948DDA309F6056630AE56', X'F4D370CA3C3940A8911DE2B5E7C6B0D7', 9, 'Rabbit and the Visitor', 'Rabbit’s rather rude cousin turns up unexpectedly and decides to stay with the toys for a few days. After a large picnic tea, where she eats most of the food, the toys get ready for bed. She puts on her pyjamas and climbs into the bed, leaving no room for Rabbit. The next morning the toys decide having a guest is not as much fun as they thought and Old Bear thinks of a plan that might persuade her to go home.', '1996-10-30', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
