INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2F29154C055340CEBEA71669F592F86F', X'6053B5C1CE86425C8166E0FCC3466061', 4, 'Episode 4', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-09-25', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2F2C834FA1FB41E5A047C5BCA08DD3D0', X'5C4E51C6E20746AD875C72988EB1E13E', 2, 'Pablo Pawncasso', 'Get revved up with the Pawn Stars as they check out a rare REO Flying Cloud hot rod from the 1930s. Will Rick muster the strength to crank up an offer for this classic ride or will the deal take a detour and sputter out? Then, Rick and Corey are presented with a well-known Picasso etching called "Poor Roby." Will the guys draw themselves a masterpiece of a deal or will critic reviews call it "Poor Rick?" And later, Rick and Chumlee meet a man trying to sell his pair of pants - miniature gold plated pants awarded to Ohio State football players when they beat Michigan. Will the guys cautiously step into this deal one leg at a time or jump right in with both feet?', '2011-04-04', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
