INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2F459F8D99F640B985EA5B98F04B2E4D', X'699572F82BFF45158DF36E7D1A21F346', 6, 'Goes Cellular', 'It’s the night of the rock lovers’ annual Granite Awards, and Arnold is about to become the first kid to win the Rocky Award. He’s so excited, all he’s been able to eat for weeks are “Seaweedies.” When he arrives for the big event, he’s totally nervous and totally... orange!', '1997-10-18', 25, '/q5O4RbXlyDodV9F9Plc8x9QdcMH.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
