INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2F4B3E30D5594D408D9C17C9339DA46D', X'DB958AF49A9A4533AF9BF0FF590D1DD9', 9, 'Coffee Talk', 'Paul tells Dolores she needs to establish boundaries with Frank; Melissa and Teresa have differing opinions of Louie''s involvement in their family issues; Dolores and Jennifer attempt to mend their friendship over lunch.', '2023-04-04', 44, '/3BAMaM3dSAqzN3Pd4qnTWYBwHUJ.jpg', '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2F528AADC666442AAF11225CE8D32654', X'8BAE6AA34B554FA6BC158F4317BD1F13', 64, 'Episode 64', 'The McFeelys bring two African lion cubs to Rogers'' television house. In the Neighborhood of Make-Believe, Lady Aberlin helps Handyman Negri with his tasks.', '1972-05-18', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2F53F9817CEA4A458DBD44852102F87A', X'6F731E6BD3C54DE684E17A19CB650E86', 1, 'Pawn of Fire', 'Walk the line with the Pawn Stars when a model train once owned by Johnny Cash chugs into the shop. Will Rick make a bid for the Man in Black or will he be singing the prison blues? Then, Chum gets scrambled when a 1920''s chicken incubator clucks on in. Will Chum hatch a deal or will it get poached? Next, Rick becomes enlightened while checking out a 17th century Tibetan Buddha. Will he be reborn as a buyer or take a vow of silence? And later, Rick and Corey take a trip down memory lane in a 1972 Cadillac Eldorado. Will the guys take home the luxury Caddy or will it turn out to be a clunker?', '2015-10-22', 21, '/5hsPAhaBFlE94I72iOcsBo5NUpB.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2F543A81B6BF4FB184EFA92D5B391DCE', X'ECB64EF34F8045A7B4A9C04434B02E35', 16, 'Chords, Swords and Rewards', 'Rick and Corey check out a sword belonging to the Freemasons. Will the guys be able to sneak in an offer or will negotiations get chopped? Then, Corey and Chumlee play with the idea of scoring a Gibson Master Museum guitar. Stamped with the serial number 1, how far will they go to pluck out this rare instrument? And later, Chumlee tries to prove he deserves a raise, but will his weaknesses outweigh his strengths?', '2014-02-20', 21, '/5cRsrQtJXv2DcWVronRvSaz7BtY.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
