INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2F60B17F73134FF1A987FBCF67D66690', X'99B7102639194813A330EB09E0E43D74', 2, 'I Lost My Tooth in Africa', 'LeVar discusses different rites of passage in growing up. The book "I Lost My Tooth in Africa" is read about a young girl who loses her first tooth while visiting her father''s family in Africa, and how the tooth fairy tradition is different in other countries. We visit with some young people who are having their first dental appointment, and LeVar discusses other culture''s customs regarding loose teeth. In another rite of passage, a friend of LeVar''s celebrates her 15th birthday with a Quincenara ceremony.', '2006-11-07', 30, NULL, '2026-04-03T17:36:22Z', '2026-04-03T17:36:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2F6247D3349843F4AFB4C79C33D7AD17', X'D2F2CE6396AF489992A83DA5EA3913CE', 2, 'For Lunch', 'Arnold''s so excited he doesn''t have to go on a field trip! But when he accidentally swallows his miniaturised class, he becomes the field trip!', '1994-09-17', 26, '/wC3zR6VE24WQQLEBseUUYk6uWuB.jpg', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
