INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2F837A1317BB46C68B2DB7966A09FBB9', X'3ADE5E1F84414C2CACF6FB933A61DCFA', 17, 'Unanswered Questions', 'The women scramble to find Katie, and are shocked to discover her true whereabouts. Gizelle battles mother nature, while Karen teaches the ladies a unique technique. The fun comes to screeching halt when Karen and Ashley get into an unexpected conflict – catching everyone off guard.', '2019-09-01', 42, '/fkNVSUUKmQKNb5BELHMr60qFKoU.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
