INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2F88C0A3F377407FB8FE656AC209381A', X'33440D76E69F47ADAC25862CCBC9DFA1', 4, 'In a Pickle', 'Karen invites all of the couples to a fun day of pickleball, but things get heated on and off the court. Candiace comes face to face with Robyn and Gizelle. Everyone is surprised when a certain husband makes an appearance. Nneka confronts Wendy with some shocking allegations.', '2023-11-26', 43, '/jLKrerMdJjS7yk3rG5f3qZPckm4.jpg', '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2F9036909EEB435A98F88CC4E66E8920', X'6053B5C1CE86425C8166E0FCC3466061', 25, 'Episode 25', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-12-08', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2F98D39B54C8455DB26E85A081F78E70', X'C01DDD2ABDB14C978D0458F791EF1C24', 38, 'The Four F''s', 'Creature coats are the key to keeping animals warm in cold weather. Zoboo, Chris and Martin realize that animals beat the cold with the four F''s: fur, feathers and fat and in the case of otters fun. But what happens when the weather warms up? Ernie the camel comes to Animal Junction looking for a good scratching post to help him shed his winter coat for summer since he won''t need it when it''s hot outside. Jackie brushes her dog, Goldy, to help her take off her heavy winter coat. Dogs and cats love being brushed and it feels good to lose that extra hair. Jackie knits a small sweater from the hair she brushed out of Goldy.', '2000-04-25', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2F9AC1EB4C4A419DB15D599DC8CFEC04', X'671BD4DA347040F99A0340FBA34D2B8E', 14, 'Guess Who''s Coming to Frozen Dinner', 'Mike''s wayward brother, Rusty, comes to town and presents Sue with an extravagant gift, which Mike thinks is stolen goods. Meanwhile, with Sue now older and living the college life, Mike feels like he''s not as close to her as he used to be and tries to figure out a way to reconnect; Axl blows the money from his first paycheck on a big screen TV and blames his spending spree on years of learning from Frankie''s lack of financial wisdom; and Brick is stumped, but delighted to discover mysterious, unmarked gifts being left at the front door of the house.', '2018-02-06', 22, '/3uy0PChQUC6QEIqImUajCveRqAT.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
