INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2FA7C224244D461B9423525504F36D74', X'6ACFEFC019044F939C06A1A09856150A', 5, 'Willow Whispers / Pink! / The Pond Prince', '', '2002-12-23', NULL, NULL, '2026-04-03T17:11:23Z', '2026-04-03T17:11:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2FAD29F6D545460A8C92366B87638B75', X'9D74600D722247C1BD1B635F5B41B7D1', 10, 'Abiyoyo', 'In one of the rare times Reading Rainbow uses a studio set, LeVar tells about storytelling through music. The then-new art of music videos is first up, with clips of Who''s Johnny (among others). Pete Seeger appears on the set to perform his version of Abiyoyo. Also unique to htis episode: all the book reviewers share the stage with LeVar.', '1986-07-04', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2FAF49B71E0F49B8B490C4244F981A4F', X'45E64A158FC04E4BA1CA9E3F42F3634D', 9, 'Biodiversity', 'Ecosystems are areas where things live. Ecosystems that are biodiverse are home to a variety of   plants and animals. A healthy ecosystem is one with a lot of biodiversity.   Imagine if humans could only eat one kind of food, say corn. We''d be in big trouble if all the corn   disappeared. Besides not having anything to munch on at the movies, we''d have nothing to eat at all.   Luckily, our ecosystem covers a big part of the Earth, and there are lots of different plants to eat. Ecosystems   are not as simple as one living thing eating another, as the corn example. The lives of animals and plants   are intertwined - what happens to one animal can have an impact on all sorts of living things.   As humans, we have a big effect on the other living things around us. We are the only animals to leave   lots of stuff around, such as houses, cars, and malls. It''s important for us to think about the choices we   make and how they will affect the other living things around us. Remember: The Earth', '1993-11-05', 26, '/cKk14w7eEpXc7KPzLhzCvpRNptB.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2FB0092360944443981F792E4C5F3627', X'4861CE46904543C7963F27B4EA539804', 105, 'Episode 235', '', '1971-04-02', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2FB4D37114224C7090B88EBD46BA3F5E', X'AD180412A5D64E4A8B49590334F2FC69', 9, 'A Bigger Oink', 'The animals in White Deer Park are still trying to deal with the army of rats and try to make the Warden aware of the problem. Meanwhile the weasels and the piglet come across a copse with a grumpy Wild Boar living there. Bully forms a task force to hunt down and kill the snakes. They find Sinuous, thinking it''s Adder and kill him. Hurkel and Shadow try to comfort Adder as Bully slinks away unnoticed.', '1995-11-23', 25, '/oVwqtCPP3NNvPNknWNLJYM5BEzd.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
