INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2FBA35EA45914FF98C66AF3D3619C40F', X'0987F081B3B74E3CABB7795E56C279D5', 9, 'Christmas Help', 'Mike helps his brother Rusty move some furniture into the Heck family''s garage, only to realize the furniture is stolen; Frankie hopes to land a part-time job in a department store so she can get a discount on Christmas presents.', '2012-12-05', 22, '/efS7qg73IbsfSBCsGdgZK5hzdxe.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
