INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2FC0CB40CDE0464B820CEFE273AFE82B', X'AD4E434833344A088928455D9BA524C1', 2, 'Loretta Swit', 'How well can Loretta fit into Miss Piggy''s roles?  It all comes to a dramatic climax with the ""Pigs in Space"" installment.', '1980-10-12', 26, '/zKnIqVwUStWjFuT1ylWJ2X7HLz5.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2FC4BC8D08FD4EC896BFF0195E9AED67', X'8C3CFAC1D8824904B38CD1981628D00E', 28, 'Episode 28', 'A behind-the-scenes look at the filming for this year''s All Star Record Breakers - in Blue Peter''s Italian sunken garden!', '1978-12-14', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2FC681C5B5C74CE29BAC2EDB5434E28A', X'45E64A158FC04E4BA1CA9E3F42F3634D', 16, 'Light & Color', 'Lighten up. It''s the ""Light and Color"" episode.   Without light, we wouldn''t be able to see. It would be like living in a room with no windows, doors, or   lamps. There''s an old saying, ""We don''t see things; we see light bouncing off of things."" We see things,   and colors, when light bounces off things and into our eyes. White light, like the light from the Sun, is   made up of all the different colors of light blended together. When white light hits something white, almost   all of the light bounces into our eyes, and we see the color white.   Things are different colors because some light bounces off and other light gets absorbed.   An orange is orange because it absorbs all different colors of light except orange light.   Grass is green because it absorbs all different colors of light except green light.   Bill Nye''s lab coat is blue because it absorbs all different colors of light except blue light. All colors,   including black, are made in the same way. It''s just a matter of ref', '1993-12-24', 26, '/jvN7fQz61QphvBG1nXT2RTZLw71.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2FC6C165736749A796658AEBA1FA6A08', X'4B2A19E02FAE492EBC31F78E63D88EBC', 10, 'Great Negotiations', 'Drive a hard bargain with the Pawn Stars and relive some of the fiercest negotiations in the show’s history: a pair of boots worn by Elton John, a James Bond Aston Martin toy car, an ancient 44 B.C. Julius Caesar Roman coin, an assortment of vintage Pez dispensers, a 16th century book that belonged to Sir Isaac Newton, an extremely rare collection of Viking copper and gold and an aphorism signed by Mark Twain has Katie Couric haggling it out with Rick for the best deal.', '2016-09-07', 21, '/hcEpJqyFlsqmwXrGNRtYZHP49I2.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2FCAC989335F4E14A69EF4CA2B465657', X'F593D90C533942F59C885BFD48D04075', 28, 'Zebra Ducks Of The Serengeti', 'After getting covered in soot, two hapless ducks are mistaken for a pair of rare African Zebra Ducks. Seeing a way to make money, the farmer transforms Shaun''s field into an exotic duck enclosure, which he gleefully opens to the public. Shaun doesn''t appreciate losing his field and sets about exposing the fraud.', '2010-12-03', NULL, '/aaBJ4JDzdjfWZBtQPzB4NXSh3Va.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'2FD0E42FF550491BA1990F2EF68B648B', X'F6015D9AECE4414AA00B06CF689FE40B', 21, 'Goes Microscopic!', 'You won''t believe your eyes when we set fire to water using miniscule science. There''s live music from Una Healy. Also, George is back to kick-start the Blue Peter garden.', '2018-05-17', NULL, NULL, '2026-04-03T17:22:10Z', '2026-04-03T17:22:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
