INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3026C11C241B4E40BAB90AF346B90DCB', X'4D2CAC0F38FD438B8AFAACF43952E535', 210, 'Episode 210', 'All Aboard! with Christopher Trace and Valerie Singleton in a magazine programme for younger viewers.', '1962-12-03', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'302AF11C155D477FA6B96F36DCA17959', X'D920EBAEF00A4E25ABFE40492C74DED6', 20, 'Saints and Winners', 'When a customer comes in with items from Tony Soprano’s wardrobe, can Rick make him an offer he can’t refuse, or will he fuggedaboutit’ Then, a pair of papal artifacts inspires Rick and Chum to mix business with pleasure as they set off to Italy for a Roman holiday. Will the holy relics be the blessing they’re hoping for’ Meanwhile, back at the shop, Corey is puzzled by a rare toy. Can he line up a deal, or does he have the wrong combination’ Next, Rick’s on a mission to track down a rare book written by an iconic philosopher. Can he get on the same page with the seller before the deal goes up in flames’ And later, the guys take a test ride on a pair of Vespas. Will Rick and Chum join the Vespa club, or will they be left in the dust’', '2020-05-18', 42, '/oJ97KHqKnnEZvNFjcyXXAeDPKyz.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'303BC772B55C4F449D35E4D1DFD401A3', X'45E01C046AC641E187D8F749EE230385', 48, 'Episode 48', '', NULL, NULL, NULL, '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'303E1F7BBDF44905B9161BB8FA4A420A', X'34674C90410E427CBE4D2A6F6F865A80', 23, 'Cool as Ike', 'The Pawn Stars prepare to invade when Rick is offered a memoir written and signed by Dwight D. Eisenhower. Detailing his command during WWII, is Rick willing to pay big bucks for this rare book, or will the negotiation force him to retreat? Then, a shop regular piques Rick s interest with a Remington New Model Army. Considered the second most popular pistol of the Civil War, will Rick make an offer, or has popularity diminished its value? And later, Corey and Chum orbit a set of food bags made for Apollo 11. Are the guys hungry to make a deal, or are the seller s expectations out of this world?', '2012-08-20', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
