INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'305D40596A454F59BDADE66F4FB2513B', X'4900FC8D5E7E408E972ECE9269D203B3', 12, 'Apples and Oranges', 'While Heather and Gina take a trip to New York, Shannon has Emily, Noella and Jen over for a dinner party. Heather and Gina take a walk down memory lane and bond over their mutual support for each other, while Dr. Jen works on improving her marriage and herself.', '2022-03-09', 44, '/v06wLMowhwedjQyHHB75Ktw14rq.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3062EFFB444643EAA19620C54E8DF9D0', X'650BAC937B5941FCB277DC6F8BDCD7BB', 14, 'Sorry Not Sorry', 'Frankie and Mike frantically attempt to shut off the water and save some treasured items when the pipes burst in the basement. But after freaking out and bickering amongst each other, Axl, Sue and Brick call a family intervention meeting to let their parents know that their constant fighting and bickering is negatively affecting them. But while the kids feel like they can benefit from their parents’ newfound realization, Frankie and Mike start to think that the kids’ lack of support makes them the ones who should be sorry,', '2017-02-14', 22, '/i95jiKKOB98CfcaGP6OvCUJbrn8.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3067C96B1BB045358FE3DE9F30213238', X'DF77DBA2BBDA4F3897138D5C856F852E', 2, 'Little Bear Lost', 'Old Bear has just finished packing a picnic basket full of food when Little Bear dashes in, followed by the other toys. They are all playing hide-and-seek but, unfortunately, they have forgotten to choose a seeker. Old Bear agrees to look for them and soon finds everyone except Little Bear. After they have searched high and low they decide to eat their picnic and then search again. But a surprise awaits them when they open the lid of the picnic basket!', '1993-10-10', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
