INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'30AA47492B554CACBFC113708F3C45E2', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 15, 'Comets & Meteors', 'Outer space is full of stuff. We’re not just talking about planets and moons. There are some bits and pieces, too small to be noticed most of the time that float around and occasionally run into all those planets and moons. Comets and meteors are the big bits of dirt, rock and ice that inhabit our Universe. More than just high-speed space chunks, comets and meteors carry important information about the history of our Universe.', '1998-05-16', 26, '/iqwPAPpzOLvc0kl1De916JRD5gU.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'30AC42FCA775401FB98F2E9F7D25DA98', X'F21CA545466C448CADA5B8ACC8B856DC', 7, 'Four Four Time', 'Karen''s mother''s car breaks down when Karen is going to her music exam.', '1999-11-05', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'30AF7E4C8EDC4B68BFCD162CA06787BC', X'363A94F9E0E5441CAA862BE2E9832DA1', 14, 'Big Apple Rick', 'Rick''s in the big apple to see if he can compute a deal on a rare piece of tech. Can this sweet piece, tempt Rick, or will he shut it down? Then, a seller flies into the shop with a special edition Stan Lee Funko Pop figure. Will Corey make a super deal? Meanwhile, Chumlee has a blast with an original flintlock wall gun. Will he hit his target, or be off the mark? And later, Corey checks out a vintage camera. Can he focus in on a perfect deal, or will the negotiations end in a flash?', '2021-12-18', 42, '/d2n7mupdtyk9fXtLgC1d6LhtdoM.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
