INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'30E1E856869D47DC9D6C3006EDBD5317', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 27, 'Miles'' adoption', 'Big Bird and Snuffy declare today as "Best Friends Day," and plan to celebrate together with a picnic in the park. Big Bird is eager to get started, but Snuffy reminds him to first pick up their lunch at Hooper''s Store.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'30E6EC4D3DD34E6A904682910D3A8185', X'A3A2C2FB8276412C9D865175167BE1D7', 46, 'Episode 46', 'with Valerie Singleton, John Noakes, Peter Purves', '1972-02-21', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'30F16FC5D7BA4DDEB87E186A4DD5523F', X'8B6BBAC8E5EF49C7A5C1197CFB19F772', 18, 'Mister Rogers Talks to Children and Parents About Violence', 'Prompted by news coverage of the death of John Lennon and the failed assassination attempts of President Ronald Reagan and Pope John Paul II, Rogers talks to children and their parents about violence in the media. Rogers shows video footage of himself at schools, discussing why people murder, with young children. The special aired only once but it was later uploaded to the internet 35 years later, during a time when its subject matter was again a much-discussed issue.', '1981-08-04', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'30FC1C517E1B4983A1EA3D61A96D7940', X'3269A890BBA94E6C9278F7EB38EB1720', 12, 'Ocean Life', 'There’s an amazing amount of living things in the ocean. There are fish, sharks, flowers, whales, squid, sea plants, sea anemones, sea otters, and all sorts of other things living in the water. But most of the living things in the ocean are so small we can’t even see them. These tiny plants and animals are called plankton – the “drifters”.', '1995-04-28', 26, '/jzrKz3LDGq3uNq2H1usVgtK8gGH.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'30FC2C15AD964939AED7E62CABEDC93A', X'E38E9D8714324A1AA7D064A559BF7570', 7, 'New Friends, Old Enemies', 'After finding himself on a log floating downstream Fox jumped aboard a boat that ended up in a town. As he sees humans surrounding him he jumps out and escapes into the town. Frightened by the bustle of the town in daylight he looks for somewhere to hide. He meets a cat called Tom and hunts rats for him in return for shelter. However when he finds a box to sleep in it is lifted by a truck, which heads out of the town, so Fox takes his chance and escpapes into a nearby field. Here he is greeted by a friendly Horse who warns him about the hunt in this area. Finding himself an empty den he goes inside for a rest. But soon he is woken by the movement of another fox, a Vixen. Meanwhile, back with the other animals, the fieldmice''s new born babies have been eaten by a butcher bird.', '1993-02-14', 24, '/1bD8PUqSkkUnEgByLQllcIZUMuB.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'30FD42999B0947CD947DFAE2799D54F4', X'871570B4BF2F4BA1994065FB932CB009', 18, 'Reunion (1)', 'Kenya accuses Phaedra of throwing shade; Kandi and Phaedra air new grievances while discussing their deteriorating relationship; Kenya and Kim go head to head; Shereé talks about her experience returning to the show; Andy Cohen hosts.', '2016-03-20', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3103E29C60F64B87ADE4BD5D19F1F08B', X'A6ED03E0C05F48F89F563F1DA50E1792', 108, 'Episode 1423', '', '1980-04-23', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3107B2C5A60443419EFF12CAFFD67332', X'1BB5392776F64ED39C415414AD0865CE', 12, 'Reunited', 'In the kingdom of Malkariss, Matthias fights the slavemaster, Wearet, and falls into the abyss. There he grimly hangs on the rope that previously lowered a mysterious basket. But as Mattimeo and friends are released by the dying Log-a-Log, the Wearet cuts the rope and Matthias falls into the basket - and meets Malkariss himself!
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3109FBD985494EDF8C621D9930E6E1A2', X'66A11A09AEE24A7B8543AB080A9D1BE4', 13, 'Sister Act', 'After the blow up at Kyle''s gay mixer, the women discuss Brandi''s influence over Kim; Lisa Vanderpump is nervous when her son receives his genealogy test results; the women attend Eileen''s movie premiere at a suburban shopping centre.', '2015-02-10', 42, '/7rcKq6RL1JbBkTiGF5Rnr3MBwB2.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'310C4821FACB402183735A0CBB97C30C', X'5C4E51C6E20746AD875C72988EB1E13E', 31, 'High Stakes', 'The Pawn Stars lock and load when a percussion pistol from the 1830s pops into the shop. A rare weapon known as a "man stopper," will the guys take a shot at buying this pocket pistol, or will a tough negotiation stop them dead in their tracks? Then, Corey faces a monstrous challenge when a signed copy of Bram Stoker''s "Dracula" creeps through the doors. Will Corey be entranced with this rare book, or will a scary asking price put a stake through the heart of the deal? And later, a guy charges in with an Orange Bowl championship ring. From Penn State''s undefeated 1973 season, can Rick make a winning play for this MVP item, or will he fumble the deal and end up on the bench?', '2011-09-12', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3116A510218C4843B24510C20072486D', X'342AE4CDC2E542CF824C55EBCD225B91', 5, 'Rattlestar Ricklactica', 'Lots of things in space, broh. Snakes and sharp stuff. Watch this, broh.', '2019-12-15', 22, '/po6Uuzz17eFcGFgiB2f6n7v0chL.jpg', '2026-04-03T15:40:42Z', '2026-04-03T15:40:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'311738E8180A48E3B98F5A767FD053B9', X'1BB5392776F64ED39C415414AD0865CE', 10, 'Malkariss', 'As the slaves arrive at the ominous Badger Head and Bell rocks, Mattimeo bravely comfronts them and promises "I will not fail us." At Redwall the citizens defend the tapestry in a pitched battle and recapture it. Simultaneously Matthias arrives at the Loamhedge Abbey and meets an old rabbit who forecasts doom, giving him an amulet.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'311EF24F245A490382835298BCDEAEB1', X'8AE35FD8562643D7A1EA0E43192D1C36', 8, 'Dudley and the Knight Club', '', NULL, 29, NULL, '2026-04-03T17:12:15Z', '2026-04-03T17:12:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3120E3A143AE4BBA96603318B8C7A6F0', X'0EBBA123871D4D2BA054EB85D2AD9450', 41, 'Robin Good and His Not-So-Merry Men', 'Robin Good has a mission - fundraising from the rich and giving to the poor!  But when greedy Prince starts stealing the townspeople''s hams, donations are down and Robin''s band of friends desert him to give robbing a try.  Can Robin overcome his hurt, show his friends what''s right and restore the townspeople''s hope?', '2012-03-06', 30, '/8fJuquwQrSTEPD1z7OKRkian9Q9.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
