INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'31276DA68A884D24A70DF4F08CBDD9AF', X'4B2A19E02FAE492EBC31F78E63D88EBC', 1, 'Mad Deals', 'Cruise the streets with the Pawn Stars when a 1969 Triumph Motorcycle gets Rick''s engine roaring. Will he ride to an offer or will it veer off-road? Next, the first ever issue of Mad comics illustrates its way into the shop. Will Rick make a satirical sale or will the deal go unpublished? And later, Corey locks and loads when a 1800s Parker Brothers shotgun fires in. Will he trigger a deal or will he shoot it down?', '2016-07-27', 21, '/uQLxukn0dqA76yMfqVKn48KVv7y.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'312770F09A05452E83E45B1DB04DB92E', X'ECB64EF34F8045A7B4A9C04434B02E35', 23, 'Shamrocked', 'Go long with the Pawn Stars when a jacket from the first-ever Pro Bowl gets thrown into the shop. Will Corey score this piece of football history or will he get sidelined? Then, Rick and Corey have trouble seeing eye-to-eye when a 1965 Buick Riviera cruises in. Can Corey speed away with this stylish ride or will Rick hit the brakes? And later, it''s St. Patrick''s Day in the pawn shop, but not everyone is in the holiday spirit. Will intern Lili be able to charm the guys, or has her luck run dry?', '2014-03-20', 21, '/umpQoSwHQiYfOLhy8m5SNLIM0z9.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
