INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'31619C855BBD40629518D494DA19B5F1', X'2E6EE129B32E4417950056F1CC9BC434', 9, 'And Still the Turtle Watched', 'LeVar discusses how people can help to preserve animals and plants in nature that are in danger of extinction. Stories profiled include scientists working to improve the bald eagle population by raising chicks and re-releasing them into the mountains, and an elementary school class that decides to plant trees in their neighborhood. Michael Ansara narrates an unusual story, told from the viewpoint of a turtle sculpture carved in a rock, and how he wishes to preserve the history of Manatoo native Americans, despite being vandalized and thought to be ignored by later generations after he was carved.', '1993-10-21', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
