INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'316E9950D0CC48DFABA4D561914715EC', X'97A3D1F5A8F147CD81222E74A092836D', 23, 'Don''t Stop the Music (3)', 'Casey is accused of being the saboteur. Lenni continues to get gifts from Marlon. Lenni asks Marlon if he even knows David but he claims that he doesn''t. Lenni suspects that he and David are lying. Hector learns that Avatar is the one leaving the anonymous notes for Jade. Gaby and Tina learn that Casey isn''t the saboteur after all. A spotlight falls and nearly kills Lenni and another note is attached but this one is different from the others left by Avatar.', '1994-02-06', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
