INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'31739E3109B04FBCB3CC5672783462E7', X'991E78F103A54D268F7575E11DB4243C', 4, 'Noisy and Quiet: What You Can Do When Someone Wants Quiet Time', 'Rogers recounts his snorkeling adventure with Sylvia Earle, back from 1990. Sylvia Earle visits the television house, and screens a videotape on the sounds of fish. In the Neighborhood of Make-Believe, everyone is upset at the constant bell-ringing and drumming at Henrietta and X''s tree. No one can convince him to stop, especially since fewer and fewer neighbors remain uncostumed.', '1999-03-08', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
