INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3177FA1350C34CB191D67D28693E39B5', X'EC8D33228CA24E8D9D22268AEE320274', 2, 'Just Pawn It', 'Rick takes a Bricklin SV-1 out for a test drive. But is this sports car a safe bet, or a bright yellow lemon? Then, a seller makes Chum a whale-y big offer, but does he have the backbone to make the deal? Meanwhile, Corey and Chum try to stay afloat with a limited-edition Nike raft and briefcase. Will he just do it or just don''t it? And finally, Rick and Chum make a long-distance song request on a Shyver Multiphone, but will the seller be singing their tune?', '2025-01-29', 42, '/wcAlIEXrDjeg3wwWY8NzCSiRZ0W.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
