INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'31C83AEF0F884D8E99BD9AB9F6B9AE49', X'EA73E13C696248048305C303DF65F89F', 15, 'The Royal Wedding (5) - The royal wedding day', 'Rogers, Miss Emile, and Chef Brockett carry out their plans for the Royal Wedding. What nobody knows until late is that King Friday wants the wedding to take place in the redesigned Castle garden.', '1969-02-28', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'31CE93B839D14F4289FF9EED1F849E2D', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 115, 'Elmo does magic; a blackout happens', 'At dusk, Maria observes the many sounds coming from her neighbors: Gordon vacuuming, Bob listening to his records, and Luis using a drill inside the Fix-It Shop. Maria naturally assumes a blackout has occurred, so she goes inside to call the electric company from the Fix-it Shop landline.
