INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'31D6DEDEDB264FD3A1DC422043AAB703', X'48A6D3B8384241DAAAECB49A9B65F17F', 11, 'The Magic Lamp', 'Kipper finds an old bike headlight that grants every wish that he and Tiger make. They find a door behind Tiger''s wallpaper, go up a very high staircase and also go on a roller coaster that takes them to a planet where a very scary dragon lives.', '1998-12-03', 30, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'31D9418CA1E14386A96ED07AC4C5F066', X'787DFA0BC8274DADA82D0548A6534D88', 23, 'Brooks Tells All', 'The half-hour special delves deep and showcases never-before-seen footage from Andy''s sit down interview with Brooks Ayers, originally seen in the reunion, where Brooks addresses the ladies'' allegations regarding his health. Andy confronts Brooks on the season''s burning questions including why he avoided seeing Shannon''s doctor, why he and Vicki told different stories about his treatment, and the claim that announcing his cancer diagnosis may have been an attempt to control his damaged public image. Brooks also reveals his true feelings about each of the ladies, including Vicki''s daughter Briana, and explains why he finally ended his relationship with OC matriarch Vicki.', '2015-11-12', 44, '/ccXwMO5M9UzrobzBIhdWCgJleMv.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'31DE044FD52D42FABF41B38508914C3E', X'05C0E384194C44179F62803EB615E409', 5, 'The end of the first week', 'Title number 0005. Opens with Mister Rogers playing with a feather on the porch. After Mr. Rogers plays with them, Betty Aberlin takes some helium balloons to the Neighborhood of Make-Believe. Tagging them with a message of peace, she floats them above the castle. When King Friday reads the message, he ceases his efforts to stop change. The wall is taken down. Mister Rogers sings his special family bedtime song called, "Good Night, God" for the first time.', '1968-02-23', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'31E022509FB34E9D8309A1BC7759CB3E', X'16CBF3F2FFFD4A78BCA396D05F5A2C6B', 6, 'Spar for the Course', 'After Binky wrecks the 18th hole at a miniature golf course, Muffy, Buster and Binky attempt to create a new 18th hole.', '2016-01-20', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
