INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'31E67842554A44039E434D6D60A67F4A', X'8A5892F6CCB74F029A5A85B134B5F0CF', 2, 'Mrs Porty''s Foxes', 'Some wear fancy hats in order to look beautiful. Some wear them to save their friends - but what else should an engine-driver do?', '1976-02-17', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'31E8286973864257A2B219ABA5982DFD', X'136B81D3964D4B8FA21492F00D96D6B9', 122, 'Election Day on Sesame Street', 'Sesame Street holds an official Election Day where residents vote on an important community decision affecting everyone. Big Bird and others learn about the democratic voting process and the importance of participation. The community comes together to celebrate their collective choice.
