INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'31E850985ACA4F7BA78E7E4B3CDAED6A', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 79, 'Episode 2174', 'Maria is strolling along Sesame Street when she finds a "Se Habla Español" sign outside Hooper''s Store. Elmo finds David arranging a plate of food in accordance to a picture. David lets him help out by pointing out all the foods on the plate.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'31EDC4E00D53432B8EE9CCAD080AD079', X'34674C90410E427CBE4D2A6F6F865A80', 19, 'Stuff It', 'The Pawn Stars are presented with the most collectable Smith & Wesson gun out there, the Model 320 Revolving Rifle. With only 977 ever made, will the guys be able to keep a bead on this incredibly rare weapon, or will some condition issues make the deal misfire? Then, Chum and the Old Man are craving pizza when they take a look at a collection of Teenage Mutant Ninja Turtles comics. Can Chum convince the Old Man to invest in these 1980''s classics? And later, the night shift gets creepy when a seller brings in a collection of custom taxidermy pieces. Will Corey and Olivia be able to buy them without getting skinned alive?', '2012-07-02', 21, '/xQc8CwL7NktZtOkoQeNdeqDQjC3.jpg', '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
