INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'320A9AC73AAD4EA789CA9B6D2D8078B1', X'941B8C6544544336BE7C1D0591C12F90', 1, 'Pingu''s Bouncy Fun', 'Pingu is jumping up and down on his bed, which causes dishes to fall down and break from a shelf. Mother comes in and tells him to stop and makes him sit on a chair. Pingu then jumps up and down on the chair, nearly frightening Pinga, and is for the second time told not to bounce. Pingu then jumps on a cushion and then on Pinga''s rabbit! Mother takes the rabbit away from Pingu and passes it to Pinga. Father arrives and settles down to read the newspaper. He and Pingu build a makeshift trampoline, and they bounce on it. When Mother comes home, Pingu falls head first on the chair. Then they take the trampoline outside and Mother puts on crash helmets. Pingu and Father do bouncing on it.', '2003-08-01', 5, '/k2T2XssmrXYBsKbOkotOkbAYyEn.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
