INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'324004D40A6C4AAA895C876AF280882A', X'F4D370CA3C3940A8911DE2B5E7C6B0D7', 14, 'Little Bear and the Christmas Star', 'It’s Christmas Eve and the toys have been busy decorating the Christmas tree. Everything is looking ready for Christmas but, sadly, there is no star on the top of the tree. Old Bear thinks it might be in the attic and Rabbit and Little Bear climb the tree to look. They find all sorts of things up there, but no star. After a wonderful Christmas party and Rabbit’s special magic show, they all get ready for bed. But in the night Little Bear wakes and remembers the Christmas star. He bravely decides to go and look for it. After a thrilling, snowy, night-time adventure will Little Bear get back in time for Father Christmas and will there be a star on the tree on Christmas Day?', '1997-12-24', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32465136E2C247CCB3DA035F349DFE86', X'97616D6E5C17449FA37655F1DA83D6C3', 14, 'Mister Rogers Talks About MAKE-BELIEVE', 'Mister Rogers arrives with a several different kinds of spoons which he takes to the kitchen to show. As he waits on a visit from a friend, Mister Rogers shows a film about how spoons are made. After the film Mister Rogers learns that his friend will not be arriving until a little later so he sings Let''s Think of Somthing to Do.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'324880E84336482893AB1D7AFC4BAB71', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 13, 'Telly doesn''t get angry', 'Oscar acts like a pirate in preparation for a bout of sailing with his pet elephants. Their ship, the S. Discontented, floats in the pool and the mast sticks out from the top of the can.
