INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3264F43B0BE546EF820F7EA8D223E109', X'ECB64EF34F8045A7B4A9C04434B02E35', 36, 'Fiesta Loco', 'Paint the town red with the Pawn Stars when a Monet landscape brushes into the shop. Will the artwork make a bad impression on Rick or will this picture be worth a million dollars? Then, Corey feels the heat when a customer brings in an old firefighter station. Can he douse this customer''s expectations or will he get burned? And later, when Rick''s history lesson on Cinco de Mayo drives the guys loco, Rick may be uninvited to his own fiesta.', '2014-05-01', 21, '/78ptrAJwTCqqMd70naWjyjmZZoB.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
