INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3284A5FBB9BD4A25AFD9D76EB0FC1F6D', X'F13CB62284E34654A8F10CEAB09A9CA6', 2, 'Franklin''s Allergy', 'One day, when playing with Bear, Franklin begins sneezing. Noting that the sneezing fits don''t seem to happen all the time, his friends diagnose him as having an allergy and after some tests, conclude that he''s allergic to Bear! Franklin and Bear try to find new ways to play together that won''t cause Franklin to sneeze, but it turns out that the cause of Franklin''s allergic reaction isn''t exactly what they thought.', '2002-04-29', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'328F037F4122461F9F6B5A65B87AD766', X'F4938E7D11A84756B40598BEDD7C9B28', 10, 'Pat''s Difficult Day', 'Pat''s alarm-clock fails to wake him up. Miss Hubbard passing by outside rings her bicycle bell to wake him up. Pat has to rush out to work in a hurry! When he calls at the Post Office, Mrs Goggins has a parcel of some spare parts for Ted and it just falls to bits. Poor Pat just ends up having a day full of disasters where one thing after another goes wrong!', '1981-11-18', 15, '/f0fApzQlgTlYVCabR0eQxNjQ3M8.jpg', '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32949E7121E443AF841B1C0145CD99D0', X'4F18AC4C8757456CA49A224F00E6A9F7', 9, 'Telly the Tiebreaker', 'Alan serves some customers some drinks and hears arguing outside. Zoe, Rosita and Devon want to put a square on their block tower, while Elmo and Dylan want a circle. Alan solves their problem by having them take a vote. The square gets the most votes, so they put it on top and use the circle as the swimming pool.', '2008-09-22', NULL, '/eqSGXqOAGNMoe10v4PrrrBy2yzO.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
