INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'329966E673034FC28D7C4675630F7C9F', X'F4C403079B5E4263A4E0DFA138131E7F', 18, 'The Best of Elmo', 'The Sesame Street character has fun singing some catchy new songs (you and your toddler just might, too), explaining the difference between light and heavy, having a laugh over pictures and numbers, and sharing the screen with a good-natured Whoopi Goldberg and Julia Roberts. Of the various Elmo videos, this one really does have the choicest material and stands up to repeat viewings--a big plus with little ones.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32997060B6784FDF95506EDE296FE552', X'70C8CB4624944DD498F66BFB9B3FAF73', 30, 'Message in a Bottle', 'The Pawn Stars are presented with a mysterious whisky flask from the Civil War era believed to have come from a Confederate spy. Can they crack the code and make the deal or will this flask''s secret compartment leave them all thirsting for answers? Then Chumlee and the Old Man meet a man hoping to sell his rare 19th Century English dueling pistols. Will the Old Man be cordial and make an honorable deal or will he be asked to step outside? And later, Corey has a chance to buy a piece of Rock-n-Roll history - the original contract for The Who to play Woodstock. Can he afford to win this battle of the bands?', '2010-07-05', 21, '/8HQs0qpOlGuNXFE1QPIClKAiDM0.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
