INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32B8DA5F66B24BD38808031B173A7C9A', X'F4C403079B5E4263A4E0DFA138131E7F', 90, 'Elmopalooza!', 'The show is a musical, featuring performances from guests Jon Stewart, David Alan Grier, Rosie O'' Donnell, Gloria Estefan, En Vogue, The Fugees, Kenny Loggins, Shawn Colvin, Jimmy Buffett, and The Mighty Mighty Bosstones, to celebrate Sesame Street''s 30th anniversary.
