INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32BBE89AA02F4914BF735F9631E97F8F', X'5A6D9A42165B4B5692730A06874DFE10', 10, 'Madeline and the New House', 'The Old House, sorely in need of repair, is condemned and the girls are forced to move to a small apartment where their snooty neighbors hate kids and dogs. But just before the wrecking ball destroys their beloved abode, Madeline enlists the aid of the ladies of the Historical Society, who help get the Old House renovated to perfection.', '1993-10-03', 30, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
