INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32C7DE318A32444D88DACFA3F7CBDEB8', X'A31FA1D7D6494846A81F4F34B6FB3331', 24, 'Paddington Takes the Stage', 'Paddington helps the Drama Society with a performance called ''The Secret Plan''.', '1979-04-10', NULL, NULL, '2026-04-03T17:22:53Z', '2026-04-03T17:22:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
