INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32CF78EC349B4B729D62AB3E5F9385F9', X'DE8EC76916BB436BBE43AEDC7E18A7D7', 32, 'Big Bird''s Fairy Tale', 'Big Bird makes up a fairy tale about a bird named Birdie who helps a Beast learn how to be a good friend.', '2020-06-20', NULL, '/zvrbBMNXITVS61sbOx7zksP1CBc.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32D2120451FA410193D6C28093B8E476', X'70C8CB4624944DD498F66BFB9B3FAF73', 25, 'Gold Diggers', 'The Pawn Stars have an opportunity to buy a huge gold bar believed to be from a 1500s shipwreck. Will the gang dig in and strike it rich or will they end up on a fool''s errand? Then Rick has a chance to shoot for the moon with a celestial navigation dome from a World War II B29 bomber. Will his offer take flight or come crashing down? And later, a woman brings a mint condition collection of golden era American League baseball field passes. Can Rick hit the deal out of the ballpark, or will he strike out looking?', '2010-06-14', 21, '/y7yKiy3tyhIBqWHYIoFT3yVBiZJ.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
