INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32D8A2F1E39343A2A7ACF11DDCDC8604', X'5144DE59E67F4FCF919B7106989AB797', 20, 'Dancing Dragon', 'Skye and Kiki unwittingly invade Julie’s privacy by opening a package meant for her. Nuzzle and Sizzle cause some mischief with it.', '1995-02-10', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32D91EF95E7E446B857E1458055AD9BF', X'879892836FEA40D78D9122C4947DB105', 9, 'This Land Is Your Land... Or Hers?', 'Robyn, Meri and Kody have a huge fight over who will get which piece of land. Janelle worries the whole family won''t get access to the pond. Tempers flare and everyone is lashing out at everyone else in the worst fight the family has ever had.', '2020-03-01', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
