INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32DCB0B40D104C9B9D1FC37E313405FE', X'73AE1459BA914185A9DABF6F2844AF49', 19, '21st Century Sonja', 'On the ladies’ last night in Cancun, Ramona addresses Dorinda’s anger issues in a group text; in New York City, Leah works to improve her relationship with her mother; Ramona sees a therapist; Luann preps for a cabaret workshop; Sonja hosts a party.', '2020-08-20', 60, '/empynKJScATt9P3eyALMl4pDDTR.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32DCE6CA3DAD4EF0AF2E4AF1F3786D57', X'5C4E51C6E20746AD875C72988EB1E13E', 26, 'Weird Science', 'The Pawn Stars travel to Utah for a rare shot at a 19th century Hotchkiss Revolving Cannon. A rapid-fire weapon used decisively in the Spanish American War, will Rick overwhelm the seller with an explosive offer, or will negotiations hit a turn for the worse and blow up in his face? Then, Corey and Chumlee try to get the party started, when an antique Wurlitzer jukebox grooves its way into the shop. Will the guys be able to stay in tune long enough to make a deal or will they be left singing the blues? And later, a woman comes in hoping to sell her antique medical quackery device. An electric zapping machine called a "Master Violet Ray," will this piece of weird science heal all of the shop''s problems or cause them to seek a second opinion?', '2011-08-08', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32E9487469144D4FA9020D2B3DAEEA3F', X'FFC2A75E0FFA4B26B1219B91B277594A', 21, 'Chasing Nay-Nay', 'The ladies return to Atlanta from the Philippines and immediately get back to work. Kenya is in the midst of shooting her pilot, Life Twirls On, as Cynthia strives to perfect her accent for the role as a Jamaican salon owner. Meanwhile, Kandi and Todd attempt to go on a romantic date, but Todd drops a bomb that leaves Kandi torn. Phaedra continues to feel the rippling effect of Apollo’s absence and is inspired to throw a charity event. Things take a turn when NeNe makes a cameo from New York and exchanges words with Claudia.', '2015-04-12', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32F80713902A46B794C3EA8D071574FF', X'05FA5E1878D241FEAE300C242C7FFB6A', 25, 'Let it Snow', 'Naughty Norman has his heart set on a Christmas tree.', '2003-05-02', 10, '/skHSVe5N3x31DBLJsZyH8o8d3gV.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
