INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'32FD9A63F9284403949DCE978BDAA89C', X'A6ED03E0C05F48F89F563F1DA50E1792', 3, 'Episode 1318', '', '1979-11-28', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'330AEF44EC644A5BB357D240B56F4D5A', X'136B81D3964D4B8FA21492F00D96D6B9', 80, 'A day at the library with Don Music', 'Don Music grows increasingly frustrated at the library as he struggles to complete a song, each attempt ending in failure and disappointment. Big Bird and the helpful librarian offer encouragement and remind him to relax. With their support and a fresh perspective, Don Music finally overcomes his writer''s block and finishes his beautiful composition.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'330D0C1B21134C38979F6BAE5DCB8C11', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 49, 'Big Bird practices magic', 'Maria and Luis welcome the viewer in Spanish, then Big Bird - or rather, "The Amazing Birdford," greets them. Big Bird has borrowed the Amazing Mumford''s magic kit and is learning how to become a magician. Susan sets three new plants on her window sill.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'330D69B3DAD6489982C0EF7E89A00E6C', X'208E80DE61E34A2F857FC667FFC29134', 21, 'Doug Henning', 'Fozzie Bear tries out a magic act, pulling a rabbit from a hat. Instead, he gets a rabbi, and then a robot. He taps the hat too hard, and gets dozens of rabbits, who follow him around and call him "Daddy."', '1980-03-14', 26, '/2BE3lTewbyPaCK9R45XGSX9PdcH.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'330E116EAEE2499AACA76C0F05B712AB', X'EC8D33228CA24E8D9D22268AEE320274', 5, 'Everything From Pawn to Nuts', 'A seller comes into the shop with some chef whites signed by the actor who played the iconic Soup Nazi on Seinfeld. Will Rick and Chum say `No deal'' for you or will they reach an agreement on price?', '2025-02-26', 42, '/eaTYYAMRipSHqOOxXWtw8xiGZ4p.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'331DFC3B2AB14D9A8F7CE04BB34CFC2F', X'05C0E384194C44179F62803EB615E409', 103, 'Roller skates', 'Rogers talks of playing with toys and reads the poem of The Land of Counterpane by Robert Louis Stevenson. In the Neighborhood of Make-Believe, Tadpole Frogg and Lady Aberlin pretend to roller skate. Lady Aberlin finds out that King Friday and Sara Saturday are in the R Room of the Castle.', '1968-07-10', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'332124149C074F47AEE4BFCB462A0B40', X'5A4E38A18E5449748097D7A7B48630A2', 76, 'Episode 76', 'with Valerie Singleton, John Noakes, Peter Purves', '1971-06-18', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'332BB17185B34D3B88083F791B844C53', X'98D80972E53A43DDA03A7703465E6F87', 26, 'Just Shoe It', 'Get your kicks with the Pawn Stars as Rick and Chumlee check out a massive collection of Nike shoes. With an asking price of $1 million, is this deal a slam dunk or an air ball? Then, an Arnold & Son longitude watch finds its way into the shop. Used for navigation on ships since the 1700''s, will Rick offer a boatload for this rare timepiece? And later, Corey and Chumlee eye a vintage handcuff collection. Featuring some of the most painful, and illegal, restraint devices ever made, do the guys try to lock this deal up, or does something rub them the wrong way.', '2013-02-11', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'332DD56C323344939ECDE09E82A35C67', X'1A534647384B4C00BB6CA3371AD962EB', 19, 'Son of a Gun', 'Get fired up with the Pawn Stars when a 1800s Wilkinson turret rifle shoots into the shop. Will Rick go in guns blazing or will he fail to pull the trigger? Then, Chum buckles up when celebrity engraved matchboxes from the private jet, "The Starship One" flies in. Will he be able to land these collectibles or will the price be plane crazy? And later, Chumlee volunteers to help the guys write descriptive cards for the shop. Will he get his facts straight or will he need a history lesson?', '2015-03-19', 21, '/nJ6WaG8j9B0HzYPMXMoJbzPuzvk.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
