INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'333724430A2B4CE68591CDE46FC61257', X'119C16D5104745EC8242C72A8EED423B', 45, 'Bully for Binky', 'Binky is the toughest kid in school and everyone is afraid of him.', '1996-11-06', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'333DDD8B62DD47B6A1E99459D3369BE3', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 9, 'Bert’s Pigeon Search', 'Leela fixes Elmo and Abby''s rocket and they begin playing spaceship, making "brr brr" sounds for their rocket. Bert rushes in, thinking he''s heard a blue-bar pigeon. He shows them his Pigeon Life List, featuring seven different varieties of pigeons. He has a check for each one, except a blue-bar. Upset, he leaves for home. The two decide to help Bert out by finding the pigeon for him. Abby magically whips up some safari gear and they use their binoculars to look for a bird. They see one in the distance and go to him.', '2010-10-12', NULL, '/vW2OlTna7B0U61xnlwn2guQxkJl.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
