INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3342F9475A734B9BB5B6D5CA22933496', X'1415EF1C411A4C26814A7C79C3628BC2', 19, 'Thank You and Good Night', 'After moving out of Sonja’s townhouse, Tinsley has Carole over to see her new digs. Luann and Tom challenge each other during a game of tennis. Bethenny deals with the stresses of renovating a new apartment, but finds distraction with a hot, new fling. Dorinda has John over for a romantic dinner, while Sonja and Frenchie talk about their upcoming trip to France together. The ladies all come together when Tinsley throws a thank you party for Sonja.', '2017-08-09', 60, '/xValwsSz9TKX0fQjNjGzW9RRnxI.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
