INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3349E00CACBE4401A3AAC0CC8A6195FC', X'CC140989C4804586B4608872B416A0B7', 2, 'Stay Away from the Junkyard!', 'LeVar decides it''s time to clean out the things cluttering up his house. What he finds is only memories of his entire life. None of this is junk, as it turns out. Michelle Mariano reads the story of a young girl visiting relatives who befriends the local junkyard manager, even though the rest of the town avoids him and spreads rumors.', '1989-07-04', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
