INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'336FA970404B4CE3AD23720174380075', X'5DB3FF78E43948E18F67988ECBF85D17', 7, 'Dogtanian Meets the King', 'All the guns in a man''s shop are stolen by le Faucon Bleu, the worst & most notorious thief and pirate in Europe. He leaves a message "Watch out tonight danger is near, for I have come to Paris", a musketeer rides through the streets telling people to lock their doors. That night only the Police, Guards and Musketeers dare to go out, even Dogtanian has locked up the house. Outside the city the Blue Falcon and his gang of thieves are scheming, the Blue Falcon scales the city''s wall to put his plan into action...', '1981-11-20', 24, '/zVe8rL9Cb836ZNHjljFayGOEik5.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'33761156102D476891A6147BBE1FD43E', X'02849655BD954D8DAF3B03321918EEEE', 3, 'Madeline and the Can Can Cliques', 'While she and the other girls learn to dance the Can Can, eleven little girls form two cliques, and Madeline is caught in the middle, much to her dismay.', '2000-09-22', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3384DFA2E2FF4016911D85BEAE193FB8', X'61E0C9D9337E4FE4A0FDE567B29AF115', 13, 'Rooms for Improvement', 'There is trouble in paradise as the ladies embark on their trip to Puerto Vallarta. Angie feels slighted after Meredith''s bat mitzvah. Bronwyn and Lisa have a falling out over room assignments. Mary chooses to stay in Salt Lake City as issues with Robert Jr. come to a head. Britani makes a new announcement. Bronwyn comes to terms with Gwen''s decision about her grandparents.', '2024-12-11', 43, '/awyDgTsJ1XLIWMiLhKq58DupMLA.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'33869D0205B1441480209236A5873D93', X'F4C403079B5E4263A4E0DFA138131E7F', 14, 'Kids'' Favorite Songs', 'Kids'' Favorite Songs kicks off with a cackle-worthy parody of Bob Dylan doing "Old McDonald," and from there the groovy gags keep comin'' ''round the mountain. Everywhere Elmo turns on Sesame Street monsters spontaneously burst into song, and all because they want him to feature their favorite tunes on his forthcoming radio countdown. For Telly, winnowing the hits to one is akin to Cookie Monster choosing between a macaroon and a figgie bar: at first he''s sure that "Twinkle Twinkle Little Star" lights his fire, but then he says bye-bye to a black sheep. The street heaves a collective sigh pavementward when word comes down that the countdown is strictly a numbers gig, no music involved. Only Sesame Street could weave well-loved musical numbers around a simple numbers lesson with such wacky pizzazz, making this a countdown that''s no letdown for high-spirited parent-preschooler combos.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
