INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'33EE7597A8C7400CB4AD41E2D16C0AB3', X'1D556682D9BB47E1993F0B648A8DAACD', 70, 'Episode 1255', '', '1979-03-02', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'33F05AD4F7B64ED2A341EB8B199F7012', X'36EA381466B44986B6EE44559D3562C1', 20, 'With Friends Like These', 'NeNe, Gregg, and Peter''s altercation stuns the rest of the group. Cynthia is forced to once again contemplate her friendship with NeNe. Kenya continues on her journey to become a mom. Kandi begins to have second thoughts about casting Porsha in the upcoming musical.', '2014-03-30', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'33F297658FFC41F2B773BB622F9C1E11', X'0FA9200282AE460985E33982BAA99AE1', 20, 'Postman Pat''s Island Shipwreck', 'Ted saves the day when Pat''s boat trip goes wrong.', '2005-03-24', 15, '/p1J37OifWcWvxum66JFCyUewMyI.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'33FEC97DDF5F4EE1A69767DA275DCBD0', X'3087A3EDE94E42769D02A78183DEA1D3', 16, 'Peaches Don''t Grow in Hollywood', 'The women visit Los Angeles, as NeNe anticipates showing off her glitzy Hollywood life. Yet tempers explode, and Kenya sounds off against her rivals, Phaedra and Porsha.', '2013-03-03', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'33FFDB0D65524AD08A8A1FE7AA6B59CE', X'ECB64EF34F8045A7B4A9C04434B02E35', 37, 'Spruce Goose', 'Wing it with the Pawn Stars when a test piece of Howard Hughes'' Spruce Goose flies into the shop. Will Rick and Chumlee take off with a part of this famous aircraft or will the asking price be sky high? Then, Rick sees stars when celebrity paintings by artist Stephen Fishwick are brought in. Can he see the big picture or will he paint himself into a corner? And later, it''s any man''s game when the guys make a wager over which donut Rick will eat. Will one of them scoop the pot or will Rick put an end to their hunger games?', '2014-05-08', 21, '/5MY3FLeUPwaWsYkSw5h1btatlXP.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'340189818BE94D4891737247DAFD16FE', X'6053B5C1CE86425C8166E0FCC3466061', 12, 'Episode 12', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-10-23', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3406BE705D6B490CBCF0678CCBC0402E', X'C21DBD225E2E4414BB67750399AAF6F0', 1, 'Mile High Club', 'The Pawn Stars prepare for a dogfight when their radar locks onto an L39 Albatros fighter jet. Used by the Soviets to train their pilots, can Rick and Chumlee fly away with this Cold War era prize, or will they get shot down before they make it back to base? Then, a guy slides in with a bat and glove signed by Babe Ruth. Complete with letters of authenticity, will the guys be able to knock this deal out of the park, or will this negotiation go into extra innings? And later, Rick and the Old Man are presented with a set of antique glass target balls from the 1800''s. Similar to the type used by Annie Oakley, will they hit a bull''s-eye on this deal, or end up missing the mark?', '2011-11-28', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'340D1162FC834F83BAC0597E40A6B3A0', X'23C93536610C41C5AC6BA6B243423258', 6, 'Shady Waters', 'The group is shook as they navigate the fallout from the messy breakfast. Gizelle returns to Lake Norman. Mia takes the ladies on a detour to unwind before trying to work things out with Keiarna. At a celebratory dinner for Wendy''s 40th, Jassi opens up to the women about her relationship, but some details aren''t adding up.', '2024-11-10', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'340F2FCDD8C643E7BDF6A654750F4196', X'AD180412A5D64E4A8B49590334F2FC69', 5, 'Tiffs And Tempers', 'Weasel and Measley find a seemingly nice burrow for them to live when they discover it is being occupied by vicious wildcats. Their loyal "weasel dog" Rollo comes to their rescue. Meanwhile, Fox confronts Trey and tells him that he''ll either come to hell or high water, Trey will respect the other animals of the park and he will step down as leader if one of the stags can fight against him for Leadership. Also Ranger, Charmer, and Whisper confront Bully for the first time and he makes his intentions clear. Charmer manages to kill one Rat. His name gets mentioned as Scragg.', '1995-10-26', 25, '/eUlfRu2YV2kjRRdPvnmooVjth9r.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'341969B121754D1E89C882B3E07E56C7', X'1D556682D9BB47E1993F0B648A8DAACD', 60, 'Episode 1245', '', '1979-02-16', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'341CAE82F04348469714C3043F59A927', X'C21DBD225E2E4414BB67750399AAF6F0', 5, 'Buyer Beware', 'Hat''s off to the Pawn Stars, when a man brings in a signed print of Abraham Lincoln. Will Rick write off this presidential paper as an impostor or will he decide this Abe truly is honest? Then, the guys are presented with a turn of the century parade cannon. Originally used to salute Civil War veterans, will Rick pay tribute to this rare piece of ordnance, or will he rain on the seller''s parade? And later, Corey and the Old Man encounter a steel mandolin from the 1940''s. A bit worse for wear, does this rusty relic have a few songs left in it, or will the seller be strumming the blues?', '2011-12-12', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
