INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3432983D6B2043DA88EE8DEF6CFF6AF2', X'05C0E384194C44179F62803EB615E409', 129, 'Meeting Robert Troll', 'Mr Rogers sings "Let''s Be Together Today" and Mr McFeely lends him an animal number book. Robert Troll makes his first visit to the Neighborhood of Make-Believe because he wants to see Sara Saturday in Westwood. However, he must wait a day for Westwood''s wise women.', '1968-08-15', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
