INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'346ACC02BD2F48EBA97A414E639C0164', X'50EE8F6C645C4D48BAB953B9F8F7FF2F', 11, 'Baby Bear''s doll', 'Baby Bear and Curly Bear are playing with dolls, and Telly comes by with his bulldozer. But Baby Bear''s embarrassed to be playing with dolls, so he tells Telly that the doll is Curly''s.', '2011-10-21', NULL, '/4piEKr6XlV6Icv51fOzvHciOAnd.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'346B641F912F4BB6A6AFC53E714642E9', X'1D556682D9BB47E1993F0B648A8DAACD', 26, 'Episode 1211', '', '1979-01-01', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'346BBDD8ABC74CE6AB585B9E548BE296', X'FFC2A75E0FFA4B26B1219B91B277594A', 15, 'Chocolate Does a Body Good', 'With Apollo now in prison, Phaedra returns home and begins adjusting to life without her husband. Cynthia drops a bomb to Claudia and Kenya, leaving them both in shock and one in tears. Todd is caught off guard when Kandi mentions going to marriage counseling. When all of the ladies gather for dinner to reconnect, tempers flare as Cynthia and Kenya confront Phaedra about illicit texts on her phone and an alleged affair with the mysterious “Mr. Chocolate.”', '2015-03-01', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'347BB24767CB4850B3050AD8CF7DED24', X'C01DDD2ABDB14C978D0458F791EF1C24', 32, 'Spots and Stripes', 'Spots and stripes are great camouflage for creatures, helping them blend into their environments. When Zoboo, Chris and Martin see striped and spotted creatures (tiger cub, serval cats, Dalmatian puppies, coati babies and a skunk), they''re inspired to paint Animal Junction in spots and stripes. Zoboo takes that inspiration a step further when he paints spots on Martin and stripes on Chris while they''re both asleep. Zoboo paints himself with spots and stripes, and the gang learns about being a camouflaged creature. Jackie says that milk weed plants may look like weeds but they''re home for striped monarch caterpillars, so please don''t pick them.', '1999-09-06', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'34801E72FA42416C9E9F6BAD0DE7B554', X'9B95011E93DB4E56A45D8AA956C15997', 20, 'Pest in Show', 'On the day of the contest to find Pontypandy''s Most Talented Pet, Radar comes to the rescue of his fellow animal friends when a fire breaks out at the Wholefish Cafe.', '2014-08-16', 10, '/gUKvr4L8yb4wrTepxGHX9OKuVZs.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'34903417168D4A789498CBFB85737474', X'21384B9C43FA410CB89D102E7CF9129B', 14, 'While the Wives are Away...', 'The wives take a road trip to San Francisco, where they work on their relationships by shopping for dresses for their commitment celebration. Meanwhile, Kody stays at home with all 17 kids.', '2014-01-19', 60, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
