INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'34A7E064895A4125B80F62F5710AB411', X'8730C55E844344B0AFEFA369C478B14F', 18, 'Sharing Song', '', NULL, NULL, NULL, '2026-04-03T15:26:09Z', '2026-04-03T15:26:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'34AA701587BE4C1DAF1FE07B0A277ACE', X'5A771F52FE964EA2B567A8DDE899059E', 28, 'The Pistol Is Mightier Than the Sword', 'Rick takes a stab at a sword with an attached pistol from the 1700s. Will he hit the bullseye or shoot himself in the foot? A portrait of legendary film and theater actor John Barrymore takes center stage, but will it perform well with Rick and Chum? Later, Rick is pointed to an antique navigational timepiece used by ships in the 19th century. Is he destined to buy it, or will he lose his way? Corey gets revved up over a 1969 Harley motorbike, but will he tire of it too soon?', '2018-05-14', 21, '/hqIuToG2FMSbtl0El3S3kaPOlck.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'34B1846A2A7D41AB9068894667650756', X'225B0F03984B47F3A1A3D3E92175E39D', 47, 'Episode 47', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-03-09', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'34B6FAF4A26B4B74B9708EED28118BC7', X'A8C6182E05E14B6891A55126CF6C94F0', 37, 'Born Free and Equal', 'Sarah, staying with Abigail Adams in Boston, is thrilled to see Mum Bett freed and resolves to fight for civil rights. In France, Ben Franklin hopes that news of Yorktown will convince King George to surrender to his former colonies. James finds himself in a tight spot as he digs deeper for the whole story.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'34BE246716604B0F951927911519CA2D', X'BF3FFAFD7D454F2C9F1B28001BD082DB', 42, 'Episode 42', 'with John Noakes, Peter Purves, Lesley Judd', '1975-02-03', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'34BE3B63DA9B4298AE7810080F410B48', X'40700E8A1DCE4895BEDE522A13A8BCAD', 13, 'Can You Feel It?', 'Brainiac, the chimp, and Lost and Found, the Labrador retriever would love to do something fun together. Zoboo first advises playing ball with Lost and Found, but Brainiac is bored because she doesn''t like to play. Next Zoboo suggests climbing and swinging all over Animal Junction but this idea makes Lost and Found sad. At last Zoboo comes up with a game they can both play-Wrestle & Chase! Martin and Chris go on a special trip and fall into a river, where they discover an elephant who is delighted to have a bunch of children give him a bath. Animals have feelings, just like people-they just have different ways of showing them.', '2001-03-16', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
