INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'34D11FF1140F4990B5515A2497678DE9', X'E4023DA233D74A2BA04ACA449BD23935', 20, 'Food Courting', 'A case of disrespect hits the Heck boys when Axl -- who is celebrating his milestone 21st birthday -- refuses to come home and help Mike move an old freezer, and Brick begins turning into a mini-Axl by dissing Frankie with a bad attitude. Meanwhile, Sue is torn over what to do when the manager of Chop Suey USA tries to woo her away from her job at Spudsy''s.', '2015-04-15', 22, '/rP1wlhWqMh1hrxN3T7wI5uipgq6.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
