INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'350E204EC3DA4219BF8014AC5580234F', X'FE19A277AED844DFA4ACFC1C4E9941B4', 7, 'Throwing Shade', 'It’s showtime for Lisa! With the debut of her clothing line Closet Freak, she is all business, trying to get everything done in time. Meanwhile, Sheree finds out that her She By Sheree fashion line debut will have to wait , yet again. NeNe gets tough on her college dropout son Brice, and Kandi calls in a favor to flip "Tardy for the Party" into a song for Kim and NeNe to record. Kim gets serious about launching her wig line, and does a little research by throwing a wig party.', '2009-09-10', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
