INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'354BA0D000FA44719404746EDD05B3E7', X'5B5E8B2F0A854488B3DC3D8B794E6582', 14, 'Armenian Rhapsody', 'Vicki and Tamra finally come face-to-face to see if there is any hope of redeeming their broken friendship. Lydia discovers the joys of when the rich get richer. Kelly''s dad comes to town and she discovers the parallels between her parent''s dysfunctional relationship and her own. Peggy and Diko celebrate their 22nd wedding anniversary with the ultimate Armenian inspired party while Shannon faces the consequences of her prying husband''s actions.', '2017-10-09', 44, '/5BbIFOWQAqqAmWHKzD2y00PTqJ3.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
