INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'35584EE16B2E4D85A3DB5689D0175C4C', X'EA1650C2E4F146C793BA74B5D45D08E5', 3, 'White Hot', 'Kandi travels to Palm Springs to offer advice and support to Kim, who’s been invited to perform at one of the biggest gay circuit parties –- the White Party. With only one song on her playlist is Kim ready for her first concert appearance? NeNe has an honest talk with Brentt about Brice''s brush with the law. After Sheree takes the high road with Dwight and his claims to have paid for the She By Sheree fashion show last year she reunites with her oldest daughter, Tierra who has moved back to Atlanta after being away at college. New housewife Cynthia struggles with her feelings about marriage, while Phaedra and Apollo don’t see eye to eye when it comes to parenting.', '2010-10-18', 43, '/2iTfdIFzn9Yz0aXmdWHNf0owrtS.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
