INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3562754E82054C63BF5CF92D1E9CF28B', X'EDC63A592FD4442A9343F2872D776BDC', 7, 'The Rhythm and Roots of Arthur', 'Pack your bags, buckle your seatbelts, and get ready for an ARTHUR road trip to the family farm! Arthur''s Great-Grand Uncle Theo is celebrating his 85th birthday, so the Reads (and Buster) are off to Ohio to join in the festivities. While D.W. and Arthur learn that farm life is a little different than life in Elwood City, Buster worries he may be getting in the way at this family reunion. With the help of Cousin Miles, some llamas, and a little bit of music, they all discover what it truly means to be family.', '2020-01-20', 55, NULL, '2026-04-03T17:37:54Z', '2026-04-03T17:37:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
