INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'356F314C171340AB937E26A2A228935F', X'7BC54DF3F32A454EAEF6A9436C35D53B', 34, 'Episode 34', 'King Friday hears about the baby platypus that will emerge soon. He tries to make the Platypus family leave the Neighborhood of Make-Believe so that his new baby will be the first born there.', '1970-03-19', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3571746341CA4AF883E985FFA757C690', X'871570B4BF2F4BA1994065FB932CB009', 5, 'Where Is the Love Boat', 'A booze cruise turns dramatic when an argument between Cynthia and Porsha escalates. Back on land, the group continues to clash over the events. Meanwhile, Kandi visits the doctor and faces troubling news, and the ladies try to unite.', '2015-12-06', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3571CA11B33A409E972F7B3440524906', X'02C86AE38C3B4CC08E1F0B27D01DCD91', 3, 'Who''s Your Poppa?', 'The ladies take a trip to the countryside to meet with Kim''s psychic advisor. After an eerie prediction of personal strife ahead, NeNe gets a letter from a family member revealing that the man who she thought was her father might not be. She must decide whether or not to pursue the paternity issue and risk opening Pandora''s box. Meanwhile, Kim has always wanted to be a country singer and decides now is the perfect time to pursue her dream. DeShawn must pull off planning a black tie gala for the DeShawn Snow Foundation in just two weeks. NeNe decides to help her and together they try to raise a million dollars for charity during the gala.', '2008-10-21', 43, NULL, '2026-04-03T16:34:44Z', '2026-04-03T16:34:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3573AB23C3354ADBBEA749E0B0524F9A', X'DE8EC76916BB436BBE43AEDC7E18A7D7', 26, 'Back to Nature', 'Abby and Rudy want to bring nature inside Hooper''s so Chris can feel like he’s outside. Abby uses her mom’s magic wand but makes a mistake and fills Hooper’s with too many animals and plants. Abby apologizes for using her mom’s wand without permission and together, with her mom, she learns how to fix her mistake without using magic.', '2020-05-09', NULL, '/4DyhPfABHXsO5Xfzs0VZbJk0brJ.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
