INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3576F85A15BB4283BA15A071E5A815D7', X'C21DBD225E2E4414BB67750399AAF6F0', 22, 'Cash is King', 'The Pawn Stars get the royal treatment when autographed memoirs from English nobility parade into the shop. Signed by King Edward VIII and the Duchess of Windsor, will Rick find these books fit for his kingdom, or will he abdicate them from his shop? Then, the Old Man and Chumlee are presented with an antique collection of 1950''s tin army trucks. Will the Old Man make a play for these classic metal toys, or should they have been recycled years ago? And later, a man rolls up with a Sun Tune-up Tester. Used for fixing cars in the 1970''s, will Rick crank up a good deal or will this outdated technology be in need of its own fine-tuning?', '2012-02-06', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
