INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'357B3C472C1540428BDF48D3BA4FD26C', X'A0FA50759CE148C199950C0FD866E549', 5, 'High Horses and Low Blows', 'The sand settles after Oceanside, but the ladies return home with unresolved feelings. Garcelle enjoys her recently finished beach house. Erika navigates deep-rooted emotions with her therapist. The ladies swap their high heels for cowboy boots at Kyle’s western party, her first solo event since her separation. Boz defends Dorit when Sutton delivers some low blows, but her efforts are interrupted when old friends and past grievances resurface.', '2024-12-17', 43, '/76ygK3OMkp6KZ6VRXeUvhMl0VFK.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
