INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'359CE7760B8947A0AAA6494722B8A9B7', X'4A8E3DB080684FF3942F91F45F665F20', 22, 'Red Hat, Green Hat', 'Leona makes her very own hat, with one red side and one green side. When she walks through the library with it on, one group of people see the green side, and the other group sees the red side, causing a great big argument among everyone!', '2000-05-02', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'35A1362C22054C15A1D6D05E172B1179', X'B1D55597D9D24EEEAB9546DBB163291A', 16, 'Pingu and Pinga Stay Up', 'It is time for Pingu and Pinga to go to bed but they have other ideas. First they play with their blocks and fakely fight over them, and then mum tells Pingu to brush his teeth and he goes by shuffling with the block boxes on his feet. Pingu brushes the bathtub instead of his teeth, then knocks Pinga''s potty, and mum finally manages to get them to go to the bedroom. At first they tried to leave when she wasn''t looking. They keep demanding things such as a teddy, pacifier, fish, or bottles. When she stops coming to their demands (though Pinga made one), they go out to find their exasperated mother asleep. They move her into the bedroom and finally go to sleep all together', '1990-04-07', 5, '/1Yq19cS4B2zP56NPJgHIBNHCh2K.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
