INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'35A33437412949DC9DF13690FC8ED56C', X'C6D5CF79F2B040AFAD1291AA4F1B1D21', 1, 'I Came, I Saw, I Pawned', 'When a seller strolls in with a collection of action figures signed by the cast of "The Walking Dead", will Chum bite? Then, Corey is too cool when a "Rock n Roll High School" poster comes into the shop. Will this deal be music to his ears, or will the beat fall flat? Next, Chum tries to catch an unusual Pok mon card. Will he succeed, or make a ghastly error? And later, Rick and Corey head to the range to check out an 18th century cannon. Will this negotiation end with a bang, or fizzle out?', '2022-04-23', 42, '/sDOsr2TTa4bZDvh2ChcMWzw1aF1.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
