INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'35ACBE1D86ED43ACA181A7502EED1676', X'EBC99729CCB74D6482C142708CD7BA85', 58, 'Episode 58', '', '1981-03-30', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'35AE5619AE9544B4AB3E05A66004AB5D', X'5BA20443D99F482081F66832D3F2BC4F', 9, 'Pseudoscience', 'People once thought that world was flat or nearly flat. It was considered a bit crazy to think of it as a big ball. But it is. You can prove it. One of the big ideas in science is that ideas can be tested. Scientists test claims. If one scientist claims that she or he can fill a balloon with invisible gas using vinegar and baking soda, other scientists can try it and see if they get the same result. Sometimes ideas are wild, extraordinary. And, the claims that go with these way-out ideas are pretty extraordinary as well. The round Earth is an example of an extraordinary claim that needed extraordinary proof. But, there are many people, who believe in extraordinary claims without looking for extraordinary proof. We scientists are always on the lookout.
