INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'35CFD2EC6B6640048EF730B630EB29D6', X'F13CB62284E34654A8F10CEAB09A9CA6', 26, 'Franklin''s Picnic', 'Franklin is sure that he won''t like anything spinach, or lots of unfamiliar foods in general. Bear seems to agree with him, but the two find themselves facing this issue head-on when Beaver organizes a picnic and those in change of bringing the food announce plans to bring some pretty strange-sounding things.', '2002-07-22', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'35D5CBB6CE8F4C03A753BB2C8D5E4943', X'227B84290DFD47E4B874C37DA20C403F', 22, 'Pawn Shop Pinot', 'When Rick and the Old Man buy an antique 19th Century wine-maker, Chumlee wants to put it into action. Will he succeed and brew a magnificent "Pawn Shop Pinot"? The Pawn Stars also consider buying a 16th Century replica signal cannon used to call ships as Rick looks at the priciest pawn ever to enter the shop - a semi truck.', '2009-12-21', 21, '/qNunJlOJe4dfBefdLDo1NB1cQFx.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'35D7F7B9AF334284A72075150095E1AB', X'9BD388DEF7FB4A7084583DB458A2ABF0', 9, 'Be Yourself', 'Rogers brings a sleeping bag into the television house. Mr. McFeely brings in a tape on how sleeping bags are made. Rogers visits a dollmaker, Ida Clowney. In the Neighborhood of Make-Believe, X feels responsible for the fall Prince Tuesday incurred. Lady Aberlin and Chuck Aber deter Lady Elaine from further "flying lessons".', '1997-09-05', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'35DB4806AEDB4FBCA190EEA359E5C8B0', X'83D1C2FB7CD949779A5D98D36CFB59D3', 1, 'Episode 570', '', '1988-11-21', NULL, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'35DEC56A220C4D3984C15ED4179E231B', X'3A96D6C63736498A926F6C479CDFB73A', 10, 'Franklin Is Messy', 'Mr. & Mrs. Turtle are always on Franklin to clean up his room. Franklin never seemed to have time to get around to it until he accidently stepped on his favorite toy. He also realized he couldn''t find anything. He starts to organize his room with his dad''s help and eventually have everything in place.', '1997-11-20', 12, NULL, '2026-04-03T17:40:14Z', '2026-04-03T17:40:14Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'35E1B7522D784D45AC2A1CB47A2DFC1B', X'3EA743EF0A2247CFB1D262F37E939253', 15, 'Telly Takes Care of the Grand High Triangle Lover''s Favorite Triangle', '', '2002-02-22', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'35E3AD46F8D941FBBD543281D59394C7', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 43, 'Grandma Grace surprises David', 'Big Bird greets David at the door of Hooper''s Store and says he can''t tell him anything about the surprise waiting for him inside. But, through a series of unsolicited and inadvertent clues, David figures out that it''s his Grandma Grace. When he opens the doors and gives her a hug, Big Bird takes to Maria finds Forgetful Jones holding a fishing rod over the basement rail of 123 Sesame Street, saying he''s trying to "fish for an idea.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'35ED40A751D04811B066BCB2FC143612', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 86, 'Snuffy wants to be a cabbie / Telly is Oscar''s dog', 'Snuffy greets Big Bird in the yard wearing a cap and speaking with a New Jersey accent. Snuffy has decided that since taxi cabs cost a lot of money (and he only has 75¢), he''s going to carry people around on his back.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'35F5E565E8284F0591CAF51A871EC06F', X'41328FEFC1854924A8B0791B5B84F8FD', 19, '*Bleep*', 'At a glass shop, D.W. overhears a word she doesn''t know. D.W. is afraid to ask anyone what the word means, because she thinks that it causes people to break stuff. Arthur and the Tibbles warn her not to say it in front of grownups, or they will become zombie slaves (or at least the Tibbles say...). D.W. and Nadine put it to the test by having the neighborhood kid Vecita say it to her parents. D.W. accidentally says it to her mother while spying, and after apologizing to the neighbors, Mother tells her what the cuss word means. But the next day at school, all DW''s friends are saying it. Here we go again...', '2003-12-26', 13, '/bgBSc6DGciRHjuwtGncjhJxbmkw.jpg', '2026-04-03T17:37:57Z', '2026-04-03T17:37:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'360935BBC0DB44E5985133BFB3CEA03F', X'E40E6B639F84449F8E8853209B0906C8', 22, 'Chris Teaches Elmo How to Bowl', 'Gabi encounters Chris and some kids playing with his toy bowling set, which he''s had since he was a kid. She asks him if she can try it out, since she''s a good bowler herself. Gordon then asks for a turn after Gabi. She gets a strike, and Gordon knocks down two pins.', '2007-10-05', NULL, '/2oJFEz3YSs550HU9OoMjbHvx5Of.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'360E89213B384C71A7C19FAB7AA7CE6B', X'D920EBAEF00A4E25ABFE40492C74DED6', 25, 'Pawnfellas', 'When a World War II mortar storms the shop, can Chum fire up a deal before it implodes? Then, Rick Walks the Line when deciding to buy handcuffs from an iconic prison. Next, a tux worn by actor Ray Liotta swings into the shop. Will Chum be a Goodfella and buy it? Later, Corey and Chum get their hands on a bar of soap that claims to cure obesity. Rub a dub dub, will this soap get rid of the chub? Finally, Rick gets a mint chance to buy some real history, when a friend brings him a document signed by George Washington that will cost more than a couple of cherry trees.', '2020-07-06', 42, '/eZh5qttY4mxBCVRppY7l0RRcvUj.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'361A26EE27154262BFD71963F0F89B22', X'04FB713D9C5945F78DE0ACD7582DAA53', 3, 'The Jersey Breakfast Club', 'As tensions mount between Melissa and Teresa, all the ladies head out on a girls’ trip to a cattle ranch in Oklahoma. Jackie shares shocking personal details and Melissa reveals a family secret, leading Teresa to explode and forcing all the ladies to choose sides in an epic argument between the two sisters-in-law.', '2018-11-21', 43, '/sMyP2NAfoboGQscXi6Jwvy65Xm5.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'361BA580A58D4AEF90B42BD6CE4215CE', X'CA70502BD8624CDD8071468D6644D517', 4, 'Chapter Four: Dear Billy', 'Max is in grave danger... and running out of time. A patient at Pennhurst asylum has visitors. Elsewhere, in Russia, Hopper is hard at work.', '2022-05-27', 79, '/u3LeFRR7AhyPp4y0Ii7hpkD488b.jpg', '2026-04-03T15:40:40Z', '2026-04-03T15:40:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
