INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3668B1056E9141F499971D0378E3D04E', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 91, 'Telly tries to draw Oscar', 'Oscar finds Telly attempting to draw a portrait of him from the real Oscar''s descriptions, but everything comes out wrong as they have conflicting perspectives. Big Bird and Snuffy sing a song about friendship and loyalty. Later, Oscar and Telly watch a film about drawing, and Telly appreciates Oscar''s honesty about his appearance despite harsh descriptions.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'366C3FB8D5184E4B80AAE19DF531DF7A', X'D1863F2F02EC40CEAF64DB03FBE518A7', 19, 'Move It!', 'It''s ''Move It Day'' on Sesame Street where everyone moves their body. But after spending the day just sitting and eating cookies, Cookie Monster learns that exercising and moving your body gives you lots of energy and helps you feel better. Also featuring a song with Ne-Yo, Murray had a little lamb, and Elmo''s World. Brought to you by the letter M and the number 8.', '2016-05-14', NULL, '/6mLCLsC3PdSECDqU18uIglBi5pn.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
