INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3699280820484281A093055390AFFE2A', X'01B3A1E3D0E84F2BA56D9D55669AB5F2', 3, 'Not Social but Very Distant', 'The wives come to a major decision about the property lots. Christine is leaving to take Ysabel to New Jersey for surgery, but Kody''s refusal to go leaves Christine angry. Then, a member of the family has a big announcement.', '2021-12-05', 61, '/fpNEeng3FzSsM8teyZWDP90846D.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'369A7040960B4E2ABBDE9EAB0A86944C', X'40700E8A1DCE4895BEDE522A13A8BCAD', 24, 'World of Legs', 'Zoboo spies a larva and wonders what kind of legs this animal will have once it grows. Will it have strong legs like a tiger, hundreds of legs like a millipede or long ones like a kangaroo? When the larva finally transforms into a salamander, its legs are like nothing Zoboo imagined they would be!', '2001-06-01', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
