INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'369F3F98E39E4D4D9A586746037C0043', X'244B0A34284B4EC1B3A70E5ABFF6D0D1', 10, 'When Carl met George', 'George is excited about spending time with his new friend Carl, who seems to know all kind of cool facts about trains and about... well lots of things! Then George learns that Carl has Asperger''s Syndrome - a form of autism that makes Carl see the world differently than most people.', '2010-04-05', 13, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'36A8AA2B993341F3AB8B4BDD668345AC', X'0BBD380C5CB846A68838B5D60223C073', 17, 'Valerie Harper', 'This is one of only a few Muppet Show episodes that open the show after the theme song with some kind of offstage scene. There''s also a couple of scenes with the guest star in her dressing room conversing with Muppets instead of onstage in the Talk Spot. In last week''s "At The Dance", Boppity danced in drag with another monster. This week Boppity appears as normal but his partner is in drag. In both instances, he ends up headless.', '1977-01-02', 26, '/x0sfeFUyVRuGopIB1MBvJRYSCpC.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
