INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'36B17E24D6A343A98B40E59E1D4B39EC', X'98D80972E53A43DDA03A7703465E6F87', 20, 'Spare the Rodman', 'The Pawn Stars get a fast break when the ex-wife of NBA star Dennis Rodman drops by. Trying to sell a collection of Rodman''s signed jerseys, will the guys jump at the chance to own a piece of sports history, or will heightened emotions cause them to foul out? Then, Rick and Chumlee prepare to flee when they''re presented with a jury questionnaire from the O.J. Simpson trial. Do they vote unanimously to buy, or is the jury still out? And later, a BMC pedal tractor from the 1950s plows into the shop. Will the guys make hay while the sun shines, or put this relic out to pasture?', '2013-01-21', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
