INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'36C0BD6D03C24637AA3C55A8D2C9E88B', X'F30BBF8187704E74B68B280E7C85B52F', 7, 'The Revenge', 'George quits his job in a huff after he is demoted to using the regular bathroom. Newman tells Kramer that he plans to jump off the building. Jerry suggests that George just go back into work next Monday morning and pretend like nothing happened; however, that doesn''t work. Newman jumps, from the second floor. George plots revenge, and with Elaine''s help, tries to slip his boss "a Mickey." Jerry suspects that his launderer is a larcenist after he discovers that $1500 he had stashed in his laundry bag is missing. Kramer helps Jerry get revenge by bringing a bag of concrete in to put into one of the wash machines.', '1991-04-18', 23, '/pQZDgs2VmFxBIBLQlrm02kft6hV.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
