INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'36D3D28BC77D4280A16168E6248FC0E1', X'5A771F52FE964EA2B567A8DDE899059E', 12, 'The Devil Went Down to Vegas', 'The Pawn Stars dive right in with a folding bike used by paratroopers during WWII. Will they stick the landing or collapse under pressure? An antique German clock winds up in front of Corey. Will he chime in with a good offer? A fiddle signed by "The Devil Went Down to Georgia" singer Charlie Daniels puts Rick in a bind, ''cause he''s way behind - is he willing to make a deal? Later, Rick tries to dig himself out of a hole when an old miner''s self-rescuer falls into the store.', '2017-11-20', 21, '/wVQb3fMY3xZ1Od12xdlGgoK922T.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
