INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'370A044D47C84881889A3434FEFBA529', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 9, 'Pawning Reagan', 'Get stumped with the Pawn Stars when a rare double lock musket comes into the shop. Will Rick and Corey take it lock, stock and barrel or will it leave them gun shy? Then, Rick is offered an autographed photo of Laurel & Hardy. Will he make an offer or will a small detail leave him seeing double? And later, when Corey comes face to face with a Ronald Reagan foam head, will he find himself making an offer on the "Gipper"?', '2017-05-15', 21, '/clp2WoQmBC3Vz1qspRMMRPjztz6.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'370F2EBEA7D14AABA123C859CA6A4E6D', X'A75DC15E67DF4DB29E0F8B9901DBAB51', 2, 'Rumpelstiltskin', 'Boasting about one''s daughter is one thing, Telling the king she can spin straw into gold is quite another- especially when the penalty for failure is death!What will the millers daughter do? call on the assistance of a strange little man who in exchange for spinning straw into gold -- wants her first born child! The only way to save herself from a terrible fate is to guess the little man''s name.', '1982-10-16', 51, '/rv9IzyjOrt3mIPak0Z1TGz4C5vp.jpg', '2026-04-03T17:38:40Z', '2026-04-03T17:38:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
