INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'371CD79166094B59B87C71688CA1C5FF', X'D920EBAEF00A4E25ABFE40492C74DED6', 13, 'A Bombsight For Sore Eyes', 'Things get heated at the shop when a seller brings in a trophy awarded to basketball legend Julius "Dr. J" Erving. Will this trophy be a slam dunk or an air ball'' Meanwhile, Rick targets a bombsight from WWII. Will he hit the bullseye or miss the mark'' Then, a seller brings in some antique quack medicine bottles. Will Chum buy into the old fads or will the pill be too hard to swallow'' Next, Rick says hello to a little coin nicknamed the "Scarface." Will it be worth the pretty penny the seller''s hoping for'' And later, the shop gets artsy when Corey and Chum thumb through a book of etchings by Henri Matisse. Will it prove to be the masterpiece they''re hoping for''', '2020-03-09', 42, '/q0kCVArqfz5jZ7taiESxkaxwcEH.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'371CD8AA80DF4529AC83D253EFDD4D2F', X'7BC54DF3F32A454EAEF6A9436C35D53B', 63, 'Episode 63', 'Rogers makes modeling clay, a perfect spot for son Jamie to discuss clay figurines. Dancer Ethel Winter is toured around the Neighborhood of Make-Believe and Someplace Else.', '1970-04-29', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'37251BACC45D4E37AD074845A779FEA8', X'5A771F52FE964EA2B567A8DDE899059E', 24, 'Pawned and Confused', 'A seller drums up excitement for his Led Zeppelin vinyl albums that’s music to Rick and Chum''s ears. Will they think these records rock enough to roll out some cash? An elaborate 19th century office desk is a formidable piece of furniture. Will Rick move to file it under "must-haves", or will he remain stationary? Next up to bat is a game-used base from the 2016 World Series. Will Rick and Corey think it''s a steal, or will they walk? Later, Rick takes a trip to see "The Object," an obelisk-shaped item featured on the cover of Led Zeppelin''s "Presence" album, but will the seller have objections to selling such a rare find?', '2018-03-05', 21, '/A9vhv2peITWj3TMX7goEyOynOT3.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
