INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3785A4692BFD4A2B986A06996FEB7B10', X'EDC63A592FD4442A9343F2872D776BDC', 5, 'D.W. and the Beastly Birthday', 'In this all-new Arthur movie event, D.W.’s fifth birthday doesn’t go the way she had always imagined it would and she chose to escape to the magical island of Ukubonga. Meanwhile, Arthur has skipped her birthday party to go on a school trip to the planetarium – but instead of transporting him into outer space, it transports him four years in the future!', '2017-05-29', 55, NULL, '2026-04-03T17:37:54Z', '2026-04-03T17:37:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
