INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'37C2B867003848F29D8C8E123DBA3382', X'3ADE5E1F84414C2CACF6FB933A61DCFA', 14, 'Open House and Closed Doors', 'Ashley is brought to tears after making contact with her dad. Meanwhile, Candiace and her mother are still at odds, but Dorothy proves that old habits die hard.', '2019-08-11', 42, '/xEGAyud8E6iXOD3DHwkX632bpss.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'37C711BA8B014CC2AA5838488001A29F', X'4900FC8D5E7E408E972ECE9269D203B3', 9, 'Runaway Husband', 'During the ladies'' final night in Cabo, tensions rise and Emily takes a fall. Back in the OC, Gina starts to question her friendship with Noella, meanwhile Shannon hopes to strengthen her friendships with Heather and Emily. Emily throws a game night, and Dr. Jen and Ryne come to a crossroads in their marriage.', '2022-02-09', 44, '/x9YKzbESpEkStUwZAtEFH3mjV5T.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'37C8020B528B4500854A83DE5EB4CBFB', X'DFA60F316EF14BEEA9AD554B68A5448B', 4, 'Journey to the Red Center', 'Steve and Terri journey to the Red Desert at the heart of Australia. They examine venomous snakes, lizards and endangered mammals as they make their way to the world famous Uluru, also known as Ayers Rock.', '2000-12-17', 44, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'37C8FBB8A4B644239C8F3D933C78E9AC', X'5DB3FF78E43948E18F67988ECBF85D17', 19, 'Dogtanian Is Put to the Test', 'Dogtanian continues pursuing The Black Moustache, on the way out of the Musketeers headquarters he runs into Athos who''s showing off his new baldric. Dogtanian tries to see the back and makes Athos look a fool when he finds out the baldric doesn''t have a back. Athos challenges him to a duel, Dogtanian agrees and arranges it half an hour after his duel with Porthos. Dogtanian resumes the chase and runs into Aramis, as he''s approaching he accidently kicks a stone at Aramis'' girlfriend, leading to another duel again half an hour after the duel with Athos...', '1982-02-05', 24, '/jjvqt0H2wjPYeymtfLlKip7ryzf.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
