INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'37D8A1F115BA481A81136432A70DC850', X'BFDF87FF01DD4B5494BD19B384F41BDB', 2, 'Making Friends But Not Amends', 'While Heather travels to Turks and Caicos to help Terry reconnect with their kids, Tamra tries to save Ryan and Sarah''s relationship. Meanwhile, Kelly decides to befriend Vicki against Meghan''s warnings. As Shannon continues to rebuild her relationship with David, Vicki does the same with her business. Later, Meghan invites the ladies over to her new house to demolish her kitchen; however it''s Kelly who seems to smash her chances of friendship with the girls when she reveals she has befriended Vicki.', '2016-06-27', 44, '/25w8ltQVaChvt20bWYewDBANPmm.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
