INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3886490C2E6B43B09EA3E396FCE281F6', X'BFDF87FF01DD4B5494BD19B384F41BDB', 17, 'Puppet Strings and Tamra''s Wings', 'The Ireland trip ends with the conclusion of the bus ride from hell. Back in Orange County, the women try to make sense of their war on foreign soil, while Meghan escapes to St. Louis to get away from the drama. After months of strict diet and exercise, Tamra is finally ready to flaunt her body on stage at her long awaited fitness competition and the ladies gather to cheer her on.', '2016-10-24', 44, '/sGczUQNQOxOllsKrudpAln5TSjf.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3887E7B6905A42F280D47E3F5F12CB5A', X'5A771F52FE964EA2B567A8DDE899059E', 13, 'Revolutionary Rick!', 'Rick celebrates the 500th episode of Pawn Stars by spending some capital in our nation''s capital. First up is a set of silver spoons made by American patriot Paul Revere. Can Rick cut a deal for this cutlery? Meanwhile, back at the Gold & Silver, things get lit when a talking candle prop from "H.R. Pufnstuf" fires things up. Later, a flamingo given away at the opening of the 1946 Las Vegas'' Pink Flamingo Hotel flies in.  Will Corey swoop in to peck it up? Finally, back in D.C., Rick gets his hands on two items worth millions of dollars that belonged to THE American forefather, George Washington.', '2018-01-22', 21, '/oWbt3JEB0LGodKRn0lpqIRyxeRA.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
