INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'38A22FED57F34FF2BD8C392876A8DB34', X'05C0E384194C44179F62803EB615E409', 2, 'King Friday Challenges Change', 'Title number 0002. Opens with Mr. Rogers arrives with a painting. Mr. Rogers shows how a burlap bag can be many different things when one imagines it. After he turns it into a cape, Betty (Lady) Aberlin comes to visit and he lends it to her for strength when she goes to visit her great-uncle, King Friday XIII. Meanwhile, King Friday worries about an invasion of people who want to change the Neighborhood of Make-Believe and drafts her as a border guard.', '1968-02-20', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
