INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3911642BBC0544BAAADD5AB4A1813BBC', X'6F731E6BD3C54DE684E17A19CB650E86', 24, 'Longshot Pawn', 'Take a shot with the Pawn Stars when an ultra-rare Nepalese Bira gun from the late 1800s cranks its way into the shop. Will Rick aim for a deal or dodge the bullet? Next, a 1970s Bob Peak TWA mural makes a big impression. Will Corey take flight with an offer or crash land? And later, a three-trumpet brass horn blares in. Will Rick squeeze out a deal or blow it?', '2016-01-27', 21, '/3zFK0ftlDL4HCy5cNxmHHUOdv72.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
