INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'393554D7FAA64017B68C05680F66320F', X'9E4790F43AAB459CA5ED7100B4E39A75', 3, 'Two Truths and No Shakshuka', 'The women confront Jenna for sneaking out in the middle of the night. Brynn arrives in the Hamptons. At lunch, the women grill Jessel over her incessant complaining and Brynn calls out a double standard. Over sushi, everyone bonds playing a scandalous game of Two Truths and a Lie.', '2023-07-30', 44, '/2Hand04LlNg4jkYlG0qhtxeH5KH.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
