INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'393F315E36B344DE96B447E1C75DB17B', X'C01DDD2ABDB14C978D0458F791EF1C24', 1, 'The Nose Knows', 'Toothbrush, the baby elephant finds Martin and Chris Kratt, roaming about in a cave where bats live. Since Toothbrush has been separated from her family, the Kratt brothers aide her in searching for them. This way, she will be reunited with them again. A garder snake is spotted, when Jackie was cutting the grass. The snake likes being in dark areas, so she doesn''t mow down, part of the grass.', '1999-01-25', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3941133324524ABE95148C02677062EC', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 27, 'The Greatest Pawn on Earth!', 'Come one. Come all. Step right up to the Gold & Silver Pawn Shop!  When an early addition of P. T. Barnum''s autobiography shows up in the shop, will Rick be a sucker and pay too much for the famous hoaxer''s tell-all? Then, Rick tries to solve the mystery over what could be an extremely rare 1966 Dodge Charger with a Hemi engine. He''ll either be burning the tires as he drives off with the sale or hitting the brakes if it''s too hot rod to handle. Later, a Napoleonic era Imperial Guard sword falls into Chumlee''s hands and his valiant attempt to buy it could turn into a real swashbuckling affair.', '2017-08-07', 21, '/oVze0SnVvYsvufp2iMqqx7XA53b.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'39444ECC0C92446BB4C583A5A21F40DF', X'4900FC8D5E7E408E972ECE9269D203B3', 8, 'Sweat, Lies, and Pornography', 'As Cabo heats up and truths are revealed, the ladies struggle to keep their cool. Emily looks inward for answers, while Jen''s pain pushes her to emotional limits. As Heather looks at properties, Gina questions whether her investment in Noella is worth the cost. And despite Shannon''s efforts to keep the peace, she only stokes the fire more, causing an explosive chain of events.', '2022-02-02', 44, '/uQ7Wsai8uy2ZJZqxwhtwiN3BDN7.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3945D633B33142A9872AFE297B8095F7', X'D5383B3D56364D71B99CB84774B4B3C6', 17, 'Pingu is Curious', 'Pingu is asleep in bed, and is woken by Mother and Pinga singing “Happy Birthday”. When he gets up and goes into the kitchen he finds a large parcel waiting for him. He wants to open it, but Mother tells him he has to wait until 12 o’clock. Pingu goes outside, paces up and down for a short while and then notices that Mother and Pinga are about to go out. As they leave, Pingu is sitting by the door nonchalantly looking at a book. Mother asks him if he’d like to come with her and Pinga, but he says that he’ll stay and read the book. Once Mother and Pinga have gone he rushes inside to the parcel, and looks at it from several angles, including from under the table. Forgetting he’s under the table he gets up and bangs his head, and while rubbing it is dismayed to see that he’s knocked over a flower vase, and that the water inside has run all over the parcel. He puts the parcel on the stove to dry it off, and sets about clearing up all the water that was spilt. On finishing, he remembers that the parcel is still on the stove and takes it off, but it’s very hot and he drops it on the floor. Pingu blows on his hands to cool them, and then notices that the parcel is somewhat battered. He straightens it up, and then goes to get a drill so he can make a hole in the parcel to see what’s inside. While he’s looking, he hears Mother and Pinga returning. As they come in, Pingu goes out with the drill hidden behind him so that Mother and Pinga don’t see it. Pinga notices that a patch has appeared on the outside of the parcel, follows Pingu outside and sees him toss the drill into the shed. She asks him what he was doing, but Pingu tells her he wasn’t doing anything. When 12 o’clock arrives, Mother opens the parcel while Pingu, Father, Pinga and Grandfather watch. Inside the parcel is a very battered birthday cake! They’re surprised to see the state that the cake is in, but Father and Grandfather sample it and say that it tastes good, so everyone is happy.', '1999-11-27', 5, '/jr44vJmd8kQnqsEA5No5ZOzX1pB.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3946A157750B46EF988BA7B5E1416817', X'6EF86C2733E747E5A053483059DFD16D', 59, 'Episode 59', '', '1982-04-08', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
