INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'395D1EA9A08744E1913D299A95AB4150', X'CA19F89515144988A70995E84EAB7CEE', 25, 'Action Packed Pawn', 'Things in the shop get lit when Corey checks out a Jason Aldean neon light. Is the seller''s asking price crazy town, or will it be Corey''s kind of party? Then, Rick has a hoot when he checks out a ceramic owl vase made by none other than Pablo Picasso. Next, a deal turns peppery when a poster from the Beatles'' "Yellow Submarine" movie lands on the counter. Will Chum be left feeling blue, or will it all come together now? And finally, when Rick buys 507 signed basketball cards, Chum makes a full court press to convince Rick that a mystery pack sale is just what he needs to turn a profit--but is his suggestion out of bounds?', '2021-09-25', 42, '/sI13guk3uhuCHNkoXoca3MNZ7cG.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
