INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'396367A278A84E91A6AA42EFB27320BF', X'ECB64EF34F8045A7B4A9C04434B02E35', 51, 'Get in the Ring', 'Grab a ringside seat when the Pawn Stars square off for memorabilia from undefeated boxing champ Rocky Marciano. Can Corey land a knockout blow or will he end up down for the count? Then, Rick checks out a one-of-a-kind, battery-operated, glow-in-the-dark car. Will he take charge and make an electric deal or end up in the dark? And later, Chumlee uses modern technology to "tele-presence" into work. Can he get the job done or will Rick pull the plug?', '2014-06-26', 21, '/mX6xNoT9Q5kDvmmpuNemH0FA7UN.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
