INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'39737CB52D354F6F86FEEC2D85B44F99', X'1415EF1C411A4C26814A7C79C3628BC2', 5, 'The Politics of Friendship', 'Carole and her mom go canvassing in Pennsylvania in the last moments before the presidential election, and later Carole and her friends watch the results come in while at her party. Sonja is conflicted between “Frenchie” and Rocco. Dorinda conspires to get Ramona to a surprise party she’s throwing for her, but Ramona unknowingly throws a wrench in the plans.', '2017-05-03', 60, '/o7JTs2ZijGnZuBW3EgJ1VnCM3jU.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'39794F2649CE4B769156E487920DB383', X'CC4729160B8B44988A9AC5C1E7E66097', 17, 'No Business Like Clothes Business', 'The ladies wrap up their trip to Paris and back in L.A. Kyle throws a party for the opening of her store.', '2013-03-11', 43, '/sarn7RNk5cWP56pu2ECh7FmtSTd.jpg', '2026-04-03T16:34:55Z', '2026-04-03T16:34:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'397A7F99222D4204BCEC060ED77244D6', X'D8CCF6D3E37A430AB67D7FBF269BF0BE', 17, 'Reunion (1)', 'The ladies reunite in New York to discuss the season''s highs and lows. New housewife Monica sets the record straight about her past – from her affair, history with the Mormon church and how she became an informant in her ex-friend''s criminal case. Angie confronts Monica and Meredith about the rumors regarding her husband and the Greek Mafia.', '2024-01-09', 44, '/fXGKcCitDCMqATuSwWjDsLfQlYg.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'397FE5C90D8C47C2BF7108D6ED35295A', X'6FEDBA8252F34184BE776B26E556CD0E', 7, 'A Family Group', 'Paddington attempts to take a photo of the Browns using an old camera.', '1976-01-13', NULL, '/dYe9hAMPjagSQbqEwOS7aRsUECB.jpg', '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3984BA14497D431FA9915C2AA1C35E3E', X'70D9E39768134785887D27D034928BAE', 19, 'Pingu Hides a Letter', 'Pingu comes in from playing with his ball and sees a letter on the table. The letter is sealed, and has nothing written on the envelope. He wonders what it might be about but leaves it and has a snack. He is about to go out again when curiosity gets the better of him, so he returns to the letter, opens it and is about to look at the contents when he hears someone coming. He quickly hides the letter, just before Pinga and Mother enter. Mother notices the letter is no longer on the table, and asks Pingu if he knows where it is. Pingu says he doesn’t, so Mother and Pinga search everywhere for it. Mother then asks Pingu again if he knows about it, and this time he owns up to having opened it and gives it to Mother. It was for Pingu all along, and is an invitation to a party. Pinga shows Pingu her own invitation that she’d already opened. Pingu then notices that the party is today, and it’s now the time that it’s almost time to start, so they have to rush to get there, and they make it just in time before it started.', '1996-07-18', 5, '/zGZkTKkV5pGpTPmwD8RbfaKueWS.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'398A500B119F44429968BED9367178ED', X'A8C6182E05E14B6891A55126CF6C94F0', 20, 'An American in Paris', 'While visiting Abigail Adams, Sarah gets exposed to smallpox. Meanwhile Alexander Hamilton joins George Washington in the battle.', '2002-09-27', 30, '/hM3052fq9xYFPPzUfpdWoTwHzNW.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'398A67936B6E479EB9E6187A9ADF6324', X'D9973960273B4A92A7DA62EFE8860D09', 4, 'Roaring Emotions', 'At the conclusion of Whitney’s 20s Party, Jen’s explosive temper reaches a boiling point and Meredith and Mary are the targets. Meredith finally reveals the truth about her marriage to Lisa, while Jen shares the details with Heather, who then tells Whitney. Mary takes the high road and invites Jen to her luncheon hoping to squash their issues for good, but when Jen tries to open up to the group things take a sudden turn for the worst.', '2020-12-02', 42, '/2Q7vjLmGnm2vpJy8AyhlMvreRsX.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
