INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'39BCF21F212B4DC5A3F1545CDEE27F49', X'ECB64EF34F8045A7B4A9C04434B02E35', 2, 'You Say You Wanna Revolution', 'Join the Pawn Stars Revolution when the guys check out an Annual Register from 1776. Including a printed copy of the Declaration of Independence, will they declare their intention to buy it? Then, Corey checks out a set of gambling tokens from the Nevada State Prison. The only legal casino to ever exist in a prison, will he put them on lock down? And later, when Chumlee''s laziness reaches an all-time high, Rick sentences him to a week of hard labor.', '2014-01-02', 21, '/3XPLJ5hrpbLbY6A5fTAB6RTqUVg.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
