INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'39F530F6657B44628FC5879DBECD61D3', X'4B2A19E02FAE492EBC31F78E63D88EBC', 2, 'Pawn No Evil', 'Lose your senses with the Pawn Stars when a Japanese animatronic "speak no evil, see no evil, hear no evil" monkey swings in. Will Chum take the moral high ground or will he turn a blind eye? Then, Rick feels cheated when a painting revealing Glenn Ford''s love affair with Marilyn Monroe two-times its way into the shop. Will Rick commit to the best price or will the negotiation be a quickie? Next, things get greasy when Rick checks out an 1800s wooden oil barrel. Will he pump out a sale or will the deal run dry? And later, a Chinese Ming Dynasty Kuan banknote reigns over the shop. Will Rick inflate an offer or will he pass the buck?', '2016-08-03', 21, '/fAedlthOCRlDmfRlNt2ARSruEcY.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
