INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3A126596EE1344AC9E94A3AE8F5CFE2D', X'ABEB8D075C864F6AA110B11CBA2A4138', 14, 'The Boiling Rock (1)', 'Sokka wants to break his father out of jail and asks Zuko for information on Fire Nation prisons. Sokka and Zuko head for the Boiling Rock, a prison located in the middle of a volcano, to rescue Sokka''s father.', '2008-07-16', 24, '/keivJ7wk45aLbg03AqEb9WgrYSz.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3A1460A65838485DA8CA86A12F862DCA', X'1996DDD820C94A3096BE2B87FAB8D17C', 17, 'Into the Comics (4)', 'Lenni discovers Manny Gytes rejection letter of his cartoon Stoop Dude. The team sets out to confront Manny with the help of his aunt.', '1993-01-17', NULL, '/tvNQJJSlrGXlQRcUCd7Y0KVxl5f.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3A1B8145BEAF416D88E3721904631B50', X'7B19039A31AC425C8FB1B51CF2447821', 14, 'Making Waves', 'The ladies get together for the first time in months when Emily throws an elegant beach party. But with a lot of unfinished business in the group, the gloves quickly come off. Gina is shocked to learn Shannon is holding a grudge against her and Braunwyn struggles with evolving feelings in her relationships. Later, Elizabeth takes steps to heal the wounds from her past, and Kelly confronts Braunwyn about her authenticity.', '2021-01-13', 44, '/5BWd1IcaDOWbB9uVivPapOmyIcv.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3A2581758B244710923068AB72339052', X'8C3CFAC1D8824904B38CD1981628D00E', 38, 'Episode 38', 'On 17 January. 1912 Captain Scott''s Antarctic expedition reached the South Pole - only to find a Norwegian flag planted there! Chris investigates the dramatic story of Roald Amundsen - the first man at the South Pole.', '1979-01-22', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3A264CBF3D3A4B6DB02310ABDF46BE97', X'0FA9200282AE460985E33982BAA99AE1', 13, 'Postman Pat and the Tricky Transport Day', 'When Pat''s van breaks down one snowy day, he has to use a lot of different vehicles to finish his round.', '2005-03-14', 15, '/e8ouzHFoFFBqX6r5zQhKGVZr247.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3A26AF8141BB402AB1617947CD04543C', X'56428E5E7DAA468D8BD2076956507AA8', 7, 'Light Optics', 'Don''t stay in the dark - Bill Nye will help you absorb the science of light optics. Light is energy that normally moves in a straight line, but often something gets in the way. When light runs into something, three things can happen - the light can bounce off, it can go through, or it can be absorbed. Often all three things happen at the same time. Light bounces off mirrors. You see yourself in a mirror when light bounces off your face, into the mirror, and then into your eyes. Light goes through glass. If the glass is bent or curved, the light gets bent on its way out of the glass. The glass in a magnifying glass or a pair of eyeglasses is curved so that it bends light, making things look bigger. More light is absorbed by dark-colored things than by light-colored things. Colors are made when some light is absorbed while other light is bounced back. Black things look black because when light hits them, they absorb almost all of the light.', '1994-09-10', 26, '/28TyqRpbzdGgPE98HQzbXcm7LGH.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
