INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3B068559DAB7486DA46C937E98CC030D', X'698A60DF8ED44CA9BCB1EBAB343DACDD', 22, 'The Handicap Spot', 'There are many repercussions after the gang parks in a handicap space.', '1993-05-13', 23, '/vLeQ7eHc8aJM1K9j5mIU3k2xq15.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3B0B1904C9A54746AB7F72F6FE24E003', X'EA1650C2E4F146C793BA74B5D45D08E5', 1, 'New Attitude', 'Gossip spreads fast when Kim reveals her lesbian affair in the tabloids, and NeNe rekindles her roller coaster relationship with Kim just in time to get the inside scoop. NeNe’s got drama of her own -- her marriage is on the rocks and her old friend Dwight has been spreading rumors behind her back. Shereé pursues her long-time dream of becoming an actress and Kandi starts getting back into the dating scene. NeNe, Kim and Sheree hit up a couture shoe event and run into new housewife Phaedra Parks – the pregnant, classy, but sassy attorney-to-the-stars, who arrives with her old pal Dwight.', '2010-10-04', 43, '/9l5Xyc7j4z1w6pPQ0MB1NDIe9lb.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3B0C5083F65643ED88F5A643DD6AC58B', X'5DB3FF78E43948E18F67988ECBF85D17', 23, 'Marco''s Mission', 'The Jewels were given to the former King of France by the King of Spain, Louis decides to return them as a sign of friendship, The Three Musketeers and Dogtanian have be given the honour of carrying out the mission, Treville proudly strokes his mustache. Richelieu and Rochefort have plans to stop them reaching the Spanish Court. Pip is at a show satirising Cardinal Richelieu staring a mouse called Marco. Widimer and the Cardinal''s guards have been ordered to stop the show. Marco knocks Widimer off his horse, Pip joins in the fighting but doesn''t help and Marco and the Ringmaster are arrested. Richelieu and Rochefort tell Marco there is a conspiracy to start a war between France and Spain and ask him to help stop it...', '1982-03-05', 24, '/iDZHksFsoMCZ53qaFA8epQPwu7H.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3B0DFDCCA96A436CA943D7ADD76DC804', X'740A96A0A0754BE2BE92A178D0939384', 12, 'Hair Training', 'Prairie and her friend Gabrielle are practicing a dance, but their hair doesn’t move the same way. Nina helps them realize that the dance is even more fun when they each let their hair do what it wants to do! Elmo and Big Bird join in and let their fur and feathers fly free.', '2018-02-03', NULL, '/dfb2yjWPzinZcccuZyhkutWaahw.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
