INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3B65947CB1504E42B562C8CDB674CBDE', X'D6092173D23B4449BAFFE0E16FE56C9A', 12, 'Front Page News', 'Marlo invites the ladies to saddle up for a hayride, but the fun is interrupted by news that unearths trust issues within the group. As the countdown to Cynthia and Mike’s wedding approaches, Cynthia is met with minor setbacks.', '2021-03-07', 43, '/hp99V5yKKBpnxKOk2iqsqxyer7E.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3B65A21B886545F892E8CF6CA7565CA5', X'2E6EE129B32E4417950056F1CC9BC434', 6, 'Follow the Drinking Gourd', 'LeVar reflects on a time when Africans were brought to America as slaves. He talks about how African-Americans risked their lives for freedom, and discusses how the music from slavery times effected the African culture. Keith David reads the featured story, which explains that the African-American folk song, "Follow the Drinking Gourd," was in fact a coded message to slaves giving them instructions on how to take the Underground Railroad north to states that abolished slavery.', '1993-10-18', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3B73354C77F1435893B60711CEC8FE02', X'0EBBA123871D4D2BA054EB85D2AD9450', 49, 'Beauty and the Beet', 'Mirabelle and her traveling family band, the Veggie Tones, are determined to make their next gig at Vegetable Square Garden. On their journey, a fierce winter snowstorm hits, and the family gets stuck at a run-down resort! Mr. Beet, the grumpy manager, makes them sing - and clean - for their supper. Why is Mr. Beet such a beast? And can Mirabelle''s kindness change him? Find out in this hilarious and heartwarming tale of unconditional love!', '2014-10-14', 30, '/zYC04JoeBFToILcpuRf4wjMzhKj.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
