INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BB713E5415745F18B804666DE8DFD9D', X'D306A064E835417E85480CF806295F31', 4, 'Hot Mic in Miami', 'Larsa hosts a paw-ty for her dog''s birthday; Nicole receives upsetting and possibly threatening news from her father; Julia worries that Martina may leave her; Lisa hosts a pool party for the ladies where Lenny''s true intentions are revealed.', '2022-12-08', 54, '/bcfxGBF8uyQtW8cPI2opVYuBcqB.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BB731FB63D34E3393210981581AA699', X'70D9E39768134785887D27D034928BAE', 20, 'Pingu is Not Allowed to Join in the Games', 'Pingu is on a walk when he comes across Pingo and Robby playing badminton. He wants to join in, but they won’t let him. He mopes off to a nearby block of ice, where he finds a basket of fish. He’s about to look closer but Pingo tells him to leave it alone. Then Pingo hits the shuttlecock very high, and it lands on top of the ice block. Pingu goes up to the top of the block to get the shuttlecock but won’t return it except in exchange for their basket of fish. Pingo and Robby decide to play a trick on Pingu, so Robby gets a crab that they put under the fish before letting Pingu have the basket. Pingu puts his hand in the basket and is bitten by the crab, which holds on. Pingu is so startled he falls off the block of ice, and the crab makes good its escape. Robby is sympathetic about Pingu’s hurt hand, but then goes onto the top of the ice-block with Pingo and he and Pingo eat all of the fish except one. They then feel sorry for Pingu and take him the last fish, which he eats. Robby then gives Pingu his racket to use, and all three of them then play together happily.', '1996-07-25', 5, '/hBXFDt4ZotGI8TQM2qNMMA1ovU5.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
