INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BBEAA0A95F24B3B87C4D98B02FEED36', X'9193E795DA7C40ECB68FF63AA7D5174F', 38, 'The Game Revealed: Season 7 Episode 5', 'The Game Revealed: Season 7 Episode 5', '2017-09-25', 60, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BC319F8C4074795A4434A41B687F4BB', X'4FE93658C46343298E649D523869C2CB', 22, 'Put Up Your Dukes', 'The Pawn Stars have a chance to buy a 450 year-old book once owned by Sir Isaac Newton, but when hand-written notes and formulas are discovered in the margins the gravity of the situation becomes clear. Can they postulate a proper price or will this deal require an equal and opposite reaction? Then, a man walks in with his grandfather''s Army jacket from the Spanish American War. Will Rick and Corey offer up the shirts off their backs or will one loose thread cause the whole deal to unravel? And later, Rick and Chumlee check out a collection of John Wayne memorabilia. Will they sound a charge to secure pieces of the western legend or will Rick be forced to retreat?', '2011-01-31', 21, '/i6FkMWjo16LBuLCkP6QJn5ofkFi.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
