INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BC6286393E54C17A4C8FCBB11F85866', X'33319C06A2B043BF8694B3E8E37E49E9', 19, 'Bouncy Mattress', 'Rosie and Jim accidentally break Neil''s mattress so he goes to buy a new one from Furnitureland in Bristol.', '1997-05-30', 10, NULL, '2026-04-03T17:19:38Z', '2026-04-03T17:19:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BC675AF8707400BA90596EFC4E4365C', X'B1D55597D9D24EEEAB9546DBB163291A', 23, 'Pingu''s Parents Go to a Concert', 'Pingu’s parents are off to a concert for a change leaving Pingu and Pinga in charge of taking care of the house and promise to good, as Pingu and Pinga started to cry. As their parents leave, Pingu and Pinga perform antics such as jumping on their beds and asking Pinga to turn on a radio (as the music blares) while Pingu makes a pancake. Mother and Father had arrive at the concert. Pingu flips the pancake into the air many times, much to Pinga''s delight and it ends up getting stuck to the roof! Pinga tells him to look up, Pingu does so just as the pancake falls on his head making him look like an elephant then he trumpets . Meanwhile, Mother and Father have a small talk while at the concert hall (as the Orchestra plays classical tune in piece). Then, Pingu bounces his red ball and he and Pinga play catch making a big mess in the process. At the concert, Father has fallen asleep and Mother wakes him up and they are a little bit worried about Pingu and Pinga. Afterwards, Pingu rifles through a dresser strewing a top hat at Pinga. He then puts on a women''s hat and throws it at Pinga who is stuck in a blue box then Pingu pushes her as Pingu convinces Pinga (with the box she was stuck in now on her head) to come back to where he is standing then Pingu pretends to be a monster and is devouring Pinga. Meanwhile, Pingu’s parents are worried about what Pingu and Pinga might be doing as they have a look at the photo of Pingu and Pinga. Then Pinga turns on the bathtub and adds bubble bath to the bath water as Pingu jumps into the bathtub and play messily and then they tip over leaving a mess on the floor. Meanwhile, the concert is finished, and Pingu and Pinga try desperately to clean things up and Pinga shuts off the radio while Pingu shoves every single pair of clothes he has all strewn about into the dresser by jumping on the clothes. When Pingu''s parents come home, Mother find out that the dresser had clothes completely shoved in. They are not amused and Mother asks if Pingu and Pinga did this. They say yes. They are afraid that they are angry at him, but they are not, and they forgive Pingu and Pinga. Mother cleans out the dresser, and they congratulate Pingu and Pinga for watching the house.', '1990-10-06', 5, '/6MP3Hia22KZRsVNu5JMjV0DXefK.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BCD79D6363B4C65BD40B6F88E4074DF', X'150D1480F3F143F99A22D2527756FBA2', 15, 'Lost at Sea', 'Wendy''s couple''s trip continues; Gizelle and Robyn leave in the middle of the night, furthering the tension between them and Wendy.', '2021-10-17', 42, '/tinOdfMu6ZV01EXl6ntTfHvWaB1.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BD078F861834F0F94390FB9CB19DA88', X'B5AB3A72BC794E9BA53196739AFD7AEA', 7, 'The Elephant', 'Emily brings a tatty straw elephant without any ears.  Bagpuss and his friends try to solve the mystery of how it lost its ears by singing songs...', '1974-03-26', 15, NULL, '2026-04-03T17:23:58Z', '2026-04-03T17:23:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BD1A4A900CB40208B915CF46D4022FE', X'3EE646E823AE4DECBBC6C7E6A210D55B', 63, 'Getting exercise', 'Susan finds Telly about to go on a morning run with Gordon, but he''s gathered several items to take with him - an umbrella in case of rain, an extra pair of shoes in case he slips in a puddle and loses them in a tree, a stool to sit on when putting on the extra shoes, and a flashing light to warn ot. Telly and Gordon return from their run and see Oscar emerging from his can, wearing.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BD41301EB86426480D6B041050A729F', X'B753871204CE43A6916362280BBB084B', 17, 'Luis Teaches Telly and Elmo That Flowers Are Alive (3867)', '', '2000-01-25', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BD72EE944D6480FA5CE6766225340AE', X'DF77DBA2BBDA4F3897138D5C856F852E', 6, 'The Circus', 'There has been a party in the playroom and the toys can see that there is lots of food left on the table, but it is just out of reach. Little Bear explores underneath the tablecloth and discovers that it looks just like a circus tent; a starting point for a wonderful new game. Many of the toys want to perform in the circus and others come to watch. It is Rabbit who turns out to be the star of the show and he, accidentally, solves the problem of the out-of-reach food.', '1993-11-07', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
