INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BDDE687D3304FF69E730A29F9FA6F85', X'D3E13496E3C8490383B45A31FEDEE232', 3, 'The Southern Air Temple', 'Aang is excited about going home for the first time in one hundred years, but he is shocked to find out that the temple is deserted. Aang tells Sokka and Katara about his childhood as they explore the temple, but they soon discover something that Aang never expected. Meanwhile, Zuko must make repairs to his ship and the only way he can do it is to dock his ship at his rival''s naval base.', '2005-02-25', 25, '/bFBUv2VDtyBuilulFynsNGPINnw.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BDF30959A0E4FAC874DD0D4D8095027', X'787DFA0BC8274DADA82D0548A6534D88', 12, 'Racing to the Truth', 'Meghan, Heather, Tamra, and Shannon head to NASCAR while Vicki enjoys a birthday getaway with Brooks. Later, Shannon tries to put on a happy face during her birthday dinner with David and her girls. Heather throws a luncheon at her unfinished home, where Meghan confronts the OG of the OC.', '2015-08-24', 44, '/iNm2SzVg29aSReDhZVmcpeuhegI.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BE2867B473A4265A0C0DE5D1B5D7289', X'9E30A416EDBD490BBB0F18D5C45F0BDF', 4, 'Irked at Cirque', 'While mastering circus school, Brandi and Kyle face off over bullying accusations and Joyce and Lisa butt heads.', '2013-11-25', 42, '/n2CEvDsm60TbY8tjhedEuuBjAtD.jpg', '2026-04-03T16:34:55Z', '2026-04-03T16:34:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BE37A6D73CA41DE93B317355816D1A0', X'4DA606E79D2346828BD5F535E1DA706F', 18, 'Franklin''s Collection', 'Franklin did not know what to bring to school for show and tell. Everyone had a collection of some sort except for Franklin. Franklin sets out to find a collection but didn''t think it was anything spectular until Mr. Owl pointed out what a great collection Franklin has.', '1998-11-02', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BEFBDB569444EF19A32BFF9748EEB71', X'7B19039A31AC425C8FB1B51CF2447821', 2, 'Tequila Truth Serum', 'Kelly is focused on her future with fiancé Rick, but wonders how long her recently brokered peace with Shannon will last. Elizabeth and Jimmy bond over their shared Mexican heritage. Braunwyn struggles with her identity and worries that her friends won’t stick around now that she’s not “fun” anymore. Gina reveals that she heard Braunwyn made fun of her “small house” but it turns out she isn’t the only one making disparaging remarks. Gina also brings up the awkward text messages she had with Sean last year. When Emily calls Braunwyn to clarify, she refuses to discuss over the phone. Later, when rumors start to spread, Braunwyn is forced to reveal a secret to Shannon.', '2020-10-14', 44, '/r29LcSzSr5HQCrErGRwzr2hMh8J.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
