INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BF9A2DCF8254EC2A57AB08E13695269', X'3EE646E823AE4DECBBC6C7E6A210D55B', 37, 'Telly Monster follows Gordon to school for a "Wide World of Sesame Street" report', 'Telly hosts "The Wide World of Sesame Street," a program which shows a day in the life of someone on Sesame Street. "Wide World of Sesame Street" continues as Telly hides in the bushes and watches Gordon at the bus stop, waiting for the bus with a group of people (including Mike and Lisa).
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3BFABE378F3F4AE0B7F7A1939D0C0AD8', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 64, 'Big Bird stays up late', 'Big Bird stays up past bedtime and explores Sesame Street''s nocturnal world with its unique nighttime residents. He learns why sleep is important for growth and health.
