INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3C0AE5631DD246A2ABE7F217625A6590', X'943B0C940CC540E8A0E1BD5660772CC3', 9, 'Dirty Ol'' Dad', 'The ladies have a dinner get-together in Miami with Sonja and her date—who happens to be Aviva''s lusty father. Later, Aviva seeks advice on how to deal with Ramona, and Carole calls out LuAnn about a past misdeed.', '2012-07-30', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
