INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3C2F7F48A7E844C9B20DCC11FE3CBB0F', X'A4843A51AEEF427C902C7FB3BD670CD4', 23, 'Need a Little Help Today', 'Bear has caught a cold and his nose is so stuffed up that he just has to take it as assumed that the viewers smell good today. Tutter suggests he get a little rest on the couch and then the kids all decide that they''ll do their best to help Bear feel better. Tutter recalls that when he needed some water, Bear helped him to reach the faucet. Ojo brings Bear her favorite toy, Snow Bear, to help cheer him up. She recalls the time when he helped her to feel better when she fell down while trying to fly. Pip and Pop deliver Bear a package containing a clam with the message "Get Well Soon." They recall the time when Bear let them be postal delivery otters. Treelo gives Bear a hug and recalls the time that he was afraid of going down the drain in the bathtub. And Tutter recalls a time when he wasn''t feeling all that well himself.', '1997-11-19', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
