INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3C469E0A72844838AF2361FFFEA0C019', X'842C6419AB984D3488451D9782291AAD', 4, 'Gratitude', 'Zach plans to invite a lot of classmates to his birthday party -- more guests means more gifts! -- until his parents tell him that they can only afford a small party for Zach’s closest friends. Disappointed, Zach retreats to Plato’s Peak where he hears several tales which demonstrate the importance of gratitude.', '1998-03-08', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
