INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3C8057E0A8804C1AA2755A684B00AF71', X'3982796B54514100904246BEDF6A20A5', 5, 'Pingu''s First Kiss', 'Pingu and his friends Pingg, Pingo and Pongi are doing some tricks on skates when Pingu''s girlfriend Pingi comes along. Pingu greets her by kissing her on the hand, and the other three laugh and take the mick out of him. Annoyed, Pingu impresses all of them with the best trick yet. Pingi applauds and suggests to Pingu that they go off together, but Pingu’s friends want him to stay with them. Pingi goes off, and Pingu is not sure what to do. He goes back to his friends but, as Pingo tries a new trick and the other two watch him, sneaks away to join Pingi, who is gracefully dancing on her skates. Pingu joins in the dance, and they’re about to kiss for the first time when Pingg, Pingo and Pongi skate past teasing them. Pingu and Pingi go off to be alone a couple more times, but each time the others find and tease them. They eventually manage to evade the others and have their first kiss, and then impress the other three with some figure skating', '1992-01-19', 5, '/rM3xcaOUyxwtfTpex3thMakEROD.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3C82AC9791404B03A89630717A134840', X'4B2A19E02FAE492EBC31F78E63D88EBC', 24, 'Seven Barreled Pawn', 'Hit the deck with the Pawn Stars when they head to the gun range to check out a rare Nock Volley gun used by the Royal Navy. Will Rick fire away with an offer or will the deal be kickbacked? Next, an etching by Joan Mir paints its way into the shop. Will Chum think it''s surreal or will it leave a bad impression? Then, the first American pasta machine cranks in. Will Corey make a saucy sale or will it boil over?', '2017-01-16', 21, '/6IT60U4QWdpg9s9RzJZ9VXKdEwM.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
