INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3C9CE7B465194A36B4B2EA8BB0702408', X'9B95011E93DB4E56A45D8AA956C15997', 17, 'Turtle Hunt', 'Sam and Ben work together to fix a special camera onto the shell of a beautiful blue Leatherback Sea Turtle, so that they can see underwater from its point of view. The camera comes in handy when Norman and Mandy, who are out turtle-spotting alone in a boat, get in trouble at sea.', '2014-07-26', 10, '/jdFMNEpAHrw0nm3AhGNflVMKTNS.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3C9D4CA748194067AEEB19AFF7D39771', X'C21DBD225E2E4414BB67750399AAF6F0', 6, 'Silence of the Lambo', 'The Pawn Stars fasten their seat belts when a 2003 Lamborghini Murcielago speeds into the shop. Originally purchased for $400,000, will Corey keep the negotiation on track, or is this 200 mile-an-hour super car more than he can handle? Then, Rick is presented with a true one of a kind, when a guy brings in a set of Saddam Hussein''s fingerprints. Taken in Baghdad by the FBI, will Rick try to capture this rare piece at all costs, or will he play this one by the book? And later, Rick and Corey check out a sterling silver Tiffany Walkman originally owned by a member of the rock band "The Who." Will the guys try to win this one for a song, or is this antiquated device worth its weight in silver?', '2011-12-12', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
