INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3D99689A718F4ABCBA0F2E7CDA1715F1', X'4F18AC4C8757456CA49A224F00E6A9F7', 21, 'Mine-itis on Sesame Street', 'Leela plans to have her lunch break with Elmo, when Bert, Grover and Cookie Monster wander by in a trance, chanting “Mine!” and swipe her food one by one. Just then, in a “Sesame Street Nightly News Update”, Brian Williams reports that no one is sharing on Sesame Street. He then continues to interrupt them when they have a question to ask. Leela and Elmo are in disbelief, so they set out to prove people are still sharing.', '2008-10-24', NULL, '/wEEuti1JHSxUGpYEGgsE6g3GOJI.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
