INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3D9ED94CE31D4965AE0EE848D4942C0D', X'3EA743EF0A2247CFB1D262F37E939253', 45, 'David Alan Grier as Aladdin', '', '2002-04-05', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3DA9865D2F2143268114B9C3D86394B1', X'66006278BAF0485F8DADB214343509F6', 7, 'Rufus Xavier Sarsaparilla', 'A group of good friends and their unusual pets are able to identify each other simply with pronouns.', '1976-03-06', 3, '/lAWaUkNv5nXBKsedVv9Y0dCjdki.jpg', '2026-04-03T17:13:55Z', '2026-04-03T17:13:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3DAE525A79FE4269A13F781B3AAC60EA', X'45E64A158FC04E4BA1CA9E3F42F3634D', 20, 'Eyeball', 'Look no further ... Bill Nye is on the ball - the eyeball.   For their small size, your eyes do an important job. By working with your brain, your eyes can tell the   difference between thousands of different colors. They can follow a fast-moving hockey puck across the   ice. They are even sending messages to your brain about what you''re reading right now. Eyes work a lot   like a camera. They take in light, focus light, and make images. With help from the brain, your eyes help   understand the world around you.   Light bouncing into your eye passes through an opening called the pupil. If you look in the mirror, your   pupil is the black area in the middle of your eye. The pupil can open or close, depending on the brightness   of the light. After passing the pupil, the light is focused onto the back of your eye by the lens, a thin layer   of cells. On the back of your eye are special cells called rods and cones that are sensitive to light. These   cells send electrical messages to your', '1994-02-11', 26, '/liet78quyNwphWl8GLLgJZ30oeH.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3DAFCEC65EC74D5F8DE9657B6E83698B', X'6FD9FD9DE378411B94B176BA4BD518FE', 38, 'Episode 38', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-01-31', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
