INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3DB530389A3444D3A122984204BFB664', X'BC1B58B0F2D64214914B231F27FB4D61', 12, 'Auld Lang Syne for an Eye', 'The wives get set to ring in the new year by trying fresh approaches to life: Teresa works on her new cookbooks; Melissa tries to live out her dream; and Caroline''s daughter vows to shed pounds. The gang then celebrates New Year''s Eve at the Brownstone, but backstabbing and finger-pointing prevail.', '2011-08-07', 43, '/mBBVAPTnDYDj6dr5hI2XmNibDvP.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3DB5507B0B7643F3992AF046BF158450', X'DE052E8E7DBD454AA6D8B9AFBA6E9BFA', 9, 'The Invisible Womble', 'Orinoco thinks that if he turns invisible no one will interrupt his sleeping while he pretends that he is in work.', '1973-02-19', NULL, '/pnqExC7PXNujGVcPQN9GE2ahwyF.jpg', '2026-04-03T17:23:19Z', '2026-04-03T17:23:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
