INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3DC10F0A038F4084AED5EB6BB9873EA0', X'69B3BEFE579A43ADA7D6EC30FFE3ADF7', 32, 'Episode 1087', '', NULL, NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3DC8918501DC43F3BC2A1EC9BE450680', X'EC8D33228CA24E8D9D22268AEE320274', 4, 'No More Mr. Nice Buys', 'When an outfit supposedly worn by Alice Cooper hits the counter, it''ll be "No More Mr. Nice Guy" as Rick tries to land a deal. Then, Chum gets mercenary when he makes an offer on a 7-foot tall Deadpool PEZ dispenser. Will the seller accept, or is it all a joke to them? After, Rick and Chum trade looks at sheets of MetaZoo cards with an old adversary--will Rick get burned on a deal again? And later, Rick and Corey go for the gold on a sale of a 1988 Winter Olympics torch. But will they cross the finish line?', '2025-02-12', 42, '/vWkcq7n5HDPzK3hhibrux8Q9srY.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
