INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3DD5709EFE30462F8992F4DEAAFC94EE', X'51F03551BA41409D85F4E51BDDFDF82E', 12, 'Charity Wives', 'In the Season 2 finale, fiery feuds and catty conflicts erupt when the housewives try to work together to organize Jill''s charity event. Meanwhile, LuAnn tutors Bethenny in the fine art of modeling, after which Bethenny struts her stuff on the catwalk at a Moroccan fashion show.', '2009-05-05', 60, '/seXL8liNbzZ5Cydk4ZpI9Jv3LnP.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
