INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3E11BCB7A07E43EAB8B299BC8F7BF4A8', X'4900FC8D5E7E408E972ECE9269D203B3', 2, 'Loose Lips and Lawsuits', 'Gina and Emily investigate a juicy rumour about Shannon and Heather''s old friend, Nicole; Gina feels compelled to reveal the truth, resulting in an explosive string of arguments that shuts down Heather''s party.', '2021-12-08', 44, '/1pqwBq5GsVOme4kPI5NgL71ULlL.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3E1812B65F1D4AF881D5E8DED617A43E', X'F4C403079B5E4263A4E0DFA138131E7F', 36, 'Fiesta!', 'Fiesta means party in Spanish, and Sesame Street is pulsating with activity in this upbeat preschool program featuring Latino songs. Jim Henson''s Muppets join the fun while everyone''s favorite, Elmo, learns the Conga-Wiggle dance. Maria, Rosita, and Gabi create floats and costumes; even Oscar reluctantly partakes in the festivities. The dialogue is sparse in order to devote most of the 30-minute show to singing and dancing during eight Spanish/English tunes, featuring special performances by Linda Ronstadt and Celia Cruz. Most of the music will be familiar, such as "Conga Counting Song," "Amigo," and "It Sure Is Hot." Kids will also learn greetings, familiar words, and numbers in Spanish. While some might wish for the addition of live-action scenes of Mexico or a more complex story line, the bilingual focus is solid and the ever supportive cast of Sesame Street grownups, kids, and Muppets make it a neighborhood worth visiting.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3E1E69E39A8841FB858D91A64EF099CB', X'3982796B54514100904246BEDF6A20A5', 2, 'Pingu''s Admirer', 'Pingu goes to school. On the way he meets Pingg, Pingo and Pongi playing limbo, and joins in, but then the schoolmaster rings the bell. The schoolmaster has just started the lesson when a new student arrives. The new student is a girl named Pingi. The schoolmaster greets Pingi, and he finds a place for her to sit. Unlike his friends, Pingu does not want anything to do with her. He spreads out his things all over his desk and puts his legs wide apart to make it seem as though there is no room at his desk, and is infuriated when the schoolmaster picks his seat anyway. Pingo offers Pingi a lollipop, which she takes and offers to Pingu. He refuses, so she gives it back to Pingo. She then draws a heart and offers that to Pingu, and he snaps at her, earning himself a reprimand from the schoolmaster, who firmly orders him to be nice to her. On the way home after school Pingi follows Pingu and, when Pingu lets her have a piece of his mind, she cries. Pingu walks away, and Pingi throws a snowball at him. He throws one back in retaliation, but it goes through the window of a nearby igloo. He and Pingi both hide in a barrel to escape the wrath of the igloo''s irate owner, and they end up liking each other. They walk together the rest of the way and Pingu actually cries a bit when they have to part.', '1991-11-04', 5, '/aZSmGX3LaYjjHrH7wNfVkvAylyG.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3E26417B00AF4CF99C69FA929B07F813', X'33825A1537DC4FF982BDCC720498149A', 1, 'Of Friends and Frenemies', 'LeeAnne is overwhelmed by the planning of her wedding; D''Andra inherits the family business which isn''t doing as well as she thought. Stephanie hosts a “Friendtervention” in an attempt to help mend fences between former besties LeeAnne and D''Andra.', '2019-09-04', NULL, '/4LvFsAw7PRwwR0k20EsXvdcvJYe.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3E2CAD8D282E4CD3B967E1A81BF832DD', X'4892E2AF46C14B4EAC81EAC161B5A347', 22, 'Episode 22', 'Rags, the "Blue Peter" pony, has finished her training and passed all her tests. Today, "Blue Peter" film cameras follow her progress as she starts work as a fully-qualified pony for Handicapped Riders.', '1977-11-24', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3E317086E3B4465491ED030AAFE9902D', X'E48599F866FF4C0F927465B9AE1CDA9E', 5, 'Episode 5', 'Rags at Ascot  Blue Peter''s trainee pony for handicapped riders goes to the races and joins the VIPs in Tattersalls at Britain''s premier race-course.', '1976-09-27', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3E3B291D1EA34B02BEF74E75C794F33A', X'97A3D1F5A8F147CD81222E74A092836D', 5, 'Get the Message (1)', 'Tina is videotaping Max setting up his instruments when he is nearly killed in a car accident caused by Mr. Fernandez. Fernandez says that he swerved to avoid hitting someone that ran in front of his car, but Max thinks he did it deliberately. Lenni begins accuse Fernandez of being a reckless driver and Alex angrily begins stalking Lenni. Gaby breaks up her friendship with Tina when Tina writes an unpleasant story in the paper.', '1993-10-03', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3E452D9FC09C4AFDAE48B7ACB5022541', X'543EC6DCC6C7447CB5A74484D9618391', 1, 'Welcome to the District', 'In the series premiere, Michaele hosts a Polo event with some high members of society, including the Ambassador of India, Michelle Jones and Republican Lobbyist, Edwina Rogers. Lynda is reluctant to go due to old rivalries, Mary is tied up with the guest list for her birthday party and Cat gets a lesson in public relations at Stacie''s dinner party.', '2010-08-05', NULL, NULL, '2026-04-03T16:35:01Z', '2026-04-03T16:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3E5171F23D3D40C48DDCB66C5334F2A0', X'4D0FD8A552004DFCB96CAE436DC8803C', 2, 'The Wall', 'LeVar visits the Vietnam Veterans Memorial in Washington DC, and discusses its historical significance to helping people learn about the service men and woman who died in the war. Artist Mia Lin, who designed the black granite wall, is profiled as she describes the reasons she chose the materials and design style for the monument. Jason Ruggiero reads the featured story of a boy who accompanies his father to the monument to search for his paternal grandfather''s name on the wall, and his observations of other visitors.', '1992-10-06', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3E57C898FB944CD7BCD323A8FED5A908', X'FD0F7DFB28AA46879EF88FF0088CE25A', 9, 'Leela''s Cell Phone Addiction', 'Zoe and Abby are frustrated that Leela constantly texts.', '2013-10-17', NULL, '/zGQoKeLI3jd1G7bC2OcxW8R2CiV.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3E62BAC20F634F4A8BE605201BC884E6', X'5C4E51C6E20746AD875C72988EB1E13E', 37, 'Rick or Treat', 'The Pawn Stars are ready for Halloween when a 19th century vampire killing kit stakes out the shop. Complete with a gun and silver bullets, will Rick try to hunt down these terrifying tools or will an eternal negotiation spook the deal? Then, a couple appears in the store with a set of equipment used for paranormal investigations. Everything for recording evidence of spirits, will this ghostly gear capture Rick''s attention, or will lack of proof leave him feeling skeptical? And later, Rick tries to get the guys into the holiday spirit when he holds a costume contest in the shop. Will they dress to impress, or will this haunted holiday become a bust?', '2011-10-24', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
