INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3E8CC7B97ECF41A89ACDE7E7788EA048', X'3AF7EA64FA134097B8E440AF07083054', 65, 'Episode 65', 'In preparation for Chrissy and Terri''s puppet show, Mister Rogers has made an "icebox cake" from chocolate wafers and whipped cream. Before the play, the Neighborhood of Make-Believe finds Lady Aberlin in search of the world''s smallest talking witch.', '1974-05-17', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
