INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3F1B1B9AB362486890FE34484C418E2C', X'E48599F866FF4C0F927465B9AE1CDA9E', 25, 'Episode 25', 'Lifeline Lebanon  As the result of the Civil War hundreds and thousands of children and babies-many of them orphans-are in a desperate condition. Some are badly burned, others have been injured by shells and gunfire, all are suffering from malnutrition and are in need of urgent medical care. Britain has provided the only mercy mission to be allowed into the war zone, but to keep this lifeline going and enable the doctors and nurses to extend their stay, Blue Peter is asking for your old postage stamps and postcards. 300 old stamps or 10 postcards can be sent for the minimum postage rate of 61p. Even the smallest donation will help to save a life so send it off to: [address removed]', '1976-12-06', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3F1B8263024A467E8BDC3005901DBBBC', X'5A771F52FE964EA2B567A8DDE899059E', 14, 'Series Rings and Rap Kings', 'The Gold & Silver is brushed with a stroke of luck when an original Marc Chagall painting draws Rick''s attention. Will he master this piece, or will he gloss over it? Later, Rick takes a swing at buying a Boston Red Sox World Series ring. Can he strike a deal, or will he strike out? Corey goes crazy for a first edition of Ken Kesey''s novel, "One Flew Over the Cuckoo''s Nest." When the BMW that legendary rapper Tupac was shot in rolls up, all eyes are on Rick and Chum. Will they drive this deal home, or decide to steer clear?', '2018-01-22', 21, '/naDZSOwvuXrimnZQQKAMMvYKzq5.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
