INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3F3638073F7E478883091213B676F3CD', X'F9A8D8B3D72E437EA9D57477F6D64DF8', 29, 'Wash Day', 'It’s Wash Day today, and Gabrielle gets to spend time with her Auntie, Kayla. Auntie Kayla combs, shampoos, conditions, and detangles Gabrielle’s hair. During bath time, Gabrielle’s hair is twisted up in a shower cap and at the end, Gabrielle gets to pick out a new style for her hair. Wash Day is really special to Gabrielle and her family.', '2023-05-18', 26, '/imaH8o07fZOwPpdyFzMeQxFHpvx.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
