INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3F5448A96A8C4FFF86A4FB58AD67F37F', X'1D713CA64E174F84949C8CFD98514127', 17, 'Rock Stars and Race Cars', 'Play along with the Pawn Stars when self-portrait from Rolling Stones guitarist Ron Wood makes its way into the shop. Will Rick and Chumlee get "Satisfaction" or will it be a case of "You Can''t Always Get What You Want"? Then, Rick gets nostalgic when a stack of love letters letters handwritten by Mickey Rooney are mailed in. Will this be a red-letter day for Rick or will it be unrequited love? And later, Rick toys with the idea of buying slot cars from his early childhood. Will he race to buy them or will the deal crash and burn?', '2014-09-25', 21, '/dED3ODNd4Iwi8PNgxT4YO4dWRNK.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
