INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'3FE517D96EE6445C9DF75A8634DAC2D4', X'6B5CAA66F66F4ED1817FA00BAD08790E', 5, 'Casinos and C-Cups', 'Dina, Caroline and Teresa head to Atlantic City for a weekend of shopping, gambling and spa treatments. Teresa has an argument with her husband about plastic surgery after going bikini shopping, while Danielle is down in the dumps after splitting up with her boyfriend and turns to her children for support. Later, she pops out for a friendly birthday lunch with Jacqueline.', '2009-06-09', 43, '/i2BBLaiFmRKcTj5Dsr7mEocxGkD.jpg', '2026-04-03T16:35:14Z', '2026-04-03T16:35:14Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
