INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'40713BBC2B254FAABE86B092A79340FB', X'3269A890BBA94E6C9278F7EB38EB1720', 20, 'Animal Locomotion', 'Some animals have wings that let them fly and hover. Other animals have legs, from two to more than 200, to get them walking, galloping, or running. Some animals’ legs are really pumped-up for powerful jumps. Animals also strut, stroll, slither, swim, slime, sprint and squeeze their way around.', '1995-10-27', 26, '/9dB5nkV6J542S67Wi6LEYCa0ydZ.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
