INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'407F71D547074FEEB368591644A93637', X'7BC54DF3F32A454EAEF6A9436C35D53B', 54, 'Episode 54', 'A watch repairman shows Rogers the proper use of his watch-cleaning machine. In the Neighborhood of Make-Believe, Nurse Miller tells all that Queen Sara and the newborn prince will begin to accept visitors next week.', '1970-04-16', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4082111357624FFA8A6A74A17DCDA891', X'C6D5CF79F2B040AFAD1291AA4F1B1D21', 7, 'Roadmaster Rick', 'When Rick and Corey discover a newfound love for an old Buick Roadmaster, will they be able to rev up a deal? Then Chum checks out a doll and volleyball signed by Tom Hanks. Can this be a successful toy story, or will the negotiations be cast away? Next, when a physical bitcoin comes into the shop, can Rick bank a sale, or is the asking price crypto-nite? And later, Corey tries to cut to the heart of the matter when a samurai sword lands on the counter. But will he be able to carve out a price that makes everyone happy?', '2022-06-11', 42, '/5VXtlAgLL2JxjdOX8zvMl0hw3F5.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'408336E2023F48A7812220420374BE9C', X'A0FA50759CE148C199950C0FD866E549', 1, 'Grace Time Is Over', 'The women of Beverly Hills are back and change is in the air! Erika is reinventing her home and herself, Garcelle is taking on new roles and Kyle is navigating life post-separation. Dorit is experiencing the biggest change of all – after nine years of marriage she and PK are separating. The split sparks Dorit to be more outspoken than ever, especially with regards to her friendships. The women wear their bizarre best to Sutton’s Surrealist Ball where new friend Bozoma makes a stunning entrance.', '2024-11-19', 55, '/lzNft25hnLRWrgHa8HPRD5PQmxq.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4087356FDAC544B68C443D336F6A0C7C', X'05C0E384194C44179F62803EB615E409', 26, 'Jamie Rogers visits', 'Title number 0026. Opens with Mister Rogers arriving with a baby doll in a bag. Mr. Rogers discusses growing and changes a doll''s diapers. A friend brings his 5-month-old baby for a short visit. Nurse Miller also assures Tadpole Frogg he is growing at just the right pace. Mr. Rogers then shows a video of Jamie, his eldest son when he was 14 months old on picture picture. Jamie (a.k.a. James), who is now 8 years old, comes to visit and sing the "tomorrow" song with his dad before they leave.', '1968-03-25', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
