INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'40916D00CFBC4B2DA042F55B504C7B9F', X'D01919FB98E042BFB9D91CECF912F6E1', 4, 'Zoe''s New Zoemobile (3789)', '', '1998-11-19', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'409356A1A0374E9A9F23009ED5937A82', X'97A3D1F5A8F147CD81222E74A092836D', 27, 'What''s Up With Alex? (3)', 'When Alex gets to Kevin''s house, Kevin is having a party and offers Alex another joint.  Alex turns him down and leaves.  When Alex gets home, he is greeted by his parents, who found the joint, and they ground him.  Jamal and Jeffrey talk to a drug counciler about their school project.  Jamal discovers that Arnie''s mother used to date Big Ralph, so Arnie knew he could get a deal on the stolen items.  The team finds out that the kid in the video is wearing a Dragons'' jacket, and suspect it''s Spencer.  Alex goes to a Dragons game, but Kevin doesn''t show up.  Alex quits the team when he realizes Kevin''s drug use is causing him to slack off in school and on the court.  After the game, he goes to Lenni''s house instead of going home late, and the team encourages him to write an apology letter to his parents.  Jamal and Jeffrey learn to work together on their project and invite Alex to work with them.  Later, Alex finds Kevin carrying his TV down the street, and then getting attacked by a mys', '1994-04-24', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
