INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'40B96726B51846EBB489987821F693FC', X'C6D5CF79F2B040AFAD1291AA4F1B1D21', 3, 'Pawned Lightnin''', 'Rick and Corey race to San Diego to take a spin in the classic car Hell''s Chariot, from the movie Grease. Is the flaming hotrod the one that they want, or will they "drop out" of the deal? Then, Chum takes a whack at a Punch-A-Bag game once played by Jack Dempsey. Will he score big, or will he get KO''d? Meanwhile, will Rick see red when he hears the asking price for a set of University of Alabama school rings? And later, will a set of Three Stooges trading cards have Chum laughing all the way to the bank, or will his offer be a slapstick in the face?', '2022-05-07', 42, '/eFKSnaEALuzirhCUjOx9L92iz8C.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
