INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4132365ED2884A20AE57DE829074A49E', X'FE19A277AED844DFA4ACFC1C4E9941B4', 5, 'Home Is Where the Heartbreak Is', 'Lisa and NeNe go shopping to prepare for their trip to L.A., and NeNe meets with photographer Derek Blanks to discuss her “Alter Ego” photo shoot. Shereé meets with an event promoter to discuss Mercedes Benz sponsoring her “She By Sheree” fashion show. Meanwhile, Lisa brings NeNe for a visit with her family and a celebration of her grandmother’s 92nd birthday. Back on the East Coast, Kim visits Kandi in the recording studio. As they bond, Kim asks Kandi to produce "Tardy for the Party" for Kim and NeNe to record.', '2009-08-27', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
