INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41436710B7A4455083AC355ACFF6EDEF', X'5C1B881FAC584D72B63F209952D4F902', 10, 'Episode 10', '1066 and All That....  It''s 913 years since Britain was successfully invaded and next Sunday marks the anniversary of the famous battle that took place at Hastings. Christopher has taken Blue Peter film cameras to Caen and Bayeux in France and Battle and Hastings in England to follow in the footsteps of King Harold and William the Conqueror.', '1979-10-11', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41437A4588FC4A42B5C30CF13587CC7D', X'FA6F43F4B9444C33AC69DDDBF54C0C16', 5, 'Little Red Riding Hood', 'Mary Steenburgen encounters a surprise on the trip to grandmas -- he has big eyes - big ears and a set of sparkling Razor sharp teeth. He has decided to take an extra liking to "Miss Hood" as he accompanies her on her trip through the forest. He hasn''t counted on the cunning and ever-sweet Granny nor has he thought about what danger he might be in from Miss hoods admirer -- all in all the vain wolf learns that humans are just as cunning.', '1983-11-10', 51, '/637nz7MofZxtTQgy6ZoopCEyRd6.jpg', '2026-04-03T17:38:40Z', '2026-04-03T17:38:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'414D5F343D2C4F13861F5DDD05587ACE', X'190C6E498849440487D4EAEF943A6024', 9, 'Oakie Doke And The Orchestra', 'Doke delivers some bottles to Granny Annie''s house for her lemonade, which accidentally gets ruined by Neptune, who puts baking powder in the lemonade instead of sugar. While Granny Annie cleans up, Oakie stops by the Corncrackers'' house to teach the animals to make music and they all form an orchestra.', '1995-11-06', 10, NULL, '2026-04-03T17:19:24Z', '2026-04-03T17:19:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
