INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4164EB6D70F34A5D84A87C3728EB66EB', X'DA06465B91544FEBA455374DF7DAB02F', 21, 'Telly''s and Baby Bear''s Story (4103)', 'Baby Bear and Telly decide to use their imaginations to write a story together, but have a hard time deciding on whether their story should be about a magic bowl of porridge or a magic triangle. With Maria''s help, they realize that best friends should be able to work together and compromise by deciding to write a story about both! Their story takes place in the Kingdom of Dum Diddley Dum Diddley Do. In this Kingdom, there is a magical triangular bowl of porridge. The bowl has three sides and three angles, and is filled with an unlimited amount of delicious porridge that King Baby Bear absolutely loves. Baby Bear and Telly realize that they make a great team and decide to write another story together!', '2005-09-26', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
