INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41AAD78F38B64D34AF6119DD43198AE8', X'4A8E3DB080684FF3942F91F45F665F20', 5, 'Shooting Stars', 'The lions try to stay awake at night, in order to see a meteor shower. Of course, this is not as easy as it sounds, as Theo says, ""Lions need a solid 22 hours of sleep a day!""', '2000-04-07', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41ACD3E228044C3AAB0D122A6B6A9BDA', X'DE8EC76916BB436BBE43AEDC7E18A7D7', 5, 'A Dog and a Song!', 'When Elmo and Abby can''t find a band for their friend Mick to sing in, they come up with the idea of making their own band. The music sounds just right for him.', '2019-12-14', NULL, '/ncqtlI9YxedbQttcYmJxTHC6QU.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
