INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41B62AACA90D403EB017A392420268FE', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 118, 'Queen of the Castle: The Elaine Benes Story', 'When Seinfeld needed a girl, Julia Louis-Dreyfus fit the bill, bringing luster and laughter to the show.', NULL, 22, '/dqghFBEQRkiWax3kpNoxfwqPnqo.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41B8CF1A54A54E34B13608AE133EB540', X'D5383B3D56364D71B99CB84774B4B3C6', 4, 'Pingu and the Big Fish', 'Mother is rolling out dough in the kitchen. Pinga is playing nearby. Pingu comes over and sees Pinga’s trumpet on the floor. He picks it up and blows it. Pinga tries to get her trumpet back from Pingu, but he won’t let go. When Pinga lets go, Pingu tosses the trumpet into the air over his shoulder, and it lands in Mother’s bowl of flour. Mother comforts Pinga, then tells Pingu off and tells him to go away. Pingu trudges outside and sees one of his neighbours telling another about his successful fishing trip. Pingu sees the bucket of fish that has been caught and has an idea. He rushes indoors and gets his fishing rod. On his way out Mother stops him, points to the clock and tells him not to be late back for supper. Pingu goes to a nearby pool and starts to fish. Pingo arrives and watches. Pingu has a bite, but hooks nothing, and Pingo laughs. Pingu is annoyed and shoves the rod at Pingo, telling him to try and do better. Pingo soon has a bite, but when he lifts the rod there’s a lobster hanging onto the bait, clacking its claws. The lobster drops back into the water, taking the fishhook with him. Then a big fish jumps from the water and splashes back in. They wonder how they can catch the fish, as the hook has gone. Then Pingu has a brainwave. He takes the handle from the bait bucket and uses it to make a large hook, which he ties onto the line. Pingu baits the hook and Pingo starts fishing again. There are lots of bubbles around the float but no bites. Later, as it’s getting dark, Father arrives home from work. He goes indoors and greets Mother and Pinga; Mother tells him that Pingu went out earlier but hasn’t yet returned. Father goes out on the sled to look for him, eventually finding him fishing at the pool with Pingo in attendance. While Father tells Pingu he should have been back home earlier, Pingu gets a bite, and it takes all three of them pulling together to land the large fish that Pingu has hooked. They proudly take the fish home, Mother cooks it and Pingu’s family and Pingo all enjoy a fish supper.', '1998-01-08', 5, '/nzyQkLDV6SR4nZ0J4FZY6GAXJ5z.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41BF37517EBC4088870967759889B235', X'387DA09C95C349E8A7FFFCBB68362CC0', 9, 'Love', '', '1993-03-19', NULL, NULL, '2026-04-03T17:35:46Z', '2026-04-03T17:35:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41C90057C6364D9A9D9B595949281A18', X'119C16D5104745EC8242C72A8EED423B', 46, 'Misfortune Teller', '', '1996-11-06', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41D2C728DFD946ADB74C21D06D759089', X'5BA20443D99F482081F66832D3F2BC4F', 10, 'Flowers', 'Flowers are an important part of many plants. Plants use flowers to make other plants – to reproduce. Flowers have special parts, called stamens and pistils. When pollen from the stamen finds its way down through the pistil, the flower is pollinated, and seeds start to grow. The seeds eventually find their way to the ground, the seeds sprout, and more plants are born.', '1996-01-27', 26, '/72XaGmWtSRaeiVvWt0doULPQCyu.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41D75D271F4D49A2AA652ADF41ED65AA', X'6F731E6BD3C54DE684E17A19CB650E86', 8, 'Riders on the Pawn', 'Run in slow motion with the Pawn Stars when a David Hasselhoff signed rescue buoy from the set of "Baywatch" floats in. Will Rick and Chum hassle the Hoff for a deal or will it get cancelled? Then, sparks fly when two flintlock blunderbuss pistols barrel in. Will Rick aim for a deal or will it be a blunder-bust? Next, Rick and Corey get energized while checking out a six person solar bike. Will they amp up the offer or will the seller charge too much? And later, Rick breaks on through to the other side when a yearbook featuring Jim Morrison is brought to the shop. Will he make a deal for the Lizard King or will he graduate without an offer?', '2015-11-12', 21, '/cY8wbsDcHpppb5D2RGg6d5msuPF.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41DF0309E6DA4D6A9FB69787D9A9252F', X'4C79C0B621A442778967BE1E791EFDBE', 6, 'Poor Pingu', 'Pingu wakes up, and tries to wake Pinga. She doesn’t wake. Pingu then sees she’s got red spots on her head, and suspects she’s put them on herself with the crayon he finds nearby. Then more spots appear and Pingu pulls back the blanket. Pinga is covered in spots. She has measles! She yells, and Pingu calls his parents in. While his parents comfort Pinga, Pingu is asked to call the doctor, get a wet cloth, get some milk, get a woollen hat, get some biscuits and open the door for the doctor. The doctor examines Pinga, and everyone ignores Pingu, so Pingu starts to examine the contents of the doctor’s bag. He finds a badge, but this is grabbed from him and given to Pinga who by now is starting to feel a bit happier. Pingu is fed up with the attention Pinga is getting and of being ignored himself, so he fakes that he has a cough, then a temperature and then a sore foot. All of this is ignored. Father then asks Pingu to empty Pinga’s potty, which he unhappily does. On his way back out of the bathroom he spots Mother’s lipstick, and uses it to make some spots on his head like those of Pinga. He goes back into the bedroom and pretends that he’s poorly, and he’s put straight into bed. Mother wipes Pingu’s brow with the wet cloth, and the spots start to come off! Pingu is told off, and Mother wipes away the rest of Pingu’s lipstick spots. Some proper spots then appear on Pingu’s head, and he’s now really got a temperature and the measles as well. Pingu is given his own badge by the doctor, and is now the centre of attention rather than Pinga. Pinga is dismayed, so she gets out of her bed and climbs into Pingu’s bed next to him. The doctor gives each of them a lollipop, and they quickly cheer up.', '2005-01-10', 5, '/hRQseRjLBk32OxpEhVuKU6noUSW.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41E300DF38CD4F68B10EE5E19924FB4F', X'9193E795DA7C40ECB68FF63AA7D5174F', 6, 'You Win or You Die', 'A prequel to Game of Thrones Season 2 which recaps on the first season and gives insight into what''s to come.', '2012-03-24', 22, '/6M8HOqp1AnaabsMnBDczrxMPPVS.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41E396F3E1634E24AA6D2FBA266C4514', X'5BA20443D99F482081F66832D3F2BC4F', 1, 'Rivers & Streams', 'Water is massive; rivers are powerful. As rivers flow downhill, they wear away rock and soil to form canyons or winding curves in the land, called meanders. Sometimes rivers fill and overflow their banks. Rivers with too much water create floods that can carry away plants, trees, buildings and boulders. Rivers and streams support most of the ecosystems on land.', '1995-11-03', 26, '/o2AkrlCEjk1zeJTOMm6caFG8IbC.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41E53722A2EE4F26BE19E902F4095CCB', X'D306A064E835417E85480CF806295F31', 18, 'Reunion Part 2', 'Larsa opens up about her new boyfriend, Marcus Jordan, and defends her fighting tactics; Julia gives an update on Martina''s multiple battles with cancer; Kiki joins the ladies and drops a bomb on Lisa.', '2023-03-16', 44, '/xyZGU5KNBqQ6522trbVvlDEPMBo.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
