INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'41F7F74D74C941089D088B3731D4E2DD', X'97D7FF20E6FF4DBBBCDDFD87A1D0FA4E', 8, 'May the Miniforce Be With You', 'Corey finds out if the force is with him, when a seller comes in with two Star Wars Lego minifigures. Can he "C" his way to a deal, or will he run into a brick wall? Then, Rick and Chum mosey on down to Texas where WWE Champion Booker T helps them authenticate a pair of wrestling boots. Will they tag team a deal, or tap out? And finally, Rick tries not to pop with excitement when he checks out a Jeff Koons Balloon Dog statue.', '2023-05-03', 41, '/mHPJ8KOpS79NShwEI1CAhW9ogYm.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
