INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4293DD2FADDB4461865847566653174F', X'40700E8A1DCE4895BEDE522A13A8BCAD', 12, 'Buddies', 'Martin and Chris are best buddies and Zoboo wants a special friend he can depend on as well. He meets a sea anenome and a clown fish, some sloths, langur monkeys and chital deer. At last, he finds his own best buddy Shark, the chameleon.', '2001-02-12', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'429CB17BBD2149CCB4B4DAF000865EEC', X'F4D370CA3C3940A8911DE2B5E7C6B0D7', 10, 'Little Bear''s Cold Day', 'It is a very cold day and all the toys are trying to think of ways to keep warm. They play various games that involve running, skipping and rowing but as soon as they stop they feel cold again. Zebra even suggests that they hibernate under a pile of leaves. Ruff thinks that a game of catch would be a better idea. However, it isn’t until they are in the middle of the game that they realise just why they have been feeling so cold all day.', '1996-11-06', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'429F4813463F480084645117E28C1E48', X'87F8406382B345A4936C3759E5D91CE3', 8, 'A Wolf Pack Of Secrets', 'Jen lashes out when Lisa brings a salacious rumor about Jen to light. Meredith and Heather plan a girls'' trip to Vail, while Whitney meets with her brother Will to check on her estranged father Steve. Finally, Lisa hosts an intimate event, leaving Jen off the guest list, and Meredith reeling after a cryptic warning from one of Mary''s former parishioners.', '2021-10-31', 44, '/dSx0oiXaWDN57KFlo1Ah9JhwQRh.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'42A32874CB71445DA323499B8C7AE574', X'54FACB0BDB5941FE9D64C7C7221A3C81', 10, 'Shalloween', 'After learning that Bethenny missed her Halloween performance, Luann takes another dig at Queen B; Dorinda shows off her new apartment to John; Ramona, Dorinda, and Sonja attempt to give a speech at the NY Loves Kids event.', '2019-05-08', 60, '/o2CSLkdwerrpsAP9vIfgaHFvyVc.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
