INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'42B7054CD62D402DB00036D71E00C43D', X'CEFD1496B6494C62AEF935A22558AC08', 9, 'You''ve Yacht To Be Kidding Me', 'More sun and tequila as the housewives keep the party going in the Mayan Riviera, Mexico.  Brand and Stephanie go undercover disguised as LeeAnne and D’Andra to swindle their room key in search of the “toy” that Kameron just loves to hate.  And it’s anchors away when their grand finale yacht trip sails into stormy waters as the truth comes out about vicious rumors LeeAnne and Cary have leveled at each other’s husbands.', '2017-10-09', NULL, '/qyK1bW6sMX7zPN4eEY1DEhxRMZl.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
