INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'42B81771D1F74D6F87A2437B97C7FDE1', X'3B5C322F56504381948F712C5AA2D0A5', 3, 'Hotel Animal', 'LeVar dreams he is miniature size and everything around him is "so very big." When he Awakes, everything is back to normal. He learns that size can influence your perception. Things look bigger and a little scary when you''re small. But as you grow, your perception changes. The suggested books are "Hotel Animal," "The Three Bears," "Mr. Tall and Mr. Small," and "Zoom."', '1996-10-09', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'42BACE15EEAC468BB49A4C434D5BD3FE', X'DE052E8E7DBD454AA6D8B9AFBA6E9BFA', 17, 'Weighing In Time', 'Orinoco decides to put himself on a diet, because he thinks he''s too fat.', '1973-06-18', NULL, '/UADMBNVSo1MnJTe88oK6S5rq5h.jpg', '2026-04-03T17:23:19Z', '2026-04-03T17:23:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'42BF7C3723F54BDDA10DD544C7CFFE84', X'1D713CA64E174F84949C8CFD98514127', 31, 'Captain Rick', 'Set sail with the Pawn Stars when a medal from British explorer Captain Cook lands in the shop. Will this medal be a discovery for Rick, or will the deal end up shipwrecked? Then, Chum hits the green when checking out a golf putter from the famed 1963 Frank Sinatra Invitational. Will he score a hole in one or wind up in the rough? And later, when Rick’s stress level hits a new high, Chumlee tries to calm him down. Will his idea help Rick keep his cool or will he erupt?', '2014-11-13', 21, '/eUoLK95Sxd4t4n29AchjjxK1l6D.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
