INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'42D0EC9E05444238B5570141874EDB40', X'56FC62048C9D4BA3A4E70D0A7DE40DC3', 17, 'The Dinner Party from Hell - Producers Cut', 'Camille throws a glamorous dinner party at her Malibu home and, in addition to the housewives, she invites a few special guests. The guests, however, bring up a sore subject and sparks fly between all the women in an explosive showdown.', '2011-02-15', 43, '/dFxCPgtt6jnq5kYT5CI7SlD65LS.jpg', '2026-04-03T16:34:54Z', '2026-04-03T16:34:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'42D8CACA1B794547A082D691AC552809', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 23, 'Zoe Loves Rocco', 'Zoe asks Elmo to watch her pet rock Rocco for her, but he''s too busy playing with Baby David to notice when the rock disappears. He tries to placate Zoe by giving her a new rock, then uses his memory to figure out where the rock went.', '2010-12-28', NULL, '/egdShQrQRd8wZh1mJR27SYp8CST.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'42DA0039B3DB443FAA10B4BB27D8235D', X'90CC8678A14F4D05BC1E54A3117895D5', 2, 'Winter', 'A harsh winter arrives and the Farthing animals are finding food scarce, especially because their recent arrival left them unable to stock food. Whistler and Speedy spare some of their fish for the meat-eaters, but the animals soon become sick of the same diet. While out hunting Fox and Vixen meet Scarface and his mate Lady Blue. Vixen tries to start a conversation with them but Scarface warns her to stay on her own land. Meanwhile Badger slips in the heavy snow while out walking and is injured. The Park Warden finds him and takes him back to his home to treat him. The other animals worry for their missing friend. Badger manages to persuade the Warden''s cat to inform the others that he is safe. While the cat is telling Mole about Badger being with her at his cottage, Kestrel spots them and thinks Mole is in danger. She dives on the cat, injuring her and causing her to fall to the ground in pain.', '1994-01-14', 25, '/thpemi5p0O2oNI66gX3CTWXh3mJ.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
