INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'42EE4E08AD7744C2972DFF099353D13C', X'BD8A516B9872472DA8387AFF1070FEA3', 12, 'Lou Rawls', 'Fozzie Bear has a new rollerskating act, but since he doesn''t know how to skate, he spends the entire episode careening around backstage. He eventually manages to roll out onto the stage to tell his jokes, but when he gets too ambitious and tries to skate backwards on one leg, he falls off the stage.', '1977-12-16', 26, '/dgfqY85w5dKcR1bKlUYGezK5CQV.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'42F2A500EF914644BAD9C0175A576C6F', X'4D2CAC0F38FD438B8AFAACF43952E535', 173, 'Episode 173', 'A magazine programme for younger viewers. Introduced by Christopher Trace including Letter U in the Blue Peter Alphabet and R.J. Martin showing you how to start Your Own Coin Collection.', '1962-02-26', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'42F5A29FCCAC45F8B4E8DE5A196F82EF', X'87F8406382B345A4936C3759E5D91CE3', 20, 'Memorial Meltdown', 'The Cinco De Mayo festivities intensify as the tension between the ladies boils over. Mary and Meredith cling together as the rest of the women hound Meredith for the date of her father''s memorial and struggle to understand Meredith''s unwavering support for Mary. Once back in Salt Lake City, the women try to make sense of all chaos left behind in Zion. Jen visits Mary’s church to see if the rumors are true, Lisa seeks advice from John and Meredith offers an olive branch to Heather and Whitney.', '2022-02-06', 44, '/6mPo4JJnynvfVhb6PlAFerSu26q.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
