INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'42FFDF7A76824A5FADD203B4C7F899FD', X'7CCD5605FE0B4E00AE7F3E3DAA252F8B', 9, 'No Boundaries', 'Alexis Bellino and Tamra Barney continue to grow closer and meet for a game of tennis. After the match, the ladies talk about Gretchen Rossi’s upcoming Tupperware party and Alexis is shocked to learn that the two are still feuding. Later, Gretchen and her boyfriend, Slade Smiley go to the Del Mar races with Alexis and her husband, Jim, where the discussion turns to the ongoing argument between the ladies which Alexis is determined to mediate.', '2010-01-21', 44, '/pi6LG7VlRC8NEq1IywL2xeVZTBc.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
