INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4318CDE9A64E45259A918D71CE1AFA18', X'34BDCCFA3C144E1C914885C29AADC0E1', 50, 'Around Africa in Eight Hours', 'Allison has lost her computer records on Africa.  Chris and Martin have only eight hours to try and revisit all the places they had been to during the series.', '1996-08-09', 30, NULL, '2026-04-03T17:11:47Z', '2026-04-03T17:11:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'431A573268FD4788AF9E2DF4A3243F0A', X'3EE646E823AE4DECBBC6C7E6A210D55B', 75, 'Miles'' grandparents visit', 'At Gordon and Susan''s apartment, Preston Rabbit is excited because Susan''s mother and father (Dorothy and Lee) are coming over for a visit. He assumes that being grandparents, they''re going to give presents to Miles; as a present-giver himself, watching others give presents is the next best thing. As Susan’s parents try to chat with Gordon and Susan, Preston eagerly picks at the shopping bag Dorothy and Lee brought, and Lee thinks it''s time to reveal what''s inside.
