INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'43538DDAD24247D482E53C3111CA60C4', X'0191683425EC43D69A1B8EA5D9630ADC', 9, 'Whistle-Stop', 'Shaun finds musical whistles that make the flock move involuntarily, creating chaos.', '2025-06-05', 7, '/t4IJzH2hN9dlUSR4qbZ1KiYrRg8.jpg', '2026-04-03T17:39:33Z', '2026-04-03T17:39:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'43541CFE0C99487AA72B6EAF8B971A8B', X'5C16DB9D5E7140EBB44EF559B2DDB8F3', 7, 'The Boy Who Left Home to Find Out About the Shivers', 'Overcoming fear is a problem for most people, but there once was a boy whose problem was his complete lack of fear! Peter MacNicol stars as that boy in this amusing production narrated by Vincent Price. The king played by Christopher Lee promises the boy treasure and a beautiful princess if he can defeat an evil sorcerer who has haunted the kings castle. The boy meets an ominous mute hunchback, a headless man and ghosts galore and finally the sorcerer himself (in a duel to the death fight). Yet, he still has no fear, until the surprise conclusion.', '1984-09-17', 51, '/iMiUSLitczrJvWU0TAUZL9xsRmj.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
