INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4369745F9C404D96A264228111C90C2B', X'F4D370CA3C3940A8911DE2B5E7C6B0D7', 8, 'The Jolly Dragon', 'Old Bear is reading Little Bear a very exciting book about a dragon. When Old Bear explains that there aren’t any real dragons, Little Bear decides to pretend to be a real dragon living in a cave, just like the one in the book. But it isn’t until the other toys arrive that he discovers how realistic his dragon mask is. It takes Old Bear to sort out the problem of just too many dragons.', '1996-10-23', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
