INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4373BB023EF147EFA2E830D5EF59ED5A', X'F812042DEB85432E80473675886E0B1B', 9, 'Digging Up the Past', 'Wishbone and Joe meet a charming elderly Oakdale resident who has returned after a long absense, and together they search for a ""time capsule"" in Joe''s backyard.  Meanwhile, Wishbone imagines himself as Rip van Winkle, who falls asleep in the forest and wakes up twenty years later to discover that a whole new nation (the USA) has been born.', '1995-04-02', 28, '/tnplStnQDp8il0LFS1a4UM3PM05.jpg', '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'43744CFC644D449AB9BF499A0EDBBB15', X'208E80DE61E34A2F857FC667FFC29134', 13, 'Lola Falana', 'After years of failure Gonzo is actually appriciated for the actor he is and decides to quit the Muppet Show and move on to movies. Piggy, more jealous than sad, asks Gonzo to refer her to the director. This is one of the episodes that teeters on the edge of being very sad.', '1980-01-18', 26, '/dKoTYpRzGScOXhffhZt4EnOG6ks.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4380AF2CF9664D4D8BFC8B47C54FC379', X'5D97D70CFCEC41CE8E0D78AB624FE334', 4, 'Grover''s Super Suitycase', 'Elmo''s sad his daddy has to go on a work trip, and Grover''s on a mission to cheer him up — but it isn''t working. Sounds like a job for the Help Fairies!', '2025-11-10', 30, '/tLe01PNJkRi8joi2U31G3g17AKL.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
