INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'43E402EB354E4715BC27482BD0A42F50', X'20D7138EEEA846A88ADA2B0F0EE1F674', 4, 'Episode 4', '', '1982-09-23', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'43EABDDED80D4663AE24F2B0A8D758B6', X'AD4E434833344A088928455D9BA524C1', 17, 'Debbie Harry', 'Robin''s Frog Scout troop visits the show, getting in everyone''s way backstage. They ask Debbie for help earning their punk merit badges, and she teaches them how to do the pogo. When Gonzo cancels his act, the Frog Scouts get their chance to do a performance of close-order drills.', '1981-01-25', 26, '/kcRR8yJW1Nh4Yz3IueeuH5AMzRq.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'43F86221F9F149B996531A5C28F9CE97', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 1, 'Forensics', 'Forensic scientists try to find out the who, what, when, where, and why of events in the past – crimes. Most forensic scientists work in police labs. They collect evidence from the scene of a crime and analyze the evidence in a lab. Forensic scientists look for clues that will help them solve a crime. Fingerprints, footprints, hair, blood, and traces of gunpowder can be helpful evidence. Forensic scientists use all sorts of scientific instruments to analyze even the smallest bit of hair or the tiniest chip of paint. By scientifically testing evidence from the crime scene, and by knowing about evidence from past cases, forensic scientists can piece together what happened, to figure out who did what, and to help police catch a criminal.', '1997-09-19', 26, '/yjVkHw6JReCit9oIdcVd7IZb0hZ.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'43F9092DB431440BB6329106A0339698', X'A8FACD21E7864FFFB89F7EB83EBA2231', 44, '2399 - Ronald Grump builds the Grump Tower', 'Ronald Grump, the Grouch building tycoon, approaches Oscar with a new idea - a two-story can-dominium called "Grump Tower." In exchange for Oscar giving up his property to build the tower, Grump gives him a spot in the tower, as well as three bags of trash. Maria thinks it''s a rotten deal, which only encourages Oscar further.', '1988-01-14', 58, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
