INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'442FB4254E6E4E389BE0327FD2D4D564', X'EB7E3BB45746457781C6F5B2DC2EFC6E', 14, 'City of Walls and Secrets', 'Having finally made it into Ba Sing Se, the kids are given a house in the upper ring. The kids are anxious to tell the Earth King their plan but there are complications. Meanwhile, still convinced that Iroh and Zuko may be Fire Nation, Jet decides to take matters into his own hands and do whatever it takes to get the refugees to reveal their true nature.', '2006-09-22', 25, '/ewTBqdyYruMREGkKbMZysZ0QgoG.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
