INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'44637756DDC6494AB0A233761C2A53AC', X'54900370898846B8B7AA61D2B88D7056', 7, 'Above Neck and Below the Belt', 'In a can''t-miss crossover event with "Below Deck Down Under," the women take off for Heather''s Caribbean adventure, but one housewife is noticeably missing. Once on deck, Britani flirts with Capt. Jason and the deck crew. Angie tries to find her sea legs. Bronwyn and Whitney question whether one of the women has been leaking stories to the press.', '2025-10-28', 54, '/f2mIUK6ar7kOmX8tdrL4zFa0cGJ.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
