INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'446E0FBD810A48AF8F8DC5453D515F75', X'2F5A4FFE2548418185AC6145CB3E3BF7', 4, 'Kody''s Shocking Move', 'Aspyn goes wedding dress shopping, but after the fun, Kody drops a huge bombshell; with a weird whiteboard presentation, he tells his wives they need to sell their houses and move; Janelle digs in her heels and refuses to do this to her kids.', '2019-02-17', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'446EF0AD63124BC4A648721F49AAC8EB', X'CA09391ADE6A4B2BAEFCC2EFBC80A106', 1, 'Alistair''s Time Machine', 'LeVar goes to a totally-fictitious spot to find inventors from all eras. True to form, these inventors come from the distant past, Reading Rainbow''s near-present, and the future. Arnold Stang narrates Alistair''s Time Machine, the story of a boy who invents a machine that takes him centuries back in time.', '1991-09-16', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
