INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'44715ED5B80249648AB88707ED79DA96', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 10, 'Up In The Air', 'Big Bird and Snuffy are having a playdate and jumping in the arbor to see who can stay in the air the longest. They quickly realize that they come right back down after jumping in the air. Gordon comes by and explains that they can’t stay up in the air because of gravity. They might not be able to see it, but gravity pulls everything, big and small, down to the ground. Big Bird and Snuffy watch as Gordon shows them examples of gravity by experimenting with different items such as a book, a writing pad, a ruler, and a pencil. Shortly after Gordon leaves, Big Bird and Snuffy see Abby and tell her what they have just learned. They can’t help but think how fun it would be if there wasn’t any gravity and they could float in the air. With some help from Abby’s magic, they do just that! Floating is so much fun until they try to play catch, and the ball doesn’t come down. Then, they try to play with their race car, but it floats away too. Even their sandwich floats away! Suddenly, Gordon floats toward them and calls Abby to bring back gravity so things can return to normal. With a spell and the wave of her wand, gravity returns. Big Bird and Snuffy happily return to the ground and continue their playdate!', '2010-10-14', NULL, '/leQI2fqyvcD0rjPsNchtteDByCP.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4475AC52BCE041788C2F4A3D9F08A4BB', X'4A8E3DB080684FF3942F91F45F665F20', 27, 'Piggyback, Piggyback', 'After reading a book about a king who rode on his friend''s back (because he didn''t want to get his feet dirty), Leona wants to do the same. So she hops on her dad''s back, and doesn''t want to let go!', '2000-05-09', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
