INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'447DEDCF22474CD5AB4FC2808D42D818', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 55, 'Big Bird and Snuffy pretend to explore Sesame Street', 'Big Bird and Snuffy pretend to explore Sesame Street, imagining it''s their first time seeing it. They observe an "umpadumpus tree," meet some friendly native "Sesame Streetians" speaking "Sesamese" and attempt to communicate with them and learn their customs, and encounter a wild animal (Barkley). Oscar kicks off the annual Grouchketeer Dirty Face Contest.
