INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'44A2D49D484448CBB606BDB87A8BB734', X'ECB64EF34F8045A7B4A9C04434B02E35', 41, 'Everybody Do The Dinosaur', 'Head to the front line with the Pawn Stars as a Henry rifle from the 1800s storms the shop. Will Rick be able to hit his mark or will he mis-fire? Then, Corey is brought back to the Jurassic Period when he encounters a pair of dinosaur eggs. Can he whip up an offer or will the eggs leave him scrambled? And later, when Chumlee holds a garage sale, Rick is put in the buyer''s seat when he spots some vintage wrestling dolls. It''s boss versus employee in a big battle of negotiating skills and only ... one ... man ... can come out on top.', '2014-05-22', 21, '/jvNPCcJ1I4hRuKNZOjNsC9pKg24.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'44A73D3A2DCE4014B4A0555A6A7CC6F0', X'D920EBAEF00A4E25ABFE40492C74DED6', 23, 'Bang, Zoom, Pawn on the Moon!', 'It''s a space race at the Gold & Silver for an autographed Apollo 10 book. Can Rick land a deal before the seller lifts off? Meanwhile, Chum calls in Joey Fatone to get NSYNC on a collection of figurines. Can they get them No Strings Attached, or will the seller say Bye, Bye Bye? Then, a set of Bob Hope''s golf clubs putt into the shop. Will Rick''s offer be par for the cost? And later, Rick steps right up for a chance to buy circus sideshow banners. Will he get clowned, or be the master of cereMoney?', '2020-06-22', 42, '/lmz74VhSU17W7wnsFCr7o9iMgAh.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
