INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'44E8F6DDBADC4539B3DEC0C783D35690', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 39, 'Telly meets Placido Flamingo', 'Telly Monster and a few kids hear some unique vocalizing; sounds they''ve never heard before on Sesame Street. They approach what Telly describes as "some kind of bird," a simplification the voice objects to, who introduces himself as Placido Flamingo from Santo Domingo, world famous opera star. He e Bob comes by as Placido continues to lead Telly and the kids with vocal lessons.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'44EFC8B7302C4794999FCEA9816930E2', X'363A94F9E0E5441CAA862BE2E9832DA1', 11, 'Declaration of Indepawndence', 'Rick heads to New York City to check out an original broadside of the Declaration of Independence; a seller jets into the shop with a rare playset based on the hit ''80s film "Top Gun"; Corey kicks it with a Chelsea Football Club jersey signed by American soccer phenomenon Christian Pulisic; a seller brings in a memo written during production of "The Wizard of Oz" that leaves Chum over the rainbow.', '2021-12-11', 42, '/xMXjARqg4Da30ogKLxTRYZ3XNw3.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
