INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4508DBE648B547E0933DC3B27A5DBC81', X'5BA20443D99F482081F66832D3F2BC4F', 5, 'NTV Top 11 Video Countdown', 'Join Bill Nye as he counts down the hits from the Soundtracks of Science. Along with the music, Bill does a few new experiments on the lab bench. You’ll see the grunge band Nyevana’s classic “Air Pressure,” Momentisey’s “The Faster You Push Me,” and divas En Lobe’s “Whatta Brain.” There’s even a special appearance by Mudhoney, a real band from Seattle. But if you want to know who’s the number one artist from Not That Bad Records, you’ll have to tune in.', '1995-12-01', 26, '/eIpSfO2CU7XHeuZN5RJ4tBgy0PX.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
