INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'45711A8C720745F5B51A6CB878D04F7D', X'5062CE298DBB48AB879B0771221678D5', 11, 'Treasure Island', 'Percy uncovers a treasure map and he and Squirrel go and find the island it was buried in. They do find it eventually, but Percy then remembers he left a fruitcake inside the oven, and goes back to his hut, leaving Squirrel not knowing where he is.', '1999-11-28', 15, NULL, '2026-04-03T17:19:02Z', '2026-04-03T17:19:02Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'45714BA4C235429B9E11222C42960AF2', X'42E591E22A884434AE9F3D4B1D685613', 26, 'The Bald and the Beautiful', 'Get "superfly" with the Pawn Stars when the guys eye a coat custom-made for Elvis Presley. Will they get all shook up over this one of a kind piece, or is the seller headed for Heartbreak Hotel? Then, Chumlee checks out a Mercedes-Benz golf cart. Will he take a swing at buying it, or is the price out of range? And later, the guys tease Rick about his bald head, but will their pranks get out of hand?', '2013-10-10', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4571F7F900134DB6A9BA9EE4CC8D0FD5', X'78A02D50E3DC4549844A3CF357A32EF4', 5, 'Shade Grenade', 'Reeling from the news that her son, Kairo has run into trouble with the law, Sheree leans on Bob for support. Kenya and Matt''s relationship continues to spiral downward and at his surprise party, Kenya shocks guests with news about the guest of honor. While Cynthia and Noelle begin to look for a new home, Mama Joyce surprises Kandi and Todd with a special evening. On her way to visit Apollo in prison, Phaedra receives a disturbing phone call that turns her world upside down.', '2016-12-04', 43, '/rAIaPDRXGyv9OvigLSg7EG5lWlg.jpg', '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4578D4E15AEE4721A00557CA7E09E3DA', X'44624EE803F04261837968DAF4666B42', 3, 'Arthur Plays the Blues', 'Arthur''s beloved piano teacher is retiring, but she assures him that the new teacher is outstanding. When he meets Dr. Fugue, who''s as strict as he is odd, Arthur begins to doubt his own abilities.', '2001-10-01', 13, NULL, '2026-04-03T17:37:57Z', '2026-04-03T17:37:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
