INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'457ED7CB1A31417781320A6A9AA199A3', X'70C8CB4624944DD498F66BFB9B3FAF73', 5, 'Guns and Rangers', 'The Pawn Stars have a chance to buy a key from the 16th or 17th century, but this key doesn''t just open doors, it shoots bullets! Will they use this rare antique key-gun to unlock a deal - or shoot themselves in the foot? Then Corey and Chum meet a dumpster diver with a life-size Power Ranger. Will Corey use his super hero powers to conjure up some cash, or will the dark forces compel him to cast the Ranger out? And later, Rick has a chance to buy a trophy presented to Jeff Gordon for being one of NASCARs top five drivers. Will Rick throttle up his cash register for the trophy, or will the deal go screeching into a pit stop?', '2010-02-01', 21, '/kwD7vpbN9YYh1Ioh7E3P7il88cK.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
