INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46406E94BD7B436297A60AC30FE551B1', X'04572E48BBFD476BAEBEB6DC424F742D', 2, 'Kaer Morhen', 'Seeking a safe place for Ciri, Geralt heads for home, but danger lurks everywhere — even Kaer Morhen. Yennefer''s dreams could be the key to her freedom.', '2021-12-17', 59, '/bD0fkV9hxxxjmQXWfjB1LZQ154s.jpg', '2026-04-03T15:40:45Z', '2026-04-03T15:40:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
