INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4647B16D98A0422DA2248CB7EB03409C', X'F6015D9AECE4414AA00B06CF689FE40B', 13, 'Sport Relief Spectacular!', 'Find out how Lindsey and Radzi got on with their Sport Relief Challenge. How many steps will they be able to add to the Mega Mileathon Totaliser? There''s a sneak peek behind the scenes of Sport Relief. Plus Dako Flying Angels showcase their fantastic gymnastic display skills!', '2018-03-22', NULL, NULL, '2026-04-03T17:22:10Z', '2026-04-03T17:22:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'464DDFD8E9234B73870A88660BFD59AC', X'73AE1459BA914185A9DABF6F2844AF49', 21, 'Viva la Dysfunction', 'In the season finale, the women look to the future but can''t escape the past. Luann records a new song that she hopes to feature in her upcoming cabaret. Leah continues to rebuild her relationship with her mother. Sonja clashes with Ramona on how to prepare the townhouse for sale. An invasive surgery has Dorinda looking back at her tumultuous year. And when the ladies come together for Sonja’s Drag Queen Bingo party, the evening goes from fabulous to ferocious when an old wound is ripped back open.', '2020-09-03', 60, '/evRUmxvSgYpT6Ii5KRa7oqb1vmF.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
