INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46D6DFF2A6CC434CA52D463E2CB9FC45', X'95CA8B6FCCBC431A9D959B23367BBFED', 16, 'Threats and Promises', 'Kathy’s dinner party ends abruptly, following a flurry of accusations hurled amongst the women. In the fall out, Garcelle accuses Lisa of never having her back, and Sutton unloads on Kyle for pushing her too far. While Crystal is sympathetic to Erika’s reaction, someone close to Dorit takes a more critical approach toward her friend.', '2021-09-08', 43, '/o5WvOfGoPCFhIdinDEGahG4UcVB.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46D790EFA5964E9F80D21064F23A62C2', X'46D7A706C7A84EBEB96F387C66E8BB8B', 84, 'Episode 1529', '', '1981-03-19', NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46E216DE833E41198222312671479438', X'27A5A980EC0D4637B5BADF8324A6405A', 19, 'The Paper Route', 'Brick takes a job delivering newspapers, in order to save up enough money to buy night vision goggles. Meanwhile, Axl tries to convince Sue that a long-distance relationship with Matt won''t work. Elsewhere, Frankie discovers that Mike has been hoarding batteries.', '2012-03-14', 22, '/oVxDrUscSF6alvxr5tsaeyaIpIN.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46E41FD74C564CCBBEC7E64B2F159CB1', X'2F8DD62982C34F8E87C0963473C49284', 11, 'Resorting to Madness', 'As the ladies head to Puerto Rico, drama around room assignments threatens to throw the trip into chaos. Erin and Ubah attempt to clear the air and make amends. A comment from Rebecca offends Brynn and leads to a heated exchange at dinner.', '2024-12-10', 43, NULL, '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46E431E6AE74475DB265DF88EEB5CDB0', X'3087A3EDE94E42769D02A78183DEA1D3', 15, 'Praise the Pageant', 'Cynthia stages her pageant and cautiously allows Kenya to be a judge. Elsewhere, Phaedra enlists chef Roblé Ali to serve up a lusty dinner; Kandi tunes up to record a duet with gospel''s Marvin Sapp; Porsha tries to juggle various elements of her life.', '2013-02-17', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46EBF021D5C2406D927C652F28D42F79', X'136B81D3964D4B8FA21492F00D96D6B9', 78, 'Snuffy''s disguises', 'Snuffleupagus tries on a series of clever costumes and disguises, hoping to fool Big Bird into thinking he''s someone else entirely. Despite the creative costumes, Big Bird easily recognizes his long-eared friend. Snuffy laughs good-naturedly at how transparent his disguises really were.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46EC7127657841BC97AAC33A3256B6DA', X'7CCD5605FE0B4E00AE7F3E3DAA252F8B', 7, 'Love and War', 'After a tumultuous year, Vicki Gunvalson has a romantic surprise in store for her husband, Donn. Alexis Bellino and her husband, Jim, get their three small kids ready for church. Although they enjoy the finer things in life, they feel justified because they are very generous with their donations to their church and a number of charities. Tamra Barney and her husband Simon, rehash their recent trip to Florida and disagree about whether or not Tamra should let Gretchen back into her life. Lynne Curtin agrees to allow Gretchen to take her teenage daughter Alexa shopping.', '2010-01-07', 44, '/jJpdRm4IF9jFzbBMsOWaaDoBw5a.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46F0B205F23B4D88BFD943C84BBC1433', X'EBC90A3F7ECB46B3AF55E3DEEBE49408', 11, 'Arthur Makes Waves', 'James invited D.W. and Arthur to swim at his house. Arthur is shocked to learn that Molly is James''s older sister.', '2005-04-04', 13, NULL, '2026-04-03T17:37:58Z', '2026-04-03T17:37:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46F3BF3A23BA429B80EB62D0EB22A6E1', X'7C422193B07849D881EFF2B9F94F059D', 52, 'Mother Goose visits', 'Episode #3057', '1993-01-19', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46F67F4593A34951830694FE7C8E6321', X'1A534647384B4C00BB6CA3371AD962EB', 1, 'Trading Up', 'Get animated with the Pawn Stars when an original sketch from "Rocky and Bullwinkle" is brought into the shop. Will Rick and Chum be drawn to it or will their plans get erased? Then, Rick is presented with what is believed to be a first edition of Richard Nixon''s memoirs. Will he win this presidential piece or will he resign to defeat? And later, Chumlee spends the day trading up ordinary items with the guys in order to get what he really wants. Will his wheeling and dealing lead to a big score or will the guys end up shutting him out?', '2015-01-08', 21, '/lMK055kBUQchtvqctQfP6VENWw5.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46F7D11E173C493E871EF676390F6745', X'596E6E8FF65147F283B8D4CDEE8E5927', 15, 'Episode 15', '', '2005-07-10', 25, NULL, '2026-04-03T17:21:20Z', '2026-04-03T17:21:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46FB9D721AB3479DB9315F58E59C3A7E', X'36EA381466B44986B6EE44559D3562C1', 8, 'Ghosts of Girlfriends Past', 'NeNe plans a visit to a local haunted mansion to spook the ladies. Phaedra isn''t getting along with NeNe''s friend, Mynique. Kandi begins to annoy NeNe.', '2013-12-22', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46FD025C56AE4B5190606F0807761889', X'97A3D1F5A8F147CD81222E74A092836D', 17, 'Who is Max Mouse? (1)', 'Jamal is writing an essay for a high school he wants to get into. Just then, Ghostwriter appears with a warning. Suddenly he is kicked out of the computer. A weird message appears from someone or something called Max Mouse. At the auditorium, the computer teacher informs everyone that a hacker is loose. He warns the students not to use any disks. Strange things start happening: the sports page advertisments for basketball tryouts is changed, and Jasmine is arrested because she is suspected of using stolen credit cards. While Tina was trashing in the computer lab, she finds strange words on a sheet of paper with a wad of gum on it, along with Janice Hall''s computer quiz, which was very hard, and she had gotten an A on that quiz.  [Why would it be in the trash? --minnymouse35] Then Ghostwriter informs the team that Lenni could be in trouble with the police, and they learn that the words Tina found on the sheet are passwords to get into the school computer.', '1993-12-26', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'46FE7FBF2049420EB00FDA76FAB4FC43', X'1996DDD820C94A3096BE2B87FAB8D17C', 20, 'To the Light (3)', 'While trapped in the abandoned subway, Rob tries to spell out a message to Ghostwriter to tell the team where he is. Can Ghostwriter read the message?.', '1993-02-07', NULL, '/u1AkxdIMehkRRWCcFOHRI0r8KcD.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
