INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'471314FC42FA485BAF792908B3FC64C3', X'0191683425EC43D69A1B8EA5D9630ADC', 20, 'Fleece Navidad', 'Shaun goes extra Christmassy for the background of the Farmer''s Christmas card photo by secretly knitting festive jumpers to brighten it up.', '2025-12-01', 7, NULL, '2026-04-03T17:39:33Z', '2026-04-03T17:39:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4713E60F53A740FAA1E5B1B28E6E382D', X'9310A2885AF04746A8D7D7635FFB6BEB', 10, 'Work', 'Mister Rogers opens by talking about how his job is to make television programs for children. As the camera pans out, viewers are treated to a glimpse of the studio where Mister Rogers'' Neighborhood is filmed. After briefly introducing Johnny Costa, Bobby Rawsthorne, and Carl McVicker, Mister Rogers returns to his television home and talks about writing music. He then sings It''s You I Like and spends some time thinking about the kind of work that children do.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4719ACCF4E7641FA933E082438B37175', X'4861CE46904543C7963F27B4EA539804', 69, 'Episode 199', '', '1971-02-11', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'471AD16B60264EFAAEDB436DBCFE13D2', X'B6A0F2287DDC409CB808681B777A6704', 9, 'Mister Rogers Talks About SUPERHEROES', 'Rogers brings model dinosaurs and takes viewers to a hall of dinosaur skeletons at a natural history museum. A dinosaur with a crown appears in the Neighborhood of Make-Believe, although it is really a skeptical Purple Panda in a costume. This is all part of Lady Elaine''s ploy to scare the neighbors.', '1980-05-29', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'471E1594BA584C6BB69367BC8AB8D575', X'9B95011E93DB4E56A45D8AA956C15997', 12, 'The Pontypandy Cup', 'When Joe and Mike discover that Norman is entering Pontypandy''s big go-kart race, The Pontypandy Cup, they get very nostalgic about the go-karts they made when they were kids.', '2014-06-21', 10, '/sMtNXoli6uOhg6NqWhR8JcYy3qW.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'471E1665BDAB4F17B53E3CA1C151BB0F', X'D8CCF6D3E37A430AB67D7FBF269BF0BE', 9, 'Don''t Come for My Sound Bath', 'After Angie and Monica reconcile, Angie gets caught in the middle of Lisa and Monica''s feud. Whitney juggles parenthood and career by throwing two parties in one weekend, and tensions boil over between friends. Heather tries to come to an understanding with Lisa. Meredith dips her toes back into the group, but Lisa has questions about her recent behavior.', '2023-11-07', 55, '/bC41GYLkCD9nn1jADKlD5NAHztl.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4730D873ABD4409896C63EA7FCB650B3', X'4060AD7F4B8F43938EB166A150B928B6', 10, 'Huff and Puff Away', 'After Chris reads the story of the Three Little Pigs, Elmo wonders if they can change the story so the wolf isn''t mean.', '2021-01-14', 26, '/gUNyH8ctuv3VFsAVAfPOaiwaTK.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'47390DC071A94FE28EAA4ACBC1283344', X'F593D90C533942F59C885BFD48D04075', 11, 'Cheetah Cheater', 'A wildlife film inspires Pidsley the cat to play a prank on the flock by disguising himself as a leopard. Shaun is convinced there is a huge beast on the loose and concocts a plan to catch it.', '2009-12-13', 7, '/vaEcLlOtL3G8EN8QB1fawjtwP5q.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
