INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4744F8BCA6074DABAC3C7D07C64A53A5', X'52F9C16BA60F4EB7B9915C3BF70877BF', 7, 'The Finale', 'Jeana shops with her son, Shane, for some last minute items as he prepares to leave for college. She also decides its time to bond with her daughter Kara -- by inviting her to an exclusive diamond-shopping trip. Its time for Shane to leave the nest and Kara is visibly upset with her brother''s departure.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'474782FDD1CF4E18AC98548D8C35B2C0', X'F593D90C533942F59C885BFD48D04075', 6, 'Who''s The Caddy', 'The farmer comes across his old golf clubs and decides to knock a few balls around, instantly putting his back out in the process. Shaun takes the opportunity to learn how to play, while Bitzer is forced to tend to his injured master inside the house.', '2009-10-21', NULL, '/s4ZhBzvrbOnsywtcoEvaUCsiWUT.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'474853429D2B436F9851B57E419EF1C1', X'4900FC8D5E7E408E972ECE9269D203B3', 15, 'When in Aspen…', 'The ladies head to Aspen for some fresh air and much-needed relaxation. Upon arrival, Noella and Heather go head-to-head over the primary bedroom. Shannon begins to question her friendship with Emily. A relaxing dinner is turned upside down when all the women face-off over brewing tension.', '2022-03-30', 44, '/cb5RAXmuFEKkzAsALDmK9KKKQpI.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
