INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4752644E75444D2892F73031CB427049', X'9193E795DA7C40ECB68FF63AA7D5174F', 94, 'Histories & Lore: The Free Cities', 'Jorah Mormont explains the rise of the “Free Cities” of Essos in the wake of Valyria’s Doom, detailing how the cities differ and what one can expect to find in each one.', '2013-02-19', 4, '/lqhA7XSmZnPRxTyWlqvlHrsAjlX.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'47543A56C3214797BA62EC258195413D', X'5C1B881FAC584D72B63F209952D4F902', 60, 'Episode 60', 'Octavia Aviator!  Twelve-year-old Paul Sharp from Retford won Blue Peter''s ''Name the Owl'' competition and two days as a VIP guest of the RAF''s Number 8 Squadron at Lossiemouth. As well as meeting the squadron''s Great Eagle Owl mascot, newly-named Octavia, Paul joined the crew on a training flight over the North Sea in one of the squadron''s historic Shackle-ton aircraft!
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'47570FFC8C514BE6B02F68BDB8A4772C', X'4B4D327B6C8B459C9E73B1D4D84AED77', 6, 'The Green-Eyed Monster', 'Sister gets jealous of Brother getting a new bike.', '2003-09-23', NULL, NULL, '2026-04-03T17:40:22Z', '2026-04-03T17:40:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'475A15552FDE4AADB6B69B5E95E5097C', X'AD180412A5D64E4A8B49590334F2FC69', 13, 'Bully-Bully-Bully', 'Owl and Hollow return to White Deer Park just in time to overhear Bully addressing an assembly of his rats. She goes to gather the other animals and they plan to counterattack. Plucky sends Mossy to find Laird so he can send the white deer to stampede the rats. But despite their best efforts, the rats are still too numerous. There seems to be no chance of stopping them, until Cleo bites off Bully''s tail. All the animals, including the rats begin to laugh at Bully and he skulks off to the sewers where he came from. After the battle was won, the other rats apart from Spike returned to where they were before they came to the park and Fox calls an assembly to announce that he has decided to step down as leader of Farthing Land. He places Plucky in charge despite slight protest from Ranger. Trey returns to inform the animals that the Warden has merged White Deer Park with the new sanctuary to make one large wildlife preserve. He announces that with so much more space, he has decided to lose his brutish disposition, though he is still not fond of weasels. As Fox and Trey walk away together, Plucky decides that after a hard day''s fighting, everyone should rest and explore the new addition to White Deer Park the next day.', '1995-12-21', 25, '/2nMWgibFjsQWS5KIYJTxzJJieoJ.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'475FCC4455C0485381A9D65A8A44590C', X'3087A3EDE94E42769D02A78183DEA1D3', 17, 'The Strip Is a Trip', 'After leaving Hollywood, the Atlanta ladies head down to Sin City for the ultimate girls'' weekend in Las Vegas. When Porsha refuses to go to the strip club because of Kordell''s alleged objections, the ladies decide to school her on how to gain some independence in her marriage. Kenya can''t play nice with Phaedra forever and finally confronts her on the last night of their trip.', '2013-03-10', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
