INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'48273049A7CC472DBD247A1431EEFE71', X'05044F495F9C4E7FA74DB2FF19475D0E', 9, 'There Will Be Bloodwork', 'As their Florida trip approaches, the women cope with monumental life changes; Dina says goodbye to her long-time assistant, Luke; Teresa and her husband face a medical scare; Amber''s doctor delivers troubling news.', '2014-09-14', 43, '/5IEQpvpjYh1xiBruX3Hbg6ssPt8.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'482B4F95EFD740B3B8D3286A87D2BEC3', X'70C8CB4624944DD498F66BFB9B3FAF73', 28, 'Chumlee''s Dummies', 'The sky is the limit for the Pawn Stars as they consider buying a 1939 Allied Forces World War II plane. Will the gang soar to new heights and make the deal or will it stall out and take a nose dive? Then the Old Man has a chance to buy a munitions receipt from the War of 1812, signed by future President Andrew Jackson. Will this correspondence from the Commander in Chief be reimbursed for cold hard cash or is this historic invoice a cheap imitation? And later, a man saunters in with a pair of life-size western cowboy mannequins. Will Chumlee boss around a couple of new companions or will these hombres pack up and hit the trail?', '2010-06-28', 21, '/uXfJWzDEdKuENUejJvo6sOmOx00.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
