INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'484984D846764B3C93794B40A83B38B8', X'51F03551BA41409D85F4E51BDDFDF82E', 8, 'Game, Set, Feud', 'Jill gets set to play her doubles tennis match against Ramona and Mario, but it could be a histrionic racket when her pro tennis partner opts out and Jill invites Simon to play with her. It''s game, set, drama when the other wives attend the match. Meanwhile, Jill shows her home redesign to Bethenny; and Bethenny seeks help with her product-logo design.', '2009-04-07', 60, '/6jTJekac98AWhPPf9K7oNpGxkFj.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'484B75EB532B4488A90B34A476BF646E', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 8, 'Gilded Pawn Age', 'All aboard with the Pawn Stars when Rick checks out a Gilded Age train. Will he be able to hook up a buyer for this thing, or is Rick holding a one-way ticket to No Sale? Then, a classic Nintendo race car game from the 1960s rolls its way into the shop. Will Corey and Chum hit the brakes on a sale or will they cross the finish line? Also, Is it a bird? Is it a plane? No, it''s an amazing Superman and Batman print. Will it save the day and become a sale or will the heroes be defeated?', '2017-05-08', 21, '/7uyl7t7WN8W7qebOhkBmYnn4Erx.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'484DBF8D99C64649AC36B7A53299D143', X'E1063F8766C24E2DA91353362941AA19', 29, 'Episode 304', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'484F17A48F934CB28FA580E0C6F9E288', X'42E591E22A884434AE9F3D4B1D685613', 28, 'The Enigma', 'It''s a first for the Pawn Stars when a WWII Enigma machine comes in the shop. Used by the Germans to send top-secret messages, can they crack the code to owning this incredibly rare artifact? Then, Corey and the Old Man check out a photo of Old West gunfighter Doc Holiday. The only known photograph showing Holiday as a dentist, will this negotiation be like pulling teeth? And later, Corey''s big-spending ways have him strapped for cash. Can a financial adviser set him straight?', '2013-10-17', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
