INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'485D0ADE798B4EADBCAAA3A7F54C5E13', X'42E591E22A884434AE9F3D4B1D685613', 34, 'The Merchant of Vegas', 'Drop in on the Pawn Stars when the guys check out a Cushman scooter allegedly used by paratroopers during WWII. Will this negotiation have a soft landing, or spin out of control? Then, Rick and Corey look at a rubber bullet and shell casing from the Bloody Sunday massacre. Can Rick and the seller be as one, or has the battle just begun? And later, the guys send Chumlee to the mint to design a new commemorative coin for the shop.', '2013-11-07', 21, '/ndnhploAXo9BUaOcpIDOImVZ25X.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
