INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'48611B14C16D4F93AE2B75C3ECFAD208', X'B91685B5C0D44040B72E620169541BFC', 6, 'Studio, Jewelry, and Babies', 'Jo has her first studio taping and needs something strong to get her through... Lauri get a surprise herself when she comes out of a photo shot and will her new business fail after all...Vicki is jealous and girl''s night out is a little more than cooking...Tammy leave town for the weekend and her daughter has party but what does it take to pull it off and oh does mom find out?...And will anyone ever buy a horse for Tammy''s girls again?', '2007-02-20', 44, '/kFz4xEmMKswAffI7q1rWLmLFmfh.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4872DEE132AA42B49E2E06EF8309CFFA', X'4F149920CA764C31A71BD5B65A380905', 4, 'Greatest Haggles', 'Relive some of the toughest negotiations in the history of Pawn Stars including: a first edition "20,000 Leagues Under The Sea" book, a 1932 Ford Roadster, and a $95,000 Les Paul guitar owned by Mary Ford.', '2014-12-01', 22, '/99bmkqpi8X00vQ4hwfzgIUIfK3H.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
