INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'488666937F3F4442AF0D9205F39C9DE0', X'B753871204CE43A6916362280BBB084B', 44, 'Reporters Telly and Baby Bear cover the X Games (3894)', '', '2000-03-02', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'488A2C6397E1429C8CCBAE62B118921F', X'3982796B54514100904246BEDF6A20A5', 9, 'Pingu''s Family Celebrate Christmas', 'Pingu and Pinga are getting ready for Christmas. They help Mother make some biscuits, and then they go with Father to help choose a Christmas tree. While Father puts up the tree, Mother gets the wrapped presents to put under it. Pingu and Pinga want theirs now, but Mother says wait. Mother then trips over a rope on her way to the tree, and drops the presents. Fortunately not breaking them. She blames Father, and they have an argument about it. Pingu and Pinga go out to see what the fuss is about, and when Mother and Father see them, Pingu and Pinga tell them to stop and make up, which they do. Mother then tells Pingu and Pinga to go into the igloo, and to make sure they stay there and can’t see out she locks the door and blocks up the keyhole. Mother and Father then decorate the tree, while inside the igloo Pingu and Pinga wrap up Mother and Father’s presents. When Mother lets them out, they take their presents to put under the tree, and are amazed when they see it all decorated. They give their presents to Mother and Father; Mother gets some hand warmers and Father gets a spotted bow tie. Pingu and Pinga then open their presents. Pingu gets a book, a ball and some earmuffs; Pinga gets a teddy bear, a dummy and a scarf. As night falls, the tree lights up and together they all sing Silent Night.', '1992-12-25', 5, '/s81HUgFK0L1jULgWdWCo0JKQL5u.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'488EA0AD53FE4C10A0DB4EB922235721', X'C9ADC698BE924DD794ADD8F6759361CA', 11, 'Welcome New Friends Pt 1', 'Rogers tells viewers of the time he had an imaginary friend. Daniel has an imaginary friend, Malcolm Apricot Dinko, whom he consults to decide whether he should spend the night with Grand-père.', '1973-03-05', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
