INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4898DC2B58C74748A5C3B25374145D03', X'F4938E7D11A84756B40598BEDD7C9B28', 9, 'Pat''s Foggy Day', 'There is a thick fog in Greendale. Pat feels foolish when he thinks a scarecrow is Ted and gives him a letter. When Pat calls at the church, Jess gets out the van. Pat soon finds him but they end up completely lost in the fog. When Miss Hubbard arrives at the church to see the Reverend Timms, she suggests that they ring the church bells to guide Pat and Jess back to the church.', '1981-11-11', 15, '/xVXqL8pF20vddAa9s3kniPmS2O.jpg', '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'489C037F1E6342E0884582867E65650A', X'9920276098D04DDAAB2048D2B5C65987', 5, 'Get Schwifty', 'When a massive head descends into Earth''s atmosphere, Rick and Morty must save the planet by coming up with a new hit song. Meanwhile, Jerry, Beth, and Summer become part of a new religion.', '2015-08-23', 23, '/jBUDahgRdHQUrDGcd44ju2AllbV.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'48A107EF4DB849828B80A565A59E15E2', X'52F9C16BA60F4EB7B9915C3BF70877BF', 2, 'Is It Hunting Season, Yet?', 'Rabbits have overrun the gated Orange County community, and Jeana''s son Shane has gained the reputation as the official "rabbit hunter." Jeana decides it''s the perfect time to take her kids on a vacation to Mexico, where Shane finds romance.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'48A2360C2E1A473E9F2A4612421BF5AD', X'301FB9134E76408FB84B05BF979766FE', 3, 'The Maestro', 'A maestro impresses Elaine, jeopardizes Kramer''s lawsuit and makes Jerry curious about housing in Italy.', '1995-10-05', 22, '/jkPBUlfcQftTQAVmlmOqs0Avmz4.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'48A8F8069EE24DB1924692FC901F4846', X'3087A3EDE94E42769D02A78183DEA1D3', 8, 'Fools of Engagement', 'As the Anguilla trip comes to an end, there is still plenty of unfinished business to be addressed. Kenya hopes to leave the island with at least an engagement ring, while NeNe focuses on squashing her bumpy past with Kandi. Cynthia works to clear the air with Kenya, but Porsha keeps her guard up in case Miss USA decides to come for her again. Tensions rise at the final vacation dinner when one couple gets thrown into the hot seat.', '2012-12-23', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'48AC958271D341FBB2DD068C812859BA', X'EFDF1E4F84764382A9D72B9DA4188BE0', 9, 'Transformations', 'Rogers fixes the ball float in the toilet. Maggie Stewart demonstrates some sign language, using a book in the process. The Neighborhood of Make-Believe remains perplexed by the mysterious package for Purple Panda. And things don''t get any better once Purple Panda arrives.', '1996-08-16', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
