INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'48D29DA910384631B00EB16A80067578', X'45E01C046AC641E187D8F749EE230385', 2, 'Pontypandy Extreme', 'Norman is upset when Trevor accidentally runs over his skateboard. Not prepared to wait until his birthday for a new board, Norman decides to retrieve coins from the bottom of a wishing well and buy one himself. When Norman becomes trapped, Sam must use the abseiling skills he has just learned from Tom to rescue him.', '2008-02-12', 10, '/pkRoPrXwNbCcu1JEZLQqgbQsTom.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'48D3CE0D3B6941A1B2ED6ACDCBDE592D', X'3ADE5E1F84414C2CACF6FB933A61DCFA', 1, 'That''s The Way The Cookie Crumbles', 'Gizelle attempts to rekindle her friendship with Karen by delivering her homemade treats, but is shocked by what greets her at the door. Recovering from their miscarriage, Ashley and Michael are back in full baby making mode, meanwhile Robyn takes her romantic relationship with Juan to new heights. And with her wedding only days away, Candiace reveals that she''s invited her half-brother to the nuptials, causing her mother to launch a verbal attack that threatens to derail the festivities.', '2019-05-05', 42, '/4KA71PHqVnh4xmDBCtyhweXWOu1.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
