INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4976928504574AAAB4B6F2ABFE7B8162', X'465E5A6D74B64FFBB54F51103F8329B3', 4, 'Fourth Wall Down', 'The ladies start to let their guards down as they take in the breathtaking sights of Turks and Caicos; Kenya gets a triggering message that sends her into a spiral; Melissa begins her high school sleepover-inspired night at the villa.', '2021-11-18', 45, '/nLSXI97Jb9lSqY91ljzp6vw0dq5.jpg', '2026-04-03T16:34:40Z', '2026-04-03T16:34:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49796182F9BB44F498FC1A1379C6B006', X'EFDF1E4F84764382A9D72B9DA4188BE0', 10, 'Transformations', 'Rogers shows a wooden egg that contains a speckled egg. He then returns to the McFeely''s house, where plants are transplanted and ducklings are delivered. In the Neighborhood of Make-Believe, Lady Elaine Fairchilde retrieves the package for Purple Panda. Much to everyone''s surprise, the package opens itself. Maggie Stewart Stops Instead Of Mr McFeely A Videotape On How People Make Towels', '1996-08-16', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'497A93F3E57E4A55A3E30F5FC297EE1C', X'34674C90410E427CBE4D2A6F6F865A80', 13, 'Dirty Sox', 'Pop goes the Pawn Stars when four original paintings by Andy Warhol brush by. Do the guys give these rare works 15 minutes of fame, or just send them back to the factory? Then, a baseball signed by members of the infamous 1919 Chicago Black Sox has Rick and Corey seeing green. Will the guys signal for a steal, or does a tough negotiation knock the price out of the park? And later, a pair of 10k gold sunglasses comes in on the night shift. Can Chumlee and Olivia eye a good deal on these vintage specs, or will the seller have it made in the shade?', '2012-06-11', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'497F6D9CB7E3488D94087E22A82D05AF', X'D1863F2F02EC40CEAF64DB03FBE518A7', 28, 'Mi Amigita Rosita', 'Rosita is bothered by a story that doesn''t resonate with her culture, so she writes her own book about things she loves: dancing, Mexican wrestling and playing with her friends. Also featuring celeb vocab in espanol with Gina Rodrigues, and Elmo the Musical. Brought to you by the ABC''s and the number 9.', '2016-07-16', 30, '/8qhlVyqgBXGlHjAEywzfS2C0vY2.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
