INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49834956561848A6A455DED523ED9850', X'6C1EC19F74DF4F359A6117B98175D826', 8, 'Mind Your P''s and BBQ''s', 'Garcelle is honored for her work with a local charity, but her acceptance speech isn’t charitable to one guest. The ladies feel mom-shamed when Denise shows up to Kyle''s kid-friendly barbecue without her kids. Lisa, Erika and Teddi are annoyed when Aaron mansplains to them – a situation Dorit knows firsthand is problematic for husbands in this group.', '2020-06-03', 43, '/fslHhX8mGivoQCqG9am5hKGdMkL.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49843BC09B6C42F9A71EF3493AEC28EB', X'9C9D89DF5F6B41D084C6B8CA7BD2A2E6', 5, 'Bug Scouts', 'Bug Scouts Elmo, Abby, and Cookie Monster want to help Artie the Ant carry a heavy crumb. They try pushing the crumb, but it’s too heavy to move. What if they break the crumb into smaller pieces? Let’s try!', '2021-12-09', 20, '/zMldaJvP7qKtyDFI4VWiVwzuVE1.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49873AE51F21418EA8CBECBBE29D41A5', X'AE8F64D94B834147A44CBFE720381F8E', 13, 'Abby Has the Sparkle Fairy Freckles', 'Elmo and Abby are playing tag. Suddenly, Abby’s freckles start sparkling! Abby calls the Fairy Doctor who looks at Abby’s freckles. Abby has a case of the Sparkle Speckle Fairy Freckles! This is where freckles sparkle and glow, and eventually fall off. The Fairy Doctor tells Abby the magic words to get the freckles back, “Fricka-Fracka, Freckle Back-A”.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49897CDA4764436E8A7DA369F68A9495', X'A8DB07E5FBA349A9BD12947C111B39BE', 22, 'Reunion (2)', 'A reunion continues with the Big Apple ladies. Here, Bethenny gets emotional about her life situation, Dorinda addresses her inclination to meddle, and the group zeros in on the saga revolving around Tom.', '2016-09-07', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
