INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49B1C4994E424D7AB4D0958149072494', X'42E591E22A884434AE9F3D4B1D685613', 37, 'Rebel, Rebel', 'Hail to the Pawn Stars when Rick and Corey check out a letter written by George Washington during the Whiskey Rebellion. Can the guys rally the troops to force a deal? Then, things get larger than life when Rick and Lili check out a Bob''s Big Boy statue. At over eight feet tall, will the shop have room for this classic piece of Americana? And later, Chumlee decides to throw a housewarming party at his new house. Will it be the party of the year, or a total flop?', '2013-11-21', 21, '/edg5taRVWsVAP8hdWZNu1JAxLRU.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
