INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49BAF3D663914BBCAC1B0CA90AE490B1', X'432A6ABDDCCA44CC82CEFB39E33B8949', 42, 'Episode 42', 'Susan Linn helps Rogers discussing how puppets can be used to express feelings. Her Audrey Duck character appears in the Neighborhood of Make-Believe, and scares Baby Ana Platypus.', '1971-04-13', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49C54873417F44C1958AC0C8B0DB3DC3', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 119, 'Oscar meets Rachel the artist', 'Big Bird greets Susan, Maria and Barkley before checking out what Bob is up to. Bob is listening to an opera on the radio and Big Bird imagines if everyone sang instead of speaking. Maria stands still as Rachel, an artist, paints her portrait. Oscar enjoys Rachel''s stained overalls and bossy attitude as she tells Maria to sit still.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49C784C8A644492B9B8DC497EDED2BFC', X'3CE5073998114824B0ABD68F59C37F5B', 4, 'Are You a Snail?; Wonderful Worms', 'The Information Hen helps some creatures figure out if they are snails or slugs; a search ensues for a missing pet worm.', '2008-10-06', 30, NULL, '2026-04-03T17:12:30Z', '2026-04-03T17:12:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49CAEB412B214A25A05FF8E26DE179AA', X'9DF0F8C1723F40618692E8C51A6A7223', 8, 'Episode 8', '', '2026-07-12', NULL, NULL, '2026-04-03T15:40:44Z', '2026-04-03T15:40:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49CC13567AAF48BD87F7EFA1DE865CA3', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 20, 'Veggies Revolt', 'Chris serves Telly a tuna sandwich with no lettuce just when a group of vegetables is heard nearby. They are holding picket signs, while marching and chanting. Anderson Cucumber, a reporter for VNN, arrives to find out what’s going on. The vegetables aren’t taking it anymore. They think no one likes them and they don’t feel appreciated, especially because Telly didn’t order lettuce on his tuna sandwich. Telly explains he was actually going to have salad on the side. Everything seems okay now until Zoe leaves broccoli on her plate. Chris encourages Zoe to eat her broccoli, but she would prefer to dance. So, Chris introduces The Veggie Dance! All the dancing makes Zoe hungry, so she tries the broccoli and loves it! This makes the vegetables happy until Anderson Cucumber reports that Cookie Monster is eating cookies instead of vegetables. Chris helps Cookie Monster pretend that his vegetables are cookies, such as a delicious broccoli cookie. Cookie Monster devours the entire plate of vegetables! Another victory for the vegetables! Shortly after, baby Natasha refuses to taste the strained vegetables that Gina is feeding her. The vegetables become offended again and plan to leave, but Chris explains that Natasha is just a baby, and everyone else on Sesame Street loves vegetables. However, by the time everyone finishes singing “We Love You Vegetables,” even baby Natasha has eaten her peas!', '2010-12-14', NULL, '/urQZ8vLD2fo6PXdu4eulB5Mlkei.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49D260115F0941C8BF62B3405330D793', X'136B81D3964D4B8FA21492F00D96D6B9', 108, 'Fluffy goes missing', 'The gang searches frantically when Fluffy, a beloved pet, mysteriously goes missing from Sesame Street. Everyone helps comb the neighborhood, creating lost animal signs and asking questions. After much worry and searching, Fluffy is finally found safe and reunited with his relieved owner.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49D2911454CD4AD9BBABF49DD6B12527', X'E291DF42D44F49E5BF812DF32EE4A30F', 3, 'Lost And Found', 'Ojo loses his favorite teddy bear and the members conducted a search party to help search for it, but in vain.In the end, they played hide-and-seek and Ojo found his bear back.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49D550C5B1C2460893458B4F4CDC3E9D', X'F63C3F6109704E3781CC2B9045A9952C', 51, 'Baby Bear Roller-Skates (3966)', '', '2001-03-12', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
