INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'49E8FF4DB350462987EFD9826C733D7B', X'DA06465B91544FEBA455374DF7DAB02F', 1, 'Telly Learns How to Catch a Ball (4083)', 'Everyone on Sesame Street is outside having fun and playing catch! Well, everyone except Telly, who admits to BabyBear he doesn’t know how to catch a ball. Baby Bear, Rosita and Maria each try to help Telly. But no matter how hardhe tries, the ball slips through his fingers! Just when Telly decides he’s ready to quit, Baby Bear introduces a surpriseguest, New York Yankees manager, Joe Torre! Joe assures Telly he’s doing everything right, and reminds him thatsometimes learning something new takes a lot of practice. As he leaves, Joe tosses the ball to Telly—and he catchesit! Now Telly wants to practice even more', '2005-04-04', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
