INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4A457545DE9D4733B1DC177EDA839AD8', X'AE8F64D94B834147A44CBFE720381F8E', 21, 'The Planet G', 'Maria helps Elmo write a story about the letter “G.” Elmo is having trouble thinking of letter “G” words, but Maria reminds him of the letter “G” sound. Elmo thinks of the word “golf”. He draws a picture of himself playing miniature golf and hitting the ball so hard it flies into space and lands on Planet “G!” Elmo remembers another “G” word, “goldfish”, just like Dorothy, his pet fish! He draws a picture of himself riding on a goldfish up to the planet “G” to look for the golf ball.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4A47A974B83441C7BEFB1F84F4C7E9D8', X'5704FB3FFBBC417788B09226373A9D4E', 43, 'Episode 43', '', '1966-02-09', NULL, NULL, '2026-04-03T17:20:12Z', '2026-04-03T17:20:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
