INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4A4A3D279A704085B3338E02A3B012FE', X'5C4E51C6E20746AD875C72988EB1E13E', 28, 'Out of Gas', 'The Pawn Stars are off to the races when a guy brings in a 2000 Porsche Carrera engine that has been recovered from a junkyard. Can this deal go through firing on all cylinders, or will the engine''s questionable history make the negotiation run out of gas? Then, the guys pace themselves for a showdown when a seller brings in an early 19th century dueling pistol. Just half of the original two-gun set, will they drop some Hamiltons on this rare piece, or will they misfire and have to run for cover? And later, Rick is ready to rock when a hat once owned by Lynyrd Skynyrd front man Ronnie Van Zant comes into the shop. Will he give a sweet home to this piece of music history, or will the seller fly free and keep the hat for himself?', '2011-08-15', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
