INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4A52A2AD01B54E07A880182F608FFB18', X'9310A2885AF04746A8D7D7635FFB6BEB', 13, 'Mister Rogers Talks About GRANDPARENTS', 'Mister Rogers mentions that he has been thinking about an old car that his grandparents had when he was younger. Showing a picture of the car that he brought with him, Mister Rogers shares a video to remember a time when he drove a similar car. He also mentions that his grandparents often read to him which he believes is the reason he enjoys books so much. Mister Rogers then looks at a picture book about tools before singing Did You Know.', '1984-05-09', NULL, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
