INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4A7E8C5FC6904965BDB2180AD1426B1E', X'42E591E22A884434AE9F3D4B1D685613', 5, 'Ready to Rumble', 'Let''s get ready to rumble with the Pawn Stars as the guys check out a pair of punching bags owned by Rocky Marciano. The only champion to go undefeated in his career, can they land a knockout in negotiations? Then, Rick checks out a Swiss Doxa pocket watch from the 1800s. Will he give it the time of day? And later, when Corey installs a punching bag in the warehouse, the Old Man is inspired to show off his boxing skills.', '2013-06-13', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
