INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4AC86D0198A5438396D04E13EE92768C', X'7CCD5605FE0B4E00AE7F3E3DAA252F8B', 12, 'You Can Dish It But You Can''t Take It', 'Lynne Curtin’s daughters, Raquel and Alexa, are home alone when a stranger knocks on the door and hands Raquel an eviction notice. Vicki Gunvalson hears terrifying health news about her daughter, Brianna. Alexis Bellino and Gretchen Rossi meet for dinner and discuss Lynne’s housewarming party the night before. The ladies head to San Francisco for a girls weekend away. At dinner that night, everyone is annoyed by Alexis’ non-stop phone calls and texting with Jim at the table. The ladies begin the next day with a round of shopping followed by a beautiful water front lunch. Vicki takes a business call at the lunch table and this rubs Alexis the wrong way and she confronts Vicki about her comments over the previous night’s calls to Jim.', '2010-02-11', 44, '/pE5dgWeEHXyKBEcEwQlQxoT69Iq.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
