INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4AE0551E10374453931AC00BFCC30984', X'63F9BF6D39B344F4B885A56807277A80', 102, 'The Muppets On Muppets', 'Feature filmed in the late 1990s for Muppet Show reruns airing on the Odyssey Network, but not seen by the public until it was included as a bonus feature on Muppet Show: Season Two DVD box set. Kermit, Gonzo, Rizzo, Animal and some special guest pals sit down for these personal, revealing interviews. Notable for including multiple characters who were created for Muppets Tonight and had never appeared on The Muppet Show.', '2007-08-07', 13, '/f3a11y57y4f9gmxWByIFe9POMfl.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
