INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4AE8F260A3914CD0890FF4BDABA2714B', X'0FA9200282AE460985E33982BAA99AE1', 5, 'Postman Pat and the Thunderstorm', 'Julian is afraid of thunder and lightning, as is Mrs. Goggins. Bonnie goes missing, so Pat and Julian brave the thunderstorm to find her. Julian overcomes his fear by putting Bonnie''s needs first.', '2005-03-03', 15, '/d41pqaEW1l4ymw6ixoEMXsCFUxc.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
