INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4AEE7F9441D047E9B5F002BFEBE4D298', X'78A02D50E3DC4549844A3CF357A32EF4', 2, 'Housewive House Wars', 'Another unexpected guest pops up. Cynthia is forced to deal with the impact her marriage has had on her daughter and comes face-to-face with Peter. Kandi and Todd juggle launching an Ace-inspired product line and construction of their new restaurant. Momma Joyce gets the rumor mill going about why Phaedra''s divorce is dragging on. Porsha plans a girls outing.', '2016-11-13', 43, '/eZiALtDEkr2pnGq1y2Nm1XfMWED.jpg', '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4AFA9B74AD12479B942AB2D177D4E254', X'95C86B7F162E4E74812E73CCA314F182', 2, 'The Lion, the Witch and the Wardrobe (2)', 'After being given a task by the White Witch Edmund finds Lucy again and they return to their own world. Edmund lies to Peter and Susan saying that Narnia was a game he and Lucy was playing, will Lucy''s story ever be believed and will the Children all finally get into Narnia?', '1988-11-20', 30, '/c7zCRGqXwOSt3AJPYpyWrqEBwbw.jpg', '2026-04-03T17:17:41Z', '2026-04-03T17:17:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4AFF14715A2042BA8D02857A87324EBB', X'2B968A9C5FC04E93BCF931D3E4C7B210', 45, 'Episode 45', '', '1976-02-12', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4B0159D3701C49789E2A41EC199D8083', X'56428E5E7DAA468D8BD2076956507AA8', 3, 'Blood & Circulation', 'It''s time for a heart-to-heart talk about blood and circulation with Bill Nye the Science Guy.   Your blood is your bud. Without blood, your skin would dry up and fall off, your internal organs would die,   and your brain would be kaput. Blood gives every cell in your body the food and oxygen it needs to survive.   Blood also cleans up after our cells by carrying away waste. Blood even protects your body from disease.   What more could you ask from a friend?   Blood patrols your entire body. Blood is pushed around by a powerful pump called the heart. Every time   your heart lub-dubs, blood is propelled through tubes called arteries, capillaries, and veins. Your heat   pushes your blood in a complete loop around your body about 2,000 times every day.   Your heart is a muscle, and, like all muscles, it can get stronger. A healthy heart needs exercise to stay   strong. An average heart pumps about 70 times a minute, but a healthy, well-exercised heart pumps 50   or 60 times a minute. Heal', '1994-03-04', 26, '/uD5v8SUCvD68Dk9btmGtRzZdgNP.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
