INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4B05FAA308F9458DAB5DE1A3EC50628D', X'0BA7CC9B13144E1EB74F76463A622991', 13, 'Josephine the Short-Neck Giraffe', '', '1989-03-17', NULL, NULL, '2026-04-03T17:35:45Z', '2026-04-03T17:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4B068EF4517A41698FF7FC71106F2457', X'98D80972E53A43DDA03A7703465E6F87', 18, 'I Herd That', 'Set your sights on the Pawn Stars, as they check out a Sharps buffalo rifle from the 1870s. Renowned for its accuracy, can the guys separate this antique weapon from the herd? Then, Rick is offered an aphorism signed by one of America''s greatest writers, Mark Twain. Will Rick be clever enough to make a deal, or get outwitted? And later, the guys try to avoid a sour deal when some Victorian-era pickle castors drop by. Highly valued by collectors, will Rick make an offer, or is something not quite Kosher?', '2013-01-14', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4B0847A5B4F54ED9A2952C14B4241AFB', X'ABFE14EEDB424DDEA96A601FF3C53ECC', 7, 'Captain Snow', 'While Cluny plans to recapture the tapestry by burning down the abbey gates, Matthias determines to renew his search for Martin''s sword but does not know where its keeper, Asmodeus, hides. He learns that only the fierce mouse-eating owl, Captain Snow, knows where he is. To ask him Matthias has to pass the gigantic marmalade cat, Squire Julian Gingivere, and the Shrew of Mossflower Wood! Matthias breaks off the search for the sword to return with his new allies to once again beat Cluny.', '1999-09-24', NULL, '/z0oYSKx0uU3MD5dQY0HZl1N7BLI.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4B0E22DF07DA46B285F08428EAA73E64', X'70D9E39768134785887D27D034928BAE', 22, 'Pingu and the Ghost', 'Mother is ironing, but is distracted when a pot on the stove comes to the boil. Pingu sneaks out of the bedroom, takes a newly ironed sheet and returns to the bedroom without being seen. He draws a ghostly shape on the sheet and puts it over his head. He then jumps out of the bedroom right in front of Pinga, giving her quite a scare. Pinga dashs, crying, squealing, and squeaking. over to Mother to be comforted. Pingu laughs at her. Mother is not so amused, particularly when she spots what Pingu has done to her clean and newly ironed sheet, and Pingu is sent to bed. Later, Pingu is awake and alone in the dark bedroom, as Pinga is snuggled up in bed with Mother and Father, when the wind gets up. As well as the wind whistling round the igloo, Pingu can hear lots of odd noises coming from outside. The bedroom window suddenly bangs open and Pingu sees a strange shape moving around nearby! Is it a ghost? By now he is very frightened and hides under the blankets. Then a light shines under the door, he hears strange footsteps and there is also a mysterious shadow. Pingu cries out and is heard by Father, who has been having a late snack. Father goes into the bedroom and turns on the light, and then sees that the window is open and shuts it. Pingu tells him about everything he’s seen and heard. Father tries to reassure him, and tells him that the strange moving shape was just the towel blowing in the wind from the open window. Pingu is not convinced and is still frightened, so he’s allowed to join Mother and Father, with Pinga, in his parent’s bed.', '1996-08-08', 5, '/mkOQ3E9CG42ceUohspSySmjtURl.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4B134D4139C841D3B37EBC7736C1D760', X'8E5ED8A408E540069F36C68C91DDFEE4', 20, 'Episode 769', '', NULL, NULL, NULL, '2026-04-03T17:36:40Z', '2026-04-03T17:36:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4B14AEE284D040799C797EBFEDD2F4F8', X'68138DE20900460AB58E480688F1E081', 19, 'I Built That!', 'When Ojo decides to pretend that she''s a big bear, Bear invites her to join him on a berry-picking expedition at the Otter Pond. He''s going to make a triple-berry pie, but first needs the most important ingredients. He teaches Ojo the essentials --- showing her what types of berries are good to pick. After she learns the basics, Bear leaves her to the picking so he can prepare the crust for the pie. He and Ojo also find that Pip and Pop are trying something new. They each have a new toy --- their very own otter hoops. When they can''t them to work, they express concern that they''re broken. Bear and Ojo help them to see that often you have to practice at something before you can be good at it. In the Shadow segment, Shadow puts her spin on "Here We Go ''round the Mulberry Bush." In her version, a dog and a woman are washing clothes by hand, but decide instead to take them to a laundromat. They''re then freed up to go perform in a circus, until a man sends them back to work on the laundry.', '1998-08-08', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
