INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4B299FF428174BB9BD6B618B48AA03AC', X'70C8CB4624944DD498F66BFB9B3FAF73', 2, 'Wheels', 'The Pawn Stars have a chance to buy an incredibly rare 1970s Indian mini-motorcycle. Will they purchase the little hog and restore it to its former glory, or will they all be taken for a long bumpy ride and find out it''s a fake? Then Rick and the Old Man consider buying a ship''s bell believed to have been salvaged from a 1600s shipwreck. With suspicion that the bell was never submerged in salt water, the Pawn Stars will need to decide if the deal will ring true or crack under pressure. And later, a man takes a chance at selling his classic 1900s roulette wheel. Will Rick take a gamble with luck on his side, or will the deal spin out of control and put him in the red?', '2010-01-18', 21, '/5SwCvzDc3OEtqhhKq4j8bEEzgrS.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
