INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4BD02D3A708F45878B4E2488B95871AA', X'EFDF1E4F84764382A9D72B9DA4188BE0', 7, 'Transformations: A Juggler on a Unicycle Visits', 'JoAnn Swaim does a juggling act outside Rogers'' television house. Rogers shows pictures of the show''s neighbors as children and as adults. The Neighborhood of Make-Believe is looking for Purple Panda so they can give him his package.', '1996-02-20', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4BD092D9E8F0422588AF3A25A04935DC', X'45E64A158FC04E4BA1CA9E3F42F3634D', 4, 'Skin', 'Learning about skin science is no sweat.   It''s gigantic. It''s gargantuan. It''s your skin. It''s your body''s biggest organ. If you could lay your skin out   flat, it would cover about one and a half square meters. Your skin stops you from drying out, protects you   from the weather, and keeps bacteria and viruses from getting inside your body.   Your skin is also your personal air conditioner and heater all in one. Sweating cools you off. When you''re   hot, glands in your skin push a mixture of water and other chemicals onto the surface of your skin. When   the water evaporates, it takes some of the heat with it, and you''re cooler. When you''re too cold, your skin   muscles start twitching. Shivering makes your body warm up.   Without skin, you wouldn''t be able to feel the difference between a sheet of paper and a wool blanket.   There are thousands of touch receptors inside skin. When you touch the remote control, the receptors   send information about the remote''s temperature, thicknes', '1993-10-01', 26, '/5bMTXdmgDT2W4p7hQyRhscEDt3r.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
