INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4BF1BF94FEAD4271B4DE23F39F26B60A', X'119C16D5104745EC8242C72A8EED423B', 23, 'Arthur Writes a Story', 'Mr. Ratburn gives the class an assignment --- to write a story about anything they want. It seems like a simple assignment and it doesn''t even have to be bound and sent to a publisher as Muffy suggests. Arthur, however, finds it a hard task when he starts trying to write to please everyone''s tastes. He starts out with the simple story of how he got his dog Pal, but after following the advice of each of his friends, it morphs into a bizarre country tune about baby elephants being born in outer space.', '1996-10-22', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4BF61705234346D9844CF73C95705678', X'A8C6182E05E14B6891A55126CF6C94F0', 32, 'Benedict Arnold', 'According to James'' theory, there are British spies that are close to General Washington, how else could you explain all the conterattacks by the british? James is on a mission to find out! In the mean time, in his west point house, Benedict Arnold is bitter about the Congress. Becasue of his bitterenss, he meets up with one of the british officers and tells them of Washington''s plans, plans that if the british could get a hold of, would mean the end of liberty. What will Sarah think when she finds out her hero is a traitor?', '2003-01-20', 30, '/R6DXj0tbgvWPRsp23Y8E3Y17D9.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
