INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4C0F61EE1B3A41A7B9EC54F87C486FC6', X'78A02D50E3DC4549844A3CF357A32EF4', 25, 'Secrets Revealed', 'Phaedra and Porsha explore the world of edible hotel decor, while Kenya looks into maximum security for Moore Manor. Kandi''s baby mogul Ace has his first photo shoot for his baby product empire, while Noelle confronts Cynthia about how she handled the news of her divorce. As Kairo heads off to college, Shereé gets ready for her book launch. While Kenya and Cynthia try to persuade Phaedra to warm up to Kandi before their beef heats up to a full boil, Shereé and Porsha share a moment that sheds light on one of the biggest conflicts of the season. Porsha and Peter finally get to the root of their longstanding feud with a shocking admission from Porsha.', '2017-05-14', 43, '/5mvNfFSNYL7WSsikoqawgix0uNl.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
