INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4C289A0DD97246248ECD41FE36D6E916', X'70C8CB4624944DD498F66BFB9B3FAF73', 24, 'Whale of a Time', 'The Pawn Stars are presented with an engraved whale''s tooth believed to be authentic 1800''s scrimshaw. Can the gang make a whale of an offer or will it be a fluke? Then, the Old Man sets his sights on a pair of mysterious Civil War era rifles. Will he take aim and hit the mark or end up dodging a bullet? And later, a man brings in a pristine edition of Playboy''s very first issue - featuring Hollywood legend Marilyn Monroe. Will Rick sneak a peek or just read the articles?', '2010-06-14', 21, '/6GFOpWNeu8u0FUak4Z5gkUuOaC7.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
