INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4C4F00A90AE6499E90D3861AFD10E4AC', X'05C0E384194C44179F62803EB615E409', 19, 'Looking for a place for a windmill', 'Title number 0019. Opens with Mister Rogers arriving with a toy raft made out of straws. He plays with it and other floating toys in a tub of water. In the Neighborhood of Make-Believe, Scientist Alder is checking the wind velocity for Donkey Hodie, who is looking for a place with a good wind to build his windmill. He decides the best place would be in the hills behind the Castle, but King Friday objects because he wants his privacy. Back at the house, Mister Rogers shows different kinds of fans.', '1968-03-14', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
