INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4C5B05D3FD304132BE6A4475C439A64E', X'4FE93658C46343298E649D523869C2CB', 26, 'Wise Guys', 'The Pawn Stars take a mission briefing when presented with a fully functional 1941 M3 Armored Scout Truck from World War II. Will the gang head to battle for this bulletproof piece of military history or will an auto ambush force them to retreat? Then, Rick and Corey meet a man hoping to sell a check signed by notorious mobster Carlo Gambino. Will Rick make him an offer he can''t refuse or will this deal sleep with the fishes? And later, Rick and Chumlee check out a 1987 Apple II GS Computer. Will they boot up some cash for this classic piece of technology or is the deal bound to crash?', '2011-02-14', 21, '/yPT54dWgBaFG3gc7TCM3SKqgtKl.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
