INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4C60839859504326974E20B08CB68B9D', X'05C0E384194C44179F62803EB615E409', 1, 'Change: The First Program', 'Title number 0001. Opens with Mr. Rogers talks about tying his shoes. Mrs. Russellite sends an invitation to Mr. Rogers to see her lampshade collection. Lady Elaine''s changes to the geography of the Neighborhood of Make-Believe worry King Friday, who begins to impose new rules and restrictions in Make-Believe, and builds a wall.', '1968-02-19', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
