INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4C731FB545D44475A55A45303CE796CF', X'F4D370CA3C3940A8911DE2B5E7C6B0D7', 11, 'Ruff and the Big Wheel', 'When Little Bear accidentally breaks a wheel on Zebra’s cart, Old Bear finds a box of shiny, round lids to mend it. There are enough lids left over to make a lovely go-cart. When it is finished it turns out that Ruff is too big and needs a bigger cart of his own. But there are only two wheels left. Old Bear hunts in the cupboard under the stairs and finds a wheel that is much bigger than all the others. You can’t make a go-cart with only one wheel but what Old Bear does make is even more fun.', '1996-11-13', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
