INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4D371405D6624385B540B82539119048', X'F4C403079B5E4263A4E0DFA138131E7F', 38, 'Plaza Sésamo: Lola Aventuras', '"Lola Aventuras" ("The Lola Adventures") is a recurring segment on Plaza Sésamo, debuting in 2005. Each segment has Lola  going on an adventure and trying to solve a problem that she faced on her adventure. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4D37A2F1587842C494225B047A9F4A25', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 7, 'Do-It-Yourself Science', 'Do-it-yourself science involves a question, observations, a hypothesis, and experimentation. You have probably come up with questions after you noticed something unusual. For instance, why do fingers get all pruny and wrinkled when I sit in the tub? The observation – shriveled fingertips – is the first step. Do-it-yourself science requires an eye for details surrounding your observations. Collecting related information helps you get to the next step, what scientists call a hypothesis, or “educated” guess. After weighing all the evidence, you hypothesize that your fingers get pruny because of the hot water in the tub. Once you have a hypothesis, it’s time for the fun part – testing it out.', '1997-11-21', 26, '/mpSGYGf5QSt1p6l9V5s0ynU36Hd.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
