INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4D6AFD6C11374B3E8D109ABA7BB0EE16', X'33440D76E69F47ADAC25862CCBC9DFA1', 5, 'Pie in the Austin Sky', 'Ashley attempts to combat rising tensions in the group with a trip. Mia and Robyn bond over recent personal struggles. The rift between Wendy and Nneka widens as new claims and questions arise.', '2023-12-03', 43, '/bGNs1YPv2UjqicbpdKUem8bcPjm.jpg', '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4D6C186764B5407F906797F1632196DB', X'7C542833ED0A42729C53E822408AB434', 4, 'The Bravest Bird', 'Hannah starts a scarecrow business, but there is one brave little bird that just isn''t scared of her scarecrows.', '2024-10-03', 10, '/ewfiqISGKSWgX6SFLald50su82g.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4D6D9EA40B1C451AA0E7AFCA722AD011', X'353F8B38D837435488BDD51E98A3421A', 2, 'DELETE ME', '', NULL, 5, NULL, '2026-04-03T17:24:26Z', '2026-04-03T17:24:26Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4D7246F6F4DA40B1A44581E9225416B8', X'45E64A158FC04E4BA1CA9E3F42F3634D', 14, 'Structures', 'Are you tense? Need some structure to your life? Then tune in to Bill Nye the Science Guy as he   explains the science of structures.   All structures give support or create a shape. You can find structures everywhere. Bridges, buildings,   chairs, shoes, plants, spiderwebs, tables, and even your own body are all structures. A structure''s shape,   size, and what it''s made of depend on what the structure does and how strong it needs to be.   When structures give support, they either experience a pull (tension) or a push (compression). Structures   in tension, such as ropes, cables, or blimps are made from stuff that is good at pulling. The materials in   tension are usually thin. Structures under compression, such as elephant legs and courthouse columns,   are made from hard stiff stuff. Compared to structures under tension, structures under compression are   much thicker. When it comes to structures, form (the size and shape) depends on function (what it does).   Build support for Bill', '1993-12-10', 26, '/mlrSQ7yEP2IH5uSRWPWrUd5QXrm.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
