INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4E03147C20C1461C8BB839A3813511E0', X'5DB3FF78E43948E18F67988ECBF85D17', 6, 'Dogtanian Meets His Match', 'Juliette is still missing and her uncle has inadvertently revealed there is something in her room. At the house Dogtanian meets Monsieur Pip for the first time, catching him stealing food from the table. Dogtanian discovers that Pip''s family have lived there for generations, and he''s only stealing food because Juliette''s Uncle has been kidnapped by the Cardinal''s Guards...', '1981-11-13', 24, '/lai7M04Tecb2ur5mrqf3m6hnQvA.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
