INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4E10165775024FD7A4BC2294E1E1F2EC', X'3FC7C152E4F6426AA89936EC454C4403', 47, 'The Greatest Show in Dragon Land', 'The friends are excited to go to a new theme park called Wonder World, but they have to go through many obstacles to get there, despite Zak and Wheezie''s broken wing. However, when they finally reach Wonder World, everyone thinks this place isn’t Wonder World at all, since they think the obstacle rides were much more fun than the rides there.', '2000-01-20', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4E1307183319436B8BA3957A8C7D6D3E', X'A4843A51AEEF427C902C7FB3BD670CD4', 13, 'Music to My Ears', 'Ojo has formed an orchestra and has invited everyone in the Big Blue House to participate. Viewers are invited to participate too as Bear and the kids hold a concert out at the Otter Pond. Ojo is the orchestra "constructor," and Pip and Pop are using pot and pan lids for cymbals. As Bear searches for his kazoo, he comes across Treelo and asks for his help. When Treelo spots a radio, he turns it on and starts singing and dancing to music. He then goes off to create his own instrument. Bear finds his kazoo and also finds that Tutter wants to play the clarinet, but it''s too big for him. Bear helps Tutter to come up with another way to participate in the orchestra. In the Shadow segment, Shadow presents the tale of the cat and the fiddle. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4E16FC5AB6564DA0817B28B0CFB25A64', X'E606692A47B7411EB54B7C6BF61A67B7', 4, 'A Shower of Stars/Two Moons and One Lagoon', 'It''s nighttime at the library roof garden as Theo gives an energetic Leona a reread from the episode Shooting Stars. Then, under a full moon, Cleo gives Lionel and Leona a story from the episode Touching the Moon.', '2005-05-09', 30, '/5UonhiksNoxQaCOCxS6TS8bu459.jpg', '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
