INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4E3956EC28A043C8915B1C8B31203579', X'5A6D9A42165B4B5692730A06874DFE10', 2, 'Madeline''s Christmas', 'One year, at Christmas time, as Madeline, her friends and Miss Clavel get ready by making presents for family and friends, decorating the school and baking cakes and cookies, Paris is hit by a huge and very unexpected snowstorm.', '1990-11-22', 23, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
