INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4E5AB462E2184406A0863A5087CD4BC6', X'7C422193B07849D881EFF2B9F94F059D', 35, 'Sir John Feelgood visits', 'Episode #3040', '1992-12-25', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4E5C5169D351455A8EDF84E1EBC7AD7E', X'1A534647384B4C00BB6CA3371AD962EB', 12, 'All Hail Rick', 'It''s a royal affair with the Pawn Stars when Revolutionary War documents signed by King George III reign into the shop. Will the documents be fit for a king, or a royal faux par? Then, Chum feels the need for speed when checking out a pair of Cushman Scooters. Will he drive a hard bargain, or be taken for a ride? And later, after checking out a BB gun in the shop, the guys all take part in a competitive shoot-out. Who will call the shots, and who will miss the mark?', '2015-02-26', 21, '/drHjiVzivKnb4xzcalwEKksR7Hd.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4E634B1599304950A988F26A134AEDD6', X'8BDF0AD3A7984D5AB304C7501EAE6867', 2, 'Hold On To Your Daddies', 'Tamra Barney''s husband, Simon, has quit his job at the Mercedes dealership and is now working on his own business start up....from home. The couple''s McMansion is closing in on this housebound couple, so Tamra goes on a sexy shopping spree to spice things up. Meanwhile, Gretchen Rossi talks her fiancé, Jeff, into going motorcycle shopping at Harley Davidson. Even though the real estate market is in the dumps in Orange County, Jeana Keough still manages to make money by selling off the distressed properties of her friends. Lauri Peterson checks in on her daughter, Ashley, and learns all about the new skincare business that she is trying to launch. Vicki and Donn Gunvalson take time out from their busy lives to have a date night, but an evening of romance and reconnection turns into a bitter sparring match over their marriage. The ladies are unpleasant to new girl Gretchen during a day trip to Beverly Hills and the Sonya Dakar spa. Lauri ducks out early and starts to distance herself from the group.', '2008-12-02', 44, '/5qDPQpg3q6OMZ0eA9952xj2Dqoy.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
