INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4EEB1A0292544D3CBB924039E1600C11', X'4FE93658C46343298E649D523869C2CB', 8, 'Like a Rolling Chum', 'The Pawn Stars have the opportunity to own a piece of classic U.S. sports history - a hockey stick signed by the legendary 1980 Men''s Olympic hockey team. Will the gang score the game winning slap shot at the buzzer or will they lose it all in overtime? Then, a man brings in an original 1970 vinyl record of Bob Dylan''s "Self-Portrait." Will this deal hit the top of the charts and go platinum or will Rick leave it all blowin'' in the wind? And later, Rick gives Chumlee a special assignment that requires him to run around Vegas searching for a needle in a haystack. Will Chumlee put his back into it and come back to the shop prevailing or will he simply wish he’d stayed home that day.', '2010-09-20', 21, '/1IuLaTXbTmffSD1djD2tzNegHLX.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
