INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4F50DDA50CE44121944177CD9A7C8C00', X'432A6ABDDCCA44CC82CEFB39E33B8949', 1, 'Episode 1 (#1131)', 'Episode 1131- The show opens with Mr. Rogers walking in, carrying several pieces of construction paper. Mary Sweenie and her daughter Meghan stop by and invite Mr. Rogers to come see them tomorrow. King Friday feels that babies are getting too much attention and on Prince Tuesday, he tries to limit such attention to one hour a day. Picture Picture shows us how construction paper is made.', '1971-02-15', 29, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
