INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4F5E2AFDEDDB4F9AB51283ACC970FE02', X'8012F05A66A34254885F0A679393F3DD', 12, 'Attack of the Slime Monster (4)', 'The team trys to come up with a conclusion.  Tina and Casey discover the Slime Monster''s weakness, cold.  Just before the discover their plan, He attacks Lenni and the rest of the team!  Luckily, Tina escapes and Jamal and Tina melt the Slime Monster with vegtable oil.', '1995-02-12', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4F62463FCE2A4F0DAA9502114DD261C7', X'01B3A1E3D0E84F2BA56D9D55669AB5F2', 9, 'The Teflon Queen', 'Kody faces off with his sons Gabe and Garrison, and they trade blame over COVID restrictions. Then, Janelle suffers a huge loss as Christmas is approaching. The family hopes they will all test negative and finally be together.', '2022-01-16', NULL, '/h8wdyI47AE6g9iWcYWB5H8yoIaM.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4F68D7E3CA1947288562E913C6D93A7C', X'F07B879456254682AAE1E56966B4C7A8', 6, 'Yellow Belt', 'When Ben teases Jody that girls can’t learn martial arts, she quickly teaches him a lesson.', '1996-01-22', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4F6C64E970FE42BDB6E305B29165DFF2', X'DBD3583FE9B246D1A37E309EB666E233', 13, 'Make It Rain Down in Africa', 'The ladies'' South African vacation continues with the "Talls" and "Smalls" moving beyond Sheree and Marlo''s intense showdown. After blowing off some steam at a Cape Town nightclub, the women travel to the luxurious Shamwari game reserve. On safari, NeNe finds herself caught between the competing attention of Marlo and Cynthia, while Sheree, Phaedra, and Kandi learn about the pharmaceutical benefits of elephant dung. Later, the entire group has an opportunity to visit a South African orphanage, where they are touched by the children and leave with the sense that this trip has been a life-changing experience.', '2012-02-12', 43, '/pVGNudDR6fmvXFpqMrWccIw3bTO.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4F7D5063D81E49C78C6CECC03C02F32C', X'DBD3583FE9B246D1A37E309EB666E233', 9, 'Unlikely Duos', 'Phaedra’s ready to make her family funeral business a reality, but it’s going to take some convincing of Apollo that working with the dead isn’t as creepy as it sounds. Driven to write a hit song in every music genre, Kandi goes country and travels to Nashville to work with country music star Jo Dee Messina. Kim struggles with her oldest daughter Brielle, who begins acting up as she adjusts to life after Kim’s new baby. Seeking to put rumors to rest about her alleged tryst with a fellow Atlanta socialite’s boyfriend, NeNe meets with Marlo Hampton, and learns a lot more about her than she had expected.', '2012-01-08', 43, '/vXkRYqVFdYFDcmMwCqxjYcgmqx5.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4F7FB22893EB4E219DCA71119C71D918', X'151E88A195764BD1B84AC4D64C1C9FE8', 19, 'We Need To Talk About Kathy', 'When Kathy skips the flight home from Aspen, whispers surface about a meltdown directed at Kyle that took place the night before. Back in Beverly Hills, Erika tells Dorit she’s hurt that Garcelle talked behind her back and vows to say it to her face. Sutton and the others don flapper dresses for Crystal’s swank Roaring 20s birthday party. However, when Kathy arrives as if nothing is amiss, Lisa heads for the exit, and Erika decides to share what she heard.', '2022-09-21', NULL, '/824u09dMuTsu3iWltNSbadiyETQ.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4F83C3AE5CA54F969802C776A96D7361', X'CB8A0322BE77485BB339BDD572BCA349', 9, 'The Chips Are Down', 'D.W. eats a big green potato chip and to get her off his back Arthur tells her that it''s fatal and she could die. So D.W. spends this day as her last day until she finds out the truth.', '1998-11-20', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
