INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4F979F7D6F4A446188CA865C263B87FD', X'97A3D1F5A8F147CD81222E74A092836D', 15, 'Lost in Brooklyn (3)', 'Malenga finds one of the paintings and realizes that Safria is in New York. Jamal runs into his best friend Rob. Rob arrives at Lenni''s house but he has some terrible news. His mom just got a new job in Australia and he just returned to get ready to go. Malenga contacts the team. Malenga and Tina arrive at the hotel. Tina prays for Safria to be all right.', '1993-12-12', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4F97C5C6ED1E4A10941454777BD308E1', X'DB958AF49A9A4533AF9BF0FF590D1DD9', 4, 'Housewarming History Lesson', 'After the guys night blowout, the divide between Teresa, Joe and Melissa is at a standstill; Frankie hits Dolores with hard questions about their shifting family dynamic; Rachel and Jen Fessler spill the tea on Jennifer Aydin.', '2023-02-28', 44, '/oRj8WDhI9QAHdq0kQur3jGIVxtl.jpg', '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
