INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'4FFBFBA08621474BB0BD4B3DAF18955A', X'3FC7C152E4F6426AA89936EC454C4403', 17, 'Emmy''s Dream House', 'A Purple Goo Cloud is going to rain all over Dragon Land, so everyone builds a tree house to shelter. However, Emmy becomes bossy and wants everything to be done her own way, until she learns how to share with her friends and give them what they want.', '1999-09-23', 30, '/vGIBEiVVdLRPVe8qS81E5ATEqsR.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
