INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'50001F44FE9F41BBBC0810D8A5C29824', X'D6092173D23B4449BAFFE0E16FE56C9A', 3, 'Ten Ten, Twenty Twenty', 'Porsha returns home from her second arrest in Kentucky and also reveals that she and Dennis have called it quits. Kenya offers Cynthia marital advice and juggles her fast track friendship with LaToya. Drew and Ralph agree to go to marriage counseling, while Cynthia and Mike disagree over when to host their dream wedding.', '2020-12-20', 43, '/gzCOccENsLDxyJXLK3HdVV54QQT.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5006198C61A44890AF099070E61AD69D', X'5C4E51C6E20746AD875C72988EB1E13E', 1, 'Evel Genius', 'Batter up with the Pawn Stars when an autographed photo of Babe Ruth slides into the shop. Will Rick go into extra innings for this rare piece of baseball memorabilia or will a tough negotiation cause him to swing and miss? Then, the guys take a peek at a collection of 400 antique prosthetic glass eyeballs. Made from hand-blown glass, will they see eye-to-eye on this deal or will this collection have to stare down a new buyer? And later, Corey and Chumlee are presented with a classic 1970''s Evel Knievel pinball machine. Broken and beat up, will Corey rev up a death-defying leap to restore this cool rider collectable or will one look have him say "Game Over"?', '2011-04-04', 21, '/ccIbTcybZYh2QedX6EHiJ8DGNAE.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
