INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'501CE7498858413BBCEA6573AE950FC3', X'4FE93658C46343298E649D523869C2CB', 13, 'Never Surrender', 'The Pawn Stars are presented with a letter signed by one of the 20th century''s greatest leaders, Winston Churchill. Will the guys stand up and fight for a deal or will unverified signature force them to surrender? Then, Rick and the Old Man meet a guy hoping to sell a Holy Relic from the first American Saint Elizabeth Seton. Will this precious religious item bring the guys good fortune or will the Old Man remain the only relic in the shop? And later, a man brings in a gas fueled remote controlled toy Hummer with some mechanical problems. Will they take a chance at rewiring this RC truck to make a buck or will this deal run out of batteries?', '2010-11-01', 21, '/fELnnVu0zUVB5ppG1cyZsCZhJrJ.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
