INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'506BBCF8ABAA40F098376C7FA3536F2B', X'095258D0D8DB40968AC76A42CD4CBDCF', 3, 'Boober And The Glob', 'It''s Joke Day in Fraggle Rock, and Boober''s trying to get out before his friends find him and make him participate in the holiday he hates. But before he leaves, a huge purplish-pink glob rolls into the Great Hall. Boober ends up meeting Cotterpin Doozer as well, and the Doozers are on their way to start building near the Blob. However, the Glob starts to eat the Doozers, one by one, and soon enough, Cotterpin''s inside the Glob too. Even though a part of Boober really just wants to run away and pretend it isn''t happening, he''s forced into action and must find a way to set the Doozers free.', '1985-01-14', 24, '/wOzVOWhfv90r9XphcVp4Fyocx9m.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
