INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'506FCE886F9E4FAF99EDB678C291A942', X'208E80DE61E34A2F857FC667FFC29134', 23, 'Carol Channing', 'Miss Piggy buys a cute new pair of shoes, but they''re too small, and she can''t walk in them. She wants to take them back, but Kermit compliments them, so she has to keep wearing them. She complains to Carol, who says she should have them stretched, and gives them to the gigantic Timmy Monster, who runs around the block in them.', '1980-03-28', 26, '/uEisEgcu4UDaZw5u7ak6PJNFMdX.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
