INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'508FB0E6C47D4EB990FD6F52F5882B0A', X'CA19F89515144988A70995E84EAB7CEE', 17, 'Atomic Pawn', 'Chum goes for a hole-in-one when a signed Jack Nicklaus golf glove swings into the shop. Meanwhile, Corey targets a G.I. Joe Tomahawk helicopter toy. Will he get to be a real American hero, or will this deal go AWOL? Next, an antique Fender amp rocks Chum''s world. Will the price be music to his ear, or off key? And later, Rick and Spencer go on a picking adventure in Huntington Beach, California. When they find a treasure trove of military items, does Rick have enough ammunition to close the deal?', '2021-05-10', 42, '/yHVggrETWBHduPyT0ZdjbEux7L0.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
