INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5097F247503B47448D333750275F6B5D', X'D9973960273B4A92A7DA62EFE8860D09', 13, 'Chilly Reception', 'Heather works hard to finish her new Beauty Lab location for her launch party, but worries that she hasn’t connected with Jen since Vegas. Mary goes to her place of peace, her church choir, while Lisa spends time with her family doing what she truly loves – making business plans. Meredith and Seth realize that their marriage is a hot topic for their friends while Sharrieff surprises Jen with a date night she won’t forget. And at the At theBeauty Lab Launch Party, Jen tries to make amends with her friends but it doesn’t go as well as she planned.', '2021-02-03', 63, '/qPbM1x4fDbHkCIvlBYLMdamrbJJ.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
