INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'50996297AA554AB38D3D3A35583A2F6F', X'465E5A6D74B64FFBB54F51103F8329B3', 5, 'Stormy Waters', 'A fabulous yacht day turns into a boat ride from hell; Cynthia checks the ladies, and Ramona''s choice words upset Kenya; Teresa hopes her home cooking can bring everyone together.', '2021-11-25', 48, '/hS5y4r3I4SnFaGTAoG5gudVJwCp.jpg', '2026-04-03T16:34:40Z', '2026-04-03T16:34:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'509CB9FBF8B74278AFBCDB6E50C7B721', X'4A8E3DB080684FF3942F91F45F665F20', 13, 'Pandora''s Box', 'After reading the story ""Pandora''s Box"", Lionel and Leona come across a similar-looking box, themselves, and wonder if they should open it or not. Apparently ignoring the moral of the story, they open it, and unleash a terrible thing to all the library patrons: Hiccups!', '2000-04-19', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
