INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'512E18817B7044B9BD8676DB190DC283', X'4D2CAC0F38FD438B8AFAACF43952E535', 130, 'Episode 130', 'For younger viewers. Introduced by Christopher Trace and Leila Williams. April in Italy: Second week. You see some old Italian customs, learn how Italian designers have influenced the world of motor cars, and hear some more of a famous story.', '1961-04-10', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5131EEA6ED2148B19135147E889C019B', X'23C93536610C41C5AC6BA6B243423258', 2, 'Double Trouble', 'The fallout from Karen''s "hattitude" birthday continues as a few of the ladies try to reel in the drama. Gizelle and Wendy meet to hash out their issues, Keiarna checks-in on Karen and Stacey opens up to Ashley. Gizelle and Ashley''s GnA event is challenged by the Grande Dame, who forces the ladies to make a difficult choice.', '2024-10-13', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5137C4E584874773AAC74B9F2328140F', X'5A771F52FE964EA2B567A8DDE899059E', 18, 'The Happiest Place to Pawn', 'Rick and Corey are inspired by an anti-war speech signed by Dr. Martin Luther King. Will they "sit in" or sit this one out? A remote-controlled miniature version of a boat from Disney''s Jungle Cruise ride has Rick and Chum navigating a tough deal. Rick pins his hopes on a German "Blue Max" medal from WWI, but can he honor the seller''s high asking price? Later, in an interesting development, an antique Nikon camera from the 1950s makes a flashy appearance. Will Chum snap it up or shutter himself off?', '2018-02-05', 21, '/vWnd2ILKNWnA11hmOayLyksLjEu.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
