INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'513D578E0347465FBC36B52D151B8378', X'C7994637B7C742C7AAEE1BFF4144FE23', 7, 'Dazed and Accused', 'As the weed dinner continues, Kyle and Sutton’s friendship seems to go up in smoke. Garcelle and Crystal struggle to make sense of Denise’s showdown with Erika. Dorit schools PK on their children’s future. Feeling let down by her friends, Kyle turns to sister Kim for support and advice about her family.', '2023-12-06', NULL, '/a0TN2tm1h3STJ4ExHrFI9CEBC7M.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'51418F2EB7464CAA8C3E6E4BABC82A95', X'A4843A51AEEF427C902C7FB3BD670CD4', 24, 'Lost Thing', 'Bear hears a shout coming from the kitchen and finds Ojo begging Tutter to let her peek inside his mousehole. When he won''t let her, saying that she''s too big, she cries. It turns out that she''s lost her favorite toy, Snowbear. Not wanting to see her cry, Tutter agrees to help her find it --- mice are great at finding things. Pip and Pop soon join the hunt, but Bear''s bedroom gets rather messed up in the process. Ojo begins to despair, but Bear helps ro raise her spirits by encouraging her to keep up the hunt. Treelo then comes up with a great idea that could help her to find Snowbear. 
