INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5153531F903A4DB1A85A63DAB79B9A90', X'42684FCA0BC74F4CBF7DF41FD288A764', 15, 'Postman Pat and the Flying Saucers', 'The children are out hunting for UFOs, whilst Ted''s new invention – the Washer-Sorter machine – is playing up. Later, a strange bubble creature appears in the station café...', '2004-09-29', 15, '/vHvmSvrJB4kscGVAgkwRU0cGx8L.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
