INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'51639978F68A42B4A8E3209DCF1E1CF0', X'06030129FF2D4490B66C9F41BBE7AABD', 14, 'Shopping', 'John sets out to the shops to buy some food and drink for a picnic. Rosie and Jim are hungry and want to have a picnic too, so they add their own items to John''s shopping list without him knowing. Bearing in mind that John doesn''t even like the items that Rosie and Jim added, they''re afraid that John is going to be upset. However, John isn''t overly upset after all, as he sees a family having a barbecue and gives them Rosie and Jim''s items.', '1990-12-03', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'516A653834AD42E9B2E363C8414D39C0', X'EFDF1E4F84764382A9D72B9DA4188BE0', 17, 'Brave and Strong', 'Rogers'' friend Brad Brewer, a knitter and puppeteer, talks of the puppets and puppet shows he has performed in. In the Neighborhood of Make-Believe, Elsie Jean Platypus explains that the cereal stopped falling on the Platypus Mound when she wasn''t afraid of it. But Daniel is afraid of the cereal snowfall on his Clock. And Then Maggie Stewart Shows A Videotape On How People Make Grits', '1996-08-02', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
