INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5187369A1D3D429286101F826F29C0D3', X'E291DF42D44F49E5BF812DF32EE4A30F', 18, 'Bats Are People Too', 'As the viewer arrives, Bear decides to try something a little different --- he wants the viewer to sniff him! It turns out that Bear''s idea may have been prophetic because some very different things are happening around the area of the Big Blue House. Pip and Pop were out playing by the Otter Pond when they found something they''ve never seen before --- something with wings hanging upside-down from a tree. Bear explains to them that it''s a bat. He tries to tell them all about it, but they disappear in a flash. Bear returns to the Big Blue House, where Ojo and Tutter both express the same sentiment. They''re scared of the bat and don''t want to have anything to do with it. Things only get worse when they all sit down and talk about it. Bear, however, meets the bat, whose name is Benny, and asks everyone else to meet it too. They reluctantly agree and find that not only is he not like what they expected --- Treelo is already his friend!', '1999-09-20', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
