INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'519701AE141443769EB6603447031E6B', X'AE8F64D94B834147A44CBFE720381F8E', 25, 'Jacks Grows His Own Beanstalk', 'Jack from Jack and the Beanstalk comes to Sesame Street and tells Leela and Telly he has a problem. He only has a cow, but he needs a beanstalk! He knows he’s supposed to trade the cow for something but doesn’t know what. Leela gives him a clue—he needs to find something that grows in the ground.
