INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'526F7499710345418906F714E5A479D2', X'4FE93658C46343298E649D523869C2CB', 3, 'Double Trouble', 'The Pawn Stars reach for the sky when a man walks in with a custom set of 19th century double barrel firearms - including a multiple caliber dual shotgun/rifle and a hand carved pistol. Will they load up and take aim at a deal or will a pair of misfires send the seller packing? Then, Rick and Chumlee are presented with an extremely rare unopened bottle of 1921 Dom Perignon Champagne. From the first year it was produced, will Rick shake up a deal and toast his good fortune or will everything just fizzle out? And later, a man comes in with a collection of autographed talking Freddy Krueger dolls from the horror classic "A Nightmare on Elm Street." Will the Old Man dream up a killer price for this trash talker or will the negotiations be a nightmare on Las Vegas Boulevard?', '2010-09-06', 21, '/aDyodDXwCPZVLhd6hQXhwpvEonx.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
