INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5297418AEA3B4F9CBEAC28922D3CDA0D', X'27A5A980EC0D4637B5BADF8324A6405A', 10, 'Thanksgiving III', 'Frankie''s parents, Pat and Tag, invite the Hecks to spend a few days at their house to celebrate Thanksgiving together. But the festivities begin to fall apart quickly when Frankie''s sister, Janet, and her family also join in, and soon the siblings are at each other''s throats over their widely differing parenting techniques. Meanwhile, Mike tries to offer some advice to Axl on how to pick up girls when he witnesses his son trying to impress a pretty mini-mart cashier - and fails miserably; Brick attempts to prove his innocence when he is accused by Janet of damaging her daughter''s expensive toy; and Sue is stoked when Frankie, Pat and Janet invite her to take part in their gossip sessions.', '2011-11-23', 22, '/bqD8PLbqTUCBu1ucZaU1lbq1n6Z.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
