INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'52A5668484E24B9999863E2234FD9D69', X'C9ADC698BE924DD794ADD8F6759361CA', 1, 'Is Santa Claus Real?', 'Rogers gives a Santa Claus costume to Chef Brockett. Both Betty Aberlin and François Clemmons talk of how as children, they used to be afraid of Santa Claus. Santa Claus, himself, also comes to the neighborhood. This is the first series episode to use the closing song "It''s Such a Good Feeling". This continued as the closing song until the end of the series in 2001.', '1973-02-19', 30, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
