INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'52BECF1321D64A0B88C77B880532810C', X'9193E795DA7C40ECB68FF63AA7D5174F', 174, 'Histories & Lore: The Blackfyres', 'Varys explains the backstory of House Blackfyre.', '2019-12-03', 6, '/hONNT8vXmERepBV0b6iv6votE1s.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'52C76CA23CFE4DD4AD9BC9153A9A1D85', X'1D713CA64E174F84949C8CFD98514127', 41, 'Clowning Around', 'Saddle up with the Pawn Stars when a Gene Autry guitar struts into the shop. Will Corey and Chum pony up the money for the "Singing Cowboy" item, or will the deal be out of tune? Then, Rick starts clowning around when a Red Skelton portrait comes in. Will Rick be laughing all the way to the bank, or will he suspect some funny business? And later, when Chum decides to sell his shoe collection in the shop, Rick has other ideas. Will Chum''s business deal get up and running or will it cause a big stink?', '2014-12-18', 21, '/4g9TK1dx0QOtD46r3azIDAQvXE7.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
