INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'52F6E178989A42D0A0697BF69468CBA5', X'227B84290DFD47E4B874C37DA20C403F', 19, 'Hot Air Buffoon', 'The pawn shop heats up after Corey spends big bucks buying a huge 12 passenger hot air balloon - and at the same time breaking one of Rick''s golden rules. Will Corey rise to the occasion and patch up the deal or will his dicey decision deflate the shop''s profits? Then, when a man tries to sell his classic 1960 Gibson Les Paul guitar, Rick has some concerns: will the deal rock on or rock on out? And later, a man brings in a bottle of medicinal whiskey from Prohibition and the Old Man is forced to decide: Buy it, deny it, or drink it?', '2009-12-14', 21, '/cGdMDJHNYwLc0GTinpMAgk73ZP2.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'52FDCAB6A51F4F42AE32BD26E25A213A', X'8012F05A66A34254885F0A679393F3DD', 7, 'Four Days of the Cockatoo (3)', 'Hector and Lenni are able to warn Alex and Gaby about the smugglers the retreat back to Lenni''s apartment. Jamal and Tina learn that Palm Cockatoos are endangered species,so the team tries to contact the police but it doesn''t work so they contact the fish and wild life service, an animal rights society. They tell Mr. Fernandez that they won''t give the bird to anyone except the fish and wild life people. Hawke, disguised as a pregnant woman overhears them and has a new idea. Just then two agents from the wild life society arrive at the bodega but Gaby reads a message from Ghostwriter and realizes that they are imposters, but when she goes to save Calypso the van takes off with her inside.', '1994-11-13', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'52FE05C043914C768D95E2DF424BA13C', X'68138DE20900460AB58E480688F1E081', 10, 'It''s All In Your Head', 'Ojo gets the idea to put on some Olympics games out by the pond. Everyone''s excited, especially Tutter, who predicts that he¡¦s going to win every event. He doesn''t, he realizes that you don''t have to be good at everything to be a winner, but when the limbo competition rolls around K it turns out nobody can get lover than a mouse!', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'53006EE4FF824BDCBE671CFD699189C8', X'D405F9734C7E4CB6B7C0D09A884C9B35', 2, 'March Madness', 'The ladies participate in a marriage-equality march over the Brooklyn Bridge, yet there''s drama with these mamas when tension heats up between Sonja and Alex. Elsewhere, an offensive remark delivered by Ramona spreads back to Cindy.', '2011-04-14', 42, '/PNnhzGNOfUcee5RmuA0FooqRC8.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
