INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5311FCE895D14DC39AE964A95577B922', X'23C93536610C41C5AC6BA6B243423258', 4, 'Bunking Beds and Butting Heads', 'The ladies arrive in Lake Norman, N.C., to turn up, but some aren''t ready for the heat that''s unleashed. Jacqueline''s relationship with Mia is questioned. Stacey and Keiarna both have bones to pick with Ashley. Mia reveals a long-held alleged secret about Karen, leaving everyone shocked.', '2024-10-27', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
