INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5316A66AF25B41FA84817F16C1C71E97', X'B1D55597D9D24EEEAB9546DBB163291A', 26, 'Pingu and Pinga Play Circus', 'Pingu, Pinga and Robby put up signs announcing a circus and lots of penguins start to go see the circus, and during the performance, Pingu plays the drum, Pinga plays the trumpet and Robby plays the accordion, Robby does roly-polies, Pinga juggles balls (which failed when Robby laughed when she dropped them, though she threw one at Robby''s hat flattening it.), Pinga and Robby do a "lion-tamer''s act" and Robby does dog acts. Pingu does a bunch of dances and actions during Robby''s accordion performance and he lifts a big faux dumbbell, drops it (to make it look heavy) and Pinga takes it away with no effort at all. In the next performance, Pingu and Pinga jump on top of a board and Pingu lands in a bucket of blue paint which splatters all over Pingu and Robby, Pinga arrives and scolds Pingu to be more careful and jeers at him by laughing. After this, Pingu decides to spit blue paint onto Pinga, covering her in paint too.', '1990-10-27', 5, '/onwjMweFgnikJBOO8JN33FkhrxI.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
