INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5375E85A57BD4F95A4C9C0DB01B894F0', X'70C8CB4624944DD498F66BFB9B3FAF73', 23, 'Top Secret', 'The Pawn Stars look to purchase top-secret maps and battle plans for Iwo Jima. Will the gang storm the beach for this strategic piece of World War II history or will they be out-gunned and forced to retreat? Then the Old Man and Chumlee look to buy a 1967 Ford F-100 truck. Will they fire up all cylinders and hit the deal full throttle or will it run out of gas? And later, Corey and Chumlee have a chance to buy an 1860''s ore cart from the mines of Goldfield, Nevada. Will they strike it rich or fall off the tracks?', '2010-06-07', 21, '/ynJgGqwAiD1FapBnjUtUaAgDjm.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
