INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'537DE790E90049399A78C772F20B80FA', X'AE373811CD7F4E4CBF5F6E5EEF167F8D', 6, 'The Great American Melting Pot', 'A look at the Democratic recipe that built America.', '1976-04-17', 3, '/lJu2g8gtY1bpRIf2OF5TXCmdkEI.jpg', '2026-04-03T17:13:56Z', '2026-04-03T17:13:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'538299BB54964C8CB527EE6B88E0442A', X'F4C403079B5E4263A4E0DFA138131E7F', 21, 'Learning About Letters', 'Big Bird and Telly Monster lead young viewers through the alphabet, letter by letter, in a magical and imaginative half-hour discovery of letters and their sounds. The perfect tape for young Sesame Street fans who are just beginning to get the hang of what letters are all about, it includes short skits, songs, and other bits of business--some original, some culled from the Sesame Street show--featuring a variety of Muppet characters as well as the human residents of that famously educational thoroughfare.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
