INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5395A996A72941929398E7F77F042131', X'F07B879456254682AAE1E56966B4C7A8', 5, 'Helping Hands', 'Kiki decides to prune a big tree by herself and becomes exasperated when she discovers that the job is too much for her to do alone. She learns that it’s okay to ask for help when you need it. Nuzzle obtains a motorcycle and Sizzle so badly wants to try it herself. Julie, Ben, and Leon do not appear in this episode.', '1996-01-19', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
