INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5396EA28682F41DF9BFBB73550DF8DF3', X'70C8CB4624944DD498F66BFB9B3FAF73', 7, 'Pinball Wizards', 'The Pawn Stars have an opportunity to buy a classic 1973 pinball machine in need of some serious repair. Will they rack up a high score and make the deal? Then Corey and Chum meet a guy interested in selling his personal transporter - better known as a Segway. Will Corey shell out a nice stack of cash for a new ride? And later, a woman hopes to sell Rick a 1924 St. Gaudens Double Eagle gold coin - often called the most beautiful coin ever produced by the U.S. Mint. The only question is: is it real?', '2010-02-08', 21, '/p6Llu2U8wRexZg1v3LPisEFpen2.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
