INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'53A1EC56E2394DADAF774BC6DF5C02B2', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 21, 'A noisy day in the library', 'Luis gives Telly Monster a plan on how to get Oscar the Grouch to help show one of today''s letters - R. Telly loudly begins his talk to get Oscar''s attention and asks Oscar not to help at all. The reverse psychology works.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'53A3FA1E03EE4D5C9F0E9F3E43B1F4FA', X'5D57283D079C4F6693C833A2FEEADA89', 23, 'Orlando', 'Sue looks forward to the trip to Walt Disney World; Brick begs his parents to take him to meet his online girlfriend; Axl waits to learn his final grades.', '2014-05-21', 22, '/5Ag4rfXfwi88C57i4drkqyIRepm.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'53ABD96019674F868DEB8F50CBC4F1B8', X'70D9E39768134785887D27D034928BAE', 24, 'Pingu Makes a Discovery', 'Pingu and Robby are sledging when they come across what appears to be the tail of a large fish sticking out of the ice, and anticipate a good meal. Pingu tries to pull it out of the ice, and gets annoyed when it won’t budge. Eventually they dig it out, still encased in ice, and take it home. Pingu stokes up the fire in the stove to melt the ice on their fish, while Robby gets the frying pan. The frying pan is put on top of the stove to warm up, and together Pingu and Robby lay the table in anticipation of a feast. A little while later all the ice has melted, and then they realise that what they’ve found is not a fish and, disappointingly, it’s not edible. Grandfather then comes to visit, and decides to call the curator of the museum to come and take a look at it. It turns out to be the missing figurehead of a boat on display at the museum, and the curator is very pleased that they’ve found it. Pingu, Robby and Grandfather accompany the curator when he takes the figurehead back to the museum, where a reception party is waiting, and Pingu and Robby have their photograph taken.', '1996-08-22', 5, '/lzdDVhqrvlF2oLmiBPkt7ALEaMN.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
