INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'53EEBD4F723742C0A7C2CE104FAB6836', X'42E591E22A884434AE9F3D4B1D685613', 29, 'No Shoes, No Shirt, No Service', 'Bond with the Pawn Stars when they spy a 1961 Fender Stratocaster used on the 007 theme song. Brought in by famed guitarist Vic Flick, will the guys let him lead the negotiation? Then, Corey and Chumlee check out a fully customized 2006 Dodge Magnum. Complete with suicide doors, is this a deal or dead weight? And later, Chumlee designs a new uniform shirt for shop employees. Will he have the skills to please a tough crowd?', '2013-10-24', 21, '/fZ2hAlJaF3Ly1D804eMmVVaZKFG.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
