INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'53F4285F9BD5499493C8AF91C5BE9281', X'D0B78F22678E4E469D61AAC40BA206B8', 6, 'Fifty Shades of Shade', 'Erika pushes Dorit to take her sex appeal to the next level during a magazine photo shoot. Denise lets it all hang out at dinner with Lisa Vanderpump and Kyle, and reveals some big details -- literally -- about Aaron. Lisa Rinna helps Camille plan her 50th birthday bash, but tensions run high at the celebration when Teddi and Lisa Vanderpump go head to head.', '2019-03-19', 43, '/ArcA2aIKW2prjrbt7f1vyatJWea.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
