INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'53FE2BBD9FFF4EE7AE27AC7DC21AF7F5', X'852A07B0F228419791477AEED79390BF', 13, 'Ho Ho Holidays', 'The morning after Ramona and Sonja''s birthday bash, LuAnn and Ramona learn about Sonja''s late-night escapades with one of the party guests. Leah reconnects with her siblings for the first time since their grandmother''s funeral.', '2021-08-03', 60, '/4fyN18QUlaXZF0GPTZRGDR71qYC.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5400FAE301AC441CAFF838BCA3BE9C7B', X'C6D5CF79F2B040AFAD1291AA4F1B1D21', 2, 'Put a Cork in It', 'When a seller comes in with a poster by Henri de Toulouse-Lautrec, will it make an impression on Rick, or will he bid adieu? Meanwhile, Chum unboxes some 1912 Yale baseball uniforms. Is it a home run, or a strike out? Then, Rick takes a look at a ukulele from 1919. Is this deal music to his ears, or is the seller just stringing him along? And later, Chum, Rick and Jake head to the track to test out a restored Track Rabbit go-kart. Will it run smoothly, or be a bumpy ride?', '2022-04-30', 42, '/2C7q8aD3AzBjxIGNq6NTjWj2T3Q.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'54025314A8BE41E68AA8BD090A591F36', X'D920EBAEF00A4E25ABFE40492C74DED6', 21, 'Slice and Dice', 'When a seller brings in an antique key gun, can the Pawn Stars unlock the mystery behind it? Meanwhile, Rick strikes gold…records, when a Pink Floyd album spins into the shop. Next, a rare 1600s blade slices its way into the hands of the guys. Can Corey’s negotiation cut through? Then, Chum and Corey give peace a chance in a vintage bus. Will they ride off into the sunset, or will the wheels fall off this deal? Finally, can Rick score a Jackie Robinson card collection that’s the best thing since sliced bread?', '2020-06-01', 42, '/eNACDEqwUpHcarWASx3ILr8hJzw.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
