INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5466850F9E584C83A11A904DA0E5FF18', X'5DB3FF78E43948E18F67988ECBF85D17', 16, 'Daggers and Diamonds', 'Dogtanian and Pip are returning to Paris but decide to stop enjoy the view and relax before returning. After Pip has made some remarks about Dogtanian''s feelings about Juliette Dogtanian chases him and they run into a beautiful lady. After asking about the Dagger Dogtanian received from the Duke of Buckingham Dogtanian escorts her down to the river. "Little do Pip and Dogtanian realise that this beautiful and seductive female is none other than Milady, Cardinal Richelieu''s cunning and ruthless spy."', '1982-01-15', 24, '/xM0MB4s2dqlCZuslAHR2Z7OzPRN.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
