INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'54858E987D9A48F3B850672D6ACF5075', X'97A3D1F5A8F147CD81222E74A092836D', 24, 'Don''t Stop the Music (4)', 'Lenni''s music video is finished.  Also, Jamal gets a letter informed that he has been accepted in the high school he wanted to get into. Sonia takes it to MTV but on the way there she is mugged and the tape is stolen. Lenni sends Ghostwriter to where the tape might be. Lenni realizes that David is the saboteur  and he and Marlon are in cahoots. The team sends David a phony letter from Marlon telling him to meet at an empty parking lot. David is arrested and the tape is saved. At the party Lenni''s music video is played.', '1994-02-13', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
