INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'54F59FBB93E947FF9621169B161EA7BF', X'E48599F866FF4C0F927465B9AE1CDA9E', 12, 'Episode 12', 'Brunei''s Birthday Bonanza  A fly-past of state helicopters and a procession of stilt walkers and jugglers marked the 30th birthday of the Sultan, His Majesty Sultan Haji Hassanal Bolkiah Mu''izzaddin Waddaulah ibni Al-Marhum Sultan Haji Omar ''Ali Saifuddien Sa''adul Khairi Waddien. JOHN, PETER and LESLEY join the crowds during the celebrations that lasted 40 days and 40 nights.', '1976-10-21', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'54FCFA71E7A54A89AEC235D2843CC426', X'E93F04C273444B93ABBA8BA1B2F8EB35', 71, 'Episode 606', '', NULL, NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'54FE692D381F45ECA36D30FC445890EF', X'ECB64EF34F8045A7B4A9C04434B02E35', 34, 'Ponies and Phonies', 'Saddle up with the Pawn Stars when a customer brings in a bible believed to have been carried by Pony Express riders. Can Rick and Corey rope in this cowboy classic or will it ride off into the sunset? Then, Corey travels to a galaxy far, far away when a R2D2 Pepsi machine rolls into the shop. Will the force be with him or will he let it go to the dark side? And later, Lili''s internship is up and the guys need to review her performance. Will her year at the shop go down as a success?', '2014-04-24', 21, '/7eKnm5vjal3wgpvh1qI8kX62wE9.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
