INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'55034B8CEB46473C9E3490060FBEE98E', X'FED71EEA5D41479CB12ABEB733409C5C', 13, 'Waiting for the Present', 'Rosita needs to learn how to control herself and wait to open her present from Elmo.', '2014-12-16', NULL, '/4VxhZWADi0mh0E7BB1XBaHErbjZ.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5504990B648D43B7A8133CF2A1BE25B1', X'42E591E22A884434AE9F3D4B1D685613', 43, 'Another Christmas Story', 'Get into the Holiday spirit with the Pawn Stars as the guys compete in a Christmas card competition. With a giant prize on the line, how far will they go for the win? Then, an original puppet from Jim Henson''s Creature Shop comes in the shop. Will Rick pulls some strings in order to make a deal? And later, a guy steams in with a Lionel train set from the 1920''s. Will Corey and Chumlee keep this negotiation on track, or have they bitten off more than they can choo-choo?', '2013-12-19', 21, '/ubEmn4QXendtXifO2WTu3Y9elAR.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
