INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'550A3AE2B46249AEA153804889D32FB1', X'196E5A10AC254D588416575D3A71FCEF', 2, 'Zigging and Zagging', 'Spencer drops into the shop with some tasty new finds, but will Rick bite? Then, Chum and Rick disappear from the shop to meet up with a magician selling a zig zag box. Can they conjure up an offer? Meanwhile, Corey finds himself flustered over a pricey gold necklace made of ancient coins. And later, Chum tries to script the perfect deal for a collection of Hollywood items.', '2024-07-17', 42, '/16vLYHh2zI43ruL5DjsA4J2lXUO.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'550BDB8F3A134EF68958D03CB5B747B1', X'871570B4BF2F4BA1994065FB932CB009', 14, 'Peaches Of The Caribbean', 'Kenya confronts Cynthia; Peter introduces the group to his family in Jamaica; NeNe plays peacemaker; Kenya''s new beau, Matt, clashes with Peter; Kenya''s cold behaviour threatens the commercial shoot; Kim is taken aback by gossip about her husband.', '2016-02-14', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'550E828717024B3F890A79F1B9CF03DD', X'227B84290DFD47E4B874C37DA20C403F', 13, 'Peaches & Pinups', 'Corey has a chance to buy a wooden crossbow that hasn''t been fired in almost 40 years - will it hold together and hit its mark or splinter, crack and fracture the deal? Meanwhile Rick blushes when a woman tries to sell her husband''s Playboy collection. Will he "read the articles" and buy the lot or pass on Hef''s ladies? Finally, the Pawn Stars try to sell one of their most prized items, an Ormolu clock, aka "The Death Clock."', '2009-09-20', 21, '/qNFli9PnoJlzWiTSXNi9yqnRR7d.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
