INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'556B99164CB4497F9F20E10E6F19150D', X'C9ADC698BE924DD794ADD8F6759361CA', 3, 'Episode 3', 'Rogers pretends to be a bird at François Clemmons'' studio. In the Neighborhood of Make-Believe, King Friday makes another bad rule, that nobody can have bare hands. Lady Elaine doesn''t take the rule seriously until a cold breeze blows by.', '1973-02-21', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
