INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'55B24956F48B4F8883A387FDC204107D', X'ECDEFD77A7AC4344BEA1FB1DF2FD0AC9', 6, 'Doing Time', 'The Postman is distraught when his van runs away through time, as it may lead to him losing his job. Bernard soon helps to retrieve it, however - but in the process, he has a terrifying vision of the future. Is his destiny as dark as it appears?', '2001-12-03', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
