INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'55F6A49D47FD4FB4B7AECBCB5621FD4C', X'B1D55597D9D24EEEAB9546DBB163291A', 6, 'Pingu Is Jealous', 'Pingu, Pinga and mum are spending the day inside. Pingu is building towers with blocks, but to his dismay they keep falling down. Despite mother''s efforts, Pinga does not want to go to bed - until mother rocks her to sleep. Pingu goes to his mum for help with his blocks, but she is too busy knitting clothing for Pinga. Pingu looks at Pinga, who notices that she is in bed. She starts to cry and is comforted and given attention by mother, who continues to apparently ignore Pingu. Pingu desperately tries to get attention by behaving like a baby, kicking a chamberpot around, and pretending to be a ghost, but he gives up and hides in the toy box. Mother soon puts Pinga back in bed, which Pinga still doesn''t want to do. Realising that Pingu feels neglected, mother apologizes and hugs him, and he goes to sleep with Pinga.', '1987-07-02', 5, '/8OmTK4L6FpPhPeij97qCVvMK6Tn.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'55F6B300AC2648DDB4CB30F46D9A3C8A', X'787DFA0BC8274DADA82D0548A6534D88', 20, 'Reunion (1)', 'The reunion kicks off with the Housewives gathering on the couch to rehash the past year. Meghan makes her mark on her first reunion by clashing with Vicki over her step-mom comments and demonstrating what "Judgey Eyes" really looks like. Tamra reveals the heartbreaking family drama she has been keeping secret for the past year. Plus, a Housewife from the past speaks her mind about Tamra''s religious transformation and Vicki shares hilarious memories of her late mother.', '2015-10-19', 44, '/xLidFM5zPCKklvAz47VTI4PpSNX.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
