INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'56070FB3E43C4F34979C170ACB92B74C', X'63F9BF6D39B344F4B885A56807277A80', 16, 'The Fantastic Miss Piggy Show', 'The Fantastic Miss Piggy Show is a one-hour television special starring the glamorous Miss Piggy, which aired on ABC on September 17, 1982. Miss Piggy hosts her own variety show, with special guests John Ritter, George Hamilton, and Andy Kaufman (as "Tony Clifton").  Under the direction of Kermit the Frog, the Muppets work in the studio control room and, amidst chaos, manage to keep the show on the air. Throughout the show, a romantic triangle develops among Miss Piggy, Ritter (who is smitten with the pig) and Hamilton (who is deeply uncomfortable with the star''s romantic inclinations).', '1982-09-17', 26, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
