INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'563BA59FA68D48B79F104FD8FC0CA8BE', X'F4C403079B5E4263A4E0DFA138131E7F', 103, 'Elmo''s World: Dancing, Music and Books!', 'Come look at the world through the eyes of everyone''s favorite 3-year-old! Join Elmo in three self-contained segments as he explores his special world through dancing, music, and books. Each segment gives children a chance to experience their world on the TV screen and offers adults the opportunity to experience everyday things through a three-year-old''s eyes. Meet Dorothy, Elmo''s pet goldfish and Mr. Noodle, his new friend.', '2000-10-30', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'563CB8534B5244308051964D125AAAB6', X'BB5A884361814A6DBFDF33EF2C6BE7B8', 10, 'Storming Out', 'Porsha organizes a trip to Houston to help Hurricane Harvey victims, but one of the ladies steals her thunder with a competing charity event. Meanwhile, Shereé struggles to get to the bottom of NeNe’s issues with her prison boo. Riley turns 15 and learns to drive, while Kandi tries to help her repair her relationship with her father. Tensions rise when Kenya has a tough time taking constructive criticism, setting off a storm of her own.', '2018-01-21', 43, '/qyGtvUOgFGVrkFDjUsKwVVUIVlG.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'563F7256E8BA45FC8B0462A900530470', X'56428E5E7DAA468D8BD2076956507AA8', 9, 'Oceanography', 'Surf''s up! Get the current information as Bill Nye explains why oceans are salty and explores the ocean currents. Go with the flow of ocean currents with Bill Nye the Science Guy. Most of the Earth is covered with water - we''re talking 71% of the entire Earth, and most of that water is in oceans. It depends how you count, but you can say that there are five oceans on Earth - the Atlantic, the Pacific, the Indian, the Arctic, and the Antarctic. They are all connected into one World Ocean by the flow of ocean currents. Ocean water is moving around all the time. Some of the moving water forms rivers in the ocean. Oceanographers, scientists who study oceans, call these rivers of ocean water "currents". Currents help sea animals move around, they bring up deep ocean water with lots of nutrients for small animals to eat, and they push warm and cold water around, creating different climates in the oceans. As the sea surface gets warmed by the Sun, water evaporates, but salt stays in the sea.', '1994-09-24', 26, '/gvzG3cBDMDS2DHiCFHrZJWUyg0q.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5640360AF8C4467B811455A1A9E983E5', X'8DD9292DBCB1486482974F6C3313F8C6', 3, 'Red Flags and Flag Football', 'With tensions lingering between Gina and Jenn, the ladies get their aggressions out in a flag football match; Shannon grapples with the fact that Alexis seems to be taking over everything that was once hers; Gina follows through on a tough decision.', '2024-07-25', NULL, '/sUdHLKL3c7SJYHVBlIKst0NNhB.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
