INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'565B6162482F4A048C33A87B563585DC', X'F07B879456254682AAE1E56966B4C7A8', 23, 'Leon Grows Up', 'Leon wants to be a grownup because he thinks grownups can do whatever they want. When he realizes that there are lots of things grownups have to do that kids don’t have to worry about, he decides he can wait. Sizzle wears a new sweater that makes her sneeze, and Nuzzle thinks he can be a doctor to her. Julie and Skye do not appear in this episode.', '1996-02-14', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
