INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'566FBF60744A444EAAA44DBBBD2843CF', X'68138DE20900460AB58E480688F1E081', 36, 'Call It A Day', 'When the gang all leaves the Big Blue House for the day to go to a square dance, BearTM is looking forward to getting a lot of chores done. However, each chore he starts somehow reminds him of one of his friends, and before long, the house seems awfully quiet. By the time his friends return, Bear has realized that the Big Blue House just isn''t the same without them.', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
