INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5678DF8468814ADBBC4CE77D3721D2B5', X'45E01C046AC641E187D8F749EE230385', 18, 'Sailor Steele', 'Fireman Sam and the rest of the team are training Mike Flood and Charlie Jones to be reserve firemen, and Station Officer Steele is very pleased with their progress. Both Charlie and Mike are itching to fight a fire but the training has prevented Charlie from going out in his fishing boat and there is no fish for the Wholefish Cafe. Charlie and Station Officer Steele they go out in the fishing boat, but are cast adrift after an engine fire leaves their boat stranded.', '2008-03-05', 10, '/5AaLSf8UitbJ8bTAj7y6t7Fa8z0.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
