INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5685955294244EC283BACCBE8419C543', X'EB7E3BB45746457781C6F5B2DC2EFC6E', 11, 'The Desert', 'Aang searches for Appa while Katara struggles to keep everyone together to survive in the vast desert. Meanwhile, Iroh and Zuko seek help from an ancient secret society.', '2006-07-14', 25, '/w2zbcRX7ZE6L4QQWo1xlgsrrwLy.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
