INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5686E9F726854BE68865DF80F227E97F', X'6F81C872CDB942DD83772C17CB6ED4D7', 27, 'Twinkle Twinkle Little Star', 'Elmo doesn’t give up and keeps practicing until he can play the song “Twinkle Twinkle Little Star” on his piano. Guest: 5th Harmony.', '2017-07-08', NULL, '/bxQsab68zuCYlGKFsXfnq7NFxeg.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'568936BF8D52402C8117A17724F3DD77', X'A4843A51AEEF427C902C7FB3BD670CD4', 3, 'Mouse Party', 'Today is Tutter''s birthday, and the friends in the Big Blue House decide to throw him a special surprise birthday party. Pip and Pop are placed in charge of the decorations, but run into trouble with the balloons. All the noise attracts Tutter, but Bear manages to head him off with our help. Tutter learns that having a birthday means becoming a year older. He speculates on all the great things he''ll be able to do while he''s older. Ojo works on the cake and Treelo wraps Tutter''s present. Treelo, though, gets so excited about the birthday that at first he wants to keep the present for himself.  Songs  ■When I''m Older  ■Happy, Happy Birthday  Notes  ■A big deal is made about Tutter''s present in this episode, but viewers never find out what it is.  ■Luna is so old that she doesn''t remember when her birthday is.  ■Shadow does not appear in this episode. The time normally spent on her story is taken up by Tutter''s birthday party.  ■The events of this episode were the basis for the stage show Bear in the Big Blue House Live: Surprise Party. This stage show no longer tours, but is available on video.  ■The "Happy, Happy Birthday" song is listed as simply "The Birthday Song" in the closing credits. Additionally, the closing credits run longer than usual.', '1997-10-22', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
