INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'56C14F65054B4DAA900AF4BBC3D21CDA', X'F4C403079B5E4263A4E0DFA138131E7F', 59, 'All-Star Alphabet', 'Get to know your ABCs with this fun-filled adventure that celebrates the wonder of words and the joys of the alphabet, Sesame Street-style. Shapes, sounds, and colors come to life as letters A and Z join Elmo and the gang for some F-U-N at the mall. Whether it''s crooning with Sheryl Crow or rocking with Melissa Etheridge, dozens of entertaining songs and skits add to the excitement as every letter gets a chance to shine. No matter how you spell it, Sesame Street''s All-Star Alphabet makes the grade!', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
