INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'56CC8DAAFE884CAEA38065B2EE9D7679', X'5BA20443D99F482081F66832D3F2BC4F', 12, 'Deserts', 'About 20% of the Earth is a desert. Deserts are places that get very little precipitation (rain or snow) each year, and that makes them extremely dry. Deserts cover big areas of land. The biggest desert, the Sahara, extends from North Africa to Southwest Asia and is 13 times the size of Texas. Some parts of the Sahara get as little as 2 millimeters (0.08 inches) of water a year.', '1996-01-29', 26, '/pjkC3rGlBTFLCqEl61ALV7SJzGc.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'56CF65CBF8AC48B1AB45ECCC04E97F0F', X'8730C55E844344B0AFEFA369C478B14F', 16, 'My Name Song', '', NULL, NULL, NULL, '2026-04-03T15:26:09Z', '2026-04-03T15:26:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'56D7CB9604704100A79B4EC5AC57A8E3', X'D5383B3D56364D71B99CB84774B4B3C6', 10, 'Pingu and the Magnet', 'Pingu is rummaging in the toy box, and finds a horseshoe magnet with a metal ball attaching. Holding the magnet he pulls the ball off with his other hand. He’s surprised when he lets go of the ball and it flies back and re-attaches itself to the magnet. He has another rummage in the toy box and finds a wooden ball, but can’t get it to attach to the magnet. Initially puzzled, he then has an idea and goes outside with the magnet and the two balls. He buries the magnet in the snow, smoothes off the snow and then draws a circle round the area with a stick he finds nearby. Pleased with the result, he picks up the two balls, holding one in each hand. Pingo then walks up and wonders what Pingu is doing. Pingo suggests that they play “toss the ball in the circle” and gives Pingo the wooden ball to use. They then move a few paces away. Pingo goes first, and his ball ends up inside the circle but right at the edge. Pingu’s throw stops short, but the ball wobbles and then rolls right into the centre of the circle. Pingo is astonished! They get their balls and have another go. This time Pingu goes first and overshoots the circle, but the ball rolls back and again stops in the middle. Pingo can’t believe it, and Pingu is convulsed by laughter. Mother then calls Pingu in, and Pingo goes over to examine the circle. Digging it up, he discovers the hidden magnet and realises what has been going on. He takes the magnet and buries it nearby, and then carefully covers up what he has done. Pingu then rushes out, and Pingu offers him the metal ball to use. Pingu throws his ball, which gets to the centre of the circle and then rolls out, ending up at the spot where Pingo has buried the magnet. Pingu can’t believe it! Pingo chortles, then gets Pingu’s ball for him and suggests he has another try. Pingu misses the circle, but the ball then rolls straight across the circle to where it was before. Pingu is annoyed! Pingo then tosses his ball and it ends up in the centre of the circle. He chortles, and Pingu is almost beside himself! Pingu goes over to investigate, digs a hole in the circle and is surprised that the magnet has gone. Pingo chortles, and just as Pingu realises what has been going on Father comes by on the motorised sledge and stops to speak to them. As he drives away the magnet uproots itself and attaches to the back of the sledge, to Pingu’s dismay. He and Pingo then make up.', '1998-01-20', 5, '/zqEzHFoeblRhmAA1oTn3RNtseB7.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'56D82CF002A847C185FA4AFF252E1D15', X'97A3D1F5A8F147CD81222E74A092836D', 12, 'Just in Time (4)', 'Catherine gets the message from Ghostwriter and goes to tell Frank but she finds Lucy instead. Catherine and Ghostwriter plead with Lucy to help and she agrees. The team meets up with adult Catherine and she tells them how she and Frank caught the real culprit.', '1993-11-24', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
