INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'56DBED3E40D647D6B67DD83C4A2A7AA7', X'0F64BF9F8D054F5B9A575D0C44AC3F40', 12, 'Meri Catfished', 'The Browns are in Alaska dog sledding and deep sea fishing. And in one of the most stunning and emotional twists ever on Sister Wives, Meri admits to her family that she''s been involved with a man online, but this person is not who she thought he was.', '2015-11-15', NULL, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'56DEFD092DAF43508B68A8D61A816B1A', X'573A556EED204222A12DB1B7779E1B18', 2, 'America''s Deadliest Snakes', 'Steve travels to the United States where he researches the remarkable rattlesnakes, the most venomous serpents of all, to show how placid they can be when unprovoked. In Florida, he finds snakes as diverse as the pygmy rattler and eastern diamondbacks. He also has a close encounter with timber rattlers in Virginia.', '1999-09-05', 44, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
