INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5721DA7663DD48FA86258A4E119DCF23', X'7B19039A31AC425C8FB1B51CF2447821', 1, 'An Unexpected Secret', 'Change is in the air in the OC as Shannon, Gina and Kelly have new significant others and homes. As Shannon takes a tour of Gina’s new house, she vents frustrations about Kelly. Braunwyn and Kelly head to their friend Elizabeth’s beach house and are shocked by Elizabeth’s unconventional relationship. Meanwhile Emily, with a new hip and outlook on life, celebrates her anniversary with Shane. Braunwyn convinces soon-to-be neighbors Shannon and Kelly to meet up and hash out their differences. Later, Braunwyn invites Emily over and shares a secret she has been keeping.', '2020-10-07', 44, '/gep7v56MlJ4rebTIRwsdBzVHXrD.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
