INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5738BD845CFF414185A06EBBDCEF467F', X'1A534647384B4C00BB6CA3371AD962EB', 39, 'Wheelin'' and Dealin''', 'Wheel and deal with the Pawn Stars as they rediscover some of the coolest vehicles to ever drive into the shop: a one-of-a-kind rock crawler, an impressive collection of restored Indian motorcycles, a custom dragster capable of reaching 192 mph and a John Deere ice cream machine that leaves Chumlee drooling.', '2015-07-27', 21, '/5Nh0WyumYvUR4Aan6bkEw50NBHB.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
