INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'577AFC6DA04E4BBF891254A9BD16345A', X'E38E9D8714324A1AA7D064A559BF7570', 4, 'False Haven', 'With most of the animals too tired to care where they rest they shelter in an empty barn. But Fox is wary about being near humans and sets up a watch to alert them of danger. However when Mrs Pheasant takes the place of her sleeping husband she wanders out of the barn and is killed by the farmer''s gun. With the sound of the gun the animals try to escape but they are locked inside the barn with a dog patrolling outside. Some of the animals manage to gnaw and dig an escape route allowing them all to escape into a nearby wood. However it is when they are all safe and the panic over that Fox realises that one of them is missing.', '1993-01-24', 24, '/d40dRgUmbfxNo2gDJqrw0XHnDw5.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
