INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'57A78929B2C240359719BFC61859148C', X'DA06465B91544FEBA455374DF7DAB02F', 15, 'Rock sitter for Rocco (4097)', 'Zoe needs a rock-sitter to read, sing, and play with Rocco while she is away in swimming class.  Telly agrees to take care of Rocco in the meantime. Since Rocco likes rock stories, Telly, with Elmo’s help, first tells her the story of “Goldirock and the Three Bears.”  Since Rocco also likes rock music, Telly, Alan, and Bob sing, “Rock Around the Rock” to her.  When Zoe returns from her swimming class, Telly tells her about all the fun they had while she was away, and offers to help her take care of Rocco anytime!', '2005-09-09', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
