INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'580FEF773D1640CF92D33324B03C2C28', X'EBA5535A00C74ED6B186382D83C5181B', 8, 'Episode 1713', '', NULL, NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'58118C26622946E885D89F80C94CD416', X'4B2A19E02FAE492EBC31F78E63D88EBC', 5, 'Double Your Pawn', 'Giddy up with the Pawn Stars when early Western film star Harry Carey''s collection of nearly 200 celebrity autographs lassos into the shop. Will Rick make a bonanza of an offer or ride the deal off into the sunset? Next, a 1900s Wrigley Gum vending machine pops in to the shop. Will Corey double his fun or find it''s lost its flavor? Then, a measuring device known as a railroad equilibristat chugs in. Can Rick lay down an offer or will he derail negotiations? And later, a 1960s Jimmy Jet toy zooms in. Will Chum land on a price or will he steer off course?', '2016-08-24', 21, '/kgk3yfbdDmZm0p4OWF03QqbROjz.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5816FC0694C040828F74BE0F4DB6798A', X'EBA5535A00C74ED6B186382D83C5181B', 6, 'Episode 1711', '', NULL, NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5822E195968E4625A92C02515A393020', X'C7994637B7C742C7AAEE1BFF4144FE23', 19, 'Reunion Part 2', 'The reunion continues as Sutton and Kyle''s issues come to a head, jeopardizing their friendship like never before. The moment the conversation turns to Sutton''s finances post divorce, Annemarie offers her opinion on the situation. When Dorit addresses rumors about her marriage and reveals details on her latest robbery to the woman, Garcelle finds herself in the hot seat for her questionable comments. As Erika celebrates her victorious comeback, she realizes that Crystal isn''t quick to let go of her past.', '2024-03-06', 44, '/IuJ6iZgJ3pmobKovt32t3kSM7P.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5825D9FC25434747A8D80454309F75AD', X'1A534647384B4C00BB6CA3371AD962EB', 4, 'Wilde Card', 'Read between the lines with the Pawn Stars when a first edition of Oscar Wilde''s "The Happy Prince" is brought into the shop. Will Rick be able to resist this literary classic or will he yield to temptation? Then, Corey steps into the ring with a 1972 telegram that rejects Muhammad Ali from fighting in Alaska. Will he get ready to rumble for it or will he get knocked out before the negotiation begins? And later, Chumlee bets Rick he can increase his weekly sales by using more casual and cool language. Will he be able to talk the talk or will he be at a loss for words?', '2015-01-15', 21, '/9jKbqnJsKw2g8fEW53NCzMCcP8g.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'582B4C5A531E48F6B33F4B7F987BB5F9', X'9193E795DA7C40ECB68FF63AA7D5174F', 154, 'Histories & Lore: Northern Allegiances to House Stark', 'Sansa Stark recounts the history of the North, of how it was once unified by the House Stark, of how its principal noble houses swore loyalty to them, and how they guaranteed its independence from the Andals, while she prepares herself from the Wall to confront those who now govern it.', '2016-11-15', 5, '/pr8o13e6zwFmbUCewPfSfk022F.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'582F9205C4224B169D30D64B2C2805CF', X'4B2A19E02FAE492EBC31F78E63D88EBC', 6, 'Pops Pawn', 'Gaze at the sky with the Pawn Stars when an astrological armillary sphere orbits the shop. Will Rick make a celestial deal or will they be galaxies apart? Next, a British Smarties candy dispenser sweetens up to Rick. Will he play the game or send the chocolate beans back to England? Then, things get jazzy when a signed Louis Armstrong photo and handkerchief scat in. Will Corey think it''s a wonderful world or will he send Pops packing? And later, a vintage Ghirardelli billboard gets Chum tongue-tied. Will it be a sweet deal or will it leave a bitter taste in his mouth?', '2016-08-24', 21, '/eHhfde1UMSARBuIsKafIDz1cHKT.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5835220391774120B9FA244A4B37B38C', X'A79A245FACAB4EBEAEE929867F9E52F6', 12, 'Meeting Mariahs Girlfriend Part 2', 'Mariah and her girlfriend go to the March for Women in Washington, D.C.; she invites Meri and Janelle to go too, but Kody doesn’t like the idea.', '2018-02-18', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'583572DFE76C49698BFC3341CFEECC14', X'E48599F866FF4C0F927465B9AE1CDA9E', 74, 'Episode 74', 'Jubilee Walk Way  A preview of Britain''s newest tourist attraction. JOHN and Shep follow the trail of the 5¼-mile walk to be dedicated by the Queen on 9 June.', '1977-06-02', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'584049D314C142EEB1B99A634EAB595F', X'F829D1FB64EA430F8E0EB3345653A542', 1, 'From the Outback to Hollywood', 'A detailed account of Steve and Terri Irwin''s sudden and unexpected rise to fame, in just one short decade. Footage includes the whirlwind of a promotional tour for their first Hollywood film, and their conservation work at the Australia Zoo.', '2002-11-20', 44, NULL, '2026-04-03T17:39:12Z', '2026-04-03T17:39:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'58449C5159084040A47CB3B9D05B427D', X'06030129FF2D4490B66C9F41BBE7AABD', 5, 'Horse Towing', 'Whilst attempting to travel to Dudley, the Ragdoll''s tiller comes apart in John''s hand, meaning he has to walk to a nearby stable so a horse can tow the boat to somewhere he can get it fixed.', '1990-10-01', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'58469FC62496487A898E94B01F808593', X'6F731E6BD3C54DE684E17A19CB650E86', 27, 'No Pawn for You!', 'Please rise for the Pawn Stars when a chair belonging to Abraham Lincoln takes a seat in the shop. Will Rick act like Honest Abe and make an offer or will he abolish the deal? Then, barrels fly when Corey and Chum check out a vintage Nintendo Donkey Kong arcade game. Will they think its bananas and make a sale or will it be a Ninten-don''t? Next, a signed Seinfeld script is brought into the shop and "yada, yada yada." Will Rick be the master of his domain and snag the deal or will he hear, "no sale for you"? And later, things heat up when a brigade of antique firefighting buckets extinguish the shop. Will Rick draft an offer or will he get hosed?', '2016-02-17', 21, '/16b8Rarep2qtQwqfBlrSRG4bC6Y.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
