INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'59208A93A3B14B6381596A401E8301F1', X'BC1B58B0F2D64214914B231F27FB4D61', 16, 'Singing in the Pain', 'The wives are up and running when they participate in a charity race, with Teresa''s competitive nature on full display. Meanwhile, Melissa premieres her song to an unforgiving crowd in Hoboken. And Teresa throws a birthday bash for one of her daughters, highlighted by a jaw-dropping gift.', '2011-09-11', 43, '/skxrlGEmYZAtFHZBZPEq7NHa9eB.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'592C0FB5BF0C44AA92FA2E2EDFAEDA98', X'1D713CA64E174F84949C8CFD98514127', 24, 'Chummified', 'Walk like an Egyptian with the Pawn Stars when a mummified falcon creeps into the shop. Is this ancient bird destined to spend eternity with Rick, or will it fly out the door? Then, Rick and Chumlee call a timeout when an autographed Harlem Globetrotters basketball from 1978 bounces in. Will the deal be a slam-dunk or an air ball? And later, when a metal detector comes in from the nightshift, the Old Man and Chumlee borrow it to go treasure hunting against Rick''s wishes. Will they strike gold before Rick strikes back?', '2014-10-16', 21, '/ab8ILK8NvHsePVLy8oSu3SoPWSQ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
