INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'59C0AC966E9F4C5889FE36F094B9AD49', X'53587A7ECD9344F0AD795FE586DCCB8E', 6, 'The Rainbow Puddle', 'When Kipper finds a magic frog in a puddle at the end of a rainbow, he''s granted wishes. But when the frog has a wish of his own, Kipper must find a way to give his wish away and help his new friend.', '1997-10-10', 9, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'59C1D32FCC8745E1957D25150368A002', X'136B81D3964D4B8FA21492F00D96D6B9', 70, 'Episode 1905', 'Maria and Telly discover clever tools and gadgets that help make household chores easier and more efficient. A grouch causes complications before Ernie and Bert peacefully resolve the situation. Oscar explores how to use a can while the children learn valuable lessons about using the right tools for different jobs.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'59C4231DD2C043848EC0FB5BD771F45D', X'02849655BD954D8DAF3B03321918EEEE', 22, 'Madeline at the Eiffel Tower', 'After Madeline performs a successful science experiment dropping an egg off the balcony of the old house without breaking it, Pepito dares her to drop her egg off the top of the Eiffel Tower, and the two end up getting stuck in an elevator there, and being forced spending the night. Pepito and Madeline share their knowledge. Pepito shows her Morse code, and Madeleine shows,... well... her hunger.', '2001-01-31', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
