INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'59CB73465F7640AC95C1DB2535DA9E6E', X'F5474771893041EBB0D4DB442233ACEE', 9, 'Crikey! What an Adventure: An Intimate Look at the Life of Steve Irwin', 'Steve''s family and friends remember him, in this tribute special that premiered immediately after Ocean''s Deadliest.', '2007-01-21', NULL, NULL, '2026-04-03T17:39:10Z', '2026-04-03T17:39:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'59CBA21D49514FF98C236CD9D472DCE7', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 8, 'Atoms & Molecules', 'Atoms are reeeeally small. They are so small that you can’t see them with just your eye. It takes as many as 10 million of them side-by-side to measure a single millimeter. In fact, atoms are the smallest pieces of “stuff” that are still considered “stuff.” If you take something and break it into tiny pieces, and then break it into tinier pieces, and keep going, the smallest part you’d be left with (and still have the same substance that you started with) is an atom. Atoms are the building blocks of all matter. Everything is made of only 109 different kinds of atoms, called elements. 92 of these elements occur naturally, but the rest of them – ones like Technetium and Promethium have only been found in distant stars and Californium and Einsteinium – are only made in laboratories. A molecule is born any time two or more atoms combine together.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'59CE050A8C9A47BBAF3251BB4054CA85', X'4D2CAC0F38FD438B8AFAACF43952E535', 166, 'Episode 166', 'A magazine programme for younger viewers. Introduced by Christopher Trace and Leila Williams. Chris and Leila tell you more about Dolls'' Houses and Blue Peter Alphabet reaches the letter N.', '1962-01-08', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
