INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'59FC2EF98D924A86ADB8AE4FEB70C1A2', X'DA06465B91544FEBA455374DF7DAB02F', 16, 'Goldilocks Takes Over Nursery Rhymes (4098)', 'Being completely oblivious to their feelings, Goldilocks takes Little Miss Muffet’s curds and whey, and then sticks her finger into Little Jack Horner’s pie.  She takes both of their nursery rhymes and makes them her own!  Little Miss Muffet and Little Jack Horner are so upset that they start crying and run off to Baby Bear and Big Bird who offer to help them.  They encourage Little Miss Muffet and Little Jack Horner to be assertive and stand up for themselves.  Little Miss Muffet and Little Jack Horner gain the confidence to approach Goldilocks, who is at Hooper’s Store with Alan.  Alan notices that Little Miss Muffet and Little Jack Horner are very upset, so he encourages them to share their feelings with Goldilocks.  After they express how badly she made them feel, Goldilocks realizes that she wouldn’t like it if they did the same thing to her and apologizes, saying that she really didn’t mean to make them feel sad.', '2005-09-12', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
