INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5A34410A0D934FB99B6D8FD682F8CD7B', X'05C0E384194C44179F62803EB615E409', 105, 'The neighborhood orchestra', 'Rogers demonstrates how the xylophone works. John Costa, who is on the accordion, joins Rogers on several song duets. The Neighborhood of Make-Believe orchestra holds a concert for King Friday and Sara Saturday.', '1968-07-12', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
