INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5A52075642BB4C5A979255C8E70FCF55', X'D123FD65EFB74EBBA23E190C447791CF', 8, 'Le Fin?', 'As the Hamptons trip continues, the ladies try to put last night''s drama behind them with some boxing, a little retail therapy and a lot of alcohol. Guerdy later joins the group for dinner, where Julia blindsides Adriana with an unexpected proposal.', '2022-01-27', 44, '/9TPMFzOFWh1Ydb3wIbUvoSpJOTD.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
