INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5A5A3F44F32C476ABD278682CCAEF8BC', X'17E6CC8EDCF34CE697DB5A9FC8E31EB5', 7, 'Nashville Hold Em', 'The ladies travel to Nashville to get away for Porsha''s birthday, but tension soon follows; Drew encounters startling news in court; as Brit picks up the pieces from recent allegations, she receives support from an unexpected housewife.', '2025-04-20', 42, '/rSE2VK6exVh1HmC4XwZ98n3X09x.jpg', '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
