INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5A616AF21EA24CD8B3F22DBA06A7CE91', X'54C290142DBD49FFA23FCF4C546E0B3A', 5, 'Everybody Thinks We''re Drag Queens', 'Battles continue at LuAnn''s barbecue. Elsewhere, Sonja tries to clear the bitter air by hosting a brunch; Carole receives an honor at a Coney Island parade, spurring the other ladies to strut the boardwalk dressed as seagoing drag queens; and Aviva faces her greatest fear.', '2014-04-08', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5A692EEA8C914713AECEF4D17193016F', X'F4C403079B5E4263A4E0DFA138131E7F', 118, 'The Alphabet Game', 'Sonny Friendly is the host of "Alphabet Treasure Hunt", a game show where contestants bring in items that start with certain letters of the alphabet. His contestants are Gary Grouch, Dimples the Dog and Big Bird. A video board picks a letter of the alphabet at random, and the contestants must find an item that begins with that letter. When they succeed, a piece of a cookie will light up, and when all three pieces light up, the contestant wins. At random times the board will also pick a number of letters, which then present Sesame Street segments involving those letters.', '1998-10-19', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
