INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5AFF873D27A04FACBAC8962160595A8C', X'5B5E8B2F0A854488B3DC3D8B794E6582', 13, 'Don''t Rock the Boat', 'Lydia throws Doug a party aboard a yacht to say farewell to his fertility and invites all the ladies despite her hurt feelings over being left out of Shannon''s dinner. At the party, Peggy is infuriated when David questions Diko about her health. Meanwhile, Easter arrives in the OC and Shannon looks to her mom for advice about her marriage with David. Meanwhile, Vicki decides to call Tamra to finally meet and end their feud once and for all.', '2017-10-02', 44, '/ye1KEXo5Hc1CrpRiGBEf2CyGm4Z.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
