INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5B01FEB20F644961B60BE235AD817C89', X'DF77DBA2BBDA4F3897138D5C856F852E', 1, 'Old Bear', 'Bramwell Brown remembers his friend, Old Bear, who, a long time ago, was put away in the attic for safe keeping. Bramwell and his friends decide to get Old Bear back down to the playroom but it’s a long way up to the attic and they don’t have a ladder. The friends try some dramatic and heroic rescue attempts, but nothing quite works until they remember the little toy plane. Little Bear finally manages to get up to the attic safely but how will he bring Old Bear down again? Luckily Bramwell Brown has a plan…', '1993-10-03', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
