INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5B5B12ED95B5494E858A7936DFBB3413', X'D8CCF6D3E37A430AB67D7FBF269BF0BE', 18, 'Reunion (2)', 'In Part II of the reunion, Monica breaks down while reflecting on her relationship with her mother. The rift between Angie and Monica grows as they disagree about the unseen events from Greek Easter. The group is joined by Mary, who comes to Monica''s defense and sheds light on where she currently stands with the rest of the women.', '2024-01-16', 44, '/k1wZt4vtFvBzZG4dXc6jPypt90Z.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
