INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5B682CDC213E4B7AA4D454236044424D', X'543EC6DCC6C7447CB5A74484D9618391', 3, 'Foreign Relations', 'Michaele and Tareq decide to join Stacie and her husband in Europe, and the two couples start to create a bond. Cat is working hard on her book and creating her cover, when disappointment suddenly strikes. The housewives come together at Mary''s fashion dinner to welcome a celebrity hairstylist, but previous drama comes into the light again and the night doesn''t go as planned.', '2010-08-19', NULL, NULL, '2026-04-03T16:35:01Z', '2026-04-03T16:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5B6A21246E26480EAFC6575963D3C5C3', X'BD8A516B9872472DA8387AFF1070FEA3', 1, 'George Burns', 'Kermit is hassled by Daily Scandal reporter Fleet Scribbler, who blackmails his way backstage at The Muppet Show and is determined to spin everything he hears in a negative light. He even offers Miss Piggy a picture spread if she''ll give him the real dirt on the Muppets. Soon, even the Swedish Chef is talking to Fleet, who answers in mock-Swedish.', '1977-09-30', 26, '/zvCrPLoZJBseVorPvgl1HgmUY7p.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5B6E4742491D42EB957F936CB3097780', X'432A6ABDDCCA44CC82CEFB39E33B8949', 20, 'Episode 20', 'Queen Sara asks Bob Dog to send a note asking if Henrietta Pussycat can babysit for Prince Tuesday. Bob Dog is distracted with a new rocking chair, but he finds a way to help the Royal Family.', '1971-03-12', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5B7E93BC11BD49D5803D9EF58339D778', X'DF77DBA2BBDA4F3897138D5C856F852E', 7, 'The Rainy Day', 'It is a wet afternoon and the rain is coming in the playroom window and dripping through a hole in the dolls’ house roof. The poor Doll family don’t know what to do; all their things are getting wet. The toys dream up lots of ingenious ways of mending the hole, but nothing really works until Little Bear finds a solution quite by chance. While standing on the roof, clutching his umbrella, he accidentally falls through the leaky hole and the Doll family are delighted with the surprising repair.', '1993-11-14', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
