INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5BAA899F8B0145E0A1D9B32DF68B0FBC', X'3190D082877D4951BF7CED07EF560040', 9, 'Mummies Made in Egypt', 'A camel is out of place in Boston, but LeVar rides one in preparation for a show that takes a close look at mummies. Corrine Orr narrates "Mummies Made in Egypt", a book that gives all the facts about what mummies are, how the ancient Egyptians were mummified, and what they resembled three thousand years ago.', '1988-08-30', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
