INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5BAF5380CD76402C8B16430EF988F378', X'06030129FF2D4490B66C9F41BBE7AABD', 25, 'Finding The Way', 'John travels along the River Severn through Worcester, and then goes to Ragley Hall in Alcester to a maze.', '1991-03-04', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5BB1625503BB4F59999B5E174261DBEC', X'151E88A195764BD1B84AC4D64C1C9FE8', 14, 'Shameless Not Ruthless', 'Dorit throws a charity dinner to benefit the homeless, but there is little goodwill between Lisa and Sutton. When Lisa’s anger turns to tears, her friends rally to her side in her time of need. Crystal opens up about her health, expecting support from the women, but is stunned to face questions instead. Erika’s patience is stretched thin when Kyle reveals Garcelle criticized her drinking. After a turbulent year, Diana and Asher plan for a more harmonious future.', '2022-08-10', NULL, '/h6xhPosZ5L2K28RYXqEwlbxORFd.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5BB3546339794528BF0F582CFD42C8A2', X'ABFE14EEDB424DDEA96A601FF3C53ECC', 10, 'A Favour Returned', 'Matthias'' wild sparrow friend, Warbeak, attempts to reconnoiter Cluny''s camp as he prepares yet another attack on the abbey. She is captured and Matthias has to attempt to rescue her before Cluny feeds her to Asmodeus the snake. Posing as Cluny, Basil helps rescue Warbeak and Matthias sees Asmodeus once more and resolves to find a way to kill him. he stands between Matthias and Martin''s sword and battle is inevitable.', '1999-10-01', NULL, '/A3c40sgS0cr5mryrPbIKmYGOWTw.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5BB8126ADF0347989E680D07065390B9', X'3982796B54514100904246BEDF6A20A5', 19, 'Pingu and the Disabled Penguin', 'Pingu decides he’s going to play a practical joke, and meets up with Pingo. Pingu leads the way to a nearby ice-shelf, opens a bag he’s been carrying and takes out a fish and a piece of rope. He puts the fish on the ground, ties the rope to the fish’s tail, takes the other end of the rope to the ice-shelf and then covers the rope in snow so that all that can be seen by a passer-by is the fish on the ground. He and Pingo then hide on the ice-shelf and wait. Soon a penguin comes past with her shopping and sees the fish on the ground. She’s just about to pick it up when Pingu tugs on the rope to pull the fish away, and the shopping goes flying. Pingu and Pingo find this hilarious, the female penguin doesn’t! She picks up the shopping and goes off muttering. The next penguin to come by is in a wheelchair. He sees the fish and is delighted, but can’t find an easy way of getting the fish. Pingu doesn’t think that they should trick him but Pingo does and, despite Pingu’s attempts to prevent it, pulls the fish away. The disabled penguin follows the fish, the wheelchair hits a jutting piece of ice and the disabled penguin falls flat on his face on the ground with the wheelchair upside down beside him. Pingu and Pingo help him back into his chair, and explain what they did. Fortunately he sees the joke, and decides to join in, so when Pingu and Pingo hide for the next victim, the disabled penguin also hides. The next passer-by sees the fish, takes a close look at it and spots the covered rope. He gives it a tug and Pingu, who is holding the other end, falls off the ice-shelf and hurts his foot. While Pingo and the disabled penguin see to Pingu, the passer-by has a chuckle, eats the fish and walks away. Pingu gets home with the help of the disabled penguin; the disabled penguin is in the wheelchair, Pingu is balancing on top and Pingo is pushing. When he gets home Pingu thanks the disabled penguin, and Mother bandages Pingu’s foot. The disabled penguin then amuses them by doing “wheelies” in the wheelchair.', '1994-08-10', 5, '/1NKp0ZlVICqz5JSWj7brCL1QF00.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
