INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5BF888DD265348ACB004D1BA1B96C8AE', X'ABEB8D075C864F6AA110B11CBA2A4138', 1, 'The Awakening', 'Aang awakens to find himself aboard a captured Fire Nation ship with a full head of hair and sustaining serious injuries from the previous battle for Ba Sing Se. At his side are Katara, Sokka, and their father Hakoda who recount the events that led the four to the ship and contemplate their next move. Aang struggles to fight his own desire to face the Fire Lord before he is ready. Meanwhile, Zuko deals with his own issues as he makes his long-awaited journey home, with the fear of his father''s rejection hanging over his head.', '2007-09-21', 25, '/4bucff7ht2AkY6mAVgYMsJPVxo7.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5C083902ECA84C02B69F733285EA6069', X'10DA380019024816AB86D911B2ED6FF2', 2, 'The Little Mermaid', 'Pam Dawber makes a deal with a sea witch after rescuing a human from drowning -- she wants to become human. The witch agrees to give her legs, but the prince must fall in love with her or she is doomed to be sea foam forever on the sea. The Witch also takes away her voice and warns her that every step she takes will feel like she is walking on knives. Even with all odds against her, the little mermaid follows her heart, no matter where it may lead!', '1987-04-06', 51, '/8RnY4eDkZy98PU5eNMppp7nHQj1.jpg', '2026-04-03T17:38:42Z', '2026-04-03T17:38:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
