INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5C2C0459701C40119011B927770980DB', X'BFDF87FF01DD4B5494BD19B384F41BDB', 18, 'Vicious Lies and Broken Ties', 'In the season finale, the ladies gather together at Shannon''s new house for a carb-loaded affair to celebrate Tamra''s victory at the fitness competition. However, with the residual anger surrounding Vicki''s loose-lipped gossip, Tamra, Heather and Shannon decide it''s time to shut down the rumor mill. After an evening of avoidance, they finally confront Vicki about her vicious rumors.', '2016-10-31', 44, '/iEut251Opf0W7QmEC6GLlQlOr1j.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
