INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5C5A27149C2F4E338521F7698307AA21', X'AD4E434833344A088928455D9BA524C1', 16, 'Wally Boag', 'In honor of vaudeville-influenced guest star Wally Boag, the Muppets salute vaudeville, with a balloon animal act, a bagpipe player and a hypnotist. Wally performs acts he made famous at the Golden Horseshoe Revue at Disneyland, including the Pecos Bill teeth-spitting sketch.', '1981-01-18', 26, '/7kCrw0dElcTYCIcMNPFrYpWpuxN.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
