INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5C669A04BDB84FE0B2748408AF43EF28', X'66A11A09AEE24A7B8543AB080A9D1BE4', 14, 'Surprise!', 'Eileen organizes a table-read for her husband''s latest Hollywood script, and emotions run high; Brandi agrees to a 21-day cleanse but attending Lisa Vanderpump''s surprise birthday party causes her to second-guess her decision to stay sober.', '2015-02-17', 42, '/gEgEqP4iYOpz1EYFznndI6pNGyo.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5C67058CD88D4678A0811A91FDBAB0EB', X'63F9BF6D39B344F4B885A56807277A80', 28, 'A Company of Players', 'The documentary includes previously unseen interviews with Martin Baker, Bill Barretta, Kevin Clash, Bonnie Erickson, Karen Falk, Michael K. Frith, Amy Van Gilder, Dave Goelz, Jane Gootnick, Jerry Juhl, Brian Henson, Kathryn Mullen, and Steve Whitmire. They talk about the cooperation between the puppeteers on The Muppet Show, and how a few of the core characters were developed.', '2008-05-20', 10, '/xai181tZizYCucp1lllAiqAFYRV.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
