INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5C67FAF0DE2244FE9E6072CBAF03F9FD', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 92, 'Episode 2057', 'Gordon and Bob discuss letters of recommendation while Bob worries he''s not qualified to write one. Big Bird finds three things in his nest that start with the letter H and presents them to the viewers. Oscar shares his Grouch wisdom about avoiding doing dishes by using paper plates, while Maria and Luis play a guessing game identifying pictures of objects.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5C6E4F77968F44728BC6E1246BE6015E', X'DA06465B91544FEBA455374DF7DAB02F', 7, 'American Fruit Stand (4089)', 'Alan is busy receiving a big delivery at Hooper’s Store so Miles helps him out by watching the fruit stand.  Elmo and Zoe walk by talking about cookies and ice cream. All of sudden, Sesame Street is transformed into a 50’s musical show “American Fruit Stand.”  Miles sings “I Love Fruit” (to the tune of “I Feel Good”), a song about how good fruit tastes and how good it is for the body. Elmo and Zoe get so excited about fruit that they now want an apple and an orange!  Gina comes to the fruit stand and asks Miles for some peaches and pears.  Sesame Street is transformed once again and Miles sings, “Peaches and Pears” (to the tune of “Twist and Shout”).  Maria needs some broccoli.  It happens to be her lucky day because broccoli is a special guest star on “American Fruit Stand” and Miles sings “Broccoli is Good” (to the tune of “Johnny B. Goode”).  All of the fans and groupies become so excited about fruits and vegetables.  Alan’s business has never been so good.', '2005-04-12', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
