INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5C76AFC27DB64FBA9E46B4D64B6D80F0', X'51F03551BA41409D85F4E51BDDFDF82E', 1, 'There''s a New Girl in Town', 'Season 2 lifts off with tension surrounding Jill, whose published interview incites a feud with Alex and Simon. Meanwhile, social butterfly Bethenny spends the summer in the Hamptons with Jill. And new housewife Kelly Killoren Bensimon is introduced.', '2009-02-17', 60, '/6pUwHvwKMEm4BZjlZDtYT5SkSji.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
