INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5C8136106FF44CBB84DE436F120B28CD', X'D1863F2F02EC40CEAF64DB03FBE518A7', 10, 'Say Thank You to Your Face Day', 'Elmo helps Abby, Grover, and Telly figure out how to say thank you to our nose, eyes, and mouth all at the same time. Also featuring Cookie Monster''s Smart Cookies, and Elmo''s World-noses. Brought to you by the letter F and the number 9.', '2016-03-12', NULL, '/qA2SVeBbM4HyyrG2DE1o2MfSkUD.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5C8594DE7C8C49C1A843F70FA3960B60', X'F0F8B366CB3340B3A50FA1CA7780916F', 13, 'Change of Address', 'Doc finally knows of the Fraggles, when he and Sprocket have to move. Will Gobo be able to relay the Trash Heap''s message ""You cannot leave the magic"" in time?', '1987-03-30', 24, '/qEu3WfmdrcXbgqtwyeG8dil2c0Y.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
