INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5C89AA9434E741939D272CD50FD1A3B6', X'842C6419AB984D3488451D9782291AAD', 5, 'Selflessness', 'Annie is looking forward to spring vacation until her mother asks her to help baby-sit her four-year-old twin cousins part of the time. At first, Annie balks at being selfless and sharing her time, until she learns the value of giving up something in the present to achieve a greater future good.', '1998-03-15', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5C9155C1D6254423B4F40886A361331B', X'204D86FBD99C4FD18DCD9C1BCFD3C33F', 26, 'Head Over Heels', 'Quetzal tells the friends to deliver gazpacho (ice cold soup) to a sick Fernando, but they must pass a grumpy tollbooth troll named Trumpy who tells people that the only way to get over his bridge is to cartwheel. However, Emmy has trouble doing cartwheels, so Max and the dragons help her get better at them.', '2001-09-05', NULL, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5C92C19BCA0B4ABBB00143483B631136', X'3FC7C152E4F6426AA89936EC454C4403', 25, 'Not Separated at Birth', 'Zak and Wheezie have had enough of always having to do what the other wants to do and wish they became separated from each other, so Quetzal gives them crystals that separates them. However, when they build a musical playground, they discover that they actually need each other more than previously thought.', '1999-10-06', 30, '/estcsZBFZzINddsDftO7ZRC1Oxo.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
