INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5CB09B0D25C34B78B5144487DE80C2F2', X'D6092173D23B4449BAFFE0E16FE56C9A', 6, 'The Giving Peach', 'Cynthia grapples with the decision of whether to invite her father to the wedding, knowing that her mother will disapprove. Kandi organizes a food drive to help provide groceries to local families in need. Porsha feels uncomfortable with the news that Dennis may be in attendance at Cynthia’s wedding. In the aftermath of Ralph’s father’s passing, Drew is even more determined to fight for her marriage. Kenya decides it’s time for the group to take a much needed break.', '2021-01-17', 43, '/rTTjMgNf0FF43FdwOGrS4kfEtv0.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
