INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5CD8322930F947FC997248E53105959A', X'3EE646E823AE4DECBBC6C7E6A210D55B', 96, 'Elmo looks for newspapers to recycle', 'Elmo is curious about a large "mountain" of newspapers outside Hooper''s Store and why people are adding to it. Gordon points out the sign reading, "Today is Newspaper Recycling Day," and explains why paper needs to be recycled. Elmo is hooked and wants to find some old newspapers to recycle.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5CD9F967526D4BE492C828812A44E762', X'D0E5568D939D4D89AB4EC291A90691CF', 2, 'The Big Race', 'Kipper, Tiger and Pig decide to have a race. The prize is one of Pig''s chocolate cakes. Tiger goes on his tricycle and ends up in the duck pond but Kipper keeps running. Arnold gets a lift with Jake on his scooter. Guess who gets the chocolate cake?', '2000-10-05', 8, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
