INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5CDFB37143764EAA996B6A405F273A21', X'C6D5CF79F2B040AFAD1291AA4F1B1D21', 8, 'Rick''s Big Check', 'The shop travels back in time when a map comes in from the late 1800s. Will Rick be able to navigate these negotiations, or will the seller take a hike? Then, Corey spots a killer Mustang for sale. Will he pony up the cash, or drive off without a deal? Next, Rick takes a ride to check out a collection of transistor radios. Can he tune into the right price? And finally, when Chum and Rick get their hands on some Magic the Gathering prototype cards, will they be able to enchant the seller?', '2022-06-25', 42, '/1m1b5axbKhJVZechTfi0XcXMQeT.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
