INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5CE971FFD9754774A20CFFB716223574', X'A8C6182E05E14B6891A55126CF6C94F0', 6, 'The Shot Heard Round the World', 'James, reporting on the Minutemen, and Sarah, falling in with the British forces, report from both sides on the ""shot heard â€˜round the world"" at Lexington. They each leave the scene fearful of what the future will bring though James is caught up with the romanticism of fighting for liberty.', '2002-09-09', 30, '/dH7yrHfJnWH6IwpDYkfwwm8ziRS.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
