INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5CF662A33DB04047A1A19E5C6634A160', X'05C0E384194C44179F62803EB615E409', 79, 'Calling Sara Saturday', 'Title number 0079. Opens with Mister Rogers arriving with an empty box from which he pretends to make a phone. King Friday gets advice on how to contact Sara Saturday. Once she is reached, Sara invites him to visit her at her home.', '1968-06-06', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5CF87B5760D8498F99FF4B09F2983060', X'3FC7C152E4F6426AA89936EC454C4403', 6, 'Ord''s Unhappy Birthday', 'It’s Ord’s birthday, but his friends don''t have time to play with him. Feeling sad, Ord seeks out Quetzal who tells him to share his feelings with his friends. Afterwards, everybody gives him the best birthday ever, and little did he know that his friends were planning to make a surprise party for him.', '1999-09-08', 30, '/pdRbDgKQkiIiMP8uTAxBjbbgYAf.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
