INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D025A4C5E3849DBB6244BD7913B5FC5', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 39, 'Three Cheers for Us', 'Elmo tries to bounce his ball three times, and Zoe the cheerleader cheers him on.', '2010-12-13', NULL, '/180W6eVsssIHtIqVvn1wxfEc6Id.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D03528B59314639BC019C04A11BD1F8', X'9193E795DA7C40ECB68FF63AA7D5174F', 17, 'The Game Revealed: Season 6 Episode 3 & 4', 'The Game Revealed: Season 6 Episode 3 & 4', '2016-08-01', 60, '/9xvP14MhH9OVL8SE5In4ggvZ3b4.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D05A9E3362D4E7BA8F099D86DCCFE32', X'3982796B54514100904246BEDF6A20A5', 10, 'Pingu''s Outing', 'It’s early in the morning and Mother is putting things in a pack for Pingu. She goes to wake him, and tells him to be quiet so as not to wake Pinga. Pingu goes to the bathroom, while Mother makes him breakfast. When Pingu comes out of the bathroom he lets the door slam behind him, which wakes Pinga up. Pinga cries, and is comforted by Father. Pingu eats his breakfast and leaves, carrying his pack. The family wave him goodbye. On his journey Pingu asks the way from an artist, who is out painting the sunrise, and the baker, where he’s given a free pastry. A delivery man on a motorised sledge passes him, and a package drops off the sledge. Pingu calls out, and the delivery man comes back for the package, and then gives Pingu a lift. He’s dropped off at a signpost where he has to go one way and the delivery man another. When he reaches his aunt’s home she greets him at the door, and he eats nearly all of the large meal she’s prepared for him. He’s nearly asleep on his feet, so his aunt suggests he go to bed, but he’s feeling homesick. His aunt offers him a doll to take to bed with him but he doesn’t want it, so she phones Mother. When he speaks to Mother Pingu immediately cheers up, as Mother has put his teddy bear in the pack he brought with him. He goes to bed, and falls asleep during the story his aunt is reading to him, cuddling his teddy.', '1993-03-02', 5, '/vGWSBfoEdvEvTZ56pjnJAeQRSlW.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D0F560A146A4687856D941635791FCD', X'4BF3B19481B84726885062B05609EAC8', 21, 'Hiccups', 'Tomsk and Bungo get hiccups after eating hot buttercup crumpets.', '1975-10-13', NULL, NULL, '2026-04-03T17:23:20Z', '2026-04-03T17:23:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D14378281F24DE2970170A17569BEC5', X'CA19F89515144988A70995E84EAB7CEE', 22, 'Rick''s Big Triumph', 'When a chandelier made out of KFC buckets lights up the shop, does Corey''s future look bright, or will he get fried? Then, Rick gets revved up over a very special motorcycle. But will he come out of the negotiations triumphant? Next, Chum tries to talk his way into buying a vintage Teddy Ruxpin doll. But will a lowball offer even bear considering? And finally, Corey loses his head over an eerie artifact that has a strange resemblance to Chum.', '2021-08-28', 42, '/rfOfO2axskRRNiInNo3ZaoL7DVi.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D154E3602D341D4A0975FC421EA6EDC', X'136B81D3964D4B8FA21492F00D96D6B9', 88, 'Episode 1923', 'Big Bird and Telly search the entire neighborhood for Snuffleupagus''s missing toy, asking every resident they encounter for help. The friends work together cooperatively and ultimately locate the lost item. Snuffy expresses his gratitude for their kindness and their unwavering friendship.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D18F40D47264A85BE9B90A6899F2805', X'842C6419AB984D3488451D9782291AAD', 1, 'Trustworthiness', 'When Zach discovers that his college football idol is coming to his school, he eagerly volunteers to help with the preparations. But when he’s asked to clean up the auditorium, Zach wants to back out, prompting stories from Aurora and Plato about what it means to be trustworthy.', '1998-02-15', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D1FEF339BD5434396810D3D4D46E03A', X'54C290142DBD49FFA23FCF4C546E0B3A', 17, 'Bury the Hatchet', 'Heather and Kristen continue to clash, forcing some of the women to take sides. Elsewhere, the ladies take in a rodeo show and a final outdoor Montana dinner.', '2014-07-01', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
