INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D227F301B2B49028E250BC36B9F8015', X'3ADE5E1F84414C2CACF6FB933A61DCFA', 18, 'Mom''s the Word', 'Robyn and Juan make a grand gesture to solidify their relationship. Candiace begins making financial strides without her mother’s help. Karen finally reveals her La Dame perfume with an extravagant soirée, but the ladies leave with more questions than answers. After taking a pregnancy test, a fearful Ashley visits her doctor.', '2019-09-08', 42, '/3CzIzO604erdkgiT95UuhPXRjbL.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D267200E2764951BEF0CD49D4D59F32', X'4F18AC4C8757456CA49A224F00E6A9F7', 26, 'Baby Bear''s New Baby Sitter', 'Baby Bear is very excited because Grandmama Bear is coming to baby-sit. They have so much fun together! Just as Baby Bear is telling Gina this, Papa Bear breaks the news that Grandmama is sick and won’t be able to come. Baby Bear’s spirit is crushed. Gina suggests that they ask Gabi to baby-sit. It turns out that Gabi would love to do it. Even though Curly Bear is very excited and doesn’t seem upset at all, Baby Bear feels that his sister might be nervous with a new baby-sitter.', '2008-11-07', NULL, '/wLUTi2ObkllCKyte6sKXkHwlioq.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D295431928B45E3BA105B5AF6E209F4', X'E6359E6D9BDB4ABA9CBA6F7DDD6328F9', 2, 'Diva Las Vegas', 'Teddi''s job as an accountability coach leads to questions amongst the group. Lisa Vanderpump takes Erika to task for not responding whenever she reaches out. Kyle and Dorit confront Lisa Rinna while on a Ferris wheel overlooking the Las Vegas strip.', '2017-12-26', 43, '/wmeGnavtcxOR9KR7Uu6F6RQw04O.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D298040A94A45E3A6F6ECCB186FA46A', X'EB7E3BB45746457781C6F5B2DC2EFC6E', 2, 'The Cave of Two Lovers', 'On their way to Omashu, Aang, Katara, and Sokka meet a group of nomads who show them a shortcut through the "Cave of Two Lovers". But when the group becomes trapped in the cave, it''s up to Aang and Katara to save the group by trusting in love, possibly questioning their relationship. Meanwhile, Iroh gets a lethal rash so Zuko and Iroh head to a small Earth Kingdom town for help, hoping their real identities will not be discovered.', '2006-03-24', 25, '/nnXvDDSFUylD6SS7bpm1PXaNUbe.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
