INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D426197341746D19C497C95463901D1', X'04FB713D9C5945F78DE0ACD7582DAA53', 13, 'Camels, Cabo & Catfights', 'As the Cabo trip continues, Teresa reveals her true feelings about Joe returning home; the ladies are forced to take sides after Margaret throws out shocking accusations about Jennifer. Danielle tries to get Teresa on her good side.', '2019-01-30', 43, '/lbpBVU6cz7FrCtZQX7JavbMiBF9.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D4569C73D764F9CBD60CC79A046BEC8', X'1D39506B06B84F9391360208069BD7E4', 16, 'Reunion (2)', 'The women speak on the various fights during fashion week; Sonja joins the rest of the cast where she discusses her time on the show; Kelly attempts to defend herself against allegations that she had a mental breakdown in St. John''s.', '2010-06-14', 43, '/pMon1efP3le0rXOpuP9PREi8GAw.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D47A4DDAFBA4C42B04D8842FE53D8E8', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 71, 'Elmo plays hide-and-seek with Oscar', 'The library opens fresh and clean after Linda and Micki arrive early to tidy up from the night before, revealing their shared appreciation for the orderly space. When Oscar grows tired of Elmo''s constant pestering, he suggests a game of hide-and-seek to get some peace. As Oscar realizes he''s actually worried about Elmo being lost, he''s surprised to find that Elmo returns to help him search instead.
