INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D4D227B72394058976B374398A2A551', X'05044F495F9C4E7FA74DB2FF19475D0E', 20, 'Teresa Checks In, Part 1: Tre of Life', 'The family celebrates its important events for the first time without Teresa. Joe and the girls get help and support from their relatives, including Melissa Gorga and Rosie Pierri. Teresa calls her family and sends daily e-mails.', '2015-10-11', 43, '/76E4HxLjEdX56AU528sxRE1Dv1B.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
