INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D637C53B96C4F848B98C4233A701EE1', X'941B8C6544544336BE7C1D0591C12F90', 23, 'Pingu and the Doorbell', 'Pingu and Pingo are playing with a ball outside Pingu''s house. Pingu kicks it into the doorbell, which rings. As Mother comes out Pingu hits the bell again. She tells Pingu not to hit the doorbell with the ball, but instead just press it. They continue playing, and the ball hits the doorbell again, this time breaking it. Pingo runs off with the ball, leaving Pingu behind to take the blame. Mother, Father and Pinga come out, and Pingu tries to hide the damage to the doorbell, but Mother is not fooled and tells him to get it fixed. The rest of the family go off, and Pingu tries to fix the bell by pushing it together, but it comes apart again. He tries to fix it with sticky tape, but this also doesn’t work. Pingu angrily takes the broken bell off, and goes to the shop to get a new one. He finds all sorts of doorbell at the shop and settles for a trumpeting, yodelling one, and installs it when he gets back home. When his family return and go inside he keeps pressing the new doorbell, causing a lot of vibration, noise and disturbance. Father comes out to find the culprit. Pingu takes the new doorbell off and returns to the shop with it and the old one. He trades the noisy new one for a replacement button for the old one. When he gets back, he installs the repaired doorbell, and his family are pleased to have it fixed. Pingo, who heard the noise earlier, then returns and throws the ball into the doorbell. Mother tells him off and he contritely sits on the ball, but it promptly bursts under him.', '2004-02-03', 5, '/a73SwsigBXSADpAKrwPW1ayDeoU.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5D67CE53B23D40F281031881C426599F', X'5046642D462D4EB081940BBD7962AF0F', 11, 'BabySitter In DeNile', 'Laura Carrot portrays Miriam, who wonders why people in the village refuse to acknowledge that her new baby brother Moses is a boy. She is forced to look after the baby because her parents and elder brother Aaron are working in the brickyards. She finds babysitting tougher than she thought and complains about her plight. But when Aaron is almost run down by a chariot, she learns the value of family. Once she learns that the Egyptians are taking away all the Hebrew baby boys, Miriam decides to hide Baby Moses in the Nile River. After he is plucked out of the river by Pharaoh''s daughter (Miss Achmetha), Miriam offers to have her family care for the new prince.', '2006-11-10', 30, '/sLicZDWFifaFYmBECMx7ez3JmO2.jpg', '2026-04-03T17:39:38Z', '2026-04-03T17:39:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
