INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5EA478A20DA6427A97B8CE7EEDDB2E51', X'787DFA0BC8274DADA82D0548A6534D88', 13, 'Sex, Lies and Leeches', 'Heather''s luncheon ends with a bang as Vicki storms off, upset with Meghan for continually questioning Brooks'' cancer treatment. Shannon visits Dr. Moon to help deal with pent up resentment. Tamra hosts a wild "Sex Party" that has Heather covered in blood and Vicki going for blood as she not only confronts Meghan face-to-face, but also goes after Meghan''s husband, Jim Edmonds.', '2015-08-31', 44, '/vq5w3QGdrP29TFS4tS1O0lgnZsQ.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
