INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5EB5DE339BAD4164A56484281A7E3AE1', X'D034C38DC0C742B48876394B63D84275', 3, 'A New Lease on Life', 'Alexis, Gretchen and Peggy assemble for a shop-''til-you-drop get-together. In due time, dinner conversation turns racy when they spill their lusty secrets. Elsewhere, Alexis and her family have a not-so-relaxing vacation in San Diego; Vicki considers selling a house; and Tamra tries to mend her friendship with Vicki.', '2011-03-20', 44, '/9URLzdstkqYJKJQgFw0z8r902LK.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
