INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5F1FA6998DE84AE299A703D4477BEEBF', X'D5F0284F0EE345BF8539D02A825D15B2', 5, 'A Night at the Opera', 'Adriana receives a therapy treatment and has an emotional out-of-body experience. Guerdy discovers that Larsa betrayed her trust. Julia hosts a F Cancer party in honor of Martina''s recovery, but Lisa is held up by the police.', '2023-11-29', 44, '/gv7J9l4CLgVZ1V5rdTdrEDJXRO1.jpg', '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5F295A7803E643A68C9BA194999A82A5', X'1D39506B06B84F9391360208069BD7E4', 14, 'Rebuked, Reunited, Renewed', 'Jill and Bethenny at long last trying to end their feud. Meanwhile, LuAnn performs her single at a record-release party---but the wives are more interested in her new French boyfriend. Finally, the gang gathers to witness Ramona renewing her vows with Mario.', '2010-06-03', 43, '/vQwiQJ6gg2PFIDEpHh5C7u9PuKc.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5F2BE6B4921D4F298FA48EE0BE77C9A5', X'D5383B3D56364D71B99CB84774B4B3C6', 8, 'Pingu the Archer', 'Mother is cleaning and Pingu is playing when the phone rings. Mother asks Pingu to answer it; it’s Grandfather, who has found a bow and arrows outside his igloo. Pingu rushes over, and Grandfather gives him the bow and arrows. Pingu excitedly fires one into the air. Grandfather makes a target to aim at and suggests Pingu shoots at that. Pingu shoots and misses. He shoots another arrow and misses again. Grandfather tells Pingu to practice and goes inside for a cup of tea. He sits down to enjoy it, but he hasn’t seen Pingu’s mischievous look! Suddenly an arrow hits an apple in the fruit bowl, which is on the table in front of him. Then another arrow breaks a window. Grandfather is not amused and turns to go outside; a third arrow hits him on his behind. He phones Mother, angrily tells her what Pingu has done and sends Pingu home. When Pingu arrives home Mother is waiting, and takes the bow and arrows away from Pingu. Thinking to try and cheer him up, Mother asks Pingu to tidy up the firewood that is lying scattered around next to the igloo. She takes the bow and arrows and goes inside, leaving Pingu to get on with it. Pingu unhappily goes across to the wood to start, and then has an idea! He takes the broom, which is being held by the snowman, and uses it to quickly sweep all the wood into a neat pile. He then flicks the broom into the air and balances it on his beak, and starts to dance around. Mother comes out to see how Pingu is getting on, and is surprised to see the job done and Pingu dancing. Pingu finishes his dance, and flicks the broom back to the snowman. Mother claps, and gives Pingu a hug.', '1998-01-14', 5, '/wkQDphYCQ18FSXDdiWvvtjZHQ9X.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5F2F5B5D555E41129CF01CFAC5F34D72', X'E13F4AA4DD8A48D58CC11C258F43E44D', 112, 'Season 5 Reunion Part 1', 'The O.C. housewives come together to discuss the events of the fifth season of the show that started the "Real Housewives" franchise.', '2010-03-10', 44, NULL, '2026-04-03T16:35:29Z', '2026-04-03T16:35:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
