INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5F3652E773004E1CB3733567EF59F5E0', X'5C4E51C6E20746AD875C72988EB1E13E', 14, 'Sharpe Shooters', 'The Pawn Stars hit the road to check out the forefather of modern machine guns, a Gatling Gun. Introduced during the Civil War, will Rick use all his firepower to secure a deal or will he be outgunned? Then, Corey and the Old Man try to hail down a piece of automotive history, a 1915 Ford Model T taxi. Completely restored from top to bottom, will the guys run up the meter on this negotiation or will they find they''re being taken for a ride? And later, Rick gets his hands on the gun that helped win the Civil War, an 1863 Sharps rifle. Decisive in the Union''s victory at Gettysburg, will Rick rally up the troops and charge or will a counterattack force him to retreat?', '2011-06-01', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
