INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5F51F986862642C0B2B3AE50A766D7EA', X'C01DDD2ABDB14C978D0458F791EF1C24', 40, 'Bzzz', 'Animal Junction goes buggy, and Zoboo, Chris and Martin start to think that these tiny critters are nature''s little superstars. Insects and spiders are amazing athletes: quick-leaping grasshoppers, far-flying butterflies, super-strong ants, heavily armored beetles and plenty more. Bugs have to be quick because lots of other creatures like to eat them. But if bugs disappeared, a lot of other creatures would disappear too. That''s why the Kratts always say, ''Be nice to bugs.'' Chris and Martin get a bug''s eye perspective when they shrink down to insect size and find out that it''s no picnic being an ant. Some kids stomp on ants, but Jackie''s there to stop them, explaining how cool ants and their underground homes are, far too cool to stomp on.', '2000-04-27', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
