INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5F6D5AE5A5BD4251BF84693C2F9845D7', X'272DB8169822485AB2316E060D0CCB1A', 6, 'Snowdrifts', 'It''s winter in the top left-hand corner of Wales and Ivor''s railway is not running because of deep snow. Llaniog needs supplies soon, though, as Eli the Baker is nearly out of flour. What Ivor needs is a snowplough.', '1977-11-30', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
