INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5F7C07CC87F0402681CEF02FD337BBF9', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 83, 'Slimey helps at the Fix-It Shop / Telly''s magic words', 'Slimey joins Maria at the Fix-It Shop but struggles to help with large repairs until Micki arrives with a deflated basketball that needs patching. Maria fixes the ball while noting how helpful Slimey has become and mentions the squeaky front door. Telly hides behind a crate and challenges Maria and Tanya to enter his "winner''s circle" by saying special magic words.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5F856B6CF5FD4F4E8F0A66AED373B891', X'4FE93658C46343298E649D523869C2CB', 28, 'Ah, Shoot!', 'The Pawn Stars zoom in on a long lost picture by America''s most famous photographer Ansel Adams. Will the gang snap up this scarce print or will a lack of focus keep this negotiation out of frame? Then, Rick and the Old Man meet a guy hoping to sell his Jaguar XJ6. Will they shift into overdrive for this luxury automobile or will this exclusive kitten put up a fight? And later, Corey is thrown a 1942 Chicago Bears football autographed by the entire legendary team. Will he make a move for this prized pigskin or will a tough defense force a fumble?', '2011-03-21', 21, '/pyQ0YDB87hIxn4zBQSVjz2ykEXx.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
