INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5FD9FD7711BA449A9DC0D1DE5C0B0D05', X'1D713CA64E174F84949C8CFD98514127', 40, 'Hiding Houdini', 'Get spellbound with the Pawn Stars when a book written and signed by legendary magician Harry Houdini appears in the shop. Will Rick be able to work his magic on a deal or will it vanish right before his eyes? Then, Corey and Chum are in for a shock when they spot a vintage x-ray unit. Will this machine radiate with the guys or will they see right through it? And later, Chumlee takes a vow of silence. But will his actions speak louder than his words?', '2014-12-15', 21, '/riFVjrTdVdWEpvmum1pveVclDu9.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5FDAD783D8EE4821A946BEC637D0E1C1', X'AD180412A5D64E4A8B49590334F2FC69', 11, 'The Worst Kind of Hurricane', 'As Mossy predicted, a hurricane come to the area around White Deer Park. The fierce winds knock over the last Farthing Wood beech tree and release Owl from her cement shell. After the hurricane ends, Rollo and the Warden find Shadow unconscious and take her to the cottage. Fox discovers Trey pinned under a tree. Another stag, Laird, comes to free Trey and readies to challenge him to a fight for leadership. Because of his injury, Trey reluctantly limps away abdicating his power to Laird. Afterwards, he is taken away by the Warden. Measley declares that he will take no more of Weasel''s insults and decides to take their young ones back to White Deer Park. Weasel agrees wholeheartedly.', '1995-12-07', 25, '/paxZU9bRKn4zZuFtS4ANwXdkbTN.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
