INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5FDF3E1626AF4664BE811732F0DE59DA', X'C373ABED50EF417E9F344E9050611A1B', 7, 'Whines by Wives', 'A fight between Tamra and Vicki ends their Malibu trip; Alexis and Jim open their trampoline park; Heather and Terry hit a roadblock.', '2013-05-13', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5FE2B7A77047453888254FA0646FEFB6', X'D1863F2F02EC40CEAF64DB03FBE518A7', 17, 'Camping Show', 'Elmo and Chris go camping in the woods near Sesame Street to relax and meet some new friends. Also featuring Murray had a little lamb, and Elmo''s World-plants. Brought to you by the letter N and the number 16.', '2016-04-30', NULL, '/kav8fN2CNwNcKLGOWgPehnxAsgv.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5FE34452A84340E2B1BAD813F92D00F3', X'5C1B881FAC584D72B63F209952D4F902', 20, 'Episode 20', '', '1979-11-15', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5FE3CB49C253404E8C72B8C51352593D', X'33825A1537DC4FF982BDCC720498149A', 12, 'Babes in Thailand', 'The Dallas ladies’ first day of the trip is jam-packed as they explore all Thailand has to offer. But it’s not all fun and leisure, LeeAnne and Kary remain at odds, and when D’Andra shows up to dinner wearing LeeAnne’s L’Infinity Dress as a joke, LeeAnne thinks it’s no laughing matter.', '2019-11-20', NULL, '/7k00IUKpv8a1QEQgPQqgQCfL1Ld.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'5FE8DF7D74B8421D982F6FEB55BCFFED', X'3982796B54514100904246BEDF6A20A5', 7, 'Pingu as an Icicle Player', 'Pingu has gone out, and meets up with Robby and Pingo. They play a game where one person has to find the others and, once found, get back “home” before they do. Pingu starts as finder and counts while Robby and Pingo hide. When Pingu starts looking, Pingo creeps up and gets home before Pingu notices. Pingu then spots Robby’s tail sticking out of some ice blocks, and throws a snowball at him that lands on his tail. Robby comes out, and Pingu wins the race home. Robby then counts, and the other two hide, but Pingo doesn’t realise he’s leaving a trail of footprints behind him. Robby goes to look for them, comes across the footprints and finds Pingo. Robby just wins the race for home. Then they both go off to call in Pingu, but they can’t find him anywhere. Then Pingo hears some clanging sounds and finds Pingu, who is making the sounds by hitting an icicle with a broken off piece of icicle he’s using as a striker. Pingu shows Pingo the cavern he has found, which is full of icicles of all shapes and sizes. Pingo gets a striker and makes his own sounds. Then they both hear some deeper sounds; Robby has found them and is making his own sounds with the icicles. Pingu then plays a tune on the icicles and Pingo and Robby both applaud him.', '1992-02-02', 5, '/jKo0yOOJZiUzLa46W6WwNlpL7JL.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
