INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6000215BF8BD453A8FC251534B2868C7', X'D6092173D23B4449BAFFE0E16FE56C9A', 2, 'New Peach in the Orchard', 'Porsha’s release from prison after protesting further ignites her activism. Actress and songstress Drew Sidora brings her Chi-Town flavor to Atlanta, however her marriage is anything but picture perfect. Cynthia hosts a wine tasting at Lake Bailey, and an unlikely friendship has many of the women turning their heads. Meanwhile Kandi has a full circle moment as she attends Riley’s graduation.', '2020-12-13', 43, '/lgQS3cmtvnPikCEKNqnBDHChqua.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
