INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'60478B51798849DCA721707324661527', X'4B2A19E02FAE492EBC31F78E63D88EBC', 14, 'All Pawns on Deck', 'Batten down the hatches with the Pawn Stars when 18th century engravings of the Spanish Armada dock in the shop. Will Rick carve out an offer or will they fail to make an impression? Next, explicit wax recordings from the 1890s seduce their way in. Will they arouse Corey''s interest or will he get turned off? Then, a 1980s transforming Coca-Cola robot can pops in. Can Chum convert it into a deal or will it open a can of worms? And later, a 1900s Teddy Roosevelt Bears pitcher spouts off. Will Rick cuddle up to it or think its unbearable?', '2016-11-21', 21, '/hRqISZw4b2Qy8QUyPKSgvAEL4wn.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
