INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'60A79EBE6F924A8D8D119982C693D208', X'1EFB01D30A3D46A2BBC04437617C52E6', 9, 'Wrong Turn Dilys', '', '2018-05-03', 10, '/oiu54yYx45BgIhRAYzacdZOachO.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'60AAA4350FE84C16AB33AEE840614740', X'D5383B3D56364D71B99CB84774B4B3C6', 11, 'Pingu Gets Help', 'Pingu comes out of the igloo pulling an empty trolley while the snowman watches him (with its carrot nose fallen down). He puts some snow into it and takes it back into the igloo. He then comes out again, this time with a model sailboat. He sees the snowman and puts the carrot nose in its place and spins the head around. He then makes a small mound of snow, puts the boat on top and chuckles when it slides down the slope of the mound. He goes inside again, with the boat, and then emerges pulling the trolley that now contains the boat. He pulls the trolley to a nearby pool, and puts the boat into the pool. The boat doesn’t do very much, so he blows it to make it sail. He’s dismayed when the boat capsizes and almost sinks, so he takes it out of the pool and discovers that it has a hole in the bottom. Pingu sticks a plaster over the hole, puts the boat back in the water and blows at it. The boat sails away up the pool. Pingu follows it, and when the boat reaches the end of the pool blows it back down the pool. A stranger on skis comes by and asks Pingu what he is doing. Pingu explains, and as they watch the boat it sinks again, this time completely. Pingu goes to look for it but can’t see it, even after putting his head in the water. The stranger decides to help, and edges out over the pool on his skis to see if he can find and rescue the boat. In the process the skis break, and the stranger falls in and disappears under the water. Pingu gets rather anxious, and follows the bubble trail being made by the stranger up and down the pool. Suddenly the boat appears; the stranger has found it. The stranger gives Pingu his boat back and gets out of the pool. Pingu is delighted to have his boat back, and as the stranger happily walks away in the direction he came, Pingu waves him goodbye.', '1998-07-19', 5, '/fufLMpIS4DI3vdCz71S23uwxpCZ.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
