INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'61328D0E524246038D6A338D98139BA8', X'331FC1DF6D704D79B585BF28024A4124', 16, 'Dinosaur Hunt', 'Norman Price and Trevor Evans discover an ammonite on the beach which inspires Norman to create the illusion of real dinosaurs for James and Sarah. James chases the sound of Norman''s "dinosaur growls" into a beach cave where both boys become stranded by the rising tide. Meanwhile, Sarah is stranded on a rock. Sam and Penny come to their rescue.', '2008-12-02', 10, NULL, '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
