INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'613FE2555F454D54B6214DDFE9D0EFE0', X'852A07B0F228419791477AEED79390BF', 10, 'Light As A Feather, Stiff As A Bored', 'In Salem, Eboni''s pointed question reverberates throughout the group, leading to an emotional revelation at dinner and some new body ink. The ladies take a trip back in time to the historical Pioneer Village and later at dinner, Bershan ruffles some feathers with a few of the ladies when she voices her opinion of them.', '2021-07-13', 60, '/ssBnWH3diUThfdg6MLO0RuEh37b.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
