INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6159C8479C764E55B2026F1B499FD82B', X'095258D0D8DB40968AC76A42CD4CBDCF', 11, 'The Beanbarrow, The Burden And The Bright Bouquet', 'It''s time for the annual Beanbarrow Race, and it''s Gobo and Wembley vs. Red and Mokey. But when Mokey gets delayed, Red ends up having to do the race with Lanford, Mokey''s annoying plant. As they''re racing, Red and Lanford get lost at Table Rock Cavern which is where the Clinging Creepers live. When the Clinging Creepers start to attack them, Red and Lanford must work together in order to escape.', '1985-03-11', 24, '/rMbrYFtmWBgCfYQVk7x6Wpq78sG.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
