INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'61649D81CC9949CA83867DAAF6010DC1', X'F12380A993E547BB9E2FCF1EED11EEE4', 13, 'Benevolence, Bitch', 'Kody''s apology to Christine starts well but gets tense when David brings up Kody''s relationships with his kids. Janelle seeks guidance from Meri on getting her spiritual release. Meri''s shocked friends try to talk her out of meeting up with Kody.', '2025-12-21', 61, NULL, '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'616B97E85DD84543915CAEFACABB2DAE', X'EFDF1E4F84764382A9D72B9DA4188BE0', 1, 'Mad Feelings', 'Rogers visits Red Grooms'' studio, where he is currently working on a painting of the trolley. The Neighborhood of Make-Believe sees Lady Elaine in fits because she can''t seem to draw the Eiffel Tower well.', '1996-08-16', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'616C1A8819AC4638B8E07FCBCC41E0FD', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 69, 'Maria looks for things beginning with the letter I', 'Maria and Telly search frantically through the Fix-It Shop for something beginning with the letter I while Barkley creates chaos by howling and scratching. They pull out drawers, rummage through the store, and interrupt their lunch plans in the quest, but struggle to find anything suitable. Crystal explains the importance of breathing to help demonstrate the letter and its sounds.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'616D21C24FF5499587324DF7FAE881D9', X'1BE79A20DE3341D1AF17079035B18D5C', 69, 'Episode 69', '', '1970-02-12', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'616E3B401F1F46BABD5D6D400051A693', X'05C0E384194C44179F62803EB615E409', 18, 'Practicing and playing the clarinet', 'Title number 0018. Opens with Mister Rogers arriving with clarinet in a case. Mister Rogers puts together a clarinet and plays a few notes. He talks about his childhood clarinet lessons and remembers that he did not practice enough. In the Neighborhood of Make-Believe, clarinetist Loius Paul performs for King Friday and talks about the importance of practice. Mrs. Russellite, played by Barbara Russell brings a pinwheel to Henrietta and is introduced to Donkey Hodie, who is staying in the Tree until he finds a place to live. The pinwheel gives Donkey Hodie the idea to live in a windmill.', '1968-03-13', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'61707AEC31AC4019A5A08C9CC1D3B755', X'68138DE20900460AB58E480688F1E081', 5, 'Good Times', 'Everyone has slept over at the Big Blue House, and with the rising of the Sun (who shares some words with Bear), they''re soon waking up and starting a new day. Before they can go out on their adventures, Bear helps them with some healthy morning rituals, from breakfast to brushing teeth. Children will relate to the various experiences on display, from coming to terms with a wild but believable dream to having to immediately take a bathroom break.', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
