INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'61902A3752F3470288577C3D61DF9168', X'3EE646E823AE4DECBBC6C7E6A210D55B', 68, 'Gina buys fish', 'Early in the morning, Gina returns to Hooper''s Store with some fish. She speaks to the viewer quietly, mainly wanting to keep Wolfgang the Seal from hearing about them and allowing his barking to wake everyone up. She makes it inside, but Wolfgang manages to sneak in behind her and appears when she.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'619AC61394BA47589193857A0615FBF7', X'0B9D7AE7218E45A08C3AE69912F5A6ED', 26, 'Franklin''s Missing Snacks', 'Bear is accused of eating all of the snacks his friends stored away for safe keeping.', '2000-02-21', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'619BC5ECF9A54B96B7C7B1F482ED929C', X'46D7A706C7A84EBEB96F387C66E8BB8B', 1, 'Episode 1446', 'Big Bird goes to school', '1980-11-24', NULL, '/3QPs9al1658xZ01qQNRdAzM3cPg.jpg', '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'619DF65ECA3B47878D184D76B79D144D', X'DA06465B91544FEBA455374DF7DAB02F', 11, 'Baby Bear''s First Day of School (4093)', 'Telly Monster tells Gordon that he feels miserable because in order to go on Oscar’s Annual Grouch Picnic and Field Day, he has to learn the Official Grouch Cheer and he’s the only one who can’t do it right.  Gordon talks to Oscar and convinces him to let Telly try learning to do it right.  Telly is so discouraged at this point that he keeps saying that he can’t do the cheer.  Gordon motivates Telly by practicing the cheer with him and by telling him that he can do it!  Through Gordon’s encouragement, constant practice, and believing in himself, Telly finally learns to do the cheer!  Telly shows Oscar that he can do the cheer beautifully, and boards the bus to go on the field trip with all the other Grouchketeers!', '2005-04-18', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'61A203593CE64A178A52CAC183C515FC', X'63F9BF6D39B344F4B885A56807277A80', 30, 'Mr. Willowby''s Christmas Tree', 'The special begins with the song “The Perfect Tree,” which features both Mr. Willowby (Robert Downey Jr.) singing about his desire to find the perfect Christmas tree and, within Willowby’s house, a father mouse singing that he will go out to get a tree for his family (his two children, Beverly and Ned, decide to come with him). After the song is finished, Willowby asks his butler, Baxter (Leslie Nielsen), where his tree is.', '1995-12-06', 30, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
