INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'61BDF944C09C41A3B423A11284F9056F', X'699572F82BFF45158DF36E7D1A21F346', 2, 'Cracks a Yolk', 'The principal, Mr. Ruhle, has to go away for a few days and leaves his beloved chicken, Giblets, in Dorothy Ann’s care. The Friz takes the class on a field trip to see how eggs are made - from the inside out!', '1997-09-20', 25, '/iAC7FxCmoq3i7YPgIStGpTejDDu.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'61BEA40547B24B42BE0E6D9D44A37DF7', X'0AB4DFB258C94E52B5BF49BBA0BFC597', 7, 'A No Rough Stuff Type Deal', 'Walter accepts his new identity as a drug dealer after a PTA meeting. Elsewhere, Jesse decides to put his aunt''s house on the market and Skyler is the recipient of a baby shower.', '2008-03-09', 48, '/1dgFAsajUpUT7DLXgAxHb9GyXHH.jpg', '2026-04-03T15:40:32Z', '2026-04-03T15:40:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'61C0CB82B666416DBBA02E977B5C4CB7', X'225B0F03984B47F3A1A3D3E92175E39D', 24, 'Episode 24', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-12-15', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'61C1D6E3FDBA4606AC5946E49A75A6C9', X'1D713CA64E174F84949C8CFD98514127', 3, 'Chumdae', 'Rev your engines with the Pawn Stars when a legendary 1967 Shelby GT350 speeds into the shop. Will Rick be able to cruise through the negotiation or will it be gone in 60 seconds? Then, Corey and Chumlee play with the idea of buying one of the first video game consoles, a Magnavox Odyssey 200. Can they figure out how to beat the system or will it be game over? And later, Chumlee seeks the go ahead from Rick to test out the shop''s new ice cream maker. Will the guys all scream for ice cream or will Rick give Chumlee the cold shoulder?', '2014-07-17', 21, '/pCSsfApqp4aM4wKWlaFZ4cvbODE.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'61C9D8CAF086424A8C5EE89177E191C4', X'6E0BE2A3A234453BABB70BA535A93601', 25, 'My Franklin', 'Franklin and Bear want to play in the park, but Bear''s younger sister keeps calling out to them. Franklin keeps retiring until, which makes Bear jealous, but they realize the she was actually calling out to Franklin because Bear was too busy.', '2000-07-30', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'61CDB6950C324B4184F9EC67B36A13C6', X'CA19F89515144988A70995E84EAB7CEE', 11, 'Rick''s Big Shot', 'When a seller comes in with an overcoat once owned by suspected JFK assassin, Lee Harvey Oswald, will the deal be a stroll on a grassy knoll, or will Rick lose his shot at owning a piece of history? Next, Corey checks out a 30-year-old Gibson guitar with a factory mistake. Can he pick up a sale, or will he get shredded? Then, a rare Mike Tyson Nintendo game punches into the shop. Can Chum knock out an offer, or will the seller put up a fight? And finally, Rick and Corey head out of the shop and into the desert to check out a restored WWII half-track. Will the father and son duo be able to target a deal, or will it blow up in their faces?', '2021-03-22', 42, '/g4YnyTpA9pSrbzS8Tb4vzLPxdGV.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
