INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'61F5430A85A448E5A1E4C5E87593D5B8', X'ABFE14EEDB424DDEA96A601FF3C53ECC', 3, 'Treachery', 'Cluny uses two treacherous foxes, Sela the vixen and her son Chickenhound, to plant a false attack plan in Redwall, while Matthias and his mousemaid friend Cornflower unravel the mysterious motto, "I am that is." It is an anagram for "I Matthias" written years before he was born, another clue for the quest for Martin''s sword. Cluny''s real underground attack is inventively repulsed by hot porridge and Matthias sees the fearful snake Asmodeus for the first time and realizes that somehow their fates are horribly intertwined.', '1999-09-12', NULL, '/3EpLJVg5KOJdBFaf5VShCWTRrWM.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
