INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'62604A4251D5482789E2910B9C073FE3', X'F07B879456254682AAE1E56966B4C7A8', 16, 'That''s Weird', 'The children think Ben’s Norwegian dancing and traditional costumes are weird. They soon learn that things that are new to them just might be interesting, not weird. Sizzle, likewise, finds Nuzzle chewing on a toy car weird. Skye and Jody do not appear in this episode.', '1996-02-05', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'62604AC4D8F34220B99A28CB9670C932', X'D3E13496E3C8490383B45A31FEDEE232', 14, 'The Fortuneteller', 'When the group tries to help a man who is being attacked by a platypus-bear, they discover that the local town has a fortuneteller named Aunt Wu in it, who has been forecasting the town''s fate for years. But when Sokka and Aang discover one of the fortuneteller''s most vital predictions is dead wrong, they have to develop a plan to convince the stubborn townspeople that their beloved Aunt Wu was wrong.', '2005-09-23', 25, '/leJKRM1LLF64in8IGs6NbRAyEmx.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'626580446A5B471BBB7A40702D1DE135', X'3FC7C152E4F6426AA89936EC454C4403', 45, 'Backwards to Forwards', 'During a game of Leap-Dragon, Zak and Wheezie accidentally hit a rock, sending it to one of the Backwards-Forwards Signs, and causing the entire Dragon Land to go backwards. When the mix-up becomes frustrating after a while, the gang must find a way to turn things around for them to go forwards again.', '2000-01-19', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
