INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6287D331402A4813B91507ED3228388C', X'3190D082877D4951BF7CED07EF560040', 4, 'Brush', 'Can inanimate things come to life, as the feature book suggests? LeVar finds out for himself in a factory where all the goods for the Macy''s Thanksgiving Day Parade are stored.', '1988-08-18', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6288F8AC672E46589F3EE5402DBAD513', X'F30BBF8187704E74B68B280E7C85B52F', 2, 'The Pony Remark', 'Jerry''s parents come to town for a 50th anniversary party. Jerry bets Kramer that he won''t complete his plans to renovate his apartment with levels in a month. Jerry takes Elaine to the dinner and he makes an observation about children who have ponies, this remark offends the guest of honor. When she dies soon afterwards, Jerry wonders if he should go to the funeral or go to his championship softball game. Elaine wonders about the fate of the apartment, when she hears the widower is moving to Arizona. George wonders if it will ever be possible for him to have sex again.', '1991-01-30', 23, '/sfIZKNBlfF6UgVpw1xT0LyPjhrP.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6297631E42684002A5D56F1C3B5BD667', X'543EC6DCC6C7447CB5A74484D9618391', 7, 'By the Book', 'Cat finally puts the finishing touches on her book before sharing some of the juiciest bits with the rest of the housewives, all of which inspires Michaele and her husband to seek a lucrative Book with author Matt Carson who eventually backs away from the deal. During a fun night with the housewives and their families, an argument between Cat and Stacie''s friend Erica breaks out and gets heated, bringing one of them to tears.', '2010-09-23', NULL, NULL, '2026-04-03T16:35:01Z', '2026-04-03T16:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6297FEEC797D469098454FF5A7AC4F59', X'A8C6182E05E14B6891A55126CF6C94F0', 19, 'Across the Delaware', 'James learns more about the captured British spy.', '2002-09-26', 30, '/wXoUSA3ps0ocW79tneKqwLZxWaK.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'62A4948993C348359F26F0515F5865D3', X'4FE93658C46343298E649D523869C2CB', 9, 'Hello Nurse', 'The Pawn Stars set their sites on a sharpshooter''s Kentucky Long Rifle from the Civil War. Will the seller shoot them straight on this deal or will he just be whistling Dixie? Then, Rick and Corey are presented with a very rare G.I. Joe Nurse doll from the 1960''s. Will Rick get ambushed, or will knowing be half the battle? And later, a man comes in looking to sell a set of silver dishes pilfered from Hitler''s mountain hideaway, The Eagles Nest. Will Rick bend the house rules buying an item of the infamous dictator or will this tableware be too hot to handle?', '2010-10-18', 21, '/baRHQ7fLCIFd1lk5JlWnY3ILfIT.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'62A5A22098FA4DD1A6878D3AC4384EBF', X'70C8CB4624944DD498F66BFB9B3FAF73', 1, 'Chum Goes AWOL', 'The Pawn Stars have an opportunity to buy a super fast AYT Speedboat in need of some serious TLC. But first they''ll have to strike up a deal and steer the restoration from plunging off into the deep. Then Corey meets a man interested in selling the first home audio system, an antique 1901 Edison Phonograph. But before Corey can make a sound deal, the Old Man examines the piece and makes sure Edison''s invention will ring out a profit. And later, Rick is presented with several pieces of small demonic sculptures cast in solid gold, but to Rick''s disbelief - all are painted black. Will Rick find that these little monsters are worth their weight in gold, or will the spirits compel him to cast these devils out?', '2010-01-18', 21, '/6YyV8kS2jISins9uxjUef2k2dVx.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
