INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'62CB04D8DAB949188141AD07C91B7DFB', X'79C64E0A348841BC9B5C2243FF15B373', 6, 'Star Signs and Bad Times', 'Rachel hosts a glamourous psychic soirée for the group and revelations come when Sutton presses Jennifer Tilly about her comments made to Kyle in Sedona. Boz travels to Nevada in hopes of continuing her fertility journey. Dorit confronts Amanda about her remarks on her marriage, but emotions run high when Amanda discloses it’s the anniversary of an unimaginable loss. Rachel’s friend Natalie Swanston Fuller joins the group.', '2026-01-22', NULL, '/jnRkPE8i1cNH0fLQm1MnOlRBWjU.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
