INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'63410BDF8197446BACFE3B4B100D11E5', X'AB509C47EC644FB3856003873DD0C37E', 15, 'The Highlights of 100 (2)', 'The conclusion of a two-part collection of highlights from the first 100 shows includes the characters'' concern about their self-images. Also: the evolution of "the contest"; how "marine biologist" George saved a beached whale.', '1995-02-02', 24, '/mckNSfzthlVvh3sIrEgcJzGaiSw.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6341676610674DA1A86F4D469B8E6F0A', X'05C0E384194C44179F62803EB615E409', 41, 'Rain in the Neighborhood of Make-Believe', 'Title number 0041. Opens with Mister Rogers arriving in a rain coat twirling a bag. Mister Rogers talks about sewing, and shows a needlepoint creation of the Neighborhood of Make-Believe. Corny, X and Henrietta have various reactions to the rain in the Neighborhood of Make-Believe. Lady Aberlin and X sing "Creation Duet".', '1968-04-15', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'63431D019A1E47619324A17F4CBB3C63', X'F63C3F6109704E3781CC2B9045A9952C', 59, 'The Jacket Fairy Returns (3974)', '', '2001-03-22', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6347E6227CF0455D9D2E2147CB7D27B1', X'22FFA982707041D7B3C811706A9B38A0', 2, 'Wishbone''s Dog Days of the West', 'In the dusty town of Chaparosa, Texas, one one knows how to tame the land better than Long Bill Longley and his best friend Tom Merwin. But, can our two heroes tame the resident bad guy, Calliope Catesby, before he destroys the town? Meanwhile, In Oakdale, Wanda Gilmore has also become quite a hero. That is, until a sneaky TV reporter tries to paint her as the town tyrant. Will Wishbone and his friends come to Wanda''s rescue before it''s too late! Or will Wanda watch her reputation ride off into the sunset?', '1998-03-13', 28, NULL, '2026-04-03T17:10:41Z', '2026-04-03T17:10:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'63498FCF3D4F4D6C95E103CC5516700E', X'D5383B3D56364D71B99CB84774B4B3C6', 6, 'Pingu Clears the Snow', 'When Pingu and Pinga get up and go outside, they discover that it’s snowed during the night, and everything outside is covered in snow. Father is clearing off the motorised sledge, and finding it heavy going. Pingu gets the snow shovel and starts to clear the snow away from around the sledge, as Father continues trying to clear the snow off it. Pingu also finds it heavy going, stops clearing the snow and thinks, and then goes inside the igloo. He returns brandishing the hair dryer. He starts to blow the snow off the front of the scooter, and has some success, but it’s not long before the dryer stops working and bursts apart. Pinga, who has been watching all this, calls excitedly to Mother, who rushes out. Mother is dismayed to see what has happened to the hair dryer. A bit later, Pingu is pondering the problem and goes out for a walk. He comes across a derelict abandoned igloo, and looks around. He has an idea, and starts to make repairs to the igloo. Robby comes along and offers to help, and it doesn’t take the two of them long to patch the igloo up, turning it into a weatherproof garage. Pingu and Robby are waiting when Father arrives home on the sledge that evening, and Pingu tells Father what they’ve done. Pingu and Robby get on the back of the sledge and Father drives to see the garage. Father is impressed and drives the sledge inside. It fits nicely. As Father comes out of the garage it starts to snow, and they congratulate themselves on a job well done.', '1998-01-09', 5, '/wVLam9mTwCBKNbLUqgeLj8NMVY5.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'634C7F2C40A747DC84CDC7632DE5DC43', X'90D7A60CD72F4AEA89C081DC1E187EFE', 6, 'Where the Devils Run Wild', 'Steve and Terri seek the Tasmanian tiger, thought to be extinct since the 1930s, as well as Tasmanian devils, copperhead snakes, black-faced shags, pademelon joeys and wombats.', '1998-04-12', 44, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
