INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'63667EE6343741A095FC164C66C8C82C', X'53587A7ECD9344F0AD795FE586DCCB8E', 8, 'The Bleepers', 'Kipper meets aliens from another planet. After an accident with their spacecraft, it''s up to Kipper to resolve the problem!', '1997-10-24', 9, '/ph4IXEcpIqS9lJwRewih0F6k29v.jpg', '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6366EF18DD82443EB5B35EAC50F23660', X'F5C042DC065742E8A37D247414140632', 6, 'Another One Bites the Crust', 'Tiffany throws an intimate pizza party in an attempt to get closer to the other women, but her obsession with rules and an ill-timed prank only push them further away. Stephanie goes over-budget on her first charity project, Kameron''s dog trainer stops by for an "accountability meeting," and D''Andra consults her shaman about the best way to deal with Kary.', '2021-02-09', NULL, '/nujOaysTUXBxkmu8lTSKBnBmDsF.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
