INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'637A6800A28F4CAFB66979CB511098D0', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 74, 'Episode 2039', 'Big Bird fantasizes about Maria and Gordon vanishing through impossible means—Maria swimming the Atlantic and Gordon catching a rocket to Mars—in order to teach subtraction. When reality returns and they''re actually gone, Bob becomes confused by Big Bird''s mysterious talk of his imaginative scenario. Maria later receives a handmade flower from Big Bird that lifts her spirits after a long day fixing a grandfather clock.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'637C651BA0C0473CBE582BAE63350AA7', X'EB7E3BB45746457781C6F5B2DC2EFC6E', 9, 'Bitter Work', 'Toph''s instructing abilities come into question when Aang cannot seem to overcome a block that keeps him from earthbending. Sokka gets himself in a jam, while befriending what was, moments before, his next meal, and Iroh and Zuko begin training utilizing new philosophies and methods that originate from the other elements.', '2006-06-02', 25, '/ilnwRuY533ZGv3JapxbZQGfxgyo.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'637F4FA78E46474BA85C45D35FB4BDAF', X'F5474771893041EBB0D4DB442233ACEE', 1, 'Crocs Down Under', 'The Australian Saltwater crocodile is the world’s largest terrestrial carnivore. Intrepid natural historian, Steve Irwin, journeys to Australia’s far northeastern corner to try and capture a nuisance crocodile and teach him a lesson before releasing him back into the wild. Set against the colorful backdrop of Australia’s Top End, the special shows that these often ferocious man-eaters have a gentler side that make them caring lovers and devoted parents.', '1997-01-01', 44, NULL, '2026-04-03T17:39:10Z', '2026-04-03T17:39:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
