INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'63990109C61C43C692371610FA0920B2', X'991E78F103A54D268F7575E11DB4243C', 8, 'Go-Stop-Go: A Visit with ''Arthur'' Creator, Marc Brown', 'Mr. Rogers visits Marc Brown, creator of the Arthur book series and shows him how he draws Arthur. After explaining how the TV show is made, they watch a clip of the episode "Arthur Meets Mister Rogers", which Rogers himself guest-starred on, and meet Michael Yarmush, who does the voice of Arthur and Arthur himself shows up in the Neighborhood of Make-Believe, greeting several neighbors — including Lady Elaine. Rogers views a video on how traffic lights are assembled.', '1999-04-05', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'639A16129CF54BF19B5FF70C5CC888A7', X'7C0E1F6688354E8A8AD90EEE57155B4C', 7, 'Escape From the Spirit World', 'After being shot by Azula''s lethal lightning attack, Aang falls into a deep slumber. Escape from the Spirit World explains that while Aang''s mind and body were immobile, his soul was trapped in the Spirit World. He encounters Princess Yue, the Moon Spirit, who informs him that if he does not reconnect with his past four lives, the Avatar Cycle will end.', '2007-09-11', 14, '/bzlmne0LEBfdScAKLmU7aJLyzhz.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
