INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'639EBCF75C1945C398F609417D6B66E5', X'6F731E6BD3C54DE684E17A19CB650E86', 33, 'Every Rose Has Its Pawn', 'Raise the American flag with the Pawn Stars when an original sketch of the Marine Corps War Memorial sculpts its way into the shop. Will Rick claim victory with his offer or will it become his enemy? Next, a Poison platinum disc signed by Bret Michaels rocks in. Will Rick make a glam metal deal or will it be a thorn in his side? Then, a Roman oil lamp from the first century lights its way in. Will Chum ignite a deal or will the flame burn out? And later, a military certificate from the Vietnam War shows up. Will Corey cash in or will it be worthless?', '2016-05-04', 21, '/H5pDfmzuwpSJfvgYbj1ZaOmtpX.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
