INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'63A771602ABE45A794FE117295224BE5', X'B6BAA6EC09084A4790017E7158985002', 4, 'Going Batty', 'When Ms. Frizzle invites the class’ parents in to see that their kids are learning about bats, Ralphie and the gang are convinced The Friz is a vampire! With Tyne Daly as Ralphie’s mom; Eartha Kitt as Keesha’s grandmother; Elliot Gould as Arnold’s dad; Dana Elcar as Phoebe’s dad; and Edward James Olmos as Carlos’s dad.', '1995-09-30', 25, '/lKpdSN346EScyTtUxDpRv8MxOaq.jpg', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
