INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'63DA1A0BDA13425E8F8D49E0E1699C4D', X'06030129FF2D4490B66C9F41BBE7AABD', 12, 'Woollen Mill', 'John''s woolly jumper is beginning to wear out, so he sets off to a mill to retrieve some wool to knit a new jumper. Meanwhile, Jim mistakes a sheep for a dragon, and is frightened, but soon learns that sheep are harmless. Then, Rosie and Jim finally get some coloured wool of their own.', '1990-11-19', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
