INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'63F41501AA4744DA8C888FACFF8AD690', X'03485B5EA5B7423EB21EC00E62216A35', 5, 'Bears For All Seasons', 'The cubs find something else to do in unseasonable weather.', '2004-09-08', NULL, NULL, '2026-04-03T17:40:22Z', '2026-04-03T17:40:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'63F6D43BB6824675B90A1D36D68E58ED', X'3982796B54514100904246BEDF6A20A5', 18, 'Pingu Cannot Lose', 'Pingu and Pinga are bowling. Pinga takes the first throw, and doesn’t score, but then rolls up herself and knocks all the skittles down. Pingu is not very amused; he is very surprised! Then Pingo comes by and has a go; he knocks down two skittles. Pingu throws and hits four. Pingo’s next throw gets one, and Pingu gets four again. Then Pingo gets two, and Pingu gets three, but this time his ball takes an odd path before reaching the skittles. A passer-by has a go and gets six. Pingu’s next ball goes straight, and he knocks over a skittle, but it stands up again. The passer-by gets another six and Pingu gets a one. The passer-by then gets seven, and Pingu walks away unhappily. Then the passer-by gets an eight. Robby, who has just arrived, gets one but his ball also takes an odd path before hitting the skittle. Robby thinks this is very funny. The passer-by then gets all nine skittles, and the others applaud. Robby’s next throw misses completely, as does Pingo’s. This time they all think this is funny. Pingu then has another try, but to throw he faces backwards and rolls the ball between his legs. Again his ball takes an odd route, misses, and ends up in front of the group of skittles. He has another throw. The ball hits the ball that’s already there, and both balls go round the outside of the group of skittles. They all find this extremely funny.', '1993-08-03', 5, '/z2FXzmDgzVdqyIqbv3QXeFD59kA.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
