INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'640B43C3E1244CDCA93A8A54E4339E59', X'DFE2C51C8D2C4C92A0107DBB71C3E48B', 11, 'Reptile', 'What is the oldest reptile species? Can a cold-blooded reptile freeze to death? REPTILE reveals the alien world of these often misunderstood cold-blooded vertebrates, uncovering reptilian facts that are stranger than fiction. From hot, steamy swamps to dry-as-bone deserts, travel the world in search of these amazing animals.', '1995-04-17', 29, '/mgaUX82WYCwPstqhr0KqK96TDrN.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'640CD07CB0DC4DF4B087A88C1EF38528', X'B2317FC31CFC4F19B181EFFA23959C6D', 7, 'Allegation Aggravation', 'Jennifer''s marital issues mount; the men dive deeper into Teresa''s relationship as guys'' night takes a dark turn; Margaret hosts a spa day to take Dolores'' mind off her mother''s surgery; Teresa''s anger threatens to ruin the day.', '2022-03-15', 43, '/qRMrtOU0T5Xm5SPSIiajj1mCpxw.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'640E86A607B44CDCB602FEF632FBA80D', X'F13CB62284E34654A8F10CEAB09A9CA6', 3, 'Franklin Loses a Book', 'Harriet has a favorite book called The Happy Green Frog and she wants Franklin to read it to her over and over. Franklin is okay with reading it at first, but when she keeps asking to hear it and ignoring all of her other books, he grows tired of it and hides it under a pile of newspapers. Later, the newspapers are taken out to the recycling... and the book exits with them! Franklin and Bear launch on a wild hunt throughout Woodland in the hope of finding another copy of the book to read to Harriet, but end up with a very creative solution to the problem.', '2002-05-06', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
