INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'644644BF5C684C3CB5BA2B2AD64EC4AE', X'10E64538C78A4CB082F917D14256DBAC', 24, 'The Show Must Go On', 'In the seventh-season finale, Frankie''s determined to ensure Brick can sing at his middle-school graduation after his performance is cut; and Sue feels conflicted after learning she needs to be at Dollywood on the same day as Brick''s ceremony. Meanwhile, Axl starts a new job as a country-club counselor and gets mocked by a 10-year-old version of himself.', '2016-05-18', 22, '/2kut3NfmzIJlwPvrCy76b1s9lAt.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
