INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'64562319132F4EE0AED138BD19BB8D0B', X'5BA20443D99F482081F66832D3F2BC4F', 8, 'Probability', 'Probability is a way to measure how likely it is that something will happen. Probabilities are predictions. They’re often just very careful guesses. When a scientist wants to calculate a probability, she or he gathers data and then uses the data to make her or his guess. Probabilities are between 100% (it’s definitely going to happen) and 0% (forget about it, pal, it’s not going to happen). Most things have a probability somewhere in between.', '1996-01-19', 26, '/vehWGKlFFZ1tDwbn9HVK8fSqOLA.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
