INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'64ACE8DB45D4471EB14854815103D513', X'1A534647384B4C00BB6CA3371AD962EB', 21, 'Crossing Chum', 'Get rewarded with the Pawn Stars when a 1965 Panama Canal service medal is presented to the shop. Will Rick keep his eyes on the prize or will he fail to complete his mission? Then, Corey sets his sights on a renaissance era crossbow. Will Corey hit a bulls eye or miss his target entirely? And later, Chumlee finds himself in hot water after he fails to call in an expert. Will his wacky sale turn a profit or will the joke be on him?', '2015-03-26', 21, '/aJz35oOLuP4va05jb4mPRoyAqb9.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
