INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'64AF2140217644FB8C826B422291A7EB', X'D6092173D23B4449BAFFE0E16FE56C9A', 9, 'The Hostess With The Least-est', 'As the Isle of Palms girls’ trip continues, the drama between Marlo and Kenya reaches new heights. Porsha’s heart is still focused on how she can continue her activism as she struggles to cope with the verdict in the Breonna Taylor murder case. Kandi makes sure Cynthia’s last days of singledom are celebrated with a dungeon style stripper party… including a very special surprise package.', '2021-02-14', 43, '/wFotX4Rtze7Jw49a9xmtFw4uIex.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'64B3B98025784408B8F2F68781B6D36B', X'3FC7C152E4F6426AA89936EC454C4403', 53, 'Quetzal''s Magic Pop-Up Book', 'When the gang uses Quetzal''s magic pop-up book to make up stories, they all talk at once, but nobody listens. They soon realize that by taking turns, everyone''s story gets to be heard.', '2000-01-25', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'64BF7C48131847F6A3FAA9D958787F38', X'6C1EC19F74DF4F359A6117B98175D826', 17, 'Reunion (1)', 'The ladies come together for a virtual sit-down to rehash a season of incredible highs and shocking lows, as they confront their issues and tackle viewers’ burning questions. Kyle and Garcelle waste no time airing their grievances, and their unresolved tension finally reaches its boiling point when Kyle drops a shocking accusation. Dorit and Sutton recount their awkward exchange at Lisa’s daughters’ clothing line launch event, but Dorit’s apology falls on deaf ears as Sutton challenges the motivations behind her comment. Frustrations come to a head when Erika and Lisa bring Denise to task for refusing to have an honest conversation and accuse her of manipulating the truth.', '2020-09-02', 43, '/67NFMMdzFLcLGNGln30BlT38I3h.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
