INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'64C25350E2E04326A99990743C5D61BE', X'1BB5392776F64ED39C415414AD0865CE', 9, 'The Abyss', 'Slagar reaches the abyss and forces the slaves across a rope bridge, cutting it away behind him. There is now no way for Matthias to pursue him. A full day and night behind the pursuers arrive at the abyss and are stopped dead, until Sir Harry comes their rescue by retrieving enough rope to cross the bottomless gorge.
