INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'64D23D54146C472E823CA1E84FFBA194', X'B1D55597D9D24EEEAB9546DBB163291A', 9, 'Pingu Plays Fish Tennis', 'It is time for Pingu and Pinga to go to bed but they have other ideas. First they play with their blocks and fakely fight over them, and then mum tells Pingu to brush his teeth and he goes by shuffling with the block boxes on his feet. Pingu brushes the bathtub instead of his teeth, then knocks Pinga''s potty, and mum finally manages to get them to go to the bedroom. At first they tried to leave when she wasn''t looking. They keep demanding things such as a teddy, pacifier, fish, or bottles. When she stops coming to their demands (though Pinga made one), they go out to find their exasperated mother asleep. They move her into the bedroom and finally go to sleep all together', '1988-10-29', 5, '/di7PLSt5aLtsnUmrMbSJcajiI4V.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
