INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'64E494EF89C54A78AAFC3378752B82E2', X'671BD4DA347040F99A0340FBA34D2B8E', 6, 'The Setup', 'Frankie''s mom stays with her after becoming ill; Sue suggests to Sean that they should set each other up on dates; Axl and Brick ponder what Mike actually does at the quarry.', '2017-11-07', 22, '/yqpanCQO4axA2wh59hZMFCJkq7f.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
