INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'64E57F56283542BFBDB9EF64EF18A685', X'F0F8B366CB3340B3A50FA1CA7780916F', 9, 'Ring Around the Rock', 'It''s Ma and Pa Gorg''s 513th anniversary, and they must get married again. But where''s the ring?', '1987-03-02', 24, '/xtROimI3f9dbw1B3lH5OL9tYsSU.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'64EA50C295F14167A6E238DBE4BFDA18', X'FE19A277AED844DFA4ACFC1C4E9941B4', 12, 'Baby Momma & Daddy Drama', 'Kim and Shereé return to the "scene of the crime" at FAB to make amends and to plan a surprise engagement party for Kandi and AJ. Meanwhile, Kandi, AJ and Kandi''s mom visit a marriage counselor to help ease the tension. Shereé’s finished samples for her She by Sheree line finally arrive, and she unveils them to Dwight for the first time. NeNe and her Uncle Mel travel back to her roots in Athens to give her book writer a glimpse into her life growing up. While in Athens, NeNe finds herself face-to-face with the man who claims to be her biological father.', '2009-10-15', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
