INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6522A9C0326E4C96AB3128F49E136F4F', X'D306A064E835417E85480CF806295F31', 10, 'Diamond Rings and Rumors', 'Larsa receives an unexpected package; Guerdy puts work aside to make time for family game night; Julia starts spreading the news about her adoption plans; at her engagement party, Nicole avoids her dad and defends her reputation against a rumor.', '2023-01-19', 44, '/rU8j3aBgMxqYkhWnT5zABaZjJjv.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'652722C14B2A4C2181C9A8C86B68202E', X'C9ADC698BE924DD794ADD8F6759361CA', 37, 'Episode 37', 'Rogers visits the dentist. In the Neighborhood of Make-Believe, John Reardon agrees to give Pilot Ito opera lessons. King Friday commissions an opera for Friday.', '1973-04-10', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'653C7B9DCEBE4636A417BBF81D906C9D', X'90CC8678A14F4D05BC1E54A3117895D5', 8, 'Like Father, Like Son', 'Bold has left White Deer Park and is enjoying his new independent life. He first meets Crow then a friendly female Badger called Shadow when he unintentionally enters her den. He catches a pheasant for her and they become friends. She warns him about the gamekeeper, which explains the abundance of pheasants and a lack of foxes. Shadow gets caught in a trap meant for him and stays to release her when the human is on his way. However as he chews through the wire it springs back, releasing her but catches him in the eye. Later when hunting for pheasants, unable to see out of his injured eye he does not notice the farmer until it is too late and Bold is shot.   Meanwhile back in White Deer Park, Charmer the remaining female cub of Fox and Vixen meets and befriends Ranger, Scarface''s son. Scarface kills Mrs Hare and so Mr Hare moves his family back onto Farthing land. The animals plot to kill Scarface by stealth the way he probably did to kill Dreamer. They elect Adder but make the mistake', '1994-02-25', 25, '/tLZVfphCKOlnhavzfFxAUnfQzIr.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'654551729BF94F59A63E29A6DA8C77AD', X'D9973960273B4A92A7DA62EFE8860D09', 2, 'A Snow Mountain of Trouble', 'Meredith''s birthday party comes to a cold ending when Jen and Mary get into a heated argument about Mary''s insensitivity towards Jen''s aunt. Whitney confronts Lisa about an incident at Whitney''s vow renewal. Meredith battles marriage problems.', '2020-11-18', 42, '/zjSO3um54aJfIbVTP1koFLRYC9L.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6548823D580E497DB2415A59268190F5', X'9C5608B2511148BCA9077F93472C1E03', 2, 'The Good Sport', 'After losing to Abby in several games of hot potato, Elmo turns to Telly for help in becoming better. He becomes so good that, the next time he plays Abby, he repeatedly wins; and then his newfound skill goes to his head, causing him to show off.', '2012-09-25', 58, '/csVHXtIaW9ilR5DUlAp17UV0DyJ.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'65498DE5EB4E4693AF80B87A4A43E72F', X'2AEBFAD431454BC19DEF5F1D5BDFCFC8', 18, 'The Boyfriend (2)', 'Jerry and Elaine compete for the attention of baseball''s Keith Hernandez, while Kramer and Newman investigate a spitting incident involving Hernandez.', '1992-02-12', 24, '/wEf06gmg5jb8anj0dpTiwvFNbFQ.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'654D32525D0C4B22BF7B778123F21BC5', X'90CC8678A14F4D05BC1E54A3117895D5', 10, 'Shadows', 'Bold arrives in the town with Crow and they continue to keep their bargain of feeding one another. While wandering the town for food Bold comes across a female fox but she doesn''t seem interested. The following night he sees her again and they hunt together and she, Whisper invites him back to her earth. However he can''t break his agreement with Crow so goes back to him. Crow frees him from his agreement so that Bold can be free to see Whisper and says that if they need each other, to leave food under the bush. Bold goes back with Whisper to her earth in the Church grounds and tells her his story when she thinks that he is old. She is honoured to know him, the son of the famous, heroic Farthing fox.   Meanwhile Friendly finds out that his sister Charmer is seeing Ranger and informs his parents. Fox is not happy about it and agrees to meet him. Ranger says that in a fight between the Blue foxes and the Farthing Wood animals he won''t fight for any side. A sad event leaves the animals gri', '1994-03-11', 25, '/jCocbimUBUrkLrGdVaWDlfxh0LH.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'655354A1EF8A4E67854B8F7B443967F5', X'871614062FCE4CD5A716AB2C19F08860', 1, 'Three More Little Pigs;The Ants And The Grasshopper', 'Lionel, Leona, and the Wolf each try their hand at writing a sequel to The Three Little Pigs, and Leona finds a way to work and play. Educational Goals: Highlights the joys of reading and introduces key literacy skills. Focuses on short u, the sound represented by the letter m, and synonyms for small (miniscule, little, petite, microscopic, tiny, teeny, diminutive, weeny).', '2010-09-20', 30, NULL, '2026-04-03T17:12:30Z', '2026-04-03T17:12:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
