INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'658947E4C80B413B9ECBC439584FC491', X'487FDBCDEC5A454E8268B50566EB8546', 1, 'The V.V.I.P.', 'The ladies of Dubai are back and bringing the heat. Caroline Stanbury and Sergio''s new home renovation puts their relationship to the test. Sara is ready to put her past behind her. Caroline Brooks brings her friend, Taleen, to Lesa''s Good Weather Girls brunch. Some of the ladies are confronted over disparaging comments they''ve made.', '2024-06-02', 43, '/rbVCP3OCg1q2WXfLKeXfdnWFs47.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
