INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'659C699AE73D443A9BDDC945935C018F', X'3430D88114A2497D9CF4351B78B6AA6A', 2, 'Postman Pat and the Suit of Armour', 'Garner Hall is opening to the public. Ted builds a shiny suit of metal armour and when he decides tries the suit on, he can''t see where he''s going! He crashes about, making an awful clanking noise!', '1997-04-10', 15, '/lo9QCjBQJoG1xvN0zO5uezQfQib.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'65A4370075AA403A92A07F648529D8E3', X'AE8F64D94B834147A44CBFE720381F8E', 7, 'Bears Try to Hibernate', 'There is a porridge shortage on Sesame Street! Telly runs to tell Baby Bear, but when he finds him, he is getting ready to hibernate until springtime when there is porridge again. What is Telly supposed to do for five months without a best friend? Telly and Baby bear set up a play date for the spring when Baby Bear wakes up.  Telly says goodbye and the bears try to go to sleep, but they are not tired! First, they try counting, but that does not work. Then they call Max Bear, a hibernation consultant. Max Bear arrives and tells the bears that their cottage is too warm. They must go outside where it is cold. The bears look for an empty cave or hollow tree and sing all about bears. Finally, they find a flower bed that they can dig a hole and sleep in called a den.  Telly and Chris see the bears digging and go outside to check on them. Max Bear says that they should eat something before they hibernate. Chris suggests cereal and goes to Hooper’s Store. When Chris comes back, they try the cereal and like it! In fact, the cereal is so good that they decide to eat it all winter long and not hibernate! Hooray! Baby Bear happily eats the cereal while spending time with his good friend Telly.', '2009-11-18', NULL, '/AqKU9pmvcr950VP0Iw8RT0TE1zA.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'65A65A8376C04D5E8D13BBD560092542', X'33825A1537DC4FF982BDCC720498149A', 13, 'One Fight in Bangkok', 'A close encounter with rescued elephants is a uniquely bonding experience for everyone. An exotic outdoor market proves to be a nose-holding experience, while a condom-themed restaurant is an eye-opening one. A trip to the infamous “Red Light District” shocks and surprises, leaving LeeAnne and Kameron at odds.', '2019-12-04', NULL, '/91pnsYst7pK71mLgDINZ0weebMZ.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
