INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'65CC9C3275864325B86EEBDB8EFB76E4', X'99A9678144CB4A5C910071E2A55B6B1A', 8, 'Family Vacation', 'With their upcoming nuptials rapidly approaching, Lauri and George decide to plan a family vacation. George and his daughters are accustomed to luxury travel, fine dining and staying in five Star hotels. This year, Lauri wants the family to “bond with nature” so she rents an RV and packs up the family to go camping in Yellowstone National Park in Wyoming.
