INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'663F2F43C8AF43198A536035984F3272', X'70CAC5CAFB7F4CB78C9B004D44124A1D', 5, 'Not Over It', 'Dolores begins to get serious about her new boyfriend and Margaret starts developing a shoe line. Teresa, Melissa, and Joe prepare for the Gorga''s tasting party but Melissa and Teresa get into a huge fight, threatening the progress of the restaurant.', '2017-11-01', 43, '/fGUrmzVR7V3CAfrJnS8loh19tem.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'66412006F4494D52BA9D0EAF826533BD', X'CA09391ADE6A4B2BAEFCC2EFBC80A106', 3, 'The Legend of the Indian Paintbrush', 'LeVar''s featured story is about a young Native American tribesman who finds his spiritual calling in life as a natural painter. His assignment is a special task that will influence him and his work have its memory last forever.', '1991-09-18', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
