INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'66DAFAEF76BB48F7B4D70925947C51E9', X'20D7138EEEA846A88ADA2B0F0EE1F674', 9, 'Episode 9', 'Meet Captain Webb-Foote and Vaniiuht Fannv Jones - not forget-tine Fiona and her amazing. ballet performed upside down with her head in a bucket.', '1982-10-11', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'66E17A6D8E344A1388A71FF94DB57CC8', X'3EE646E823AE4DECBBC6C7E6A210D55B', 3, 'Little Bird looks for a home', 'Telly talks to the viewer about all the things on Sesame Street he can be sure about every day: Oscar will always pop out of his can, Bob will get out of his apartment, Gordon will always come out of 123 Sesame Street, and Big Bird will always come out of his nest area.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'66E535FFFC40408C881DC996204B3DA7', X'4892E2AF46C14B4EAC81EAC161B5A347', 28, 'Episode 28', 'Today JOHN lights the first candle on the Advent Crown, PETER goes north to Beamish and rides on a Sheffield tram, and Britain''s top pet cats compete for the title Blue Peter Champion Top Cat 1977 and the silver trophy '' live'' in the studio.', '1977-12-15', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
