INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'66E9902C98E3493F8C34E37A2A1B58EE', X'4A8E3DB080684FF3942F91F45F665F20', 4, 'Farmer Ken''s Puzzle', 'Lionel plays a computer game called ""Farmer Ken''s Puzzle"", in which he must figure out how to get a hen, cat, and bag of seed, across a river one at a time. When Leona wants to play, Lionel refuses to let her, claiming: ""The box says ages 7 and up! Not 4 and down.""', '2000-04-06', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
