INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'66F398FA2A1F468E8CAFFC99A4F4D21A', X'97616D6E5C17449FA37655F1DA83D6C3', 11, 'Mister Rogers Talks About PETS', 'Mister Rogers returns with Bob Trow''s dog, Barney, which he has been pet-sitting overnight. He talks about the time he and Barney spent together and reflects on a long walk they took. Bob Trow then arrives at the house to pick up his dog.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'66F3E9EE2B6249B3A4F54F34FAE545A9', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 6, 'Up Up and Away!', 'It''s up, up and away with the Pawn Stars when Rick and Corey check out an original Superman costume. Can Rick''s super strength lift what the seller is asking or will archenemy "No Deal" rule the day? Then, Rick tries to program a good price for a retro computer and Corey is rocking and rolling over two vintage music posters. Later, Chumlee tickles the keys of a 1980s Rhodes piano, but if he can''t negotiate a good deal he may end up playing the blues.', '2017-04-24', 21, '/lV8W7hs20Ut5Cm1K3eGSJ7IgDN7.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'66F9C53758D949108E03D0BABBA94282', X'6F731E6BD3C54DE684E17A19CB650E86', 12, '70''s Pawn', 'Get groovy with some of the greatest items from the 1970s that the Pawn Stars have ever seen: a ginormous Richard Nixon head, a shoe possibly worn by Secretariat, a Mattel Electronic Football Game, a signed "Star Wars" script, some signed Arthur Ashe memorabilia, a couple of vintage Aerosmith tour t-shirts being sold by an original member of the band, and a flag from Apollo 16 that sends Rick out of this world.', '2015-11-29', 21, '/qSLyQSD8OuJ7e96kI0a45PycMgQ.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6703220CB1F24D6FA9C62A4100A67998', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 1, 'Camouflage Challenge', 'Elmo is taking pictures with his friends when they hear someone say something. It’s Camouflage Carla, played by Kyra Sedgwick! She is camouflaging and blending into the wall behind her. Elmo and Rosita want to camouflage too! Camouflage Carla tells them to join The Camouflage Club. All they have to do is pass the Camouflage Challenge and find six camouflaged things on Sesame Street in six minutes. First, they find a grasshopper that blends in with a bush. Next, they spot two butterflies that are camouflaged among the flowers. Then, they find a green lizard perched on a green leaf. Finally, they find two ladybugs camouflaged on Elmo’s red fur! Elmo takes a snapshot of each critter as they go on their adventure. At the end, they count six camouflaged things altogether. They passed the Camouflage Challenge! Carla gives each of them their very own uniform and Elmo and Rosita become full-fledged members of The Camouflage Club!', '2010-09-27', NULL, '/90GiA8fS0SWvbyrLzySCZwBIMsj.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
