INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'670704B1BFE0428099A603FA42C039ED', X'487FDBCDEC5A454E8268B50566EB8546', 4, 'Drama Queens', 'Caroline Stanbury''s new home is finally ready, but not before she and Sergio unravel from the stress of moving. Taleen''s eager to get back into her fitness career full-time. Sara''s new love interest is revealed. Ayan hosts a queens'' dinner party to celebrate the queens in her life, but it''s off with one of the ladies'' heads.', '2024-06-25', 43, '/qOV9Bm9LMOx4yS75JiQVkRcbL4e.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'670A4D5C21A145C1B4D9F1392B3DE722', X'D920EBAEF00A4E25ABFE40492C74DED6', 6, 'Silver, Slots & Robots', 'A seller comes in with an explosive pair of crutches. Will he walk out ahead? Then, Rick takes a swing at one of the first books written about baseball. Will he strike out, or will the deal be a homerun? And later, Corey and Chum try their luck on a seller’s antique wooden slot machine. Will they hit the jackpot, or lose it all?', '2019-12-09', 42, '/paoxFdiNJ9Rk4hTWWLLAZDeaz23.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'670B747182404B95B47326E3442DBE31', X'E291DF42D44F49E5BF812DF32EE4A30F', 17, 'The Tutter Family Reunion', 'The annual Tutter Family Reunion is held at the Big Blue House. Everyone works hard to get ready for this big occasion featuring Tutter''s huge family. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'670E2F6A62B2491BAB4DDBE75962251E', X'BC6D3E376E5E472D90AA4C6DF1F7DEF8', 8, 'Every Brown Revealed', 'The family compile photos and videos that demonstrate the strength of their relationships.', '2014-07-20', NULL, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6714F10B53F04EF5B28E2EB2F40FA47E', X'9193E795DA7C40ECB68FF63AA7D5174F', 108, 'Histories & Lore: The Red Keep', 'Joffrey Baratheon reveals the history and structure of the Red Keep, the main fortress of King’s Landing, from its construction by the Targaryens, to its hidden lower dungeons.', '2014-02-18', 4, '/pTWIjKCpG9LLAZvH21XoletY5JT.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6716FB58A09E471F8A4B051B0066DEF9', X'6F731E6BD3C54DE684E17A19CB650E86', 40, 'G.I. Pawn', 'Assemble the troops with the Pawn Stars when two rare G.I. Joe playsets lay siege to the shop. Will Rick make the deal his mission or will his offer be discharged? Next, Corey checks out a 1950s Chinese military motorcycle. Will he steer it towards a sale or will his offer be as small as the sidecar? Then, "the British are coming!" when a photograph and letter signed by poet Henry Wadsworth Longfellow rides in. Will Rick seal the deal or will he think twice about the price? And later, things get screwy when an antique Black and Decker drill bolts in. Will Corey fix up an offer or will he act like a tool?', '2016-06-29', 21, '/3Adz8lhFtoGyDtt3pxoocWQMWni.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
