INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'67489F96CD834CA884544851A1B18FB7', X'5DB3FF78E43948E18F67988ECBF85D17', 20, 'Dogtanian and the Blue Falcon', 'After foiling Richelieu''s plan to destroy the reputation of Queen Anne Dogtanian is training to become a musketeer. This involves running up, and falling off, a tree as well as slicing leaves. While resting on the grass Dogtanian explains to Pip that he can''t join the musketeers until a musketeer leaves the corps, coincidentally Aramis arrives seconds later to tell Dogtanian there''s now a vacant post. But Dogtanian will have to pass some tests: sword-fighting, horse riding, swimming and a trek through the forest in the middle of the night to find a hat...', '1982-02-12', 24, '/hYUxJjUQhLJJhgGOSm2K9T2eMVg.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
