INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'674C658311C14469A93FA96ACECEE862', X'4D2CAC0F38FD438B8AFAACF43952E535', 123, 'Episode 123', 'A magazine programme for younger viewers. Introduced by Leila Williams. Including Coins in Your Pocket: 4: Sovereigns and Bank Notes, a talk by R. J. Martin and Packi''s Balloon Adventures: 2: South America, written and drawn by Tony Hart.', '1961-02-20', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'674EFC58088D49048A9C1BE7752272D3', X'AD180412A5D64E4A8B49590334F2FC69', 7, 'The Long-Tailed Visitor', 'Awoken by roaring the animals slowly gather to watch as Trey fights with another stag to become leader of the herd. They hope that Trey loses as any other stag would probably treat them better but he doesn''t. While Fox is alone sleeping Bully and his rats pay him a visit and threaten his life while telling him that he should leave along with the Farthing animals. Fox refuses saying they''ll continue to fight them, surrounded by rats he fears the worst until they run away when they spot a badger on its way. Hurkel arrives to ask Fox if he wants to watch the stags fighting but when he smells rats in his earth Fox tells him to get Ranger to assemble all the foxes and Adder and Sinuous - they are going to attack the rat''s headquarters. They ask Spike where the headquarters are but he denies he knows where it is, luckily a hare tells them. When the animals return after a night of fighting, Dash believes they were chased by hunters and beagles until told it was through fighting rats. An exhau', '1995-11-09', 25, '/kbPnAlM1Yhd1IGwBnp88lOozj5y.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
