INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6790DC18D8C34B1E84E6D75CAFFD33D0', X'C06F15E31ABD4C6CA4EF93F3EB85CC89', 8, 'The Pointy End', 'Eddard and his men are betrayed and captured by the Lannisters. When word reaches Robb, he plans to go to war to rescue them. The White Walkers attack The Wall. Tyrion returns to his father with some new friends.', '2011-06-05', 59, '/hH0U1QISWGGjoFutvCLdw28MGiq.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6793880A9EE6481380CBCA928608ABF7', X'D9973960273B4A92A7DA62EFE8860D09', 5, 'Ladies Who Lunch', 'Mary’s luncheon ends in disaster when Jen accuses Mary of being racist and Mary accuses Heather of being two-faced. While Whitney deals with her daddy issues, Meredith’s marriage problems escalate and Lisa reflects on her own marriage. Heather, caught between two friends, attempts to smooth things over with Mary who is still hurting over the things Jen said about her.', '2020-12-09', 41, '/f1p24KmLTUMWiShTPbyhMQsj8iN.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
