INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'67D539037C9D4DF5A0B5C87CDF270739', X'DA06465B91544FEBA455374DF7DAB02F', 3, 'Health Food Game Show (4085)', 'Healthy Food   Spanish Word - gato   Location - Paris France   Number of the Day - 6. The letter "G" and the number 6; nutrition. Elmo plays the Healthy Foods Name Game, in which he has to find nutritious foods of various colors. Jeopardy! champ Ken Jennings joins Grover for a Health Moment, and reggae artist Wyclef Jean sings about healthy food with Cookie Monster.', '2005-04-06', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'67DD144FF6254557B5417691031EF8EE', X'C1DF0E9BE03E48E5A93061EE5EF85840', 6, 'The Shore Thing', 'Arthur and D.W. are obsessed with going to Aqualand. They beg their father to go with them, but David tells them that going to Ocean Zone would be more fun.', '2000-09-18', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
