INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'67E3FFF25F0B4243808066BD8D03D794', X'543EC6DCC6C7447CB5A74484D9618391', 11, 'Reunion (2)', 'The ladies of D.C. reunite in the second part of the reunion, and bring closure to the events that unraveled during the season.', '2010-10-21', NULL, NULL, '2026-04-03T16:35:01Z', '2026-04-03T16:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'67E67E3A2E6A4D8BB3C6C73170CA0086', X'CA19F89515144988A70995E84EAB7CEE', 7, 'Dueling and Dealing', 'A seller shoots for the moon, when he comes in with some Apollo 11 documents. Can Rick bring him down to earth before we have a problem? Then, a Harley Davidson 1962 Topper scoots into the shop. Can Chum get the bottom price on this bike? Next, Rick checks out a Renoir etching. Will it make a real impression, or is it too abstract? Finally, the stakes are high when the guys leave the shop for a little friendly competition. Will things get hairy for Rick, or scary for Corey?', '2020-12-21', 42, '/sNBxpLbNpWBrOO2FcXVeHjtThqx.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
