INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'67F9C9AB4CCA43C29816852435369B67', X'D920EBAEF00A4E25ABFE40492C74DED6', 12, 'Pawnanza', 'Saddle up with the Pawn Stars as they check out some vintage horse equipment. Will Corey say yay or neigh to the McClellan Saddle’ Next, a rare Pee-wee Herman scooter rides into the shop. Will the word of the day be “sold''” Then, a seller comes in looking for an offer on his signed poster from the TV show, “Bonanza”. Will Rick strike gold or will this deal be a “lode” of crap’ And later, a first edition of the classic book “To Kill a Mockingbird” flies in. Can Rick make a deal, or will he have to set this bird free’.', '2020-03-02', 42, '/iacnXEduSbF6A5fTL3bpM29JbCJ.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
