INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'68092648D43545A9B636DF6D60F2573E', X'7C542833ED0A42729C53E822408AB434', 9, 'Back to the Stone Age', 'Competition between Norman and Derek to make the best stone age shelter goes too far and causes a fire on Pontypandy Island.', '2024-10-10', 10, '/tWN4i8GWG39rYPQa6tI4Yar6kzv.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'680CA9B870194405AEB1F642436C0C4A', X'D5F0284F0EE345BF8539D02A825D15B2', 8, 'Palm Beach Pandemonium', 'The ladies play croquet in Palm Beach. Lisa is interrogated at dinner about her financial, parenting, and relationship choices. Nicole''s family expands in a way that she could have never imagined. Lenny files a motion citing Lisa as an unfit mother.', '2023-12-20', 44, '/dmShRheUxC2Szgq8QdKglAK4GF8.jpg', '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6810504B75D44CD8A084D115412B8FDA', X'42E591E22A884434AE9F3D4B1D685613', 1, 'Rick ''n'' Roll', 'Turn it up to 11 with the Pawn Stars when Rick attends Rock and Roll Fantasy Camp. Performing with rock legend Roger Daltrey of "The Who," will Rick hit all the right notes? Then, Chumlee and the Old Man check out a collection of tin toys from the early 1900s. Can they turn this play date into a payday? And later, a tonsillotome finds its way into the shop.', '2013-05-30', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
