INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'684B853C4A0845E9BADD85DEE6C98359', X'136B81D3964D4B8FA21492F00D96D6B9', 130, 'Sally Ride talks about being an astronaut', 'Astronaut Sally Ride visits Sesame Street to talk about her incredible experiences in space and what it''s truly like to be an astronaut. She explains her training regimen and emphasizes the importance of science and education. The kids are inspired by her achievements and courage.
