INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'685FBC5043E243159AB873570ADEBDB1', X'3EE646E823AE4DECBBC6C7E6A210D55B', 123, 'Grundgetta refuses to talk to Oscar', 'Oscar is disgusted by the bouquet of flowers Mike has gotten for Gina. He claims if he ever gave those to Grundgetta, she''d never speak to him again. Gina is happy to receive them and invites herself on Mike''s jog.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6860DB0E46134100A488F68CD2458EBA', X'3982796B54514100904246BEDF6A20A5', 25, 'Pingu Helps Around the House', 'Mother is ironing and feeling a bit harassed, as she realises that there’s a lot of clearing up and other jobs that need doing, and she asks Pingu if he could help. Pingu, who is reading, is not at all keen to help and suggests that Pinga should. Mother does not want Pinga to help because she''s too small though, but she helps anyway. But Pinga drops some on the floor on the way to the cupboard and Mother tells her off. Pinga bursts into tears and Mother comforts her. Mother then tells Pingu to help and gives him some large cloths to put away. Pingu balances them on his head, to the amusement of Pinga and the consternation of Mother, carries them on his head to the cupboard, puts them away and then goes back to his book. Mother then enlists Pingu’s help again, this time to wash the floor, and prepares a bucket of soapy water for Pingu to use. Pingu reluctantly comes over to do it, but then thinks it would be a good idea to make the water soapier, and does this when Mother is not looking. Pinga comes over to see what is going on, and Pingu covers her head with soapsuds from the bucket. Pinga goes over to Mother who wipes the suds off, and tells Pingu to get on with it. Mother then goes out with the washing. Pingu and Pinga play a game with the mop and washing cloth, then Mother comes to get Pingu to help her, leaving Pinga with the mopping to do. She accidentally knocks a blanket from the table into the bucket. When Mother and Pingu return, Pinga has finished mopping the floor and is busily playing with her toys. Later, Mother is cooking dinner when Father comes in. He greets them, and Mother goes to serve the dinner, but finds a nicely warmed blanket in the oven. Mother and Father blames Pingu and Pinga and they don''t get any supper! Pingu knows how to use it though. When Pingu and Pinga go to bed they snuggle into the warm blanket.', '1994-09-21', 5, '/zpNAI8ikjXBkknifGPbjcGIsLqL.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'68666BA8CE524B848DA50EC04DA225C4', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 126, 'Important reports from Telly', 'As Gordon prepares some breakfast, Telly interrupts the action with a Monster on the Spot message on the word important. The garfish film is interrupted for another report from Telly. He is stationed by the Fix-It Shop door to report on a story so up-to-the-minute that it has yet to even occur.
