INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'688F3EFE1FC54DF6BD7E670E4183C1AA', X'3269A890BBA94E6C9278F7EB38EB1720', 15, 'Fish', 'More than 22,000 different species of fish live in the oceans, lakes, and rivers of the world. Fish come in all shapes and sizes. Some eat water plants, some eat other fish. Lampreys and some jawless fish suck onto other fish for food. Stone fish live on ocean bottoms and camouflage themselves as rocks. Puffer fish blow themselves up like a balloon, only they’re covered with spines. There are tons of strange and cool-looking fish everywhere.', '1995-09-22', 26, '/aoGcwNXryDJY3lZBJDrYra9D83E.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
