INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6940D326874040078BEDD072079386A7', X'D920EBAEF00A4E25ABFE40492C74DED6', 28, 'Million Dollar Deal', 'A signed letter from a former president has Rick and Corey singing Sammy Davis Jr.''s praises. Will it get their official seal of approval? Next, a giant bird egg rolls into Rick''s coop. Can Rick hatch a plan to buy it before it flies away? Meanwhile, Corey steps back in time with a violin clock. Will the seller strike a chord, or will the deal fall flat? Later, Rick travels to London for a work of art, but a million-dollar asking price might break the Banksy.', '2020-07-27', 42, '/7lVRGPJoUCC21UgspjWJzMSS5hF.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
