INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'694B15D0DEDF45B5986487C0DC402B20', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 86, 'Forgetful Jones writes a book', 'Oscar creates a list of things he''s not going to do and wonders what he''s forgotten to avoid. Oscar teaches the Grouchketeers Spanish vocabulary they should never use, like "muchas gracias." Forgetful Jones borrows a hammer and nail for writing but gets pencil and paper instead, then completes a book titled "What I Remember" that Bob and Linda read and translate into sign language.
