INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'698B99A8518F465DAB3A4467EDEE30BD', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 15, 'Lock Stock and Two Nickel Barrels', 'Hit "The Big Trail" with the Pawn Stars when Rick gets offered a rare movie poster for John Wayne''s first film. Will the asking price scare Rick off, or will he saddle up anyway? Then, a vintage RC helicopter strikes Rick''s fancy. Will their negotiation take flight, or will this deal stay grounded? And later, Chum takes a shot at a couple of nickel plated pistols supposedly made by the most famous gunmaker of the victorian era. Will he meet the seller''s high asking price, or stick to his guns and prepare for a negotiating duel?', '2017-06-12', 21, '/nWjpcLvYmcd4HfHgfkfByb8jOMp.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
