INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'69AEB7670E7E4B8591EA63F834174B6D', X'D9973960273B4A92A7DA62EFE8860D09', 6, 'Sundance City', 'When Sundance arrives to Utah, it’s nonstop parties and celebrations for the ladies. When Whitney throws her husband, Justin, a 52nd birthday party, Jen and Mary finally call truce. Meredith helps her son Brooks prep for Salt Lake City’s very first fashion week while Heather is on the prowl for a one-night stand, with the help of Vanderpump Rules’ Utah natives Lala and Katie to assist. And while everyone is partying, Lisa is too busy planning Sundance parties for everyone else in Park City.', '2020-12-16', 42, '/vGH1LXpeW8g7tywTleQ1XvIQOdr.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'69B467E2BB454B10BDD12932681539FC', X'97D7FF20E6FF4DBBBCDDFD87A1D0FA4E', 5, 'Chum Goes to Hollywood', 'Rick tackles a football helmet signed by 28 Heisman Trophy winners - but can he manage to get the seller''s price a touch down? Then, Corey gears up to buy a devastatingly cool "Transformers" toy for the shop. Can he build a good deal, or will it all fall to pieces? Meanwhile, Rick tries not to go psycho over an Alfred Hitchcock poster that makes a cameo in the shop. And later, Chum travels to LA to iron out a deal for some vintage garb. Will he be able to thread the needle, or will his trip be oh sew pointless?', '2023-04-12', 41, '/9AAlGhMu7nvQy6dWEgeRn80tdTM.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
