INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'69B8A096840943708916E6731524B23B', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 5, 'What’s That Noise', 'Elmo is sleeping over at Maria and Luis'' apartment. When Elmo tries to sleep, he hears a strange noise. He calls them in, but the sounds stop when they listen.', '2010-10-01', NULL, '/kypRKo0BZx10eRFIFi29Qpjui2H.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'69BA9F0091D94072B86A0A7FAB09312C', X'3982796B54514100904246BEDF6A20A5', 14, 'Pingu the Apprentice Magician', 'Pingu is proudly presenting his magic tricks to Pinga and Pingi. He baffles them with the scarf and tube trick, he amazes them by disappearing from behind a sheet leaving only his hat and the sheet behind, and then reappearing in his trunk, and puzzles them with his hat trick. He then changes Pinga into a snowman, the snowman is given several different heads, such as Robby’s and Pingo’s, and finally appears headless; Pinga then reappears. Pinga is then made to disappear from inside a box put over her. Pingi is very puzzled until she sees how Pinga gets back inside the box. Pingu then shows his levitation trick, but unfortunately for him Pingi already knows how this is done and gets Pinga to cut the strings that support the sheet with scissors, much to Pingu''s annoyance. Pinga and Pingi laugh! Pingu finishes by folding up the sheet he used for the levitation trick and throwing it into the air, where it shimmers and then disappears. Pingu takes a bow, and Pingi and Pinga applaud.', '1993-06-29', 5, '/wwZogZAD6ZWe4UntBdFHAPrAMly.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
