INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'69FD63360D56436F9B23179D8112B96A', X'3EE646E823AE4DECBBC6C7E6A210D55B', 117, 'Savion gives tap lessons', 'Savion gives a lesson to Mike and Alex, who want to know how they can be just as good. Savion begins rapping about the importance of practice. Mike and Alex tap off to the library as Savion’s next student arrives – Linda, who brings Barkley.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6A00873ED6934AF791F2DFDBDB7CD848', X'A84AA42DE73840818DA91FAEC0209EE9', 22, 'Mother''s Day', 'Mother''s Day for Frankie is anything but serene when she finds herself doing more for Mike and the kids and less for herself. But she learns that the apple doesn''t fall far from the tree when she escapes the family for a few hours to go to her mom''s (Marsha Mason, "The Goodbye Girl," "Chapter Two") and ends up acting like a child by making her mom wait on her hand-and-foot. Meanwhile, Sue feels guilty when she steals a motivational magnet from a store whose message actually enticed her to shoplift it.', '2010-05-05', 22, '/tB2UPFzMyKpr9EdYjfjx42LfJPQ.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
