INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6A05D2B0A39941BB88382EB6493ADF98', X'6FD9FD9DE378411B94B176BA4BD518FE', 51, 'Episode 51', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-03-17', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6A05EC6B7B124AB4A6911B1D39ECE640', X'5A771F52FE964EA2B567A8DDE899059E', 23, 'In the Presence of Greatness', 'Rick and Chum grapple with a Batman utility belt toy from the 1960s. Will they be hooked into buying it? A gorgeous Mosrite electric guitar shocks everyone at the shop, but will Corey and the seller be in tune when it comes to making a deal? Rick continues his hunt for "The Object," an item featured in the album art for Led Zeppelin''s album "Presence." When one that''s for sale ends up on his counter, can he be objective about this object of his desire? Later, an autograph book signed by 41 comic book artists draws Corey''s attention. Will he sign on the dotted line after drawn out negotiations?', '2018-03-05', 21, '/wJj2PaOkrKp4wajZWMYm5Q6Ssuk.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
