INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6A87E519B6594A0588D36235052E86C2', X'4D2CAC0F38FD438B8AFAACF43952E535', 176, 'Episode 176', 'A magazine programme for younger viewers. Introduced by Christopher Trace. Including Letter X in the Blue Peter Alphabet.', '1962-03-19', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6A8B198883A943318D08857009FC369A', X'6F731E6BD3C54DE684E17A19CB650E86', 11, 'Money Makers', 'It''s time to break out that wallet and revisit some of the most expensive items in the shop as Pawn Stars pony up for some big money relics: a 1961 Fender Stratocaster Guitar, a supposed Edward Hopper charcoal study, a few pieces of Rocky Marciano memorabilia, some Mickey Mouse display items, a Ford Model A hot rod, an incredibly rare American coin, a Star Wars collection and a balloon that makes Rick think Corey is full of hot air.', '2015-11-22', 21, '/h2O8xDx5z2TIf6sL3hlRhPf2FE9.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6A913E3CD0D8428F840828049A827B1B', X'8C0F12E153794A27ACA2B69401A33B0F', 36, 'D.W.''s Very Bad Mood', '', '1998-04-15', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6A9579C6745E467394D6AC35FBE8206D', X'6F731E6BD3C54DE684E17A19CB650E86', 17, 'The Star Wars Vault', 'Take a look back at some of the best and most unique Star Wars related memorabilia to come through the Pawn Shop. An original "Revenge of the Jedi" poster, a set of 1978 Kenner Star Wars action figures, a Jabba the Hutt Play-Doh set and a rare grouping of Star Wars movie props including a Stormtrooper blaster. The force is strong with some of these items; others were relegated to the dark side of the deal.', '2015-12-10', 21, '/6Z8Z7ei0FjlzwYn4TJ1p5BpDQEB.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6A9BDDBD956A4D4E827574925F4A3E4E', X'97D7FF20E6FF4DBBBCDDFD87A1D0FA4E', 11, 'The Big Dig', 'Time''s a-ticking when a seller brings a Mr. T wall clock to the shop. Will Rick and Corey see gold, or will they pity the fool? Then, Rick checks out James Bond''s credit card from the 2006 movie "Casino Royale." Will the asking price make the sky fall, or will Harrison, Rick Harrison get the license to pawn? Meanwhile, Corey plays with an Atomic Cannon toy. But will this opportunity go nuclear? And later, Chum and Rick get down and dirty in Texas looking for fossils. But can they dig up a deal, or will they get left in the dust?', '2023-05-24', 41, '/gazuNGNgZV51QoXJTYXqPux6GT.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6AB183F0004341CABDEDA3146D54B6C5', X'F829D1FB64EA430F8E0EB3345653A542', 2, 'Casper: The White Crocodile', 'Eleven crocodiles must be relocated at the zoo, so Steve develops a new method to capture them. Also:  an extremely ornery white crocodile named Casper is introduced at the zoo and proves to be aggressive towards a female.', '2003-06-10', 44, NULL, '2026-04-03T17:39:12Z', '2026-04-03T17:39:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6AB3A3C6120C4F529B7225E6963CEA6C', X'F63C3F6109704E3781CC2B9045A9952C', 19, 'Baby Bear Is Afraid Of Getting His Hair Cut (Repeat) (3934)', '', '2001-01-25', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6AB5201960624137B6EE5835DD7D5563', X'E291DF42D44F49E5BF812DF32EE4A30F', 7, 'It''s All About You', 'Tutter receives a postcard in the mail from his Uncle Jet Setter Tutter. He''s a famous explorer, but he hasn''t seen Tutter since he was just a baby mouse. He wants Tutter to write back and tell him all about himself. Tutter''s worried that he''ll have nothing to say, but Bear helps him to see that there''s a lot that''s unique about him. He also talks with Pip and Pop, who have noticed that they''re not quite as alike as they thought. Bear tells them that even though they''re different, they can still be great friends. He also helps Treelo to come up with a game that suits his own unique personality when he gets bored with playing Ojo''s tea-party game. In the Shadow segment, Shadow retells the story of the ugly duckling. She talks about another ugly duckling who didn''t grow up with dashing good looks, but found that beauty is in the eye of the beholder. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6AB6A8944D154A02B6928461A7464B4D', X'93651310A84F42EFBCB7AB8F788F102D', 2, 'Hurricane Adriana', 'Adriana and Lea''s feud comes to a head; Romain has a question for Joanna that may jeopardize their wedding; Lisa has problems with the property she''s buying.', '2013-08-19', 44, '/5meBCLIK0BEhXqMrEJFanlULCeP.jpg', '2026-04-03T16:35:10Z', '2026-04-03T16:35:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
