INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6AC5C1F3F7414B1B9339B3454C37D2A0', X'8BAE6AA34B554FA6BC158F4317BD1F13', 22, 'Arts Foundation Pt 2', 'Andrew Wyeth illustrates to Rogers the work behind an animated film based on Rogers'' song "You''ve Got To Do It". The Neighborhood of Make-Believe establishes the King Friday and Queen Sara Saturday Foundation for the Performing Arts.', '1972-03-21', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6AD13E4DB8054597B292332E030E2DBF', X'937EE587E2EB46AA9A693D6BAB04398F', 8, 'Best Friends', 'The best of friends are those whose friendships endure everything. And it extends to all walks of life, particularly to dogs. Liza Siegler reads the story of two girls who are best friends, but their relationship is strained when one girl goes on a vacation with relatives and the other girl feels lonely and neglected, until a new neighbor moves in and asks her to help him look after his dog.', '1987-07-01', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6AD33C9E7D8F4B35978B0E0E9E11F75D', X'F4C403079B5E4263A4E0DFA138131E7F', 24, 'Elmo''s World: Wake Up With Elmo', 'Waking up is easier when your friend Elmo is there to help you greet the day! Join him as he learns all about sleep, getting dressed, and teeth. With a dancing shade, a mischievous drawer, a frisky television and a playful computer, Elmo''s World is the perfect place for preschoolers to learn all about the world around them, And Elmo has help from his friends Bert & Ernie, Mr. Noodle and the Count to aswner questions like "how do you go to sleep,?" "how do you button a shirt?" and "how do you taken care of your teeth?" In Elmo''s World, learning is always fun! 50 minutes.', '2002-05-14', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
