INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6B2C4C5C32304958AAE660E350492982', X'BB5A884361814A6DBFDF33EF2C6BE7B8', 7, 'Rock the Boat', 'Cynthia and Peter reunite to discuss business moves in Atlanta, while her date on a boat with Will gets rocked when Kandi and Todd go fishing for the truth. Meanwhile, Porsha embarks on her first blind date and Kandi confronts the challenges of raising a teenager as she tries to enjoy some much needed family time. Shereé finally tackles a personal goal but an unexpected phone call leaves her wondering if her new love is strong enough to stand the test of time.', '2017-12-17', 43, '/yHYszYNPX4GuzcCwiQMj7Jj67Zi.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6B33D73E62A041B299CF552939E52596', X'E38E9D8714324A1AA7D064A559BF7570', 1, 'The Wood In Danger', 'With the animals'' homes being destroyed by man, all of the animals of Farthing Wood meet in Badger''s earth to try to find a way to survive. The latecomer Toad, suggests that they all journey to a nature reserve called White Deer Park, where he had passed by on his journey home. The animals eventually all agree to make the journey to this new haven once they take the ancient Wood Oath, of Mutual Protection. This Oath meant that everyone promised not to eat or frighten each other. Fox is assigned as their leader and it is agreed that they will meet by the Great Oak at midnight to begin their long journey.', '1993-01-03', 24, '/lRYIWJC2mNt96HgdRtwpUKYtG0G.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
