INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6B4EB0F22FE14AFB852CE3CB055F0070', X'EA1650C2E4F146C793BA74B5D45D08E5', 2, 'Model Behavior', 'NeNe attends Atlanta''s Dogwood Festival with her friend Cynthia and gives her side of the showdown with Dwight. Cynthia, a model who has recently relocated to Atlanta, lends a sympathetic ear. But NeNe’s troubles don’t end there. Her home life is crumbling, having recently thrown Brice out of the house. Sheree agrees to go on a blind date with a doctor, and surprises herself when she enjoys the dance club he takes her that’s located in the wrong part of town. Kim is invited to perform at the White Party, a huge gay circuit party in Palm Springs. Meanwhile, Kandi records a hot track with multi-platinum artist, Ne-Yo and then decides to test out some new material at Atlanta hot spot, Uptown Supper Club, which is owned by Cynthia and her boyfriend, Peter.', '2010-10-11', 44, '/swlK306cLgzYWpe2IEQiK2ZczFs.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
