INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6B873B47A89746D6A0B11FCE184ABFA4', X'1D713CA64E174F84949C8CFD98514127', 11, 'Bo Knows', 'Read between the lines with the Pawn Stars when an etching by Pablo Picasso traces into the shop. Will Rick be able to draw a line under the deal or is the piece just too sketchy? Then, Corey and Chumlee swing for the fences with a bat signed by legendary athlete Bo Jackson. Can they hit a home run or will the guys strike out? And later, Rick is surprised when Chum is the first member of his new book club. Will they be able to get on the same page or would Rick be right to judge a book by its cover?', '2014-08-14', 21, '/7teLWF3gFXbDZ2bkcjtxXyYbmNK.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
