INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6BCBCBB45D0A44FC8AFC99B49B3CFF86', X'8012F05A66A34254885F0A679393F3DD', 8, 'Four Days of the Cockatoo (4)', 'Gaby is taken to the smugglers hide their she encounters two wanted criminals Adoment Poulet and Honey Hawke who have been smuggling endangered birds into the country and skinning them alive. Gaby leaves a message for the team but before she can finish she is captured and put in a giant bird cage. The team learns of Gaby''s whereabouts and meet up with the real agents from the animal rights society. They discover where Gaby is and heads straight for the kidnappers lair. Poulet and Hawke are captured and Gaby gives the bird to the agents so they can help restore its species.', '1994-11-20', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
