INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6CB19ED4BC5B48E6B269F5864AFFE738', X'F812042DEB85432E80473675886E0B1B', 20, 'Mixed Breeds', 'Secrets abound in all people.  Wanda and Mr. Pruitt find that out themselves, as does Wishbone in his visions of Dr. Jekyll and Mr. Hyde.', '1995-11-03', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
