INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6CC422D7D69845D0A3A1CDE82158A52B', X'A31FA1D7D6494846A81F4F34B6FB3331', 25, 'Paddington in Touch', 'Paddington goes to a rugby match.', '1980-04-15', NULL, NULL, '2026-04-03T17:22:53Z', '2026-04-03T17:22:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6CCA635FDE8844CB89CBF7A37218C432', X'E48599F866FF4C0F927465B9AE1CDA9E', 79, 'Episode 79', 'See How They Fall!  Lesley demolishes ten chimneys and creates an industrial world record with "Blue Peter"''s biggest ever blast-off.', '1977-06-27', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6CCB708949334EC79A20825AEE2483EE', X'941B8C6544544336BE7C1D0591C12F90', 19, 'Stinky Pingu', 'Pingu and Pinga have breakfast, but the breakfast is fish porridge, which Pingu doesn''t like. Mother is not pleased, and she tells him to eat it. Pinga eats hers, and Pingu offers her his porridge, but she declines. As she has finished, Mother allows her to leave the table, but Mother won’t let Pingu leave the table because he hasn''t eaten his porridge. This does not please him so, when Mother goes into another room, Pingu craftily puts the fish porridge into his backpack in order to fool her into thinking that he has eaten it. He then goes outside taking the backpack with him. He comes across Robby and tries to give him the fish porridge, but Robby takes one sniff of it and refuses. They then have a scuffle, and Pingu gets covered with the stuff. Pingu then goes home, but as he’s passing Grandfather’s igloo, Grandfather empties a basin out of the window and onto Pingu. Then Pingu trips over a dustbin and gets quite a bit of the smelly contents on him. All the neighbours he encounters on the way home are affected by the smell as he goes past (including Pingo, who is knocked out by the smell and revived by smelling salts; another one falls down a pool of water, a possible reference to Pingu and the Barrel Organ when a penguin looks up and doesn''t realize a pool of water in front of him/her,he/she falls in). Even the carrot on the snowman falls off! When he arrives home he gets in the bath though Pinga is already in it. After getting clean, he and his family sit down for dinner, but dinner is fish porridge again! Pingu tells Father the truth. Then Father tells it to Mother. Fortunately, Mom gives Pingu a roast fish instead.', '2004-01-28', 5, '/m9VuMmBxGCZCAmHudhRNTud2YzE.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
