INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6CD7925FBA5347F49723DCA442B5A733', X'BB919AEC0D5C4C589A5AFA2A0A5DE2B6', 5, 'Episode 410', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6CDA3F7CB02044268D8514A91F699E92', X'3982796B54514100904246BEDF6A20A5', 22, 'Pingu on the School Trip', 'The school class goes to see a sculptor, who is carving a giant whale. On the way, Pingg throws a snowball at Pingu that hits him on the head. When Pingu retaliates, his snowball hits the schoolmaster, earning Pingu a ticking off. When the class arrive at the sculpture they all look round. Pingg decides to help the sculptor, who is shaping the head, by carving some more on the body. This does not amuse the sculptor. On the other side of the sculpture Pingo has decided to climb the scaffolding, despite Pingu’s protests. When he gets to the top he calls out, which attracts the attention of the schoolmaster, who tells him to get down. The sculptor gives a talk to the class about the sculpture, but Pingg has slipped away and has climbed up on to the tail of the whale sculpture. He gleefully bounces up and down on it and part of it breaks off, crashing to the ground. Pingg just manages to save himself from falling by grabbing the edge of the remaining part of the tail, leaving him hanging on precariously. Pingo gets a long pole to try to help him get down, but it won’t reach, and the schoolmaster goes up onto the top of the whale but can’t get to the tail to help. The sculptor is muttering away to himself about the broken tail. Pingu comes up with a plan and, using some poles and a tarpaulin, the class build a slide that Pingg can use to come down. He lets go of the tail and slides down safely. Once the class have finished congratulating Pingo and themselves, they notice that the schoolmaster is still stuck on top of the sculpture!', '1994-08-31', 5, '/exlLtCOPXvTIgOXAJMYTuEENKKL.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6CE63A6FF1C2487582AB7007BD4A1A14', X'F812042DEB85432E80473675886E0B1B', 3, 'Twisted Tail', 'A crime wave hits Oakdale, making the kids selective in choosing friends and giving Wishbone a chance to dream of Oliver Twist.', '1995-03-25', 28, '/4ChzEWwk4shgTgfmiOpY8IBevx4.jpg', '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
