INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6CF656BACA4B45F4A540906395EAF161', X'33825A1537DC4FF982BDCC720498149A', 8, 'Guess Who''s Coming to Happy Hour?', 'A death in the family has Brandi hosting a funeral for a beloved Redmond, while Mama Dee refuses to help D’Andra with the failing family business. Kameron spins in circles when two of the ladies back out of her couples shower for LeeAnne. But Kameron sends everyone spinning, when she crashes Kary''s girls night with other uninvited guests in tow.', '2019-10-23', NULL, '/ldc2UQmqWMD3x39NMoevlrxjMrU.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
