INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6D003791A93441B8BAF3EB070AD9931E', X'4F18AC4C8757456CA49A224F00E6A9F7', 11, 'Big Bird and Snuffy Talent Show', 'Big Bird and Snuffy welcome the viewer to Sesame Street, and to the Big Bird and Snuffy Talent Show! They realize that they don''t know what a talent show is, so they ask Leela to fill them in. Big Bird and Snuffy agree to have Leela be the first guest on their talent show, but she needs to get to work at the laundromat. Thinking quickly, she decides to juggle an apple and an orange, and Big Bird has her sing the alphabet song while doing so.', '2008-09-26', NULL, '/pzET0igHgwwVp9Ec82JR1907GSy.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6D04C779704D4BF29C1496A0CDEEF6F8', X'A8C6182E05E14B6891A55126CF6C94F0', 3, 'United We Stand', 'Moses lets James report on Congress and after a British sailor is ""tarred and feathered,"" James learns about the ugliness of mob rule, when emotions get in the way of compassion. Sarah and Henri meet Abigail Adams and travel with her to bring supplies and pamphlets to the occupied city of Boston. Sarah immediately finds in Abigail a strong female role model to look up to.', '2002-09-04', 30, '/rvQVeHkkQrDBAqkuY2oezwrGxj2.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
