INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6D926EFD7B5C4BC08ACC8582180239A0', X'36E5C604FEA94BCF834371BFAF60ECD2', 16, 'Is Anybody Listening', 'Theodore thinks that the pilot boats who patrol the harbor never seem to listen to anybody, and they don''t. But soon though, the pilot boats learn a valuable lesson about not listening.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6D9C773A9BE64FCA95B83ED5F7E23008', X'BB5A884361814A6DBFDF33EF2C6BE7B8', 19, 'Reunion (1)', 'The ladies are left speechless over a shocking revelation. Plus, Porsha and Kandi get into a heated exchange when they try to work through their buried issues. Meanwhile, Kenya tries to keep the details of her marriage hidden behind closed doors.', '2018-04-08', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
