INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6DA2FB7CE7504290A36B3C5F800A8897', X'BF3FFAFD7D454F2C9F1B28001BD082DB', 31, 'Episode 31', 'The Blue Peter Flying Ballet - see what goes on behind the scenes at Christmas shows all over Britain to enable characters like Peter Pan to fly.  Join in carols around the tree with the Band of the Chalk Farm Branch of the Salvation Army, and hear the latest news of the Blue Peter '' Three Bs '' Appeal.', '1974-12-23', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6DAA058BED40489FA2BEBB7D13118077', X'4FE93658C46343298E649D523869C2CB', 29, 'Going Postal', 'Make money with the Pawn Stars as they are presented with a one of a kind U.S. postage printing plate from 1862. Will the guys trek through rain or heat or gloom of night to make a deal or will they return this one to sender? Then, a guy comes in with a rare recording of a speech given by Dr. Martin Luther King Jr. Made just months before his assassination, will Rick stand strong and buy this American icon''s recording or will the tiniest scratch make it all worth skipping? And later, Rick and Chumlee encounter a Star Wars collector''s dream, a recalled poster for Return of the Jedi. Will Rick use the force and battle for this holy grail of galactic memorabilia or will a tough negotiation have him retreating to a galaxy far far away?', '2011-03-28', 21, '/eSycdErnQe9C6StLJOLr4NPEYBe.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6DAE1000EFEF47228A2EBD438252B827', X'A4843A51AEEF427C902C7FB3BD670CD4', 15, 'Summer Cooler', 'It''s a hot summer day and Bear and everyone else in the Big Blue House are taking it easy. Bear receives a checkers set in the mail and plays checkers with both Pip and Pop and Treelo. To his surprise, they win handily, despite never having played the game before. They seem to have developed a wild move to take all of Bear''s checkers in a single flurry of jumps. Pip and Pop also beat the heat by hanging out at the Otter Pond. They''re later joined by Ojo, Treelo and Bear, but Tutter has own way of staying cool. He''s created his very own Club Tutter in the kitchen, using the sink as a swimming pool. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6DAF2F538621465B99A6628DD6AB3AD6', X'136B81D3964D4B8FA21492F00D96D6B9', 52, 'Basketball practice', 'Donna practices for her school basketball tryouts with Gordon''s help while Oscar prepares for the Grouch team. Julius Erving surprisingly emerges from Oscar''s trash can.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6DB49D4FC4034144BB261F443DFA34B9', X'C4717644555D4DF1AEC0C095B101E7C0', 8, 'Stellaluna', 'LeVar discusses bats and the importance of sleep. The featured story is of a bat who is separated from her family and adopted by a bird.', '1994-10-12', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6DB96D35E145409DBDCCE71A6C4D1164', X'650BAC937B5941FCB277DC6F8BDCD7BB', 19, 'The Confirmation', 'Frankie and Mike send Brick to Reverend TimTom''s Wilderness Jesus Jam weekend camp to brush up on his religious knowledge in preparation for his confirmation, but Brick discovers his bunkmate is the boy who he was switched at birth with that was raised by his parents for the first month of his life.', '2017-04-11', 22, '/8EZqtU3V6hO1KwjsNRnHAvE0poI.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6DBD79027FD049DE9CF5299887F56C7A', X'136B81D3964D4B8FA21492F00D96D6B9', 5, 'Maria helps Forgetful remember things by writing them down', 'Maria teaches Forgetful Jones to remember by writing things down, asking him to jot down the number seven and other information. However, Forgetful ends up with piles of papers for everything he wants to remember, leaving him buried under his own notes by evening.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6DBF68F23DF04E9C8162427A55DDAB20', X'050D8AE16CC14018933DB3C3D13DE856', 15, 'Episode 15', 'Hocus Pocus!
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6DC0BFF7592F4469BF997DC8B423AF2C', X'5B72E664D3D7435DBDC3A23D29D1178E', 3, 'Spring Clean', 'Dusty windows remind Old Bear that it’s time for a little spring-cleaning. All the toys lend a hand and find that cleaning can be fun. They even tie dusters to their feet and skate away the dust. Old Bear’s suggestion; that they try a little airborne dusting, works well at first but soon it looks as if it might end up with a rather bumpy landing. Luckily, Little Bear’s clever plan brings them safely back down to earth.', '1994-09-20', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6DCF94229F2841F586931F56A0880F32', X'89BA90EC2C794A12A11D7465D1757683', 11, 'Rick and Morty The Non-Canonical Adventures: E.T. the Extra-Terrestrial', 'A claymation recreation of a classic scene from ‘E.T. the Extra-Terrestrial’.', '2017-07-11', 1, '/eaKPq33DZFzqInw7aTkR1brEWjd.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6DD67CAD415240AD80A9735DE617933D', X'B5AB3A72BC794E9BA53196739AFD7AEA', 5, 'The Hamish', 'Nobody really knows what the floppy tartan cloth object that Emily has brought is, except Bagpuss.  He says it is a small soft Hamish, a Highland beast that keeps its distance because it makes a terrible noise, like bagpipes played backwards.  He tells a heart-rending story of Tavish McTavish, who also made a terrible noise, playing his bagpipes forwards, and his friendship with the Hamish.', '1974-03-12', 15, NULL, '2026-04-03T17:23:58Z', '2026-04-03T17:23:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
