INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6E2B0EE3DEED4B9E8EA551CB44AA36E0', X'787DFA0BC8274DADA82D0548A6534D88', 19, 'Baptism by Fire', 'In the season finale, the ladies gather together to witness Tamra''s baptism, but with the constant questions and confusion surrounding Brooks'' cancer, Vicki is the one who feels crucified. And after an evening of avoidance, Shannon and Vicki come face-to-face when Shannon discovers that Vicki has committed the ultimate betrayal.', '2015-10-12', 44, '/i1viD6e28YX41blDtfJjHbgyVWg.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6E2E9D5C12A14A5D95016B80CF8DC203', X'18DA994319634E04A7A0AE63802BB1FA', 7, 'She Said/She Said', 'Hijinks ensue when Vicki decides to celebrate her birthday with a ladies’ golf outing. Tamra and Eddie double date with Emily and her husband, in order to get to know Shane. Kelly tries to teach her daughter Jolie the value of money and the two volunteer at a homeless shelter. A rumor about Emily’s marriage sparks an unexpected confrontation between Tamra and Shannon.', '2018-08-27', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6E2ED2B55EC04B0AA3E3F7BCA49A1BA5', X'B2317FC31CFC4F19B181EFFA23959C6D', 14, 'Reunion (1)', 'Dolores and Jennifer go head-to-head; a rift forms between the Gorga and the Giudice families because of Melissa''s feelings over not being asked to be Teresa''s bridesmaid.', '2022-05-03', 43, '/ghEfOfae6oKSPsTj0OL593AHbfW.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6E373E3EC33C474FAED9AE44D269BE33', X'6FEDBA8252F34184BE776B26E556CD0E', 16, 'Trouble at No.32', 'Paddington breaks Mr. Curry''s bedroom window during a snowball fight with Jonathan and Judy.', '1976-12-23', NULL, NULL, '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6E38DF9CB7DD43179B5D367BF261BB1A', X'78A02D50E3DC4549844A3CF357A32EF4', 23, 'Reunion Part Three', 'The men join the conversation to weigh in on the drama of the season – including Bob addressing his shortcomings in his relationship with Shereé, and Todd revealing he still has a bone to pick with Phaedra. Cynthia and Peter reveal what life has been like post-divorce and Shamea sits down with the ladies to confront her BFF Porsha, raising questions about Porsha''s budding friendship with Phaedra. As the conversation turns to issues surrounding "Lesbiangate," friendships are shaken like never before.', '2017-04-30', 43, '/51k38WxBOlF2I9UTMg8xEZu3PKf.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6E3960F13AC04AC2B7B62C4313EE85BF', X'F237DF231A904F1EABE74FF2AD58945F', 18, 'Episode 617', '', NULL, NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6E39CA860A714B19A66AFDA1EEB9612C', X'D306A064E835417E85480CF806295F31', 13, 'Brujeria in the Bahamas', 'In the Bahamas, the ladies have fun in the sun and get wild on the water rides; Julia surprises the girls with a gift but is met with mixed reactions; Alexia and Adriana are forced to confront one another after Larsa causes a stir.', '2023-02-09', 44, '/cssvhFzEQC5jcmqWMGFiG5LuqtG.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6E3CB77F7BEC458FA8A3A28B60F07E3E', X'941B8C6544544336BE7C1D0591C12F90', 11, 'Pinga Has Hiccups', 'Pingu is trying to read his book in peace, but Pinga is noisily slurping her drink. Pingu gets her a straw so she can finish it, and sighs with relief at the quiet when she’s finished the drink. She then starts to hiccup, and stomach rubbing and backslapping by Pingu do nothing to stop them. Pingu takes her on the sledge to see Father at the post office, to see if he can stop her hiccups. Father suggests she stands on her head, and he and Pingu demonstrate how. Pinga tries, but then overbalances. The hiccups aren’t cured. Father then holds her upside down by the legs and tosses her in the air. This doesn’t work either. He then suggests blowing into a paper bag, and then tries giving her a shock by blowing up the bag and suddenly bursting it. Neither work. Pingu then goes with Pinga to find Robby. Robby and Pingu pretend to be walruses, by using icicles as pretend tusks, to try to scare her, but she’s not scared and the hiccups continue. Pingu then pretends that he’s scared when he sees a reflection in the ice of himself with the tusks, and rushes frantically about. This makes Pinga laugh, and the hiccups are stopped at last. Pinga and Pingu then go home, and Pinga reads while Pingu has a glass of orange to drink. Pingu then gets the hiccups and they both laugh!', '2004-01-16', 5, '/povwMNMRBI3P9Jwf2umr81ehnNZ.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
