INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6E437FE106334A78B15EDA17E2E26CC3', X'FB4ECC73CB924C5C821F92179058B37B', 85, 'Worm landing on the Moon (3740)', '', '1998-03-13', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6E446816FBFF4CEDA233343DC7076CDE', X'4B2A19E02FAE492EBC31F78E63D88EBC', 23, 'Megawatt Money', 'Earn your black belt with the Pawn Stars when two signed David Carradine replica swords from "Kill Bill" slice up the shop. Will Corey settle the score and make a sale or will he be out for blood? Next, things get dramatic when a first edition of T.S. Eliot''s "Four Quartets" shows up. Will Rick make an epic sale or will he poetically pass? Then, it’s Rick''s move when a 1965 Battle of the Bulge board game ambushes the shop. Will he take the offensive and make an offer or will the deal rewrite history? And later, things get radioactive when a 1920s radium crock is brought in. Will Rick emit a megawatt offer or will the deal become toxic?', '2017-01-16', 21, '/huO7BuCKN0aQCVvoetH8C5k2bjP.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
