INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6E68258AF3AA4EA4862C45E654AEB58D', X'B2317FC31CFC4F19B181EFFA23959C6D', 2, 'House of Hypocrisy', 'The Gorga/Giudice feud moves to the next generation as Gia goes to battle with her uncle; Jackie learns Jennifer has been digging for dirt on Evan, while Dolores'' housewarming party ends in tears when she takes Margaret''s side over Jennifer''s.', '2022-02-08', 43, '/bmnFnCF2J3kCZxqxFOQsHoKegQl.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6E6CEC009FD04065ADB443859D6FBF55', X'3EE646E823AE4DECBBC6C7E6A210D55B', 109, 'Playing football / Meet Merry Monster', 'Elmo excitedly shows Oscar the globe he was just given by his daddy. He wants to travel the world and has Oscar spin the globe and point to a location he can go. Elmo lands on Tonga and Oscar is glad to see him leave, only Elmo returns moments later and leaps onto the globe.
