INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6E78D78473164BCF9660E3713E60C295', X'F4938E7D11A84756B40598BEDD7C9B28', 4, 'Pat''s Rainy Day', 'It has been raining very heavily in Greendale. Even the letters are wet when Pat goes to the Post Office to collect them. Later Pat is stopped when a road has to be cleared of a blockage of mud. Bill brings his model plane and Pat ties an SOS message to it and flies it over to Peter, giving him the message to clear the blockage with his tractor and bulldozer plough.', '1981-10-07', 15, '/gJHHnu8A2Fqvrl6Ir7UZB012KfE.jpg', '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
