INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6EBD6471B25744498AA481A9C7CFE796', X'10E64538C78A4CB082F917D14256DBAC', 17, 'The Wisdom Teeth', 'Frankie''s excited to take care of Sue and Axl after they both have their wisdom teeth removed; and Brick lays down new house rules for his siblings while they''re back home. Meanwhile, Mike learns the diaper business was Rusty''s ex-wife''s idea and becomes furious when he finds out she may be entitled to all their profits.', '2016-03-16', 22, '/3LMIsJDB4mbKuoutFTO0wb7eqQU.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
