INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6EC84BB73528469ABCB586C1C55E3B10', X'0E4196154C964DDE8ED2715770BA77BB', 12, 'Let''s Hit the Road', 'At Mouse School, Miss Maxwell announces a field trip and gives all the mice a permission slip for their parent or guardian to sign. Tutter is excited about the trip at first and eagerly tells the kids at the Big Blue House about it when he gets there. When he tells them that Miss Maxwell said the location would be a surprise, Pip and Pop figure that the trip must be to a field. The kids think about all of the fun things they could do on a trip around the world. Tutter, however, becomes very worried that he''s going to be stranded in the middle of nowhere. He hides his permission slip from Bear and later decides to fake being sick. Meanwhile, Ojo plans a big trip on her bike. She plots out her course, but finds that sometimes you need a guide, such as a responsible adult, to help out. When Miss Maxwell hears that Tutter is worried about the trip, she provides him with some reassuring, but also a bit surprising news. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6ECB4BB2F29B4D87A4698DE1CF2F5F5F', X'331FC1DF6D704D79B585BF28024A4124', 9, 'Mother''s Helper', 'Helen goes away on a course, leaving Mike to do all of the housework. When he leaves the iron on whilst he goes out to fix Dilys'' washing machine, a fire starts.', '2008-11-21', 10, NULL, '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
