INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6ED069E54949475D982FE215E4A0B26C', X'244B0A34284B4EC1B3A70E5ABFF6D0D1', 8, 'The Good, the Bad, and the Binky', 'As Emily''s new babysitter, Binky introduces his charge to the world of pro-wrestling, and teaches her some fierce moves. But when Emily starts ruffling the feathers of other pre-schoolers on the playground, Binky worries that he has not been the best role model.', '2009-10-15', 13, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6ED431DB00BF4648ABA880913BEBF77F', X'0EBBA123871D4D2BA054EB85D2AD9450', 36, 'Sweetpea Beauty: A Girl After God''s Own Heart', 'A VeggieTales twist on the story of Sleeping Beauty and Snow White. The second story is "Snooderella", a twist of Cinderella. Its theme is true beauty.', '2010-07-31', 30, '/fim42g0EvoJmqsRrs72ZVbBK64b.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6ED6B5855D5140F6B7F9F1AD311AD5FE', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 13, 'Fluids', 'Fluids are cool; they ooze and swoosh. Whatever container you put a fluid in, that fluid will take the same shape. Milk poured into a pitcher forms to the shape of the pitcher. If you pour it into a glass, it takes the shape of the glass. You just can’t do that with a boulder. But with the right container, you could pour liquid rock from below the Earth’s crust. Fluids still act like fluids, even halfway to the center of the Earth.', '1998-05-02', 26, '/4duybQ3DaiZhPylOiBwABJquaYG.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
