INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6EDA8B6D254B49739C1CE82AE1EB23C8', X'208E80DE61E34A2F857FC667FFC29134', 19, 'Mark Hamill', 'The regularly-scheduled guest (a terrible singer) is bumped when four stars of Star Wars Episode IV: A New Hope suddenly appear in the theater.  It''s a natural for the Pigs in Space.', '1980-02-29', 26, '/hIEMcNa5rlIXWWvKngSvQ0xazzB.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6EDD0570CCA74920AC9EEF1C9E15AD6A', X'DBD3583FE9B246D1A37E309EB666E233', 20, 'Happiness and Joy', 'Cynthia hosts a model call at the Bailey Agency hoping to find Atlanta''s next "it" girl. NeNe makes a major decision about her marriage, and later meets with her "business partner" John, who surprises her with another gift. Kim is also in the giving spirit and surprises her new fiance with an extravagant birthday present. Meanwhile, Kandi launches her sex-toy line in a big way, but realizes it''ll take more than masseurs and vibrators to bring "happiness and joy" to the ladies.', '2012-04-08', 43, '/nclA2mwTAjFXP6TP0HsuaTD3LfI.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
