INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6F6521CC5FA2460E85EAB8E888A8ED5C', X'02849455D14B476B9603EEF5FB5D2AB3', 2, 'Meet the Press', 'With their relationship back on track, Robyn and Juan upgrade their lives by moving to a new condo with an interesting address. Trying to keep her man happy, Gizelle takes her new boyfriend Sherman on a romantic picnic, while Monique and Ashley hang out with a fabulous young friend who has a bubbly personality and a crown to go with it. Feeling hurt and betrayed by her friends, Karen decides to hold a "Press Conference" to answer all their questions regarding her financial situation.', '2018-04-08', 42, '/a010JrqHozOcIadFHSYjsDOkNs8.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6F6E1D5C64394F058336DE93A00F1522', X'38BF8C20C17C407192267887787CF1B1', 14, 'Bug Beard', 'In the story ""Bug Beard"", a woodcutter brings home a grubby, buggy old man he finds in the woods. His wife is not amused by the buggy old man, and so she sets about trying to clean him up. When the buggy man is finally all cleaned up, it turns out he just isn''t his happy, dancing, singing old self. Can the Lions help?', '2001-04-19', 30, NULL, '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
