INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6F8B374ED0C044E9B28DFF22FAF94D47', X'A61EDA16B5724C5BBA5557DF932417EC', 9, 'Wembley''s Flight', 'Wembley, feeling unhappy because he never gets to show off in front of his friends, meets a magical creature that gives him the power to fly. But his friends refuse to believe he has this magical gift and restrain him from flying. Other Fraggles believe him but want to exploit his gift. Wembley finally learns to fly for the right reasons.', '1986-03-03', 24, '/etzAovsv76dfQfxpCrWZQNoNhjC.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
