INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6F91A73CDF674BACB51B9960337B7A68', X'0BBD380C5CB846A68838B5D60223C073', 22, 'Ethel Merman', 'Fozzie''s agent, Irving Bizarre, negotiates Fozzie''s contract with Kermit. Kermit ends up offering Fozzie ten times as much money; unfortunately, Fozzie made nothing before. "Yeah, and don''t forget," Irving says, "I get ten percent of that."', '1977-04-09', 26, '/41bAr3bHgedIUWAkZuhkVwE4eXW.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6F927920CC244F25984239E76B1579C8', X'4FE93658C46343298E649D523869C2CB', 23, 'Pawn Illustrated', 'The Pawn Stars take aim at an incredibly rare 18th century half-size musket. Designed for a child, will the gang hit a miniature bull''s-eye or will a pint-sized problem cause them to shoot themselves in the foot? Then, Rick and the Old Man are presented with a WWII pilot''s jacket flown in the legendary P-38 Lightning. Will the guys dive into a dogfight for this leather bomber or will this deal fall from the sky? And later, a man brings in the first three years of Sports Illustrated magazine. Will Corey and Chumlee go the distance for this iconic collection or will one brutal round cause them to throw in the towel?', '2011-02-07', 21, '/5g6GIsnu7WhO42vQKMLDOXPN3a7.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
