INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6FC65DFC575C4E83ABFFE243F8309CFE', X'65F5ABC80C59497B86E58C6165EE480C', 15, 'Game of Phones', 'In Denmark, Brandi storms off during the final dinner, and D''Andra follows close behind; LeeAnne gets ready to unveil her "L''Infinity" dress; LeeAnne claims Brandi stole her phone on their last night in Denmark and that she cloned Brandi''s phone.', '2018-11-21', NULL, '/3IedZgLwnn4LKi8jBkYIpSbYg10.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
