INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6FCA458EE2EC4A1EBF1C76865F2B3581', X'06030129FF2D4490B66C9F41BBE7AABD', 10, 'Clipping', 'As John sails down the canal, he notices lots of different things being cut, so he takes a walk and goes to a farm to see some sheep having their wool sheared off. Later on, John does some trimming of his own by giving his beard a snip. Rosie and Jim join in by taking some sheep wool and begin pretending to shear it off themselves.', '1990-11-05', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
