INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6FDD3DA34BB74020A14C8E66A95638EC', X'BCAB920A51A54CBBAA5941578A0EB005', 11, 'Backed Into a Corner', 'Tensions run high at Mauricio’s party in Mexico, as Kyle demands to know exactly what Lisa Rinna said about her sister Kim. Eden seeks her mother’s advice regarding Kyle and Kim. Erika advises Rinna to come clean with Kyle, but Rinna maintains she’s done nothing wrong. The Mexico trip wraps up with a wild boat ride and a dance to remember.', '2017-02-14', 43, '/1Qi8jKsjY91I22XVrjKNtJwtS8u.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6FE1CAFE7DE14BB6A1FEA49D534C69F0', X'ABFE14EEDB424DDEA96A601FF3C53ECC', 1, 'Cluny the Scourge (1)', 'Matthias the mouse is orphaned when the vile rat Cluny the Scourge destroys his town. Adopted by the generous creatures of Redwall Abbey he grows up to admire their legendary protector, Martin the Warrior. But his peaceful young life is shattered when the Abbey is attacked by rats and Matthias meets their warlord - none other than Cluny! Matthias resolves to fight the tyrant that once again threatens his life - and his new family.', '1999-09-08', NULL, '/109sXPpEjsYNI4u92O5uLzAKgnG.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6FEF4E731C07438AAA726814E4AFB484', X'3A96D6C63736498A926F6C479CDFB73A', 18, 'Franklin and the Secret Club', 'Porcupine creates a Secret Club to be more popular than Franklin. When she finally allows Franklin to join, but he had to choose between a friend or the club, it''s Porcupine who learns the real true meaning of friendship.', '1997-12-25', 12, NULL, '2026-04-03T17:40:14Z', '2026-04-03T17:40:14Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6FF01D310DDC414E8CD209B5D26E2EB8', X'33E647E7A3E84C3A93E674E08399A790', 12, 'Little Black Balls', 'Nell has a very valuable opal which has just been eaten by a goat.  Now the entire town is scrambling to find out which goat dropping contains it.', '1992-06-19', 24, '/y5DG5ZNetCrQYduVDGaJ6Syog75.jpg', '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6FF49584CEAF42E6A090BE83DD9A0195', X'36E5C604FEA94BCF834371BFAF60ECD2', 11, 'The Day Ice Came To The Harbour', 'A big freeze slows the productivity of the harbor right down. The pilot boats are restricted to their docks so Theodore and his other tugboat friends are left in charge to make sure that the harbor is kept safe.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6FF8082F167042E7B292E3E1F579669C', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 102, 'Forgetful forgets how to read signs', 'Forgetful Jones encounters various signs around Sesame Street but can''t remember what they mean or how to read them. Others help him understand what different signs communicate. This episode emphasizes the importance of reading and understanding written information in daily life.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6FF8A910B99849C28608616CA3DAD21B', X'FE19A277AED844DFA4ACFC1C4E9941B4', 3, 'Unbeweavable', 'Shereé, NeNe and Kim’s reconciliation doesn’t go as planned. Lisa and Ed meet with a design team to discuss her new clothing line “Closet Freak,” and Kim throws a wig party to celebrate her new endeavor. Kandi meets for lunch with TLC member T-Boz to discuss her musical career, and Shereé throws a gathering to celebrate her new home. Also, Dwight throws a circus-themed birthday bash.', '2009-08-13', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'6FF9AC019396423491AB97A36889AC31', X'6EF86C2733E747E5A053483059DFD16D', 24, 'Episode 24', 'Save this copy of RADIO TIMES and transform the pages into a reindeer. A cardboard sledge completes the model and you''ll end up with a magnificent Christmas decoration that would cost pounds to buy in the shops.', '1981-12-03', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
