INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7037EA9697B845F497D789D882CD121B', X'101549F46ED145FAB543D08723F65306', 7, 'Episode 726', '', NULL, NULL, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7041D2BDD41D40A6AE992AC3A7102C54', X'4C79C0B621A442778967BE1E791EFDBE', 21, 'Pingu and the Braces', 'Grandfather is wrapping up his barbells to get rid of them, and remembering 1948. the time he was a weightlifter. now in the modern day 2005. When the barbells are wrapped he gets the sledge, to carry them to the post office, but they’re too heavy for him to lift on. Just then Pingu and Pingg arrive, so he asks them if they’ll lift them on for him. They get the first one on, and the sledge bends in the middle with the weight. They put the second on, and Grandfather ties them in place using a pair of braces, but the sledge then breaks under the weight, with the barbells falling onto the floor and the braces coming loose. The phone distracts Grandfather, and Pingu and Pingg go outside with the braces. Pingu tries them as expanding arm exercisers, and Pingg then twangs them musically. Pingu spots a large melon on the table and they try to fire it using the braces as a catapult, but it’s too heavy and drops to the ground. They then successfully fire a banana, but it behaves rather like a boomerang and comes back, so they have to duck to avoid it. Pingg then holds the braces and fires Pingu, and Pingu does the same for Pingg. Pingu then decides that he wants to go further, and attaches one end of the braces to the igloo door, the other end to the table, and pulls himself back as far as he can. His feet slip, and he twangs forward, then back, then forward again. He tries to stop by grabbing the clothesline, but misses and only gets hold of a towel. This pulls loose, so he twangs back again. Then the end of the braces that is tied to the door of the igloo comes loose as Grandfather comes out, and the braces wind round and round the table with Pingu hanging onto the end. They then unwind, and Pingu ends up running in place on a disintegrating pile of logs. Grandfather asks Pingu what he’s up to, and Pingu suddenly remembers what he was supposed to be doing and improvises a sledge out of two logs and a wooden box. He and Pingg then load the weights into the box. With Grandfather sitting on top, they then pull the box to the post office, using the braces as reins.', '2006-02-24', 5, '/oEsnS9YG24fwGiQdLEp7FJDysXV.jpg', '2026-04-03T17:22:21Z', '2026-04-03T17:22:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'704271B1B90B4E3D977AA15631A11B7F', X'EA1650C2E4F146C793BA74B5D45D08E5', 14, 'Flamingo Road Block', 'NeNe''s "keeping it real" as she presents her first on-air interview with star producer Jermaine Dupri for her local news segment; but Kim takes NeNe''s on-air mention of ''Tardy for the Party'' as a deliberate jab. With their wedding only two weeks away, Peter reveals to Cynthia that their financial situation is dire, putting both their wedding plans and their relationship on the rocks. Phaedra struggles with being both a lawyer and a new mom, while Sheree sends her kids off for a visit with their dad. Kandi has all but had enough of Kim and Sweetie''s antics on their bus tour, and when NeNe joins them in Orlando for the last leg of the trip, a massive fight erupts among the ladies.', '2011-01-16', 43, '/itmwD4qWBkyxMVkMPdyJNbvg1a7.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
