INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'704DE175CB3E4E90BB52584FDFDF97E7', X'136B81D3964D4B8FA21492F00D96D6B9', 125, 'Slimey plays basketball', 'Slimey, Oscar''s tiny pet worm, tries to play basketball with the other characters on Sesame Street, causing hilarious and endearing mishaps. Despite being much smaller than everyone else, Slimey shows determination and enthusiasm throughout the game. The gang cheers him on as he courageously participates.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'704FAAF59EC243A59A599A356E16B990', X'45E64A158FC04E4BA1CA9E3F42F3634D', 15, 'Earth''s Seasons', 'It doesn''t matter if it''s spring, summer, winter, or fall - Bill Nye is always in season.   Every year, we experience the seasons. Some months have snow and rain, while other months have   warmth and sunshine. Temperatures go from cold, to woarm, to cold again â€“ winter, spring, summer, and   fall. The cycle of the seasons takes one year, and the Earth takes one year to go around the sun.   Coincidence? No way.   The Earth''s orbit around the Sun is flat, as though our planet were spinning over a tabletop. Compared   with flat plane of its orbit, the Earth is tilted. Its axis, the imaginary line between the North and South   Poles, is tipped over a bit. In June, the north half of the Earth (the Northern Hemisphere) is tilted toward   the Sun, and it''s summertime in places like Nye Labs in the United States. Meanwhile, the south half (the   Southern Hemisphere) is tilted away from the Sun, and it''s winter there, in places like Australia and South   Africa.   The Earth''s orbit isn''t quite', '1993-12-17', 26, '/7VcXHASFCrNfBF3lfaUDq970DBn.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'705104CA7D48488798DDC22A40EA1FAE', X'C9ADC698BE924DD794ADD8F6759361CA', 45, 'Episode 45', 'Rogers has a juicer for Chef Brockett. Those in the Neighborhood of Make-Believe hold a concert to celebrate Queen Sara''s recovery from illness.', '1973-04-20', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
