INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'70753B5790B148AE9E690CF6765CEB10', X'1D713CA64E174F84949C8CFD98514127', 1, 'Press One for Chum', 'Play hardball with the Pawn Stars when an autograph of baseball legend Honus Wagner lands in the shop. Will Corey and Chum hit a home run or will this signature be going, going, gone? Then, Rick crushes on a rare, first edition of Nabokov''s controversial novel, "Lolita." Will he be seduced and give in to his love of literature or will it end up being a closed book? And later, Chumlee helps set up the shop''s new phone system. Will he get called out for doing a good job or will Rick hold the phone on his not-so-traditional ideas?', '2014-07-10', 21, '/VFx7ZDziwr98PdVZf3yAx7yN8U.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7078DEC3C88A4717AD1DA1912CADB98D', X'7CCD5605FE0B4E00AE7F3E3DAA252F8B', 5, 'Friends, Facelifts and Florida', 'Vicki Gunvalson is focused on repairing her marriage to Donn and schemes a big surprise to celebrate their upcoming 15th wedding anniversary. Alexis Bellino is raising her twin, 20-month old girls to know the importance of keeping up their good looks" and decides they are old enough to have their first mani/pedi at a nail salon. It’s plastic surgery day for the Curtins when Lynne undergoes a face-lift, while her oldest daughter Raquel has a bump removed from her nose. Meanwhile, Tamra Barney jumps back into the real estate game by showing her first house in several years. Also, Vicki travels to Florida for an insurance convention and invites all the Housewives to join her for a ladies-only getaway. But, Alexis tells Gretchen that if she goes on Vickis Florida girl trip, Jim will definitely be accompanying her. Gretchen begins to wonder about everyone''s confining relationships.', '2009-12-10', 44, '/ndRFXtQL2urPYdoVCTgrSxZiMGg.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'70798D7DBB7645DBA1A49ECF81B69791', X'42E591E22A884434AE9F3D4B1D685613', 22, 'Goldfish and Silver', 'Go off-road with the Pawn Stars as the guys check out a Honda Pilot ATV. Will they see a chance to make a profit, or will negotiations get stuck in the mud? Then, Rick and Chumlee give a seller shelter when he brings in a signed photo of the Rolling Stones. A rare early image including the late Brian Jones, could wild horses tear Rick away from this piece? And later, when Chumlee brings his pet goldfish into the shop, the Old Man is determined to get rid of it.', '2013-08-22', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'707D93166983407C9AB9CCA68AF18F76', X'5DADE172C4F34488A399B73F3ACA0DB5', 3, 'Chapter Three: The Pollywog', 'Dustin adopts a strange new pet, and Eleven grows increasingly impatient. A well-meaning Bob urges Will to stand up to his fears.', '2017-10-27', 51, '/792NQjFydcr5ucb1sga55LS6Vt3.jpg', '2026-04-03T15:40:39Z', '2026-04-03T15:40:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7080D0C4278C44ACAAC0B167969E04BB', X'937EE587E2EB46AA9A693D6BAB04398F', 7, 'Rumplestiltskin', 'This looks like an extension of the previous episode, but it is a separate venture. LeVar appears in proper attire for an English Renaissance festival. Ralph Waite reads the fairy tale of Rumpelstiltskin, about a poor miller''s daughter who is stuck between a greedy king and a conniving elf to get out of a difficult situation.', '1987-06-30', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'70852531F711460B9017F9C1AD81FAE5', X'5DB3FF78E43948E18F67988ECBF85D17', 10, 'The Great Getaway', 'Juliette''s Uncle is kidnapped by the people who kidnapped Juliette, who''s still being held in the house by Rochefort''s squire. Dogtanian plans to find them both and enlists The Three Musketeers to find Juliette''s Uncle while he goes to find Juliette. Juliette manages to escape outsmarting the squire who follows her with Rochefort. After Juliette falls in the river Rochefort lets her think she''s escaped so she will lead him to the Duke of Buckingham...', '1981-12-11', 24, '/wBqp8MzIbGzLBFI63ZO0tTvH37D.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
