INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7123CC1E59F54440BAD8716E436C3371', X'97A3D1F5A8F147CD81222E74A092836D', 13, 'Lost in Brooklyn (1)', 'An African exchange student arrives in Hurston and Tina befriends her. Safria explains to Tina that years ago her brother wanted to become an artist. Her father disapproved, they had a fight and Malenga accidentally hit him. Ever since that day Safria''s father hasn''t forgiven him and won''t allow his name to be mentioned. Safria tells Tina that Malenga has been writing  anonymous letters to her. She and Tina decide to go on a city search for Malenga.', '1993-11-28', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'712C14239C3E4D4F8009360B8DAFA0EB', X'4DA606E79D2346828BD5F535E1DA706F', 15, 'Franklin''s Birthday Party', 'Franklin''s parents couldn''t afford to take Franklin and all his friends to Tamarack Point so they built their own little amusement park for Franklin''s birthday party.', '1998-10-26', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'712C9089349745918CD4F84DE64DD2AE', X'1C9EA7D3E2544E7B8A9F33EEA9C6C341', 25, 'Reunion (2)', 'Kenya and Porsha discuss where their friendship went wrong, which leads to a spicy exchange between Kenya and Nene. The ladies open up about their past relationship struggles and Eva breaks down while talking about her journey with her daughter. Porsha and Eva have a heated exchange when Porsha calls Eva out for being a shady friend. Nene goes missing, leaving Andy and the ladies to wonder if she’ll return to defend herself.', '2020-05-17', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
