INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7148146FA2AB4D568C4151BD8D50B809', X'DBDE6570A68D4FD7A1B0A6037A266A18', 20, 'Are You In or Out', 'Drama continues at Heather''s party; Sarah acts strangely; Tamra and Gretchen commemorate their new friendship with a gift; Jim confronts Terry about calling Alexis phony; Vicki and Tamra fight.', '2012-06-26', 44, NULL, '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'714BD08DC01A443B82891CC6AF08EAA0', X'90CC8678A14F4D05BC1E54A3117895D5', 11, 'A Time Of Reckoning', 'Now sharing a den, Bold and Whisper continue to grow closer. With the help of Whisper, Crow - and a St. Bernards dog Rollo whom he befriends, Bold is now finding the struggle for survival less and less of a challenge. But his pride has taken a blow - he can''t stand having to rely on others all the time, and when Whisper reveals that she is with cub, and wants him to guide her back to White Deer Park, Bold''s self-confidence takes another blow: she only chose him for a mate due to his lineage. Whisper denies this, but the journey takes its toll on Bold and he grows steadily weaker. Meanwhile, back in White Deer Park, the feud comes to a head when Vixen and Lady Blue become involved in a vicious fight.', '1994-03-18', 25, '/aTn1VL0cvYhc2mxBJpsV5mVcWfj.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'715A196FCFB0456BAF636B1EE877811E', X'EFDF1E4F84764382A9D72B9DA4188BE0', 2, 'Mad Feelings', 'Maggie Stewart brings a water-and-oil motion sculpture to the television house. Jay Styperk, a wheelchair basketball specialist, gives Rogers a few exercises. The Neighborhood of Make-Believe is startled to see Lady Elaine has turned the Eiffel Tower upside down.', '1996-08-16', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
