INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7160F184B64E485CBF04A5CD1BB0D0C8', X'7C0E1F6688354E8A8AD90EEE57155B4C', 8, 'Creating the Legend: Waterbending', 'In the Avatar''s World, the powers of the four nations are based on four different forms of Chinese Martial Arts. Sifu Kisu discusses Waterbending.', '2010-08-20', 1, NULL, '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'716734B8BD53430D9008D4C611AB778F', X'42E591E22A884434AE9F3D4B1D685613', 4, 'Unprankable', 'The Pawn Stars prepare for a duel when a check signed by Aaron Burr comes in the shop. Will Rick try to turn this check into cash, or will a tough negotiation make the seller bounce? Then, Rick and Corey check out a 1960 Chevy Corvair. Will the guys have the guts to take this car, once considered "Unsafe at Any Speed," out for a spin? And later, Corey is determined to pay Chumlee back for a prank gone awry. Can he pull one over on the self-proclaimed "Prank Master?"', '2013-06-06', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'716B14FE23FD4DAB8948C131100385B5', X'E291DF42D44F49E5BF812DF32EE4A30F', 26, 'A Berry Bear Christmas (2)', 'Continuing from part one of the Berry Bear Christmas special, the entire gang (now with Jack) goes out caroling.  As the kids settle down to try to figure out what to do about a Christmas present for Bear, Bear turns his attention to the finding of the winter berry. Jack overhears the kids'' conversation and suggests making something.  In the Shadow segment, Shadow sings a song about a Hanukah dreidel. She then wants to give Bear a present, but says there isn''t much a shadow can give a bear. So she has him kneel down and she gives him a kiss.  Everyone enjoys their presents, but they worry that they''ve left out Jack. Jack helps them to see that they''ve already given him a gift -- a peaceful, happy holiday in a warm house with good friends. Later, the search for the winter berry proves fruitful for all.', '1999-12-06', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
