INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'71829A66A9054F1DA1164CCCD8E46EA5', X'8C3CFAC1D8824904B38CD1981628D00E', 31, 'Episode 31', 'Review of the Year  Re-live Blue Peter''s highlights of 1978 as Simon rides the Tower Bridge Death Slide, Christopher takes to the skies-on water-skis, and Lesley has a cuddle with Frankenstein''s monster! Join ANNI-FRID, BJORN, AGNETHA and BENNY in the Blue Peter studio, float in space with Skylab Astronaut Owen Garriot and flex your lips with the Fuoptimists as they give their unique ''trim-phone'' seminar.', '1978-12-28', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
