INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'719F1EFF9BA54941AC9AF7EA2EB53B37', X'EC8D33228CA24E8D9D22268AEE320274', 10, 'The Champ Pays a Call', 'Chum gets a taste of a Julia Child cookbook, but will he find a recipe for success, or will he end up with egg on his face? Then, Rick kickflips for a vintage skateboard collection. Will he land his ollie, or is it all just a trick? Later, Corey tries to score a Steph Curry jersey. Will he hit a three pointer, or will he shoot a brick? And finally, Rick comes out swinging for a punching bag signed by an Academy Award-winning actor, who may even show up for a knock-out appearance.', '2025-04-02', 42, '/rLFyiplajAAdFE81WvyUeg4fRvd.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
