INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'71A2757B305E4C94B121A3C1D52324D5', X'34674C90410E427CBE4D2A6F6F865A80', 6, 'Trigger Happy', 'The Pawn Stars get fired up when a rare three-trigger Stevens shotgun barrels into the shop. Will the third trigger be the charm, or is this gun a three-time loser? Then, Corey and Rick are presented with a movie camera used by the U.S. military during WWII. Built to operate on the battlefield, can it draw Rick''s focus or will he shoot it down? And later, an Abraham Lincoln campaign token comes in on the Night Shift. Handed out during Lincoln''s 1864 re-election campaign, will Olivia elect to bring in a second opinion or will run solo on this deal?', '2012-04-23', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
