INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'71BF82DA99B1422B9DF158C8791D7C89', X'6F731E6BD3C54DE684E17A19CB650E86', 37, 'Pawntucky Derby', 'Ante up with the Pawn Stars when they head out to see a 1980s Sigma Derby horse-racing game. Will Rick jockey for a deal or will he be left running in circles? Next, a 1940''s Moby Dick Classic Comic sails into the shop. Will Chum cast an offer or will he go down with the ship? Then, a dollar signed by Walt Disney and Ronald Reagan gets its closeup. Will Corey cash in or go broke? And later, a 1910 envelope sealer presses through the doors. Will Rick seal the deal or get stamped out?', '2016-06-08', 21, '/8eJfo7Nif4IREny2dLoxun5Giw2.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
