INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'71F4B7B74AFC437F8A748B336F242A1F', X'2DCBD12286D846E8BBE59143875ABD34', 1, 'D.W.''s Library Card', 'D.W. discovers that she can get her own library card and feel the power as Arthur has, but she can not write her own name. When she does and waits a week for a book to come in, she borrows it but never reads it because she thought she might destroy it.', '1999-10-04', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
