INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7238205954D04AC2BA19FD18706F46E8', X'F29F456F8E3849AF88087943977100EC', 12, 'Mutiny on the Pitch', 'Francine decides to leave her soccer position to Buster when the Lakewood Elementary soccer team claims she is too bossy.', '2017-05-31', 13, NULL, '2026-04-03T17:38:02Z', '2026-04-03T17:38:02Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'723AD7CD9447436E816C459E03358DCD', X'4FE93658C46343298E649D523869C2CB', 25, 'Harrison for President', 'The Pawn Stars are presented with a piece of fabric believed to be from William Henry Harrison''s presidential campaign. Will the Harrison name get the vote, or will a loose thread unravel the deal? Then, Corey and Chumlee meet a man hoping to sell his fully functional antique arcade claw machine. Can they clasp the deal, or will it slip through their fingers? And later, Chumlee and the Old Man have an opportunity to buy a box of unopened, pre-embargo Cuban cigars. Will they fire up some cash for these 60-year-old stogies or will this deal go up in smoke?', '2011-02-14', 21, '/vix2VXlKlT7goTqtwEhuvvpLbU8.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'723F2E1F60464A41AA651FE0B6E350A9', X'B1D55597D9D24EEEAB9546DBB163291A', 19, 'Pingu At School', 'Pingu walks to school with his backpack, and on the way, calls for Robby. Robby slides down a slant on a snowy mountain. Pingu does the same sliding on his backpack, rather further than Robbie. Pingu slides his backpack to Robby. Robbie dons the backpack, Pingu is amused. Pingu and Robby find two rows of desks, a blackboard and an igloo. The teacher walks out of the igloo. As the teacher turns around to close the door, Robby quickly jumps into a water hole. The teacher rings the school bell. Pingo and Pingg arrive at the school. Before a lesson, Pingu tells Robbie to hide down the water hole. The teacher, Pingo, and Pingu walk over to the water hole. Pingo jumps into the water hole, much to Pingu''s surprise. Pingo jumps back out. Pingo goes to the blackboard and draws a fish. Pingg jumps into the water hole. Pingg jumps back out. Pingg is sent to blackboard and draws a fish skeleton along with a tail fin and head. Pingu laughs in amusement. Pingg points to the blackboard telling him why it isn''t funny. Pingu acts out Robby''s actions (first trying by mimicking the noise Robby makes, then, when this fails, moves like Robby). Pingg, Pingo and the teacher do not know who he is. Pingu goes to the blackboard and draws his friend Robby. Pingu takes a fish out of his desk and holds it over the water hole to attract Robby. Robbie jumps from the water hole and eats the fish''s body leaving the skeleton, head and tail fin. The teacher, Pingo and Pingg are astonished. Pingu calls for Robby. He leaps from the water hole and Pingu introduces him. The teacher is much satisfied. Robby brings a fish out of the water while the teacher erases the chalk drawings. They pass the fish down to the teacher and plaster it onto the blackboard. Robby gets an eel and repeats the process with a flounder and a lobster. Pingg and Pingo are asked what the creatures are. Pingu tries to raise his hand in order to answer. Pingu is finally brought up to answer the question of what the lobster is. Robby writes what it is. Pingu answers the question. The teacher pats Pingu''s head happily. All this leaves a happy Pingu, teacher and cheering Robby.', '1990-04-28', 5, '/4NBzjFVcmQtfnBkqXwIK2jsFAXQ.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7240A8574A3643C0A4BB72A84425C063', X'99A9678144CB4A5C910071E2A55B6B1A', 3, 'Girls Gone Wild', 'For her graduation present, George’s daughter McKenzie hits the sun and fun of South Beach, Miami along with Tammy’s daughters, Lindsey and Megan, and Lauri''s daughter, Ashley. Money woes put a damper on the Knickerbocker girls’ good time and a trip to a famous tattoo parlor gets McKenzie in hot water with dad George.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7240E0A738DB495F87D81E5BB78BE4A6', X'D0B78F22678E4E469D61AAC40BA206B8', 7, 'Eat, Drink, and Be Married', 'Kyle, Dorit, and Teddi shop for a wedding gift for Denise, who scrambles to pull off her big day in record time. Lisa Rinna comes face-to-face with an old flame, who dated both her and Denise at the same time. After their disastrous run-in at Camille’s birthday party, Lisa Vanderpump dreads seeing Teddi at the wedding. Erika prepares for the launch of her new tour.', '2019-03-26', 43, '/vNlAGEmVlPHlRiXfhYHicNZhs8M.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
