INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7247C9E5D9DC4629BF4517A1041EEAF8', X'42E591E22A884434AE9F3D4B1D685613', 35, 'The Bachelor', 'Celebrate Rick Harrison''s last days of freedom, as the Pawn Stars throw him a bachelor party. Can he survive what they have planned? Then, a rare salesman''s copy of "The Adventures of Tom Sawyer" comes in the shop. A prospectus used for selling the book door to door, will the guys be sold? And later, the Old Man schools Lili the intern on Vegas history when some vintage casino chips come into the shop. Is this deal worth going all in.', '2013-11-14', 21, '/qr4m8EYtqBjogJevTvww755B3jb.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'72492931BF994185BF42E00F3E8C147A', X'42E591E22A884434AE9F3D4B1D685613', 16, 'Chum-parazzi', 'Flip the switch with the Pawn Stars as they check out a poem written and signed by inventor Nikola Tesla. Famous for his work with electricity, will this piece leave Rick in a state of shock? Then, a pair of wooly chaps rides into the shop. Made for cold weather cowboys, will the deal make the guys feel warm and fuzzy? And later, Chumlee goes on a quest for a famous musician''s autograph. Can he use his ninja skills to track them down?', '2013-08-01', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'724EA1DE8D9E4DB7BD00F5DA1A630DD5', X'BCAB920A51A54CBBAA5941578A0EB005', 1, 'Stronger Than Ever', 'Lisa Vanderpump introduces the group to her friend Dorit, whose permanent houseguest is Boy George. Erika celebrates her 45th birthday in style with a 1970s-inspired Studio 54 party and receives more than one birthday surprise. Lisa Rinna and Eileen awkwardly come face to face with Lisa Vanderpump for the first time in months.', '2016-12-06', 43, '/v5dqIUzEUodlCtpkfCQMHwIIwwe.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
