INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7255A8643B6A40B9875671C080806605', X'8C3CFAC1D8824904B38CD1981628D00E', 41, 'Episode 41', 'Fifteen years after discovering the South Pole, Norwegian explorer ROALD AMUNDSEN attempted the world''s first airship flight over the North Pole. Christopher tells the story of this hazardous flight which includes rarely-seen archive film of Amundsen in action in his dirigible, the Norge.', '1979-02-01', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'72587F469F884D0CBCA19465D514974B', X'4D2CAC0F38FD438B8AFAACF43952E535', 97, 'Episode 97', 'A magazine programme for younger viewers with Christopher Trace and Leila Williams.  Life in the Royal Air Force: 6: The Operations Clerk.  Introduced by Corporal Valerie Tiller.  Film provided by the Royal Air Force.  Me and My Teddy Bear with Sarah Willmott.  Animal Friends: 3: Mice', '1960-08-26', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7258E75BCF7648F6A4845B64CDFEEA65', X'3269A890BBA94E6C9278F7EB38EB1720', 16, 'Human Transportation', 'Transportation is all about moving people and their things. You can transport yourself around using your feet, a bike, a car, a train – anything that gets you going from one place to another. Humans have been moving around from place to place ever since they’ve been on Earth. That’s how we get our food and our materials like lumber, concrete and computers from one place to another.', '1995-09-29', 26, '/gcbXLSVvv69szkuZELH9Xmzsz91.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
