INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7317F6734FC646BB8F3D62333255FFC3', X'F5C042DC065742E8A37D247414140632', 14, 'A Doggone Mess', 'Stephanie plans a series of childhood games for the ladies to partake in but an unforeseen visitor catches Kary off guard. D’Andra receives a shocking letter from her estranged stepmother, while Kameron hosts a séance to communicate with her dog Louis. Tiffany finally confronts her mother about her feelings and is brought to tears by her unexpected response.', '2021-04-13', NULL, '/8BzpM7LyMrE3sa3IImdYH1eqBTr.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
