INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7320C486A99542B195544DC0FABC8DF9', X'54FACB0BDB5941FE9D64C7C7221A3C81', 13, 'It’s Not You, It’s Miami', 'After Sonja crashes Lu’s rehearsal, Luann asks the women if they think Lady Morgan might be taking something to make her act this way. The ladies then head to Miami for fun, sun, and the revelation that Ramona made out with Harry Dubin. It’s all too much for Sonja to handle, and after a few drinks she lashes out at Luann and Ramona.', '2019-05-29', 60, '/kTNbQhlOkO7sRcFhkEI9QDVpsa5.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
