INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'735AB676866F4D2CB9848580BAE4877C', X'98D80972E53A43DDA03A7703465E6F87', 24, 'Off the Hook', 'Court is in session for the Pawn Stars when the guys check out a collection of sketches from the 1954 Sam Sheppard trial. The man who inspired "The Fugitive," is Rick willing to deliver a verdict on these rare drawings? Then, a baseball signed by the entire 1962 American League All Star team slides into the shop. With signatures from Yogi Berra and Mickey Mantle, do the guys play hardball, or strike out looking? And later, when Chumlee calls in sick, the guys are on the case to see if he s faking it. Will his story check out?', '2013-02-04', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
