INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'73ED583EBDD846EA827FA9B91CE91AC7', X'A8C6182E05E14B6891A55126CF6C94F0', 7, 'The Green Mountain Boys', 'James heads to the Grants to cover the story of the settlers'' struggle; Sarah goes hoping to find a place in the Green Mountains for her family to settle, and Henri wants to find maple syrup. Sarah and James witness the capture of the fort and Sarah befriends Benedict Arnold, whom she instantly respects.', '2002-09-10', 30, '/7wAZFypa7G1SBWWnmTLY8uUQpYI.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'73EFA45783FC4452989D2DED56F98EC7', X'FB4ECC73CB924C5C821F92179058B37B', 129, 'Episode 3784', '', '1998-05-14', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'73F21F25F3FA48E6B28F5C62820027E9', X'70C8CB4624944DD498F66BFB9B3FAF73', 29, 'Strike, Spare, BOOM', 'The Pawn Stars are blown away when they meet a guy selling his homemade mortar that fires a very unique brand of ammunition - bowling balls. Will the gang line up their aim and strike a deal or will a misfire send the deal into the gutter? Then Rick is handed an extremely rare World War II gas mask believed to have been designed for baby. Will Rick try to buy this unusual artifact, or will he throw the baby out with the bathwater? And later, the Old Man has a chance to buy an original unused ticket to the 1965 classic bout between Muhammad Ali and Floyd Patterson. Will the Pawn Stars go the distance for this piece of boxing memorabilia or will a surprise uppercut sting like a bee?', '2010-06-28', 21, '/hxnhnkRmEkinS5SRmB59EhXA5v5.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
