INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'740E6CB65E714C6290C8FB4580183291', X'120DBABEA1784607BE1576335687F9F1', 6, 'Badger''s Parting Gifts', 'LeVar discusses cathartic ways to adjust to losing a loved one in this episode. He and fellow viewers talk about family members that are now gone that they miss, and how they try to remember the good times rather than dwell on the pain. Ruby Dee reads the featured story about an aging Badger, who knows he doesn''t have much longer to live and tries to prepare his friends for his passing.', '2001-04-20', 30, NULL, '2026-04-03T17:36:21Z', '2026-04-03T17:36:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
