INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'742A056651A4468DBEA6F0FCFB301A59', X'4C79C0B621A442778967BE1E791EFDBE', 22, 'Pingu''s Big Catch', 'Pingu is going fishing. Mother and Pinga come out to say goodbye, and Pingu says he’ll catch a big fish. On his way to the pool Pingu comes across Father, who is fixing his motorised sledge, which has broken down. Pingu hoots in his ear, which makes Father jump and drop the screwdriver. Pingu tells Father that he’s going to catch a big fish. When Pingu reaches the pool, Pingg is already there fishing. Pingu tells Pingg that he’s going to catch a big fish and starts fishing in a pool nearby. Pingg soon lands a small fish. Pingu then has a bite and catches a top hat. Pingg finds this very amusing. Pingg then catches another fish; Pingu catches a spring. The spring bounces around, and into Pingu, knocking him down. This again amuses Pingg. Pingu is annoyed, and insists on changing places with Pingg, who reluctantly agrees. They settle down to fish again, and Pingu catches a bicycle wheel. Pingg then catches another fish, and Pingu a lavatory seat. They swap pools again. Pingg catches another fish, Pingu catches a broken kettle, and then an old boot. Pingg is rolling about with laughter. Again they swap pools and, as Pingg lands yet more fish, Pingu gets a rusty pram. Pingu sits down, very dejected, while Pingg counts all the fish he’s caught, and then holds up a fish in each hand and makes fun of Pingu. Just then a rag and bone penguin comes by, sees all the junk that Pingu has caught, and offers him a big fish for it. Pingu is delighted to accept, while Pingg bemoans the fact that the fish he’s got are only small.', '2006-02-27', 5, '/Wb6pUybWl7UVMNDhNaRrGkmtqW.jpg', '2026-04-03T17:22:21Z', '2026-04-03T17:22:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'742C3325105E402BB8B046F1A5B03940', X'A2EDCB5763C14028B87B7FAEAE2C999B', 8, 'Dare You', 'Nicolette has some concert tickets but daring Bernard to eat a fish, will Bernard eat the school pet?', '2004-02-24', 15, NULL, '2026-04-03T17:20:06Z', '2026-04-03T17:20:06Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'742E04193ACC43FCBBB040BE2663ECB6', X'495D4222B33A46FA83513265798E558B', 2, 'Birdsdo', 'The Gribble family - Port Niranda''s most notorious residents - are trying to get rid of Old Nell, so they can buy her house. The kids must prove Nell is fine but to do this, they must go up against birds who have real problems with their bowel movement.', '1990-04-13', 24, '/2gPRglycwooTD124jjwXfakxlzI.jpg', '2026-04-03T17:40:40Z', '2026-04-03T17:40:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
