INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'746F2A22D5834386860BD4A24E2EE307', X'9DFF2271F91B47C1A20D58973840B764', 12, 'If These Walls Could Talk', 'Bronson is sick and tired of not being told anything but now every piece of furniture can talk!  Bronson decides to rescue Fay from Mr. Snapper by retrieving the Book of Love.', '2000-03-15', 24, NULL, '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'746F3EE79862452FA45B2BD354E5C6C5', X'5BA20443D99F482081F66832D3F2BC4F', 19, 'Fossils', 'Most dead animals and plants break up, get decomposed, and become part of the soil, but some turn into fossils. A fossil forms when a plant or animal dies, and gets buried. If conditions are right, water gets into the fossil bed, and chemical reactions preserve the impressions for thousands or millions of years. There are different types of fossils — imprints of animals, black carbon outlines, hardened bones, or actual animals and plants that have been trapped in ice or hardened tree sap.', '1997-09-05', 26, '/saQZFcJ0AzStTCgri4mrzghP6ie.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
