INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'749C25F2A2AC4495A11A2254E801766C', X'7C542833ED0A42729C53E822408AB434', 2, 'The Way of the Wild Walkers', 'When Peter creates a wild and adventurous trail for Scoop Dooley to follow, they both end up getting lost.', '2024-10-01', 10, '/nEoEsKBkKi8ML8Qy4jHAL6sAeYo.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'749D52C14B404006831702D72FFFEE01', X'6F81C872CDB942DD83772C17CB6ED4D7', 4, 'Super Sitters', 'Grover and Cookie Monster help Chris baby-sit and learn how to take care of a baby.', '2017-01-28', NULL, '/6iK17GBb3D0ODrRz5b5YLrvctNi.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'749F8CFAC01448C386602F839FF13925', X'56428E5E7DAA468D8BD2076956507AA8', 13, 'The Sun', 'The Sun is huge. It''s bigger than huge. It''s so big that 1.3 million Earths would fit inside a hollowed-out Sun. It''s really far away, too - about 150 million kilometers (93 million miles) Even at that distance the Sun affects everything on Earth. All the energy we have comes, or once came from, the Sun. That includes energy to light a lamp, energy to kick a soccer ball, and energy in batteries that play your personal stereo. We''re talking about nearly all of the energy. There''s a little bit of energy that comes from nuclear reactions deep in the Earth''s core. But that energy pales compared with the nuclear fusion fueling the Sun. Without the Sun, the Earth would be a big hunk of rock with nearly nothing on it. The Sun is made of gas. It has so much gravity that it''s atoms are smashed into hot gas. In the sun, atoms of gas are constantly crashing into each other. When they collide, they form new atoms and release energy. Scientists call this atom smashing "nuclear fus', '1994-10-22', 26, '/wb5Qf18Rop2vJWIhOsZMKWlzBIw.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'74A4CCBE91034E6FB9A1231BF655E128', X'3FC7C152E4F6426AA89936EC454C4403', 23, 'Zak and the Beanstalk', 'The Do-Re-Mi birds (from “Zak’s Song) have been kidnapped, and it is up to Emmy, Max, Zak & Wheezie to come to their rescue. When they learn that a giant named Mungus took the birds because he loves their songs, they teach him how to make his own music.', '1999-10-05', 30, '/2f4EONSg5hIJkMuejoo2V05ygZO.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
