INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'74C13102AE28450AB8E8533A858AF1C4', X'9C9D89DF5F6B41D084C6B8CA7BD2A2E6', 7, 'The Grouch Band', 'Oscar is getting ready for a virtual Grouch concert with the noisiest and most annoying instruments. Elmo’s Shaky Shake instrument isn’t noisy enough for the concert. What if he adds more rocks and blocks to his jar? Let’s try!', '2021-12-23', NULL, '/l5UK3VUvaa4HihYLzsBybcUP3tk.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
