INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'74D6070B6CC0444C8D5FB0AA833E6F0F', X'F12380A993E547BB9E2FCF1EED11EEE4', 8, 'Making Out Like Teenagers', 'Coyote Pass has finally sold and it''s the final chapter in the family''s breakup. Kody, Robyn, Janelle, and Meri anxiously prepare to meet on the land to close out the deal. In North Carolina, Maddie has her baby girl.', '2025-11-16', NULL, '/y1To6PCZv2IXlmm3xpBbrK2Tk8O.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
