INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'74D82625B22144B39835CDC9E580A76F', X'63F9BF6D39B344F4B885A56807277A80', 15, 'The Muppets at Walt Disney World', 'A special which aired as part of The Magical World of Disney, this show was designed to promote a planned merger between The Walt Disney Company and The Jim Henson Company that would ultimately fall through upon Henson''s untimely death.  In the show, Kermit and Robin take the Muppet gang to the  Florida swamps for the annual Bug Fry and a frog family reunion. However, the other Muppets, unexcited  by a stinking bog, become excited when they learn they can see the fireworks from nearby Walt Disney World. Kermit agrees to let the gang "take a short peek" and be right back. As the Muppets accidentally break into the park, security tries to round them all up as they visit  the Magic Kingdom, EPCOT Center, and Disney/MGM Studios. Finally, after being rounded up, Kermit meets Mickey Mouse, and the show ends with a huge musical number.', '1990-05-06', 60, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
