INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'74E5157875B445ECA3D4D85775D556B1', X'B5AB3A72BC794E9BA53196739AFD7AEA', 10, 'Old Man''s Beard', 'Emily brings in a plant called Old Man''s Beard. The friends try to figure out why it is has this name, and Bagpuss tells the story of a king who used his silvery beard to make carpets. Madeline sings a song about a master weaver.', '1974-04-16', 15, NULL, '2026-04-03T17:23:58Z', '2026-04-03T17:23:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'74E8903E005445AC95DDF89A65FDD4C1', X'AC068B8E80F646BFAFB2DCEBCF76DC36', 6, 'Between You and Me', 'Skye refuses to let Leon wear his Apache necklace, and Leon gets upset. When the kids hide Nuzzle and Sizzle’s favorite toys, they search everywhere to find them.', '1998-10-28', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'74E8E3DD9E034B50B693899DC0BBD1AA', X'4D2CAC0F38FD438B8AFAACF43952E535', 23, 'Episode 23', 'A weekly programme for younger viewers.  Including: "The Story of San Marco", a scale model serial.  With Christopher Trace and Leila Williams.', '1959-03-19', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'74EA77056CC84569B8C6E91A1A6F4523', X'5C4E51C6E20746AD875C72988EB1E13E', 21, 'Face the Music', 'The Pawn Stars seek counsel when the business card of the infamous Old Western outlaw turned-lawyer John Wesley Hardin moseys into the shop. Will the guys afford the ransom or will this deal meet its end at high noon? Then, Chumlee has a chance to buy a pristine Gibson mandolin. Can he hit a high note with his solo performance or will he be out of tune and get booed? And later, Rick and the Old Man tool around with a 1950''s Shopsmith woodworking machine. Will the seller get crafty and convince them to nail down a deal or will Rick grind negotiations to a halt?', '2011-07-25', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
