INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'750AD5D7C9B742649B55AE2D30A12BC8', X'38BF8C20C17C407192267887787CF1B1', 20, 'Dreaming Shakespeare', 'It''s Shakespeare Day at the Library.  Fanfares, flowery language and period costumes are the order of the day (Cleo is dressed as the female star of Antony and Cleopatra).  A method actor is unable to play Romeo and Juliet because Juliet is sick.  Maybe an exasperated hen can fill in.', '2001-04-27', 30, NULL, '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
