INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'750D8F74198F4EA79EFFCB87DAEE667B', X'FFC2A75E0FFA4B26B1219B91B277594A', 23, 'Reunion (1)', 'The Atlanta ladies reunite to address the dramas of Season 7. NeNe and Kandi clash; Phaedra reflects on her emotional season and stuns the group with a revelation; and Claudia and Porsha face off once again.', '2015-04-26', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'750E63999104498096412062AB5DB303', X'4B2A19E02FAE492EBC31F78E63D88EBC', 18, 'Pawn Another Day', 'Strike a pose with the Pawn Stars when Madonna''s 1988 day planner vogues into the shop. Will it make Corey a material guy or will he fail to get into the groove? Next, a 1910 phrenology head analyzes its way in. Will it get a good read on Chum or will the deal hit some bumps? Then, an 1800s locket with preacher Henry Ward Beecher closes in. Will Rick give it his blessing or condemn it? And later, a 1980s egg chair used for hearing tests cranks up the volume. Will Corey hear money or think it’s an unsound buy?', '2016-12-26', 21, '/dH7JLRxWio2Il5qJvne8hNzNbUo.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'75111520E7184C93AD3E4347476B4C42', X'0442FB97146049238558B994078DC6B8', 15, 'Portu-Girl-Bye', 'The ladies head to Madeira, Portugal for some fun and sun, but the distance proves to be too much for Ashley. Karen questions Gizelle''s relationship with Jamal, causing a heated discussion on whether or not Gizelle’s relationship is even real. Things get interesting when Robyn sides with Karen against her fellow green-eyed bandit — causing the two besties to be at odds.', '2020-11-08', 42, '/d7RWmlhR1Ag7iQKAMK3aAAz17SU.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
