INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'751FDAE387384C3CA35A29CD68977736', X'C7FFC8DF467147E3A11B606828BCB508', 5, 'Shotgun', 'When Jesse goes missing, Walt fears the worst. Skyler has an unlikely reunion. Hank shares some bad news with Detective Tim Roberts.', '2011-08-14', 48, '/cIpk1YHRcySKOET8qUfs2JC3QAy.jpg', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
