INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'754CEA8A5DD5476ABBF1D69A4BB3A136', X'13ECB08FA00049F98D9654C16C3AD653', 2, 'Grilled', 'Walt and Jesse find themselves in close quarters with an unhinged Tuco. Marie and Hank comfort Skyler, who is distraught over Walt’s disappearance. Hank pays a visit to Mrs. Pinkman on some not-so-official business.', '2009-03-15', 48, '/th3SNe0gNgRguv8VveLd4f2JcaH.jpg', '2026-04-03T15:40:33Z', '2026-04-03T15:40:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'754FFC7EBF644B7992C31FBC05142F0D', X'5046642D462D4EB081940BBD7962AF0F', 6, 'Jonah a VeggieTales Movie', 'When the singing Veggies encounter some car trouble, they''re stranded at old, rundown seafood joint where nothing is quite as it seems. As Bob the Tomato and the kids settle in to wait for a tow truck to help get their van back on the road, the "Pirates Who Don''t Do Anything" share a little story about a guy named Jonah. Jonah was kind of like a mailman except his messages came straight from God. Jonah loves his job, until the day comes when he has to deliver a message to the people of Nineveh. Instead of carrying out his mission, Jonah turns and sets sail in the opposite direction onboard a pirate ship. Soon Jonah embarks on an adventure that leads him into the belly of a whale, and to the heart of Nineveh for a hilarious showdown.', '2002-10-04', 30, '/dDYt9n7kOTevpQ7iRjLNKmme26o.jpg', '2026-04-03T17:39:38Z', '2026-04-03T17:39:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
