INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7575F077D83F4965AD7EEB569434A6CF', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 28, 'If the Pawn Don''t Fit', 'Take a ride with the Pawn Stars as Rick test-drives the infamous O.J. Bronco. Will Rick pony up the big bucks for this million-dollar item, or will the verdict read no sale? Then, Rick sits down to dinner with a rare silverware set. Will he RSVP a yes to the sale, or lose his appetite after hearing the asking price? Also, in a pawn shop far, far, away ... Can Chum use his Jedi mind tricks to buy a 1978 "Star Wars" comic? Or will he be tempted by the powers of Darth No Sale?', '2017-08-14', 21, '/e82eqFRPxfreNsPDsAIQCPqkARB.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
