INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'75A5739447C54D5888DB077BC5EDC0E5', X'E291DF42D44F49E5BF812DF32EE4A30F', 24, 'Go To Sleep', 'Ojo is sleeping over at the Big Blue House. Bear helps get ready to go to bed, tucks her in and aids her in "surfing off to dreamland." Ojo falls fast asleep. Bear thinks of getting some sleep himself when he hears a knocking at the back-door. It turns out that Jeremiah Tortoise and Doc Hogg have arrived for an exciting card game of Go Fish. Jeremiah brought the cards --- special cards that actually contain pictures of fish --- but Bear hasn''t even put out any snacks. He has totally forgotten that their game was scheduled for tonight, and now all the noise threatens to wake up both Tutter and Ojo. Sure enough, Tutter shows up, saying that he needs a drink of water. Bear tries to attend to Tutter''s needs, while keeping his attention on the card game as well.', '1999-11-19', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
