INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'760ADC400A9E41808D0F5DA93F10F3AD', X'9B95011E93DB4E56A45D8AA956C15997', 24, 'Garden Force', 'Mandy wants to give her mother her dream garden with the help of her friends. Unfortunately, a runaway petrol lawnmower and bags of fertilizer result in a call to the Pontypandy fire station.', '2014-09-13', 10, '/xeAPTtLxnQv3YXDx3Aed0uXfwk5.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'760B3878202749919B566FFB21A394B2', X'56428E5E7DAA468D8BD2076956507AA8', 6, 'Food Web', 'Feeling a little hungry? Then grab a snack and watch Bill Nye the Science Guy''s episode on the   Food Web.   When it comes to eating, all living things depend on other living things. Take a chicken sandwich, for   example. The bread came from plants. So did the lettuce and tomatoes. The cheese was made from milk,   which came from a cow. To make milk, the cow had to stay alive by eating grass. The meat came from   a chicken who once ate seed, and maybe the occasional bug. The animals that helped to make your   sandwich depended on other living things to survive. The lettuce, grain (for the bread), and tomato got   by fine on their own. Then some animal came along (you).   Plants are the only big living things that don''t need other living things to survive. All they need are sunlight,   carbon dioxide, and water to make their own food. But it doesn''t stop them from being eaten -- no way.   In fact, plants are great things to eat. All animals need them in some way for food â€“ by the way,', '1994-03-25', 26, '/iKEYnYduOMhnABiVCL30tUAbJr6.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'760B56D5B60B454088AF6AC55F1CD240', X'E48599F866FF4C0F927465B9AE1CDA9E', 2, 'Episode 2', 'The summer holidays have meant hard work for Rags, Blue Peter''s trainee pony for handicapped riders. Today she copes with her first experience of traffic on the open road.', '1976-09-16', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
