INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'76448107B0874689919AE6FCDBBEFCB8', X'97A3D1F5A8F147CD81222E74A092836D', 7, 'Get the Message (3)', 'Jamal and Rob realize that the only way to stop the feud is to try to get the team to remember how much Ghostwriter means to them. They all get letters from each other but later learn it was a practical joke and get angry. Jamal and Rob give the team the letter. They realize how mad they were and that they were thinking only of themselves. They realize that someone is trying to set them up. Rob figures out that it''s probably Calvin who was eavesdropping on them.', '1993-10-17', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7644A06471C54CB28004C4E454013999', X'CEFD1496B6494C62AEF935A22558AC08', 12, 'The Beginning of the End', 'It’s LeeAnne and Rich’s engagement party and everyone is coming, even LeeAnne’s mother, just in time to try and resolve a lifelong misunderstanding. D’Andra must face Dee and accept the consequences of failing to complete her new product on time. Cary and Stephanie try to make Brandi see the negative effect LeeAnne is having on her—the way LeeAnne has pitted all of them against each other. As Brandi begins to see the light, it sets the stage for a truly shocking turn of events that might spell destruction for this group of friends.', '2017-10-30', NULL, '/cue13DeVDB5a4Ji2lNTEgDkrpkN.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7645367E33774828BA411192B59A40A0', X'A0FA50759CE148C199950C0FD866E549', 20, 'Reunion Part 3', 'As the reunion concludes, Sutton and Dorit continue to go head-to-head. Erika is forced to confront Tom’s damning conviction and also reveals how this saga has impacted her relationship with her son. Kyle tearfully explores the end of her marriage, while big sister Kathy struggles to wrap her head around it. Just as the night is drawing to a close, one Housewife storms off, leaving the rest of the women stunned and confused.', '2025-04-15', 55, '/cZugpLjkNZaAQ0NiqEnmh8WOMrr.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
