INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7650D9F1A3884123AE461FEF43E7AE27', X'02849455D14B476B9603EEF5FB5D2AB3', 8, 'That''s Scentertainment', 'Gizelle worries about the status of her relationship; Ashley is faced with the daunting task of moving her mother out her house; Candiace struggles for independence; Karen hosts a Scent event, during which Monique confronts Ashley about a rumor.', '2018-05-20', 42, '/uqiGJtXuWJ6ZsGYh7JbXTo1Xn1D.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7651C029F40241C4A01AA850B9DDD356', X'42684FCA0BC74F4CBF7DF41FD288A764', 9, 'Postman Pat Goes Football Crazy', 'Pat and Julian are to take part in a Greendale football match. Will Pat still have all his skills?', '2004-09-21', 15, '/gxKnqDVs2jwVYMh52rO2Ga24Usc.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'76530FEBB7034AA8A6045217C9072CD9', X'70D9E39768134785887D27D034928BAE', 17, 'Pingu Plays Superman', 'Pingu is out walking when he comes across Pingo, who is brandishing a sword and making mock attacks. Pingo explains that he is acting like the character he’s found in a comic book, and shows it to Pingu. Pingu takes the comic book home to read and tosses it down onto a chair. It lands open at a picture of a superhero in a red cape (similar to Superman) fighting a helicopter. Pingu finds a red blanket in the wardrobe, puts it on as a cape, and acts out the fantasy by beating up the room. Pinga hears the noise and comes in. She finds a book on the floor that has fallen open at a picture of a princess and decides to play at this. Pingu, meanwhile, is still playing at being a superhero, getting more and more boisterous. The game ends when he falls off the table onto the floor and hurts his foot. Pingu is taken to the doctor by motorized sledge ambulance, accompanied by Mother and Pinga. Already waiting to be seen are Pingg, with a hurt foot and Pingo, who has hurt his arm and broken his sword. While they are all waiting Pinga explains what was also in the book, to the amusement of them all.', '1996-07-04', 5, '/yl1NQXVD8shSlzUWFHnjZrbP1bE.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7654A907B913469B88DAC3D082BBE91D', X'332249FA796B4F92B7F8421D523B0BDC', 3, 'The Tea Is Served', 'Kandi struggles with work-life balance. Kenya throws a fabulous birthday party for 3-year-old Brooklyn where Sheree and Drew decide to confront one another over the recent rumors.', '2022-05-15', NULL, '/bpQDxWM2NqROmYPqAakqVKKq6HJ.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7659230779BE4D9DB88AC7A452BD3C07', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 66, 'Big Bird and the mattress', 'The Grouchketeers fish in Oscar''s trash can, and Oscar tells them they''ll be getting clues on their lines for what they are fishing for. Zoe reels in a peanut, and Solomon gets some hay. Bob, Maria, and Olivia are looking after Miles while Gordon and Susan are at a school meeting. The three lull him to sleep with a song ("Lullaby the World").
