INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'768045ED44AE4FDB8D37D97F99E8C491', X'40700E8A1DCE4895BEDE522A13A8BCAD', 16, 'Grow, Zoboo, Grow', 'The Kratt Brothers are taking care of a human baby named Xavier and a baby red kangaroo named Bigfoot, and Zoboo wants to help the two babies grow. Martin and Chris show Zoboomafoo that all creatures grow, but to do so they need food, sleep and exercise.', '2001-04-06', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'768203F94C604E108FED7ECD6A19AE18', X'90CC8678A14F4D05BC1E54A3117895D5', 1, 'A Heroes Welcome', 'The Farthing animals have finally completed their long journey to White Deer Park.They are welcomed by many of the animals like Speedy the Heron (who mates Whistler), Measly the Weasel (who mates Weasel) and Frogs named The Edible Frogs. Some are not so pleased to see them. The silver fox Scarface does not want the new arrivals to be in the park and feels that they are trespassing on his territory. With the journey over the Oath is no longer needed. However the Farthing animals find it difficult to revert back to their old ways before they took the Oath and so continue to uphold it and remain friends. Fox speaks to the Great Stag and together they suggest an area of the park to be allocated for the Farthing creatures to live together how they wish.', '1994-01-07', 25, '/3rWR1QGyppoR8imwTTArr4Vst0B.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
