INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7692C75C4C054A0FA396B11512517940', X'E93F04C273444B93ABBA8BA1B2F8EB35', 57, 'A Cold Day on Sesame Street (0592)', '', NULL, NULL, '/9zM8LQeRTCf3LmLjgqkM6oSMrsA.jpg', '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7692DEEDB35F40308110AC1A71320A7B', X'E6EA14319E67463783AEA11073E8C7E0', 21, 'Reunion (1)', 'The reunion provides fun insights into Erika, Kyle defends her friend, Faye Resnick, in connection with the OJ Simpson trial, Yolanda opens up about her pending divorce, and a conversation about Yolanda''s health leads to a surprising moment.', '2016-04-19', 43, '/6TajplKlt8gU7szCxbXj3PQUGua.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'769A4552D12B4DD0BCFD125F4DD7671A', X'3982796B54514100904246BEDF6A20A5', 13, 'Pingu and the Packaging Material', 'Pingu is out shopping for a birthday present for Grandfather. He comes across a shop selling shells and goes in. He finds a nice spiky shell, which is put into an oval box just the right size for the shell. As Pingu is coming out of the shop he sees Pinga on her way to Grandfathers, carrying a box almost as big as she is. Pinga’s box is bigger than the one he’s got, so he goes back into the shop and asks if he can have a larger one. He turns down the first two offered as not being large enough, and asks for a very large one. Meanwhile Pinga has arrived at Grandfathers and given him her present, which is a picture. Grandfather hangs it up, and Pinga sings “Happy Birthday” to him. Pingu then arrives, carrying a very large box. Grandfather opens the box, to find a slightly smaller box inside. He opens this box – there’s another slightly smaller one inside it! Eventually, inside the fourth box, Grandfather finds the oval box, which he opens to find the shell that Pingu bought. Grandfather then wonders what to do with all the empty boxes from Pingu’s present. He decides they ought to go back to the shell shop, so together they take the boxes back to the shop.', '1993-06-22', 5, '/lzjB6JmDNzEpnnDS7HeoX5rOc8a.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'769B8CA5E7E341A58E335A715A7ECD2F', X'AE8F64D94B834147A44CBFE720381F8E', 15, 'Amphibian Show', 'Elmo and Abby are resting when suddenly it’s time to play the game show, “Find that Amphibian.” Elmo and Abby must find an amphibian before the game show’s tadpole turns into a frog.  They don’t know what an amphibian is, but the announcer gives them a clue- an animal that starts out living in water.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'769CDD0C60604250B4F799F9EA9C3ABA', X'ABFE14EEDB424DDEA96A601FF3C53ECC', 4, 'Sparra''s Kingdom', 'Following the complex clues which promise to lead to Martin''s Sword, Matthias climbs high into the abbey roof - and the kingdom of the crazy King Bull Sparra. A feisty sparrow returns a kindness and addresses him as King Sparra flies to attack Asmodeus - who has Martin''s Sword! The king returns in time to fight who narrowly escapes death. But at least Matthias knows where his sword quest must end in a battle against the vile snake!', '1999-09-17', NULL, '/iW7N3MmWGwsIHhWRdVShRIIQnLI.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
