INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'76B7BABAF4BC4EC3BDFF65E12CDAEC6C', X'F79F69A8E59141D09D4A3D9683DEFBBB', 3, 'We Cut It Close(ed)', 'Tamra regrets her behavior toward Shannon, and Jenn urges her to apologize and invite Shannon to the closing party; with her twins'' college departure looming, Heather contemplates the next chapter of her life.', '2023-06-21', 44, '/lIZwanedcyJhK5PJiIhbUOVG21B.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
