INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'76D880B3018043E2BD31575EEC129FD9', X'2AEBFAD431454BC19DEF5F1D5BDFCFC8', 11, 'The Alternate Side', 'Jerry gets his car stolen; Kramer gets a line in a Woody Allen film; George gets a job; and Elaine gets tired of her boyfriend.', '1991-12-04', 23, '/p7eW8RnmvkJoA72jfFHqlnfxojv.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'76E6C10916BF44B0895605BFCF0D8105', X'63F9BF6D39B344F4B885A56807277A80', 8, 'Tales From Muppetland: The Frog Prince', 'Enchanted by an evil witch, a beautiful princess is forced to speak only in nonsense phrases. One day, she finds a small frog who can understand what she says. The frog claims to really be a prince, also enchanted by an evil witch. Together they must try to break their spells.', '1971-05-12', 26, '/dESzpJmkTRpTUijbefAYUS0EcEQ.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'76E7A0C715174C3AAF2BF4224C8081B1', X'69B3BEFE579A43ADA7D6EC30FFE3ADF7', 40, 'Hawaii Day 6 (1095)', 'The gang''s last day in Hawaii.  Image and description courtesy of MuppetWiki and used with permission under the GNU Free Documentation License (GFDL).', '1978-01-20', NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'76EC7E435AD74AAFB3BCFDF80E61A5E1', X'CC140989C4804586B4608872B416A0B7', 1, 'Humphrey the Lost Whale: A True Story', 'LeVar is sailing on the Atlantic coast whale watching. He and a team of scientists learn about how whales eat and how they live in their habitats in the ocean. Jane Pauley narrates the true story of Humphrey, the Lost Whale, all about a humpback whale who gets separated from his pod and gets stuck under a bridge over the Sacramento River.', '1989-07-03', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'76EEAC43BB45406BA0800123BBFBB32D', X'6F731E6BD3C54DE684E17A19CB650E86', 15, '90''s Pawn', 'The Pawn Stars have seen some pretty dope stuff from the 1990s and they''re looking back at a few items that are all that and a bag of chips: a jacket from Pulp Fiction, a guitar pedal supposedly used by Kurt Cobain, a juror questionnaire from the O.J. Simpson trial, an early Matt Groening lithograph, a couple of Dennis Rodman jerseys brought in by his ex-wife, some Michael Jackson photos, and a few "Wayne''s World" items that leave Rick feeling not worthy.', '2015-12-06', 21, '/dGkwWwkSqp6Z5N791eJmuKBgsfZ.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'76F4446B69084D92A2D56E397BE002F0', X'4D0FD8A552004DFCB96CAE436DC8803C', 6, 'Come a Tide', 'LeVar discusses the weather: how it is traced, tracked, and covered in the media. Kids our shown how they can make a "soda bottle tornado", how a barometer works, and read the book, "Come a Tide". All this is prelude to the dramatic footage of Hurricane Hugo as it wrought havoc on South Carolina in 1989.', '1992-10-12', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
