INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'774F5883B5754088ABD057FAE41849C7', X'C9ADC698BE924DD794ADD8F6759361CA', 62, 'Episode 62', 'Rogers tries on leg braces and works crutches before he visits Chrissie Thompson and Mrs. McFeely. In the Neighborhood of Make-Believe, Mr. McFeely helps Donkey Hodie put the finishing touches on his invention.', '1973-05-15', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'775249DC4B5C41B8BB343FD5D48C0E74', X'8610109B4FB94EAEBE54C549FAE5ECC8', 3, 'Scooter Computer and Mr. Chips- Number Cruncher', 'The last of the original series were four segments about the then-novel personal computer technology. The shorts featured two characters by the name of Scooter Computer and Mister Chips, and so these were the only episodes in the series to feature any recurring characters.', '1983-11-26', 3, NULL, '2026-04-03T17:13:55Z', '2026-04-03T17:13:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7761C9550B544675A499C029F0F0A748', X'C21DBD225E2E4414BB67750399AAF6F0', 12, 'Help Wanted', 'The Pawn Stars lock and load as a triple barreled firearm made by famous European gunsmiths blasts its way into the shop. Will the guys hold their fire on this combination rifle and shot gun, or will they pull the trigger and make a deal for the rare weapon? Then, a man drops in with a collection of antique children''s toy piggy banks made of cast iron. A favorite among collectors, will these tot toys cost Rick a pretty penny, or will he save his money for a rainy day? Later, the shop is looking to hire a new broker to help cover the night shift, and Rick puts Corey and Chumlee in charge of recruiting. Will the guys be able to attract some major league talent, or will they get stuck in the minors?', '2012-01-02', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
