INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'778A1CAA1B2E45D7B796BB4D18AB3042', X'A4843A51AEEF427C902C7FB3BD670CD4', 25, 'Listen Up!', 'Bear receives a package in the mail containing a tape of soothing sounds. He''s eager to sit down and listen to them, but Ojo is worried that the tape will disturb the game of "camping in the woods" she''s playing. When she learns it''s soothing sounds, she''s eager to hear them, but then Treelo shows up and starts making noises of his own. At first, Ojo is irritated, but then Bear helps Treelo with making some sounds that won''t bother Ojo. All of this gives Ojo a great idea for a real camping trip. Meanwhile, Tutter is busy dancing, and doesn''t want any part of the camping trip when he hears about it. Pip and Pop are interested, though, after Bear tells them about it on their plastic cup telephone.', '1997-11-21', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
