INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'778B1664AB6D4818840FAFAD9488DA32', X'110E346736984E19A35BF6EBBAEB4D6B', 3, 'The Pied Piper of Hamelin', 'Eric Idle plays a wandering piper who is hired by a selfish mayor to rid his town of rats. The piper is good to his word and leads the rats to a watery grave.However when he asks for payment the mayor reneges, thus causing the piper tp play his pipe for an alternate result -- this time leading all the children out of Hamelin never to be seen again.', '1985-04-05', 51, '/j7SlQw1PKDATP0BYvzDWJz4dXIu.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
