INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7876048B64C54EFE87C7E3D6F0EBD750', X'6F731E6BD3C54DE684E17A19CB650E86', 45, 'Hollywood Goods', 'Take a trip to Tinseltown and revisit the coolest Hollywood items ever to appear on Pawn Stars: a letter terminating Marilyn Monroe from her 20th Century Fox contract, a life-size replica of the classic "Creature from the Black Lagoon," the ''51 Chevy convertible driven by Hollywood icon Steve McQueen in his final film, a rare collection of unpublished photos of Paul Newman, a prop shield used in the 1963 masterpiece "Cleopatra" and a whip supposedly from the Indiana Jones film franchise that has Chum snapping to attention.', '2016-07-20', 21, '/Ax6a6Xu2Aqx6MGGrnRKyX5nZkl.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
