INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'79BD297D7AF74CF2B8D61A343AE2F30C', X'5C1B881FAC584D72B63F209952D4F902', 1, 'Episode 1', 'Expedition Egypt: Treasure and Camels  Of the Seven Wonders of the Ancient World, only one still stands today, the massive Pyramids of Cheops, Chephren and Mycetimus, built by the Pharaohs, nearly 3,000 years before the birth of Christ.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'79BD92664FB247C38BD2BD1B7DCC303E', X'C7994637B7C742C7AAEE1BFF4144FE23', 20, 'Reunion Part 3', 'The reunion concludes with a surprise appearance from familiar face Kathy Hilton, whose presence draws mixed reactions from the ladies. Kyle recounts their difficult road to reconciliation and what it took to work through past wounds with her sister. Emotions continue to run high when Kyle opens up to the group about her troubles marriage. Faced with tough questions about her separation and the state of her friendship with a famous country singer, it becomes clear to the woman that Kyle''s future hangs in the balance.', '2024-03-13', 44, '/AttT9YwUlD0KoIcZoMy2es3Rvpe.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
