INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'79C214250FF64B0FA143E537F07B2694', X'63F9BF6D39B344F4B885A56807277A80', 21, 'Studio DC: Almost Live! - The First Show', 'Hosted by Dylan Sprouse, Cole Sprouse, and Miley Cyrus. With songs, dancing, and backstage antics, The Muppets and Disney Channel''s biggest stars team up for another fun variety show.', '2008-10-05', 26, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'79CA2973BFD640A5A460AC6A3D5C3B03', X'36EA381466B44986B6EE44559D3562C1', 9, 'Midnight in the Garden of Tea and Shade', 'Cynthia and NeNe disagree over certain parenting skills. Cynthia reveals that she is worried about Noelle. Porsha and Kenya bond over both wanting children. Porsha receives some wisdom from NeNe. Kenya attempts to make peace with Phaedra', '2013-12-29', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'79CD64AC90D64D22A57CDAAB6D1CCC2B', X'6F731E6BD3C54DE684E17A19CB650E86', 18, 'The Pawn Before Christmas', 'Go dashing through the snow with the Pawn Stars when an 1800s one-horse-open sleigh rides in. Will Rick and Corey jingle out an offer or will they get snowed in? Next, a J.H. Rector rifle aims for a deal. Will Rick take a shot or will the numbers be off target? Then, things get jolly when unpublished Christmas art from Mad magazine comes down the chimney. Will Corey say "ho ho ho" for a sale or will he be a scrooge? And later, a Christmas tin from WWI unwraps itself. Will Rick be singing carols or will he shout "bah humbug"?', '2015-12-17', 21, '/bTjcSthnkvnvijnkBLtA0DDtEIi.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'79D8C80C494A49E1A3E22B55A01D6F10', X'FD0F7DFB28AA46879EF88FF0088CE25A', 18, 'The Princess Story', 'Abby and Zoe ask Leela to help them write a princess story; imagination.', '2014-01-16', 58, '/3vxulXZ6XvDJK2yIMaxc2eM15ha.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'79D9236FF02D41EEB07ED33B21E9D819', X'D3E13496E3C8490383B45A31FEDEE232', 16, 'The Deserter', 'Aang and his friends go to a Fire Nation town so that Aang can witness some firebending, but their plan soon goes awry when it’s discovered that he is the Avatar. Fortunately, he''s rescued by an individual who serves a firebending master named Jeong Jeong who has abandoned the Fire Nation, so Aang decides to use this time to attempt to learn firebending. The firebending master, however, seems reluctant to teach Aang.', '2005-10-21', 25, '/rgdsLIpTCHPrq1DvOXtHh65qEp2.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'79DBCBA6528C478F886187FB8881A88B', X'02849655BD954D8DAF3B03321918EEEE', 14, 'Madeline and the Marionettes', 'Madeline and the girls help to reform an unhappy puppeteer in the Jardin de Luxembourg, who, because he never had the talent to be an opera singer, puts on marionette shows that twist the plots of classic fairy tales and disappoint children in the audience.', '2000-12-08', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'79DD0452F5DB43158C39C82E7DE26F73', X'DF77DBA2BBDA4F3897138D5C856F852E', 4, 'Jolly Tall', 'A mysterious box arrives in the playroom. After approaching it cautiously the toys discover it contains a new friend; Jolly Tall the giraffe. With Jolly still inside, everyone sets to work to turn his box into a cosy house for him. There is a problem though; Jolly is too tall to get out of the door! Using a toy crane, the friends finally manage to rescue Jolly and Jolly, in return, performs a rescue of his own. In the end the toys find that something Bramwell has been knitting all week turns out to be the perfect present for their new playmate.', '1993-10-24', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'79E19B02AA0149CEB5C5A75C515B4DCF', X'DA06465B91544FEBA455374DF7DAB02F', 6, 'How many balloons to raise Snuffy? (4088)', 'Snuffy wants to be a cloud in the sky.  He wonders how he is going to get up there, and then realizes that he could use a balloon to lift him up.  He wishes for a balloon and the Fairy Balloon Person (Richard Kind) comes to grant his wish.  Since it’s going to take more than one balloon to lift him up, the Fairy Balloon Person keeps adding 5 more balloons each time until they reach 40 balloons.  He starts to fly up to the sky going higher and higher.  While Snuffy is happy to be seeing birds and other clouds, he starts to get cold and lonely being all by himself.  Snuffy wishes to go back down, and his wish is granted.  He realizes that everyone he loves is down on Sesame Street and that he would rather be a snuffleupagus than a cloud any day.', '2005-04-11', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
