INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'79EC5AF824BB4D07B9A20A19C2FEC5EE', X'98D80972E53A43DDA03A7703465E6F87', 16, 'Santa Chum', 'Gather ''round the tree with the Pawn Stars as the guys get ready for their annual Christmas Party. With Chumlee in charge of the planning, can he keep it under budget and earn his Christmas bonus? Then, Rick and Corey check out a collection of military promotion documents signed by six different U.S. Presidents. Covering a single soldier s rise through the ranks starting in the Civil War, will this collection have the guys eager to enlist in negotiations? And later, Corey is offered an Italian movie poster for "Bullitt" starring Steve McQueen. Knowing Rick s love of everything McQueen, will Corey race at the chance to buy the poster, or will the deal crash and burn?', '2012-12-17', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
