INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'79F48CBCD1844811BB5DDD0ADBEE49FD', X'02849455D14B476B9603EEF5FB5D2AB3', 7, 'Blue Skies and Blue Eyes', 'The ladies continue their weekend escape in the woods, but it''s not quite as relaxing as Ashley had hoped. After a few glasses of champagne, Karen starts hurling insults at Robyn, leaving all the ladies confused. Tensions come to a halt for an afternoon of fishing, but things escalate once again when allegations swirl over Monique''s denials and Karen''s possible secrets.', '2018-05-13', 42, '/y1fH1m0o1sDjCEyy2oeF37ZrP3X.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
