INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7A13738BCC694CB8AC2C20A0E823BBB7', X'ABEB8D075C864F6AA110B11CBA2A4138', 19, 'Sozin''s Comet: The Old Masters (2)', 'While on the island, Aang seeks guidance from his past lives, but is not pleased with what he is told. The island, in fact, turns out to be a lion turtle from which Aang is given the guidance he had been seeking. Meanwhile, after the tracker is unable to track Aang, the rest of the group decide they must find Iroh. While tracking him down, the group meets up with The Order of the White Lotus, a group that transcends the division of the four nations.', '2008-07-19', 23, '/51ceqvaljO0hqBjdDtmUzliHwVp.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
