INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7A586AA5AFC649D69D3BA705C335AD5B', X'D9973960273B4A92A7DA62EFE8860D09', 11, 'All Bets are Off', 'Whitney hosts a dinner with her dad and siblings in an effort to reunite their family, while Jen sets Heather up on a date with Sharrieff’s best friend. When Whitney invites the women for a girls getaway to Vegas, Lisa, who’s still upset with Whitney, has reservations about going. And when Jen takes Heather on an exclusive shopping experience, things take a turn when Jen begins to question Heather’s true loyalty.', '2021-01-20', 42, '/h6xQcyeojJcl2G9udbE1o042kmE.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
