INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7A6AB5DE5C464187B9E5D1FA5697FAC4', X'BC6D3E376E5E472D90AA4C6DF1F7DEF8', 10, 'A Family Meltdown', 'The Browns begin a road trip to meet another polygamist family. They check in on Christine''s mother who has plans of moving to Vegas. Next, they visit their old home in Utah and are overwhelmed by past emotions. And Kody does something to upset one wife.', '2015-01-11', NULL, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7A6C2504EBD2403E93FD2E74ED3DE2B0', X'A79A245FACAB4EBEAEE929867F9E52F6', 6, 'I Will Survive Part 2', 'It''s Mykelti''s bridal shower, but Janelle''s terrified of performing with the Sister Wives. Christine gets emotional as she cuts up her wedding dress to make cloth flowers for Mykelti''s bouquet. And Maddie tells the family her big news.', '2018-01-21', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7A7519F8AFC6443DB7022914CC4625C7', X'5DB3FF78E43948E18F67988ECBF85D17', 4, 'The Three Invincible Musketeers', 'Dogtanian wakes from a dream about Juliette to the slightly less attractive sight of her uncle. Juliette''s Uncle tells Dogtanian he can stay in their house as long as he wants and that Juliette is a lady-in-waiting for the Queen. Their conversation is interrupted by the sound of a fight outside, they run out to see (a slightly drunk) Athos fighting a gang of the Cardinal''s Guards without drawing his sword...', '1981-10-30', 24, '/aTUzr3aGqwbs5FmeUnCcxhOnSoK.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
