INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7A76C944FEF14BFD8AB4EC4724B8DED4', X'4D2CAC0F38FD438B8AFAACF43952E535', 222, 'Episode 222', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. Including The story of The Three Birds told by Tim Gudgin, Ballet for Athletes - David Blair, Premier Danseur of the Royal Ballet, assisted by David Morse, shows how ballet exercises can help all athletes, and talks to Sandy Davies, England international (long jump) and past junior champion (high jump) and the Blue Peter Vet with ''Petra''.', '1963-03-04', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
