INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7ADB3D83C03C4D048AC12B85B771B497', X'0BBD380C5CB846A68838B5D60223C073', 19, 'Juliet Prowse', 'Muppy, the favorite pet of The Muppet Theatre owner J. P. Grosse, becomes a prima donna when Kermit reluctantly allows him to do a musical number with Scooter. Muppy even gets his own dressing room and star billing, but Kermit draws the line when the dog asks to change the show''s title to The Muppy Show. When Muppy locks himself in his dressing room and refuses to perform, Scooter does the number with Fozzie instead.', '1977-01-16', 26, '/20KznOBYheAjEAb4zEY3wLvyrAi.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
