INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7B48B94E6781416587CE0E6E4041BFA9', X'DD4554C26E74499A808A7DAD5F2BE50F', 3, 'Hazard Pay', 'Walt and Jesse formulate a new business plan. Walt shares a secret with Marie.', '2012-07-29', 48, '/l84H1dZVkQGgFVomKHc67RKaEC2.jpg', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7B4E6B4D5E79462F9F041E55A7DA6C84', X'E03D79BDE01F4414B0B3F3B5F26E97F4', 3, 'The Diaper Incident', 'While shopping for baby diapers for Sue, who has run out of them on a baby-sitting job, Frankie is completely humiliated when a clerk assumes she''s shopping for adult diapers. Meanwhile, after getting on Mike''s case to get a physical exam because she thinks men tend to fall apart faster than women as they age, Frankie proceeds to throw out her back and hides it from Mike, who tells her he received a clean bill of health from the doctor; a clueless Sue falls for Axl''s friend, Sean, who barely notices her existence; and Brick begins to test all of the age-old urban legends parents tell their kids - such as not to swallow a watermelon seed for fear one will grow in their belly - after discovering Frankie has used these white lies on him in the past.', '2010-10-06', 22, '/1zusev8YZq4unD86ZPiR3lNzSlw.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7B5173F96C564903A26C664AD6F6D470', X'CC140989C4804586B4608872B416A0B7', 8, 'Tooth-Gnasher Superflash', 'LeVar, the jack of all trades, becomes a garage mechanic for this episode. Much of it fantasizes about dream cars. Then comes a real dream car, which a man has decorated, followed by stock footage of an assembly line and a piece on a solar-powered car named the Sunraycer. Victoria Jackson narrates Tooth-Gnasher Superflash, the story of a family that buys a car that is not like any other.', '1990-03-28', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
