INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7B664DF542F44A438A8D616095D01793', X'432A6ABDDCCA44CC82CEFB39E33B8949', 27, 'Episode 27', 'Rogers has his eyes examined. An accident also occurs in the Neighborhood of Make-Believe, when the Trolley runs into a toy car Lady Aberlin and Corny left parked on the tracks.', '1971-03-23', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7B6758653D6948CBB874DA3ABAA9446B', X'A0FA50759CE148C199950C0FD866E549', 18, 'Reunion Part 1', 'On the heels of a tumultuous season, the ladies of Beverly Hills reunite to work through hurt feelings and shocking allegations. Dorit speaks out about her separation and feeling unsupported by Kyle, but a surprise statement leaves her at a loss for words. Bozoma responds to those questioning her relationship with Keely and accusations that she was being manipulated by Dorit. Garcelle has to answer for hurtful insinuations she made throughout the year.', '2025-04-01', 43, '/p2Nlgu672VIm8U62SybPLiTL9aH.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7B697BC676624200A40AA0ACC8927805', X'B1D55597D9D24EEEAB9546DBB163291A', 21, 'Pingu Dreams', 'It is time for Pingu''s bedtime, and he falls asleep while Mother is reading him a story. As Pingu sleeps, the igloo jumps up and down before floating away. His bed then sprouts legs and moves around. Although being rattled at first, he has lots of fun riding the bed, but he is unaware that a giant non-tusked whiskered walrus (or a leopard seal) is stalking him. The walrus/leopard seal eventually shows himself to Pingu and puts the igloo on top of him and the bed. The walrus/leopard seal takes the igloo off, squishes and stretches Pingu as if he were a plaything, and as the bed tries to escape, the walrus/leopard seal takes the mattress from it and eats it like a chocolate bar. While the walrus/leopard seal is distracted, Pingu and the bed run off in fear, but Pingu trips over a ledge and falls down a steep mountain slope. The minute he lands at the bottom, Pingu wakes up, finds out that his "snowy mountain" is actually the bed, which isn''t moving, and realizes it was all a dream. Pingu then sadly tells Mother all about it as she comforts him.', '1990-05-12', 5, '/uIyHcEAc44d6PIhowReYIQYgLg5.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
