INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7BD212F045F14A019C1E9B1BA10994D6', X'9193E795DA7C40ECB68FF63AA7D5174F', 11, 'A Day in the Life', 'The 30-minute special documents one epic day of production as tackled by hundreds of crew members across three countries. In addition to a behind-the-scenes look at the action in Dubrovnik, Croatia, Belfast, Northern Ireland and Seville, Spain, the preview includes several never-before-seen features.', '2015-02-08', 26, '/xUVCZNoGKrp4IbbExcMWUUOwDvT.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
