INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7BE5F8D3EF2147298DC8E9849A845462', X'7C542833ED0A42729C53E822408AB434', 16, 'Sketching the Wildlife', 'On a wildlife sketching trip, Norman wants to find the most spectacular creature to sketch, but this gets a bit tricky when Lily Chen tags along.', '2024-11-04', NULL, '/3N72fN7VA50CQtFQ7nwleXB0GOc.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7BE61CA02B8E4788B97234ECFE1A4809', X'98D80972E53A43DDA03A7703465E6F87', 4, 'Stick To Your Guns', 'Pledge allegiance to the Pawn Stars when the guys check out a flag cut straight from a WWI fighter plane. Flown in the same famous squadron as Teddy Roosevelt s son Quentin, will the guys engage in a dogfight for these stars and stripes or will this deal cry mayday? Then, Rick checks out a gun that belonged to Old West lawman Fred Coates. Used to fend off cattle thieves during the Wyoming Range Wars, will Rick be quick to draw his cash, or will this deal be put out to pasture? And later, when Chumlee gets caught faking his timecard, Corey has to fix the problem. Will he find a way to beat the clock?', '2012-11-12', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7BE8E948AAA04D85837E1E54D60A7DCB', X'E1063F8766C24E2DA91353362941AA19', 61, 'Episode 336', '', '1972-01-31', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7BE9E2651FC24EDAA33E7194D70FF7FE', X'4C79C0B621A442778967BE1E791EFDBE', 18, 'Pingu Boogaloo', 'Pingu is playing indoors when Mother comes by, turns on the radio, sits down and starts knitting. Pingu stops playing, and starts dancing to the swing music that is playing on the radio. The phone rings, and Mother turns off the radio and answers it. Pingu gets ready to turn the radio on again but is annoyed when he sees that Mother is clearly in for a long chat as she’s now got her knitting and is still on the phone. He has an idea, and gets the headphones from the cupboard. He plugs them into the radio, turns it on and starts to dance again. Father then comes in and consults the paper. He takes out the headphones and switches stations on the radio to listen to the world cup final, ignoring Pingu’s protests. Pingu goes outside and past the ice rink where, amongst various activities(including the hockey match father was listening to), a penguin is playing music on a special record player on runners that he’s pushing round the rink. Unfortunately, as it come past him Pingu can hear the music and can dance, but he can’t hear it when it’s the other side of the rink so he has to stop dancing. Pingu leaves the rink and goes past an igloo from which music is coming, so he knocks on the door. A penguin, singing opera, bursts out and Pingu hurries away. Then he comes across Pingo listening to the radio on headphones outside his igloo. Pingo lets Pingu share the headphones so they can both listen, but it’s not long before they have a tug-of-war that ends up with broken headphones. Pingu goes home, gets his headphones and gives them to Pingo, and goes back indoors. Mother is playing with Pinga, so Pingu sits down dejectedly on the sofa. Realising what is wrong Mother has a quiet word with Father, who gets out a record and starts playing swing on the record player. Pingu immediately cheers up and starts dancing. Pinga, and Mother and Father, soon join in.', '2006-02-21', 5, '/ifXFAhQV8qnOD1Dhh29u9rmuMB8.jpg', '2026-04-03T17:22:21Z', '2026-04-03T17:22:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7BEBD013C81B480D880DD54292DBCF84', X'D1D267DDE27F4543ACB80D28F676512A', 17, 'Episode 17', 'with Valerie Singleton and John Noakes', '1967-11-23', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7BFB1B516A5143AB8608295DD889A3EF', X'5BA20443D99F482081F66832D3F2BC4F', 17, 'Inventions', 'Almost everything around you, from paper clips to computers, was thought of, designed, and built by humans. An invention can be a totally new idea, or an improved variation on something that already exists. Inventors invent to solve problems and make life easier. Anyone can be an inventor, even you. All you need is an idea, and sometimes you don’t even need that. Silly Putty, sticky notes, X-rays, pretzels and nylon were all accidents that became great inventions after more research, experimentation, and design.', '1996-02-21', 26, '/algp01d3p3O7sO9q9qf1nD7XCf.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
