INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7C67418F98A4415AB0ECD5F1F5ACF2D8', X'C67A878749714961B5361FF01924E2A9', 11, 'The Making of Arthur', 'When Matt Damon announces a new series called Postcards from You, Arthur and his friends are excited by the opportunity to create videos about their daily lives. Everyone has a great idea for a video except Arthur, who isn''t sure what to do. He keeps bouncing between ideas, but can''t settle on anything, and finds himself hindered by D.W.''s insistence on participating. He also has to contend with having been chosen as Buster''s project.', '2007-09-03', 13, NULL, '2026-04-03T17:37:58Z', '2026-04-03T17:37:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7C6FB884103A47758F47C2E79297E9D7', X'F13CB62284E34654A8F10CEAB09A9CA6', 20, 'Franklin Plays Golf', 'When Franklin sees his Dad warming up for golf season, he becomes interested in the game as well and soon agrees to an outing at the golf course with Mr. Turtle. Bear is worried that the outing will conflict with a soccer game, but Franklin feels that he''ll have plenty of time for both events. When Franklin finds that golf not only takes a long game, but he isn''t as good as it that he thought, he enlists Bear''s', '2002-07-01', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
