INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7C7871E6853249F3B4E958356E8E4E7D', X'ECB64EF34F8045A7B4A9C04434B02E35', 48, 'Chumlee''s Last Laugh', 'Get behind the wheel with the Pawn Stars when Rick and Corey check out a massive Dukes of Hazzard toy collection. Will these good ol'' boys drive away with a deal or will they crash and burn? Then, time flies when a pocket watch engraved with Henry Ford II’s signature lands in the shop. Will Rick wind up with this automobile industry heirloom or will he be forced to clock out? And later, when Chumlee takes the stage as a stand-up comic, will he leave the crowd laughing or will the joke be on him?', '2014-06-12', 21, '/zMtNMeQ4gvMaLLKNkefQsmi2Yhm.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7C8465B5A93A4C1B91FD551623D48939', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 135, 'Sein-imation: Pinky Toe''s Wild Ride', 'Sein-imation is a series of cartoons of Seinfeld episodes. They were released on the Seinfeld DVDs as special features. They used audio from a set episode placed over a new "toon".', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7C878FA698264C1387B00C4A5DBF09BC', X'3FC7C152E4F6426AA89936EC454C4403', 63, 'Rope Trick', 'When Quetzal''s magic potion spills Ord''s jump rope after Zak and Wheezie loose their balance, it becomes alive. Zak and Wheezie want to jump rope, but don''t know how. With Emmy''s help, they learn that some things are harder than they look, but with determination, anything is possible.', '2000-04-18', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7C8BF0D77AFE4F32AC4CE16C199CCE17', X'EA1650C2E4F146C793BA74B5D45D08E5', 8, 'Is There a Doctor in the House?', 'In preparation for the birth of their child, Phaedra and Apollo arrive in Augusta where her doctor will induce the baby. Back in Atlanta, the other girls convene at Kandi''s birthday party where Kim and Cynthia grill Dwight on Phaedra''s mysterious due date. Meanwhile, Nene meets with a local TV station in hopes of snagging a job as an entertainment reporter. Kandi later visits the soon-to-be-in-labor Phaedra and finally solves the mystery of Phaedra''s due date. Sheree invites the ladies over for a party, but drama ensues when NeNe realizes that she knows something scandalous about Sheree''s date, Dr. Muhammad.', '2010-11-21', 43, '/r5qro3s7xkkdN3snqbDhCynMPw8.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7C8CE7CB75274AC681AC31551CC2F20A', X'913F846D85DF46948DD40D5909F78887', 1, 'Integrity', 'Embarrassed that his history project -- a reproduction of a relic that his father brought back from a trip to Egypt -- is too lame, Zach tells his class that the relic is real.  When his teacher asks permission to display the ancient relic in the History Fair, Zach’s “harmless” embellishment is in danger of becoming a major school-wide deception.  Concerned that this would harm Zach’s integrity, Plato tells a wise and well-known tale about a boy whose lies get the better of him.', '2000-09-24', 30, NULL, '2026-04-03T17:38:35Z', '2026-04-03T17:38:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7C935D9EB2BA4E46894ACB3B95A27657', X'C13CAC4525544775BB86C6AA65C1CA2E', 10, 'Hidden River', 'Steve dives into a crocodile-infested river to catch a turtle.', NULL, 44, NULL, '2026-04-03T17:39:10Z', '2026-04-03T17:39:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7C971044EE594657A65373A941245665', X'C4D795AE6AFA47D698194DD057030A3C', 9, 'A Mother’s Love', 'Cynthia plans an intimate college send-off for Noelle that ends in a major meltdown. Porsha and Dennis are ecstatic about their first sonogram, while Shamari and her mom foster a new bond watching over Shamari’s twins. Nene and Gregg host a family meeting with their sons to educate them on Gregg’s cancer. After a recent misunderstanding, Kandi tries to mend Momma Joyce and Todd’s relationship and turn his sour lemons into lemonade.', '2018-12-30', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7C9A93B17B1345CBB54FEFF3C379E6B3', X'34BDCCFA3C144E1C914885C29AADC0E1', 3, 'Sharks', 'Jumping at the chance to compete with Discovery Channel, Chris and Martin go to the Caribbean to dispel myths about sharks.  They have an ideal shark expert to help them.', '1996-06-05', 30, NULL, '2026-04-03T17:11:47Z', '2026-04-03T17:11:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7C9BC005644F4DAA9003A606B612FA8E', X'02849655BD954D8DAF3B03321918EEEE', 15, 'Madeline and the Ice Skates', 'Madeline gets a new pair of ice skates for her birthday and becomes so obsessed with practicing her skating she doesn''t have any time to play with her friends. When she is pulled out of the blanket, Madeline spins around like Taz for a few seconds before wobbling about and trying to regain her balance.', '2000-12-15', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
