INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7CA93B9EAB084FA188915503EFC6C482', X'4892E2AF46C14B4EAC81EAC161B5A347', 5, 'Episode 5', 'Peter Purves and Lesley Judd England goalkeeper Peter Shilton joins the team to announce the results of the Save of the Century Competition.  LESLEY helps to give Rags, the pony for handicapped riders, her first-ever bath.', '1977-09-26', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7CAD5074851C488E9FDA51F2D75B7B17', X'A84AA42DE73840818DA91FAEC0209EE9', 19, 'The Final Four', 'Mike''s dream comes to fruition when Frankie''s boss, Mr. Ehlert, offers him two tickets to the Final Four. Unfortunately, Frankie''s uncle dies and the funeral is set for the same day, leaving the two in a battle and Frankie making Mike chose what life event is more important to him. Meanwhile, Sue gets Brick out of going to a birthday party by impersonating Frankie over the phone, but the plan hits a bump when Frankie needs to call and tell them that Brick cannot attend because of the funeral.', '2010-03-31', 22, '/hdcH9c8O4IjnTgsdM2zTLAHnBYy.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7CAFEAFA4201401DB65D111FACB002AA', X'C21DBD225E2E4414BB67750399AAF6F0', 18, 'Les is More', 'Get strung along with the Pawn Stars as a 1961 Les Paul SG guitar jams into the shop. Owned by a member of Les Paul''s family, will the guys be able to fine-tune their offer, or will the deal de-tune? Then, Rick and the Old Man are presented with a copy of National Geographic from 1969 covering the momentous Apollo 11 moon landing. Will this special issue drag in some moon rock sized profits or will they abort their mission? And later, when Rick brings in a new hire to work the night shift, Chumlee volunteers to help train them into a pawn superstar.', '2012-01-23', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
