INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7CF890D6FCCC4411BA58A23AC61F1631', X'4060AD7F4B8F43938EB166A150B928B6', 13, 'Elmo and the Healthy Heroes', 'The healthy Super Food Super Heroes help Elmo and his friends find and try new, colorful healthy snacks and learn that breakfast is the most important meal, giving them the energy they need for the day.', '2021-02-04', 26, '/fFhZlyZd8HMh9vuF2alb0PAKGFP.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
