INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7CFCC6A967BB48608DDD0BCD281E7A8C', X'495D4222B33A46FA83513265798E558B', 8, 'Wunderpants', 'Pete becomes blessed with magic powers after he uses a microwave to dry his undies. Unfortunately, a frog race and a shrinkage problem leave Pete all alone and a bit undressed...', '1990-05-25', 24, '/srVG0gNv0kDTbcord05vpWUL3lS.jpg', '2026-04-03T17:40:40Z', '2026-04-03T17:40:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7CFEFCE9899B4AB78E9A40BA4D6876F8', X'02849455D14B476B9603EEF5FB5D2AB3', 4, 'First Ladies and Second Chances', 'Ready to close the chapter on her days of being the "First Lady" of the Black Church, Gizelle decides to write a controversial book loosely based on her life. Monique and Robyn try to get to the root of their issues, while Candiace hopes to step out from her mother''s shadow. Ashley seeks the advice of a therapist to help solve her marital problems and as a result, tries to make the impossible choice between her husband and her mother.', '2018-04-22', 42, '/479ZSidZkqwcEzRrjqMCO5c1AmC.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7D030BD86C5C4A59B96125C9CD069B40', X'34674C90410E427CBE4D2A6F6F865A80', 25, 'Some Like It Not', 'Take the Pawn Stars hostage, when a $20 bill from infamous hijacker "DB Cooper" skydives into the shop. The only unsolved airplane hijacking in U.S. history, do the guys pay a king s ransom, or will negotiations get lost to the wind? Then, a guy marches in with a sword from the Civil War. Made for the foot artillery, does Rick see a sharp profit to be made or will he lose his edge? And later, Rick and Corey check out a collection of paintings by actor Tony Curtis. Will these works give them a whiff of the sweet smell of success?', '2012-08-27', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7D050EB540834AE994F72BC09BAC8249', X'FD0F7DFB28AA46879EF88FF0088CE25A', 13, 'Big Bird''s Nest Sale', 'Snuffy accidentally sells Big Bird''s teddy bear while helping him with his nest sale.', '2013-11-14', NULL, '/1r2dwoBuzKgROd0UP3Wu8CGi1Op.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7D0755764E5B4D9E8662D4F882ADA449', X'1415EF1C411A4C26814A7C79C3628BC2', 3, 'A New Low', 'The ladies head to the Hamptons for a weekend of fun and an early birthday dinner at Ramona’s. Carole is staying at Bethenny’s and the only thing she can talk about is the election. Splitting her weekend between Luann’s and Ramona’s homes, Dorinda prepares to see Sonja for the first time since learning about the gossip she has been spreading about her for months . Ramona takes the wrong approach with Bethenny when asking about her film role from 20 years ago.', '2017-04-19', 60, '/gYXhLCow5o4eX0kH3Eamq9DuRld.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
