INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7D106D0C856E4F0B8401F8EFB6C9F82A', X'4892E2AF46C14B4EAC81EAC161B5A347', 55, 'Episode 55', '', '1978-03-23', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7D128E96F4A9411497F635594F60F191', X'8BDF0AD3A7984D5AB304C7501EAE6867', 9, 'Why Are You Being So Mean To Me?', 'With Tamra Barney''s formal seven-course dinner winding down, Tamra''s son Ryan sees an opportunity to make his move on a very drunk Gretchen Rossi, leaving the rest of the ladies to worry and wonder about Gretchen''s well-being. Lynne Curtin works on her budding jewelry design business. When businesswoman Vicki Gunvalson accuses her of not knowing how to work, Lynne goes out of her way to prove Vicki wrong. Jeana Keough finally moves her ex-husband, Matt, out of the house, but she struggles with how to get on with her new life. The ladies travel to Santa Monica for a trendy shopping day. Over lunch, when Gretchen confides in the women about her finances, it sparks a heated argument between Lynne and Vicki.', '2009-01-20', 44, '/wBpQlllwD1vXYxFCNiHrGjc3d6Q.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7D1836476BBC4205B378C1EC17629EE4', X'68138DE20900460AB58E480688F1E081', 31, 'Scientific Bear', 'The characters of the Big Blue House find themselves feeling many different ways and Bear is there to help sort it out. Things all start when Pip and Pop are happy and excited after they receive a fantastic new toy in the mail --- Clammy, a talking clam. Later, they''re extremely sad when they think Clammy''s broken. Elsewhere, Treelo gets angry with Ojo for spilling his feathers out the window, but Ojo is hurt and worried because it was only an accident. Treelo says he wants to stay angry forever, but Bear helps to see that this may not be what he really wants. Later, Tutter''s hilarious impressions have everyone feeling silly. In the Shadow segment, Shadow explores the feelings of a girl who''s good at rock and roll but has a curl of hair pointing out of her forehead. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7D207F13E52248628804FEA902A8FB4C', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 50, 'A day of photographs', 'Luis, Piri, Grace, and Gordon are gathered to get a group photo with Miles. Olivia, operating the camera, gets them all into place, when Gordon wishes she could be a part of the photo too. Oscar offers to take their picture and assures the skeptical group that nothing will happen.
