INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7D34394E3DCB4BE788D4B4A55F872D53', X'7BC54DF3F32A454EAEF6A9436C35D53B', 50, 'Episode 50', 'Rogers shows the dog that belongs to his son John. At Bob Trow''s workshop, Rogers finds Trow and John working on fingerpaint pictures. Handyman Negri and Lady Aberlin have a message for Bob Dog.', '1970-04-10', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
