INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7D46A68114D74B619C6B60DFBFF25A55', X'42E591E22A884434AE9F3D4B1D685613', 38, 'Open and Shut Case', 'Fly high with the Pawn Stars when the guys check out a briefcase once owned by Charles Lindbergh. Will they be lucky like Lindy on this deal? Then, Rick and Chumlee look at a prototype combat vehicle produced for the U.S. military. The only one of its kind, will the guys try to buy it, or say "no tanks?" And later, Corey is the tie-breaking vote in a dispute between Rick and the Old Man. Will Corey''s willingness to take a bribe or two get him in trouble?', '2013-11-21', 21, '/bZ28SS2zQiJdrx21Tm2dYdyqrSU.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7D4E721C96CC49E2ABE277F44CCC5485', X'EA1650C2E4F146C793BA74B5D45D08E5', 5, 'Hot Mama''s Day', 'Kim states her views on cheating as a guest on Kandi''s web chat show "Kandi Koated Nights." NeNe reveals more than just her new nose to Cynthia, and Sheree has a finger lickin'' good time on a date with the "Love Doctor." Meanwhile, Phaedra gets personal with a jar of pickles for her pregnancy photo shoot. When the ladies get together at Cynthia''s to celebrate Mother''s Day, the topic of sex becomes the main course, but by dessert, NeNe''s marital issues take the cake.', '2010-11-01', 43, '/AnrFAUagApkhjI2Gu2Nwis7RbNG.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
