INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7D770C92060F43D8BCD3D8212F07C6C1', X'4892E2AF46C14B4EAC81EAC161B5A347', 32, 'Episode 32', 'Has the Key-Note Appeal hit the jackpot? Will the keys and cars pouring into the collecting depot reach the two million target on the totaliser?  If so, "Blue Peter" viewers will have provided four mobile classrooms for deaf children in Wales, the Highlands of Scotland, Norfolk and Cornwall.  To start the new year "Blue Peter" travels back in time to the days of old when knights were bold! Peter goes to Knight School and learns the skill of jousting under the expert eye of Max Diamond.  And 52 gnomes invade the studio for a ''live'' phone-in with Noel Edmonds.', '1978-01-02', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
