INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7D8EE668F45F4BDCA694013BB53B375E', X'F07B879456254682AAE1E56966B4C7A8', 17, 'The Ballad of Davy Cricket', 'When Jody’s pet cricket dies, the friends share how different cultures deal with death. Children learn what to do with all the strong feelings that come up when someone (or something) they love dies. They find answers in the traditional practices of their culture, their families and their friends. Nuzzle is so excited to see his favorite dog groomer that Sizzle couldn’t care less. Ben and Skye do not appear in this episode.', '1996-02-06', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7D9400900DE74624B2C7D378EFDB30FC', X'AD4E434833344A088928455D9BA524C1', 11, 'Joan Baez', 'Rizzo and the other rats bother Kermit for a spot on the show, so Kermit asks Beauregard to "take care of them." Of course, Bo takes that literally, and treats them as guests. The rats make Beau their president, and manipulate him into giving them food. The rats eventually become so bold that they decide to take over the show. Kermit says Beau has to kick them out, or he goes with them. Beau chooses to stick with his new rat friends, until Miss Piggy enlightens him.', '1980-12-14', 26, '/m6n9TiNfymGBr9FqXP27RoJqc7g.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7D9C5FA5302D4F8083B77CF4C54FBCB0', X'1A534647384B4C00BB6CA3371AD962EB', 36, 'Most Mysterious', 'Get curious with the Pawn Stars and revisit some of the most mysterious items ever to appear in the shop: a retro Amphicar from the 1960''s, a vintage handcuff collection, a shocking Master Violet Ray Machine, an odd collection of prosthetic eyeballs and an unknown stone that leaves Rick between a rock and a hard place.', '2015-06-11', 21, '/u4dXCtGySZ72U92v213vad6Y0LS.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7DA0B9BA9EC94FCE992F4B7C6177CC1E', X'1A534647384B4C00BB6CA3371AD962EB', 10, 'Underground Pawn', 'Get on board with the Pawn Stars when Rick checks out an 1800s first edition book about the Underground Railroad. Containing first-hand experiences from slaves who escaped, will Rick go the distance to get his hands on this rare piece of history? Then, Rick gets ready to play ball when a full set of a baseball cards given only to troops during Desert Shield is brought in. Can he score the winning run or will he get thrown a curveball? And later, Chumlee tries to come up with his own collectible trading cards. Will Chum be able to cash in or will Rick stop the presses?', '2015-02-19', 21, '/hQzGGrxGbN0emMb92wMUvFVBKXt.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
