INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7E17446148F3443593E19F26B69158E9', X'110E346736984E19A35BF6EBBAEB4D6B', 2, 'The Snow Queen', 'Kay and Gerda are best friends. A wicked goblin who likes to cause trouble casts a spell on Kay to separate the friends. The Snow Queen snatches Kay away to her castle. Gerda must go find him. Will she ever find Kay? Is the Snow Queen helping Kay or is she freezing his heart forever?', '1985-03-11', 51, '/9XovOcFk3fSrUaFX5uxms8kzIeK.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7E1AAB285DB340DD83FF6DC8C60B344E', X'DA06465B91544FEBA455374DF7DAB02F', 18, 'What Happens Next? Show (4100)', 'Elmo is excited to play a messy scientific game show called, "What Happens Next?" with Oscar as the host! With the help of his adult friends on "Sesame Street", Elmo learns lots of new things about what would happen next if, for example, Slimey jumps into a little mud pool from a low diving board, and then from a high board. Would there be a little splash or a big splash? Elmo uses fun science words such as hypothesis when making guesses about what would happen next. Elmo has a great time learning to observe, making guesses, and checking to see if his hypothesis is correct!', '2005-06-20', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7E1C21D33CCB4401936600439CC9B9F7', X'0B9D7AE7218E45A08C3AE69912F5A6ED', 5, 'Franklin''s Masterpiece', 'Franklin wins a contest with a painting that he, Bear, Beaver, and Fox painted.', '1999-10-25', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
