INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7E2ABE3D24F04F02ACCAA7D53FA51C9C', X'3087A3EDE94E42769D02A78183DEA1D3', 7, 'I Do... But, I Won''t', 'A wife makes a big decision during a Caribbean trip. Meanwhile, Kenya fumes when NeNe questions her behavior, and Porsha infuriates one of the ladies, leading to an all-out showdown.', '2012-12-16', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7E2CF73C4E3E4428954776017597C1A0', X'5C4E51C6E20746AD875C72988EB1E13E', 25, 'Silent and Deadly', 'The Pawn Stars are on hallowed ground when a piece of marble from Abraham Lincoln''s tomb enters the shop. Without any documentation to authenticate the item, can Rick trust the seller to be honest like Abe or will the negotiation die a quick death? Then, a seller comes in with an antique African sword apparently used for beheadings. Will the guys lose their minds over this piece and buy it, or will they not be sharp enough to execute a deal? And later, Chumlee and the Old Man are speechless when a nearly hundred-year-old Charlie Chaplin wind-up doll tramps into the shop. Will they manage to make a blockbuster buy, or will this negotiation turn into a comedy of errors?', '2011-08-08', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7E2D3A3B5A6B4C66A2EA178FC706533B', X'CA70502BD8624CDD8071468D6644D517', 9, 'Chapter Nine: The Piggyback', 'With selfless hearts and a clash of metal, heroes fight from every corner of the battlefield to save Hawkins — and the world itself.', '2022-07-01', 143, '/fvoa0Hosu4yK7TUiHglV8TvjMUB.jpg', '2026-04-03T15:40:40Z', '2026-04-03T15:40:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7E2D7CB50FDE4D2E929F75DA0EAE8931', X'941B8C6544544336BE7C1D0591C12F90', 10, 'Robby the Snowboarder', 'Pingu goes snowboarding with Robby. At the snowboarding slope they start on a gentle run, passing Pingi on the way, and all get down safely. They go on to the next slope, which is steeper and which has a jump at the bottom. Pingi goes first, does a somersault off the jump, and lands safely. Pingu goes next and makes a hash of the jump, landing painfully on his rear end. Robby goes last and plays safe, going round the jump. Pingi sticks plasters on Pingu’s rear end, and gives him a safety cushion for protection. On the next jump Pingu crashes again, but this time doesn’t get hurt because he’s wearing the cushion. With some tuition from Pingi, and after being knocked off the ski tow by Pingg, who is skiing nearby, and sliding back to the bottom on his stomach, Pingu eventually manages a successful run without crashing. They then all go up on the tow and try the “big one”. Pingi and Pingu get down safely, but this time, despite previous successful jumps, Robby crashes onto his bottom. We then see Pingu, Robby and Pingi snowboarding again, but this time they’re all wearing safety cushions!', '2004-01-15', 5, '/kOmcKKMRdY3jPeAH1o3IMR8WkaR.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
