INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7E2F8A5CE9B04898A5734C5517F148EE', X'B6A0F2287DDC409CB808681B777A6704', 4, 'Mister Rogers Goes to School', 'Mister Rogers gets a beginner''s drum lesson at Negri''s Music Shop. He also discovers Mr. McFeely is learning to type, prompting an unusual quartet version of Everybody''s Fancy. In the Neighborhood of Make-Believe, Daniel tells Lady Aberlin his fears about starting school.', '1980-05-22', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
