INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7E5F6600B5AE4E7C94E6AA9FCEDE2BD2', X'936491E2AB834E1FB5C72C03F6461D86', 4, 'Autumn Story', 'Wilfred is looking forward to the deep snow to ride on his tobaggan. Better still when the snow covers the third notch comes the Snow Ball celebration at the Oak Palace. Soon Basil, Wilfred and Primrose get trapped in one the snow tunnels. Primrose finds a way out and summons the other mice to help. After that everyone celebrates.', '1997-10-26', 25, NULL, '2026-04-03T16:14:06Z', '2026-04-03T16:14:06Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7E6556B14BFB4F819917A96B9D4A87DA', X'16CBF3F2FFFD4A78BCA396D05F5A2C6B', 11, 'Postcards from Binky', 'Binky''s grandparents miss his big soccer game, and so he attempts a reenactment of the event making video postcards just as Buster did when he left with his dad.', '2016-05-24', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7E655B52F1774FEA91BF64955D900332', X'E40E6B639F84449F8E8853209B0906C8', 3, 'Word ''Dog'' Escapes Abby''s Book', 'Baby Bear and Telly Monster welcome the viewer to Sesame Street, and look forward to reading a book with Abby Cadabby. Abby arrives and introduces her magical book: The Wild Adventures of Action Dog. The others hear a barking sound, which turns out to come from none other than the book itself.', '2007-08-15', NULL, '/84bCjWK3Gh1cwfIWxXdujevbzeg.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7E6AEC9FA65041FBB224B86F7CB3274E', X'9B144910398A47D49CCD823D25CC8B0A', 17, 'Hot Tub of Sour Grapes', 'Friendships may be beyond repair when Teresa and Caroline have one last blowout after Caroline overhears a conversation between Teresa and Kathy.', '2012-08-26', 43, '/8fo8mlahQIHj2YQappGTuooRmb7.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7E6DCE1EB0F44D5ABF768611D0715AA2', X'1D713CA64E174F84949C8CFD98514127', 43, 'Motorcycle Mayhem', 'Rev your engines with the Pawn Stars when a 1957 Harley-Davidson Sportster roars into the shop. Will Corey be able to hammer down on the deal or will it burnout? Then, things get political when Rick checks out a painting of Communist leader Ho Chi Minh. Will he make a revolutionary deal, or will it be a tough loss? And later, when Chum starts helping himself to things around the shop, the guys try to tell him that taking is not the same as sharing. Will Chum teach them a lesson, or learn the hard way?', '2014-12-22', 21, '/o8c8ozBK6mRfDChx7ZxlZ1OXMCe.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
