INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7E9EE0C645AD47B3A6369A18EDBDACF1', X'9B95011E93DB4E56A45D8AA956C15997', 10, 'Up, Up and Away', 'Whilst doing some kite flying with the other kids, Mandy is inspired to want to fly over Pontypandy Mountain. Hannah tells her that her dad, Joe Sparkes, has just the thing...which turns out to be a hot air balloon!', '2014-06-07', 10, '/930wNB1gBYZDX9wf69XDForUN1w.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
