INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7EAF6F5AFE324399ADDEDB158846B7FC', X'34674C90410E427CBE4D2A6F6F865A80', 24, 'Free Willie', 'Hail a ride with the Pawn Stars when a taxi from the 1992 sci-fi movie "Free Jack" pulls up to the shop. Specially built just for the movie, do the guys give this prop some props, or send it back to the future? Then, a San Francisco Giants uniform owned by baseball legend Willie Mays has Chum and Corey seeing green. Will they try to take this deal into extra innings, or will something make them cry foul? And later, a guy walks in with a fully functioning brass hand cannon. Looking like something from a pirate movie, will Rick see a buried treasure, or is this unusual weapon just a swashbuckling novelty?', '2012-08-20', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
