INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7F0F99E2FA5C4D6AB23FEFA0A2CBD918', X'543EC6DCC6C7447CB5A74484D9618391', 6, 'Securing Homeland', 'Michaele asks for Stacie''s help in finding a home in D.C. Stacie is still in search of her biological father, while her mother is of no help. Cat and Mary bond over talks of motherhood. Cat loses a dear friend and is devastated by the loss, feeling alone while her husband is out of town. Tareq has family troubles yet again and Michaele realizes it''s taking a toll on her.', '2010-09-16', NULL, NULL, '2026-04-03T16:35:01Z', '2026-04-03T16:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7F11F97A96554D9FB6C104DAB8968ED0', X'C373ABED50EF417E9F344E9050611A1B', 8, 'Hot in Orange County', 'While Heather is in Hollywood filming a guest role on Hot In Cleveland, Terry struggles at home alone with the kids. Meanwhile, Alexis pursues her own acting career in Orange County. Gretchen and Slade ruffle some feathers when they are inconsiderate on Heather’s big day. Then, Lydia confronts her mother about her marijuana smoking habit.', '2013-05-20', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7F13F1D1FACA4B27839B0D507AA9D3AB', X'96DD06EED44A47F39372E29E8EAA77F5', 8, 'Snow Business', 'It''s Christmas Eve, and Pontypandy''s got four inches of festive snow to keep the kids entertained. They''re playing snowballs, and everyone around  town is enjoying the cold snap, except for Dylis Price. She''s not happy shovelling snow from her shop front and ducking the great hanging icicles above her head. She wonders why the Christmas tree isn''t up in the park yet. Why, the Council have been a bit late this year. She suspects they couldn''t afford one. Her comments give Fireman Sam a jolly idea...', '1988-12-22', 10, '/niA52ErBhIgBemWjcbOYgZ0BJis.jpg', '2026-04-03T17:14:37Z', '2026-04-03T17:14:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
