INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7F2374A75AAC4DCD9A04CFC2F7A0CB5B', X'8BDF0AD3A7984D5AB304C7501EAE6867', 12, 'Who''s Your Daddy?', 'Vicki Gunvalson launches her L.I.F.E. with Vicki cruise and is thrilled to get so much attention from her colleagues, but is frustrated when she can''t seem to get any props from her own family. Jeana Keough and her daughter, Kara, drive to up to Berkley to move Kara into her apartment. They find themselves strangers among the "bums" and "hippies." Tamra Barney visits her dad in Iowa and puts it all on the line, spilling her heart out to her estranged father. Gretchen Rossi does Dallas, reuniting with her four best friends from college. Lynne Curtin and her husband, Frank, take a romantic getaway to San Diego leaving their teenage daughters, Raquel and Alexa, home... with Grandma.', '2009-02-10', 44, '/pwc6uHZpghQIVWqdZvoL3aSmuCB.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
