INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7F291D18A8C94C0192D40B6253D1189D', X'1A534647384B4C00BB6CA3371AD962EB', 30, 'Behind the Wheel', 'Play ball with the Pawn Stars when a 1923 Babe Ruth baseball card, graded a perfect 10, steps up to the plate. Will Rick be able to knock it out of the park on this rare card or will he get called out? Then, Rick is brought back to the 1930s when an unrestored children''s tricycle pedals into the shop. Will he toy with the idea of fixing it up it or will the cost cause him to hit the brakes? And later, after Corey totals his truck, he is forced to drive the company car with Rick''s face on it. Will Corey end up understanding the truck''s true face value or will he force Rick to face facts?', '2015-05-25', 21, '/gItH4gYJ6pfjtklugbD5vyBQKFQ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
