INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7F3DFF49D5A94C25BC983E3504A97FCE', X'C7994637B7C742C7AAEE1BFF4144FE23', 18, 'Reunion Part 1', 'In the midst of shocking headlines and hurt feelings, the diamonds of Beverly Hills come face-to-face for a tense reunion. Kyle addresses Erika''s past comment about wanting Andy to "eviscerate" her on the couch. Dorit confronts Kyle about an ominous text message she received and the current state of their "close" friendship. Garcelle challenges Dorit and attempts to burst her bubble in order to get through to her. Annemarie swallows her pride when she apologizes to Sutton, but Crystal proves to be her most difficult patient yet.', '2024-02-28', 44, '/3i3IntStNo3VPoiqeV9R7KMjibD.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
