INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7F94537D61074C0B9B6FC52180FAFC2E', X'F21CA545466C448CADA5B8ACC8B856DC', 11, 'Time, Gentleman', 'This episode is a pilot episode, and was the first run of Bernard''s watch, it is very rare, and only ever shown once on the children''s channel citv, Bernard is trying to raise money for a local Pet Sanctuary, and his Grandad agrees to help by giving a darts masterclass. Unfortunately he isn''t as good as he once claimed to be, Bernard is forced to intervene.', '1999-12-06', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7F9643D8F04E4AAAA13C3C10E4A57555', X'D6092173D23B4449BAFFE0E16FE56C9A', 7, 'The Jet Set and the Upset', 'Drew hosts a Hollywood-themed dinner where Porsha brings up some messy gossip. Kandi starts planning a very special surprise for Cynthia. The ladies are shocked when they find out that Kenya has chartered a flight for her and LaToya to jet down to South Carolina, leaving the rest of the ladies to languish on a hot bus.', '2021-01-24', 43, '/cZpLCkRT73Nhv2nMpHdpg20BY6W.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7F974FC8C7D443BBBADD57C06A0B792F', X'119C16D5104745EC8242C72A8EED423B', 11, 'Locked in the Library!', 'After Arthur called Francine a marshmallow, Francine and her friends get really mad and it looks like they are going to fight. But when they both get locked inside the Elwood City Library they either have to make up, or prepare for a long and scary weekend, because it''s the weekend and the library closes until Monday.', '1996-10-14', 13, '/55xJltw0KaSShLZf42I0tot4bN6.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
