INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7F989B0F56FF4A48B6E367CE83C3CBA1', X'5BA20443D99F482081F66832D3F2BC4F', 11, 'Archaeology', 'Archaeologists are kind of like detectives. They’re scientists who snoop through old or ancient people’s things to find out what life was like thousands of years ago. Archaeologists find ancient cities, tombs, and temples by taking aerial photographs of Earth, by reading old documents, or by just looking at the shape of the land. When they think they’ve found a site, the archaeologists pick up a shovel and start digging. When archaeologists get close to an object, they dig very carefully. Sometimes they dig with nothing but a toothpick and a paintbrush. Whew!', '1996-01-28', 26, '/e2p4fKtFK797ganbruE8u4Duzfb.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FA077EC896D417D93EDAF1DC90D1663', X'FE19A277AED844DFA4ACFC1C4E9941B4', 9, 'Precious Pocketbook', 'Kim tells her girlfriend Cori that Big Papa is back in the picture after he whisked her away to the Bahamas. Lisa and Kandi appear in the charity performance of "Pocketbook Monologues," where Kandi’s emotional performance wins over the crowd – and Dwight. Meanwhile, NeNe meets with the co-writer of her forthcoming memoir, and Shereé finally throws her long awaited Independence Party, where NeNe confronts Kim and Kandi about recording “Tardy for the Party” without her.', '2009-09-24', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FA50CA4DF2B4367A7F4D7CF97C2779D', X'1D713CA64E174F84949C8CFD98514127', 20, 'Tough Cookie', 'Take aim with the Pawn Stars when a gold and silver Remington Arms gun pops into the Gold & Silver Pawn Shop. Can Rick charge into this deal guns blazing, or will a misfire cause him to surrender? Then, Corey and Chumlee quit their jibbajabba when a collection of Mr.T dolls come into the store. Will they "Pity The Fool" and make the deal or will the negotiation be too "Rocky"? And later, after Rick opens a bad fortune cookie, will he be forced to crack open some more, or has his luck just run dry?', '2014-10-02', 21, '/sUGPZpZVYAyx1ZUR92SOxKqai4t.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
