INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FBCCF70259E4CFCAE03F4223F7FBC10', X'2990012C38F6405184A54EC6DA711D80', 10, 'The Magic Act', 'Kipper does a magic act and makes everyone, including himself, think that he has made Arnold disappear for good.', '1999-03-25', 30, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FBE4661B8C24B65ACCEBC97DAA818DA', X'8B07363E5F5445D6B036B43793F7AF74', 1, 'Cast Away', 'Arthur is thrilled when Dad invites him to go fly fishing for the weekend.', '2002-10-08', 13, NULL, '2026-04-03T17:37:57Z', '2026-04-03T17:37:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FCF464541F04E38B909104341A97552', X'98D80972E53A43DDA03A7703465E6F87', 14, 'Silent But Chumlee', 'Things get surreal for the Pawn Stars when the guys check out an original painting by Salvador Dali. Known for his eccentric artwork, is this just too strange for the shop? Then, Chumlee is on the hunt for deals when he checks out a Silent Scope sniper arcade game. Can he win the negotiation with a kill shot, or will he shoot himself in the foot? And later, Rick and the Old Man check out a French suit of armor. Dating back to the time of Napoleon, will the deal sparkle in the setting sun or rust away before their visored eyes?', '2012-12-10', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FCFEB950D9847EAABB59B81DEC54D29', X'3AF7EA64FA134097B8E440AF07083054', 38, 'Harvest Festival Pt 3', 'Rogers witnesses actor Iron Eyes Cody and a Native American family teaching dances to François Clemmons. In the Neighborhood of Make-Believe, Lady Elaine plans to get maple syrup for the harvest festival. To start it, she tries to tap X''s oak tree.', '1974-04-10', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FD134A13C444ACD86BA654780A1AE9B', X'227B84290DFD47E4B874C37DA20C403F', 5, 'Gangsters & Guitars', 'Rick buys an old, Mafia favorite the 1962 Lincoln Continental with "suicide doors," but as the repair bills add up, so does the tension between him and the old man. Then, a guy brings in a billfold from 1857 that he found while cleaning out his garage. The best part? It''s stuffed with Confederate money. Finally the Pawn Stars get a chance to buy a rare 1942 Gibson L7 guitar that was once played at a birthday party for Al Capone. But, is the seller in tune with what it''s really worth?', '2009-08-02', 21, '/zY7EPgF3XEpe9ZWFCKVqZ9xaPLE.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FD2A7C4E49748F99151512ACF6A2D5F', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 95, 'Superbird / Miss Trump dances', 'Superbird emerges to help someone in need while Gordon and another character discuss a current situation. Miss Trump arrives on Sesame Street and dances to show the residents how to move to music. Her infectious enthusiasm gets the residents to dance along with her in celebration.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FD9EF76F2B745A7A094284E9DE17DF9', X'4F18AC4C8757456CA49A224F00E6A9F7', 8, 'Elmo & Zoe''s Hat Contest', 'Gordon welcomes the viewer to Sesame Street, when Elmo alerts him that today is "Who can wear the most hats on their head" day, and drags him to the courtyard, where an enthusiastic crowd cheers.', '2008-08-22', NULL, '/f8SVKP00OBecXzAP4Ein6iDXUzd.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FED0770EB1D413E83BCBD517BD794A7', X'B86D15EA425341A59F144A254EC601E0', 11, 'Children of the Scorned', 'Joe spends time with his goddaughter; Teresa hosts a charity event and confronts Jacqueline; Jacqueline makes an impulsive decision that has her family worried.', '2013-08-11', 43, '/8alltmNLFoqOcHdoNg8DD7zzrrT.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FEFB3F196BB47F7815FAD9867E5C02E', X'61E0C9D9337E4FE4A0FDE567B29AF115', 15, 'Smile, You''re Being Recorded', 'The girls'' trip to Puerto Vallarta goes from bad to worse when someone is caught red-handed recording the women, causing everyone to turn on her. The ladies enjoy a poolside lunch where Britani reveals her deepest, darkest secret, leaving the group baffled. Meredith makes an accusation at dinner that stops Britani in her tracks. Heather and Meredith have a misunderstanding that leaves them at odds.', '2025-01-08', 43, '/naSeGNbT4YfTRiWK0IHBNWFaMax.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FF01BCE40294894A9C8DD1BD68F5C87', X'A5F4726D4BD648CF96BDA275FA554D9C', 7, 'Episode 7', '', '1989-03-07', 25, NULL, '2026-04-03T17:21:15Z', '2026-04-03T17:21:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FF4EEA9CBB14DC3A7CBF1B5F0051661', X'5C16DB9D5E7140EBB44EF559B2DDB8F3', 5, 'Snow White and the Seven Dwarfs', 'In her effort to be "fairest in the land," a jealous and evil queen attempts to be rid of her beautiful stepdaughter, Snow White, who takes refuge in the forest cottage of the seven dwarfs. The queen, disguised by magic as an old peddler woman, tempts Snow White with a poisoned apple, which puts her into an enchanted sleep until the spell can be broken by love''s first kiss.', '1984-07-16', 51, '/dNvP8f4N3fgwVVaGulDxP0wYlug.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FF7C53C043C4017B323782B4B79FB15', X'B6BAA6EC09084A4790017E7158985002', 12, 'Cold Feet', 'Liz has gone off to a mysterious place called “Herp Haven.” Thinking she’s in trouble, the class rushes to Herp Haven, where they turn into reptiles. With Michael York as Herpst.', '1995-11-25', 25, '/7HqFonDFHnfOGvmnYgaZmxKmAQP.jpg', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FF95B8869CF4800A48537625FE34B88', X'ABEB8D075C864F6AA110B11CBA2A4138', 13, 'The Firebending Masters', 'While teaching Aang firebending, Zuko realizes that he has lost all his firebending skills. To regain his powers, Zuko and Aang must seek the original source of firebending within the ruins of a lost civilization.', '2008-07-15', 25, '/2xpOq1usmWDX9ia7cfBFmgqp8KO.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FFE3692D34543EEBE302B0DA7499E47', X'3415030FF54D42B9A290AAA05E246D86', 5, 'The Dress Doesn''t Fit', 'In the week before Maddie''s wedding, Mykelti and Tony announce their engagement; the whole family has to get to Wyoming; when the mother of the bride talks about going fishing, Maddie melts down.', '2016-12-11', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'7FFF50D1A1AA4F619EB2B9D064B878EA', X'A4843A51AEEF427C902C7FB3BD670CD4', 26, 'Friends For Life', 'Pip and Pop are playing hide-and-seek, but disagree on where they should play. Bear introduces them to the method of flipping a coin. Bear stops to contemplate friendship and then finds Treelo waiting for Ojo. He wants to play their favorite game --- Rock Boy and Snow Bear, but Ojo keeps dashing off outside. Treelo tries to get Tutter to play the game instead, but finds that Tutter''s not interested in the game. Both of them eventually join Pip and Pops'' game of hide-and-seek and then find out the reason why Ojo has been so busy. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'800312F5AD6A44189F83D7C2245031EF', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 56, 'Oscar thinks Slimey has run away', 'Uncle Wally and Bob are up very early to go jogging with Gordon. Bob remains groggy and falls asleep standing up as Wally and Gordon converse. Wally knows how to get Bob up and running; he places a small radio in his hands and plays the "William Tell Overture," which wakes him up.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'80034CF359764AB897BE0BF015B3E3E0', X'BF3FFAFD7D454F2C9F1B28001BD082DB', 39, 'Episode 39', 'with John Noakes, Peter Purves, Lesley Judd', '1975-01-23', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
