INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8009FEA88E8C4EC4B035B8A77098085D', X'3AF7EA64FA134097B8E440AF07083054', 34, 'The History of Planet Purple Pt 5', 'Rogers discusses voting and sees a voting machine at Trow''s Workshop. Most in the Neighborhood of Make-Believe oppose the vote to add "Fairchilde" at the end of the territory''s name.', '1974-04-04', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'80114C4E5462417BA05889E5FD2DF9E6', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 73, 'Episode 2168', 'The Count welcomes the viewer and unveils the number 2, and then presents Snuffy as he is going to count to two. Forgetful Jones is sitting down at Hooper''s with a piece of paper when he calls out to David to ask to borrow a carrot so he can write a note to himself reminding him to order chicken feed.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8011FB9A236243FE9E158B7AEF042F71', X'8A5892F6CCB74F029A5A85B134B5F0CF', 11, 'The Cuckoo Clock', 'It doesn''t tell the time any more. It doesn''t sing any more. It is no use at all, except to a homeless bird and her family.', '1976-02-12', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8015499F99314905961B9724CCCA3D05', X'65D1CAD80120425EAE9B5020CE773B32', 1, 'Revolving Door of Lies', 'Shannon is loving the single life as Jenn preps for her wedding; Emily reveals a heartbreaking family issue; Tamra opens up about her past trauma in therapy; Heather deals with problems at her Beverly Hills mansion.', '2025-07-10', NULL, '/1hHpvZdLzA5GBd2q7nrkIWzwJeJ.jpg', '2026-04-03T16:35:36Z', '2026-04-03T16:35:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'802585B0BD02418B92187AFC966DD82E', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 12, 'The Pawnshine State', 'Rise and shine with the Pawn Stars as Rick and Chumlee take a trip to the Sunshine State to check out a fully loaded 1964 Rybovich Yacht. While in Florida, Rick visits his friend, Lisa, at her own pawn shop in town. A local Florida Highwaymen painting catches Rick''s eye, but he also sees opportunity for Lisa''s pawn shop to grow. Rick votes to check out a voting machine from the 2000 Presidential Election that could be a winner for Lisa''s store. Meanwhile, back in Vegas, Corey sees green when a seller brings in some original Incredible Hulk comic books.', '2017-06-05', 21, '/WTaRyk9sgPfoHz2waMgP5Ddo6T.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8026947AA75D4FA9852C0A6FA66A9962', X'F593D90C533942F59C885BFD48D04075', 22, 'What''s Up, Dog?', 'A wayward balloonist lands in the sheeps field. Shaun and his friends are intrigued by the hot air balloon and inadvertently take to the skies. Down on the ground an ever more desperate Bitzer runs himself ragged attempting to bring the wayward sheep back down to Earth safely.', '2010-12-05', NULL, '/50UG9VIyptbyPA0YeDkkBioX9vG.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'802A2CD108A14977AB28635881745ACD', X'D1863F2F02EC40CEAF64DB03FBE518A7', 8, 'When Dinosaurs Walked Sesame Street', 'Elmo, Chris, and their friends on Sesame Street have dressed up as dinosaurs. With help from Elmo''s book, they learn that there are small and big dinosaurs, some dinosaurs are herbivores and some are carnivores and that Big Bird is a dinosaur! Also featuring Jurassic Cookie parody, and Elmo''s World-dinosaurs. Brought to you by the letter D and the number 15.', '2016-02-27', NULL, '/x8KH0N1EeLdrb4nY0KOTbSObxOs.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
