INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'80503030496F4F7298EF539529025E2A', X'740A96A0A0754BE2BE92A178D0939384', 29, 'Elmo and Abby''s Bubble Fun', 'Alan and Chris introduce Sesame Street''s first-ever Bubble Fest! Elmo, Abby, Telly and the kids gather for the festivities. Telly is excited, as he''s never blown a bubble before, and neither has Abby (her mommy''s always made them with magic).', '2018-06-02', NULL, '/nVUQ0Rf73VntjKj1bCRW31SzoEs.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
