INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8072862A72EF475F8F9C11D6B880E1F0', X'CA19F89515144988A70995E84EAB7CEE', 18, 'Once a Pawn a Time in Hollywood', 'When a vintage Yellow Cab hat pulls into the shop, can Rick hail a fare deal? Next, a seller pops in with a gum ball machine. Will he stick to a fair price, or do Corey and Chum have to burst his bubble? Then, Corey gets to play with the world''s first video game console. Can he control the negotiation, or will it be game over? Finally, Rick and Chum are ready for their close up as they head west to check out a treasure trove of Hollywood memorabilia in California.', '2021-05-17', 42, '/eQUEppKj7V2W1e1I9bVK1rCLiaI.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
