INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'80B2F932CA934EA8A1A2993C9537ADBA', X'5A771F52FE964EA2B567A8DDE899059E', 3, 'Pawn or Bust', 'A bust of Marlon Brando has Rick making its owner an offer he can’t refuse ... or can he? It''s game on with the Pawn Stars when a Donkey Kong penny bank from the early 1980s barrels into the store. Rick needs to keep both eyes open when he spots a cyclops print made by a member of the band Devo.', '2017-10-23', 21, '/75VRLezNuLTPlDniQMVZvVsUBG5.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'80B8965C8B5C4267BFF8F36909D6E9CD', X'1A534647384B4C00BB6CA3371AD962EB', 33, 'Dangerous Deals', 'Take caution and revisit some of the most dangerous items that have exploded their way into the pawn shop including: a double barrel Coaching gun from the 1800''s, an extremely rare Let Mat Pistol, a $335,000 mint condition Gatling Gun, a pair of Soviet Missile Launch keys and a post Civil War parade Cannon that leaves the guys shaken but not stirred.', '2015-05-28', 21, '/ouoYLaCRagT3pLnpnVDZlZjurxz.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'80C65E269C3F40CE83153B791FD96414', X'70C8CB4624944DD498F66BFB9B3FAF73', 4, 'Pezzed Off', 'The Pawn Stars have a chance to buy an extremely rare 18th century double-barrel coaching gun engraved with a mysterious golden script. Can they discover its true origins and make a deal or will the inscription hide its secrets forever? Then Corey and Chum meet an outspoken Pez collector looking to sell 50 pieces of classic Americana. Will Corey click out some serious cash for these collectibles, or will he get his sugar fix somewhere else? And later, a woman hopes to sell Rick a 1932 "S" Quarter - a rare version of the first Washington silver quarter introduced into U.S. currency. But Rick has questions about its authenticity, will this quarter be worth its weight in silver, or is it destined for a parking meter?', '2010-01-25', 21, '/1ISiP3mP5RSqiW89rB2MemVdK0w.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
