INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'80D937E456EE408EBDB54AF657CA2ADE', X'45E01C046AC641E187D8F749EE230385', 15, 'Poorly Penny', 'On Fireman Sam''s day off the crew are inundated with the Jones'' emergencies. Firefighter Penny Morris has caught a cold, but she still tries to perform her firefighter duties. However, when the Joneses get stuck on Charlie''s boat, Penny''s illness takes hold while she is out on Neptune alone, and Sam has to come to the rescue.', '2008-02-27', 10, '/kkd7RlSWPVoqJwqo62kOEbfdUR2.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
