INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'80F026A2B7A140F0BFCEE88C6A755FAB', X'05C0E384194C44179F62803EB615E409', 20, 'How windmills work', 'Title number 0020. Opens with Mister Rogers arriving with a model windmill and talks about how windmills work. Judy Rubin, the “Art Lady,” shows some windmills made by children. She and Mister Rogers make windmills of their own. In the Neighborhood of Make-Believe, Daniel tells Handyman Negri he thinks that King Friday is afraid of Donkey Hodie''s biting. Maybe that''s the reason the King won''t allow Donkey Hodie to put his windmill near the castle. When Donkey Hodie convinces the king that he doesn''t bite anymore, the king changes his mind.', '1968-03-15', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
