INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'811AC779755C47A2A2F3738F9534E6A3', X'05C0E384194C44179F62803EB615E409', 38, 'King Friday meets Sara Saturday', 'Title number 0038. Opens with Mister Rogers arriving with a bicycle handle. Mr. Rogers demonstrates exercises by using a stationary exercise bicycle and free weights. He then sings "I Like You As You Are". Lady Betty Aberlin tries out the exercise bike. In Make-Believe, Sara Saturday, who had been the damsel in distress a week earlier and frightened by the monster, is welcomed to the Neighborhood of Make-Believe. Lady Aberlin sings "Then Your Heart Is Full Of Love".', '1968-04-10', 30, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
