INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'812EA7E05C9F49D8B594E7A13D9CE00D', X'FB06E6584B5446828783EAA88A99E61E', 8, 'The Tardy Tumbler', '', '2014-10-02', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'81302B49BEFA42DE94975B8FA9759B18', X'68138DE20900460AB58E480688F1E081', 15, 'Change Is In The Air', 'Since Bear''s friend Ursa has never seen the Big Blue House, he''s decided to take some pictures of things around the Big Blue House and make an album to send to her. As he searches for good opportunities, he finds that the kids of the Big Blue House are curious about his camera. Tutter seems to keep popping up whenever he tries to take a shot in the kitchen, so he finally has Tutter pose for a photo. The other kids have their photos taken as well. Treelo is a bit reluctant because he doesn''t understand how the camera works and is worried he''ll be sucked into it. While taking everyone''s photos, Bear also notices that his camera seems to keep disappearing, but by the time he looks for it again, it''s back where it was. In the Shadow segment, Shadow tells an unusual version of the traditional "Roses are Red" poem. It ends with an alligator eating a pair of blue-suede shoes. 
