INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8172B098A8564B78941D00EBE139B788', X'740A96A0A0754BE2BE92A178D0939384', 16, 'Street Food', 'Lily, a four-year-old tiger cub from China, joins Chamki, Zuzu, and all their new friends for an international food festival on Sesame Street. The group learns about traditional dishes from Japan, South Africa, India, and China. Rudy is reluctant to try the unfamiliar foods, but he’s pleasantly surprised when Elmo, Abby, and Chris encourage him to taste a few.', '2018-03-03', NULL, '/4d3Jt25WW0Jk3vtjP6PLeRYi9ye.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
