INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'817E32BFE44448ECB76C7FE02BE78B04', X'CA19F89515144988A70995E84EAB7CEE', 14, 'That''s the Way the Cookie Crumbles', 'When a Mick Foley t-shirt and autographed mask come into the shop, Rick calls in a very special guest to authenticate it. Can he wrestle a superstar price, or end up getting slammed? Next, a seller walks in with an unopened McDonald''s cookie from the 1980s. Will Corey take a bite out of this deal, or will the negotiation go stale? Later, Murray the Magician shows Chum a few tricks up his sleeve when they check out a magical book. Is a purchase in the cards, or is the deal cursed? And finally, Rick and Corey clown around in LA when they take a road trip to see a collection of vintage coin operated arcade machines. Can they score big, or will it be game over?', '2021-04-19', 42, '/9SbkDsjaW1Oz5MvtdHdy0u7hn3W.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
