INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8189BD0EC782440F86D416F55BA161D5', X'8BAE6AA34B554FA6BC158F4317BD1F13', 53, 'Telecan Crisis Pt 3', 'Rogers talks about staying still, something that Mr. McFeely will need to practice. The same thing occurs for the telecan kiosk. Handyman Negri tries to tie it up, but that interferes with King Friday''s calls.', '1972-05-03', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'818CEDC9F5574CCA83C5670CF054C09B', X'151E88A195764BD1B84AC4D64C1C9FE8', 7, 'Ship-Faced', 'The women set sail aboard Dorit’s luxury yacht in Mexico, but Erika goes overboard with her partying and winds up three sheets to the wind. Diana admits to Kyle that her temper is still burning hot at Sutton. Garcelle springs a surprise on Lisa, who turns the tables with a stunning admission of her own. Crystal vows to stop holding onto the past.', '2022-06-22', NULL, '/dFw26ypM1PcPc4hzsUNJLo7H6Z1.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'818F7085E94942F2B83045803094904C', X'6B5CAA66F66F4ED1817FA00BAD08790E', 3, 'Not One of Us', 'Danielle tries to bring tranquillity to the housewives'' lives by organising a Moms'' Night Out Spa Party but the mood turns sour when her guests circulate rumours. Later, Caroline and Dina pressure Jacqueline to end her friendship with Danielle.', '2009-05-26', 43, '/7RXtzsM29ESVsGH8ejLX68bAK4M.jpg', '2026-04-03T16:35:14Z', '2026-04-03T16:35:14Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8195150AEB66403A95C96F3FBF776B4A', X'5D57283D079C4F6693C833A2FEEADA89', 20, 'The Optimist', 'Sue frantically tries to earn a college scholarship for when she graduates high school in two years; Frankie hopes to correct a mistake at work without her boss finding out; Brick demands a formal apology from Mike after a misunderstanding.', '2014-04-30', 22, '/k3GFC7fpyUGuOQzo5bMMCiD4ZvL.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
