INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'819B82FC39094FAB92373DA5AB0A57EE', X'5F170F24C8184CE68FC35AA4CA520757', 4, 'A Cloudy Day', '', '2022-02-21', 13, NULL, '2026-04-03T17:38:04Z', '2026-04-03T17:38:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'819DFC4265C64FE5AD32659DAB136650', X'1996DDD820C94A3096BE2B87FAB8D17C', 4, 'Ghost Story (4)', 'The team, consisting of Jamal, Lenni, Alex, & Gaby, discover that the backpack thieves are planning a final secret ceremony. They leave a fake message in one their lockers saying that the ceremony is cancelled. Alex goes undercover as one of them but there''s one problem: Alex doesn''t know which code name to go by.', '1992-10-25', NULL, '/8zAQMZT55VSEsULFjNBtjueAZOa.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'819E2562D26B46BF8D59F4EDC2FC5FE2', X'4C79C0B621A442778967BE1E791EFDBE', 23, 'Pingu and the New Scooter', 'In the igloo, Mother and Father are cleaning, Pinga is rummaging in the toy-box and Pingu is playing with his wooden engine. Father wants to put the vacuum cleaner away in the bottom of the cupboard, but there’s already a box of oddments in the space. Father asks Pingu to put the box in the shed, which he reluctantly does, and also which angers Pinga. When he gets to the shed there’s no room, so he starts getting some things out of the way. One of the things he moves is an old scooter(His old one from the previous episodes). He puts the box away, and then decides to go for a ride on the scooter. On his ride he meets Pingg and Pingi, who are out on their own scooters that are much newer and brighter. They’re doing tricks using the ice slopes, and Pingu decides to have a go. Unfortunately, he doesn’t manage to get up much speed and rather than jumping the gap falls into it, breaking off the front wheel. Dejectedly he heads off home, but on the way passes a shop with a bright shining new scooter on display in the window. He rushes home and pleads with Father to get it for him. Father agrees to look at it, but only after all the toys have been tidied away. When this has been done, Pingu goes outside and gets a shock; Pingg has already brought the scooter. Pingu and Father go into the shed, In which he created his sled in, where Pingu breaks up his old scooter. He then notices that Father, who has been rummaging around, has found some wheels that would go nicely on a new scooter, and together they build a new scooter. Pingu goes to meet up with his friends, and shows off his new scooter. They then go on the jumps, but Pingg’s new scooter doesn’t perform very well, while Pingu’s does. Father is watching and applauds Pingu’s performance.', '2006-02-28', 5, '/5uS8xh2Qv9272VF1NlwfB69QRbY.jpg', '2026-04-03T17:22:21Z', '2026-04-03T17:22:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
