INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'81C03DC5CE4843E49EA18F6A06CD379A', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 17, 'Frontier Fortune', 'Strum along with the Pawn Stars when a Gibson lap steel guitar jams into the shop. Will Rick rock out an offer or will he be playing a different tune? Next, a letter from pioneer Ezra Meeker and a set of commemorative Oregon Trail coins trek on in. Will Rick pay a frontier fortune or will the deal fall off the wagon? Then, the smell of tobacco fills the air when a Victorian snuff box shows up. Will Corey sniff out a sale or will he strike it down? And later, colonial bone dice from The Stamp Act of 1765 roll in. Will Rick throw the seller a bone or will he revolt against the deal?', '2017-06-26', 21, '/5qywut5C7GHWw8IqPo3qI4XYm2W.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
