INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'81D67E0EDF6C435CB04AA5B44AC1CDCE', X'BA99B779CADA43A7902A2ADB472C2E30', 4, 'Episode 4', 'The first two thirds of this episode are a wonderfully crafted and tense escape sequence with the rat catcher on the job and poisonous gas being pumped into the wall cavities. The last third sees our family out in the big wide world, and when you are only 15cm high the world is very big indeed.', '1992-11-29', 30, NULL, '2026-04-03T17:17:47Z', '2026-04-03T17:17:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
