INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'823D8DFCBE79444E869A45E853C1E6B5', X'5DB3FF78E43948E18F67988ECBF85D17', 26, 'Dogtanian''s Dream Comes True', 'Dogtanian, Pip and The Three Musketeers have sailed back to France from Spain, Juliette is there eagerly awaiting Dogtanian''s return. Cardinal Richelieu, Count Rochefort and Captain Widimer are discussing Dogtanian''s return and how to get him, Widimer suggests poison - to the disgust of Rochefort who believes in the Cavalier''s code of honour. Richelieu likes Widimer''s plan and tells him to do it behind Rochefort''s back, if he succeeds he''ll become Count Widimer. Dogtanian is handing out gifts when Rochefort knocks on the door, Planchet goes to answer but only finds a note on the doorstep. The note challenges Dogtanian to a duel and warns him of Widimer''s plan...', '1982-03-26', 24, '/wl1lWmfQ7wp3b8W4jjZK3OEmnCj.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
