INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'82515C67CEAF409AB9191DBEB8639184', X'61E0C9D9337E4FE4A0FDE567B29AF115', 16, 'When All Is Said and Done', 'On their final day in Mexico, the ladies surprise Lisa with a Lisa-themed lunch, but things take a turn when Whitney finally pushes Lisa to her limit. Mary reveals her frustration with Angie after feeling disrespected and betrayed. The women come together for a beautiful private dinner where Heather''s attempt to help the women move forward goes horribly wrong.', '2025-01-15', 43, '/is7UaL6Naf8Di8Z2xgz7N9pHTvE.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'82537E9C7D8F4A46A0D36D1428CD59FB', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 48, 'David and the potted plant', 'David has been looking after a potted plant for his friend and is on his way to return it. On his way there, he hears arguing coming from Big Bird''s nest. He goes inside, where Big Bird and Snuffy are both blaming each other for knocking over their box of crayons.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'825B6A1AEB744F0C97902BE2E6B5D946', X'42E591E22A884434AE9F3D4B1D685613', 40, 'Gnarly Harley', 'Kick start the Pawn Stars when the guys check out a customized 1951 Harley Davidson. Will they try to buy it for the shop or is Corey looking to add to his own collection? Then, a seller brings in a crank organ from the early 1900''s. Can they grind out a deal? And later, when Lili the intern notices Rick''s dirty fingernails, the guys try to convince him to get a manicure.', '2013-12-05', 21, '/rphIrxOVOFxY152qfqm8kCZIW3p.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
