INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'82C01B64A62E4A4BB758D5B15B941B02', X'4B2A19E02FAE492EBC31F78E63D88EBC', 21, 'My Country, Pawn of Thee', 'Warm up your vocal chords with the Pawn Stars when handwritten lyrics to "My Country, ''Tis of Thee" come into the shop. Will Rick be feeling patriotic or will he commit treason on the deal? Next, Rick blasts off when a WWII era Linemar Space Explorer Toy launches in. Will he think it''s out of this world or will he put his offer on the shelf? Then, a United Nations Helmet from Somalia drops into Corey''s hands. Will he go to battle for a sale or will he quickly retreat? And later, a giant bell from the classic El Rancho Hotel and Casino chimes in. Will Rick ring in a deal or will it be too much to gamble?', '2017-01-02', 21, '/qOxdLeq7RCuUcFAuUwXVJ66fZr2.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
