INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'82CF3A840EE1405C9B9489A034E730B0', X'D3E13496E3C8490383B45A31FEDEE232', 12, 'The Storm', 'Sokka accepts a job for a fisherman who is looking for someone to help him out with his fishing. After the fisherman finds out Aang is the Avatar, Aang runs away in response to the fisherman''s hostile reaction. When Katara finds Aang, he begins to reveal his life before he was frozen in the iceberg. Meanwhile, after Zuko gets into a fight with his crew, Iroh tells them about Zuko''s complicated past, attempting to make both sides understand each other.', '2005-06-03', 25, '/rm6aSQ4H5ayVtjjMt0pi8Pth7h4.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'82CF4BEC7CEB48C5A692BDC98BC811C7', X'5FA796B4EAA34D89A7460A8B86CB8432', 2, 'Jack, the Seal and the Sea', 'LeVar takes a journey aboard a fishing boat to explore small ocean wildlife, such as plankton, sea horses, and small sharks as he learns information from oceanographers about caring for the seas and oceans. Leslie Uggams reads the featured story of a fisherman who decides to educate his neighbors about prevention of water pollution after he must rescue a small seal trapped in debris.', '1990-09-11', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'82D65D69395548068F687B69DD2F9413', X'A9657E86413549CEB1F9C295113077E1', 30, 'Episode 30', '', NULL, 30, '/g1iBxxsVNe4P0xdzXX5qgb56Zjt.jpg', '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'82E02D4E58D2427DA46738AF7530ED3D', X'EBC99729CCB74D6482C142708CD7BA85', 1, 'Episode 1', 'Expedition Malaysia  There''s more than a touch of Eastern promise in this year''s expedition! Simon and Sarah have explored one of the world''s most exotic countries. Giant turtles, coconut collecting monkeys, dragon boat races, Sepak Raga - the football game where you kick with the back of your heel, blow-pipe hunters and the world''s largest and hottest tin smelting works are just a few of the unusual sights they saw.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'82EBFC7FE5BE45959DA6413925E2EDF5', X'941B8C6544544336BE7C1D0591C12F90', 6, 'Pingu''s Windy Day', 'It’s a very windy day. Indoors, Pingu and Pinga are playing happily, building a tower with bricks. Mother empties the washing machine into a basket, and leaves it by them. Pinga turns the basket upside-down over herself and runs around, being egged on by Pingu. To stop them messing about with the basket Mother, who is about to go out with Father, asks them to hang up the washing outside. As Mother and Father leave the wind blows down the brick tower. Pinga and Pingu go outside to hang up the washing, which they manage to do after a bit of a struggle against the wind. As they start to go back inside the washing gets free and blows away. After a bit of a chase they manage to catch all the washing and go back indoors. Pingu rigs up a line between two chairs and hangs the washing on this. They then resume their play with the bricks, building another tower. Mother and Father then return and, as they enter, Pingu just manages to prevent the tower from being blown down by the wind by shielding it with a piece of the washing. Father then asks if they’d like to come outside to play with the kite. They say no. Father decides to go by himself but as he opens the door to leave the wind blows down the tower of bricks!', '2003-09-05', 5, '/mTBVX25F8nnzx6n3mW5FxRN7MDh.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
