INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8329B21EFFE945E6A405B8DAFD3AE026', X'45E01C046AC641E187D8F749EE230385', 5, 'Heap Of Trouble', 'For the Pontypandy Flower and Vegetable show, Mike is entering a marrow that he has been growing on his compost heap. But he did not heed Sam''s advice about turning over his compost regularly, so when he removes his marrow, the air gets into the heap and starts a fire!', '2008-02-15', 10, '/8bJbV6ClZOL084fbU2wFsVdVVXp.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
