INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8333EB6F9DCC444390AF102132E05A6C', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 6, 'Life Cycles', 'My, how you’ve grown! The popular exclamation from your Auntie may be no great revelation, but growing bigger is a part of life. In fact, it’s part of the whole cycle, or pattern, of human life that began with your birth. The different stages in life are called life cycles. Humans aren’t the only ones with life cycles. At first, you might think that you have nothing in common with a cactus in the desert, or a fish in the sea, or the mold in your gym shoe, but you do. You’re all alive. You all have or will experience birth, growth, reproduction, aging, and eventually, death.', '1997-11-14', 26, '/65jlQhkHz6rlUpNBiLk5uvopDpu.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
