INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'83356F8282CB48AEA77908050D7AC5A6', X'B86D15EA425341A59F144A254EC601E0', 14, 'Horse Whisper to a Scream', 'Unorthodox therapy opens old wounds and leaves Caroline in tears; Melissa and Jacqueline face their trust issues; Teresa''s husband reveals something shocking.', '2013-09-01', 43, '/1oTnz3ALOd26uCD1kTt8vuYs9az.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'83356F954BD34EE59A278E28F7BCA00E', X'E291DF42D44F49E5BF812DF32EE4A30F', 19, 'Words, Words, Words', 'Bear wakes up early on a sunny day and finds himself thinking about words. He enjoys reading the words in the Woodland Valley Gazette, as it helps him to keep up-to-date on what''s happening in Woodland Valley. While reading the paper, he hears a commotion in the kitchen and finds Harry and Tutter playing there. Tutter wanted to play knights and shining armor, but something about what he''s saying is causing Harry to quack up a storm. He told Harry that he could be "Big Beaky the Dragon" and now every time he says "big beak," Harry goes "all quacky." Bear has the two talk things out and Tutter finds that Harry is sensitive about the size of his beak. He apologizes, saying that he likes his beak. Next, Bear helps Pip and Pop when they can''t find the "whatchamacallit" that stops the water from draining out of the bathtub --- the plug. Pip and Pop find that they''e good with words, and rhyming. Later on, Ojo and the others hold a tea party in the attic. Harry''s shy and afraid to join in, but Bear tells him that if he uses his words, the others will let him join in. In the Shadow segment, Shadow tells the tale of Peter Piper, who picked a peck of pickled peppers. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8335C747F8EE424EA8619C2E165B3B52', X'EBC99729CCB74D6482C142708CD7BA85', 5, 'Episode 5', '', '1980-09-22', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
