INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'833EB0C75B6C4934B9882F64D4E1F304', X'A0FA50759CE148C199950C0FD866E549', 8, 'A Perfect Storm Out', 'Bozoma hosts a healing spa day for the ladies that proves to be anything but serene. Garcelle receives a long overdue apology. Kyle is confronted with mounting suspicions over her friendship with PK. Sutton takes issue with Kyle’s stormy escape. Dorit feels betrayed by Erika’s loyalty to Kyle, leaving Erika caught between two friends.', '2025-01-21', 43, '/lSIkvJYXwlS6nuuLjtu5PPBpLMx.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'83437FB4D899468E881FA1B997117CA8', X'6F731E6BD3C54DE684E17A19CB650E86', 29, 'Blockbuster Buys', 'Break the bank with the Pawn Stars and look back at some of the priciest items in the shop''s history: a $70,000 Panama Pacific gold coin from 1915, a Hydro Jetpack that sends Corey sky high, rare artwork from graffiti sensation Keith Haring and an exclusive Hertz Penske GT Mustang with an $85,000 asking price that has Rick burning rubber.', '2016-03-30', 21, '/m1W2Fz9FYKZL1mTeTeRJ9AYY6kb.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
