INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'83473A9424D2410088FE273B1553822B', X'E1063F8766C24E2DA91353362941AA19', 103, 'Episode 378', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8350166231094C4993191BE8D9A53922', X'68138DE20900460AB58E480688F1E081', 18, 'All Weather Bear', 'At the Big Blue House, Bear finds that his friends are all making inventions. Tutter has decided to create a "mouseapult," hoping to reach the cheese drawer more easily. He finds that it still has some kinks to work out. Ojo and Treelo create a device called an "everything machine." It''s just pretend, but it''s still a lot of fun. Additionally, Bear finds that Pip and Pop''s ball is stuck in a tree, but he finds that he''s not quite tall enough to reach it. He ends up inventing a ball-grabber device, but it turns out to be more of an "everything-grabber." In the Shadow segment, Shadow tells the story of Yankee Doodle, or tries to anyway. She finds, though, that Yankee Doodle has different ideas about the type of animal he should be riding on and what he sticks in his hat. 
