INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8352D105C7884DB9B7C72A6F03407F5A', X'ECB64EF34F8045A7B4A9C04434B02E35', 11, 'Rescue 9-1-Chum', 'Fight fire with the Pawn Stars when Rick and the Old Man check out a vintage smoke suit air pump. Missing its most valuable piece, will the guys end up getting burned? Then, Corey looks to cash in on a silver certificate when he finds an unexpected error. Will he be able to rack in the big bucks or be left with an empty wallet? And later, Chumlee gets hosed when he shows up to work late again. Given a special task, will his plan go up in flames?', '2014-02-06', 21, '/uX7AbmVxOAKSIEYVjB9iMXzE24y.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
