INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8365D6C51E7C478A9B22D2E8F0217322', X'8BDF0AD3A7984D5AB304C7501EAE6867', 10, 'The Girls Want To Come Out And Play', 'Vicki Gunvalson and Jeana Keough take a road trip to Chicago to visit Vicki''s friends from high school and former housewife Kimberly Bryant. Jeana and Vicki attend Jeana''s son, Shane''s, baseball game in Kane County, IL. When Shane mistreats Jeana before and after the game, Vicki and Kimberly defend their friend.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'836663B6457C4949B2C9C57F129CAACE', X'7C0E1F6688354E8A8AD90EEE57155B4C', 2, 'The Legend So Far', '“The Legend So Far” is an eleven-minute-long recap episode of “Avatar: The Last Airbender” narrated by James Garrett, the voice of Avatar Roku. In this recap, Roku retells some of the events that have occurred in Aang''s journey before episode eighteen, “The Waterbending Master”, and provides a sneak peek of the episodes still to come. It served as an introduction to the three-part Book One finale, which began with the episode “The Waterbending Master”.', '2005-11-18', 12, '/imCl0txmn64itMUt2vFaQCv0Syw.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
