INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'84692C1201454F39B1AC27F009631B40', X'1EFB01D30A3D46A2BBC04437617C52E6', 2, 'Norman Man Vs Firedog', '', '2018-02-10', 10, '/xr6hjf2IvBc7qTgndqgFEVKLr02.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'84719663CB3944DDAE19FF4C6F6238DD', X'B1D55597D9D24EEEAB9546DBB163291A', 1, 'Pingu is Introduced', 'The episode begins as the family is enjoying their lunch. Pingu tries to scoop up his potatoes but is having great difficulty, so he smashes his fork which makes it easier to swallow them whole. Father scolds him, but then ends up showing how difficult it is for him to keep his potatoes on his fork too. Pingu laughs and blows bubbles into his drink, with Mother telling him off for it. He then moves on to his fish which he puts into his mouth and pulls up again to reveal the bones. He does not want to eat his greens, but Father tells him he must if he wants to leave the table. Once finally eaten through his straw, Pingu rushes to the bathroom and spits the greens into the toilet. Pingu exits the bathroom and the table is cleared, so he slides under the table and sneaks into the toybox, to find his red rubber ball. He asks Father to inflate it for him, so he fetches the pump and does so. While he waits, Mother lets Pingu have a lick of her ice lolly. Pingu finally goes outside with his ball, sets it down and goes back in to blow his nose. While Pingu is gone, two bullies named Pingo and Pingg come along and steal the ball. Pingu soon returns and a big fight ensues to rescue his ball, resulting with Pingg hitting Pingu on the head and Pingo tripping Pingu up onto the ball, causing it to burst. Pingu runs back to his igloo, chased by snowballs thrown at him by Pingo. Father blows up the ball again while Mother puts a plaster on Pingu''s head. Father also plasters up the damage that the ball suffered too. Pingu then finishes off the day with a sleep in his hammock.', '1986-05-28', 5, '/1OOYGRQWqbYDQFT8h77wOdelbv9.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8473077E10254DA2B4675A82A332BB20', X'24003C6DD9194616A7DD0D38BB7A0656', 3, 'Gondola', 'Pat visits Stratford-upon-Avon to have a ride in a gondola.', '1996-01-19', 10, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
