INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8505B21D8C1840E5A7F0DC1BC9D24CD3', X'3087A3EDE94E42769D02A78183DEA1D3', 9, 'Dress Down and Strip Bare', 'With the ladies back from romantic Anguilla, relationships are tested and this time it''s not only Kenya and Walter in the romantic hot seat. Divorce rumors swirl around Phaedra and Apollo, while Kandi and Todd’s relationship moves forward when they receive a visit from their pastor. Kenya continues to investigate whether her man is serious about love and NeNe gets the money shot in the cover shoot of a lifetime.', '2012-12-30', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
