INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8519AD2132F347B596F6BA6892D73C25', X'CA19F89515144988A70995E84EAB7CEE', 19, 'Off the Rails', 'When Chum gets his hands on a trio of vintage comic strip characters, will the seller play with his emotions, and toy around with a deal? Next, a book by Amelia Earhart flies into the shop. Will Rick dare to make a deal, or will the price soar too high? Then, a pair of "Romeo and Juliet" sculptures hits the counter. Can Chum play a part in the negotiation before it turns tragic? And later, the guys take a trip to meet up with Spencer at the Glamis Sand Dunes to check out a one of a kind sandrail. Can Rick drive home a deal, or will he be left in the dust?', '2021-08-14', 42, '/rh0MtDkaPSd8o8qrVLXPcKqZaUB.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
