INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'854A8F2D8E554AACAC90F51FA14311C6', X'33319C06A2B043BF8694B3E8E37E49E9', 8, 'Football', 'Neil visits Bristol City F.C. to watch the 1996 Gloucestershire Cup match versus the Bristol Rovers F.C..', '1997-02-28', 10, NULL, '2026-04-03T17:19:38Z', '2026-04-03T17:19:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'855124964E1C42999BFFD912746C2E9C', X'4B2A19E02FAE492EBC31F78E63D88EBC', 3, 'Pawn Halen', 'All hands on deck with the Pawn Stars when a set of 1814 naval history books from John Adam''s personal library sails into the shop. Will Rick anchor up to a deal or will he throw them overboard? Next, an electronic cigar box guitar signed by the legendary frontman Sammy Hager rocks in. Will Rick think it''s red-hot hit or will he cancel the tour? Then, a 1901 coin sorter comes into the shop. Will Chum count up an offer or will he get rid of the loose change? And later, Rick rides out to see his restored 19th century racing sulky. Will he think it''s a two-wheeled winner or will he gallop out the door?', '2016-08-10', 21, '/6tWMbKPtSmXerGWDaiBwsjuWe8i.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
