INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8565FB3A929B46E7838506D816156EA6', X'004ABC4CCE774DF98C979F56EA8B37CE', 10, 'Cousins', 'Mouse''s two cousins come to stay at Kipper''s house. At first it seems like a good idea, although Kipper is confused as to which mouse is which. But the cousins are always hungry and they make a lot of noise. Kipper and Mouse would like them to go - but how do they set about it?', '2000-03-23', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
