INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'85741CF14699453F861CD51FFABFF172', X'262E8E7CFA784578A216ADD6F184C4D2', 9, 'No Place For Home', 'Kody, Meri and Robin realize that there are no polygamist houses to be found in Las Vegas; a surprise birthday party for Meri.', '2011-05-15', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'85747E259E2A4DB8BD5C82CE7710C784', X'E40E6B639F84449F8E8853209B0906C8', 9, 'Sleeping Grouchy', 'Oscar and Grundgetta are reading The Tale of Sleeping Grouchy" and Slimey, Telly and Elmo join them. The story begins, "Once upon a time, there was a very, very, very grouchy princess . . ." and it tells the tale of a princess that was so grouchy, she said things like, "Phooey!" "Ewwww!" and "Sounds horrible!" One day the grouchy princess was on a grouchy walk. She said, "Phooey!" so many times that it disturbed a wizard who was walking nearby and he cast a spell on the her, putting her to sleep for a hundred years! Princess Grouchy''s parents were very upset. They loved their grouchy daughter dearly and wanted to find a way to break the sleeping spell. They offered a reward to any prince who could wake the princess up. Prince Elmo came and tried to tickle Princess Grouchy awake with a feather, but it didn''t work. Prince Telly played his loud tuba with his back-up band, The Cat''s Meow, but Princess Grouchy still did not wake up. Finally, Prince Slimey arrived.', '2007-08-29', NULL, '/2NW5tVpaW2Vdhhh0O5y09c9WCX1.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'857A964D54564B6B9B9FCE6EB22316E7', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 2, 'Space Exploration', 'Space is hard to explore, because it’s really, really big. Most things in space are so far away that people we build special equipment just to see them. We use telescopes to magnify far-away solar systems, planets, and stars. Rockets send astronauts past the Earth’s atmosphere. Space probes with special cameras send back pictures of planets for scientists to study. Astronauts perform experiments in orbit around the Earth. We do all these things and more to learn more about our universe.', '1997-09-26', 26, '/99eo9VpOaKNbr5uSGTNTXMkJqKf.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
