INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8584051BE34C487389E365575FE5D84C', X'4F18AC4C8757456CA49A224F00E6A9F7', 13, 'Abby Thinks Oscar is a Prince', 'Chris reads Abby Cadabby “The Frog Prince”, which she anxiously waits for the ending of. Chris finishes the story and Abby loves it. As Abby walks down the street, she finds herself amazed that a frog of all things could be an enchanted prince. While Oscar deals with a man with some trash behind her, Abby wonders if some on Sesame Street could be a prince. She sees and Oscar and gets the idea that he may be an enchanted prince!', '2008-10-07', 58, '/hPOSBwe1WN1Rw65NJdjy8JopLfE.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
