INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'85A43153D0F843E48481F009815830EF', X'DE8EC76916BB436BBE43AEDC7E18A7D7', 13, 'A New Friend on Sesame Street', 'There''s a new face on Sesame Street! With Elmo and Rosita’s help, military kid Charlie finds her way around the neighborhood and learns that Sesame Street is a place where everyone can be friends - no matter how different they are.', '2020-02-08', NULL, '/df4wf0tmLcpG80NkaZYzKzoaMJY.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'85A684306D8A4CC780136B8C55A2B231', X'244B0A34284B4EC1B3A70E5ABFF6D0D1', 3, 'The Silent Treatment', 'George wonders whether anyone would notice if he just disappeared, and so vows not to speak until someone notices him. Of course, his friends do notice, and they decide to cheer him up with a surprise party.', '2009-10-13', 13, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'85BC9D1BDC8348F9AD7BA800BA63C66D', X'8BAE6AA34B554FA6BC158F4317BD1F13', 36, 'Lady Elaine Flies into Space Pt 1', 'Rogers makes a crayon rubbing of leaves. Mrs. McFeely invites him to their house to see a fern and a reptile called a caiman. In the Neighborhood of Make-Believe, Lady Elaine is still thinking about space travel. She sends Mrs. McFeely for leaves on which, Lady Elaine thinks, she can ride to Jupiter.', '1972-04-10', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'85BCCBD073974B7B9D27ADF3630F4497', X'EB7E3BB45746457781C6F5B2DC2EFC6E', 8, 'The Chase', 'Tired from trying to escape a machine that shows up every time they try to sleep, Aang and the gang have to escape Azula and her team, but their exhaustion leads to a tight situation. Meanwhile, Zuko must deal with something personal, and Iroh bonds with an unlikely individual.', '2006-05-26', 25, '/jM4D3ngfBqV1VzQeHKOadjT4qxG.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
