INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'85D3B1B85996427BB971F06B71A5BF8C', X'2794739239BA45A6B67BFC609EB26E51', 20, 'Tidal Turmoil', 'Hannah and Norman help at the Pontypandy Vets but end up losing the sheep and Prince the Horse, who gets stuck in sinking mud at the tidal flats.', '2023-05-31', 10, '/gaZ8iNKrhcBLPA2S6tKp9XOO1Kh.jpg', '2026-04-03T17:14:41Z', '2026-04-03T17:14:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
