INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'85DD01B3C4DC46C5B3EC1043CC691C26', X'EB7E3BB45746457781C6F5B2DC2EFC6E', 17, 'Lake Laogai', 'Aang and his friends continue to search for Appa and, unbeknownst to them, they aren''t the only ones looking for him. During their search, the kids meet up with Jet, whom they are understandably reluctant to trust. The kids soon realize that the Dai Li are doing their best to thwart the kids'' efforts to find Appa. Meanwhile, Iroh is offered his own tea shop in the upper ring, and Zuko discovers the avatar is in the city.', '2006-11-03', 25, '/cdrc7Caz9VabYfBl9bH9R93wk4j.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'85DF3641250B4F6AB4A7977F28AAEC19', X'91C151D984974056A4EE753CDCB08CEA', 2, 'Episode 1457', 'Mister Rogers is taking things to his garage including a large carrying case used to store the Neighborhood of Make-Believe modles. As he is putting the models in the case, he notices that the base of the tree model has been slightly damaged. Luckily Betty Aberlin is in the garage doing some painting and is able to help repair the tree.', '1976-02-17', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'85E060513E7C4808B493EB5BF32E0F91', X'573FA62F55A94F1797CCD1A005A83CC8', 22, 'Elmo and Abby''s Hot Potato Hoopla', 'While playing hot potato with Abby, Elmo learns how to win -- and lose-- gracefully.', '2025-06-12', 26, '/4oS8jRbJhvQNXwpis6hPKd4XXuS.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'85E128CBD82B4D829FC78147123BED3D', X'9C5608B2511148BCA9077F93472C1E03', 1, 'Get Lost, Mr. Chips', 'Alan is getting ready for the Cookie Connoisseurs Club, the most exclusive cookie appreciation club in the country, to come to Sesame Street to taste his super cookies. Alan asks Chris to distract Cookie Monster while the club meets. Chris tries, but it''s too late. Commander Chiphead, the club''s Cookie Master, says that Cookie Monster can only taste Alan''s cookies if he''s a member of the club. To join, he must recite the Cookie Connoisseurs Club Pledge of Allegiance and follow the three rules: to first look at the cookie, then smell the cookie, and finally, only nibble the cookie to savor its flavor. Cookie Monster thinks he can follow these rules, but devours the first cookie right away! Commander Chiphead is not happy, but gives Cookie Monster another chance. Chris suggests that Cookie Monster try to pretend that the cookie is something else to help him control himself. He pretends that it''s a yo-yo, which seems to be working, but once Cookie Monster smells the cookie, he eats it right up.. Next, Cookie Monster tries to pretend that the cookie smells like something stinky, which helps him get past rule #2, but as he goes to nibble it, he loses control again. Cookie Monster has one last chance, so this time he keeps reminding himself out loud that he needs to control himself so that he can stay in the club and get to try all sorts of cookies. The strategy works! Now it''s time for the last cookie, and Commander Chiphead is so excited because it is one of his favorites. He loses control and devours the entire thing. Cookie Monster offers to help teach him self-control since he''s so good at it now.', '2012-09-24', NULL, '/gNSK5odxvq2jJy7B9dpDlSnHBLC.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
