INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'863D2C309ECC4EA5A8CDE5D6764C2041', X'3EE646E823AE4DECBBC6C7E6A210D55B', 101, 'Episode 2846', 'Maria introduces the word "WET." She tries to describe it, but is interrupted by others who remark how hot the weather is today. Maria writes the word "HOT" on the other side of her card, noting that when it''s hot out it feels nice to get "WET." She''s then doused with water.
