INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'86497F1006684448B1CE8289FBBB4F43', X'1D556682D9BB47E1993F0B648A8DAACD', 76, 'Episode 1261', 'Big Bird and Snuffy hit the dance floor and groove to a disco version of "Rubber Ducky".  Guy Smiley and Cookie Monster appear in the classic "Beat the Time" skit.  Grover sings about the letter "I".  Bob and Big Bird encounter a dragon in New York''s Chinatown.  Ernie''s opera singing wakes the neighbors.  Harry Monster visits the eye doctor and an animated version of "We All Live in a Capital I".', '1979-03-12', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'864D48D9BE5F4BA8AB976F197B1F5BF7', X'FE19A277AED844DFA4ACFC1C4E9941B4', 6, 'My Ego Is Bigger Than Your Ego', 'Kim lays down the house rules with her new nanny and then finally buries the hatchet with Lisa. Kandi meets with her wedding planner, but her plans for an engagement party are dashed when she finds out that her nephews and AJ''s son are in a life threatening car crash. Kandi spills her guts to Sheree and their friendship grows as they realize they have a lot in common. Nene gets all of the ladies in line for their Alter Ego photos and then directs them all in a riveting photo shoot. At the photo shoot, Kim and Sheree talk civilly for the first time and decide to do something nice for Kandi in light of her family tragedy.', '2009-09-03', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'864DAF5B814645849FB19C77FBE3825A', X'3EE646E823AE4DECBBC6C7E6A210D55B', 103, 'Elmo and friends play Wubbaball', 'Big Bird and Jelani welcome the viewer when Elmo comes rushing in. He tells them and the kids about what just happened to him involving some blue monsters and a Wubbaball. Big Bird tries to get him to clarify what a "Wubbaball" is, but Elmo cuts him off as he starts his story.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'865008F2411E4FE79E7AB3F3228F4BBA', X'94EFC1313A474BCBA519330E791CE905', 1, 'One Snowy Night', 'It is a freezing day in the park. Soon the snow does begin to fall, and fall very heavily. The weather reports warn of heavy snowfall and strong winds, advising everyone to have their hot water bottles to hand.', '1996-12-01', 15, NULL, '2026-04-03T17:19:01Z', '2026-04-03T17:19:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'865078AA137A440DA5C72B4966F147A8', X'D8CCF6D3E37A430AB67D7FBF269BF0BE', 1, 'Fresh Powder, Fresh Start', 'The women of Salt Lake return and Heather wants to get everyone together for a fresh start. Whitney''s public comments about Meredith put a strain on their already fragile friendship. Angie introduces her friend Monica to the ladies. Lisa struggles with her son Jack''s decision to go on a Mormon mission.', '2023-09-05', 44, '/1R8cfiPIcgGJTh6hTMudE192zec.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'86518C7978C342E4871AA068DFDDEA79', X'D1D267DDE27F4543ACB80D28F676512A', 8, 'Episode 8', 'with Valerie Singleton and John Noakes', '1967-10-23', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'866599CEAD6F46128EC775D8C2B130C2', X'6FEDBA8252F34184BE776B26E556CD0E', 19, 'Mr. Curry Takes a Bath', 'Mr. Curry decides to try out the new sauna Mr. Brown has had installed, Paddington ends up being locked inside.', '1976-05-05', NULL, NULL, '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'86677D813DB2475286DE6D4CD5A50A0F', X'D5383B3D56364D71B99CB84774B4B3C6', 26, 'Pingu and His Cup', 'Pingu is competing in the sports day, and has already failed in his first event. He runs up for the high jump, trips on a bump in the snow and crashes into the jump, dislodging the bar. The bar lands on his head! Pingo and Robby then both successfully knock the ball through the ring. Pingu skies his ball; it hits the schoolmaster on the head, and stops just short of the ring. Pingu gets his third cross on the scoreboard in three tries. In the sledge race, at the start Pingu just can’t get his sledge to go, and Robby (on a tray) and Pingo disappear into the distance. Pingu then manages to start by pushing his sledge, catches up, and has a narrow lead over Pingo at the turn. On the way back, Pingo hits a rock in the snow when trying hard to catch up with Pingu and his sledge goes out of control. He crashes head first into the snow, and his sledge shatters. Pingu stops and goes back to help. At the finish, they’re wondering where they all are, and then Robby appears on his tray and finishes first. Pingu and Pingo then arrive together (both on Pingu’s sledge), cross the finish line and crash into the first aid tent, which falls on top of them. The schoolmaster marks up the scoreboard with success for Robby, and fails for Pingu and Pingo. Pingo, on a crutch, then explains to the schoolmaster what has happened, and Pingu has his fail erased and is given three successes! He is awarded the cup, has his photograph taken holding it, and rushes home, but no-one is about! He puts the cup on the stove and goes looking, eventually finding Father sawing wood. He excitedly explains to Father about his win and rushes inside to get the cup to show him, but the cup has melted! Pingu is aghast, but then remembers the photograph that was taken with him holding the cup, and shows Father that instead.', '2000-04-09', 5, '/snP03c0bPQNf2XXMGD7UzzsYfgJ.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'866CB17C72DF4CBF88A02530CB7DA754', X'A8C6182E05E14B6891A55126CF6C94F0', 35, 'James Armistead', 'The Americans send out James Armistead, a slave, to spy on the British by pretending to be Benedict Arnold''s slave.  He finds out that Cato, Moses'' brother is a British slave. The British ask James to spy on the Americans the same way he is spying on them.', '2003-01-23', 30, '/izsAnnffWyTddt2ldzqPtR4DCjC.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'866D823E4DE94C09BB91A70F8951BD7E', X'03485B5EA5B7423EB21EC00E62216A35', 12, 'Mighty Milton', 'A new cub named Milton is teased by Too-Tall and his friends.', '2004-04-08', NULL, NULL, '2026-04-03T17:40:22Z', '2026-04-03T17:40:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'866FACA73DE047BA8F0149F5E7E3AC99', X'D1863F2F02EC40CEAF64DB03FBE518A7', 6, 'Valentine''s Day', 'It''s Valentine''s Day on Sesame Street! Elmo and Abby make valentines for each other and learn about the importance of friendship. Also featuring Cookie Monster''s Twilight parody, and Elmo the Musical. Brought to you by the letter V and the number 14.', '2016-02-13', NULL, '/tGcbQ5hnW7PPSgdsDxcGgxSqm7T.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8679913F81B04D959D212A6B4BBD3924', X'21745B85D26942FAB4DD701B2DA5C085', 75, 'Episode 75', 'with John Noakes, Peter Purves, Lesley Judd', '1974-06-06', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'867A6E46C7C1456AAD3609BFE17631EA', X'D1863F2F02EC40CEAF64DB03FBE518A7', 11, 'Abby''s Fairy Garden', 'Abby is going to teach Elmo how to garden, but a gnome takes his seeds and flower pot. Abby and Elmo need to play memory games in order to get them back. Also featuring Murray had a little lamb, and Elmo''s World-Plants. Brought to you by the letter G and the number 17.', '2016-03-19', NULL, '/9a4IRaKJzJSC3KJABaSOdzRriuJ.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'867A971D627145A7A544207AEE52D6FA', X'136B81D3964D4B8FA21492F00D96D6B9', 4, 'The adults explain Mr. Hooper''s death to Big Bird', 'When Big Bird eagerly presents drawings he made of his adult friends, he''s devastated to learn that Mr. Hooper has died. The adults gently explain what death means, reassuring Big Bird that they''ll help care for him and David will run the store. Big Bird tearfully says goodbye to Mr. Hooper''s portrait as his friends comfort him.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'867E2F8201C94451A5D1E9CF5B6942EE', X'9F448CB807F84040840BC8690371EC41', 13, 'The Comeback', 'Kramer arranges to die with dignity; Jerry learns his tennis consultant is a lousy player; George becomes obsessed with responding to an insult long after the fact; Elaine offends her video advisor.', '1997-01-30', 23, '/9ECbFHKynwqOzPPViZnHpcq21Rz.jpg', '2026-04-03T16:34:12Z', '2026-04-03T16:34:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8680BFD521A545C6B519466DA2C998A7', X'0F64BF9F8D054F5B9A575D0C44AC3F40', 5, 'All About Christine', 'This one''s all about Christine! She reveals the things she never wanted to talk about at all and what she was really thinking during the most memorable moments of the past five years.', '2015-09-27', NULL, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'86811E44439C4CC490D096A9D2207E3F', X'98D80972E53A43DDA03A7703465E6F87', 10, 'The Offer', 'Start your engines with the Pawn Stars as the guys check out a 1956 Chevy drag racing car. Custom built for the 1/4 mile, will the guys race to make an offer or will negotiations stall before the light turns green? Then, when a guy brings in a historic magician''s "sawing in half" box the guys learn that cutting Chumlee in half is the easy part ... putting him back together is a bit tougher. And later, Corey shocks Rick and the Old Man when he tells them he''s considering a job offer from another pawn shop.', '2012-11-26', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
