INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'869018D012C04DCE9E4AC30CB90DF472', X'DEC4A06D731B41E48B15374F47D1F5C7', 14, 'The Importance of Being Family', 'Teresa tries to stay strong as she bids adieu to her husband, who begins a prison sentence. Meanwhile, Siggy visits the Holocaust Memorial and reflects on her father''s experiences, and a possible ray of hope shines on Jacqueline and Teresa''s friendship.', '2016-10-16', 43, '/fPaQmey9HUU4uCJqr6qX3Idrvxu.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
