INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8699397A1A34432FAD20FBDB182FA1F7', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 34, 'Forgetful Jones loses his numbers', 'Bob walks outside of his apartment and greets the viewer. He''s just happened to receive his mail, and decides to go through it as he strolls down a busy Sesame Street.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'869B80BE57224D2681BF60ADFFA57B71', X'E38E9D8714324A1AA7D064A559BF7570', 8, 'Friends In Need', 'Now that he has met the lovely Vixen, Fox is in his element. He asks Vixen if she will be his mate. But she tells him he that must prove himself to her first but does agree to help him get back to the other animals. They eventually find that the animals have taken two paths. The two foxes each take a path and agree that whosever is on the wrong path will head back to join the other. While following their own path both Fox and Vixen hear the cry of the hunt and it is on the trail of Vixen. Fox makes it halfway up to the top of a steep hill where the rest of the animals are but runs back down to draw the hunt away from Vixen. He succeeds but only for a while as they give up when he escapes back up the hill. Fox is devastated to realise that poor Vixen may not make it as she is exhausted and collapses. A huntsmen is edging his horse on to trample on her when all of a sudden Adder appears. She bites the horse''s leg, causing it to rear back and stumble down the hill, letting Vixen escape to', '1993-02-21', 24, '/t1M8QpZ6Yzm9UtcgSB4rMLTs8WV.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'869BFDB4FC514BFA9550EAF0156DCE21', X'EA73E13C696248048305C303DF65F89F', 8, 'Sara Moves In (3) - Royal wedding announcement', 'The Neighborhood of Make-Believe is in the midst of a change. X the Owl turns the Z on his knothole door to an X, Lady Elaine Fairchilde paints the pillars of her Museum-Go-Round. But the big change is the news that Sara Saturday will marry King Friday.', '1969-02-19', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
