INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'86CC8B9454CA4CA494CBDC593C856684', X'8012F05A66A34254885F0A679393F3DD', 9, 'Attack of the Slime Monster (1)', 'Casey is writing a scary story for a local contest about ""Gooey Gus: the Slime Monster"", a doll that spits out grape bubblegum.  Casey thinks her story isn''t scary enough, so she asks for Lenni''s help.  Lenni adds atmosphere and writes how the Slime Monster is about to come after Casey.  Alex and Gaby come to help, too, and Gaby writes about Alex and Jamal finding the Slime Monster seemingly alive in an alley, and then Alex, Gaby, and Casey find the Slime Monster in a crock pot.', '1995-01-22', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
