INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'86E239D5964C42D8A0EE3C5F9A9D33FA', X'1C9EA7D3E2544E7B8A9F33EEA9C6C341', 7, 'What Would Michelle O Do?', 'Marlo takes Porsha on a hookah and Hennessy-fueled pedal tour to get her mind off her break up. Kenya deals with her own relationship issues and visits an estate lawyer to discuss the worst-case scenario. Rumors abound that someone in the group secretly recorded Cynthia talking behind Nene’s back. Meanwhile, Nene seeks advice from her life coach on how to restore her sisterhood with the ladies. Kandi begins to worry she and Todd may not see eye-to-eye when it comes to raising their new daughter, and after weeks of heartache, Porsha reluctantly agrees to attend another therapy session with Dennis and must decide if she’s ready to give him another chance.', '2019-12-15', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'86E440E228A244D6B6FCE230B801BBE4', X'ECB64EF34F8045A7B4A9C04434B02E35', 39, 'Tickets to Ride', 'Take a "magical mystery tour" with the Pawn Stars when a pair of rare tickets to The Beatles film, "A Hard Day''s Night," buzzes into the shop. Will Rick "come together" with these tickets to ride or will he "let it be"? Then, an 1850s Indian Peace Medal, given by President Fillmore, lands in the shop. Will Corey purchase this Presidential peace offering or will he have reservations? And later, Rick gets all hot and bothered when control over the thermostat becomes an all-out war. Will things in the shop get heated or can the guys get Rick to chill out?', '2014-05-15', 21, '/qUyREdxgufr64iHXKmZuMB86hCS.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'86EB157E4DA24EE183801F5A7743A18D', X'CB8A0322BE77485BB339BDD572BCA349', 28, 'D.W.''s Perfect Wish', 'Arthur notices that D.W. is not excited about her birthday. So he tells her about her memories throughout her year as a four-year-old.', '1998-12-31', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
