INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8700847765C94A7EBC39AC2E7BF9B4DF', X'5D57283D079C4F6693C833A2FEEADA89', 11, 'War of the Hecks', 'Sue makes a discovery that leads to an ultimate prank battle with Axl; Brick tries to read a recommended biography on Debbie Reynolds.', '2014-01-15', 22, '/cn2AUeF7IbGAU0vuELcr7BuBbOZ.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'870360F8D5414E8FAC0A783E38C64CB9', X'BB919AEC0D5C4C589A5AFA2A0A5DE2B6', 17, 'Episode 422', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'87100D75ACFF4B0098D09C40981A1BEC', X'941B8C6544544336BE7C1D0591C12F90', 25, 'Pingu Pancakes', 'Mother is making pancakes, and Pingu and Pinga ask if they can help. Mother lets Pinga have a stir, and then Pingu has a turn while Mother gets the stove ready. Mother then has to intervene when Pingu stirs too vigorously and sprays batter over them all, and around the room. Mother then shows them how to flip the pancake in the pan and they clamour to have a go themselves. Pinga goes first and with Mother’s help manages the flip. Pingu wants to try by himself but does it much too hard, and the pancake sticks to the ceiling. Pingu tries again, still gets it wrong and hits the picture on the wall. After a number of further unsuccessful attempts, which leave the room well covered in batter, Mother again shows him how to do it and prepares another pancake for him to flip. This one files out of the door when Father opens it to come in, hitting him in the face. Father flips the pancake back and it lands in the pan, much to the surprise of Pingu and Mother. When Father comes in, Pingu shows that he has at last got the hang of flipping pancakes, and they all applaud. Pingu then makes them all pancakes for tea, but doesn’t make one for himself - he waits for the first one he flipped to drop back onto his plate from the ceiling!', '2004-02-05', 5, '/tYg07lWvoBtlNSicEjn8cKwc9E.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
