INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8715EE0378A74F5D9E57F6DD99A6943D', X'C9ADC698BE924DD794ADD8F6759361CA', 36, 'Episode 36', 'Rogers works a typewriter specifically used with teleprompters. In the Neighborhood of Make-Believe, Pilot Ito wants to take opera lessons. King Friday calls John Reardon in to teach her.', '1973-04-09', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8716A35ACFD04A0EA87CAC89F4D36260', X'262E8E7CFA784578A216ADD6F184C4D2', 23, 'Sisters'' Special Delivery', 'The Sister Wives are buzzing with excitement as Robyn''s first contractions finally kick in. But not everyone is happy about it. The emotion builds as each of the Browns face their true feelings about Robyn''s family becoming their own.', '2011-11-27', NULL, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8717C2A9A7EF4643BBF750A6924687F4', X'D8CCF6D3E37A430AB67D7FBF269BF0BE', 4, 'Don''t Be a Drag', 'On the final day of their Palm Springs trip, Whitney takes over and calls Meredith on her behavior. Monica and Lisa''s tension reveals itself in head-to-toe drag. Angie and Meredith continue to throw insults at each other. Heather and Angie bond during a team building exercise. Mary bows out of participating in the ladies'' plans.', '2023-09-26', 44, '/3xiOub7RxYXcX1D5O29wzRBOQS4.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'871C323196D544638DAE426574B240F8', X'42E591E22A884434AE9F3D4B1D685613', 15, 'Colt to the Touch', 'Put the pedal to the metal with the Pawn Stars as Rick and Corey check out a ''51 Chevy driven by Steve McQueen in his last movie. Will a test drive make Rick feel like the new King of Cool? Then, a man moseys in with a Colt .45 he claims was used to kill Jesse James. Can the guys make a killing of their own? And later, Chumlee checks out an Atari Centipede arcade game. Will he spend a pile of quarters on this classic piece, or is it game over?', '2013-08-01', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'87282516365F44EC9A762E00AD2A9509', X'63F9BF6D39B344F4B885A56807277A80', 6, 'The Great Santa Claus Switch', 'The show, narrated by Ed Sullivan, begins at the North Pole with Santa Claus and his elves getting ready for another Christmas. However, Cosmo Scam has hatched a plan to kidnap Santa and take his place. As part of the plan, Cosmo plans to abduct Santa''s elves (one at a time) and replace them with his evil henchmen.', '1970-12-20', 50, '/nTOmLGzHlxEn1HEDuCnGGwcnLDK.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
