INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8733DDA551324EC8AD1BE485E7ADB957', X'78A02D50E3DC4549844A3CF357A32EF4', 13, 'If These Woods Could Talk', 'The ladies finally reach the woods of Georgia for a fabulous weekend of "glamping," but are shocked to learn that they''ll be spending their first night sleeping in tents. Later at the campsite, Marlo confronts Kenya over unresolved issues, leading to a massive argument. The next day, the women begin to come together and bond over their outdoor activities, but things quickly fall apart at dinner when Kandi learns about major rumors flying around about her. Forced to confront old drama and new drama too, the women all decide to speak their truth.', '2017-02-12', 43, '/cP5Z3CERRgfcngz3Pys7pdErO6p.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
