INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'87453CA62E404136A65779EB5F0B5316', X'C21DBD225E2E4414BB67750399AAF6F0', 11, 'Corey''s Big Play', 'Take a ride with the Pawn Stars when they check out a 1924 Dodge Brothers sedan. Complete with the original wooden wheels, will the guys make a move for this piece of automotive history, or will a questionable restoration have them dodging the deal? Then, a guy drags in a 19th century ball and chain that''s inside a Wells Fargo strongbox. Will Rick be able to put these rare pieces on lockdown, or will he get distracted and let them slip away? And later, Corey and Chumlee check out a Terminator "skill stop" slot machine. Will the guys save the future by defeating this terminator, or is this killer robot more than they can handle?', '2012-01-02', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
