INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'87C392173C6E4A5C991CCE25DDA72907', X'0E4196154C964DDE8ED2715770BA77BB', 26, 'This Is Your Life, Bear', 'When Bear decides to do some relaxing and tune to his favorite station, WCHA-CHA, he hears an announcement for a contest. The station will play a sample from a cha-cha record and the first caller to identify the name of the tune and the artist will win. Bear resolves to sit tight so that we won''t miss the contest, but has to get up to help out when the kids in the Big Blue House call. Luckily, he manages to make it back in time for the contest and succeeds in being the first caller and identifying the record. He wins a trip for himself and everyone in the house to Sequoia City. Tutter overhears him celebrating, but only hears a little of it --- he hears Bear saying that he needs a vacation and thinks that he''s upset. He and the rest of the kids decide to put together a special celebration for Bear to show him how much he''s appreciated.', '2006-04-28', 25, '/16i6qchDIthr4uOJccUotJpmeIn.jpg', '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'87C4146CA73E4705AEC1A92B115FBC14', X'8A5892F6CCB74F029A5A85B134B5F0CF', 13, 'The Water Tower', 'Some engines are very particular about what they will or will not be willing to drink, for the sake of who or what happens to be in the drink.', '1976-02-16', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'87C4BFB4308F45518A93E29F6E5A448A', X'4D2CAC0F38FD438B8AFAACF43952E535', 244, 'Episode 244', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. Including: Dances from Spain by Manuela Vargas and members of the Spanish Dance Company. Little Watha: 3: The Tomahawk by Oliver Postgate. Is there magic in the Valley of the Gods? Little Watha finds danger - and a gift from the brother of a great brave. Told by Peter Hawkins and Patricia Hayes. Owning a Pony - Ross Salmon and Elizabeth give Moorland King his final training.', '1963-08-26', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'87CD590E45D041C2992B0B4DFEB1E73B', X'F12380A993E547BB9E2FCF1EED11EEE4', 3, 'All About Eggplants', 'Mykelti and Tony drive right into a tornado as Christine and David help them move to North Carolina. Kody and Robyn decide to begin anew while someone makes an unexpected pregnancy announcement.', '2025-10-12', NULL, '/xin9Afl6EYPIgBwmgGQSRafABqX.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'87D224253BA643C4AF40D55DA5F60AC9', X'39505290458D46B98BDF69EE037230E2', 3, 'Regina''s Big Mistake', 'As LeVar works to make a clay model of his childhood home as a birthday gift for his mother, artists and their different mediums are profiled. Anna Holbrooks reads the story of Regina, who frets about making the perfect drawing in art class, and gets frustrated when her classmates accuse her of copying them when she has difficulty deciding what to draw after the teacher gives the class a theme.', '1997-04-09', 30, NULL, '2026-04-03T17:36:20Z', '2026-04-03T17:36:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
