INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'880168B12A5246399E5F3144897FFE72', X'D77EACDE596342859AEC3DDAA65F0C59', 1, 'The Tin Forest', 'LeVar visits a school in New York City to ask the class how they have coped since the past year when the World Trade Center was destroyed nearby and they had to evacuate and some children lost family members. Jeff Bridges reads the story of The Tin Forest, about a lonely man who builds a metal forest of trees and animals in hopes of attracting real animals to ease his sadness.', '2002-09-02', 30, NULL, '2026-04-03T17:36:21Z', '2026-04-03T17:36:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
