INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'88ABC7F74AE9401DADCE7A83CADD436C', X'3EE646E823AE4DECBBC6C7E6A210D55B', 55, 'The Dawg family moves to Sesame Street', 'Big Bird sees a large amount of stuff on the sidewalk, as an employee of the ABC Moving Company (Phil Hartman) moves more and more things from the truck. Gordon, Susan, and Luis welcome the Dawg family, whose daughter, Brooke, hides nearby.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'88B80F8B78834BE8A3F5C5EDC9A946E9', X'98D80972E53A43DDA03A7703465E6F87', 21, 'Million Dali Baby', 'Keep it surreal with the Pawn Stars when Chumlee and Olivia are offered a sculpture by Salvador Dali. Without any proof of authenticity, will they take a night shift risk? Then, the guys are spinning over an atlas from 1862. Showing the world as it stood during the Civil War, can they map out a deal? And later a 1930 s pinball machine rolls into the shop. Will Chumlee s expertise on pinball machines help the Old Man score a good price, or will it just put him on tilt?', '2013-01-28', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
