INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'88BD09CECB4841A587FDB0305BCD9520', X'F9A8D8B3D72E437EA9D57477F6D64DF8', 9, 'How to Catch a Robot Dog', 'Elmo and Tamir need to catch Norbert’s robot dog, Alfred, but he keeps running away. What if they make a fishing pole with a magnet since Alfred is made of metal? Let’s try!', '2022-12-29', 26, '/eF9SOgOtSnBLjKlyHpD2a2ZRJvl.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
