INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'88C3653D11A54552A663230EC5B3139E', X'36EA381466B44986B6EE44559D3562C1', 22, 'Final Curtain Call', 'With Kandi''s musical approaching, ticket sales aren''t where they should be and Porsha isn''t paying attention at rehearsals. NeNe has to see a doctor after enduring strange pain. Apollo and Phaedra discuss their marriage. Kenya has a pet funeral to attend.', '2014-04-13', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'88C4066B9466419A9647176CA16C02DD', X'E606692A47B7411EB54B7C6BF61A67B7', 20, 'The Coyote And the Rabbit:', '', '2005-08-14', 30, NULL, '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'88C75841038A4199BD246BDCF03B4BD2', X'70C8CB4624944DD498F66BFB9B3FAF73', 13, 'Big Guns', 'The Pawn Stars are presented with the most explosive item to ever walk through the door - a pair of Soviet nuclear missile launch keys. Can the gang count down and launch the deal or will it blow up in their faces? Then Rick hopes to buy an extremely unique 1920s ukulele banjo made by the legendary guitar company Gibson. Will Rick strike up a chord to buy this antique instrument or break a string making an unsound deal? And later a man walks in the shop with two of the biggest guns Rick has ever seen. But when it comes to pricing these behemoths of bang will size really matter?', '2010-03-08', 21, '/ikhJtshxEaJGhuy9oTvjBrp9Ui4.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
