INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'88D0815DDACE4BD79274A78B4D4F82AF', X'F9A8D8B3D72E437EA9D57477F6D64DF8', 8, 'Rudy''s Favorite Sweater', 'When Rudy’s favorite sweater no longer fits, Nina suggests they have a clothing drive so everyone in the neighborhood can donate clothes they don’t need to those who do.', '2022-12-22', 26, '/mt7ctqIYrzeg1JZyqcBBjundmse.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'88D26CF8B5FD4844B654BEB006500423', X'6F731E6BD3C54DE684E17A19CB650E86', 44, 'Famous Finds', 'Search for success with the Pawn Stars and rediscover some of the most famous finds in the shop''s history: a 40-year-old Bob Dylan album that lands Chum face to face with the voice of a generation, molds of Joe DiMaggio''s and John McGraw''s Baseball Hall of Fame busts, a book printed by revolutionary founding father Benjamin Franklin, a suit worn by the Godfather of Soul James Brown, a rare collection of autographs from Gemini space program astronauts and a football program from the first ever NFL championship game that sets Corey on a mission to prove himself.', '2016-07-13', 21, '/kefJSkWrPOkVRo8wGwzECysltVb.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'88D6C4732BDA4B2CB99DFAD5FDD374CF', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 77, 'Gordon waits for Mr. Snuffleupagus', 'Gordon settles in beside Oscar''s trash can with food and supplies to finally meet Mr. Snuffleupagus as promised to Big Bird. Oscar and Grundgetta prank Gordon with a trash-can Snuffleupagus disguise, and Susan reminds him of their dinner date that he''s reluctant to leave. When Big Bird excitedly claims Snuffy actually did appear nearby, Gordon realizes his long vigil may have nearly succeeded.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'88D7BF375E7B4789913A6209F20C902E', X'F6015D9AECE4414AA00B06CF689FE40B', 15, 'Thrills and Skills', 'Warning, this is the most hair-raising and exciting episode of Blue Peter ever! Radzi conducts four million volts of electricity to shoot lightning bolts from his hands.', '2018-04-05', NULL, NULL, '2026-04-03T17:22:10Z', '2026-04-03T17:22:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
