INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'88E3F7AEC7294889BE86BD9DC88575E4', X'ABEB8D075C864F6AA110B11CBA2A4138', 20, 'Sozin''s Comet: Into the Inferno (3)', 'Sokka, Suki, and Toph try to stop the Fire Nation''s air fleet. Meanwhile, Zuko and Azula duel in an Agni Kai and Aang confronts the Fire Lord.', '2008-07-19', 23, '/jM6NzBbk5P22j3dWnIpOb7oTXeS.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'88F07ED84CE74A5EAF57EE88CCD264E8', X'56428E5E7DAA468D8BD2076956507AA8', 8, 'Bones & Muscles', 'In this show, you can Bone up on Muscles. When you clicked on the Nye Labs web site to read this, you used your bones and muscles. Without them, you can''t click, surf, or even sigh. Bones and muscles work together, or you aren''t going anywhere. Muscles always pull, even when you push on something like a door somewhere in your body your arm and leg muscles are in tension. They are all attached to bones, and those bones are pushing; they''re in compression. By pulling on bones you can breathe, talk, and move all over the world. Your bones support your weight like beams of steel or wood. They''re stiff and strong. Rigid as they might seem though, they do flex. And, if you bang one hard enough, it swells up. You have a lump. That''s because bones are full of blood vessels. Bones are not solid like rocks or skeletons in a dinosaur museum. Bones flex and grow. In fact, putting healthy amounts of stress on your bones is good for them.', '1994-09-17', 26, '/7hwgpEWPSysbpn9YbbizJZao8lv.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
