INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'88F671711A7A4BAF8318337941B25FC7', X'5A4E38A18E5449748097D7A7B48630A2', 72, 'Episode 72', 'with Valerie Singleton, John Noakes, Peter Purves', '1971-06-04', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'88F80FD699DE4D17A4F8D3E8D57F493C', X'4D2CAC0F38FD438B8AFAACF43952E535', 285, 'Episode 285', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. If you have ever watched "It''s a Square World," Michael Bentine''s programme, it is likely that you have seen him grappling with the Bumblies. They are little creatures, with twittery voices and rapid movements, who pop up at the most awkward moments - during a lecture or a song - and take over the programme with their antics and furious energy. You must have wondered about them - where they come from, and how they get in. Today you may have a chance to find out because Michael Bentine himself is coming along to talk about them. We say "may" advisedly, because with Bumblies you never know what can happen!', '1964-06-29', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8903F548B5A24FFBB6245FB7B39F1CE5', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 61, 'The Handicap Spot (Syndicated Version)', 'Going out to buy an engagement party present for The Drake, George parks his father''s car in a handicap parking spot, after taking Kramer''s advice.', NULL, 30, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8909A07CAE734E008B00CAC32CB740EE', X'5A771F52FE964EA2B567A8DDE899059E', 9, 'Royally Pawned', 'A set of royal British armor has Rick suiting up to strike a bargain. Chumlee''s purchase of a U.S. Open custom electric guitar gets no love from Rick. Will Chum be able to net a profit before Rick reaches his break point? Signatures and a movie script from famed comedy duo Abbott & Costello inspire Corey and Chum to reenact a hilarious scene from the film, but the amount of money this seller is asking for is no laughing matter. A seller with an antique coin-operated scale throws his weight around during negotiations. Can Rick get him to lighten up enough to make a deal?', '2017-11-13', 21, '/l17fn2vJ35lqu0bLo5pWXMxugqg.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
