INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'899FA4D4DAFA4F219BEA29ADA4AF0870', X'5C4E51C6E20746AD875C72988EB1E13E', 11, 'Peacemaker', 'The Pawn Stars reach for the sky when an 1890''s Colt .45 "peacemaker" rides into the shop. Considered the ultimate cowboy gun, will the guys square off and draw quickly for this collectible classic or will a lack of firepower have them running for cover? Then, Rick meets a man hoping to sell his photos of a Japanese Zero shot down during World War II - in Alaska! Will Rick reach new heights to make a deal or will he fall into a tailspin? And later, Rick and Chumlee get up close and personal with the King of Rock & Roll when a man brings in Elvis Presley''s medical records. Will Rick give this sale a clean bill of health or is the prognosis not looking good?', '2011-05-09', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'89AA5B0457A94B0E837B13604B8E24CC', X'941B8C6544544336BE7C1D0591C12F90', 22, 'Pingu''s Stick Up', 'Pingu and Pinga are having their breakfast cereal when Grandfather calls and tells Mother that he has run out of milk. Mother gets some milk out of the refrigerator and leaves the igloo. Pingu helps himself to some more cereal, and some green fish stickers come out of the box. Pinga wants some of the stickers, but Pingu won’t give her any. Then Pinga shakes the cereal box, and gets some pink fish stickers. Pingu sticks a green one on his mug and Pinga sticks a pink one on the cereal box. Pingu then takes Pinga’s rabbit and sticks one of his stickers on it, and, much to her chagrin, won’t give Pinga the rabbit back. He goes into the bedroom and sticks a green sticker on Pinga’s bed. Pinga, who has followed to try to get her rabbit back, is not at all happy about this and stomps out of the bedroom. Pingu bounces gleefully on the beds, then wonders what Pinga is up to and goes out to see. She’s put her pink stickers everywhere. Pingu goes outside and puts a green sticker on the ground; Pinga puts one on the scooter and rides off. At Grandfather’s house, Mother and Grandfather are outside talking. Pinga puts a sticker on each of them and rides on. Pingu is annoyed when he arrives too late. Pinga then goes to the post office, Pingu catches up and, as Father comes out, they both put one of their stickers on him at the same time. He separates them, and then puts his green sticker on Pinga and his pink sticker on Pingu. Pinga rides ahead and continues to spread pink stickers about, including on Pingo! When they reach a playground Pinga claims the swing with one of her stickers, and Pingu claims the seesaw with a green sticker. They each sit on their claimed piece of equipment, but can’t play properly as Pinga needs Pingu to push her and Pingu needs a partner to balance the other side of the seesaw. Pingu goes and pushes Pinga on the swing and they both go on the seesaw, and then make up by placing their respective colour stickers on each other.', '2004-02-02', 5, '/eNCxp0BOx5U3jFulLg1Di1fpzIZ.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'89AC9BA3547A4D73B24E56C116918066', X'082D18AFD82E4DB887461F7473706DAE', 10, 'The Gift of the Sacred Dog', 'The first of many programs favoring Native Americans. In this instance, a Midwestern legend suggests how horses arrived to the tribe. Later in this episode is the song "Ancient Places, Sacred Lands" which lists several words originating from various locations of the United States and the tribal meaning of their names.', '1983-06-17', 30, NULL, '2026-04-03T17:36:14Z', '2026-04-03T17:36:14Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'89B33A6CC6184C8BB57A8683CE4F92D4', X'97A3D1F5A8F147CD81222E74A092836D', 28, 'What''s Up With Alex? (4)', 'The ""mysterious stranger"" turns out to be a drug dealer that Kevin had to pay back.  Alex talks to Mr. Oliver about Kevin''s drug problem.  Meanwhile, the team tricks Spencer into telling them that the Dragons player in the video was Kevin.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'89C56EB7B5114B0BA2DC5661FC916057', X'6F81C872CDB942DD83772C17CB6ED4D7', 26, 'The Camouflage Game', 'Elmo, Rosita and Chris try to find six camouflaged things on Sesame Street so they can join the Camouflage Club. Guest: Kyra Sedgwick.', '2017-07-01', NULL, '/3AZa7GXOEdmrD3qybDics6IO4SE.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
