INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A21AC7BA47D48EEBA15EC9977684137', X'97A3D1F5A8F147CD81222E74A092836D', 21, 'Don''t Stop the Music (1)', 'Lenni, Max and Sally are all watching Lenni''s video from the Star Jam episode Building Bridges. Just then, they get a call from Smash Records. Jade Morgan is inspired by the video and wants Lenni to star her in a music video. Lenni has writer''s block so she writes a song about self-confidence. Jade is inspired by the song and decides to allow the team to be in the video.', '1994-01-23', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
