INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A335D4B5C0E4BCE929522DF40E47C9E', X'2DCBD12286D846E8BBE59143875ABD34', 18, 'Buster''s Best Behavior', 'Buster and Arthur feel like that they are boring and they think they are not good at anything, so they try to imitate each others'' lifestyle.', '1999-10-15', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A371E1BC5884D55A09E17DC0633A1B0', X'CEFD1496B6494C62AEF935A22558AC08', 10, 'Don''t Cry Over Shattered Glass', 'It''s Brandi''s annual holiday party and she finds herself center of the drama when LeeAnne reveals that Cary can''t be friends with her and Stephanie anymore because of their behavior in Mexico. And when Brandi challenges her for an explanation, Cary sides with Kameron, infuriating Brandi so much, she blurts out a humiliating secret about Cary and Mark.', '2017-10-16', NULL, '/kewNJM5vogELqt08eAtdah60ETG.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A393C8D41104CCB96D21EE5A3711F63', X'095258D0D8DB40968AC76A42CD4CBDCF', 19, 'The Cavern Of Lost Dreams', 'When Cotterpin Doozer hears that Gobo is the bravest Fraggle in the Rock, she gets him to help her find the Cavern of Lost Dreams, which is where the original tower was built. When they get there, the remaining two Doozers, Yeaster and Crusty, don''t want to come back. Will these two Doozers finally accept the changes that have occurred and move back to the Rock and help build once again?', '1985-05-06', 24, '/qbxwkrLnP4E52QFON6O5YQvWvmg.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A41EFBCBADD4FDC829E04D10051DA31', X'3B5276CEBC2043EBA638FE5CED3178A8', 3, 'The Long Night', 'The Night King and his army have arrived at Winterfell and the great battle begins. Arya looks to prove her worth as a fighter.', '2019-04-28', 82, '/lto7fBOnfBUqH5QN8CWdFc70QjW.jpg', '2026-04-03T15:40:38Z', '2026-04-03T15:40:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
