INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A5208624E7042769A4BCB81190BAB27', X'3087A3EDE94E42769D02A78183DEA1D3', 1, 'Got Sexy Back', 'NeNe looks at a possible reconciliation with Gregg, and Kandi and her new man are moving in together.', '2012-11-04', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A560A8C01774AC3B8104A1C36158C7D', X'D5383B3D56364D71B99CB84774B4B3C6', 20, 'Pingu The King', 'Pingu is shovelling snow outside the igloo when he has an idea. He’ll build a castle. Pingu builds castle like ramparts round the igloo, and a nearby abandoned door becomes a drawbridge. He goes indoors, makes himself a paper crown, and sets out the kitchen chairs and table for the throne room. Pinga comes and asks Pingu what he’s doing. Pingu visualises himself as the king and explains. Pinga decides she wants to be queen and goes to the toy box. While Pinga is rummaging, Pingu is making a royal carpet with a cloth he gets from the cupboard. Pinga returns wearing a crown, and Pingu bows to her and invites her to sit on her throne. Pingu sits on his throne, and has another idea; he needs some subjects. He goes to the phone and, visualising knights wearing armour in battle, invites his friends over to join in the game. Pingo and Pingg arrive, and come in when the drawbridge is let down. They chortle when they see Pingu and Pinga on their thrones. Pingu acts all imperious, and gets annoyed when Pingo and Pingg don’t respond as he thinks they should, and clouts Pingo on the head, to his surprise. After some more ordering about from Pingu, Pingo goes and gets a carton of drink and a mug from the sideboard, pours some drink into the mug and gives it to Pinga, and gives the carton to Pingu. Pingu and Pinga both have a drink. Pingu tosses the carton to Pingo and Pingg, and it bounces off their heads onto the floor. Pingo goes to have a drink himself, and is not very happy to find the carton empty! Pingu now imagines himself in a coach, and orders Pingo to get it. Pingo bows to Pingu, and gets the toy truck. Pingu gets off his throne and into the truck, envisages himself being driven in the coach and orders them to pull the truck. Pingo gets annoyed and decides he’s had enough, and unceremoniously dumps Pingu out of the truck and onto the floor. While Pinga helps Pingu recover, Pingo and Pingg go outside. Pingg makes a snowball and throws it at Pingu, hitting him on the head. Somewhat dazed, Pingu imagines his castle falling down, takes off his battered crown and throws it in the bin.', '2000-01-30', 5, '/bTMwDS6MD1AmSQJoneff5JVfYl1.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
