INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A62CCABFC9845D1832EF4647AAAFB99', X'7BC54DF3F32A454EAEF6A9436C35D53B', 49, 'Episode 49', 'Rogers welcomes Mrs. Franks, who demonstrates how to carve leather. Later he discusses wearing an eye patch. In the Neighborhood of Make-Believe, Handyman Negri assures King Friday that his eye is underneath an eye patch.', '1970-04-09', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
