INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A71257A85C14CCAA37C65E4C34EA202', X'7B19039A31AC425C8FB1B51CF2447821', 9, 'The Lies That Bind', 'The ladies begin to self-document their lives during the mandated lockdown due to the global pandemic. Elizabeth has a change of heart about her divorce proceedings, Emily and Shane’s relationship takes a turn, and Kelly travels across the country to be with her fiancé, Rick. When tension arises between Shannon and John, Gina gives her two cents. Meanwhile, Braunwyn struggles to keep her sobriety and marriage intact during the quarantine stress. And as Braunwyn digs into Elizabeth’s past, Elizabeth invites the ladies for a bonding trip in Lake Arrowhead and Shannon receives some shocking news.', '2020-12-09', 44, '/9xrGkk0P9IoZdy0HLWtO983lQSZ.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
