INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A7E3BEDE14B44F2B0DE2C6184D7AC72', X'34674C90410E427CBE4D2A6F6F865A80', 15, 'Pin It to Win It', 'Play detective with the Pawn Stars when they try to discover the origins of a mysterious rifle brought into the shop. Will Rick pull the trigger on the deal of his life, or will the negotiation blow up in his face? Then, Corey and the Old Man are presented with a signed print by Leroy Neiman. Considered one of America''s greatest living artists, do the guys draw up an offer for this highly collectable piece of art, or get painted into a corner? And later, a collection of old sports pins needle their way into the shop. Can they nail down a deal or will this one fall apart?', '2012-06-18', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
