INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A881313624941F699891C230BC8A389', X'E3A2866991B545F7BB735006ACC084E8', 6, 'Still Life', 'The Farmer oil paints the farm, but runs out of white paint for the sheep. Shaun tries to fix the painting, but soon the rest of the flock are a riot of colour. Although the painting appears ruined, it actually proves to be a fortune-winning masterpiece at the end.', '2007-03-07', 7, '/sorEnRYTLQ19DMumDUPKJfZduJu.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A8A190DBB964588B5C8A6D4961C45A7', X'D7FF9136A8334C43A37CA985A34F45A9', 10, 'All Your Eggs in One Basket', 'Christine is excited to celebrate her first Easter since divorcing Kody. Janelle says her life is also better without Kody but reveals she would consider polygamy again. After learning Aurora is interested in a boy, Meri reflects on marrying so young.', '2023-10-22', NULL, '/qeZxInUylKzVqGFxnpiLFVLZnUf.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A8DEFC628EC43FC9D758A0E5A3204B0', X'4C79C0B621A442778967BE1E791EFDBE', 8, 'Pingu and the Present', 'Pingu is at home, playing aeroplanes, when an envelope is delivered. It’s for Pingu, and when he opens it he sees that it’s a card inviting him to a birthday party. Pinga wants to see it, but Pingu won’t let her, and Mother eventually has to intervene. Mother looks at the card and gives Pingu a fish to pay for a present. Pingu is just on his way out of the door to get the present when Mother tells him to take Pinga with him. Pingu and Pinga is not too happy about that, but Mother insists. At the toyshop, Pingu eventually decides to get a model aeroplane as the present. On the way home Pingu continues to not be very nice to Pinga, this time by hiding from her and being rude to her. While backing away he trips and drops the present, which slides into a small crevice that then gets partially blocked by a small fall of ice, with just a bit of the ribbon from the present sticking out. After searching for a while, Pingu spots where the present has gone and tries to get it out by pulling on the ribbon, but it won’t budge. Pinga says that she’s small enough to go through the gap to get the present, and Pingu is delighted when she gets it. When they get home, Pingu explains to Mother what has happened and sets off for the party, taking Pinga with him to her delight. When they arrive Pingu explains why he’s brought Pinga along as well, and Pinga gives the present.', '2005-01-12', 5, '/vvbk7fCbvQ5ftOhsynVmCrdLXMN.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A969324881441F39943379C72CCD420', X'E48599F866FF4C0F927465B9AE1CDA9E', 17, 'Episode 17', 'Real gladiators'' armour and a 2,000-year-old loaf of bread are two of the fascinating collectors'' items John saw when he took Blue Peter cameras to Italy and visited the site of the world''s most devastating volcanic eruption.', '1976-11-08', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8A98AEA13A334F08B1E01FCFE8FE1CF3', X'6FD9FD9DE378411B94B176BA4BD518FE', 63, 'Episode 63', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-04-28', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8AA1B716E18F48CE85375E95E85A614B', X'151E88A195764BD1B84AC4D64C1C9FE8', 4, 'The Crystal Conundrum', 'Crystal talks through her differences with the group, but the conversation takes an unexpected detour when she brings up old wounds — a stunning revelation that leaves Kyle completely confused. Erika tries to justify her stance on Tom’s legal situation, but Garcelle isn’t impressed. Lisa’s world is turned upside down by a family tragedy, Dorit begins therapy and Diana is confused by Sutton’s dietary choices.', '2022-06-01', NULL, '/1KoCIuYM5xYDPZC5lTBQ02wqBY7.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8AA2C489CCD342CE9C88893E5C9B02A4', X'06030129FF2D4490B66C9F41BBE7AABD', 16, 'Ferry', 'John goes off to Hampton to see a ferry. When Rosie and Jim see a boat that''s going to the same place as the Ragdoll, they fear that it''s going to cause a crash, but of course, it doesn''t. John hops aboard a ferry to be transported from one path to another that has the river as a collision.', '1990-12-17', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8AA6A78D490C4BEBA03271060FAC4B43', X'1E085F654B6945008FFC654D2F638DBB', 21, 'Elmo and Abby''s Ocean Adventure', 'After Abby turns Sesame Street into a magical ocean, Dorothy disappears, and Elmo and Abby must follow clues to find her.', '2024-03-28', 26, '/70oJJXiEpdErO0ynIjiN8ydX9J2.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8AABAF73C0A34EE6BE57D2D73AC4548D', X'EA73E13C696248048305C303DF65F89F', 13, 'The Royal Wedding (3) - Variety show in the Neighborhood of Make-believe', 'The Neighborhood of Make-Believe stages a variety show, which includes a ballet called "The Purple Glove Ballet".', '1969-02-26', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8AB0530C765B4208A6085B8AAD4914AD', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 18, 'Poké Pawn', 'Get ready to GO with the Pawn Stars as a very valuable Pokémon collection makes its way into the shop. Will Rick battle for a sale or will he be defeated? And next, it’s about time the Pawn Stars got a 1926 Dunhill Watch Lighter in the shop, but does it spark enough interest to be worth buying or will the deal flame out?', '2017-07-10', 21, '/7DuUR8NuBnxrKgFyqeHqDuqut4n.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8AB25ED0336C4AEEA214E247274CF82F', X'4C79C0B621A442778967BE1E791EFDBE', 5, 'Mother''s New Hat', 'Mother and Father are out shopping with the children when they pass a hat shop. Father says he’ll buy mother a new hat, and Mother tries on a flowery one and then a hat with a feather. While she’s doing this Pingu and Pinga are amusing themselves by also trying on hats. Mother isn’t sure which of the two hats she wants, but her mind is made up for her as the shopkeeper sells the first hat to another customer, so she ends up with the feathered one. When they get home Mother and Father are both tired out and fall asleep. Pingu comes in the room, sees them asleep, takes the hat out of its box and puts it on. He then goes into the bedroom, puts on a blanket as a cloak and gets a wooden sword, and then plays at musketeers. He twirls the hat around on the tip of his sword but it comes off and Pinga catches it. Pinga puts the hat on and Pingu chases her round the room, and they then have a tug of war with the hat. Pinga ends up with the main part of the hat, and Pingu with the decorative flower, which has come off the hat. Pingu sticks the flower back on, but in the wrong place, and Pinga says that it’s wrong. Eventually they fix up the hat, and manage to sneak it back into its box just before Mother and Father wake up. Mother and Father decide to go for a walk and Mother opens the hat box to get out her new hat, but is very surprised when she sees it as it now has more feathers and a lot more flowers on it than when it was bought. Pingu and Pinga are downcast with Mothers reaction, but are delighted when Mother decides that she likes it. Mother and Father then go off for their walk, and Pingu and Pinga congratulate one another.', '2005-01-07', 5, '/iP06jRMlGYgOQJgMfKgO1cKA7Yg.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8AB4C0931F9C4F68B2B763D83776B94E', X'225B0F03984B47F3A1A3D3E92175E39D', 81, 'Episode 81', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-07-13', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8AB6193C32DE4404BFC4EE5B39105F62', X'D0E5568D939D4D89AB4EC291A90691CF', 13, 'The Farm', 'Kipper, Tiger (wearing his proper farmer''s boots), Pig and Arnold are off to the farm. Arnold finds a large white egg and makes a nest for it in his buggy. The others tease him, but soon the egg hatches and a duckling appears. It joins it''s mother duck and six brothers and sisters and soon Kipper with Arnold on his shoulders, Tiger slipping in the mud as he carries the buggy, and finally Pig, join the end of the fluffy procession.', '2000-12-21', 8, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
