INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8AC148957F624890A029D06B270E17F6', X'0E4196154C964DDE8ED2715770BA77BB', 1, 'Welcome To Woodland Valley (1)', 'In the first part of "Welcome to Woodland Valley," viewers learn that a tragic event has happened in Woodland Valley --- a tree has fallen and ruined part of the village library. Everyone''s upset about it, but the entire Woodland Valley community is pulling together to help out. When the kids of the Big Blue House, including Harry, find out, they decide to help in their own way. Viewers explore more of Woodland Valley than they''ve ever seen before, visiting the library, the post office, the general store and the mouse school that Tutter will be attending, among other locations.', '2002-09-09', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
