INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8AEE4A711CB74184A0FD2EE5E2F0067B', X'D5383B3D56364D71B99CB84774B4B3C6', 14, 'Pingu the Pilot', 'Pingu is telling Pinga all about the plane in the book he is looking at when he hears a buzzing sound. They run outside, and wave excitedly at a plane as it flies overhead. Pingu rushes back inside and gets his toy plane out of the toybox. Pinga follows Pingu inside, and they have an excited chat. Pingu flies his plane, which crashes into the wall and then falls into the soup that is simmering in a saucepan on the stove. The saucepan falls off the stove, spilling the soup all over the floor. Mother, who is making the children’s beds, hears the clatter and goes to investigate. She angrily tells Pingu to go and play outside. Outside, Pingu wonders what to do. He has an idea, rushes into the shed, and a lot of banging is then heard. Pinga comes out to see where Pingu is, hears all the noise coming from the shed and goes to investigate. She excitedly discovers that Pingu is busy converting his sledge into a plane. Pretending to be flying, she rushes back indoors and gets her rabbit from the toybox, then runs back. They both get onto the sledge, and then wonder how to make it fly. Just then, Father arrives on his motorised sled, and asks them what they’re doing. They excitedly tell him, and then wonder why he then goes into the shed. He emerges with a small sail, which he attaches to their sledge at the back, and then gives Pingu his hat to wear. The wind gets up, and the sledge slides away. Pingu and Pinga excitedly sail about, pretending they’re flying. Mother hears the commotion and comes to find out what is going on. She and Father then watch as the children enjoy themselves on the sledge.', '1999-01-22', 5, '/uJHL5w7Ao6H1vJgjJHeZl54u2RT.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8AF31FB885A94D4DAC6EB1C6525D4052', X'C21DBD225E2E4414BB67750399AAF6F0', 19, 'Hole in One', 'The Pawn Stars prepare to fire when an 1830''s musket made by cotton-gin inventor Eli Whitney shoots into the shop. Can Rick come up with a perfect battle plan to secure this rare weapon or will he shoot himself in the foot? Then, when a man brings in a golf ball once owned by President Lyndon B. Johnson, Rick attempts to tee up a good deal. Will he sink a hole in one or miss his mark and land in the sand? And later, a man comes into the shop with a 1929 Chicago Cubs World Series press pin. Will Rick and Chum make headlines with this deal, or end up buried on the back page?', '2012-01-30', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8AF3CFDA28F14E1A8021884A5AB48FC2', X'3ADE5E1F84414C2CACF6FB933A61DCFA', 6, 'Boundaries, Bayous and Beignets', 'The ladies wrap up their time in the Big Easy with some enlightening and frightening experiences; unresolved issues fester between Ashley and Candiace; Karen unleashes her fury on Gizelle and leaves everyone speechless.', '2019-06-09', 42, '/2Tgi3dEwj8tQGeqEOmZUXCq4XlM.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8B006A83B1AF43DA873524BE11B5E94E', X'20D7138EEEA846A88ADA2B0F0EE1F674', 18, 'Episode 18', 'Celebration Cake: Top pastry chef Rocco Zuchetto reveals the cake of the year - designed by Blue Peter''s top prizewinner for this year''s Lord Mayor''s Show.', '1982-11-11', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8B068AEBCD684BE28CE0378F9604DE1F', X'5A82421858314C6DAEF38B5BA9147532', 14, 'Episode 1589', '', NULL, NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8B1A5BF43D69416EB35A2950B713E6E0', X'70D9E39768134785887D27D034928BAE', 9, 'Pingu Argues with his Mother', 'Pingu is outside the igloo splitting wood for the fire. Pingo comes by, carrying a ball, and asks Pingu if he’d like to come and play. Pingu goes in to ask Mother, who is ironing, if this would be okay. He is angrily denied and Pingu starts to argue. Eventually, Pingu goes back outside and tells Pingo the answer. Pingo goes off, and Pingu angrily goes back to chopping wood. After a while, Pingu goes to ask Mother, who has finished ironing, again, when he is still denied, he starts to argue some more. Pingu angrily leaves, sticking his tongue outside the igloo to his Mother, and starts moving the wood he’s cut into the igloo, stacking it by the fire. Pingu goes back out for another load of wood and brings it inside. But he decides that he’d rather go and play, and sneaks off. He meets up with Pingo, who is trying to sink balls into a makeshift basketball hoop, supposedly a barrel, and Pingu joins in. Mother comes and fetches Pingu back, and stands over him while he loads more wood and takes it to the igloo. Mother follows, shutting the door behind her. Pingu angrily strews the wood all over the floor, hurting his foot in the process. Mother is not sympathetic, so Pingu angrily kicks the table, breaking a fruit bowl and hurting his other foot even more. Mother becomes very furious: (she had enough for slapping Pingu in the face) and tries to punish him, but he gets terrified, bursts into tears, and runs into his bedroom in a terrified way and slams the door, leaving Mother stricken with remorse and feeling ashamed of herself, so she sits in a chair to calm down. Later, Mother, Father and Pinga sit down to dinner, but Pingu isn''t there. When Father asks where he is, Mother glumly explains to him what has happened. Father, annoyed, goes to find Pingu, but there’s no sign of him in the bedroom and the window is open. They all go outside to look for Pingu, but can’t find him. They sit down to their meal again, Mother and Father still can’t eat as they are worried. Then Pinga has an idea and goes to look in the wardrobe, where they find Pingu fast asleep in there! Pingu soon wakes up and Mother hugs him and they both make up.', '1995-08-13', 5, '/8DjwwgCkuj4Sl0PM5e80DVzJNm7.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8B1B87268CA64FC5BC6638C21A6DFE27', X'5C1B881FAC584D72B63F209952D4F902', 29, 'Episode 29', 'Two hundred years ago this week the most famous pantomime star of all time was born. His name was Joseph Grimaldi , and everyone from King George III to flower-girls in the gallery knew his catchphrase ''Here we go again!'' Chris tells the story of Grimaldi''s amazing life and shows one of the clown costumes he wore at Drury Lane.', '1979-12-17', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8B1C7BA1700346C08644700F328EA49A', X'515339666203439AB35A1E2326081F8B', 1, 'Pingu at the Wedding Party', 'Pingu and his family visit a wedding.', '1997-10-17', 25, '/aSFBlqB1LPe3wueOD9DVnPasJQ2.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8B2D14024B664DF8A5516A5D543E2231', X'C01DDD2ABDB14C978D0458F791EF1C24', 37, 'Cats', 'It''s kitten pandemonium when all kinds of kittens turn Animal Junction upside down. An overwhelmed Zoboo, Martin and Chris try to take care of these curious creatures but quickly realize that they''re in over their heads. Luckily, the cavalry rides to the rescue when the mother cats arrive to take control of the situation. The guys wonder if wild cats are similar to house cats and go to see if lions and cougars purr. Jackie is busy brushing her cat Rapunzel, a great way to show her cat that she cares for her. Plus, birds and squirrels love the loose fur for padding their nests.', '2000-04-24', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8B3472C5F20F46B59B2A7FC8B72DA868', X'3D4D8F6A970847E89C9926EBAFDB2609', 122, 'A hot day on Sesame Street (3647)', '', NULL, NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8B349449AFBC4887A98B77F7ED5C67F2', X'DFE2C51C8D2C4C92A0107DBB71C3E48B', 4, 'Dinosaur', 'Journey into the Jurassic to unearth the facts behind a lost world! Students will gain an understanding of the science of paleontology, master dinosaur entomology, explore the prehistoric landscape, investigate the Mesozoic era, evaluate theories of extinction and compare dinosaur physiology. This program brings these amazing creatures to life millions of years after their extinction!', '1995-06-12', 29, '/wJhUQjzBB4ccetoFgTwzDy2fqu1.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8B34FEDB1FFC4F8BA5C232065E28501B', X'E48599F866FF4C0F927465B9AE1CDA9E', 35, 'Episode 35', 'PETER becomes a carillonneur when he plays the 47 bells of Loughborough''s world-famous Carillon, and discovers how manure played a vital part in their casting.', '1977-01-13', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
