INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8B43BC6A4DA44EBFB8855368E00B06B6', X'E291DF42D44F49E5BF812DF32EE4A30F', 14, 'Wait For Me', 'Patience is discussed here, while Ojo and Pip and Pop wait for a package to arrive. Tutter can''t wait for his cheesy fruit pops to be finished, so Bear helps him out with an alarm clock that will let Tutter know when the pops are finished.', NULL, 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8B45F34216264276AF7FCA2605E210B4', X'4F3632B8A91046B6B2EDF2882CC14B2D', 1, 'Sesame Street Presents: The Street We Live On (4057)', 'At the start of SESAME STREET''s 35th season, the high-spirited red muppet, Elmo, learns more about the street on which he lives. With the help of his friend Grover, Elmo is seemingly transported through time to the Sesame Street that existed before he was born. In these flashback moments, Elmo meets Mr. Hooper, the man behind the name of that famous store; witnesses Maria and Luis'' wedding day and the birth of their daughter Gabi; and experiences Gordon and Susan''s adoption of Miles. The finale of the episode features Sesame Street''s entire cast singing a new composition called ""The Street We Live On."" The story ends with Elmo''s realization that he doesn''t have to dream to find his friends on Sesame Street - all he has do to is run outside to be a part of this very happy family.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8B46D65CE4F44685908E65CC0D048033', X'8C3CFAC1D8824904B38CD1981628D00E', 20, 'Episode 20', 'Only 39 days to go until Christmas so now''s the time to get ahead with cards and presents! Lesley shows some ideas for cards that cost only a few pence to make.', '1978-11-16', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8B49A7643E84405EB7765316FD67B546', X'136B81D3964D4B8FA21492F00D96D6B9', 89, 'Birdwatching with Nobel Price', 'Nobel Price takes Big Bird on an exciting birdwatching expedition where they observe various bird species and learn about their unique characteristics. Big Bird discovers that different birds have distinctly different features, calls, and behaviors. Nobel Price shares her expert ornithological knowledge with enthusiasm.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8B4B30E8976840BBA7E828F396AD26DD', X'A6EFE88301134477BF0657B42A3770EE', 11, 'The Dealership', 'At a car dealership, Kramer takes a test drive, while Jerry''s deal is threatened by a fight between Elaine and Puddy.', '1998-01-08', 22, '/4Jz1gvwrkqMGECh1Zqv1ROET1V.jpg', '2026-04-03T16:34:12Z', '2026-04-03T16:34:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
