INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8C48E82A5E144205A82FF36741F718CA', X'F5266C49EB294594B5D9F927EDFEE336', 14, 'Missing Piece', 'Shaun comes across a discarded jigsaw puzzle.', '2014-02-20', NULL, '/mfONRioAZIk0msAUEs1db2bwNRJ.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8C4E85EED1624F588FBC9E3BFC349AF2', X'DB555B9887D64CD2B7B4973F9206CB1E', 1, 'New Friend, New Flames', 'Shannon feels better than ever after shedding over 40 pounds and the baggage of her marriage. She immediately hits it off with Kelly’s new friend, Braunwyn, a mom of seven children. Gina starts the year dealing with the ramifications of a recent DUI, while Emily takes on the role of single mother when her husband Shane studies for the California BAR exam. Kelly settles down and is smitten with her new beau, a successful plastic surgeon. Tamra has moved into a new home in her dream neighborhood of Coto de Caza, but is troubled that her sons are not speaking.', '2019-08-06', 44, '/zUhYJIkybB682aUkhN9PPIlCLSi.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
