INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8C5C0F2E9CB84640AF4AAFB3A95131B4', X'6F731E6BD3C54DE684E17A19CB650E86', 9, '60''s Pawn', 'The swinging 60s have taken over as the Pawn Stars look back at some of their favorite items: an original Playboy Bunny outfit, a golf ball belonging to President Lyndon Johnson, two tasty coconut cups from the set of "Gilligan''s Island," some unused Beatles tickets, a possible fragment of the Apollo 11 heat shield, a Batphone, and a set of Jimi Hendrix prints that are working their voodoo on Rick.', '2015-11-19', 21, '/gBUfTnlBu1PxfsPshh5oDmyQym6.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
