INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8C6C0D5642E64FC1832CE5E6F426525D', X'3EE646E823AE4DECBBC6C7E6A210D55B', 70, 'Meet Benny Rabbit', 'Luis heads off from Maria and Gabi and promises to bring back a surprise. As the two practice saying the alphabet, they run into a scraggily, ornery rabbit, who tells them that the next letter is D. "Look, Gabi! A cute little bunny rabbit," says Maria.
