INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8C7A037E2E3542D2A880C9D28DFDDBBC', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 24, 'Business is Brewing', 'Business is brewing at the Gold & Silver Pawn Shop as Rick takes a look at a couple of antique beer items. With beer on his mind, Rick hops over to his friend''s brewery in San Diego to tap into the drink''s history. Also, the guys track down an original McCormick Farmall tractor, but how far will they dig into their pockets for it? And later, Corey must decide if he wants to take action on a "Django Unchained" signed movie slate, while Chum figures out if a print of "Dogs Playing Poker" is a King or a Joker.', '2017-07-31', 21, '/pXGJofU93lxfWzCBx87UtNTUOPz.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
