INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8C84C8ED9FD34384A9D3A1FFCCE922D1', X'6920E4B08F6C46F286E048CDEE5F6089', 2, 'The Rock Collector', 'An astronaut arrives on the planet.', '1971-04-25', 9, '/1JsvHro7qFxu62obcXm9x1OlEMV.jpg', '2026-04-03T17:23:53Z', '2026-04-03T17:23:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8C89AE6B35F0481EB4AF1992CFA8B9E1', X'ECB64EF34F8045A7B4A9C04434B02E35', 49, 'Spacing Out', 'Blast off with the Pawn Stars when a "Space 2005" wristwatch radio rockets into the shop. Will this device from the Space Race era be out of this world or will it crash and burn? Then, Rick tries to make a drive-by deal when he checks out a rare, 1964 VW Karmann Ghia. Can he steer the negotiation in his favor or will he be taken for a ride? And later, when Chumlee "accidentally" puts valuable coins into one of the shop''s slot machines, it''s up to the Old Man to hit the jackpot. Will he be able to cash in or will his and Chum''s luck run out?', '2014-06-19', 21, '/jfuuvcKMZ0s84Wg0UpOnsHRh3nb.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
