INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8CA82D2B0D224018B7FD46B67357A777', X'70C8CB4624944DD498F66BFB9B3FAF73', 27, 'Deals from Hell', 'The Pawn Stars meet a man hoping to sell a several hundred-year old edition of one of the world''s most hellish books - "Dante''s Inferno." Will they pass through the gates of hell for this evil epic or will they be tricked by the devil? Then Rick is presented with an antique serpent shaped sword from the Philippines. Can he hold on to the twisted steal weapon or will this deal slither out of his grip? And later Corey has a chance to purchase photo rights to the late great King of Pop: Michael Jackson. Can he make a "Thriller" of a deal or will he moonwalk straight out of the negotiation.', '2010-06-21', 21, '/mrc0ZJvVeab20Z3LvOK2djBHepV.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
