INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8CD2568B288D40B689FFB0B1379E10D8', X'F15647D3C8BF4E37A6BC589853787F3B', 6, 'Back to the Drawing Board', 'Nick and Todd, both talented artists, compete for a coveted spot and reward in a contest. Neither win, but both learn the meaning of good sportsmanship and fair competition.', '1989-07-09', 28, '/xIgJKNsPvlptIYjPeNeBCnITkBl.jpg', '2026-04-03T17:40:08Z', '2026-04-03T17:40:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8CD355F51A914305B4667B9A42F45067', X'5704FB3FFBBC417788B09226373A9D4E', 25, 'Episode 25', '', '1966-01-14', NULL, NULL, '2026-04-03T17:20:12Z', '2026-04-03T17:20:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8CD541D7E167404186A28397123C2F4B', X'3982796B54514100904246BEDF6A20A5', 1, 'Pingu at the Doctor''s', 'Mother goes out and leaves Pingu and Pinga at home. They decide to play dentist, but Pinga does not want to play when Pingu threatens to use a hammer and chisel on her. Pingu chases her, and during the chase a table gets knocked over by Pinga and Pingu bangs his beak on it. His beak is broken and bleeding. Pinga is sympathetic and bandages it up and takes Pingu to the doctor. Pingu is terrified when he sees the tool the doctor is going to use and runs off. Pinga and the doctor chase him round the outside of the igloo, but Pingu comes back inside and locks the doctor and Pinga out. Inside, all the other patients laugh at the whole fiasco. Pingu then rings Mother, who comes to the doctor and comforts him while his beak is being treated. While Pingu ends up with a brace on his beak, Pinga wants a lollipop, the doctor gives her one. Asking for the other one too, she kindly cleans the lollipop for Pingu and gives it to him. Mother then takes them both home.', '1991-11-03', 5, '/wNusoPejHXXrahcaONtSMoTYkLQ.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8CE762611B614D0CA1C1B3FE362B93FE', X'4861CE46904543C7963F27B4EA539804', 59, 'Episode 189', '', '1971-01-28', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8CF6B98A80934D5784F7DFF4C396BF3A', X'17E6CC8EDCF34CE697DB5A9FC8E31EB5', 8, 'Boots on the Ground', 'Porsha''s cowboy-themed birthday bash comes to an end; although Drew''s arrival didn''t dampen the birthday girl''s parade, a message received from Atlanta did; Angela overhears a conversation among women she thought were her friends.', '2025-04-27', 42, '/nTY1qQqwGZfLf1xSx6D6nlQJcvi.jpg', '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8CFCBAE5FB064485BA23ADF0D2F4404C', X'68138DE20900460AB58E480688F1E081', 2, 'Raiders of the Lost Cheese', 'Bear opens the door and greets the viewers, saying he was wondering when we were going to get here. He invites us to come in the Big Blue House. He starts to say that he was on the way to the kitchen, but then stops and sniffs, asking if we were just outside in the backyard, because we smell "all fresh and grassy." He suggests that maybe it''s just that we smell this good all the time and then heads into the kitchen, where he has something he wants to show us. It turns out to be a microscope...
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8D00969B987A4007A6B3D24B7ED538DD', X'1D713CA64E174F84949C8CFD98514127', 2, 'Fireworks and Freedom', 'Send out an SOS with the Pawn Stars when a WWII Morse Code reader clicks into the shop. Will Rick crack the code to capture this rare item or will he send out all the wrong signals? Then, a customer brings in a letter written by Secretary of State John Quincy Adams, who would later become president. Can Rick lead a successful campaign to capture this letter or will he concede the race? And later, when Corey insists on taking over Rick''s annual 4th of July barbecue for the shop, will he provide a new spark for an old classic or will his ideas fizzle?', '2014-07-10', 21, '/geFpryzKbMJfeStk2SYsxhO3sON.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
