INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8D1841BA6F6B4AB4AED112F5AD6C5FCD', X'15B8DCAE871D41CAA88EBEB4EC6530F7', 2, 'In Kyra''s Pocket / Sandbox / Yee Ping''s Appendix', '', '2001-04-11', NULL, NULL, '2026-04-03T17:11:22Z', '2026-04-03T17:11:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8D1EC93FEC09451C8EEF5BD3EE6407ED', X'0E4196154C964DDE8ED2715770BA77BB', 14, 'Appreciation Day', 'It''s an ordinary day at the Big Blue House, but Bear decides to check his calendar, wondering if there''s anything special coming. He checks his calendar and finds that tomorrow is Teacher Appreciation Day. Wondering if Tutter and the other mice at Mouse School know, he decides to tell them before soccer practice. It turns out when he arrives that the mice were just in the middle of talking about how much they like Miss Maxwell. Bear decides to split them all into teams of two, and partners Tutter with Lily to make Miss Maxwell a gift. Tutter''s not too sure about the arrangment at first, worrying that the shy and quiet Lily won''t be very good at helping him to make Miss Maxwell a gift. Bear, however, persuades Tutter to give Lily a chance and things start coming together nicely. They write a poem for Miss Maxwell. There''s another special appreciation surprise later on. In the Shadow segment, Shadow retells Aesop''s Fable ''The Lion and the Mouse''.', '2003-10-27', 25, '/c3JIOEeD16wGzQHkMNi0HCmH6Tk.jpg', '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
