INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8D6B709E830E4E84B7B4FAF0B1A3E968', X'ABFE14EEDB424DDEA96A601FF3C53ECC', 5, 'Cluny''s Clowns', 'A traveling circus comes to Redwall and Cluny uses it to try in infiltrate the abbey with his lieutenants, dressed as clowns. The mysterious circus star, Wild Ivy the Knifethrower, seemingly mesmerizes Matthias. But she is, in fact, an ally. As Cornflower is threatened with death by Cluny, Ivy turns her circus against the rats in an acrobatic battle of fire-eaters versus fur! And Wild Ivy has seen - that Matthias and Cornflower are destined to be together - if Redwall survives.', '1999-09-18', NULL, '/xyZEEqKvFvCTWkRcN69eLRETtkD.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
