INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8DCFACC15D5047AFACF4FE456A050D8F', X'1C9EA7D3E2544E7B8A9F33EEA9C6C341', 4, 'Love, Marriage, and Sour Peaches', 'On top of the float for WorldPride, Cynthia and NeNe come face to face for the first time since their fallout. Porsha confronts the reality that Dennis was unfaithful. Kenya is forced to acknowledge the growing divide in her long-distance marriage.', '2019-11-24', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
