INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8DD9967AD55F4A04AC5B3326212B83E2', X'05C0E384194C44179F62803EB615E409', 90, 'Presents', 'Mister Rogers brings signs to talk about. After Betty Aberlin visits to bring a gift from King Friday and Sara Saturday, she goes back to Make-Believe to hear King Friday''s announcement that everyone will get a big surprise next week.', '1968-06-21', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8DDE65BBA37D4980A93216B3E42A8D76', X'A3A2C2FB8276412C9D865175167BE1D7', 14, 'Episode 14', 'with Valerie Singleton, John Noakes, Peter Purves', '1971-10-28', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8DDFF5614D32443D9F42715FD08DBE35', X'FA6F43F4B9444C33AC69DDDBF54C0C16', 2, 'The Nightingale', 'Cathay, a kingdom with harmony and peace. A simple kitchen maid, whose mother is very sick, learns of magical faeries and a root that can cure even the worst disease. She also comes across a beautiful bird, the nightingale, that she soon falls in love with its song.  The emperor, is unpleased to learn that his great and vast palace does not completly please the poets, rather a simple bird, the nightingale, does. His royal court gets the bird, with the help of the kitchen maid, and the emperor is very pleased. After a while, an artificial bird is given to the emperor as a gift. He banishes the other the nightingale. But when the artificial bird breaks, he suddenly becomes deathly ill. It''s up to the nightingale to save him, but will she after he banished her? Mick Jagger portrays the emperor very well, Barbara Hershey is superb as the kitchen maid, and Edward James Olomos is great as the prime minister. The Nightingale has a great message and great fun!', '1983-05-10', 51, '/1yx6LkljpgttBCloLyDeZi8taYW.jpg', '2026-04-03T17:38:40Z', '2026-04-03T17:38:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8DEFD152D62248DCB77E5FA7A55AC942', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 1, 'The Seinfeld Story', 'While doing his stand up act, Jerry takes questions from the crowd. One of the questions is "where did the series come from?" An often asked question, Jerry responds by showing a videotape he''s prepared.', '2004-11-25', 22, '/1MTwKm5Jr3FbJtNmvMS7waqmXXh.jpg', '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8DF1F482241B430AB830D28B39AF1237', X'EBC99729CCB74D6482C142708CD7BA85', 25, 'Episode 25', 'Last year nine million Blue Peter viewers raised nearly £4 million to help the starving people of Cambodia. Today you can discover more details about the 1980 Appeal. Your help is urgently needed, so have a paper and pencil handy to take down the Appeal address. There''s good news for pocket money savers too, because Sarah will be showing a Christmas present to make for Grannies and Grandads - so keep a look out for old margarine carton lids - and all will be revealed!', '1980-12-01', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8DF2D289C15E4AC2B8DD61D2FB2EBA2E', X'227B84290DFD47E4B874C37DA20C403F', 15, 'Fired Up', 'The Pawn Stars want to buy an airplane propeller that may be historically tied to Charles Lindbergh - can they find an expert or documentation to confirm the link or will this deal crash and burn? Then when a man brings in a 1750s Flintlock Musketoon, Rick has doubts about its authenticity. And later a young man brings the Old Man a key chain that he believes belonged to Willie Nelson - the only question is - which one.', '2009-11-30', 21, '/s3Xh6aQ3GvGQrbTA8i4Gba7U4UY.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8DF61953BC514BFF84B1173EE72B6E78', X'42E591E22A884434AE9F3D4B1D685613', 14, 'Rage Against that Machine', 'Aim, fire, twist and repeat as the Pawn Stars check out a pair of rifles with double rotating barrels. Designed to give 19th century hunters a 2nd chance, will Rick fire up a quick offer? Then, Corey and Chumlee check out a pair of cleats worn by Yankees legend Bucky Dent during his famous home run. Can they knock this deal out of the park? And later, when Chumlee breaks the coffee machine, the Old Man sends him on a quest for the perfect cup of joe.', '2013-07-18', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8DF9214F73914488B52CCDEFAB70DB7B', X'9AE29D087CE847F985842D3E861067A8', 10, 'Fly', 'Walt becomes obsessed with a contaminant in the lab and refuses to finish the cook until it is eliminated. A frustrated Jesse attempts to get Walt back on track.', '2010-05-23', 48, '/3ns0vN3bEl7elFWoodHJ9nDBogC.jpg', '2026-04-03T15:40:33Z', '2026-04-03T15:40:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
