INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8E65CEA346D7471995DF1CCA475F2CC3', X'DB555B9887D64CD2B7B4973F9206CB1E', 9, 'Miracle at Miraval', 'The Miraval trip continues as Vicki unleashes another rumor about Kelly, leading Kelly to explode at the Tres Amigas. Everyone goes beekeeping, except Kelly, who stays behind. At beekeeping, Shannon flirts with the beekeeper. After, Emily and Gina hash through their issues. At dinner, an emotional discussion leads to an unlikely apology. And the ladies have some late-night fun in the hot tub, where Brauwnyn reveals how she celebrates Sean’s “monumental” birthdays.', '2019-10-01', 44, '/pCHzaROceDk2v5CbzJfMmpJmkr.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
