INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8F60FDCEB70C4BB0AE917A9FFE5B5963', X'A4843A51AEEF427C902C7FB3BD670CD4', 18, 'Working Like a Bear', 'It''s time for Bear to go to work, and a bear''s work is berry-picking. He invites the viewers to join him as he locates his berry-picking bucket and hunts for berries to fill it, including strawberries, boysenberries, blueberries, blackberries and huckleberries. Before he finds his bucket, he finds Ojo and Treelo playing in the living room. Their game has come to a halt, as Ojo is tired of Treelo pretending to be a baby. Bear helps her to find something new to play and shows her how Treelo can still be the baby in the new game. Bear learns about Tutter''s work, which includes cleaning up his mousehole and shopping for cheese. Shadow sings the song "I''ve Been Working on the Railroad" and gives Bear a tip as to where to find his berry-picking bucket. Later, after Bear finishes his work, Bear talks with Pip and Pop and helps them to see that they too did work today.', '1997-11-13', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
