INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'8FFD46B37F6F4D4A9E2DFFAA0C342303', X'101549F46ED145FAB543D08723F65306', 2, 'Ruthie Dances', '', '1993-11-23', NULL, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90004CCFFA114C74A9AE9FBF84EA64AC', X'C21DBD225E2E4414BB67750399AAF6F0', 29, 'Pawn with the Wind', 'The Pawn Stars see dollar signs when a $1 bill signed by Clark Gable comes into the shop. Allegedly signed while he served in WWII, will the guys try to cash in on this rare bill, or is it not worth the paper it''s printed on? Then, Corey and Chumlee are presented with a rare 1800s Wells Fargo double barrel shotgun. Made to protect stage coaches in the Old West, will the guys bravely ride shotgun on this deal, or will a misfire cause them to surrender? And later, a souvenir from Ulysses S. Grant''s funeral makes its way into Rick''s hands. Will he see this tribute as a vital piece of presidential memorabilia, or will this keepsake be dead on arrival?', '2012-03-05', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
