INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'900303F12E4E4548B137D93070033AB4', X'DBD3583FE9B246D1A37E309EB666E233', 6, 'Three Wigs and a Baby', 'Kim doesn’t make it to her due date and gives birth to her first baby boy. Meanwhile, Cynthia and NeNe take a business trip to New York City, where Cynthia gets advice on her new modeling school from old flame, Russell Simmons, and reveals to her best friend Kithe that she’s not altogether happy with her life in Atlanta. NeNe meets with her business partner, Famous Famiglia Pizza''s co-owner, John Kolaj, who seems interested in having much more than a business relationship with her. Shereé’s mother makes a revelation which gives Shereé the resolve to take Bob to court for child support. Kandi gets Mama Joyce dolled up for an online dating profile photo shoot. Phaedra demonstrates her talents as a lawyer by getting her client out of hot water for drug charges.', '2011-12-11', 43, '/6hmgM8OdV1myXwGWpS3NnVRVRYy.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
