INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9034489AEA2A4B00BF4BBA534E478F7C', X'0EBBA123871D4D2BA054EB85D2AD9450', 48, 'Celery Night Fever', 'A determined young girl sets out to save the city park from being turned into a parking lot by getting her grandfather (Larry the Cucumber) to stage a reunion concert with the Disco Band he headlined forty years ago. The problem? None of those guys are talking to each other, all of them holding grudges for how the band fell apart all those years ago... Its theme is forgiveness.', '2014-08-05', 30, '/vQPWOB3GcPwzCnqZ3bD9F3CLsxQ.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
