INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'903DFF7691174563A3DD37AE80F32E5A', X'CA3F764EB3304980BD7A2908A73B77B6', 11, 'Tempest in a Tea Party', 'Lisa''s elegant tea party is the unexpected setting for a heated confrontation and Taylor reveals her true feelings toward Lisa and the women finally discuss with Taylor the real issues behind her troubled marriage.', '2011-11-14', 43, '/nSrvEwxbbivzTMwKgHLIyYPS7A4.jpg', '2026-04-03T16:34:54Z', '2026-04-03T16:34:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9042625445474502906FFF76EA79842A', X'34674C90410E427CBE4D2A6F6F865A80', 8, 'What the Truck', 'Go off-road with the Pawn Stars when they''re presented with a 1960''s Mercedes Unimog. A German military vehicle built to go just about anywhere, will the guys cross rocky terrain for this rare truck or will they tell the seller to hit the trail? Then, a guy marches in with a sign that hung on the Berlin Wall. Will Corey and Rick make a deal or will the item divide them? And later, a collection of 1980''s Garbage Pail Kids trading cards has Chumlee reliving his childhood. Can he convince Rick that these are worth picking up, or do they belong in the trash?', '2012-05-21', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9043579DC62A4370B2A86CD222DBB40D', X'27A5A980EC0D4637B5BADF8324A6405A', 12, 'Year of the Hecks', 'After realizing that no one keeps their New Year''s resolutions, Frankie decides that they will be assigned anonymously to each family member, and an all-you-can-eat buffet feast will be the reward for those who can abide by their chosen resolution for a week. But chaos soon ensues when Frankie must spend more time with Brick, Mike needs to smile more, Axl has to keep his bedroom clean, Sue needs to stop trying out for things she''ll never make, and Brick must stop reading all of the time.', '2012-01-04', 22, '/pAAuRGlJBMPLKvV6epTZS5VGZ63.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
