INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'905457E795214932A3EECCA2553DF627', X'9193E795DA7C40ECB68FF63AA7D5174F', 87, 'Histories & Lore: House Tyrell', 'Margaery Tyrell details House Tyrell''s history serving under House Gardener before the War of Conquest and House Targaryen afterwards, before surrendering to Robert Baratheon after he defeated the Targaryen dynasty.', '2013-02-19', 4, '/3XQ4iCTYNG2B2ru2K7FcWN7nU5K.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
