INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90621BCFB7B8461FAAA75E03555C9124', X'5C4E51C6E20746AD875C72988EB1E13E', 32, 'Pirate''s Booty', 'The Pawn Stars find themselves sailing on strange tides when a street-legal pirate ship parade float cruises their way. Will Rick surrender some booty for this one of a kind vehicle, or will a tough negotiation have him walking the plank? Then, a woman drops in with a World War II bomber jacket and flight mission logs. After surviving 29 missions, including D-Day, will these items continue to fly high and enjoy a hero''s welcome, or will heavy flak force the seller to retreat? And later, Rick and the Old Man are presented with an antique carriage strong box. Used to protect travelers from thieves in the 18th century, will the guys lock up a solid deal for this rare piece, or will it be a highway robbery?', '2011-09-12', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
