INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'908491D7FAD3466A93CCE474BA9CC140', X'E6359E6D9BDB4ABA9CBA6F7DDD6328F9', 17, 'Better Latex Than Never', 'As the Berlin trip concludes, one of the ladies can’t seem to be on time to any of the scheduled events; surprisingly, it’s not Dorit. "Pretend amnesia” rears its ugly head again, and Erika is surprised to hear how Teddi truly feels about her. Kyle’s still upset with Dorit but chooses to ignore her own feelings for the sake of the trip. Dorit stresses over final preparations for her fashion show—and fears she won’t be able to pull off her big comeback.', '2018-04-10', 43, NULL, '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90862307D0C54072BA2C9D1482891F25', X'6B5CAA66F66F4ED1817FA00BAD08790E', 2, 'Mamas Knows Best', 'Danielle tries to warm to Dina but the women find themselves at a loss in each other''s company, Jacqueline worries her daughter isn''t getting good enough results at school while Teresa and daughter Gia receive good news about an audition. Meanwhile, Caroline''s daughter concedes that she''s ready to do her beauty course.', '2009-05-19', 43, '/yIH7JkcFwGV60SY9O3wN6Q05wFI.jpg', '2026-04-03T16:35:14Z', '2026-04-03T16:35:14Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90868A5CE4C04B52B3211D0E11099A1C', X'C1DF0E9BE03E48E5A93061EE5EF85840', 2, 'Double Dare', 'Arthur, Francine, and The Brain dare each other to skip school for a day', '2000-09-04', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9088806EBE9D43DE978A02BC137417C9', X'70D9E39768134785887D27D034928BAE', 16, 'Pingu and the Toy', 'Pingu meets Pingo, who is playing with his new clockwork car. Pingo winds up the car and sets it going. The car runs into a block and Pingu goes to rescue it, but Pingo won’t let him touch it. Pingo winds the car up and again sets it going, chuckling away as it goes round and round. Pingu, who wants to have a go himself, sticks out his foot as the car comes past him so that the car hits it and crashes. Pingu then goes off, leaving a somewhat annoyed Pingo. Pingo sets his car going again, but the car only goes a short distance and then breaks apart. Meanwhile, Pingu has hurried home and found his piggy bank, but all that’s in it is a button. He sadly goes out and walks away. He goes past Grandfather, who asks him why he’s so sad. Pingu explains, and Grandfather takes him to the stall that’s selling the cars and buys him one. Just after they’ve gone Mother goes past the stall and is also sold a car. Pingu goes off happily, and his way takes him past Pingo, who is looking sadly at his broken car. Pingu has a good laugh at Pingo’s bad luck, and then sets his own car going. When it stops Pingo wants a go but Pingu won’t let him. Pingu then starts his car again, but it stops almost immediately. Pingu gives it a good kick to get it going. It slides away and breaks, much like Pingo’s did, which greatly amuses Pingo and annoys Pingu. Pingu goes home, tossing the broken car away. When he arrives, Mother says she’s got a surprise for him, and brings out the toy car she’s bought. Pingu makes an shocked face, comes and takes it, and angrily tosses it into the trash bin, where it breaks apart in the same way as the others! He then goes and plays with his wooden bricks.', '1996-06-27', 5, '/2ky2sn191ANP3nfqYBtcBS02n9y.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'908D4093C5BA4963892847DBD914B029', X'95C86B7F162E4E74812E73CCA314F182', 1, 'The Lion, the Witch and the Wardrobe (1)', 'It''s 1940, and the Pevensie children, Peter, Susan, Edmund and Lucy, have been sent to stay in the countryside where they will be safe, away from the war. Their home for the duration is a huge rambling mansion that the children cannot resist but explore, during which Lucy stumbles across an old wardrobe which hides a magical secret.', '1988-11-13', 30, '/hLOml3BY6jqmX6sGUeocZu9qD41.jpg', '2026-04-03T17:17:41Z', '2026-04-03T17:17:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90955E1DF0854174885144C40E936BBF', X'5DADE172C4F34488A399B73F3ACA0DB5', 5, 'Chapter Five: Dig Dug', 'Nancy and Jonathan swap conspiracy theories with a new ally as Eleven searches for someone from her past. “Bob the Brain” tackles a difficult problem.', '2017-10-27', 58, '/westZSpDwRPjxG2eBWIT7utDcnL.jpg', '2026-04-03T15:40:39Z', '2026-04-03T15:40:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9096FA1D04AA4DDD965323FE5017B28D', X'5BA20443D99F482081F66832D3F2BC4F', 3, 'Marine Mammals', 'Whales, dolphins, otters, walruses, and orcas are just like us, they’re mammals. Well, they’re not just like us. They live in the ocean. They breathe air, have hair, nurse their babies, and they are warm-blooded. They keep the same body temperature all day. To do that in the ocean isn’t easy. Water soaks up heat, so the ocean is really pretty cold. Marine mammals have all sorts of ways to keep warm. Whales, dolphins, and walruses have thick layers of fat called “blubber.” It’s great insulation. It holds their body heat keeping them warm in the cold ocean. Sea otters have thick layers of fur that cover their whole bodies. Otters fluff their fur to trap air between the hairs. It helps them float, it the air keeps them warm even when they dive deep hunting for food. These adaptations make it possible for marine mammals to live all over the world’s oceans.', '1995-11-17', 26, '/aMoChXtuDwZy61WXveJ3pHm6pHm.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90977F58BF904864BAF4F7B4772919EC', X'BB919AEC0D5C4C589A5AFA2A0A5DE2B6', 46, 'Episode 451', '', '1973-01-29', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90A0EA5137EE4209B07E906968AE11CE', X'D1D267DDE27F4543ACB80D28F676512A', 59, 'Episode 59', 'with Valerie Singleton, John Noakes, Peter Purves.  Valerie Singleton has taken a lioness for a walk through a busy street, been flown into the Borneo jungle by helicopter, and was the first white woman the Ibans had ever seen, and nearer home, she''s learned to ice skate - all in the ''Blue Peter'' cause.  This week Val undertakes a new venture - learning to show-jump. She does ride as a hobby, and in fact she was seen on horseback last year in the film of the Blue Peter team in Jamaica.  Val''s instructor in today''s programme is Alan Oliver, one of Britain''s leading show-jumpers, who has been carrying off awards since the early 1950s. She''s certainly in good hands.', '1968-03-28', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
