INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90B7A3A1C2394B2DA0F053AB6B5FC624', X'1BE79A20DE3341D1AF17079035B18D5C', 123, 'Big Bird Draws Letter R''s (0123)', 'Here comes Cookie Monster!  A prank on Bert backfires on Cookie and Ernie.  Cookie''s call to his mommy ends when he eats the telephone.  Song "One of These Things" and animated ABC song.', '1970-04-29', NULL, '/kP0anmIuYv9Bw7TmRz4VUsuiFhG.jpg', '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90B7ED4CA2DC430991BA29F84CF8F7B9', X'98D80972E53A43DDA03A7703465E6F87', 11, 'Putt, Putt, Pawn', 'The Pawn Stars start a cola war when a 1950''s Pepsi Machine pops into the shop. An incredibly rare unit painted "Coke red" instead of "Pepsi blue," is this mysterious machine worth big bucks, or will the deal go flat? Then, a guy brings a copy of John Milton''s "Paradise Lost." The first edition with engraved illustrations by Gustave Dor - has Rick found the holy grail of literature? And later, the guys challenge each other to a high stakes game of mini-golf. With the loser having to wash everyone else''s car, how far will they go to win?', '2012-12-03', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90C0BABDB9924F738C3761EE0EC31737', X'21384B9C43FA410CB89D102E7CF9129B', 5, 'Christmas Surprise', 'The Browns celebrate Christmas a week later to give everyone time to move into the new houses. Kody challenges his wives to a contest. Robyn has a special gift for Kody.', '2013-08-18', NULL, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90C4D984F40F481DB4057B4B6C0A52DC', X'84CE360A90D14FC0BE0633BDCBE8E60A', 11, 'Jake''s Friend', 'Jake has an imaginary friend called Wilbur.', '1999-12-02', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
