INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90C66DE14A32482B800375ED474BF220', X'8730C55E844344B0AFEFA369C478B14F', 37, 'Five Little Ducks', '', NULL, NULL, NULL, '2026-04-03T15:26:09Z', '2026-04-03T15:26:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90CBEB28F23B4F4D810E14FE1C0CB1C8', X'97616D6E5C17449FA37655F1DA83D6C3', 6, 'Mister Rogers Talks About DISCIPLINE', 'Mister Rogers arrives with a blanket which he has just picked up from the cleaners. Unfolding the sofa bed and using the blanket to cover it, Mister Rogers sits and talks about the feelings children have about blankets and teddy bears. He then sings Please Don''t Think It''s Funny and shows a film about how people make blankets.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90D2DEADAAEC4146B4CA9E92A5D93FDC', X'E291DF42D44F49E5BF812DF32EE4A30F', 2, 'Nothing To Fear', 'When Bear receives a package from "L.L. Bear" in the mail, he''s surprised to find that he received a skunk clock rather than the bear clock he order. Rather than returning it, he decides to give it a try and hangs it up in the kitchen. He hears Ojo and Treelo outside and finds Treelo swinging on a swing. He gets off and asks Ojo to try, but finds that she doesn''t want to. She admits to being somewhat scared, but finds a compromise in starting out by first taking small swings. As Bear heads off into the living room for a nap, Tutter is disturbed by the "tick-tock" of the skunk clock, mistaking it for a real skunk. He''s scared by it, but eventually comes to realize that it''s actually alive and is nothing to be afraid of. Out at the Otter Pond, Pip and Pop play a game called "Double D Dare." When their daring starts to get dangerous, Bear suggests that they think of things to do that are silly, but not potentially dangerous. Sometimes, if you''re scared to do something, there may be a very good reason for it. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90D66BD9A2EC45A9BC03F3AC02E1D3BE', X'4D2CAC0F38FD438B8AFAACF43952E535', 51, 'Episode 51', 'Introduced by Christopher Trace and Leila Williams.  Including: Brigade of Guards: 5 and Dressing a Doll with Peggy Franks.', '1959-10-09', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90D8B342D9C8429E88DE54EF7F0C9DC8', X'AD180412A5D64E4A8B49590334F2FC69', 8, 'Scared Silly By Snakes', 'The two snakes find their way to Bully''s nest after speaking to a rat with a feeling of impending doom. However Bully manages to escape leaving Adder and Sinuous frantically racing through tunnels with overwhelming numbers of rats looking for a way out. Adder reaches the surface but Sinuous turns the wrong way and ends up trapped underground.   Toad tells Fox about the dwindling Frog numbers due to the rats eating them and Fox agrees to get the foxes to stand guard around the pond.   Whistler informs Plucky about the events happening in White Deer Park and how they need his help to fight the rats. When the gates to the new reserve open to let out a van Plucky takes his chance to escape and jumps into the back of the van. However it goes the wrong way, but it is forced to stop when sheep block its path. Plucky jumps out and races back to White Deer Park.   Meanwhile Owl is devastated when Hollow tells her about the pretty young owl he intends to become his mate once mature. Owl refuses', '1995-11-16', 25, '/sS0vebJ5JW5yXjzSB4osoULQ0GW.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
