INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90ED9DA6E51B49BCA310B0E75FA76121', X'4D2CAC0F38FD438B8AFAACF43952E535', 240, 'Episode 240', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. Including: Petra''s Training Class, Blue Peter cameras show Petra at work at her training club and Pet Pin-ups, Giving you another chance to win a badge.', '1963-07-22', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
