INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90FCB56D7EB1459CB225076DA3FECD5C', X'8012F05A66A34254885F0A679393F3DD', 6, 'Four Days of the Cockatoo (2)', 'Gaby finds a name tag on the bird and learns that its a palm cockatoo, and they nickname the bird Calypso. Casey still can''t understand why she can''t go home to her mother. Gaby decides to make some flyers for Calypso''s real owner. Hawke finds one of them and makes a phony call pretending to be the bird''s real owner. Just then Calvin arrives at Lenni''s house and informs the team that palm cockatoos aren''t permitted in the usa. The team realizes that Gaby is giving the bird to a smuggler,so they leave hoping to warn Gaby before it''s too late.', '1994-11-06', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90FD39E0D34C49D0ADC4B91BC5046B71', X'C4717644555D4DF1AEC0C095B101E7C0', 3, 'Summer', 'In this episode of Reading Rainbow, LeVar shows the kids the different sights and sounds of Summer. The different wildlife of Summer, and how they live. Also, there are segments on the different seasons and how they effect different parts of the country. The featured book is "Summers" written by Ron Hirschi, and read by Ossie Davis.', '1994-10-05', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'90FF3DA9F6CE4ED89163980C6AE93D52', X'D405F9734C7E4CB6B7C0D09A884C9B35', 5, 'Following Pecking Orders', 'Jill returns from Australia a new woman---or so she says. Her newfound sense of purpose to avoid gossip quickly ends when she dishes about Ramona during lunch with Kelly, LuAnn and Sonja. In addition, Sonja details the group''s "pecking order" dynamic; Cindy and Ramona meet for drinks, but tension spills over.', '2011-05-05', 42, '/1dZa7D3gjksigCwhDdVIL6JZbyK.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
