INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9136FC3286C840BB8D49EEAD1BCD1B3B', X'C21DBD225E2E4414BB67750399AAF6F0', 10, 'Apocalypse Wow', 'The end is near for the Pawn Stars when they check out an alleged original print by Renaissance artist Albrecht Durer. Known for his depictions of the apocalypse, will the guys battle demons to capture this valuable work, or is this demonic image more than they bargained for? Then, Corey feels like a third wheel when he checks out two trike-style motorcycles in the same day. Both equipped with V8 engines, will Corey be overpowered by these tricked out machines, or will a tough negotiation "tri" has patience? And later, a guy comes in with a statue of 80''s advertising icon Spuds McKenzie. Will Rick and Chumlee try to tame this party animal, or has this dog already had his day?', '2011-12-26', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
