INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9139B75F1A03407E8A1B076D81B3E36D', X'CC140989C4804586B4608872B416A0B7', 6, 'Dive to the Coral Reefs', 'Within the sea, lies a combination of scuba diving and (just slightly) snorkeling as LeVar and a friend of his dive beneath the ocean to explore a living coral reef and the life around it. Fran Brill narrates Dive to the Coral Reefs, a book that shows the life and structures of the beauty that lies beneath the sea.', '1990-03-26', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
