INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9160525DE9224A7BB3B7002A157249C7', X'F812042DEB85432E80473675886E0B1B', 19, 'One Thousand and One Tails', 'While greed threatens to grip the humans around him, Wishbone imagines himself as Ali Baba among forty thieves.  The sheer power of 1001 Arabian Nights seems overwhelming.', '1995-11-02', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9163083169F94C0FBB1582062D185C28', X'DB555B9887D64CD2B7B4973F9206CB1E', 12, 'Fashion Show Faux Pas', 'Braunwyn’s daughter Rowan makes her debut at OC Fashion Week with her clothing line Dark Rabbit. Shannon takes on the role of momager as she coaches daughter Adeline on how to walk a runway. Rowan and Adeline triumph, while Braunwyn and Kelly back each other up in an argument about Dr. Deb. Meanwhile, Gina gets a new look as she grapples with whether to reconcile with her ex or move forward with a new relationship. Eddie learns about Tamra and Braunwyn’s time in Del Mar. Emily and Braunwyn bond over a discussion about the father figures in their lives. Tamra’s son Ryan has a tattoo removed and agrees to go to therapy.', '2019-10-22', 44, '/4mSGVkOXB9hIz7grF9Hf0PzMWLt.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
