INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'91B15C814B3E48B78E6AC24B571F3695', X'4FE93658C46343298E649D523869C2CB', 21, 'Darth Pawn', 'Make sweet music with the Pawn Stars as they check out a 1763 Stradivarius violin. Found in an attic, could this violin play a tune worth a million bucks or will this deal hit a sour note? Then, Rick and Chumlee meet a man selling life-sized Star Wars figures. Will Rick use the force and buy these rare pieces of galactic memorabilia or will this deal end up in a galaxy far far away? And later, Rick and the Old Man check out the World War II airplane''s version of GPS, an octant. Can they successfully navigate their way to a deal or will they hit turbulence?', '2011-01-31', 21, '/8FzaQS5L6xSoeQOaoeDd3zOQXxj.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
