INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'91BADD202DCD44F687BF5F8FE28400D4', X'4892E2AF46C14B4EAC81EAC161B5A347', 1, 'Episode 1', 'Expedition Brazil  Rio de Janeiro is one of South America''s most exciting cities. In today''s film report John, Peter and Lesley climb two of its famous mountains, Sugar Loaf and Coreovado. and join the kite fliers on Copacabana beach.  In the studio - a stunning display by the US Army Drill Team.', '1977-09-12', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
