INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'91CE2D7DBAC9457EA92176B91186756A', X'1A534647384B4C00BB6CA3371AD962EB', 22, 'Hot Wheel of Fortune', 'Go surfin'' with the Pawn Stars when the world''s rarest Hot Wheels car, the Beach Bomb #1, rolls into the shop. Will Rick get supercharged to make a deal or will he get dumped? Then, Rick gets creative when checking out an etching by Rembrandt. Will this work of art be priceless, or not worth the paper it''s printed on? And later, Chum decides to write his memoirs. Will his novel become a best seller or will he get writer''s block?', '2015-04-02', 21, '/4onBSa8rKHSuzB9KAOXwzvk8MNL.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
