INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'91EA7FEC7E184B01A8FB972A98BCCB90', X'C21DBD225E2E4414BB67750399AAF6F0', 2, 'Patriot Games', 'Hit the gridiron with the Pawn Stars when they check out a 2004 Super Bowl ring. A genuine player''s ring from the New England Patriots, will the guys rush for extra yardage for this ultimate piece of sports memorabilia, or will a tough negotiation leave them three and out? Then, a guy brings in a diary written by his ancestor during almost every major battle of the Civil War. With a handwriting style nearly impossible to decipher, will they be able to unlock the secrets of the past, or are these memories lost to history? And later, a poster from the movie Bullitt comes roaring into the shop. Signed by Steve McQueen, Robert Duvall, and Jacqueline Bisset, will Rick jump into the chase for this rare piece of movie history, or will some suspicious signatures leave him idling at the side of the road?', '2011-11-28', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
