INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'91FAE39E099D497C8934D08E70548565', X'5DB3FF78E43948E18F67988ECBF85D17', 22, 'The Jungle Adventure', 'Dogtanian and Pip are still stranded on the island. Pip is hungry so they walk inland to find some food, they find some fruit which Pip knocks from the top of a tree. Before Pip can tuck in they hear a strange noise and go to investigate. They find a "monster with a tail where its mouth should be", also known as an elephant stuck in the mud. They go in to rescue it, Dogtanian doing most of the work, but before it''s out a crocodile comes in. Pip tries to catapult a rock at the croc, but launches himself onto its back, Dogtanian tries to duel it but has to run and is caught in its mouth. The elephant uses his trunk to throw some trees on the croc and saves the day.', '1982-02-26', 24, '/7yGpIahRg2Rf35wk78YkzNMoc6y.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'91FAF7E931D7400BA5F1A983E9B0D5A6', X'6053B5C1CE86425C8166E0FCC3466061', 63, 'Episode 63', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-04-27', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'91FEAAAB540949E3A8E075807250CA0F', X'F1959B8419304F85B2FD9000B3ABF48A', 29, 'Episode 808', '', NULL, NULL, NULL, '2026-04-03T17:36:40Z', '2026-04-03T17:36:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9203E9E513A84E5A91A81559C7EB04FE', X'D5383B3D56364D71B99CB84774B4B3C6', 5, 'Pingu Shows What He Can Do', 'Pingu and Pinga are playing outside the igloo with the bricks, seeing how high they can get a pile without them falling over. Pingi arrives on her scooter, and, unseen by Pingu, watches them playing. Pingu and Pinga laugh when a particularly high pile collapses. Pingi laughs as well; Pingu hears and is surprised to see her. Pingu pretends that he wasn’t enjoying the game, and tries to act macho. Pingi asks Pingu if he’ll come with her, on his scooter. Pingu abandons Pinga, leaving her to play on her own, and goes off on his scooter with Pingi. As they ride away he pretends that he’s on a motorbike by making appropriate engine noises. Mother comes outside, sees Pingu and Pingi riding away, and then sees that Pinga is playing on her own, so she joins her. As Pingi goes on ahead, Pingu hides behind a nearby ice column, then calls out to her. Pingi returns, stops near the ice column and looks around. Pingu comes out from behind the column on his scooter and rushes off. Pinga turns and follows him. They reach some abandoned igloos. Pingi gets off her scooter and enters one. Pingu follows, and then kisses her hand. Pingi responds by giving Pingu a big kiss on the cheek. Pingu is delighted, and exuberantly performs all sorts of tricks on his scooter, to Pingi’s amusement. They then ride around the igloos a bit more before making their way back to Pingu’s home. When they arrive they find Mother building a tower of bricks for Pinga, which Pinga then blows down, and they all laugh.', '1998-01-09', 5, '/bTENHuJYMx19X9bVytd74O24qsN.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
