INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'92218684E2614447BFFE613B0B4A331D', X'A860511CB630415E99A1A9E0922FBFD7', 14, 'Buster''s Garden of Grief', 'Fritz asks Buster to take care of the community garden for him while he recovers from his ankle injury. Buster has to stop short when he finds out he''s going on a camping trip with his mother. So, he asks Muffy, Francine and Arthur to care for the garden for him.', '2012-05-24', 13, NULL, '2026-04-03T17:38:00Z', '2026-04-03T17:38:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9223C2A79A4E482592765A31B00B2A46', X'98D80972E53A43DDA03A7703465E6F87', 19, 'Funny Money', 'Get boxed in with the Pawn Stars as they check out an original work by Pablo Picasso. Will the guys shell out some green, or leave the seller feeling blue? Then, a guy moseys in with a saddle used by John Wayne in the movie "True Grit." Do Rick and Corey duke it out over this rare piece, or send the seller riding off into the sunset? And later, a scissor katar knife from the 1800 s slices into the shop. Can Chumlee talk the guys into cutting a deal?', '2013-01-21', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9231D3D05B6E41B5ACC08FE08FB884C1', X'F593D90C533942F59C885BFD48D04075', 24, 'Bitzer''s Basic Training', 'Bitzer thinks The Farmer is planning to replace him, so Shaun helps to knock his friend into shape. Unfortunately Bitzer goes completely over the top with his training regime and starts running the farm with military precision driving everyone crazy.', '2010-05-16', NULL, '/6mIRZpFmlbTdGGWPhniYnfGd3zC.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
