INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9241D98333E3491E96470A991A645985', X'DA06465B91544FEBA455374DF7DAB02F', 5, 'As the Porridge Cooled (4087)', 'Telly is doing a “Monster on the Spot” report about Baby Bear, who is telling the story of what really happened to the three bears as their porridge cooled.  Instead of walking, they were very active as they ran and jumped through the woods.  Suddenly, they find they’re lost in the magic garden of a wizard who put a spell on them and turned them into ducks.  Baby Bear, using fun science words, tests his hypothesis that the type of animal they turn into depends on the kind of animal sound they make.  Through his experiment, he finds out that his guess is correct!  They all make bear sounds and transform into bears again.  The wizard wouldn’t let them out of the garden until they name three things about vegetables.  With the help of the Singing Vegetables singing, “We Are the Vegetables,” the three bears figure out that vegetables are delicious, are good for you…and are musical!', '2005-04-08', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
