INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'92745AC283ED4090B2EB2F58EB19C17A', X'C01DDD2ABDB14C978D0458F791EF1C24', 27, 'Fast and Slow', 'Between the cheetah and the snail, the Kratts find a great deal about the speed of animals.  Then there is the chameleon, which varies speed a good deal.', '1999-06-28', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'927556C2B6AA43EE9417F689D7095257', X'C21DBD225E2E4414BB67750399AAF6F0', 7, '$=MC2', 'The Pawn Stars try to stay focused when a limited edition photograph of Albert Einstein comes in the shop. An iconic image from the cover of Time Magazine, if the price goes up, it must come down. Then, Rick and Corey are presented with a collection of confidential documents from the Pentagon. Possibly found at a yard sale, will Rick seal the deal on these Vietnam-era reports or will this classified treasure get him into hot water? And later, the Old Man takes the day off to tour a World War II era B-17 Bomber. With Chumlee along as his driver, will these two have the guts to fly in this 65-year-old Flying Fortress, or will they chicken out and keep their feet on the ground?', '2011-12-19', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
