INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'929B451A3D454C4C8CD60347FA30B529', X'C01DDD2ABDB14C978D0458F791EF1C24', 2, 'Eye Spy', 'After admiring the camouflaged coats and amazing night vision of two visiting black jaguar cubs, Martin and Chris build a pair of  "Eye-Spy goggles", a contraption that lets them see the world as various animals do. Jackie replants the evergreen that was her Christmas tree and decorates it with apples and popcorn for the birds.', '1999-01-26', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'929D7969D0934173B0F44266E4B76514', X'61E0C9D9337E4FE4A0FDE567B29AF115', 3, 'Basketball, Bobbleheads and the Brow Girl', 'Whitney takes the women on a girl''s trip to Milwaukee, but things heat up when Bronwyn confronts Lisa for not defending her at the ropes course. Meredith reveals an unsavory rumor about Whitney''s jewelry line to Heather. Angie discovers something shocking about Britani''s on-again boyfriend, leaving her to break the news to Britani. The women enjoy a VIP experience at a basketball game where Meili confronts Lisa.', '2024-10-02', 43, '/mjGtairpaG2bZjapUXjCSTlaHZr.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
