INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9353D3C881B140D1A0C62C03C0446E88', X'38BF8C20C17C407192267887787CF1B1', 13, 'Five, Six, and Thistle Sticks', 'Lionel''s friend, Lenny - a fellow ""Cliffhanger"" aficianado - comes for a visit, after having since moved away. When he arrives at the library, however, Lionel finds out that Lenny doesn''t like ""Cliffhanger"" anymore. That instead, he has taken a liking to a similar book hero, ""Justin Time""! Can Lionel and Lenny still be friends, even if they don''t like the same things?', '2001-04-18', 30, NULL, '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
