INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'936366B6B5224A0D8F0E0768B45FBB4D', X'4C79C0B621A442778967BE1E791EFDBE', 1, 'Pingu''s Sledge Academy', 'Pingu and his friends Pingo, Pingg and Pongi are out having fun on their sledges, but they’re so boisterous that they’re a menace to everyone else, leaving chaos behind them wherever they go. They go first to a patrolling Sledge Academy students, then to a stall. The Instructor gave Father a vestment. Pingu and his three friends then pass by to an poor lady, from Pingu Wins First Prize, then to a man with the newspaper, and his hat and paper flew. Then they pass by on Pingi, to two igloos and a vegetable stall, and eventually they crash into a fish stall. When Pingu gets home, he’s told by his parents that they’re not happy with his behaviour on the sledge and threaten to take it away from him unless he goes to the Sledge Academy. He and his three friends attend a course and, after a few mishaps, learn to control their sledging. They complete the course successfully and are awarded diplomas.', '2005-01-03', 5, '/hP8neUJGAQ2ecrpJ1qtll5guSO1.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'936584A61B554C85B6D8398141D33A72', X'F30BBF8187704E74B68B280E7C85B52F', 8, 'The Heart Attack', 'George thinks he''s had a heart attack. The doctor tells him otherwise, but he might want to get his tonsils and adenoids removed. Elaine is interested in the doctor and he is interested in her tongue. George not wanting to deal with the cost, follows Kramer''s suggestion of going to a holistic healer. The healer''s cure turns George purple and the ride to the hospital is delayed over a Chuckle.', '1991-04-25', 23, '/qcx6ufKDH0PYQ13T4rHDSCakyw3.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
