INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'93770D4F3F624A71A5F02172D5F18D74', X'1A534647384B4C00BB6CA3371AD962EB', 29, 'Fake or Fortune', 'Test your judgement and revisit the best fakes and surprising fortunes ever to appear on Pawn Stars: a two million dollar painting by Claude Monet, a 1715 gold coin from a sunken ship, a set of rare autographed Hollywood Postcards from the 1950s, a bejeweled Black Widow Brooch and a collection of signed Beatles Memorabilia. Real or fake, these items could mean big bucks or a big bust for the shop.', '2015-05-21', 21, '/z5L59DYU7UvHxJSCjQS7tTqndZP.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
