INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'93C7E7509C644E68B13CD96DC99446F5', X'E3A2866991B545F7BB735006ACC084E8', 26, 'Tooth Fairy', 'The farmer comes across his old golf clubs and decides to knock a few balls around, instantly putting his back out in the process. Shaun takes the opportunity to learn how to play, while Bitzer is forced to tend to his injured master inside the house.', '2007-09-05', 7, '/gCJSDE01wpgU3C0PlBEWkAAQBo1.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'93CF301C28AA4883B7378E739C4216EE', X'9C9D89DF5F6B41D084C6B8CA7BD2A2E6', 8, 'The Letter M Mystery', 'The letter “M” goes missing from everywhere around Sesame Street, and it’s up to Nina and the gang to find it.', '2021-12-30', NULL, '/iZqrUwWKqoV5mhX9itN94nN5h66.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'93D20859602D4CE5A89313675E56490B', X'432A6ABDDCCA44CC82CEFB39E33B8949', 49, 'Jealousy Pt 4', 'Rogers shows cake-decorating tools and sees a man decorate a cake at Brockett''s Bakery. Chef Brockett takes a cake to the Neighborhood of Make-Believe for Collette. Henrietta is in the center of what happens.', '1971-04-22', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'93D783B3A0974AEC8C057B99727767EE', X'D5383B3D56364D71B99CB84774B4B3C6', 25, 'Pingu Loses the Bet', 'Pingu is going out on his sledge, but before he gets very far Mother calls to him to stop, and asks him to take Pinga with him. He’s not happy about this but does so reluctantly. They stop at a fairground stall, where the main prize for throwing balls at six cans, and knocking all the cans down, is a large teddy bear. With his three balls, Pingu knocks all the tins down, and wins the bear. Pinga wants to have it, but Pingu won’t give it to her. The stallholder sees what’s happening and wonders what to do. He has an idea, and suggests that Pingu and Pinga compete for the bear by throwing at the tins against one another. Pingu and Pinga agree, but what Pingu doesn’t know is that the stallholder has used a magnet to hold Pingu’s cans onto the shelf! Pinga completely misses the cans with her first throw, and hits a nearby snowman. With his first throw, Pingu knocks down four tins. Pinga gets closer, but still misses, with her next throw. Pingu gets one more tin on his second throw. Pinga gets one tin on her third throw, and Pingu is gleeful. He takes his last throw and hits the remaining tin full on, but is amazed when it doesn’t fall down. He’s even more amazed when Pinga has another throw – the stallholder has sneaked her an extra ball when Pingu wasn’t watching! She hits the tins. Only one falls initially, but the rest soon topple with a bit of help from the stallholder. Pingu has lost, and regretfully gives Pinga the bear, which she cuddles. Pingu and Pinga then go home, and wave goodbye to the stallholder as they leave.', '2000-04-07', 5, '/t1iy4td93JxjRPNcEU2ngTVrKvO.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'93D79B1104DC4D62B183C68F930B6040', X'C9ADC698BE924DD794ADD8F6759361CA', 23, 'Episode 23', 'The Neighborhood of Make-Believe welcome another two new visitors from the Planet Purple, called Paul and Pauline.', '1973-03-21', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'93E1547A48B04B7F858D42C5D81C2800', X'C67A878749714961B5361FF01924E2A9', 1, 'Swept Away', 'Arthur, Buster and D.W. enjoy summer vacation at the beach. When it becomes unsafe to swim, Grandma Thora suggests building a sandcastle and they quickly become immersed in this pastime. When the tide threatens to sweep away their castle, Arthur isn''t ready to let it go.', '2007-06-25', 13, NULL, '2026-04-03T17:37:58Z', '2026-04-03T17:37:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'93E9210D4ADB49E9B6B7BF463B02DB3C', X'991E78F103A54D268F7575E11DB4243C', 6, 'Go-Stop-Go: You Can Never Go Down the Drain', 'Rogers assembles a fountain in his kitchen. He shows a videotape of numerous fountains from around the world. Chuck Aber shows a videotape on how raincoats are made. In the Neighborhood of Make-Believe, King Friday donates the old castle fountain to Mayor Maggie and the people of Westwood. Lady Elaine gets a gift as well. Chuck Aber gives her a nozzle to squirt water. Maggie Stewart Brings A Videotape In For Mr McFeely On How People Make Shirts', '1999-03-22', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'93EF974E0A28490B91E3BBDBF5584FF6', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 37, 'Elmo Steps in for Super Grover', 'Super Chicken and her sidekick, Robin, fly in to help Elmo. Horatio becomes Super Grover''s sidekick.', '2010-12-07', NULL, '/r0HXtWQ7HCOccFiKZsHoVczeMc6.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'93F136E3A01E447A9B03BD093E8FCA10', X'4F8C16F69B924BE99B6B837F26AD3720', 2, 'Story Time', 'Karen finds it very difficult to write stories at school, so she uses the watch to give herself more time to think. But then she finds herself trapped in time when she loses the watch.', '1998-10-09', 15, NULL, '2026-04-03T17:20:04Z', '2026-04-03T17:20:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
