INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'93FA6FD48675493FB1D10B820C8D04D2', X'4B2A19E02FAE492EBC31F78E63D88EBC', 19, 'Four Score and Seven Pawns', 'Pull the trigger with the Pawn Stars when an 1800s Colt revolver barrels into the shop. Will Rick lock and load or get gun shy? Next, an antique Chinese fingernail guard scratches in. Will Chum lift a finger to make an offer or fail to nail it? Then, a life mask of Abraham Lincoln casts its way in. Will Rick cement a deal or will it crumble away? And later, a screen-used Playboy magazine from "Forrest Gump" reveals itself. Will Corey run to make a deal or be left sitting on a bus stop bench?', '2016-12-26', 21, '/4A2SgqoovvrjdYKqRJebpCrCMUC.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
