INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'940DFE9089BA4103BCDA3E11FA9A9465', X'A8C6182E05E14B6891A55126CF6C94F0', 27, 'The New Frontier', 'Sarah decides to go off into the wild Ohio Fronteir to find her father, while there she''s found by some friendly Indians who wish to help her. An English friend of the Indians comes to help and Sarah gets a very wonderful surprise and makes a sad decision.   Meanwhile James and every other poor person is having trouble with the rich overcharging them. A man trys to tar and feather a rich Tori, but James disagrees.', '2002-11-05', 30, '/iP4o6wxgpTAMkWqo4X5lPeubbcR.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'940FC3BFDE8B4389A17C4DB2A5B105CC', X'42E591E22A884434AE9F3D4B1D685613', 21, 'On a Mission to Pawn', 'The Pawn Stars are on a mission from God when the guys check out a replica of the iconic Blues Mobile from the movie "The Blues Brothers." Complete with a loudspeaker on the roof, can they pick it up for a song? Then, Corey and Chumlee check out a blueprint of the original electric chair from the Illinois State Penitentiary. Will sparks fly during negotiations? And later, Rick''s desk is falling to pieces, but will nostalgia foil any plans to replace it?', '2013-08-22', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
