INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'94141B8000E647FEA93636E00B426768', X'F4C403079B5E4263A4E0DFA138131E7F', 62, 'Elmo''s World: Families, Mail and Bath Time', 'Sesame Street''s lovable, furry red monster, Elmo, invites young viewers to explore three subjects of enormous interest to kids. First up: What makes a family? Elmo looks at all sorts of families and talks about the joy of being part of one. He also explores how mail journeys from the sender to the recipient, and then ends the episode with a discussion on how to keep clean while he takes a dip in a soothing bath.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'941A2BD5A93842DC96F42035E3C8D278', X'D9973960273B4A92A7DA62EFE8860D09', 8, 'Hot Tub Confessions', 'While Heather works on expanding her business, Lisa and John have a heart to heart about how much work she’s taking on and Whitney enlists her husband, Justin to have a difficult conversation with her father. And although Meredith and Seth decide to give their marriage another shot, after a fun day of snowmobiling, Whitney grows curious about Meredith’s marriage and wonders if there is any truth to what Jen is implying. Later, Lisa, Meredith, Jen and their husbands hang out at Jen’s house; While the women dish about their marital issues, the men give their side of the story.', '2020-12-30', 41, '/7bI7Zw1fYZhWEAXxAkqZVpnRar1.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
