INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'94205C8C4C1A466695E9F53FB651518F', X'6D2B78D726124AFB81CADEE774AF9C2B', 11, 'Making Mistakes 1', 'Rogers starts off the program by showing a picture book of animals, but the giraffe picture is misplaced as a skunk and the skunk image is misplaced as a giraffe. Susan Linn enters with the puppets she uses in talking to children. The puppets also go to the Neighborhood of Make-Believe all week. One of them, Audrey Duck, has her feelings hurt.', '1987-05-04', 30, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'942082BCCC2846D68B0701E8D5790F4E', X'B6BAA6EC09084A4790017E7158985002', 13, 'Ups and Downs', 'There’s a monster in Walkerville Lake! Wanda competes with Gerri Poveri, a TV reporter whose ratings are sinking, to be the first one underwater.', '1995-12-02', 25, '/cLyBsyD94X3KcCMLJQFx98GF6x6.jpg', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9434C16172EE4283A651D01CBD252E9D', X'54900370898846B8B7AA61D2B88D7056', 18, 'Reunion (2)', 'The reunion continues with Mary sharing an emotional update about her son and how she feels about her church being in the spotlight. The women attempt to find resolution about what happened on the plane ride from Canouan. Heather draws a line in the sand with Meredith. Meredith provides some insight into the shocking root of her issues with Britani.', '2026-01-20', 42, '/pb2YHop73T7DF8xxWKRr3qvhyiX.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'944175EEB04A441F9BC63FE28C2E4F7B', X'70C8CB4624944DD498F66BFB9B3FAF73', 8, 'Chopper Gamble', 'The Pawn Stars have an opportunity to buy something they''ve never bought before - a helicopter! Can Rick convince the Old Man to come along and spin up a deal? Then Rick has a chance to buy a 240-year-old lottery ticket signed by founding father George Washington. Is this the prize of a lifetime? Later Corey has an opportunity to buy five classic mint condition Pete Rose baseball cards. Should he gamble on baseball?', '2010-02-08', 21, '/5FqGYl2E4xpgjSxredMS4w1GT7V.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
