INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'94A7087919C743CFB22A37130071129E', X'5A771F52FE964EA2B567A8DDE899059E', 26, 'Payne in the Putt', 'Rick is wheels up to Washington D.C. to go see one of the first ever Jeeps that was built to use in WWII. While he''s in town, he stops by an antique book store to read up on an ancient alchemy book. Meanwhile, back in Vegas, a magic lantern image projector from the early 20th century has Chum seeing things in a whole different light. A fortune-telling gambling machine is, without a doubt, a great find for the shop. Will Chum see a purchase in his future? Later, by a stroke of luck, a pair of knickers that belonged to golfer Payne Stewart swing into the shop. Will Chum land in a hazard during negotiation, or will he land the shop in the green?', '2018-04-30', 21, '/7lFblNFJ4VaaKmVnSt4kE0WEz33.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
