INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'94C33914C9544894B82BEBE0EC749F0C', X'BD5F5A3F07FA4689B67B02BE5D65F1B2', 18, 'Postman Pat and the Popular Policeman', 'PC Selby tells Pat that he is leaving Greendale. Pat is upset by this, but organises a party to show PC Selby how much he is loved.', '2006-03-06', 15, '/6C4SfJ10bPa95tzGisAcPDV2Mud.jpg', '2026-04-03T17:14:31Z', '2026-04-03T17:14:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'94C5783837A34D8482C0EEF32BB32A6C', X'3269A890BBA94E6C9278F7EB38EB1720', 17, 'Wetlands', 'Wetlands are not just home to different animals and plants, but they also control flooding and help keep the Earth’s water clean. Flood waters move more slowly through wetlands because they have to go through barriers of plants and dirt. Wetlands help stop erosion because the plants stop the soil from washing away. Plants and soil in wetlands slow water enough that bacteria and other decomposer organisms can break down and even absorb some types of pollution. Wetlands are wet. Let’s keep them that way.', '1995-10-06', 26, '/cYfOgud5uFNXx9R65UVixaQVcp6.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
