INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'952335E47D9945AB85A55C1C7FBA239F', X'A6EFE88301134477BF0657B42A3770EE', 19, 'The Maid', 'Elaine''s area code is changed; a co-worker steals George''s desired nickname; Jerry sleeps with his maid; Kramer endures a "long-distance relationship" when his girlfriend moves downtown.', '1998-04-30', 22, '/xYX3ltDUSDNzOToE0frwLO1Srnk.jpg', '2026-04-03T16:34:12Z', '2026-04-03T16:34:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
