INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'952CCDBDF31C46A58B5FED75D21BE869', X'CA09391ADE6A4B2BAEFCC2EFBC80A106', 7, 'Raccoons and Ripe Corn', 'LeVar spends the day following around wildlife artist and children''s book author Jim Arnofsky, who shows LeVar how he is inspired to create the stories by the signs of animals around the woods near his home. Julia Barr reads several of Arnofsky''s books: Raccoons and Ripe Corn, about a family of raccoons that feast on a nearby corn crop; Come Out, Muskrats!, about some shy muskrats hiding in their pond home; and Deer at the Brook, about a family of deer taking a drink at the stream.', '1991-09-24', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'952E941A0DC24175A550FB4E9A9CBEC3', X'4D2CAC0F38FD438B8AFAACF43952E535', 289, 'Episode 289', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1964-07-27', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'952EA1F95B9946988DB177094F848DC5', X'4D2CAC0F38FD438B8AFAACF43952E535', 147, 'Episode 147', 'For younger viewers introduced by Christopher Trace and Leila Williams. Including More About Brownies: 4 and filming on location for "Whistle Down the Wind" starring Hayley Mills with an excerpt from the film, shown by courtesy of the Rank Organisation and Malcolm Mitchell with his guitar.', '1961-08-21', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9541245F10D34E868B114A8241B2786F', X'DA06465B91544FEBA455374DF7DAB02F', 17, 'Elmo''s And Zoe''s Scientific Exploration (4099)', 'Elmo watches a leaf floating in a bucket of water and this observation leads Elmo to many other scientific questions. Elmo, Zoe, and Telly are all curious about whether or not objects such as a leaf, an apple, a rock (Rocco), and a triangle either float, sink, and/or slide. They first have a hypothesis about what might happen and then they test their hypothesis with an experiment. In the meantime, Gordon is there to ask Elmo, Zoe, and Telly about what is happening and what might happen next. They all have a wonderful time exploring together, and learning great new words such as experiment and hypothesis.  Sponsored by P, 15.', '2005-06-01', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'95535B58223B43D0960C663F1C7462C1', X'F4C403079B5E4263A4E0DFA138131E7F', 26, 'The Great Numbers Game', '1 to 20 is your aim if you want to play this game. With a push of the start button, Elmo, Telly and Gabi find themselves inside The Great Numbers Game. Each number they find leads them to one of Sesame Street''s classic counting cartoons. Who will be the winner? Everyone wins when they play The Great Numbers Game!
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'95581998753E4C048CF394CBACCFD4F4', X'D1D267DDE27F4543ACB80D28F676512A', 70, 'Episode 70', 'with Valerie Singleton, John Noakes, Peter Purves.', '1968-05-09', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'955F90E997C545B58947667BDF0D7E7F', X'89BA90EC2C794A12A11D7465D1757683', 13, 'Rick and Morty The Non-Canonical Adventures: A Clockwork Orange', 'A claymation recreation of a classic scene from ‘A Clockwork Orange’.', '2017-07-27', 1, '/7zuu4EHoMCVXA4Dm33nC1oTaYS4.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9560E8757B6C4E0698E3814B31FF8270', X'5C4E51C6E20746AD875C72988EB1E13E', 22, 'Off the Wall', 'The Pawn Stars prepare to charge when a man brings in a Civil War musket once carried by an ancestor wounded in battle. Complete with rare documentation, will the guys execute a brilliant battle plan for this firearm or will the customer secede from the shop? Then, Rick blows a gasket when his son Corey sells an extremely rare movie poster from his personal collection - can Corey make it up to him, or will this movie memorabilia mess-up bomb? And later, a rusted-out 1950s atomic missile-themed pedal car squeaks its way into the shop. Will the seller hit his target to turn his trash into cash or should this Cold War relic been dismantled years ago?', '2011-07-25', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9560FEFB028F4126985B6D09256C0F89', X'2F5A4FFE2548418185AC6145CB3E3BF7', 10, 'Moving Meltdowns', 'Kody sees the plans for his one giant polygamist house and loves them, but his wives may not; just weeks away from leaving their homes in Las Vegas, tensions run high; Robyn presses Kody to settle down and Gabe walks out.', '2019-03-31', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'95675D588C6840D9AF25E83A034EEF5A', X'D1863F2F02EC40CEAF64DB03FBE518A7', 23, 'Music Magic', 'When Elmo uses Abby''s magic wand, all anyone on Sesame Street can do is sing! Also featuring ''Just like Magic'' song with Sara Bareilles, Cookie Monster''s Furry Potter parody, and Elmo the Musical. Brough to you by the letter M and the number 20.', '2016-06-11', NULL, '/jK0iHInU54BPGWYH2VmI57OgYkA.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'956ACE442C434EA5A9CD1A92B2F4051E', X'ECB64EF34F8045A7B4A9C04434B02E35', 24, 'Head Games', 'Huddle up with the Pawn Stars as pendants from the first two Super Bowls rush into the shop. Can Rick score the deal of his football dreams or will it be intercepted? Then, Rick and Corey check out a pair of Igorot spears. Used for headhunting in the Philippines, can they strike a deal or will they lose their heads? And later, the Old Man gets flooded with birthday gifts, but will he get the only present he wants?', '2014-03-20', 21, '/35RtKqjmoW5XLYu2pY495S9xhw6.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
