INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9578A7F8CEFE455CB2A34CD5BFC527AD', X'B6BAA6EC09084A4790017E7158985002', 1, 'Blows Its Top', 'To help them understand how the Earth makes islands, Ms. Frizzle presents the kids with an island that hasn’t been discovered yet!', '1995-09-09', 25, '/pZQKrrS4qO4AM3vpt8RV7BIXHsc.jpg', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'957D61994B5142AAB1F2331A6F12463E', X'A4843A51AEEF427C902C7FB3BD670CD4', 9, 'What''s in the Mail, Today?', 'One morning, Bear steps just outside the Big Blue House to check the mail. There''s plenty of mail, but Pip and Pop are disappointed to learn there''s none for them. Bear cheers them up by letting them deliver the mail to everyone and personally takes a letter to Tutter --- his first ever. It''s from his Grandma Flutter and he''s very pleased to receive it. Pip and Pop deliver a package to Treelo, which turns out to contain a feather. Tutter decides to write a letter back to his Grandma. Ojo also receives mail --- a postcard from her Uncle Koala. Shadow tells a story of a girl who wrote a letter, but lost it.', '1997-10-30', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
