INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'958F4A97DE4044F5923024AB15E61E2A', X'BFDF87FF01DD4B5494BD19B384F41BDB', 15, 'Shamrocks and Shockwaves', 'The ladies jet off to Ireland to explore Meghan''s heritage and try their luck of the Irish. On a pub crawl, an over indulgence of spirits leads to a sobering exchange of words between Tamra and Kelly, ultimately pushing Tamra over the edge. With Kelly on the outs, the rest of the ladies try to salvage their first day in Ireland by enjoying a traditional Irish Hooley Night.', '2016-10-10', 44, '/6k8k8fJKbFs7t3wysa4L3lNMLGV.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'959145AEED5244FDA0C857E1466CCE02', X'0FB5CE6502584423BE8AF7BA9C37BB6B', 3, 'Seal Watch', 'James is hoping to spot a seal, but his Dad''s binoculars prove to be more trouble then they seem.', '2023-10-23', 9, '/vkgX9hjx8w5OXbixuMsAsFqP5jH.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'95937DD8CA4949268006665DE53C4A45', X'DA06465B91544FEBA455374DF7DAB02F', 10, 'Big Bird, Snuffy and Friends Hike (4092)', 'Maria and Luis are planning for their hike gathering their backpacks, water, and trail mix.  Big Bird and Snuffy are especially excited since they have never been on a hike before!  Maria explains what great exercise it is and how many interesting things you can find around you.  They don’t get very far on their hike because they stop to observe things around them that they’ve never really noticed before - the bark and leaves of a tree, the colors of a pebble on the ground, and even a tap dancing spider!  Even though they don’t get very far, Big Bird and Snuffy had a great time on their very first hike!', '2005-04-15', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
