INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'95A19044DE65461CA5679065C3954A99', X'BA99B779CADA43A7902A2ADB472C2E30', 1, 'Episode 1', 'The first episode sets the scene and introduces us to the main characters and starts to show us what it is like to be only 15cm high. We find out that they are the only borrowers in the house and also meet the humans that co-inhabit the house. The first of a series of problems start with Pod ''being seen''. Arrietty, who has never been allowed out of their below the floorboards home, is introduced to the art of borrowing.', '1992-11-08', 30, NULL, '2026-04-03T17:17:47Z', '2026-04-03T17:17:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
