INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'95AB96FCE1CA42FCBA38D77F9FF901E0', X'89BA90EC2C794A12A11D7465D1757683', 33, 'Vindicators 2: Little Trains', 'They should probably go to therapy, but instead…', '2022-07-23', 3, '/7OiY0XY9n4SJIcbtr8pfixz5ZWC.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'95B1BBE2BFB9494E9056F01C057D4FE6', X'E291DF42D44F49E5BF812DF32EE4A30F', 21, 'The Yard Sale', 'Doc Hogg stops by the Big Blue House to collect for charity. He''s collecting for muskrat relief following recent flooding that left many of them homeless. Bear is completely out of money, so Doc Hogg agrees to come back later. Bear and Ojo then find Tutter struggling to cram an excess of stuff into his mousehole, giving Ojo the idea for a yard sale. The idea takes off and Pip and Pop are assigned to be sales-otters. Treelo finds some things of his own to sell and Ojo helps out by painting pictures. Tutter, however, finds it difficult at first to part with some of his things.', '1999-09-29', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
