INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'95B3FEDD5CC744B8A603137BE92932EA', X'5B5E8B2F0A854488B3DC3D8B794E6582', 19, 'Candle Wicks and Lunatics', 'Vicki surprises her son Michael with a new role at Coto Financial, while Kelly complains to her mother that she''s finally at a breaking point in her marriage. Tamra fulfills her greatest wish of attending her estranged daughter''s high school graduation. The ladies celebrate the launch of Meghan''s new candle line and Peggy finally comes face-to-face with all the women after her sudden departure in Iceland.', '2017-11-13', 44, '/dbs20ddOU9btbuDfEmdWWbjV9JR.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
