INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'95C0BABC8A9745FD8CF72084F1E709E7', X'D64C5D0C41A0440488E755C405302D79', 2, 'The Night Lands', 'Arya shares a secret with a familiar recruit; a scout returns to Dany with disturbing news; Theon comes home to the Iron Islands.', '2012-04-08', 54, '/3EW7wYNXUVaHT4XRuIoNFrqhZh5.jpg', '2026-04-03T15:40:36Z', '2026-04-03T15:40:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
