INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'95C79070D1E249B8BE412F074970FA1D', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 88, 'Episode 2183', 'Big Bird walks up to Susan and the kids on the stoop of 123 Sesame Street, wanting to show them a new trick where he can make a rhyme for any part of the body. Big Bird is still trying to think of a rhyme for "elbow," leading to a montage of him pondering all around the street in frustration.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'95C88BA9208C4F62A6214F83741C42C0', X'4FE93658C46343298E649D523869C2CB', 12, 'Bare Bones', 'Roar down the road with the Pawn Stars as they stumble upon a Down and Dirty custom motorcycle frame. In need of everything from wheels to a motor, will the gang turn this easy rider into easy cash or is this project simply sputter itself out? Then, a man brings in a collection of Mazon Creek fossils that are hundreds of millions of years old. Will Rick be able to chip away at the seller''s price or is the price set in stone? And later, Rick and Chumlee visit a man with a classic Vegas blackjack table from the Stardust Casino. Will Rick go all in for the win or bust and lose it all?', '2010-10-25', 21, '/sSgQs71Rw44Dtyw29CGSKRPJAAs.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'95C94AFAF14646FABA4C860DC83FEE61', X'1415EF1C411A4C26814A7C79C3628BC2', 17, 'Tequila-thon', 'It’s a new day in Mexico and the drama continues as Bethenny confronts Ramona about attending the Tequila trip. Tinsley readdresses the press article with Sonja, while some of the other ladies try their hand at surfing. The ladies all go shopping together and Ramona tries to buy her way back into Bethenny’s good graces. Tinsley and Sonja’s tension resurfaces at dinner. Bethenny takes the ladies on an educational day-drinking trip to the agave fields in Tequila. The ladies ride the drunk train back to the villa where Sonja puts Ramona in the hot seat.', '2017-07-26', 60, '/f7lhbHaOEiWdNvoQ7WC2fdjWFTJ.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'95C95824A1464C569C28F356A0C7E78C', X'DF77DBA2BBDA4F3897138D5C856F852E', 10, 'The Apple Tree', 'Little Bear decides to grow an apple tree as a surprise for Old Bear. With help from his friends he manages to plant an apple pip in a flower pot. He is disappointed to hear that, despite watering it and keeping it warm, his pip could take years to grow into a tree. However, while he is waiting, Bramwell Brown finds a way that they can help Little Bear make an instant tree that will really surprise Old Bear.', '1993-12-05', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
