INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'95EE07C896E14AB5BF057789201350F2', X'33440D76E69F47ADAC25862CCBC9DFA1', 19, 'Reunion (1)', 'The season eight reunion kicks off as the women take center stage among their Monarch magazine Icons gallery to rehash all of the drama that occurred both on and off camera. The ladies bond over what they do best, which is talking dirty. Robyn gets called to task for always defending Juan. Candiace is caught off guard when Gizelle and Robyn drop some shocking allegations about Chris. Mia opens up about her new boyfriend and is confronted with a rumor from her past.', '2024-03-31', 43, '/jLLV7jzVWZhsDVZHui2KaEJwKPx.jpg', '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
