INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'960D3FF70063447492D78A394C7E22F6', X'3A96D6C63736498A926F6C479CDFB73A', 26, 'Franklin Goes to Day Camp', 'Franklin and Bear befriends Possum at day camp until he notices Possum was getting all of Bear''s attention. Franklin tries to clown around and get back Bear''s attention but just ended up getting in trouble.', '1998-01-26', 12, NULL, '2026-04-03T17:40:14Z', '2026-04-03T17:40:14Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'960FA6528C3D4BD4AE48D7D805A60D0F', X'70C8CB4624944DD498F66BFB9B3FAF73', 14, 'Flight of the Chum', 'The Pawn Stars have a chance to buy one of the quietest air crafts ever made - a vintage Schweizer glider. Will the gang soar into a good deal and restore this glider to its high flying status or will they take it too close to the sun and get burned? Then Corey meets a man selling an autographed jersey of famed New York Yankees icon Lou Gehrig. Can he reach deep and catch the Iron Horse''s jersey or will he strike out swinging? And later the Old Man is speechless when a guy comes into the shop with an extremely rare casino chip known as "the one arm bandit." Will the Old Man bet the house for this historic Vegas relic or fold when the stakes get too high?', '2010-03-08', 21, '/mo7H16jg0hnUuGiYt4chBClLXFQ.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
