INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'961F97A0EE58412BA188A0720825131E', X'3269A890BBA94E6C9278F7EB38EB1720', 9, 'Germs', 'Don’t panic, but germs are all around you. Germs are bacteria, viruses, protozoa, and fungi, very small one-celled organisms. Your skin keeps most of these organisms from ever getting into your body. If germs slip inside, your body has some powerful weapons to attack and destroy them. And not all germs are bad; there are good germs, too, like the ones that live in our stomach and intestines – our guts.', '1995-04-07', 26, '/grzXSh8MGmxJ75nHe2pMYVxNZwP.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'96290C28FEDC4F7CB6370B2BE96E14BB', X'63F9BF6D39B344F4B885A56807277A80', 100, 'Muppets Commercials - Purina Dog Chow', 'Rowlf the Dog made his television debut in these rare commercials produced for Purina Dog Chow between 1962 and 1963. Designed by Jim Henson and constructed by master puppet builder Don Sahlin, Rowlf went on to become a national television star on "The Jimmy Dean Show" (1963-1966) before settling into his role as The Muppet Show''s resident piano-playing hound dog. His sidekick in these spots, Baskerville, was also occasionally seen on The Muppet Show.', '1962-12-31', NULL, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
