INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9631F3055847494188F36923C8BB16BA', X'33319C06A2B043BF8694B3E8E37E49E9', 6, 'Pony and Trap', 'Neil meets a friend riding a pony and trap. She agrees to let him ride it with her and they go around the Gordano Valley Riding Stables'' course.', '1997-02-14', 10, NULL, '2026-04-03T17:19:38Z', '2026-04-03T17:19:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
