INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'968FD79A483A46DCB2A9E254BFD9E134', X'21745B85D26942FAB4DD701B2DA5C085', 65, 'Episode 65', 'with John Noakes, Peter Purves, Lesley Judd', '1974-04-29', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9691253201BE4DC5906DE018F182D3B7', X'4FE93658C46343298E649D523869C2CB', 17, 'Luck of the Draw', 'At high noon the Pawn Stars look at a collection thought to belong to our country''s most legendary Western lawman - Wyatt Earp. Will a tough negotiation lead to a showdown at the O.K. Corral or will the peacemaker save the day? And later, a man brings in a gold medal from the 1984 Olympic games in Los Angeles. Can Rick put everything on the line to compete for sport''s highest honor or will he stumble at the start? Then, when presented with a perfect pair of 19th Century pistols, Rick has some concerns. Will he take his best shot at these perplexing old pistols or will a hasty decision halt the handgun deal?', '2011-01-17', 21, '/boofcTqL0hzLoxpAfr5vWa77Mni.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9692805CD38240B6AA62CC75C115FF92', X'F812042DEB85432E80473675886E0B1B', 36, 'The Entrepawneur', 'Based on a portion of the epic poem ""Metamorphoses,"" by the ancient Roman poet Ovid, this episode focuses on the story of King Midas.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9694436D16E348169711953B5B3B4A5F', X'C6D5CF79F2B040AFAD1291AA4F1B1D21', 11, 'There''s No Crying in Pawn Stars', 'Chum tries to put his best foot forward when a Nike Lebron sneaker hits the counter. Will it be a slam dunk? Then, Rick keeps a close watch on a seller who comes in with a signed Pulp Fiction poster. Can he negotiate a royale-y good price? Next, Corey might be in over his head when several Jim Henson sculptures float his way. But is there something fishy about them? And later, all that glitters might not be gold when Rick and Chum head to the range to fire an antique pistol.', '2022-10-19', 42, NULL, '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9695915E4BCB4F0296DCDF1EEEC1A39A', X'6F731E6BD3C54DE684E17A19CB650E86', 7, 'Promissory Pawn', 'Blast off with the Pawn Stars when Corey and Chum check out a water-propelled jetpack. Will the deal get off the ground or will they send it packing? Then, a promissory note from the Mexican-American War tries to secure territory at the shop. Will Rick do the deed or will he lose interest? And later, things get spiritual when a statue of the Hindu god Shiva is brought into the shop. Will Rick find his inner peace and make an offer or will he loose his faith?', '2015-11-12', 21, '/3LddoZvdfcU2t3Xjxp7Pj5tz1SN.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9695EF9C05A84EAE9EED1BE8F756DFED', X'331FC1DF6D704D79B585BF28024A4124', 11, 'Seeing Red', 'Bronwyn takes Sarah and Nipper the dog out on a walk along the cliffs to tire out Nipper, but trouble strikes when Sarah trips on a rock and hurts her leg. However, thanks to Fireman Cridlington''s new song they remember that red is a sign for danger.', '2008-11-25', 10, NULL, '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
