INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'96A3CA4ECE214FE7805066C12E2AEDC4', X'F07B879456254682AAE1E56966B4C7A8', 25, 'Hurricane Julie', 'When Julie sees that her excitement about playing in the wading pool is actually hurting people (and pets), she understands that it is important to be careful.', '1996-02-16', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'96AECB3BF29048088B19D249594D79E5', X'3B154D00CB7B49C4A0536EBBBE906EBA', 3, 'Cookie Monster Is Blamed for Stealing Cookies (4033)', '', '2003-04-09', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'96B5F6FEC2E44D54A43186A8C5282703', X'A4843A51AEEF427C902C7FB3BD670CD4', 4, 'Shape of a Bear', 'Tutter is excited because Bear has promised to bring him a box, but he''s getting a bit impatient at the wait. Viewers learn that the box is a rectangle and that there are shapes all around. They also find out that everyone has their own unique shape --- something that Ojo, Pip and Pop learn when they become shape explorers. Treelo also learns about shapes when Bear plays with him in a "tent" he made out of a bedsheet. Shadow also pays Bear a visit and tells a story of a very special shape --- a star.  Songs  ■Me, I''m the Shape of the Bear (and Reprise)  ■Twinkle Twinkle Little Star  Notes  ■When Ojo is playing with her blocks, she sings "Heigh-ho. Heigh-ho. I love my blocks, you know." This is a play on "Heigh-ho. Heigh-ho. It''s off to work we go" --- lyrics from the song "Heigh-Ho" in Disney''s Snow White and the Seven Dwarfs.  ■The Bear-only version of the song in this episode is Track 18 on the album Songs from Jim Henson''s Bear in the Big Blue House. On the album it is titled simply "Shape of a Bear," but on the credits at the end of the episode, it is listed as "Me, I''m the Shape of the Bear."', '1997-10-23', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'96B6C7B7B10241868E7BC46879377CB7', X'51F03551BA41409D85F4E51BDDFDF82E', 6, 'Runway Run-In', 'The ladies have a passion for fashion as they attend various Fashion Week shows, but not without catty bickering between Ramona and Simon, not to mention between Kelly and Bethenny. As for Kelly, she covers all the fashion action for her column. And designer Zang Toi throws a private fashion show for Jill and her friends.', '2009-03-24', 60, '/aQVb2rk1TuQw1AaK5iBOl98mfiI.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
