INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'96E57AD2F9984D69BED32811D27CE864', X'42E591E22A884434AE9F3D4B1D685613', 31, 'Brush with Greatness', 'Get in the ring with the Pawn Stars when the guys check out a painting by Muhammad Ali. Known more for his skills in the ring than with a brush, can a knockout artist create knockout art? Then, Corey and Chumlee eye a Colt Dragoon pistol. Owned by one of the original settlers of the Lone Star State, will the guys make a Texas size offer? And later, the guys hire a consultant to make the shop more efficient, but will they embrace his changes?', '2013-10-31', 21, '/jBSFcAb4xMVMdxXgPfQSOKzDAhd.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
