INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9708D7F513A94BADAE574FEC8824CCF7', X'49A0092491694B3FB8F0D7BD68794DB9', 11, 'Sleepover With One Eye Open', 'Jennifer is left feeling defenseless and abandoned; Teresa opens up to Gia about the stress she''s facing from Louie''s ongoing legal battle; Jen Fessler is left wondering if her friendship with Rachel can recover; Dolores plans a retreat.', '2024-07-21', NULL, NULL, '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'970AC39AD8384DAB84B8AA882EB17B5C', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 1, 'The adults begin to believe that Snuffy is real', 'Big Bird challenges the adults'' skepticism about Mr. Snuffleupagus by passionately explaining the difference between what''s real and imaginary. Gordon, Maria, and Linda come to his defense, while other adults remain unconvinced. Maria visits Big Bird''s nest and brings back a note from Snuffy, proving his existence to believers and skeptics alike.
