INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9753E33CE53D4A0DB2AC663FE2065192', X'DEC4A06D731B41E48B15374F47D1F5C7', 6, 'Swimming With the Gefilte Fishes', 'Teresa bids adieu to her ankle bracelet and the ladies plan a trip to celebrate. Also: Siggy reconnects with her religious roots; Dolores makes headway on her home renovation; and Melissa corners Jacqueline about a dust-up with Teresa.', '2016-08-21', 43, '/pqKnOm7iEpzfOwlr9JIs4JRDysW.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9758E34E488946FCBF706A1F8B864D29', X'A0FA50759CE148C199950C0FD866E549', 10, 'Sweet Home Augusta', 'While Kyle gets emotional over her new life, Bozoma tries to make sense of her new future with her man. Sutton plans a trip back home to Augusta with Garcelle and Kyle, but not everyone is met with the Southern hospitality they were hoping for. Kathy’s Capri-inspired dinner gets molto teso when Dorit opens up about the state of her separation as Erika urges her to stand her ground.', '2025-02-04', 43, '/o6ca6mm1C4UZpeNujZzxp3GS69p.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'975ABBE7D99044CD899A0D21D69C6DA5', X'4D2CAC0F38FD438B8AFAACF43952E535', 317, 'Episode 317', 'With Christmas two weeks away, the Blue Peter team, led by producer Biddy Baxter, is preparing for its seasonal shows. Tonight, Christopher Trace and Valerie Singleton will present some festive items. They''ll share the history of the Christmas tree and introduce a visiting troupe from Kitzbühel, Austria: The Gay Tyrolese, led by Toni Praxmair. This world-famous group of dancers and singers will perform several traditional routines, including the humorous ''Woodcutters'' Dance'' and a ''Miners'' Dance'' using cowbells. The most exciting dance will be the ''Schuhplattler,'' where the performers slap each other''s leather shorts. Additionally, in the first of a new series, Gordon Murray will demonstrate how to make bottle puppets for a Christmas show.', '1964-12-07', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
