INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'978D894116AC4B6189515B26F769098A', X'C21DBD225E2E4414BB67750399AAF6F0', 8, 'Pony Up', 'The Pawn Stars gain access to classified information as a collection from former Attorney General J. Howard McGrath enters the shop. Complete with his Secret Service I.D. and some counterfeit money, will this political memorabilia be a hot sale, or land the guys in hot water? Then, Rick and Chumlee encounter a 1960''s U.S. Marines vehicle called a "Mighty Mite." Capable of driving nearly submerged in water, will Rick charge into hostile territory for this all-terrain truck, or will the negotiation get mired in the mud? And later, the Old Man is off to the races when he gets his hands on an electronic horse race analyzer. Will this 1970''s technology help him beat the odds, or should this gadget have been put out to pasture years ago?', '2011-12-19', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
