INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'979780A3A57443F19F9C142143F63B06', X'D3E13496E3C8490383B45A31FEDEE232', 9, 'The Waterbending Scroll', 'After Katara attempts to teach Aang waterbending, but realizes that he is learning it much faster than she is, she is desperate to improve her abilities.  When Katara inadvertently stumbles across a waterbending scroll that can help improve her abilities at a pirate’s store, she decides to steal it, realizing that she couldn’t hope to afford it.', '2005-04-29', 25, '/c4xpfkn2iRVr50hal2NPu7mbZSC.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
