INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97B60F8676614ED9A9EBFE36AEAB9C0E', X'CA19F89515144988A70995E84EAB7CEE', 10, 'Knock Your Sox Off', 'Corey plays ball when he gets a signed letter that knocks his White Sox off. Will he swing for the fences, or get shut out? Next, Rick looks at a John Wilkes Booth poster you''re not going to want to hang in your bedroom. Can Rick capture a deal before it gets away? Then, Rick and Chum strut to a seller''s house to check out some "peacock" wicker furniture. Does this deal have legs, or will it fly away? Finally, Rick sees a German album you''re not going to hear in a discotheque. Will he say "Notgeld" or "Yesgeld" to this collection of unique bills?', '2021-01-11', 42, '/6ehOU1NEBRXvDegkZIuuSrLfHxL.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
