INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97C348588B7446C084D8D415514D810E', X'BA33491A8F194E61AE9F0A67DB3C65B0', 17, 'A Grande Finale', 'Ashley lands her dream home, with a little help; Robyn makes an unexpected change to her wedding plans; Gizelle reveals her health diagnosis; Karen and Charrisse have a showdown at Candiace''s music video reveal party; Mia confronts Karen.', '2023-02-05', 54, '/jf4alIIyrOhkX6How7YxOOZEaG7.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97C4D7FA87E14637AFD06E1D85BCB21B', X'CA19F89515144988A70995E84EAB7CEE', 1, 'Close Encounters of the Pawn Kind', 'Chum sets his sights on something out of this world when a seller brings in a signed copy of "The Coming of the Saucers". Will Chum be able to identify the perfect price? Meanwhile, a seller claims to have a painting by artist, Ralph Blakelock. Will this deal have Rick seeing all the colors of the wind before it Van Goghs away? Then, Rick and Corey get a history lesson when they check out a "We Buy Gold" sign from the 1900s. Can the duo raise the bar on the negotiation? And later, Rick and Chum take a trip to L.A to see a very special collection of Kobe Bryant memorabilia.', '2020-11-16', 42, '/oWtXUvYmi4iJRk55iS9nlKBG3RI.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97C4E5C80E1848068A7A1923D6344FE2', X'EFDF1E4F84764382A9D72B9DA4188BE0', 14, 'Helping', 'After Rogers draws with some colored chalk, he sees a videotape on how this type of chalk is made. In the Neighborhood of Make-Believe, Purple Panda is called on to help Lady Elaine overcome her fear of "vacuum sweepers".', '1996-08-16', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97C9051D5CA54163865D2562EC60BC9A', X'4D2CAC0F38FD438B8AFAACF43952E535', 115, 'Episode 115', 'A magazine programme for younger viewers. Introduced by Christopher Trace and Leila Williams. An Elephant''s Drum, a story by Michael Diver, aged 10 with pictures by Tony Hart. The Three Worlds of Gulliver - An extract from the new film shown by courtesy of Columbia Pictures. Six by Four: 6: Gradients and high levels, a series in which Michael Humphries shows you how to make a better lay-out for your model railway.', '1960-12-28', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
