INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97CDE658070B4E8BA83C8D95AFCA4ED2', X'740A96A0A0754BE2BE92A178D0939384', 15, 'Chamki Visits Sesame Street', 'Big Bird is getting ready for a visit from Chamki, his pen pal from India. Grover, Elmo, Rosita and Cookie Monster build a giant bird feeder to help her feel comfortable on Sesame Street. When she gets there, the gang finds out that even though she and Big Bird have a lot in common, she''s not a bird at all!', '2018-02-24', NULL, '/5HZCQzlzQ81rKvbo6S7oNJOjvrF.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97CE29E098A9458C97FE3EDC5A4A33D6', X'5B72E664D3D7435DBDC3A23D29D1178E', 10, 'The Birthday Band', 'It is Old Bear’s birthday and the toys decide to surprise him with a special, musical treat. Everyone sets out to find or make an instrument and soon they are making wonderful music. Old Bear is delighted with his surprise and the only problem is that Bramwell has managed to lose his special birthday buns. However, all is revealed when Little Bear’s big bass drum rolls out of control.', '1994-10-10', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
