INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97D39EBD255D4AD584397FCFC9433233', X'7B19039A31AC425C8FB1B51CF2447821', 6, 'The Vow Renewal', 'With Coronavirus making its way to California, Shannon stocks up on supplies, and Kelly gets bad news. Braunwyn and Elizabeth bond over addiction and fleeting friendships. Braunwyn visits her mother, Dr. Deb, for the first time in months, ahead of her vow renewal and deals with an uncomfortable reunion. Emily and Gina begin to question discrepancies with Elizabeth’s stories. Later, Kelly confronts Shannon about her competing water line idea, which boils over while Braunwyn and Sean exchange vows with an ordained drag queen.', '2020-11-18', 44, '/5OM2RWDrWlhD9SLNMiSqCdUcrk9.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
