INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97D9A9B479C94EE49A80D4D3F6D8A0FF', X'53587A7ECD9344F0AD795FE586DCCB8E', 3, 'The Seaside', 'Kipper and his friend Tiger go to the beach and are having a great time when the tide comes in.  Unexpectedly, Kipper must come to the rescue.', '1997-09-19', 9, '/puv2Ur995LXS0r0fUD3kvmbSacs.jpg', '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97DFEDC6AE5245CEBFFA1B3405504132', X'A8DB07E5FBA349A9BD12947C111B39BE', 14, 'The Benefits of Friendship', 'Bethenny glams it up for a Skinnygirl event, despite her health issues. Also, Ramona and Sonja take a dance lesson; Jules sees her plastic surgeon; and the women gather for drinks, with LuAnn confronting Ramona and Sonja delivering shocking news.', '2016-07-06', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97E12929F6E54ED0880483DB9B1B77F6', X'97D7FF20E6FF4DBBBCDDFD87A1D0FA4E', 10, 'Thunder Pawns', 'Rick sees red when a Rolex Submariner hits the counter. Will his offer make a splash, or is it just a waste of time? Meanwhile, Corey gets slap happy over a hockey stick signed by Paul Newman. Can he score a deal, or will he be iced out? Next, Chum and Santos are sweet on a set of Mr. Softee trading cards. And later, Rick tries not to explode with joy when he heads to the range to check out a set of Bolivian thunder mugs.', '2023-05-17', 41, '/mcSVPZQNRVCvphKK7yOFvWFfSPA.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
