INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97F232ED01FB41EA9FCBE163F0746C6A', X'879892836FEA40D78D9122C4947DB105', 2, 'Happier Alone?', 'When angry neighbors drive Meri out of Flagstaff, even Kody starts to wonder if the move might be a mistake. The houses in Vegas are not selling and the family is drowning in rents and mortgages. At least the pond on their land gets the kids excited.', '2020-01-05', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97F41D0E73444E98A91D2DB3D2B0A769', X'D920EBAEF00A4E25ABFE40492C74DED6', 17, 'Crossbows, Coins and Conspiracies', 'It’s hands up at The Gold & Silver Pawn Shop when someone brings in a toy gun from a classic 60s show. Will Chum be a tough negotiator, or will he cry “U.N.C.L.E.’” Then, Rick tackles a LaDainian Tomlinson jersey that charges into the shop. Later, a seller brings in the original microfilm from the investigation of JFK’s assassination, asking what the Pawn Shop can do for him, instead of what he can do for the Pawn Shop.', '2020-04-10', 42, '/m28NDYCsUtM5BIqYZ43qrJLPPcG.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97F45063A13F4133B6CAA2C9CEC7B4F8', X'A8C6182E05E14B6891A55126CF6C94F0', 15, 'The Turtle', 'Sarah, Henri and James reports on a sea monster in the New York harbor, then they meet the submarine inventor David Bushnell.', '2002-09-20', 30, '/fRv3aS966zxf0z7Vr6xn9Y2TVNo.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97F5D44E464C440A8E1AE7018CB47683', X'89BA90EC2C794A12A11D7465D1757683', 24, 'Samurai and Shogun (2)', 'Samurai Rick''s savagery knows no limit in the epic conclusion of his battle to save Shogun Morty.', '2021-11-12', 6, '/8LyTMfir8eQPh1ADzDc5BZ9LtUS.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97FAE642C6434975A0897FFDA96CCEED', X'A4843A51AEEF427C902C7FB3BD670CD4', 16, 'The Big Little Visitor', 'Tutter receives a letter in the mail that his Grandma Flutter is paying a visit to the Big Blue House. Bear informs Tutter that the letter says she''s coming today, which sends Tutter into something of a panic. His Grandma likes for things to be clean, but Tutter doesn''t feel there''s enough time to get ready. Everyone in the Big Blue House helps Tutter to make a go of it. They clean up the house, Tutter cleans out his mousehole, and Pip and Pop weed the flowerbeds with Ojo''s help. Having all gotten dirty, they take a bath. But then, Bear does the cha-cha-cha and Tutter joins, leaving him all hot and sweaty. Grandma Flutter arrives and Tutter learns she''s just happy to see him. He even finds out some things he never knew about her before. In the Shadow segment, Shadow tells the story of "Hickory Dicky Dock," about the mouse who went up the clock.', '1997-11-11', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'97FB3FE970004A2D98028000B7AFF069', X'8730C55E844344B0AFEFA369C478B14F', 12, 'Yes Yes Vegetables Song', '', NULL, NULL, NULL, '2026-04-03T15:26:09Z', '2026-04-03T15:26:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'980071F5E5394FB8AE3CF673A6927456', X'68138DE20900460AB58E480688F1E081', 13, 'Picture This', 'Bear mistakenly receives a piece of Doc Hogg''s mail, and decides to give him a call and let him know. This begins a day full of mistakes, including wrong numbers, a broken vase, and Pip & Pop''s accidental discovery of a new type of sandwich. Eventually, Doc arrives, the vase is mended, and, hey, those baloney-on-the-outside, bread-in-middle sandwiches are delicious! Maybe mistakes aren''t such bad things after all.', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9808D996FCEB44E3B6A44272FF527A18', X'F4C403079B5E4263A4E0DFA138131E7F', 109, 'Preschool Is Cool! ABCs with Elmo', 'Professor Grover is the teacher in preschool and Elmo is his helper for today''s alphabet lesson! But before Professor Grover can start, he wants to find one thing that starts with each letter, in his own silly and loveable way. Will he succeed? Will Elmo and the class ever be able to sing the alphabet song? Featuring alphabet themed stories and songs, kids will find it easy as ABC to join in the fun with furry friends Grover and Elmo in a real preschool. After all, preschool is cool!', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9812E7EFBD204FCA8EB4719D0785DADE', X'3AF7EA64FA134097B8E440AF07083054', 57, 'Episode 57', 'Professor Arne B. Larson shows a few ancient musical instruments at Negri''s Music Shop. In the Neighborhood of Make-Believe, Corny leaves on a business trip, ruining Lady Elaine''s thoughts of a wedding between them.', '1974-05-07', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'98136D55032E446699E70AFDC30EC139', X'4D2CAC0F38FD438B8AFAACF43952E535', 34, 'Episode 34', 'A weekly programme for younger viewers.  Introduced by Christopher Trace and Leila Williams.  Owen Williams tells you about working with wood.  The Tale of Mr. Jeremy Fisher, a story by Beatrix Potter with the original pictures.', '1959-06-11', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
