INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9822563B8C204746817FA11A17425A6F', X'101549F46ED145FAB543D08723F65306', 27, 'Episode 746', '', NULL, NULL, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9823C6606B7F433C8F5DEE80B61A4DF7', X'1A534647384B4C00BB6CA3371AD962EB', 17, 'Last Call Pawn', 'Ramp up with the Pawn Stars when a Line Drive Pinball Machine bumps into the shop. Will Corey get the high score, or will it be game over? Then, don''t count Rick out when he checks out an 1895 Morgan Dollar. Known as the "King of all Morgan Dollars," will it be worth every penny or will this coin break the bank? And later, when Chum takes over a shift at Corey''s new bar, will he use this opportunity to call the shots or will it be closing time?', '2015-03-12', 21, '/sAGouAGs6K1oQUGoUhpVK2HSvgm.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'98247267D08D4E1E9E1AAED1DB20C81F', X'A8DB07E5FBA349A9BD12947C111B39BE', 4, 'BBQ, Brunch or Bust', 'A Hamptons weekend continues, with the ladies arriving at Bethenny''s house, John preparing to apologize to Bethenny and Bethenny basking in birthday behavior. Also, Carole and LuAnn discuss their issues. Later, Jules hosts a brunch, yet dramas emerge.', '2016-04-27', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9825BF34C4B44E2E93FC0EF8809ABCBB', X'5C4E51C6E20746AD875C72988EB1E13E', 7, 'Pom Pom Pawn', 'The Pawn Stars prepare to be boarded when a customer brings in a 1600''s naval blunderbuss. A small weapon thought to be for a child, will this pint-size gun bring an adult-size price or will this deal end up shooting blanks? Then, Rick is presented with the ultimate Coca Cola collectible - a 1978 GMC Coke sponsored motor home. One of just five made for a promotional giveaway, will Rick drive this fabulous prize away or will a tough negotiation bring everything to a screeching halt? And later, a San Francisco 49ers cheerleader hopes to sell her 1989 Super Bowl ring. Will Corey show some spirit for this rare piece of football memorabilia or will a fumble on the play get him booed?', '2011-04-25', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
