INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9852F683E8BA4250A1F0304CE43040FF', X'DBDE6570A68D4FD7A1B0A6037A266A18', 4, 'Who''s Laughing Now', 'Tamra tries to convince Vicki that her friendship with Gretchen won''t overshadow their bond, while on the other side of town, Alexis and Heather meet for a doomed lunch to try and work out their differences. Vicki and her daughter Briana have a heart-to-heart about Vicki''s new boyfriend.', '2012-02-28', 44, NULL, '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9854580214CF4AF2BACAA9417047135A', X'D0E5568D939D4D89AB4EC291A90691CF', 12, 'The Magic Carpet', 'A magic carpet, complete with three wishes, turns up in Kipper''s house. He wishes himself and Hippo to the moon to meet the Bleepers. The carpet tips Hippo off when they reach the moon and the Bleepers find him and wonder what he is and how he got there. When Kipper turns up the Bleepers wonder how he got there. He tells them about the carpet but they laugh. He gives them a ride right round the moon and at last they believe him.', '2000-12-14', 8, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
