INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'98BB401FFA03498F8E014E7984D73A50', X'D6092173D23B4449BAFFE0E16FE56C9A', 16, 'Hurricane Housewives', 'The ladies'' trip to New Orleans continues and Marlo gets in the middle of Porsha and Kenya’s feud. Kandi makes a last minute decision to escape the impending hurricane and head home to open Blaze Steakhouse. Back in Atlanta, Porsha reveals to Cynthia that she''s drawing a line in the sand in her relationship with Marlo.', '2021-04-04', 43, '/1x8GwVaN3vNFlpoAhHA3NrTWq5g.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'98BCCADC31024C7D9298F395FC5C775B', X'D0E5568D939D4D89AB4EC291A90691CF', 4, 'Pig''s Sweater', 'Pig is very proud of his new purple woolly sweater and shows it off to Kipper. Arnold spots a big red arrow, and then another, and they follow them into the woods. Pig doesn''t notice he has caught his sweater on a branch. The arrows were Tiger''s idea and he laughs at them from a tree he''s hiding in. Then he realizes they''re lost. The unraveled wool from Pig''s sweater leads them back home.', '2000-10-19', 8, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
