INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'98DE43D9F802496884CCAD94AB4B03CA', X'34674C90410E427CBE4D2A6F6F865A80', 11, 'Silver Linings', 'Take a shine to the Pawn Stars when a guy brings in 100 pounds of pure silver. Including a single brick worth over $35,000, will the guys mine a deal, or will a led center cause the deal to sink? Then, Rick gets stumped when a seller brings in a mysterious book. Hand-written in Cyrillic, can this ancient text turn a successful chapter for the store, or is the end written in stone? And later, the guys flash back to the ''90s when a collection of movie props from "Batman Forever" come into the shop. Will nostalgia lead them to bite, or will they not even bat an eyelash?', '2012-06-04', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
