INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'990146339C0349618E7102B44B8A7480', X'B1D55597D9D24EEEAB9546DBB163291A', 3, 'Pingu Helps With Incubating', 'Pingu’s family has an egg, and while his parents do the laundry, Pingu has to sit on it. At first he is proud and happy to help, but he quickly gets bored, and gets up and starts listening to music called "Woodpeckers From Space". He does dances and other steps, but the egg suddenly sprouts a leg and starts to dance around the house. When Pingu notices this, he tries to stop things and catch the egg before his parents find out, trashing the igloo in the process. Pingu''s parents, eventually noticing the commotion and finding out what''s happening, rush over to help. Father catches the egg and mother turns off the record. Mother finds Pingu hiding in a cupboard beneath the record player; afraid his parents would be angry at him. They are not, however, and mother hugs him. Mother and Pingu clean up the igloo and Father sews him a hat for a great job taking care of the egg.', '1986-06-11', 5, '/oCXCrAH3vmrlXdPhYJVUcXKLxmy.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
