INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'990F6A8D558A467BAD28F109C388B39D', X'F4C403079B5E4263A4E0DFA138131E7F', 133, 'Preschool is Cool: Making Friends', 'Professor Grover is the teacher in preschool and Elmo is his helper for today''s lesson! But before Professor Grover can start he wants to show Elmo how to be friends with the class. Is making friends really that easy? Will Elmo and the class ever be able to get along? Featuring socio-emotional themed stories and songs kids will learn all about important socio-emotional skills they need to get along with others in a fun and entertaining way. Join Elmo and Grover as they share stories and songs about making friends taking turns sharing and laugh along with Professor Grover''s silly antics.', '2012-10-02', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
