INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'993E0EF656B74AB796C950119830C033', X'C7994637B7C742C7AAEE1BFF4144FE23', 11, 'A Celebration of Life', 'The women head to Ojai for Annemarie''s birthday, as frosting isn''t the only thing Sutton is licking. Dorit questions her marriage after PK''s shocking admission in therapy. Kyle hosts a celebration of life event for her late friend.', '2024-01-10', 44, '/bBVz01Ogglddd7F8hOtAD0B25Kw.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'993F63708A6D4BFF972F3E4A01EFB8B7', X'6BE7468483E64D00BD693E4FCA97CABB', 11, 'Reunion', 'Bravo Media’s The Real Housewives of Dallas brings big drama from the big D on a supersized reunion. For their first rodeo, Andy Cohen sits down with Cary Deuber, Tiffany Hendra, Stephanie Hollman, LeeAnne Locken, Brandi Redmond, their friend Marie Reyes and Cary’s husband Mark Deuber, to rehash the season’s most memorable and difficult moments. In the supersized reunion, Brandi divulges a painful secret about her marriage to Bryan, while Stephanie sets the record straight on Travis’s to-do list. Cary and Mark confront LeeAnne about the scandalous rumor she spread about them, and Tiffany responds to allegations about her racy acting past. Marie also joins the ladies on the couch to share new details about that heated night in Austin.', '2016-06-19', 75, '/86FZgJBH1oYvX6PEAWPWHOOF0BA.jpg', '2026-04-03T16:35:03Z', '2026-04-03T16:35:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'994AC6EFBECA417ABDFD45C386E53B41', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 159, 'Sein-imation: Conquering The Van Wyck', 'Sein-imation is a series of cartoons of Seinfeld episodes. They were released on the Seinfeld DVDs as special features. They used audio from a set episode placed over a new "toon".', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'994EBCDE20A04E309B729B739D6BAF5E', X'56428E5E7DAA468D8BD2076956507AA8', 17, 'Momentum', 'The momentum of a moving thing, like you riding your bike, depends on how much mass you and your bike have and how fast you’re speeding down that hill. An elephant on a bike has more momentum than a mouse on a bike moving at the same speed. A mouse on a fast bike has more momentum than a mouse on a slow bike. If there’s an elephant on a fast bike, you’d better get out of the way.', '1994-11-19', 26, '/jPqY55rQW8Zxg9IFdTRQ45MPpB8.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
