INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9959470AB2674D9D80EFC982399F7B3B', X'78A02D50E3DC4549844A3CF357A32EF4', 16, 'Maui Mayhem', 'Extinguishing all hope of a peaceful getaway, the group''s first dinner in Maui escalates to new heights as Kandi and Porsha erupt over who''s to blame for the salacious rumors that have surfaced. Kandi tries to shake off the drama by planning a speed boat adventure without Porsha, meanwhile Shereé and Bob''s courtship hits a major speed bump of its own. Later, Phaedra attempts to mend the ladies'' broken friendships by organizing an emergency "restoration service" and Bob tries to salvage what''s left of his relationship with Shereé.', '2017-03-12', 43, '/eNU8kY0hdyQbLcaYuqWSxooivJX.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
