INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'99612E7DCA4F404EB1689BB0CCE613B6', X'A8F3A6817ABC41E099889B8804D74611', 13, 'Kody Begs For an Answer', 'The teachers are in for a big surprise when Kody and the wives all attend Parent/Teacher conferences for their kids. Later, Logan graduates from college, but not without some family mayhem. And Kody demands an answer from Meri about having another baby.', '2012-11-25', NULL, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'99645961FA494C0FB4A0E9358B06F2FF', X'C21DBD225E2E4414BB67750399AAF6F0', 30, 'Zoodoo', 'The Pawn Stars sing "Hail to the Chief" when an autographed collection of presidential memoirs comes into the shop. Written and signed by President Harry S. Truman, will Rick campaign to buy these rare books, or is the seller just not on the same page? Then, Corey and Chumlee are presented with a toy "Robby the Robot" from the 1956 movie, Forbidden Planet. Can this mechanical gizmo automate the deal or will it run out of batteries?', '2012-03-05', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
