INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9966821DB36B47F3AB5D6C18E85010D9', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 81, 'The Two-Headed Monster Writes a Story', 'The Count and Gordon count all the body parts on Miles, which add up to "one fine, wonderful, beautiful baby boy." Gladys the Cow feels incensed when she finds Elmo trying to act like her. He claims they''re the same, and Gladys is quick to point out the obvious physical differences.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'99671950A0F448D897952EF6C41F190E', X'F3100D00163F4164B5516ED56605A264', 7, 'Episode 7', '', '2002-05-17', 25, NULL, '2026-04-03T17:21:19Z', '2026-04-03T17:21:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9969CDFF586741DE9D9DB2A42AA08B10', X'119C16D5104745EC8242C72A8EED423B', 18, 'Arthur''s Cousin Catastrophe', 'The Read Family is having a big reunion, with aardvark relatives from all over coming. Arthur normally enjoys the festivities, such as sack-racing and swapping stories, but finds himself hiding because he''s worried that his cousin Mo has a big practical joke planned for him. He remembers her being awful to him in the past and is sure that she has something big planned. However, his worries might just be unfounded.', '1996-10-17', 13, '/nbdPNPdt5TaDVwIrNFLC2sdj9EQ.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'996CA83985884D73B7A8910D8349E1F3', X'D405F9734C7E4CB6B7C0D09A884C9B35', 8, 'Misfortune Teller', 'LuAnn hosts the ladies in Morocco, where she nabs Sonja and Ramona trying to secretly leave the property shortly after they arrive. Later, Jill runs into an old friend while shopping, and he invites the women to his birthday party, which features a fortune teller and a snake charmer.', '2011-05-26', 43, '/av6Yhf46i8F0q4m0D9YWhktx4Qh.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'99721CF7A4DE4CED826905DD49A351C8', X'136B81D3964D4B8FA21492F00D96D6B9', 115, 'Captain Vegetable rhymes / Forgetful in the Fix-It Shop', 'Captain Vegetable leads an entertaining rhyming lesson while Forgetful Jones attempts to work in the Fix-It Shop, causing good-natured chaos everywhere. Despite his bungling efforts and memory lapses, Forgetful manages to complete his assigned task. Everyone appreciates his willingness to help despite his challenges.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9978F3C50E38424792228B970BCC492A', X'6F731E6BD3C54DE684E17A19CB650E86', 26, 'Lock, Stock, and Pawn', 'Batter up with the Pawn Stars when an all-star Dodger''s baseball memorabilia bench faces Rick in the bottom of the ninth. Will it be a grand slam sale or will he strike out? Then, a 19th century Hobbs & Co. lock box bolts in. Will Corey hold the key to unlock a deal or will it get jammed? Next, there''s a prankster in the shop when an original Woody Woodpecker oil painting is brought in. Will Rick tap into a sale or will he laugh it off? And later, Rick gets schooled when a set of educational books called the Delphian Course cram into the shop. Will Rick become a deal-making savant or will he have to repeat the class?', '2016-02-10', 21, '/h5gsSAgbl7YJsJq2l2nbFpeI5AD.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'997BE649C49048CA8655928911C66CC0', X'F0F8B366CB3340B3A50FA1CA7780916F', 1, 'Mirror, Mirror', 'It''s Red''s 28th birthday in a row since the Festival of the Bells when she finds a magic mirror (named Mavis) that leads her to a very special birthday party.', '1987-01-05', 24, '/5lWpdSWkidfc8BzjCM3amJljDs3.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9982077802ED48179249806680A812A2', X'33319C06A2B043BF8694B3E8E37E49E9', 20, 'Theatre', 'Neil visits the Bristol Old Vic Theatre Royal to watch a play.', '1997-06-06', 10, NULL, '2026-04-03T17:19:38Z', '2026-04-03T17:19:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'998B0935A51940549B2E5B2AAA828034', X'05C0E384194C44179F62803EB615E409', 128, 'Disappearing', 'Mr Rogers shows how to tie a shoe, and also explains the meaning of the word "disappear," which isn''t always exactly what it seems. With Officer Clemens, The Neighborhood of Make-Believe bids goodbye to Sara Saturday, but she and King Friday declare that she will return. Officer Clemens sings "I Like to Be Told".', '1968-08-14', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
