INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'99A0167CFB4B4B93872924E40456C929', X'0BA7CC9B13144E1EB74F76463A622991', 5, 'Secrets: A Surprise Party for Mister Rogers', 'Rogers writes a message in invisible ink. Mr. McFeely shows a videotape of how suitcases are made. In the Neighborhood of Make-Believe, Chuck Aber must inform Lady Elaine that he had no plans to marry her, but he does have some good news. Rogers finds a message that leads him outside, where several neighbors hold a birthday party for him.', '1988-11-25', NULL, NULL, '2026-04-03T17:35:45Z', '2026-04-03T17:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'99A621A13FC34DA8889B636DE9C957AA', X'36E5C604FEA94BCF834371BFAF60ECD2', 10, 'Theodore, The Vegetable', 'The Dispatcher assigns Theodore to be the tug in charge of an incoming cargo ship called Julia.   However when Theodore actually meets up with her, Julia questions his ability to handle her and Theodore is not so sure himself either.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
