INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'99ABED58110348B495994E31B6917E1A', X'2E6EE129B32E4417950056F1CC9BC434', 4, 'The Salamander Room', 'LeVar explores the rain forest and animals in their habitats by visiting a park that recreates the rain forest environment artificially to make the animals comfortable. This episode also includes a film of scientists who study the region''s animals from above by climbing inside a tree''s canopy. Lynne Thigpen reads The Salamander Room, about a little boy who finds a small newt while on a nature walk, and all the rationalizing he does to convince his mother to let him keep the salamander as a pet by turning his bedroom into a model rain forest.', '1993-10-14', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'99B023103DE64402B9F63ADBF1003CC4', X'2E6EE129B32E4417950056F1CC9BC434', 1, 'Amazing Grace', 'LeVar visits a theater to discuss acting and how pretending to be someone else sometimes helps people express themselves in different ways. He also visits with his friend, Whoopi Goldberg, who was launching her own talk show, and discussed how her unique look has sometimes helped, and hindered her career as an actress/comedienne.', '1993-10-11', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
