INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9A161250E4AF4E1CB3FFA76B9B7D7E57', X'1D713CA64E174F84949C8CFD98514127', 18, 'Pawn Fiction', 'You never can tell with the Pawn Stars when a cast jacket from Pulp Fiction dances into the shop. Can Rick walk the path of the righteous man for this piece of movie memorabilia or will it end in uncomfortable silence? Then, Corey goes solo when opera gloves signed by Hollywood legend Clark Gable are brought in. Will he be able to hit the right note with this deal or will the fat lady sing? And later, Rick heads to well-known Las Vegas legend Lonnie Hammargren''s home to check out his collection of unique items. Will Rick hit the jackpot or will this treasure hunt turn into a wild goose chase?', '2014-09-25', 21, '/epcX8KYY1majk2GUDH5s42HRFvM.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
