INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9A3994732D4945968761DEAA0D5D08B7', X'D589B6702E7549229F56029B48E54927', 13, 'Tell All: Part 1', 'In part one of the Tell All, nothing is off limits as the Browns discuss this season''s jaw-dropping moments. Has Meri''s dream of buying a B&B driven the family even further apart? With Utah''s tough new polygamy law, can the Browns ever go home?', '2018-03-25', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
