INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B2ACF0C76E64F81AD98566993AA2960', X'63F9BF6D39B344F4B885A56807277A80', 1, 'The Muppets Valentine Show', 'The Muppets Valentine Show was a variety special that aired on ABC.  Internally, Jim Henson regarded this as a pilot for what would eventually become the The Muppet Show in syndication. Although a later special,  The Muppet Show: Sex and Violence, would more closely resemble The Muppet Show in cast and content,  The Muppet Valentine Show would introduce several characters who would become regulars on that series, as well as the concept of having one human guest (Mia Farrow), and a tone aimed toward both adults and children.', '1974-01-30', 26, '/xlAi5m8PrID9FoxFAYb2lzftTXv.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
