INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B35379A40C54E19ACEAE0165148051D', X'BE719633FBF14DF587E42DA02389F497', 11, 'Dry Stone Walling', 'Neil comes across a man carrying rocks to repair a dry stone wall and offers to help with Rosie and Jim secretly also helping.', '1999-03-30', 10, NULL, '2026-04-03T17:19:39Z', '2026-04-03T17:19:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B36EDF2BBD440DBAF4F643212513B7B', X'3269A890BBA94E6C9278F7EB38EB1720', 8, 'Friction', 'Friction is a force that slows moving things down and turns the moving energy into heat energy. When two things rub together, like your bike tires and the road, friction between them slows you down. There’s also friction in the metal parts of the wheel’s hub – at the center. There’s even friction between the fibers and rubber of the tires themselves as they flex and roll. That’s why you eventually stop rolling when you stop pedaling. Rough things make more friction than smooth things. Rubber shoes on a clean wooden basketball floor create more friction than do hard metal skate blades on smooth ice.', '1995-03-31', 26, '/kKBsJFrgNmoIa8EZ3qyA4ZOaS96.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
