INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B463D53D48942BEA103E41571423A65', X'2E6EE129B32E4417950056F1CC9BC434', 7, 'If You Give a Mouse a Cookie', 'One thing leads to another in this episode, with LeVar in a bowling alley, showing how certain actions lead to consequences. Included is a piece on an expert at domino displays and domino art. Beth Howland reads "If You Give a Mouse a Cookie," the tale of a little boy who offers a cookie to a mouse, and all the events that occur afterwards as a result.', '1993-10-19', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B46F47E072243279B274A2BCC079660', X'F4C403079B5E4263A4E0DFA138131E7F', 56, 'Springtime Fun', 'That loveable little red muppet Elmo is back to entertain and educate the hordes of children who love him! In SPRINGTIME FUN, Elmo gets out his colorful bike and protective helmet and rides through the natural wonder that is spring, pointing out friendly flowers and insects along the way!', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B50BC1798674A5A969225F2B5E1FCEA', X'4861CE46904543C7963F27B4EA539804', 33, 'Episode 163', '', '1970-12-23', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B512E3EF8D54FA589101CEA79F22761', X'994C75E506FA4BE1A142EA7B2C892DD0', 4, 'Curiosity: Tony''s Costume, Book and Toy Shop', 'Rogers gives a final discussion on false faces. He then visits a new studio set, the toy-and-book store run by a new neighbor, Tony Chiroldes. In the Neighborhood of Make-Believe, everyone is still looking for Little Panda and Prince Tuesday. Betty Okonak Templeton uses a telescope, as do the others, to discover just the planet to seek. It is up to HulaMouse to rescue Tuesday and Little Panda.', '2000-09-07', NULL, NULL, '2026-04-03T17:35:49Z', '2026-04-03T17:35:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B56B08632844AC6B497B916E60FD61D', X'363A94F9E0E5441CAA862BE2E9832DA1', 4, 'Appetite for Pawnstruction', 'Corey has an appetite for a deal when a Guns N'' Roses collector box rocks into the shop. But will Corey end up in Paradise City, or out in the cold November rain? Then, Chum gets flap happy over a pair of signed lawn flamingo prototypes. But will their unusual color leave him in the red? Next, a seller asks Corey for $250,000 for a rare Batman comic. Is this a joker, or a dynamic deal? And finally, Rick and Chum go goofy for a unique children''s bike featuring Donald Duck. But when the restoration reveals a surprise discovery, will the feathers fly?', '2021-10-23', 42, '/93FXwoSEvCo1vk2DYfmKTPgRTZ0.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B5A67299A794449903F2804466F2268', X'6C1EC19F74DF4F359A6117B98175D826', 7, 'Santa Denise', 'What promises to be a relaxing trip to Santa Barbara instead opens old wounds for Dorit, Erika, Teddi and Kyle. After feeling judged as a mother, Lisa Rinna turns the tables on Denise, forcing her to examine her own history of risqué behavior. Meanwhile, Garcelle weighs the pros and cons of being a working mom as she prepares to leave town for a job.', '2020-05-27', 43, '/udal2F9fLc7weYlq4ECBIKjq4Fq.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B5B853851B04971A690D8B920B19EAF', X'4FE93658C46343298E649D523869C2CB', 5, 'Cornering the Colonel', 'The Pawn Stars have an opportunity to buy the iconic suit of Kentucky Fried Chicken founder Colonel Sanders. Will they dig into a family-size deal and fork over a bucket of cash or will they find out they''ve bitten off more than they can chew? Then, a man brings in a Presidential commission from the only U.S. President to serve two non-consecutive terms - Grover Cleveland. Will Rick make an executive decision to secure this historic document or will the deliberations get vetoed? And later, Corey and Chumlee check out an old arcade punching bag game measuring a player''s punching power. Can Corey score this vintage game by way of knockout or will a sucker punch send him down for the count?', '2010-09-13', 21, '/AmmP33wNdN6yvzyxX7IAZMjCs7Q.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B62B2E4AAFB42D7B52D1A972BEB73DA', X'3EE646E823AE4DECBBC6C7E6A210D55B', 122, 'Elmo fills in for Little Jerry', 'Elmo observes Mike talking with rock stars Big Jeffie and Little Chrissy, who will be performing at Mike''s high school dance tonight. However, lead singer Little Jerry has caught the chicken pox and can''t perform, meaning they''ll have to cancel. Mike suggests he could fill in.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B6B6F31812141E0B8FFB39F7CE03A06', X'4D2CAC0F38FD438B8AFAACF43952E535', 105, 'Episode 105', 'A magazine programme for younger viewers.  Introduced by Christopher Trace and Leila Williams.  Including How Other Children Live: 6: A Day at Ole''s Farm, a film produced by the Danish Television Service, Making Your Own Den shown by Tony Key and Packi''s Caravan: 5, Told and drawn by Tony Hart.', '1960-10-17', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B6C2B5A162F469CA6A80222A48AA4A9', X'3D4E0E451C67475EB37D9E7E6B8B942A', 5, 'Bone of Contention', 'Joe and David''s friendship is tested when they both are interested in the same girl. Wishbone, as John Alden, and his best friend have to decide how valuable their friendship really is in Henry Wadsworth Longfellow''s poem, ""The Courtship of Miles Standish.""', '1997-03-07', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B7EDE91A77F449CA30FD4D1EF8C6D22', X'4B4D327B6C8B459C9E73B1D4D84AED77', 2, 'Too Small for the Team', 'Sister wants to join the girl''s soccer team, but Coach Brown thinks she''s still too young to take part because the cubs are bigger than her. Sister grudgingly accepts the position of team manager instead. It''s a tough job, and Sister''s perseverance doesn''t go unnoticed by the coach, who ultimately invites her to play in a big soccer match when a team member goes home sick.', '2003-09-17', NULL, NULL, '2026-04-03T17:40:22Z', '2026-04-03T17:40:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
