INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B94D73102F843E496C58191D3E33255', X'9C9D89DF5F6B41D084C6B8CA7BD2A2E6', 20, 'Friendship Celebration', '', '2022-03-24', NULL, '/rPkVMdTFrbidFhtHtTTLPmZSnTU.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B9548F74E4247259B7C3F83B9259520', X'B054AFF3548C4F56B372B1EA26613ABB', 9, 'Mister Rogers Talks About GAMES', 'Mister Rogers arrives with a small cooler containing an ice cream bar shaped like a gorilla. Taking a bite, he explains that foods that are shaped like animals and people are very different from real animals and people. This leads into a shortened version of Everybody''s Fancy.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9B9F073B5F6E45A2A63E783F9FF9FA81', X'87F8406382B345A4936C3759E5D91CE3', 9, 'I Was Driving Carpool!', 'Mary hosts a cooking class and confronts Whitney for missing her call and disobeying the dress code. Heather meets with her once devout Mormon niece and Lisa defends her son’s charity guest list. Finally, the ladies get ready for their trip to Vail; but before they depart, Jen receives an urgent call leaving her friends shocked and concerned.', '2021-11-07', 64, '/a26RE6viI68NksSSrK9NcIkLRNe.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BA9E2973AA9448ABABC2803070969B1', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 20, 'Motion', 'Things can appear to be moving, when they really aren’t. Sometimes an object might seem to be at rest, even when it is in motion. It’s all relative. Relative motion, that is. How things appear to move depends on how you, or any observer, happens to be moving. So, if you’re on a bus looking out a window into another bus, and your bus begins to back up slowly, you may think the other bus is moving forward, when really it’s not moving at all. That’s motion in motion. It happens all around us all the time.', '1998-06-20', 26, '/uCN9i3i90LoSxBPgJgnjMiNB7iS.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BAD6E2DF2BC4AD6AB25ED1FDD7BAF4D', X'D405F9734C7E4CB6B7C0D09A884C9B35', 16, 'L.O.V.E. Duel', 'LuAnn hosts an anniversary party celebrating her one year of dating Jacques. Among those invited: all the Big Apple ladies and songstress Natalie Cole, who offers to sing a tune—with LuAnn. Meanwhile, Ramona throws a dinner party and discloses that she wants another baby.', '2011-07-21', 42, '/lQAlNVepCdLc0afQuHTNVi5tSnX.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BB798902E484CA6AB3ECD6313B82E44', X'EA73E13C696248048305C303DF65F89F', 30, 'Reflections', 'King Friday and Queen Sara return to the Neighborhood of Make-Believe to find the disguised Joey Hollingsworth and Lady Aberlin.', '1969-03-21', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BB7D7BE14B24340B20E51F41CE90AE8', X'5DB3FF78E43948E18F67988ECBF85D17', 9, 'Juliette Kidnapped', 'Once Dogtanian has realised what''s going on he sets out with Planchet and Sandy, ''the only horse with the nose of a thoroughbred bloodhound'', to find Juliette. They search but have to stop under a tree and continue in the morning. Juliette tries to escape from the house she''s being held in, but is caught by Rochefort''s squire and tied up. Although tied up Juliette still tries to escape, she moves to the window and signals with her mirror...', '1981-12-04', 24, '/uD4mm2IS1C9Dqyj6SDTo84CxJNc.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BB91B54CC324A72A9CE00C02923E5A2', X'3EE646E823AE4DECBBC6C7E6A210D55B', 16, 'A rainy day on Sesame Street', 'It''s a rainy day on Sesame Street and nobody appreciates it more than Oscar the Grouch. Elmo wants to see a rainbow and studies the ground below.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BC1180CC0F347A188FE850140ABE8FA', X'54900370898846B8B7AA61D2B88D7056', 10, 'The Higher the Hair, the Closer to God', 'Whitney throws a High Body Count surprise party in honor of Britani, who is touched by her friends’ outreach, but gets a rude awakening from Jared. Bronwyn and Lisa have difficult conversations with their husbands. Mary prepares to reopen her church and strives to be a bedrock of support for her son. The group is reunited for the first time since their return from Canouan.', '2025-11-18', 42, '/6wUo3H0s16s5a7KCNYaq6J4NZv4.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BC36F0D79FF43F5BECB593AAEA6C373', X'70C8CB4624944DD498F66BFB9B3FAF73', 32, 'Phoning It In', 'The Pawn Stars have a chance to purchase a rare piece of American political history - a collection of personal letters from Kennedy brothers John, Bobby, and Teddy. Written during the height of the Camelot era, will the gang run a tough campaign to make a deal or will their election funds come up short? Then, Rick and Chumlee visit a man hoping to sell an enormous toy collection of 80''s iconic original Transformers. Can Rick transform this collection into cold hard cash or will this army of robots decept-and-con him? And finally, the Old Man is presented with vintage Mickey Mouse telephones. Will he dial up a great price for these collectible Disney pieces or disconnect the line?', '2010-07-12', 21, '/kWPJiLujmW9kBcz7DDtbY6UjvRq.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BC41E6172F74032B4D5628DED3E4BFE', X'9BD388DEF7FB4A7084583DB458A2ABF0', 5, 'Sharing', 'Mr. McFeely shows a videotape on how heavy equipment is used in construction sites. In the Neighborhood of Make-Believe, Lady Elaine agrees to display and return all those "borrowed" things. But there is a trick or two involved.', '1997-09-05', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BC6C8284AF84C399E0BE09918439A7D', X'A9657E86413549CEB1F9C295113077E1', 3, 'Rise and Bloom', 'Max wants to see the Bursting Blossoms event in Dragon Land, but it happens at sunrise and he''s afraid he''ll sleep through it.', '2005-02-22', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BC6F9B87F5043CCBAD4F4E7F0E5CA27', X'150D1480F3F143F99A22D2527756FBA2', 6, 'Land of the Free, Home of the Shade', 'Ashley and Michael adjust to caring for two children while on a family photoshoot; It''s Candiace''s first time hosting a girl''s trip, but the mood dampens after Gizelle and Karen''s issues resurface again.', '2021-08-15', 42, '/e44OwCVrWUHdLuN82aKxJ8ImJqU.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
