INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BDEB91E7F5F41C1ABF2303E5F07F270', X'136B81D3964D4B8FA21492F00D96D6B9', 10, 'Dr. Nobel Price \"discovers\" the law of gravity', 'Gilbert and Sullivan sing "The Letter B" while Oscar plans a vacation with predictably Grouch packing. Dr. Nobel Price drops his teddy bear repeatedly and declares he''s discovered gravity, ignoring Olivia''s attempts to explain it.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BDFCB330B504C6A9FFAC0C3DADABD82', X'C73FA7F17AC644D4AC1F182A70D92313', 3, 'Car Wash Chaos', 'When the kids set up a car wash competition, Sarah finds herself trapped in Nurse Flood''s car when it rolls into the sea at the beach with the tide coming in. Time to call Ocean Rescue!', '2021-10-05', 10, '/lE17DN9UHNzxF03kh7JaylsJzAr.jpg', '2026-04-03T17:14:41Z', '2026-04-03T17:14:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BE6C5FAD83F48CF9535058A0C717F74', X'45E01C046AC641E187D8F749EE230385', 29, 'Episode 29', '', NULL, NULL, NULL, '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BE7CA027BAF44AB96D72ACD561CCCF6', X'110E346736984E19A35BF6EBBAEB4D6B', 1, 'The Three Little Pigs', 'If you work hard you can overcome the most formidable obstacles. Thats the morale of this most popular of fairy tales. Billy Crystal and Valerie Perrine are in trouble when they come up against Big Bad Wolf Jeff Goldblum. Billys older brothers just miss ending up on the wolfs plate by the hair of their chin-ee chin chins when he blows there houses of straw and sticks away. Billy the more practical pig, takes his time and constructs his house out of sturdy brick. when the cigar-chomping wolf arrives- he huffs and puffs but can''t blow Billy''s house down.', '1985-02-12', 51, '/rcfS6BSTnQxOzgYqhXgNiWHVNoL.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BF1865721E84C8B8943F62B4468490D', X'C9D2B3FB78454F3C9847CE1F7717257A', 17, 'Rebel Without a Pawn', 'Corey and Chumlee rock out with personal memorabilia from legendary AC/DC front man Angus Young. Next up, Hollywood rebel James Dean''s ID bracelet finds its way into the shop before Rick heads east to score big with a rare relic from WWII.', '2019-07-22', 42, NULL, '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9BF840E7544B4120B4741F49416FD2E4', X'F21CA545466C448CADA5B8ACC8B856DC', 13, 'Ending Time', 'Bernard wakes up on New Year''s Eve to find that his watch has been stolen by an arch-criminal Mr Rattle. Mr Rattle is mean to Bernard and his mother knocks Mr Rattle out with a vase. When he finally gets it back, the villain''s deeds have made the watch stop working. Could the new millennium be the end of Bernard''s watch?', '1999-12-17', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
