INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9C125BF64B88490892447E0BD534D133', X'6A2D283971064C3B8906C9B3E4BFCC8B', 19, 'Reunion (1)', 'Andy Cohen hosts as the California ladies come together to deal with the big issues and conflicts of the season.', '2014-09-25', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9C14F217CA0B4FEA973237DA7C588C3C', X'66A11A09AEE24A7B8543AB080A9D1BE4', 6, 'Medford, 90210', 'Lisa Rinna returns to her hometown of Medford, Ore., to visit her ailing parents; Eileen gets a chance to meet everyone at Kyle''s barbecue party; Brandi pressures Lisa Vanderpump for an answer about her housewarming party.', '2014-12-23', 42, '/dUI0155h5i3mvIYjLOzPB9xyoYA.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9C1D45F97B924DE28449C5D34469E1D1', X'0E4196154C964DDE8ED2715770BA77BB', 24, 'A Strange Bird', 'One morning, Bear decides to visit the post office, knowing that Jeremiah can be slow in delivering the mail and wondering if anything''s come. At the post office, he finds a two-week old postcard that reveals that a penguin named Puck from the South Pole is paying a visit to the Big Blue House --- today! Bear hurries home to greet Puck. Everyone there is eager to meet him, but the kids begin to worry when they find his food tastes and his behaviors somewhat odd. They try to play with him, but worry that they just don''t understand him. Meanwhile, Tutter learns all about diversity at Mouse School. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9C2155AE70904E5D9992D7725FA4978C', X'E93F04C273444B93ABBA8BA1B2F8EB35', 54, 'Episode 589', '', NULL, NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9C21667FF43B49CD9F88BCF35FE9C959', X'20D7138EEEA846A88ADA2B0F0EE1F674', 45, 'Episode 45', 'What do a bent knee dolphin, the flamingo position and an inverted vertical with support sculling have in common? Sarah discovers the answer when she joins the girls of the Rushmoor Synchronised Swimming Club.', '1983-02-17', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9C23719397ED47C39125AC5A9310AC37', X'C21DBD225E2E4414BB67750399AAF6F0', 27, 'James Gang Rides Again', 'Gang up with the Pawn Stars when original photographs of Old West outlaw Jesse James ride into town. Will the guys break the bank on these incredibly rare items, or will the seller make a quick getaway? Then, Chumlee and the Old Man get an earful when they''re presented with a Leslie organ speaker from the 1950''s. Can they turn up the volume on this negotiation, or is the deal too far out of tune? And later, a guy walks in with a Boy Scout first aid kit from the 1930''s. Will Rick be prepared to make an offer, or will he think it lacks merit?', '2012-02-27', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9C2428D7F35E45D8AA90DDE2979D216E', X'9193E795DA7C40ECB68FF63AA7D5174F', 100, 'Histories & Lore: The Unsullied', 'Jorah Mormont recounts the legendary Battle of Qohor, in which three thousand Unsullied slave-warriors held off an entire Dothraki horde outside the gates of Qohor.', '2014-02-18', 4, '/jAGQIhdM7zCPs5R4ad0zG0FD6g.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9C2480DA074A43E6B6E850538394BD53', X'70D9E39768134785887D27D034928BAE', 23, 'Pingu and the Postcard', 'A postcard is delivered which Pinga picks up. On it is a picture of a Hawaii beach fringed with palms. On the beach is a dancer who is wearing a garland made with pretty flowers, and a drummer. Pinga shows the card to Pingu, and says that she wants a garland of pretty flowers. Pingu is not sure that he can do anything about it, but Pinga points out Mothers lovely pot of flowers. Pingu goes over to the pot, takes off all the flowers, and makes Pinga a garland with them. He then takes off all the leaves and uses them to mimic the palm trees. Finally he empties the pot, throwing the soil and stem aside, and turns it upside down. He uses the upside down pot with a pan from the stove, which makes a good sound when banged with a spoon, to make a drum. He then plays the drum he’s made while Pinga dances. Mother then arrives home and at first enjoys what she finds them doing, but passes out when she sees what has happened to her plant. Pingu and Pinga rush over to her and are wondering what to do when Father arrives home. They seat Mother in a chair, and Pingu and Pinga explains to Father what they have done, and why. Father goes to the florist and gets a replacement pot of flowers for Mother, who is delighted when she revives and sees them. Mother and Father then enjoy a repeat performance given by Pinga and Pingu.', '1996-08-15', 5, '/iCdb9CsMI6O779iyvw3GMiSr44c.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9C26E0D466E349A09289A29DD63BDD2D', X'05C0E384194C44179F62803EB615E409', 67, 'Dedication at the Rockit Factory', 'Title number 0067. Opens with Mister Rogers arriving with a yoyo. King Friday is ready to dedicate the new factory, but Lady Elaine senses he is afraid of elevators. This changes some of the dedication.', '1968-05-21', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
