INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9C92631D745E44649ABE05BAE71536A3', X'DA06465B91544FEBA455374DF7DAB02F', 19, 'Elmo and Zoe Claim a Ball (4104)', 'Zoe and Elmo find a ball on "Sesame Street" and begin arguing over whose ball it is. They both keep saying, "It''s mine!" Luis then enters and explains that instead of arguing over whose ball it is, they could have fun with it by sharing, taking turns, and playing together. While Zoe and Elmo are learning to share and take turns, Baby Bear comes in and is so relieved to see his ball! They all begin to argue over whose ball it is again until Zoe and Elmo are finally convinced when Baby Bear shows them the letter "B" that he had marked on the ball for "Baby Bear." Baby Bear could see that Elmo and Zoe are sad to see the ball go so he decides to share the ball, and they all realize that taking turns and playing together is even more fun than owning your own ball.', '2005-09-20', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
