INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9D567A61D5124B059CD99D44D4A72554', X'5C4E51C6E20746AD875C72988EB1E13E', 12, 'The Great Escape', 'The Pawn Stars take the stage when a Harry Houdini straitjacket magically appears in the shop. Will the guys be tied up with a locked offer or will they narrowly escape with their wallets intact? Then, a guy slides into the shop with a loudspeaker from the former home of the Brooklyn Dodgers - Ebbets Field. Can Rick make the call to buy or will some painfully high-pitched feedback get him booed out of the shop? Then, a man comes in with a letter written and signed by Helen Keller. Considered one of the most amazing women in history, will Rick over come all odds to secure this piece or will a suspicious pencil signature end negotiations?', '2011-05-09', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
