INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9D78D6D256094D6BB9CD9D3F4BDF8151', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 35, 'The Count counts counts', 'The Count becomes obsessed with counting and recounting, driving friends crazy with his numerical enthusiasm. He finds endless joy in tallying everything on the street.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9D7AE2FDC0974A4F8A3D2F233FAFF263', X'87F8406382B345A4936C3759E5D91CE3', 1, 'Best of Frenemies', 'The women of Salt Lake City return and fractured friendships have split the group in two. Caught in the middle, Lisa tries to get Jen and Meredith to make amends. While Heather prepares her daughter for college, Whitney throws a birthday bash for her stepson and Mary starts a podcast. Lisa’s friend of 10 years and new housewife, Jennie is introduced.', '2021-09-12', 44, '/2x3fp4NB6zyKXB11G198jXWY5rH.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9D808C06F62D488D9F43CCB8DAB0F2B2', X'79916E0E881C43A7B4EE00E5052A94BE', 26, 'Theodore''s Backwards Day', 'While working Theodore''s engine breaks down thus resulting in him only being able to go backwards. This incident makes him feel embarrased and so decides to try and hide from everyone the fact that he can''t go forward.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
