INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9D889CDCA7FA450FAAB4475AAF28B1FC', X'D199804FCCF54E36892956C1E356B74D', 99, 'Episode 1024', '', '1977-04-14', NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9D8B7A47BDBD4AA1845B58C4E577B502', X'3A96D6C63736498A926F6C479CDFB73A', 11, 'Franklin Fibs', 'All of Franklin''s friends can do special things.  Franklin can''t seem to think of anything he could that his friends couldn''t so he made up that he could eat seventy-six flies in the blink of an eye.  But didn''t realize fibbing could also get him into trouble.', '1997-11-27', 12, '/4zBIZb0M01FmzHSvRWBuETvWAiJ.jpg', '2026-04-03T17:40:14Z', '2026-04-03T17:40:14Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9D8BBC5E2DAD4516ADFC1C4367E17597', X'5BA20443D99F482081F66832D3F2BC4F', 6, 'Spiders', 'Be sure to get this straight: spiders are not insects, they’re arachnids. Spiders have eight legs, and insects have only six. Spiders have two body parts, a head and an abdomen, while insects have three body parts, a head, a thorax, and an abdomen. Insects have antennae, and spiders do not. Some insects sting. All spiders have fangs and venom. There are almost certainly a few spiders in the room with you right now.', '1996-01-05', 26, '/rvXlFxeOgSm7kJtWuUOpj9oZl7Z.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9D905C692C834951A210FADF07CEC46B', X'6D2B78D726124AFB81CADEE774AF9C2B', 15, 'Making Mistakes 5', 'Rogers goes to Brockett''s Bakery for a sing-along. The Neighborhood of Make-Believe stages its much-anticipated poetry reading, with Audrey Duck at the center of attention.', '1987-05-08', 30, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9D9643EF17524BEFB587964F51BEF7D0', X'BFDF87FF01DD4B5494BD19B384F41BDB', 5, 'Boogie Fights', 'At Shannon''s 70''s-themed party, disco fever takes on a whole new meaning when Shannon gets into a heated argument with Kelly about her rumor-filled past. While Vicki juggles work, babysitting her grandsons and nursing Briana back to health, she still finds time to "whoop it up" with the ladies, at least the ones who are speaking to her. Heather confronts Terry about his lazy parenting after he schedules a work trip for Mother''s Day. With Jimmy out-of-town again, Meghan looks for support from her friends during her IVF treatments. Tamra tries to help Kelly mend fences, but winds up stirring the pot instead.', '2016-07-25', 44, '/43MdZqGubwm0Tg8xLfy3fI84lc9.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9D9BFFD218E546039974E16B33E0BB4A', X'227B84290DFD47E4B874C37DA20C403F', 2, 'Confederate Conundrum', 'An 1861 Civil War saber finds its way into the shop - but if it''s real, why was the blade never sharpened? Then Rick and the owner of a Chuck Berry autographed Fender guitar find themselves on different pages when it comes to bartering over this item. Finally, the Pawn Stars appraise a "1916 National Cash Register." It looks real, but will they pull out the money from their 2009 cash register?', '2009-07-19', 21, '/r8q0vyNSXHJleBH0ZKeUeyZQBcO.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9DA34F3ECDBC4E8E9DD100BFB542DD38', X'095258D0D8DB40968AC76A42CD4CBDCF', 2, 'Red-Handed And The Invisible Thief', 'Red absolutely loves her radish bars (which are the equivalent of Pop-Tarts in our world). So when she sees that whenever she wakes up from sleeping that her bars are missing, she sets out to find the crook, which leads her to think her roommate Mokey stole them. She also gets Gobo to hide in a hole outside her room to watch and see if it really is Mokey; after Gobo gets distracted from reading a postcard, the bars go missing again, but Gobo claims he didn''t see anything. So finally she gets Wembley to stay the night with her to catch the thief, and what Wembley finds ends up being quite surprising.', '1985-01-07', 24, '/cDfFezzPJ4HLw2LZ59tBHFcc5N3.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9DA3B2A168694139BD06908FB20B6835', X'4060AD7F4B8F43938EB166A150B928B6', 19, 'The Bike Shop Music Band', 'To help attract new customers to the bike shop, Nina and her friends make musical instruments out of bike parts.', '2021-03-18', 26, '/kMuuEfQ686xh9vYyvpuXYnPmeES.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9DA8752098C043398B61EF5F4A8D26C9', X'9193E795DA7C40ECB68FF63AA7D5174F', 88, 'Histories & Lore: House Greyjoy', 'Theon and Yara Greyjoy divulge the history of the ironborn and how House Greyjoy became the dominant family of the Iron Islands.', '2013-02-19', 3, '/vO6Z7upn9yPUOXJ2azxr0z1qxqx.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
