INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9DABA15C1D9B485E8DE64B0F46791A7E', X'7C422193B07849D881EFF2B9F94F059D', 54, 'Natasha can''t fall asleep', 'Episode #3059', '1993-01-21', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9DB0103609724BEA81CBF8DD40FACED1', X'B1D55597D9D24EEEAB9546DBB163291A', 5, 'Pingu Goes Fishing', 'Pingu is going fishing; he climbs down a series of cliffs into a craggy, secluded area and finds an ice-fishing hole. He catches a fish, but he is unaware that Robby the seal, behind him, is emerging from another hole that the one Pingu is fishing at connects to, eating the bait, and snatching and attaching the same fish to the line each time. Pingu finds out and foxes Robby by luring him away from the ice holes and closing them off with large slabs of ice. A high-speed acrobatic chase ensues and Robby tries desperately to escape the young penguin by forcing his way under the ice-slab which stands between him and freedom. When Pingu tries to stop him by shouting at him, Robby''s right flipper briefly gets trapped, and the weeping seal seems severely hurt. Pingu is struck with remorse and sympathy, consoling Robby before his flipper is ''miraculously'' healed. Robby recognizes the goodness in Pingu''s soul and rewards his sensitivity with a much larger fish.', '1986-06-25', 5, '/bCjJOWji3YV9maKk0ERu1irE4O2.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9DB537E1443E4CB0A3B3B46C3F5DFA12', X'EBC99729CCB74D6482C142708CD7BA85', 26, 'Episode 26', 'Peter joins a team of men with one of the most dangerous jobs in Britain - the crew of the fishing boat Fruitful Harvest. Seventy miles off the coast of north-east Scotland, skipper Robert Reid and his men battle with Force 9 gales and 30-foot waves as they haul in their six-ton catch.', '1980-12-04', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9DB60D12922D4E0FB660069C823F8FA5', X'DBDE6570A68D4FD7A1B0A6037A266A18', 12, 'Bombs Away', 'In Las Vegas, and in front of the other housewives, Gretchen performs with the Pussycat Dolls. In spite of Jim''s objections, Alexis continues to follow her career path, while Vicki treats Briana and Ryan to dinner.', '2012-05-01', 44, NULL, '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
