INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9DC2A5B323F34B69BF99F575ED32B3CB', X'4F3632B8A91046B6B2EDF2882CC14B2D', 13, 'Snuffy''s Invisible (Part 1) (4069)', '', '2004-04-21', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9DC2E969CEE84CC1BC6C9EEE0160251E', X'D5383B3D56364D71B99CB84774B4B3C6', 1, 'Pingu''s Disadvantage', 'Pingu is out on his sledge. He sees some skis and an ice hockey stick lying at the bottom of an ice tower, stops to investigate and finds Pinga, Robby and Pingg playing hide and seek. Pinga has covered her eyes and is counting, while Robby and Pingg go to hide. When Pinga has finished counting, she turns and is about to go to look for the others when she sees Pingu. Pingu tells her where Robby and Pinng have hidden. Pinga calls out to them, and rushes back “home” before they can get there, so they lose. Pingu thinks this is funny, but Robby and Pingg are annoyed. They let Pingu join in, but he has to be the one doing the seeking, so Pingu counts while the others hide. There’s no sign of them when Pingu turns, so he goes to look. He hears Robby, and goes towards the sound. Robby hides behind a nearby ice tower as Pingu looks for him and goes past. He comfortably beats Pingu “home”. Pingg and Pinga are already there, so Pingu loses! Pingu, reluctantly, is seeker again. This time he cheats by turning while still counting so he can see where they go to hide. Despite this he can’t find them, and is puzzled. He spots a discarded ladder nearby, and props it up against a nearby ice tower so he can climb to the top to get a better view. While he’s climbing the ladder the others come out from behind the broken barrel that was near the ladder, and easily get home first. Pingu loses again! On the next turn he tries the same trick with the counting, but this time goes straight to the ladder and starts to climb. What he doesn’t know is that Pingg and the others have hatched a plan. Pingg has hidden behind the barrel where he was before, and sees exactly what Pingu is doing. When at the top of the tower, Pingu spots Robby’s tail sticking out, and goes to get down from the tower. Pingg, however, has removed the ladder, so Pingu is stuck on top of the tower. The others join Pingg at the bottom of the tower and, when Pingu asks, won’t put the ladder back. They then rub salt in the wound by getting home while Pingu can do nothing but watch. They all laugh at Pingu. Pingu then slides down the ice tower.', '1998-01-05', 5, '/kTI3H2md0msntJVSweUSfK78zYM.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9DC2FB00559447178F26D243F7E67E52', X'45E01C046AC641E187D8F749EE230385', 4, 'Fireworks For Mandy', 'While playing hide-and-seek in the mountains with Norman, Mandy finds a distress flare. Norman wants to let it off but Mandy resists, fearing that it could be dangerous. When they discover Penny stranded on a cliff, they use the flare to raise the alarm. It is up to Sam, Elvis and Tom to rescue Penny.', '2008-02-14', 10, '/gbqIs33sqcTH6yJZ5JqeUudhSsQ.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
