INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9DD3250B6A46418699E0C994240E9C30', X'650BAC937B5941FCB277DC6F8BDCD7BB', 10, 'Escape Orson', 'The Hecks find themselves spending New Year''s Day attempting to stave off a zombie apocalypse in the Orson Escape Room, desperately trying to beat the Donahue''s record of getting out with more than one minute, eight seconds to spare. Meanwhile, Brick is convinced that the mild-mannered man assigned to the family''s Escape Room group is really the famous author of the "Planet Nowhere" books; Sue divulges a secret about herself to Axl that''s she''s been keeping since childhood; and Mike is stunned when Frankie reveals that she had a romantic dream involving Frank Sinatra.', '2017-01-03', 22, '/fdBm6pGYiijfnxBrySNVoRNDHcS.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
