INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9E031524632E4BCA89A05210B17333F1', X'61E0C9D9337E4FE4A0FDE567B29AF115', 7, 'The Huzzbands', 'Angie''s anniversary party leaves the group at odds, causing Bronwyn to question who she should invite to Palm Springs. Justin and John work to resolve their issues. Angie takes Heather to task for misrepresenting her comments about Lisa and betraying her trust. Meredith finds herself in conflict with Angie''s husband, Shawn, over a podcast and reveals she''s facing challenges in her marriage with Seth. Bronwyn invites Heather over to make amends, but things quickly go awry.', '2024-10-30', 43, '/bCUDOeeSsYr45VXyjP5SPJbt1u9.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
