INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9E46DA5315724BFE95EB05116E6770AF', X'5B72E664D3D7435DBDC3A23D29D1178E', 2, 'The Boat Race', 'Old Bear and his friends are playing in the garden. As Bramwell is making pirate hats with scraps of newspaper, the toys think it would be a good idea to have a boat race. First of all, the toys have to build their boats, (although Sailor already has his own) then, when they are ready, they launch them in the stream and the race begins. It doesn’t go quite according to plan but a spectacular air/stream rescue by Rabbit saves the day and it isn’t the biggest boat that wins the race.', '1994-09-13', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
