INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9EA30757446049808A1481AC8185BB48', X'EFDF1E4F84764382A9D72B9DA4188BE0', 20, 'Brave and Strong', 'With the crisis at the Neighborhood of Make-Believe over, Daniel asks that his pile of fallen cereal should be distributed to the people who need it most. A forklift is just the tool to cart boxes of cereal from the Clock. Maggie Stewart Stops By With A Film Of Mr McFeely Painting A Picture Of Mr Rogers', '1996-08-13', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
