INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9EAC0ECE32064DFB87CE2388861C1AEE', X'F30BBF8187704E74B68B280E7C85B52F', 5, 'The Apartment', 'Kramer tries mousse in his hair. Jerry gets Elaine an opportunity to get the apartment right above him, before he realizes the possible implications. George tests the "man with a wedding band" theory of meeting women.', '1991-04-04', 23, '/njzSUcIpCle3ZU0dk7FiPzKvbEi.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9EB157D24F6747188221919E40CD9533', X'E2AA315868E5494F951A498CA0518DBB', 1, 'The Stand Off', 'It''s breakfast time and The Farmer discovers he has no fresh milk for his morning cup of tea. He sets off in great haste, only to become ensnared in a ''rush hour'' traffic jam. Shaun and The Flock are too impatient to wait for breakfast and take matters into their own hands.', '2012-11-30', 7, '/scjCuaLj4tmBMti9JUlNfvvLQbS.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
