INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9EE4DA2CB610470B9C368FAC2D2E37A1', X'DB81AD4293A7492689E5D4CEFA257B83', 4, 'Dog by Night', 'At a flea circus, a rare Transylvanian flea named Count Dracumite sinks its teeth in Pete, turning him into a werewolf at night. Not only is he in love with Fiona''s dog, but Pete may have to stay that way.', '2001-02-21', 24, NULL, '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9EE80D2351C94A789DCA0B95360253C6', X'3FC7C152E4F6426AA89936EC454C4403', 67, 'Up, Up and Away', 'The gang has a great time playing Pop the Bubbles, until Ord’s experiment goes wrong and he is trapped inside a humongous indestructible bubble! Ord cannot get out all by himself because the bubble''s skin is too tough to pop, so his friends find a way to keep him from floating away. They must also find out a way to help Ord get out of the bubble.', '2000-04-20', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9EE8CB838EAA4D389CB07D7D40A41636', X'5C16DB9D5E7140EBB44EF559B2DDB8F3', 6, 'Beauty and the Beast', '"Love can make a man become a beast and love can also make an ugly man beautiful." This is the moving message Susan Sarandon and Klaus Kinski deliver in their memorable performances of Beauty and the Beast. Beast takes Beauty into a mysterious world of misty gardens and candlelit chambers, in this world the shy unselfish beauty comes to know the grotesque beast. The suspense builds as Beauty discovers that ugliness can mask great goodness, and that promises should always be kept ... no matter what the cost.', '1984-08-13', 51, '/j4SQ5ogggTGN63IR5RBpUaoTmQl.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
