INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9EFAD26804F941BB8C33F35D2E4DF074', X'A8F3A6817ABC41E099889B8804D74611', 6, '4 Wives, 4 Valentines', 'What''s the most awkward day of the year for a Polygamist? Valentine''s Day! And how do the Browns handle monogamy''s biggest holiday of love? This year, Kody takes his young daughters to a daddy-daughter Valentine''s dance at their school.', '2012-06-03', 22, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9EFC3CDC7DF14E2BA2314121DF03108C', X'EA1650C2E4F146C793BA74B5D45D08E5', 9, 'Nene Get Your Gun', 'Phaedra adjusts to motherhood as she brings her new baby home from the hospital and proving it doesn''t get easier, Kim wrestles with her daughter''s questions about sex. Sheree decides she has had enough and confronts "the doctor" about his evasiveness. Kandi rewrites "The Ring Didn''t Mean a Thing" to make it more Kim friendly and plays the new track at Kim''s parents'' dinner party. Cynthia plans her dream wedding with a celebrated stylist friend and high-end wedding planner, while NeNe''s marriage nears the breaking point as her relationship problems are exposed in a very public way, leading to a dramatic confrontation with Gregg.', '2010-11-28', 43, '/3ebH50I8GrX1JfqfwN4dCnxtYNT.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
