INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9F52B0CA4F8C47E7806F64C3635D12D8', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 14, 'Where’s The Itsy Bitsy Spider?', 'Elmo, Telly, and Rosita wait for the Itsy Bitsy spider to appear on a water spout in the arbor. Chris loves the song “Itsy Bitsy Spider,” so they all sing it together. After Chris leaves, they decide to find Itsy Bitsy. First, they think about where bugs are found: near plants, flowers, and in dirt. Using the clues, they decide the Itsy Bitsy Spider might be in the garden. When they reach the garden, Telly observes a bug with six legs but they find out it’s a beetle, not a spider. The beetle teaches them that a spider is not an insect, but an arachnid, or a bug with eight legs. They come upon a second bug, but it’s another insect- a hopping grasshopper! The grasshopper gives them the clue to check the spider’s home. Rosita spots an ant hill, but they find out that ants, not spiders, live in ant hills. Then they count the ant’s legs and realize it’s an insect, not an arachnid. The ant gives them the clue that a spider lives in a sticky and stringy place. Elmo realizes that they need to look for a spider web. Telly finds part of a web and follows the string until they reach the Itsy Bitsy Spider! But Itsy Bitsy explains she has more important things to do than sing “Itsy Bitsy Spider.” She is waiting for her egg sac to hatch. Suddenly, the sac hatches, and Telly, Rosita, and Elmo watch in awe as the tiny baby spiders are born!', '2010-11-09', NULL, '/jDlNlPkvaYWOigQeuF2WBBZzSXo.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9F5A791227064C34908B374C88FD8E0F', X'B2317FC31CFC4F19B181EFFA23959C6D', 15, 'Reunion (2)', 'Margaret and Teresa face off while Jennifer reveals new information about the state of her marriage. Jackie sheds further light on her eating disorder. A heated exchange between Melissa, Margaret and Jennifer causes even Andy to lose his patience.', '2022-05-10', 43, '/hwkkbl4u6VUQY0QjD7QDGa7JW05.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
