INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9FD34960982D4E0EA5F6566080DABAC6', X'E40E6B639F84449F8E8853209B0906C8', 23, 'Elmo Shows Abby How to Pretend', 'Abby Cadabby looks for Elmo, and introduces the viewer to her toy frog, Prince. When Elmo sees it, he doesn''t understand how a frog could be a Prince, until Abby explains he was a prince that got turned into a frog. She kisses the frog doll, and POOF! it turns into a prince doll (and vice versa).', '2007-10-08', NULL, '/8C3fbrEtGOkEh1G4rPVAOztwwsN.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
