INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'9FEDEE0581E64B158CBDF4792D58F946', X'63F9BF6D39B344F4B885A56807277A80', 24, 'Disneyland''s 35th Anniversary', 'The celebrity-laden special, directed by John Landis and hosted in part by Tony Danza, focused on the changes to Disneyland over the years, as stars recalled their favorite attractions. Miss Piggy and Gonzo are prominently featured in a story-sketch titled "Pigerella," written by Bill Prady. Piggy, recalling her first visit to Disneyland, longs to replace Cinderella (played by Debbie Carman) in the big parade. After much conniving, Piggy succeeds, after "fairy god-thing" Gonzo gets himself and the real Cinderella lost (though Gonzo seems to develop a fondness for Cinderella). Another sketch involved cast members from Cheers, including Rhea Perlman, George Wendt, Kelsey Grammer, and Bebe Neuwirth; Will Smith, Ernest P. Worrell, and C-3PO also made appearances.', '1990-02-04', 30, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
