INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A08DFF834140451689C3FEEC7D5A5CD2', X'225B0F03984B47F3A1A3D3E92175E39D', 6, 'Episode 6', 'A magazine programme for younger viewers. Introduced by Christopher Trace.', '1966-10-13', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A08E573626DB4513A2AF8A8C39C80F5E', X'C6D5CF79F2B040AFAD1291AA4F1B1D21', 12, 'Samurai, Stones and Skateboards', 'Rick rocks out when a seller brings in a blazer worn by the Rolling Stones'' Keith Richards. Can he get some satisfaction, or will he exile the jacket? Then, Chum brings out his inner warrior when a Japanese samurai mask hits the counter. Will he be able to scare up a good price? Meanwhile, Corey tries to paint a picture-perfect deal when a Norman Rockwell autograph comes into the shop. And later, Rick and Chum head to the range to see a big game gun. Will the duo land this huge deal?', '2022-10-26', 41, '/n20IVHMa7ZYsLeDvys4qMqGuZ2d.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A09116DE69924828B1E4420594F4FD18', X'5C4E51C6E20746AD875C72988EB1E13E', 9, 'Spidey Cents', 'The Pawn Stars call Houston with a problem when they are presented with a piece of the heat shield from NASA''s most heroic flight - Apollo 13. Can the team complete their mission and return to profit, or will the price send them spinning out of orbit? Corey and Chumlee hit the dirt when a seller brings them a classic 1973 Husqvarna enduro motorcycle. Will they pay up to fuel the deal or will an unseen engine problem cause the deal sputter out? Rick and Corey are drawn into a web of intrigue when a customer brings in some original artwork from the comic book "Spider Man." Will the guys find they have the super powers to stick this deal or will their spidey sense tell them to let this one go?', '2011-05-02', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A095D836E6D04854B6585FE6BE0CB5CE', X'573A556EED204222A12DB1B7779E1B18', 11, 'Wild River of Africa', 'The Luangwa River in Zambia includes hippoes, Nile crocodiles and monitor lizards among its residents. Steve witnesses a crocodile feeding frenzy.', '2000-06-19', 44, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
