INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A0B241EC91C54002B2987E177636FAC5', X'0F64BF9F8D054F5B9A575D0C44AC3F40', 8, 'Robyn''s Big Announcement', 'This is a big week! The adoption of Robyn’s kids is coming to a head as the Browns sign official paperwork with their lawyer. Only one thing stands in their way now... a judge.', '2015-10-18', NULL, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A0B305C4DF4D4E2099AE3B4C2D1EDA03', X'56428E5E7DAA468D8BD2076956507AA8', 12, 'Balance', 'Bill Nye''s going to use the force to pull you into the world of balance. A force is a push or a pull. You can feel a force when someone pushes you. You can use a force to pull a door shut. Anyone can make forces by pushing and pulling, and you don''t need to be Luke Skywalker to use a force. In a game of tug-of-war, if the pull of your team is the same as the pull of the other team, the forces are equal. The two teams are in balance, and the rope doesn''t budge. Things are in balance when forces that are pushing or pulling them are equal. If your tug-of-war team pulls harder than the other team, the forces are not equal. The other team falls all over the place. Unequal forces make things move and twist. A lot of things are designed to take advantage of unequal forces. Wrenches, screwdrivers, door handles, and water faucets use forces made by you to do work. A well-balanced science diet starts with Bill Nye.', '1994-10-15', 26, '/A88ei6AbSPm2Y7AnDCb3bs2XN8I.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
