INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A1022AB528CC4D5DB920AC5CA150F510', X'23C93536610C41C5AC6BA6B243423258', 3, 'Momma Knows Best', 'Shocked by the dramatic GnA ousting, the group seeks answers and apologies. Keiarna settles in at her boyfriend''s house. Mia and Inc have a staycation to get some space of their own. Stacey''s close friend TJ comes to town. Gizelle attempts to make amends with the ladies before an upcoming trip, with surprising results.', '2024-10-20', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
