INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A1086EADB45A42DB840D9CAF56917F30', X'6F731E6BD3C54DE684E17A19CB650E86', 4, 'Godfather of Pawn', 'Feel good with the Pawn Stars when a James Brown suit dances into the shop. Will Rick be saying, "please, please, please" for the Godfather of Soul''s wardrobe or will it be too funky? Then, it''s a game of cat and mouse when Corey and Chum check out an artist proof from the film "Anchors Aweigh." Will the deal set sail or will they be left out at sea? Next, Rick feels exposed when a controversial 1917 Standing Liberty Quarter circulates the shop. Will he be in the money or will the deal not make sense? And later, Chum butters up to a 1920s popcorn maker. Will he make a concession and settle on a price or will the deal go stale?', '2015-10-29', 21, '/hllX5cFmMKk9566ZXS780DVcZYs.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
