INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A11852D896184AC59B183F1C37036F58', X'05C0E384194C44179F62803EB615E409', 72, 'Stop litterbugs', 'Title number 0072. Opens with Mister Rogers arriving with plant food and talks about how plants and people grow. Judy Ruben shows crafts that kids made with recycled containers. In the Neighborhood of Make-Believe, King Friday and Handyman Negri start a campaign against littering and they learn that everyone is interested in cleaning up the environment.', '1968-05-28', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A11B72FE5EB74073B9060DDEA6DBDB5F', X'D01919FB98E042BFB9D91CECF912F6E1', 16, 'Rosita and Telly''s Fix-It Shop (3801)', '', '1998-12-07', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A11E42391BB0412085FB8B88B36422AB', X'1D39506B06B84F9391360208069BD7E4', 13, 'Shunburn', 'The ladies'' Virgin Islands getaway continues---but it''s not a stunning development when Kelly departs the resort in the middle of the night. Before long, unexpected guests arrive at the island, and a warm welcome does not await them. Back in the Big Apple, Jill tries to reconcile with Ramona and Bethenny.', '2010-05-27', 43, '/aiLpkmnq1QtXBPyylOSrYzSRtIw.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A11F6C01B54A4BEBA8693CD7C1F34332', X'D5383B3D56364D71B99CB84774B4B3C6', 23, 'Pingu Helps Grandfather', 'Pingu’s family are all at home. Pingu is reading a comic, Pinga is playing doctors, with her teddy as the patient, Father is reading the paper and Mother is knitting. The phone rings. Father answers. It’s Grandfather, who’s had a fall putting up a picture and broken his foot! When Father has rung off and told the family what has happened to Grandfather, he and Mother have a discussion. Pingu goes and sits on the motorised sled, ready to go. The discussion shows no sign of ending, so Pingu calls out to hurry them up. They briefly stop talking, and then resume. Pingu is fed up with waiting, so he gets off the sled and starts walking to Grandfather’s house, muttering to himself. Father gets onto the sled and calls to Mother and Pinga. They come, and then Mother says she’s forgotten something and goes back in to get it. She returns wearing her floral hat. Father moans about the delay, but then Pinga also says she’s forgotten something and goes to get it, coming back carrying her doctor’s bag. Mother and Pinga get on the sled and Father asks if they’re ready to go. They both nod, but then Father can’t start the sled! He also goes back inside and returns, sheepishly showing Mother and Pinga the sled starter key, which he’d forgotten. Mother and Pinga both laugh, and they all set off on the sled. By now Pingu has reached Grandfather’s house. He enters, and commiserates with Grandfather. He then sees the smashed picture on the floor and the stilts, one broken, that Grandfather was using to get high enough, and has an idea. He splints Grandfathers foot using the broken stilt, tying it on with some cloth. Father, Mother and Pinga arrive. Pinga rushes in to help and is surprised to find Grandfather standing, with his foot splinted and using the unbroken stilt as a crutch. They take Grandfather to the hospital. A doctor takes Grandfather inside to be treated, while the others wait outside. Pingu brushes away a tear as Grandfather goes in, and is consoled by Mother. Grandfather then comes out in a wheelchair, with his foot and the broken stilt both neatly bandaged up. Grandfather gives the stilts to Pingu, who gets on them and walks around, to everyone’s amusement.', '2000-03-04', 5, '/6xWiCrra6eucuFb9hcQyu8B0S6D.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
