INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A27478E18C864314A6ABFA7C714B0CCD', X'DBD3583FE9B246D1A37E309EB666E233', 17, 'The Error Apparents', 'Kandi heads to Nashville to boost her country-music career; Sheree mulls over a marriage proposal for her daughter as NeNe reassesses her divorce from Gregg; Mal sets out to apologize to Cynthia; Phaedra throws a water-park party for her son; Kim and Kandi try to mend their fractured friendship.', '2012-03-18', 43, '/t7WZE9FOE5Oular5Dl5DsFhe0Mf.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A27480D63BCD471A88B82BFCEB0FB770', X'E291DF42D44F49E5BF812DF32EE4A30F', 16, 'That Healing Feeling', 'When Bear hears a commotion in the living room, he finds Ojo and Tutter in something of a panic. They were playing and Tutter hurt his tail. It''s all bent up and in a lot of pain. Bear does his best to help him feel better and then puts in a call to Doc Hogg. Doc Hogg asks Bear to bring Tutter over to his office, but Tutter is somewhat scared. Ojo''s been there before, though, and offers to come with him. He also brings along his stuffed toy, Kitty. When he gets there, he''s still somewhat scared, but eventually finds that there''s really nothing to be afraid of. The Shadow segment, Five Little Monkeys, is recycled from "Picture of Health." 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A2771AF150604B6B8F283C54C66B22E7', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 57, 'Inside Looks (on The Implant)', 'Inside look from the season 4 episode "The Implant."', NULL, 4, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A278E31395FB4EC49A2A5BF1FE3A934F', X'6F81C872CDB942DD83772C17CB6ED4D7', 25, 'The Recycling Fairy', 'Redusa the Recycling Fairy visits Sesame Street and helps everyone recycle their old trash into something new to help keep the earth clean and beautiful.', '2017-06-24', NULL, '/wYjj57iF1FBNCZW3A0N2vELilQ7.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A27B06D4B0CC462291F4E398978133E0', X'4B4D327B6C8B459C9E73B1D4D84AED77', 7, 'Trick or Treat', 'Brother Bear & Sister Bear celebrate Halloween.', '2003-09-24', NULL, NULL, '2026-04-03T17:40:22Z', '2026-04-03T17:40:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A27BD1BF6AD74B1793BFC1A01A5504F0', X'18DA994319634E04A7A0AE63802BB1FA', 6, 'Rumors', 'The ladies are surprised to learn how the poker night ended, leaving Gina and Emily at odds. Vicki travels to L.A. to record radio commercials for Coto Financial and ends up embarrassing her son Michael in the process. Shannon gets emotional as she goes to court as part of her divorce. Her good friend Tamra surprises Shannon with the gift of a matchmaker, while Kelly dates the “milkman.” After Emily leaves a happy hour early, the other women start to speculate about her marriage.', '2018-08-20', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A27BD2C4551A4A918E23E34DC6761DDC', X'34674C90410E427CBE4D2A6F6F865A80', 3, 'Wild Thing', 'Soar to new heights with the Pawn Stars when an A6 Texan fighter plane buzzes the tower. Actually flown during WWII, will the guys try to land this ultimate piece of war machinery or will they think the whole idea is just plane crazy? Then, a 1974 VW Thing cruises by. The same model as Rick''s first car, will his nostalgia trigger an offer, or will this trip down memory lane turn into a nightmare? And later, a guy brings in his collection of Civil War-era cannon balls. Will Rick and Chumlee shoot for the moon over these cast iron weapons or will their offer be way off target?', '2012-04-16', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A28380733A094D9D94421F8EC3804667', X'DE8EC76916BB436BBE43AEDC7E18A7D7', 34, 'Fourth of July Celebration', 'It''s July Fourth on Sesame Street! Elmo, Abby Cadabby, and Rudy look for the perfect birthday present for America, but Alan teaches them that holidays are really about spending time with family and friends. Together, they do something kind for all their neighbors.', '2020-07-04', NULL, '/2eLN4SWOswiuNVNv3WRdGBDXIVc.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A28574138E9C4332B1F3BC1B383852EF', X'208E80DE61E34A2F857FC667FFC29134', 22, 'Andy Williams', 'Miss Piggy asks Andy to sing "Love Story" for her and Kermit, who have just become engaged. Unfortunately, Kermit hasn''t heard about the engagement yet. The rumor slips out, and soon everyone thinks Kermit and Piggy are getting married.', '1980-03-21', 26, '/hbPVfryON6THJmwwpi7jV3GE6FC.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A285C56B699E4A9194F090626C65AC54', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 145, 'The Last Lap', 'Comments from the cast and crew of Seinfeld look at the decision to end the series after Season Nine. It gauges reactions to that choice and also gets into the creation of “The Finale” as well as attempts to keep it a secret. We also hear reactions to the episode.', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A28694DB99F24038BB18491C84B47DF5', X'D1863F2F02EC40CEAF64DB03FBE518A7', 4, 'Saved by Superfoods', 'The SuperFood Super Foods fly onto Sesame Street to help their friends try new foods, find a healthy snack, and explain the importance of eating breakfast. Also featuring Orange is the New Snack parody, and Elmo the Musical-Tomato. Brought to you by the letter H and the number 10.', '2016-01-30', NULL, '/8tezJGjD4uqVaaSPiETNtRXTArJ.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
