INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A290E46C744A4634A30AB3AFB1E5348A', X'3430D88114A2497D9CF4351B78B6AA6A', 10, 'Postman Pat and the Robot', 'Ted invents a new robot postman to help give Pat a rest. When it goes out for its test run and arrives at the Post Office, it scares Mrs Goggins. When it gets loaded with post, it causes havoc over Greendale. Pat and Ted follow after the robot in Pat''s bus.', '1997-06-05', 15, '/mC91yuoKlXT4JHziXi7WPv2Txeq.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
