INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A29D09ADF75345BD82ECE42165ABCFF6', X'D1863F2F02EC40CEAF64DB03FBE518A7', 33, 'Don''t Get Pushy', 'Telly is upset when Rosita pushes Baby Bear by accident because she is too excited; but with the help of her friends on Sesame Street, she learns how to control herself. Also featuring Cookie Monster''s Les Moussarables, and Elmo the Musical. Brought to you by the letter E and the number 11.', '2016-08-20', NULL, '/qXsZtvMf1cwudl7CdIlFEVWgNrR.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
