INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A29E97F7F08B4776BAED911CDD3DE175', X'C21DBD225E2E4414BB67750399AAF6F0', 26, 'Guns Blazing', 'Prepare for battle with the Pawn Stars as one of the rarest guns in American history pops into the shop. A 9-shot LeMat revolver used by the Confederate Army, will Rick charge into this deal guns blazing, or let it fire right past him? Then, it''s a race to the finish when a tire signed by legendary NASCAR driver Dale Earnhardt rolls on by. Will Corey be burning rubber to get this piece of racing history or will the negotiations lose their traction and hit the wall? And later, Corey and Chumlee are presented with a 1980''s handheld Donkey Kong game. The pre-cursor to Game Boy, will Chumlee go bananas over this Nintendo classic, or is it game over?', '2012-02-20', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
