INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A34DD2DF2D5F413EBFD18CBA7BB5C0A5', X'3269A890BBA94E6C9278F7EB38EB1720', 10, 'Climates', 'There are lots of different climates all over the world. Deserts are warm and dry. Temperate forests are cold and wet. Tropical rain forests are warm and wet. Animals and plants live in climates that are good places for them to live. Cacti wouldn’t grow too well in the Arctic, just like polar bears would over heat in the desert.', '1995-04-14', 26, '/qfQE7A7k2Hb8x9JBfxNMWufWuub.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
