INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A36F832847084D3983A3EBD88C5D6E73', X'1D713CA64E174F84949C8CFD98514127', 39, 'United We Stand', 'Go full throttle with the Pawn Stars when Rick and Corey race to check out an unrestored BSA bike from WWII. Will this military motorcycle rev their engines or will the deal stall? Then, Rick and Chumlee step up to the plate when they spot a pair of Roberto Clemente prototype sneakers. Can they walk off in the legendary outfielder''s shoes, or will they be a bad fit? And later, Rick and the Old Man lose their seats when a bet with Corey and Chumlee goes south. Will Corey & Chum be sitting pretty or will it turn into a stand off?', '2014-12-15', 21, '/s0p0K4GzeQev2eOpTqsXYRikHVr.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
