INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A37CE527D7DE4C62825F5B949589C678', X'27A5A980EC0D4637B5BADF8324A6405A', 1, 'Forced Family Fun (1)', 'Frankie insists that the family go on vacation together before school starts; Mike and Frankie remember their honeymoon, which was ruined by Nicky (Ray Romano), a guy Mike knew in high school.', '2011-09-21', 22, '/eruqr3VASh1aCjZVpDICFxIyqbv.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
