INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A38C173DF6754C179F9E54DCFAD79DFA', X'61E0C9D9337E4FE4A0FDE567B29AF115', 14, 'La VIDA Loca', 'The Mexico trip continues as the ladies set sail on a yacht excursion. Lisa updates the group on life with John and Henry. Britani takes offense at the lack of enthusiasm over her latest announcement. Bronwyn reveals some dark truths about her marriage and is surprised by Heather''s grace and Lisa''s lack of support. Mary arrives and the ladies come together for a beautiful VIDA dinner where Meredith learns her late-night antics have fueled Britani with fresh gossip. Angie and Bronwyn confront Lisa at dinner, causing a dramatic conclusion to the evening.', '2024-12-18', 43, '/jcqNeueUPOa3DITQ5Q6exOUMRHx.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
