INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A39D69971FF546789F4D192053C756A8', X'E38E9D8714324A1AA7D064A559BF7570', 10, 'Between Two Evils', 'A busy motorway lies ahead of the animals. All of the animals are hesitant to cross it because of the dangers involved. Most want to find another way around but the sound of the Hunting horn can be heard in the distance. They have to cross the motorway. They split into groups and take it in turns to cross. The larger animals like Fox and Badger help the smaller animals along and Whistler carries the fieldmice, the voles and the shrews to the other side in his beak. It is only the prickly hedgehogs who can not be carried over. The hedgehogs try to cross the road but their instincts get the better of them and they curl up when they see a car heading towards them and they unfortunately die.', '1993-03-07', 24, '/Ac0hJkZSsn754ELOwyMUi6KZTOu.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
