INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A4AD8105682D48CFB89F416CCB5DEB89', X'F4C403079B5E4263A4E0DFA138131E7F', 112, 'Being Green', 'Mr. Earth (Paul Rudd) hosts Sesame Street''s first "Earth-a-Thon." Abby, in an attempt to help Elmo be more "green," accidentally turns him the color green. When Abby has a hard time turning back, he begins to sing "It''s Not Easy Being Green," until Mr. Earth convinces him that "It Can Be Easy Being Green."
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A4AF70AD90CA4FE094A1E8199F0DC47B', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 32, 'Episode 2127', '"Explorer Jones" and the kids pretend to be explorers. They''re looking for the alphabet, but Forgetful doesn''t know what it looks like. After identifying it as Maria''s hot plate and Bob''s shovel, he finds it in the direction of the viewer.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A4B1249ADC5B4C04B4F524E004C89247', X'02849655BD954D8DAF3B03321918EEEE', 25, 'Madeline and The Dog Who Cried Wolf', 'When Genevieve wakes up with a strange rash, Dr. Fleabag the vet prescribes lots of loving care, which Genevieve enjoy so much that she begins to fake ailments.', '2001-02-21', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
