INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A4EA4304A67649769E227390B378D4B5', X'3AF7EA64FA134097B8E440AF07083054', 1, 'Painting The Walls [1326]', 'In this episode Mister Rogers paints the walls of the television house blue. From Seasons 2-3 the walls of the television house were painted yellow with the brown wooden bottom panels. From Seasons 4-6 The walls of the television house were painted a brighter yellow but more of a tan color and the brown wooden bottom panels were removed from the walls. Parts of the kitchen set were also updated. The walls of the television house would stay blue until the end of the series in 2001. Beginning with this episode Mister Rogers says "You''re alive" in a higher toned voice. This is the first episode to use what would become the show''s more-familiar neighborhood toy-like model town and it was used until the end of the series in 2001.', '1974-02-18', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A4ECFD8419D94354A3C05B7333D269AC', X'5144DE59E67F4FCF919B7106989AB797', 11, 'Different Drummer', 'Julie plays referee to Skye and Leon’s dispute over whose cultural drum is more significant. The two eventually agree that both drugs are significant in their own way, and neither''s is necessarily better. Sizzle takes up skateboarding.', '1995-01-30', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A4F19AA832D74D5A95E8EDE471620FCE', X'A79A245FACAB4EBEAEE929867F9E52F6', 9, 'PolygaMexicamist Wedding Part 1', 'Mykelti''s polygamist family ties the knot with Tony''s Mexican Catholic family with a unique winter wedding where they beat bride and groom piñatas; Christine forgets to bring Kody''s shirts.', '2018-02-11', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
