INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A5951D06FA794E41924F32C5DC7928E8', X'0E4196154C964DDE8ED2715770BA77BB', 19, 'The Great Bandini', 'Bear and our friends from the Big Blue House are on their way to attend a performance of the famous musician, the Great Bandini. All of them are in awe of the Bandini''s skill and on their way, they meet somebody headed to the concert --- Edwina Badger. Edwina Badger helps them all to see the musical talents that they also possess. They learn that there are all sorts of ways to make music and that the voice can be a powerful instrument. In the Shadow segment, Shadow sings a song about jazz music.', '2003-02-07', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A59E276673B841C3ABB4791216C50233', X'E48599F866FF4C0F927465B9AE1CDA9E', 38, 'Episode 38', 'Up Helly Aa!  For hundreds of years the Shetland Islanders have celebrated the end of the Viking winter with a spectacular and fiery ceremony. John reports from the great blaze at Lerwick.', '1977-01-24', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A5A163AFFB344F03B65CE6B37AA91CBD', X'CA19F89515144988A70995E84EAB7CEE', 3, 'Decoding a Deal', 'Corey finds himself in such a lovely place when a test pressing of the Eagles mega-hit, "Hotel California" comes into the shop. Will the seller take it easy, or to the limit? Meanwhile, Chum checks out a ring from the "Little Orphan Annie" radio show. Will it be a "hard-knock" sale, or will Chum bet his bottom dollar? Then, a customer soars in with a model of Leonardo da Vinci''s flying machine. Will Rick get this deal off the ground, or will it come to a screeching halt? And later, when Rick examines blueprints by renowned architect, Frank Lloyd Wright, can he draw up a sale?', '2020-11-23', 42, '/1WVJD2MFkFYcHxf9JztYgY8FgeD.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
