INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A5ADFFCE56E048BDAFFE6E334340C4E4', X'AD4E434833344A088928455D9BA524C1', 4, 'Linda Ronstadt', 'Afraid that Linda will steal her frog away, Piggy locks Kermit up in a chest owned by Gonzo when Scooter helps him move his mildew ""collection"" and hides it.', '1980-10-26', 26, '/c8f0KoC9bLTzdLBIoOfkrAvsCrZ.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A5AFE11ACFEC458DB5F749559019065D', X'45E01C046AC641E187D8F749EE230385', 19, 'Fireman James', 'James is keen to be a firefighter and listens to calls to Jupiter on his walkie-talkie. After one call he gets to Norman and Lion first and helps rescue them, but then a later call sees him trapped by fire at the Flood''s house.', '2008-03-06', 10, '/zXnc2CRNX1bK8NOonuGDIpyKnov.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A5B24969311B4FE09207F33D223C8BED', X'F9A8D8B3D72E437EA9D57477F6D64DF8', 1, 'Community Mural', 'Friends on Sesame Street are painting a mural to celebrate the people in their neighborhood. When Abby has a hard time finding a paint color that is the same as her fur, she learns to mix paint to make a color that looks just like her.', '2022-11-03', 26, '/3anJ8MZIyMxXrsOwwSNB5o3mTS4.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A5B4E9BDD1DE476482672D0A866BE81B', X'BF722849CDDB452B9C0F7F0D96E94C26', 13, 'Perseverance', 'When Plato discovers that Zach and Annie have given up guitar and karate lessons, he takes them on a hike to the top of Plato’s Peak. Along the way, Annie and Zach discover various objects, prompting several stories from Plato and Aurora about the importance of perseverance.', '1997-03-02', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A5C3B513D31445C39C64D694E5589335', X'6EF86C2733E747E5A053483059DFD16D', 1, 'Episode 1', 'Expedition Japan: Who was the ''tall, fair-haired and very red-faced European'' pulling the float at Kyoto''s famous Gion Festival? None other than Simon, sweltering in 90°F, and that''s how he was described by five "Blue Peter" viewers who just happened to be in the crowds lining the streets! But that was nothing compared with wading shoulder high into a sea of 50,000 eels, playing the part of a Samurai warrior at the Kyoto Movie Studios and coming face-to-face with the massive 30-stone Sumo wrestlers who make Big Daddy look a mere midget.
