INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A5DBA92719DE448A8EB4BDFCEF00B77D', X'7CCD5605FE0B4E00AE7F3E3DAA252F8B', 8, 'Let Bygones Be Bygones', 'Lynne Curtin meets Gretchen Rossi to discuss the conversation she had with Lynne’s teen daughter Alexa, about her alleged drinking and depression. Vicki invites Tamra to an "all girls" slumber party at her house. Vicki is excited to host a girls-only slumber party to make up for the fact that the men crashed the recent girls trip to Ft. Lauderdale. Later, Vicki surprises her friends by bringing in a psychic who reads their auras and they are caught off guard by some of his insightful readings.', '2010-01-14', 44, '/6ALkPsluwuOpk3HDc4PY7Wn2bG4.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
