INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A615CECDC8F141E784DFA7742CCEB031', X'27A5A980EC0D4637B5BADF8324A6405A', 15, 'Valentine''s Day III', 'Frankie and Mike decide to try a fresh approach to Valentine''s Day by having dinner out with friends. But a clueless Mike angers Frankie by refusing to present her with a simple romantic gesture. Meanwhile, Axl can''t think of a life-changing moment that''s occurred in his life when he''s assigned to write a school paper on the subject, Brick is tasked with writing a report on love, and a hapless Sue doesn''t understand why her new boyfriend has suddenly turned into a bad kisser.', '2012-02-08', 22, '/t1O9iwFuMT2C6v6Tol87nbhVfi8.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
