INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A637192F0A33429182348853CBB0E9C3', X'F4C403079B5E4263A4E0DFA138131E7F', 52, 'Elmo''s Animal Adventures', 'Animals are on the loose on Sesame Street! Elmo invites you to join him and his animal friends as they embark on three fun-filled adventures. Help Elmo and Telly find little Bo Peep''s missing cow by following clues and working together. Then, use animal facts to help Elmo & Abby succeed on "The Find The Amphibian" game show. Plus, camp out with Elmo in a wilderness adventure as he learns how animals and little monsters are different. Includes special guest appearances by Cameron Diaz and Patricia Arquette.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
