INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A64484F1B4E24DE9A96C270816DAB877', X'E40E6B639F84449F8E8853209B0906C8', 14, 'Chris Helps Elmo Write a Letter', 'At the Fix-it Shop, Abby Cadabby and Elmo watch Maria fix a toaster. ("I love having an audience," Maria says.) An excited Rosita rushes over to show them the letter she received from her abuelita, and asks Maria to read it. In the letter, her grandma says she was looking at a picture of Rosita, and it made her happy. It makes Rosita happy, too, as she imagines a hug from her abuelita. Right then and there, Rosita decides to write a letter back, and runs off.', '2007-09-12', NULL, '/pFHvATjNgJT5slNobhEfYKIftdH.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
