INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A670D43313464D119661847BD5611BFB', X'C01DDD2ABDB14C978D0458F791EF1C24', 34, 'Water Creatures', 'When two African penguins stop by Animal Junction, Zoboo, Chris and Martin talk about water creatures. Even though penguins are birds, they swim instead of flying. But these penguins aren''t swimming! Finally, they realize it''s because the pool water is too warm for them. But when the water is chilled with ice cubes, there''s no stopping the penguins! Jaguars love to swim, too, and the Kratts play ball in the big pond with a black jaguar who stops by. Jackie has a new goldfish named Sunny, who is also sensitive about water temperature. To keep from shocking Sunny, Jackie puts his bag into the aquarium until the water in the bag is the same temperature as the aquarium.', '1999-09-08', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
