INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A72CBFCB848543E78BD3C42F2AA81DAF', X'27A5A980EC0D4637B5BADF8324A6405A', 8, 'Heck''s Best Thing', 'Frankie and Mike are convinced that slacker son Axl will blow his interview with a football scout, which could earn him a scholarship to college. Meanwhile, Sue and Brick begin a texting marathon - and rack up some serious charges - when they discover that Aunt Edie accidentally gave them her cell phone; and Frankie tries to be completely attentive to the family''s needs when she realizes that she''s more considerate to outsiders than her own kin.', '2011-11-02', 22, '/3iAylhcNP4030FZ8R5ibF8RsNty.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A72FBABDBADB4FB881663B321B5360A9', X'5046642D462D4EB081940BBD7962AF0F', 8, 'The Asparagus of La Mancha', 'An adaption of Spanish novel Don Quixote, "Asparagus of La Mancha" starts with Knight Don Quixote facing three Peas in a surrealist world made of cooking utensils and foods. Then he wakes up. It was a dream. He and his best friend Poncho work in a Spanish restaurant of Cafe LaMancha. However, Jean Claude comes in to inform the duo of a new restaurant opening across the street called ''The Food Factory'', the most successful, and biggest, restaurant in the world. With their customers abandoning them, Don is sure they will go out of businesses. After losing another game of Spanish checkers to Poncho, Don goes back to sleep. He assumes his latest dream has informed him to try different themes to win back their customers. This fails, and shortly after, the Food Factory manager offers Poncho a job at the Food Factory. Poncho refuses. Don''s next dream convinces him to attack the Food Factory.', '2006-09-09', 30, NULL, '2026-04-03T17:39:38Z', '2026-04-03T17:39:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A731975F30D342758E5FAF4CA1A10C98', X'3AF7EA64FA134097B8E440AF07083054', 63, 'Episode 63', 'Mister Rogers brings with him a collection of puppets from around the world that were provided by the Lovelace Marionette Theatre. He then goes to Elsie Neal''s shop to find Elsie Neal helping Terri and Chrissy Thompson for their upcoming puppet show. In the Neighborhood of Make-Believe, Lady Elaine is ready to do remote TV work. The first act is Lady Aberlin in a primitive witch costume, which scares Henrietta.', '1974-05-15', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
