INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A747BFEB694447C8B3000C5BB9F418EB', X'751012D37DF140848E960EFD6559CF06', 1, 'Flying', 'Major Clanger builds a flying machine, and Tiny Clanger gets stuck at the top of the cave with a balloon.', '1969-11-16', 9, '/mJbTVg2k2dZ9WwRRWf3alpHkPpb.jpg', '2026-04-03T17:23:53Z', '2026-04-03T17:23:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A74A920EAEBC498CBFD9608A5BFA72C4', X'8BDF0AD3A7984D5AB304C7501EAE6867', 11, 'Vegas Baby', 'With her wild 18-year-old daughter, Alexa, is running circles around her, Lynne Curtin seeks her mom''s advice about how to be a better parent. After four years away from home, Jeana Keough travels back to Wisconsin to see her family, only to be reminded of all the reasons she moved to California to begin with. Back in Orange County, Tamra Barney celebrates her mom''s new facelift by taking her out on the town in hopes of finding her a new man. Vicki Gunvalson comes to a surprising decision regarding the purchase of the million-dollar yacht she so badly wants. After two grueling months in the hospital undergoing chemotherapy, Gretchen Rossi''s fiance, Jeff, returns home. Later, the housewives blow off some steam with a girls'' overnighter in Las Vegas.', '2009-02-03', 44, '/tsqI72jlmg9YWlO0dY6xtvKMj7j.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A74C51F051F348FC98E900D742851CD5', X'BB919AEC0D5C4C589A5AFA2A0A5DE2B6', 47, 'Episode 452', 'The Geefle and the Gonk is a Sesame Street story about two aliens on the planet Snew, narrated by Jerry Nelson. (First: Episode 0452) The segment was written by Jeff Moss and directed by Jim Henson.[1]
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A74E6AA4F9584811AEBBB5C4A5D88C62', X'05C0E384194C44179F62803EB615E409', 63, 'Fire in the factory', 'Title number 0063. Opens with Mister Rogers arriving with hot dog buns in a brown bag. Mister Rogers warms some wiener buns in his oven so that Chef Brockett and Mr. McFeely can enjoy them. In the Neighborhood of Make-Believe, everyone has turned their attention on the fire that has completely burned down Corny''s factory. King Friday and Henrietta are especially frightened. Chef Brockett and Lady Aberlin help to put out the fire. Corny is devastated, so Daniel shows kindness by inviting him to stay with him at his Clock until the factory is ready again. Mr. Rogers talks about how many things can be scary when they are out of control, such as fires.', '1968-05-15', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A758146220014DCB871E60CD84989CB7', X'8BBF02B3DC844CC6ABBC81CF76ACF365', 12, 'Dress-Up', '', '1991-09-12', NULL, NULL, '2026-04-03T17:35:45Z', '2026-04-03T17:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A75BB31355684F5AA03BA6080E6EE2C7', X'941B8C6544544336BE7C1D0591C12F90', 20, 'Pingu and the Band', 'Pinga has a spoon, and is banging on a box with it. Pingu thinks this is a great idea and starts banging on a tin. He then gets some spoons, and soon he and Pinga are banging on almost everything, making quite a racket. Mother has had enough of the noise being made, and tells them to go outside. They then bang on the sledge, the snowman’s hat, aunt''s dustbins and front door, some mailboxes and at the post office, where Father is working, getting told to go away several times in the process. Eventually they arrive at Grandfather’s house. Grandfather is dozing in his chair outside, and they give him quite a waking up shock by banging loudly on the table. Grandfather retreats hastily indoors, but then comes out playing his accordion. Pingu sees some icicles and plays on them like a xylophone. Pinga then plays them too, after Pingu gets her a box to stand on so she can reach them. Pingu then uses a fish skeleton as a güiro (somehow it sounds like a snare drum). They try playing all together, but initially it doesn’t go very well. They then play in rhythm with Pingu starting, then Pinga, then Grandfather. Pingu and Grandfather march off, so Pinga takes an icicle and follows, playing the icicle like a trumpet. They march home, and those who hated the noise being made earlier enjoy the music now being played.', '2004-01-29', 5, '/d47jkUoS87RZy8h7pYaJa9QDY9q.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A761E83234854D0081C08B691D01D3E4', X'63F9BF6D39B344F4B885A56807277A80', 103, 'The Muppet Show (2026 TV special)', 'Music, comedy, and a whole lot of chaos is bound to ensue when The Muppets once again take the stage of the original Muppet Theater with their very special guest, Sabrina Carpenter!', '2026-02-04', 30, '/sQZFVAD0BoIiNdSn5RRyWUqvhH8.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A764EBECBAF145D692C0745FE8B6BF03', X'79C64E0A348841BC9B5C2243FF15B373', 10, 'The Cult''s Out of the Bag', 'Rachel finally gets her wish with a Hot Girl Summer at a Hamptons club. Kyle and Dorit put their problems aside to enjoy the vibe. Boz and Sutton want to get to know the real Amanda, who finally sheds light on a tough time in her past. Erika and Sutton dine with Denise, who opens up about her volatile divorce. Erika stuns the table with a revelation of her own.', '2026-02-19', NULL, '/pSyqaEwVOvH44vlvyLsGkkgUl7x.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A76FB27EC23A4D2EB139E690169AF0EE', X'84CE360A90D14FC0BE0633BDCBE8E60A', 8, 'Crazy Golf', 'Tiger wants to show everyone how good he is at crazy golf. He''s a bit upset when Kipper manages to get the ball through the windmill - and he doesn''t.', '1999-11-11', 8, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
