INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A779363C2DFE4CDEA416A0D6B34EA3C4', X'6FD9FD9DE378411B94B176BA4BD518FE', 13, 'Episode 13', 'with Christopher Trace and Valerie Singleton.', '1965-11-01', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A78066E2122C46678A1638025A3A8002', X'ECB64EF34F8045A7B4A9C04434B02E35', 19, 'Field Trip', 'Play along with the Pawn Stars when Semie Moseley''s personal guitar jams into the shop. Will Rick be able to hit all the right notes for this one of a kind instrument or will this deal go out of tune? Then, the Old Man and Chumlee discover signed photos of Enola Gay. Known as the plane that dropped the atomic bomb over Hiroshima, will the guys go nuclear for it? And later, a class of elementary school kids takes a field trip to the shop. Will Rick teach them the tricks of the trade or will the guys disrupt class?', '2014-03-06', 21, '/ijGkSZsBq6bbDcCRUl5BQxFxO7a.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A7886E35CEF0477B878C6F6B76EFAC86', X'4B2A19E02FAE492EBC31F78E63D88EBC', 22, 'Killer Pawn', 'Scream bloody murder when a signed shower curtain by Anthony Perkins from the psychological thriller Psycho, lurks into the shop. Next, an 1882 Gold Certificate and 1918 Federal Reserve note cash in. Then, an 1800s Millionaire Calculator has Corey and Rick counting their luck. And later, a 1950s Russian night vision scope finds its way in.', '2017-01-02', 21, '/uhYY988YnvmnIpd1Vm4xCtpCAlS.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
