INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A7C97195D62B4F4E8FFF298FC06D8EE9', X'F5C042DC065742E8A37D247414140632', 3, 'Kary''d Away', 'Stephanie starts a charitable foundation and encounters nothing but resistance from Travis, while Tiffany’s demanding mother makes her feel like nothing she does is ever good enough. Kameron hosts an outrageous party for Kary’s 50th birthday, where Tiffany and Kameron spar over chicken feet and things get out of hand after a night of drinking.', '2021-01-19', NULL, '/AmReL4jdrk6g9cjl5HmOrAzvjs4.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A7CCEBFA725C4962BAF93A5A34BF52F4', X'F5C042DC065742E8A37D247414140632', 1, 'Bursting the Quarantine Bubble', 'With the stay-at-home order finally lifted, the divas of Dallas are ready to make the most of their quarantine bubble, as safely as possible. Kameron gets a new dog and hosts a socially distanced garage sale. Brandi looks for ways to make amends after a controversial video resurfaces on social media, and D’Andra introduces everyone to her friend, Dr. Tiffany Moon.', '2021-01-05', NULL, '/1EdPEciSWUzbB7I0cgZwLUaKxdb.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
