INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A7FE85E013FE49FF953EA982B0365EA2', X'5B5E8B2F0A854488B3DC3D8B794E6582', 17, 'A Case of the Vickis', 'Vicki''s health scare continues and brings out a side of Peggy that shocks the ladies. Later, a broken friendship might finally be on the path to mending, while a drunken night causes fractures in another.', '2017-10-30', 44, '/nK0412upxQECRA1okjgkGGtxn1K.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8052C175D7D4524B9E6119A35A46BF9', X'3FC7C152E4F6426AA89936EC454C4403', 16, 'The Talent Pool', 'Cassie notices that all her friends have special talents except her, so she goes to the Talent Pool to finds a talent. However, the Pool turns out to be grumpy and refuses to give Cassie a talent.', '1999-09-22', 30, '/tsQCfi9Wd4b7UR2hxz07zDiMtor.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A80B66B9A0564AED98444D4F562486DA', X'45E01C046AC641E187D8F749EE230385', 7, 'Stuck In The Muck', 'There''s trouble for Trevor Evans as the school bus swerves off the road and breaks down in the Pontypandy hills. Unfortunately, mobile phones have no signal up in the Welsh hills and he is stranded - with a beast about. Fireman Sam comes to the rescue, with the assistance of Tom in the helicopter. Then they search for Trevor, who made an attempt of finding help. In the end everyone is safe and they go home. Norman spots a black animal passing over the road just before the bus rounds a corner, but when he tells everyone else about his sighting, nobody believes him.', '2008-02-18', 10, '/s9jcH56dJDSjvBMI5drVs0Gw35i.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A80D20302CAC43B48F5BB1188F8E6AD5', X'0E4196154C964DDE8ED2715770BA77BB', 2, 'Welcome To Woodland Valley (2)', 'In the second half of the two part special, the plans are coming together for a potluck dinner Bear is holding. Everyone will get together at the Big Blue House, eat good food and talk about solutions to fix up the library. The kids are hard at work collecting books to restore the library''s collection. And Doc Hogg is getting down to business as to just what to do about the tree currently occupying a large portion of the library. He wants to remove it, chop it up and use it for firewood to heat all of Woodland Valley, but Ojo makes a discovery that changes the plan --- a couple of possums living within the tree.  Songs  Good Morning  Everything''s Great About the Library  Woodland Valley Cha Cha  Goodbye Song  Notes  This is a direct continuation from Part 1.  Brad Garrett and Gilbert Gottfried voice the Possums in this episode and receive a "With" credit. They had previously appeared on Hollywood Squares with Bear.', '2002-09-09', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8174837BF934EA5B4C77A1524A1177E', X'9193E795DA7C40ECB68FF63AA7D5174F', 105, 'Histories & Lore: The Lord of Light', 'Thoros of Myr details his personal history as a follower of the Lord of Light, from his skeptical youth in Myr, to his visions in the flames that have made him a believer.', '2014-02-18', 4, '/iLKykUL21OQzXuQVlzjWtXctrFO.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A81A8C54F9454FA99DC4B555B98F1D83', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 38, 'Abby''s First Sleep Over', 'Abby goes to Big Bird''s nest for her very first sleepover, and Maria reads her "Hey, Diddle, Diddle.', '2010-12-09', NULL, '/85ZpIdQIXxYNj1yDR65LsoTWpcn.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
