INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A823A0676EE04EF1AC9E13EAD08D221F', X'AD180412A5D64E4A8B49590334F2FC69', 3, 'Water, Water', 'Water becomes an issue for the Animals of White Deer Park. Shadow and Hurkel arrive at the park only to see that the only water source Trey will allow the animals to drink from has been poisoned. That was the stream that The Great White Stag perished from. Meanwhile outside White Deer Park, Owl encounters a Rook  named Moth eaten Rook who wants to talk to her. However Owl flies away with the Rook following her.', '1995-10-12', 25, '/9rAI1Mtop6Qs8nqzdlaePHSYWYt.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A824D614B35E46C2AA7EA338922E4190', X'9C9D89DF5F6B41D084C6B8CA7BD2A2E6', 4, 'Sesame Street Art Museum', 'Everyone is making a painting to hang in Sesame Street’s art museum. Rudy wants to paint a rainbow, but he can’t make the perfect purple. What if he mixes the red and blue paint a little bit at a time? Let’s try!', '2021-12-02', 20, '/gbK1bxWxb9yB9jLjWhOkAZe057F.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8259F3B43E34FA7A02D4FB4CC958616', X'5A771F52FE964EA2B567A8DDE899059E', 15, 'Can''t Pawn Me Love', 'Rick travels to an art gallery in the Venetian Hotel to see some monstrously expensive illustrations from the classic children''s book, "Where the Wild Things Are." Back at the shop, a collection of ultra-rare Beatles vinyl records sends Chum across the universe. Can he work it out with the seller, or will he decide to let it be? Chum warms his buns with an antique hot dog bun warmer, while Rick is frank about an electric hot dog cooker. Later, Rick and Chum can only hope to force the sale of a Princess Leia action figure signed by the late Carrie Fisher.', '2018-01-29', 21, '/u2BRSeh7jJPz5NwAO1JSYxaJ4Mn.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A829450291D8431E851083CAD30CA454', X'4091B13B4DB64857AD2220B5658C6B89', 6, 'Dildos Down the Shore', 'As the ladies and their husbands head down the shore, Teresa finalizes her divorce and Joe Giudice''s rumors about Joe Gorga come to a head. And, a gift from Teresa to Jackie sends the entire group into a tailspin.', '2021-03-24', 43, '/2oUgcLYjvlR14qjPBATiZt6mReZ.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
