INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8376282E6294806B75FA7C0AEB4A314', X'C373ABED50EF417E9F344E9050611A1B', 9, 'Speech Therapy', 'Vicki is torn between spending time with Brooks or babysitting her grandson; Lydia convinces Alexis to talk to Tamra; Gretchen visits a fertility doctor; Tamra gives a speech at the Los Angeles Women''s Expo.', '2013-05-27', 44, '/xhxM8jKRNw72LHamCfn2lYbe4LQ.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
