INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A83A30DB54124124BEA6D53B9625395E', X'4892E2AF46C14B4EAC81EAC161B5A347', 6, 'Episode 6', 'Expedition Brazil  PETER joins the gauchos of Rio Grande do Sul and helps to round up some of Brazil''s five jmillion cattle.', '1977-09-29', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A83D807B21954BCC8A62DF78F8BA5003', X'F9A8D8B3D72E437EA9D57477F6D64DF8', 22, 'Monster Truckin''', 'Elmo and Chris are making their own monster truck jump, but they don’t have a ramp. What if they make one out of a pizza box lid? Let’s try!', '2023-03-30', 26, '/8pM7zCB2ttDxt2Aabdm0996P3XX.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A83E2574C6BE44838079BA634B5920E2', X'D5383B3D56364D71B99CB84774B4B3C6', 12, 'Pingu in Paradise', 'Pingu and Pinga are playing hide-and-seek. Pingu hides in the toy box while Pinga is counting. Pinga looks for Pingu inside, can’t find him and goes to look outside. She can’t find him there, either. Mother then comes out to go shopping and Pinga tells her she can''t find Pingu. Mother takes Pinga with her to the shops. After they have gone, Pingu peers out of the box and can’t see anyone. He feels tired, falls asleep in the box and has a dream. The toybox moves itself across the floor and the lid on the saucepan rattles about. A plate falls out of the cupboard but as it lands on the floor it morphs into two plates. Pingu suddenly wakes up. The telephone rings and Pingu goes to answer it. The receiver comes off in his hand and the body of the phone then falls off the wall and on to the floor. It turns into flowers, and the receiver that Pingu is holding also turns into a flower. A book and some toys jump out of the toybox and onto the floor. The book morphs into three and they start to dance, together with the lid of the saucepan. Some firewood joins in. The propellor on the toy plane starts to turn, and the plane takes off, does a couple of circuits inside and then flies out of the door. Pingu follows. He can’t see the plane anywhere. The snowman suddenly talks to Pingu and points. Pingu goes to where the snowman is pointing and sees some flowers growing in the snow. To Pingu’s surprise, one of the flowers then changes itself into a large tree. Blossom, and then fruit, form on the tree, and an apple falls off. Pingu eats the apple. Nearby he then sees a cascade of pink liquid (possibly milkshake). He goes across to it, produces a straw and drinks all the liquid. A fish flies up from the last of the liquid, lands on Pingu’s hand and then flies into Pingus mouth. Pingu swallows the fish, and then spots a number of giant lollipops sticking up in the ice a short distance away. He starts to lick a large pink lollipop, and is surprised when it moves away from him. Pingu then wakes, to find Mother and Pinga have returned from shopping. Pinga gives Pingu a pink lollipop she has brought back for him!', '1998-11-20', 5, '/vcTrwXZ5iYdxYWxHXKl74ThhuuY.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
