INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A857700FB8A54504AB2909CB235B785A', X'8C3CFAC1D8824904B38CD1981628D00E', 60, 'Episode 60', '', '1979-04-09', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A85CD02F2A8A48E6AF33A8C548EF7963', X'E40E6B639F84449F8E8853209B0906C8', 8, 'Big Bird Helps Zero', 'On a beautiful day, Big Bird encounters a sad number Zero, who is upset because he is nothing. He sings a song about it. Big Bird sets out to show Zero that being nothing is really something. When they go to Hooper''s Store, Zero asks for a banana split, but Alan realizes he''s out of bananas, which is the perfect cue for a musical number parodying "Yes, We Have No Bananas." In song, Alan explains how the number zero helps him keep track of what he needs to order whenever he runs out of something in the store. This makes Zero feel a little better, but he is still not convinced of his worthiness.', '2007-08-27', NULL, '/znadl8F6PDL4C7geFkeELxGrJpu.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
