INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8A1CF084D454D14AE4C376218836F86', X'4D2CAC0F38FD438B8AFAACF43952E535', 221, 'Episode 221', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers, including Ballet for Athletes - David Blair, Premier Danseur of the Royal Ballet, assisted by David Morse, shows why dancers have to be fine athletes and how their exercises can help football, high jumping, hurdling, and all kinds of sport and The Swapping Song. David Blair and David Morse appear by permission of the General Administrator, Royal Opera House Covent Garden, Ltd.', '1963-02-25', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8A2CC27770948A4A3B2C3D3C0640120', X'4FE93658C46343298E649D523869C2CB', 1, 'Peeping Pawn', 'The Pawn Stars are presented with a supremely rare 1776 Massachusetts penny made by Revolutionary War legend Paul Revere. With only one other coin known to exist in the world, will the gang crank out a mint for this priceless coin or will they find they can’t spare the change? Then, Rick has an opportunity to buy a hand grenade made by a top-secret American World War II spy program. Will he pull the pin to make a truly explosive deal or will the negotiations have him running for cover? And later, Rick and Corey meet a man hoping to sell his 1950s peep show machine. Will they like what they see and bare their wallets or will it be too stripped down for comfort?', '2010-08-16', 21, '/lQqvRMbwQy5QCau79pGDASDLaYV.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8A7B1B291AA4BEC93926EE7009CC225', X'68138DE20900460AB58E480688F1E081', 16, 'Look What I Made', 'Doc Hogg pays a special visit to the Big Blue House to give everyone a checkup. Before he arrives, Pip and Pop dress up as doctors and pretend to give a checkup to Treelo. Bear tells the viewers all about Doc Hogg and what doctors do. Later, Doc Hogg gives everyone their checkup, but Ojo seems to have disappeared. Bear finds her hiding with Snow Bear --- it turns out that she''s scared of getting a shot. Bear helps her out by teaching her a special song that Doc Hogg once taught him. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8A816F9ED87415A8CAE8FD9532602E1', X'D6092173D23B4449BAFFE0E16FE56C9A', 1, 'No Justice, No Peace', 'Porsha’s involvement in the Black Lives Matter movement leads her to Louisville, Kentucky, where she risks everything to demand justice for Breonna Taylor. In the wake of the pandemic, Cynthia and Mike are on different pages when it comes to planning their dream wedding. Kandi prepares to send Riley off to college while anticipating fallout for seeking back child support from Riley’s estranged dad. After almost a year apart, Kenya comes to a crossroads about whether her marriage is worth saving.', '2020-12-06', 43, '/vskjhtU9h7iffoStQUnyMN6CicM.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
