INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8EABD9412C94BA099E2102849D17BFF', X'25FE20D16FC6423693F673178498CDFA', 5, '1st Wife''s 20th Anniversary', 'While the three wives buy a friendship ring for Kody''s fiancée Robyn, Kody prepares to celebrate his 20th Anniversary with his first wife, Meri. But when nothing goes as planned, will Kody end up in the dog house?', '2010-10-10', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8EC5E99C08E4C43A3C6C17C8F73F747', X'BFDF87FF01DD4B5494BD19B384F41BDB', 1, 'When the Ship Hits the Fan', 'The ladies kick off an explosive 11th season with an epic boat party filled with tensions at an all-time high as Vicki fights to win the ladies back after a year of lies left her friendless and alone. Heather''s mansion is still a work in progress, and so is her relationship with her workaholic husband Terry. Shannon''s marriage is on more solid footing, so it''s time to look for a new home for her family. Unable to have children the old fashioned way, Meghan starts in vitro fertilization (IVF) with no help from husband Jimmy. And new housewife Kelly Dodd brings her big personality to the party, but her loud mouth gets her in big trouble.', '2016-06-20', 44, '/w5gzPJ4zGdCXCNVCivTUfwW7GzJ.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8EE119DC3144D549FD0665F5A7DE200', X'939D270CEA8E4CC8A5A5E59DF2C8062C', 6, 'Dinner on the Rocks', 'Caroline Stanbury clears up some issues with Lesa at an afternoon of high tea; Caroline Brooke throws a pool party; Ayan picks a bone with Nina; Sara’s unsolicited advice leads Caroline Brooke to question her relationship with her.', '2022-07-13', 44, '/arLluxe2DaRkzj5ou3oWZOzZ68R.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8F0ED1A22D944139947FDA63F5AB3A2', X'991E78F103A54D268F7575E11DB4243C', 11, 'When Things Get Broken: What a Computer Can and Cannot Do', 'Rogers enters with a computer mouse and introduces viewers to a different room of the television house. He introduces viewers to the online neighborhood ([1]). Mr. McFeely shows a video on how a computer mouse is fixed. In the Neighborhood of Make-Believe, King Friday and Queen Sara are searching for the "royal mouse". He has been in the Museum-Go-Round, busily planning a surprise with Lady Elaine.', '1999-04-26', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8F181F2E0944EBDBEBF547D79D384D2', X'4FE93658C46343298E649D523869C2CB', 10, 'Chumdog Millionaire', 'Travel back in time with the Pawn Stars as they encounter an 80''s icon - a DeLorean sports car. Will the gang set the tires ablaze in search of its flux capacitor or is this automobile''s best years all in the past? Then Rick and the Old Man meet a man hoping to sell a letter from President Franklin D. Roosevelt. Will they draft themselves up a New Deal to buy this piece of presidential history or will their campaign lose ground? And later, Rick, Corey and Chumlee have an opportunity to appear on the game show Who Wants to be a Millionaire. Will they jump into the hot seat and go for the big bucks or will Rick''s final answer be no?', '2010-10-18', 21, '/dgRG55RkeWSO1oBSCJceon8EMBy.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8F245B87E184CBC9C1C462478F58DE2', X'38BF8C20C17C407192267887787CF1B1', 23, 'Good Night, Knight', 'A famous marionette team is preparing to tell the story of Orlando Furioso and his battle to rescue Angelica from the curse of Fallerina.  It''s a story Leona knows by heart, and she has more than a loving desire to see this play.', '2001-05-02', 30, '/wTvXWeQZiNdrpfAAKMT8KWussYN.jpg', '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A8F46EC7E5654B6EBF6BEAB864E992D3', X'4FE93658C46343298E649D523869C2CB', 6, 'Ready, Set, Pawn', 'The Pawn Stars burn up the racetrack when a seller brings in a competition dragster racecar. Can the guys set a new track record and win the deal or will the negotiation stall out and finish last. Then, Rick and Corey are presented with a Japanese land mine training kit used to train American soldiers during World War II. Will the guys detect a good deal or will it all blow up in their face? And later, Corey and Chumlee check out a fully restored 1957 Dr. Pepper vending machine. Will they pop a cold one just like the Dr. ordered or will this soda machine deal go flat?', '2010-09-13', 21, '/am2RY92ZtYHOrkRAuKYezjkpjbE.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
