INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A90C49D2844C4AEBBA73117F3CD6260A', X'F79F69A8E59141D09D4A3D9683DEFBBB', 9, 'Loose Lips and Relationships', 'Jenn and Tamra put their issues to rest and plan a triple date. Eddie confronts Ryan about all the rumors. As Heather nears the finish line with her L.A. penthouse, she ventures into new territory with a unique business venture and a surprising offer. Shannon strategizes how to handle discussions of her romantic relationship. Emily and Shane work through parenting issues. Gina brushes up on her real estate skills.', '2023-08-02', 44, '/i5wZiqKNJkRZSWHna5G5oWpYM07.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
