INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9361F15EFA648DC92AA7B82E7A07E96', X'3269A890BBA94E6C9278F7EB38EB1720', 11, 'Waves', 'Energy, things like light, heat, and sound, moves in waves. You’ve probably seen waves in the ocean, or ripples when you throw a rock in a pond. Moving energy is not like the wave you do with your hand.', '1995-04-21', 26, '/nhTm54m4ldcGF8NzPIgu8pd3itw.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A937562323B447F8A23FF57C664122EB', X'698A60DF8ED44CA9BCB1EBAB343DACDD', 11, 'The Contest', 'George''s mom lands in the hospital; a contest begins among Jerry, George, Kramer and Elaine, involving a naked woman and an attractive man.', '1992-11-18', 24, '/q8vTMeNDqsRuw6Q31fKCUbvYC1W.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A93CBCF54C554087BB4F70B86427CE0D', X'56428E5E7DAA468D8BD2076956507AA8', 19, 'Atmosphere', 'The air that surrounds Earth is called the atmosphere. Compared to the size of the Earth, the atmosphere is very, very thin. It’s made from gases – mainly nitrogen, oxygen, and water vapor, with a little argon, carbon dioxide, xenon, neon, helium, and sulfur. The atmosphere does a lot for Earth. It blocks ultraviolet light and burns up a lot of meteors. It traps in heat, keeping Earth cozy. Even clouds are formed in the atmosphere – keeping the Earth wet with rain.', '1994-12-03', 26, '/ugOMSgOolgd1nbGzIhVLU3GQ1MX.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
