INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A94ECECD7C5E42B8866D7B7801366B8F', X'CA19F89515144988A70995E84EAB7CEE', 4, 'The Spy Who Pawned Me', 'Rick checks out a collection of James Bond movie trading cards. Will Rick secure the cards or will they fall into the fiendish hands of Spectre? Meanwhile, a seller brings in an old Chinese bell, will the deal be music to Corey''s ears? And later, Chum and Antwaun set sail on a trip to Lake Tahoe to check out a vintage sailboat. Will the sail withstand the perils of negotiation or sink to the depths of no return?', '2020-11-30', 42, '/rWvCWoh5K8ZO5rJTN30q2IpYG0b.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9504E0C5F40411D8EDCE83D10A52149', X'BF722849CDDB452B9C0F7F0D96E94C26', 2, 'Honesty', 'When Zach Nichols breaks one of his father’s cameras, he concocts a story to escape blame. However, three cautionary stories he hears up at Plato’s Peak make him see the "big picture", and convince him to confront his father with the truth.', '1996-09-02', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9543C74A2FA4DD5A9F9D9044BF7ED79', X'5704FB3FFBBC417788B09226373A9D4E', 15, 'Episode 15', '', '1965-12-31', NULL, NULL, '2026-04-03T17:20:12Z', '2026-04-03T17:20:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A95525BD2EFF4CFFBAAE53C8AB87B699', X'98D80972E53A43DDA03A7703465E6F87', 30, 'Shekel and Hyde', 'Empty your pockets with the Pawn Stars when the guys eye a 2,000 year old Shekel of Tyre. The same type of coin given to Judas to betray Christ, will they make a deal of biblical proportions? Then, Rick and the Old Man are up in arms over a pair of engraved Colt pistols from the 1860s. Worth a small fortune if they''re factory engraved, can they connect them back to the Colt Armory? And later, when one of Rick''s purchases turns out to be stolen, will the guys ever let him forget it?', '2013-02-25', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A95856A94D7D4E019C64319D3BC29DE3', X'7BC54DF3F32A454EAEF6A9436C35D53B', 18, 'Episode 18', 'Rogers enters with a typewriter and the many ways to put the word "typewriter" to paper. In the Neighborhood of Make-Believe, an artist draws paintings of King Friday and Queen Sara.', '1970-02-25', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
