INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A965A137299D40C786AE96EF97AA119D', X'97A3D1F5A8F147CD81222E74A092836D', 8, 'Get the Message (4)', 'With the team reunited and Ghostwriter back. the team puts a phony ad in the paper to catch the art thief.', '1993-10-24', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9703F1C3FAD4DD2B30AA1901F87E977', X'ECB64EF34F8045A7B4A9C04434B02E35', 22, 'Bang Bang', 'Join the front lines with the Pawn Stars, as Rick gets spooked when a WWII embalming kit invades the shop. Will Rick be able to dodge its gruesome history to make a death-defying deal? Then, Corey and Rick get fired up over a pair of Reid knuckle duster pistols. Can they hit the bull''s-eye with these rare guns or will the deal end in a standoff? And later, Rick has plans for a new company website, but Chum has plans of his own.', '2014-03-13', 21, '/wUcK15GWYaUkvqZjvvBMRSWvTqX.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A975812EDECD4C809B97E8135668542C', X'432A6ABDDCCA44CC82CEFB39E33B8949', 4, 'Episode 4 (#1134)', 'Rogers discusses the about string quartet (e.g. violins, banjos, guitars) and hears each instrument at Negri''s Music Shop. In the Neighborhood of Make-Believe, Mr. McFeely delivers a bass fiddle to King Friday.', '1971-02-18', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A976FBFF685C47C79DBC265BC3290A1B', X'FE19A277AED844DFA4ACFC1C4E9941B4', 11, 'High Heels & Record Deals', 'NeNe organizes an over-the-top high heel marathon for her Twisted Hearts Foundation. Lisa and Ed make a tough decision about his NFL career, and Lisa takes a pregnancy test. Despite her engagement with Big Papa, Kim moves forward with starting her wig business. Kandi confronts Kim about not attending her show, and then flies to LA for an important meeting at Capitol Records about a possible record deal. Shereé shoots a promo video for her upcoming fashion show, but Dwight is so not into it. NeNe meets with her uncle and must decide if she’s finally ready to meet the man who claims to be her biological father face-to-face.', '2009-10-08', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
