INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9786769C32E403DA1A1550A50E19BF7', X'AE8F64D94B834147A44CBFE720381F8E', 12, 'Mary, Mary Quite Contrary', 'Mary Mary Quite Contrary walks along Sesame Street and dumps a pile of dirt outside Oscar’s trash can. Gordon explains that she can not leave the dirt; she is making a mess! Mary Mary insists that she is going to grow a garden with silver bells and cockle shells. Gordon tries to tell her that silver bells and cockleshells aren’t alive. Gardens need to have things growing in them, like vegetables, fruits or flowers. Mary Mary decides she will grow flowers in her garden by using dirt, sun, and water.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A97B378F05FF47A2BC4492CF40EE5A7C', X'8B07363E5F5445D6B036B43793F7AF74', 10, 'Pick a Car, Any Car', 'When the Read family car breaks down, Arthur is heartbroken. He wants to save the vehicle before his parents replace it.', '2002-11-25', 13, NULL, '2026-04-03T17:37:57Z', '2026-04-03T17:37:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
