INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9949FDF36F34403A293367325C0EEC7', X'05C0E384194C44179F62803EB615E409', 70, 'Glass', 'Title number 0070. Opens with Mister Rogers arriving with a briefcase containing glass blown animals made by Mr. Zandhuis, who then comes to show how glass is blown into different shapes, such as a swan. Henrietta must tell everyone how to get to "Someplace Else", which is where Donkey Hodie lives. Lady Aberlin coerces the king to come with them by telling him one of his famous speeches is expected. Everyone travels from the Neighborhood of Make-Believe to his mysterious home at the Windmill so that Donkey Hodie can get his wish of visitors all day long. Mr Rogers sings "Once Upon Each Lovely Day".', '1968-05-24', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
