INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9C13812BD8243978D561DB408C5B086', X'262E8E7CFA784578A216ADD6F184C4D2', 4, 'Carving Into Polygamy', 'Candy, pumpkins,and Polygamy: The Brown family celebrates Halloween with 16 trick or treaters, 21 colorful costumes, and 24 great pumpkins.', '2011-04-03', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9C2BBC2D9D74A2A9628ED666E96B3D6', X'3EE646E823AE4DECBBC6C7E6A210D55B', 31, 'Oscar tells the story of the "Knights of the Broken Table"', 'In today''s Grouchketeer meeting, Oscar will read the story of Grouchelot. Oscar returns to tell the rest of the story: Sir Worry-a-lot (Telly) wishes to join the King''s court, but first he must pass some tests.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9C3942C3051416F9C0102C54E023A55', X'0E4196154C964DDE8ED2715770BA77BB', 25, 'Let It Go', 'When Bear visits the kitchen for a glass of water, he finds Pip and Pop wanting one as well. They make a dash with the water for the Otter Pond, saying that they have a "serious situation." They tell Bear that they''re worried the Otter Pond is going to dry out and Woodland Valley will turn into a desert. Bear offers them reassurance and then seeks to find out the origin of this rumor. It turns out to have come from a rather surprising source. Later, when rain finally does come in the form of a storm, both Bear and Shadow do their best to assuage the kids'' worries. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9C5B52374224F7B919AF15CECCE3FE8', X'FED71EEA5D41479CB12ABEB733409C5C', 20, 'Bert''s Sign Painting Challenge', 'Chris helps Bert calm down as he struggles with letters that look similar.', '2015-02-19', NULL, '/8yDehz0iEF4yhWGfHY9E2BiiSu.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9C93ECE6AE049D6893FB558787B0D7F', X'FA6F43F4B9444C33AC69DDDBF54C0C16', 1, 'Rapunzel', 'From High atop a tower, a beautiful young woman lets down her hair - and lets in love. Thats the time-honored story of Rapunzel. Shelly Duvall, producer of the entire Faerie Tale Theatre series of which Rapunzel is a part , stars as the maiden.Jeff Bridges is the prince who climbs to Rapunzel''s balcony via her long , long hair.And Gena Rowlands is the lovely, but wicked witch who tries to keep them apart.', '1983-02-05', 51, '/2dY9STZD8EfuKvc61tQDEt5sEKD.jpg', '2026-04-03T17:38:40Z', '2026-04-03T17:38:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
