INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9DAFC45E4BB435B81F4A5A66F4A9A79', X'D405F9734C7E4CB6B7C0D09A884C9B35', 18, 'Reunion (2)', 'Conclusion. Andy Cohen hosts a reunion installment featuring the upper-crust Big Apple ladies, who recall Season 4 dramas and field viewer questions.', '2011-08-01', 63, '/kDJprj2VC0oEkldKVSC5kcVKgSi.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9DB99B6F5B1492B80E6642662BDC68B', X'BFDF87FF01DD4B5494BD19B384F41BDB', 12, 'Stage Moms and Dropped Bombs', 'Shannon panics about her families'' impending move, while her daughters prepare for an upcoming rock show. Vicki celebrates Briana''s birthday and makes it uncomfortably clear she is ready to fill up her love tank. The ladies come over to help Shannon purge her outdated closet; however tensions run high over unresolved issues between Shannon and Kelly, as well as Tamra and Meghan. Friends and family gather to watch the Beador girls perform, but Shannon''s night is rocked by a shocking allegation from an uninvited guest.', '2016-09-19', 44, '/7SSlcrZAiyy8ALArTIRGCKQrAGh.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9DBCB4DF8794D8393FB1138E3D91D6F', X'C4D795AE6AFA47D698194DD057030A3C', 4, 'Pass the Peach, Throw the Shade', 'Porsha faces Dennis'' mother; Kandi and Todd meet with Dr. Jackie; Shamari drops a bomb on her mother-in-law; Cynthia hosts a Bailey-Cue; NeNe hears a surprising rumor; the ladies find themselves in the hot seat during Cynthia''s Pass the Peach game.', '2018-11-25', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9E5B25B2AF14BA8B71F3C0CA736C34F', X'3EE646E823AE4DECBBC6C7E6A210D55B', 92, 'Cleaning the vacant lot', 'The gang makes it to the lot where they meet its residents, Audrey and Louise, the Pigeon Sisters; Oscar takes an instant liking to them. Louise has a big appetite and continues pecking at the sign, mistaking it for a cracker. Audrey helps her read it.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'A9F4576715AD415F9804039BA9BE762B', X'ACAC417E2AA342E79E08ED0D6071A3EE', 1, 'Ghouls Just Wanna Have Fun', 'The ladies of New York are back after an eventful summer. Newly divorced Luann sits down with Dorinda and starts to open up about her relationship with Tom. Meanwhile, Bethenny mourns an unexpected death in the family. Typically reluctant to exercise, Carole preps to run the New York City Marathon. All the ladies reunite when Dorinda throws an epic Halloween party that nobody will forget.', '2018-04-04', 60, '/1DO2GbHWSpZ1AdyfprhqMYz6tLr.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
