INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AA42A4CC64C74769BED4632B903EDBE6', X'73AE1459BA914185A9DABF6F2844AF49', 16, 'Not Very Merry-Achi', 'Luann hosts a spa day for the women she met through the Fortune Society. Ramona gives Sonja a talking-to over her birthday night antics and gives Leah the cold shoulder. The women head to Cancun, Mexico, where Leah confronts Ramona.', '2020-07-30', 60, '/gYxafWcwHXtr7ZK7MLQk8jqoImC.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
