INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AA4845B46CD04395B8DE307CE9F3D3C2', X'E6EA14319E67463783AEA11073E8C7E0', 2, 'Ciao, Tuscany!', 'Kyle and Lisa Vanderpump are enjoying a fabulous time zooming through Italy in a Ferrari and taking in the tranquil countryside when family problems interrupt. Meanwhile, back in Beverly Hills, Yolanda takes drastic measures to improve her health and Eileen and Lisa Rinna are stunned by her condition.', '2015-12-08', 43, '/pcQZ5GFVFggO95jq25LVInfJGwp.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
