INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AA857D29F5584C019C232329DC3E71A1', X'91F66DA756A2423AB855F09D582805B2', 8, 'The Three-Legged Pot & When Jabo Jammed', 'Leona makes a three-legged pot dance; a boy named Jabo doesn''t dance or sing, but he can jam.', '2007-11-05', 30, '/oOwr4iYzc5OovtnuAKzuC4fLJcg.jpg', '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AA94AC4A071B442088D97AADA25A0625', X'90CC8678A14F4D05BC1E54A3117895D5', 7, 'The Feud Begins', 'The animals grieve when Dreamer, Fox and Vixen''s cub is found dead. Although it cannot be certain as to the cause of death, Fox believes that Scarface is to blame. The impulsive Bold slips away and wanders into Scarface''s land, where he meets Ranger, Scarface''s son and tries to become friends. Scarface spots them and imprisons Bold in his earth.   Fox and Friendly enter Scarface''s land in an attempt to rescue Bold, but soon become surrounded by blue foxes. Fox manages to convince Scarface to allow Friendly to return home.    Meanwhile Bold was able to cunningly escape just as his father and brother trespassed onto the blue foxes'' territory.   Weasel informs the White Stag about the situation and he steps in to prevent any feuding. Fox is allowed to return to Farthing land, only to find Bold was already there. Fox is infuriated with him and tells him that he will remain where Fox can watch him at all times and is not to wander off. Bold can not take it and feels the park isn''t big enoug', '1994-02-18', 25, '/phRnUuUq6MwRnH0Bm1ZXdv0yU9L.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
