INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AAA803A6583C45C58FD61264C5B3DD9F', X'B1D55597D9D24EEEAB9546DBB163291A', 8, 'Pingu and the Avalanche Incident / Barrel of Fun', 'Robby plays around some barrels near some ruins, when he sees a barrel that is half covered with planks, like a sledge. Pingu comes around and he and Robby play with the sledge-barrel. They go down a long and winding hill two times, with Robby being the brakes - almost crashing into a sculpture both times. Unfortunately, when they go down a third time, they lose control, and Robby falls off and Pingu crashes into the sculpture which collapses over him, trapping him inside. Robby goes for help, and gets an emergency paramedic to lift a slab of ice from the rubble in order for Robby to slide under and get Pingu. He gets Pingu out just before the paramedic''s arms give way to the weight of the slab. The paramedic then puts a patch on Pingu''s head, and he, Robby, and the paramedic leave.', '1988-10-29', 5, '/a9HHpnoo4JJ1Dqjx3SKrspRCc49.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
