INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AB4576B56BB74ED7B6C8FB51D1C5D8A4', X'BD8A516B9872472DA8387AFF1070FEA3', 2, 'Madeline Kahn', 'Madeline tells Gonzo she thinks he''s terrific on the show, and the ego-starved Gonzo instantly falls in love with her. He drops in to Miss Piggy''s dressing room to tell her he no longer has a crush on her, which pleases her until she finds out that he likes someone else. Gonzo''s obsession takes him to the brink of marrying her until hearing her comments to Kermit of his going off the deep end breaks his fragile heart.', '1977-10-07', 26, '/iwpmZLm16pHMt7h33iHwaIA4WLG.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
