INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC11BA4C9D3847C6BD443235A8E2757C', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 7, 'Inside Looks: The Robbery', 'Inside look from the season 1 episode "The Robbery."', NULL, 3, NULL, '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC171E17FC9B4B73A75A1DB2A0109380', X'6C1EC19F74DF4F359A6117B98175D826', 18, 'Reunion (2)', 'Kyle takes a turn in the hot seat when she is left to answer for her attitude towards Dorit and Erika. When her daughters are brought up in conversation, Lisa bares all and addresses Garcelle’s implication that she has a need for attention. Teddi reflects on the exhilarating joys and crippling fears of parenthood during a pandemic. A defiant Denise comes under fire for her connection to Brandi Glanville, but Garcelle and Dorit maintain their loyalty and quickly come to her defense.', '2020-09-09', 43, '/c6tJ5C33QRtONrTwOEpEtYlQfeU.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
