INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC2242ED042E4D2EA09D43F50F69A982', X'D122D150FB7F46FAB9E163D3B08A118C', 1, 'Episode 1', 'The Clock family - Pod, Homily and Arrietty - make a new home for themselves with their relatives Uncle Hendreary, Aunt Lupy and Eggletina.', '1993-11-14', 30, NULL, '2026-04-03T17:17:47Z', '2026-04-03T17:17:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC25D95E125E45D5BD26336B52D63CE9', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 23, 'Dollars & Dunks', 'Shoot some hoops with the Pawn Stars when Rick checks out a warm-up jersey signed by The Black Mamba himself: Kobe Bryant. Will he make a slam dunk on a sale or buy nothing but air? Then, Rick has an axe to grind over a seller''s asking price for an antique weapon and Corey might be Leaving Las Vegas when he makes an impulse buy on his favorite book. Later, Rick and Chumlee will either raise a glass for an old-timey toaster or get burnt on a no sale.', '2017-07-24', 21, '/7A6tEF8kQfpnlzdIZe3YtEzDdjz.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC2C943E3BD344A6956656E205FA3B13', X'5B5E8B2F0A854488B3DC3D8B794E6582', 18, 'The Real Vikings of Orange County', 'After being hurt by Kelly''s words, Peggy reveals a secret video to Lydia. Meanwhile, the rest of the ladies whoop it up at a Viking dinner where Tamra and Vicki continue to get along, much to the dismay of Shannon. When Peggy finally arrives at the dinner, her preemptive strike on Meghan thoroughly backfires. Once everyone returns to the OC, Shannon discovers the nature of her unbalanced behavior, but also finds her marriage on thin ice.', '2017-11-06', 44, '/kGEVSs8Yi2Y5vIoF1uVbRKJNSqU.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC33CD372324468EAB18055FFB580C1B', X'1A534647384B4C00BB6CA3371AD962EB', 14, 'Sword Play', 'Ride along with the Pawn Stars when a 1951 Willys Wagon pulls into the shop. Will Rick kick the deal into high gear or will he fall off the wagon? Then, Rick takes a stab at a pair of 19th Century European swords. Will he keep his edge or will the deal be cut short? And later, when the guys realize Rick hasn''t shown up for work, do they send out a search party or throw their own?', '2015-03-05', 21, '/A7g4G8mwekYsfVTk0dZNnW5wIOJ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC3670A0C86943189E72728E5183D4CD', X'A1B69730D22548F2A7E71D314CF3B349', 24, 'Episode 24', 'with Valerie Singleton, John Noakes, Peter Purves', '1968-12-12', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC369F9D072E4B358C6E2ED0F93FD538', X'1A534647384B4C00BB6CA3371AD962EB', 38, 'Greatest Gambles', 'Roll the dice with the Pawn Stars and revisit the greatest gambles in the shop''s history: an antique White Eagle medallion, a book possibly signed by "Shoeless" Joe Jackson, a questionable Gibson mandolin, a rare Albrecht Durer etching and a 1984 Chris-Craft boat that leaves Rick questioning Corey''s judgment.', '2015-07-20', 21, '/aqepigkIWTckDNjOfwwH9iXgE7m.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC37FF8003404663B4E2123F4254A110', X'BF722849CDDB452B9C0F7F0D96E94C26', 5, 'Courage', 'When Annie Redfeather hits a hurdle and falls flat on her face during a track meet, her friends at Plato’s Peak offer several stories to bolster her courage so she can face the next big race.', '1996-09-04', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC395DE042944E18AAAD2A24015EF38B', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 17, 'Measurement', 'Did you know that the Concorde moves 300,000 times faster than a land snail? Or that a giant redwood can be as tall as a 35-story apartment building? The only reason we can make these comparisons is because people have measured these things. We don’t compare jets and snails every day, but we do rely on measurement constantly. When you take your temperature, you find out how it compares to the temperature of someone who is healthy. When you bake brownies, you’ll need to measure the ingredients first to make sure they turn out tasty. Using measurement, we can make useful comparisons of distance, time, mass, and temperature.', '1998-05-30', 26, '/9ArUdfIwBo7zrjPqo4XD81jwPAd.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC398FC087724EF0A85F9154D6C62058', X'1BE79A20DE3341D1AF17079035B18D5C', 104, 'Episode 104', '', '1970-04-02', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC3CB44F109447A8BFD550C6E02FE07B', X'06030129FF2D4490B66C9F41BBE7AABD', 2, 'Painting', 'Tree branches scrape against the Ragdoll, scratching off its smart paint. So John goes out to the shops to buy some paint to make his boat look nice and shiny again. Rosie and Jim do some painting of their own, and they learn about mixing colours together to make even more colours.', '1990-09-10', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC3F9424528247E9B7F8F9C0D06FAFB7', X'3EE646E823AE4DECBBC6C7E6A210D55B', 107, 'Elmo pretends to be a Grouch', 'Elmo tells Maria that today, he wants to learn how to be a Grouch for a day. Oscar refuses to help, constantly replying "NO" and waving a sign with the word. Maria doesn''t think Oscar would even be able to teach Elmo; Oscar feels insulted and decides to teach Elmo some Grouch things.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC40657EFAE54E7AB4586B26EBF10822', X'F9A8D8B3D72E437EA9D57477F6D64DF8', 21, 'Grouch-ercise', 'Oscar''s been feeling terrible all day, so Elmo, Abby, Grundgetta, and Nina try to find different exercises to help him feel better. As they set off to tell Oscar all the exercises they came up with, they find him returning from a long, grouchy walk picking up trash. Oscar feels much better and is back to feeling good and rotten.', '2023-03-23', 26, '/fTp6gDAbqoZVhNxnBLXCg3ZcFSX.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC43C5CCE4C44355B38070C7D0C0D957', X'9C5608B2511148BCA9077F93472C1E03', 19, 'Best House of the Year', 'The Three Little Pigs build a house for the "Best House of the Year" contest, but it can''t stand up to the Big Bad Wolf''s huffing and puffing. With Leela''s and Elmo''s help, however, they design a new home that can withstand the wolf''s powerful lungs.', '2013-02-21', 58, '/uvPUzV29GHOKpT7c47yy00Ob5As.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
