INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC550D831FCD41E7B36561D56137B301', X'E1063F8766C24E2DA91353362941AA19', 5, 'Episode 280', 'As Bob welcomes the viewers, Sesame Street is suddenly beset with an outburst of jackhammers and roaring compressors. Maria and Tom come by and see that workmen are fixing the street, and they complain about the noise. Oscar pops up wearing a hard hat and says he''s heading to where they''re digging, not wanting to miss all the noise, dirt and mess.', '1971-11-19', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC58A5F68343451391A49C425FE38B19', X'D405F9734C7E4CB6B7C0D09A884C9B35', 3, 'Hairy Mess', 'Alex attempts to mend her relationship with Sonja by having lunch with her. Meanwhile, Ramona, who gained infamy for her wild-eyed runway walk the year before, is asked to appear on the catwalk again. This time, she enlists Sonja for some modeling tips. Also: Alex basks in her new career as a model; LuAnn''s boyfriend throws a get-together featuring wine and speed dating; dramas intensify between Kelly and Ramona.', '2011-04-21', 42, '/wTIlvGl49Wv2D8Dn1Gy3FZJyp1L.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC5B36DF184C45ADBD5255572C96E555', X'684AF21E04594832B094DB0997E354C5', 17, 'Reunion Part 2', 'Hosted by Bravo''s Andy Cohen, part two reunites Lea Black, Marysol Patton, Adriana De Moura, Ana Quincoces, Joanna Krupa, Karent Sierra, and Lisa Hochstein to discuss catfights and confrontations on this season. Alexia Echevarria and Elsa Patton join the ladies to rehash the drama.', '2013-01-03', 44, '/cfFrItt1Q4bJd73uKmMVrneHlmr.jpg', '2026-04-03T16:35:10Z', '2026-04-03T16:35:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AC5DCA87FEDD475EA85576799EAB08BE', X'0E4196154C964DDE8ED2715770BA77BB', 17, 'The View from You', 'At Mouse School, Miss Maxwell shows the mice a fruit bowl and asks some of them to tell her what they see. She explains the idea of point of view and assigns everyone a project to demonstrate their point of view to the class. Tutter struggles with the assignment --- as far as he''s concerned, he sees things from a "boring old Tutter point of view," and not any differently than anyone else. After hearing about the assignment, Treelo paints some paintings to show his point of view. Meanwhile, Tutter finds a camera his Grandma Flutter gave him and decides to make a film called Mouse on Mars --- but not only does he not know much about Mars, it doesn''t really represent his point of view. He joins Bear in listening to a Shadow story about the point of view of a duck and a ladybug. Afterwards, Treelo''s paintings provide inspiration.', '2006-04-21', 25, '/nZ7kRkrh27poOS5DWP9w6bwKzHl.jpg', '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
