INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ACE16230722D48E98E0AA0A0A481F732', X'21745B85D26942FAB4DD701B2DA5C085', 52, 'Episode 52', 'with John Noakes, Peter Purves, Lesley Judd', '1974-03-11', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ACE58BC7B2D44118A7F98800CAEA9B1F', X'3982796B54514100904246BEDF6A20A5', 23, 'Pingu Visits the Kindergarten', 'Pinga is waiting impatiently to go to kindergarten, but Mother is busy and gets Pingu to take her. On the way they pass Pingo and Pingg on their sledges. They ask Pingu to join them but he refuses. When they get there Pinga is given a piece of paper, and she goes to sit down. On the way she trips and falls over, crumpling the piece of paper. Pingu helps her up. The teacher asks the class to make a hat with their pieces of paper, but Pinga is unhappy that her piece is crumpled, so Pingu asks if she can have a fresh piece. The teacher gives him two pieces of paper and he gives one to Pinga. Pinga tries to make a hat, but can’t. Pingu takes the piece of paper and makes the hat for her. He then uses the other piece of paper he’s got to make a hat for himself. Pingu then joins in the dancing, the session on the school slide, and listens to the story. On the way home they meet Pingo and Pingg by a pool in the ice, who laugh at the hat that Pingu is still wearing. Pingu takes off the hat, folds it into a boat and puts it on the water. He blows the boat into the middle of the pool, but Pingo and Pingg then try to hit it with snowballs. However, they don’t manage to hit the boat as it keeps moving out of the way, They’re puzzled by this until they see why; Robby is in the pool moving the boat from underneath. Robby then does some balancing tricks with the boat, ending up wearing it on his head like a hat, and they all applaud.', '1994-09-07', 5, '/8O2kXQT6Oll25xbEWx9K0u2eCyo.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ACE72A1167764FE993D0BCB847771B30', X'FC120008C5C447D7A3A991A401394C41', 1, 'The Birthday Boy', 'Brother is kept home from school with the flu and neglects to do the schoolwork Sister delivered from his teacher. Then, when Sister gets her first loose tooth, Brother teases her that the dentist will extract it with a big yanking tool.', '2003-01-06', 24, NULL, '2026-04-03T17:40:21Z', '2026-04-03T17:40:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ACEE2FF09EC04DB58BA03E953E59790E', X'ECB64EF34F8045A7B4A9C04434B02E35', 3, 'Truly Trivial', 'Burn rubber with the Pawn Stars as they check out a motorcycle custom-built for actor James Caan. Will Corey make the seller an offer he can''t refuse? Then, an Al Hirschfeld lithograph gets drawn into the shop. The last print made before his death, can they sketch out a deal? And later, when Chumlee find a book of trivia, he tries to stump Rick. Who will prevail in this battle of useless information?', '2014-01-09', 21, '/au9T0BnXJABaZTUilLmWuiD7hvf.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
