INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ACF724D220694A4497D6B621406CB0D4', X'80775C3DFA4146F696ECEFC2E14EFDCF', 13, 'Sonja Island', 'Ramona and Bethenny have a tear-filled heart to heart after the other ladies go to bed. In the morning, Dorinda has a serious talk with Sonja, reminding her to stand up for herself and not allow the other women to walk all over her. Sonja decides to skip the yacht outing where the other women have luxurious day connecting with each other.', '2015-06-30', 60, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ACFCEEE853754DE28522536ADEF6F4CE', X'E03D79BDE01F4414B0B3F3B5F26E97F4', 14, 'Valentine''s Day II', 'Axl has a new girlfriend he wants to impress on Valentine''s Day, while Brick has a crush on a fellow student and Mike accidentally lets the news slip out, humiliating his shy son. Elsewhere, Sue searches for a boy she kissed on a Halloween hayride.', '2011-07-01', 22, '/8ia8auEz7C48cTgCKuMNQu7dzY6.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
