INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AD18D1FC01804CA091C16C362701F86E', X'C67A878749714961B5361FF01924E2A9', 3, 'Arthur Sells Out', 'Arthur is excited about the release of the new video game Dark Bunny: Return of the Moomies, but doesn''t have the money to buy it. When his attempt at online sales through the school newspaper falls flat, Buster recommends getting advice from Muffy. Muffy''s sales tactics soon result in great sales, but border on dishonesty and leave Arthur facing an important moral decision.', '2007-06-26', 13, NULL, '2026-04-03T17:37:58Z', '2026-04-03T17:37:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AD18FF0B255D40B5B346FFB9490AFEA0', X'C4D795AE6AFA47D698194DD057030A3C', 25, 'Porsha''s Having A Baby: Grandmother Dearest', 'Porsha is engaged to the love of her life and expecting her first child. Her fairytale ending is not without its share of drama however, and she and Dennis soon realize that they may be in over their heads. In an effort to garner the support they desperately need, they decide to bring in reinforcements: their mothers.', '2019-05-05', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AD1E1F0D97A84D95A39E1D83C2B1604C', X'1D713CA64E174F84949C8CFD98514127', 5, 'Pawn Apocalypse', '"Walk this Way" with the Pawn Stars when a pair of vintage Aerosmith tour shirts jam into the shop. Will Rick feel "Sweet Emotion" for this rock star memorabilia, or will he "Dream On"? Then, Rick and Corey sound the alarm when a U.S. Navy foghorn comes ashore. Will the guys successfully navigate the deal or will they have to keep their distance? And later, Corey braces himself for the apocalypse when he checks out a state-of-the-art survival vehicle, built to fight off zombies. Will Corey escape in style or will he let the deal die?', '2014-07-24', 21, '/yD88CjBl6FK2WaO4GBJLbMCUikJ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
