INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AD23114DBA9448BCB4D42403FED13AD7', X'34674C90410E427CBE4D2A6F6F865A80', 9, 'Three Hour Tour', 'The Pawn Stars try to cash in when a seller presents them with rare $1 and $5 bills from the 1800''s. Will they see dollar signs or will the asking price break the bank? Then, the guys plug their ears when a Big Bang Cannon pops in. A tiny toy that makes a big boom, but will it work? And later, a guy pings the shop with a memento given to U.S. sailors who sank U-68, Germany''s most feared WWII submarine. Will Rick set his depth charges on "buy" or let this deal sink to the bottom?', '2012-05-28', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
