INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AD4CCCC01D7D47A1B9AFD38A05EC1FCB', X'943B0C940CC540E8A0E1BD5660772CC3', 10, 'You Want to What Me in the Where?', 'Ramona invites all the ladies—except for Heather—to a dinner, but the heat is on when LuAnn slights Carole. Elsewhere, LuAnn throws a holiday party, where a boozy Sonja squares off against LuAnn and the ladies get up on stage to sing.', '2012-08-06', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AD56097333224CAE822012BC7DFEEEEB', X'5B72E664D3D7435DBDC3A23D29D1178E', 12, 'Old Bear''s Chair', 'The toys are having a wonderful time using Old Bear’s special chair as a slide. Finally, when Ruff has a go, it collapses and, however hard they try, they can’t put it back together again. They decide it must be broken and are worried what Old Bear will say when he finds out. However, when at last they pluck up courage to confess, Old Bear shows them how easy it is to mend a deck chair ... if only you know how!', '1994-11-22', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AD5B5E949A104B4A90A6B0EDFAF0AA4C', X'E40E6B639F84449F8E8853209B0906C8', 1, 'The Bookaneers', 'Elmo and Alan are reading in Hooper''s Store, when they both hear a boat, then see it (includes a rare appearance of Sesame Street) and the storefront is boarded by a group of Bookaneers. An Anything Muppet and a salty dog are led by their pirate captain, played by guest star Tina Fey. They demand that Elmo hand over his book, but Elmo explains that he loves to read. The pirates invite Elmo to become a Bookaneer, but he must first pass a series of tests.', '2007-08-13', NULL, '/ee3NVlQhmYQUeWhuRUMTK8sTkrs.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AD69D2136FAC4E1E940050EC6D926F56', X'3269A890BBA94E6C9278F7EB38EB1720', 3, 'Plants', 'A plant’s recipe for food has only three main ingredients: sunlight, carbon dioxide, and water. When plants make their food, they give off what animals need – oxygen. Without oxygen, animals like us wouldn’t be able to breathe. If plants weren’t here on Earth, we wouldn’t be here.', '1995-01-28', 26, '/73gFycd6jDUdaXzv4RA8UE1jGCD.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
