INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AD80B3247A304731AA1991F9EFFA0D14', X'937EE587E2EB46AA9A693D6BAB04398F', 3, 'Chickens Aren''t the Only Ones', 'LeVar wants to find the answer to the old question, "Which came first, the chicken or the egg?" Posing as field reporter for E.G.G.-TV , he uncovers other discoveries instead, such as loggerhead sea turtles emerging onto the sand to lay eggs. Georgia Engel narrates Chickens Aren''t the Only Ones, a book told in rhyme showing all kinds of animals who lay eggs like chickens.', '1987-06-24', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AD8DC61A25FD4DCD9680CB18A61C1945', X'F0F8B366CB3340B3A50FA1CA7780916F', 6, 'Beyond the Pond', 'Red and Gobo''s swimming competition is interrupted by the annual arrival of the Knobblies, pink vine-like plants which are particularly thick this year, and which turn out to lead to something quite unexpected.', '1987-02-09', 24, '/6dEIsfideg9Qzj3usrUjZ7NFSld.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
