INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ADA8CD69AF7B46F48F93E010A42E4118', X'7B19039A31AC425C8FB1B51CF2447821', 15, 'Reunion (1)', 'The reunion begins with Shannon on defense regarding the disparaging comments surrounding Gina’s new home and her involvement in digging into Elizabeth’s past. Tensions flare when Kelly and Emily call out Braunwyn for deflecting when she makes an accusation about Shannon. Andy presses Kelly about her controversial comments surrounding the pandemic, and Emily gets emotional about Shane and their experience with COVID-19. Braunwyn reveals a surprising connection to Elizabeth’s past leading to an explosive confrontation. Emotions run high when Shannon reveals Braunwyn’s involvement in a serious incident with her daughter.', '2021-01-20', 44, '/5KA1rV2KrsJdkNI2yXimOxk0ZTv.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ADB67EC7017B4E59BE5C616F2E18EE2C', X'136B81D3964D4B8FA21492F00D96D6B9', 93, 'Snuffy sleeps over at Big Bird''s', 'Snuffleupagus spends a special sleepover at Big Bird''s nest, and the two friends stay up late talking, playing games, and having pillow fights. Big Bird worries that Snuffy might be uncomfortable in his nest, but Snuffy assures him it''s absolutely perfect. The happy friends fall asleep together, grateful for their special night.
