INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ADE8EFA03DD4489AADC307E88E1C9332', X'EAE164B17FAE44BA8ECB7B089255345C', 4, 'How They Got Here', 'The saucy socialites from Manhattan return in this half-hour special featuring highlights from the past two seasons of drama, shenanigans, friendship, conflict, and more drama. Get the tea on Bethenny’s game-changing return, Luann’s quest for love, Sonja’s rebound from financial woes, Carole’s unconventional romance, Ramona’s reemergence onto the dating scene, and Dorinda’s introduction into this tight-knit circle of friends.', '2020-04-09', 60, NULL, '2026-04-03T16:35:21Z', '2026-04-03T16:35:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ADEE88EEE19E455EA17278A324007DE0', X'939D270CEA8E4CC8A5A5E59DF2C8062C', 3, 'Lemons Into Lemonade', 'It’s Fashion Week in Dubai and the designers aren’t the only ones putting on a show; Ayan and Brooks deal with the fallout of their argument at Nina’s dinner; Caroline worries about Serigio’s baby fever.', '2022-06-15', 43, '/62Zv9xTtPVAQUqSr2CUv1Fspd42.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ADF336CB80B14F669B06D6C32F57A85F', X'2F8DD62982C34F8E87C0963473C49284', 9, 'Coming Clean', 'At Ubah''s pigeon picnic, Erin finds herself in hot water with the ladies, leading Racquel to question their friendship; Ubah notices a fertility specialist to discuss options for starting a family; Erin opens up to Jenna about a secret from her past.', '2024-11-26', 43, NULL, '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ADF362318A174551846254C00F9CC8F1', X'4C79C0B621A442778967BE1E791EFDBE', 3, 'Pottery Pingu', 'Pingu and Pinga are at Grandfather’s house. Pingu is a bit curious about what Grandfather is doing. Grandfather says that he’s making pottery, and Pingu really wants to try it. Grandfather helps Pingu to try, but it doesn’t go quite right and all that remains on the wheel is a piece of clay shaped a bit like a crown. Grandfather then goes to fire the vase he made previously and the piece remaining from Pingu’s try. Pingu then gets an idea; he could try doing pottery by himself, but Grandfather tells him not to. Pingu then has several tries while Grandfather isn''t looking, with the starting piece of clay larger each time and with Pinga either helping or standing guard. The first two tries are unsuccessful, with the clay ending up being splattered about. On the third try Pingu attempts a large vase. This also flies apart and the clay breaks some of the pottery that Grandfather has made, in particular the lid of a vase. It also covers Pingu and unfortunately splatters Grandfather, who has just opened the window of the igloo to see what is going on, as well. Grandfather is not too pleased, but comes out to decorate the pots he’s just fired. He’s even less happy when he realises that the lid of a vase has been broken, but Pingu suggests trying the crown-shaped piece of pottery he made earlier. It’s a good fit, and they all end up happy.', '2005-01-05', 5, '/rDKnosmUOXxmpAHO035D9m5U1hJ.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
