INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE0183F020EC48679EB645FE316120B5', X'E1EF357B4EDF412AA7857060C0E33BD2', 12, 'Madeline and the Wild West', 'Madeline rides a pony named Gallop in the world''s biggest rodeo, Cheyenne Frontier Days in Cheyenne, Wyoming.', '1995-11-25', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE024B8E7035407C9A5B28519AC04A45', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 3, 'Oh Holy Pawn!', 'Get holy with the Pawn Stars as Rick gets the chance to purchase a page from the Gutenberg Bible. Known as the first printed book, will the single page break Rick''s bank or leave him wanting more? Then, Corey checks out a rare six-sheet movie poster from the classic "Ziegfeld Follies" that''s so big it doesn''t even fit on the counter. Will he offer a larger than life price, or leave the seller singing in the rain?', '2017-04-17', 21, '/4694GwQVaN7sxl7BVnzIiqjKzNt.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
