INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE06C09DFAC34B5EB3A6737DC55482E0', X'5A771F52FE964EA2B567A8DDE899059E', 22, 'Blades of Deal', 'Rick drives up to a 1984 Ferrari 308 that he hopes to drive off with. Can he accelerate a deal, or will the high asking price throttle negotiations? Corey is all ears when a seller brings in a phone-operated music player from the 1930s. Rick throws his hat into the ring for a cowboy hat owned by Larry Hagman of the TV shows "Dallas" and "I Dream of Jeannie." Later, a Vegas Golden Knights hockey jersey signed by goalie Marc-André Fleury gets an icy reception from Chum and Rick - until Fleury himself skates in to tell them whether it''s authentic.', '2018-02-26', 21, '/sgJXVkvZcUrS94owBWxsYLZ7M1L.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
