INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE0BD76D9FE6407FAF8492A6D4A5D2B8', X'BB5A884361814A6DBFDF33EF2C6BE7B8', 3, 'Chateau Get Down', 'Porsha clings to her family after losing yet another friend, but is shocked by accusations from her sister. Meanwhile, a new man challenges Cynthia''s singles game. After an unexpected incident, NeNe is suddenly left home alone to fend for herself, while Kenya struggles to find new ways to connect with her long-distance husband. Shereé plans to turn the Chateau into a disco palace, only to have the dance floor pulled out from under her when the party planner leaves her in a serious bind.', '2017-11-19', 43, '/51GfkrmZ6nAjFIFbtnDTlmYtDHF.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
