INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE144B4A11B6477FA6990BDD0B9D4287', X'54FACB0BDB5941FE9D64C7C7221A3C81', 4, 'Making Up Is Hard To Do', 'Bethenny throws a lunch sit-down with Dorinda and Luann so the two can hash out their issues. Later, Luann begins her court-ordered community service and discusses her first meeting with her parole officer. Tinsley gets a visit from Dale, who puts pressure on her to figure out what''s going on with Scott. Ramona goes on a blind date, while Barbara is shown the door by Dorinda.', '2019-03-27', 60, '/uT2x2QuMSaj6KfM75DyEUFLXBB7.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE1881E8B4F0485BB1AD724384AA5BEF', X'96DD06EED44A47F39372E29E8EAA77F5', 1, 'Treasure Hunt', 'Sam introduces Sarah and James to his new metal detector, and they get hooked on looking for treasure. Unfortunately, they manage to burst a water pipe in the park while searching for Bella''s keys! Meanwhile, Norman''s game of ''Knights Of The Round Table'' backfires when his saucepan helmet gets stuck on his head. Overall, it''s a busy day for Sam and the crew...', '1988-09-01', 10, '/j8CQwbECH2Yh8HQQ9hFXvGjPYKd.jpg', '2026-04-03T17:14:37Z', '2026-04-03T17:14:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
