INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE4CFEBC0B3E4F9FA8112DC5EE7EE7F9', X'7C75633629DB4634B976E993E8F51DA2', 10, 'Welcome to the Bermuda Triangle', 'A "bonding" excursion to Bermuda turns cold when some of the women are shut out of the trip. Robyn makes a critical relationship decision. Monique and Gizelle at last address their issues. The ladies take a sunset cruise.', '2017-06-11', 42, '/bXmoX7NsXoc7fl7r5Uk1k1iPlwD.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
