INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE53BBA57F7647699EE206A0BC624A28', X'D1863F2F02EC40CEAF64DB03FBE518A7', 3, 'Grover''s Street Safari', 'Grover takes Elmo and friends on a Sesame Street Safari and they pretend to be all of the wild animals they see. Also featuring Cookie Monster''s Smart Cookies, and Elmo the Muscial-cowboy. Brought to you by the letter S and the number 5.', '2016-01-23', NULL, '/3sNWZpGWPwg8N9AVdLndzqY1t9g.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE54A75DAE5E4D7399006B639B56CF68', X'56428E5E7DAA468D8BD2076956507AA8', 15, 'Forests', 'In Bill Nye the Science Guy: Forests, Nye shows students the levels of a forest, which include the canopy, the under story, and the floor. His special guest is Nalini Nadkarni, who has no qualms about going high up in the canopy to check out the wildlife and other happenings there', '1994-11-05', 26, '/53Pkvk4kTYXZ8VBTBLwKrTlfSF8.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
