INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE6F355BD4F9409BA291B347D23D9431', X'DE8EC76916BB436BBE43AEDC7E18A7D7', 15, 'There''s a New Count in Town', 'Charlie is counting everything on Sesame Street so the Count decides to leave, thinking he’s not needed anymore. But there’s too much to count for Charlie on her own so she asks for the Count’s help. Charlie explains that she loves to count but she could never take his place. The Count agrees to stay and he and Charlie continuing counting together.', '2020-02-22', NULL, '/7E409c5zSU9wZLrjmVKeGalfNTP.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE6F8D8D164345D7990EF135F79FCEA9', X'0A9ABA05559F4DB4A6CA8AC35CC378D1', 8, 'No One', 'While Jaime weighs his options, Cersei answers a request. Tyrion''s plans bear fruit. Arya faces a new test.', '2016-06-12', 59, '/xl2l1a3kXGxWwZqGDgjowBk4x46.jpg', '2026-04-03T15:40:37Z', '2026-04-03T15:40:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE76DB198D424AFE8A502B8DEB29F221', X'F4C403079B5E4263A4E0DFA138131E7F', 17, 'Elmo Says Boo!', 'Elmo visits The Count''s castle to tell him funny scary jokes. Classic Sesame Street segments are separated with new joke segments set in the castle''s exterior, featuring one Sesame Street character and a child, and interior, featuring The Count, Elmo, and some combination of the Bats, the Skeleton, a painting of the "Groana Lisa," a suit of armor and the Count''s pipe organ.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE77D471618B47C29D3C36FD937987EA', X'5BA20443D99F482081F66832D3F2BC4F', 20, 'Time', 'Time affects every living thing on Earth. Trees shed their leaves. Some animals only come out at night. There are even insects that only emerge every 17 years. Days, hours, minutes, and seconds – all of these were invented by humans. Humans came up with these units of time to organize their lives and to study the world. One of the first ways humans told time was by noticing the difference between daytime and nighttime. Humans use the Earth revolving around the Sun to divide time into years and seasons. Months are based on the movement of the Moon around the Earth. A day is when the Earth spins completely around its own axis.', '1997-09-12', 26, '/oDIJvvZpEpecmwiMyRM2d90Md6L.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE78C082738343D8813E417AAA8469A0', X'D1863F2F02EC40CEAF64DB03FBE518A7', 2, 'Mucko Polo, Grouch Explorer', 'With Mucko Polo (Alan Cumming), Elmo, Abby, and Oscar use their five senses to explore and search for the grouchiest things on Sesame Street. Also featuring Grover finds a pyramid and Elmo the Musical-Guacamole. Brought to you by the letter E and the number 6.', '2016-01-16', NULL, '/cY20trMI7vps2VWJE6HIspzRkgI.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE837CE13C9A43F5AE66E0A3E47258D3', X'3D4D8F6A970847E89C9926EBAFDB2609', 27, 'Episode 836', '', NULL, NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE8523868ECA48D99B9F948EA530DAF9', X'994C75E506FA4BE1A142EA7B2C892DD0', 1, 'Curiosity: A Field Trip to ''The Edible Schoolyard''', 'Rogers uses a frame to concentrate on small sections of a large mural. Seeing a set of vegetables in one section of the mural, he reflects on a visit to a vegetable garden, referred to as an "edible school yard". In the Neighborhood of Make-Believe, King Friday is irritated when Purple Panda and his compatriot, Little Panda, fool him. He commands that they cancel all curiosity.', '2000-09-07', NULL, NULL, '2026-04-03T17:35:49Z', '2026-04-03T17:35:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE863923A0DC41CA8F059F3ED33D4631', X'79916E0E881C43A7B4EE00E5052A94BE', 4, 'Emily and the Rocket', 'Theodore and Emily see a large light travelling across the sky one night. They at first think that it''s a shooting star but it is later found out that it is something much, much bigger.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AE8C431E929641D9941D7A98EF8089EE', X'70D9E39768134785887D27D034928BAE', 1, 'Pingu the Cross Country Skier', 'Pingu comes out of his igloo and sees Pingo, on his skis, nearby. Pingu gets his own skis, goes to meet Pingo, and they agree to have a cross-country skiing race. As they are very evenly matched, it soon gets competitive, and Pingu tries to slow up Pingo by putting his ski-stick between Pingo’s legs. Pingo does the splits and stops, but soon gets going again and quickly catches up with Pingu. They come up to another rather older cross-country skier who is travelling more slowly and, as they go past him one to each side, Pingu surprises the other skier by shouting into his ear. The older skier is understandably none too pleased, shouting angrily and waving his stick at Pingu and Pingo as they race off ahead. Both Pingu and Pingo think this is rather funny! A little while later Pingu and Pingo start arguing again, and Pingu repeats his trick with the ski-stick. This time Pingo falls over and is somewhat annoyed, while Pingu stops and has a good laugh. Pingo makes a snowball and throws it at Pingu, knocking Pingu backwards off his skis. As Pingu gets up, the older skier comes past, stops, waves his ski-stick and tells off Pingu and Pingo. Pingu mockingly mimics the older skier, and then he and Pingo start off on their race again. Again they go past the older skier, but this time downhill where they’re all travelling faster. After various evasive manoeuvres by all three, Pingu ends up crashing into the older skier, falling over and breaking a ski. The older skier tells Pingu it was all Pingu’s fault, and starts to ski away. Pingu starts to cry, and the older skier takes pity on him and turns back. He then kindly helps Pingu get home by giving Pingu a ride on the back of his skis to the starting point of the race, where Pingo is waiting to flag them in!', '1995-06-17', 5, '/rcBdUSm28ZYil9MLm0lPnNh0yQg.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
