INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AEB2C2FD225C4A3FA394CEB472216AC9', X'B6A0F2287DDC409CB808681B777A6704', 2, 'Mister Rogers Goes to School', 'Mister Rogers takes his television neighbors to a kindergarten classroom at the local school. Prior to beginning the Neighborhood of Make-Believe segment, he disguises the Trolley as a school bus with a cardboard cover. The disguise arouses everyone''s attention in the neighborhood. It gets to the point where King Friday decrees that a school should be built in the neighborhood within three days. After scouting four locations, Lady Aberlin and Handyman Negri decide that the school should be built at Someplace Else. Harriet has agreed to be the teacher for Ana, Daniel, and Prince Tuesday.', '1980-05-22', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
