INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AEBBF49ECDB5430386096BCE8112A1BA', X'F4C403079B5E4263A4E0DFA138131E7F', 30, '25th Birthday Musical Celebration', '', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AEBC3834888946C5A0B357E65AC3F955', X'70C8CB4624944DD498F66BFB9B3FAF73', 16, 'Helmet Head', 'The Pawn Stars have a chance to shoot and score with a 2006 NBA Championship Ring. Will the gang make the big score or will a surprise Shaq Attack throw the shop off its game? Then Rick considers buying a highly collectible 1964 Austin Healey. Can Rick put the pedal to the metal for this fast British car, or will he find out the hard way there is nothing "simple" about an Austin Healey? And later a man walks into the shop with an extremely old and rare diving helmet from the 1800''s. Will Rick sink some serious cash into this piece of early sea exploration, or will he find the deal just can''t stay afloat?', '2010-04-05', 21, '/6872xeSn2skKYtLghSPNxBIhZ1J.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
