INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AF0B7A054851453BADA38396A9F04C92', X'1D713CA64E174F84949C8CFD98514127', 44, 'Generation Gap', 'Walk like an Egyptian with the Pawn Stars when a Roman shield movie prop from "Cleopatra" pops by the shop. Will Rick make an offer fit for a Pharaoh, or will this item end up ancient history? Then, a 1922 silver peace dollar rolls in. Will Rick go to war to win this rare coin, or will it be one lost cause for currency. And later, the guys talk about their generations. Will their arguments cause a big s-sensation, or will they just all f-fade away?', '2014-12-22', 21, '/5Frudk1AXadE4hGftkid7gxqq4u.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
