INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'AFF172B3556D41B4B5647DA6E52F7E66', X'FA6F43F4B9444C33AC69DDDBF54C0C16', 4, 'Jack and the Beanstalk', 'Fe-Fi-Fo-Fum... Remember the shivers you felt from the giants cry when you were a child? Now in this delightful production of Jack and the Beanstalk, a marvelous script and magical special effects recreate the adventure. Dennis Christopher is the idealistic hero who trades a cow for magic beans, then climbs the resulting beanstalk and stumbles onto an incredible adventure. A large part of that adventure is an encounter with Jean Stapleton and Elliot Gould, a giant husband and wife time that make this one of the most memorable episodes.', '1983-09-08', 51, '/3f9BkjGncepKwU3DksvZF567z9u.jpg', '2026-04-03T17:38:40Z', '2026-04-03T17:38:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
