INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B0093F010CA04CCDBD17B517606AB700', X'50EE8F6C645C4D48BAB953B9F8F7FF2F', 12, 'Elmo and the Butterfly', 'Elmo and Telly are reading the book Fascinating Facts about Insects. First, they see two ants and learn from their book that ants never sleep. Next, they see two ladybugs and learn that ladybugs smell with their feet. When a butterfly flutters in, they wonder where his friends are and worry that he is lonely.', '2011-10-28', NULL, '/yzSjVS7rWLtJOSMln0fHgfiViJz.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B00A82BC079B45BA90690889BFB12ABC', X'5C1B881FAC584D72B63F209952D4F902', 43, 'Episode 43', 'Welcome World ... We''re Ready!  That''s the claim of Lake Placid, the small mountain village in the United States of America where the 13th Winter Olympic Games open next week. Tina reports from the Adirondack Mountains on how the people of Lake Placid prepared for the invasion of 1,200 competitors and 600 officials.', '1980-02-07', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B011343C1AAC4D43B6B65717F7DB1CAE', X'C4717644555D4DF1AEC0C095B101E7C0', 10, 'Ruth Law Thrills a Nation', 'Once again the show looks into firsts in air travel, recounting great pilots such as Bessie Coleman, Amelia Earhart and the featured book''s heroine, Ruth Law. Linda Lavin narrates the story of Ruth Law, who traveled from Chicago to New York City in a single engine airplane, without benefit of headlights to keep the weight down, in the early 20th century, in two days.', '1994-10-14', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B019421025294685826ECB841E537D74', X'3AF7EA64FA134097B8E440AF07083054', 4, 'The Model Train Set [1329]', 'Bob Trow sets up a train display at his workshop, where he and Rogers discuss relative size. The potato train arrives with a package from the Owl Correspondence School for Harriet Elizabeth Cow. She is to help X learn about safety.', '1974-02-21', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
