INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B01E8D447BAE47C8B0E24B2826595076', X'684AF21E04594832B094DB0997E354C5', 1, 'A Tale of Two Miamis', 'The wives return for a new series of intense rivalries, eavesdropping and confrontations. Plus, a new set of socialites are about to shake their world.', '2012-09-13', 44, '/d4Iem1ueP1DpFwirVsWQ260DlaM.jpg', '2026-04-03T16:35:10Z', '2026-04-03T16:35:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B0248F2CFC4A4888B15FAC10A55F64C9', X'54C290142DBD49FFA23FCF4C546E0B3A', 1, 'If You Can Make It Here', 'Heather hosts her own birthday bash in the Season 6 opener. Also: Aviva tries to make amends with Ramona; and the ladies are introduced to Heather''s friend, Kristen Taekman.', '2014-03-11', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B02570851BD64417A990F3CDC096929B', X'6FD9FD9DE378411B94B176BA4BD518FE', 29, 'Episode 29', 'with Christopher Trace and Valerie Singleton.', '1965-12-30', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B02750DA1DE248AAAA1A18F3A1ABB99D', X'6E0BE2A3A234453BABB70BA535A93601', 8, 'Franklin Snoops', 'Franklin accidentally snoops on Bear''s birthday present and tells him it''s an action figure. He then convinces his friends into buying all the accessories, but when he finds out the action figure was for his own birthday, Franklin gives it to Bear to avoid revealing the truth so nobody is let down.', '2000-05-29', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B02BCA4C08264BC382E66B73285046CB', X'1A534647384B4C00BB6CA3371AD962EB', 9, 'Rick the Giant', '''Obey'' the Pawn Stars when art posters by Shepard Fairey unroll in the shop. Made by the same artist that produced the famous President Obama posters, can Rick "Hope" to make the deal or will he not part with his "Change"? Then, Corey and Chumlee get out of this world when checking out a Mork figurine. Will Robin Williams'' legacy help the deal lift off, or will Corey and Chum bring him down to Earth? And later, Rick and Chum try to decide if they are friends or merely coworkers. Will they be all work and no play, or will Chum prove he''s more than just an employee?', '2015-02-12', 21, '/n6T36sXCmNMVFXjCLypWToAchqO.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B02CD158118D4813B36AEFE7556249B6', X'6A2D283971064C3B8906C9B3E4BFCC8B', 14, 'Fully Loaded', 'Tension rises between Shannon and Heather at Lizzie''s dinner party; Vicki and Briana see a therapist; Ryan''s news shocks Tamra.', '2014-07-21', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B030A4CA14A8474DA1FF6E376D4D17E6', X'0E4196154C964DDE8ED2715770BA77BB', 23, 'Tutter''s First Big Sleepover Bash', 'While Treelo, Pip and Pop are staying at Otto and Etta''s, Tutter holds a sleepover for all classmates at school at the Big Blue House, with Ojo joining in as well. The mice are astounded by the size of the house and everything in it, but Bear does his best to assure them that they''ll be well taken care of. He suggests that they think of it as their "home away from home." They decide to play a game called "parmcheesy" and Ojo''s worried because it sounds like a game only for mice, but Tutter assures her it wouldn''t be a party without her. When it comes time for bed, Keisha wants to call her parents and soon all the other mice do too. As for Tutter, he''s a bit worried what the mice will think of his stuffed toy, Kitty, but Bear shows him that they all have their own stuffed toys. As they settle in to sleep, Luke is first uncomfortable with his pillow and then wants to hear a lullaby. Shadow appears to sing her special lullaby, but Luke misses the one sung by his parents and wants to go home. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B04094E7DA494065959BD72B550E113C', X'F8B697543E4145E5832A64D9C2809AD7', 2, 'Pupil Of The Year', 'Bernard tries to help Nathan become Pupil of The Year to get two tickets to a football match. Nicolette has other ideas.', '2005-01-13', 15, NULL, '2026-04-03T17:20:06Z', '2026-04-03T17:20:06Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
