INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B05E5202272C4479B4427FBF6B66B05A', X'EBC90A3F7ECB46B3AF55E3DEEBE49408', 13, 'Three''s a Crowd', 'Prunella gets jealous when Marina joins yoga lessons with her and her mother.', '2005-04-05', 13, NULL, '2026-04-03T17:37:58Z', '2026-04-03T17:37:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B0665BAC27754647B067D24B7BE1EFEA', X'42E591E22A884434AE9F3D4B1D685613', 11, 'A Hard Day''s Pawn', 'Twist and shout with the Pawn Stars as they check out a collection of memorabilia signed by all four members of The Beatles. With a guitar autographed by Paul McCartney himself, can they come together on a price or will the guys let it be? Then, a family friend pays Corey a visit looking for a deal on a piece of art. Will Corey give him the family discount? And later, the guys decide the Old Man needs a hobby.', '2013-07-11', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B068F0A2B6CF4A9D89792A60E5016463', X'DD4554C26E74499A808A7DAD5F2BE50F', 2, 'Madrigal', 'Walt and Jesse pursue an unlikely business partner. The DEA filters through various leads in hopes of finding something.', '2012-07-22', 48, '/9WIzJqqUthdASBRE1Ts8ymrDhIv.jpg', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B069902F4DAD48868A2E159358845E9D', X'E48599F866FF4C0F927465B9AE1CDA9E', 31, 'Episode 31', 'Do you remember ...  when John and Peter helped bath Rodney Bewes''s triplets? Lesley''s historic flight to America on Concorde? Wobbling Wally, Britain''s largest flag and John''s Fierljeppen? They''re all in today''s programme when John, Peter and Lesley pick their favourite adventures of 1976.', '1976-12-30', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B070D1A6F2AF4F4887ADE9ABFAED92EA', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 19, 'Luis'' birthday', 'Telly Monster and Big Bird are fighting over who gets to read a book in Big Bird''s nest, tugging on each end until it tears in half. They apologize to each other and decide to each read their own half.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B07CFF7853DE4228883201EBCEC08403', X'A605EDF869BA46DB8C0C523B1EF5447B', 8, 'Episode 8', 'with John Noakes, Peter Purves, Lesley Judd', '1972-10-05', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B07D087F28EB41FD9DDD4BF088A828EE', X'E48599F866FF4C0F927465B9AE1CDA9E', 7, 'Episode 7', 'Silver Jubilee Competition  It''s over 40 years since Britain''s last Royal Silver Jubilee and already preparations for the 1977 celebrations are under way.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B07E1BBE93F04D0AB73C5C4C02607708', X'E291DF42D44F49E5BF812DF32EE4A30F', 4, 'The Senseless Detectives', 'Bear is busy doing some cooking --- he''s making his annual batch of cookies for everyone in Woodland Valley. As he starts to bake the cookies, he gets a call from Ojo and Tutter. They''re pretending to be Big Blue House detectives, but they feel that they''ve solved all the mysteries in the Big Blue House, or perhaps even the world. Bear gives them a new challenge by using dishtowels to blindfold them so that they can play one of his favorite games --- "What is It?" Using senses other than sight, he first has them identify a flower and then peanut butter and jelly sandwiches. Later, they find an actual mystery to solve when Treelo reports that his "banananana" is missing. With Bear''s help, the senses of touch and smell are used to track down the stinky, squishy old banana. When the cookies are finally finished, the kids decide to cover up all their senses except taste in an attempt to get Bear to give them some cookies. He quickly ends the game --- he was planning to share the cookies with them anyway. They all end up sharing the cookies together outside, as Pip and Pop express their appreciation for all the wonderful sounds, sights and smells of nature. In the Shadow segment, Shadow retells the story of Little Red Riding Hood. In her twist on the story, the Granny is a doctor. 
