INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B0D8DFDBFF9C476F93ADE317804D4F4E', X'9193E795DA7C40ECB68FF63AA7D5174F', 125, 'Histories & Lore: The Kingsguard (Jaime Lannister)', 'Jaime Lannister details the heroes and storied triumphs of the Kingsguard believed to be the most honorable knights in the realm.', '2015-02-17', 4, '/bnPPxLOqaq0jVUTU3B3Watm5QEr.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B0D9A8AE421248B1A30DA68998DAFDE2', X'F4C403079B5E4263A4E0DFA138131E7F', 65, 'Elmo''s World: What Makes You Happy', 'Join Sesame Street’s curious red monster as he explores the things that make him happy: friends, signing, and dancing. Each episode comes to life in Elmo’s bright, exciting, and very original room – the drawer, door, shade, and TV all join in the fun. Elmo’s visitors in this delightful DVD include his friends from Sesame Street, an Opera diva, and even a dance team! Also featuring Elmo’s pet goldfish, Dorothy, the zany Mr. Noodle, and special guest star Kristen Chenowith.', '2007-01-01', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B0DA2F952D144B8D9D90147051A54ACF', X'A4843A51AEEF427C902C7FB3BD670CD4', 11, 'A Wagon of Different Color', 'After Bear finds coupons for the market, he decides to take everyone in the Big Blue House to the market. He runs into an unexpected delay when he finds out that Ojo has decided to repaint the wagon. Bear teaches her all about mixing paint to create different colors, Treelo admires all of his own colors in the mirror, and Bear plays fashion consultant when Tutter can''t decide what color outfit would be best to wear to the market.  Songs  What''s in the Mail Today?  Some of the Colors I See  Notes  The events of this episode were loosely adapted as the book Bear Loves Colors!  Tutter shows off his tendency to shout out names of cheeses as if they were epithets in this episode. He shouts out the names of no less than three different cheeses (cheddar chunks, brie and gorgonzola) when he gets upset over being unable to decide what to wear to the market.', '1997-11-03', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
