INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B1A0E4BDD1A843B19D2B5BFC39DFFC09', X'53587A7ECD9344F0AD795FE586DCCB8E', 12, 'Tiger''s Torch', 'When Tiger gets a new flashlight, Kipper and his friend are inspired to go camping. But when the two get spooked in the dark, they have to find a way to feel safe again.', '1997-11-21', 9, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B1A0EF8B2E904F9BAEE937491343273F', X'1A534647384B4C00BB6CA3371AD962EB', 8, 'Rick Gets Axed', 'Go batty with the Pawn Stars when a piece of original artwork from the 1995 Batman-Spiderman crossover comic swings into the shop. Will Corey and Chum come out heroes and capture this comic book memorabilia, or will their Spidey-senses fail them? Then, Rick checks out a deadly Revolutionary War halberd. Will he walk away with this deadly weapon, or will it be a losing battle? And later, when Chum''s complaints inspire a casual Friday at the shop, will the Old Man dare to dress down?', '2015-02-12', 21, '/4TT1vtRBvoPOqbxbW6MF4k8LQsx.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B1A7A2DADE4644B7B51ECB3AD487D5B8', X'BFDF87FF01DD4B5494BD19B384F41BDB', 16, 'Bringing up Old Ghosts', 'After a bumpy start to their vacation in Ireland, the women head off on separate adventures. Meghan takes Kelly to nearby Greystones Village in an attempt to locate distant relatives, while Vicki, Tamra, Heather and Shannon travel to a milk farm to get up close and personal with Ireland''s finest cows. The two groups reconvene for dinner where Kelly awkwardly tries to make amends with Tamra. However, the peace treaty doesn''t last long, as tensions reemerge and bombs fly when the ladies make their way back to the airport, leaving this group of friends in disarray like never before.', '2016-10-17', 44, '/oKQDZidySsd6SRhPuBZkDPWsHGy.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
