INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B1E7E71918C24ADD9D2A03E5D746784F', X'4C79C0B621A442778967BE1E791EFDBE', 26, 'Pingu and the Abominable Snowman', 'Pingu is quietly reading his comic when he comes across a picture of a monstrous abominable snowman. He draws his own version, and scares Pinga with it. Pingu then draws a three-toed footprint and he and Pinga rush around the igloo playing at being chased until they run full tilt into Mother, knocking her over. Outside, Pingu creates some abominable snowman footprints made from a pair of snowshoes with spoons tied to them. He then goes off, pretending to be an abominable snowman, leaving a trail of footprints behind him. Pinga comes out to look for him, sees the trail of footprints, and follows them. Meanwhile Pingu, who has found an old blanket and put it over his head, continues to make footprints. He hears Pinga following and hides behind a block of ice. When Pinga stops by the block, Pingu scares her and chases her round the block. Pingu then trips and loses one of his snowshoes. While he’s putting it back on Pinga comes up behind him, realises what’s going on and, as Pingu gets up, pulls the blanket away, scaring Pinga. They both laugh, and then continue together. Later, they’re on their way home when they get back to the spot where Pingu ambushed Pinga, and Pingu spots some large footprints that weren’t made by him. Then they hear crunching in the snow, and see a huge shadow on the ice. Terrified, Pingu runs away, leaving Pinga, who covers her eyes and trembles in terror. She hears a sneeze, and looks. From behind a block of ice comes a real abominable snowman named Bajoo, but he’s not much bigger than she is. Pinga and Bajoo then go to find Pingu, and the snowman explains that he’s also been following the footprints. Bajoo quickly hides when Father comes on the motorised sledge to take them home, but as they’re leaving, he pops out to wave goodbye.', '2006-03-03', 5, '/p0dHm52sf9FJydLP64lij3CuD2Q.jpg', '2026-04-03T17:22:21Z', '2026-04-03T17:22:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B1E89379E6BD41E686B1584E8AE28827', X'204D86FBD99C4FD18DCD9C1BCFD3C33F', 5, 'Finders Keepers', 'The friends are going to the Dragon Land Aquarium for a day, but Zak and Wheezie lose the tickets.', '2001-06-06', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B1F20C4EF29243E4BB4E91BA79433A15', X'5D57283D079C4F6693C833A2FEEADA89', 15, 'Vacation Days', 'Brick makes it hard for Mike to relax during the vacation he was forced to take; Frankie is furious when she learns that Axl was in town without letting her know; Sue tries extra hard to please her customers after receiving a bad review.', '2014-03-05', 22, '/54LXyZrXwfg6Rgyb6nNCrtxGMHL.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
