INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B1F3205CE62549E5B48BDAE6EC6B2DDC', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 102, 'Inside Looks (on The Fusilli Jerry)', 'Inside look from the season 6 episode "The Fusilli Jerry."', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B1F82CAAB6A748E6B1C6AA689761760B', X'941B8C6544544336BE7C1D0591C12F90', 13, 'Pingu''s Ice Sculptures', 'Pingu comes across a notice showing a picture of an ice sculptor. Then he sees Mother posing on a block of ice, with pursed lips and holding a vase. He asks her what she’s doing, and out of the side of her mouth she tells him to see Father. Father is nearby, chiselling away at a block of ice, and he tells Pingu that they’re entering the ice sculpting competition, and shows Pingu the leaflet. Father says that Pinga is also entering, and nearby Pingu sees her making a sculpture / model of her rabbit. Pingu laughs at her effort, and Father tells him that the competition has a prize and why doesn’t he join in. Pingu thinks briefly about it, and then continues on. He sees Robby, who is busy carving a sculpture of himself. Pingu throws two snowballs at the sculpture, giving it bulbous eyes, and then adds a moustache, rather messing the sculpture up. Robby goes off in a huff, with his nose in the air, and starts a new sculpture. When he looks around he sees that Pingu is carving a sculpture of him, but it has a very big head with its nose in the air! Pingu laughs at Robby. Robby quickly completes his sculpture, which turns out to be a caricature of Pingu. This annoys Pingu, who makes another Robby sculpture, and Robby retaliates with a Pingu sculpture that has a long thin neck, and that is on a column of ice. Pingu converts this, by changing its height and adding a hat and telescope, so that the figure looks rather more military. They both chuckle at this, and then do some hybrid sculptures together. Meanwhile, Mother and Father are having an argument about their finished sculpture; the beak isn’t right. Then the lower part of the beak cracks and falls off. Mother and Pinga snigger, Father is a bit miffed. They and Pinga then take their sculptures to the competition, passing the various sculptures that Pingu and Robby made earlier, and come across them doing a sculpture together. Pingu and Robby take this sculpture to the competition. When the competition is judged, the judge laughs at Mother and Father’s sculpture when the he sees that the beak has been tied together with rope, but is amazed when he sees Pingu and Robby''s sculpture and awards them the trophy.', '2004-01-20', 5, '/7CsaiMx9K1EecKb0eTUCCgEfwl5.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B1FAE62547A546B88B0DE888128DD5C3', X'05044F495F9C4E7FA74DB2FF19475D0E', 17, 'Reunion (2)', 'Joe Giudice joins his wife to discuss his father''s death, his prison sentence and money woes; Joe Gorga defends his relationship with his sister; Jim and Bobby go head to head over everything that happened during season six.', '2014-11-06', 43, '/nBphpWndSwOfsWzv1enb2TLsBhB.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
