INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B25561D20F8746AE913195DEC2440F05', X'432A6ABDDCCA44CC82CEFB39E33B8949', 37, 'Episode 37', 'Rogers tries on various moustaches. Betty Aberlin visits to put on wigs. In the Neighborhood of Make-Believe, King Friday  commissions a new opera.', '1971-04-06', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B257A6DDB9BD438BB71A7ECAC0F4AFB0', X'5B72E664D3D7435DBDC3A23D29D1178E', 4, 'Ruff Follows His Nose', 'Ruff sets off in pursuit of an irresistible smell. Little Bear follows him and together they search high and low for Ruff’s mysterious smell. Ruff’s nose leads them all over the house and he discovers plenty of smelly things but not the one he is looking for. However, in the end, with the other toys’ help he finally tracks down what he has been looking for in the most unlikely of places.', '1994-09-27', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B25E678AD18D4BA98A072EEE05133024', X'4A8E3DB080684FF3942F91F45F665F20', 8, 'The Boy Who Cried Wolf', 'Click the Mouse brings the Boy from the story ""The Boy Who Cried Wolf"" out of the storybook, so he can learn more about how to properly care for his sheep.', '2000-04-12', 30, '/vUgj2Zh9iTMxncJLnQ7juGkMIcs.jpg', '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B263D3A0E3E1422A9D9FD68129DA2152', X'227B84290DFD47E4B874C37DA20C403F', 7, 'Brothels & Busses', 'A young man wants to trade a 1750 Blunderbuss gun for an engagement ring. Will Rick exchange vows and buy the gun or will he get cold feet and run? Then, the Pawn Stars get an opportunity to purchase an ejection seat allegedly from a World War II fighter jet, but is this deal destined to crash and burn? And later, a guy looking to make rent money wants to pawn his original 1966 Schwinn Stingray bike which has Rick remembering the good old days. Will his trip down memory lane include laying out the dough?', '2009-08-09', 21, '/3IpiF99pzBDASq2Q3FbgHt5VuaQ.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
