INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B273B9C1DAA644B48105D0B81980924F', X'0442FB97146049238558B994078DC6B8', 6, 'The Text Heard ''Round the Lake House', 'The ladies host a pageant to help pass the time at Monique’s lake house. Meanwhile, Monique''s frustration with her husband Chris’ lack of support grows. Wendy and Ashley make amends, but Wendy’s sudden turn leaves Karen questioning her authenticity. Candiace''s world is turned upside down when she receives a shocking text about one of the ladies'' husband, leaving her contemplating whether or not to break the news.', '2020-09-06', 42, '/j71Tnb5fSz9fyeAk6vdZjiITzNJ.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
