INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2744A56F8244578A67EA6831B1A2692', X'18DA994319634E04A7A0AE63802BB1FA', 10, 'Italian Night Fight', 'Vicki sets the record straight after Kelly continues to tell stories about Steve to Tamra and Shannon. Gina’s parents visit from Long Island to support her with the divorce. Vicki throws an Italian themed party, complete with a cooking lesson, where the ladies continue to think Gina is being too flippant about her divorce. Overwhelmed by the others doubting her, Gina sneaks off to the bathroom and calls an unexpected person for help.', '2018-09-24', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
