INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2827529AA8A431D95FFCD476FDC0835', X'FB4ECC73CB924C5C821F92179058B37B', 124, 'Episode 3779', '', '1998-05-07', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B284F2C5ED3F4193B23FFDB319014929', X'4D504E489B0347A198CEBE9AD8BCB6C8', 8, 'Pinky''s Day Out', 'Rick, Corey, and Chum look back at some of the most adorable moments from Gold & Silver Pawn Shop''s fuzziest employee--Pinky the Pomeranian.', '2026-03-04', 41, NULL, '2026-04-03T16:34:25Z', '2026-04-03T16:34:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B289AFE44E074F6C8690F4AE9E28C58B', X'1E085F654B6945008FFC654D2F638DBB', 14, 'Sesame Street''s Lunar New Year Celebration', 'Lily, Qui and Ji-Young are celebrating Lunar New Year on Sesame Street. They share with their friends how their families celebrate the holiday.', '2024-02-08', 26, '/dDJlbR1QPRbMffSPJGbt4MvVLI0.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B28C1B45720546C9888C8324CDE88FE8', X'1D713CA64E174F84949C8CFD98514127', 16, 'Pinball Punch', 'Become a pinball wizard with the Pawn Stars when Chumlee checks out two classic machines. Can he get the high score or will it be game over? Then, Rick wings it when he checks out a carrier pigeon capsule from WWII. Will he make an offer on the fly or will it be one for the birds? And later, the guys give Rick a hard time when he decides to take up boxing. Can he prove he’s got the eye of the tiger or will he end up down for the count?', '2014-09-18', 21, '/9MVIkcomeCFCqkqdSLItVBNnvXi.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B28D7199E27142A5BE49090CC1E4D8C4', X'200ECA8DCCB84470B0FA868D95B41C33', 1, 'Two Swords', 'King''s Landing prepares for a royal wedding; Dany finds the way to Meereen; the Night''s Watch braces for a new threat.', '2014-04-06', 59, '/nwtWHSlKnXS1sRLuzzwEmIuXjj8.jpg', '2026-04-03T15:40:36Z', '2026-04-03T15:40:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B28F74E2B36F409DA3818FE34CB46C3D', X'F4C403079B5E4263A4E0DFA138131E7F', 96, 'Best of Sesame Street Spoofs! Volume 2', 'Sesame Street has always focused on ABCs and 123s, but what happens when the Muppets on the Street become spaceship pilots, investigators, or emergency room doctors? Hilarity ensues! Spoofs Volume 2 contains recent favorites like "True Mud," "30 Rocks," "Desperate Houseplants," "Mad, Mad Men" and "A''s Anatomy."', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B28FE0AB790E4F4FA0F38696C5C8E4E6', X'E291DF42D44F49E5BF812DF32EE4A30F', 25, 'A Berry Bear Christmas (1)', 'The winter holidays find Bear and his friends planning a big celebration. They''re all getting ready for Christmas, but also learn about Hanukkah and Kwanzaa. Bear also celebrates his favorite tradition, the finding of the winter berry.  As things start out, Pip and Pop have put together a reindeer wreath. Everyone wants to help out with the wreath, so Bear suggests they all add something of their own. Later, the group meets Santa Hogg and presents him with a large list of holiday wishes. Then there''s a bit of an argument when Treelo wants to open everyone''s presents and not just his own.  In the Shadow segment, Shadow thanks Bear for his gift of a scarf --- Shadows don''t get cold, but it''s the thought that counts. She then sings the song "It''s Kwanzaa Time."  After hearing a howling noise, the group takes in an old hound named Jack with no home and invites him to stay at the Big Blue House for the holidays. This gets everyone thinking about the true meaning of the holidays.', '1999-12-06', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B299D3DCD3F74BD19B057D96AC059B6E', X'432A6ABDDCCA44CC82CEFB39E33B8949', 29, 'Episode 29', 'Rogers puts on an opera costume that includes a turban. He invites Betty Aberlin to a costume party set for the next day. Those in the Neighborhood of Make-Believe agree to a costume party to allay the doldrums.', '1971-03-25', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B29AFCF161974C22B6473616D2F3B0A2', X'51C41996C4524A28B1743765855BE794', 3, 'Alike and Different', '', '1987-11-25', NULL, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B29E3E2BC1084239ABFEC2FF95C1D73B', X'F1325B5644E04B6E89BC82CAC30AFEA6', 26, 'Sky Lanterns', 'Mrs. Chen''s class make sky lanterns for Chinese New Year, but Norman Price creates a disaster when he lets go of his too early.', '2012-09-29', 10, '/xqmpuTlagBS9uilmgjNdmBOQfaX.jpg', '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2A39894497F463A8150916229B5E998', X'C21DBD225E2E4414BB67750399AAF6F0', 13, 'Learning the Ropes', 'The Pawn Stars are back in school when a first edition of Henry David Thoreau''s "Walden" comes into the shop. Will the guys be on the same page about this novel''s value, or will the seller throw the book at them? Then, Corey focuses his sights on a 19th century rope gun. Used on ships to shoot ropes a long distance, will he try to tie this one up, or is it knot a good deal? And later, Corey and Chum conduct interviews to find the shop''s newest night shift broker. Can they sift through the candidates to find a diamond in the rough, or will they bring Rick a bag full of fool''s gold?', '2012-01-09', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2A4D3A681F344359C050861DAB2C476', X'F4C403079B5E4263A4E0DFA138131E7F', 55, 'Elmo''s World: All About Faces', 'Join Sesame Street’s curious red monster as he explores his face! Elmo learns about winking and whistling, and even tries to balance a ball on his nose! Elmo also finds out that the optometrist can help you take care of your eyes, it’s very important to blow your nose properly, and brushing your teeth will keep your mouth happy.', '2009-01-09', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2A5C779A7BA476ABA38D305A3317A7F', X'5C4E51C6E20746AD875C72988EB1E13E', 35, 'Security', 'The Pawn Stars march to a different beat when a customer presents them with a drum from the Civil War. Will Rick try to snare this rare piece, or will he simply tell the seller to about face? Then, a guy roars into the shop with a uniform from one of America''s first motorcycle clubs, the Royal Riders. Can Rick and Corey rally up a sweet deal for this piece of biker history, or will a long, bumpy negotiation leave them in the dust? And later, when Antwaun the shop security guard has to take some time off, Chumlee volunteers to cover for him. Will Chumlee be able to fill those extremely big shoes, or will Rick decide it''s not worth the risk?', '2011-09-26', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2A8E9EB81D84CB5BE573AD5B54C70F0', X'4B2A19E02FAE492EBC31F78E63D88EBC', 8, 'Triple Axel Pawn', 'Jam out with the Pawn Stars when a custom Fender quad guitar rocks into the shop. Will Corey hit the right chord on an offer or end on a sour note? Then, a Wheaties box featuring Tonya Harding skates in. Will Rick spin a deal or will he be on thin ice? And later, Rick feels the weight of it all when he checks out two steelyard scales from the 1700s. Can he strike a balance or will his offer go uncalibrated?', '2016-08-31', 21, '/eH7oTNzS6L2X4jJwTI6mqLuMsns.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2AAA0BDAC944BBDA66400B0B12494C2', X'D5351B608A0C482AA6DD4FB860CFE143', 25, 'Episode 1415', 'Mister Rogers arrives with a model merry-go-round which he has borrowed from a friend. He plugs in the model and watches as it moves, pretending for a moment that it is a real merry-go-round. In the kitchen, Mister Rogers uses paper plates and cups to make his own model merry-go-round.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2AB2EE35EB24AA6BB9522F1D7A7EF20', X'D405F9734C7E4CB6B7C0D09A884C9B35', 12, 'Sixteen and Skip the Sweet', 'It''s a birthday blitz when Ramona plans a sweet-16 party for Avery, LuAnn meets with a party planner for her own daughter''s 16th birthday, and LuAnn throws a surprise birthday bash for Jill.', '2011-06-23', 43, '/ukZ7gWscS4nbPOWHVE9a2z9aZ13.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2AF0E91123E4778A007215B7DE67A88', X'4D504E489B0347A198CEBE9AD8BCB6C8', 9, 'Shoot for the Pawn Stars', 'Rick, Corey, and Chum get locked and loaded with weapons expert Alex Cramner to take an explosive look back at some of the highest caliber deals they''ve ever made, both in the pawn shop and out on the gun range.', '2026-03-11', 41, NULL, '2026-04-03T16:34:25Z', '2026-04-03T16:34:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2B2C7F78B9F4D0693528ECC4E9658A1', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 103, 'Carlos goes on a Grouch tour', 'Carlos is guided through a special tour of the Grouch neighborhood by Oscar and other Grouches. He learns about Grouch culture, values, and way of life as they show him around. The tour reveals what makes Grouches unique and different from other residents.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2CAF6F0AD8D4C19AAB8F26C202FA8AB', X'8AE35FD8562643D7A1EA0E43192D1C36', 3, 'Mr. Crabby Tree Falls in Love', '', NULL, 29, NULL, '2026-04-03T17:12:15Z', '2026-04-03T17:12:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2CDA35F90224CF5B5B532F96B0A49D2', X'91F66DA756A2423AB855F09D582805B2', 1, 'The Problem with Chickens & An Egg Is Quiet', 'Chickens that do not lay eggs; eggs that do not hatch.', '2007-09-17', 30, NULL, '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2CEBC7B614B4D9C941B447090647291', X'F79F69A8E59141D09D4A3D9683DEFBBB', 6, 'Big Trouble in Big Sky', 'The adventure continues in Montana when the ladies partake in fly-fishing and white-water rafting; Heather helps Gina deal with pent-up emotion, but later feels betrayed and contemplates their friendship moving forward.', '2023-07-12', 44, '/xc7cfL3ZAIV85jyX0z5uD5xGYpP.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2D2C27279994DBCA3CBEC7A408B96C0', X'D5F0284F0EE345BF8539D02A825D15B2', 13, 'Miami in Mexico', 'The ladies arrive in Mexico City, but Larsa and Alexia start the trip off on the wrong foot; Guerdy discovers someone has been speaking poorly about her to the press; a sexual and provocative dinner experience brings some truths to light.', '2024-01-24', 44, '/5LrR0zuuZgxoBi8gye7neUFxORo.jpg', '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2DF43A25DFA45E3AD95C852475A7746', X'34674C90410E427CBE4D2A6F6F865A80', 10, 'Family Feud', 'The Pawn Stars experience some family drama when a rifle from the Hatfield-McCoy feud ambushes the shop. Formerly owned by the notorious "Cap" Hatfield, can Rick get this antique Winchester for a fair price, or will the seller force him into a bidding war? Then, a work by rock and roll artist Denny Dent rocks and rolls through the shop. Will this painting of John Lennon be a deal to remember, or will the asking price force Rick to just let it be? And later, a guy comes in with an inkwell owned by William Andrews Clark. Known as the man who helped build Las Vegas, can the guys ink the deal on this piece of local history?', '2012-05-28', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2E22C5B12BC4E0EAF8D4374309F8C06', X'852A07B0F228419791477AEED79390BF', 18, 'So... That Happened', 'A special episode pulls the curtain back and reveals never-before-seen moments from Season 13. In this new footage, fans will get a closer look at all the fun the ladies had together, from playing Red Rover at Ramona and Sonja’s birthday party to learning how to twerk to having run-ins with Salem ghosts. Viewers will even get to engage with the episode through a hilarious, multiple choice guessing game of “What Happens Next.”', '2021-09-07', 60, '/i9HtsmFJI3yHaSfdhFr99jJ4b1F.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2E7DF20D0F044CC8CC9FF81285CD5C4', X'E6254AE47D72493B8B37B677D8B76C46', 124, 'Episode 789', '', '1975-04-24', NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2E8AC7C621D431C8358536F8DFC7C45', X'F12380A993E547BB9E2FCF1EED11EEE4', 9, 'Standoff at Coyote Pass', 'It''s an awkward final showdown at Coyote Pass with Kody, Robyn, Janelle, and Meri. Janelle takes a trip to New Orleans and let''s loose with girlfriends to celebrate, and Kody considers finding a therapist to help repair relationships with his children.', '2025-11-23', NULL, '/kx3S3LgeFyozs9YjsGEQj6FTnDL.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2EA403A486E4D27AF8D476944ACA630', X'095258D0D8DB40968AC76A42CD4CBDCF', 10, 'The Secret Society Of Poohbahs', 'Mokey really, really wants to be a part of the Secret Society of Poohbahs, even though Red keeps telling her it''s just a silly club. Then one day Mokey gets a letter saying that the Poohbah''s would like to see her and find out if she''s worthy of being a part of the club. She tells Red of her invitation, only to find out that she wasn''t supposed to tell anyone about it. She goes back to find out if she can be a part of the society, but when a member called the Mind-Reader knows that Mokey told her roommate of the invitation, she''s immediately rejected, but the Beggler Beg and the Vanguard (who look an awful lot like Gillis Fraggle and Convincing John) say that, if she brings her roommate to verify that Mokey''s legit, she can be a Poohbah. Mokey gets all worked up about this, but when she brings Red back so she can be a Poohbah, Mokey finally learns not to take anything too serious that these Fraggles tell her.', '1985-03-04', 24, '/rCi3QUyk2F3IQ4F9PtFOxhwwQug.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B2EBC2E2426F4033987B4E46F21AE520', X'0D2293DDDFCA45918F9A0FBE023F8D1C', 3, 'Betrayer Moon', 'Geralt takes on another Witcher''s unfinished business in a kingdom stalked by a ferocious beast. At a brutal cost, Yennefer forges a magical new future.', '2019-12-20', 68, '/jiNkIfEOsKQNNc0roNmzZZ0VJVi.jpg', '2026-04-03T15:40:45Z', '2026-04-03T15:40:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
