INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B30196A3BEF4450ABE66E02EF470ED54', X'02C86AE38C3B4CC08E1F0B27D01DCD91', 2, 'It''s My Party!', 'The day after Shereé''s big birthday blowout, NeNe, still angry about the party, has lunch with her friend and hairdresser, Dwight, who convinces her to take the high road and not waste any time or energy. Meanwhile, Kim is throwing her 11-year-old daughter Brielle an $18,000 birthday party. Kim''s girlfriends join in the festivities and NeNe and Shereé put their differences aside for the day. Lisa isn''t able to make the party as she gets laid up with the flu, but husband Ed helps nurse her back to health.', '2008-10-14', 43, NULL, '2026-04-03T16:34:44Z', '2026-04-03T16:34:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
