INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B364EAC7D39F4244BF4BF986B2109377', X'0442FB97146049238558B994078DC6B8', 5, 'Look Who''s Squawking', 'Monique invites everyone to her lake house for a weekend retreat, but the ladies are not prepared for her additional guest. Karen expresses her dislike for Wendy''s obsession with her sex life, meanwhile Gizelle and Candiace''s friendship takes a surprising turn. Ashley decides to bring baby Dean along for the festivities, but Wendy''s strong opinions on her decision leaves the women stunned.', '2020-08-30', 42, '/uvadprlCKHv72iP53fKjN3OY4mZ.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
