INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B37513CFCB6847388FD85065085033F4', X'BFF09904103D4AE29C13C1FEBC903A46', 3, 'Saturday Sancocho', 'LeVar attends a rummage sale to observe how people sometimes barter for items when they don''t have money to buy them. Josie de Guzman reads the feature story about a girl who follows her grandmother around the farmer''s market to trade items to get the ingredients for their weekly chicken stew after they discover they are out of all the groceries they need and don''t have cash to buy them.', '1998-10-07', 30, NULL, '2026-04-03T17:36:20Z', '2026-04-03T17:36:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B3796DDFE2424966ABD3C71B6034533A', X'4D2CAC0F38FD438B8AFAACF43952E535', 165, 'Episode 165', 'A magazine programme for younger viewers. Chris and Leila show you how to make A Doll''s House. An excerpt from the film Babes in Toyland. Shown by courtesy of Walt Disney Productions. Letter M in the Blue Peter Alphabet.', '1962-01-01', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B37B205589C4466DAD83742DF39B7A2B', X'4C79C0B621A442778967BE1E791EFDBE', 15, 'Green Eyed Pingu', 'Pingu comes out to play with his ball, when Pingi walks past. Pingu calls to her to stop, catches up with her and starts kissing her on the hand. Then Pingg appears, tags Pingi and they start a game of tag. Pingu tries to join in, but it quickly goes back to Pingg and Pingi playing without Pingu. Pingu has an idea, collects his sledge and then Pingi, and goes off with her. They come to an old igloo, and start a game of hide and seek. Pingu hides, and Pingi starts to look for him. Then Pingg, who has followed them on his sledge, pops up and Pingi starts talking to him, abandoning the game with Pingu. Pingu is jealous and goes off in a huff, then has another idea and gets his ball. He tosses the ball to Pingi, who is on Pingg’s sledge, and she and Pingu start a game of ball. All three of them play together briefly, then it turns into a game of “pig in the middle”, with Pingu as the “pig”, and he never gets the ball. Pingu goes off and comes back with a bunch of flowers and a cuddly toy for Pingi. Pingg goes and gets a ragdoll. Pingu goes off and gets a sledge full of gifts for Pingi, Pingg gets a big bunch of balloons. Pingu dumps the toys in a heap next to Pingi and gets a fish, Pingg then gets a few fish and Pingu then goes and gets a sledge piled high with fish. Pingu and Pingg look at each other across the pile next to Pingi, dump their fish on the pile and face up to one another. They then start a snowball fight, while Pingi is busy getting out from the pile around her. Once out she stands up, and is hit in the face by a snowball thrown by Pingu. They both go to console her, but she shrugs them both away and angrily walks off. Pingu and Pingg make up, and then go off to find Pingi, each with a selection from the gifts. When Pingi sees they’ve made up she kisses Pingg on the cheek, to Pingu’s dismay. She then gives Pingu a proper kiss, to his delight.', '2005-11-30', 5, '/4KnEVq4nmW7Qfl9CsXGGuUcAkhx.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
