INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B4127A058192489A8392A5197CE61455', X'082D18AFD82E4DB887461F7473706DAE', 6, 'Digging Up Dinosaurs', 'Technically not the first science-related show in its history, LeVar seeks a place where archaeologists retrieve dinosaur bones. At the end of the program, LeVar buries a time capsule, containing (among other things) a can of old Coke and his picture. Linda Gilman reads Digging Up Dinosaurs, a story about how paleontologists unearth dinosaurs skeletons and preserve them in museum exhibits.', '1983-06-13', 30, NULL, '2026-04-03T17:36:14Z', '2026-04-03T17:36:14Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
