INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B48091E058A6415E968405EE2436C132', X'A4843A51AEEF427C902C7FB3BD670CD4', 1, 'Home Is Where the Bear Is', 'One morning, Bear finds Ojo playing pretend, having created a tent that''s she''s pretending is her home. Her imaginary home gets Bear thinking about his real home, the Big Blue House. Bear decides to take us all on a guided tour of the home. He takes us to the kitchen, which we learn is Tutter''s favorite room. The bathroom is the favorite haunt of Pip and Pop. Treelo likes Bear''s bedroom, mainly because of the bed. Shadow retells the story of the little old lady who lived in a shoe. Finally, Bear also enjoys going up to the attic, because he gets to talk there each night with his friend Luna, the moon.', '1997-10-20', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
