INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B49679AA0B3F40C88159F9FA2E93BCC3', X'EBC99729CCB74D6482C142708CD7BA85', 41, 'Episode 41', 'Happy Birthday! Jack and Jill, Britain''s favourite Silver Tabbies, celebrate their fifth birthday today. But will Jill do her famous disappearing act on this important day? All will be revealed!', '1981-01-29', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B496A88C8A12447480DE9A038021BD06', X'DB81AD4293A7492689E5D4CEFA257B83', 3, 'Linda Godiva', 'Linda has the power to become invisible.  After ruining Gribbs'' reputation she agrees to help Pete win a horserace but ends up revealing a lot more than the fact she''s holding the reins.', '2001-02-14', 24, NULL, '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
