INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B4A1372E78114F5CBB16C758B6306A50', X'1996DDD820C94A3096BE2B87FAB8D17C', 14, 'Into the Comics (1)', 'Lenni encourages the team to get involved in a comic book contest. The team thinks it''s lame until she tells them the winner gets to star in a comic book with Cosmic Cook''s drawing of Hood Man. Someone, however, wants them out of the way.', '1992-12-27', NULL, '/gmcl7WOVHQDsGzmihELKNjUCPLQ.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B4A4344F6D6A48A18EB7C6301D38C1FD', X'C21DBD225E2E4414BB67750399AAF6F0', 25, 'Pawnocchio', 'The Pawn Stars feel their noses growing when some hand crafted Pinocchio dolls walk in the shop. Will the guys pull some strings and make this deal happen, or get tangled up in a rough negotiation? Then, a guy brings in a Cy Young baseball card from 1909. Potentially worth thousands, will Rick play hard ball for this rare item, or is this deal out of his league? And later, a guy comes in with a harmonica that once belonged to Aerosmith front man Steven Tyler. Can they make a deal with some Sweet Emotion, or will they tell the customer to Walk This Way right out of the shop?', '2012-02-20', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B4A9546D88894C48A58EEFD2F864ADB1', X'56428E5E7DAA468D8BD2076956507AA8', 11, 'Insects', 'Bill Nye''s not here to bug you - he just wants to tell you about insects. Do you know when you''re looking at an insect? All insects have six legs, three body segments, antennae, and an exoskeleton. Insects don''t have bones. Instead, they have hard shells called exoskeletons. Like a little suit of armor, an exoskeleton protects the insect''s body and also keeps it from drying out. Although people call any crawling critter with an exoskeleton a "bug", the "true bugs" are insects that have special mouth parts for piercing and sucking. And, spiders are not bugs or even insects. They''re built differently with only two main body parts and eight legs instead of six. If you think you have a wild time growing up, take a look at an insect''s life. Most insects go through at least four stages of growth -- egg (little round thing), larva (a bit like a worm), pupa (insect in a cocoon), and adult. It''s a long road to maturity for an insect. Everyone''s buzzing about the "Insects" episode. Don''t miss it', '1994-10-08', 26, '/48nG5BtCaaqRNbxoo41VWQDe7pD.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B4A98248130648DF9BC0576FAE124876', X'A84AA42DE73840818DA91FAEC0209EE9', 15, 'Valentine''s Day', 'Valentine''s Day unexpectedly finds Frankie and Mike home alone and ready for a romantic evening while Brick is away at his first sleepover, Sue goes to her first boy-girl party, and Axl has a big date night planned with some friends. But Cupid''s arrow doesn''t exactly hit the target, and the best laid plans soon begin to unravel.', '2010-02-10', 22, '/rBbqvWXOmTs1X03DdsLj2RjzgI8.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
