INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B4BDEC391A0F4884ACB80692BACAD0BF', X'331FC1DF6D704D79B585BF28024A4124', 29, 'Elvis Sings the Blues', 'Elvis breaks his leg and wonders if he is cut out to be a fireman. Station Officer Steele is back on the job and leads the team to rescue Mike Flood who has slipped and is dangling from the roof. Unfortunately, Steele gets into trouble himself when Norman gets his head stuck in the railings and only Elvis is available to help.', NULL, 10, '/fgAFyONGqWEL4aRbwCKdfzitZLL.jpg', '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
