INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B4D64E0AA5884ED0A95C583F31D0EAC9', X'095258D0D8DB40968AC76A42CD4CBDCF', 6, 'Pebble Pox Blues', 'Gobo''s come down with the Pebble Pox, so it''s up to Boober and Wembley to go to the Cave of Shadows to get Gobo''s cure. However, Boober''s not too fond of the idea, and shares his worries with Wembley along the way. Before long, Wembley comes up with a bad case of the Pebble Pox, too. Will Boober leave his sick friend behind and ditch the journey, or will Boober put his germ-worries aside to help his friends?', '1985-02-04', 24, '/Agi2rU0DS5Typjk9bsvFR2OwfJp.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
