INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B5192EE4165B4592A426CEB592F6EEE7', X'5046642D462D4EB081940BBD7962AF0F', 4, 'Heroes of the Bible! - Lions, Shephards and Queens (Oh, My!)', 'This collection includes three short stories, beginning with "Daniel and the Lion''s Den," in which Larry the Cucumber portrays Daniel and overcomes adversity and fear thanks to God. Then, in "Dave and the Giant Pickle," an Asparagus goes head-to-head with a giant pickle, and in in "Esther... The Girl Who Became Queen,"  a small-town girl finds the future of her townspeople is up to her.', '2002-03-05', 30, '/jqMoamN82GRClZqKQWLleg2OvCr.jpg', '2026-04-03T17:39:38Z', '2026-04-03T17:39:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
