INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B53AEF3C99CF4C299BB5AF8F0143FA59', X'208E80DE61E34A2F857FC667FFC29134', 11, 'Dizzy Gillespie', 'Statler is sick (of the show), so Waldorf brings his wife Astoria to the show. Meanwhile, Inspector LaBrea of the County Environmental Department arrives backstage to monitor the noise level of the show. LaBrea tells Kermit that to keep the noise down, he has to cut the trumpets for the show. Kermit tries to keep LaBrea busy while Dizzy performs.', '1980-01-04', 26, '/oDDHRkXjMo1JwK9epIgIl7c2Pkx.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
