INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B53DC5BAE04C4BE58A91AFA4769392A5', X'D0E5568D939D4D89AB4EC291A90691CF', 6, 'Clay Time', 'Kipper finds Tiger messily trying to make a clay pot on his new potter''s wheel. They decide to make some pots together and Tiger tells Kipper how difficult it is. Pig gives Arnold a ride on the potter''s wheels thinking it is a car without wheels. They find the pots Tiger and Kipper have been making and think they''re chocolate cookies. Tiger has some explaining to do.', '2000-11-02', 8, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B53F2A93C0FB4028951AB293768BA654', X'5C1B881FAC584D72B63F209952D4F902', 14, 'Episode 14', '''Oh I wish I''d looked after me teeth'' - says Pam Ayres who will be in the studio today rendering her famous poem with its awful warning to compulsive sweet-suckers.', '1979-10-25', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B53F45687CEF4BDD8A6E24E177663288', X'F9A8D8B3D72E437EA9D57477F6D64DF8', 5, 'Jobs Day', 'It’s Jobs Day! Elmo and his friends are learning about jobs they would like to do when they grow up. When Gabrielle doesn’t know what she wants to do yet, she learns that if you work hard and practice, you can do anything you want to do. First lady and teacher Jill Biden teaches Elmo, Abby, and Tamir about all different types of jobs.', '2022-12-01', 26, '/iBHTm1p94GSdjOcFDvIZuNNlKGr.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
