INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B54FD35066BF4AF189B82D9C056652DB', X'4091B13B4DB64857AD2220B5658C6B89', 13, 'House of Horrors', 'Teresa takes her relationship to the next level while Melissa and Joe’s relationship hits a breaking point. Additionally, Jennifer’s excessive drinking threatens to ruin Marge’s Halloween Bash.', '2021-05-12', 43, '/tKdHF1TfEvmAhYaA8QkdX1ESk6D.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B553ABBE472C46AB8191D37387981996', X'5A771F52FE964EA2B567A8DDE899059E', 11, 'Top Rope, Bottom Dollar', 'Rick and Chum thumb through an ancient tome that was believed to hold the secret for turning metals into gold. Will the two band together to buy this banned book? A costume signed by "Macho Man" Randy Savage leaves Corey and Chum wrestling with a tough decision. A half dollar that was supposedly pierced by sharpshooter Annie Oakley finds itself in Rick''s crosshairs, but this shot is anything but cheap. Later, a fancy French gunpowder flask leaves Rick locked and loaded - but will he actually pull the trigger on this sale?', '2017-11-20', 21, '/4ZmBAMkwk64gbsgo1YwJa4j4Obj.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
