INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B563D091972748A38A4913DC1DFD4156', X'61E0C9D9337E4FE4A0FDE567B29AF115', 8, 'The Desert and the Deserted', 'Bronwyn and Todd take the couples to Palm Springs to celebrate their 10th anniversary, but once in the desert, the divisions in the group become clear. Even after being uninvited on the trip, Heather makes her presence known in Palm Springs. Tensions between Lisa and Bronwyn boil over in the hot tub, resulting in Todd asking Lisa and John to leave early. Meredith gets upset when Seth prioritizes work over their marriage, suggesting trouble in paradise.', '2024-11-06', 43, '/oQZ4fuZgzBsOn5wMb8AGf2YkRN7.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
