INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B56E0DB6BB8B45EB887CBDFAA81A9338', X'1CAFB2C3BBCB4172B02D441A5AAA155F', 3, 'Giving and Receiving: How People Make Toilets', 'Rogers brings back The Potty Book that he had introduced back in 1989, and reads it in full, this time. Mr. McFeely shows a videotape of how toilets are made. Betty Okonak Templeton visits the Neighborhood of Make-Believe in search of Lady Elaine.', '1998-08-21', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
