INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B59450166F1E4714BFAE28133AEB9421', X'98D80972E53A43DDA03A7703465E6F87', 13, 'Take the Money and Run', 'Take aim with the Pawn Stars when the guys check out a Kentucky Long Rifle. Made famous by frontier marksmen like Daniel Boone, will the guys take a long shot on this iconic big-game gun? Then, Rick gets a geography test when he''s offered a 1700s map depicting California as an island. Can he plot a course towards a sale, or will this piece just get him lost? And later, Corey''s longtime demand to be made a partner in the shop comes to a head when he says "now or never." Will Rick and the Old Man cut him a deal, or kick him from the nest?', '2012-12-10', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
