INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B5E9AA630EAA4F789985F2E10BB23EAF', X'F4938E7D11A84756B40598BEDD7C9B28', 3, 'Pat''s Birthday', 'Pat always thought he had managed to keep the date of his birthday to himself. He tells Jess not to give his secret away. When he arrives at the Post Office, all of the post is for Pat. As he then goes on his round, everyone he meets knows it''s his birthday! How did all those people know?', '1981-09-30', 15, '/jxjTU8YroNrvbaBLNHjlfejoajH.jpg', '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B5EB6D24CF19401E8647C1A1B1C2A50F', X'ABEB8D075C864F6AA110B11CBA2A4138', 3, 'The Painted Lady', 'When the gang arrives at a suffering fishing village, a mysterious spirit appears to help the villagers.', '2007-10-05', 25, '/jIOrXmDp5YcCwPoeaw6MGLU1rfd.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B5F3F25007014784A9977AB1A8AB2ABC', X'876145F4B55E4070B35B893A67F88BAC', 12, 'The Hamptons Hangover', 'Unable to make peace with Jackie and Melissa, Jennifer questions whether she should stay in the Hamptons; the Giudice family visits Joe in ICE; Margaret tries to make peace with her mother; Jackie comes to a realization about her eating disorder.', '2020-01-29', 43, '/pCNNoHC1MZ3axILi9p52Z3uqCCa.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B5F4154395554A19A402FBD4FE3661C5', X'10E64538C78A4CB082F917D14256DBAC', 2, 'Cutting the Cord', 'Nervous, Sue overwhelms Frankie and Mike with text messages as she waits for her roommate to arrive. Hutch and Axl deal with an ant infestation. A mysterious bodyguard protects Brick at school.', '2015-09-30', 22, '/wceTF9A9GbCfuAzr4m4oDBBwsHJ.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B5F9CE54746B488B9C649603046B8F17', X'5C16DB9D5E7140EBB44EF559B2DDB8F3', 4, 'Thumbelina', 'Carrie Fisher and William Katt are Thumb-Sized Lovers...Video magic transforms Carrie Fisher into the diminutive heroine of Thumbelina, a girl so tiny she slept in a matchbox, so kind even field mice loved her, so beautiful she married a Prince. Raised by a kindhearted charwoman, Thumbelina is kidnapped and almost forced to marry first a Toad, then a crotchety Mole, played by Burgess Meredith. She manages, however, to escape to a beautiful garden kingdom where she meets a handsome equally tiny Prince, William Katt. This tale teaches us that everyone, no matter how unique, can find someone to love. Featuring production design based on the work of 19th century illustrator George Cruikshank. Thumbelina is a marvelous fantasy that will enchant big and small alike.', '1984-06-11', 51, '/gwc6wAgLMomsfoxjCD6Z12yuYPh.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B5FAECA9690641B48ECB36BC5E2F4B71', X'1D455F6041E8480093594445E4DF2B77', 6, 'Environment', 'A major crisis has arisen in the Neighborhood of Make-Believe. Their nearby landfill at Someplace Else has reached the saturation point.', '1990-06-01', NULL, NULL, '2026-04-03T17:35:45Z', '2026-04-03T17:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B5FCAFEA589349DAAC1D8C3297F72D97', X'6EF86C2733E747E5A053483059DFD16D', 31, 'Episode 31', 'Remember Simon as an Elvis look-alike, Sarah wearing corsets and Peter slogging it out in the first ever London Marathon? They are just a few of Blue Peter''s 1981 highlights and others include Kevin Keegan in action in the studio, a meeting with Morph, the birth of Goldie''s puppies and leaping through fire with the legendary White Helmets.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B60A2DD59F4849CE8BCE2087E5069161', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 28, 'Telly''s New Shoes', 'Telly makes a shoe wish so the Shoe Fairy will come and give him his first pair of shoes.', '2010-10-07', NULL, '/632T4wu2dX08hjxIWwV8aA8tKrH.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
