INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B64144ECB788421EBA59B1FB3808D0FF', X'0EBBA123871D4D2BA054EB85D2AD9450', 38, '''Twas The Night Before Easter', 'It’s Easter time in Crisper County and cable news reporter Marlee Meade is hunting for a way to help others. She cooks up a plan to save the old theater with a cast of costume-clad townies, massive props and a 20-foot robot rabbit to perform “Up With Bunnies.” Now there’s only one thing missing– the star of the show! When word spreads that singing sensation Cassie Cassava (Melinda Doolittle) is arriving to perform in her hometown church’s Easter service, Marlee schemes to steal the starlet for her own pageant! But when things go haywire, will it be curtains for Marlee’s dreams–or will she discover the true meaning of Easter and what helping others is really all about?', '2011-03-08', 30, '/1rScTnddsB0AbxLxbxBOIeXblkP.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
