INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B65D40AB14DF4054819C358653C522CD', X'0442FB97146049238558B994078DC6B8', 3, 'Sip and See You Later', 'Gizelle spends her birthday with Jamal and the girls, but underlying tension makes for an awkward celebration; Candiace struggles to understand Monique''s anger towards her after their recent reconciliation.', '2020-08-16', 42, '/Am2XqqqYjzbZetwtBlRQ42LoiW0.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B664B933D3CE4070AD101C8F8972F77D', X'1BB5392776F64ED39C415414AD0865CE', 7, 'Perl in the Toplands', 'Safely across the river, Slagar awaits Stonefleck''s army of rats. Below the cliffs, Matthias meets Sir Harry the owl who reveals a way to ascend them. Matthias and company ascend but also comes under attack in the Dark Forest almost losing Cheek before making their escape. Across the river Mattimeo leads an escape of his own but is immediately recaptured by Stonefleck''s rats. Back at Redwall, Ambrose Spike and the others set traps for the invading birds and they engage in what is to be a long battle of wits and courage. The birds take Cornflower, Rollo, and Mrs. Churchmouse hostage and threaten to kill them unless Redwall surrenders. The stand-off temporarily resolved by the Abbot, but it leaves the captives in great danger. Matthias and the pursuers launch a raft to rescue Mattimeo but come under massive fire and take to the water, only to find it is alive with nibbling fish. Without any choice, they have to ride the river.', '2000-12-10', NULL, '/s14J3PxOKEUzoUn3g8xgiGvYzUT.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B6689189CD1949BAB343D82A134C131A', X'9193E795DA7C40ECB68FF63AA7D5174F', 106, 'Histories & Lore: Wargs and the Sight', 'Bran Stark explains the legendary abilities of warging and the Sight, skills that, although innate to the mythical Children of the Forest, only present themselves in modern men on rare occasion.', '2014-02-18', 3, '/zWOrKoYl2UYpR5C4BrDeEgoGoim.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B66E55EB274D457AA90FF67F6F14644F', X'3FC7C152E4F6426AA89936EC454C4403', 51, 'Crash Landings', 'Max and Emmy coach a relay race in Dragon Land, but Zak is very nervous because he thinks he and Wheezie might get injured during the event by flying fast. So they use as much protection as they can and manage to win the relay race.', '2000-01-24', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B66EFCD21F3949F3BBB728196D790022', X'A8C6182E05E14B6891A55126CF6C94F0', 21, 'Sybil Ludington', 'James learns from the courageuos Sybil Ludington that the thought of independence not only lies in the hearts of soldiers and determined young men, but also in the hearts of determined young women. Sarah travels to Philadelphia with General Benedict Arnold and witness his passion of being ranked to a higher office in the army.', '2002-09-30', 30, '/aD0MBwAYxJ4ac1ohNyAEXu8gCsn.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
