INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B6713A1DEBF84085A09323A78622721C', X'F4C403079B5E4263A4E0DFA138131E7F', 111, 'A Celebration of Me, Grover', 'He''s furry, he''s blue, and he''s everyone''s adorable, old pal, Grover, in his very own special! Come to the Flyers'' Club Roost where everyone on Sesame Street has gathered to celebrate the many sides of Grover.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B6721418B53D4D0581DAAABFDCFDC870', X'22BEBA7F9B8E456393DA46E76ECBA427', 1, 'A New Friend On Sesame Street', 'There''s a new Muppet On the block!  It is Abby''s first day on the street.  Can everyon''s favorite fairy-in-training overcome her shyness and make new friends?  Also in this episode: Law & Order: Special Letters Unit and a performance by John Legend with Hoots the Owl.  Special guest Kristin Chenoweth stops by Elmo''s World.  This episode is brought to you by the letter M and the number 4.', '2006-08-14', NULL, '/gCecENWNPZpm0hypKYPKIST24wp.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
