INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B6779A96132646A78DFD9359AC4E1441', X'D123FD65EFB74EBBA23E190C447791CF', 1, '¡Bienvenidos! Same Beaches, New Shade', 'The ladies reunite with an old friend and meet new ones; Alexia seeks closure about her marriage.', '2021-12-16', 44, '/x4iAfxEAIxJBs8nReTKyjjuQ6nu.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B67EDCDDEE8B4931AFD2F45C15BB3A83', X'70D9E39768134785887D27D034928BAE', 7, 'Pingu''s Prank', 'Pingu’s neighbour comes out of the igloo, puts out a piece of washing to dry and goes back inside. Pingu happens to walk past, and as he does so the washing falls off the line. This worries him, so he picks it up and rings the doorbell to tell the neighbour what has happened. The neighbour takes the washing, hangs it up again and rewards Pingu for his kindness by giving him some biscuits. Pingu then meets Pingo, who sees Pingu finishing a biscuit and asks if he can have one. Pingu gives him the bag, but it is empty! Pingu explains how he got the biscuits, and shows Pingo where. To Pingu’s horror, Pingo pulls the washing off the line and rings the bell on the igloo. When the neighbour opens the door, Pingo tells the same tale, expecting the same reward. The neighbour realizes what is going on, and shuts the door in Pingo’s face. Pingo and Pingu then play a couple of tricks on the neighbour, both involving ringing the doorbell and then running away, and the neighbour gets very annoyed. Another penguin then comes to deliver a parcel, rings the doorbell and, when the door is opened, is soaked by a bucket of water thrown by the neighbour! The neighbour apologizes, but the other penguin is very angry, then slams the parcel into the hands of the neighbour and stalks off angrily. The parcel then starts to leak (an indication that there was a liquid of sorts in the parcel), then the neighbour throws it to the ground, kicks the bucket away and goes back indoors, slamming the door. Then the washing drops to the ground again, so Pingu hangs it back up and both he and Pingo walk quietly away!', '1995-07-27', 5, '/zOhKCeTtFJdBuytDDXOC9eM2DQD.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B67F49FCD974446F9D34A28AC81D7827', X'EC8D33228CA24E8D9D22268AEE320274', 9, 'Three Ring Pawn', 'A seller brings in a signed Righteous Brothers record; Rick fine-tunes an offer for a 1950''s Gretsch guitar; Chum is locked and loaded when he checks out a Palmer rifle from the Civil War.', '2025-03-26', 42, '/oVNoUWc3bH2J1R0uvrSD5pjBOBZ.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
