INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B6B1365B17064BF0BF5B0439F5C026A8', X'CA19F89515144988A70995E84EAB7CEE', 2, 'Rick''s Gone with the Wind', 'Chumlee gets ready to rumble when a rare wrestling figure comes into the shop. Will he be king of the ring, or get smacked down? Then, a portable craps table is smuggled in. Will Corey take a gamble, or roll the dice? Next, Rick checks out a vintage Eclipse windmill. Can he generate a deal before it''s gone with the wind? And later, Corey gets Beatlemania when given the chance to buy a Starr''s drum kit. Will Corey and the seller Come Together or Let it Be?', '2020-11-16', 42, '/6ulp6VhzTisslG4tXtMxyHgqyZ7.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B6B4E77E5B70404D8FDBFE2E03D38F2C', X'3EEE3180ACB7429D95AFF575BB4AB932', 4, 'The Tortoise and the Hare', 'LeVar has entered a bicycle race. He''s in competition not just with the other bikers, but with himself as well. This program also includes a lengthy piece on a karate class. Comedienne Gilda Radner reads the Aesop''s tale of "The Tortoise and the Hare," about an arrogant rabbit that''s over confident that he can beat a determined turtle in a foot race.', '1985-07-05', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
