INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B6C2A74E738548238AE88ABEEE95D98E', X'5C16DB9D5E7140EBB44EF559B2DDB8F3', 2, 'The Princess and the Pea', 'Prince Richard is looking for something to complete his life. The royal fool(jester). Helps him decide that he needs a wife, with a demanding mother and a dumbfounded father, that''s all he needs in his life, until Alicia comes along. She is kind and gentle, and persists that she''s a princess. Richard has had it with the demands of his mother and hates all of the princess presented to him, so he decides to marry Alicia. The mother however, is not so sure Alicia, so she puts her to a test to see if she is a real princess which has hilarious consequences! Liza Minelli is classically funny as Alicia. "The Princess and the Pea" is great family fun!', '1984-04-16', 51, '/sycREibCHeAP9ndREwZAdsGtIfI.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
