INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B6E75570D209419E9F925A75D127E44E', X'C21DBD225E2E4414BB67750399AAF6F0', 28, 'Ring around a Rockne', 'The Pawn Stars are blown away when a signet ring that belonged to mob boss Lucky Luciano comes out of hiding. Can the guys make the seller an offer he can''t refuse, or will this deal go to sleep with the fishes? Then, Rick is in the red zone when a letter signed by legendary football coach Knute Rockne steps up to the line of scrimmage. Will Rick win one for The Gipper, or will he fumble the negotiation? And later, Chumlee is presented with a collection of antique Cracker Jack toys. Will he go three strikes and out on these classic collectibles or will he win one for the home team?', '2012-02-27', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B6EB91560C3C45D7BAF6F2DB9EAD727C', X'227B84290DFD47E4B874C37DA20C403F', 23, 'Bikes and Blades', 'Rick has a chance to buy a 1940 quartermasters spyglass that may be from a WWII ship. Can he discover the ship it came from, or will this deal sink? Then Corey considers buying a customized 1996 Harley Road King motorcycle, but there is one significant flaw - a pink flame paint job. Will Corey get in touch with his feminine side, or will this bike be too hot to handle? The guys also meet with a man hoping to sell knives that his grandfather smuggled back from WWII.', '2009-12-27', 21, '/6i4mWhE34JHiQko6s8o2V2rVTC5.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
