INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B6EF62A65B0F4A2BAAB6D279D6EB2DE0', X'991E78F103A54D268F7575E11DB4243C', 7, 'Go-Stop-Go: How People Make Sidewalks', 'Rogers and Chuck Aber discuss the proper safety gear for inline skating. Those in the Neighborhood of Make-Believe think they have made progress to curb Lady Elaine''s random squirts. Mr. McFeely shows a video on how concrete sidewalks are made.', '1999-03-29', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B6F1AC53C0504BA08EFCE7F22C5ABBBC', X'F4C403079B5E4263A4E0DFA138131E7F', 54, 'Bedtime With Elmo', 'It’s nighttime on Sesame Street and Elmo doesn’t want to go to sleep yet, he wants to play! Elmo’s Daddy shows Elmo why everyone needs sleep, even little monsters. Children will enjoy this soothing tale as we watch Elmo and his friends get ready for bed; and parents will love the great strategies Elmo’s Daddy uses to get Elmo to sleep. But what if you are afraid of the dark, as Abby Cadabby is? Filled with lullabies and a special favorite book, dreams and happy thoughts; this video will enchant children of all ages, if they don’t fall asleep before it ends! Featuring the special DVD extra of Andrea Bocelli singing “Time to Say Goodnight” to Elmo.[1]', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
