INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B6FAF8CE9FD14B57B8203399E5D10665', X'1C0A48A44D1C424BB54F265883E6B26E', 1, 'Who’s Gonna Check My New Boo?', 'When Sheree introduces the ladies to her latest squeeze at Ross’ 40th birthday, the ladies reveal her new boo might be up to no good; as the walls close in on Sanya and her family, cracks start to reveal that their living situation isn’t so comfy.', '2023-05-07', 44, '/jKTYGvgsmpvFP17pmOxJj3mdvtO.jpg', '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
