INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B704EE9ABC454D7E8A81251B3FEBE296', X'0E4196154C964DDE8ED2715770BA77BB', 5, 'Rockin'' Rocko', 'Pip and Pop are eager to introduce Bear and everyone at the Big Blue House to Rocko --- an old friend of theirs that they haven''t seen in a long time. On the way to pick him up, they describe him to Bear as being a bit shy, so it comes as a big surprise when the Rocko they meet up with turns out to be full of energy --- singing and dancing and raring to go. Indeed, it seems like Rocko''s going to be a lot of fun at first, but then he starts trying to play games that everyone''s uncomfortable with and behaving rudely. Suddenly, nobody wants to play with Rocko, but Bear wonders if Rocko is hiding something behind his "cool" personality. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B7057D2D5B204BEB804237BCCB5EC5CD', X'A79A245FACAB4EBEAEE929867F9E52F6', 1, 'Meri Moving? Part 1', 'In the season premiere, Mykelti brings Tony''s family home to meet her parents, but there''s one small problem: they don''t speak English. Then, Meri and Christine''s mom, Annie, go to Utah for a potential business opportunity.', '2018-01-07', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
