INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B7085BAA29A94364910256A49D87EC08', X'D920EBAEF00A4E25ABFE40492C74DED6', 11, 'Secret Agent Pawn', 'It’s operation seal the deal as Rick checks out fake government ID’s belonging to Nazi spies. Can he complete the mission before Corey diverts it’ Next, a seller comes in with a first edition Teenage Mutant Ninja Turtles comic book. Will Rick and Chum shell out big bucks, or will the Foot Clan slash its worth’ Then, Corey checks out a little piece of Janis Joplin. Will Corey sing the Kozmic Blues, or be arrested by the memorabilia’ And later, Rick is granted rare access to the CIA. Will he unveil government secrets, or be left on a need-to-know basis’', '2020-02-10', 42, '/jPPLYvPTibxog1zR3wATS3uCYEd.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
