INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B73DF81027A845E58E23CF9E1114B6EA', X'E3A58098E0DA42F7970996DC0A4866C8', 10, 'Everybody''s Special', 'Cornflake S. Pecially feels everyone has forgotten that today is his birthday. It adds to the drama of the surprise birthday party, for which Daniel and Prince Tuesday have made a card. But Mr Mcfeely And Chuck Aber Stops By Videotape How People Make Ham Then As Soon As They Leave Maggie Stewart Brings Another Videotape On How People Make Ice Cream', '1995-09-19', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B7403719146F4A3CB2C9A6C2A85E4F31', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 40, 'Episode 2005', 'Various Sesame Street adventures unfold with moments of learning and discovery throughout the day. Each scene brings its own brand of comedy and heart.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B743678889644B6EA7ADCAAB298F08A6', X'70D9E39768134785887D27D034928BAE', 4, 'Pingu''s Big Trip', 'Pingu is on his way home with his sledge when he sees a poster showing a tropical paradise. He is excited, and when he gets home goes into the shed. A lot of sawing and banging is heard. This catches the attention of Pinga, who is playing nearby, and she goes to listen at the door. Pingu tells her to go away. Pingu goes back into the shed to finish off the changes he is making to his sledge – he has put on a deck, and a mast for a sail. He finishes off by putting a small barrel on the sledge. He then raids the igloo for food, taking a fish and a loaf of bread, which he puts into the barrel. He leaves the shed and Pinga goes in, and is surprised to see what Pingu has been doing. She attempts to get into the barrel, but with both her and Pingu’s food supplies it’s too full. To make room she takes out the food and hides it in a nearby box, and gets into the barrel. Pingu then returns with a cloth that he puts on top of the barrel and sets off, pushing the sledge. After a while he’s a bit tired and peckish, so he stops for a rest and a snack. He takes the cloth off the barrel, and is surprised when the barrel jumps about. Pingu is then annoyed when Pinga pops up out of the barrel, and even more annoyed when he discovers that the food he put in the barrel is not there! Pinga then produces a couple of lollipops from her satchel that they eat. They continue on the long journey and stop when they reach another poster. Pinga cries because she is hungry and wants to go home, so Pingu consoles her and they set off home, arriving as it’s getting dark and the stars begin to come out. They go into the igloo and rapturously greet Mother, who has just finished baking a chocolate cake and seems blissfully unaware of their adventure, and they all sit down to eat.', '1995-07-06', 5, '/yWetGx2sFquxOk3rcZFASKXXv1e.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B743AF791BEE489195947F5A447171DE', X'ACAC417E2AA342E79E08ED0D6071A3EE', 22, 'Reunion (3)', 'Bethenny and Carole continuing to go shot for shot about the dissolution of their friendship; the women relive their stomach-churning trip to Colombia; Carole revisits the highs and lows of her season; Tinsley takes issue with Carole’s protests about their relationship; Sonja discusses a new chapter in her life and delves back into her issues with some of the ladies; and the women end things by sharing their biggest regrets of the season.', '2018-09-05', 60, '/6MzNhUMrOW3AQFriyPf8lP5p6eB.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
