INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B74930E83D694E92AE895DBC1BDE8D59', X'0442FB97146049238558B994078DC6B8', 12, 'Fully Charged', 'Wendy and her husband, Eddie host a “Sip and See” for their baby girl, and extend an invitation to Eddie’s estranged parents. Ashley and Michael seek counseling for their issues, while Karen continues to fight for her marriage. After weeks without an apology from Monique, Candiace decides to take a legal next step, and the possibility of jail time for Monique leaves the rest of the ladies in shock.', '2020-10-18', 42, '/1rgLnRELxi4Rnj98K4eYwIApg0h.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B74E9DB0F8824A879A8F5F791D38950D', X'6BE7468483E64D00BD693E4FCA97CABB', 1, 'Everything''s Bigger in Dallas', 'Everything’s bigger in Dallas - the egos, the attitudes, and the bank accounts. Cary hosts a benefit at her home where inappropriate behavior by best friends Brandi and Stephanie raises the ire of social maven, LeeAnne. Later, tensions boil over at a prestigious charity event as Stephanie is dragged into a feud between Brandi and LeeAnne. Meanwhile, Leanne’s best friend, Tiffany, questions whether her recent move back to Dallas from Los Angeles was the right decision for her and her rocker husband, Aaron.', '2016-04-11', NULL, '/imk142ASKMoiPAVllfH8HAceAp.jpg', '2026-04-03T16:35:03Z', '2026-04-03T16:35:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
