INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B789D24D71154AC9AA595589040E1AB5', X'65F5ABC80C59497B86E58C6165EE480C', 16, 'Party Fouls', 'On the season finale of The Real Housewives of Dallas, LeeAnne picks a church and a date for her wedding, while Mama Dee officially signs over her company to D’Andra. Stephanie throws a college kegger for her husband Travis who is about to leave for Business school. There’s plenty of fun to be had playing beer pong, doing keg stands, and playing in a giant foam pit, but this kegger takes a turn when a conflict between LeeAnne and Brandi escalates.', '2018-11-28', NULL, '/x8phhoswSSRMyz84488h97q3mMb.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B78CEB82ACEC47CA8F7BF42D89352F8F', X'52F9C16BA60F4EB7B9915C3BF70877BF', 8, 'Reunion', 'The five women reunite to tell their stories and reflect on the show.', '2006-05-13', 44, '/6Wu8URmWpKpEq1WA2uAu3fHGR8P.jpg', '2026-04-03T16:35:29Z', '2026-04-03T16:35:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B78E6799A1754A699109DF494AADE2F0', X'DA06465B91544FEBA455374DF7DAB02F', 20, 'Gina''s Vet Assistant (4102)', 'Gina is so busy that she is in desperate need of an assistant. With just a wish, her Furry Godmother appears and grants her a veterinarian''s assistant who happens to be Grover! Unfortunately, Gina doesn''t seem to be able to help the hiccupping duck in her examining room because Grover keeps screaming, "Emergency!" Gina also finds it difficult to help the other animals because Grover mistakes a camel for a horse, a lamp for a living thing, and a cat for a tiger.Gina then teaches Grover about these animals and about living things so that he can better understand what a real veterinary emergency might be. In the end, Grover doesn''t think that he is cut out to be Gina''s assistant, but finds a new calling curing hiccupping ducks- by surprising them!', '2005-09-02', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B78E7C6029BD41BDA04E56831D42971E', X'235468B020FC4714BC3FD7E7AEB25F4B', 20, 'Reunion Part 3', 'Lisa demands an apology. Larsa comes face to face with Jody. The ladies relive the good, the bad and the ugly from their travels by land and sea. Marysol is accused of stirring the pot behind the scenes.', '2025-10-16', NULL, NULL, '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B79C0A6CFA6F4F76A9A26F3DB5C53854', X'432A6ABDDCCA44CC82CEFB39E33B8949', 2, 'Episode 2 (#1132)', 'Episode #1132- Mister Rogers and Mr McFeeley make a puppet using paper mache. Meghan Sweenie has her routine check-up. Dr. Mermelstein tells Rogers the basics of this physical operation. In the Neighborhood of Make-Believe, Prince Tuesday''s crying prompts some neighbors to take action.', '1971-02-16', 29, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
