INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B7A46E1D3E10417E9DC3309DFE78C78A', X'C21DBD225E2E4414BB67750399AAF6F0', 3, 'Blaze of Glory', 'The Pawn Stars go gangster when they check out a 1937 Oldsmobile. Allegedly owned by mobster Bugsy Siegel, will the guys go to the mats over this rare luxury ride, or has this classic car seen its last drive-by? Then, a guy comes in with a genuine Olympic torch. Carried in the opening ceremonies of the 1984 summer games, will this piece burn a hole in Rick''s pockets, or will a marathon negotiation make the deal flame out? And later, Rick and Chum reach for the sky when the world''s smallest pistol pops into the shop. Will this tiny Austrian gun aim its way onto Rick''s shelves, or fail to make a big impression?', '2011-12-05', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
