INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B7CD5FFA20AD4207820F6FB852382C72', X'D122D150FB7F46FAB9E163D3B08A118C', 2, 'Episode 2', 'Pod tells the Hendrearys that he and his family are leaving. Eggletina shows them a way out through the scullery drain, but as they make their way, a roaring wall of water rushes towards them.', '1993-11-21', 30, NULL, '2026-04-03T17:17:47Z', '2026-04-03T17:17:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B7CDA4EEFA2A4D3296C42176B830E3C4', X'ABEB8D075C864F6AA110B11CBA2A4138', 2, 'The Headband', 'To better blend in as Fire Nation citizens, Aang enrolls in a Fire Nation school, giving himself an opportunity to learn more about the Nation and to enjoy life as a normal kid for the first time since he discovered he was the Avatar. Meanwhile Zuko, growing more and more paranoid about the Avatar''s false demise, brings himself to confront the imprisoned Iroh.', '2007-09-28', 25, '/2b5qDWFIxJDlv2d7FLPd9IDwdnk.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
