INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B7D1FD61E8C140E9BAC021A88514658C', X'4F18AC4C8757456CA49A224F00E6A9F7', 10, 'Curly Bear Chases Birthday Cake', 'Today is Baby Bear''s birthday, and he''s about to celebrate it in the courtyard! Telly arrives with his present, and Baby Bear goes over the plan: first they''ll play some party games, then treat themselves to his Mama Bear''s special chocolate-porridge cake. This cake is very special to him, and he''s worried that his little sister Curly will ruin the cake, so Telly promises to guard Curly from getting her grubby paws on the cake.', '2008-09-24', NULL, '/izo1eaS1VY9X16cGgQ793dcLf56.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
