INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B7EF5F4A62E047C8AB6CEDA09775348A', X'5C4E51C6E20746AD875C72988EB1E13E', 4, 'Missile Attack', 'The Pawn Stars take evasive action when a Cold War era heat-seeking missile guidance system locks onto the shop. Will the guys engage and try to blast this deal out of the sky or is this former military secret still too hot to handle? Then, Corey and Chumlee check out a 1986 Buick Regal. Customized from top to bottom, can Corey shift into gear and hit cruise control or will a bumpy negotiation make this low rider hit rock bottom? And later, a man hops into the shop looking to sell an original 1960''s Playboy Bunny uniform. Will Rick jump up his offer to buy this iconic costume or has the price for this sexy rabbit become over inflated?', '2011-04-11', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
