INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B8015A71813E4DC48BE8966BA83104C6', X'FE19A277AED844DFA4ACFC1C4E9941B4', 1, 'New Attitude, Same ATL', 'The Atlanta ladies are back in the drama-filled second season premiere. Shereé decides to throw herself an “Independence Party” to celebrate her recent divorce, while Lisa and her husband discuss the idea of having another baby. The ladies attend actress and comedienne Niecy Nash’s birthday party, where Shereé and NeNe reflect on their tumultuous past. Kim decides she wants to design a line of wigs, and gets the ball rolling by going to cosmetology school. New housewife Kandi contemplates her new life with fiance AJ, while Sheree’s party plans start to go awry.', '2009-07-30', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
