INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B8949465C1C345A29A0299D5DEB06E5B', X'BB5A884361814A6DBFDF33EF2C6BE7B8', 14, 'Barcelona Breakdown', 'In the aftermath of Kim''s text heard ''round the world,'' the women demand that Shereé put her friend in check. Porsha wreaks havoc on the streets of Barcelona, and Cynthia gets over her man problems by taking a dip in the lady pond. It''s all fun and games until things go off the rails during a heated debate. As tensions rise the trip comes to a surprising end for one of the ladies.', '2018-02-25', 43, '/pA8RDwZStnxuFSGZo6qDAvcWQ5u.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
