INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B8A419784EBF468297CA857A9780CD8E', X'87F8406382B345A4936C3759E5D91CE3', 17, 'Who’s Calling Who A Fraud?', 'The ride to Zion has the women on edge as Jen and Lisa face off over her refusal to choose sides between Jen and Meredith. Whitney aims to reunite the group with some spiritual healing, but her efforts quickly go to waste when tempers flare at the white dinner. Meredith’s integrity is called into question, and Jen finally gets a chance to ask for the truth.', '2022-01-16', 44, '/jAEIyLm8W6ci8C4P3zH1zXfXLSW.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B8AC6E7DC2304AB9A94B90C8D1A8ED84', X'94EFC1313A474BCBA519330E791CE905', 3, 'The Rescue Party', 'Percy is having a day off and is busy making sandwiches for a picnic. The rabbits are frolicking in the park and the youngest is being a bit too reckless. She tumbles down the hill and lands on Percy''s doorstep. He tells her that he is having a picnic and then warns her to "Look before you leap". She bounds off, barely heeding his words, more excited about telling the other animals that there is a picnic!', '1996-07-20', 15, NULL, '2026-04-03T17:19:01Z', '2026-04-03T17:19:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
