INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B8BB9E3450BB4BCEA3D88A6C9359B481', X'56108BEED8F24A4BBD6F82205C30318E', 1, 'Stay safe near water with Rosie & Jim', 'This video has been produced by British Waterways, which run the country''s canals and rivers, with Ragdoll productions to help children to understand the dangers of Water in am imaginative way using Rosie and Jim, as well as Duck! The 7 minute video covers the safety points featured in a free Rosie and Jim leaflet which can be obtained from the address below. You might find it helpful to teach Children the safety song featured in the video which is sung to the tune of the Rosie and Jim theme song. British Waterways also produce "Rosie & Jim''s Waterway pack", containing Children''s activities and games plus guidance notes for parents priced £1.00 to cover postage and packing.', '1990-11-10', 10, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
