INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B8DAD0F2B3D744D09E3CD75E14C65819', X'004ABC4CCE774DF98C979F56EA8B37CE', 13, 'The Key', 'Kipper finds an old key and remembers it''s for a clockwork mouse in his toybox. His friend Mouse is unimpressed - it''s not like a real mouse. Kipper decides the two mice should have a race and when the clockwork mouse wins, Mouse has had enough. She decides to hide the key.', '2000-04-13', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
