INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B8FEAF6AFF7F480F8FE9638454442E26', X'D6092173D23B4449BAFFE0E16FE56C9A', 8, 'Beach Please!', 'The ladies arrive in Isle of Palms, South Carolina, and are immediately faced with an unexpected mystery. Tensions flare between Drew and Latoya. As the trip gets fully underway, the women realize they have to confront Kenya for proving to be a less-than-fabulous hostess.', '2021-01-31', 43, '/1MUzbeoN0v7vIldNRIzLLLIiybC.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B900396A671D4439B5E71065628EEC9A', X'BFDF87FF01DD4B5494BD19B384F41BDB', 6, 'Frenemies of the State', 'In the wake of all hell breaking loose at Shannon''s 70''s party, Shannon heads to Dr. Moon to try a new remedy to remove toxins. Kelly tries to make amends by inviting Shannon to sit down and rehash the night. Meanwhile, Meghan travels to Washington, D.C., with Heather by her side, to speak on behalf of colorectal cancer. Tamra explores custom bikinis for her fitness competition and Vicki tours Briana''s new house in the midst of renovations.', '2016-08-01', 44, '/8vk3E58jc0YHOxCffTDo29j8tgu.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
