INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B90E5999DA7E4BCC8F5517F3CC3D695D', X'3430D88114A2497D9CF4351B78B6AA6A', 5, 'Postman Pat Follows a Trail', 'Pat finds a long string across the road and follows it to see where it leads. It leads to a tree where Katy and Tom''s kite is stuck. Pat needs to find someone with a ladder to rescue the kite.', '1997-05-01', 15, '/5BaXjiIT5COTdCKVdoKJL2SJNJg.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B911BE39E8684345BAE4CF0EB66A357C', X'5A6D9A42165B4B5692730A06874DFE10', 15, 'Madeline and the Singing Dog', 'After being evicted from the opera for barking along with her favorite arias, Genevieve is dog napped by an impresario who sets her up at a dinner theatre. When Madeline finally catches up with her talented canine, Genevieve, now a star is reluctant to go home because she is still embarrassed about the incident at the opera. It is up to Madeline to convince Genevieve how much she is missed at the Old House.', '1993-11-07', 30, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B91754FCDD91462AB2A7A44DD8C5BA91', X'C01DDD2ABDB14C978D0458F791EF1C24', 36, 'Hail to Tails', 'A kinkajou comes to hang out in Animal Junction. Her prehensile tail -- a grabber the kinkajou uses to swing through the trees and hop on the ground -- takes center stage. Creatures use their tails for all kinds of things, and Chris and Martin decide to create supertails that combine all the best elements of creature tails. Jackie visits a litter of newborn kittens, who are cute and cuddly, but must be picked up gently by placing hands around their stomachs. A kitten''s tail is not a handle!', '1999-09-10', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B91922AB49F2489485DBE9EA72885903', X'1BB5392776F64ED39C415414AD0865CE', 5, 'To Be a Warrior', 'Mattimeo and his companions race to the landslide beneath where their parents are buried. They are seen by Slagar who send rats to recapture them. Within the cave Matthias and the pursuers are close to suffocating while above them - unknown to them - Mattimeo digs frantically.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B91A636605794E818773907F397D0BAD', X'E1063F8766C24E2DA91353362941AA19', 97, 'Episode 372', 'Susan, Bob, Luis and Maria are putting together a snowman. Big Bird observes the pictures they have of various snowmen to figure out which one they''re going to build.', '1972-03-28', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
