INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B924106AAB60472984B178A3FE97438E', X'EA73E13C696248048305C303DF65F89F', 33, 'Making cotton candy', 'Chef Brockett must explain cotton candy and carnivals to King Friday, and neither interest him. Lady Elaine gets into her fortune-teller mode for the upcoming carnival.', '1969-03-26', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B925F8D3706E404095BF22DFB64DB3A5', X'5C4E51C6E20746AD875C72988EB1E13E', 36, 'Poker Night', 'It''s a high stakes proposition when a man saddles up to the shop with a 19th century professional gambling set. Complete with knife and pistol for when the going gets rough, will Rick go all-in to buy this rare piece, or will a suspicious marking make him call the seller''s bluff? Then, a man bops in with the doll version of Chumlee''s favorite rapper, Snoop Dogg. Will Chumlee scratch up a platinum deal for this collectable piece, or will the negotiations go up in smoke? And later, all bets are off when the guys have an after hours back room poker game. Will the Old Man live up to his King of Cards claim, or will one of the guys make him look like a joker?', '2011-09-26', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B9290DD3202247B9862E2F54A9D88089', X'F4C403079B5E4263A4E0DFA138131E7F', 107, 'A New Baby in My House', 'The birth of a baby is an exciting time. But for an older sibling, it can be a time of confusion and frustration. Through a musical fairy tale, Mrs. Snuffleupagus teaches Snuffy that it’s natural to feel upset when you’re no longer the only kid in the house. Parents’ attention may be divided, he learns, but their love is as strong as ever. Snuffy discovers that, just as his baby sister is special, he has a special place in the family now too—older brother!', '1995-04-18', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
