INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B937968ED80D4611B6F384A9EE4D50BB', X'9E4790F43AAB459CA5ED7100B4E39A75', 8, 'Business Classy', 'Over the holidays, Jenna''s brother visits New York and Brynn connects with her brother in Los Angeles. Sai and Ubah shop for the group''s warm-weather getaway to Anguilla, but Jenna''s choice to fly separate from the rest of the ladies results in an icy greeting on an island paradise.', '2023-09-03', NULL, '/v6Lmb9OX5U2ri5r7NyWt2RIP6UI.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
