INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B94BE5CCED0D4B1EAEA3EE89E24C1FF4', X'0BBD380C5CB846A68838B5D60223C073', 13, 'Charles Aznavour', 'When he''s unable to get a spot on the show, Gonzo asks Scooter to be his manager. Scooter advises Gonzo to do a rock act, banging on a large rock with a mallet. Later, Gonzo tries his hand at female impersonation, wearing a dress and a blonde wig. Scooter gives up managing when Gonzo eats his contract.', '1976-11-28', 26, '/8dY207HoBQTE7lyTWa3C01PDfgo.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
