INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B95D9416BC494C2587FA71FD31472C4F', X'7BC54DF3F32A454EAEF6A9436C35D53B', 10, 'The Pie Restaurant Pt 5 - Opening of the pie restaurant', 'Dr. Yen Wang shows two laboratory rats, with which he wishes to show that the study of rats is intended to benefit human beings. The Neighborhood of Make-Believe opens the pie restaurant, but King Friday orders Bob Dog to move it to Someplace Else as a response to what he did in episode 9.', '1970-02-13', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B96F129EC46845C1A67E5AE8FDECA17D', X'ACAC417E2AA342E79E08ED0D6071A3EE', 16, 'Guess Who’s Arguing At Dinner?', 'As the ladies head out for a day of shopping in Cartegena, Bethenny continues to unravel and the women’s patience with her begins to run out. Carole approaches Sonja for insight on Bethenny. Later over dinner, Tinsley, Ramona, and Sonja try to not eavesdrop on a heated conversation between the two distant friends. A comment Luann makes to Dorinda sends Dorinda off the deep end and puts their friendship on the rocks.', '2018-07-25', 60, '/3iMnV1YSGj0UDItgkFumveCeQWD.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
