INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B97868291C3044A98DB71C926A3AA3A6', X'89BA90EC2C794A12A11D7465D1757683', 14, 'Rick and Morty The Non-Canonical Adventures: Body Snatchers', 'A claymation recreation of a classic scene from ‘Body Snatchers’.', '2017-07-27', 1, '/uktZHU52N8xKjnhscxjGosD5LmI.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B978AA2E2B1C42F2B124F07432272C2E', X'70C8CB4624944DD498F66BFB9B3FAF73', 10, 'Off the Wagon', 'When Corey has a chance to buy an extremely rare Belgium-made 1942 Sarolea motorcycle, Rick has a big concern ... making money. Will they pony up and make a deal or let one of the rarest bikes in America roll out the door? Then the Pawn Stars have a chance to buy a Civil War sword believed to have belonged to a Confederate officer. Will Rick go to battle for this piece of American history, or will its authenticity spark a pawn shop civil war? Then later a woman brings in a cast iron printing press from the 1800''s. Will the Old Man ink an offer or invest in a Xerox machine instead?', '2010-02-15', 21, '/hQM2Op45tdiYBSsMiJAQFxhhjJE.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B97B64AA812443DCB9645E70F4010909', X'332249FA796B4F92B7F8421D523B0BDC', 1, 'The Edge of Fashion', 'Marlo hosts a high-fashion gala to introduce her business, Le’Archive, to Atlanta’s elite, but not everyone is buying what she has to sell. Drew gets an Olympic workout with her new friend, Sanya, and an epic runaround from her husband, Ralph. Sheree returns with an exciting update on her boyfriend.', '2022-05-01', 43, '/jJNW8Osae0VOVnLJ2sthXoDgipr.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B97B9D7C649747CEA981A103B829A058', X'78A02D50E3DC4549844A3CF357A32EF4', 15, 'Lei It All on the Table', 'The tea over-floweth when Kandi relays Porsha''s accusations to Cynthia, Shereé, Kenya, and Shamea, all while Porsha spills the details to her sister. Kenya gets a surprise visit from her brother and his kids that helps her realize she needs to make a decision about her relationship with Matt once and for all. Kandi and Todd plan a couples'' getaway to Maui for all the ladies. Phaedra treats Porsha to a day of beauty treatments in order to convince her to attend as her guest. Tensions erupt when Shereé''s attempt to lei it all out on the table backfires and Porsha finally pushes Kandi past her limit.', '2017-03-05', 43, '/blTbi23uL74GoKFM5DYqkoGD5WV.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B9816C8A70AA4F02AA08DA6859F833D3', X'A8F3A6817ABC41E099889B8804D74611', 3, 'Brutal Honesty', 'As the Sister Wives prepare for Kody''s birthday, Christine tries to reconcile with Robyn by opening up about the problems she''s had since Robyn joined the family. How will Robyn handle this brutally honest conversation?', '2012-05-27', 21, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B9822EA2D8614780AACB4A751B2794BD', X'61E0C9D9337E4FE4A0FDE567B29AF115', 11, 'Troop Salt Lake City', 'Heather and Whitney host a girl''s camp to reunite the women, but fractures in the friend group only become more evident. Meredith invites Mary to a gallery to work through their issues, but things quickly go awry. Lisa and Angie meet up to attempt to make amends, but Bronwyn threatens their reconciliation when she reveals what Angie and Whitney have been talking about behind everyone''s back. As her bat mitzvah approaches, Meredith hosts a Shabbat dinner. Mary has a heart-to-heart with Robert Jr. and learns a dark truth.', '2024-11-27', 55, '/gteq7K8BGhJPkH1sArWPmDgYOf2.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
