INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B9B2F320D7FB444E97B49A2F265E05C6', X'5B5E8B2F0A854488B3DC3D8B794E6582', 4, 'We Have a New Puppet Master', 'While the fallout from The Quiet Woman leaves Shannon and Kelly both stunned, the ladies move on with their lives as Shannon takes her daughter Sophie out for a driving lesson and Kelly looks to improve her love life from the inside out with vaginal rejuvenation. Lydia’s mom, Judy throws a birthday party from her grandson Stirling, where Vicki forms an instant bond with new housewife Peggy. Tamra looks to break the cycle of parental alienation and divorce in her family.', '2017-07-31', 44, '/lBKqHSJVO1qL5seTELDLTXsZGXd.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
