INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'B9B83896065845E88E46FE66B412210E', X'02849455D14B476B9603EEF5FB5D2AB3', 18, 'Unsolved Mystery', 'Ashley finally gives Michael an ultimatum on having a baby, while reality starts to set in for Candiace that she is about to be an instant stepmother. Robyn throws a birthday party for her youngest son, and a new family member makes a special appearance. Meanwhile, Karen and Ashley get into a heated discussion that is escalated by Michael and Ray’s interaction. The ladies question Karen about the mysterious pizza delivery, and her response leaves everyone puzzled.', '2018-08-05', 42, '/xlKeaNGRN4wARjDJOiyYmqycVv3.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
