INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BA1D1ED09D5A468AA0E7170EC9A7B179', X'42E591E22A884434AE9F3D4B1D685613', 32, 'Chum of All Fears', 'Trick R'' Treat with the Pawn Stars as Corey and Chumlee try to pull off the perfect duo Halloween costume. Can they be counted on to work as a team? Then, when Corey checks out a 1933 Plymouth, the Old Man tries to edge in on the deal. And later, a guy brings in a 1977 Mattel Electronic Football Game. A relic from Rick''s childhood, can he separate business from nostalgia?', '2013-10-31', 21, '/xHtvBPDP9wAGAsYfzerK8xBCA8X.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BA2527FD203249AC88D9DF85F44D5212', X'97A3D1F5A8F147CD81222E74A092836D', 3, 'Am I Blue? (3)', 'The police connect the cup in Gaby''s room to the missing spaceship. The costume is found in the toy chest. Gaby confesses that she got the money from the cashier, but has no idea how the spaceship got in her toy chest. However, no one believes her except Alex. Just as Alex confesses to the police that Gaby didn''t steal the spaceship, The producer of Galaxy Girl rushes over to tell the police that he got a note from Galaxy Girl''s #1 fans, and the police suspect Gaby again because she is Galaxy Girl''s #1 fan.', '1993-09-19', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
