INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BB4FADA6C8E94F31997683AB06207012', X'E3A2866991B545F7BB735006ACC084E8', 35, 'Troublesome Tractor', 'The Farmer trying to impress his new date by cooking a romantic dinner. Unfortunately, the Farmer can''t cook and Bitzer is a useless maitre d''. Can Shaun and the flock save the day when they take over the catering behind the scenes?', '2007-09-12', 7, '/gEfb8UNuboCZh8IK5q0KNgSPWvD.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BB55A5460C1E4FC7910BB5EBE8DC82E9', X'CA19F89515144988A70995E84EAB7CEE', 20, 'Bohemian Pawnsody', 'When Rick gets a chance at an iconic collection of Hard Rock photographs, can he capture a deal, or will another one bite the dust? Next, Corey gets revved up for a Harley Davidson motor. Will he put the pedal to the metal, or stop short? Then, Rick and Chum come face to face with giant statues of the Chipmunks. Are they nuts for wanting to squeak out a deal? And finally, when a collection of Pat Morita memorabilia comes into the shop, are happy days ahead, or will Rick''s offer get karate kicked to the curb?', '2021-08-14', 42, '/9MK7MB6VqDUbJYwmFZVtGUoo8oM.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BB56ACE5C0E4464DBBDBA83192A39B65', X'A8C6182E05E14B6891A55126CF6C94F0', 8, 'The Second Continental Congress', 'Desperate for information on what Congress is doing behind the closed doors of the statehouse, James unknowingly befriends a British spy. Sarah and Moses meet George Washington and together use ""Yankee ingenuity"" to fix Washington''s carriage after it breaks.', '2002-09-11', 30, '/ck5KFJwG6QFX3ZRAQcR6kQsq45m.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BB56E93DB73C4C33A662F74601DCA6DF', X'941B8C6544544336BE7C1D0591C12F90', 16, 'Pingu''s Balancing Act', 'Robby is balancing a fish on his nose and Pingu wants to have a go. Robby tosses the fish to Pingu, and it lands on his head and sticks there. Mother then calls Pingu inside to help lay the table. Pingu sees the plated fish ready to be eaten and can’t resist trying to balance his on his beak, but it falls off onto the floor. He then tries to balance the fruit bowl on his head but this also falls off, and shatters. Mother tells him to clear up the mess. Pingu then spots a banana that was in the bowl and so he stops clearing up and tries to balance this. He does quite well until Mother returns and tells him to get back to clearing up. Father arrives home and the family sit down to dinner, but there’s no sign of Pingu. He then appears, balancing Pinga’s rabbit, but then overbalances and ends up in the toy box. As he emerges, trying to balance a ball, Mother goes across, takes the ball, dribbles it for a bit, and rolls it back into the toybox and tells him to sit down and eat his dinner. He rapidly gulps down his fish but doesn’t want the green stuff. When Pinga drops a piece of her fish, and is distracted, he puts his greens onto her plate and asks to get down. He gets the ball and takes it outside to practice balancing. Robby is still there, with his fish. Pingu has a go at balancing the ball, but fails to keep it up for more than a few seconds. Robby thinks this is funny and shows off his balancing skill with his fish, including flipping it up and down while moving. Unfortunately he goes too far and the fish ends up stuck on top of the shed. Robby’s very unhappy about this, so Pingu goes over to help. He gets Robby to hold the ball in position and then bounces up and down on it until he’s high enough to get the fish. He flips off the fish but is left clinging to the top of the shed. He slips off and lands feet first on the ball. After a wobbly start he discovers that he can balance on top of the ball and move around as well. Robby has a go, but falls off and the ball crashes into the igloo door. The family rush to see what’s happening, find Robby and Pingu performing, and applaud them.', '2004-01-23', 5, '/sNVFzhNZIKe2xlmFmi51ANOe2fh.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
