INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BB663DB8BA22413888465309DD18F0C0', X'1756FC59E1874D0EA7BA465EAFC4FBA0', 13, 'Camping / Troll Under the Bed / Puppy Love', '', '1996-10-20', NULL, NULL, '2026-04-03T17:11:21Z', '2026-04-03T17:11:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BB6C24DC6E4F4B3DA7E3B50939E42BFC', X'68138DE20900460AB58E480688F1E081', 35, 'And To All A Good Night', 'Bear has received a book of brainteasers and is eager to try some of them. As he tries them out and shares them with the viewers, he finds that the kids of the house are doing some thinking as well. Tutter found a piece of string and is delighted because there''s all sorts of things he can do with it. A couple of things he does include using it as a lasso for cheese and as a trail to direct Bear to a present --- his very own ball of string. While out at his favorite thinking spot, Bear talks with Pip and Pop. They try to do some thinking of their own, but can''t figure out anything to think about. Bear helps them to see that they are in fact, thinking, and helps them to recap several things they thought about later during the day. In the Shadow segment, Shadow tells a story about a man in the wilderness. It finally comes time for a break from all that thinking and Ojo and Treelo decide they want in on whatever fun thing Bear is going to do. It turns out that it''s time for the Bear Cha-Cha-Cha! 
