INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BB81631886C44FEAA1AE1382531F0EDD', X'D0B78F22678E4E469D61AAC40BA206B8', 17, 'A Double Shot of Brandi', 'Kyle plans a girls’ trip to Provence, France. Erika and Lisa Rinna are astonished by Camille talking out of both sides of her mouth about Dorit – and are certain Dorit will call her on it. Denise spends a wild night with new friend Brandi Glanville and gets an earful about the other women.', '2019-06-04', 43, '/tM1vA4WAj1YXpTIWDtWwUJbI9nk.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
