INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BB8A358E19424AC086D61493F9B287DE', X'227B84290DFD47E4B874C37DA20C403F', 4, 'Knights in Fake Armor?', 'It''s clear that this is no ordinary pawn shop as the Pawn Stars wheel and deal items ranging from an old school Pac-Man to a Medieval Jousting Helmet. If these items are as real as their owner''s say they are - they could be worth up to $30,000! Then, an old timer brings in a pristine 1884 Trap Door rifle that the guys buy hoping that it still fires. But, when the gun range owner says that simply firing it could cause a "catastrophic malfunction" the guys decide it''s time to bring out their human guinea pig.', '2009-07-26', 21, '/rP5CCApTd1LNPN8YA6iJ0KTWTT5.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
