INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BB9D07332211425C9595CDC81E59B99A', X'D1863F2F02EC40CEAF64DB03FBE518A7', 34, 'School for Chickens', 'Elmo helps Professor Buck Awe, played by Saturday Night Live''s Taran Killam, teach a class of chickens using strategies he learned in preschool. Also featuring Murray has a little lamb, and Elmo''s World. Brought to you by the letter S and the number 14.', '2016-08-27', NULL, '/5KwJsyQ9Ute92jo1fvRQlpW1DQt.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BBA5881B8D704DAC8D25A1A5E01EADAF', X'D9973960273B4A92A7DA62EFE8860D09', 15, 'Reunion (2)', 'Mary reveals intimate details about her marriage and sets the record straight about her church. Jen finally puts the hospital comments to bed, meanwhile Meredith demands respect from the women about her marriage. Frustrations heighten between Lisa, Whitney and Heather, which finally pushes Lisa to her breaking point.', '2021-02-17', 42, '/oy1Wo1IBuaKxRsZXDIuuLQmIj85.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
