INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BBAC5E9D1EE443FB8C4BE25CF5AACBCC', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 123, 'Episode 2218', 'The Grouchketeers assemble as the audience for The Grouch News, anchored by Oscar the Grouch. He checks in with English correspondent Dwight. Telly comes into the Fix-It Shop with a problem - he''s forgotten the name of a new friend he''s made, and frets about their next encounter, worried it might cause some animosity.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BBADFD74CF904C5D9E687E9FBF87F31E', X'D920EBAEF00A4E25ABFE40492C74DED6', 9, 'Gold (& Silver) Digger', 'When a revolutionary French gun butts into the Gold & Silver Pawn Shop, can Rick and Corey hang on to their Boutet? Next, Corey saves a trip to the post office when someone brings in their vintage stamp book. Then, Chum gets wrapped up in a Kanye West jacket. Will this Gold Digger take his money, or leave him heartless? Later, a real-life recreation of a sword from the video game "World of Warcraft" swings into the shop. Can Rick cut a deal, or will he suffer the Wrath of The Lich King?', '2020-01-27', 42, '/u9Py0L40YjIxogo7YRGYO73l5xK.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
