INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BBB7156676754D89BA07DB276C3979D5', X'E48599F866FF4C0F927465B9AE1CDA9E', 78, 'Episode 78', 'Blowpipes and Bloodsuckers  Highlights of Blue Peter''s eventful expedition to Brunei in Northern Borneo, when the Chief of the Punan tribe gave JOHN a blowpipe lesson, LESLEY met a mini parasite with a mighty bite, and PETER tried his hand at raft building during a Jungle Survival course.', '1977-06-23', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BBBA4B6802824CDA8A1FFB69FC731696', X'68138DE20900460AB58E480688F1E081', 34, 'Wish You Were Here', 'When Bear reads Tutter the story of "Mousy the Great," Tutter wants to be just like his hero. But when Ojo rescues him from the "dragon," he''s not too sure he''s very good at it. With a little help from Bear, Tutter learns that heroes come in all shapes and sizes. And every single one is great.', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BBBA8D3C467E4A61BC634EA848C6349A', X'262E8E7CFA784578A216ADD6F184C4D2', 16, 'Defending Polygamy', 'Kody and his wives finally return to his hometown for the first time as open polygamists. How will his childhood friends receive him? Later, after revealing the sex of the baby, Robyn and Kody finally decide to announce the name.', '2011-10-16', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BBBC1D85E28E4570AFB63C0452A118E7', X'65D1CAD80120425EAE9B5020CE773B32', 6, 'What Voodoo You Do?', 'As the New Orleans trip continues, the ladies keep the festivities going by attending a dog parade and making voodoo dolls; Jenn continues to question the intention behind sharing the unflattering picture; Shannon remains cautious.', '2025-08-14', NULL, '/bQyoC533bxw4WNWSD50CbN8WM8b.jpg', '2026-04-03T16:35:36Z', '2026-04-03T16:35:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
