INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BBEDB2235A6C405ABF5C529D2B1AE112', X'1C0A48A44D1C424BB54F265883E6B26E', 17, 'Reunion Part 1', '', '2023-09-03', NULL, '/1EZ3Omc7S8fYd4T9Tz40kbdCn4q.jpg', '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BBEF9A51BDBA423F9F5EA81671BDF48B', X'4FE93658C46343298E649D523869C2CB', 11, 'Gone with the Schwinn', 'The Pawn Stars are brushed with Vegas royalty when they are presented with a huge truckload of personal tapes from Rat Pack legend Sammy Davis Jr. Will they be singing a sweet tune to make this deal or will they be left reaching for the stars? Then, Rick meets a man with a mysterious miniature cannon believed to be from the 18th century. Will Rick make a booming offer for this little noisemaker or will it prove to be all bark and no bite? And later, Corey and Chumlee have a chance to buy a pair of pristine 1950''s Schwinn Phantom Bicycles. Will they pedal themselves up a difficult negotiation or will they be thrown off their game by one sharp turn?', '2010-10-25', 21, '/wDK9RpymogCOhXdlPnYEIvTkkZ3.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BBF52B7239EE425FB98F7A720BCEC93F', X'E03D79BDE01F4414B0B3F3B5F26E97F4', 4, 'The Quarry', 'When Axl is suspended for skipping school, Mike decides it''s time to teach his son a lesson about life and makes him go to work with him at the quarry. But Mike''s master plan backfires when Axl likes the job so much that he wants to quit school and lead the life of a quarryman. Meanwhile, Frankie is devastated when she fears that she accidentally prayed away Sue''s cross-country team after it''s cut by the school; and while practicing a magic trick, Brick makes the main TV remote disappear - and can''t figure out how to make it reappear.', '2010-10-13', 22, NULL, '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BBF88417F75D43688C4E4985E25FCC77', X'D1D267DDE27F4543ACB80D28F676512A', 65, 'Episode 65', 'with Valerie Singleton, John Noakes, Peter Purves.', '1968-04-22', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BBFAF2AA5D6143249733AAC426D6AD92', X'97D7FF20E6FF4DBBBCDDFD87A1D0FA4E', 9, 'Jumpin'' Jake Flash', 'A set of replica Muppets has Chum feeling green with envy; But will going gonzo over these furry friends land him the goods? Meanwhile, Rick flips over an autograph book from the 1800s, but are the signatures the real deal? Next, when a pair of pants supposedly worn by Keith Richard rolls into the shop, Corey teaches his brother Jake you can''t always get what you want. And later, Rick has a "finger-lickin" good time when he pops over to a gallery in L.A. Will he find the secret ingredient to success, or walk away feeling spicy?', '2023-05-10', 41, NULL, '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
