INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC002DB972DF464D9B00E74349CC9B8B', X'CA3F764EB3304980BD7A2908A73B77B6', 23, 'Reunion (3)', 'Kim Richards exclusively reveals to Andy Cohen, "I am an alcoholic" and discusses life after rehab. Housewife friend Dana Wilkey also appears to recount with her recollection of Game Night followed by the husbands who field viewer questions.', '2012-02-13', 43, '/8huqSp3mFgnphiEk79H1qbJOpEt.jpg', '2026-04-03T16:34:55Z', '2026-04-03T16:34:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC08D2A305C64633B18365942E8B35F8', X'913F846D85DF46948DD40D5909F78887', 5, 'Perseverance', 'During a trail bike race with her friend, Zach, Annie is left in the dirt and becomes discouraged.  She rests up at Plato’s Peak, just enough time to hear the story of The Tortoise and the Hare, which teaches her a valuable perseverance lesson: Slow and steady wins the race.', '2000-10-22', 30, NULL, '2026-04-03T17:38:35Z', '2026-04-03T17:38:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC0F56D762F54773915F041EAF23C994', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 78, 'A day with books on Sesame Street', 'Luis is swamped with work at the Fix-It Shop, and Maria is too busy reading her book - The Adventures of Captain Swashbuckle - to help. While fixing Big Bird''s record player, Luis tells him of a story he''s reading about Captain Swashbuckle, a pirate.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC12819FB8D5432AB7194687BF3E5596', X'BBE548394A6E45E1B3C57B77F98A0E86', 8, 'Episode 8', '', '1994-02-23', 25, NULL, '2026-04-03T17:21:16Z', '2026-04-03T17:21:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC13D6A6F7AF485C817A9FD235C738B5', X'7C75633629DB4634B976E993E8F51DA2', 11, 'The Grand Dame Slam', 'A sunset cruise hits rough waters when Charrisse corners Karen about her overbearing hosting duties while in Bermuda. Also, Robyn discovers many men are interested in her. In Potomac, Michael makes changes at the restaurant, and Karen breaks news about her coveted Potomac address.', '2017-06-18', 42, '/qtu1OaDwxWzrfBbJ5y6d7XztShm.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC19FC33EB774E0F994C88B382BFAB67', X'3FC7C152E4F6426AA89936EC454C4403', 13, 'The Giant of Nod', 'Zak and Wheezie practice for tonight''s concert hosted by Quetzal at Singing Springs, but they war over various songs they wanted to play and disturb the nap of a twelve-inch creature known eponymously as "The Giant of Nod". He desperately throws them in a tree trunk, so it''s up to them to save the gang so they can make it to the concert.', '1999-09-21', 30, '/uYwl6qcISwyZgFb7NjnCEQj1pTr.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC1D12964EC64589B757BBA9247AC141', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 31, 'Max the Magician', 'Everyone tries to figure out the secrets to Max the Magician''s tricks, only to discover that they''re really just math.', '2010-10-15', NULL, '/zVtdwejXYJXkLfoNdx8ttdB1wm3.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
