INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC25823BD2E54506B07981431482687C', X'F30BBF8187704E74B68B280E7C85B52F', 12, 'The Busboy', 'George inadvertently meddles in the life of a busboy, by getting him fired. He tries to rectify things; however, he winds up compounding them by losing the busboy''s cat. Elaine discovers that a week is much too long to have a houseguest. She does everything in her power to get him out. The busboy''s life is saved and made for the better after his involvement with George, until he meets Elaine''s houseguest.', '1991-06-26', 23, '/sxybPj7nX8a0M4bULeVWzFVb2R0.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
