INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC7B9E84F2814CF6AC5DF38D2A70DF84', X'F21CA545466C448CADA5B8ACC8B856DC', 4, 'Time to Go Home', 'Karen is bored when she has to stay with her Gran, but having the magic watch proves to be very useful at times like this.', '1999-10-15', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC7BC330454E45E58D331C4102D2BAF0', X'363A94F9E0E5441CAA862BE2E9832DA1', 12, 'The Prince of Pawn', 'When a painting by Prince pops into the Pawn Shop, is it time to Party Like it''s 1999, or will we hear what it sounds like when Rick cries? Next, Chum takes a gamble on a Cartier poker set. Is he all in, or is it too much of a wild card? Later, Corey takes off to Virginia to check out some radio-control airplanes. Will he land a deal, or fly home solo? Finally, Chum let''s Spencer run point on a custom lowrider bicycle. Can Spencer handle the deal, or will he just spin his wheels?', '2021-12-11', 42, '/fMGda2BIsFHcA4x8lWoR9g2MinC.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC7F45DFBFCD43B19D743A333BAA67D2', X'20D7138EEEA846A88ADA2B0F0EE1F674', 30, 'Episode 30', 'Today there''s the latest news of the Treasure Hunt Appeal in aid of children and babies suffering from kidney failure. Your treasure can save lives, and the depot will be open over Christmas, except for Christmas Day, Christmas Sunday and Boxing Day.', '1982-12-23', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC81025D9F574A02BCD9646DAAF10EBC', X'6ACFEFC019044F939C06A1A09856150A', 1, 'The Wishing Fountain / Bunton Q. Bunny / Boo Who?', '', '2002-11-24', NULL, NULL, '2026-04-03T17:11:23Z', '2026-04-03T17:11:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC88DD02921C4DC1A11A42644B90A976', X'E291DF42D44F49E5BF812DF32EE4A30F', 12, 'Smellorama', 'Spring has come to Woodland Valley and Bear is delighted by all of smells of the season. It''s a veritable smellorama for him. As he makes his way to the kitchen, he finds smells there as well. Tutter has created his own "smellseum." Bear loves the smell of lilacs in his collection, but doesn''t think much of his limburger cheese sandwich smell. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC8AB68B329E49919DB6317700CABC67', X'03485B5EA5B7423EB21EC00E62216A35', 4, 'The Big Blooper', 'Sister starts to swear after seeing a movie meant for teens.', '2004-09-07', NULL, NULL, '2026-04-03T17:40:22Z', '2026-04-03T17:40:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BC90EA0C85B746688A8D17F35DF79F25', X'D920EBAEF00A4E25ABFE40492C74DED6', 14, 'Watches, Waistcoats and Wizards', 'Corey gets a lesson in the Care of Magical Creatures when a life-sized house elf from Harry Potter comes into the shop. Will he be able to get the seller under his spell'' Then, Spencer comes fresh off a picking trip with a van full of items. Will Rick and Chum take the HOV lane straight to a deal'' Next, Rick checks out a waistcoat and watch as old as the founding fathers. Will it be good enough for his John Hancock, or will it go overboard like the Tea Party'' And later, the Pawn Stars take a trip to the mountains to see if Chum will go through with a death defying climb.', '2020-03-16', 42, '/aZAPdumm1f6FrtAehxdOMYQGitG.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
