INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BCBC12921352470E8CA64EF8BB6EDA53', X'F5C042DC065742E8A37D247414140632', 16, 'Southfork Goes South', 'Recreating the infamous “Who Shot J.R.?” moment from the hit series Dallas, the ladies try to solve the mystery of "Who Shot Brandi?" The husbands join their wives for a day of fun and armadillo racing, but the absence of Eduardo proves too much for Kary to handle. A night of partying turns destructive when Kary and Brandi break into the iconic J.R. Room, causing the other ladies to confront them about their behavior.', '2021-04-27', NULL, '/712G3EkfZ630lcxGtGYbP5b9Waj.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BCBEA09D87C04BEEA215B27BE4C2897C', X'73AE1459BA914185A9DABF6F2844AF49', 2, 'Stooping to a Lower Level', 'In the city, Tinsley defends herself to Sonja and Leah over her continuing feud with Dorinda. To celebrate the end of summer the ladies head out to Ramona’s house in the Hamptons for a long weekend. Tinsley’s flu leaves her voiceless and Leah’s tattoos become big news. Despite being relegated to the basement, Luann apologizes to the women for her behavior over the last year.', '2020-04-09', 60, '/ofvkatcwtsgcdFFRthY8Q7gJzo0.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
