INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BCCCAD6BB4134C9E90B0A9AC2A445CC0', X'02C86AE38C3B4CC08E1F0B27D01DCD91', 1, 'Welcome One, Welcome ATL', 'In the premiere episode of Real Housewives of Atlanta, NBA wife DeShawn and her family see their custom built mansion for the first time and she begins the search for the perfect staff to run it. Real estate powerhouse Lisa is learning to balance business and motherhood with her NFL hubby''s support. Meanwhile, after a three-year divorce battle with former NFL player Bob Whitfield, socialite Shereé plans a birthday blowout at her estate to celebrate her new life, and cracks the whip on her staff to make sure no detail is missed - from the Louis Vuitton cake to the exclusive guest list. All the Housewives are invited, including NeNe, who has ongoing tension with Shereé. In between shopping sprees funded by her mystery multi-millionaire boyfriend, "Big Papa," blonde bombshell Kim meets NeNe for lunch and they plan to arrive at Shereé''s party fashionably late, but a scene erupts when one of them isn''t on the list.', '2008-10-07', 43, NULL, '2026-04-03T16:34:44Z', '2026-04-03T16:34:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BCD176DA3E4547D7AE8E70672674B3C1', X'332249FA796B4F92B7F8421D523B0BDC', 15, 'No Michelle Obama', 'On their last day in Jamaica, Sanya and Kenya can’t move past a miscommunication. Kandi refuses to forgive Marlo for their epic showdown. Shereé puts She by Shereé planning into full throttle.', '2022-08-21', NULL, '/cZ5u28hOeGculKMQYMc5ORe22j3.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BCDD460ED28C42A394E5A408D5851CC4', X'7C422193B07849D881EFF2B9F94F059D', 5, 'Cyranose de Bergerac undergoes sensitivity training', 'Episode #3010', '1992-11-13', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BCDF2CA7784249DC909FCA572FD0893F', X'3269A890BBA94E6C9278F7EB38EB1720', 6, 'Evolution', 'All living things have genes, which are like little sets of blueprints. Genes have information about the color of your eyes, the shape of your nose, and whether you hair is straight or curly. When living things make other living things, they pass copies of these blueprints to the offspring. The copies are mixtures. They’re never exact, never quite perfect. So, the cool thing is that no two sets of blueprints are exactly alike. So each living thing is different from other living things. Scientists know about evolution from fossils. Fossils show how living things used to look millions of years ago. Scientists take information from fossils to see how living things have changed over thousands, hundreds of thousands, and millions of years.', '1995-02-17', 26, '/srLsvT8m0oYm6ZZBHOS11nEA1sN.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
