INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BCFE5B893EDE4A15A7E854599E6A9542', X'ECB64EF34F8045A7B4A9C04434B02E35', 44, 'Pawn U', 'Turn the page with the Pawn Stars when a first edition of Mark Twain''s "A Yankee in King Arthur''s Court" finds itself in the shop. Will Rick make a deal that''s one for the books or will it be nothing to write home about? Then, the guys take a trip to Neverland when a 1953 Peter Pan animation flies in. Will Corey and Chumlee join the Lost Boys or make the seller walk the plank? And later, Rick takes his business expertise to the classroom. Can he school some college students on the tricks of the trade or will they end up teaching him a lesson?', '2014-05-29', 21, '/s2HmrbjeYDYTQZCrLh1ZLLeQNs0.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
