INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BD0606C53CAE45EC883B7DA510255849', X'8B6BBAC8E5EF49C7A5C1197CFB19F772', 10, 'Competition', '', '1981-06-05', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BD073F8574F54DCD9E9106659BCBC18E', X'1D713CA64E174F84949C8CFD98514127', 13, 'Break on Through', 'Break on through with the Pawn Stars when a painted bedroom door from the childhood home of The Doors'' Jim Morrison lands in the shop. Will this unique canvas light Rick''s fire or will it leave him singing the roadhouse blues? Then, Chumlee checks out a 1988 Zelda board game. Will he use a link to the past and win big or will he not have enough hearts to bring the game home? And later, when Corey gets a lead on a rare and perfectly restored collection of Indian motorcycles from the early-to-mid 1900s, Rick decides to tag along to keep him in check. Can he steer Corey away from overspending or will things fishtail into a roadside disaster?', '2014-09-01', 21, '/4Geoo1bKLZwW3Byz1RIfzjVs7mF.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
