INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BD353EFAE0F44CC6AAD9594C88FA0319', X'D8CCF6D3E37A430AB67D7FBF269BF0BE', 5, 'The Nastiness and Rumors', 'Heather talks to her daughters about the effect her book has had on them. Whitney and Justin struggle with their changing roles now that Justin is back at work. Lisa, still hurt from the accusations made in Palm Springs, hosts an event and confronts Monica. The rumors about Angie''s marriage reach a boiling point.', '2023-10-03', 44, '/6kjFpqhr99hd9muWvsjCL5NgJHj.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BD35BBD5C40B4E4EB90A783175FDFF22', X'BB5A884361814A6DBFDF33EF2C6BE7B8', 21, 'Reunion (3)', 'Kim reflects on her return to the show, which leads to a fiery verbal encounter with Kenya. While NeNe and Kim go head-to-head in the ultimate battle of words.', '2018-04-22', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BD35DF7269C345F98626E8EC6B5E571D', X'5144DE59E67F4FCF919B7106989AB797', 9, 'Roamantics', 'Ben brings in an ant farm to show everyone, but Leon unwittingly wreaks havoc in an attempt to give the ants fresh air, and has to make some sacrifices to restore order to The Puzzle Place. Nuzzle gets carried away with a roll of paper towel.', '1995-01-26', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BD4323351B644570B092B3A6CFBC24F4', X'F593D90C533942F59C885BFD48D04075', 14, 'Hide And Squeak', 'The Farmer is terrorised when a cute mouse appears in the farmhouse and Pidsley the cat is ordered to dispose of the rodent. When the mouse takes refuge in Shaun''s fleece, the flock persuade him to protect their new friend from the pitiless cat.', '2010-01-10', 7, '/9RIhwqqXLFgZgz3qDJGYfELqFuN.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BD45A4DF040940E499D2592CADB95BC2', X'02C86AE38C3B4CC08E1F0B27D01DCD91', 5, 'Out of Tune', 'Shereé and Lisa let loose at a pole dancing class. Lisa, DeShawn, NeNe and their husbands spend a luxurious evening together at a vineyard to celebrate DeShawn''s 34th birthday. The dinner takes a turn for the worse after NeNe starts to gossip about Shereé and makes up a nasty song about Kim''s music career. Kim and Shereé have a Botox date during which Kim finds out about the song NeNe sang about her, the two bond over mistrust for NeNe. When Kim ignores NeNe during an afternoon of lingerie shopping, the tensions mount and things get ugly. Kim''s plans for stardom are at stake as Grammy Award-winning producer Dallas Austin sends her to celebrity music coach, Miss Jan. Meanwhile, inspired by DeShawn, NeNe starts her own foundation for battered women, Twisted Hearts. She throws a "Big Hats" fundraising brunch and opens up about her past turmoil to a moved audience. After futile efforts to get NeNe and Kim to talk, DeShawn joins NeNe for a girls'' night where they focus on surrounding themselves with positive people and true friends.', '2008-11-04', 43, NULL, '2026-04-03T16:34:44Z', '2026-04-03T16:34:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BD45B09F417D4E7FBFCF2D7A6E674439', X'526BD779909A480DA38D1FA625A7C21F', 5, 'Karen''s Grande Dame Reunion - Part 2: Surry Secrets', 'After an intense exchange, Aunt Val shares her plan for the future of the family farm. Karen and Rayvin learn more details about their ancestral history and are shocked by the secrets found along the way. The Family Reunion begins with a good time outdoors, but when the Wooden men join Karen for a tough conversation about the legacy of the farm, Val makes a revelation that leaves everyone floored.', '2022-04-25', NULL, NULL, '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
