INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BD5F2CA12EAA40E1A4F49F4D65ABCB7E', X'5C4E51C6E20746AD875C72988EB1E13E', 23, 'Buffalo Bull', 'The Pawn Stars hope to win by a landslide when President Ronald Reagan''s high school yearbook comes into the shop. Complete with a signed letter from The Gipper, will the guys make an executive decision to buy this presidential memorabilia, or will a tough negotiation force them to veto? Then, a man comes in hoping to sell some puppets and props from the original Buffalo Bill Wild West Show. Tied to an obscure performer named Buffalo Ben, will Rick pony up some cash for this collection, or will he send it out to pasture? And later, Rick and the Old Man get a call to check out a vintage phone booth. Will they try to dial up a deal for this piece of telephone history, or drop the call before negotiations begin?', '2011-08-01', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
