INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BE0A58368C804D37B53AB17D5D2426D2', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 16, 'Rakhi Road', 'Leela is making bracelets to celebrate an Indian holiday called Rakhi, a time when sisters, brothers, and friends show how much they love each other by exchanging special bracelets, foods, and gifts. Leela already sent a bracelet to her brother, Sunil, in India and now she is expecting a bracelet from him any moment. While she waits, she helps Telly and Zoe make bracelets for their friends. Just then, a delivery person brings a box that turns out to be a sample of laundry detergent-- not her brother’s gift. Meanwhile, at Hooper’s Store, Elmo comes upon Chris who is making a bracelet for Leela. He wants to do something special for Leela since she’s feeling homesick. They decide to use the computer to learn more about Rakhi and to find some recipes for traditional Indian foods such as phirni, carrot halwa and laddoo. Now all they need is some Indian music to make the Rakhi party complete! Leela is surprised and happy to see how Chris and Elmo brought a little bit of India to Sesame Street with all of the decorations, food, and music. Everyone exchanges their bracelets and Sunil’s bracelet for Leela finally arrives in the mail! Now the Rakhi party can really begin. Everyone dances and sings about the importance of friendship and family.', '2010-11-26', NULL, '/AckzzBVfG3aWcbDlnFsMPv2VMQw.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
