INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BE1732C94E704BF0AEC25C6DA6CB6FBD', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 4, 'Architecture', 'Towers, teepees, castles, and condominiums – some kind of planning goes into all buildings, no matter how big or small. Architects are people who design buildings, and the areas around buildings. Usually architects draw on a computer or a big desk (a drawing board). The plans show the dimensions of all parts of a building. Architects try to design with the purpose of the building in mind, but even buildings used for the same thing can look very different.', '1997-10-24', 26, '/7Lo3pWHyNi9Mjtt4KyBGWhuAiAu.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BE1A2B6E647C448DAC387845842195A8', X'6F731E6BD3C54DE684E17A19CB650E86', 36, 'Stairway to Pawn', 'Get your ghoul on with the Pawn Stars when a talking Herman Munster doll creeps into the shop. Will Chum think it''s franken-tastic and make a deal or will he get spooked out? Next, things get amped up when a bass guitar signed by John Entwistle from the "Who" and John Paul Jones from "Led Zeppelin" is brought in. Will Rick pick up a sale or will he fret and miss out? And later, Rick''s in mint condition when he checks out a rare 1867 Proof Shield Nickel. Will he strike up an offer or will he discontinue the deal?', '2016-05-25', 21, '/aCNzeygSk2Xmi1jo52oKIOPZ8Pa.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
