INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BE1F7A3BF4AA4541A37985180ADF17AF', X'793A6B2C7CAD4F12A94374729E3D9CA6', 15, 'DELETE ME', '', NULL, 5, NULL, '2026-04-03T17:24:24Z', '2026-04-03T17:24:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BE23DFB64B9F4D0681C32C4C1200A00B', X'C21DBD225E2E4414BB67750399AAF6F0', 15, 'Crosby, Stills and Cash', 'The Pawn Stars are blown away when a pair of WWII bomb fins drop into the shop. Designed to keep bombs on target, will the guys try to blast out a deal for these rare military items, or will they run for cover as the negotiation implodes? Then, Rick tries to get in tune with a guy who brings in a Martin guitar signed by 60''s super group Crosby, Stills and Nash. Will Rick''s offer be music to the seller''s ears, or will he get nothing but feedback? And later, the guys continue their daunting search for a new employee to work the night shift. Will they pick beauty over brains or go with a safe bet?', '2012-01-16', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BE26CF8A5FA0408CBCEABEC4D8C5867F', X'E40E6B639F84449F8E8853209B0906C8', 13, 'Gabi, Telly, and Zoe Have a Picnic', 'Gabi, Zoe and Telly are gathered around at a picnic table outside of Hooper''s Store for a picnic. Maria brings them a melon and sets it on the table. They briefly turn their attention away from the melon while Telly shows them the triangular napkins he brought. But when Telly goes to get the melon, he finds it''s missing! Everyone is confused - where did the melon go? It''s not under the table.', '2007-09-10', NULL, '/vxo24Mg6O6veE32BTuLlBt68hf1.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BE2841F581614055BE5375113AAA55D2', X'BC1B58B0F2D64214914B231F27FB4D61', 1, 'In The Name Of The Father', 'Melissa and Kathy are busy preparing for a family christening. Jacqueline''s lunch with Ashley goes sour when her feelings of guilt and frustration boil over, and Teresa focuses on saving her family from ruin.', '2011-05-16', 43, '/hWPEHjrDsdkNOh93Zziwnixq2Fb.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BE31EF26019F4DCBA6150A74D7CA027B', X'787DFA0BC8274DADA82D0548A6534D88', 5, 'Game Changer', 'Vicki gets a phone call that forever changes her life. Shannon offers an olive branch to Meghan when she hosts a Bunco party at her house. Meanwhile, Meghan moves into another house and Heather has an unorthodox date night with Terry that gets a little bloody.', '2015-07-06', 44, '/A43UEVqU2Nkti3yDWoKMSnVGfqQ.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BE35FCB603BF4F2FAB7DA13D0602F8AE', X'DE8EC76916BB436BBE43AEDC7E18A7D7', 2, 'The Great Sesame Street Cake Off', 'Cookie Monster and Gonger team up against Grover and Alan in a competition to see who can bake the best birthday cake for Nina. Elmo and Rosita help the two teams work together, combining one team’s cake and the other team’s frosting to make the ultimate birthday treat.', '2019-11-23', 30, '/38s0GdDj8lb1RLAiElnrVwTea8p.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
