INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BE3CB3CFBD514588B822D7FC143CBF90', X'ECB64EF34F8045A7B4A9C04434B02E35', 5, 'I''ll Be Doggone', 'Take one giant leap for mankind with the Pawn Stars when Rick checks out a jetpack from the Gemini space program. Used to prove that jetpacks could work in zero gravity, will Rick''s offer be out of this world? Then, Chumlee''s nuts over a Snoopy comic book with a personal drawing from Charles Schulz. Will Chumlee be able to kick the proverbial football and make a deal? And later, Rick''s take on a commercial for the pawn shop inspires Chumlee to make a version of his own. Whose commercial will reign supreme?', '2014-01-16', 21, '/aRjyIEXY4UbcPAnjGhO8BwXu6Zr.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
