INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BE784F93F1834322A1C0FB70E990110A', X'5FA796B4EAA34D89A7460A8B86CB8432', 3, 'The Bicycle Man', 'Wheels are set in motion for this program. In-line skating, then a brand-new commodity, get featured side-by-side with bicycles. Tom Matsusaka narrates The Bicycle Man, a story about an American soldier who visits Japan and performs amazing tricks on a bicycle.', '1990-09-12', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
