INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BED985DEE4A74355957405F1BAEB7040', X'FE19A277AED844DFA4ACFC1C4E9941B4', 4, 'Mummies, Mommies and Baby Mommas', 'NeNe and Dwight chat during a visit to the salon, while Lisa discusses a trip to L.A. to visit her mom. Kandi meets with her photographer and business team to discuss her image. Fitness guru Shereé attends a bodybuilding event, while Kandi and AJ get their engagement photos taken. Also, when Kim learns that her nanny left her girls home alone without supervision, drama ensues. Then, the ladies attend a King Tut cocktail party with their kids.', '2009-08-20', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BEDCB06E964F4AC3A9FDBD7C720D5968', X'5C4E51C6E20746AD875C72988EB1E13E', 13, 'Broadsiding Lincoln', 'The hunt is on when the Pawn Stars are presented with one of the most sought after items in American history, a John Wilkes Booth Wanted Poster. Will this priceless piece give them the slip or is Rick determined to bring it in dead or alive? Then, a guy buzzes the shop with a fighter pilot''s G-Suit. Designed to prevent pilots from passing out, will the guys lock their radar onto this item or will a tough negotiation leave them feeling woozy? And later, Rick is flashed a Police badge from 1930s Al Capone controlled Chicago. Will Rick follow the strict letter of the law to make a deal or will the seller need some extra "convincing?"', '2011-05-30', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
