INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BF1460E04360482DA0D8D8AAEF7355FE', X'7CCD5605FE0B4E00AE7F3E3DAA252F8B', 2, 'Friends, Enemies, and Husbands', 'Lynne Curtin''s private showing for the ladies of her cuff line comes to a screeching halt thanks to a heated fight between rivals Tamra Barney and Gretchen Rossi. The camps divide, with Tamra unloading her feelings on her friend, Vicki Gunvalson, while Gretchen tells her side of the story to Jeana Keough and Lynne. But Lynne is feeling her loyalties pull in two directions now that she and Tamra Barney have grown closer. Meanwhile, Simon sells a luxury car to an acquaintance and his wife – Jim and Alexis Bellino – and he invites them on a double date so Alexis can meet Tamra.', '2009-11-12', 44, '/y6LO3aUfJlbsS9RC8Zu3yTDCpHz.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
