INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BF513105FE8C46CF945A5D382B750BBD', X'E03D79BDE01F4414B0B3F3B5F26E97F4', 9, 'Thanksgiving II', 'Mike begrudgingly invites his brother, Rusty, who is temporarily living in a tent, and his father, Big Mike, who has recently broken his hip, to join him for the annual Heck family Thanksgiving. But when Frankie observes the macho Heck men''s non-communicative nature, she encourages a not-so-receptive Mike to engage them in a real conversation and express their feelings. Meanwhile, Brick is ecstatic when he discovers that Bob is bringing his girlfriend, Linda - the local librarian who loves books as much as Brick does - to Thanksgiving; and Sue wants to start a mother-daughter tradition of baking a pie for the holiday, but ends up getting more sliced up than the crust.', '2010-11-24', 22, '/d3uaevdcZgFS6Ocm7kDH3XeRsCR.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
