INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BF847F0F83F440CCB03CFA31B8617A21', X'DF77DBA2BBDA4F3897138D5C856F852E', 13, 'The Doll''s House Christmas', 'Old Bear and his friends have decorated the playroom for Christmas. But Little Bear and Bramwell suddenly notice the dolls’ house; forgotten in a dark corner of the playroom, it has no Christmas decorations at all. The two friends have an idea and while Rabbit and Duck entertain the Doll family, the others all work quickly to decorate their house with a tiny Christmas tree and lots of miniature decorations. The dolls have a wonderful surprise when they return and declare it is the best Christmas they have ever had.', '1993-12-21', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
