INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BF92373CA0704A12BED134EEF06A207F', X'1E967562CB824C1AB523A8212971DA9E', 3, 'Celebrating the Arts: A Native American Potter', 'The Neighborhood of Make-Believe sees Chuck Aber and HulaMouse''s finished sand sculpture. Lady Elaine quickly criticizes it and just about everything else. But the sand sculpture inspires Lady Aberlin to dance, and leads Daniel to create a tiny mobile. Daniel suggests why Lady Elaine might be hurting people''s feelings. Rogers does a video insert of his visit to a lady''s pottery.', '2001-09-07', NULL, NULL, '2026-04-03T17:35:49Z', '2026-04-03T17:35:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BF95FDE1300241FF8B503C5BE15D9418', X'F4C403079B5E4263A4E0DFA138131E7F', 88, 'Elmo Loves You', 'Elmo is making a very, very super special surprise card for someone Elmo really loves but a gust of wind blows it away! Rosita joins Elmo to chase after the card but they can''t reach it. Can Super Grover use his heroic skills to save the day? Will Elmo be able to give his surprise card to someone very special? Join Elmo, Rosita and Grover as they learn about love, emotions and friendship in this lovely tale featuring the new song "Elmo Loves You" and a special music video about signing "I Love You."
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BF9A1499D4174FDD9D3EFDFB34CFE61D', X'BCAB920A51A54CBBAA5941578A0EB005', 14, 'Sweet Georgia Jayne', 'Kyle hosts a party at her store where Lisa Vanderpump''s invitations to Hong Kong get out of hand. The ladies gather at Villa Rosa for lunch, where Dorit tries to chip away Erika''s icy personality. After lunch, Erika flies back home to Georgia to see her mother and reconnect with her roots.', '2017-03-07', 43, '/9CGPsWjOeNvSwKcYtb3xkCL1zY4.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BFA195FE226D4D7DBC0FB93B0FCD717C', X'C21DBD225E2E4414BB67750399AAF6F0', 21, 'Air Mail', 'It''s a blast from the past for the Pawn Stars when they check out a huge collection of mini bikes from the 1970''s. Will the guys saddle up and buy the micro machines, or will they hold out for the full-sized counterparts? Then, an early 1900s baseball bat swings into the shop. Will Corey and Chumlee hit a hum-dinger of a deal, or will they let it walk? And later, Rick is presented with a piece of mail flown by Charles Lindbergh on the Spirit of St. Louis. Will he soar to new heights for this historic piece of airmail or will the negotiations stall out and take a nosedive?', '2012-02-06', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BFA7F033366149BDB36884614F9A89F4', X'B5AB3A72BC794E9BA53196739AFD7AEA', 4, 'The Ballet Shoe', 'One dirty old shoe is left for Bagpuss and his friends to repair, and the mice suggest that it might be suitable for living in, which leads Madeleine to sing along with the mouse organ.  Yaffle doesn''t believe anyone could live in a shoe, so the mice trick him by going around and around, and appearing out of the shoe!', '1974-03-05', 15, NULL, '2026-04-03T17:23:58Z', '2026-04-03T17:23:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
