INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BFB642368D0A4198B2AEA8E763821BD0', X'7C542833ED0A42729C53E822408AB434', 26, 'The Big Show', 'It''s time for the finale of the Pontypandy Festival - the Big Pontypandy Talent Show! But when Elvis knocks a drink over the drone control panel, the drones crash land, causing fires in the fields all around the show area.', '2024-11-12', 10, '/xUx3x5JCQD6M8IIRcT5fpcxDLN5.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BFBA59862A254276AA95E324519F3C2B', X'EC8D33228CA24E8D9D22268AEE320274', 8, 'Gold and Silver Horde', 'Rick checks out a horde of coins from Kentucky – but is all that glitters gold? Or will Rick be played for a fool? Then, Chum gets into the spirit when a mentalist brings in a magical clock. Will it be time for a deal, or will Chum get ghosted? Later, Corey isn’t ready to say die to a deal when a seller brings in a poster from “The Goonies” – but will this be treasure, or will Corey be cursed? And finally, Chum tries to drum up a deal on a sparkling snare. Will the seller feel the rhythm, or will Chum have to tap out?', '2025-03-19', 42, '/u35xouZz4cPBPn5cObbwBlUXpjM.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
