INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'BFD9E7ABD8C94EF1AB32D59B6B40CEA3', X'AD4E434833344A088928455D9BA524C1', 5, 'Tony Randall', 'Browsing through an old book of magic spells, Tony accidentally turns Miss Piggy into stone. He considers bringing her to a stonemason for help. Fozzie, Gonzo and Floyd crack stone jokes as Kermit and Tony try to find a spell to change her back. Of course, the show must go on, and the Piggy statue takes the stage for "Pigs in Space".', '1980-11-02', 26, '/8jP8aatkmlXmZaxrwqAhQvZT2Z9.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
