INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C020884165CE48ABB5F18804BD2C8806', X'5A6D9A42165B4B5692730A06874DFE10', 7, 'Madeline and the Forty Thieves', 'At the Old House - and all over the neighborhood - people''s hats, gloves and scarves are missing. Madeline and Pepito work with Detective Moreau to find the perpetrators, then finally discover that the "thieves" are some altruistic magpies who are distributing the warm clothes to the homeless in the park.', '1993-09-12', 30, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
