INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C033458F0A54499FB2A6C39B68E90F4D', X'1996DDD820C94A3096BE2B87FAB8D17C', 1, 'Ghost Story (1)', 'Jamal sees some strange masked creatures in the park and finds a THABTO button where the masked creatures were.  Also, Jamal''s sister, Danitra, goes to college and leaves him her computer. On the first day he gets a weird message asking ""Where are the children, are they OK?"". Lenni Frazier, a school mate of Jamal''s, is also contacted by the strange ghost-like creature.  Who is this mysterious being?  Meanwhile, elementary student Gaby Fernandez gets her backpack stolen on her way to school.', '1992-10-04', NULL, '/6CcslHExwh5TUz0XioEQZnnwSDs.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
