INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C0428DBDA4704C379CED56EEFCB67EE7', X'65F5ABC80C59497B86E58C6165EE480C', 5, 'Rodeo Barbie', 'LeeAnne and Rich settle their marriage woes and vow to start the wedding planning process. Kameron prepares for the Global Pet Expo, despite her children''s disapproval. Brandi plans a rodeo adventure for new bestie.', '2018-09-12', NULL, '/Aafa4BJncVRTbiSkSXkTeQnrmg3.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C048F900DD1143899AB433911CF391E9', X'34674C90410E427CBE4D2A6F6F865A80', 27, 'Fork It Over', 'Take flight with the Pawn Stars as they check out a fork from the wreckage of the Hindenburg. Considered one of history''s greatest disasters, will Rick fork over some cash for this rare item, or will the deal crash and burn? Then, Old Man and Chum are offered a high-caliber Winchester rifle. Nicknamed the "elephant gun" for its ability to take down big game, can the guys separate this piece from the herd, or are they taking a shot in the dark? And later, Rick and the Old Man check out a 1958 Packard Baker. Will the Old Man be able to say no to this combination of a Packard and a Studebaker, or is this one too far gone even for him?', '2012-09-03', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
