INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C05D37737B6B4E0C903253D186C8F09F', X'F15647D3C8BF4E37A6BC589853787F3B', 4, 'Skate Expectations', 'After trying to protect a geeky boy, Philip, from Derrick, Nick finds himself in a skateboarding contest, even though he isn''t that good at it. He practices, but on the day of the race, Derrick''s friends try to sabotage it. However, Nick''s friends notice and even though he loses the race, they disqualify Derrick and so he does end up winning. He learns about cheating, practice, friendship, and standing up for others.', '1989-06-25', 28, '/cZ6Aw7nxzqDuPLk9ngoC0NH0WXF.jpg', '2026-04-03T17:40:08Z', '2026-04-03T17:40:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
