INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C07AF03D5911459087458CACD0B4B34C', X'5C4E51C6E20746AD875C72988EB1E13E', 34, 'Bugs Money', 'The Pawn Stars get revved up when they check out a classic 1941 Indian motorcycle. A rare version made for military use, will this bike kick-start their engines and drive them to make an offer, or will the guys feel they''re being taken for a ride? Then, a woman putters into the shop with a golf club once owned by the King of Cool himself, Dean Martin. Can Rick sink a hole in one on this deal, or will negotiations slice off course and get stuck in the sand? And later, Corey and Chumlee get animated when a seller arrives with a Bugs Bunny poster autographed by the voice of Bugs, Mel Blanc, and the animator Friz Freleng. Will the guys go loony for this cartoony, or will the wylie wabbit evade capture as usual?', '2011-09-19', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C080D305F3A346969639314F434F5A4D', X'98D80972E53A43DDA03A7703465E6F87', 25, 'Room and Hoard', 'Press play with the Pawn Stars as Chumlee checks out a gold video game cartridge from the 1990 Nintendo World Championships. Considered the "holy grail" of video game collectibles, will Chumlee drop enough coins to win it for the shop? Then, Rick and the Old Man eye a set of keys to Al Capone''s jail cell. From Capone''s stretch at Cook County Jail, can the guys nab this artifact, or will it evade capture? And later, the guys discover that the Old Man is a bit of a hoarder, but it''s what he''s hoarding that raises eyebrows.', '2014-02-11', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
