INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C09CA71BECC543588D32C825EA0823A5', X'BC1B58B0F2D64214914B231F27FB4D61', 4, 'Gobblefellas', 'The wives'' Thanksgiving is stuffed with drama, resentment and regret. Divisions mark Turkey Day when Teresa presides over a "friendsgiving" feast for only Jacqueline, Caroline and their families. Conversely, the Gorgas host a separate get-together with the Wakiles.', '2011-06-06', 43, '/9nHsEiTBWO7IS0seOXrVFy16aYj.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C0A1C08CDE7145C280FF988DBF1C290D', X'4C79C0B621A442778967BE1E791EFDBE', 4, 'Pingu and the Litter', 'Pingu passes a stall selling wrapped fish-shaped snack bars. He gets one, and has just started it when Pingg, Pingo and Pingi arrive, and they also each get a snack bar. The stallholder offers more bars, which are put into Pingu’s satchel. Pingu walks on, and tosses away his original wrapper. Pingg, Pingo and Pingi also toss away their wrappers. Pingu eats another bar, and throws away the wrapper as well. The wrapper gets blown into an ice pool and is eaten by Robby, who then coughs it up into Pingu’s face. Pingu gives Robby a bar to eat. The wind is blowing discarded wrappers around, and Grandfather gets one on his foot and trips up. Pingu offers Grandfather a bar, but he refuses. Pingu eats the bar, and is just about to throw the wrapper away when Grandfather says not to. Pingu looks about, and there are dozens of wrappers being blown about. Pingu starts to collect them, putting them in his satchel. The wrappers are getting everywhere, causing all sorts of incidents, but Pingu continues to collect all he can. Father is driving but a wrapper comes flying in the air blinding him and crashed in front of a dustbin. Pingu arrives back at the original stall and Father tells him of for throwing bar wrappers and put it in the bin then pingu takes the wrapper out of the bin and uses the wrappers that he has collected to make a big arrow that points to a litter bin, to encourage everyone to use it rather than to just throw away their litter. The episode ends when Pingi throws a wrapper into the litter bin, and they all laugh.', '2005-01-06', 5, '/ihxl1w8uYIi8mHvylo1aR8ZGKDz.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
