INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C0AE17BDBE504C97B8A5053797613A76', X'1D713CA64E174F84949C8CFD98514127', 8, 'Playboys and Players', 'Join the club with the Pawn Stars when a collection of Playboy Club memorabilia hops into the shop. Will Rick be let in on the iconic collection or will he be left out in the cold? Then, Corey and Chum check out a pair of old Murray bicycles, one of which has never been ridden. Can they get a handle on the deal or will they be taken for a ride? And later, the Old Man decides to take a trip to the shooting range, but Rick thinks he needs some back up. Once they''re stuck in a car together, who will take the first shot?', '2014-07-31', 21, '/dWqjEVgXgmbBMmad5hpbH14gfoR.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
