INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C0EF24B0FB7D4242902E7261557118BF', X'05C0E384194C44179F62803EB615E409', 68, 'Bicycles and dance class', 'Title number 0068. Opens with Mister Rogers arriving with a bag of all different kinds of toy bicycles, and explains the difference between them, tricycles, and unicycles. He sings the "Everybody''s Fancy" song. He also then attends a children''s dance class taught by Miss Nelson and Bruce of Dimension 5 records, and is introduced to Bruce''s "musical computer". Later,  Blackberry the cat comes to visit before accompanying Mr. Rogers back home.', '1968-05-22', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C0EF8E4BE44C42B1A5A4AD667393FEA9', X'42E591E22A884434AE9F3D4B1D685613', 9, 'Sticks and Stones', 'Stand tall with the Pawn Stars when a letter signed by Napoleon Bonaparte marches into the shop. Marked with Napoleon''s official seal, is this a piece de resistance, or another Waterloo? Then, a guy flashes a collection of Las Vegas police badges from the 1940s. Will Rick and Chum bring them in for questioning? And later, a woman springs an antique pogo stick on Corey. Will he tell her to bounce?', '2013-06-27', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C0F8AC779130485A913B543E094440F7', X'A5F4726D4BD648CF96BDA275FA554D9C', 6, 'Episode 6', '', '1989-02-28', 25, NULL, '2026-04-03T17:21:15Z', '2026-04-03T17:21:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C0F943A2893D4AE48CBC705EB397DBC0', X'9193E795DA7C40ECB68FF63AA7D5174F', 77, 'Histories & Lore: House Targaryen', 'Viserys Targaryen recounts the conquest of House Targaryen and its ruling of the Seven Kingdoms before being brought down by the treacherous Usurper Robert Baratheon.', '2012-03-05', 3, '/uar0gEock4e8XtzbESI9KVxR6ke.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C0FD2050274846C98CBD8AE3950DEEE5', X'941B8C6544544336BE7C1D0591C12F90', 2, 'Pingu Finishes the Job', 'Mother and Pinga go out to the shops, and Father and Pingu go into the shed to repair a leg on a broken table. When Father rummages in his toolbox Pingu does as well, so Father moves him out of the way. While Father repairs the table, Pingu sidles back to the toolbox and starts rummaging in it again. Father spots what Pingu’s doing, removes him from the toolbox and plonks him in a chair. Father then pops out to get some paint, leaving Pingu alone in the shed. Pingu can’t resist the lure of the toolbox and has a good rummage, then puts it on the newly repaired table. The table collapses under the weight. Pingu tries to repair the damage but only succeeds in sticking his hand to the tabletop, and then trashing the shed in getting it free. Grandfather comes in and collects the legs of the table together, and Pingu gets the top but gets his hand stuck again. As they’re recovering from freeing Pingu’s hand, Father arrives back. Pingu and Grandfather tidy up, and Father starts putting the legs back on the table. When he’s finished he stands the table upright but it wobbles, as one of the legs has been broken and is now shorter than the others. The three of them then try to fix the problem by sawing pieces off the legs, and end up with a table with very short legs! Pingu and Grandfather paint it, cover it with a cloth and go back into the igloo to await the return of Mother and Pinga. When they arrive the table is unveiled, and Mother is not amused. Pingu has an idea; he sits Mother down on the sofa, pulls over the table and puts a cushion on top, and invites Mother to use it as a footstool. She puts her feet up on it and relaxes.', '2003-08-08', 5, '/sirahYblyO9sAaiheoOc5NcBpVi.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C0FFC0784045494D9224B3C0D7B4A6AA', X'4D2CAC0F38FD438B8AFAACF43952E535', 133, 'Episode 133', 'For younger viewers. Introduced by Christopher Trace and Leila Williams. Young Modellers'' League, first of a new series on trains, aeroplanes, and ships. The Girl Who Liked Animals by Pamela Young (aged 7), a prize-winning entry from our competition. Dressing Up: 1: The Nurse', '1961-05-01', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
