INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C11F71118EF7454CAC2AF91BA336BD94', X'9D74600D722247C1BD1B635F5B41B7D1', 3, 'Feelings', 'Pictures, dialogues, poems, and stories portray a variety of emotions we all feel - jealousy, sadness, fear, anger, joy, love, etc. Also includes Let''s Make Music, Feeling Sad, Meet Koko and Penny and book reviews for Honey, I Love and Other Love Poems, Fireflies! and Loudmouth George and the Sixth-Grade Bully.', '1986-06-25', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
