INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C12697B1139C47D4943F8B2AF6C7C138', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 88, 'The Martians cause trouble for Big Bird', 'A spaceship lands on Sesame Street and pink and orange Martians emerge, exploring the Fix-It Shop where they mistake Maria''s computer for something to break. They also destroy a clock that Maria blames on Big Bird, angering him. The Martians hide in Big Bird''s nest to hatch an egg, while Big Bird gets blamed and Bob discovers mismatched socks, Oscar leaves Irvine with Micki and Piri for babysitting.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C129850B6CCD4DA2B3C97BC0B5426887', X'136B81D3964D4B8FA21492F00D96D6B9', 72, 'Episode 1907', 'The residents of Sesame Street gather to discuss the true meaning of friendship and share heartfelt stories about trust and kindness. Big Bird reflects on his special bond with Snuffleupagus and how much their friendship means to him. The gang celebrates their connections with an uplifting song about caring for one another.
