INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C1727EAE5C1D4EDA819BDFFF46D46A1D', X'C9D2B3FB78454F3C9847CE1F7717257A', 11, 'He Shoots, He Pawns', 'Rick plays ball with Kareem Abdul-Jabbar on a bucket load of his most prized personal memorabilia; Chumlee goes for bronze with a bust of Michelangelo''s famous Pietá; Rick receives some correspondence from Gen. George Armstrong Custer.', '2019-06-03', 42, NULL, '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C179681BCEF74A56AC0E5A85DCC6B509', X'0442FB97146049238558B994078DC6B8', 19, 'Deck the Halls With Drama', 'Robyn and Juan seek couples therapy to move forward in their relationship. Gizelle works hard to make sure Robyn’s engagement goes off without a hitch, but Michael''s skepticism causes her to panic. Candiace confronts Karen about setting her up, while Michael Darby and Chris Bassett square off, leaving Michael unhinged.', '2020-12-06', 42, '/fwhFhpizq87H5kg0qy15yDx5GXO.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C179B04349DE4E109DACF43D926C1D32', X'3AF7EA64FA134097B8E440AF07083054', 59, 'Episode 59', 'Rogers shows all the puppets he uses in the Neighborhood segments. He and Bob Trow (the man behind Harriet Elizabeth Cow) demonstrate the washer-dryer-sorter-dumper. In the Neighborhood of Make-Believe, Lady Elaine overcomes her disappointment of the day before by starting a television station, called MGR-TV.', '1974-05-09', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C184E1E73D3A4EF7B02FAB121845CF78', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 8, 'Music Magic', 'Elmo makes everyone on Sesame Street sing---with a wave of Abby''s magic wand.', '2010-10-08', 60, NULL, '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C192C66494FA4BD4B3C323435A7ADC5E', X'C9ADC698BE924DD794ADD8F6759361CA', 51, 'Episode 51', 'Rogers welcomes back the McFeelys. They share photographs of their grandchildren. In the Neighborhood of Make-Believe, Lady Elaine shows her impatience for Mr. McFeely''s return.', '1973-04-30', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C195EA383C394D05B69DCF1FF7FA9270', X'42E591E22A884434AE9F3D4B1D685613', 41, 'Woah Pilgrim', 'Put up your dukes with the Pawn Stars when the guys are offered the hat John Wayne wore in "The Man Who Shot Liberty Valance." Will they negotiate with guns blazing, or send the seller riding off into the sunset? Then, Chumlee puts on his best poker face when he checks out a card playing book from 1866. Is the deck stacked in Chumlee''s favor, or is he drawing dead? And later, when Corey brings his dog to the shop for the day, the guys try to put her to work.', '2013-12-12', 21, '/3hfk1GfhcpKjUbIAmvrhgI8vyHY.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
