INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C19D9764DBEF4488891C894B1AB31C24', X'A9657E86413549CEB1F9C295113077E1', 29, 'Episode 29', '', NULL, 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C1A4CC631FBD4B9BAEA654EA2D9987DF', X'70C8CB4624944DD498F66BFB9B3FAF73', 11, 'Fortune in Flames', 'Rick has a chance to buy a little piece of militaria he''s never had before - a Flame Thrower. Can he turn up the heat and coax a deal or will this deal go up in flames? Corey and Chumlee head to an auction to bid on a classic gypsy fortune-teller machine. Can they foresee the future to place the winning bid, or will they wish they went out for fortune cookies instead? Then later the Pawn Stars have the opportunity to buy a rare Manhattan Arms revolver from the mid 1800''s. Will the gang be able to load and fire this antique handgun, or will it jam up and misfire the deal?', '2010-03-01', 21, '/hEnxX35XiS0NdDoAjR3qdeiy8ZE.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
