INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C1A7A8F67BE1490FA60BA89784AFEB2A', X'6F81C872CDB942DD83772C17CB6ED4D7', 1, 'The Kindness Kid', 'The Kindness Kid (Zachary Levi) visits Sesame Street to spread kindness and Grover wants to be a Kindness Kid too, but every time he tries to do something kind, he fails. Chris helps Grover realize that just trying to help someone is actually being kind.', '2017-01-07', NULL, '/9RyTOl72tmJNoCKVhTBSJG2Hnbb.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
