INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C1DDFC1A0D5845118581D8DF39F3B457', X'F593D90C533942F59C885BFD48D04075', 1, 'Double Trouble', 'When Shaun dresses as the farmer he suddenly has the power to boss Bitzer around, so he decides to throw a party. All goes to plan until Shaun encounters the real farmer...', '2009-10-18', NULL, '/fptr5foTrKy14wp7L0JHiymlOWK.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C1E0811A70D6418BAB0F3B72026C19F6', X'1D713CA64E174F84949C8CFD98514127', 26, 'Secret Admirer', 'Open wide with the Pawn Stars when an early 1900s Peerless Harvard dental chair rolls into the shop. Can Corey drill into the negotiation or will it be like pulling teeth? Then, Rick gets ready to party on when memorabilia from the 1990s movie "Wayne''s World" is brought in. Will Rick think he''s not worthy or will the items make him say no way? And later, Rick is surprised when he starts receiving letters from a secret admirer. Will the letters strike the right note or will Rick be sending them straight Return To Sender?', '2014-10-23', 21, '/eUdRAr3JoQo2vHsCpwKBsPouR4c.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C1E331B06CC54D0E85B2FCBF47F8C1F7', X'1996DDD820C94A3096BE2B87FAB8D17C', 27, 'Over a Barrel (1)', 'The team is having fun in the community garden, but when Gaby faints the team starts getting suspicious. Even more strange things start happening when the pet rabbits die. The team learns that each victim has been in the garden before they got sick. They go straight to the source where they find barrels filled with toxic waste.', '1993-04-11', NULL, '/7yM0HTcf3PtcGh6SGhzfatfei5q.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
