INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C205F7589D1C475C88891312189FF6C1', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 89, 'Gordon agrees to visit Snuffy''s cave', 'Buster the Horse greets Gladys the Cow as his sister, but Gladys protests with a song about how they''re different while horses sing about similarities. Maria finds Gladys practicing her role as a cat for a stage production of "Cat on a Hot Tin Roof." Big Bird asks Gordon and Olivia to write permission for a sleepover at Snuffy''s cave, and Gordon helps Big Bird pack, confused to find his own name on the list.
