INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C2340D3F60F44B14A975B22B40860015', X'831E3A6BC1A748B7A5ACB18ED67BEB10', 2, 'Divas, Queens and Bubalas', 'Gizelle’s reputation is called into question by Potomac''s queen bee, Karen, and its self-appointed social director, Charrisse. Will they be able to play nice, or are these domestic divas going to take off their white gloves and get dirty? Katie has to tap into her Jewish roots to prove herself a true member of the tribe for her twins'' naming ceremony. Things get a little dicey when the ladies meet the young, boisterous beauty queen Ashley Darby. Will Ashley be able to break into this coveted circle of sophisticated women?', '2016-01-24', 42, '/eA4amxKOHb2Nxxw8tPlv7n4px8a.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
