INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C23FDF78023D438898929166A0B8C81C', X'DBD3583FE9B246D1A37E309EB666E233', 21, 'Reunion (1)', 'Hosted by Bravo''s Andy Cohen, the ladies of Hotlanta, Cynthia Bailey, Kandi Burruss, NeNe Leakes, Phaedra Parks, Sheree Whitfield, Kim Zolciak get together to set the record straight on some of the most talked-about antics of the season and answer some of America''s most burning questions.', '2012-04-15', 43, '/gqfHdDo07fLhPeUPRxpRsBKuFNb.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
