INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C25B1555554A42DF9160FBC35A921EE9', X'05FA5E1878D241FEAE300C242C7FFB6A', 22, 'Birthday Surprise', 'It is Sam''s birthday and everyone is keen to surprise him. Norman is tasked with keeping Sam out of the gym, but a fire at Bella''s café distracts Sam.', '2003-04-29', 10, '/6kedYztlhL3vdnrUMwjv8Ohjpbw.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
