INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C2667968062F414082AB2A4C4D1B5FC7', X'5A771F52FE964EA2B567A8DDE899059E', 10, 'Pawnie and Clyde', 'A set of illustrations from Disney''s "Sleeping Beauty" prompt Chum to make a sketchy deal that draws lots of attention. Flashy door handles from one of Las Vegas'' first casinos has Rick feeling like he won the jackpot. Handwritten memoirs from a member of Bonnie & Clyde''s gang are so unique it''s criminal. Are they a steal, or is this seller committing highway robbery? An original version of The Game of Life leaves Rick and Corey anything but board. Rick hits the mother lode when a device used for gold mining strikes up an interesting prospect, but this pan might be too much for him to handle.', '2017-11-13', 21, '/S4F9Cdvyra5J1yKjVOY3pAL2iH.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
