INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C274C49B28784688959DFFD19527F786', X'EA1650C2E4F146C793BA74B5D45D08E5', 10, 'Auto-Tuned-Up', 'It''s time for Kim to face her fears and work with the vocal coach who once told her that she didn''t know what she was doing. Meanwhile, Sheree is ready to take her newfound passion for acting to the next level by auditioning for a talent agency and considering a role in a local play. While Phaedra and Apollo bask in the joys of new parenthood, Cynthia is caught in an uncomfortable position when Peter confronts NeNe about taking all of Cynthia''s attention away from him. It all comes to a head at the "Fast Life Drag Race" when Kim thinks that the other ladies are getting too close for comfort with her girlfriend Tracy and NeNe does not appreciate the cold shoulder she gets from Peter.', '2010-12-05', 43, '/9au0PUElBYh9wPhFGFWACKPg38Z.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
