INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C2A295A108374E0581ACA996D4E5FA25', X'9193E795DA7C40ECB68FF63AA7D5174F', 16, 'The Game Revealed: Season 6 Episode 1 & 2', 'The Game Revealed: Season 6 Episode 1 & 2', '2016-08-01', 60, '/lVFVxh3iayEd7mAtLwo94j34zeC.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C2A7C4378B1C4AAA9FA3740B81A84193', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 4, 'The Ironing Monster', 'Leela and Elmo are sorting laundry in the Laundromat when Grover stops by to have his Super Grover cape cleaned. Grover realizes that people all over the Laundromat need his help. Bert has soggy socks, Gina is out of fabric softener, and Cookie Monster has a stain. Without his cape, a new superhero must be born! Grover returns as Iron Monster, complete with a metal suit! Chris shows up asking Leela to break his dollar so he can do his laundry. Iron Monster misunderstands and wrestles with the dollar to “break” it. Leela comes back and explains that Chris just needs quarters&ndas; four quarters for each dollar. Gabi comes to the Laundromat with two mustard stains on her sweatshirt. Iron Monster tries to get rid of the stains by subtracting them, but adds five more stains instead! Leela shows Iron Monster how to subtract all of the stains with a stain remover as Elmo counts along. Finally, Iron Monster tries to solve Maria’s problem by using static cling to find Maria’s missing sock. After laundry goes flying everywhere, Leela suggests they check the missing sock box. They sort through different patterns and find the lost red and white striped sock. Finally, Grover’s cape is ready. Before he flies off for his next adventure, Grover points out that Iron Monster is not needed anymore because the Laundromat already has a fantastic superhero, Leela!', '2010-09-30', NULL, '/9fk8kxUvpRMnNg9KnzJWo86e65H.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C2AD5A1D0CC24D74A3F6DD50873CC385', X'8BAE6AA34B554FA6BC158F4317BD1F13', 7, 'Episode 7', 'Rogers'' son Jamie and a friend play with a toy on the floor of the television house. In the Neighborhood of Make-Believe, Robert Troll starts a game of catch, but doesn''t want to throw because he thinks no one will throw back.', '1972-02-29', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
