INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C2BF7EB3BA5149F89D8773BB8C7B4F5A', X'5DB3FF78E43948E18F67988ECBF85D17', 1, 'Dogtanian''s Journey', 'Dogtanian is fighting his rival François LaVache, son of the Mayor, with wooden swords and beats him easily. A Musketeer from Paris watches on his way to meet the noblest man in Béarn and congratulates Dogtanian on his victory. François rushes home assuming he''s there to meet his father, but Dogtanian sees the Musketeer arrive at his house. We find out that Dogtanian''s father is friends with Monsieur de Treville, Captain of the Musketeers...', '1981-10-09', 24, '/8abTqsVbxKq3nW0cNpjjhCyLwt3.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
