INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C2DD50EA85074063A43A794448F1420B', X'1CFDFF3AD5314A9EAFC98010A979DD27', 6, 'The Voyage of the Dawn Treader (4)', 'The world''s end and the final enchantment draw near.', '1989-12-24', 30, '/zV3LvtIsVUBdwJVnRGKWHhPbSAr.jpg', '2026-04-03T17:17:41Z', '2026-04-03T17:17:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C2DE62E2E3254D059AA1C27852D48E69', X'3982796B54514100904246BEDF6A20A5', 15, 'Pingu''s Birthday', 'It’s Pingu’s birthday, and he’s having a party with Pinga and his friends Pingo and Pingi. The party area is decorated with balloons and lights, and there are snacks and drinks on the table. Grandfather is providing music on the accordion. Robby arrives with a present for Pingu. It’s a cap, which he promptly puts on. Pingu shows the others what he’s received; a book, some crayons and a ball. They then all tuck in to the snacks and drink. Pingu shares a drink and a snack biscuit with Pingi (which leads into a Lady and the Tramp-style kiss). Pingi then pulls Pingu’s cap over his eyes so he can’t see and tells him he has to find her. He goes where he thinks she is, but she steps out of the way. She calls, and he changes direction towards her, but she steps out of the way again. Robby calls, and Pingu tries to catch him, but Robby backs away. The others all join in, calling in turn, and Pingu doesn’t know whom to find. Eventually he looks for Pingi again, but she moves out of the way and he collides with Mother, who has just come out of the igloo. She takes his hat off so he can see whom he’s found, then puts it back on. The game continues, Pingu not managing to find anyone. Mother then comes out with the cake and they all gather round. Pingu, now feeling much better, blows out the candle, the others sing “Happy Birthday” (in Penguinese) to Pingu, and then they all dig into the cake.', '1993-07-06', 5, '/49sdYHfKiP9gXpN5QuFAa7QDJUn.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C2F21171FF294C03A26D8D03C62777F2', X'7EEF937C448342BDBAFE263A7D4E4573', 4, 'Under Construction', 'Two inches tall and trapped in a bathroom at Wanda’s house, the kids must use what they’ve learned about structures to escape before Wanda’s mother discovers them.', '1996-10-05', 25, '/zE2SOfuQeyQKNAkhfRari0pi0t9.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
