INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C2F8DE00F33C4381811C827EC2A41BB1', X'4B2A19E02FAE492EBC31F78E63D88EBC', 29, 'Under Pressure', 'Shine on with the Pawn Stars when a drawing by John Lennon scribbles into the shop. Will Rick give this piece a chance or will he fail to imagine an offer? Next, Senator William Sharon''s engraved menu from the Comstock Lode mines in. Will Rick see the silver lining or will the deal get tarnished? Then, a Rolex water pressure tester ticks in. Will Corey make time for an offer or will it get water damaged? And later, a 1950s Buddy Lee doll struts in. Will Rick zip up a deal or will he think it’s child''s play?', '2017-02-06', 21, '/sXdgMZ4ieqS1C5Yip2Kso3YBUMc.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
