INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C2FDD3243A954007BCEDEBF4E5062656', X'0D24C74283F24F378A5D0B09C7DF6A7F', 1, 'What Doesn''t Kill You Makes You Stronger', 'Geralt sets out to save Ciri from the claws of Emhyr, unaware of her true fate. Beset by Vilgefortz, Yennefer attempts to uncover his plan.', '2025-10-30', 59, '/ihhPrHJhamp5iGu6LACWMzTT94r.jpg', '2026-04-03T15:40:46Z', '2026-04-03T15:40:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
