INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C31FA7C072794325B9F8F49E58908F0F', X'1A534647384B4C00BB6CA3371AD962EB', 16, 'One Man''s Junk', 'Step up to the plate with the Pawn Stars when a baseball believed to be signed by the 1959 World Series Champions, the Dodgers, gets thrown into the shop. Will Corey be able to hit it out of the park or will he strike out? Then, Rick gets his big break when he is presented with a rare Berndt-Maurer 1930s movie camera. Will he yell "Action" on the deal or will it be a bad take? And later, the Old Man vows retribution after Rick bans all junk food from the shop. Will revenge be sweet for the Old Man or will the plan go sour?', '2015-03-12', 21, '/cBGNdENFwqfstLhMjoElLD4LPcU.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
