INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C32C5174A8084FB5B5BA79E0542C53CB', X'E40E6B639F84449F8E8853209B0906C8', 6, 'The Tutu Spell', 'Abby and Zoe are playing in the courtyard. They love dancing so much, so Zoe lets Abby try on her tutu. To return the favor, Abby lets Zoe try out her wand. As she''s figuring it out, she inadvertently wishes that everyone would wear a tutu and wear ballet.', '2007-08-21', NULL, '/oG34xqMAJdZWFISRvCyJKGHBSJD.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
