INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C4C0155D54BC410A9E1BC58573513274', X'C01DDD2ABDB14C978D0458F791EF1C24', 20, 'Animal Daycare', 'Today, Animal Junction is full of baby creatures! A baby ring tailed lemur, lynx kittens, bobcat kittens, a sliver fox kit, and baby coatis all need to be taken care of. Chris and Martin build a creature playpen to keep them all in.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C4C19135C90E41AC89F0C326DAF55119', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 67, 'Introducing Leo the Party Monster', 'Luis and Maria go about their business at the Fix-It Shop when they hear a loud tune blaring. In comes Leo the Party Monster, a monster who loves partying more than anything. Leo shows up again, asking to use the Fix-It Shop''s computer to write out some invitations for a party at Bob''s apartment. He promises Luis he won''t do any partying while he works.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C4C3DF62E5A44D3981923421BB27BF22', X'A8FACD21E7864FFFB89F7EB83EBA2231', 6, 'Episode 545', '', NULL, NULL, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C4C4694769CB44E7A6FE4E997A16DCB6', X'3FC7C152E4F6426AA89936EC454C4403', 22, 'Four Little Pigs', 'The kids and dragons want to do a "Three Little Pigs" puppet show, but Zak, Wheezie, and Emmy argue over wanting to be the Big Bad Wolf at the same time, until Emmy decides to add a fourth pig to the story while she lets Zak and Wheezie play the wolf.', '1999-10-04', 30, '/deQD6fZ0KXJD3kkvZnvxXGsUzWh.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C4C745D6D51B46568AAD0F01D49D8680', X'E3A2866991B545F7BB735006ACC084E8', 5, 'Scrumping', 'Those pesky pigs have taken all the apples, and wont let the sheep have one - they didn''t count on Shaun!', '2007-03-07', 7, '/qaEjuKu5gXaCgaKV6mF8QMl1TWl.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C4D1FED39DEC45A29BF3373308050458', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 1, 'Pawns Ahoy!', 'Sail away with the Pawn Stars as a peg leg pistol hobbles its way into the shop. Will Rick and Corey say, "ahoy" or will they toss it overboard if it doesn''t fire? Then Corey and Chum check out four yearbooks signed by the ultimate teenager, James Dean. Will Corey be a rebel without a cause and turn down the offer or will he be a cool kid and make a sale?', '2017-04-10', 21, '/chNvqJKXlwEm7AwaCXd8TSf2Y9Z.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
