INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C4DB4B680D774A0DBDCF94413B281856', X'23C93536610C41C5AC6BA6B243423258', 18, 'Reunion (1)', 'The season nine reunion begins with a surprise as the ladies learn that the Grande Dame will not be in attendance, but not completely absent either. Wendy expresses her disappointment with Karen''s lack of accountability this season. Ashley, Mia and Stacey reveal the statuses of their divorces. Jassi and Stacey confront Mia about her shocking behavior during her off-camera birthday in Miami.', '2025-02-16', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
