INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C4F17FC4AF894CFC9CF8C7DB5AD095E9', X'DBD3583FE9B246D1A37E309EB666E233', 11, 'Shaping Up and Shipping Out', 'Kim tries another get-skinny-quick trick as Kandi suffers through a boot camp workout to shed pounds before her trip to Africa. Phaedra fills Apollo in on socialite Marlo’s criminal history and decides to keep her distance from now on. Meanwhile, NeNe hatches a secret plan to bring Marlo along on the ladies’ 10-day journey to South Africa. While the other women prepare for their vacation, Kim is forced to prepare for life without Kroy when the NFL lockout comes to a sudden end.', '2012-01-22', 43, '/kEqjsvpYQa5I29rrtmAUaqsN1ay.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C4F402256DC348ECBFD80151CAD0DD9B', X'42E591E22A884434AE9F3D4B1D685613', 6, 'Dog Day Afternoon', 'It''s dog eat dog for the Pawn Stars when Corey''s pet pooch spends a day at the shop. Is it man''s best friend, or the Old Man''s worst nightmare? Then, a guy brings in a cavalry sword used by John Wayne in the movie Rio Grande. Will it take a "grande" cut out of their bankroll? And later, a Civil War medical syringe jabs into the shop. Will Rick and Chumlee plunge into this deal, or do needles make them squeamish?', '2013-06-13', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
