INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C51DD03205CA4DF8B6A400AC63D82FAF', X'831E3A6BC1A748B7A5ACB18ED67BEB10', 11, 'Reunion (1)', 'Fevers spike as Gizelle, Katie, Ashley, and Robyn try to pull Karen off her podium as the Grande Dame of Potomac. Ashley defends her hostessing, her husband and her humping despite the slings and arrows of shade-rageousness. Robyn makes a surprising admission about her feelings for her ex-husband. And questions about the sensitive topic of race spark a high-octane feud.', '2016-04-10', 42, '/zt05b0CTebeM6JKvalMUZj4mEIj.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
