INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C53975FD28D341B6AA74B840420F22F2', X'EBC99729CCB74D6482C142708CD7BA85', 30, 'Episode 30', 'This time next week, Christmas Day will be nearly over. If your cards are arriving thick and fast and there''s nowhere left to put them, you might like to make a Christmas card hanger that doubles up as a very attractive last-minute decoration.', '1980-12-18', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C541AD3EB80044A4979470A8D7E87820', X'52A4705898E04CCBABA0B1481FBC2A96', 2, 'Black Ball''d', 'It''s party central between a ladies'' luncheon (with transportation issues) and an all-star gala (with an interloper). See the shots from the shindigs here.', '2011-03-01', 44, '/ajbA34JYt68NWHrXNSDBQtPeHFN.jpg', '2026-04-03T16:35:10Z', '2026-04-03T16:35:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C54A20C5410E4DEAA89F51A96F485C84', X'941B8C6544544336BE7C1D0591C12F90', 15, 'Pingu and the Knitting Machine', 'Mother arrives home with a big package. Pingu wants to know what’s in it, so is close by when Mother reveals the contents – a knitting machine. The machine knits what Pingu thinks is a hat, and he puts it on, but Mother shows him that it’s not a hat but a tea cosy. Mother and Pingu go outside, and Mother puts a sign outside the door indicating that she’s ready to knit things. Grandfather comes by and Pingu tells him all about the new machine. He goes inside just as Robby turns up. When Grandfather comes out he has a new pair of knitted mittens and a scarf. He gives the scarf to Robby and they both go off. Pingu goes back inside. Mother is busy knitting. Pingu goes up to the machine and starts fiddling with one of the balls of wool. Mother tells him to leave it alone and to go and play. He goes away, but sidles back and has another play with the wool. Mother again tells him to stop. Mother then loads up her basket with things she’s knitted and goes out, and Pingu grabs the chance to have a go on the machine. He sits up to the machine, changes the balls of wool for different colours and sets the machine going. Pinga arrives as the machine starts to knit a scarf, which gets longer and longer. Pinga feeds in new balls of wool and the scarf gets even longer. Pingu tries to stop the machine, but it goes even faster and he and Pinga end up wrapped tightly in a roll of the scarf. Mother comes back, and is surprised at what she finds. Then Father comes in, unrolls Pingu and Pinga, and Mother tells them off. They tidy up the long scarf and then Pingu has an idea, so the machine is used to make a hat for each of the four of them using the wool from the scarf.', '2004-01-22', 5, '/hvQ4AYsjVSJgzb9HZjrxPGzh1RO.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C553D7472E6E48FEB211A412104218FC', X'FC120008C5C447D7A3A991A401394C41', 26, 'The Giddy Grandma', '', '2003-02-16', NULL, NULL, '2026-04-03T17:40:21Z', '2026-04-03T17:40:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
