INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C5795ADEA601467EA584FBFA597CFA2F', X'5144DE59E67F4FCF919B7106989AB797', 34, 'Just Kidding', 'The others tease Skye when he forgets to bring a bat to a baseball game, prompting Skye to get upset and leave. Ben feels badly their teasing, even though they were just joking. Sizzle and Nuzzle climb up a tree in the greenhouse but are too scared to come down. Leon and Kiki only make cameo appearances.', '1995-03-02', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
