INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C5871DF94ECD437680B78BFC564121BF', X'05C0E384194C44179F62803EB615E409', 73, 'Rainbow cookies', 'Title number 0073. Opens with Mister Rogers arriving with two boxes which contain a ring and a hat. Mr Rogers sings "Let''s Go Right Away". Lady Elaine is derided for throwing litter around as a protest. What she really has wanted is one of Chef Brockett''s cookies.', '1968-05-29', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
