INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C58E684E6703461C86F82281F822B41F', X'227B84290DFD47E4B874C37DA20C403F', 6, 'Damn Yankees', 'The Old Man hopes to hit a home run when a baseball autographed by the 1951 World Series Champion New York Yankees comes into the shop but he''ll need to verify its authenticity before he steps up to the plate. Then, Rick checks out a 25-piece Knights of the Round Table set but with all the kings'' men accounted for, is it really worth its weight in gold? Finally, the Pawn Stars have a chance to buy a West Point Cadet jacket owned by a famous general in 1909 - will they try it on for size, or send it to the Salvation Army?', '2009-08-02', 21, '/6ytwfWTtm4MTf6luPmKtvpv4wPc.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C590B6C813E94A7FB5F638D234342231', X'3430D88114A2497D9CF4351B78B6AA6A', 9, 'Postman Pat and the Big Surprise', 'Pat does some gardening before work. When he tries to remove a weed, he sprains his back and Sarah calls Dr Gilbertson in. Pat needs a day in bed so Sarah offers to take the post instead. Everyone is surprised to see Sarah delivering the post instead of Pat. Sarah has also forgotten something.', '1997-05-29', 15, '/34wcgLzXfS3esfsMbx58E7w1BA4.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C590C73DCF034D56ADF9E70F8AA6B013', X'53F9624FFCF84F7782F6D2EB3F5376EE', 28, 'One on One (3)', 'In part three of this One-on-One interview special, Meri discusses her distrust over Coyote Pass.', '2025-06-08', NULL, '/i3I46TN3M6HKRQKiWEaSXP11Typ.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
