INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C5AED4B3909841EA94F348E15BF54E6E', X'CA09391ADE6A4B2BAEFCC2EFBC80A106', 6, 'Opt: An Illusionary Tale', 'In this episode, all is not what it seems as LeVar demonstrates optical illusions from the book by Arline and Joseph Baum. He also shows how special effects are created for television; meets artist Christian Thee, who paints trompe l''oeil, or "trick-the-eye," paintings; and shows clips of kids creating their own optical illusions as well as camouflage tricks that animals use to deceive predators.', '1991-09-23', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
