INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C5D2DD60104B4C59978261E44921017D', X'D0B78F22678E4E469D61AAC40BA206B8', 12, 'The Ultimate Ultimatum', 'After weeks of not speaking, Lisa Vanderpump finally sits down with Dorit to hash out their issues. Unresolved tension between Kyle and Dorit comes to a head at Teddi''s dinner party. Meanwhile, Erika and Lisa Rinna endure a challenging workout, while Denise gets her first taste of Camille''s insincere ways.', '2019-04-30', 43, '/nsrnFOxV9DqgojSvKIgauXurYM3.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C5D6E773989846ED99951053E27A3566', X'D034C38DC0C742B48876394B63D84275', 9, 'Whine Pairings', 'Peggy and Micah throwing their annual dinner party and hire celebrity chefs, Susan Feniger and Mary Sue Miliken of Border Grill, to cater the event. Tamra’s new boyfriend, Eddie, meets the ladies for the first time. During the party, Alexis causes a scene and flees the table, leaving Peggy livid and Donn is shocked by Vicki’s comment to the group about wishing they had started their own family together. Mary Sue Miliken of Border Grill is a contestant on Top Chef Masters 3.', '2011-05-01', 44, '/jSw2BJZZA8NwfjCbqkQRpm8Iwte.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
