INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C5F0A70A8E5544C3A7B80BB4FD78388A', X'97616D6E5C17449FA37655F1DA83D6C3', 2, 'Mister Rogers Talks About DISCIPLINE', 'Mister Rogers arrives with a piano roll for a player piano. He explains how a piano roll works and talks briefly about how he had to practice regularly to learn to play the piano. At Negri''s Music Shop, Joe Negri helps Mister Rogers to demonstrate a player piano before they look inside to see how it works. Before Mister Rogers leaves, Mr. Negri shows a short film about how piano rolls are made.', '1982-03-01', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C5F14F233973491D8D05B033CE0AEAA0', X'4D2CAC0F38FD438B8AFAACF43952E535', 265, 'Episode 265', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1964-01-27', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C5F8508A4BA143149A7A03CCB1515FE9', X'3EE646E823AE4DECBBC6C7E6A210D55B', 72, 'Remembering times of sadness', 'Susan tells the viewer that today, everyone will be discussing times when they felt sad. Prairie Dawn is the first to go, describing the day she got sick on the premiere of her new pageant, "The Life of a Potato.". A flashback shows Susan tending to a bed-ridden Prairie.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C5FBA63315034CB4ACA304762296389A', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 25, 'Grouch Mother''s Day', 'Oscar tries to give his mom the worst Grouchy Mother''s Day ever, but he has keen competition from his sister Bunny. Also: the "Word on the Street" features Rachel Griffiths ("Brothers & Sisters") discussing the word "dozen" with Elmo.', '2010-12-30', NULL, '/ntm2GNk51ktqsxxmPXHPe50BnV1.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
