INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C5FCFC51B35A4C2E9B190B0431DBA992', X'3415030FF54D42B9A290AAA05E246D86', 7, 'Guide to Wedded Bliss', 'Relive special moments from three Brown family weddings. Robyn and Kody get married as the other wives help celebrate. The entire family takes part in a commitment ceremony. Plus, Kody and Janelle''s daughter Maddie says "I do", at the wedding altar.', '2016-12-25', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C5FDF0D314874348B5EB3F44FEE5C9C8', X'B1D55597D9D24EEEAB9546DBB163291A', 7, 'Pingu and the Snowball fight', 'Robby the seal jokingly attacks Pingu with snowballs. Pingu is enticed immediately to join an acrobatic game in which a large pink fish is the object of their japery. Pingu, in a bizarre moment of claustrophobic inertia, finds the fish''s mouth trapped over his head and Robby, briefly abandoning his joking around, aids his relatively new friend by removing the fish from Pingu''s head. They then play a tennis-style game using the fish. However, the fish is eventually caught on the rope and, after a futile attempt to retrieve the fish, Pingu retrieves it using a pair of ice-stilts placed conveniently by his igloo. Robby strips the fish of its skin and flesh and divides fish in totally equal parts.', '1987-10-15', 5, '/ahxt0jqjTiXMJj0n1djZ8nHMIg8.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C5FE02E3D9484BB5ABE3898A60699C69', X'79C64E0A348841BC9B5C2243FF15B373', 16, 'The Last Supper', 'The ladies’ Italian adventure comes to a dramatic end with an explosive final dinner that leaves longstanding friendships fractured. Back in Beverly Hills, Dorit poses for her book cover. Boz looks for a new house with Keely. Rachel hopes the fallout from Tuscany doesn’t ruin the disco vibes at her birthday bash.', '2026-04-02', NULL, NULL, '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C600AAF314164EF0AD16CC4EBBA4870B', X'84A2412422904B86AA885514DA7BD0B6', 8, 'Going Away and Coming Back', 'Rogers gets a feel for shooting a basketball from a chair. This segues eventually to his visit with a wheelchair basketball team called the Steelwheelers. More residents in the Neighborhood of Make-Believe join in Stephen''s search for a hidden tunnel. One clue comes from a scrap of paper.', '1994-04-12', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
