INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C60F7A6548844C81B20DA15DAC94025B', X'F4D370CA3C3940A8911DE2B5E7C6B0D7', 12, 'The Birthday Camp', 'It is Little Bear’s birthday and the toys have given him a tent. He is so excited that he wants to sleep in it that night. Old Bear isn’t so sure but Rabbit volunteers to look after him, so they all go out in the garden to put up the tent. As it gets dark Little Bear and Rabbit discover that they are still rather hungry but they have forgotten to bring a torch to find the food. However a night-time visitor comes to their rescue and the birthday goes on getting better long into the night.', '1996-11-20', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
