INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C62EF2D4DCC14120B54070813FB1BC74', X'3B5C322F56504381948F712C5AA2D0A5', 4, 'Someplace Else', 'LeVar shows us his travel room, a place very dear to him. His travel room has many maps and globes of places that he''s visited. While we all love our own homes, we often imagine what it would be like to live somplace else. In this episode, we see what life is like in New York city, on the high seas, and in Hawaii. Books used in the this episode include "Somplace Else," "Me on the Map," "Town Mouse, Country Mouse," and "Somewhere in the World Right Now."', '1996-10-10', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
