INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C68D17A259704AB8810D66F4252DF4CC', X'9193E795DA7C40ECB68FF63AA7D5174F', 129, 'Histories & Lore: Valyrian Steel', 'Jorah Mormont details the mysterious properties of Valyrian Steel, a metal considered magical that was used to forge the blades of the great Houses of Westeros.', '2015-02-17', 3, '/kjrCJBHEpLFZidS7kBJHoQyURz0.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C68DB9DF3F474CC8885F5EAAA44A5D10', X'9193E795DA7C40ECB68FF63AA7D5174F', 69, 'Histories & Lore: Robert''s Rebellion (Robert Baratheon)', 'Robert Baratheon reminisces on his glorious victories against the supporters of the Mad King Aerys II Targaryen.', '2012-03-05', 3, '/xKf9v5ifIOsoWpmWhROG1STMBi0.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C68E9219124346928098545C0EF1D6FA', X'70D9E39768134785887D27D034928BAE', 2, 'Pingu''s Museum Visit', 'Robby goes to Pingu’s home to ask him to come out and play, which Pingu thinks is a good idea. They go off with the sledge and slide down a slope. At the bottom they narrowly miss Father, who is on his motorised sledge. Father then tows them to the art museum, which is where he is going to deliver a large package. While Father and the curator of the museum unload the package, Pingu and Robby go over to a sculpture that is in the form of a ring on top of a block. Pingu does a circus trick and Robby becomes a blue ball. After briefly wondering what it is meant to be, they then have some fun jumping through the ring. They then wander across to a tumbledown igloo, which has a somewhat skewed picture hanging on the wall. Pingu straightens it up. At this point the curator arrives and tells them off for messing about with the exhibits, and they go. The picture then slips back into the crooked position and, after a couple of attempts by the curator to straighten it, to his annoyance it falls off the wall. A final attempt by the curator to get the picture straight, by hanging it from a nail he hammers into the wall, ends up with the wall collapsing on top of him, to the amusement of Robby and Pingu. Pingu and Robby then spot a sculpture made of little blocks balanced on a larger block. Robby taps the sculpture, and it falls apart! They decide to rebuild it and it ends up looking like a rabbit, but is rather wobbly. Robby finds a stick, which Pingu uses to prop the sculpture up. Father then calls out that he is going, Pingu and Robby rush to get on the sledge, and they leave. The curator then spots the “rabbit” sculpture, removes the stick and the sculpture falls apart again. Once more the curator ends up less than happy!
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C698CCA88BE045ADB0ECFF1D0F098AD7', X'2389D176A1A846249B1C9C0C12A3BE4E', 5, 'Lost Ring', 'Bella is very happy about the diamond ring she inherited, until it goes missing ...', '1990-11-12', 10, '/yetogbi19Cx0MFS8jRO9SW6y3Cu.jpg', '2026-04-03T17:14:37Z', '2026-04-03T17:14:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
