INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C69D74B2A0E24559B795C5E45D76449A', X'9B144910398A47D49CCD823D25CC8B0A', 3, 'Third Eye Blind', 'It''s a gossip filled cruise down the Jersey coast; Jacqueline plays referee between two sisters-in-law.', '2012-05-06', 43, '/tsOl5m75pFJqdBnRnZnfDz5c49j.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C69F6ECAA54244B290197E5776A62994', X'45E64A158FC04E4BA1CA9E3F42F3634D', 8, 'Phases of Matter', 'Bill Nye is going through a phase - a phase of matter. Check out the ""Phases of Matter"" episode   to find out about rock-solid solids, liquidy liquids, and gassy gases. It''s phase-tastic!   Everything around us is made of stuff called matter, and all matter is made of atoms. Matter is anything   that comes in three varieties, what scientists call phases. There are solids like rocks, cookies, and desks.   There are liquids like water, honey, and juice. And there are gases, we breathe air and the helium in   balloons. The main difference between the three phases is how fast the matter''s atoms move.   All atoms move around because they have energy. The more energy that''s in something, the faster the   atoms move. Atoms in an ice cube don''t move very much - they''re frozen in place. The atoms in liquid   water slip and slide around - that''s why you can pour it and spill it. Water vapor atoms are moving pretty   fast - that''s why they float around in air (a mixture of other gasses). Changing', '1993-10-29', 26, '/r7Tyra8HnXJZYaetVgtS6J3htv0.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
