INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C703731C10C24699BD19DE6BAAB3D6A8', X'42E591E22A884434AE9F3D4B1D685613', 46, 'A Very Vegas Christmas', 'Celebrate the holidays Vegas style as the guys from Pawn Stars, Counting Cars and American Restoration get together for a Christmas barbecue. First they''ll deck the halls with pawn shop drama, when they debate the best and worst deals they''ve ever made. Then, the guys take a look back at all of the amazing restorations that Rick Dale and Danny have done for the pawn shop. And later, it''s finally time to eat. But can these guys cook as well as they negotiate?', '2013-12-19', 21, '/cRiUJ4yQCql5a8q42MKmPk7vE8x.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
