INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C7095A7156B1429E8011DA0D973FA897', X'4900FC8D5E7E408E972ECE9269D203B3', 1, 'Fancy Pants is Back', 'After a five-year hiatus, Heather Dubrow is back; Gina and Emily pay a visit to Dr. Jen Armstrong for some OC style self-care; things go awry when Shannon spills a secret about her old friend, Nicole, leaving Gina and Emily in an awkward position.', '2021-12-01', 44, '/cZ0CyyNnfFMbE8D2Zt760K5AJCe.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C70CBB264B234D9582BE15412F5A3B43', X'33E647E7A3E84C3A93E674E08399A790', 10, 'Yuckies', 'While Mr.Gribble sets out to destroy a rainforest and erect a casino, Nell sets out to save the magic Yuckles from extinction.', '1992-06-05', 24, '/p59UpeidWkpAUhRjs30u0tdbQyH.jpg', '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C70E7DC392D94B42B6EEB2CA9DE579A8', X'BF0F7445F58F467FA81BFCC2BF6BCA21', 21, 'Wembley and the Great Race', 'Wembley and Gobo''s friendship is strained when Wembley beats Gobo in a race.', '1984-05-21', 24, '/wI9Kvdqt2H1bhXqzMPVSZKaHwoI.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C71566D9A3A94A8E97CCAE86891C85A7', X'45E64A158FC04E4BA1CA9E3F42F3634D', 1, 'Flight', 'Things that fly need air. Even though we walk through it, breathe it, and sneeze it, air seems to be a whole   bunch of nothing. But air is there, and it''s powerful. Balloons inflate because air presses on the insides   and outsides of the balloon. Air pressure in tires supports the weight of bikes, buses, trucks, cars, and   planes. But air doesn''t need to be inside something to exert pressure. Air that moves around pushes,   too.   What do birds, planes, kites, Frisbees, and helicopters have in common? They fly because moving air   creates lift, or a push up. Airplane wings are shaped to push air down. The momentum of the air going   down pushes wings up. Air above the wing gets going faster than the air underneath. Fast-moving air   zips along, without pushing as hard side to side or up and down. The slow air pushes up from below   harder than the fast air pushes down from above ... and you''re airborne!   Every flying thing, from the tiniest flying insect to the biggest airplane, us', '1993-09-10', 26, '/jSE0by5opmjybp3tl6GPSFK0vSQ.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C71DF656831C4AEBAFF0A0DBE4C77943', X'C01DDD2ABDB14C978D0458F791EF1C24', 28, 'Horses', 'Everybody likes horses, so the Kratts spend time with a foal and her mother, a strong Belgian draft horse.  Then the brothers learn what''s different about zebras.', '1999-06-29', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
