INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C74A2EE85E6D43FF807DB0C2FBCC89BE', X'A0FA50759CE148C199950C0FD866E549', 13, 'Caviar Catastrophe', 'Sutton and Dorit’s feud gets dirty as a food fight almost breaks out at Jennifer Tilly’s first group lunch. Bozoma’s hopes for her fertility journey are met with a reality check. Shocking photos leave Garcelle and Erika seeking answers. Kyle facing even more questions about her future.', '2025-02-25', 43, '/tx8JjRBOkmbLHWj0o4yGfHr3HgS.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C74DD39F2A994D4D8032A4ED2EC442FA', X'1D713CA64E174F84949C8CFD98514127', 42, 'Oldest Trick in the Book', 'Climb to new heights with the Pawn Stars when a signed, limited edition copy of Seven Years in Tibet is brought in. Can Rick read between the lines on this literary classic or will he judge a book by its cover? Then, things get comedic when Corey and Chumlee check out a Three Stooges promotional projector. Will they have the last laugh or will the joke be on them? And later, Chum tries to institute new policies in order to liven up the beginning of the work week. Can he successfully turn it into a fun day or will it be just another manic Monday?', '2014-12-18', 21, '/1FNrhQEu1a7okOyOmPqBQQzaOK5.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C74FEE8017C944ECA64EC37E2C096F69', X'0E4196154C964DDE8ED2715770BA77BB', 15, 'Show Your Stuff', 'One weekend, Bear decides to start a new hobby --- "whittlin''." He gets a block of wood and an instruction book, but finds that his early efforts don''t look much like the duck in the book. He determines, however, to keep trying. Meanwhile, the kids in the Big Blue House are exploring talents of their own. Ojo continues working on her bike-riding, while Pip and Pop have developed a synchronized-swimming routine. Treelo searches all over for his talent. Tutter, however, experiences a lack of confidence when he learns how great Rita is at kicking the ball in soccer. He tells Bear that he''s quitting the team.  Songs  Do Your Thing  Notes  There is no Shadow segment in this episode.', '2003-11-03', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
