INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C773DC4F8737463790158C0444686421', X'7C422193B07849D881EFF2B9F94F059D', 53, 'Telly is "Triangle Guy"', 'Episode #3058', '1993-01-20', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C7765F9C87BC4E3B98641EAA910C053D', X'3269A890BBA94E6C9278F7EB38EB1720', 4, 'Rocks & Soil', 'We live on top of rocks – the Earth’s surface. There are three basic types of rocks — igneous, sedimentary, and metamorphic — and each type is made a different way. Igneous rocks are made from cooled lava. Sedimentary rocks are made from small pieces of other rocks stuck together. Metamorphic rocks are formed when other rocks are heated or pressed, or both. One type of rock can change into another type of rock as the Earth’s surface shifts and changes. It takes the right conditions and a lot of time.', '1995-02-03', 26, '/i4821AlQyvq1wB3OvlZHIlhO79a.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
