INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C7D46C26F2AF49BF80B6582A4CF71613', X'CA19F89515144988A70995E84EAB7CEE', 16, 'Pawn Stars and Movie Stars', 'Rick and Chum flip out when Spencer stops by the shop with a few vintage items. Will they tilt the negotiations in their favor, or will they not be able to see eye to eye? Next, a Bruno Mars platinum album spins into the shop. Can Corey land a funky deal, or will he get locked out of negotiations? Later, Chum twists and shouts when a pair of boots signed by Ringo Starr walk into the shop. Will he and the seller be able to come together, or will Chum have to make his peace with not landing a deal? And finally, Rick calls in actor Dennis Quaid to help authenticate a signed poster for his upcoming movie. Can Rick be a great communicator, or will the seller give him the cold shoulder?', '2021-05-03', 42, '/vtDX07MEGZvEvUlchjTIYI3YTKE.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
