INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C806565D3F73496FB68069E5B8FB36BD', X'97A3D1F5A8F147CD81222E74A092836D', 19, 'Who is Max Mouse? (3)', 'Jamal suspects that Janice lied about having her own computer. The team challenges Max Mouse to some online games and creates their own screen name and get the phone numbers of their suspects.  Then they learn Calvin had another screename: Red Parrot, so they take him off the list. Hector gets some tutoring from Alex on how to face up to a bully. Just then Lenni and Jamal''s names and phone numbers appear on the police suspect list.', '1994-01-10', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
