INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C80EC819764F4AC4A6635AFE74C54E95', X'FC120008C5C447D7A3A991A401394C41', 19, 'The Talent Show', 'Convinced that he doesn''t have any talent to offer for the upcoming school talent show, Brother is recruited to be the talent scout. Guided by Teacher Bob''s advice that everyone has talent, Brother helps the other cubs discover their own special talents. In so doing, Brother discovers he also has a talent just as Teacher Bob suspected--a talent for finding talent.', '2003-01-30', NULL, NULL, '2026-04-03T17:40:21Z', '2026-04-03T17:40:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
