INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C81FD59965674858BD31E37BC5B7D05E', X'F4C403079B5E4263A4E0DFA138131E7F', 58, 'Elmo Visits the Doctor', 'Join Elmo on his first trip to the doctor’s office! Elmo and his Sesame Street friends learn how going to the doctor can help an earache, a fever, and a stuffy nose feel better. Loaded with clever songs, brand new animation, lighthearted lyrics, and a never-before-seen Elmo’s World that explores being a doctor, this fun-filled video will help preschoolers learn that going to the doctor can be a prescription for fun! DVD bonus feature: Kid Friendly Instant Play Elmo Doctor Game!', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
