INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C88357FF670844818AD4196F023579BE', X'4D504E489B0347A198CEBE9AD8BCB6C8', 6, 'Raking in the Dough', 'When a seller brings in a life-sized E.T. statue, Rick tries to make an out of this world deal. Will he dial up a great offer, or will he need to phone home for something better?', '2026-02-18', 41, '/iNrTGykPiLQ9ielFRWFolupfGDT.jpg', '2026-04-03T16:34:25Z', '2026-04-03T16:34:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C88761A30D23474083C70A84ED192330', X'4B2A19E02FAE492EBC31F78E63D88EBC', 15, 'Locked Up and Rail Roaded', 'Burn rubber with the Pawn Stars when they test drive a 1950s Chrysler Town & Country Newport. Will Corey drive a hard bargain or lack the horsepower? Next, a cubist painting by New Zealand artist Louise Henderson brushes in to the shop. Will Rick get a square deal or will he paint himself into a corner? Then, antique railroad locks from the late 1800s clasp their way in. Will they secure a place in Rick''s heart or will he ride them out of town? And later, an early-1900s self-heating gasoline iron steams in. Will it smooth things out with Chum or leave him hot under the collar?', '2016-11-28', 21, '/guGGha3kXxiaPJ3KUZSS7xhXr2w.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
