INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C8DB1C2EF5F54B90A7910B6CA8DEB297', X'98D80972E53A43DDA03A7703465E6F87', 6, 'Man. Make. Fire.', 'Go cruising with the Pawn Stars when Rick and the Old Man eye a 1949 Hudson Commodore. A premium luxury ride of the post-war era, will the guys add this classic car to their collection, or put the brakes on negotiations? Then, when a guy brings in a 2,000 year-old fire starter, the guys challenge Chumlee to create fire the old fashion way. And later, Rick is blown back to the ice age when he''s presented with a fossilized mastodon tusk, but can he sink his teeth into the deal before Chumlee burns down the shop?', '2012-11-13', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
