INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C8FB2D42A65C469183811AB5DF58022B', X'0B9D7AE7218E45A08C3AE69912F5A6ED', 9, 'Franklin and the Fortune Teller', 'Beaver tells Franklin that he will have a bad day, so Franklin becomes cautious the following day and ends up missing out on a lot of great stuff.', '1999-11-08', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C907AA96523A4F3E9BFDD20F05AA7F44', X'3982796B54514100904246BEDF6A20A5', 16, 'Pingu at the Fairground', 'Pingu, Pinga, Mother and Father go to the funfair. They pass some balloons but don’t buy one. They come to a barrel organ, Pingu gives the player some money and he plays a tune. Pingu and Pinga rush on and stop at a candyfloss seller, and they both have some. At the “hit the tins” stall Pingu has a go, gets all the tins down in his three throws, and receives a lollipop as a prize. Pinga also has a go, but she throws before the stallholder has completely finished putting back the tins. The ball misses, bounces off the backboard onto the stallholders head, and then into the tins, knocking them all down. The stallholder is not very happy about this, talks angrily to her and doesn''t give her a prize. They move quickly on. Both Pingu and Pinga then have an ice cream. At the sweet stall Father buys Mother a candy pendant that he puts round her neck, and Pingu and Pinga each have a twisty candy stick to eat. Pingu and Pinga have a ride on the roundabout. Pingu then rides on the swings, and Mother is concerned by how high he''s going. When he gets off he feels a bit poorly. On the way home, Pinga has some more candyfloss, but Pingu doesn’t want any. They each get a balloon, but Pingu misses the string when taking the balloon off the seller and the balloon floats away, so Pinga lets go of hers as well. Then they all go home.', '1993-07-13', 5, '/upUUzfjnsSSUwlfnqvhs0vijFSl.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C908DEA41B6746C48034BB8621077295', X'83D1C2FB7CD949779A5D98D36CFB59D3', 3, 'Episode 572', '', NULL, NULL, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
