INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C9140BC76E1A4C91855DC57A691761EA', X'98D80972E53A43DDA03A7703465E6F87', 17, 'Little Pawn Shop of Horrors', 'Huddle up with the Pawn Stars when they eye a football signed by the 1967 Chicago Bears. The final season for famed coach George Halas, can the guys break down the seller''s defense for the win? Then, Rick and the Old Man duel for a 1925 Gibson banjo. Will they get this piece for a song, or will negotiations hit a sour note? And later, some props from the movie "Child''s Play" inspire Chumlee to make a movie. Is he bound for Hollywood stardom, or will Rick pull the plug on the project?', '2013-01-14', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
