INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C92CCD67A52842BABF3748DB4BBD7D26', X'D405F9734C7E4CB6B7C0D09A884C9B35', 14, 'Burlesque Is More', 'Sonja hosts a burlesque-themed party and puts on a show for her guests. Elsewhere, Jill visits her daughter at college; LuAnn and Jill hear LuAnn''s new single at the recording studio; and Simon confronts Jill about her cyber-bullying accusations.', '2011-07-07', 42, '/zF32P4qs4HMnPiiPnU1umrc9c7O.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C92D5AB246AD405E80EDFD4561DE9ECE', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 11, 'Big Bird''s toys', 'Bob plays “Pop Goes the Weasel” with two kids and Forgetful Jones, who plays the cymbals off-cue. Bob instructs him to play after the word “fun,” but he does so when Susan stops by and asks if she can join the fun.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C92DE8FA7C2945B09FE0FE235699C4DD', X'CA19F89515144988A70995E84EAB7CEE', 8, 'The Need for Speed', 'When a seller speeds into the shop with an iconic piece of Sammy Hagar memorabilia, Corey calls for back up. Will he drive home a deal? Meanwhile, Rick has a chance to buy a vintage whiskey strap. Is he willing to pour out some cash before it walkers away? Then, a Nintendo demo system inspires Chum to create a video game about the Pawn Shop. And later, Rick checks out a J.K. Rowling signed Harry Potter book. Does Rick have the magic touch, or will "he who must not be named" cast misfortune on the Gold & Silver?', '2020-12-28', 42, '/q2sKptPAmM8BefK6FgmGZgmJN9i.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
