INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C947B30FEE934DC79BF2F95753406EDB', X'4F18AC4C8757456CA49A224F00E6A9F7', 16, 'Elmo Steps In for Super Grover', 'Chris welcomes the viewer and meets up with Elmo, whose toy airplane is stuck in the tree. He suggests using a ladder, when all of a sudden, Super Chicken and his assistant, Robin, fall out of the sky. The duo begins to formulate a plan when Super Grover crash lands to save the day!', '2008-10-08', NULL, '/xN3nlCCIjRCRzbvvuJUsckIO4bi.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C948E782E71541259370B92699E4475E', X'40700E8A1DCE4895BEDE522A13A8BCAD', 1, 'Green Creatures', 'Zoboo realizes that plants and trees are as alive as all the creatures he meets in Animal Junction. The Kratt Brothers teach the lemur that plants grow well if they get good soil, lots of sunlight and enough water. And there are plenty of creatures willing to help plants flourish, including Toothbrush the elephant, Popcorn the binturong and a whole family of sloths. When Martin and Chris follow Popcorn to India, they visit a 2,000-year old fortress, where green creatures like vines and plants are taking over the site.', '2000-10-03', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C94ABE07883C4F8683E7D7CC6CA6C998', X'4FE93658C46343298E649D523869C2CB', 16, 'Packing Heat', 'Take a ride with the Pawn Stars as they check out a 1962 mobster-style Cadillac Fleetwood limousine. Will the guys make an offer the seller can''t refuse or will the deal become too much of a stretch? Then, Rick and Chumlee are presented with a collection of 1990s Atlanta Braves championship World Series rings. Will Rick step up to the plate and take negotiations into extra innings or will he strike out looking? And later, a man walks into the shop with two vintage pistol lighters. Will Corey pull the trigger to fire up a deal or is this seller just blowing smoke?', '2010-12-13', 21, '/iXBDwKguI3lc0pRzzpD8oM0y8ty.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
