INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C9B6D73917E94EAA84DC928B8F7F9671', X'F8B697543E4145E5832A64D9C2809AD7', 10, 'Cookie', 'When a superstar decides to sing at the school, the janitor has too many jobs to handle. Bernard helps him out, with bad consequences as well as Mr. Steel rocking his way to love.', '2005-03-10', 15, NULL, '2026-04-03T17:20:06Z', '2026-04-03T17:20:06Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C9B85A40942A4055B7A46985B142B7ED', X'095258D0D8DB40968AC76A42CD4CBDCF', 4, 'The Grapes Of Generosity', 'Gobo finds the legendary "Grapes of Generosity", mystical fruits which are rumored to compel anyone who eats them to share them with others. However, when Gobo brings them back, he ends up eating them and keeping them all to himself. Before long, Gobo becomes weightless, and tries to hide it from everyone else. But when he hears that Red climbed to the very top of the Great Hall, it''s up to him to get Red down safely, and finally admit to everyone that his own problem was caused by being greedy.', '1985-01-21', 24, '/h2jl5Lwei8vKIb1AKgvxff1M1eX.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C9B8EE92B1DF4B6E94D23C48283EA736', X'BBFEE3B49C9548A6BEAA791FA08B1F43', 5, 'Episode 5', 'Meet the bird with a six-foot wing span that can soar to an incredible 200 feet before swooping on its prey at 45 miles-an-hour: Heidithe white bellied sea eagle.', '1983-09-26', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'C9C9D3D760684FD8A19BA9E57CD67DF7', X'C373ABED50EF417E9F344E9050611A1B', 11, 'Dirty Dancing in Mexico', 'While still in Puerto Vallarta, Vicki, Lydia and Tamra continue their night away partying — while Heather and Gretchen continue to sit back in the limo. Gretchen tells Vicki how much she was annoyed by her antics but Tamra shocks the ladies when she tells the specifics of her past to Gretchen. Back at the resort, Mexican strippers arrive to spice up the night but Lydia is a bit nervous about the whole situation. Alexis, home in Orange County, asks Jim for an item that he is unwilling to purchase.', '2013-06-10', 44, '/6oPwS7xjPpGKVah7rInJMTJm1zc.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
