INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CA18B1F467EA491FB257E98AC0698B7D', X'87F8406382B345A4936C3759E5D91CE3', 12, 'A House Divided', 'Separated from the church, Heather meets with her estranged sister to make amends. Whitney feels blindsided when Mary''s late night gifting results in a renewed friendship with Lisa. And when the group gathers to hash out their grievances before heading home, a heated argument divides the ladies, leaving two behind in Vail.', '2021-12-05', 44, '/oLuYhtu8aw5gYnvEHQoYV32AsCZ.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
