INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CA2747B2AABA433CA6BFC38701C586F0', X'0EBBA123871D4D2BA054EB85D2AD9450', 42, 'The Penniless Princess', 'Sara Crewe moves from Africa to London with her father. He goes off to war, so he sends her to a prestigious boarding school where she is under the strict direction of the headmistress. She is bullied by her classmates and becomes friends with an eccentric girl and one of the young servants. Sara is notified of the death of her father and as the loss of his fortune, but is allowed to stay at the boarding school but as a servant. She shares the food she receives with others and reads the Bible to her friends. One of her father''s friends searches for her unsuccessfully. Later, he befriends a poor servant girl that lives next door, only to find out that it is Sara and adopts her.', '2012-08-14', 30, '/cEicCjmleViGsLgDHDl5zqVYUvm.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CA28BE09906F4A9E85BD6C023F3B46BA', X'941B8C6544544336BE7C1D0591C12F90', 17, 'Pingu Gets Lost', 'inga is ill, and Mother sends Pingu out to get some milk as they’ve run out. As he’s returning home with the milk he tries to balance the bottle on his head and drops it. The bottle rolls into a crack in an ice wall. The crack is too small for him to get into, so he bashes his way through, and finds himself in an icy cave. Unfortunately his method of entry brings down a fall of ice, blocking up his entrance hole. He retrieves the milk and sets off to find a way out. As he wanders around he doesn’t notice that a loose woollen thread in his scarf has become trapped by the fall of ice and the scarf is unravelling behind him. He gets hopelessly lost, and wonders what to do. Then he finally notices the thread behind him, and he retraces his route all the way back to where he entered the cave, rolling the wool round his flipper as he goes. He bashes his way out and triumphantly marches home. When he gets indoors, brandishing the milk, Mother asks him what has happened to his scarf. Father takes the ball of wool and starts re-knitting the scarf, and Pingu gives Pinga her bottle of milk.', '2004-01-26', 5, '/mSzuJ3ppTCYPGlEVjwgUTBCWe7x.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
