INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CA535AE703184BFEBA30AEE2E8634156', X'A9657E86413549CEB1F9C295113077E1', 25, 'All Together Now', 'The friends go to the Dragon Land Carnival, but when Emmy and Enrique go off to play together, Max feels left out. However, Emmy and Enrique don''t notice it.', '2005-03-16', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CA56EC7450F14B1BBB1B40FC8FC8CB5E', X'4F18AC4C8757456CA49A224F00E6A9F7', 3, 'Sock Chaos at the Laundromat', 'At the new Sesame Street laundromat, Chris welcomes the viewer as he does his laundry. He says he loves the noises the washing machines make (singing a variation of "The Wheels on the Bus"), while an Anything Muppet lady disagrees with him. He folds his clothes, then notices he''s got one missing sock (all the rest of his socks are in pairs). He wonders where his sock went, when Abby Cadabby poofs into view. He shows her the one sock he has which is missing its match, and she proceeds to show him the trick she was going to show Elmo: her "Two Trick," which involves turning one thing into two.', '2008-08-13', NULL, '/tXLeL5wFZgMnYxCwnrc8DcYkyjb.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
