INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CA81E76CBE4F4C3DB6E82E4FD81EA559', X'136B81D3964D4B8FA21492F00D96D6B9', 105, 'David''s imaginary friend', 'David creates an imaginary companion to help him navigate a difficult day full of challenges on Sesame Street. The imaginary friend provides encouragement and support as David faces various obstacles. Eventually, David realizes his real friends on the street are even more valuable than an imaginary one.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CA866883374B44A8B8B5639D04FDDF8A', X'050D8AE16CC14018933DB3C3D13DE856', 35, 'Episode 35', 'In 1877 the clipper ship Avalanche sank off the Dorset coast. Now divers have recovered part of her cargo, and Simon, Janet and Michael sample a bottle of 117-year-old champagne!', '1985-01-10', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
