INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CA9971AF027B4B8EA0E4CA6226FBA629', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 73, 'Forgetful Jones and the labels', 'At Hooper''s Store, Telly frets about testing everything before using it, while Olivia demonstrates guessing musical instruments behind her back. Forgetful Jones peels off can labels trying to peek inside, then forgets what the labels do, leading Luis to explain their purpose and help match them back to the correct cans. Forgetful''s memory troubles multiply when he next forgets where he left his can opener.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CA9B9D793239454B9CB89CD59DFBF8F7', X'D73C357E10784DE8A77A25C206262A1E', 5, 'Ghost Train', 'Big, Little and Dog ride the ghost train.', '1992-10-27', NULL, NULL, '2026-04-03T17:24:52Z', '2026-04-03T17:24:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
