INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CB244E18B6B44EEC9DE9DEAD1A4FF709', X'1A534647384B4C00BB6CA3371AD962EB', 32, 'Penny for your Pawn', 'Test your strength with the Pawn Stars when a 1930s Gottlieb grip tester pulls up to the shop. Will Rick muscle in on the deal for this vintage game or will it not work out? Then, Rick gets hung up on a limited edition piece of abstract art by Hollywood actor, Anthony Quinn. Will he be able to sculpt a concrete deal or will the seller stonewall him? And later, Chum offers to help promote the shop by trying to make images of the Old Man go viral. Will his idea break the internet or will he end up crashing the whole system?', '2015-05-28', 21, '/6KbQSEaqFg3wsiCYiO2JuYi4JAD.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
