INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CB3650ED76144033AFF94946B4910746', X'F829D1FB64EA430F8E0EB3345653A542', 5, 'River of the Dammed', 'Steve is the special guest of the Belize Zoo as they celebrate their 20th anniversary. He also travels up the Macal River to observe a controversial dam project and tangles with a highly venomous fer-de-lance snake while searching for Morelet crocodiles.', '2003-06-13', 44, NULL, '2026-04-03T17:39:12Z', '2026-04-03T17:39:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CB3C044073F54E79AEBB4A2682C47510', X'6C1EC19F74DF4F359A6117B98175D826', 11, 'Kiss and Tell All', 'Lisa invites Dorit and the others on a glamorous Roman getaway. Denise tries to make nice with Erika, but gets an ice-cold shoulder instead. Garcelle digs into Sutton’s past, while Brandi drops a bomb on Kyle and Teddi which threatens to turn their dream vacation into a nightmare.', '2020-07-22', 43, '/392Xdf52nxD8x2xFLasrbDwpuXf.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CB3E0A5D6B2F41AA9F6BF4DFEA2797D0', X'34674C90410E427CBE4D2A6F6F865A80', 16, 'Love Me Spender', 'Rock out with the Pawn Stars when an Elvis Presley contract gyrates into the shop. Signed before The King got famous, will the guys try to buy this piece of music history, or will they send the seller to Heartbreak Hotel? Then, Chum and Corey look down the barrel of a rare Winchester rifle. Made for the popular 1800''s sport of target shooting, can the guys score a bulls eye with this deal? And later, a seller brings in a set of buttons that belonged to the Queen of France, Marie Antoinette. Will Rick be able negotiate without losing his head?', '2012-06-25', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
