INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CB4CD2F4A1D0480290E2DF27B0335A7F', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 127, 'Jerry Seinfeld: Submarine Captain', 'A half-hour look at what Seinfeld did to pull the show together to get season 8 going and what he did behind-the-scenes to substitute for Larry David.  Most of the cast and crew discuss what went on behind the scenes of the show as well.', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CB5092E2935A4A14918181E0EB908567', X'6E314631D72B4EBDBF39D123D19108FC', 1, 'Roald Dahl Special', '', NULL, NULL, NULL, '2026-04-03T17:20:13Z', '2026-04-03T17:20:13Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CB52D65E8E3C40B381AC38406A59A99B', X'4C79C0B621A442778967BE1E791EFDBE', 14, 'Pampering Pingu', 'Pingu and Pinga have been out shopping with Mother. Father then drives by on the motorised sledge, but as he goes past snow is thrown up by the sledge and splatters Mother, to Pingu and Pinga’s amusement. Just then, Mother notices a beauty salon, and goes inside with Pingu and Pinga. The beautician seats Mother in a reclining chair, and settles Pingu and Pinga on chairs to wait, giving each of them a lollipop. While the beautician works on Mother, Pingu finds a bottle of lotion on a trolley and squeezes it, sending a blob across the room and into a cup of tea that a lady, who is having a face treatment, drinks and leaps from the chair in shock. Pingu hastily puts the bottle of lotion back, and then discovers that his chair will go up and down and round and round, so he spins himself about, eventually coming off. Pinga wants to try this in her chair, so Pingu spins her round very fast, making her giddy, and she falls off the chair. Mother has progressed in her treatment to having shades on her eyes, with vibration from the chair to relax her. Pingu takes the bottle of lotion and uses it to model a beard, moustache and hair on Mother''s head. When the beautician spots this she’s surprised and shows Mother. After she’s cleaned herself off, Mother looks across to where Pingu and Pinga are sitting, and sees that Pinga has also sprouted a beard and hair modelled from lotion. She gets Pinga to sit in the chair next to her. Pingu is bored, so he puts on some hair curlers from the trolley, and a towel as a cloak. He goes across to Mother and startles her by his appearance and the noise he makes, causing chaos and generally wrecking the place. When the hubbub has ended, Pingu is angrily told off and has to clear up the place. When he finishes, Mother, Pingu and Pinga leave. As they get outside, Father goes past on the sledge again, this time covering Pingu with snow. Mother takes Pingu back inside the beauty parlour for some restorative treatment, which he’s not happy about.', '2005-11-29', 5, '/eQaQEIjW6vi0G8Hq1OQnScoKqCt.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CB5479383DA34730A3E29127AC19A2F0', X'9193E795DA7C40ECB68FF63AA7D5174F', 152, 'Histories & Lore: Vaes Dothrak', 'Jorah Mormont explains the structure and places of interest of Vaes Dothrak, the vast capital of Dothraki people, and mentions some of the rituals practiced there by the Dosh khaleen.', '2016-11-15', 4, '/y9jS3e4fZzYUhkYa0S3D9A2kYY6.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
