INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CBAF7A50C88F436AB9C783712DB6682D', X'EA1650C2E4F146C793BA74B5D45D08E5', 11, 'Contract Player', 'It''s time for Kim to start rehearsing for her upcoming tour with Kandi, but she''s more interested in get-skinny-quick treatments than learning the choreography for her show. Sheree receives some good news about her talent agency audition and enlists Kandi''s help to prepare for her role in a local play. Tension lingers from NeNe and Peter''s blow-up phone fight. The ladies think that Cynthia''s priorities are a bit off, but Cynthia has a plan to smooth things over with NeNe. Meanwhile, Dwight tells Phaedra what everyone has been saying about her mysterious pregnancy. Phaedra is not happy and intends to confront the ladies about the gossip.', '2010-12-12', 43, '/pUmFPTx4X3Iodyw6k6IrYKaWFdT.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
