INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CBBD7F8063AA4452BB0F06CB1FE78C7D', X'E4023DA233D74A2BA04ACA449BD23935', 2, 'The Loneliest Locker', 'Mike and Frankie search for second jobs in order to send Sue to a good college, Sue and Brad produce a play for school, Brick finds some of his old "lost" toys, and Axl raids the house to furnish his new home.', '2014-10-01', 22, '/puyR1ayxpRBUt5yziZEJDiIoYD2.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CBC1618CF41A4C22A9D18F1FEF66FE49', X'34674C90410E427CBE4D2A6F6F865A80', 7, 'Bossy Pants', 'The Pawn Stars are flying high when a panel off the world''s fastest airplane, the SR-71 Blackbird, soars by the shop. A supersonic spy jet from the Cold War, will the guys have the intelligence to make a deal? Then, a solid bronze 16th century cannon fires into the shop. Specially made for use on ships, can the guys battle on the high seas for this antique weapon or will the deal sink their fortunes? And later, a customer brings in a vintage pair of gigantic Levis jeans. Used as a display in stores, will Rick and Chum wear the pants in this deal or will they need to button up their skills?', '2012-05-21', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
