INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CBE5865BCE0E4408A6A3BA626A7062E6', X'E03D79BDE01F4414B0B3F3B5F26E97F4', 6, 'Halloween', 'Frankie is excited over being invited to an adult neighborhood Halloween party. But will she be able to get Mike to dress up in a costume, or will he have his own idea of fun? Meanwhile, a melancholy Sue''s spirits are lifted when she discovers that Reverend TimTom is back in town and hosting a Halloween church event; things don''t go quite as planned for Axl, his friends or their dates as they head out to an exclusive haunted house party; and Brick chooses a unique Halloween costume that is not easily defined.', '2010-10-27', 22, '/tCqtQiIgWPLNz5AvlPezn4JOcep.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
