INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CBF6C515063D4658B5265FACA8987136', X'97A3D1F5A8F147CD81222E74A092836D', 4, 'Am I Blue? (4)', 'Gaby writes an apology letter to her parents while the team learns of the real culprits identities. Gaby is cleared from the suspect list and to show their forgiveness, her parents and the producer of Galaxy Girl surprise Gaby with a visit from the actress who plays Galaxy Girl.', '1993-09-26', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CBF9CCE99B574D3C9476DFB0B7259D6C', X'740A96A0A0754BE2BE92A178D0939384', 11, 'Kitty Kindness', 'When a lost kitten gets discovered on Sesame Street, Chris and Elmo put up signs to try and find its owner; Grover and Cookie Monster help look after the kitten and learn how to take care of it.', '2018-01-27', NULL, '/xOzfF2zyBC2nZ4zyFK95TkPJKEU.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CBFA6D39BF1443BABDC09971389C5F8C', X'97A3D1F5A8F147CD81222E74A092836D', 25, 'What''s Up With Alex? (1)', 'Jamal is happy when Casey goes back home. Tina finds her school ID in a trash can and realizes the last place she had it was in her jacket - in her locker. Jamal and Tina find out that her locker was broke into and her expensive sheepskin jacket has been stolen. Other thefts occur at Hurston. The team (and Ghostwriter) learn that Maria''s camera was stolen, and Delilah''s tape recorder as well. With Ghostwriter''s help, they discover that a fence named Big Ralph is selling the stolen items and on their stakeout, they see Delilah buying her tape recorder back. Hector goes to look at the stuff but Ralph catches him. Meanwhile, Alex is chosen to be an alternate on the Dragon''s basketball team but ends up taking Victor''s place when Victor gets mad at the captain (Kevin) and quits.  Alex hangs out with his teammates, Kevin and Spencer, and ends up coming home late and getting in trouble with his father.', '1994-04-10', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
