INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CC28444572A94DC997B5DCD419548D08', X'36EA381466B44986B6EE44559D3562C1', 19, 'Mexi-Loco', 'Phaedra feels that it''s time to question Apollo and Kenya. Gregg discloses an issue he has with Peter. Kenya wants to re-do NeNe''s pillow talk event with the hope that things will go smoother.', '2014-03-23', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CC322CACA42A48989DA892697B5EDE76', X'D3E13496E3C8490383B45A31FEDEE232', 11, 'The Great Divide', 'While on their way to the North Pole, Aang and his friends arrive at a giant canyon where two groups of refugees are bickering over who should get to go across.  Aang decides to walk across with the two groups to ensure they don’t fight one another.  However, he soon learns that the two tribes have been feuding for one hundred years and they both believe their actions are justified.  But when the predators inside the canyon start to come out, Aang is stuck trying to defend both tribes from each other and the vicious wildlife.', '2005-05-20', 25, '/rApMjdBNbwInH5zpqSquJ9Yi3hp.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
