INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CC418915F56544378B3D398D0FB7EBB6', X'67E1143EC43B4F9387D164E1BB6E199D', 23, 'A Big Surprise & Matilda Ramsay!', 'Lindsey and Radzi try their hand at indoor skydiving.', '2016-06-10', NULL, NULL, '2026-04-03T17:22:09Z', '2026-04-03T17:22:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
