INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CC49BD0FA2B0466B818198C4C78B53B8', X'204D86FBD99C4FD18DCD9C1BCFD3C33F', 22, 'Bye Bye Baby Birdie', 'Emmy finds a baby Rhyme Bird and names her Cutie Pie. However, she realizes she mistakenly takes her away from her family and she and her friends go to bring her home.', '2001-09-03', 30, '/ykf5Fb8jv5amcanusGXEXDUFjh0.jpg', '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CC4B20E9CE474E4694DF2FE3B28F1668', X'1996DDD820C94A3096BE2B87FAB8D17C', 29, 'Over a Barrel (3)', 'Tina and Alex learn from Momo that someone substituted his boss''s barrel''s but he has no access to his files. They ask Ghostwriter for some help and learn who substituted the barrels. They go straight to Miller''s place and learn that he also sponsors a children''s program. They overhear him arguing over the phone  about the barrels and planing to destroy some invoices that prove he is responsible for the toxic waste. They head town to Momo''s place to get the invoices but someone has gotten to the invoices first. They realize that Miller is probably the thief but have no proof.', '1993-04-25', NULL, '/WMwH5HyZUL2gGq3j8thyDWa3sa.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
