INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CC53AD9184254F0388CB44779750E421', X'136B81D3964D4B8FA21492F00D96D6B9', 81, 'Grandma Grace''s birthday', 'The entire neighborhood surprises Grandma Grace with a wonderful birthday celebration at Hooper''s Store, complete with decorations and a special cake. Everyone contributes something meaningful to make the day unforgettable. Grandma Grace is deeply moved by the love and effort her friends put into honoring her.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CC577C1B15F344AD8F46AF3AC873E6DD', X'1A534647384B4C00BB6CA3371AD962EB', 20, 'Mystery Caller', 'Roll with the punches when the Pawn Stars check out a Superman vs. Muhammad Ali comic book. Will it be a knockout deal for Corey, or will he throw in the towel? Then, Rick finds himself in the grey when inspecting an Edward Hopper charcoal piece. Will the deal be black and white, or will he draw a blank? And later, Rick suspects that all the office phones are broken. Will the guys figure out why the phones are ringing off the hook, or will they just hang it up?', '2015-03-26', 21, '/hAp4awulI4DTMkS5HcWHcBys58s.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
