INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CCBC41D074FD47128B477B8933FFBC9D', X'136B81D3964D4B8FA21492F00D96D6B9', 114, 'Remembering Mr. Hooper''s egg cream', 'The residents reminisce fondly about Mr. Hooper''s famous egg cream drinks and the wonderful memories he shared with everyone on Sesame Street. They gather together to celebrate his legacy and the joy he brought to their community. The group decides to preserve his special recipe and keep his memory alive.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CCBC606FA36548A7809525198B80984D', X'1D713CA64E174F84949C8CFD98514127', 14, 'Tricky Ricky', 'Go long with the Pawn Stars when a signed jersey from San Diego Chargers quarterback, Dan Fouts, gets thrown into the shop. Will Rick be able to make the completion or will it slip through his fingers? Then, Rick tries to learn the trick of the trade when Harry Blackstone''s vanishing birdcage appears. Will he have the magic touch or will it disappear right before his eyes? And later, Corey and Chumlee talk Rick into joining their fantasy football league. Can Rick take charge or will he get sacked?', '2014-09-01', 21, '/4qhJLPTuNQpBruzBVSeYPgmwXNm.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
