INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CCF60EAE2DC74F7AA25FFD3F4BA94A6D', X'F4938E7D11A84756B40598BEDD7C9B28', 2, 'Pat and the Magpie Hen', 'Pat stops for a picnic lunch near Thompson Ground halfway through his round. He falls asleep in the warm sunshine. Some hens cause mischief, one takes Pat''s sandwiches and the other takes Pat''s keys! The hen surprisingly leaves Pat''s keys in a nest in a tree. Dorothy soon comes to see what the commotion is about. Pat and Dorothy then go to get a ladder and Pat climbs up the tree to find a magpie''s nest with some other missing things. Who has ever heard of a magpie hen?', '1981-09-23', 15, '/vDpTIz2cBkPgTMelNImha5gks0r.jpg', '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
