INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CDBD859F54A848F08BC7F75946946124', X'73AE1459BA914185A9DABF6F2844AF49', 23, 'Reunion (2)', 'The ladies relive their trips to the Hamptons, Newport and Mexico, including all the drama in between; Ramona addresses Leah''s behavior, and tempers flare when she claims Leah ruined her birthday party with her risqué dance moves.', '2020-09-16', 60, '/yqtfW7UHfjGvEiuSVOn1OicYx8n.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CDCA5B593FA64CFF9410BB63710DCCE1', X'FE19A277AED844DFA4ACFC1C4E9941B4', 13, 'Catwalks & Cat Fights', 'After almost 2 years “She by Shereé” is about to debut, but big changes are on the horizon and serious trouble is brewing between the ladies. As Lisa prepares for a new future without Ed''s NFL paycheck, Kandi finally sees a breakthrough between AJ and her mother, and Shereé tries to keep it together before her clothes go down the catwalk. Meanwhile, it’s NeNe who is ready for a meltdown. After her return from meeting the man who claims to be her father, she butts heads with Gregg, battles with Kandi at Shereé’s show, and has a blowout fight with Kim. Will a glass of wine be able to undo the damage this time?', '2009-10-22', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
