INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CE366715F492416F850B726D7710D404', X'F5C042DC065742E8A37D247414140632', 8, 'Austin, We Have a Problem', 'In part two of the trip to Austin, D’Andra and Kary finally find common ground – even if it is on the water. Tiffany bonds with Stephanie and Kameron, while Brandi finds herself walking on eggshells around Tiffany and confronts her about feeling like she can’t be herself around her.', '2021-03-02', NULL, '/zv6Ro6tRWiYwR03KP88JwJJV5Vi.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
