INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CE529C31965B40C6A795E1D61F08E7AA', X'DA06465B91544FEBA455374DF7DAB02F', 26, 'Adventures of Little Big Bird (Part 2) (4108)', 'Previously, Big Bird was accidentally changed into little Big Bird when Mumford tried to do a magic trick.  While it was fun being little, little Big Bird now wants to be big again so that he can play with his friend Snuffy.  He decides that he has to make his way to Alan and Gordon who are playing chess so that they can help find Mumford to change him back.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CE55EFBD5169437E85AA306A6FDA4356', X'ECB64EF34F8045A7B4A9C04434B02E35', 29, 'Traffic Jammed', 'Take flight with the Pawn Stars when a letter recovered from the United Flight 736 crash gets delivered to the shop. Will Corey get the message or will it be returned to sender? Then, Rick examines some nozzles from the Queen Mary ocean liner. Can Rick float the deal or will he go down with a sinking ship? And later, when traffic is driving away business, Rick lets Chum take the wheel by finally making him a manager ... of the parking lot. Will Chum clear the jam or is he heading for a crash?', '2014-04-10', 21, '/aqzRwBfHbuojVMYWOPfKJ3WIrFL.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CE593B9E936942EEAB334E872E264EE2', X'D5383B3D56364D71B99CB84774B4B3C6', 3, 'Pingu the Mountaineer', 'Father is cleaning the motorized sled, and asks Pingu to go and find him a clean cloth from the shed. Pingu goes to look and isn’t having much success, but then he comes across an old rucksack. Inside the rucksack he finds a photo of Father and Grandfather in mountaineering gear, in front of a cairn of stones. Pingu drags the rucksack out, shows the photo to Father and asks if he can go up the mountain. Father initially says no, but then remembers how he felt about it and agrees, to Pingu’s delight. They get the gear, Pingu carrying the rope, and Mother waves them goodbye as they set off. Just as the reach the base of the mountain the trailing end of the rope catches between two rocks. Pingu tries flicking the rope in various ways to dislodge it, but it won’t budge. He then pulls on the rope as hard as he can. The rope finally comes free, and Pingu ends up sliding on his bottom right up to the base of the mountain. Father and Pingu rope up, and start to climb, with Father leading. Father is finding the going hard and starts to get very tired. He then realises that the reason he’s so tired is that Pingu has been letting himself be towed up by Father, and is not putting any effort into it himself. Father tells Pingu to do his own climbing. They come to an ice bridge over a crevasse and Pingu doesn’t want to cross. Father crosses and, after overcoming his reluctance, Pingu crosses as well. Father gives Pingu a hug, and points out how much closer to the top they are. When they reach the top Pingu is delighted, and can see their igloo in the distance. Father then takes a photo of himself and Pingu that’s similar to the one that Pingu found of Father and Grandfather.', '1998-01-07', 5, '/gAt4CCebI5Pwx8swGn1kVWmll6X.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CE5DE7185D4D44258564F767FCFF19D4', X'C73FA7F17AC644D4AC1F182A70D92313', 7, 'Too Many Peas, Too Many Plugs', 'When Dilys overloads a socket at the Cut Price Store and starts a fire, Mandy learns that every job on the Fire Rescue team is the most important job!', '2021-10-08', 10, '/pt4MQyMxQXm8KTAIzYADLkowaqc.jpg', '2026-04-03T17:14:41Z', '2026-04-03T17:14:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CE5E9B81E1374DCB83869864B5113C84', X'42684FCA0BC74F4CBF7DF41FD288A764', 2, 'Postman Pat and the Hungry Goat', 'Alf''s goat Rosie escapes, so Pat and Alf help to round her up but not she does a lot damage like eating the labels off Pat''s parcels.', '2004-09-08', 15, '/buZDIHAnxjdx8ggCyZAPJMqMfbq.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CE6BE77C5EC0486C9A22499ACFCC6295', X'ECB64EF34F8045A7B4A9C04434B02E35', 20, 'McKinley Family Jewels', 'Be dazzled with the Pawn Stars when Rick falls in love with a tiara that belonged to the wife of President McKinley. How far will Rick go to hide his affinity and acquire the First Lady''s fancy heirloom? Then, a Felix the Cat sparkler toy pounces into the shop. Can the cartoon cat get a laugh out of Chumlee or is he just kidding himself? And later, when Rick receives a secret package, everyone loses their patience. Will their curiosity get the best of them?', '2014-03-06', 21, '/1GgAnQhMOgf5lYP3vZBQtdby5en.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
