INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CE9CC6E456F442038EB5660A7E113754', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 115, 'Inside Looks (on The Caddy)', 'Inside look from the season 7 episode "The Caddy."', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CE9CD84DE2C14AF4A81794B747D55446', X'1A534647384B4C00BB6CA3371AD962EB', 7, 'The Smoking Gun', 'Join the revolution with the Pawn Stars when a Brown Bess musket fires its way into the shop. Will Rick hit the target with a deal or will there be a misfire? Then, Rick hits the books when Thomas Jefferson''s personal copy of Jay''s Treaty marches in. Will this piece of United States'' history cause Rick to surrender or will he fight his way to a deal? Later on, Corey gets rocked when a smashed guitar from KISS front man Paul Stanley comes by. Will Corey rock n'' roll all night or will he end up getting played? And later, Rick tries to snap Chum out of it when he''s bored at work. Will it be a historic victory for Rick or will Chum revolt?', '2015-01-25', 42, '/tZ9v16XdnwoiQYFMQUiA5XuUPcN.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CEA0A0E508D44F20A07795634403E8D7', X'D920EBAEF00A4E25ABFE40492C74DED6', 10, 'Ship Happens', 'Rick heads to Boston to check out an iconic warship. Will he sign for the USS Constitution, or will this deal sink his battleship'' Meanwhile, Corey asks for Help! when a Paul McCartney signed guitar Wings into the shop. Can he Come Together with the seller, or will he Let It Be'' Then, when the guys get a look at a curious corkscrew collection, will it have them popping bottles, or spiraling out of control'' Finally, when Rick gets a lead on an Apple 1, he has to decide if he wants a byte.', '2020-02-03', 42, '/3JzcUrPpbjo4BHPLYvA2uXuqPDM.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CEA16B6C1F954745A26D90F341D067EF', X'1CAFB2C3BBCB4172B02D441A5AAA155F', 7, 'You and I Together: A Visit with Koko the Gorilla', 'Rogers'' comforts a visit with Koko the Gorilla. No such warmth can be found in the Neighborhood of Make-Believe when a different gorilla visits. The lone exception is Lady Aberlin, who finds the gorilla tame.', '1998-08-21', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
