INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CEC5C2757BCB457891EAB98DCF0661C2', X'ACAC417E2AA342E79E08ED0D6071A3EE', 9, 'Holidazed and Confused', 'Carole and Bethenny continue to hash out their issues during the murder mystery dinner party. Back in the city, Bethenny''s holiday party is interrupted by a surprise, which leads to hurt feelings. At Luann''s blood drive, Carole is upset when she finds out that Bethenny has been talking about her behind her back. Then, Ramona confronts Bethenny on an epic sidewalk phone call. In a shocking turn of events, Luann gets arrested over the holiday.', '2018-05-30', 60, '/gKfZhheAHDtBdQpgw192Fi5DBQ7.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
