INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CF1D613E63D74FE5B2113DB2D9D1AACC', X'ECB64EF34F8045A7B4A9C04434B02E35', 1, 'Finding Fonzie', 'Get starstruck with the Pawn Stars when the guys check out an original poem handwritten by Marilyn Monroe. Will her words leave them speechless? Then, a hybrid rocket engine blasts in. Built into a suitcase as a sales sample, will the asking price for this oddity be sky high? And later, when Rick''s autographed Henry Winkler photo goes missing, he goes to great lengths to bring Fonzie home.', '2014-01-02', 21, '/aO8h8aTJSNPG86QMUu3GjKP9wr2.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
