INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CF28E6BD191C4AAB8927ECE2952D4CCC', X'38BF8C20C17C407192267887787CF1B1', 15, 'Trains and Brains and Rainy Plains', 'Lionel gets a brainstorm after he hears Bringing the Rain to Kapiti Plain.  What if he and Leona ride a train through the plain of the book?', '2001-04-20', 30, '/6bnJfFH4UHcyr9iIi5uK6p8SAh3.jpg', '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CF2B95ADE57F4306A65253D9443E36C9', X'095258D0D8DB40968AC76A42CD4CBDCF', 5, 'Blanket Of Snow, Blanket Of Woe', 'Mokey''s been making too many promises lately; most notably, she was supposed to knit a tarpaulin for the Trash Heap before the next big snow. But she ends up being too late, and when she sees Philo and Gunge mourning over the frozen Marjorie, she decides she has to fix her mistake. When she overhears the Gorgs need to throw out some yucky, hot soup, she along with the help of Gobo go into the Gorg''s castle to find a way to get the soup on the Trash Heap so she can thaw out.', '1985-01-28', 24, '/jpBa3ELExP6k3qYHW47CEeKUGJK.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
