INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CF6D484943C748DD974AAD7A3F999792', X'1BE79A20DE3341D1AF17079035B18D5C', 1, 'Gordon Introduces Sally to Sesame Street (0001)', 'In the first episode of Sesame Street, Gordon takes a girl named Sally on a tour of Sesame Street, introducing her (and the viewers) to the various characters on the show. On the street, Sally meets the human cast -- Gordon, Susan, Bob and Mr. Hooper -- as well as two Muppet characters, Big Bird and Oscar the Grouch.', '1969-11-10', NULL, '/49IucoIY5an8lBVLrTXddMExcqY.jpg', '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
