INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CF8BD70D996C4028AFDBFF96F57043D3', X'3087A3EDE94E42769D02A78183DEA1D3', 20, 'Divas into Icons', 'Now that Kenya has moved beyond Walter and the Battle of the Booties with Phaedra, she decides to throw a big party; everyone must come in assigned costumes to her Hollywood Icons gala. The ladies are all dressed to impress, but one rogue Housewife turns an evening of elegance into a full-fledged showdown and this time Kenya might have gone too far.', '2013-03-31', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CF9997C9714C43629BB66708E5E6A8DC', X'4DA606E79D2346828BD5F535E1DA706F', 12, 'Franklin''s Music Lessons', 'Franklin and his class were entertained by Mrs. Panda and her piano. This inspired Franklin and Beaver to take up piano lessons from Franklin''s Granny. He didn''t realize how practice can really be perfect until he noticed how well Beaver was playing the piano while he was out goofing off.', '1998-10-12', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
