INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CFA9279D36C74D84BBEB3B3C7B159382', X'1A534647384B4C00BB6CA3371AD962EB', 34, 'Pawn of the Jedi', 'Travel far, far away with the Pawn Stars when a draft of the original "Star Wars" script signed by George Lucas soars into the shop. Will Rick and Chum win the war for this obi-one of a kind piece or will the force not be with them? Then, Rick goes back in time when he checks out a terracotta medallion of Benjamin Franklin. Will Rick cash in on this patriotic piece or will he be frank in turning it down? And later, Chum wants to open a museum to display some of the shop''s hidden items. Will Chum be able to create a work of art or will Rick turn Chum''s plans into ancient history?', '2015-06-04', 21, '/lsQiitNHeG0ML85NnRUUL6CXHNd.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
