INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CFDB73123DC9493D96DE3E93E3D05136', X'671BD4DA347040F99A0340FBA34D2B8E', 19, 'Bat Out Of Heck', 'Frankie is surprised but relieved when Dr. Goodwin agrees to buy all of the peanut brittle that Brick needs to sell for school. But the good doctor displays a bit of Mr. Hyde behavior when Frankie doesn''t deliver the product in an expeditious manner. Meanwhile, Axl is getting sick and tired of having Mike tell him how to run his life; and things go off the rails when Axl attempts to trade in the Winnebago and buy a car. Sue is more determined than ever to win a very prestigious and competitive hotel scholarship; and Frankie swears that she''s seeing something mysterious flying through the house.', '2018-04-10', 22, '/9svqyvWLBXmrs6xxBjHZPaFwbjw.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
