INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CFE640C064774B2DABB4832E44FE4AEE', X'ECB64EF34F8045A7B4A9C04434B02E35', 21, 'You Snooze, You Lose', 'Battle it out with the Pawn Stars when Rick checks out a German two-handed sword. Built in the early 1600s, will he execute a deal for this antique weapon or lose his edge? Then, Corey steps up to the plate when a set of 1933 baseball cards slide into the shop. Will he score big or get thrown out of the game? And later, Corey''s noisy new neighbors are keeping him up at night. Will he find a quiet place to rest or become the shop''s worst nightmare?', '2014-03-13', 21, '/t883tO3qjCTWX7xU6Weln8J5GUF.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CFE64EFB169C4D2B8925A949863EBE3C', X'C5AE23D008DF4F18AF080CCC8FDEF868', 8, 'Like a Windy Day; Winter Is the Warmest Season', '', NULL, 30, NULL, '2026-04-03T17:12:30Z', '2026-04-03T17:12:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CFF2794119CF458BA9039FA87E1438C3', X'110E346736984E19A35BF6EBBAEB4D6B', 4, 'Cinderella', 'Cinderella is once again helped to the ball by her fairy godmother (this time played by the hilarious Jean Stapleton) as the story of Cinderella unfolds and how she loses her glass slipper-- this one has an amusing twist at the end -- that shows even fairy godmothers are vindictive.', '1985-08-12', 51, '/u58qqzJQlXis6dFO0F57UfLo300.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'CFF349C363434199A6DCA73719429D83', X'DE8EC76916BB436BBE43AEDC7E18A7D7', 24, 'Dog Day Engineers', 'Zoe and Rosita help Nina dog sit but their arms get tired after continuously throwing the balls. They don''t give up and keep thinking of a way to solve this problem. They figure out how to design a bike-powered ball-throwing machine they can pedal using their feet. They are two real engineers!', '2020-04-25', NULL, '/ySlhxTaYJhmLz4sGYIyDwZ89Kjw.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D001D114CD794C7795335C0042A8EE43', X'05C0E384194C44179F62803EB615E409', 16, 'Making things for others', 'Title number 0016. Opens with Mister Rogers arriving with lumber scraps and uses nails to hammer some of the pieces together to make a boat. In this episode, the puppet character Donkey Hodie appears for the first time. In the Neighborhood of Make-Believe, artist Virgil Cantini visits and shows King Friday some of his nail sculptures. Lady Aberlin knits a sweater for Henrietta Pussycat. X the Owl wants a gift too, so Lady Aberlin promises to knit him a scarf.', '1968-03-11', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
