INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D06174948EDC4680836D909A6EC670E3', X'F4C403079B5E4263A4E0DFA138131E7F', 47, 'The Best of Elmo 2', 'Join everyone''s favorite red monster for a fun filled story featuring some of the most popular Elmo segments ever! Elmo meets a robot on Sesame Street who is losing his power. The robot is a "Memorybat," and he needs "memories" to power up again. Elmo Gladly shares his memories of special times with his friends - singing about the outdoors with Jason Mraz, rhyming with Adam Sandler, reciting the alphabet with India.Arie, and counting to four with Feist. Elmo remembers even more fun with Destiny''s Child, David Beckham, and The Goo Goo Dolls. Will Memorybat get his power back? Every Elmo fan, young and old, will enjoy this story of friendship and treasure this collection.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
