INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D0BC9119B5EB4061B6BBEF12AC2488F5', X'BD5F5A3F07FA4689B67B02BE5D65F1B2', 19, 'Postman Pat''s Noisy Day', 'Pat is feeling very musical today. He keeps hearing strange and interesting sounds around Greendale.', '2006-03-07', 15, NULL, '2026-04-03T17:14:31Z', '2026-04-03T17:14:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D0C13E176E9A42EEB197F65891CBC139', X'050D8AE16CC14018933DB3C3D13DE856', 76, 'Episode 76', 'Remember the Los Angeles Olympics and the first flight of the shuttle? Pictures of events like these from all over the world are beamed live to our TV screens, thanks to the huge satellite tracking station at Goonhilly. Michael climbs the giant receiving dish to give aerial one a fresh coat of paint, and reports from the new Blue Peter aerial which starts work today. With luck its first pictures will be seen on today''s programme!', '1985-06-13', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
