INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D12BECD893224C08A92130A64164EF36', X'4D2CAC0F38FD438B8AFAACF43952E535', 38, 'Episode 38', 'A weekly programme for younger viewers.  Introduced by Leila Williams.  Special Brownie edition including a film "Brownie Stepping Stones" (shown by courtesy of the Girl Guides Association).', '1959-07-09', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D12C6A23EAD34F1DA0DDE0DD747DB1DA', X'671BD4DA347040F99A0340FBA34D2B8E', 21, 'The Royal Flush', 'In an attempt to get Frankie the best Mother''s Day gift ever, Sue and Brick enter a trivia contest where they could win a trip for two to London for the upcoming royal wedding; and Axl is offered a job interview that could change his life.', '2018-05-08', 22, '/uRqGMguiDiaokoNUzqX41wxuSUu.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D12E0E17417E43F0AD55702CFC96AE01', X'BF3FFAFD7D454F2C9F1B28001BD082DB', 44, 'Episode 44', 'with John Noakes, Peter Purves, Lesley Judd', '1975-02-10', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D139BE58BDBA46C9A941640C4CAA890E', X'B1D55597D9D24EEEAB9546DBB163291A', 18, 'Pingu''s Lavatory Story', 'Pingu and his family are eating lunch. Pinga opens her mouth for Pingu to put a piece of fish in her mouth, but Pingu ends up eating it himself, much to Pinga''s annoyance. Pingu then heads off to go to a bar type shop to get a drink. Pinga follows him and wants a drink too. Pingu buys her two, but when she drinks them, she tinkles on the ground and Pingu hurriedly sends her home; she makes it to her potty just in time. Pingu then finds he needs to go to the toilet, and rushes home just in time to see his dad go into the bathroom. He pushes Pinga off her potty so he can use that instead, and is sent outside, and he then in a rage plays doorbell ditch so that dad has to rush out of the bathroom to get it and Pingu can run in and use the toilet. He urinates on the floor because it is too high, however, father angrily tells him to clean it up. While finished and walking away thinking of an idea, he then attempts to go to the toilet on stilts, but Mother comes in and tells him that he can''t go in the toilet with them, Pingu explains to her that he can''t reach the toilet. Mother thinks of an idea and suggests they build some steps out of ice. They do so, and Pingu is finally able to go to the toilet in peace..', '1990-04-21', 5, '/wZtt8RKEnEincrnWAOwvIZQ5TOx.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D146906AAE3746AB94D36968C1D278B1', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 83, 'Luis cleans up Big Bird''s nest', 'Luis has a board with three drawings of animals on it. Luis discovers the mess in Big Bird''s nest, and he decides to clean it up himself to show Big Bird he cares. He comes across a glued mass of craft supplies, and throws it away assuming it''s trash.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D14C1CD434E74DA1A74F5655773B0F7E', X'56428E5E7DAA468D8BD2076956507AA8', 10, 'Heat', 'Things sure are heating up at Nye Labs. Snow cones, flowers, hot dogs, people -- everything is made of molecules. No matter what they''re in, solid, liquid, or gas, molecules are always moving, even if just a little bit. The speed of the molecules depends on their temperature. Cold things have slow-moving molecules, while hot things have fast-moving molecules. In fact, temperature is really a measurement of molecule speed. For a cold thing to get warm, its molecules have to speed up. Heat moves in three different ways -- conduction, convection, and radiation. Conduction is the flow of heat between two solid objects that are touching. Heat conducts from your warm fingertips into a cold can of soda. Convection is the transfer of heat with a liquid or gas. A hot bath feels warm all over not just where you''re sitting.', '1994-10-01', 26, '/9sv5uK3d81DeJAco6wgVE7GFzCa.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D154B3620BC5424F872442A276BFE3DD', X'3EA743EF0A2247CFB1D262F37E939253', 12, 'Copier at Mail-It Shop Is Broken', '', '2002-02-19', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D154D10CF59A4A6AB87DF8F70F916738', X'E40E6B639F84449F8E8853209B0906C8', 4, 'Lucy the Lazy Lizard', 'Maria welcomes the viewers after a piece of toast flies in her face. Elmo stops by, and asks Maria to read him a story. Maria points out that she''s already read that book to him ten times. Elmo replies, "Let''s make it eleven!" Maria finally agrees to read Elmo his book, Lucy the Lazy Lizard - a book with a lot of L words in it.', '2007-08-16', NULL, '/i0zjQC3p7w5sQhygQjiQahRYHny.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D159FA88876D4647AF293526D936D5CF', X'4D2CAC0F38FD438B8AFAACF43952E535', 17, 'Episode 17', 'Toys, model railways, games, stories, cartoons. A weekly programme for younger viewers with Christopher Trace and Leila Williams.', '1959-02-05', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
