INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D17995816892433C9BDEA1E9B62D249B', X'95CA8B6FCCBC431A9D959B23367BBFED', 23, 'Reunion (3)', 'Kyle and Kathy discuss the years they spent apart and their eventual reconciliation; Crystal reflects on her struggles with Sutton and the heartbreaking racism she encountered in the past year.', '2021-10-27', 43, '/jjBRhtt2650GZEeoVLYbc40fQSc.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D1844FEA583D4ED4BC7DEE9633FECA0E', X'5144DE59E67F4FCF919B7106989AB797', 8, 'Rock Dreams', 'Skye aspires to perform music, but is discouraged by the fact that he doesn''t know very many Native American performers. Eventually he makes contact with Native American Robby Romero and his band, Red Thunder, who reassure him. Nuzzle gets so tired of watching Sizzle listen to Swiss yodeling music that he tries to make her yodel herself.', '1995-01-25', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D18E1D38D67C48F0A51B3AEEA1EFE206', X'1C9EA7D3E2544E7B8A9F33EEA9C6C341', 14, 'Lions and Tigers and Shade', 'Cynthia and NeNe finally sit down to try to work through their differences; NeNe invites the ladies to a jungle themed brunch, but things do not go according to plan when some guests leave early while others show up unannounced.', '2020-02-16', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D192615809D04723B752D41474E52B05', X'941B8C6544544336BE7C1D0591C12F90', 3, 'Pingu Digs a Hole', 'Pingu comes out of the igloo with Father, to see him off to work, and they find the sledge covered by snow from an overnight fall. Father digs it out, but leaves the shovel behind in the snow when he goes. Pingu decides to try it out and digs a hole right outside the front door of the igloo. Mother comes out with the washing and falls into the hole. While she’s getting herself out, Pingu sneaks off so that she doesn’t see him. Pingu then meets Robby, and they dig a hole together. Soon they are tunnelling around the neighbourhood, and the fishmonger can’t understand where a crate of his fish has gone or why he’s sinking into the ground. Father returns home to collect the rest of the family for a picnic and finds Mother, with Pinga, outside the door where the hole has appeared, but there’s no sign of Pingu. They walk off, calling Pingu. Pinga, who is lagging a bit behind, then gets picked up on the crest from the rapidly growing tunnel, and she’s deposited on the ground in front of Mother and Father. When they catch up to her they can’t understand how she’s got in front of them. Father lays out the picnic but the tunnel arrives and stops right under the cloth. The picnic sinks into the ground and Pingu and Robby surface, Pinga, Mother and Father find out and Father yells angrily at Pingu, closely followed by the fishmonger who is not at all happy. Pingu and Robby fill in the tunnel and recover the crate for the fishmonger, and he gives them both a fish. Pingu then tucks into his fish at the picnic, which is now being held back in the igloo.', '2003-08-15', 5, '/zAeovBoFaWKjXEG73LBs5EqqdSe.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D1A2D3D3413D42B883953AF3A14305CB', X'E03D79BDE01F4414B0B3F3B5F26E97F4', 20, 'Royal Wedding', 'Frankie gets swept up in the excitement of the upcoming royal wedding. Meanwhile, Mike has to make a few layoffs at the quarry, and Brick helps Sue with her audition for the school news team.', '2011-07-22', 22, '/a1qYxZVFVf5Tj5y13xcptvP26mi.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
