INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D1A64C9FDF184EB48ACA1BE5606384B0', X'FC52608BB1C941C5B3CA2A7FF35BCABC', 2, 'Rich and Famous', 'Dilys wishes she were rich and famous, so goes off to do some treasure hunting in the attic. But she gets more than she bargained for when she knocks over a candle, setting the roof on fire...', '1994-10-27', 10, '/n4PFFhdc0i8b6b1sKpaFgWB9ig5.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
