INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D1DBF06D987149BC81D0C8D754DFB2B8', X'6EF86C2733E747E5A053483059DFD16D', 50, 'Episode 50', '', '1982-03-08', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D1DD7BB86A5D48219DB0193DEE6501E0', X'97A3D1F5A8F147CD81222E74A092836D', 22, 'Don''t Stop the Music (2)', 'As the team starts rehearsing for Lenni''s video, strange things start happening. The lights go out, someone puts glue where their feet are going to be put and a wireboard short circuits. The team realizes that whoever is behind the sabotage must be working on the video. Leif isn''t upset with the glue. Sonia wants to use the accidents for publicity. Ghostwriter reads a letter to David from Marlon Campbell, the same guy who tried to bribe Lenni to work for him. But, David says that he doesn''t know Marlon. Casey Austin, Jamal''s cousin, sneaks into the studio to spy on Jamal. Jamal and Gaby read an article that years ago Leif and Jade used to be lovers. Leif was in show business with a few hits but when he dropped Jade broke up with him and he hasn''t forgiven her. They hear a noise and thinks it''s Leif running away scared, so they decide to surround him but instead find Casey.', '1994-01-30', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D1DE57C1332348BCB297CEB50AA14A94', X'E40E6B639F84449F8E8853209B0906C8', 15, 'Big Bird, Elmo & Abby, Song for 3', 'Big Bird and Elmo are excited, because they''ve got a special song for two friends, which they are. They count each other, and sing "One and One Make Two." They almost sing it again, when Abby Cadabby appears in a poof, and asks to join them. Suddenly, Big Bird realizes the song won''t work this time, because it''s a song for two, and if Abby joins them, they won''t be two anymore, but three. What to do? Abby suggests making herself disappear, but that turns out to be not such a good idea. The three friends decide they should ask Gabi what they should do. They explain their predicament, and Gabi suggests they sing a song for three instead of two. What a great idea!', '2007-09-14', NULL, '/nHb9qI6y1KCGfEXMGnNUa2zt11A.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D1E0B19AE9134119AC22842876256D74', X'5062CE298DBB48AB879B0771221678D5', 4, 'The Rabbit Who Was Afraid of the Dark', 'Rabbit has become afraid of the dark, and the others don''t know what is causing it, but Percy does - she hasn''t been eating enough carrots! She then eats some more, and is then able to see in the dark, and is not scared anymore.', '1999-10-10', 15, NULL, '2026-04-03T17:19:02Z', '2026-04-03T17:19:02Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
