INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D200A9565C584EC48823198E48A79AAA', X'45E64A158FC04E4BA1CA9E3F42F3634D', 13, 'Garbage', 'Garbage is a look at two different kinds of garbage -- biodegradable and non-biodegradable. Nye emphasizes the importance of recycling and cutting down on the amount of the waste that cannot break down. The music video "Recycle" has a familiar melody, taken from "Respect," the Aretha Franklin hit.', '1993-12-03', 26, '/4qrryEbUWqPzEA73cJ9XtzeCwPu.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D2074202B2804FD58311AC87F57DF2BC', X'F9A8D8B3D72E437EA9D57477F6D64DF8', 18, 'Art Rocks!', 'Elmo, Abby, and Big Bird are painting pictures in the community garden, but they don’t have any paper. What if they paint on rocks that are strong and smooth? Let’s try!', '2023-03-02', 25, '/qplJGon15Xx6UtzIMfWb4Hhkyop.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D20EA53CD9A34AA48E866AAEBC9C714A', X'95CA8B6FCCBC431A9D959B23367BBFED', 7, 'Defining Women', 'With rumors swirling about her divorce, Erika reveals new details about why she left her husband. A group outing on the town goes up in flames when Kathy unintentionally reignites a dying spark. Meanwhile, Lisa Rinna confronts tabloid rumors of her own, Dorit adds a special piece of art to her collection, and Garcelle’s son has strong thoughts about her love life.', '2021-06-30', 43, '/2W6pgSqOicqIdQwC8vZVaEejTdp.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D210CA84F7DA492E990A63A5EF8CE848', X'4C79C0B621A442778967BE1E791EFDBE', 19, 'Pingu and the Daily Igloo', 'Pingu has found a leaflet advertising for a paper boy, brings it home and persuades Father to let him do it. Father takes him to the paper shop and Pingu goes inside to get the papers. When he comes out with them he can barely lift the box. Father offers to help but he wants to do it all himself and loads them onto his sledge. Father shows him how to fold the paper to get it through the letterbox, and he sets off. The first one he tries to deliver he gets all crumpled trying to get it into the letterbox, and also traps his fingers. The next one he has to deliver to Punki, and he has to try three times before getting the correct paper. On the way to deliver the next paper he passes Pingi, who is in the playground and wants a partner for the seesaw. He’s just about to join her when Father comes by and tells him he’s taking too long to deliver the papers. He leaves Pingi, and delivers the next paper at speed as he whizzes past the igloo, tossing it through an open window. It lands in a washing basin, soaking the penguin using it at the time. The next one is delivered in the same way, but this time it lands in the loo and surprises the penguin who is in the nearby bath. The following paper is delivered to Grandfather; Pingu gets this one in the bowl of cereal that Grandfather is eating at the time. He continues in this manner, and when he gets back to the paper shop dumps all the papers he hasn’t delivered into the bin outside. He goes to find Pingi at the playground, but she has gone. When he gets home he’s aghast to find a queue of angry penguins at the door, returning their papers and complaining to Father about the delivery service. Pingu feigns innocence. Mother and Pingu then clean up all the returned papers, with Pingu putting them through the mangle, Mother ironing them and Pingu folding them. Father then takes him out on the round again to deliver them properly.', '2006-02-22', 5, '/i6Vfos3C3f361tS4iIzkyJPYOem.jpg', '2026-04-03T17:22:21Z', '2026-04-03T17:22:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D215057AA4B64B62A9193DA9F81D2534', X'EBC99729CCB74D6482C142708CD7BA85', 74, 'Episode 74', 'Pot Black!  Sarah tries her hand at being a chimney sweep''s assistant when she joins Dodd Diggins of Framlingham in Suffolk. Dodd has been cleaning chimneys with brushes for 50 years and says '' You can keep your modern methods''. The Rev Valentine Fletcher collects chimney pots and his prize exhibits range from 18th-century giants of six feet to mere midgets with fluted edges, which he says are the rarest.', '1981-06-04', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D2179977FF504FE0914B7F03A29A4D30', X'D5383B3D56364D71B99CB84774B4B3C6', 2, 'Pingu Refuses To Help', 'Pingu and Pinga are in their bedroom. Pingu is reading, and nibbling on some cereal in a bowl, while Pinga plays with the bricks. Mother is in the kitchen, feeling a bit harassed. First the washing machine finishes, then the phone rings and then a pot on the stove starts to boil. She calls for help. Pingu ignores the call. Pinga responds and goes to the stove, but she’s too little to do anything about the pot. Mother comes over, sorts out the pot and then she and Pinga go to the washing machine. Mother unloads the washing into the basket, and calls to Pingu to come and help, but he doesn’t respond. Mother goes outside with Pinga. She’s just started hanging out the washing when Father arrives home. He greets Mother and Pinga. Mother tells him that Pingu’s not being very helpful, so Father goes to speak to Pingu about it. When Father reaches the bedroom, the door is shut and locked. Father bangs on the door and calls to Pingu, who just ignores it and continues with what he is doing. Mother, Father and Pinga confer, and then leave Pingu to it. Pingu finishes his bowl of cereal and decides he wants some more. He goes to the door, opens it, checks that the coast is clear, then goes to the cereal packet and puts some in his bowl. He then wonders why it’s so quiet and goes to look outside. Mother and Father are hanging out the washing, watched by Pinga. Feeling a bit left out, Pingu goes back inside. He checks the washing machine, and finds a small cloth that has been left behind. He rushes outside to give it to Mother, but she, Father and Pinga all ignore him. Pingu tries to get their attention, but they all turn away and go inside. Pingu looks inside, and sees Mother giving Pinga a heaped bowl of cereal. He disconsolately trudges back outside. The washing on the line starts to judder, and the line frays and then breaks. Pingu grabs the broken ends of the line, one in each hand, just in time to prevent the washing from falling to the ground. He struggles to keep his grip, and moans with the strain. Pinga hears him and goes outside to find out what’s going on, then rushes back in to tell Mother and Father what’s happened, but it was too late. They rush out and Father repairs the line while Pinga tries to cheer Pingu up. Mother then cheers Pingu up by giving him a big hug.', '1998-01-06', 5, '/eSaS0KBTI4wWffv3WdxtXQb34Z4.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D2204346D21349B3A4EA258F4A9A0F5B', X'ECB64EF34F8045A7B4A9C04434B02E35', 33, 'Road Test', 'Travel back in time with the Pawn Stars when a guitar that belonged to The Who''s bassist, John Entwistle, strikes a chord with Rick. Will his nostalgia for the band cause him to shell out big bucks for a piece of his "generation" or will he not "get fooled again"? Then, Rick and Lili get the presidential treatment when a customer brings in a Richard Nixon paper dress. Will this campaign outfit dress to impress, or wear out its welcome? And later, the guys decide it’s time to put the Old Man''s driving skills to the test. Can he prove to them once and for all that he’s the king of the road, or will his license to ride expire?', '2014-04-24', 21, '/5Sh4q8775D13lAylCQ9ygaORG9q.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D22448C623DE445399EAFA0962DF9AB3', X'740A96A0A0754BE2BE92A178D0939384', 14, 'Chinese New Year', 'It''s Chinese New Year on Sesame Street! To learn how some people celebrate the holiday in China and around the world, Nina helps Elmo, Abby Cadabby, Cookie Monster and Grover build their own dragon costume. (Guest: John Legend).', '2018-02-17', NULL, '/3iZ0ZhfGQpYw8QZoZBj5LFEiEM0.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D2299EF852BB4A9999868FA6EA798693', X'136B81D3964D4B8FA21492F00D96D6B9', 117, 'Hooper''s has a broken window', 'A window at Hooper''s Store breaks and the community comes together to fix it efficiently. Luis takes charge of the repair while others watch and learn about the maintenance process. Once the window is fixed, everyone celebrates the restored and beautiful storefront.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D22A364DCBDD48C78A188A4AAC57D6DC', X'70CAC5CAFB7F4CB78C9B004D44124A1D', 12, 'Ain''t No Misbehaving', 'Teresa models in a photo shoot for her upcoming book; Dolores takes her son Frankie on a college tour; the Gorgas prepare for their restaurant opening; Teresa and Melissa go head-to-head over a business decision; Danielle receives some closure.', '2018-01-03', 43, '/yDIo8I02ATmYWosbcRFqYT9XgUs.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
