INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D22E62D08EE347A19901C1D3BA915E2B', X'5C1B881FAC584D72B63F209952D4F902', 35, 'Episode 35', 'In the Swim  Chris spends the day with Britain''s 800m Women''s Freestyle record holder, 14-year-old Jackie Willmott from Southend. Jackie swims a gruelling 10,000m per day and starts her training at 4.30 every morning - going on till after dark with lessons squeezed in between. Will all the effort pay off? Watch the 1980 Olympics to find out!', '1980-01-10', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D23336B9BA0C48989FE47947FDC8BFFF', X'04572E48BBFD476BAEBEB6DC424F742D', 5, 'Turn Your Back', 'As a powerful mage joins the hunt for Ciri, she cuts a deal with Vesemir over his extraordinary discovery. Geralt explores the mystery of the monoliths.', '2021-12-17', 58, '/xPytQd9tDAxDoECXbNwbeR3Fi2h.jpg', '2026-04-03T15:40:45Z', '2026-04-03T15:40:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D2392A278D6A478DAA0425F2AC862755', X'B8C1B631985045F39361CDAD5571A492', 1, 'It''s Over', 'Janelle tests positive for COVID-19, and Kody confides in Robyn about his troubles with Christine. Then, Kody and Christine sit down to have a tense discussion about the future of their marriage, which leaves Christine feeling empowered and Kody defeated.', '2022-09-11', 41, '/1NtLYTgSPv90pV7elsXt5NvMVNI.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D23B89BB4A714DC6AF0C9937E3D5D39F', X'5C4E51C6E20746AD875C72988EB1E13E', 5, 'Not On My Watch', 'The Pawn Stars become a house divided when a Confederate Civil War knife marches into the shop. Known as an "Arkansas Toothpick," will the guys sharpen their tactics to take a stab at this rare piece or will a tough negotiation leave them licking their wounds? Then, Rick and Chumlee are presented with a 1936 Rolex formerly owned by infamous con man Bernie Madoff. Will Rick give this watch all the time it deserves or will one false tick cause him to lose his shirt? And later, the gang checks out something that''s right up their alley, a 1950''s arcade bowling game. Will they prove it''s all in the wrist as they strike up a deal or does this vintage machine belong in the gutter?', '2011-04-18', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D24032A16CD44D4E9DEB459C0F07242E', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 42, 'Episode 2137', 'Forgetful Jones explains to Maria that he’s labeled all his body parts so he won’t forget them, but she points out that he’s labeled them incorrectly (“Hubba-wha? She puts the "nose," "ear," "cheek," and "finger" labels in the right places, but Forgetful lets her have his spare “nose” Telly wants to play catch with Oscar, and knocks on Oscar''s trash can twice.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D244A1AFB3B64553BC70729019996D46', X'C7994637B7C742C7AAEE1BFF4144FE23', 14, 'Aches and Spains', 'Hearts are racing after Crystal''s medical emergency, but nurse anesthetist Annemarie comes to the rescue. Dorit opens up to Garcelle, allowing the two to finally move forward. Disappointed in her friends, Erika gets tipsy ahead of dinner but wows the group with her erudite observations at the table. While planning her healing ceremony, Sutton is overwhelmed by old emotions, forcing her to find comfort in an unlikely friend.', '2024-01-31', 44, '/eUtVHuvnEnRgCvXAkfyB3EeNZIy.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D245D9A23AB44714876DAC95CA3DBB97', X'4F18AC4C8757456CA49A224F00E6A9F7', 25, 'The Help-O-Bots', 'Chris welcomes the viewer and counts the pies that were just delivered (counting 17 pies total). Elmo, Telly and Rosita rush to him and ask him to read a book to them. Chris begins the book, which is about a helpful robot named Rico who loves to help en la manana (the morning), en la tarde (the afternoon) and en la noche (the night). After the story, Chris goes back to work and remarks a robot like that would be of good use to him, which sparks an idea in the monster’s heads.', '2008-11-05', NULL, '/lSQwHu4y3oWEkPTyDvS6GrZOlLg.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
