INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D26901C9A0D4437DAD92D6015AC19B31', X'D920EBAEF00A4E25ABFE40492C74DED6', 15, 'Pawnsplosion', 'When given the chance to drive a WWII tank, Rick says Sherman, but will he go to war to own this piece of history'' Meanwhile, two is a party, but three''s allowed when a Triplet Bicycle rolls in. Then, vintage toy soldiers march into the shop. Will they get Corey''s attention, or retreat'' Next, Rick and Corey are visited by Haunted Mansion memorabilia. Will they possess the spooky souvenirs or cast them out'' Later, things get HOT when Chum finds a flamethrower. Will he fire up a deal, or get burned''', '2020-03-27', 42, '/yhkzKkgLXJFQg3yTmWZCKuYMoYh.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
