INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D26C2DF9E5CB4927B2CF83B2E067CB58', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 26, 'Stamp Stumped', 'Call it heads or tails, when Rick flips around a few gold and silver coins that come into the shop. Will he buy them all or call it chump change and walk away from the deal? Also, Corey is a bit stuck on whether some odd tax stamps are even worth the paper they''re printed on. Later, Chumlee is hoping everything is gonna be alright when a signed Bob Marley album comes in. Will he be jammin'' out to a big sale or will it be no deal, no cry? To round out the offerings, Rick considers taking some concertina lessons and a vintage Win-a-Card game could be Topps for Corey.', '2017-08-07', 21, '/xboa2DorTAqc2kP3YInTzWLoIXG.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
