INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D28C026015274868B0B96BEA744EEB93', X'227B84290DFD47E4B874C37DA20C403F', 12, 'Plane Crazy', 'The Pawn Stars travel back in time over two centuries to colonial Boston but is this seller''s map the real deal or will the guys tell him to take a hike. Meanwhile, Chumlee''s purchase of fake art leaves Rick painting him a different sort of picture. Then will the Pawn Stars finally get their wings by buying the shop''s first ever plane or will excess baggage keep this aircraft grounded.', '2009-09-13', 21, '/h24J5ihR0MaENRzW6aNJq29qnBf.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
