INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D2915D4B92634ED3BC65FB31592F87C1', X'DF77DBA2BBDA4F3897138D5C856F852E', 11, 'The Winter Picnic', 'One cold morning Old Bear decides all the toys should go for a picnic. They pack lots of hot food, wrap up warmly and pull the picnic basket to the top of a hill on a little cart. After enjoying the food and playing lots of games they realise how cold they are and climb into the basket to keep warm. Imagine their surprise when the picnic ends with a rather bumpy, and very exciting, journey home.', '1993-12-12', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
