INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D2C0CF5845554E5A91C0281E8A2F87C9', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 117, 'Snuffy imagines himself as a cloud', 'Mr. Snuffleupagus imagines himself as a fluffy white cloud floating in the sky. Through his imagination, he experiences what it would be like to be weightless and free. Big Bird shares in this fantasy, exploring the possibilities of cloud living with his friend.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D2C7DB2BD38D4B60AD441179C52C388E', X'F13CB62284E34654A8F10CEAB09A9CA6', 12, 'Franklin''s Reading Club', 'Mrs. Goose at the Woodland library announces a summer reading contest to Franklin and his friends: anyone who reads thirty or more books will receive a nifty reading club t-shirt. Franklin and Bear like the look of the t-shirt and decide to try and read really fast so that they can get their t-shirts before anyone else. When they find that their friends are getting great enjoyment out of reading, while they can''t even remember what they read, they question the wisdom of their idea.', '2002-06-03', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D2C9C768DB5A485797A5050C7CB6F3E6', X'68138DE20900460AB58E480688F1E081', 20, 'Tutter''s Tiny Trip', 'Last night there was a big storm, but today it''s a warm, sunny day outside, so Bear and the kids have decided to go swimming out at the Otter Pond. They''ve even come up with something tempt Tutter out of the Big Blue House and into the water --- a floating chair that even includes a place for him to put his cheesarita. Everyone goes outside for some summer fun, but they find that the pond is covered in debris blown in by the storm --- leaves and branches everywhere. They all work together to clean it up, but then it starts raining. Tutter scatters at the first sign of rain. Pip and Pop want to stay outside, but when the lightning comes, in they go. Inside, Ojo and Treelo find themselves bored, until Bear gets their imaginations going for a weather-filled trip to Ojo Island. Pip and Pop despair the rain, but learn that without the rain, they could never have fun at the pond. Then, once the rain stops, Ray provides a special surprise for everyone. In the Shadow segment, Shadow tells a story of a robin who manages to have fun even in snowy weather. 
