INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D302A45B6E5441D2963CBBD9DD89BD79', X'151E88A195764BD1B84AC4D64C1C9FE8', 10, 'So You Say', 'As Sutton''s garden party finds itself in the weeds after Lisa''s outburst, Erika seeks forgiveness from Garcelle for her past indiscretions. Meanwhile, Crystal gets involved in Sutton''s love life and Kyle is left reeling by an accusation she does not agree with. Dorit finds comfort in Hanukkah traditions, but a frigid lunch has Diana feeling anything but the holiday spirit.', '2022-07-13', NULL, '/anIWLDwkiqtnrQlsD148BcWpapP.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
