INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D3089299C83D4FEF95C83E0FCF920272', X'A8C6182E05E14B6891A55126CF6C94F0', 4, 'Liberty or Death!', 'James, Sarah, Henri and Moses travel to Virginia, where they witness Patrick Henry''s speech. Moses is shocked to find his brother Cato on the slave auction block and risks his own freedom to rescue him. Cato sees hope for himself in Dunmore''s Proclamation and in the end leaves his brother to seek his own path to freedom.', '2002-09-05', 30, '/uEB90yIicnfziCTjPasAX7GyiE.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
