INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D3368E02385041C3AF96DD24BF558F85', X'4F18AC4C8757456CA49A224F00E6A9F7', 19, 'Sesame Street Bird Games', 'Chris and Alan close Hooper’s Store, welcome the viewer and plan on going bowling. However, their plans are put on hold when they hear a fanfare and Big Bird shows up, announcing the “Sesame Street Bird Games” and tells them they’re the judges. A penguin adviser arrives and hands Alan an envelope with the game’s rules. He also gives them their judicial headgear. Alan questions why they must do it and Big Bird points out that it will be fair if non-birds judge the events. The other two contestants arrive (a chicken and a duck), so the games can now commence!', '2008-10-20', NULL, '/8MBqVqPhu2PKLV2iIfn2RpMQyhV.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
