INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D39493A75C544A608AFCDE027B6CF69A', X'3EE646E823AE4DECBBC6C7E6A210D55B', 81, 'Experiences with the sky', 'As the sun shines, Big Bird plays with his shadow along the construction door wall. He wants to introduce it to Gordon, but Gordon points out that because of a cloud covering the sun now, his shadow is gone. Big Bird assumes that the shadow has left because it''s upset that the sun is covered.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D394A8446B474AAD97F5B032A5011433', X'A84AA42DE73840818DA91FAEC0209EE9', 1, 'Pilot', 'Meet the Hecks – an ordinary family struggling to survive each other and life in Middle America. PATRICIA HEATON stars as a working mother whose family life is one big happy mess.', '2009-09-30', 23, '/vgJsLMwGHWLEoOZB6qOpn2TLB4Q.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
