INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D3AF0462705C4BB19C02ADBC65E603EE', X'A84AA42DE73840818DA91FAEC0209EE9', 7, 'The Scratch', 'Frankie must create the illusion of a picture-perfect family when an accident causing a small scratch on Brick leads a social worker to visit the Heck household.', '2009-11-18', 22, '/xe4IwKJJ3e0QOL8pUuQsAeqZUHv.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D3B5977F19454FE2BC4BABEEFC021071', X'3269A890BBA94E6C9278F7EB38EB1720', 1, 'Planets & Moons', 'Each planet is different. They are all different sizes – Pluto’s the smallest, and Jupiter’s the biggest. They come in a variety of colors – Mars is covered with rust, so it looks red; the methane (cold natural gas) in the atmosphere of Uranus makes it look blue; and Saturn’s colorful rings are made of icy rock. As far as we know now, Earth is the only planet in our solar system that is home to living things.', '1995-01-14', 26, '/skQcEBJInzVFqXhOX33ZNNwHy2R.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
