INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D3B76022033041A7B105B77715B3E393', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 87, 'Telly prepares to visit Granny Monster', 'David procures 12 ping-pong balls for Telly. He asks why Telly would need so many, and Telly begins his lengthy explanation: he''s going to visit his Granny Monster, who has a ping-pong table at home. Telly needs a suitcase for his trip and David has already gotten him a big one, but it''s not big enough. David appears with a bigger suitcase, which still isn''t big enough.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D3C058620EEB4A409B4EC1D0A6516B19', X'136B81D3964D4B8FA21492F00D96D6B9', 104, 'Grundgetta meets astronaut Sally Ride', 'Astronaut Sally Ride visits Sesame Street and meets Grundgetta, sharing fascinating stories about being in space and exploring the universe. Grundgetta is captivated by tales of rockets, weightlessness, and cosmic adventure. Sally Ride explains the training and dedication required to become an astronaut.
