INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D42C2BCBC896484EABB15D4BD4474DFE', X'EA1650C2E4F146C793BA74B5D45D08E5', 4, 'Petty Boughetto', 'Despite the toll her marital problems and troubles with Bryson are taking on NeNe, she is determined to get her "happy" back, even if that’s through plastic surgery. Phaedra and Cynthia finally find time to get to know each other better as they attend Atlanta''s premiere horse racing event, the Steeple Chase. Inspired by a late night host, Kim is ready to be a two-hit wonder and asks Kandi to write her next song. Dwight helps Phaedra plan her over-the-top Kentucky Derby-themed baby shower. Kandi, Cynthia and Kim quickly realize this shower is unlike any other shower they''ve ever attended.', '2010-10-25', 43, '/7pev8Ynnkn1s5uydtLCD1iNVLRI.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
