INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D4371C03057F4673946E272E7AF46850', X'3269A890BBA94E6C9278F7EB38EB1720', 7, 'Water Cycle', 'About 70% of the Earth’s surface is covered in water, and almost all of that water has been around since the Earth formed billions and billions of years ago. That means a glass of water you drink today could be water that a dinosaur once sipped. Water is constantly recycled on Earth as rain, snow, sleet and hail. It makes its way in and out of oceans, lakes, streams, hail, and glaciers. Scientists call the recycling of water the water cycle (not that bad, huh?).', '1995-03-24', 26, '/a8yNGYQHai9VvVUg7rKhrY3cDVp.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D43BFE8766014EBE89D9C5D5998CBD19', X'68138DE20900460AB58E480688F1E081', 1, 'Ooh, Baby, Baby', 'Grandma Flutter drops her granddaughter, Baby Blotter, off at the Big Blue House while she goes to her dance class. Bear helps Tutter learn how to care for a baby -- but everyone''s at a loss when Blotter starts to cry. The day is saved by Treelo, who comforts the baby and gives her his rattle.', '1998-06-08', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
