INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D456269FCF8D4706B2CB7E4788E222BE', X'015CCEB30A474F26A68381A4696951F0', 8, 'Postman Pat and the Greendale Rocket', 'The children set off on a school outing and are very excited when they discover Greendale''s old forgotten steam train, the Greendale Rocket. Everyone volunteers to get the Greendale Rocket back into action. Pat and Ted try to get the engine working again. Will it work again in time for the grand reopening?', '2003-09-06', 25, NULL, '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D457A72CFFC34912AEF9CCA8327D46DB', X'EA73E13C696248048305C303DF65F89F', 36, 'Shoes and magic', 'A Wizard enters the Neighborhood of Make-Believe to find Lady Elaine Fairchilde. He plays games and then stubs his toe, prompting Dr. Platypus, who also meets King Friday for the first time.', '1969-03-31', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D45B8277A09C40949193A06576ADFA2B', X'18DA994319634E04A7A0AE63802BB1FA', 18, 'Femme Finale', 'Emily plans a Femme Fatale party for the ladies, as her mother, Susan, visits Orange County for the first time in five years; Shannon has a very adult conversation with her 16-year-old daughter, Sophie; Tamra and Gina try to hash out their issues.', '2018-11-19', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D464DC8553C04F0C96549C21DE24A904', X'98D80972E53A43DDA03A7703465E6F87', 23, 'Comic Con', 'Fly high and aim low with the Pawn Stars as they check out a Japanese machine gun camera. Used to train fighter pilots during WWII, will the guys have the skills to keep this deal on target? Then, Chumlee and Corey take a look at some sketches drawn by Spider-Man creator Stan Lee. Known as a writer, but never an artist, are they legit, or a web of lies? And later, Rick and the Old Man eye a $1,000 Federal Reserve note from 1918. Will they fork over a stack of hundreds, or is this G note past its prime?', '2013-02-04', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
