INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D47338873BA1491EA9E5D4BF3A549814', X'BB5A884361814A6DBFDF33EF2C6BE7B8', 13, 'Livin'' La Villa Loca', 'The ladies'' arrival in Barcelona gets off to a bumpy start when Cynthia confronts Eva and Porsha about the tea they spilled concerning Will. Cynthia''s hosting duties are questioned after the ladies arrive at their "villa" and things heats up between Marlo and Kandi when shade is thrown at the group dinner. Back home in Atlanta, Kim gets wind of a joke made at her expense and all of the ladies are shocked by her next move.', '2018-02-18', 43, '/2nLR31KuZqurHmF48Bn9FBTSoTr.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
