INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D4C1786410CB4A118612C0D4DCA4FE86', X'65F5ABC80C59497B86E58C6165EE480C', 12, 'Where''s Copenhagen?', 'Cary invites all the ladies to join her for a trip to Denmark; LeeAnne goes wedding dress shopping; Stephanie and Travis renew their vows; D''Andra hosts a pop-up event for her company, during which Brandi finds out what LeeAnne called her.', '2018-10-31', 44, '/ddM7Wgmdamlll8AfpRWZpMTZnR8.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D4C1DEDA817349A78483A2EDA1061727', X'98D80972E53A43DDA03A7703465E6F87', 9, 'Sweet Pawn of Mine', 'Kick off your shoes with the Pawn Stars when Rick and the Old Man are offered a pair of slippers owned by Pope Leo XIII. Considered one of history''s most influential popes, will the guys have a prayer of making a deal? Then, Chumlee and Olivia are working the night shift when a guy brings in a driver''s license owned by god guitarist of Guns N Roses: Slash. Is this rock memorabilia worth waking up Rick? And later, the Old Man''s 20 cup-a-day coffee habit sparks a family intervention. But can you really teach this old dog a new trick?', '2012-11-26', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
