INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D4ED454290854726B318E982D8407B29', X'119C16D5104745EC8242C72A8EED423B', 12, 'Arthur Accused!', 'Arthur had a job to collect coins for Mrs. McGrady to raise money for a new dog for the Elwood City firemen, and when he left the bag of quarters where Mrs. McGrady was working, she said she never received them. While this was happening, Buster opened his detective agency, he has no idea his first job will involve Arthur. Now, it is up to Buster to solve this mystery, was Arthur the real thief?....', '1996-10-14', 13, '/254fZiTjQZA9p5iyKIhixafaYq5.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D4ED5BFABE084CA792FC085A9DE627D7', X'4861CE46904543C7963F27B4EA539804', 46, 'Episode 176', '', '1971-01-11', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D4EF33C6547D4E0EAC921E4654ADD4EA', X'D5383B3D56364D71B99CB84774B4B3C6', 18, 'Pingu Gets Organized', 'There’s nobody in when Father gets home from work. The igloo is in a mess, with toys all over the floor and cooking stuff not put away. As he starts to tidy up, Pingu comes in. Father asks Pingu to put away the toys, and gets on with clearing up the cooking stuff himself. Pingu tosses all the toys into the toy box, and tells Father that he’ll go and tidy up the bedroom. While Pingu is in the bedroom Pinga arrives. She rummages in the toy box and, tossing toys out of the way, emerges with Pingu’s toy engine. She goes outside to play with it. Father is there, hanging up the washing. Pinga shows him the toy she’s got, and makes it go in a circle round herself. Pingu comes out from the bedroom and is a bit niggled to find toys left out on the floor. He puts them away, goes outside, and is even more annoyed to find Pinga with his engine. He grabs it from her, which makes Pinga distraught. Father comes over to mediate, and whispers something to Pingu. Pingu thinks this is a good idea, gives the engine back to Pinga and goes back indoors. He soon comes back out, pulling a truck full of toys, and he and Father build a ramp to slide the toys down. Pinga, meanwhile, is building with the bricks. Pingu makes a tunnel at the bottom of the ramp, and he and Father slide all sorts of toys down the ramp, but none go through the tunnel! Finally, Father rolls the engine down the ramp, and Pingu is delighted when it rolls through the tunnel. Father goes inside, and initially is not very happy when he finds the toy box on its side with the toys spilling out. However, on reflection he realises that children will always make a mess and decides not to worry about it.', '1999-12-08', 5, '/zBPY5RPw3ODwz5FWICweqMR83e4.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
