INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D50D6B0C5DCE4C088EF4BDA5980AC597', X'D034C38DC0C742B48876394B63D84275', 8, 'Kiss and Tell', 'For Gretchen’s birthday, Slade surprises her with a poor man’s party of take-out food and a unique gift that leaves her speechless. Peggy and Tamra are excited to model in an OC Designer’s fashion show, but a surprise model throws Tamra for a loop. Former housewife, Lynne Curtin goes to Fernanda’s gym to workout, but when Tamra is a no-show, Fernanda shares a shocking secret.', '2011-04-24', 44, '/k1S3tv5icpMNuyYVvsjrYCS3epr.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
