INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D5D60EBF02E841FF9CD6DE55D11AF257', X'050D8AE16CC14018933DB3C3D13DE856', 5, 'Episode 5', 'Simon and Goldie join the spinners and weavers at the'' Quarry Bank Mill, Styal - 1984 Museum of the Year - and discover how children as young as 8 or 9, working as apprentices, kept the looms turning for over 50 years, in the days when cotton was king!', '1984-09-24', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D5D94A3715E5444FBB1E0320486A19BE', X'E38E9D8714324A1AA7D064A559BF7570', 3, 'Through Fire And Water', 'The Newts are finding the journey more difficult than the others so when they come across a large lake, they decide to make it their new home. After saying their goodbyes the rest of the animals continue on their journey. After crossing to the other side of the lake Weasel announces that she can smell fire. Soon the other animals spot smoke in the distance, gaining on them. Fox''s instincts kick in and he begins to run away from the fire but he has to overcome them when Toad is missing. He has been left behind and its up to Fox to go back and rescue him. Toad is rescued by Fox but Badger discovers that mole is missing. He has been picked up by a fire fighter and placed inside his pocket. Badger heads back and rescues him. It is then that they realise that the Newts have died in the blaze. They are the first of the animals to lose their lives on the journey.', '1993-01-17', 24, '/zQm6nCGw3CynmvydjAc1rk36b7G.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
