INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D5FC0B46E8744C18993D135DE7DD7B08', X'99A9678144CB4A5C910071E2A55B6B1A', 10, 'Diamonds Are a Girl''s Best Friend', 'It’s the Big 4-0 for Tamra, and everyone’s invited to celebrate aboard Simon’s new yacht. It’s drunken fun in Newport Beach as Simon surprises Tamra with a gift that has all the ladies’ tongues wagging. Quinn and Billy have been dating for three months and things are going well, but there are huge differences between them. Quinn is ready to have “the talk,” but Billy has other plans. Officially separated, Jeana contemplates divorce. But not before she enjoys the former glory of her Playboy days. Jeana is going to Glamour on, the largest celebrity autograph convention, celebrating 25 Years of Playboy. With only days until their wedding, George and Lauri are frantically caught up in preparations. But missing from the plans is Lauri’s son, Josh. Estranged for several months, Lauri really wants Josh to be part of her special day but in order for that to happen, Josh must agree to meet with a therapist.', '2008-01-15', 44, '/sqbVToEVIVudknCtNvhVGrbhyEL.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
