INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D623E2332560426992F9459AC941FD85', X'6F731E6BD3C54DE684E17A19CB650E86', 6, 'Eye of the Tiger', 'Go undercover with the Pawn Stars when a banner from the WWII secret airborne division, The Flying Tigers, infiltrates the shop. Will Rick make a covert deal or will the mission be compromised? Then, things get messy when a 1980s Ooze-It toy seeps in. Will Chum squeeze out a good price or will it slip through his fingers? And later, Rick is muted by an unsigned illustration from the silent film era. Will he entertain a sale or will he be at a loss for words?', '2015-11-05', 21, '/uiqefh6wqFtbtjcxassWbuBWTtT.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D62B4926E7694059A92C644B453C46B3', X'0BBD380C5CB846A68838B5D60223C073', 7, 'Florence Henderson', 'The Muppet Theatre is plagued by a variety of pig-related problems, both onstage and off. First, The Bouncing Borsalino Brothers flub their act and crash through the stage floor. Backstage, Miss Piggy throws herself at an uninterested Kermit and then jealously interrupts his onstage Talk Spot, physically threatening guest star Florence Henderson, whom she thinks is horning in on her frog. The feud continues in the Panel Discussion as Florence throws pig slurs around.', '1976-10-17', 26, '/mHUqVHjYmH6a9a6YhInJ5grkWGv.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
