INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D6AD3398B7634AEFAC5EEA80D702D835', X'F4938E7D11A84756B40598BEDD7C9B28', 8, 'Pat''s Windy Day', 'Pat finds it hard to steer his van in such a big wind. A fallen tree blocks the road and Peter goes to borrow a chainsaw from the forestry commision to cut the tree up. When Pat can get on his way again, his van''s engine jerks. Pat gets out to have a look at it and the wind blows his hat off and it ends up in a lake!', '1981-11-04', 14, '/ta9hjREmkfazzHdKAlvIAVpRibX.jpg', '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
