INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D6B544B2078349DF857685821BCA0A66', X'4900FC8D5E7E408E972ECE9269D203B3', 3, 'Gone Guy', 'Shannon apologizes to the ladies after Heather’s party, but finds that some are more receptive than others. Meanwhile, Noella’s husband blindsides her with unexpected news. Gina struggles to move forward with her friendship with Shannon and Dr. Jen works on her relationship with her mom. Emily reconnects to her faith as her daughter prepares to be baptized in the Mormon Church.', '2021-12-15', 44, '/ld5LzW2zqfGwUAWVLgp57MT8VKP.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D6BB32C6E350455692419E6EADD21B09', X'5C4E51C6E20746AD875C72988EB1E13E', 16, 'Buy the Book', 'Go cruising with the Pawn Stars as they check out a classic 1932 Lincoln roadster. Exceptionally maintained, will Rick and the Old Man strike gold and ride off in this vintage beauty or is the seller not firing on all cylinders? Then, the guys nearly lose their pants when a Civil War Confederate belt buckle walks into the shop. With a lifesaving bullet lodged in the front, will the guys lay down some cover fire to seize this deal or will a tough negotiation have them sounding a retreat? And later, a man comes in hoping to sell his first edition copy of Ernest Hemingway''s "For Whom the Bell Tolls." Will Rick play this negotiation by the book and strike a deal or will this story have a tragic ending?', '2011-06-06', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
