INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D6C477CA62274DB5A0E98B6D32EC34B0', X'ECB64EF34F8045A7B4A9C04434B02E35', 12, 'Extreme Pawnover', 'Hop on the highway to hell with the Pawn Stars when Chumlee checks out a one-of-a-kind Ford Model A dubbed the "Hellbilly." Complete with flamethrowers and a skull stick shift, will he burn a hole in Rick''s pocket to score this custom car? Then, Rick and Corey get nostalgic when vintage Pinocchio and Donald Duck toys wind up in the shop. Will they hit the negotiation on the nose or end up getting played? And later, when the Old Man leaves town, Rick rushes to make some expensive renovations. Will the Old Man get ugly, or just get even?', '2014-02-06', 21, '/e7YOb4AE4GD9hKUqhShZLTkCTrc.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
