INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D6E462966B434D51AB26BAB4256F4038', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 130, 'Big Bird and Officer George look for Barkley', 'When Barkley goes missing, Big Bird teams up with Officer George to search for the dog throughout Sesame Street. They follow clues and ask residents if they''ve seen him. The search becomes an adventure that teaches about community cooperation and the importance of finding lost pets.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D6E51A400F4B47FCBD8F0805A8AF67D2', X'F07B879456254682AAE1E56966B4C7A8', 18, 'Little Leon, Big Ben', 'The children decide to host a circus. But Leon is too small to fit into a costume. With his friends’ help, he discovers that size shouldn’t matter.', '1996-02-07', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D6E5D3116CE841CBB5A686D0150ABEE5', X'B1D55597D9D24EEEAB9546DBB163291A', 25, 'Pingu and the Organ Grinder', 'Pingu is spending time with a stranger who is busking by playing a barrel organ, which makes him feel upset because of how poor he is. He is more upset when arrogant penguins just walk past refusing to give money. First, a male penguin just walks around the organ. Secondly, a female Penguin walks past the organ. Pingu tries to stop her, but she pushes him away with her belly. Pingu asks another male penguin for some money, but he gets a fish instead. Pingu gives the fish to the busker and tries the organ. Pingu asks another penguin for some money. They both look up and the penguin walks away. Seething with rage, Pingu turns the organ''s handle quickly. The penguin doesn''t look where he''s going and falls into a fishing hole. Pingu is even more upset when he follows him home to find it an old, broken down, messy ruin. Feeling sorry for the busker, he borrows the barrel organ and goes around town playing it in front of a tailor, bakery, tavern and a fishmonger, the pleased owners of which give him free supplies. He then goes back to the busker''s place and sets out for him a nice meal with the supplies, and goes outside to make some repairs to the house. The pleased busker then rewards him with a harmonica.', '1990-10-20', 5, '/o6dKJCaTB0DVDdhH54GA2T0HCe9.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D6E6C8BBB9634A3DBA132DB3E6172A09', X'23C93536610C41C5AC6BA6B243423258', 15, 'Old Rumors, Die Hard', 'The ladies return from their Panama trip. Ashley prepares for her Drag King event. Stacey works to finalize her divorce while fielding requests from TJ. Gordon reveals some shocking information to Ray, which Karen levies against Mia to figure out the truth.', '2025-01-19', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D6E82AF95A8E40F384506AA25ABA8197', X'F9A8D8B3D72E437EA9D57477F6D64DF8', 11, 'Gold Medal Tango', 'Elmo, Rosita, and Chris are making a doggy obstacle course for Tango. They find a hula hoop that Tango could jump through, but it won’t stand up. What if they put the hoop through the slats of two chairs? Let’s try!', '2023-01-12', 26, '/gSUXSeYWX5ejO7GVSKpihVW3BLL.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D6F9C0F1FA784AD3AFC26AACD8A2C8F0', X'05C0E384194C44179F62803EB615E409', 76, 'Cheering up King Friday', 'Title number 0076. Opens with Mister Rogers arriving with a briefcase and box containing dolls of all kinds. Betty Aberlin visits to finish making a doll for King Friday. Dr. Marchl gets opinions from Corny, Mrs. Frogg, and Lady Aberlin. She is trying to cheer up King Friday, who has been missing Sara Saturday.', '1968-06-03', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D6FD773761A947ADB1143BFBDE63D781', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 37, 'Inside Looks (on The Limo)', 'Inside look from the season 3 episode "The Limo."', NULL, 2, NULL, '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D70B5FD03DE84FD296BA6ED0E578BD09', X'F1BFFB39ECC94322A528C335D8048732', 1, 'CoComelon Sing-AIongs:playdate with JJ', 'Join J.J. as he sings adn dances his way through the first day of school and explores the wonders of the classroom,park and beyond', NULL, NULL, NULL, '2026-04-03T15:26:05Z', '2026-04-03T15:26:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D70D455AFBC3468892DB6470E4EE9E06', X'02CDC01216D24444B010B45AD42283B9', 4, 'Part 4', '', '1997-12-07', 28, NULL, '2026-04-03T17:18:35Z', '2026-04-03T17:18:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D712E2856FD44174AC7427A951A4917D', X'70D9E39768134785887D27D034928BAE', 11, 'Pingu Has An Idea', 'Pingu and Pinga are in the igloo, trying to decide what record to play. Pingu chooses a record and puts it on the record player, but before he can set it playing Pinga points out that Mother has fallen asleep in her chair. They take the record player outside, but as it’s not plugged in it won’t play. Pingu spots a wind turbine fan on the top of a nearby igloo and has an idea – he’ll build one to power the record player himself. He goes into the shed and finds an old broken one on the floor, which he soon mends. He takes it outside and fixes it onto the roof of the igloo, banging it into place. The noise startles Mother awake, but only briefly. Pingu and Pinga connect the turbine to the record player, but are disappointed when nothing happens – there’s no wind! They try turning the record by hand, but this doesn’t work either. Their Father then arrives on his motorised sledge, parking it near the record player. He gets out and removes the battery to check, then looks at the sledge’s motor. Pingu, who is sadly wondering what to do next, spots the battery and has an idea. He disconnects it from the sledge, connects it up to the record player and switches on. It works! He and Pinga are delighted but Father is surprised! The music wakes Mother and she goes outside to find out what is happening. Father explains, and they all end up dancing.', '1995-08-24', 5, '/orWF2wUQvAMM1GyzsJtiA8rqplH.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D714546FDE084A7D877E31BA892D99DE', X'73AE1459BA914185A9DABF6F2844AF49', 18, 'Hitting All the Wrong Cenotes', 'On day three in Mexico, the ladies tread carefully at breakfast when Dorinda snaps at Sonja and Leah. Luann and Leah pick up two single men while on a stroll down the beach and bring them back to the villa. While Dorinda stays in bed, the ladies enjoy a fancy dinner with their new male friends.', '2020-08-13', 60, '/qkUhRxUxqV7KHUMr4lMjC1x0hAm.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D7188F21099C4799BA356DF2047CA3CE', X'204D86FBD99C4FD18DCD9C1BCFD3C33F', 29, 'Teasing is Not Pleasing', 'The friends are playing in a Dragonbasketball game, but the other team has lots of bullies, especially two dragons named Buster and Mooky, and they tease Emmy during the game.', '2001-09-07', NULL, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D718AC01DFF74297A311B1B1FA9B9EF5', X'0E4196154C964DDE8ED2715770BA77BB', 10, 'At the Old Bear Game', 'Pip and Pop absolutely love baseball. They collect baseball cards and are especially obsessed with Ferret Jeeter, whom they believe to be capable of any sort of amazing feat. They declare Ferret Jeeter to be their hero and take little notice of Bear''s attempts to tell them that he knows Ferret Jeeter. After all, everyone knows Ferret Jeeter. But it turns out that Bear really does know him personally; he and Ferret were classmates (and teammates) at Hazelnut High. Bear invites Ferret over to the Big Blue House, where he teaches the gang some things they never knew about Bear. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D71CB2F78957474EBCCC45AA8E32D526', X'699572F82BFF45158DF36E7D1A21F346', 8, 'Gains Weight', 'Phoebe is chosen to give a slam-dunk exhibition during the big basketball game. When she finds she can’t jump high enough because gravity is “pulling on” her, Ms. Frizzle takes the class into space and turns the Bus into a planet—with adjustable gravity!', '1997-11-01', 25, '/f0MuWGU79BwNPcH9K1L2mfcwpd5.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D722233A678C4F3786ACDC0330750F1B', X'4C79C0B621A442778967BE1E791EFDBE', 25, 'Pingu Makes a Big Splash', 'Father takes Pingu and Pinga to the swimming pool. While they’re getting ready to go in, they see a penguin dive into the deep pool from the top of the diving block, which worries Pingu. Father then jumps into the shallow pool, as does Pinga, but Pingu gets in by sliding in from a sitting position. Pingi, Pingo and Pingg arrive and have a good laugh at Pingu in the shallow pool, and challenge him to come over to the big pool and jump in. Pingu goes off with them, and they climb to a ledge halfway up the diving block. Pingo and Pingg jump straight in, but Pingu shows off to Pingi and climbs a bit higher. He goes to jump in but once he sees the height he can’t, and climbs back down to Pingi. By now Pingo and Pingg have climbed back up, have a laugh at Pingu and jump in again. Pingi also jumps in. Pingu decides he’s not to be outdone, so he climbs right to the top and stands on the edge. With Pingo, Pingg and Pingi urging him on, Pingu gathers his courage and jumps, but changes his mind at the last minute and just manages to grab hold of the edge of the diving block before he falls, thinking it might be frozen solid. Father and Pinga come over as Pingu hangs precariously over the water, and Father shouts instructions to Pingu. Pingu tries to climb back but slips, and falls head first into the pool with a big splash. When he climbs out Pingu is congratulated by the others, but is a bit shocked by the experience. He then gets his courage back and dives in properly from the lower ledge, and is cheered by the others.', '2006-03-02', 5, '/yD36NrWEp5WD09KOPXhokKefVm4.jpg', '2026-04-03T17:22:21Z', '2026-04-03T17:22:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
