INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D761BDF2C95C4632BD6277C6FBC63DD1', X'BF3FFAFD7D454F2C9F1B28001BD082DB', 4, 'Episode 4', 'Expedition - Thailand  Ankle-deep in mud, John, Peter and Lesley help out in the rice fields and discover a village where everyone makes special umbrellas that disintegrate at the first drop of rain!', '1974-09-19', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
