INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D76A9CF64612424684B0D266403E3915', X'4B2A19E02FAE492EBC31F78E63D88EBC', 28, 'Houston, We Have a Deal', 'Moonwalk with the Pawn Stars when a lunar Bible from Apollo 14 lands in the shop. Will Rick make a good offer on the good word or leave it in orbit? Next, a 1930s Buck Rogers Disintegrator Gun zaps in. Will Corey laser in on a deal or will it be an atomic bust? Then, miniature samples of a 1950s kitchen cook their way in. Will Rick think the mini models mean big money or will he walk away from everything and the kitchen sink? And later, a 1950s Beetle Bailey original print marches in. Will Rick draft a deal or will he go AWOL?', '2017-01-30', 21, '/5p54YyLNcbAUgJPL2AkX10iOEtP.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
