INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D77ABC6C5A45475A9E757058AC835647', X'ECDEFD77A7AC4344BEA1FB1DF2FD0AC9', 7, 'Running on Time', 'Bernard receives a model train, but has no tracks to see it run on. He makes a friend in someone with a large model railway, Mr. Arnold. But when Mr. Arnold finds a note from his wife saying she''s left him, can his knowledge of trains and Bernard''s watch help save their marriage?', '2001-12-04', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
