INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D78B8C47FF604E7999F8EEC78BF33CD9', X'6A2D283971064C3B8906C9B3E4BFCC8B', 1, 'Hawaii 5 Uh-Oh', 'Vicki tries to move forward when her divorce is finalized in the Season 9 opener. Also: Tamra''s gym is open for business; and Heather invites Vicki and Tamra to Hawaii for a weekend getaway, but friction develops over wardrobe choice.', '2014-04-14', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D7917C8FD9064AF6B3DEEC25650A4C7B', X'913F846D85DF46948DD40D5909F78887', 2, 'Work', 'Annie decides to build an electric motor from scratch for her science, but when the task turns out to be harder than she expected, she is prepared to give up. That is, until Plato tells her the story the Wright Brothers who worked tirelessly to make their dream of human flight a reality.', '2000-10-01', 30, NULL, '2026-04-03T17:38:35Z', '2026-04-03T17:38:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D793295A9E354303BD2D7E6AD14025FB', X'A1B69730D22548F2A7E71D314CF3B349', 1, 'Episode 1', 'with Valerie Singleton, John Noakes, Peter Purves', '1968-09-23', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D793D2FF2D85476A850627410BAEE25C', X'DB555B9887D64CD2B7B4973F9206CB1E', 22, 'Reunion (2)', 'In part two of the reunion, tensions flare between Kelly and the Tres Amigas as the ladies continue their debate about what went down at Miraval, including all of the rumors that were lobbed at Kelly. Braunwyn opens up about how the show has complicated her relationship with her mother, Dr. Deb. Emotions run high as the Kelly versus Vicki feud is replayed and Kelly gets emotional about the loss of her former friend. Tamra gives updates on her family and her new business. Questions about Tamra’s true motivations as a friend turns into a heated argument between Kelly and Shannon. The group trip to Florida is brought up and Vicki surprises everyone by insisting Braunwyn and her wilder ways has “destroyed” the show she created.', '2019-12-23', 44, '/danAExZJmTSASq2KbfqGLMzGP0O.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
