INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D794AA53333F4B82A0CA64B4C723B5CD', X'5C1B881FAC584D72B63F209952D4F902', 55, 'Episode 55', 'A-Z of Space  Since 1957 five planets in our solar system have been photographed and men have walked on the moon. Reg Turnill, who reported for the BBC on the space programmes, investigates what the future holds for interplanetary explorers.', '1980-03-20', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D7969BD7568649AA9C1EB6A65EF2CDB5', X'70C8CB4624944DD498F66BFB9B3FAF73', 12, 'Backroom Brawl', 'The Pawn Stars are presented with a mysterious pocket-sized sundial believed to be from the 16th Century ... complete with a concealed secret inside. Will the gang be able to shine a light on this puzzling piece of history, or will the seller darken their day by shooting for the moon? Rick and the Old Man have a chance to buy a photo album of famed union organizer Jimmy Hoffa. Will they wheel up a deal for this item, or will it be sent back to be hidden and buried away for ever? Then later Corey and Chumlee set their sights on a rifle sharpshooting arcade game from the 60''s. Will Corey target a good price for this vintage game, or will his plan backfire?', '2010-03-01', 21, '/kdfFamPIxwbo6nhvgTGDJBdEhpt.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
