INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D7ED79421D334323AB4C777C7EC0A335', X'227B84290DFD47E4B874C37DA20C403F', 14, 'Old Man''s Gamble', 'The Pawn Stars get a call about a 1979 KISS pinball machine - can it still "Rock ''n Roll All Nite", or will it steal Corey''s quarter and KISS the deal goodbye? Then Rick is stumped when a woman brings in a 1914 Star-note $20 bill. Will everyone walk away with new money, or will it turn out to be chump change? And when an old easy rider brings in his classic 1982 Harley Davidson Shovel-head, Chumlee decides to buy it for himself - but can he raise the cash before the Old Man sells it off.', '2009-09-27', 21, '/ywCeVJN0GvtuuSYg18rmCrmMPGp.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
