INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D8D8C460F350472B8147DAE21CBDF8D1', X'C21DBD225E2E4414BB67750399AAF6F0', 4, 'Looney Dunes', 'The Pawn Stars pray to the rock gods when a collection of unpublished photos of Jimi Hendrix blasts into the shop. Taken by Jimi''s personal photographer, will Rick be able to contain his excitement and make a deal, or will he tip his hand and see the signal go from green to red? Then, the guys see history repeat itself when they check out two high-performance dune buggies in the same day. Will they jump at a chance to buy these tricked out toys, or will both deals sputter out when negotiations get stuck in the sand? And later, Rick and the Old Man check out a rare 1930''s Levi''s jacket. Will Rick be busting at the seams to snatch up this highly sought after denim, or is this old piece just not a good fit?', '2011-12-05', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
