INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D8EA80DDAD9C461DABAAABC0B66B9532', X'36EA381466B44986B6EE44559D3562C1', 6, 'The Old Lady and the Shoe', 'Phaedra, still upset with Apollo, returns home to Atlanta. Cynthia and Leon — Noelle''s dad — sit down with Noelle to tell her about "the birds and the bees". Kenya comes to the conclusion that it''s time to get her priorities straight. Due to the stress of her divorce and the never-ending rumors, Porsha is admitted to the hospital. Kandi and Todd start the lengthy process of planning their wedding.', '2013-12-08', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
