INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D8F359529B724C8BAF90448A24E97515', X'7BC54DF3F32A454EAEF6A9436C35D53B', 9, 'The Pie Restaurant Pt 4 - Repairing a fence', 'Bad manners cost Bob Dog after he eats all the pies in Lady Elaine''s restaurant.', '1970-02-12', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D8F43B8923EB4E5395CA47A58C8FD191', X'0E4196154C964DDE8ED2715770BA77BB', 18, 'To Clean or Not to Clean', 'Bear returns to the Big Blue House from a business trip for Bearcraft Tools to find that everything''s a mess. He left Lois in charge while he was away and it seems she was perfectly willing to go along with the kids'' idea of not cleaning up so that they''d have more time to play. Now Ojo and Treelo are missing their toys --- Snow Bear and Rockboy, Pip and Pop have been stuck in one spot playing an increasingly boring game of tag and Tutter''s trapped in the cheese drawer. Bear talks things over with everyone and they begin to see that maybe their time-saving idea is actually wasting time. They then have the same sort of idea about taking a bath, but Bear helps them by getting them to visualize what would happen if they stopped taking baths. In the Shadow segment, Shadow sings a song about how to make doing chores fun. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D8F6950715A940D78A5B3EEEE877924A', X'235468B020FC4714BC3FD7E7AEB25F4B', 4, 'Boogers and Birkins', 'Guerdy breaks down over the events from Marysol’s surprise wedding party. Larsa introduces the group to Stephanie, a no-nonsense businesswoman. Adriana throws a baby shower for Julia and Martina, but a grieving Lisa makes a premature exit.', '2025-07-02', 42, '/46un5CiBYyJy7jXXK4U6JTFGyEh.jpg', '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
