INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D90D446F22A64C8DB378F91AD0C7749C', X'8C3CFAC1D8824904B38CD1981628D00E', 14, 'Episode 14', 'Red Indian Teddy  Make your bear the chief of your tribe, complete with feathered headdress and tomahawk plus a Teddy-sized tee-pee and camp fire. When the clocks go back next Sunday and the long, dark winter evenings begin, there''ll be plenty of time to transform Britain''s favourite toy!', '1978-10-26', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D90FE8E211674265846B4570354B64CB', X'3219200875294677933FC55EA6146368', 18, 'Reunion (1)', 'While the women of Potomac gather to discuss Season 10, the topic on everyone''s mind is Wendy''s recent legal woes. Stacey is held accountable for her season of alleged loose truths. Angel confronts the women in regards to her treatment in the friend group. Tensions with Ashley boil over.', '2026-02-15', 42, NULL, '2026-04-03T16:35:42Z', '2026-04-03T16:35:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
