INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D912B1FBEC514529AE343EF8CA031299', X'CEAB3D79ABBE47FBB8B33073FCCB1EC7', 8, 'Rise of the Numbericons: The Movie', 'Our heroes realize that math is hard, but saving the universe is harder.', '2023-12-03', 23, '/8xmc22qIVtn1MSZM5C8pAb94QO8.jpg', '2026-04-03T15:40:43Z', '2026-04-03T15:40:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'D913055CCE8641D4BA5413FA5B4E2EB1', X'70C8CB4624944DD498F66BFB9B3FAF73', 31, 'Rough Riders', 'The Pawn Stars have an opportunity to buy an 1875 Remington pistol so rare that only four are believed to exist in the World. Presented to a member of Theodore Roosevelt''s legendary Rough Riders, will the gang pony up the cash for this exclusive antique or will they suddenly find themselves in rough territory? Then Rick and the Old Man meet a man hoping to sell a Civil War bugle associated with General Custer''s ill fated 7th Calvary. Will they charge into the valley of death to seize this deal or will Chumlee be called upon to play taps? And later, the grandson of a famous Prime Minister comes in with a clock presented to his grandfather by President Richard Nixon. Can Rick and Corey successfully campaign to secure the Presidential timepiece or will he refuse to negotiate?', '2010-07-05', 21, '/95N348ZhNKl6ea3sOmAx5IdbIDk.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
