INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DA0B6D41221544798CC96D5FDED80152', X'CA3F764EB3304980BD7A2908A73B77B6', 19, 'Night of a Thousand Surprises', 'New drama and old faces pop up at the launch party for Lisa''s new lounge and a disheveled Kim tells Kyle the truth about her new boyfriend Ken.', '2012-01-16', 43, '/nK8wYOYimLmvkUZrcXo9cXwGxlO.jpg', '2026-04-03T16:34:55Z', '2026-04-03T16:34:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DA0C63312A774DDC88E17E9079E7A745', X'332249FA796B4F92B7F8421D523B0BDC', 4, 'Big Apple Squabbles', 'The ladies travel to the Big Apple for Kandi’s Broadway show, but her giftbag generates unexpected buzz with her single friends. A condo reveals the cracks in Kandi and Todd’s relationship. Drew and Ralph attempt to repair their own marital woes with a 30-day challenge.', '2022-05-22', NULL, '/yYHbSBDE4QaQBhrXxAfEA0i4Try.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DA13A870622B4D7787F5CAD060F20E97', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 10, 'Lakes & Ponds', 'What do you get when you have a big hole in the ground and some water? Lakes and ponds. All lakes and ponds have one thing in common – they happen when a basin, or hole, forms, and then fills with water. A glacier may grind a long gulch, volcanoes and earthquakes may make a sinkhole, or engineers may build a dam – they can be human or beaver.', '1998-02-21', 26, '/d3LgU4o9CCTPkp1huM89vezox8k.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
