INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DACA54D912B640F19ABF15506F49F027', X'70C8CB4624944DD498F66BFB9B3FAF73', 18, 'Hell Week', 'The Old Man has an opportunity to buy lost footage of legendary President Franklin Delano Roosevelt. Can he muster the money for this 8mm piece of White House history or will this film end up on the cutting room floor?  Then Rick considers buying a huge antique cast iron coffee grinder from the 1800''s and a lunch box from the 1960''s. And later Corey and Chumlee are challenged to compete in a parking lot obstacle course, designed just for them by the Old Man. Erik M. Underwood guest stars in this episode.', '2010-04-19', 21, '/c7Hfokk0GOh9sCjO1qwA6PrETXj.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DACE3D9B860E47FBBBCE53568107BFFD', X'C21DBD225E2E4414BB67750399AAF6F0', 20, 'Yankee Panky', 'The Pawn Stars get ready to rock when a man brings in an extremely rare original poster from one of Jimi Hendrix''s final performances. Will Rick play along with the seller''s asking price and make a deal, or will the negotiations hit a sour note? Then, Rick and the Old Man get revved up when a race suit worn and autographed by actor Paul Newman roars into the shop. But will a lack of official paperwork bring the deal to a screeching halt before it reaches the finish line? And later, Rick and Corey are in scoring position when a customer brings in a photo signed by three baseball Hall-of-Famers: Mickey Mantle, Willy Mays and Harmon Killebrew. Can Rick and Corey make a record breaking deal or will they strike out?', '2012-01-30', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
