INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DAF92E525351456C9604129821F3D61D', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 11, 'Smell', 'How do noses work? Objects give off tiny amounts of tiny molecules into the air. When just a few of these molecules get up your nose, they dissolve in the mucus up there. Some molecules come into contact with special receptors on what’s called your “olfactory membranes.” Each nostril has a membrane, and each membrane is only about the size of a postage stamp. The membranes hold millions of receptor cells, each of which are ready to send messages to the brain about the molecules that go up your nose.', '1998-02-28', 26, '/wbKGPtG5ADg50dkR2FbTXQHInBv.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
