INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DB1E317F9C324AF98F152E2B83799443', X'196E5A10AC254D588416575D3A71FCEF', 1, 'Choose Your Wea-pawn', 'When a friend swings by to show Rick and Chum a star-studded collection of photos, will the duo expose the right price, or get shot down? Then, a vintage LP of the single "We Are the World" spins into the shop. Will this deal make a brighter day for Corey? Meanwhile, Chum and Santos give each other a hand, when they check out an ancient Chinese cannon. Can they get a firm hold on this deal, or will it implode? And later, Rick races to Adam Carolla''s garage for a chance to bid on a car once owned by legendary actor, Paul Newman. Will Rick do a victory lap, or will he be left in the dust?', '2024-07-10', 42, '/qREb921PVRSDdvzSC2cH5a7sM5O.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
