INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DB2499DDDD2B4AD7B6E225E8D223CF73', X'F4938E7D11A84756B40598BEDD7C9B28', 7, 'Pat''s Thirsty Day', 'All of Greendale''s water supply has had to be turned off. When Pat arrives at the Post Office, Mrs Goggins gives him some lemonade to quench his thirst. Later Granny Dryden shows Pat an old water pump in the village. Can Ted fix it in order to get a water supply working?', '1981-10-28', 14, '/ytFQlRl4gv1tA1zU2xWOmDPy3JX.jpg', '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
