INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DB2B047BA32D454CB2D09F635FEEC336', X'E291DF42D44F49E5BF812DF32EE4A30F', 15, 'Morning Glory', 'Bear, Tutter, Treelo, Ojo, Pip and Pop have just had a sleepover and now Bear is waking up in the morning. It''s still early, but the sun''s about to rise and then everyone will be getting up. Some rise faster than others --- for example, Ojo finds all the morning noise upsetting at first, but given just a bit longer to sleep, she''s good to go. Bear gets everybody going with a good breakfast. Treelo wants to run and play, but Bear helps him to appreciate that breakfast will give him the fuel to do that. Then, fueled and ready to go, they head for the events of the day. While Tutter, Treelo and Ojo go out flower-sniffing, Pip and Pop decide to go riding in their inner-tubes. When Pop can''t find his, they all help to tidy up the house in an effort to find it. Bear then settles down to read a book, but not before the Shadow segment. Shadow sings a song about the morning, featuring a newspaper-fetching dog and sweetly-mooing cows.', '1999-08-26', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DB2C35A9D83C40259A7E66D54F6BE530', X'E8B959C0686543329BE1B8F720716AA8', 11, 'Sheepdog', 'John visits Netherly Farm in Mathon to see a sheepdog at work.', '1991-12-09', 15, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DB2EAECC59E14EAE800AF316909D0CBE', X'ECB64EF34F8045A7B4A9C04434B02E35', 18, 'Purple Haze', 'Set sail with the Pawn Stars as a collection of Viking items float into the shop. Will Rick discover a treasure trove or be steered in the wrong direction? Then, Rick is in rock and roll heaven when a Fender Stratocaster played in the studio by Jimi Hendrix comes up for grabs. Can he get this legendary piece on his shelves or will the deal leave him in a purple haze? And later, Rick gets the rare chance to look at some Viking swords that are over a thousand years old. Will he be able to wield a deal?', '2014-02-27', 21, '/2N9pD8B51vSeppOIdbx1qsp8GL8.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DB3226C211E04B8CB6EF33B8C5888E06', X'3EE646E823AE4DECBBC6C7E6A210D55B', 116, 'Big Bird yells "TOOTHPASTE!"', 'Big Bird interrupts Jelani and Gordon''s lesson to explain why he''s saying "TOOTHPASTE!" Today''s letter is F, and kids use toothpaste to brush their teeth; when their baby teeth fall out, the tooth fairy collects them - and fairy starts with the letter F!
