INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DB393DC82674473CA4E9310F63A1E6EC', X'3F27DC9B9BBE4AFF8CD990BE629A885E', 2, 'Episode 2', '', '1997-01-09', 25, NULL, '2026-04-03T17:21:17Z', '2026-04-03T17:21:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DB399263D5064912A9778A8C06F78FE9', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 5, 'Farming', 'Before food gets into your kitchen, before it even gets to the store, it’s on a farm. Almost everything we eat is grown on a farm, an area of land used to raise animals and plants. Farming nowadays can get pretty complicated. Farmers are scientists – agricultural scientists. Farmers work hard to keep their farms healthy. Soil is stirred up to get oxygen to the microorganisms that live in between the grains and to plant roots – that’s called tilling the soil to aerate it. Plants need to be protected from pests with either chemical pesticides or biological pesticides. Animals like bats and friendly insects eat other pest insects (chomp,chomp). Animals are milked, corralled, fed, sheared, slaughtered or cleaned-up after.', '1997-10-31', 26, '/YG8HekMIWFb9TV6wf4hi237w3W.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DB4DB1E017994940802BA3C5085196D7', X'3EE646E823AE4DECBBC6C7E6A210D55B', 66, 'Celebrating the letter K', 'Telly and the kids flash signs with the letter "K" on them and march around chanting the letter. Telly wants Oscar to provide them with a K word in honor of the letter of the day, but he naturally refuses. Telly and the kids disguise themselves as Grouches, hoping to dupe Oscar into showing them a K word.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DB50EEAC64B64CB59C058AF20E3D4D1D', X'4D2CAC0F38FD438B8AFAACF43952E535', 214, 'Episode 214', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. Including Building a Model Farm: Landscape Lay-out, Christmas Card Scrapbook and Part 2 of The Magic Egg by Anna and Edward Standon.', '1963-01-07', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
