INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DB888334B4CE40CEAB2B42656E8F0F1D', X'05C0E384194C44179F62803EB615E409', 97, 'Trouble with the telecan', 'After Mister Rogers tries on many different types of shoes, Handyman Negri sees that communication with the Neighborhood of Make-Believe is intact by repairing the "telecan". Norma Canner and her young students perform dance steps for King Friday.', '1968-07-02', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DB8EFE64B1BC45CDB2BFFB7486713143', X'F30BBF8187704E74B68B280E7C85B52F', 10, 'The Baby Shower', 'Elaine needs to use Jerry''s apartment to hold a baby shower for a woman that once dated George. George reflects that she was "unequivocally the worst date of my life." Jerry has to go out of town for a show, so he lets Elaine use the apartment. Kramer sells Jerry on the idea on getting an illegal cable hookup. The party begins. The cable guys come to install the hookup. Jerry''s show gets canceled, so he returns to the apartment with George (who''s prepared to confront the bad date). Jerry is the victim of his own confrontation.', '1991-05-16', 23, '/i6msp3bTvFlxpMfSHSu7fQtWhBi.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DB8F4DE470CC4A02BCEF13BB867DA89D', X'1D713CA64E174F84949C8CFD98514127', 15, 'Dodging Dillinger', 'Make a getaway with the Pawn Stars when bullet shells from John Dillinger''s last robbery get caught in the shop. Will Rick be able to escape with this rare ammo or will he get locked up in negotiation? Then, Rick and Corey try to make a drive by deal on a vintage Schwinn Whizzer from 1947. Will this motorized bike start their engines or will the deal stall? And later, Chumlee relives his childhood when a customer brings in a Stretch Armstrong doll. Can he pull a fast one for this elastic toy or will it break apart?', '2014-09-18', 21, '/i0qwwtALhrfV4aaV3NPZt3fswTm.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
