INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DBAA670B473244E8BF1DD1873252A65F', X'34674C90410E427CBE4D2A6F6F865A80', 18, 'Hot and Colt', 'Take aim at the Pawn Stars when a Colt Paterson revolver pops into the shop. Believed to be a prototype of Colt''s first gun, will the guys draw up a plan to own this piece of firearms history, or does the seller''s story need a little work? Then, the Old Man relives the glory days when a 1955 GMC truck drives in. The last GMC with a classic rounded body design, does what''s under the hood live up to the iconic look? And later, life imitates art when a guy brings in an animation cel from the 1960''s cartoon "Tennessee Tuxedo and His Tales." Complete with a picture of "Chumley the Walrus," will Corey break the bank over his best friend''s namesake, or is the cel simply not suited for the shop?', '2012-07-02', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
