INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DBECF6ECD1AC46E78D5E80663A618406', X'EA1650C2E4F146C793BA74B5D45D08E5', 13, 'Tour-ture', 'Phaedra is worried about having Kim at their ultra southern baby debut - Ayden''s Sip n'' See party, but when Kim shows up with her nursing license, Phaedra is ready to hear her out. Meanwhile, NeNe has no worries about nailing her interview with Jermaine Dupri, until she is thrown a curve ball. When Cynthia''s fiancé, Peter, reveals that his restaurant is on the brink of financial collapse, Cynthia''s dream wedding is in jeopardy and not even a counseling session can solve their problems. After a tearful goodbye with her girls, Kim is confident she''s going to kill it on Kandi''s promo tour. However, when the tour kicks off in Charlotte and Kim proceeds to complain about everything from the schedule to the size of her bunk, Kandi realizes she had no idea what she was in for.', '2011-01-09', 43, '/wPMlfdKipqZiyaQKtT7qwWM3ymZ.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
