INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DC17927E335C431E80D8BC90CC79B56E', X'913796E9C0CE44DD98BCF6F520CB2444', 5, 'How Much is a Million?', 'In this episode of Reading Rainbow Levar ponders what it takes to count to one million. Levar visits a Crayola factory and learns how crayons are made into many different colors and sizes. Levar then visits Giants stadium in New Jersey to see how stadium officials count the number of fans who attend different events. Finally, a vendors of Giant stadium discuss and how they use mathematics to estimate the amount of food they need for an event. The book "How Much Is A Million," by David Schwartz is read by Nick Sullivan. The kids review the books "Only One," "One Hundred Hungry Ants," "How Many Stars In The Sky."', '1995-10-12', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
