INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DC43E1D0F1A84562A7C8FDA3526EEB7D', X'3087A3EDE94E42769D02A78183DEA1D3', 19, 'Donktabulous!', 'Kandi’s housewarming party is supposed to be a joyous occasion, but Kenya brings drama after finding out that her ex Walter is there; Cynthia has to intervene because Kenya may have taken things too far. Meanwhile, NeNe and Gregg settle deeper into their rekindled relationship. Kandi holds her first Bedroom Kandi sales gathering, and the women are shocked to see how big her empire has grown. Porsha seeks the advice of a therapist concerning her relationship with Kordell, and Phaedra and Kenya are set to battle it out: Booty vs. Booty with their upcoming workout videos.', '2013-03-24', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
