INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DC853BDEDC264F2EBEFBD55E932517B2', X'9193E795DA7C40ECB68FF63AA7D5174F', 158, 'Histories & Lore: House Dayne', 'The young Eddard Stark recounts the history of House Dayne, the former kings and lords of Starfall, and how they have been linked to their legendary sword Dawn, especially his last and greatest bearer, Arthur Dayne, the Sword of the Morning.', '2016-11-15', 5, '/sRjY3jvI7cBxKsWSFHcI8PUYNYZ.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DC8B63B720D44A069322C26258643670', X'AD4E434833344A088928455D9BA524C1', 18, 'Johnny Cash', 'In honor of Johnny Cash''s appearance, the show is simulcast over country radio station WHOG, and the radio broadcast threatens to overwhelm the actual show. The head of WHOG, Big Tiny Tall Saddle, insists on making all the decisions. He refuses to let Rowlf go on, and instead schedules Grampaw McGuire and his whistling bricks. Kermit tries to run his own show, but Big Tiny is one of the toughest men alive -- when he''s annoyed, he has a habit of wrapping microphone stands around people''s necks. Fozzie is replaced by Wally Whoopie, a stand-up comedian who makes fun of the bear -- which inspires Kermit to stand up for his friend, and his show.', '1981-02-01', 26, '/bcYjGf4Na4lXbrhwkr7WthEvSUa.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
