INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DC916D5013DD4923B302D407A2E3D2CF', X'7EEF937C448342BDBAFE263A7D4E4573', 12, 'Rocks and Rolls', 'To celebrate the founding of Walkerville, Ms. Frizzle’s class sculpts a stone likeness of its founding father, Captain Walker. As they add the finishing touches, the statue tumbles down the mountain. Ms. Frizzle turns the Bus into a huge boulder and the kids into rocks while bumping down the mountain in a desperate attempt to save the statue.', '1996-11-30', 25, '/nyG4cABBOmU0CrhX3OH6i8RDPRA.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
