INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DCA39E9E0C2C4583A227FD5AD30BDB4B', X'5D97D70CFCEC41CE8E0D78AB624FE334', 2, 'Cookie Monster''s Big Puzzle', 'It''s Cookie Time... but Cookie Monster and Tamir can''t figure out why Elmo doesn''t want one! Abby helps Grover learn that doing puzzles takes patience.', '2025-11-10', 30, '/AlQ7SLruGnoY1KDX3bDMG2hiGBQ.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DCB1509A5BD1482CB98BFB76BF3D2137', X'3EE646E823AE4DECBBC6C7E6A210D55B', 78, 'Telly hosts "The Wide World of Numbers"', 'Today, “The Wide World of Sesame Street” will be covering numbers. Reporter Telly Monster is asking what people’s favorite numbers are. He first visits the home of Polly Darton, but her back up group, the Git Along Little Doggies, opens the front gate, smashing Telly against the wall.
