INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DCBA53247A11453AB39F54B3F3750BBE', X'A84AA42DE73840818DA91FAEC0209EE9', 13, 'The Interview', 'Mike loses his job when the plant shuts down for scientific research after he discovers a dinosaur bone in the quarry. However, Mike starts to get irregular feelings when he discovers how drastically things have change technologically over the years when considering the terms of searching for a job. Meanwhile, Frankie feels she must once again come to Brick''s rescue when he decides to run for school historian.', '2010-01-13', 22, '/lqK2MuCqxyyHhruOnSGfZGPZ4Tz.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DCC17CF2DF574BC991808F751BA66E23', X'AE8F64D94B834147A44CBFE720381F8E', 6, 'Y a Quest? Y Not', 'Telly excitedly runs to Abby and Elmo to tell them he has the book they’ve been waiting for, How to be a Knight for a Day. Hooray! Telly, Abby and Elmo look to the book to tell them how to become knights. First, they have to wear a suit of shining armor. They zip off and whoosh! Elmo, Abby and Telly are dressed in suits of armor. Clank! Clank! Clank!
