INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DCCB0DD16B1A4373BB05D147B4C095ED', X'E48599F866FF4C0F927465B9AE1CDA9E', 73, 'Episode 73', 'Jubilee Spring Clean!  JOHN joins steeple-jack Reg Dosell on a perilous 170-foot ascent by stepladder to give Admiral Lord Nelson a wash and , brush-up for the Queen''s Silver Jubilee Procession.', '1977-05-30', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DCCC6B0491B8470D992605F365BEF78F', X'D920EBAEF00A4E25ABFE40492C74DED6', 19, 'I Don''t Give a Dime', 'Things get flashy when a seller brings in an unusual diamond made from the DNA of a musical genius. Can Rick compose himself before it gets hairy’ Then, a vintage collection of paperbacks books it into the shop. Are these novels still only worth a dime’ Next, legendary Disney animator Floyd Norman draws Rick’s attention to his collection of prints. Will Rick think they’re sketchy, or can Mr. Norman paint him into a corner’ And finally, Chum has a very special surprise in store for Rick’s birthday.', '2020-05-11', 42, '/f1Yt2Ei4YrBDhanD0Jnb2HjJvLv.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DCD5FB7F97464967B08BE22F70C7C548', X'EB7E3BB45746457781C6F5B2DC2EFC6E', 20, 'The Crossroads of Destiny', 'Everyone races against time to stop Azula''s sinister plan. Zuko finds companionship in an unlikely source. Aang''s destiny hangs in the balance—and so does Zuko''s, as Iroh tells him it''s time to make a choice.', '2006-12-01', 22, '/5Ix70WNv3rqYv0AVWPifE7euOq4.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DCD7F38B588A4C9CBCA507318D69DF71', X'44624EE803F04261837968DAF4666B42', 19, 'Arthur Loses His Marbles', 'When Arthur discovers that Grandma Thora is a marbles champion, he trains with her so he can beat all his friends. And though Thora teaches Arthur everything he knows, she doesn''t teach him everything she knows.', '2001-11-26', 13, NULL, '2026-04-03T17:37:57Z', '2026-04-03T17:37:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DCDDB48F2BA74E9B80ACDAFAD414C381', X'6053B5C1CE86425C8166E0FCC3466061', 43, 'Episode 43', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-02-12', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DCDFC70455B24EADAA34BC05D2663398', X'AD180412A5D64E4A8B49590334F2FC69', 10, 'The Mole Game', 'Toad and Spike invent a game called "The Mole Game" They have to guess where Mossy the Mole will come up. Ranger ends up winning when Charmer asks what Toad and Spike are doing, which quite makes his day. Adder has vowed to kill as many rats as she can to avenge her mate''s death. Owl is still imprisoned in her Jacket of building cement, a few other fellow flappers (A Robin, A Green Woodpecker, A Rook, and another female owl) decide to try and break the cement by shoving her off the branch, but the plan fails, she is off the branch and still in the cement (It made her feel very Slow and Heavy). Toad and Spike continue playing their game, but soon become surrounded by Bully and his rat army, Spike''s cover is blown when he responds to Bully''s Call of "Who am I" With a "Bully Bully Bully" complete with salute! Toad tries to escape, but ends up captured. Mossy has rushed to get help, only to find Dash. Dash goes and gets some White Deer to chase her, they stampede over the rats, squashing nearly every one. Spike feels awful for his behaviour, but is relieved when Toad is found alive at the pond, and Toad fully forgives him when Spike promises to fight like a Terrier the next time it happens. Spike was kicked out of the rat plague.', '1995-11-30', 25, '/yI6475jtZecWrZv5bqqjNz65SRy.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DCE31A8E7BD744C0A2F57BAB82581BCB', X'E3A2866991B545F7BB735006ACC084E8', 3, 'Shape Up with Shaun', 'Shirley grows heavier, and Shaun and the flock do their best to help her lose weight. It works, but an accident in which Timmy and a tractor were involved launches Shirley into a pie truck—and back to her fat, weighty state.', '2007-03-06', 7, '/3LmpY2SaeSh2Rhs745L9PdZXMlt.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DCE3B99B0DF441059312B9CDF8D9F2A1', X'40700E8A1DCE4895BEDE522A13A8BCAD', 25, 'Messy and Clean', 'It''s time to clean out the closet but the more Zoboo tries to help, the bigger the mess he makes! No sooner is everything back in its place, than some European wild boars and a capuchin monkey mess everything up again. Zoboo has lots of fun learning how messy and clean means different things to different animals.', '2001-06-07', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DCE946AC064D44FF921905043EE67FCC', X'A8DB07E5FBA349A9BD12947C111B39BE', 23, 'Reunion (3)', 'Reunion dramas include Sonja opining on how she was treated by the ladies during Season 8. Also, the women discuss the lighter side of their Miami excursion, and Luann is on the hot seat when the conversation turns to Tom.', '2016-09-14', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DCED618EB2D14EBBA988BD011293ED00', X'E1063F8766C24E2DA91353362941AA19', 55, 'Episode 330', 'Today, Rafael and Luis open up their new Fix-It Shop, and Big Bird wants to give them a gift. So he puts on various disguises and acquires all the free flashlights they are giving the customers, just so he can give them back as a gift.', '1972-01-28', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
