INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DD1686EF880F4695B92919030F1AA5C4', X'FED71EEA5D41479CB12ABEB733409C5C', 5, 'Enthusiastic Penelope', 'Chris helps Penelope, an overly excited penguin, learn how to control herself and make new friends.', '2014-09-19', NULL, '/lMZqWB1SjTwmBoVqJ9yO49CXNOI.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DD18F354008B48029C3491523DF9D104', X'E4023DA233D74A2BA04ACA449BD23935', 9, 'The Christmas Wall', 'Frankie loses her Christmas spirit, Mike unsuccessfully tries to exchange the new family Christmas tree, and a fight over Rudolph the Red Nosed Reindeer threatens to break up BossCo.', '2014-12-10', 22, '/7q8uXyFzfDmvTpoJymtObp9Mbll.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DD19FE08256B41CB9228F04EDED46D20', X'8BDF0AD3A7984D5AB304C7501EAE6867', 5, '120 In The Shade', 'Jeana Keough, Vicki Gunvalson and Tamra Barney go to Lake Havasu for the Fourth of July, but when Jeana brings Vicki''s nemesis, Frankie, Vicki feels betrayed and refuses to speak to Jeana. Later, Ryan reveals his latest tattoo in the strangest of places, which causes Tamra to have a meltdown. Meanwhile, Gretchen Rossi vacations with her family in the Central California mountains at Bass Lake but is devastated when she gets the news that Jeff is not doing well in the hospital. Lynne Curtin prepares for her daughter, Raquel''s, upcoming 18th birthday party. An incident at her home spray-tan party tests Lynne''s patience when Raquel has a spoiled brat fit.', '2008-12-23', 44, '/gxJxu4AZCjja3vUMjZWtWG8zqY8.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DD1BADD5A6104739A4E02583F91C2401', X'78A02D50E3DC4549844A3CF357A32EF4', 20, 'Chateau She Did That', 'Shereé unveils Chateau Shereé at a housewarming party. At the party, things heat up when Kenya finds herself going toe-to-toe with a blast from the past. Cynthia carries the bone that Apollo''s girlfriend was a guest at Kandi and Todd''s OLG Restaurant preview. Phaedra lends a helping hand to Kandi''s former disgruntled employee. Porsha discovers a new sense of clarity in her relationship with Todd.', '2017-04-09', 43, '/cAVWrWo3qtGPY2ZjfBSS4mObTAf.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
