INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DDB4344ABE57440BB3E9E09ABAC7E0D8', X'B1D55597D9D24EEEAB9546DBB163291A', 13, 'Pingu Plays Ice Hockey', 'Pingu, Robby and their new friend Pongi are dawdling around when they see a hockey team having a game. They decide to join in. At the first two tries they didn''t get a goal, but then on the next try, they get one. The other team is a bad loser, however, and on the final try, they play aggressively to ensure they do not win, knocking them with the putt, forcing them into corners, and so on, and they win the game. They want another game, but Pingu and his friends refuse due to the team''s bad sportsmanship and for injuring Robby as well. Them and the team then discard all their gear, and do figure skating instead, and the song called "Hand in Hand".', '1989-12-18', 5, '/lPO25bwHEFRMlYCgH7KVMKSxYdg.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
