INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DDC8E0F13AFB4E50A75117920D19236F', X'4B2A19E02FAE492EBC31F78E63D88EBC', 13, 'Hidden Pawn', 'Go all in with the Pawn Stars when a 1769 playing card with a political message shuffles into the shop. Will Rick show his hand and make a deal or will the odds be stacked against him? Then, Corey shifts gears and checks out a motorcycle that was owned by actor Dennis Hopper. Will the deal go down like "Easy Rider" or will he pump the breaks? Next, Rick lights up when an antique stained glass lamp illuminates the shop. Will he be blown away and make an offer or will he throw shade? And later, three "Charlie''s Angels" figurines sneak in. Will Corey be saying "Good morning, Angels" or will the mission be compromised?', '2016-11-14', 21, '/2ZpRXPFOXV8PlVsbIHNG6EVoBtb.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
