INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DE17588C70004FDEBD2AB5D93A4664AF', X'5B72E664D3D7435DBDC3A23D29D1178E', 13, 'The Car', 'It looks as if nobody wants to ride in Zebra’s little wooden cart now the toys have seen Bramwell Brown’s big, red car. But the car likes to go very fast and the lack of brakes makes it really rather dangerous. After much excitement and a few disasters, all the friends agree that Zebra’s little cart might be, after all, a much safer and more comfortable ride.', '1994-11-29', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
