INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DE450580C3954FA2B7FA38309DCCCD91', X'E8B959C0686543329BE1B8F720716AA8', 7, 'Small Animals', 'John visits Evesham in Stratford-upon-Avon to see some small animals at Twyford Country Centre.', '1991-11-11', 15, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DE4974CA94E549659F9782B4829C4DF1', X'DA06465B91544FEBA455374DF7DAB02F', 9, 'Snuffy Learns To Dance (4091)', 'Snuffy sees Elmo, Zoe, and her friend, Carina the Ballerina, ballet dancing and wants to join in on the fun.  He tries to follow along with them as they leap and twirl around, but ends up crashing on the ground and knocking them down.  Snuffy becomes sad and insecure about his size when they tell him that maybe he’s too big to dance ballet.  Snuffy tries to figure out ways to make himself smaller by imagining himself as a mouse and doing scrunching down exercises, but becomes discouraged since he can’t seem to change his size.  Then, Big Bird, Luis, Maria, and Gabi all reassure Snuffy that they love everything about him and that he is beautifully big and perfect just the way he is.  At the end, Zoe, Elmo, and Carina apologize to Snuffy for hurting his feelings and realize that anybody can dance and that dancing should be about having fun with all your friends, no matter what size they are.  They all dance happily together.', '2005-04-14', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
