INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DE6FD270DD4649B298D62E516E6B7E14', X'363A94F9E0E5441CAA862BE2E9832DA1', 2, 'When Pawns Cry', 'When an early handheld video game system comes into play, will Corey be able to make a deal before it''s game over? Then, a seller brings Rick a tambourine once played by Prince. Will the negotiation have Rick partying like it''s 1999, or will doves not be the only ones crying? Next, Corey checks out a baseball roster signed by Ty Cobb. Is this a peach of an item, or a swing and a miss? And when a program for a silent film hits the counter, Rick and Chum reminisce about their trip to Italy. Will Corey''s jealousy get the better of him, or will he be able to expresso his feelings?', '2021-10-09', 42, '/gQ6dwaqohOlBFpZkbI8jzJy92r8.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
