INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DE7DD601746B4A95918049423C1D1A86', X'A8C6182E05E14B6891A55126CF6C94F0', 25, 'Allies at Last', 'James learns about religious freedom from Moses Michael Hayes; Sarah and Henri are in occupied Philadelphia.', '2002-10-04', 30, '/4wroHduTksqrykKNHTVyBLYoV9q.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DE833C2191F64F27B57209CBDCD8215D', X'70D9E39768134785887D27D034928BAE', 25, 'Pingu Steals', 'Mother sends Pingu to the bakers to get some bread. He is just leaving when he sees the jam biscuits. He notices that the baker’s wife is distracted talking to another penguin and takes one of the biscuits. On the way home he starts eating it, but conceals it when a stranger walks past. He is still eating it when he gets home so he hides it behind his back. Mother eventually asks him what he is hiding and after Pingu tries to hide it, she demands to know what he has, so Pingu is forced to own up and Mother takes him back to the bakers to apologize, much to his dismay! Once there, Pingu is too unhappy to apologize and turns away. The baker comes outside and hears about what has happened and decides that as a punishment, Pingu should help him clean the chimney of the bakery, to which Pingu accepts. Pingu is sent onto the roof of the bakery to free the chimney brush, which has got stuck because the rope is tangled. Pingu untangles it, but unfortunately is still holding on to the rope when the baker tugs on the other end, and Pingu gets pulled down the chimney. As a thank-you the baker gives Pingu a cake in a bag, and he rushes home to show Mother. Mother is pleased and she and Pingu go into the bathroom to wash up. Pinga lookes curiously in the bathroom where they are washing up. But when Pingu and Mother come out, much to Pingu''s dismay, they find Pinga eating Pingu''s cake! Mother decides not to help him or let him make her apologize and bring it back, Pingu shouts at her in an attempt to get it back but Pinga still continues eating it. Pingu is not happy and tells her off.', '1996-08-29', 5, '/qQjuflFYSa4vbDK2wrLu9UbglgP.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DE84E1C8D1FE4A3BA0B21C734319EF17', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 83, 'Running With the Egg: Making a Seinfeld (2)', 'Part 2 of the cast and crew discussing the process of making an episode of Seinfeld.', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DE86D0CBC3BB46D1B944CBD2B5E36D95', X'3EE646E823AE4DECBBC6C7E6A210D55B', 104, 'Elmo plays "Three of These Things"', 'Big Bird looks in his mailbox, and to his surprise he finds a square. He goes outside to find out who it belongs to, and finds that Mike and Maria also have squares of their own which they got in the mail. Telly shows up, displaying the triangle he got in the mail, which confuses them further.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DE8CAB14386D41E1B91B27126F813986', X'4091B13B4DB64857AD2220B5658C6B89', 11, 'Teresa in Love', 'Jennifer throws a Turkish Tea Party to try to help her mother while the guys go on an outrageous golf outing. On the other hand, Dolores struggles with her biopsy, and Joe Gorga reveals too much about Teresa’s boyfriend.', '2021-04-28', 43, '/5NZE43Yn72RVhG9KU76bM9RM0C2.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DE8DD24B1FB8446FB909779752028382', X'05C0E384194C44179F62803EB615E409', 37, 'Drawing with Chalk', 'Title number 0037. Opens with Mister Rogers arriving with paints and paper. Inside the Television house, Peggy Lipschutz draws with chalk while Vivian Richman plays guitar and sings four songs, along with Joe Davidson on banjo, and Charles Kubelik on bass violin. Songs include a song in Hebrew, based on Psalms 133, "John Henry" and "This Land is Your Land".', '1968-04-09', 39, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
