INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DE9151F875464AA7A2B9113DF17D39E0', X'272DB8169822485AB2316E060D0CCB1A', 19, 'DELETE ME', 'Very small dragons do sometimes make mistakes when they meet an old enemy, especially if they don''t notice what he is made of.', '1977-12-22', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
