INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DE939000376744A0889A691D2BA4BDF8', X'0BBD380C5CB846A68838B5D60223C073', 16, 'Twiggy', 'Kermit is skeptical when everyone backstage is terrorized by "the Phantom of the Muppet Show." There turns out to be one, though -- Uncle Deadly, a monster-actor who performed in the theater years ago. After being panned by the critics, he vowed never to perform there again, and not to let anyone else perform either. He warns the Muppets, "Leave or be doomed!"', '1976-12-19', 26, '/d4W2Jd6KWYB88zEPZikyy4t6F56.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DE98A1E5B6F34B63B9CF65DFEE16A051', X'68138DE20900460AB58E480688F1E081', 9, 'The Great Pretender', 'After Ojo runs in from the kitchen scared of a bee, Bear suggests that they watch a bee at a safe distance in order to find out what the insects do other than sting. In the course of the day, Bear, Ojo, Pip&Pop and Tutter find that every creature has a place and a purpose¡K "just part of that many..." great things about nature. 
