INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DEBDE73DC0A348C8891C6E3AAAFE3C8E', X'F593D90C533942F59C885BFD48D04075', 31, 'The Magpie', 'A magpie has nested in the big tree and is causing chaos by stealing everything around the farm. The magpie''s nest soon begins to fill up with loot and Shaun has to come up with a brilliant plan to outwit the burgling bird.', '2010-06-13', NULL, '/gB2zTHHAjvxqc9mfFgV6qCu6ji.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
