INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DEC31BBC9DBB47FEA4AFC28785969CE9', X'22BEBA7F9B8E456393DA46E76ECBA427', 24, 'Gina Adopts A Baby (3)', 'Snuffy and Big Bird want to play with Marco, so they bring over a wagon filled with baseball equipment, rollerskates, a pogo stick, and checkers. Gina tells them the baby is too young to play with any of those things and suggests that they think like babies to come up with games everyone can play together.', '2006-11-14', NULL, '/i91oBYnc2qQKZhOyMSDzEuFxcYr.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
