INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DEC6BFD1FD184F85968218009653DD57', X'F1325B5644E04B6E89BC82CAC30AFEA6', 5, 'Elvis In Concert', 'Pontypandy is holding a Charity Concert and Elvis is to be the star act. Mike and Elvis have got a giant wooden guitar, but they fail to see a cliff and Mike ends up falling down, clinging onto it.', '2012-04-14', 10, '/eqgc1WGXRHMS7ksdc5jB1OSFIU.jpg', '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DEC910DAD5DF4F4ABBF6581B9C64EF52', X'5BA20443D99F482081F66832D3F2BC4F', 4, 'Earthquakes', 'Earthquakes happen when pieces of land in the Earth’s crust scrape together. The crust of the Earth is made of big slabs of land called plates that are constantly moving just a little bit. The plates scrape by one another, and sometimes they don’t move smoothly. An earthquake happens when the plates get unstuck suddenly and jerkily slip past each other. The majority of earthquakes occur along plate boundaries such as the boundary between the Pacific Plate and the North American plate. One of the most active plate boundaries for earthquakes is the massive Pacific Plate commonly referred to as the Pacific Ring of Fire. The fire comes from the volcanoes that form near the edge of the plates.', '1995-11-24', 26, '/38rO4Avkyapnt7P793vQJaGAobt.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DECD91D1571C42EB9B740F02DD6BA2DC', X'02849455D14B476B9603EEF5FB5D2AB3', 17, 'Hot Gossip, Cold Pizza', 'Karen meets with her assistant Matt to find out his involvement in the alleged rumors regarding her living situation. Ashley finally comes clean to her mother about some of Michael’s inflammatory comments, causing more tension between the two. Determined to find out the truth about whether Karen really lives in her house, Gizelle, Robyn and Ashley plan a scheme of epic proportions.', '2018-07-29', 42, '/znXikPmOmQA1mP2emXkfhSzR6DS.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
