INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DED4796E058D46E7BAF0FD9505071E95', X'939D270CEA8E4CC8A5A5E59DF2C8062C', 14, 'Reunion (2)', 'Caroline Stanbury and Lesa dig their heels in the sand and hash out their issues; Ayan reveals more of herself and opens up about her childhood trauma; the ladies exchange gifts to show each other what they think about one another.', '2022-09-07', 44, '/nP9uEftlZAfIcW8FrJCrSP4rl6m.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DEDFB32D050E47A2A8AA6770D92BAF6D', X'5C1B881FAC584D72B63F209952D4F902', 65, 'Episode 65', 'The Rochdale Pioneers  It''s hard to imagine life without supermarkets and nowadays we take clean shops and clearly-marked prices and weights for granted. But 130 years ago finding a shop you could trust was very difficult indeed - until a group of writers in Rochdale started Britain''s first co-op.', '1980-04-28', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DEDFF9BC93E045D1AA2BB5A747C4D6F0', X'B892884D7B564255A4C608F5D0122273', 8, 'Rock and Mineral', '', '1996-10-21', 29, '/y7W4e4O5ZdRPu6bG1tzsuGqQdO0.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DEE2DD9680C64AC7AE71BEA453F589F2', X'4B2A19E02FAE492EBC31F78E63D88EBC', 17, 'Gotham Pawn', 'Save the day with the Pawn Stars when limited edition Batman and Joker Bolin Guitars swoop into the shop. Will Corey be the superhero and make a deal or will he become the villain? Next, a bronze sculpture by M.L. Snowden molds its way in. Will Rick carve up an offer or will the art go unappreciated? Then, a pair of signed Betty Crocker letters get Rick cooking. Will he make a delicious deal or will he find it unappetizing? And later, a WWII era Adolf Hitler pincushion pokes in. Will Corey take a stab at a sale or will his offer be offensive?', '2016-12-12', 21, NULL, '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DEF62741A6DB4DEB8C18B1641927EDD5', X'A4843A51AEEF427C902C7FB3BD670CD4', 7, 'Why Bears Can''t Fly', 'Pip and Pop invite Bear to the Otter Pond for a game of catch, but he keeps getting distracted by other events in the Big Blue House. Ojo and Treelo are pretending to fly and it gets Bear thinking about gravity and things that fly. When Ojo takes a fall and hurts herself, however, after trying to fly for real, Bear has to tell her that bears and kids can''t fly, no matter how hard they try. He also helps Tutter to use gravity to get eggs into his mouse hole. In the Shadow segment, Shadow retells the story of Humpty Dumpty.  Songs  Gravity (Music and Lyrics by David Yazbek)', '1997-10-28', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
