INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DF04D0026CF2418FBFF9129E7F837BB3', X'F760505E28A14D38964D5A2617B5B402', 6, 'Monster', 'From Medusa to Dracula, all cultures have their monsters! In this exciting DVD, students learn what makes things scary and build an understanding of the universal presence of mythical creatures, such as vampires and dragons. Explorer the science behind many myths, identify viruses and bacteria, and uncover our love/hate relationship with monsters of all types, from mosquitoes to dragons.', '1997-09-29', 29, '/mdMxQQGaCfkTQMfmzt6EOPJhcv5.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
