INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DF25958A1F664AEF9D922ACA079C292D', X'02849655BD954D8DAF3B03321918EEEE', 16, 'Madeline and the Giants', 'When Madeline and the girls go to Dr. Cohn for a physical, all the girls have grown several inches except Madeline, who has a dream that she will be Tom Thumb-sized for her whole life. In the end, she feels better when she discovers that Georgette, the tallest girl, has size issues as well.', '2000-12-23', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
