INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DF50C97115EE4BCF9C45AD6AA6F8D5F6', X'23C93536610C41C5AC6BA6B243423258', 11, 'Secrets of the Love Lagoon', 'Stacey gets some heat for her relationship with TJ. Wendy makes a grand invitation to continue her 40th festivities in Panama. Karen hosts a "Love Lagoon" party at her home – full of risqué questions, unexpected answers and one uninvited guest with eight uninvited balloons.', '2024-12-15', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DF5281BADF8445BE81BA0AD19A157FDB', X'F4C403079B5E4263A4E0DFA138131E7F', 68, 'A Magical Halloween Adventure', 'Boo, Creak, Ahh, Shriek! Halloween is the time of jack-o-lanterns, dressing-up, and lots of silliness on Sesame Street. It''s a Halloween extravaganza when the monsters from Sesame Street get invited to a Tricks & Treats party. But when Mumford the Magician has some trouble with his magic wand, Elmo and friends get sidetracked on a wonderful hayride. Share in the surprises as they learn to carve pumpkins, make scarecrows, and discover that monsters don''t really have to be scary! Features special guest star Caroline Rhea as Gilda the Great!', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DF5293DC5266425B9D52558329E9F605', X'119C16D5104745EC8242C72A8EED423B', 26, 'Buster''s New Friend', 'Arthur is lonely when Buster starts spending time with a new super-cool friend named Mike.', '1996-10-23', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DF54C6BFB2A34A058D239978728C8E2E', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 106, 'Trumpet Afternoon', 'Ernie blows his trumpet, creating loud and sometimes off-key notes that bother the residents. Various characters react to the trumpet sounds throughout the afternoon. Despite the noise challenges, the episode celebrates music and Ernie''s enthusiasm for his instrument.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DF5C302C970644CE8FE26FCD631F240D', X'EBC99729CCB74D6482C142708CD7BA85', 49, 'Episode 49', '', '1981-02-26', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DF60029197324945A1C64B2CE8118D02', X'E40E6B639F84449F8E8853209B0906C8', 19, 'Zoe and Rosita Find Abby''s Magic Wand', 'While pretending to be leaping elephants, Zoe and Rosita encounter a mysterious object lying on a crate. Rosita thinks it looks like a popsicle stick, but Zoe remembers where she''s seen it: it''s Abby Cadabby''s magic wand! Rosita wonders what it would be like to be a fairy god-monster and do wonderful magical things for everyone every day - but Zoe advises her against waving the wand, because she''s not a fairy god-monster.', '2007-09-26', NULL, '/l10jqWq3q5AlJSLXkkj1nu7lYMy.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
