INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DF83E5DA9D6C4EA38F6C4E8DD3DA05F1', X'7BC54DF3F32A454EAEF6A9436C35D53B', 36, 'Death of a Goldfish', 'A fish in Rogers'' tank has died. Rogers buries it and, with Bob Trow''s help, constructs a tombstone with a pentagon that bears a fish drawing. In the Neighborhood of Make-Believe, concern hits when the Trolley stops at the Castle and doesn''t move. Eventually, with help from Bill Platypus, they find out that the Trolley simply suffered a derailment, preventing full electrical pickup (as explained earlier by Mister Rogers).', '1970-03-23', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DF8C5FDBB0BE40CEA947B0C577C884B6', X'1C9EA7D3E2544E7B8A9F33EEA9C6C341', 9, 'A Whine of a Time', 'The ladies head to Canada to partake in the annual Toronto Carnival but before the festivities can get started, Porsha gets a few things off her chest after Kandi reveals that Eva has not been the loyal friend she claims to be. Riding high off her recent engagement, Cynthia wonders whether or not Kenya purposely tried to ruin Mike’s proposal. In the aftermath of their recent triple date, Kenya reveals that things with Marc have not improved. As the ladies settle into their first night in Toronto, a surprise guest shows up!', '2019-12-29', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DF90335712EA435495D9112AC8E78890', X'05FA5E1878D241FEAE300C242C7FFB6A', 5, 'Bathtime for Dusty', 'Scruffy dog Dusty is chosen to be the fire station mascot, but first he must have a bath. Dusty is not keen on the idea, though.', '2003-04-04', 10, '/eqo7D6Oa0pEZhx1qFwxYq6bRvjM.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
