INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFA2FB32A9264562B21C1BAF6EC1E237', X'4060AD7F4B8F43938EB166A150B928B6', 11, 'Tough Monster Race', 'Elmo, Abby, Grover, and Nina want to make an obstacle course on Sesame Street. But they don’t have anything to go over, under, around, or through. They wonder what they can find around them to make these obstacles. What if they use a broom to go over, a blanket to go under, pool noodles to go around, and a cardboard box to go through? It works! The friends made the best monster obstacle course ever.', '2021-01-21', 26, '/xi0o6FuEHxOZfzgPy5R5DLmTgde.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFA3129ACA534FC4BA8850099627DE9B', X'69B3BEFE579A43ADA7D6EC30FFE3ADF7', 15, 'Episode 1070', '', NULL, NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFA64DA9864A44D79B6C857D0D1EC1CB', X'4FE93658C46343298E649D523869C2CB', 18, 'Houdini''s Handcuffs', 'The Pawn Stars work their magic when they''re presented with handcuffs and leg shackles once owned by the legendary magician Harry Houdini. Will a sleight of hand help them unlock an amazing deal or will everything disappear in a puff of smoke? Then, a seller rushes in with a Vince Lombardi Super Bowl Trophy from the 1999 St. Louis Rams. Will Rick and Chumlee throw a Hail Mary for the game-winning touchdown or will a bad negotiation force a fumble? And later, Corey and Chum come across a collection of comic buttons found inside Pep cereal in the 1940''s. Will this old nutritious breakfast give the boys an edge or will they find it''s all too much to stomach?', '2011-01-17', 21, '/jcr11ZuzHXAxPWRmHLR5SvGExWv.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
