INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFB1070E214A4C3288335C241168B78D', X'5BA20443D99F482081F66832D3F2BC4F', 16, 'Heart', 'Your heart pumps your blood around your body, all hours, every day of the week, to keep you alive. Your heart is about the size of your fist, and it’s made of special muscle called “cardiac” (KAR-dee-ak) muscle.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFB25F996F194BDD8B14D5C4DE0947F8', X'F13CB62284E34654A8F10CEAB09A9CA6', 10, 'Franklin''s Bargain', 'When Bear buys a neat detective kit at Mr. Mole''s shop, Franklin is disappointed to learn that they''re all sold out, but Bear tells him that he can get a "Super Snooper Spy Kit," however, he''ll have to get it before it''s sold out. Franklin checks his savings and finds that he doesn''t have enough money. Hoping to earn the money, he decides to strike a bargain with his Dad to get it by doing an extra chore. He first deals around doing the dishes and then fails keep up his end of the bargain after agreeing to a different chore.', '2002-05-27', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
