INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFB46E7100DF4E0EA43FC01F0D928550', X'BCAB920A51A54CBBAA5941578A0EB005', 7, 'It''s Expensive to Be Me', 'After her explosive encounter with Kim at Kyle’s game night, Lisa Rinna vents to Eden. Erika records the music video for her new song before jetting off to Mykonos, Greece, with Kyle. Lisa Vanderpump’s son Max begins a quest to find his biological parents, while Dorit tries to find common ground with Lisa Rinna and Eileen.', '2017-01-17', 43, '/u9ix1RWnsgdB4d3Rey6q2U8rtvk.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
