INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFC44CC946AB4D2D9DF0ABCEDDE80161', X'DB958AF49A9A4533AF9BF0FF590D1DD9', 14, 'Rat in the Street', 'The Catanias go out for a celebratory family dinner, Paul and Brittany included; Frank continues to poke at Paul as Paul hints there may be more than just one wedding in the group''s near future; Rachel and John share big news with Jaiden.', '2023-05-09', 44, '/hJ0XZuZnttLrZ8vljIgYR2Eo8zv.jpg', '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
