INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFCAFD41C41F433D9939AF13DE227B0A', X'10E64538C78A4CB082F917D14256DBAC', 3, 'The Shirt', 'Frankie is shocked when Mike trades in his flannel for a Hawaiian shirt. Sue accidentally tells Devin that Axl loves her, leading Devin to question their relationship. Brick gets overambitious while cleaning the bathroom.', '2015-10-07', 22, '/dsduoxSPDjYXR7wfDJdkhNtBTgd.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
