INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFCC9167380848FDB476C0FEBACC9B58', X'9D74600D722247C1BD1B635F5B41B7D1', 8, 'Imogene''s Antlers', 'LaVar visits the Philadelphia Zoo in Pennsylvania to learn about animals with horns and antlers. In today''s featured story, a young girl wakes up one morning to discover she''s grown her own pair of antlers.', '1986-07-02', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFCD8BD591964BCFAE3515D4EE9590A4', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 61, 'Episode 2026', 'Characters explore surprising adventures around Sesame Street with unexpected twists at every turn. Each moment brings its own special kind of fun and learning.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFD048835567497E9E6FA70B703198BB', X'C6D5CF79F2B040AFAD1291AA4F1B1D21', 10, 'Yay or Neigh?', 'When a customer soars into the shop with a rare H.G. Wells book, and an astronomical asking price, will Corey shoot for the stars? Next, there''s no horsing around when a statue made of turquoise moseys on in. Will it be a yay, or a neigh for Rick? Then, Chum spins over to LA to have a record collection appraised. Did he scratch on this deal, or will their value be music to his ears? And finally, Rick casts his line at a vintage Plymouth ''Cuda muscle car--but will it be enough for its owner to bite?', '2022-10-12', 42, '/fkFlGG6hUM3uGXcKdblXox8hU7g.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFD09DD4561D4B589135D39BFEC288A9', X'A0FA50759CE148C199950C0FD866E549', 11, 'Mind Your Business', 'Sutton takes Garcelle and Kyle to visit her childhood home as old wounds are reopened. Dorit and PK reconnect, but Erika senses a trap. Bozoma is ready for the next step of her fertility journey, but not without her daughter’s approval. Sutton confronts her mother about the past and their future.', '2025-02-11', 43, '/4xHWruEuDDiwNb8VamrXXXRIOFd.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFD894660CD34840AD5C5487145DB61B', X'8BAE6AA34B554FA6BC158F4317BD1F13', 19, 'Episode 19', 'X wants to ask King Friday for a job. He earns the title printer of Royal calling cards.', '1972-03-16', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFDCA8754B1B477F9F70884E69250D9F', X'2E6EE129B32E4417950056F1CC9BC434', 5, 'Silent Lotus', 'This episode takes a look-in at deaf culture. LeVar discusses forms of communication that doesn''t involve words, like hand signals, mime, and gestures, like in charades. He also asks a friend who is a deaf actress to teach him some sentences in sign language. Lea Salonga reads the featured story of a shy young girl in Cambodia, whose parents realized her lack of communication was due to being a deaf mute, but in noticing her natural talent for dancing, approached the king to request that their daughter be allowed to join the royal dancing troupe.', '1993-10-15', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFE1204254FF4CC68A39907633E34F82', X'E93F04C273444B93ABBA8BA1B2F8EB35', 49, 'Cookie Monster’s Cousin Apple Monster Visits (0584)', '', NULL, NULL, '/5oIY0dH1HWkkGJROVGlPUFYLfp6.jpg', '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFE169C8A74C43FC9186F1DE72A0FD2D', X'6B5CAA66F66F4ED1817FA00BAD08790E', 9, 'Reunion: Watch What Happens (2)', 'Danielle''s book is still at the forefront of the housewives'' minds and the ladies chide her for bringing it to the dinner party. Later, Danielle asks whether she was the reason Jacqueline and Dina briefly stopped speaking to each other and both give her separate answers.', '2009-06-25', 43, '/fYjKoTkR9qmL7C9OyLbxkWmqtm2.jpg', '2026-04-03T16:35:14Z', '2026-04-03T16:35:14Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFE21E3B6E984342B4B6A7067275AB71', X'C67A878749714961B5361FF01924E2A9', 19, 'Big Brother Binky', 'When Binky''s parents tell him that they''re adopting from China, he isn''t sure what to make of it at first. He learns that "adopting" means that he''s going to become an actual big brother to a baby girl and will be heading to China to meet his new sister. Binky eagerly assists with preparations for the big trip and the new arrival, but begins to become concerned that his parents will no longer have any time for him. After his worries are eased, the big moment finally comes. At first, Binky is ill at ease around his new sister, who seems to cry a lot, but then discovers a special talent. Back at home, he''s eager to show off his new talent to his friends, but finds that he seems to have lost it.', '2007-09-07', 26, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFE7174C0DF14D5EADC9A3103F19C1C7', X'E6EA14319E67463783AEA11073E8C7E0', 4, 'The M Word', 'Kyle reflects on her career when her 7-year-old daughter, Portia, expresses an interest in acting; Lisa Vanderpump invites the women over to show off the mini-horses; Lisa Rinna makes a shocking suggestion about Yolanda''s health.', '2015-12-22', 43, '/iNiJ9gRIKWEeHFoiFG33sfmmdFN.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'DFEFB921148A409B83A7F67729B7B0CC', X'9193E795DA7C40ECB68FF63AA7D5174F', 138, 'Histories & Lore: Robert''s Rebellion (Barristan Selmy)', 'Barristan Selmy recounts how he was named to the Kingsguard, saw King Aerys descend into madness but revered Prince Rhaegar Targaryen. Barristan describes the fateful Tourney at Harrenhal, the ensuing War of the Five Kings, and how he fought beside Rhaegar at the Battle of the Trident where he was killed.', '2016-03-15', 6, '/fiH6P2z9BtAconZ5V70J9av0jPr.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
