INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E04435895DD74565800156E3DE778063', X'D5351B608A0C482AA6DD4FB860CFE143', 17, 'Episode 1407', 'Mister Rogers arrives with three balls and a film but does not get the opportunity to show any of them before Mr. McFeely arrives with a film about tadpoles.  In the Neighborhood of Make-Believe, Bob Dog and Francois Clemmons are playing fetch with a ball when Lady Elaine joins in for a moment.', '1975-03-11', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
