INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E04DFCCF926747E5B7E44C87C2E165C6', X'2B968A9C5FC04E93BCF931D3E4C7B210', 66, 'Episode 66', '', '1976-04-26', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E051AB56301B466A8D4475F0FC788AF3', X'90CC8678A14F4D05BC1E54A3117895D5', 5, 'A Joke Backfires', 'Its spring and Vixen finally gives birth to her cubs. The animals all gather to congratulate the new parents and to help decide on names for the four cubs. The poachers still plague all the animals in the park but when the warden returns they believe their troubles to be over. However the poachers continue to hunt in the park while the warden remains ignorant to their nightly activities. Fox sets into motion a plan to get rid of the poachers by bringing them to the attention of the warden. Wandering round in the open and calling out they finally spot him and give chase - straight to the warden''s cottage. Hearing gunshots the warden runs out and catches the poachers in the act, putting a stop to their hunting for good.', '1994-02-04', 25, '/cQBxmW9rY8Pb6YY4C0fu5hR7Mbp.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
