INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E0575A48AEB9457882B41243C184D65C', X'ECB64EF34F8045A7B4A9C04434B02E35', 9, 'Smurf and Turf', 'Go six feet under with the Pawn Stars when the guys check out a 19th century Fisk iron casket. Will this eternal tomb hold Rick''s interest or be left for dead? Then, Corey and Chumlee toy with the idea of making an offer on a massive Smurf collection. But will a tough negotiation leave them feeling blue? And later, Davey Deals is a long-time friend of the shop, but what happens when said friend overstays his welcome?', '2014-01-30', 21, '/e522mtxHcR7bmougyrYP3KC0rFC.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
