INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E06EFCF4765F4F159F6680FED8610BBC', X'DD4554C26E74499A808A7DAD5F2BE50F', 12, 'Rabid Dog', 'An unusual strategy starts to bear fruit, while plans are set in motion that could change everything.', '2013-09-01', 48, '/5VkI8lm7Xcmlxk92pWRyW341d70.jpg', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E070826C049841928C1DCC06355920D4', X'70D9E39768134785887D27D034928BAE', 8, 'Pingu and the Birds'' Mother', 'Pingu pushes a box containing some fish out of the igloo, and lays the fish out in a line on the bench. He walks off, but then sees a seagull fly overhead carrying a fish. It appears to have come from the direction of the igloo. He goes back to the igloo and sees that one of the fish he put out has gone missing! As he’s standing there, the seagull swoops down and grabs a fish. Pingu then hides under the fish box, and when the seagull comes back to take another fish he grabs it. There is a tug-of-war for the fish between Pingu and the seagull. This ends with the seagull getting away with the nice parts of the fish and leaving Pingu holding the skeleton, complete with head and tail. Pingu is rather annoyed, and goes to find out where the seagull is taking the fish. He sees it fly to an ice tower, and sneaks up to the bottom of the tower. When the seagull flies away, Pingu climbs up the tower to see what is going on. He finds a nest containing three baby gulls. The mother seagull comes back with another fish. Pingu realises that he left the fish at home undefended and rushes back, but arrives just too late to stop the seagull taking yet another fish. He is annoyed, but then hears the seagull cawing as it searches for fish to feed the baby gulls, and he decides to help. He puts the last remaining fish into the fish box, puts the fish box onto his sledge and goes off. When he goes past his neighbour’s house he spots two fish hanging on the line and takes them. The neighbour comes out and wonders what has happened to the fish, and goes to talk to another penguin nearby who is outside his igloo, cutting wood. Pingu spots that this neighbour has a fish hanging in a bowl, and takes it. He goes past another igloo and takes the three fish he sees hanging there as well. He then goes back to the seagull’s nest and, when it flies away, tosses the fish he has collected up to the nest. Pingu is very pleased at what he has done for the seagull and goes home. On the way he passes the three neighbours who are talking together, wondering what has happened to their fish! The seagull circles above Pingu, cawing, and he waves to it.', '1995-08-03', 5, '/yRfvJQjOwJ0lnLlMJWygqwsjIrY.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
