INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E0B8486921DF4AAE90EF08DB6F3BE087', X'8BAE6AA34B554FA6BC158F4317BD1F13', 16, 'Episode 16', 'Rogers demonstrates the different sounds made from bells and crystal glasses filled with water. Joey Hollingsworth tap dances in the Neighborhood of Make-Believe. King Friday and Queen Sara present Henrietta a bell for babysitting Prince Tuesday, but it makes X jealous.', '1972-03-13', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
