INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E0BEEB5048BA4FE0A6183A3EB2E5847A', X'0442FB97146049238558B994078DC6B8', 4, 'Celebrations and Strange Explanations', 'Gizelle struggles with the fact that her daughters have questions about her rekindling a relationship with their father, and turns to her best friend Kal for guidance. Candiace and Ashley finally bury their year-long feud, meanwhile Monique expresses her marital frustrations to Chris. Karen decides to throw a lavish housewarming party, but Candiace and Gizelle’s spat almost puts the celebration on pause.', '2020-08-23', 42, '/dgIXmF8oOK9BthfG4eJeHcvRtdU.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
