INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E0CAA8955ECD43D5B74D2148498F9E69', X'84A2412422904B86AA885514DA7BD0B6', 5, 'Things to Wear', 'Using a portable sewing machine, Rogers shows the stark contrast between clothing of today and clothes of the 1700s. Then he visits a building in Colonial Williamsburg. In the Neighborhood of Make-Believe, Lady Elaine and Betty Okonak Templeton exploit the loophole in King Friday''s three-cornered rule. Finally, everyone else takes off the hats.', '1994-03-22', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
