INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E0CE6A6D77DA4A23A522F357252CD6B5', X'F5C042DC065742E8A37D247414140632', 18, 'Reunion (2)', 'In the conclusion of The Real Housewives of Dallas season 5 reunion, Tiffany and Kameron spar over chicken feet, cultural stereotyping, and their social media war. D’Andra defends her name change and reveals shocking new facts about the battle over her inheritance. Brandi talks candidly about her unexpected pregnancy, her missteps with Tiffany, and her husband’s recently surfaced betrayal.', '2021-05-11', 44, '/SHqLNP5tQh8Qh9vnUzt6icwCrH.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
