INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E0CFE209EC6F4943B623A5E166C42E90', X'BC6D3E376E5E472D90AA4C6DF1F7DEF8', 13, 'Anthropologists Move In', 'The Browns have agreed to do something they have never done before -- allow total strangers to move into their houses! Two anthropology students will live with the Browns for several days to get an unfiltered look at their polygamist lifestyle.', '2015-02-08', NULL, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E0D116A3B91C40249CC8A85DF23ACAEB', X'2F8DD62982C34F8E87C0963473C49284', 7, 'Dodging Rumors', 'Ubah considers the next steps in her relationship; Erin and Racquel go on a double date; Sai and her daughter get a surprise; an alleged secret spreads throughout the group.', '2024-11-12', 43, NULL, '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E0DBF7602DD246EF9E57E4BD2EC4D606', X'3B5C322F56504381948F712C5AA2D0A5', 2, 'Bread is for Eating', 'LeVar Burton focuses on the art of baking bread and its cultural value throughout the world. Bread is considered to be the most basic food that we consume. It can be fun to make, tasty, and it''s part of a balance daily diet. But in many cultures, the making and comsumption of bread takes on an even larger meaning for many. The Hopi Tribe of northern Arizona bake their bread, bekee, on a hot stone outside. In keeping with Native American tradition, the stone is always borrowed and a family member is invited to help with preparations. This time is viewed as an opportunity to draw closer to one another and nature. In the Indian culture, no meal is complete without bread. Nan, the basic bread is spicy and baked in a clay oven. This episode''s suggested books are "Bread is for Eating", "Bread, Bread, Bread", "The Tortilla Factory", and "Walter the Baker."', '1996-10-08', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E0DC2C5E5CE24ED1B57F47E3A440ED86', X'4F3632B8A91046B6B2EDF2882CC14B2D', 9, 'The Sesame Street Square Game (4065)', '', '2004-04-15', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E0DC9FAA8A2B44D094AA9ABE72433BA4', X'9193E795DA7C40ECB68FF63AA7D5174F', 14, 'Red Nose Day ''Game Of Thrones'' Musical', '“George R.R. Martin meets Chris Martin – what could go wrong?” That’s Emilia Clarke in the epic, 12-minute video for Coldplay’s totally fake Game of Thrones musical, right before she rips into a song called “Rastafarian Targaryen.” Here’s a sample lyric: “Call me Daenerys Targaryen when you want to reach me, and if you feel the love then you can call me Khalessi.” The sketch, part of Red Nose Day, includes cast members Kit Harington, Peter Dinklage, John Bradley, Rose Leslie, Charlotte Pope, Thomas Brodie-Sangster, Alfie Allen and Nikolaj Coster-Waldau, who performs a piano ballad called “Closer to Home” to a photo of Lena Headey as Cersei. (“Are you thinking about Joffrey? Such a spirited lad. I was his uncle, I was also his dad.”)', '2015-05-22', 60, '/kOk3k9QGezLWMGFGAovukX3R67m.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E0DCFCF7076448AA8086286351010841', X'4C79C0B621A442778967BE1E791EFDBE', 12, 'Pingu Gets Carried Away', 'Pingu is on Father’s motorised sledge, pretending to drive. Father comes out and tells Pingu to get off. Pingu is so downcast that Father says that he’ll give Pingu a driving lesson. Pingu and Father get on, and they set off slowly, Pingu driving with Father’s assistance. It’s not long before Pingu wants to go faster, and he gets very excited. Father tries to control him, but in the confusion the drive stick gets pushed to full and they go whizzing off, crashing through some hanging washing. Pingu then manages to break the drive stick, and they plough through a snowman and into a candy stall. The stallholder runs away from the sledge, which follows him, stopping inches away from flattening him against some ice. The sledge starts to go backwards, and is only saved from going into a pool by Pingu throwing the decorative candy from the stall, which got caught on the steering earlier when they hit the stall, in the way so that the driving tracks come off the ground. Pingu, pulling the decorative candy, and his Father walk back to the candy stall, apologize to the stallholder, and Father helps to put it back up. After this, they clean up the mess, but Father wants a lollipop, but the stallholder won''t let him, to Pingu''s digust, who bursts into tears, who tries to get comforted by Father and the stallholder. They can’t put the decorative piece back because the chain has broken, but the stallholder has a different one that he can use. They leave to get the sledge with Father carrying the lollipop and Pingu pulling the decorative candy. When they get back to the sledge they can’t get it going because the drive stick has gone, but Pingu has the idea of using the lollipop stick instead. Then Pingu, not trusting himself with the sledge, won’t get on it, but Father has an idea and he ends up driving back towing the decorative candy, with Pingu sitting on top.', '2005-11-25', 5, '/s2ZH7SYybMLuHludw4SZEDgOWpW.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E0DD7081418B448CA54357FC567C412F', X'C01DDD2ABDB14C978D0458F791EF1C24', 16, 'Itchy', 'Everyone has got an itch, whether it''s from poison ivy, bugs, or burrs.', '1999-02-15', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E0DF59FCAA0643918785A1FEB6BDEE3A', X'CA19F89515144988A70995E84EAB7CEE', 15, 'To Infinity and Be-pawned!', 'Rick tries to win one from the Gipper when a special pendant hits the counter. Can the patron saint of pawn shops help Rick land the deal? Next, a massive collection of vinyl LPs has Chum''s head spinning. Can he get into a groove with the seller, or will this deal get scratched? Then, it''s happy days for Corey when a dress from Laverne and Shirley comes into the shop. Will he be able to skirt the issues with this item? Or will Corey take the L and let the dress walk out of the shop? And finally, Rick and Chum get fired up when they head to the desert to shoot the shop''s newest firearm. But their canon feels quaint when they spot the big guns - and Rick might just explode from jealousy.', '2021-04-26', 42, '/8rL5vId3dcylfJCXDsZD5X8GaCW.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
