INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E0E3F3A935254FF1849472C2150A9120', X'CEFD1496B6494C62AEF935A22558AC08', 1, 'Look Who''s Not Talking', 'The Housewives take sides as Brandi and Stephanie reveal that a summer-long feud has ended their friendship. And who of all people has become Brandi’s friend and confidante, but LeeAnne Locken. Meanwhile, an old police report about LeeAnne’s past resurfaces, threatening to derail her new goal of controlling her anger. And everything comes to a head at Cary’s birthday party for Mark, where Brandi and Stephanie come face to face as two new housewives join the cast in the Season Two premiere.', '2017-08-14', NULL, '/fDfYJtsTN02z0YNtWRxfzPwEjDK.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
