INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E109F33C3752459CAE0F22E6843A058E', X'3B5276CEBC2043EBA638FE5CED3178A8', 4, 'The Last of the Starks', 'In the wake of a costly victory, Jon and Daenerys look to the south as Tyrion eyes a compromise that could save countless lives.', '2019-05-05', 79, '/qe508xwVVO7cF2oWzfJp52StkTk.jpg', '2026-04-03T15:40:38Z', '2026-04-03T15:40:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E10C2E0C5F464204B078DC0CE56AE48A', X'7C75633629DB4634B976E993E8F51DA2', 13, 'Reunion (1)', 'The ladies revisit this season’s highs and shady lows as suspicions surrounding Karen''s move are revealed and the question of who will claim the new title of “Grande Dame of Potomac” is answered. Gizelle and Monique go head to head, while Charrisse disputes cheating allegations. Rumors continue to swirl about Robyn and Juan’s relationship, leading Robyn to call out Ashley for her meddling. And the reunion takes a shocking turn when Charrisse accuses Gizelle of having an open relationship in her first marriage.', '2017-07-09', 42, '/oUg4Blc1GkDgQLT7kgITQvMm2De.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
