INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E115A313593F44B48A7746E101768A26', X'AD4E434833344A088928455D9BA524C1', 13, 'Glenda Jackson', 'Glenda reveals herself to be Black Jackson the pirate captain, and she takes over the Muppet Theater with the help of Short John Silver (Sweetums) and Eric, a heartless pirate parrot (in disguise as a penguin). They tie Kermit up, turn the theater into a ship, and cast off to look for buried treasure. The show ends with a musical battle at sea, with Gonzo and a crew of chickens fighting to save Kermit and the theater.', '1980-12-28', 26, '/fph4B4dfemicHv0rrXoCEy4PvQC.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E115DFF729D34BE48C18F3CFF4416935', X'A6EFE88301134477BF0657B42A3770EE', 23, 'The Finale (1)', 'The gang plans a trip to Paris to celebrate after NBC picks up Jerry and George''s sitcom. But there''s an in-flight emergency, stranding them in a small town.', '1998-05-14', 56, '/eYxgFMhFfoz742lfOCgLFROg5iT.jpg', '2026-04-03T16:34:12Z', '2026-04-03T16:34:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E119CE288D1F4F4EAAF74EAFC167C988', X'27A5A980EC0D4637B5BADF8324A6405A', 21, 'The Guidance Counselor', 'Sue finds a kindred spirit in her awkward school guidance counselor, Jane Marsh (Whoopi Goldberg), who inspires her to reinvent herself. Meanwhile, Frankie is ecstatic when she and Mike buy a much needed new bed but is gobsmacked when her stubborn husband insists on assembling it himself; and Brick attempts to call the President to outlaw the Presidential Fitness Challenge, which would force him to accomplish some strenuous physical exercises at school.', '2012-05-02', 22, '/AmV8EFmBDnjvVGT4KNB7QlFYhUu.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E11ADFBC811F45DAA668C01E8499E720', X'EA73E13C696248048305C303DF65F89F', 31, 'A present from the king and queen', 'In the Television house, Rogers plays a matching game. In the Neighborhood of Make-Believe, the Royal Family give moving frames to X, Henrietta, and Lady Elaine.', '1969-03-24', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E11C8EC8FC524A6ABDDD0F857A1BFB6A', X'5213521551604D429D0FDB242B1ABCAA', 1, 'The Wonderful Towers of Watts', 'LeVar visits Watts, a neighborhood in Los Angeles. The featured story is about Simon Rhodia and The Watts Towers. Also featured are young Watts residents trying to make the neighborhood a better place.', '1995-10-02', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E11E274566F4469B8017C97EB713E4E3', X'3982796B54514100904246BEDF6A20A5', 24, 'Pingu and the Stranger', 'Pingu has gone out to get some fish from the fish stall. While he’s on the way, two strangers enter the village, and are shunned by everyone they meet. Pingu arrives at the fish stall, gets out his shopping list and is about to tell the stallholder what he wants when the stallholder sees the two strangers, who are just behind Pingu. The stallholder quickly closes the stall and walks away, leaving Pingu without any fish to take home. Pingu walks away, but hides behind a nearby igloo, and then surreptitiously follows the two strangers out of the village to a nearby ice pool. Another penguin is fishing. One of the strangers takes out a shell horn and blows it, getting a rasping squawk noise. The two strangers look up, and soon a fish drops from the sky into the hands of one of the strangers. Pingu is amazed. The stranger with the horn blows it again. Another fish drops from the sky and lands on the ice nearby, but this time the penguin fishing and Pingu are looking up, and they see that a seagull is dropping the fish. The strangers offer the fish to the penguin fishing, but he refuses and hurriedly walks off. Pingu comes out from where he’s been hiding and walks up to the strangers, who give him the fish and let him try the horn. Pingu blows, but only gets a gentle squeak from the horn. The strangers urge him to try again, and he gets a raspberry sound. No fish is dropped either time. Then the seagull swoops to catch a fish from the pool, and as it flies overhead the strangers urge Pingu to blow again. This time he gets a better sound, and the seagull responds with a squawk, dropping the fish it has just caught! The fish is given to Pingu, and Pingu then soon fills the basket with fish. As they’re waiting for the seagull again some of the villagers come to look at what is happening. The next fish dropped by the seagull lands on one of the villagers, and after initial amazement they all laugh. The horn is shown around and the villagers chat happily with the strangers.', '1994-09-14', 5, '/3vPNkuLX1UMdNLntOBiBgXzg2QI.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E12C65FDEA794EEA92A91177E6DD9FD6', X'56FC62048C9D4BA3A4E70D0A7DE40DC3', 9, 'The Dinner Party from Hell', 'Camille throws a glamorous dinner party at her Malibu home and, in addition to the housewives, she invites a few special guests. The guests, however, bring up a sore subject and sparks fly between all the women in an explosive showdown.', '2010-12-16', 43, '/jS8ocDmpIIVIymtHLlo5iGiYiT.jpg', '2026-04-03T16:34:54Z', '2026-04-03T16:34:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E12DCD1B093C47A5A46FE843C0165BAE', X'151E88A195764BD1B84AC4D64C1C9FE8', 16, 'Altitude Adjustment', 'Kyle charters a private plane and flies the women to Aspen in style, but Dorit packs emotional baggage along with her snow pants. The mountain weather isn’t the only thing that’s cold, as Garcelle and Sutton ice out Erika in a very public fashion. Kyle’s ski chalet goes from cozy to creepy when Rinna summons the spirits with a Ouija board. Diana and Sutton’s feud is rekindled after a combustible word leaves the ladies fuming.', '2022-08-31', NULL, '/1fHXpiww3mJ9LptnT2M9yjXwNzB.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
