INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E131EF5127AB424A89CBAAFE10498E4B', X'F829D1FB64EA430F8E0EB3345653A542', 9, 'Island of Snakes', 'Steve Irwin travels to Sri Lanka to help laborers contend with some of the most venomous snakes in the world like the Russell''s vipers and the cobras. And, for the first time in his life, he goes head-to-head with a man-eating mugger crocodile.', '2004-06-16', 44, NULL, '2026-04-03T17:39:12Z', '2026-04-03T17:39:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
