INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E16145107B9D40459E3F898EC1CCA770', X'2AEBFAD431454BC19DEF5F1D5BDFCFC8', 22, 'The Parking Space', 'George argues with a stranger over a "dream" parking space in front of Jerry''s apartment.', '1992-04-22', 24, '/i1nIU4Xc3rRhMmk7Ul6JDInVorz.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
