INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E16634DA8BC2471D86DA7D87ABB65A29', X'98D80972E53A43DDA03A7703465E6F87', 34, 'Hello, Goodbye', 'Get by with a little help from the Pawn Stars when alternative artwork for "Sgt. Pepper''s Lonely Hearts Club Band" rocks into the shop. One of the Beatles'' most iconic albums, will the guys twist and shout for this piece of music history? Then, Rick eyes a pair of lithographs by Joan Mir and Marc Chagall. Both leaders of the Surrealist movement, can he dream up a deal? And later, the guys get a little starstruck when actor Steve Carell wanders into the shop. Will it be just another day at the office?', '2013-03-11', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
