INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E16BAB0A8A594487A02321B72FC29BA6', X'9AE29D087CE847F985842D3E861067A8', 8, 'I See You', 'The family waits for news about Hank. While Jesse covers at the lab, Walt attempts to placate Gus. After witnessing a disturbing outburst, Walt worries he and his family are in danger.', '2010-05-09', 48, '/edBDR59bzVWdMtCawimRzOMgrlW.jpg', '2026-04-03T15:40:33Z', '2026-04-03T15:40:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E16EB0513441474EA13548C102945B97', X'F0F8B366CB3340B3A50FA1CA7780916F', 2, 'The Riddle of Rhyming Rock', 'In setting out to solve the riddle of Rhyming Rock, Gobo learns from the Storyteller about a book of magic spells his Uncle Matt discovered. The book includes a spell for solving riddles. But he doesn''t hear the whole story and when he uses the spell everything goes wrong and Gobo has to find a way to right the damage he has done.', '1987-01-12', 24, '/9FxVexgFhOIfIk0CVcYnq47Htbf.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E170774A02AE4EBD9DFCBB84069F15D4', X'3D4E0E451C67475EB37D9E7E6B8B942A', 9, 'Pup Fiction', 'Intrigue and mystery surrounds a letter addressed to Wanda.  In trying to trace the anonymous note, Wishbone drifts into Jane Austen''s gothic horror novel Northanger Abbey.', '1997-03-11', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
