INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E181DD99AE39440AB953B383BAB4EDE1', X'4B2A19E02FAE492EBC31F78E63D88EBC', 16, 'Silver Stash Pawn', 'Laugh it up with the Pawn Stars when a first edition of The Adventures of Bob Hope comic gets Rick and Chum chuckling. Will they entertain an offer or "boo" it out of the shop? Then, an ancient Egyptian mummy mask gets Corey all wrapped up. Will he preserve a sale or will the deal be deceased? And later, things heat up when a 1950s Disney fire extinguisher blazes in. Will Rick add fuel to the fire and make an offer or will the flame fizzle out?', '2016-12-05', 21, '/nfmw3z9q5l5lvDX3u7wkUacLrIe.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
