INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E184A4A5AD064769A72B68413327CBF0', X'ABFE14EEDB424DDEA96A601FF3C53ECC', 2, 'Cluny the Scourge (2)', 'While Redwall prepares for a long siege, Cluny steals the symbolic tapestry of Martin the Warrior from within the abbey, and Matthias learns that Martin''s great sword still exists - but nobody knows where. As Cluny''s next attack is repulsed Matthias meets a new ally, Basil Stag Hare, and learns that his own destiny is inextricably linked to his hero Martin. Matthias will become Redwall''s next protector - but only if his quest for the sword is successful.', '1999-09-11', NULL, '/aYDRXIunGis0pJHyZx2Ft6W76uR.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
