INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E1D2F3089F124734BA8B762853366D50', X'BD8A516B9872472DA8387AFF1070FEA3', 3, 'Milton Berle', 'Fozzie Bear is so intimidated by the thought of meeting Milton Berle, "the King of Comics," that he spends the whole show hiding from the guest star. His flimsy disguises don''t fool Kermit or Scooter, but when Fozzie finally overhears Milton saying that he''d like to do a song-and-dance with him, Fozzie springs out of hiding, and the pair performs "Top Banana" together in baggy pants and big shoes.', '1977-10-14', 26, '/kpuNRWoTIbeRJrgOxFevpSNUcW9.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E1D39F8F885A4AA8B7E1D6C2BE794B50', X'5144DE59E67F4FCF919B7106989AB797', 7, 'Butterfingers', 'The kids hold a relay race, but Ben drops his baton, prompting the nickname “Butterfingers” from everyone else. Nuzzle tries to show off his bravado by wanting to be called “Professor Muscles.”', '1995-01-24', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E1D4D52EB1FD48D7AFDFCCDC4B66B4B9', X'70C8CB4624944DD498F66BFB9B3FAF73', 20, 'The British Are Coming', 'The Pawn Stars are presented with a classic 1946 Seeburg Jukebox. Will the gang tune up their wallets and hit a high note of a deal, or will it become the day the music died? Then Rick and Corey meet a man hoping to sell a 1775 Massachusetts war bond but is there something special hidden in the engraving? Finally Rick and the Old Man check out a 1965 Chevy Impala. Having fond childhood memories for this car, will Rick be swayed by nostalgia and rev up a good deal, or will the Old Man bring it all to a screeching halt?', '2010-04-25', 21, '/kvEUr27uKVdQFlmq0KCIvo5PST3.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
