INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E1E42D7DF7184A5AB7AE4A4DB56162F8', X'BD8A516B9872472DA8387AFF1070FEA3', 11, 'Steve Martin', 'Kermit cancels the show in order to audition new acts. Guest star Steve is angry at first, but he goes on to perform for the cast. Fozzie worries that Kermit plans to hire replacements, especially after the audition of a canine comedian, Baskerville the Hound. Kermit tells Fozzie that he should appreciate seeing another artist''s work -- until Lenny the Lizard auditions as a new emcee. A young singing girl, called Mary/Terry/Carrie Louise, is systematically removed off, when she makes an attempt of audition with her croaking partner.', '1977-12-09', 26, '/uxKypdheEHNdpzwekHMQ1arvzHH.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
