INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E2176646FCC241ED92BF20B1F05E30C3', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 11, 'La La Land', 'It''s "Lights, Camera, Action!" as Rick heads to LA on a shopping spree for the shop. First up, the largest collection of Willy Wonka and the Chocolate Factory props in existence. Will he be able to make a deal, or will his hopes of owning a piece of the film be everlasting? Then, Chum checks out a helicopter owned by Vegas magician Dirk Arthur. Will their deal take flight or disappear? And later, Rick gets offered a painting done by Leonardo DiCaprio. While the actor isn''t known for his art, will Rick see a potential for profit or leave this piece in the city of angels?', '2017-05-22', 21, '/kC6wgCj5LfAwPvse0xAabGZE1LE.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
