INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E2419562A0B84798894D2E6C76D3D47C', X'F4C403079B5E4263A4E0DFA138131E7F', 104, 'Elmo''s World: Flowers, Bananas & More!', 'Join Sesame Street''s curious red monster as he explores flowers, bananas, and hair! Elmo''s World offers kids and adults a fresh and light-hearted take on the world around them. Each episode comes to life in Elmo''s bright, exciting, and very original room - the drawer, door, shade, and TV all join in the fun. And he''s even visited by a Muppet banana and a talking cactus! Also featuring Elmo''s pet goldfish, Dorothy, the zany Mr. Noodle, and classic songs that will delight viewers of all ages.', '2002-05-14', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
