INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E327E0DDCC4E4ED9A483BF8A3E5F7E2C', X'8BAE6AA34B554FA6BC158F4317BD1F13', 15, 'Episode 15', 'Rogers goes to traffic court to plead the case that led to his parking ticket. Lady Elaine leads a march on the Castle to show that everyone has different interests.', '1972-03-10', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E3295850E1E54B12B58513EF1883F8AF', X'787DFA0BC8274DADA82D0548A6534D88', 7, 'Bowling in Heels', 'Vicki enlists the powers of a medium to try and communicate with her mother. Shannon discovers that to lose physical weight, she has to do more than just exercise, she must deal with the weight of her emotions too. Meghan tries to teach her step daughter responsibility but learns a lesson about parenting instead.  While Tamra and Eddie struggle to work together at the gym, Heather is eager to start a new project with Terry. All the ladies come together for a fun night of bowling and a surprise announcement.', '2015-07-20', 44, '/hLAffab9kUpN5s8OuXiq9ByWiaM.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E32F69FE55B24BF5895695660BB2EA24', X'EBC99729CCB74D6482C142708CD7BA85', 46, 'Episode 46', '', '1981-02-16', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E3300B84A44D49F794E30F93B07C9C23', X'70D9E39768134785887D27D034928BAE', 12, 'Pingu and the Broken Vase', 'Mother goes out, leaving Pingu and Pinga alone at home. They make themselves a makeshift house indoors, using the chairs as walls with a blanket on top as the roof. They take some toys and cushions into the makeshift house, but it collapses on them, much to Pingu’s annoyance. They then have an argument, and Pinga throws a cushion at Pingu, hitting him on the head. Pingu chases Pinga around the room, and throws the cushion back at Pinga. He misses, but hits a vase on the sideboard. The vase falls off the sideboard and shatters on the floor. They then realise that their parents are due back shortly, and rush to tidy everything up. Pingu wraps the pieces of the vase in a cloth and puts it in the cupboard, and tells Pinga not to say anything. Father then arrives with a bunch of flowers for Mother, and is surprised when he can’t find the vase. Pingu and Pinga deny any knowledge of the vase’s whereabouts, but Father becomes worried after he finds a piece on the floor! To Pingu’s dismay, Pinga tells Father what happened and shows him the bag where the pieces of the vase are hidden. Father looks furiously at Pingu, who bursts into tears. Father spots a jar on the dresser and puts it onto the table with the flowers in it, which cheers everyone up. Mother then arrives back and is rather pleased with the flowers, but Pingu is still dismayed when Pinga tells her everything that has happened.', '1995-08-31', 5, '/lrMJJbJJKxDyWr3o2PiRkrsFqxz.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E33F1BC766F24023ABDA0A8B60A12E7B', X'AD4E434833344A088928455D9BA524C1', 10, 'Gladys Knight', 'The theater is under repair, but the workers have to destroy in order to build.  They take the roof right off, leaving this show victim to the elements.', '1980-12-07', 26, '/xbqfgm6kIPfkOwrpX2eJ0coRKAb.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
