INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E395FFB7886C4FD38AB87D527996290F', X'CA09391ADE6A4B2BAEFCC2EFBC80A106', 2, 'The Adventures of Taxi Dog', 'LeVar is a taxi driver in New York for a day, but the focus of this show soon lands on the subject of a service dog as well as how dogs are such good pets to us. Vincent Gardenia reads the story of an adopted stray dog who helps his new owner, a cab driver, get better tips when he entertains the customers on rides.', '1991-09-17', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
