INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E3EE05711E1941CE9043ABC0AEB26A1F', X'BF0F7445F58F467FA81BFCC2BF6BCA21', 16, 'Junior Sells the Farm', 'Junior is tricked into selling the castle by the insidious Wander McMooch.', '1984-04-16', 24, '/f5sk6wEJTpwPZRZHlsYG6uthW2Q.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E3F243B7A5454E8CA82F6D4BEDD12715', X'3982796B54514100904246BEDF6A20A5', 17, 'Pingu as a Babysitter', 'Mother is going out with a friend, and Pingu has the job of babysitting the twins. After Mother and her friend have gone the twins, who were lying peacefully in bed, throw their pillows at Pingu, hitting him on the head. Then one twin cries because his dummy has come out. While Pingu is retrieving the dummy and washing it, the other twin crawls off and pulls the tablecloth off the table. Pingu is just in time to stop the vase smashing on the floor. The first twin then grabs the frying pan that’s on the stove. Pingu eventually gets both of them into their highchairs and feeds them. While he’s feeding one, the other is yelling, and vice versa. Eventually they both stop crying and Pingu checks their nappies. Luckily only one has a dirty nappy so Pingu changes it, and tucks them both back into bed. He then sits down with a book, but they both start to wail again. They don’t want their teddies, but doze off when Pingu rocks the bed. Pingu goes back to the chair, but they start crying so he rocks them back to sleep again. Then he has an idea, and ties a cord to the end of the bed, with the other end of the cord tied to his foot. Now, when they start crying, he can waggle his foot and rock the bed without having to get out of the chair. When Mother and her friend arrive back the twins are fast asleep; Pingu is in the chair with his foot rocking the bed, also fast asleep!', '1993-07-27', 5, '/ZtcDKikHyG53QLyvb78tvjX8Db.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E3F8B5A1B843408E96BAED4BB9034710', X'EFD2082E32F54EDD9A7BA4326D6992C9', 35, 'Cookie Monster''s Museum Mystery', 'A brand-new museum has opened on Sesame Street - the Museum of Modern Cookie! Cookie Monster, Elmo and Chris are very excited to check it out. While walking around the museum, the paintings suddenly begin to disappear and the museum guards think Cookie Monster stole them. With Abby''s help, Cookie Monster, Elmo and Chris catch who really was taking the cookie art. Season finale.', '2019-07-13', NULL, '/qB2NLitBsxBYocOv4VQysLPEMeI.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
