INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E4046370AB2F440D8C6C3BFD9594B44A', X'D7FF9136A8334C43A37CA985A34F45A9', 17, 'One on One: Part 3', 'In this final episode of one-on-one interviews, Kody is confronted with the question of whether he has a "favorite wife." Then, Kody and Janelle open up about the conflict over holidays and reveal the status of their relationship.', '2023-12-10', NULL, '/tGPsETIcrm6BbGxbuxJvPf4Qx8y.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E40EB87688B2436BB6E6A222789DDC5C', X'4FE93658C46343298E649D523869C2CB', 4, 'Getting A Head', 'The Pawn Stars are presented with a classic piece of Detroit muscle - a 1969 Buick Skylark. Will the gang put the pedal to the metal and restore this beauty or will the deal get flooded and stall out? Then, Chumlee and the Old Man look to buy a Civil War field desk complete with captured Confederate documents. Will they sound a charge and seize this rare piece of U.S. history or will suspicion cause them to retreat? And later, Rick is presented with a piece from the jungles of the Amazon - a human shrunken head. Will he slice up a deal for this rare tribal charm or will he decide the shop doesn''t need the bad karma?', '2010-09-06', 21, '/j1HF1yQzB3zx6ObzV500rfQCzOd.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
