INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E42A8D89A462418BAC37196B0A3DE2A8', X'04207E76D8554F29A0661732FEEA34B5', 7, 'Play At Your Own Risk', 'Danielle, feeling empowered after standing up to the Manzo clan, decides it''s time to live again. Jacqueline hosts a poker night with the guys and gets some scandalous information from Danielle''s ex, Steve. Meanwhile, Dina can''t deal with the constant fighting and makes a big decision that changes everything.', '2010-06-14', 43, '/aj6um0p30Zorj81Zft3y5m0K5OZ.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
