INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E42EA991D3D74F1BB614CD5DFF9656CC', X'6F731E6BD3C54DE684E17A19CB650E86', 10, 'Prohibition Pawn', 'March to the beat with the Pawn Stars when a Civil War drum rolls into the shop. Will Rick and Chum like the sound of the offer or will they think it''s out of step? Then, the bases are loaded when an 1834 book with the original rules of baseball is up to bat. Will Rick make a grand slam deal or will he send it walking? Next, things get gnarly when a 1970s skateboard kick-flips in. Will Corey do a 180 and make an offer or will the deal grind to a halt? Then, Chum''s a blind pig when a corkscrew from the Prohibition era turns the shop into a speakeasy. Will it be a straight up sale or will it be on the rocks? And later, things get slushy when an antique cast iron ice shaver is brought to the shop. Will Corey be in the mood for a snow cone or will the seller be crushed?', '2015-11-19', 21, '/wk35ZYk4UZKTIep96kkV4I3pCQU.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E42F9FC72A60451597BB3C74B8EA4A57', X'7B19039A31AC425C8FB1B51CF2447821', 5, 'An Unexpected Guest', 'After her explosive meltdown at Shannon’s housewarming party, Braunwyn finds herself trying to make amends and move forward. Braunwyn opens up to Gina about her life-long struggle with alcohol, and their friendship takes a drastic turn. As Jacob experiments with drag, Sophie continues writing her book about dealing with her parents’ divorce leaving Shannon to worry about the effect it had on her daughters. Meanwhile, Elizabeth struggles to process her sister’s issues. Gina deals with the next steps in the case against her ex-husband and struggles balancing that with their co-parenting relationship.', '2020-11-11', 44, '/nzpt6WUdCB87O7PybYuUT6AmukV.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
