INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E43353F9FF5D47F4ADACC2E9F7BF0BCB', X'1D39506B06B84F9391360208069BD7E4', 7, 'New Girl, Old Money', 'Socialite and single mom Sonja Morgan helps LuAnn throw a charity party. Meanwhile, Ramona proposes that she and Mario renew their wedding vows; Alex, Kelly and Ramona walk the runway at Brooklyn Fashion Weekend; and a stunning discovery awaits Bethenny.', '2010-04-15', 43, '/fRVfNXV8uNHeCV2o1bk043YNFl5.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E437EDFFFD2948BFAF6C862A51CB5E5F', X'BC6D3E376E5E472D90AA4C6DF1F7DEF8', 11, 'Courting Another Wife', 'The blow up between Kody and Christine continues as they approach their final destination. Can Kody get to the root of the problem? Later, the Browns meet another polygamist family, the Colliers and discuss the idea of the Colliers courting another wife.', '2015-01-18', NULL, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E4391DEEF5FC4FEB8F64876D77494025', X'99A9678144CB4A5C910071E2A55B6B1A', 9, 'Frienemies', 'Vicki rakes Jeana over the coals after a visit to her second home, which Jeana is selling, reveals it to be a disaster area. Lauri finally asks her daughter, Ashley, to be her Maid of Honor and attends a food tasting to choose the menu for her approaching nuptials. Lauri’s bridal shower is a smashing success drenched in excess. Quinn tries to force boyfriend Billy to commit while Tamra helps pave the way for Ryan to finally move out of her house.', '2008-01-08', 44, '/tMr40p1DpiS4pS1BBoEdz1NIXVG.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
