INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E4534A17EFA94F089D429919E576AA8E', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 2, 'The Happy Scientists', 'Gordon is grading his classes’ science experiments when Elmo, Rosita, and Telly run in and accidentally land on the papers. Gordon encourages Elmo, Rosita, and Telly that anyone, including them, can be scientists. All they need to do is to ask questions and investigate! They look around Sesame Street and see Leela giving Barkley a bath. Elmo comes up with a question: Does everyone on Sesame Street take a bath? Gordon guides them through the scientific process. First, Elmo and Rosita hypothesize, or guess, that everyone takes a bath. Telly isn’t sure that everyone takes a bath so he forms a different hypothesis. They investigate and record their observations in their journals. They find out that Chris takes a bath, a cat licks itself and takes a tongue bath, a sparrow takes a dust bath, an owl takes a sun bath to get rid of germs, and even Oscar takes a mud bath in his trash can. This makes Telly mad since his hypothesis was wrong-everyone does take a bath on Sesame Street. Gordon explains that it’s okay to be wrong in science because the most important part is the process, or the steps you take to get your answer. Telly, Rosita, and Elmo become happy scientists! They not only learn all about the scientific process, but also find an answer to their important question!', '2010-09-28', NULL, '/x0O9Oc7as81CNw5aOXcMwVNDtw0.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E454D373D68E423D9EDB771D21FB4EBE', X'6A2D283971064C3B8906C9B3E4BFCC8B', 3, 'Fakes-Giving, Fake Friends', 'Dinner continues at Shannon''s OC abode. In addition, Shannon''s marriage is dissected by the others; Heather departs for the holidays; and the ladies address their grievances at a "fakes-giving" feast.', '2014-04-28', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E45FCD0835B843CD954656BD7AB74DE3', X'3EE646E823AE4DECBBC6C7E6A210D55B', 93, 'Cleaning the vacant lot', 'The Pigeon Sisters do some morning strutting and cooing, when Gordon shows off the trash bins the city has provided them. Gordon observes the litter and has a flash of inspiration — they can turn the vacant lot into a garden! He and the pigeons imagine what it''ll look like, singing "I See a Garden."
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E467073036EC46E4A94A6519D097ED76', X'7BC54DF3F32A454EAEF6A9436C35D53B', 23, 'The Clemmonses are Moving Pt 3 - Fish', 'Betty Aberlin gives Rogers a black angel fish for his tank. In the Neighborhood of Make-Believe, she dresses up as one. At the Tree, she introduces a song praising Henrietta Pussycat.', '1970-03-04', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
