INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E46A46B2F31849F2BF74FBCFA1C7BC1C', X'C0C0B0BAE6E34A3095671102881EDDF3', 1, 'Based on a True Story', 'A new girl named Ladonna moves to Elwood City from Louisiana with her family. In order to make friends, she tells the Lakewood students stories about her life. As she continues with her tales, the stories begin to repeat, and the kids are noticing. Ladonna begins to fabricate her stories and is caught by the Brain when she makes an actual mistake.', '2012-10-15', 13, NULL, '2026-04-03T17:38:00Z', '2026-04-03T17:38:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
