INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E47988CD9D3E4C1B86B7878EC82C7D8A', X'1D556682D9BB47E1993F0B648A8DAACD', 47, 'Episode 1232', '', '1979-01-30', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E47DCAFE268040B8B6F20CC9A12F738B', X'0E4196154C964DDE8ED2715770BA77BB', 7, 'Show and Tell', 'Ojo is in a hurry for Tutter to get home from Mouse School so that they can play their favorite game, Cave Explorers. Bear goes to pick Tutter up and finds out that Tutter has an assignment --- everyone at Mouse School is to give a show-and-tell of their favorite thing on Monday. Tutter considers it a big responsibility and is eager to get started, even though Bear notes that he has all weekend to work on it. Tutter gets so caught up in the project that he tells Ojo he doesn''t have time to play cave explorers. Ojo becomes upset and feels that all Tutter ever talks about anymore is school. Meanwhile, Bear plans for a relaxing day at the Big Blue House, but is distracted by a leaky faucet. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E47F64207EC34EF2BF0B858F0A005371', X'05044F495F9C4E7FA74DB2FF19475D0E', 6, 'The Family Business', 'Melissa and Joe try to take their business to the next level; Teresa and Rino want to expand their restaurant business; Rosie introduces her girlfriend; Amber turns to her family for support.', '2014-08-17', 43, '/7xZkvMitTBd8hxstiASbtpi6N8H.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
