INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E48C34A80028483D94299ED548E63C5A', X'DFA60F316EF14BEEA9AD554B68A5448B', 1, 'Sidewinders of Arizona', 'Steve and Terri visit the Barry M. Goldwater Military Range in Arizona to track down the sidewinder rattlesnake. Afterward, Steve visits the airmen at Luke Air Force Base, who prove to be fans of his show. Steve gets the opportunity to fly in an F-16, the plane that carries the sidewinder missile named after the rattlesnake.', '2000-11-19', 44, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
