INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E4998DB2576F45E6AA9E9886A86DCB34', X'E6359E6D9BDB4ABA9CBA6F7DDD6328F9', 14, 'Heaven Knows', 'Teddi worries about seeing Erika at Lisa Rinna''s luncheon; Kyle''s séance conjures up unexpected guests, but the group gets a bigger shock when Erika reveals information about her past; Lisa Vanderpump is struck by tragedy at home.', '2018-03-20', 43, NULL, '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
