INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E4B52533F7854061AA64B2D68BB9D49A', X'F5474771893041EBB0D4DB442233ACEE', 3, 'Lights! Croc! Action!', 'A very unusual behind the scenes look at the making of Steve''s first feature film "The Crocodile Hunter: Collision Course".', '2002-06-27', NULL, NULL, '2026-04-03T17:39:10Z', '2026-04-03T17:39:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E4B87EF9552C42E39BD30D4163986239', X'99A9678144CB4A5C910071E2A55B6B1A', 5, 'Rebels Without a Cause', 'Overprotective Vicki visits daughter Briana with an assortment of pepper sprays to give to her for her protection. They talk about Briana''s future with her long time boyfriend, Colby, and Vicki admits that she is in no rush for them to get married. Son Michael comes home from Colorado with his girlfriend, Lauren, and a double date dinner with Briana and Colby turns into a Vicki-venting session as both siblings rebel against their mother. Later, Michael''s recent interest in his mother''s lucrative insurance business sets the stage for him to take a training trip to Seattle with her.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E4C22D34CC7B4CD5A51A254DB1011178', X'90CC8678A14F4D05BC1E54A3117895D5', 13, 'Reconciliation', 'The Farthing Wood animals celebrate in the lieu of Fox''s defeat of Scarface - but Scarface makes a shocking return and, as retribution kills Mrs Rabbit. On his way home however, Adder finally puts an end to the tyrant, biting him as he drinks from the stream. Scarface''s death marks an end of the feud - but Fox and his family have no time for celebration. Whisper has arrived at White Deer Park - but without Bold, Bold having hidden himself away, his pride refusing to let him return to the park. Fox and Vixen manage to find their son just in time to say one last goodbye before he dies, Bold at last content with his father''s approval. Bold''s death triggering an epiphany, Fox at last gives his blessing to Ranger and Charmer''s union.', '1994-03-30', 25, '/drbc5xRBkxITVNRtA9wfjlV99bg.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E4CC73E8887A43E0BE5E466797D5F2D8', X'684AF21E04594832B094DB0997E354C5', 5, 'Eager Beaver', 'Joanna tries to mend a struggling relationship. Also Karent receives some advice on how to deal with the mean-spirited people in her life. Meanwhile drama flows when all the ladies attend a noble charity gala; Karent gets a warning about Adriana, and Alexia throws her first bash in months.', '2012-10-11', 44, '/4m0MXSpGmW5511XBN7xBJSowF1T.jpg', '2026-04-03T16:35:10Z', '2026-04-03T16:35:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
