INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E4FE4B2E18D041EFB2E6D87868763AFE', X'095258D0D8DB40968AC76A42CD4CBDCF', 13, 'Scared Silly', 'Boober''s been testing belouviouses, which are the part of a Fraggle''s tail that flares up when scared. And when he tests Wembley''s, Wembley wants to get even, so Philo and Gunge give him ideas on how to test his belouvious back. When hiding in the laundry and shouting "Boo!" doesn''t work, he goes with an elaborate plan of setting up scary masks, spiders and snakes. Wembley goes back to Philo and Gunge to tell him of what he''s set up, Marjorie tells him that when the boys tried scaring her, she nearly blew up. Wembley misunderstands this, and tries to go back to tear down his plan before Boober shows up, but he''s too late, and thinks that Boober''s blown up. Did Wembley go too far?', '1985-03-25', 24, '/ej6wG9Wu3wqHzKa2gJ3GnGTMa7z.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
