INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E57ADB71313D4860AEBB2D709F1AE643', X'1A534647384B4C00BB6CA3371AD962EB', 28, 'Pawn Creature', 'Run for the hills with the Pawn Stars as they come face-to-face with a life-size Creature from the Black Lagoon. Will Corey reel in the deal or will he be out of his depth? Then, Rick gets the inside scoop with a handwritten love letter from Judy Garland to Frank Sinatra. Will Rick get caught up with this whirlwind romance or will it be an unrequited love? And later, Chum and Corey attempt to frighten Rick with pranks throughout the shop. Will he scream blue murder or will Rick seek revenge?', '2015-05-21', 21, '/x0CtGX0mG87hPvyW6yl5ydOf6K8.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
