INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E5CA76FF628D43428EDD277D0AD6F199', X'228172B6FED04226ACDF820049D2C72E', 2, 'Felons No More', 'The Browns visit their polygamist friends to discuss the sudden and exciting possibility that polygamy will be decriminalized in Utah. The car trip to get there is a mess, but once there, the excitement is palpable. Could the family relocate back to Utah?', '2021-02-21', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E5CB77531DFB4DAC9C8D769987F59DB0', X'2E6EE129B32E4417950056F1CC9BC434', 10, 'June 29, 1999', 'What''s fact and what''s fiction? What''s the truth and what''s absurd? LeVar looks into unusual stories and tries to distinguish the actual news from fabrications. Charles Kimbrough reads a story (set in the future from the time the show was originally broadcast) about a young girl''s science experiment to grow vegetable seeds in space, and how weeks later the country was inundated with giant plants falling from the sky.', '1993-10-22', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
