INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E61768F178B74273B31401AF8989CF96', X'994C75E506FA4BE1A142EA7B2C892DD0', 8, 'Ready to Read?: Lots of Ways to Learn Words', 'Rogers witnesses a majestic ballet dancer and her teacher. In the Neighborhood of Make-Believe, Lady Elaine reveals her plans for a new game show.', '2000-09-07', NULL, NULL, '2026-04-03T17:35:49Z', '2026-04-03T17:35:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E619F1B635F2405BB2DFBC5B02604F71', X'D5383B3D56364D71B99CB84774B4B3C6', 15, 'Pingu Teases Pinga', 'Mother comes out to inspect the washing, and checks on Pingu and Pinga who are playing outside, Pingu with his train and Pinga with her rabbit. Pingu is a little bored, and decides to tease Pinga, by taking her rabbit and putting it out of her reach on the snowman. Pinga is distraught, and Mother tells Pingu to give the rabbit back to Pinga, which he does. Mother then goes back inside with the washing, wakes up Father who is dozing in a chair, and tells him to iron the washing. As Father gets started on the ironing, Mother goes past with a package that she tells him she’s going out to deliver. Pingu and Pinga clamour to go with Mother, but she says she’s going by herself. As she walks off Pingu, who’s annoyed at not being allowed to go with her, grabs Pinga’s rabbit and puts it on the snowman again. Pinga asks him to give it back, but Pingu refuses. Pinga makes a snowball and throws it at Pingu. The snowball hits Pingu on the head. Pingu is annoyed, and chases Pinga indoors. Pinga grabs hold of the table leg and Pingu can’t drag her loose. The commotion wakes Father, who has dozed off while doing the ironing, and he tells them to stop it. Speaking together, Pingu and Pinga each try to blame the other. Father tells them to be quiet and to go outside. Pingu sticks his tongue out at Pinga, Pinga sticks out her tongue back, and they both go outside, followed by Father. Pingu gives Pinga back her rabbit, to Fathers approval. Father goes back inside. Pingu walks away, then gets annoyed when Pinga sticks her tongue out and blows a raspberry at him. In revenge, he goes back, grabs the rabbit and puts it back on the snowman. As Pinga tries to go back indoors, Pingu rushes ahead and shuts the door with his back against it so she can’t get inside. Pinga makes another snowball and throws it at Pingu. The snowball misses Pingu but hits the doorbell, making it ring. The bell wakes Father, who has dozed off at the ironing board again! He goes outside, but can’t see any sign of Pingu and Pinga, who have run away. Father looks around and sees the rabbit on the snowman, so he goes across and takes it off, putting it on the ground. He then sees Pingu’s train nearby, and he puts this right on the top of the snowman, where it will be out of Pingu’s reach. Father then goes back indoors. Pingu and Pinga reappear, and Pinga is delighted to get her rabbit back, but Pingu isn’t happy to find his train on the top of the snowman, out of reach. When asked by Pingu, Pinga denies doing it. Pingu tries to get his train but can’t, and Father, who is listening at the door, is amused. Father goes out, talks to Pingu and Pinga about the error of their ways and gives Pingu back his train. Pingu apologises to Pinga, Pinga apologizes to Pingu, and they both snuggle up happily to Father.
