INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E660DAF0757549A8BE54B02FCDE9B3CB', X'F4C403079B5E4263A4E0DFA138131E7F', 48, 'Abby and Friends: P Is for Princess', 'Once upon a time on Sesame Street there lived a fairy in training named Abby Cadabby, and she loved going on all kinds of adventures. She loved playing princess with friends like Rosita, but what happens when a misguided Prince (played by actor Paul Rudd) tries to rescue them? Pretending and the Letter P are the focus of two more stories in this enchanting title that also features fun with Natalie Portman and Elmo in "The Princess and The Elephant". This title will also feature two bonus episodes of Sesame Street''s animated show Abby''s Flying Fairy School.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
