INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E67126B340084A85901ACF05694A90EF', X'6F731E6BD3C54DE684E17A19CB650E86', 20, 'The Pawn Awakens', 'Wield a lightsaber with the Pawn Stars when a one-of-a-kind "Star Wars" packaged Boba Fett prototype strides into the shop. Will the Force be with Rick or will he not pay the bounty? Next, an early 1900s Shelby bicycle wheels in. Will Corey frame out a deal or tire of negotiations? Then, Steve Grad wows Rick with his otherworldly "Star Wars" autographed poster and massive card collection. Are these the Droids he’s looking for or will he think it''s a C-3P-no? And later, a "Star Wars"-used piece of the Death Star docks at the shop. Will Rick laser in on an offer or will it blow up in his face?', '2016-01-06', 21, '/p7a8CvlHQ3XVLjZvhpNYaN1X05B.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
