INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E69679CEC3774A8B9CF0AB22D098A1F9', X'6F731E6BD3C54DE684E17A19CB650E86', 19, 'Wicked Weapons', 'The Pawn Stars are breaking out the big guns as they revisit some of the most wicked items to ever come in the shop: a thermonuclear weapon warhead cover, a desk with a dark secret, a percussion pistol from the 1800s, a child-sized musket, a collection of knives, a thunder mug, and a massive mortar that bowls Rick over.', '2015-12-17', 21, '/sRKcRJAeNsbZUhGTTw4a7qFDvkK.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E698B682F03E4CC09CA1AED63804F445', X'2794739239BA45A6B67BFC609EB26E51', 22, 'Baking Blunder', 'The Pontypandy Pioneers bake up a storm to earn their baking badges, but when a greasy oven bursts into flames, they call the rescue teams.', '2023-07-02', 10, '/pE1otS8PT6QLGfsQUEPGqMb8Fny.jpg', '2026-04-03T17:14:41Z', '2026-04-03T17:14:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E6A283E351AC40FCA3E660CBCCA324EC', X'E291DF42D44F49E5BF812DF32EE4A30F', 10, 'What''s Mine Is Yours', 'A package comes in the mail for Ojo --- a book from Ursa titled Bears Around the World. Ojo wants to keep it all for herself at first and read it alone, despite Tutter and Treelo''s pleas for her to share it. Bear explains to them that sometimes when somebody has something new, they might want to keep it to themselves at first. But as Ojo becomes excited by the book, she begins to change her thinking. Meanwhile, Bear finds himself sharing quite a bit. He shares his food, he shares his berry-picking bucket with Pip and Pop and he lets Ojo, Tutter and Treelo use his bed as a comfy reading spot. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E6A6B1994DF848A7A7119F987B475584', X'7C0E1F6688354E8A8AD90EEE57155B4C', 6, 'Super Deformed Shorts: School Time Shipping', 'Another edition of Tiny Aang, Katara, Sokka, Toph, Zuko, Iroh, and Appa''s adventures— this time with ever more Chibi characters! The Golden Dragon Dance is coming up and Tiny Aang wants to ask Tiny Katara, but he''s got plenty of competition from Tiny Zuko, Tiny Jet, and Tiny Haru!', '2007-09-11', 4, '/mzSSiOS7YJcIK7g3ewRdKjlMrSe.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
