INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E6C2EA41693F4874B18AD00365D2591A', X'1D713CA64E174F84949C8CFD98514127', 10, 'Shufflin'' and Hustlin''', 'Stay awake with the Pawn Stars when an early, illustrated version of Rip Van Winkle is brought into the shop. Will the beautiful illustrations arouse Rick to spend for this classic or will he end up losing sleep over it? Then, Corey and Chum encounter a candle in the shape of President Richard Nixon''s head. Will this unique item light a fire under the guys or will they get burned? And later, in order to get the Old Man to be more active, the guys take him out to play shuffleboard. But will he play by the rules or will he turn this excursion into a shuffle hustle?', '2014-08-07', 21, '/Y9SCzhhQaMd0mP9DmwPu8LFPr3.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
