INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E6DB33AD24AA4575BEC92D2D38F1CF0A', X'63F9BF6D39B344F4B885A56807277A80', 27, 'Of Muppets and Men', 'This made-for-TV documentary treats Muppet fans to a behind-the-scenes look at the making of their favorite program, The Muppet Show. Includes interviews with creators Jim Henson, Frank Oz, and the rest of the crew of the series, as both themselves and as their Muppet characters, who share their experiences from working on the set, as well as discuss the special efforts that went into bringing each episode to life.', '1981-01-01', 26, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
