INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E6E881A36694424B8261AF8E698BDD63', X'2F8DD62982C34F8E87C0963473C49284', 16, 'Reunion (1)', 'The ladies meet to discuss a dramatic and shocking Season 15. Brynn confronts Sai for putting her through hell. Sai claps back at Brynn and accuses her of constantly lying. Jessel speaks her mind over the continuous gossiping about her marriage.', '2025-01-28', 43, NULL, '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E6EA32A8746A44A0BE563FFF86FBC946', X'543EC6DCC6C7447CB5A74484D9618391', 10, 'Reunion (1)', 'The ladies of D.C. reunite and tempers flare. Cat comes clean about her marriage problems. Lynda makes a shocking revelation about her habits. Stacie updates us on her situation with her birth father. The issue of race is discussed. The ladies doubt Michaele''s claims that she has multiple sclerosis and that she was a Washington Redskins Cheerleaders. Part 1 ends when Andy Cohen wants to bring out Tareq Salahi and housewife Lynda speaks up and says she will not allow it unless her boyfriend, Ebong, comes out as well.', '2010-10-14', NULL, NULL, '2026-04-03T16:35:01Z', '2026-04-03T16:35:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
