INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E7498C1DD25B4597AB7AE248780642C0', X'787DFA0BC8274DADA82D0548A6534D88', 21, 'Reunion (2)', 'On part two of the reunion, the ladies get wild and crazy looking back at the best OMG moments of season 10. While Shannon faces scrutiny about her marriage and David''s affair, tensions rise when Heather gets heated about Vicki''s betrayal of Tamra. Jim Edmonds also joins the ladies on the couch and is put in the hot seat about his marriage to Meghan. Briana makes an appearance and is no holds barred when it comes to her opinions about Brooks.', '2015-10-26', 44, '/vD5uPOGcUE4tViTITegqR0mso6S.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
