INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E7A1722045FB4D45BEA57D657A35B3D1', X'6F731E6BD3C54DE684E17A19CB650E86', 39, 'Pawn of Liberty', 'Catch a wave with the Pawn Stars when an original Beach Boys surfboard rides into the shop. Will Rick hang ten with a totally awesome deal, or will he have a gnarly wipe out? Next, Rick gets adventurous when a magazine feature penned by Mark Twain turns up. Will it be an instant classic or will it be sold down the river? Then, things get sloppy when an early 1900s spirit hydrometer pours in. Will Corey have the liquid courage to make an offer or will he be off the sauce? And later, things get psychedelic when an original Peter Max Statue of Liberty painting is brought in. Will Rick liberate a deal or will it get torched?', '2016-06-22', 21, '/u2Pi1LrzAdKSW8qmjOZQL16d2Hf.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
