INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E7EA2E04112F438E88809A50BEEDCE30', X'0FB5CE6502584423BE8AF7BA9C37BB6B', 15, 'Dog Versus Cats', 'Mandy and Sarah help create a film showcasing the difference between dogs and cats.', '2023-11-03', 9, '/y2Fi7u6H8lJE1FP7DDBqm5nu1zB.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E7EDB0894DB94A9686D609C17A4B240A', X'70D9E39768134785887D27D034928BAE', 3, 'Pingu''s Grandfather Comes to Visit', 'Father is cooking dinner, and Pingu and Pinga are laying the table – except that Pingu is juggling the beakers and Pinga is enjoying watching the act! Father then comes out of the kitchen, and tells them to hurry up and finish off laying the table. After Pingu finishes up he reads a book, while Pinga prepares the chairs. There is a knock on the door - Grandfather has arrived. After greeting the children Grandfather gives them each a lollipop to suck. Father comes and greets Grandfather, and then takes the lollipops away from the children and puts them away, much to their disgust. Grandfather and the children then sit down at the table, and while they are waiting for the food Grandfather amuses them with a trick, making a flower disappear and then finding it again behind Pinga’s head. Father then appears with the fish part of the main course; Pingu grabs the biggest fish (his fish) much to Pinga’s dismay. Father brings the vegetables, lectures Pinga that she should not have the biggest fish and gives her the little fish. They all finish off their fish, and they are forced to eat their greens, which they don''t like. Grandfather tries to feed Pinga hers, but she refuses and shoves the bowl to Grandfather, who reluctantly finishes them off. Pingu then also shoves his bowl of greens to Grandfather, who eats those as well! Father then brings out a large chocolate cake for pudding and dishes out portions all round. The children tuck in but Grandfather is too full to eat his. Pingu and Pinga then each take a second slice, and so does Father. However, Grandfather doesn''t want to eat his. Father wants to know why, and he finds out that Grandfather has ate all of Pingu and Pinga''s greens. Father tells off the children for spoilng Grandfather''s appetite by refusing to eat their greens and making him eat all of them. By then Pingu has finished his second slice of cake so he snaps at Father, and he takes Grandfather’s unwanted slice and tucks it, finishing up the cake. While Father eats his angrily, Pingu and Pinga snuggle with Grandfather.', '1995-06-29', 5, '/6JU00h3tk3hSyUJ17h3PgmxW4bh.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E7EF69628845480AAC8D6FD14A94903C', X'22BEBA7F9B8E456393DA46E76ECBA427', 5, 'Herb, The Dinosaur, Comes To Sesame Street', 'Herb, the plant-eating dinosaur—the only dinosaur left, except, of course, for his cousin Shirley—pays a visit to Sesame Street. He meets many interesting new people; learns about healthy salads from Alan, about taking turns from Zoe and Rosita, and about the alphabet from Big Bird and Elmo; and even gets to play with a worm.', '2006-08-18', NULL, '/yejeuTXQ4n96Zg9sAfReFTz5w2Z.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E7F08832A7EB45C0836CA8CA41BEB1AC', X'DB81AD4293A7492689E5D4CEFA257B83', 11, 'Radio DA DA', 'Using Nell''s old radio, Pete and Linda are transported back to WWII. As they soon realise, everything they do in 1945 reflects what happens in 2001.  Now, Linda and Pete must make life go back to normal or the Gribbles will have complete control of  Port Niranda.', '2001-04-18', 24, NULL, '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E7FDB5FEE5FC4BC696DDCBC24587D403', X'FB4ECC73CB924C5C821F92179058B37B', 18, 'Episode 3673', '', '1997-12-10', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E800F7133950425DABAC7FF1ACDD2EB1', X'1996DDD820C94A3096BE2B87FAB8D17C', 15, 'Into the Comics (2)', 'Jamal and Lenni try to figure out who sent that terrible cartoon of them. Rob visits a homeless poet and hears him read one of his poems. Alex and Gaby fear their parents might get divorced after hearing them argue.', '1993-01-03', NULL, '/C4gQcospH1p7nBsLd8yEqkatF3.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8010BEF3EDC412C913FB5E6F9EA9931', X'941B8C6544544336BE7C1D0591C12F90', 12, 'Like Father Like Pingu', 'After saying goodbye to Mother and Pinga, Pingu and Father set off on a fishing expedition together. A fishing hole needs to be dug when they reach the spot where they want to fish. Pingu plunges the big spade in the ice but can’t get it out again. Father gives Pingu the trowel to use, and then tries to remove the spade but only succeeds in breaking it. Father takes the trowel back off Pingu and laboriously digs a fishing hole in the ice with it. Pingu takes Father’s rod, which is rather better than his own, and goes to start fishing but Father realises what Pingu has done and takes his rod back, to Pingu’s disgust. They start fishing, and Pingu gets a bite. Father takes over Pingu’s rod to fight the fish, pushing Pingu out of the way, but to Pingu’s dismay loses it. They continue fishing, and Father gets a bite. Pingu joins in the struggle and they eventually land a tiny fish! Pingu is amused, Father isn’t. Pingu then gets a bite and Father comes to take over again, but Pingu won’t let him. The fish that Pingu lands is large, and Father claims it as his own, leaving Pingu with the tiddler that Father had caught with Pingu’s help. Before setting off for home they consult the map; Father suggests one way, Pingu says it’s the opposite, but Father knows best! Pingu tells Father several times that they’re not going the right way, but is ignored. After some time they still haven’t reached home, and then Pingu recognises the ice arch where they’d previously been fishing. At last they go Pingu’s way, and eventually arrive home in the dark. Mother and Pinga come out to greet them. Father gets the big fish to show them, leaving Pingu with the tiddler, but then thinks about it and gives the big fish to Pingu so he can take the credit for catching it.', '2004-01-19', 5, '/tlKQU2Hu1M4KXeIyfseRicpq23t.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
