INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E84E4E446705407DA1801EFEF16CCE5E', X'BD8A516B9872472DA8387AFF1070FEA3', 8, 'Bernadette Peters', 'Robin wants his own spot on the show, but his uncle Kermit doesn''t even notice him with bigger costars like Thog, Sweetums, and Timmy stomping around. The little frog even tries to run away but just ends up locked in his own suitcase. When Bernadette Peters notices him and tries to cheer him up, however, Robin finds out that all the Muppets believe in him. He becomes so confident that he demands to sing "They Call the Wind Maria," but Kermit settles on a cute, little song called "I''m Five" instead.', '1977-11-18', 26, '/peUxECsz1JNt81hMmw0ulkaAoQ4.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
