INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E86C832984BD48FCAB9A988C2CD78206', X'F5C042DC065742E8A37D247414140632', 2, 'You Dim Sum, You Lose Some', 'Kameron spars with a controlling Court, who refused to keep her informed about their house-selling process. D’Andra sees her Shaman and reveals that her step mother, whom she hasn’t spoken to in 16 years, has recently reached out to her. Kary’s daughter Olivia comes home from college in Los Angeles suffering from stress and anxiety. Tiffany throws a Dim Sum brunch and finds herself going head to head with Kameron.', '2021-01-12', NULL, '/eeMX0HhntVv8R1A0c4VsHsCUStr.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E86CE33A272D453EB893E81AC419F827', X'BCAB920A51A54CBBAA5941578A0EB005', 20, 'Reunion (2)', 'Drama continues to run high as Erika, Eileen and Lisa Rinna stand their ground against PK’s attempts to explain himself. The women share insights into their various careers and laugh at the over-the-top ways they greet each other. However, things take a turn when Eden and Kim Richards join the ladies. Simmering issues quickly come to a head and it all becomes too unbearable for one of the ladies.', '2017-04-18', 43, '/fkFnHFJD6bj9Ekl6nVC3L6IwxCj.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
