INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E88DE7D48AC24324B214107570B3B032', X'90CC8678A14F4D05BC1E54A3117895D5', 6, 'Home Is Where The Heart Is', 'The cubs Bold, Charmer, Dreamer and Friendly are being taught the ways of the world by their parents Fox and Vixen. However while Fox is away Scarface spies on the cubs while Vixen is teaching them to hunt. Weasel spots him and bravely informs Vixen, scaring him off by singing. However Vixen doesn''t believe her and upsets Weasel. Fox later sniffs the area and believes Weasel may have been telling the truth.   Back at his den Scarface''s jealously tells Lady Blue that Vixen''s cubs are better than hers. After this Lady Blue decides to see the cubs for herself and is confronted by Vixen.   Meanwhile Toad has awoken from hibernation confused and his homing instincts drawing him back to Farthing Wood. However he is caught by a young boy and put into a jar. He becomes fascinated with a female Toad also trapped in a jar and so comes out of his trance. Luckily for them Whistler catches the two occupied jars, dropping one and freeing the female Toad and taking Toad to the warden''s cottage to be', '1994-02-11', 25, '/krZZcD6CKP9yWmkbqlWUuDggGiq.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
