INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E89C4D79AFE04330937A08F1F7A23CBF', X'F07B879456254682AAE1E56966B4C7A8', 9, 'The New Adventures of Julie Woo', 'Julie tries out a new and different game and realizes how much fun it can be. Nuzzle takes up the Scottish bagpipes and tries to get Sizzle to play too, all the while annoying her by calling her “lassie.” Kiki and Leon do not appear in this episode.', '1996-01-25', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E89F2DF87B76492DAC81D4C59EEA831F', X'9F448CB807F84040840BC8690371EC41', 11, 'The Little Jerry', 'George finds a new romance--in a women''s prison; Kramer buys a chicken, then puts his fowl to foul use; Elaine encourages her shaved-headed beau to grow back his hair.', '1997-01-09', 22, '/5uDnNgnAvcR2ABjM1akgOEARi3S.jpg', '2026-04-03T16:34:12Z', '2026-04-03T16:34:12Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E89F98DB18634296B9D317C538A48B86', X'C06F15E31ABD4C6CA4EF93F3EB85CC89', 7, 'You Win or You Die', 'Robert has been injured while hunting and is dying. Jon and the others finally take their vows to the Night''s Watch. A man, sent by Robert, is captured for trying to poison Daenerys. Furious, Drogo vows to attack the Seven Kingdoms.', '2011-05-29', 58, '/o6ldSDhIINGNKZR62mHf2m64dD.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8A1DA79B4974E5F870783D87C4BC31A', X'9193E795DA7C40ECB68FF63AA7D5174F', 288, 'Creating the Visual Effects: Season 1', 'Creating the Visual Effects: Season 1', '2020-11-10', 18, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8A9EED1CC51433288E5FC0712DF898C', X'AE8F64D94B834147A44CBFE720381F8E', 1, 'Frankly It''s Becoming a Habitat', 'Big Bird is eating a hot bowl of soup on a cold day outside Hooper''s Store when Freddy Flapman, played by Lin-Manuel Miranda, from Flychert Real Estate, finds Big Bird and tries to convince him to migrate somewhere warm. Freddy Flapman tells him that he might like living in a new habitat and takes Big Bird on a virtual tour! First, Freddy Flapman takes Big Bird to the beach where there are pelicans and gulls and beautiful ocean views. Next, Freddy Flapman transforms Sesame Street into a big swamp where Big Bird learns all about this habitat and where owls and ducks like to live. Freddy Flapman pops up one last time and Big Bird’s nest area is turned into a beautiful rainforest! Big Bird likes it. The rainforest is warm and colorful and has animals of every color and size. In fact, Big Bird likes it so much he wants to move there! Big Bird begins packing and waving good bye to all of his friends on Sesame Street. Just as he is about to leave, Big Bird’s friends remind him of all the things he would miss if he migrated to the rainforest. Big Bird realizes he can’t leave, after all this is where all of his friends are and Sesame Street is where he belongs!', '2009-11-10', NULL, '/7pOrzwkI9hHwWXeMpatdIMYD6WL.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8AB97D11A384C499CDB1C93178ECD79', X'D5351B608A0C482AA6DD4FB860CFE143', 9, 'Episode 1399', 'Mister Rogers arrives with a chromaharp (autoharp) and shows how it is played as he sings Old MacDonald. He shows a picture of a standing harp in a book.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8AF90329A194338A3EDE5914BBD2E57', X'4D2CAC0F38FD438B8AFAACF43952E535', 139, 'Episode 139', 'For younger viewers. Wallis Rigby and Christopher Trace talk about making models that fly. The Girl on the Rock, Hugh Tracey tells a story and Aerobatics, Dreamy Daniel in a cartoon film.', '1961-06-19', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
