INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8C7C2564EEB4571B58538184AB9C593', X'3EA743EF0A2247CFB1D262F37E939253', 7, 'Cousin Bear Is Afraid of Shadows', '', '2002-02-12', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8C860AC9575497EA7D091BFEE2E3EAF', X'9310A2885AF04746A8D7D7635FFB6BEB', 11, 'Mister Rogers Talks About GRANDPARENTS', 'Rogers takes the model Neighborhood Trolley to the Pennsylvania Trolley Museum in Washington, PA filled with real trolleys. He rides one of the restored trollies (Philadelphia Rapid Transit Company #5326) in one direction and drives it back in the other direction. After returning to the television house, Rogers shows the controls of how he operates the Trolley. In the Neighborhood of Make-Believe, the Trolley and everyone else is surprised with a French trolley called "Grandparents'' Express." It has a message for Grand-père that his granddaughter Colette is visiting.', '1984-05-07', NULL, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8D6A6A5C76B43C1983863B8BB8B8D0A', X'4A8E3DB080684FF3942F91F45F665F20', 14, 'Lionel''s Great Escape Trick', 'Lionel gets a few pointers on the technique of doing magic tricks, from the master magician Harry Houdini, himself. When he locks himself in the closet for his act, though, Leona fears that he''s stuck in there, so she asks Click to come up with some magic words in order to get her brother out of the closet.', '2000-04-20', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8D7F25DA21E4F18AECBD66E862E1B6F', X'05C0E384194C44179F62803EB615E409', 81, 'Mail delivery', 'John Reardon pretends to be a mailman while he visits the Neighborhood of Make-Believe. He sends a note that King Friday and Edgar Cooke are staying with Sara Saturday a few extra days. Lady Elaine, meanwhile, wants to set up a campsite at the Castle garden.', '1968-06-10', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8DDC99E16F9437491B1444C89844C02', X'5B5E8B2F0A854488B3DC3D8B794E6582', 9, 'Drag Bingo Bombshell', 'Kelly suspects her new pal Shannon of being up to her old tricks and confides in Meghan. Meghan puts her detective hat back on to investigate Vicki''s issues with Shannon and Tamra. Vicki''s looking to move forward with her new love, while Peggy takes her daughter to New York. The ladies attend a Drag Bingo event, where Lydia faces a moral dilemma and old arguments spark anew.', '2017-09-04', 44, '/6hBqWNUF04TqHBFbPSRLwe5pHTZ.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8DF108545CC4B73B8D683F0890D6F98', X'96DD06EED44A47F39372E29E8EAA77F5', 3, 'Thief in Pontypandy', 'Sam''s mislaid his watch, Bella''s necklace has disappeared and Dilys'' earrings have gone missing! Can Sam solve the mystery?', '1988-09-15', 10, '/z3o5ZBSpobjqpICUKmoRFSOhwpb.jpg', '2026-04-03T17:14:37Z', '2026-04-03T17:14:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8E00E74D5E64B909A27D4D3C0023829', X'AE8F64D94B834147A44CBFE720381F8E', 23, 'Tribute to Number Seven', 'Today is the number seven day on Sesame Street! Rosita, Abby, and Zoe begin singing about the number seven as they count seven dancing chickens. Next, Maria does the number seven rumba. As the seven celebration continues, a sniffling letter “S” arrives. He is sad because he can’t think of anything to do to help celebrate the number seven. Abby and Zoe get an idea! What if the letter “S” finds seven words that begin with the letter “S?”
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8E051FAF6BC496BBC5A28C74E87949E', X'050D8AE16CC14018933DB3C3D13DE856', 77, 'Episode 77', 'Janet goes back in time to the 1890s and the days when grand houses were the setting for glittering parties. At Warwick Castle the guests for dinner one hot June evening in 1898 included two future kings, a prime minister-to-be and a dazzling array of High Society''s most beautiful ladies. You can meet them all, as they prepare for the feast!', '1985-06-17', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
