INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8F467C19B784B42AAA0448A2507857D', X'9920276098D04DDAAB2048D2B5C65987', 6, 'The Ricks Must Be Crazy', 'Rick and Morty travel inside the car''s battery, where Morty discovers Rick has created a universe containing sentient life solely to produce power for him. Meanwhile, Summer must deal with being locked in the car with Rick''s overzealous security system.', '2015-08-30', 23, '/9T5ZiW2qhqMRdx79q800SBYbxDv.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
