INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E8F79388B4DD49BBA63FF1B37C071F06', X'D3E13496E3C8490383B45A31FEDEE232', 10, 'Jet', 'While traveling towards the North Pole, the group almost gets captured by the Fire Nation.  However, when a charismatic young man and his band of rebels attack the Fire Nation camp and rescue them, they learn that they are trying to resist the Fire Nation’s motives to expand their territory.  Katara and Aang really enjoy their time with the band of rebels, but Sokka soon discovers that they aren’t as noble as meets the eye.', '2005-05-06', 25, '/aoHnmhUAmMDx8oV9iimMVsScvrW.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
