INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E902C64968734029B0B8CA46371F5CE9', X'831E3A6BC1A748B7A5ACB18ED67BEB10', 1, 'Mind Your Manners', 'Welcome to Potomac, where proper etiquette is key, and breaking the rules comes with serious consequences. At a birthday party celebrating Karen Huger, grande dame of Potomac high society, Gizelle Bryant’s lack of manners puts the two divas into a battle for supremacy. And as if that wasn’t enough, Gizelle is under fire from Charrisse Jackson Jordan, for acting not very lady like in her plush home. International model Katie Rost, a divorced socialite with three toddlers, is doing everything in her power to get her boyfriend to put a ring on it. Meanwhile, Robyn Dixon, who lives with her ex-husband, former NBA star Juan Dixon, must decide if she wants to rekindle her relationship with her ex.', '2016-01-17', 42, '/nELt2MS9a2tq5Y5oOf6XxDWucMm.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
