INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E94F339FA8BE4F5DBD21C025707AAE98', X'4FE93658C46343298E649D523869C2CB', 2, 'Ace in the Hole', 'The Pawn Stars hope to capture a glimpse of the Old West when they are presented with an antique professional gambler''s toolkit. Complete with every game of the trade and elaborately designed with a secret compartment for trouble, will they up the ante and make an offer or will they be forced to fold? Then, Rick and Corey look to buy rare pieces of 1896 U.S. currency known as the "Educational Series." Lavishly designed by the U.S. Treasury, will the bills receive high praises or will a series of bad reviews send to them back to school? And later, a man hopes to sell his 1950''s radiation detecting Geiger counter. Will the shop emit some serious energy for this relic of the Cold War or will the deal force them all to duck and cover?', '2010-08-16', 21, '/p1W61pHvs2Atpdi21ZDAefLvkgK.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
