INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E987C22C9ACD4036A499EAAADC532016', X'7C542833ED0A42729C53E822408AB434', 22, 'History Trails', 'When Professor Pickles decides to create a historical walking trail, he doesn''t realize that his decision to use real props instead of cardboard ones will result in an emergency of big proportions.', '2024-11-06', 10, '/fXKeuruQrtqr6ftdmtAyD28OpEQ.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E98A3BF58E674AC9999EB9283052BA25', X'3982796B54514100904246BEDF6A20A5', 6, 'Pingu''s Curling Game', 'Robby, who has a proper curling stone, invites Pingu to have a game with him. Pingu doesn’t have a curling stone, but borrows Mother’s hot water bottle to use instead. On their first go, Robby gets his the furthest, on the second Robby again gets his the furthest, but both finish up near a neighbour who is sitting on an ice block reading, and he tells them off for disturbing him. They swap stones, and play back the way they came. Robby wins this as well. Pingu is annoyed, and plays the stone as hard as he can. Unfortunately, it goes toward the neighbour who is reading and knocks the seat from under him, depositing him on the ice on his backside! He is understandably rather annoyed at this and goes to tell Pingu off, but Robby tries to pull him back. This annoys him even more and he follows Pingu home. Pingu goes indoors and hides, but the neighbour bangs on the door and comes in. The neighbour explains to Pingu’s Mother what has happened, and Mother gets Pingu to apologise. Fortunately, by now the neighbour has cooled off a bit, and he and Pingu shake hands. The neighbour and Pingu then have a game. Pingu gets his the furthest (because his jumps over the other!), much to the neighbour’s annoyance.', '1992-01-26', 5, '/enTgwx7Y1WRZEnaltIMOOtxlmst.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
