INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'E9D5C5D3AEDE4F268E3552BDB2633A1F', X'6F731E6BD3C54DE684E17A19CB650E86', 3, 'Fender Bender', 'Get heroic with the Pawn Stars when a 1939 Superman doll flies into the shop. Will Rick save the day and make a deal or will it be his kryptonite? Then, Corey gets electrified when a 1952 Fender Telecaster guitar jams in. Will it have the rock `n'' roll chops or will it get the axe? Later, an antique Japanese matchlock gun shoots into the shop. Will Rick draw first and make an offer or will he bite the bullet?', '2015-10-29', 21, '/tgtW2SJjzpEZCN3c51xMG9QNBcp.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
