INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EA5941889973490ABE3066C3B83439F8', X'6BE7468483E64D00BD693E4FCA97CABB', 3, 'Making Frenemies', 'Tiffany features Cary’s couture closet in her web series, Sanctuary of Style, and discovers a shocking revelation about Mark. Meanwhile, Brandi deals with fallout from Bryan after her alcohol-infused episode at a male strip club and LeeAnne invites Stephanie and Cary to lunch to address Brandi’s behavior at the Mad Hatter’s Tea Party. Later, Brandi’s mother shares a family secret causing Brandi to question everything she thought she knew about her grandfather.', '2016-04-25', NULL, '/9kg3Fyvopu51dxT8sVObedu9hdf.jpg', '2026-04-03T16:35:03Z', '2026-04-03T16:35:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
