INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EA9F2E8983094C2484B83926AF9DC071', X'526BD779909A480DA38D1FA625A7C21F', 4, 'Karen''s Grande Dame Reunion - Part 1: The Grande Dame of Surry County', 'Karen sets out to plan her first ever family reunion at the Wooden farm in Surry County, Virginia - but it''s not all fun and games. Prior to the reunion, Karen''s young cousins task her with confronting Karen’s Aunt Val, the current owner of the family farm, about the succession plan for the land. With no plan in place, the younger generation could lose everything - but the question is, does Val want to lose control?', '2022-04-17', NULL, NULL, '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EAA4FD43169344FE938F89FC25E313EA', X'831E3A6BC1A748B7A5ACB18ED67BEB10', 8, 'All Shades of Shade', 'Gizelle''s inner entrepreneur takes center stage, but the shade is real when Katie blows off a focus group for her budding makeup line. Juan and Robyn take a romantic trip down memory lane, making her more confused than ever about the state of their relationship. Karen launches a charity event close to her heart, but Ashley and Michael must get "on par" before they are welcome in her home. And will Karen push Ashley one-step too far?', '2016-03-20', 42, '/xbgOwSFacyzhzWUmls68NeZIMii.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
