INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EAAA72B13D6B4C3FA0F5D6A66F4B6A68', X'D034C38DC0C742B48876394B63D84275', 5, 'No Hate', 'Peggy consults a nip-tuck surgeon. Meanwhile, Vicki has trouble balancing her workload demands with family time. And Fernanda throws a party to celebrate her citizenship, but tensions run high when Tamra can''t attend.', '2011-04-03', 44, '/pXkqR6vgO133Ii5s46w26Hl9Bq1.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EAAB2E748B834FB98C4F58F30426471E', X'2B968A9C5FC04E93BCF931D3E4C7B210', 2, 'Episode 2', 'For the past six months Buttons, the 3 Bs Appeal trainee guide dog puppy, has been puppy-walked on the programme. Now, in her Advanced Test, she has to prove whether or not she''s good enough to go away to school to be enrolled at a Guide Dogs for the Blind Training Centre.', '1975-09-11', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EAB37D988D314119A269EAEBB3FB0165', X'095258D0D8DB40968AC76A42CD4CBDCF', 8, 'Believe It Or Not', 'Red and Wembley decide they''re going on an adventure out in the Gorg''s Garden today. At the same time, Ma is trying to get Pa and Junior to clean the basement, which is something that they really don''t want to do. Junior catches a fluffy little creature named Skinfrith, and then Red and Wembley set him free so they can have some fun. But what they don''t know is, this Skinfrith is a magical creature that can change into anything that someone can imagine. And before long, Skinfrith gets into the Gorgs'' basement, and Ma thinks there''s a terrible beast inside, which is what Skinfred turns into. Wembley and Red sneak in to save their new friend, but they need to convince Ma Gorg, who''s trapped in the basement with them, that Skinfrith isn''t all as bad as he seems.', '1985-02-18', 24, '/2ZJJB220b8OEoc2xeGLUvrOuhmh.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
