INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EABE40933DAD4912B07285406E14DF23', X'F4D370CA3C3940A8911DE2B5E7C6B0D7', 4, 'The Colour Chase', 'The toys are having a drawing competition and when it’s finished they want to play another game. Old Bear suggests they have a competition to find objects that match the colour of the pencil they have chosen. They all set off in search of coloured objects that match their pencils. Little Bear is disappointed that he picked brown for his colour because he can’t find many brown things but gets a double surprise as the colour chase comes to an end.', '1996-09-25', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
