INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EAE111F37BE0427B95A9674D68ACD792', X'BDDD64274F85402CB58C5C18AB159704', 7, 'Episode 802', '', NULL, NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EAE343559A7A44269CD68B0B1B2BCDAE', X'3087A3EDE94E42769D02A78183DEA1D3', 10, 'Off the Hook', 'As NeNe prepares to leave for LA to begin shooting The New Normal, she has many challenges thrown her way. Kandi and her boo continue to settle into their new life together, causing her to confide in Porsha about the thought of marriage. A pre-nup conversation is far off for Kenya -- things haven’t been right for a while with her and Walter. After heart-to-hearts with Aunt Lori and Kandi, she takes Walter on a fishing date to give it one last shot at reeling in her man.', '2013-01-06', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EAE6C7917B0C45FA8AB74EC955473A75', X'70D9E39768134785887D27D034928BAE', 26, 'Pingu and the Lost Ball', 'Pingu is building a tower with wooden blocks when Pinga comes along and picks up her ball, which is nearby. Pingu’s tower falls down and Pinga laughs. In revenge, Pingu takes Pinga’s ball and won’t let her have it back. Pinga wants it, and chases him round the igloo. Pingu then puts the ball up on to a high shelf out of Pinga’s reach and goes out to play. He meets up with three of his friends, who are skating. After playing he goes home, and is annoyed to find that the ball is not where he’d left it. He asks Pinga if she knows where it is, but she says she doesn’t. He then asks Mother, who is ironing, but she also says she doesn’t know where it is. He looks around the igloo, but doesn’t find it, so he goes to look outside. A stranger walks by, pulling a sledge laden with boxes. The sledge bumps on a small block of ice, the lid on one of the boxes bounces up and Pingu sees what he thinks is the ball in the box. He confronts the stranger, who invites him to look in all the boxes. It was actually a Piggy Bank. The ball isn’t there, and Pingu apologizes to the stranger and trudges home. The family sit down to tea, but Pingu is still worrying about where the ball has gone and doesn’t want his. He goes into the bedroom and finds the ball under the blanket on Pinga’s bed, where she had hidden it! Pinga goes to the bedroom and sees what''s going on and laughs, but she becomes dismayed when she finds out what he''s going to do with it. Pinga chases Pingu around the house to get the ball back, while Pingu gets happy that he found the ball, to Mother and Father''s amusement!', '1996-09-05', 5, '/gtBFzG65mbtaeXBC9FvK6Aq6SOo.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EAE81D4BBE614730BC15E0BF99B347EF', X'DE052E8E7DBD454AA6D8B9AFBA6E9BFA', 26, 'What''s Cooking?', 'A bird nests in the Wombles'' ventilation shaft.', '1973-06-29', NULL, '/3Gkkp2HOE9p4aO2SdvTyMGyEPP8.jpg', '2026-04-03T17:23:19Z', '2026-04-03T17:23:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
