INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EAEE19C4340F4AD4AD2B029D7F0534E1', X'D9973960273B4A92A7DA62EFE8860D09', 14, 'Reunion (1)', 'The reunion kicks off with Jen revealing the issues that still haunt her and her husband Sharrieff, while Whitney addresses the rumors swirling in her marriage. Meredith confronts Jen about the awkward night at her house, leading to a heated conversation about Brooks. Tensions rise with Lisa and Mary when Lisa defends her friendship with Jen.', '2021-02-10', 42, '/rfAjC0SLnNfAvOvnmPQsSWbQ5ny.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EAEE421BEC1D4FD4814461872F0629B2', X'2F8DD62982C34F8E87C0963473C49284', 14, 'Quit Your Beachin', 'A day at the beach in Puerto Rico goes awry as Ubah''s complaints upset Racquel. The ladies indulge in hairy antics. Jenna teaches a synchronized swimming routine. Tensions rise as the women begin lashing out at one another.', '2025-01-14', 43, NULL, '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EAEEE96D6A544825B18412EAD45ADAA0', X'1D39506B06B84F9391360208069BD7E4', 6, 'The Ambush', 'Bethenny and Ramona have a venomous argument while walking across the Brooklyn Bridge. Things don''t get any better for Bethenny, who then learns about a family illness. Meanwhile, Kelly snaps photos of random Manhattan denizens for an article; and Alex continues to piece together a fashion-weekend event.', '2010-04-08', 43, '/zuIXaJV24WI3WDslJ2zEeCtglOb.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EAF60BB252D747B2822EA322F287EDD5', X'E291DF42D44F49E5BF812DF32EE4A30F', 20, 'Let''s Get Interactive', 'Doc Hogg is remodeling his office, so he asks Bear to hold some of his stuff at the Big Blue House for a while, including his computer. He also gives Bear permission to use it, so he shows Tutter and Ojo how it works. They learn that computers are interactive and that interactivity isn''t something that can just be done with computers --- just doing something as simple as talking with someone is interacting. At first, they''re reluctant to use the computer, but are soon having fun with it. As it turns out --- Pip and Pop already know about interactivity --- Pip shows Bear how much fun it is for him to interact with Pop, as opposed to something like a rock. Bear takes a crack at solving the daily puzzle, with the help of Treelo. In the Shadow segment, Shadow introduces the viewers to Gus, an "interactive shadow-dog" who''s looking for his friend Gloria.', '1999-10-12', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EAFA2CD944A14B1A892FD43AC3AF9FB2', X'6A2D283971064C3B8906C9B3E4BFCC8B', 7, 'Choke-Lahoma', 'Vicki travels to Oklahoma to help her daughter Briana look for a house. Heather and Lizzie meet with their children. Shannon and Heather also meet to discuss their issues. Shannon invites Lizzie for a makeup lesson at her house, Tamra discovers something shocking about her son.', '2014-06-02', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
