INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB265C4A0195432E9B883E7FE435E763', X'F4D370CA3C3940A8911DE2B5E7C6B0D7', 7, 'Duck Tries To Fly', 'Little Bear and Rabbit find Duck trying to improve his flying skills. They decide to try to help him but their various contraptions don’t seem to be too successful; even Little Bear ends up flying further than Duck. Duck is beginning to think that flying is not such a good idea when Sailor offers him two old sails from his boat. The triangles of cloth give Duck a good idea and when the toys all go out in the garden they do see a bit of flying after all.', '1996-10-16', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
