INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB398859D5A14DFE8F1D068DDEC5FF92', X'4D2CAC0F38FD438B8AFAACF43952E535', 48, 'Episode 48', 'A weekly programme for younger viewers.  Introduced by Christopher Trace and Ann Taylor.  Including: Brigade of Guards: part 2 and The Tale of Samuel Whiskers: Part 2, a story by Beatrix Potter with the original pictures.', '1959-09-17', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
