INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB414B0F2A23451A882EDF825828D12E', X'65D1CAD80120425EAE9B5020CE773B32', 14, 'Hoedown Throwdown', 'Tamra meets with Katie in hopes of uncovering the truth; Shannon and Jenn''s friendship continues to blossom when they engage their dogs with a pet psychic; Heather hosts an event for the Trevor Project.', '2025-10-09', NULL, NULL, '2026-04-03T16:35:36Z', '2026-04-03T16:35:36Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB470329171C4E80A739F2EE37B51D02', X'3982796B54514100904246BEDF6A20A5', 11, 'Pingu and the Camera', 'Pingu is out taking photographs of Robby. He then photographs an interestingly shaped block of ice from a variety of positions. Meanwhile Robby has found an ice-bridge, and shows it to Pingu. Robby climbs up to the top, and Pingu takes some photographs of him there, in various poses. They then spot a hot-air balloon drifting past, and Pingu snaps this as well. A photojournalist arrives, who also takes some pictures of the balloon, with Pingu standing in the foreground. Pingu goes home, and then goes with Father to the photo-shop to have the film developed. Unfortunately there’s nothing on the film, as Pingu has forgotten to take the lens cap off the camera. Pingu goes sadly home, and father consoles him. Mother and Pinga arrive home with the paper, and Mother shows Pingu the front page, which has a big picture of the balloon with Pingu standing in front. Pingu cheers up, and Mother frames and hangs the picture from the paper on the wall. Pinga wants to take a picture of Mother, Father and Pingu in front of the balloon picture. Pingu has to remind her to take the lens-cap off first!', '1993-03-09', 5, '/moKfXigWkVARcdTFCHj4iNTR7Bi.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
