INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB5635A2D3D44E23AB2DAD4D870F8E2D', X'3AF7EA64FA134097B8E440AF07083054', 27, 'Water Flowing and Stopping Pt 2', 'Audrey Roth''s daughter Holly shows some of her crafts at Rogers'' television house. Later Rogers hears a Vietnamese musician at François Clemmons'' studio. The Neighborhood of Make-Believe also becomes the perfect place for a magic switch to turn the Castle fountain on or off.', '1974-03-26', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
