INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB60BA8D0B574C8FA051B596E94B43A2', X'EFD2082E32F54EDD9A7BA4326D6992C9', 20, 'Elmo the Engineer', 'Elmo and his dad become engineers as they design a device to help Elmo put away his toys.', '2019-03-30', NULL, '/k5XQdQLCJHdgzdMAKE1lIXjEzWu.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB61124B1C7246359DF2C7C40112CCE4', X'68138DE20900460AB58E480688F1E081', 29, 'The Way I Feel Today', 'One morning, Bear is trying to decide on what type of tea to have --- cold iced tea or hot tea. With the viewers'' help, he decides on the iced tea. He also finds Tutter trying to get some tea as well, but needing his help to get a glass and the sugar. At first, Tutter is bothered by how his small size keeps him from doing anything. Then, he helps Bear and he finds that being the opposite of big isn''t so bad after all. More opposites are explored when Bear keeps filling his lemonade glass and Pip and Pop keep emptying it. He also shows Ojo and Treelo how they can dance together, alternating their opposite favorite styles of music. In the Shadow segment, Shadow presents a feature called "Tales of Incredible Opposites," featuring a story about Jack Sprat and his wife. 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB64E5649E114F879F06485FF65AA04F', X'22BEBA7F9B8E456393DA46E76ECBA427', 16, 'Slimey The Hero!', 'When Slimey says that he wants to be a hero just like Trash Gordon, Rosita and Elmo are doubtful because they think heroes are supposed to be big and strong. But Oscar reassures him that he can do it, and Slimey takes on the mission of saving the letter of the day.', '2006-09-14', NULL, '/nlXmkLkDw3zVDXveiW1Xfm4Vwox.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB69C2F166094857B4A8CB4199680579', X'BB919AEC0D5C4C589A5AFA2A0A5DE2B6', 107, 'Episode 512', '', '1973-04-24', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB6B1978511148EBBA526D2152B2E800', X'1D713CA64E174F84949C8CFD98514127', 34, 'Off to the Races', 'Strike silver with the Pawn Stars when the book "The Big Bonanza" hits the shop. Can Rick find a gold mine or will he only dig up dirt? Then, Rick moves mountains when an ancient Tibetan door comes in. Will the sky be the limit on this deal or will the door be slammed in his face? And later, after Corey gets a ticket, the guys decide to find out who''s the better driver down at the racetrack. Who will get the checkered flag and who will spin out?', '2014-11-20', 21, '/1jCLCOPhTlIjjVOwYky8BAc6aPA.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
