INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB78799A08B44D2488C801F79C5F4A94', X'97A3D1F5A8F147CD81222E74A092836D', 1, 'Am I Blue? (1)', 'Gaby is excited when she learns that her heroine, Galaxy Girl, is making a special show at Hurston. She wants to buy a Galaxy Girl costume to wear at the assembly but she doesn''t have enough money, so she borrows some money from her parents cashier planing to return the costume and get a refund. At the show something goes wrong and the model spaceship is stolen. She can''t return the costume because it was on sale. Gaby is heart broken when she doesn''t get to meet Galaxy Girl. She becomes more worried when the team leaves to confront Calvin but is even more scared when she finds the space ship model in her toy chest.', '1993-09-12', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB7EAD6E8682452ABC5D4F0AACAB2151', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 121, 'Episode 2086', 'A short episode with minimal scenes and interactions among the regular cast. Basic educational content is included. The focus is on simple, everyday moments.
