INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB8AA64E3BE74B4A8A0266DEDC7F6156', X'E9352408A84B4C1A905C7AA862062F7F', 24, 'Roller Skating', 'Pat comes along with friends to Coventry Sports Centre to watch their daughter, Jade, roller skating.', '1995-07-30', 10, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB8F33FBDA3A40ADA668C52AF6100FAE', X'852A07B0F228419791477AEED79390BF', 6, 'Stop and Throw the Roses', 'The gravity of Luann and Eboni’s paint party confrontation begins to set in, and beachside fishing turns cold when politics are brought up in conversation. Meanwhile, Heather’s faux pas comes back to haunt her as the ladies glam for Luann’s 70’s style Halloween pageant.', '2021-06-08', 60, '/jcwVOjvr0Yg5v9K8puh8AsZM4jx.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB8FA343BF65445AB3AD2861C9CDDF40', X'DBDE6570A68D4FD7A1B0A6037A266A18', 14, 'Happily Never After', 'Slade''s engagement ring shopping plans; Alexis throws a birthday party for her twins; Tamra gets a tattoo removed; Vicki and Briana fight.', '2012-05-15', 44, NULL, '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB91CBF0AB024983A1741D1BDAAAB73B', X'0B9D7AE7218E45A08C3AE69912F5A6ED', 23, 'Franklin and the Thunderstorm', 'Franklin doesn''t want his friends to know that he is afraid of thunderstorms.', '2000-02-14', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB94E96EB52547A5AA05E64287C2EE0C', X'7BC54DF3F32A454EAEF6A9436C35D53B', 5, 'The NOM Models Pt 5 - Making mud pies', 'Title number 1070. Opens with Mister Rogers arriving with a small cup and spoon from the ice cream shop. Rogers receives the Factory model from Robert Trow. Beforehand, Rogers makes simple puppets from wooden spoons. In the Neighborhood of Make-Believe, Lady Elaine orders chairs from Cornflake in preparation for her new pie restaurant.', '1970-02-06', 29, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB98C4C7BB9B4A4DAE136B219636364F', X'573FA62F55A94F1797CCD1A005A83CC8', 26, 'Counting Bats', 'Elmo, Abby, and The Count play a game of hide-and-seek in The Count''s Castle to round up all ten Batty Bats before nap time.', '2025-07-10', 26, '/e6Iyy5fQnYgsCdil4PvXfhGpQ7j.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB9C0C37DFDA478D980FEB400AFEED3F', X'879892836FEA40D78D9122C4947DB105', 8, 'Doubting Polygamy', 'Kody tells his friend Kyle, a polygamist whose first wife left him, that he is feeling jaded about polygamy. Kody''s wives are refusing to all live under one roof and the roller-coaster of houses sold, lost and stalled has everyone at a boiling point.', '2020-02-23', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB9C9C97E17D43EABB7989617D6DAA31', X'7BC54DF3F32A454EAEF6A9436C35D53B', 43, 'Episode 43', 'Rogers goes to Negri''s Music Shop to see Betty Aberlin perform a few simple magic tricks. Lady Elaine has her reservations about the upcoming play the Neighborhood of Make-Believe will stage. Mr. Anybody tells her she can be in the play if she asks to.', '1970-04-01', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EB9CE02FCDD240B7AFDC8E3855D049AF', X'27A5A980EC0D4637B5BADF8324A6405A', 9, 'The Play', 'Frankie is thrilled when she learns that the Orson Community Theater is putting on a production of "The Wizard of Oz," and that kids don''t need to audition to be munchkins, as they will be automatically cast - which is a perfect scenario for a hapless Sue. But things quickly go awry when Frankie is cast in a singing role and learns the director is not happy with Sue''s performance and may cut her from the play. Meanwhile, Brick asks his unreliably quirky Uncle Rusty to attend his school''s Special Friends Day - with disastrous results.', '2011-11-16', 22, '/gOl6sYbz8eOyjldCSYQYQG2Hdjw.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBA2B5D6F0A248448A3A6DBEDC75C944', X'6F81C872CDB942DD83772C17CB6ED4D7', 5, 'Having a Ball', 'When Saul the Ball is disappointed that he can’t play ball with Elmo and Rosita inside the house, Elmo and Rosita help him use his imagination to play other games.', '2017-02-04', NULL, '/dtuqYoSjKJCmXBsy8FUrYFpJebd.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBAAAEA0A39041CAAB4ACE673C76D2A2', X'05C0E384194C44179F62803EB615E409', 49, 'Bubbles', 'Title number 0049. Opens with Mister Rogers arriving with a straw in his front pocket. Mr. Rogers uses drinking straws to demonstrate the use of blowing soap bubbles. Mrs. Rubin also shows paintings that were all done with straws. King Friday is missing Sara Saturday. Lady Aberlin invites everyone to the castle to see a dancer named Paul Draper.', '1968-04-25', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBAEC756DDA8415889980885C977C408', X'33440D76E69F47ADAC25862CCBC9DFA1', 17, 'Fashion Show-Down', 'The ladies of Potomac are handling their business. Ashley and Gizelle work on their fashion line, GnA. Robyn and Juan tour potential franchise locations. Wendy organizes her pilot episode. Mia brings everyone together for an iconic photoshoot, but drama is just on the horizon at a GnA showcase.', '2024-03-17', 43, '/9IpnPSYTZNXn71rU9HbIcO9rALf.jpg', '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBB79D516FA9418789A80E66EA41A661', X'54FACB0BDB5941FE9D64C7C7221A3C81', 20, 'Reunion (3)', 'The women finish raking Luann over the coals about her sobriety; Barbara joins the ladies to discuss her scandalous comment about Luann''s singing; the ladies relive some of their most outrageous moments; Sonja is in the spotlight for her drinking.', '2019-07-25', 60, '/5cC4mDbqXuOkbtYPQWXT67Up4Bo.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBBEEC81A69444CD81401B9DE977F5A9', X'2389D176A1A846249B1C9C0C12A3BE4E', 1, 'Dilys'' Forgetful Day', 'When Dilys falls off the ladder, Norman''s got a lot of explaining to do!', '1990-10-15', 10, '/zBOWiAWEQSgfH5y9UTdV6mIOXH.jpg', '2026-04-03T17:14:37Z', '2026-04-03T17:14:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBC1BBA9B7904BF292CE4B52C2A7D16F', X'ECB64EF34F8045A7B4A9C04434B02E35', 31, 'Sleeping Giant', 'Jam along with the Pawn Stars when a 1969 Les Paul Professional guitar rocks its way into the shop. Will this classic strike a chord with Rick or will he be left singing a different tune? Then, Corey and Chumlee hit the brakes when they spot a 1930s Rolls-Royce hood ornament. Will they get on the fast track to a good deal or be left in the dust? And later, when the guys notice the Old Man snoozing more than usual they try to take matters into their own hands. Can they wake the sleeping giant or will he become their worst nightmare?', '2014-04-17', 21, '/obhVMU8M33IjKGEpj3dyJowiGcm.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBC4F17822A64DBFA2F970F94E665865', X'AD4E434833344A088928455D9BA524C1', 21, 'Paul Simon', 'Paul inspires Gonzo to be a songwriter. Unfortunately, Gonzo writes songs like "For You": "For youuu... I''d wash my hair with stinky glue, I''d fry my legs and eat them too, I''d put a spider in my shoe -- for yoouuuu!" Paul is stunned. Later, Gonzo''s chickens run off with Paul, so Gonzo develops a new obsession -- asparagus. But at the end of the episode both the chickens and the asparagus run away when Paul asks for chicken with a side of asparagus.', '1981-02-22', 26, '/3ifthNvZrPAxxRnQXk7waK0Dkkd.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBC4F9FC2FFE43A19AB520020B9E1F3E', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 19, 'Science of Music', 'Music is the art and science of expressing ideas and feelings through sound. A sad song can say more about how someone feels than most words, and a familiar song can make crowds clap together and feel like one happy family. Whatever the emotion, music seems to have a way to communicate it. The music we listen to today is the result of years of experimentation with sounds. As people figured out what they liked best, they invented instruments that could play their favorite tones and developed popular rhythms, or patterns of beats. Each note of music, and every tone of each instrument is a sound wave. Some sound waves sound great together. Some not so good. Getting the exact soundwaves in the pattern you want – now that’s science.', '1998-06-13', 26, '/pMXCd8Voj0hm29Rw1ALbb9BRXQY.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBC9E21458AE4D98B80D44CF568AD69C', X'1D556682D9BB47E1993F0B648A8DAACD', 102, 'Episode 1287', '', '1979-04-17', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
