INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBD4D82C5C9C45CEBBCC803EAEDDE572', X'F07B879456254682AAE1E56966B4C7A8', 10, 'We Three Kings', 'When Leon’s uncle tells him he’s the “king of kids,” Leon suddenly gets an ego boost and acts royally around The Puzzle Place, making Skye and Ben his subjects. Eventually, pro-basketball player Cedric Ceballos tells them that there is a difference between being bossy and being a leader. Sizzle suddenly decides to be “queen of cats” and makes Nuzzle do everything for her.', '1996-01-26', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBDFAF90EC244249B1DA5CF1DEE6770C', X'1D713CA64E174F84949C8CFD98514127', 32, 'McQueen Dreams', 'Take flight with the Pawn Stars when a letter from WWI fighter pilot Eddie Rickenbacker soars into the shop. Will Rick land this piece of history, or will the deal take a nosedive? Then, Corey takes a look at a military swagger stick from 1865. Will Corey bring out the big guns to make the deal, or will a tough battle push him into retreat? And later, after Rick gets excited for some "The Great Escape" movie posters, the guys make fun of his mancrush on Steve McQueen. Will their teasing be a "Bullitt" to Rick''s heart, or will Rick make "The Getaway" from their taunts?', '2014-11-13', 21, '/5fj5binCaHIjjHBJD3RZrb0ABTj.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
