INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBE9335AF44342AC86151F3CFF87D59A', X'5A771F52FE964EA2B567A8DDE899059E', 4, 'Chum''s Risky Business', 'Chumlee is holding out for a superhero when a seller brings in boxes upon boxes of inherited comic books. Rick learns you have to buy money to make money when some rare turn of the century currency hits his counter. Chumlee flips out when an antique pinball machine launches into the store.', '2017-10-23', 21, '/qLq8ty5rCa6nAEhpBujfoz0wtkU.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
