INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBF0263C7F934AC09ACE7F131C002384', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 71, 'Gladys presents herself', 'Big Bird has asked Gladys the Cow to help say hello to the viewer, but she balks at a cow of her talent being wasted on such a menial task. Maria questions why Oscar has left an old, junky car seat out on the street. Oscar tells her it''s for an important lesson about safety, and the Grouchketeers show how to use a seatbelt.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBF0951B547643CCBF1452CB7C2CB280', X'3982796B54514100904246BEDF6A20A5', 21, 'Pingu''s Hospital Visit', 'Pingu and Mother visit the injured Pinga in hospital. When they enter the hospital, a doctor is pulling a badly injured penguin who got hurt in a bad post truck accident. When they find Pinga, Pinga is pleased to see them, and Pingu shows her a picture he’s drawn of her accident. The nurse comes in to treat Pingi, who is in the bed next to Pinga, and puts a screen between the beds. Mother gives Pinga some flowers, and both Pinga and Pingu have an apple. Pingu’s getting a bit bored, so he rides around on a stool with wheels. He then sees the shadows that are being made on the screen by the nurse and Pingi by a light the nurse turned on. The nurse turns off the light and goes out. Pingu pulls the screen round in front of Pinga and Pingi, puts a mobile table behind the screen, a pillow into the table, and the light behind. He turns on the light and gives a shadow performance to Pinga, Mother and Pingi, pretending to be a surgeon operating. Mother, Pinga and Pingi find Pingu’s performance very amusing and laugh out loud. The noise attracts the attention of the nurse and a surgeon, who come in to find out what’s causing all the laughter. They see the end of Pingu’s performance, and applaud with the others when Pingu finishes. Pingu is given his own surgeons outfit as a prize for his performance.', '1994-08-24', 5, '/ypGGBR8k7e4FPyIJAoD7KbAgO9W.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
