INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EBF4DC2892994C7F8C77EAE008712DD0', X'0FB5CE6502584423BE8AF7BA9C37BB6B', 5, 'Mystery at Pumpkin Hollow (Part 1)', 'The Why Files and the Detectives are both on the case within Pumpkin Hollow, with strange sounds and disappearing pumpkins to boot.', '2023-10-25', 9, '/2mHdKiQofNNuRHxbtfzf4Z0sFXW.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EC01A8852DF14F60A42990A0B1F79579', X'FFC2A75E0FFA4B26B1219B91B277594A', 7, 'Nice to Metria', 'Cynthia returns to work and joins forces with singer-actress Demetria McKinney. Meanwhile, NeNe goes live on the air in Tampa to debut her clothing collection; Kenya meets a prominent producer; and Kandi receives cold treatment from Mama Joyce at a family barbecue.', '2014-12-21', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EC04B86B282F493090813A0724BE58C0', X'F63C3F6109704E3781CC2B9045A9952C', 42, 'Zoe''s Zoemobile Delivery Service (Repeat) (3957)', '', '2001-02-27', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EC09FCBF4F14480CA1C2EF8937E759AF', X'70D9E39768134785887D27D034928BAE', 14, 'Pingu Seeks Revenge', 'Pingu has been out with Pingi, and kisses her goodbye. Pingg spots them and, while Pingu is waving to Pingi as she walks away, throws a snowball at Pingu which hits him on the back of the head. Pingg is amused; Pingu is annoyed. Pingu throws a snowball back that Pingg avoids. After again being hit on the head by a snowball thrown by Pingg, Pingu chases him home, throwing several snowballs at him on the way, but none of the snowballs hit their target. Pingu and Pingg end up with Pingu on the wooden bridge over the water in front of Pingg’s igloo, exchanging words with Pingg who is by the front door. Pingu is still annoyed, but then has an idea. He goes home, gets a saw, returns and cuts partway through the bridge. He then stands at the edge of the bridge and taunts Pingg, who comes out of the igloo and shouts back. Just then Grandfather comes to use the bridge, and starts across. Pingu tries to stop him crossing by going onto the bridge and shouting, and jumping up and down. The bridge breaks as Pingu had planned but he, rather than Pingg, ends up in the water! Pingu is rescued, but is completely frozen in a block of ice. Once home Mother, aided by Pinga, and a lot of hot-water bottles, thaws him out. Pinga then laughs at him.', '1996-06-13', 5, '/9cHygYtWxRJdn35FzysalSOMTjF.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EC0DD10D2BB341268BC5B8E864E35FEE', X'F812042DEB85432E80473675886E0B1B', 22, 'The Pawloined Paper', 'Joe has a substitute teacher for his class, who he likes a lot.  After a word puzzle he makes up about her gets snatched, courtesy of Curtis, Joe must get it back before anyone sees it.  Meanwhile, Wishbone tears the living room upside down looking for his toy newspaper, which is right under his nose the whole time, just like where the stolen letter is hidden in today''s story ""The Purloined Letter"" by Edgar Allen Poe', '1995-11-05', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
