INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ECA02BAC4AF54ABB885F27526943B587', X'42E591E22A884434AE9F3D4B1D685613', 10, 'The Pawntridge Family', 'Prepare to dive with the Pawn Stars as the guys check out a first edition copy of 20,000 Leagues Under The Sea. One of the rarest first editions, can they navigate this monster deal? Then, a collection of signed Metallica memorabilia rocks into the shop. Will the negotiation have Corey and Chumlee banging their heads? And later, when Rick starts taking guitar lessons, the guys try to talk him into a pawn shop jam session.', '2013-06-27', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ECA281A5E9B842228AC850E07EC0962C', X'E38E9D8714324A1AA7D064A559BF7570', 5, 'Snare For The Unwary', 'When the normally cowardly Mr Pheasant offers to go back and look for Adder on the farm he is shocked to find that his wife has been made into the farmer''s dinner. It is then that he too gets shot. The other animals hear the gun shot and realise what has happened so Owl volunteers and flies over to the farm in search of Adder. Owl finds Adder and they catch up with the rest of the animals and continue on the journey. While crossing a river, the rabbits panic in the water so Fox jumps in to save them. However in their panic they try to climb onto him and put him in danger as well. Badger swims in to help the exhausted Fox and keep him afloat. While the rabbits are taken to safety a large log, floating down stream strikes Fox and Badger.', '1993-01-31', 24, '/tMwN4lV85PXGFZgzjWdfmbM3XiH.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
