INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ECF9CAD0683645C1A15313EE2D54B17D', X'97616D6E5C17449FA37655F1DA83D6C3', 10, 'Mister Rogers Talks About PETS', 'Mister Rogers arrives empty-handed and has some quiet time on the porch while he waits for Bob Trow to arrive with his dog. As he waits, he sings It''s a Perfectly Beautiful Day and is surprised when Mrs. McFeely stops by with a parrot in a cage. Just as she leaves, Bob Trow arrives with his dog, Barney, and leaves him in Mister Rogers'' care for the night.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ECF9CF10441848F8B9F074E9E961E0F1', X'BCAB920A51A54CBBAA5941578A0EB005', 3, 'Going Commando', 'Kyle and Lisa Rinna cross paths in New York City while traveling with their daughters. Back in Beverly Hills, Lisa Vanderpump surprises Ken with a $25,000 watch on his birthday, and Eileen continues to struggle with the loss of her mother. Later, over drinks with the group, Erika''s short dress leads to quick peeks and judgments passed.', '2016-12-20', 43, '/1myrgy0vOB5dM9na8gnKnk0FloH.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
