INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ED2A2C07FDB541C49E2D81AA9D0D8A12', X'4A8E3DB080684FF3942F91F45F665F20', 26, 'The Roar That Makes Them Run', 'Lionel and Leona try to convince Theo to show them his Lion-powered ""Mighty Roar that Makes them Run"", but Theo is reluctant to do so -- after all, they''re in a library!', '2000-05-08', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ED2FFA3C62CD42509AB11F5D811524FB', X'4C79C0B621A442778967BE1E791EFDBE', 11, 'Sore Tummy Pingu', 'Pingu''s Mother arrives home with groceries, including a box of fish-shaped crackers that gets Pingu and Pinga very excited. Pingu gets plates for himself and Pinga. Pingu hoovers his plateful of crackers and asks for more, and every time he does, Pingu''s Mother says "no". Pingu asks Pinga if he can have some of hers, she shakes her head. When Pingu''s Mother has put away the groceries, Pingu sneaks some crackers from the box and eats them. He then takes the box, which contains the remaining crackers, and goes outside with it. He finishes the box and goes off to search for more crackers. On the way he meets Pingg. Pingu gives the box to his friend and walks off. Pingg puts his hand in the box and discovers the box is empty. Pingu passes Grandfather’s igloo. Grandfather is outside, snacking on a plate of crackers, and he gives Pingu the last one. Pingu asks if Grandfather has any more, and Grandfather goes inside his igloo and returns with the box. Pingu excitedly helps himself to more, and Grandfather warns him not to take too many or eat too fast. As he gives the box back to his Grandfather, his stomach rumbles loudly and he clutches it in agony. At the hospital, the doctor examines Pingu and explains to Grandfather that Pingu has a sore stomach caused by eating too many crackers. Pinga, Mother and Father arrive, with Pinga carrying a box of crackers. Pinga offers a fish cracker to Pingu, which he refuses, and Pinga then offers them round. Mother, Father, the doctor and Grandfather each take and eat one, as does Pinga. Everyone then belches, one at a time, and they all laugh as this happens. Pingu then produces the longest and loudest burp, and realises that all his pain has now gone. Pinga then offers Pingu a fish cracker, but Pingu again refuses.', '2005-11-24', 5, '/aspaW4aZn9Z9X7lvhyYwH6AOwG.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ED349006CEA44F01945EAD2A6F2E69A1', X'7A83EC7F6F294AAD80A149CD578555B8', 5, 'The Circus / Chance and the Bird Bath / The Annual Bathtub Race', '', '1995-05-26', NULL, NULL, '2026-04-03T17:11:21Z', '2026-04-03T17:11:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ED40EC353ECF44B0831E8439EF4F5A6A', X'D1863F2F02EC40CEAF64DB03FBE518A7', 26, 'Elmo and the Bookaneers', 'The Bookaneers, a band of book and reading-loving pirates led by Tina Fey, comes to Sesame Street! They invite Elmo to become a Bookaneer, and together they look for the pirates'' treasure, the library. Also featuring ''B is for Book'' with Pharrell, Cookie Monster''s Smart Cookie, and Elmo''s Wold. Brought to you by the letter B and the number 1.', '2016-07-02', NULL, '/aX6wq10ht9JndGbKqH946P5Xv7q.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ED41B568921E446F96FCF71AE28EFD82', X'1996DDD820C94A3096BE2B87FAB8D17C', 7, 'Who Burned Mr. Brinker''s Store? (2)', 'Jamal finds himself in hot water when the fire is blamed on him. Lenni learns that Jamal was at the arson but didn''t commit the crime.', '1992-11-08', NULL, '/uvOOkGeCbAAYY4DMrTiziXl0JTE.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ED473A4E3DB24B58AFEC691F88E18BD7', X'0BBD380C5CB846A68838B5D60223C073', 2, 'Rita Moreno', 'Fozzie Bear becomes embroiled in a running gag involving the backstage phone. Throughout the episode, Rita parodies her combative image. She battles with several Muppets, including Miss Piggy, a Full-Bodied Muppet, and Animal, who''s backing her on drums in her closing number, "Fever."', '1976-09-12', 26, '/1rUAmsRxZnUyo6x1W9puET2DMfG.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ED48F3650D694690B87AAAFEBBF2141B', X'3D4E0E451C67475EB37D9E7E6B8B942A', 1, 'Halloween Hound: The Legend of the Creepy Collars (1)', 'Joe and his two best friends, David and Samantha, form a team to go on a Halloween scavenger hunt.  Damont also competes in the game, but he tries to win by cheating.  Meanwhile, Wishbone imagines himself as Ichabod Crane in Washington Irving''s ""The Legend of Sleepy Hollow"".', '1997-03-03', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
