INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'ED6C2B596BE742D19F6F749E4297F811', X'F13CB62284E34654A8F10CEAB09A9CA6', 24, 'Franklin''s Advice', 'During a soccer match, Snail deflects the ball and scores the winning goal, but the victory comes at the cost of a cracked shell. Despite Franklin''s advice, Snail refuses to tell his parents about the injury for fear of being pulled from the team. Putting his friendship on the line, Franklin gives Snail one more chance to tell his parents or he will have to do it for him.', '2002-07-15', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
