INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EE5A259B164C45999C780898C7975932', X'1415EF1C411A4C26814A7C79C3628BC2', 2, 'It Girl, Interrupted', 'Former “it girl” Tinsley Mortimer, has just moved back to the city after a tumultuous few years, including getting arrested, and is the latest boarder in Sonja’s townhouse. Bethenny invites Carole and Ramona over to discuss life, politics and Sonja’s new roommate’s tragic fall from the heights of the NYC social scene. Ramona fills Dorinda in on the dirt she has about Tom, Luann’s fiancé. Sonja throws a Mad Hatter tea party to introduce everyone, except Dorinda, to Tinsley.', '2017-04-12', 60, '/gHORgZdi1k2cPNrHkdZXaSLBvTo.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
