INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EE7816CBD2814240BD0CC09A56930BE0', X'0FA9200282AE460985E33982BAA99AE1', 22, 'Postman Pat and the Lucky Escape', 'Pat and the Reverend are accidentally lost in the vestry. While PC Selby and the others chase after Dr. Gilbertson to retrieve the vestry key, Pat and Rev. Timms find a way to escape through an underground passage.', '2005-03-28', NULL, '/gnb626VQXv8wqLbaPSsM5q8EI8f.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EE7819B7BCB143128E5429F81CD0DCC7', X'5144DE59E67F4FCF919B7106989AB797', 19, 'Party of One', 'Leon learns a hard lesson in racism when he’s barred from attending a friend’s birthday party simply because he’s African-American. Nuzzle refuses to fetch a stick for Kiki because she didn’t say “the magic word” (which Sizzle tries in vain to guess).', '1995-02-09', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EE79BE3A6314448B9DE353DB3F9CDF7A', X'9193E795DA7C40ECB68FF63AA7D5174F', 178, 'The Real History Behind Game of Thrones (Part 1)', 'Watch historians, along with George R. R. Martin, explore the interweaving inspirations of the actual players in the era known as "The Wars of the Roses" and other historical events in this two-part series.', '2016-03-14', 18, '/vugVYerD7nOsSXv8KqokcZNUd7O.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
