INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EE8F0B61849B4F21AB515C3A06226D58', X'20D7138EEEA846A88ADA2B0F0EE1F674', 28, 'Episode 28', 'All the stop press news about the 1982 Appeal which is bringing life-saving help to children and babies suffering from acute and chronic renal failure. If your parcel of treasure is too heavy to put in the post, stand by for details of a nationwide free delivery service and see the number of parcels flashing on the Totaliser.', '1982-12-16', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EE8FDFEE6FD343FB89AF426D7B4D02A6', X'3EE646E823AE4DECBBC6C7E6A210D55B', 114, 'Elmo borrows Radar from Big Bird', 'Savion plays a rhyming game with the viewer while tap-dancing. Big Bird recites a poem for Gina, Snuffy, Savion, and the kids and they must guess who the subject is. He''s someone with them right now, covered in fur, and is cute and small - it''s Radar!
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EE9235125333443A8C54E4530662CB1C', X'9C5608B2511148BCA9077F93472C1E03', 7, 'Brandies Is Looking For A Job', '', '2012-10-12', NULL, '/brz8XiM014UponT7BFR9UTGKmc7.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EE9783BF53E74D388F459D5EB7DED75B', X'2DADBC6B684F4884A0B257BDA7546DC2', 9, 'Autograph Time', 'Lucy gets the chance to see her favourite boyband, Altitude. She sneaks into their room and gets them tea because they think the food is horrible. On the way back to the studio, she finds out that Abby has had an accident; that is until Lucy realises she hasn''t got a ticket. Abby is played by Samantha Birch, the actress who plays Sam in the following series.', '2000-11-17', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EEA4B43A1389446494A3C190963BBB81', X'DBD3583FE9B246D1A37E309EB666E233', 18, 'Fresh Princes', 'Kroy returns home after a monthlong stay at football camp. Kim welcomes him with a home-cooked meal—prepared by a private chef, of course. Meanwhile, NeNe has an important conversation with her youngest son; Phaedra hosts an extravagant church ceremony for her son, but drama surfaces between Kim and Cynthia.', '2012-03-25', 43, '/vL51RWruexcbCGeb5O6DOIIBRvn.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
