INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EEAEDB8BD1D34DADBDCCF2DA3780E73E', X'3EE646E823AE4DECBBC6C7E6A210D55B', 58, 'Finding 40 parts of the body', 'Telly has volunteered to help Count von Count count 40 body parts. Telly''s list has 12 parts now and he begs Oscar to help him.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EEB0F1A5EF2D4EC0AEA79BB8EF003181', X'1D713CA64E174F84949C8CFD98514127', 25, 'Hidden Treasure', 'Shoot the breeze with the Pawn Stars when a tree with an 1800s revolver inside it takes root in the shop. Will Rick think money grows on this tree or will he be barking up the wrong one? Then, Chumlee gets creative when checking out a Renaissance etching by Pietro Facchetti. Will Chumlee be able to etch out a deal or will the artwork fail to leave an impression? And later, the Old Man demands the shop give a Senior Citizen''s Day discount. Will Rick respect his elders or will he tell the old guard to hit the road?', '2014-10-23', 21, '/t6CJ4PbXkYWLTzkp4q5tfapuxXZ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
