INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EFA92DBD76F4435FBAE109939EB0DE68', X'650BAC937B5941FCB277DC6F8BDCD7BB', 23, 'Fight or Flight', 'Having finally graduated college, Axl tells Frankie and Mike that he''s planning on going to Europe over the summer with Kenny. Although Frankie thinks this is a great once-in-a-lifetime opportunity, Mike is less than pleased and thinks his slacker son should be putting all of his summer efforts into finding a job. Meanwhile, Sue begins to panic after she barely scrapes a parked SUV and doesn''t hear back from the owner after leaving several notes on the windshield, and Brick discovers that his sudden onset of backaches is due to not sitting in his lawn chair, which was replaced by a normal kitchen-table chair.', '2017-05-15', 22, '/gDmi1vYQFYlfu99WY5chZXXmke2.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
