INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EFB4BE58868F4F9EA629143BBAF81E39', X'842C6419AB984D3488451D9782291AAD', 3, 'Integrity', 'When Annie’s handmade weathervanes sell like crazy at the school fair, she cuts a few corners to keep up with the demand. Later, when the weathervanes begin to fall apart, Annie is confronted by angry customers who want their money back. Humiliated, Annie retreats to Plato’s Peak where she hears several tales about the concept of "integrity."', '1998-03-01', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
