INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EFE16EE84DA64130947868F1B5C2A67E', X'0E4196154C964DDE8ED2715770BA77BB', 11, 'The Amazing Skippy', 'Treelo invites his squirrel friend Skippy for a visit to the Big Blue House and the kids are all excited to meet him. They are all surprised to learn that Skippy is blind and have a lot of questions for Bear while Treelo takes Skippy on a tour. They learn from Bear that Skippy has a disability, but isn''t sick and that he likes to do many of the same things they do. As Skippy joins the kids during the day, they begin to wonder if he has special powers. He seems to know things that he seemingly couldn''t know without some sort of special power. Skippy, however, teaches them that there''s a lot one can tell by using all one''s senses.', '2002-10-07', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EFE2A1C88BE8436E98E1B1AB678459D5', X'1CAFB2C3BBCB4172B02D441A5AAA155F', 14, 'Little and Big: Inventor of a Sphere that Goes from Little to Big', 'Mr. McFeely shows a videotape of his visit to inventor Chuck Hoberman. Rogers gets a visit from Mrs. McFeely. In the Neighborhood of Make-Believe, Handyman Negri rescues both Bob Dog and Lady Elaine. Rogers plays a cassette tape of cello music and reflects on Yo-Yo Ma and his son Nicholas.', '1998-08-14', 30, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EFEA67FC73DD4ABDAFC8B5643C1F28FD', X'ECDEFD77A7AC4344BEA1FB1DF2FD0AC9', 8, 'A Worrying Time', 'Sam tries to cure her aunt Rowena of worrying all the time by trying to get her to try high-risk activities, but she is too worried. But when Sam ends up in danger, can her aunt get over her fears to save Sam?', '2001-12-05', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EFEDD3BBC2FC4D67BD2C758AE6E3D17F', X'02849455D14B476B9603EEF5FB5D2AB3', 10, 'RSVPlease!', 'Candiace attempts to persuade her mother to give her control of the family business, while Ashley and Michael revisit their prenup. Monique and Robyn host two different events on the same day, forcing the ladies to reveal their loyalty. After celebrating her birthday without Sherman, Gizelle begins to re-evaluate their relationship and receives advice from a very unlikely source.', '2018-06-03', 42, '/rfmLsSORP4ng5OZsw2nYeLdXdTz.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
