INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EFFA772AB21044E8A91B083E9D16F8E3', X'1D713CA64E174F84949C8CFD98514127', 23, 'Smarty Pants', 'Get ready to rock with the Pawn Stars when a guitar owned by music legend Stephen Stills strums through the door. Can Rick take the lead in the negotiation or will he end up getting played? Then, Corey tries to stay focused when a 1800s detective''s camera comes into the shop. Will he be able to snap up a picture perfect deal or will he get shot down? And later, Chumlee faces off with Rick in a battle of wits. Will Rick be the smart money in this pawn showdown or can Chumlee beat the boss?', '2014-10-16', 21, '/j8X41QCVLU9POeLEqYep4delBAD.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'EFFC595B5C21428CBCAAAA00032CFFB2', X'42E591E22A884434AE9F3D4B1D685613', 2, 'Grumpy Old Man', 'Keep it reel with the Pawn Stars when Rick checks out a recorded telephone conversation of President John F. Kennedy. Capturing a rare moment in which JFK was angry, can Rick keep this deal on track? Then, the guys are flying high when an F16 flight suit buzzes by the shop. Will their offer meet the sky high expectations? And later, the Pawn Shop becomes a hostile work environment when Chumlee tries to secretly record the Old Man yelling at him.', '2013-05-30', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
