INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F04323B3AFFD44F2B0156D84AD485715', X'45E01C046AC641E187D8F749EE230385', 6, 'Twitching The Night Away', 'Norman and Trevor go bird watching. Elvis is preparing to go on a TV show and says he might not be a fireman for much longer. However he decides to help when the forest catches fire.', '2008-03-03', 10, NULL, '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F0446A0E074744109B5E89EC280EC204', X'1A534647384B4C00BB6CA3371AD962EB', 25, 'Avengers Assemble', 'Save the day with the Pawn Stars when two original #1 comic books from the Avengers and Giant Size X-Men series fly into the shop. Will Rick "marvel" over these rare finds or will he play the villain? Then, Corey is faced with a mystery when he is presented with a cane belonging William Pinkerton from the infamous Pinkerton detective agency. Will he call in an expert to help investigate or will he end up closing the case? And later, Chumlee leaves work to track down his own comic book collection. Will he return with the Holy Grail or will his comics not make the grade?', '2015-05-07', 21, '/it67hPWstKPnPcyLJl9tSCSwU2I.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
