INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F056E76FA9AF4BF5949D9996754AD57C', X'150D1480F3F143F99A22D2527756FBA2', 5, 'The Rumor Mill', 'Ashley''s new baby, Dylan, makes a first impression that Gizelle will never forget; Mia opens up about her childhood trauma to Gizelle and Robyn.', '2021-08-08', 42, '/fOn8jGCH5AslI8vNybnLtr30VEL.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F0573983343E44F7A405E810C7AE29DE', X'ECB64EF34F8045A7B4A9C04434B02E35', 30, 'Chum''s Revenge', 'Start your engines with the Pawn Stars when Rick checks out a 1956 Buick. Known as the ultimate family wagon, will he drive home a deal or be stuck in second gear? Then, Rick teaches Corey to be "a believer" when a "sweet" Neil Diamond jacket flashes into the shop. Can they hit the right note or will they be out of tune? And later, the Harrison men get family portraits made to hang in the shop. Even though Chumlee is left out, can he find a way to leave a lasting impression?', '2014-04-10', 21, '/sTcf4cCCtI1aOq4H9LG0Tci5Zph.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
