INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F05F51D649204765BE6F04DC11C5298D', X'E38E9D8714324A1AA7D064A559BF7570', 2, 'The Journey Begins', 'When their only means of water is filled in the animals all meet by the Great Oak to begin their long journey to White Deer Park. While performing a head count Badger discovers that Mole is late. He eventually shows up and the animals begin their journey. They stop at a human''s swimming pool to quench their thirst but they make too much noise in their excitement and wake up the human''s cat. Fortunately the cat is too fat to fit through it''s flap so the animals escape with out being caught.', '1993-01-10', 24, '/vM4P1P7KvHRZ2qfQyx5N1So4Z7P.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
