INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F0657C57B78443D688258385D9B58101', X'095258D0D8DB40968AC76A42CD4CBDCF', 9, 'Wembley And The Mean Genie', 'When Gobo, Red and Wembley are searching for unique items, Wembley comes upon an old green bottle. He takes it back to his cave, and while he''s polishing the bottle up, a genie appears. Wembley can hardly believe his luck, but this genie has his own agenda. He destroys all the items Gobo and Red found, then he scares Boober half to death by making his laundry look like ghosts. Gobo says he needs to get rid of the mean genie, but the genie says he needs to stop letting Gobo boss him around. Later on, Wembley decides Gobo was right, and they create a plan to get the genie back in the bottle, then bury it. The plan works, but Wembley feels sorry for the genie, and lets him out. Later on, when Gobo''s trying to show everyone the bottle, he accidentally breaks it, but Wembley confesses he let him out. The genie shows up again, and turns all the Fraggles into something that looks like a Fraggle army. It''s up to Wembley to stick up for himself to make things right again.', '1985-02-25', 24, '/yVjTJB9fHcxwYry2AfoPX0Gsn0z.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
