INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F073AE10AAD3447AAF48B21A27309A1B', X'3FDCCC2CE56342FB8874C93879CD4141', 13, 'Wanted', 'The farm is paid an unexpected visit from an escapee from the nearby prison who takes refuge in the barn. After a short while with Shaun and the gang, though, prison doesn''t seem such a bad option.', '2016-11-09', NULL, '/hjZ9je4LlQBGe3oBnEZIKzx6lMp.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F076E6F65C754AA691FAB53CF559C7BC', X'6F731E6BD3C54DE684E17A19CB650E86', 5, 'Napoleon Bonapawn', 'Paint it black with the Pawn Stars when a rare Rolling Stones record spins into the shop. Will Rick be satisfied or learn he can''t always get what he wants? Then, Corey tackles a football used in the first Hall of Fame game. Will he kickoff a deal or end up blind-sided? Next, Rick''s on guard when three swords from the Napoleonic era charge into the shop. Will his negotiating make the cut or will he forge on? And later, Chum gets animated by some Donald Duck model sheets. Will he quack up an offer or be left ruffling his feathers?', '2016-11-05', 21, '/5e5ljFCKDBfzIMyfwrBSnDGa4gD.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
