INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F0915EACC0064E868BA7EFCE39B1A882', X'FC52608BB1C941C5B3CA2A7FF35BCABC', 8, 'Disaster for Dinner', 'A fire drill practice is being held at Bella''s Cafe, but first there''s trouble at 3 Vale Road when Sam''s robot catches fire.', '1994-11-17', 10, '/2yOhVgxO0aXQgTFdjMuoGcUXQgJ.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F09261F27FB8489B9F191BA516F9CE5D', X'42E591E22A884434AE9F3D4B1D685613', 33, 'Winchester, Lose or Draw', 'Head West with the Pawn Stars when the guys check out a Winchester rifle from the Wounded Knee Massacre. A Native American weapon captured by the U.S. Army, will Rick try to capture it for the shop? Then, a nickel slot machine from the 1940s drops by. Is it worth the gamble? And later, the guys find a stray dog outside the shop and it''s up to Chumlee to find its rightful owner.', '2013-11-07', 21, '/pEtwkT0Qe7lYuQlP0e56pG73z76.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
