INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F098CEA9DD66430094472FB1A1275FA5', X'0BBD380C5CB846A68838B5D60223C073', 10, 'Harvey Korman', 'Embarrassed about being the "token person" on the show, Harvey is dressed up as a giant chicken.', '1976-11-07', 26, '/kttNSMghyajdU9arnaPl6q1I1pm.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F09BAF72CCE64EF789FA46ED39C95400', X'70C8CB4624944DD498F66BFB9B3FAF73', 3, 'Shocking Chum', 'The Pawn Stars are presented with one of the most expensive items that has ever come into the shop - sunken treasure from the Taj Mahal dynasty. Will they break the bank to plunder the prize, or will they let it sink back down to the deep? Then Rick has an opportunity to buy a 1948 portable electric shock therapy machine - can he charge it up and make the deal, or will this negotiation run out of batteries? Then later Rick considers purchasing a tricked out Yamaha Rhino built for desert 4-wheeling. Will this deal dry up and evaporate like a mirage, or become Rick''s new favorite off-road oasis?', '2010-01-25', 21, '/4lQoxqsQGfh4Qxh979MR24EesDH.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
