INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F0A17B1FBF9C42CEA4A71DA96E74F0EB', X'5C4E51C6E20746AD875C72988EB1E13E', 10, 'Necessary Roughness', 'The Pawn Stars prepare for battle when a collection of secret plans from the WWII D-Day invasion marches into the shop. Will the guys storm the beach for these former top-secret wartime documents or will a ferocious negotiation force them to retreat? Then, Corey and Chumlee are presented with the head of a rare 1970''s toy called Stretch Serpent. Will Corey try to charm this slithering snake head or will this bodiless deal come back to bite him? And later, a man walks in hoping to sell a leather football helmet from the 1940''s. Can Rick keep his head in the game or will he be forced him to punt?', '2011-05-02', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
