INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F0EB60F8668B4D87BC691B9A42B8202B', X'ACAC417E2AA342E79E08ED0D6071A3EE', 2, 'Running Your Mouth', 'Sonja makes hurtful accusations about Tinsley’s finances. Meanwhile, Dorinda attempts to improve her friendship with Sonja. Carole runs the New York City Marathon after months of training, but with a surprising omission in her cheering section.', '2018-04-11', 60, '/elKFsvVtVysjYW6tfyyZwXlPICX.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F0ED5E8D94FB49A0B3BB374E6DAB7932', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 74, 'Episode 2169', 'Susan asks Telly to go to her car and retrieve Miles'' toy from the front seat. Telly runs back and forth, asking questions about how to open it, which key to use, and which plaything to bring back. Gordon sings "I Heard My Dog Bark" as Susan, Bob, Uncle Wally and some kids make the animal sounds.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F0EDD7E884674D8B91B3C2255F31EEEE', X'F5266C49EB294594B5D9F927EDFEE336', 25, 'Hidden Talents', 'Mowermouth the goat gets to annoy everyone when he places first Shaun, then the Flock under his hypnotic spell. Bitzer and Shaun need teamwork to put the goat in his place.', '2014-09-29', NULL, '/7GynqmGDvRbO7dmrSBlLnGbUAiZ.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F0F002BAD11E4334906305C139A808AA', X'D5383B3D56364D71B99CB84774B4B3C6', 13, 'Pingu''s Dangerous Joke', 'Pingu is out walking. As he goes past a neighbour’s igloo he hears snoring. He throws a snowball at the igloo which lands on the bell, making it ring. Pingu then hides behind a nearby mound. The ringing of the bell wakes up the neighbour, who comes out to see who is there. He can’t see anyone, but then spots the snow on the doorbell. He brushes it off and angrily goes back inside. Pingu thinks this is very funny! Pingu walks on and arrives at Grandfather’s house, just in time to see Grandfather walking off, pulling his sledge. Pingu runs to get ahead of Grandfather, hides as Grandfather goes past, and then follows surreptitiously as Grandfather continues on. Grandfather reaches some old abandoned igloos and starts to collect odd scraps of wood, loading them into a box on his sledge. Pingu has an idea, and hides while Grandfather continues to search for wood. When Grandfather goes a bit further away, Pingu comes out and knocks the box of wood off the sledge, then hides again. Grandfather is surprised when he sees what has happened to his box, and tries to find out what caused the wood to fall off. He stops to examine the ice nearby. Pingu, meanwhile, has crept up to the top of a mound of ice next to where Grandfather is searching, and slides some ice down the mound, which lands at Grandfathers feet. Pingu chortles at Grandfather’s surprise. While Grandfather is consoling himself with a sandwich, a boulder of ice that Pingu loosened when he got the previous ice for sliding, starts to roll down the slope towards Grandfather. Pingu is dismayed and calls out a warning; Grandfather looks up, sees the boulder heading towards him and, dropping his sandwich, jumps out of the way just in time. His sandwich is totally squashed! Pingu slides down, and says he’s sorry when Grandfather tells him off for playing such a thoughtless trick. Pingu then picks up the box of wood he knocked off the sledge earlier, puts it on the sledge and helps Grandfather to get it home.', '1999-01-21', 5, '/8TcFo6YBu89m1YkpCsepEOwRjXd.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
