INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1772752A9AE4546960E50195AFD9E41', X'45E64A158FC04E4BA1CA9E3F42F3634D', 17, 'Cells', 'You can''t see them, but they''re everywhere even inside Bill Nye. This is not science fiction, it''s the   science of cells.   All things that live are made from cells. You can''t see them, but every part of your body, including everything   inside your body, is made from cells. Cells eat, they grow, and they make more of themselves (what   scientists call replicate).   There are millions of different types of cells. Dog cells are different from fish cells. Bird cells are different   from your cells. And inside your body, there are many different cells, each one doing a different job to   keep your body going.   Cells may be tiny, but without them, we''d be nothing.', '1994-01-21', 26, '/y3KgzUiXaxhiln3FoXzn2Z6cCO6.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
