INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F19E76F2E7AB4908ABE0B4360EFD89DA', X'EB7E3BB45746457781C6F5B2DC2EFC6E', 10, 'The Library', 'When Aang and his friends find a professor who knows of a library that contains information about the world, Sokka decides to go there to hopefully find some information to use against the Fire Nation. The library is guarded by the knowledge spirit, Wan Shi Tong, who unfortunately doesn''t welcome humans into his library, because he believes they only seek information for evil purposes.', '2006-07-14', 25, '/fvAu7bhOFyI9HEt1Msp0WutlILb.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
