INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1A52A91845341A6B7F4C23DA826A5D0', X'93651310A84F42EFBCB7AB8F788F102D', 9, 'Birkin Buddies', 'Adriana makes unreasonable demands; Marysol and Alexis try to stop Adriana from ruining her own wedding; Romain and Joanna find more problems between them; Lisa comes to Lea''s defense.', '2013-10-07', 44, '/gSukW8G0iKu3yw9v6ROKje3h24c.jpg', '2026-04-03T16:35:10Z', '2026-04-03T16:35:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1A601540F1A47F5B32D47E19CDC4CD4', X'04FB713D9C5945F78DE0ACD7582DAA53', 9, 'Communion and Confession', 'The feud between Teresa and Jackie threatens to upset Joey''s communion; Jennifer is offended when she learns that Jackie has written an article about her family. Dolores plans an event for a homeless shelter; Milania copes with her detained father.', '2019-01-02', 43, '/lD2tfFJmjigLRUowOKmKdXYDoTg.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1B1DAF351544A6E97DF89A82F3A9877', X'3982796B54514100904246BEDF6A20A5', 12, 'Pingu''s Parents Have no Time', 'Pingu and Pinga are flying their kite when the wind goes light and it crashes onto the roof of the igloo. Pingu tries to pull it off with the string but the string breaks. Pinga goes inside to get help from Mother or Father, but they’re busy and say that they have no time to help. Outside, Pingu is trying to dislodge the kite by throwing snowballs at it. The first one hits Pinga as she comes back out of the igloo. She cries, but is comforted by Pingu. The second hits the kite, which slides off the roof and lands on the ground in a broken heap. This time Pingu goes in to ask for help, but Mother and Father are still too busy. Pingu and Pingu then go off on the sledge to see Grandfather, who helps them make a new kite. Meanwhile, Mother and Father realise it is getting late and go outside to get Pingu and Pinga, but there’s no sign of them. They get on Fathers motorised sledge and go looking, asking the post-office attendant, the fishmonger and a neighbour if they’ve seen them. They all say they haven’t. Eventually they arrive at Grandfather’s igloo, where they see a kite being flown behind the igloo; Pingu is flying the new kite, watched by Pingu and Grandfather. Mother and Father thank Grandfather for his help, and Mother, Father, Pingu and Pinga all go back home together', '1993-05-09', 5, '/nRqFZed0YMw3h0qHDuu6MjAmFig.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1B5685F06D84B85B4C30F99B179B170', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 127, 'Leo''s street party', 'Gordon comes across Dexter juggling in the yard and wishes he can juggle as well as he can. Telly has caught word that Leo the Party Monster is throwing a dance party, but has a big worry - he doesn''t know how to party. Leo tries teaching him some of his moves and recommends he practice.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1B8392482F0484EA723D88F6D742CBD', X'1E085F654B6945008FFC654D2F638DBB', 5, 'Sesame Street Self-Portraits', 'Elmo, Tamir, Charlie, Julia and Cookie Monster are making self-portraits, drawing what they look like and what they love to do.', '2023-12-07', 26, '/a1EiN722kMPZaZOe3aK2UfEqON3.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1B93516E90141C4B9D833090CB60ADC', X'42684FCA0BC74F4CBF7DF41FD288A764', 17, 'Postman Pat and the Job Swap Day', 'The school roof needs repairing so Pat suggests that Greendale has a job swap day to raise enough sponsorship money.', '2004-10-01', 15, '/xl4aS41fl4Lzu3ReXMr4ml62iq2.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1BA7D8B727B4F0598B7888B71A0D2A0', X'1996DDD820C94A3096BE2B87FAB8D17C', 31, 'Building Bridges (1)', 'The team is excited about the upcoming star jam talent show because they are in charge of it. When their friend Cambell arrives with a sore eye, they realize that violence is in the neighborhood. Rob, a coaching assistant, makes friends with an ex-gang member. The gang feels safe that Hurston hasn''t been the target of vandalism. Or has it?', '1993-04-25', NULL, '/yFMmVXAnXWuGxNOD0ZyOGSRXvaF.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1BB45A182454877ACFA83AD38B6B09C', X'097823B34B9F460D9CCF923AF9E525BB', 14, 'Celebrations', 'Friday''s Comet arrives in the Neighborhood of Make-Believe, bearing a note that neither King Friday nor anyone else will forget. They all go to the Museum-Go-Round for Henrietta''s surprise birthday party. After the party, Henrietta is surprised to hear that Reardon is making a new opera that will air the next day.', '1986-05-08', 30, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1C1DEDD4ACA4B3C86D96E5B58AF277F', X'E40E6B639F84449F8E8853209B0906C8', 5, 'Abby Plays the Letter ''P'' Game', 'Elmo wants to play tag, but Zoe wants to play checkers. Alan notices them arguing, and suggests they play the "letter P game." In order to play, they need to look around the store for things that start with the letter P, such as pickles. While Elmo and Zoe have difficulty looking for P words, a penguin (who pronounces his p''s hard) comes in and orders a peanut butter sandwich on pumpernickel bread, with a slice of pineapple, and a potato.', '2007-08-17', NULL, '/e0kcpXRHV9K3gavXwmbTvNiCnQl.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1CA2F55F9CE4176B7DA04128FB39E54', X'332249FA796B4F92B7F8421D523B0BDC', 14, 'Montego Baes', 'As Sanya continues to host the group trip in Jamaica, Kenya is not impressed with Sanya’s hosting skills. Kandi has a hard time moving past her conflict with Marlo. Everyone is over the drama when Drew races herself into another injury.', '2022-08-14', NULL, '/w1w8rmPQaxKNUQCed7QVoiQh4iM.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
