INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1D2189338E745D3B9E8734DFA4CF185', X'D8CCF6D3E37A430AB67D7FBF269BF0BE', 6, 'Après Rumor', 'The rumor about Angie''s marriage has a ripple effect in the group. Meredith finds comfort in her family after a traumatic incident on the road. Old issues between Lisa and Heather resurface. Monica''s parenting is called into question by her own mother.', '2023-10-10', 44, '/4uwzbc4ljKqC28DeRkbAcBdcX7d.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1DA4601819841679E9B15C54DC0CF42', X'573FA62F55A94F1797CCD1A005A83CC8', 29, 'Putt Putt Cookie', 'When mini golf is canceled because of the rain, Abby poofs up a course, and Cookie Monster''s friends teach him how to hit the ball into the hole.', '2025-07-31', 26, '/iWHPIGIWbkLR26tz4RAYeU089O5.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1E7DD7FCEF7413F93C49C8CC1F75BF5', X'4D0FD8A552004DFCB96CAE436DC8803C', 9, 'Through Moon and Stars and Night Skies', 'What is it like to be adopted? In what may be the high point of the 10th season, this show has a lengthy sequence about adopted children in families. Andrew Lei narrates Through Moon and Stars and Night Skies, a story about a boy who was adopted by a pair of parents who wanted a child very much.', '1992-10-15', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F1EE98EDD2F749DCB3CACA3F38BB8D80', X'1A534647384B4C00BB6CA3371AD962EB', 5, 'Money Ball', 'Hail to the chief with the Pawn Stars when an archive of items signed by President Franklin Delano Roosevelt is brought into the shop. Will this presidential collection get Rick''s vote or will it get vetoed? Then, Rick steps up to the plate when he is presented with a rare photograph of Babe Ruth from his rookie season. Can he call the shots or will he be thrown a curveball? And later, after Chumlee lends money to Rick, he goes to great lengths to get back what he''s owed. Can Chum get payback or will Rick end up cashing in?', '2015-01-22', 21, '/sQyUMKgZs9QiBb1yMpG3R4RlNkO.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
