INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F2689A25281B4155825717458088AB42', X'D920EBAEF00A4E25ABFE40492C74DED6', 24, 'Mystery Safe', 'It''s a bird! It''s a plane! It''s Superman pajamas! Can Rick and Chum make a deal for the Man of Steel before the seller flies away? Then, Rick says cheese as he cuts a deal on a vintage industrial slicer. Will he take the gouda with the bad, or let it melt? Next, a Mario Andretti signed helmet races into the shop. Does Rick want to go full speed ahead on the buy, or let it pass? Meanwhile, Chum enlists Alex''s help on a rare World War II jacket. Will he be able to patch up a purchase, or is this a battle he can''t win? Later, a vintage clay pigeon shooter pulls into the shop. Can Rick hit the mark, or will this one skeet away? Finally, Corey and Chum are offered a locked safe with unknown treasure inside. Will they buy the safe, or be sorry?', '2020-06-30', 42, '/eotCzmpV8atEBaDlQUhdubELvVe.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
