INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F27035C9F1DB43FDBC694B992B609531', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 41, 'Episode 2136', 'Telly, while helping Luis at the Fix-it Shop, asks him when lunch will be. When he realizes they''re both hungry Telly panics, but Luis says they can take a lunch break. Piri encourages him to try and remember, so Telly thinks hard and finally remembers the order.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F271F87F6463469CA3053B9ECCBDCCE9', X'CA19F89515144988A70995E84EAB7CEE', 12, 'Pawn Shop Rock', 'A blade rumored to belong to a Japanese World War II admiral commands Rick''s attention. Can he cut a deal, or will the negotiations be pointless? Then, the guys take another Harrison under their wing for a summer job he''ll never forget. Next, some vintage baseball cards slide into the shop, leaving both Rick and Corey speechless over the $60,000 asking price. Will they knock this deal out of the park, or strike out? Finally, a guitar pick belonging to Elvis has Corey all shook up. He can''t help falling in love, but the deal might land him in the heartbreak hotel.', '2021-03-29', 42, '/NEr41biQkMITfj7xA5bjs8WESm.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
