INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F290C8625C9A4350BA6BC94C54BE91C4', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 82, 'Telly gets angry with Luis', 'Telly shows Big Bird his early marble collection in a jar, but when Big Bird tries to look closer, his wing gets stuck inside. Luis and kids find hidden letter As hidden within an ocean picture. Forgetful Jones returns to Hooper''s Store moments after eating, ordering lunch again as if nothing happened, while Telly grows angry when Luis breaks his promise to play ball in the park.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F291438C4D334099B135735400069C1C', X'B892884D7B564255A4C608F5D0122273', 9, 'Seashore', 'What happens to a crab that loses its claw? How did one low tide wreck the entire Greek army? SEASHORE dives into the explosive front line between land and sea. From crashing waves and blasting winds to placid tide pools, discover what makes our coastlines so alluring to the masses of wildlife and humans who gather there.', '1996-10-28', 29, '/291m9xdAczYnF5cCFTriFGRNCyn.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
