INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F2C34CAD3E134E25A7F70377E5B6C17E', X'91C151D984974056A4EE753CDCB08CEA', 4, 'Episode 1459', 'Mister Rogers arrives with a plastic pail which he takes to the garage. On the way, he picks up a bottle of glue from the kitchen and fills the pail with sand from the backyard sand table. In the garage, he spreads the glue on a large piece of construction paper and sprinkles it with sand. Chef Brockett calls to let Mister Rogers know he will be coming over to bring back the film of Mari Gardner from the previous day. While he waits, Mister Rogers makes another piece of artwork with glue and glitter.', '1976-02-19', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
