INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F301D546B8C044D7BF6530B268F59C2A', X'A75DC15E67DF4DB29E0F8B9901DBAB51', 1, 'The Tale of the Frog Prince', 'Robin Williams and Terri Garr star in this wonderful adaption of the frog prince. Angered by the lack of an invitation to the christening, the prince''s godmother goes into a rage and transforms the baby into a frog. A few years later the beautiful and vain princess loses her magic ball down the well,the frog takes pity on her and gets it out in exchange for a night in the castle, he will eat with her and sleep with her.she tries to blow him off but the king (Rene` Auberjournois) finds out and forces her to let the frog stay.after a brilliant battle with a scorpion the princess kisses him and "POOF," he turns back into a prince.', '1982-09-11', 51, '/oDpsCRaEI3w0zzss3ueJDJFIOgg.jpg', '2026-04-03T17:38:40Z', '2026-04-03T17:38:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
