INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F34CA818FD67420188D237FE10008235', X'7BC54DF3F32A454EAEF6A9436C35D53B', 14, 'Growing from a baby into an adult', 'Rogers discusses growing both on the inside and on the outside. Mr. McFeely brings a dry aquarium holding frogs and tadpoles. Later Mr. McFeely visits the Westwood Children''s Zoo. Queen Sara returns to the Neighborhood of Make-Believe from Westwood after two days with Dr. Frogg.', '1970-02-19', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F34E1789ADEF4393A2B024929772B7DB', X'E6359E6D9BDB4ABA9CBA6F7DDD6328F9', 9, 'That Was Weird', 'Teddi’s beach house weekend ends abruptly—and disastrously—when Dorit reveals to Erika what was said about her after her unexpected departure. The ladies descend upon New York for Fashion Week. Lisa Rinna helps her daughter, Delilah, get settled in New York City. Private information about Lisa Vanderpump is revealed publicly—and some of the ladies worry how she’ll react once she finds out.', '2018-02-13', 43, '/lKl88wy5hNVxMleBI2a594bTPDb.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
