INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F35556A9DCF44CF0953104EFD938D743', X'8B6BBAC8E5EF49C7A5C1197CFB19F772', 3, 'Divorce', 'Rogers recalls the day he test-drove an electric car. Later he meets Jeff Erlanger, a boy in an electric wheelchair, who demonstrates his wheelchair and describes some of his physical handicaps. The Neighborhood of Make-Believe continues its all-out search for Prince Tuesday. When he is found, he has a mix of emotions.', '1981-02-18', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
