INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F35DD0012A0844188C57763F879910E8', X'1415EF1C411A4C26814A7C79C3628BC2', 12, 'Regency Reunion', 'Sonja’s love triangle gets more complicated as things heat up with "Frenchie." Meanwhile, Tinsley goes apartment hunting. Carole and Adam bicker over items he left behind in her apartment. Fredrik and Bethenny look over her apartment as they plan to put it on the market. Carole and Dorinda go to Washington DC for the Women’s March. Ramona throws a party at her apartment with a surprising guest list.', '2017-06-21', 60, '/zBPCzqxxf9ByL8oLpkiE67F17Ws.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F3670D228AE04A6F9F45B0FDA6B30D3F', X'C21DBD225E2E4414BB67750399AAF6F0', 16, 'Cash Cash Bang Bang', 'The Pawn Stars are amazed when a first issue Spider-Man comic book swings into the shop. Potentially worth hundreds of thousands of dollars, will the guys have the spidey-sense to buy this super rare book or will they tangle up the negotiation? Then, a guy moseys in with an antique 1860 Colt Army Pistol. Considered the assault weapon of it''s day, will Rick have the firepower to draw up a deal? And later, Old Man checks out a gold mining stock certificate issued to author Mark Twain. Issued in 1876, will the deal pan out, or will the guys end up in a deep hole?', '2012-01-16', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
