INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F368169F366743358CA45C552C451A47', X'F4C403079B5E4263A4E0DFA138131E7F', 71, 'Elmo''s World: Pets', 'Having pets teaches kids about responsibility and caring - and ELMO''S WORLD: PETS! helps them understand more about what having a pet means. This compilation of episodes shows how to keep pets healthy and happy, and features both adults and kids caring for their own pets - including Elmo and his pet goldfish, Dorothy. Features the charming animation and fun live-action footage of the "Elmo''s World" series.', '2011-04-11', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F36C749914F44CA7BBFE618C4FCF7C6F', X'3269A890BBA94E6C9278F7EB38EB1720', 19, 'Populations', 'Populations need a couple of basic things to survive – food and a place to live. When two or more populations of living things are crowded into a small area, there is competition for food and space. A population of birds and a population of squirrels compete for seed and bread crumbs in a park. Competition is a natural part of life, but problems can arise if populations get out of balance.', '1995-10-20', 26, '/akr8Ox85ARRwXHsGftqzjhfkHsc.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
