INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F3BAA19C8F22463FBE4ACF85793D350C', X'F5C042DC065742E8A37D247414140632', 11, 'Mommy Dearests', 'D''Andra makes amends to Momma Dee on the heels of their epic fight, while Kary bonds with her daughters on a hike and Stephanie unveils her first locker room project for charity. When Tiffany hosts an elegant luau to make up for her disastrous pizza party, Brandi and D''Andra clash over what it means to be a "real" Christian.', '2021-03-23', NULL, '/pQEUTAa8lwXbsGYc3vqcjJKuS8L.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
