INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F4097D8C099042D88160656C8E6231DC', X'6C71887AD6E341F1AA7CF482ABC104D2', 2, 'The Silver Chair (2)', 'Jill and Eustace are introduced to Puddleglum who agrees to be their guide to the ruined city of the giants, but will their new found Marshwiggle friend meet his fate before they manage to get there?', '1990-11-25', 30, '/kLVTjJwdQEakEU3jwceGf2o0eB8.jpg', '2026-04-03T17:17:41Z', '2026-04-03T17:17:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F40A787B9D2C4F4484EBEA19EBEB0285', X'45E64A158FC04E4BA1CA9E3F42F3634D', 12, 'Sound', 'Listen up, scientists. Bill Nye is here to make some noise in the ""Sound"" episode.   Your vocal cords do it. Speakers playing rock music do it. Even a school bell does it. They all vibrate; and   that''s how sound is made. Plucking a stretched rubber band makes the rubber band vibrate. Air molecules   around the rubber band move, pushing other air molecules. As the rubber band continues to vibrate, it   sends waves of sound through the air. It''s a lot like the ripples you see when you drop a rock into a pond.   You hear sound when rippling air pushes on tiny bones in your ears. Nerves in your ears send a message   to your brain about the sound you''re hearing.   Different sounds make different patterns of waves with different distances between them. Plucking,   banging, whispering, and yelling are all vibrations in air, yet they all sound very different. Sound vibrations   can be thought of as waves moving through molecules. Low-pitched sounds have big gaps between   waves, while high-pi', '1993-11-26', 26, '/kqezzxipxNonCR1nXWfUyMElgXR.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F4159CF967F842F89E81DD71CCFF6FC7', X'83D1C2FB7CD949779A5D98D36CFB59D3', 47, 'Eipsode 2598', 'Loud talker Guy Smiley goes on safari and scares off the animals.  A classic skit staring Ernie as "Old King Cole".  The Two-Headed Monster sings a lullaby to itself.  Snuffy writes a love letter to his grandmother.  Mumford''s magic trick accidentally shrinks David.  Ernie hosts an arboreal fashion show.', '1989-04-26', NULL, '/uc0vsmQKgZzDLHGAJQTukScdvvc.jpg', '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
