INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F41DBEE23B50464C8AEDAC795C6E9AB6', X'0BBD380C5CB846A68838B5D60223C073', 21, 'Bruce Forsyth', 'Fozzie Bear has a plan to get back at Statler and Waldorf when he does his act, but is crushed when he''s replaced by Bruce Forsyth. Fozzie throws some nasty jokes and, for the first (and last) time, leaves the two old codgers speechless. Then Fozzie and Bruce end up performing together, and sing "Side by Side." A duck appears frequently in the sketches and skits.', '1977-01-30', 26, '/yVVPr4poG1ONKMbkkogPpG2Y6Js.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
