INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F4899E50776B46BFA02BC67990EC9B91', X'B1D55597D9D24EEEAB9546DBB163291A', 11, 'Pingu''s Tobogganing', 'Pingu and his friends Pingo and Pingg are going tobogganing up in some high mountains. After a long climb, they reach the top, and sled their way down. Pingu''s friends go down at great speed, but Pingu has trouble; his sled doesn''t seem to slide and he can only go slowly. It then turns out that the skis on the bottom of Pingu''s sled are rusted, and his friends give him a greased rag to polish them with. After Pingu''s friends come down a second time, he shows them how clean the skis are, and does a test, which turns out successful. They try a third time, but Pingu over-polished the skis, and he goes zooming down too fast to control. His sled breaks, and he crashes into a snowman, getting stuck inside it. Pingu''s friends find him, move the snowman inside, and then put it near the furnace so it melts to free Pingu. When he thaws completely, Pingo offers him the greased rag again. Pingu rejects angrily. Then they all have a good laugh about it.', '1989-12-16', 5, '/yAFAyf36SJymgpZ3x9i9Gdidy34.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F4923C10C27741B0A2E4BB5CD28F6A0C', X'D8CCF6D3E37A430AB67D7FBF269BF0BE', 16, 'Mysteries, Revealed?', 'On their final day in Bermuda, Heather receives a devastating phone call with incriminating information that affects the rest of the women. Meredith remains in hot water for her role in the rumors about Angie. A bombshell about Heather''s black eye is revealed. Someone in the group is exposed and the women must decide whether they will cut ties or accept past mistakes.', '2024-01-02', 44, '/qehVbTQzAUsDB1GAb4iGXIsB8wl.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
