INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F4A4FA29A6534359B681EB9D0A968587', X'45E01C046AC641E187D8F749EE230385', 1, 'Blow Me Down', 'Station Officer Steele gets out his kite and pretends it''s his nephew''s. When he tries to fly it at the Flood''s house, it gets stuck on the roof. Meanwhile Norman Price, Charlie Jones and Dilys Price are in need of help in the sea. Fireman Sam is in charge at the Fire Station, so he goes to the rescue.', '2008-02-11', 10, '/7v3gzy1uXqDypJj5FCWmFIFBRWu.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
