INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F4B552769D524C29B14C0F2C26E824FB', X'F07B879456254682AAE1E56966B4C7A8', 15, 'Those Ears, Those Eyes', 'Julie is upset because a classmate calls her eyes “funny.” Her friends help her see that everyone’s eyes are different and beautiful, and that they are all just right for them. Nuzzle imagines what it would be like to have different kinds of ears.', '1996-02-02', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F4BABFE595DD4A66BE51E0614B11B691', X'EA73E13C696248048305C303DF65F89F', 2, 'The Froggs are Moving (2) - Squares', 'King Friday needs to find another curator to operate the Museum-Go-Round. The Frogg family cannot leave until Lady Aberlin and others can fill that post. In the meantime, King Friday has a portrait of himself to give the Frogg family. Handyman Negri also arrives at Rogers'' television house to collect a frame for the picture which sends to the neighborhood on the trolley.', '1969-02-11', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
