INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F4BDF3AF646F42029012AB0EB2F39CFA', X'AB509C47EC644FB3856003873DD0C37E', 2, 'The Big Salad', 'Kramer fears a golf dispute has pushed his opponent to murder; Jerry dates a woman whom Newman rejected.', '1994-09-29', 22, '/smPCkHsiE4p9mTeMVscwnI451M9.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F4BF7A8581E74B1FA5E09C12DB155F15', X'68138DE20900460AB58E480688F1E081', 39, 'When You''ve Got To Go...', 'Bear and Tutter are trying to have a fun game of checkers, while Ojo and Treelo are having their own fun playing. For some reason, though, everyone seems to be talking about the toilet and the bathroom. It all starts when Tutter needs to use the toilet during his game of checkers with Bear, but doesn''t want to leave the checkers game. Bear assures him it will still be waiting for him. Tutter uses the bathroom and then washes his hands, stating that his Grandma Flutter taught him to. Later, Ojo has an accident and is very embarrassed, but Bear lets her know it''s okay --- accidents can happen to anyone. When Pip and Pop hear about the day''s events, they invite everyone to join their secret club --- The Mystic Order of the Toileteers. It''s for everyone who uses, or is going to use the potty. In the Shadow segment, Shadow introduces a song with some new twists on the phrases "party party" and "potty training."', '1999-02-28', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
