INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F4C7050B377E436BAF13A2F1BBEAD163', X'DBDE6570A68D4FD7A1B0A6037A266A18', 10, 'Cabin Fever', 'Alexis plans a camping trip near Santa Barbara, but pulls out. Gretchen skips the trip due to her Pussycat Dolls performance, and Tamra recovers at home from her surgery.', '2012-04-17', 44, NULL, '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
