INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F509E26C8B784570AE04A3F5B7085953', X'E291DF42D44F49E5BF812DF32EE4A30F', 8, 'Woodland House Wonderful', 'Despite something of a mess in the living room of the Big Blue House, Bear is prepared for a relaxing day. He settles down for some relaxing music listening, but then receives a phone call. It''s Ms. Henrietta Vanderpeen, informing him that the Big Blue House has been selected as the House of the Month for Woodland House Wonderful. Bear is excited, but worries about the state of the house. He tells the kids the exciting news, but finds out from them that there''s even more cleaning to do than he thought. Everybody pitches in to get ready by cleaning the house, taking a bath, and brushing their teeth.  Songs  Clean Up the House  Everybody in the Tub  Brush Brush Bree', NULL, 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
