INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F510DBDC45F943E89051836F67E06EF5', X'DC6EF505D1944259B2565711D25ACA6B', 1, 'Dragonstone', 'Jon Snow organizes the defense of the North. Cersei tries to even the odds. Daenerys comes home.', '2017-07-16', 59, '/3SB4PUzZAnY6HnZbVbktIZoopGs.jpg', '2026-04-03T15:40:37Z', '2026-04-03T15:40:37Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F5194D524F5E4BF19017BDC257B09749', X'1A534647384B4C00BB6CA3371AD962EB', 15, 'Live Long and Prosper', 'Get fired up with the Pawn Stars when an Eli Whitney Civil War revolver drops into the shop. Will Rick go forth and win this firearm, or will he blow his shot? Then, Corey boldly goes where no man has gone before when checking out a signed picture of the original Star Trek cast. Will he engage and beam this item into the shop permanently, or will things get highly illogical? And later, when Corey un-friends Chumlee on social media, Chumlee decides to un-friend Corey in real life. Is this the end of them as pals or will it lead to the beginning of another beautiful friendship?', '2015-03-05', 21, '/s8BfDMaVH6UpZ264qLhxWifDsfu.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
