INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F53A0BCB0ED248079EFD8175BDE4CA79', X'0E4196154C964DDE8ED2715770BA77BB', 16, 'Grandma Flutter''s 100th Birthday', 'It''s Grandma Flutter''s 100th birthday. Bear and the kids of the Big Blue House take some time to reflect on aging and all of the experiences that life has to offer. Ojo, Treelo, Pip and Pop work to decorate the house and prepare for the party, but Tutter still needs to pick out a gift for her. Bear takes him to the General Store, but he''s not sure exactly what to buy her. While at the General Store, Tutter learns about some of the wonderful things that his Grandma has done in her life. As he hears more and more, he becomes overwhelmed, until Bear helps him to see how he can work it all into a perfect gift. Bear also plays a game of chess with Doc Hogg. He''s not very good, but Doc Hogg helps him to see that he has a lot of time to learn. Shadow also pays a visit and tells a story about about the life of a hammer.', '2006-04-24', 25, '/c1N3c2vZO7qTsEnaNOmFYXwL5Ku.jpg', '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
