INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F554D4BEE6E84518B9F6FEC31FE0E264', X'3ADE5E1F84414C2CACF6FB933A61DCFA', 20, 'Reunion (2)', 'Monique and Candiace address their broken relationship and the breach of trust that lead to its downfall. Robyn''s future with Juan is put into question. Gizelle and Monique address their ongoing feud in hopes of finally putting it to bed. Robyn reveals whose "bleep" Michael wanted to "bleep" that fateful night at L2.', '2019-09-22', 42, '/fqUhSFpQgIYTMUUnc5Hh8OoMmm0.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
