INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F55A6A7431D8444A83E4F564E88BD0D3', X'C01DDD2ABDB14C978D0458F791EF1C24', 22, 'Pets', 'Chris and Martin find a bunch of pets at Animal Junction. They all belong to Jackie and her animal helpers. Zoboomafoo learns how to take care of ducklings, goldfish, a rabbit, puppies, kittens, a crab, and even a calf. We also learn that all pets need lots of love. Zoboo also learns which animals should be pets and which ones should be ""free and in the wild"".
