INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F5AAE2267B464D4D82694F2DADB0F33A', X'70C8CB4624944DD498F66BFB9B3FAF73', 26, 'Aw Shucks!', 'The Pawn Stars meet a man hoping to sell a mysterious coin from the 1800''s believed to be from George Washington''s funeral. Will this piece be linked to one of our most revered Presidents or will it get stamped with a Presidential veto? Then the boys head out to the farm to see an early 1900s hand-crank corn shucker. Can they count the kernels and make a deal or will this husk prove too thick? And later Rick has a chance to buy an antique gaming wheel commonly used in speakeasies. Can he turn a profit, or will this deal spin out of control?', '2010-06-21', 21, '/kumcDRjwqYzJDEStL9ybCJqcki3.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F5ACC33BA7644E2095C638248A52CAB8', X'4EB9B495796241D9BA8A3BED48D9BCC6', 4, 'Too Cool', 'Lionel thinks the new kid at school, Derek Cheetah, is too cool to be on his baseball team. But what does Derek think? Guest Starring Mo Lewis of the New York Jets.', '2002-10-07', 30, NULL, '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F5AD82AB928A4DF29127EAA9DF1CF112', X'0B9D7AE7218E45A08C3AE69912F5A6ED', 4, 'Franklin''s Starring Role', 'Franklin feels sad when he doesn''t get a big part in the school''s production of Sleeping Beauty, thinking he won''t get the same attention as a stage manager, not until he realizes how important his role is.', '1999-10-18', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F5AF98A202AC4A54B377A33F93C281AA', X'3FC7C152E4F6426AA89936EC454C4403', 40, 'No Hitter', 'Max''s anger is out of control when he punches Emmy''s arm and later kicks Ord''s tail during a game of Dragon Ball when things don''t go his way. Quetzal teaches him to redirect his fury, first by not hitting others, next using words, then action, to let it out.', '1999-10-22', 30, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F5B27E2085974FF3A2BFAA0E963E28C6', X'7B19039A31AC425C8FB1B51CF2447821', 16, 'Reunion (2)', 'In part two of the reunion, Braunwyn struggles to come to terms with her past behavior involving Shannon’s daughter. Gina shares an update on her relationship with Travis. Andy questions Kelly about her social media posts, while the ladies confront Braunwyn about her authenticity. Elizabeth opens up about growing up in a cult. Sean joins the ladies to discuss Braunwyn, their modern marriage and their future. The ladies close out the season with a toast and share what they learned from the most challenging year that tested their friendships and relationships.', '2021-01-27', 44, '/rexq4jxNoWNNx5Fe46InczLv4pa.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
