INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F5CAA5FA59D44136B1D4B29B06764E0A', X'27A5A980EC0D4637B5BADF8324A6405A', 14, 'Hecking It Up', 'With Indiana hosting the Super Bowl, Frankie is devastated when she hopes to land a plum assignment as an official volunteer and ends up with a less-than-stellar position. Meanwhile, the entire Heck household takes advantage of the Donahue''s new car while they are out of town, and a scary, close call with the car causes Sue to profess her true feelings to her new boyfriend, Matt.', '2012-01-18', 22, '/4DK5YaCtuZ9KBBmiPDMJ8Jskdoq.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
