INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F5CD2167A0664A7294171D9B3B43D5B0', X'9B144910398A47D49CCD823D25CC8B0A', 11, 'The Sniff Test', 'Melissa oversees an overblown birthday bash for her daughter but an awkward meeting between Teresa and Jacqueline takes the cake. Meanwhile, Kathy serves up a meal for her sister''s new flame and Caroline''s son considers introducing his new girlfriend to his family.', '2012-07-08', 43, '/nhKwy6z2EEd9uURAE9TsFQwmvZn.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
