INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F5DEEDDFE782467BB6B9734E48523D9A', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 129, 'Elmo and Big Bird play with a sleeping Barkley', 'Big Bird and Elmo intend to play with Barkley, but he''s fast asleep. Elmo darts off, inspired to make a game that won''t involve waking him up. Elmo returns with some paper and a pencil. His idea is to interpret what Barkley does in his sleep and turn it into a story.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F5E25D616BCC4B1386605F7C6D97CF6F', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 52, 'Real Grouches', 'Oscar hosts "Real Grouches," the show that showcases talented Grouches from around the world. First, Romeo Scuggs shows how he can play his screechy violin in-between shouting "Scram!" Then, Luba Merquit performs a song on a screechy blackboard.
