INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F66657AFCC164D9EBD0994549301B090', X'BB5A884361814A6DBFDF33EF2C6BE7B8', 1, '50 Shades of Cynthia', 'Kenya returns home from vacation with big news but quickly learns that her secret is already out. Despite the explosive rumors from last year, Kandi shows no signs of defeat as business continues to boom at the OLG restaurant. Meanwhile, Porsha struggles with letting people back into her life after being betrayed, and Cynthia celebrates her fiftieth birthday one more time. Things heat up at the party when NeNe comes face to face with a former friend.', '2017-11-05', 43, '/6LmJaMz5xzYhwfkuyJQTCv3s7TQ.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
