INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F673CEFF2C9A4AD2B61F7A98527CCCC6', X'F812042DEB85432E80473675886E0B1B', 15, 'Golden Retrieved', 'Wishbone is distressed with his owner Joe''s infatuation with his new mountain bike, which causes Joe to pay less attention to Wishbone, and to act less caring and patient towards him.  Then when Wishbone goes missing for a day, Joe realizes how much Wishbone means to him, and how his dog''s company is so much more important than his new bike.  Meanwhile, as Silas Marner, Wishbone learns the value of human warmth and companionship as opposed to acquired wealth.', '1995-10-27', 28, '/uIU67cpkKYDnjT7Lavkxi4fIgJJ.jpg', '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
