INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F6A4AE7FB3044B4CBE8E92BAAC98E726', X'A84AA42DE73840818DA91FAEC0209EE9', 20, 'TV or Not TV', 'After failing to pay the electric bill on time, the electric company shuts off the Heck''s power. This leads Frankie and Mike to cut down on their unnecessary expenses, including their cable TV. The kids take up other activities to fill the void, but Frankie and Mike have a hard time figuring out what to do. Meanwhile, Brick and his other socially-challenged friends have to go outside for recess when the school library shuts down.', '2010-04-14', 22, '/xe04CWO6Ra5kw9DqZSOXFVng5xD.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
