INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F6BB32D1ABA5400BA4EEF22EB43206F1', X'42E591E22A884434AE9F3D4B1D685613', 44, 'Lost in Spacelander', 'Serve time with the Pawn Stars when they check out a lap desk made by Dr. Samuel Mudd. Made when Mudd was imprisoned for his role in Lincoln''s assassination, can Rick snag it for the shop, or will it make a clean getaway? Then, a 1959 Bowden Spacelander bicycle pedals into the shop. Rarely seen outside a museum, can the guys keep both wheels on the ground? And later, a good deal earns Chumlee a bonus, but will he spend it wisely?', '2013-12-26', 21, '/8hcUDLPZvTTuu1Ng2mUJpYHlHut.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
