INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F6D438F390D44D369CEE975509022C5F', X'B5AB3A72BC794E9BA53196739AFD7AEA', 1, 'Ship in a Bottle', 'Emily Brings home a bottle with some bits of wood in it.  Professor Yaffle tells them it is a ship-in-a-bottle.  Bagpuss finds this puzzling, wondering where it would sail to.  With the help of a nursery rhyme and a poem about Mermaids, the ship is magically reassembled.', '1974-02-12', 15, NULL, '2026-04-03T17:23:58Z', '2026-04-03T17:23:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
