INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F6E9D64E8E10467084A21CB4B1725895', X'1E085F654B6945008FFC654D2F638DBB', 17, 'The Kitty Sisters', 'Chris and Elmo put up signs to try to find a lost kitten''s owner, and Grover and Cookie Monster learn all about how to take care of a kitten.', '2024-02-29', 26, '/n1EKlCxEDN0es1Jh6y6eJCo20mk.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F6F0388B1A0A473ABDDCF9A3612950CD', X'941B8C6544544336BE7C1D0591C12F90', 21, 'Pingu and the Snowball', 'Pingu is enjoying himself by playing and juggling snowballs. Pingo comes along and starts a snowball fight. As the fight tails off, Pingu makes a larger snowball that he can’t lift. Pingo makes an even bigger one! Not to be outdone, Pingu makes his even bigger, so that it’s now larger than Pingo’s. Then they spot the ski hill and, with a lot of effort, push Pingu’s ball up to the top. As they push, the ball is getting bigger all the time, so that when they reach the top it’s quite large. At the top they take a rest. Unfortunately, the ball then starts to roll down the hill and they can’t stop it. Pingu manages to get out of the way, but the ball catches up Pingo as it rolls down the hill. The ball is rolling fast when it reaches the bottom of the hill and continues on, collecting a line full of washing (with Punki beside it and not in the snowball.) and a cactus (After Grandfather threw it after he sees the giant snowball.) before crashing through a public toilet (with a penguin in it.). It then rolls into an ice overhang and reverses direction, making Pingu, who has been chasing after the ball, hastily reverse and run hard to keep in front of it. On reaching the post office Pingu quickly makes a makeshift ramp from some parcels, which lifts the snowball up, and it breaks apart on landing. Pingo is very cold after his experience, so Pingu and Father take him to their house and sit him in front of the fire with a hot water bottle. Pingu then wraps Pingo in a blanket and rolls him around, to their amusement.', '2004-01-30', 5, '/q1okgMUOIAcA9Bl2vniPC70QGEP.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
