INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F702150C22CF43DEB32DF2C264C87FF7', X'ABFE14EEDB424DDEA96A601FF3C53ECC', 9, 'The Visitor', 'Cluny captures a traveling spice salesmouse an holds his wife ransom against the mouse entering Redwall and capturing Cornflower. Torn between love and honor, he does as Cluny demands. But with Matthias'' help the two outwit Cluny with expansive flair and rescue the mousemaids, riding back to safety in a spectacular underground waterborne escape.', '1999-09-26', NULL, '/gia72fBxAVMw8Hkf3GzxIppk1kg.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F705E5F0AF7F4CD19C74767A6AA9D39A', X'42E591E22A884434AE9F3D4B1D685613', 27, 'Say It, Don''t Spray It', 'Strum along with the Pawn Stars when a Gibson Super Jumbo guitar once owned by Peggy Eames comes in the shop. A former star of the "Our Gang" series, can the guys negotiate an "oh-tay" price? Then, Corey and the Old Man check out a Buck Rogers tin rocket. Made in the 1930''s, will they pay 25th Century prices? And later, Chumlee decides to put some graffiti art on the shop''s exterior. Can he pull it off, or will the only tag be on his toe?', '2013-10-17', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
