INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F72BB71ED8094C27AD6B353674F0F732', X'C373ABED50EF417E9F344E9050611A1B', 12, 'Chicks and Salsa', 'Heather and Alexis meet at the coffee house to fix their friendship. Briana prepares emotionally for Ryan''s upcoming deployment. All the ladies, and husbands, come together for Lydia''s salsa dance party but Lydia brings her claws out once Slade starts to make rude remarks. Brooks surprises Vicki at the party with flowers and the room begins to fill with rumors regarding her love life. Gretchen is told that Alexis will be at Tamra''s wedding dress shopping trip and questions whether she will attend or not.', '2013-06-17', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
