INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F76F2BAA1BE14F99BB54A56101BF32A3', X'D0E5568D939D4D89AB4EC291A90691CF', 10, 'The Missing Tape Mystery', 'It''s Arnold''s birthday and he''s got some great presents. Pig has given him a cassette player - but the tape is missing. They want to play musical chairs - who has the tape? Everyone thinks everyone else has it until Tiger asks some searching questions. And the tape is in Tiger''s.... well, that would be telling wouldn''t it?', '2000-11-30', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
