INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F77A7389E73247538FA4D7729A6BA2BB', X'7C75633629DB4634B976E993E8F51DA2', 7, 'Over the River and Thru The Woods', 'While Charrisse struggles to break the news of her marriage troubles to her daughter, Monique and her husband Chris try to reconnect as a married couple by returning to where they started. Karen shocks the world of Potomac by revealing her most guarded secret, leaving the rest of the ladies speechless. Armed with Gizelle by her side, Robyn decides to pay Ashley a visit to her restaurant. The pleasantries quickly go out the window as Ashley and Robyn get into it over spreading rumors, gossip, and emu!', '2017-05-21', 42, '/xM4KWd6mSl0FpkapMWvY5V3tMk3.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
