INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F77DA83CD17C4BC7AF4D66C63AA8BC26', X'913F846D85DF46948DD40D5909F78887', 4, 'Courage', 'Zach promises to drop off his father’s film at the lab before going on a hike with Annie, but decides to do the hike first.  When he and Annie get stranded on a steep trail, Sock goes for a rope while Ari tells a story to boast Zach’s courage.  They get off the trail safely, but Zach doesn’t make it to the lab before it closes.  Now he must have the courage to tell his father of his mistake.', '2000-10-15', 30, NULL, '2026-04-03T17:38:35Z', '2026-04-03T17:38:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
