INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F7933924F2D94BB78FDE107712A068CD', X'F1325B5644E04B6E89BC82CAC30AFEA6', 14, 'Ice Cold In Pontypandy', 'When Trevor is driving his bus to Newtown he skids off the road and lands in a nearby lake. Moose Roberts decides to look for help and leaves but when Trevor starts a fire to keep the group warm the ice on the lake cracks and Fireman Sam comes to help', '2012-10-13', 10, '/5OyeCWKZ3E41pTkfpZVqJmQAdJ2.jpg', '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
