INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F7A20A8F80A144EEA5DD045A94EF2886', X'21745B85D26942FAB4DD701B2DA5C085', 10, 'Episode 10', 'with John Noakes, Peter Purves, Lesley Judd', '1973-10-11', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F7ADAA266D654D9AA08B994156ED088E', X'68138DE20900460AB58E480688F1E081', 3, 'The Big Sleep', 'It''s nighttime at the Big Blue House and Bear is all set to sit on his swing and read a good book. Then, Ojo shows up --- it turns out that there''s a sleepover scheduled tonight that Bear completely forgot about. Before he knows it, Tutter, Ojo, Treelo, Pip and Pop are all there and ready for the big sleepover, despite his protests that they''re not ready. He tries to settle back down to his book, but there''s a lot to do during a sleepover. He prepares the kids a snack, reads them a story and supervises as they all brush their teeth. Finally, everyone is ready to go to bed, after some final, special good-night touches. Ojo has difficulty getting to sleep, but eventually dozes, only to be awakened by a bad dream. Bear soothes her back to sleep and then finds Shadow. Shadow sings her own special version of the lullaby "Hush, Little Baby." 
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F7B257A406884C59A143717C1223B353', X'7BC54DF3F32A454EAEF6A9436C35D53B', 26, 'Episode 26', 'Rogers shows models of a bicycle and a tricycle. Along the way, he introduces the prefixes "bi" and "tri" to compare what each one means. In the Neighborhood of Make-Believe, Bob Dog fears moving wheels.', '1970-03-09', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F7B718F9C14645CA861CDB5797A2F73F', X'ACAC417E2AA342E79E08ED0D6071A3EE', 17, 'Ship Happens', 'Tensions arise at breakfast as Luann and Dorinda continue their argument from the night before, as do Carole and Bethenny; the ladies ditch the city for a private island and some fun in the sun, despite the strained relations; and the day ends abruptly with a traumatic boat ride after the ladies are rushed off the island due to high seas.', '2018-08-01', 60, '/zt7ABW5m1NI7rqyN6hDGyq6s27A.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
