INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F7D477929C8F497A9338B56BE2630EF0', X'D8CCF6D3E37A430AB67D7FBF269BF0BE', 8, 'Moms, Missions and Matrimony', 'Tensions escalate as Monica dines with her mother and Angie talks to her dad about her marriage. Lisa puts her focus on planning a mission location reveal party while Whitney meets with Mary for an explosive dinner.', '2023-10-31', 44, '/cW4U2RSefXPTwB3lX2alkCOFaeg.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F7DDCFDC2D184C768C4340F557E82445', X'136B81D3964D4B8FA21492F00D96D6B9', 1, 'Gordon and Snuffy run in the NYC Marathon', 'Big Bird helps Snuffleupagus train for the NYC Marathon while the Sesame Street crew cheers on Gordon. Despite Snuffy''s repeated tardiness at every checkpoint, Big Bird patiently waits for his friend to finish the race, even sleeping in the park overnight. Gordon and Susan eventually return to help push their car home as thanks for Big Bird''s loyalty.
