INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F89BE50A383A40BE8F74FF64EB0C8F02', X'AE8F64D94B834147A44CBFE720381F8E', 14, 'The Rainbow Show', 'Elmo is drawing when he looks up in the sky and sees a rainbow! Wow! Elmo rushes to show everybody, but when Rosita arrives, the rainbow has disappeared. Elmo asks Leela if there is something he can do to bring the rainbow back. Leela offers to draw a picture of a rainbow. Leela can’t remember all the colors of the rainbow, but uses the acronym Roy G. Biv to help her remember the colors.
