INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F95E3ABAFBD94AD6AD2E44C8BFF092F5', X'6E0BE2A3A234453BABB70BA535A93601', 26, 'Franklin''s Mom', 'Bear, Franklin and his family prepare to go out for a camping trip. While packing up, Mr. Turtle accidentally drops a frying pan and it lands on his foot which gives him serious injuries, forcing him to stay out of the vacation. Mrs. Turtle takes care of the rest of the work, which has some differences than what Mr. Turtle does.', '2000-07-30', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F960D74660B74458A0219D85CE782258', X'DA06465B91544FEBA455374DF7DAB02F', 23, 'Super Chicken on Sesame Street (4105)', 'Super Chicken helps Luis and Maria replenish their supply of packing tape at the Mail It Shop, helps Miles untie shoelaces, and fixes Gabi’s broken popcorn machine.  As Super Chicken quickly comes to the rescue and solves everyone’s problems, Super Grover begins to feel sad and useless as a superhero. He thinks that perhaps his friends on Sesame Street don’t need him anymore.  However, Luis, Maria, Gabi, Miles, and Big Bird all convince Super Grover that the only real superhero for Sesame Street is him, especially since there’s no other superhero in the world who can give a super hug like he does!', '2005-09-30', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
