INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F97096C4F0D14AB5A2E2F981737CC60D', X'BBFEE3B49C9548A6BEAA791FA08B1F43', 76, 'Episode 76', '', '1984-06-14', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F97EB7A833F34B0EB48D96C4DB41CA51', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 16, 'Storms', 'Storms are big, loud, and often accompanied by rain, snow, sleet, or hail. Where do these wild, dangerous, and necessary tornadoes, hurricanes, and thunderstorms come from? Storms happen when huge different air masses collide. Along the border of these air masses, water vapor condenses into clouds, strong winds form, and the clouds rub against each other with the ground often becoming electrically charged waiting to send lightning bolts across the sky. What starts out as a placid summer day turns into two air masses boxing it out 10,000 meters up.', '1998-05-23', 26, '/azd7TDs0GDVtBeMUBH1OmSkQbz3.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
