INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F99641B09D1E493F8C1C1E5CBA220368', X'0BBD380C5CB846A68838B5D60223C073', 3, 'Sandy Duncan', 'Fozzie performs Gags Beasley''s famous "banana sketch," which everyone has heard of except Kermit. When Kermit asks Sandy and Fozzie to tell him what it is, they laugh too hard to explain it.', '1976-09-19', 26, '/4HLcpeVt5OGubDgV2Ftt3f0yKOi.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
