INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F9B09156001E491BA339D681EC0D6957', X'3269A890BBA94E6C9278F7EB38EB1720', 5, 'Energy', 'Energy can change forms. Your body changes the energy in food into energy you can use to do things. Dams turn the energy in falling water into electrical energy to bring power to your house. Sound energy changes into moving energy (like when the bass is so high you can feel the floor move).', '1995-02-10', 26, '/zCPLaW9XsZXoE0etzibwK0M7sCo.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
