INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F9B54A1215FD45BDB75EA3BDD02600BF', X'98D80972E53A43DDA03A7703465E6F87', 3, 'Three Pawn Night', 'Step up to the plate with the Pawn Stars as they check out a Babe Ruth baseball card from when the Bambino was a pitcher with the Boston Red Sox. Will they swing for the fences for this rare card, or will the seller throw them a curveball? Then, Corey eyes an officer''s artillery sword from the War of 1812. Will he keep his edge or will the deal be cut short? And later, Corey and Chumlee are offered a keyboard used by the band Three Dog Night. Can this piece of classic rock memorabilia have the guys singing "Joy to the World?"', '2012-11-12', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
