INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'F9C5DE85F6A34B589FAF2C4086B6C99C', X'3982796B54514100904246BEDF6A20A5', 20, 'Pingu and the Gift', 'Pinga is playing happily with her teddy and toy pram when Pingu zooms up on his new scooter. Pinga immediately switches her attention to the scooter and really wants a go. Pingu won’t let her, and scoots off. Father then arrives on the motorised sledge, and Pinga greets him. He agrees to take her for a ride, but doesn’t look where he’s going and flattens the pram, destroying her teddy. Pinga is heartbroken and starts crying. Pingu arrives back, sees the broken pram and goes indoors. Pinga is still crying, so he tries to distract her by playing his drum. This has little effect so Mother tries a lollipop, giving Pingu one as well. This also has no effect. The family try other solutions, but none of these stop Pinga crying. Pingu then decides that he knows what she wants and gets his scooter and tells Pinga she can have a go. She immediately cheers up and sets off at speed. After crashing into and through various things she hits a bump and falls off, ending up buried under the snowman. Pingu is very worried she might have hurt herself, but she comes up laughing. Pingu gives her a cuddle, and the scooter!', '1994-08-17', 5, '/1b6DIaZeJxuE0mgfbskkwNErBDl.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
