INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FA6924307D4E4DBF9F520507E60F5790', X'E40E6B639F84449F8E8853209B0906C8', 24, 'Elmo Is Jealous of Marco', 'Gina welcomes the viewer to Sesame Street. Elmo is looking forward to playing checkers with her today, but it becomes difficult because Marco needs his mommy''s attention. Gina thinks he needs to eat, so she leaves with Marco to get his baby food, leaving Elmo all alone.', '2007-10-10', NULL, '/jtz4TJKt0iZRvIlO51jSzqK4CFX.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FA6BF0D6A77E4300B8FC6DC193F85BFF', X'70D9E39768134785887D27D034928BAE', 21, 'Pingu Draws a Winner', 'On his way home from school Pingu passes a lottery ticket seller, and watches a man as he has a go. The man doesn’t win, and goes off angrily. Pingu is about to leave when the ticket seller points out the prizes; a car, an igloo and first prize, a box of fish. Pingu is now keen to have a go, but has only a small fish, so he tries to pay with it. The ticket seller angrily refuses and Pingu trudges off. The ticket seller, who is very poor, then relents and calls Pingu back, and gives him a ticket in exchange for the fish. To his delight, he wins a prize and rushes home to tell Mother. She realises that Pingu has won the fish, and phones up to have it delivered. When it arrives Pingu and Mother are very pleased, but then Pingu thinks that rather than keep it themselves it would be better to give it to the ticket seller. Pingu takes the fish to the ticket seller, who is very happy to accept. As Pingu is leaving the ticket seller calls Pingu back and gives him a talisman as a thank-you. Pingu is delighted, and goes excitedly home.', '1996-08-01', 5, '/weaPhBnECgmHPPWZbuY8VLd3NhT.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
