INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FA949B0276C542CE85B83C57DD8C56CB', X'54900370898846B8B7AA61D2B88D7056', 6, 'Out of Gas', 'Friendships are challenged as Heather confronts Lisa. Angie and Mary have a heart-to-heart talk. Britani struggles to reconnect with her daughter. Lisa and John''s communication issues come to a head. Bronwyn''s marriage is tested following major accusations.', '2025-10-21', 42, '/xffLw0dSdJViU9FRFa0iR6w1pd5.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FA949E84E047416B8D67135662220796', X'F4C403079B5E4263A4E0DFA138131E7F', 78, 'Learning to Share', 'Like most kids, Elmo sometimes has trouble taking turns and sharing his toys. Even with his best friends Zoe. With a little help from Sesame Street favorites Big Bird, Cookie Monster, and Oscar, and special guest Katie Couric, Elmo discovers that sharing with friends makes playtime twice as much fun. Filled with songs and silliness, Learning To Share is a very special introduction to the Sesame Street Kids’ Guide To Life - a new home video series that helps make growing up a lot more fun. Plus Katie Koric gives parents some helpful TIPS for guiding kids through learning how to share.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
