INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FAA50E10C6C84BCA8F5D350E3A64D88C', X'CEFD1496B6494C62AEF935A22558AC08', 6, 'Don''t Cry Over Spilled Tea', 'LeeAnne gets a stunning surprise from Rich at the Texas State Fair. D’Andra decides to call an "Honestea" at her house where she’ll use a teapot, some notes, and a gavel to coerce her beloved back-talking b* to get their issues out on the table and move on. But a little too much honesty threatens to send the teacakes flying.', '2017-09-18', NULL, '/hRh3xMarj91SmnN3PyfGGMNbmle.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
