INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FAB4A9681A834721872E05C1C02A6283', X'DF77DBA2BBDA4F3897138D5C856F852E', 9, 'Little Bear''s Big Race', 'Little Bear finds Bramwell Brown examining a piece of tinfoil. Together they make some silver cups, and this gives Rabbit an idea. He suggests they have a sports day and use the cups as trophies for the winners of each race. They have a sock race, a potato and spoon race and a six-legged race. Little Bear begins to feel rather sad because he is sure he won’t win a prize; he is just too small to beat the others. However, his friends find a way to cheer him up and in the end, he has a surprising bit of luck.', '1993-11-28', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
