INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FABA788AFC554B328F774DA26D747EE0', X'54900370898846B8B7AA61D2B88D7056', 17, 'Reunion (1)', 'The women of Salt Lake City come together in NYC to discuss the past season and celebrate hitting a milestone 100 episodes. Lisa answers questions about her self-described very different lifestyle. Tensions flare when Bronwyn and Lisa go toe-to-toe about their truce. Heather and Angie are accused of teaming up against Lisa. Britani joins the stage and gives an update on her relationship with her daughter. Angie brings a scroll of evidence to prove who is behind the alleged leak.', '2026-01-13', 42, '/hl401Q117sCPAUZYaLHMmfdJhA7.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
