INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FAC333AE1656494699B0867CA8DA9EDD', X'34674C90410E427CBE4D2A6F6F865A80', 4, 'To the Moon', 'Ride in style with the Pawn Stars when a limousine formerly owned by Jackie Gleason pulls up to the shop. Will this luxury ride really be "The Great One" or is the seller stretching the truth? Then, a football spirals into the shop signed by the winners of Super Bowl I. Including Vince Lombardi himself, can Rick push this deal into the end zone or will he get stymied by a tough defense? And later, Rick and the Old Man are presented with a commemorative plaque of Mount Rushmore. Made of pure silver, will they silver tongues to get a good deal or will the seller’s price be set in stone?', '2012-04-16', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
