INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FAF21F1ED9A4435C98719007FAFF5C58', X'8BBF02B3DC844CC6ABBC81CF76ACF365', 6, 'Growing', '', '1991-09-05', NULL, NULL, '2026-04-03T17:35:45Z', '2026-04-03T17:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FAF308FE0E0A463DA56D67F73A4725A1', X'A8C6182E05E14B6891A55126CF6C94F0', 14, 'New York, New York', 'Sarah does a report on the loyalists opinion on the revolution in New York. Meanwhile James escapes to Manhattan with the Continental Army.', '2002-09-19', 30, '/jqSjC4CFqbkIRrTX1X4Sqk5kIPA.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FAF365C3F0A74EC6B32169D7C403DAEE', X'5BA20443D99F482081F66832D3F2BC4F', 7, 'Pollution Solutions', 'Dirty water, land, and air are a result of pollution. People are the only animals on Earth that make pollution. Garbage, burning fuel, chemicals, sewage, oil, and pesticides are all human-made things that make the Earth’s atmosphere, water, and soil unclean. Humans are even leaving trash in space, such as broken satellites, pieces of metal, paint from rocket skin, and even cameras and toothbrushes. Much of the junk people make and leave behind hurts plants, animals, you and me.', '1996-01-12', 26, '/7VasFnXlXP0XYZVRnxR6k5sCa52.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FAF8B3C1E1604BF293DFBF4F93911266', X'1BB5392776F64ED39C415414AD0865CE', 6, 'Ironbeak', 'From Redwall Abbey, Warbeak and her sparra squadrons fly South bearing the riddle. They hope to find Matthias to help him for his quest. But they are unaware that their departure is observed by Ironbeak, an evil raven general who invades Redwall as soon as Warbeak is gone. They drive the citizens of Redwall into the cavern hole and make them prisoners in their own abbey. Slagar and his slaves ascend the huge Great South Cliffs and cut off the means of pursuit leaving Matthias unable to follow. They pass along through the Dark Forest and are attacked by the fearsome and terrifying Painted Ones. They survive to find that Slagar is about to cross a huge river beyond which a huge rat army awaits him and his slaves.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FAF8D9B9731C41F7B8B6ED0279535930', X'B1D55597D9D24EEEAB9546DBB163291A', 15, 'Pingu Builds an Igloo', 'Pingu is going on a camping trip of sorts with Pingo. When Pingu said goodbye to his parents, Father offers Pingu a hat. He does not want to wear it, but father insists. When he leaves he gleefully takes the hat off and puts it in the box. When they meet, they head up at the spot how they will use blocks of ice to build an igloo, however, they cannot agree on where to build one, get into a fight, and go off to build their own separate igloos. Due to them only having half the blocks each, however, they can only build hopeless half-built structures which promptly collapse after some fighting over the last remaining block (Pingu''s collapses, much to Pingo''s amusement, then Pingo''s collapses, much to Pingu''s amusement). They then make up, build a proper igloo, and start up by happily eating fish at night on a blanket inside.', '1990-01-21', 5, '/z5f5pllXxdY14WmS9adPE2seqlK.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
