INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FB17BBD6119049DBB0AAA883E6DD6BD7', X'68138DE20900460AB58E480688F1E081', 17, 'If At First You Don''t Succeed...', 'Bear is expecting Doc Hogg to show up for lunch, but busy ol'' Doc keeps changing the plan. Bear and his friends learn to "roll with it" in a day of all kinds of change.', '2010-01-01', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
