INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FB1E0520AF0949E2B5E484FDB0A36BF8', X'AB509C47EC644FB3856003873DD0C37E', 16, 'The Beard', 'A toupee qualifies George to date Kramer''s friend; Elaine tries to change a gay man; Jerry owns up to watching "Melrose Place."', '1995-02-09', 23, '/aaHDIf6iMHdaN1lUiWkBjfUOTnU.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FB2146921D004FBCA61B79A8735DCDDA', X'1F34E2414C1D4586921A1C5AEB1FBBAA', 120, 'Episode 2215', 'Maria introduces Snuffy to Baby Natasha, whom she''s watching while her mother is away. Elmo stops by the Fix-It Shop and plays his latest game. He packs his make-believe suitcase for a make-believe trip to his granny''s, making sure to get a "goodbye hug" from Luis before he goes.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FB228973C69F4C569C8EA6E36079E087', X'D6092173D23B4449BAFFE0E16FE56C9A', 5, 'Don''t Come For Me Unless I''ve Invited You', 'After nearly spoiling Cynthia''s proposal last year, Kenya seeks redemption with a surprise engagement dinner. Kenya uses the opportunity to confront Porsha about being uninvited to her party and Kandi sends her daughter, Riley, off to New York University.', '2021-01-10', 43, '/tmRZzYkYPwHBFyhrAcG4xc05ZoR.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FB272B972E4B42A2A6CA095D4F9D84AE', X'4060AD7F4B8F43938EB166A150B928B6', 6, 'Holiday at Hooper''s', 'It’s holiday time on Sesame Street! When their parents run late from the holiday concert, Elmo and Baby Bear stay with Alan and Nina at Hooper''s Store. But they are disappointed not to celebrate Christmas Eve and Hanukkah as they had planned. Elmo, Baby Bear, Nina, and Alan sing carols, eat latkes, and make lots of decorations. They create a wonderful holiday celebration all by themselves—and Elmo and Baby Bear realize that the best part of holidays is being together with friends and family.', '2020-12-17', 26, '/3dfLb4zzDm3YkhqFZdI1jIadP9k.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FB2FC1CB58274A3FAC4AC18E3C084D7A', X'9C9D89DF5F6B41D084C6B8CA7BD2A2E6', 10, 'Martin Luther King Jr. Day', 'Elmo and his friends are making a Peace Tree to celebrate Martin Luther King Jr. Day. They each draw a picture to show how they will carry on Dr. King’s wish by treating people fairly and kindly every day!', '2022-01-13', NULL, '/sjdPjntJQZF9E67g7Mcw8SPdnvE.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FB33D30698284899933665CB9F25DBF5', X'20D7138EEEA846A88ADA2B0F0EE1F674', 79, 'Episode 79', 'Discover which country the team will be exploring for the 1983 Summer Expedition. And if you''re faced with a long journey-Janet has the answer, a quick and easy pocket game to make.', '1983-06-27', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
