INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FB4CB314CFF4426092D239C58EE55543', X'991E78F103A54D268F7575E11DB4243C', 1, 'Noisy and Quiet: Different Sounds Bells Can Make', 'Rogers witnesses the Westminster Choir College Bell Choir. Mr. McFeely shows a video on how bells are made. In the Neighborhood of Make-Believe, Mayor Maggie presents a loud bell to Henrietta. That bell quickly becomes a big irritant to the others.', '1999-02-15', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FB4DF4438E914E14A7D66B3CC970BBE8', X'54C290142DBD49FFA23FCF4C546E0B3A', 19, 'There''s Something About Harry', 'Carole hosts a lavish party to celebrate her birthday. Sonja is presented with a present from Aviva''s ex-husband Harry.', '2014-07-15', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FB56265033E244EF93A30D6D6FD70D94', X'DA06465B91544FEBA455374DF7DAB02F', 14, 'Mexico on Sesame Street (4096)', 'Rosita is feeling homesick for her abuela and for Mexico. Seeing how much Rosita misses Mexico and her abuela, Big Bird and friends decide to bring Mexico to her by decorating Sesame Street to look just like Mexico! They also bring in authentic Mexican food and Luis sings a traditional Mexican song. Rosita is truly surprised and grateful when she realizes what everyone has done. To everyone’s surprise, Rosita’s abuela shows up too! She missed Rosita so much that she had to fly in to see her. Rosita couldn’t be happier! They all continue the fiesta together.', '2005-09-08', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
