INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FB6FD1B637E242878B9E4CC0E577B48C', X'150D1480F3F143F99A22D2527756FBA2', 12, 'Reasonable or Shady?', 'Karen is ready to reveal her new candle line to the rest of the ladies, while Wendy struggles to get on equal footing; Mia''s family and her mum sit down for some much needed time together, but there is still a lot of work to be done.', '2021-09-26', 42, '/up4jXTAG13l1mXea1g0p9NAK618.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
