INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FB92CBF780FD4B0D870564348D8642AE', X'4A8E3DB080684FF3942F91F45F665F20', 10, 'Lionel''s Antlers', 'Lionel wakes up one morning, much like he does every day, to find that overnight, he''s grown a pair of antlers on his head! To help him feel better, Cleo reads him the book ""Imogene''s Antlers"" - also about a kid who woke up one morning to find she had grown antlers. When Lionel is still feeling low, his parents try to come up with helpful ""uses"" for his antlers.', '2000-04-14', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
