INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FBA0AC5BDD724DADA7C5DA3BE79FD2D5', X'6BE7468483E64D00BD693E4FCA97CABB', 2, 'Mad as a Hatter', 'LeeAnne enlists the help of a Dallas designer to create an extravagant hat for Mad Hatter’s Tea Party, one of the most coveted events on the Dallas social calendar. Brandi struggles with her husband Bryan’s constant business travel as she hosts a birthday party for her mother. Elsewhere, Tiffany and Aaron go house hunting, despite Aaron’s reservations about setting down roots in Dallas. Later, Stephanie and Cary are dragged deeper into Brandi’s conflict with LeeAnne when Brandi arrives to the Mad Hatter’s Tea Party donning a hat decorated with a special surprise.', '2016-04-18', NULL, '/gfu4w0CsLQ4LmQT9w23wZYoPEqD.jpg', '2026-04-03T16:35:03Z', '2026-04-03T16:35:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
