INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FBC456DBDAB14B10B0D013B8B70DB47A', X'F13CB62284E34654A8F10CEAB09A9CA6', 13, 'Franklin in Two Places', 'Franklin finds himself caught in a difficult situation when he promises to support Bear during his big-kid baseball game and attend Beaver''s art-show, both of which are happening at the same time. Bear is best friend and he did promise him first, but he wants to honor his commitment to Beaver because he''s always dodged attending her events in the past. Not wanting to hurt either''s feelings, he tries to make himself visible at both events without Bear or Beavers'' knowing, but quickly finds the juggling act harder to maintain than he thought it would be.', '2002-06-10', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
