INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FBDB71C36E5B4170B52976F146D2B638', X'40700E8A1DCE4895BEDE522A13A8BCAD', 14, 'Fearfest', 'A big thunderstorm hits Animal Junction and Zoboo sees something frightening in the dark. But the scary creatures are just grizzly bear cubs! Martin and Chris tell their lemur friend all about grizzlies and other animals that seem scary - but really aren''t.', '2001-03-23', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
