INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FBE21D044E4747FC983B2C677FDD7836', X'5C4E51C6E20746AD875C72988EB1E13E', 19, 'Making Cents', 'The Pawn Stars consider sending a search party out for Chumlee when he takes off to look at a 1950''s Bally''s coin operated kiddie ride. Will he step up and make a rocking buy or will he drop too much change on a shaky deal? Then, Rick and Corey meet a woman hoping to sell a script from the legendary classic film The Godfather. Signed by Al Pacino, will the guys make an offer she can''t refuse or will the seller look to skim a little off the top? And later, the guys get ready to polka when a vintage Excelsior accordion chimes its way into the shop. Will the guys look to play a happy tune or will negotiations hit a sour note?', '2011-07-18', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FBEF908EDE40454483FA3C6398CF7C40', X'3FC7C152E4F6426AA89936EC454C4403', 46, 'Sounds Like Trouble', 'Max and Ord make a goo ball and the friends play catch with it, but it goes on the loose, and then rolls into a dark cave. However, Ord is still scared of the dark, so it''s up to the rest of the gang to help Ord brave his fear of the dark once more to find it.', '2000-01-19', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
