INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FC0A5433223D4B84B1CD583B5C43D242', X'F593D90C533942F59C885BFD48D04075', 2, 'Draw the Line', 'The flock hijack a road line-painting machine and cause chaos while creating giant works of art in the field. However, will farmer appreciate their art?', '2009-10-20', NULL, '/5wc2gFFkKvNdsj5TMiEDnX60XyJ.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FC0B1D7213AB47D199CF4437F24E3E26', X'190C6E498849440487D4EAEF943A6024', 4, 'Oakie Doke And The Birthday Cake', 'Mrs Tickle has a cold this morning, which Lizzie is not pleased about, as it''s her birthday today. To cheer up, Doke gets some help to make a cake for Lizzie''s Birthday Party, but Mrs Tickle already has a surprise for Lizzie.', '1995-10-02', 10, NULL, '2026-04-03T17:19:24Z', '2026-04-03T17:19:24Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FC0C250F34C54A5EAEB22F01E5A57442', X'7CCD5605FE0B4E00AE7F3E3DAA252F8B', 15, 'Is This All There Is?', 'Season 5 finale. The housewives prepare to attend the season finale party. Vicki, still hurt by the San Francisco trip, vows to stay clear of drama. Gretchen and Slade color-coordinate outfits, looking (according to Vicki) as the plastic toppers of a wedding cake. Lynn''s daughters arrive at the party obviously under the influence, and Lynn excuses herself for knowing stating that the limo was big and she didn''t know what her daughter''s were up to. Tamra and Simon have a heated argument in the limo on the way to the party, with Tamra stating that she wants a divorce. The show ends with a recap of each housewife as is the tradition, and the last summary is that Tamra and Simon are divorcing.', '2010-03-04', 44, '/iaQd9a1q7ow1bq2QCwBi0MNqbhD.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FC0CC68E1F794FE5AD95DD53FD63B016', X'7B8E3988FBF34CFCAEB2782AE5A64E2D', 6, 'The Furry Four', 'Telly, Abby, and Elmo are reading Telly’s favorite comic book “The Furry Four!” They decide to pretend to be The Furry Four and quickly change into their furry, super costumes. Elmo is the Furry Flash, Abby is the Furry Tornado, and Telly is Mr. Furry! But that only makes three. They need one more member to be Furry Muscles so they can become The Furry Four. Telly, Elmo, and Abby go on a mission to find one more member! First, the superheroes run into Rosita and Zoe. They could be the The Furry Five, but Rosita and Zoe have planned to plant flowers in the garden with Maria. The mission continues. Abby, Telly, and Elmo think they found their fourth member when they come across a chicken, but he flies away in his cape. Next, they come across a squirrel who agrees to become the fourth member but he hurts his back trying to lift a mailbox while activating his super, furry power. Just then they see Chris sweeping outside Mr. Hooper’s Store. It turns out that he would love to pretend to be Furry Muscles and join the group. At last they found one more! Their first mission as The Furry Four is complete!', '2010-10-04', NULL, '/cZbu39ON06kX2BDA9CyRBklyLKD.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
