INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FC249A47C9A048D5B5D6D0FDECF36812', X'787DFA0BC8274DADA82D0548A6534D88', 24, 'Secrets Revealed', 'The Orange County vault is opened with never-before-seen footage from season ten including Shannon''s unique ladies lunch, Vicki''s night out and Heather''s teachable moment to Meghan about the finer points of Botox. In Tahiti, the women experience a wild ride, and back in Orange County, Heather proves the devil is in the details when building a mega home. Plus, secrets are revealed with more reunion footage addressing Vicki''s scandalous history with Brooks.', '2015-11-12', 44, '/Aus113dnBfFm9q48hBS9RyQ6nya.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
