INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FC51A980AF6C457DAFF3E4B905DA8932', X'6C1EC19F74DF4F359A6117B98175D826', 1, 'The Crown Isn''t So Heavy', 'Kyle''s new clothing line brings the women of Beverly Hills together for New York Fashion Week, where Dorit quickly realizes Kyle''s lack of experience in the fashion world could turn into a runway disaster. Erika takes Lisa Rinna, Teddi and Denise on a revealing trip down memory lane. Denise, who is trying her best to ignore legal issues with her notorious ex-husband, introduces the group to her longtime friend Garcelle Beauvais.', '2020-04-15', 43, '/2J1SnheNj7bh5kCXrXGfrSJWuNZ.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FC54647134ED4366B645F444DD8D23AA', X'EA1650C2E4F146C793BA74B5D45D08E5', 15, 'Floridon''t', 'Kandi''s tour bus makes it to Miami, where Phaedra, Sheree and Cynthia are awaiting its arrival. Their plans for a fun, relaxing weekend to celebrate Cynthia''s bachelorette are quickly dashed when the bus doors open to reveal Kim and NeNe in the middle of a blowout fight. Kim and Kandi celebrate the final show of their promo tour and NeNe invites her best friend Diana down to stay at the house with the ladies. A brief respite from the battle comes as Cynthia walks in a Miami Swim Week swimsuit fashion show, but Cynthia''s own thrill of being back on the runway is short-lived. When pressed by the other women to talk about her upcoming wedding, Cynthia breaks down in tears over the stress of her nearing nuptials.', '2011-01-23', 43, '/8g2Gm7upaNvlYmYmYO2BcuhREsC.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
