INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FC6A58773E0B4ECF98088AB589515479', X'02849455D14B476B9603EEF5FB5D2AB3', 6, 'I Came From Jesus', 'Exhausted from her busy life, Monique has a car accident that leaves everyone concerned about her well-being. Karen embraces her entrepreneurial spirit with a new business venture, meanwhile things heat up between Robyn and Juan. Ashley plans a fun outdoor retreat for the ladies to let off some steam, but things take a surprising turn as two of the ladies challenge Candiace when she stands up for herself.', '2018-05-06', 42, '/4oritUnpaiHNpQ5BcJYt3yV67rU.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
