INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FC76A54CB6634773AFDC2B216DE6FF9B', X'F79F69A8E59141D09D4A3D9683DEFBBB', 7, 'Oh Nobu You Didn''t', 'Gina questions her friendship with Heather; Emily reconnects with her estranged mom; Heather throws a dinner party at Nobu, but the fancy ambiance quickly turns tense when Emily and Gina confront Heather about her behavior.', '2023-07-19', 44, '/9zIRmpwcySNQjc3EcBauBT3pJeV.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FC80D1121BE748F983C30DC77D519A4A', X'0E4196154C964DDE8ED2715770BA77BB', 3, 'Step By Step', 'Tutter is getting ready to start Mouse School. His teacher, Miss Maxwell, is coming to visit him at the Big Blue House. Tutter is excited about the visit, but worries over things like what tie he should wear and how he should introduce himself. Then, Ojo, Pip and Pop tell him that he''ll have to know a lot to go to school, and he begins to worry that he''s just not ready. As he frets, Treelo helps Bear to make a cake. And when they all pay a visit to the General Store, Pip and Pop note the training wheels on Ojo''s bike. Worried they make her seem like a little bear, she borrows Bear''s wrench to remove them. 
