INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FCAB3FF0BA5F426E958CFB5953C5140B', X'4D0FD8A552004DFCB96CAE436DC8803C', 5, 'Sophie and Lou', 'LeVar takes a spirited leap into the world of dance. He gets a mambo lesson from Latin dancer, Jackie Rios, and has a hop while learning some fresh hip-hop moves. LeVar shows that there are different kinds of dancing done all over the world. Lola Falana narrates Sophie and Lou, a story of a young lady who is very shy and lives all alone. Sophie learns to dance by herself until she meets her match.', '1992-10-09', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FCB18499C1F446EAAD11CD070A865AE8', X'B753871204CE43A6916362280BBB084B', 21, 'Miles Babysits Natasha (3871)', '', '2000-01-31', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FCB2FE965A39495CAD50547B710F82C3', X'78A02D50E3DC4549844A3CF357A32EF4', 8, 'Bosom Buddies', 'The juicy details surrounding Kandi and Phaedra''s disastrous lunch begin to spread like wildfire, leaving Porsha on a mission to defend Phaedra from the allegations. When Porsha and Shereé decide to confront Kandi about the drama, everyone is left speechless when new accusations are brought to the table. Meanwhile, Cynthia looks to get a different type of makeover, while her daughter Noelle and soon-to-be-ex Peter share a tearful reunion. Kandi celebrates her daughter Riley''s 14th birthday as Shereé deals with the cost of having expensive taste and Porsha takes an unusual exercise class to help spice up her new relationship.', '2017-01-01', 43, '/rE62MX364PhbMi7TPsVCBQ5s7ld.jpg', '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FCB9389A875644E086A9ABEF02508CB4', X'51F03551BA41409D85F4E51BDDFDF82E', 15, 'The Lost Footage', 'The dynamic divas from New York City are featured in previously unseen footage from the sudsy series'' second season.', '2009-05-28', 60, NULL, '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FCC084CE036A429D81C20512EBB1136C', X'F13CB62284E34654A8F10CEAB09A9CA6', 7, 'Franklin and the Bus Patrol', 'As part of "Bus Safety Month," Bear is named "bus patrol officer" by Mr. Owl. Bear is familiar with the rules and seems to be good at the job, but when he ends up ticketing his friends for violations, they become upset with him. Franklin ends up commenting about how he''d do things if he became bus patrol officer and then regrets it when that''s exactly what happens. Both he and Bear learn a lesson.', '2002-05-20', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FCCCA55C06DB47E7AD59855622F1243E', X'BB5A884361814A6DBFDF33EF2C6BE7B8', 12, 'Peaches Be Trippin''', 'Cynthia deals with the fallout from Porsha''s news about Will, leading her to question their budding relationship. Porsha sits down with an unexpected ally, while Kenya begins shifting priorities after some potentially life changing news. Cynthia enlists NeNe''s help in getting all the girls together for a girls'' trip to Barcelona and Porsha attempts to squash all of the beef in the group by hosting a vegan dinner. As everyone gets ready to leave for Barcelona, the ladies are all shocked to learn who is - and who isn''t - going to Spain.', '2018-02-11', 43, '/iR7ulNMHAXLMUSrLOgOlvgqFwll.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
