INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FCE0FD347A92464BB44D5DB13CCB2741', X'16CBF3F2FFFD4A78BCA396D05F5A2C6B', 14, 'Carried Away', 'Pal''s cousin Dr. Yowl whisks Pal, Kate and Mei Lin away on an adventure through the solar system in his kennel.', '2016-05-26', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FCEB3F2C313949558549FBEBB2FE4EC3', X'D8CCF6D3E37A430AB67D7FBF269BF0BE', 13, 'Bermuda Views and Bathtub Blues', 'On their first international trip together, Whitney and Lisa avoid each other until Heather''s comments send dinner into chaos. After not getting a room with a bathtub, Meredith goes from a little under the weather to severely ill but recovers in time to hold the ladies accountable on the Sprinter ride to dinner. Excited to kick off her birthday celebration in Bermuda, Monica comforts Meredith, and a new layer of their friendship is revealed when dirt on Angie surfaces.', '2023-12-05', 44, '/vCNs0ctJ679vSHk1IsyDaOrUb9f.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FCEDD2D366474C5A91C6D3893D70D8F5', X'D3E13496E3C8490383B45A31FEDEE232', 4, 'The Warriors of Kyoshi', 'The gang arrives at Kyoshi Island and are captured by some Kyoshi warriors. When Aang reveals that he is the avatar, news quickly spreads out, eventually reaching Zuko, who then goes to Kyoshi Island to capture him.', '2005-03-04', 24, '/4VNx9JspNnWZibkkr7XydYPHh2m.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FCEEC9D75711454A8F0EB49A7E3259C0', X'B1D55597D9D24EEEAB9546DBB163291A', 10, 'Pingu on Makeshift Skis', 'Pingu jumps outside and flies around like a plane, when he sees the carrot for the snowman''s nose has dropped off. He puts it back on and finds it looking like a Rhino''s horn when he turns the head. He then sits on a sledge and starts drumming on his belly, when he sees Pingo coming along on his new skis. Pingu, most impressed, decides to tag along with him and, not having a pair of skis of his own, uses some junk in a ruined igloo to build a make-shift pair of his own. Pingu and Pingo then go climbing one of the mountains, with Pingo nearly slipping. After having fun whizzing about down the mountain, with Pingo taunting Pingu, they start racing competitively with Pingo going first, Pingu going next, with both stopping at one point, and both of them end up breaking their skis. They put what they can back together, and then decide to go with each of them on only one ski and go home, arm-in-arm, singing instead.', '1988-12-16', 5, '/oLXJryX07cCwND3z6Ag0dxMYUjS.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FCF16C2C612948BAA410B2B4719AF145', X'3B5C322F56504381948F712C5AA2D0A5', 1, 'Always My Dad', 'A girl, whose parents are divorced, doesn''t see her father very often but frequently thinks about him and treasures the time they have together. Also contains Family Day Picnic, Love to Go Around, A Special Bond and book reviews for Boundless Grace, Taxi! Taxi! and The Perfect Spot.', '1996-10-07', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
