INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FCFD7543C05946C28CABA95594181E13', X'7BC54DF3F32A454EAEF6A9436C35D53B', 55, 'Episode 55', 'Instead of the Neighborhood of Make-Believe, Rogers sees a story played out in Betty''s Little Theater. Four dancers, dressed as raccoons, perform a nighttime adventure.', '1970-04-17', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
