INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FD0DCA317E854218A1AE1D5CDBCA77F8', X'04E133FDC4A34DFA8369C6DCFD1E3A5A', 84, 'Episode 2049', 'Maria and Luis receive a postcard from Forgetful Jones on vacation, featuring humorous descriptions of his misadventures with biking and roller skating. Telly asks street people like Oscar, Big Bird, and kids for a word beginning with the letter Y in a "Monster on the Spot" segment. Oscar declares X is the best letter for crossing out things Grouches don''t like, while Telly complains about his warm jacket to Maria.
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FD0F4C058D8344439D387465A269D18B', X'9C9D89DF5F6B41D084C6B8CA7BD2A2E6', 24, 'Sesame Street Goes to the Farm', 'Elmo, Bert, Rosita and Ernie visit a farm, where they learn a lot about the machines, animals and food that can be found there.', '2022-04-21', NULL, '/b8PXrJ3AZoyZS1GUIr3Oftv8R6a.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FD110DC3E467474B80C122A661721507', X'3982796B54514100904246BEDF6A20A5', 4, 'Pingu Surfing on the Ice', 'Mother has hung out some washing, with help from Pingu. Mother has just gone back inside the igloo when the wind suddenly gets up, so Pingu decides to have some fun on an ice-surfer. He builds this himself, making the platform and mast from some stuff he finds in the shed, and for a sail using one of Mother''s clean sheets that she has just hung out to dry. After some fun zooming around, while going up a hill the wind suddenly stops and Pingu and his ice-surfer go crashing back down. The sheet he’s used for the sail is now filthy. Pingu mournfully goes back home, is told off by his mother for dirtying the sheet, and has to clean it. As he is doing this, with not very much success, Robby comes along. By swish-swashing his tail, Robby very quickly gets the sheet spotless. Mother is very pleased by the result, and Pingu and Robby share a fish given to them by Mother as a reward.', '1992-01-12', 5, '/z9hyTu2AYtzqN9Jp5GK0fZ5NrpU.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
