INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FD62EB6E4D5444F0A93CB13742AAEE54', X'3269A890BBA94E6C9278F7EB38EB1720', 2, 'Pressure', 'When you push something, you’re using pressure. Pressure depends on two things – the power of the push and the area that’s being pushed on. A push on a small area makes more pressure than the same size push on a big area. Pushing hard on something creates more pressure than a little nudge, naturally.', '1995-01-21', 26, '/lrSU8WiouXnQL17tOvSWbUjWWyA.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
