INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FD97C799BD7C4773A38BD0EE80FF9E7A', X'8C3CFAC1D8824904B38CD1981628D00E', 6, 'Episode 6', 'Expedition USA  Break One Nine! Are there any smokies in the area? Double Dutch? No - just the language of CB (Citizen Band) Radio in Texas. Simon discovers how this new form of radio communication has been a life saver. And in Houston - America''s Space Age City - he takes his life in his hands on the "Greezed Lightnin" - an incredible roller-coaster ride that loops the loop!', '1978-09-28', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
