INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FE030E5120704F92839E4D04ABC1B145', X'4B2A19E02FAE492EBC31F78E63D88EBC', 7, 'Death and Taxidermy', 'Get spooked out with the Pawn Stars when a 1547 edition of "The Dance of Death" haunts the shop. Will Rick take the book to his grave or will the negotiation have a bitter end? Next, things get whimsical when two sculptures from Dr. Seuss'' unorthodox taxidermy collection are brought in. Will Rick''s heart grow two sizes or will he say, "Green eggs and scram"? And later, a tear-gas baton forces its way into the shop. Will Corey think it''s a riot or will he be blinded by the price?', '2016-08-31', 21, '/6FTDmL64u2TBruleKUnTVJ7Jv8A.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
