INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FE51AC1E738147479EF20D3F970302BC', X'650BAC937B5941FCB277DC6F8BDCD7BB', 13, 'Ovary And Out', 'Frankie becomes sad when her doctor informs her that her ovaries are shriveled up, which means her days of having kids are over. In an attempt to cheer her up, Mike offers to have him and Frankie babysit the neighbor''s baby overnight, which puts some perspective on being an older parent. Meanwhile, Sue and Axl are a bit shocked when romantic sparks fly between Sean Donahue and Sue''s roommate Lexie; and Brick tries his best to hone up on his font knowledge when he meets Gibson, a worthy font opponent.', '2017-02-07', 22, '/aXa2gvCpJ4Q2ZMYYrdkoS3z0nAK.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
