INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FE585BD495E8430BB8D7E10C8FCFDD91', X'C9D2B3FB78454F3C9847CE1F7717257A', 9, 'A Game of Pawns', 'A limited edition autographed Game of Thrones item is up for grabs. Then, as Chumlee stirs up commotion with an Amazonian blowgun, picker Spencer Victory drops by with an ancient Middle Eastern sword. Later, Rick checks out an intriguing collectible from an early 1900s Democratic National Convention.', '2019-03-25', 42, NULL, '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
