INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FEC165F5611A4472ABBEBABC94AD6A4F', X'5C1B881FAC584D72B63F209952D4F902', 73, 'Episode 73', 'Portable Pavement: A replica of the largest Romano-British pavement north of the Alps fills the Blue Peter studio today-all 115,052 pieces of it! Simon, Chris and Tina help to fit the giant jigsaw together and meet Bob and John Woodward, who''ve painstakingly re-created the famous Wood-Chester pavement.', '1980-05-29', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FEC20F2824DD477BA3F16F52445B3C53', X'23C93536610C41C5AC6BA6B243423258', 19, 'Reunion (2)', 'The reunion continues with Mia spiraling backstage after her confrontation. Keiarna and Stacey face tough criticism about their relationships with Greg and TJ, but when new revelations are made, the women are left speechless. When the ladies take her to task for her actions throughout the season, Mia finally reaches her breaking point.', '2025-02-23', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FEC39CED9601438B805D356ACE1EED24', X'4FE93658C46343298E649D523869C2CB', 15, 'Monkey Business', 'Mount up and ride with the Pawn Stars as they take aim at a hat believed to have been worn by Western movie legend John Wayne. Will the gang decide to rustle up some quick cash or will they be forced to put up their dukes? Then, Rick and Chumlee are presented with an etching allegedly from one of the greatest artists in history - Rembrandt. Uncovered at a yard sale, will this artwork turn out to be a hidden masterpiece or a case of mistaken identity? And later, a woman hopes to sell her classic 1950s clapping chimp toy. Will the Old Man and Chumlee offer to play nice or will there be too much monkeying around?', '2010-12-06', 21, '/55oAV9yZpUOxZ6KhITPOSE9yyJ3.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
