INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FF129BF515ED40E59A85C262110BAC31', X'F4C403079B5E4263A4E0DFA138131E7F', 116, 'Elmo''s World: Head to Toe with Elmo', 'One, two, buckle your shoe...Elmo gets dressed, and you can, too! Come along and learn all about jackets, hats, and shoes with Elmo. With a dancing shade, a mischievous drawer, a frisky television and a playful computer, Elmo''s World is the perfect place for preschoolers to learn all about the world around them. Elmo and his friends take a trip to the shoe store, learn how to make a magical hat, and chat with a fuzzy pink jacket. Getting dressed and learning are fun in Elmo''s World!', '2003-01-14', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
