INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FF22C565C273406C9834085D7DA94F2F', X'119C16D5104745EC8242C72A8EED423B', 20, 'Francine Frensky, Superstar', 'Francine has always gotten the worst roles in school plays, so everyone in the Ratburn class asks Mr. Ratburn to give her a good part in the next one. The play is about Thomas Edison, and Francine is given the role of Edison himself. She takes her role very seriously, to the point where she starts to trying to run everything her way and insults her friends. After the hurt and the anger, they set out to show her that she can''t just forget their needs', '1996-10-18', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
