INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FF73CBA9B4A24AFE838009F0FCF73965', X'E38E9D8714324A1AA7D064A559BF7570', 6, 'Who Shall Wear The Crown', 'After the incident crossing the river, Badger is spotted still alive but caught in some reeds. Toad, Hare and weasel swim over to help Badger get untangled before they all swim back to land. Fox is nowhere to be found so Kestrel files downstream to see if she can find him. She sees him lying on the log heading under a bridge but as the log appears on the other side Fox is no longer there. Badger is assigned as the new leader and to add to matters Toad forgets which way to go. Owl suggests this is because his homing instincts have come into play. Hare and Vole inform Badger that Mrs. Fieldmouse has given birth to her young. Badger suggests that the animals should stop to rest for the time being.', '1993-02-07', 24, '/qHNe6yjB3bZECOlAjVB4EclW3S6.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
