INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FF787E6BB0E54D968E817B214E3146D6', X'ECB64EF34F8045A7B4A9C04434B02E35', 17, 'Magic Bus', 'Head back in time with the Pawn Stars when Rick checks out a fully restored 1960s VW Samba. Featuring a rare 23-window design, will this iconic bus cause him to get bit by the bug? Then, Chum gets scrambled when a piece of egg art from Sergio Bustamante rolls into the shop. Will he be able to cook up an offer or will this deal not go over easy? And later, when Rick announces a bonus for the employee of the month, Chum tries to prove his worth. Will he show the guys he''s top dog, or end up at the bottom of the barrel?', '2014-02-27', 21, '/5o3dQPtd57zzZosgFg92AKHug9y.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
