INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FF89B369C8DF4B28B3B0D4265214DE17', X'1D39506B06B84F9391360208069BD7E4', 12, 'Sun, Sand and Psychosis', 'A Virgin Island getaway turns nasty when an argument breaks out between Kelly and Bethenny, ruining a peaceful breakfast and precipitating a meltdown for Kelly. Later, Bethenny cooks up dinner, but it''s hard to swallow when there are yet more blowups. Cut to the Big Apple, where Jill mulls over going to the Virgin Islands to see all the drama in person.', '2010-05-20', 43, '/8cS3SIvwR1zR7Pg6MYNESVw4YbK.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FF8C4F179180455499305558FE37BADF', X'C4D795AE6AFA47D698194DD057030A3C', 12, 'The Peaches of Tokyo', 'While in Tokyo to celebrate her bachelorette party, Eva receives devastating news that threatens to derail the trip; Porsha shares a secret with the rest of the ladies; NeNe and Tanya get into a heated confrontation that leaves everyone confused.', '2019-01-19', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
