INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FF914F067E5C4CE3976E5DF84B5C6464', X'BF874BE37E2F4A0EB205C76AC1AD69FC', 30, 'Inside Looks (on The Subway)', 'Inside look from the season 3 episode "The Subway."', NULL, 3, NULL, '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FF921422ABD44DA3AD505095E226327F', X'A8F3A6817ABC41E099889B8804D74611', 17, 'Confronting Failure', 'With the Sister Wives living separately for over a year now, the Brown family structure is falling apart. After stressing out over finances, the wives try hard to start a web business, and Christine makes another attempt to pass her real estate exam.', '2012-12-16', NULL, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FF97B67274554A68810AAA7054ED3B21', X'319BD5D6FF58426FB9DAA0BB2CB87B02', 3, 'Genes', 'The color of your eyes, the shape of your nose, and the straightness (or curliness) of your hair depend on your genes. Not jeans the pants, but genes, the long strands of chemicals in your cells. Genes are like a blueprint for your body, and your cells follow the blueprint to build you. All living things have genes in their cells. You get your genes from your parents – half from your mom and half from your dad. Your parents got their genes from their parents, your grandparents. Living things pass down their genes from generation to generation. Genes from a mother’s egg cell mix with genes from a father’s sperm cell to make a complete set of plans for a baby. Baby humans, baby dogs, and baby plants all grow up to look like their parents because of genes.', '1997-10-17', 26, '/b49yJmD2UqvR3O33PGvxKEXt8yM.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FF9EA39C9A7741BEAC398D11AB77751F', X'9193E795DA7C40ECB68FF63AA7D5174F', 122, 'Histories & Lore: Robert''s Rebellion (Oberyn Martell)', 'Oberyn Martell reveals the Dornish perspective of Robert''s Rebellion - or the War of the Usurper as they call it - including the murder of his sister, Elia Martell, during the sack of King''s Landing.', '2015-02-17', 5, '/y8AdtzUGoctsnq4fQtTQrvdKOsx.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
