INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FFAF9D62F4BF4AE7B1FF409E0FD17630', X'119C16D5104745EC8242C72A8EED423B', 5, 'D.W. All Wet', 'Whew, boy is it HOT today. The Reads decide to head to the beach in order to cool off, but D.W. refuses to go along (she thinks there is an octopus in the water).', '1996-10-09', 13, '/jC6IQoq2nwqZUDzR4PLOwmrHTvp.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FFB09E53C0F4436786DA4C7EC28BAD0A', X'05044F495F9C4E7FA74DB2FF19475D0E', 10, 'The Day of Jacqueline', 'Dina, Melissa and the twins travel to Florida; Dina has a secret about the twins that threatens to ruin the trip; Amber awaits news about the possible recurrence of her cancer; Jacqueline returns and confronts Teresa about her past.', '2014-09-21', 43, '/hfnHr09eoO46cBR0pSTjEcXoXtz.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FFB27CC4644A479D8AB4B530CA2822AF', X'6E0BE2A3A234453BABB70BA535A93601', 3, 'Mr. Fix-It Franklin', 'Franklin gets to help out around the house on small fix-it jobs. He then tries to apply it to helping his friends, which seem to work at first, until he finds out that his fixes caused bigger messes. However, his friends forgive him and his parents tell him that learning from one''s mistakes is experience, too. And with his father''s help, he does it again the right way.', '2000-05-15', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FFB313CA621C4FC69E84C0BE416AEE5A', X'225B0F03984B47F3A1A3D3E92175E39D', 56, 'Episode 56', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-04-13', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FFB615A3DFB84275A32F95A848F304CB', X'5B72E664D3D7435DBDC3A23D29D1178E', 1, 'Ruff', 'The toys meet a new friend; a bouncy dog called Ruff. When they discover that he has never had a birthday party they quickly set about putting things right. They decide to hold an all-week birthday to celebrate all the birthdays Ruff has missed. Each day brings different birthday fun; parties, presents, games and birthday cakes. And on the seventh birthday they give Ruff the present he has always wanted.', '1994-09-06', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FFB73660FE6146B78DF40A2DA3D25D1D', X'C9D2B3FB78454F3C9847CE1F7717257A', 14, 'Pawning Picasso', 'Corey snipes an early 1800s prototype rifle made by the man who invented the Baker Rifle; one of Marlon Brando''s most prized possessions shows up; an original work made by the one and only Pablo Picasso shapes up to be a great addition to the shop.', '2019-06-24', 42, NULL, '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FFBF44B3E1804887A3BF2F9EE825F2AE', X'0FA9200282AE460985E33982BAA99AE1', 9, 'Postman Pat and the Runaway Train', 'The reverend Timms inadvertently starts the Greendale Rocket. Pat and PC Selby give chase in the patrol car, while Ajay and Mr. Pringle are in hot pursuit on the railway pump-truck...', '2005-03-08', 15, '/3cWYD7FEyMFH3B0g42ghx8jr1D8.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FFC3D4399827459BAC32D33C4443767B', X'3430D88114A2497D9CF4351B78B6AA6A', 11, 'Postman Pat Takes Flight', 'The Major Forbes prepares for a film show about his balloon flights across the world. When Pat arrives at Garner Hall, the Major asks Pat to climb onto the roof, untangle the string and cast him off into the sky. Unfortunately it sets off with Pat still clinging to the basket!', '1997-09-01', 15, '/ewJBnejZ2QM1flnkPvOH4GM0TdT.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
