INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FFC936DD751E4830BF94FA4356514790', X'2AEBFAD431454BC19DEF5F1D5BDFCFC8', 7, 'The Cafe', 'While Jerry tries to help a cafe owner, Elaine tries to help George with an IQ test, and Kramer...well, nobody can help Kramer.', '1991-11-06', 23, '/w2ITewmpbxPPjkM1CkE4IiLI9IV.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FFC9A01A3D4C49349B44063486CDABFB', X'4F18AC4C8757456CA49A224F00E6A9F7', 15, 'Slimey Adopts a Pet Bug', 'Gina meets up with Oscar, who’s trying to start up the Sloppy Jalopy, and Slimey, who eagerly bounces up and down in his booster seat. She learns that Oscar is taking Slimey to get his own pet bug, which Gina finds funny. They drive off, leaving Gina in the car exhaust.', '2008-10-07', NULL, '/p72AhIc5K5xfkhGC5JwrwjWPwrr.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FFCD974BF62D4CC0BD3CC3ABC46DA0C0', X'831E3A6BC1A748B7A5ACB18ED67BEB10', 4, 'Desperately Seeking Marriage', 'Katie renovates the house behind Andrew''s back; Charrisse tells her friends the shocking truth about her 18-year marriage; Karen learns how to fly a plane; Ashley gossips online, incurring the wrath of her close-knit community.', '2016-02-14', 42, '/ar7FULl7l41p1mRz1Uu2Aq01wqe.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FFCE720093354EE19D8E87D11B48D0E5', X'58ADB9AB3F1B4A1187B69B0B2DBB6AAF', 22, 'Mini Miles', 'Schedule a playdate with the Pawn Stars after Rick stumbles upon what could be one of the first Barbie dolls ever made while visiting his good friend, Marie Osmond backstage at her long running Vegas show. Will it turn out to be the real deal or is the seller just playing make believe? Then, Corey can''t believe how well Chumlee can drive a tiny amusement park car - he also can''t believe how much the seller wants for it. Later on, a "Citizen Kane" production still signed by Orson Welles comes into the shop and it''s anyone''s guess if a rare $10,000 certificate from 1900 meets the shop''s gold standard.', '2017-07-24', 21, '/sljZhhTkV6PmcrF6NyW1cTcdr3G.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
