INSERT INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES (X'FFF3F32CE8BD4A6C939D5C4DF0D146EF', X'95CA8B6FCCBC431A9D959B23367BBFED', 15, 'The Dinner Party From Hell: Part Two', 'Kyle assesses the progress at Sutton’s new home, while Dorit hopes her new business venture is the right fit for her family. Crystal invites Erika, Garcelle and Kathy over for a dinner where duck is served, but beef is on the menu. Kathy puts her staff to work arranging an evening to remember, but when Erika and Sutton face off, it quickly becomes a night the ladies would rather forget.', '2021-09-01', 43, '/jTor70cCh0xdFuMuMlsc9NWE8un.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z') ON CONFLICT(id) DO UPDATE SET tv_season_id = excluded.tv_season_id, episode_number = excluded.episode_number, title = excluded.title, overview = excluded.overview, air_date = excluded.air_date, runtime = excluded.runtime, still_key = excluded.still_key, created_at = excluded.created_at, updated_at = excluded.updated_at;
